    local hardeningModule = (function()
-- installs hooks, scans process memory, or unloads the user's game.
local function new(host)
    host = host or _ENV
    local refs = {}
    local function remember(path, value)
        if type(value)=='function' then refs[path]=value end
    end
    local stringLib=type(host.string)=='table' and host.string or nil
    local debugLib=type(host.debug)=='table' and host.debug or nil
    -- The existing payload AntiDump manager deliberately wraps dump/load and
    -- debug extractors later in startup. Track stable primitives only, so the
    -- guard cannot flag the payload's own compatibility wrappers.
    remember('string.sub', stringLib and stringLib.sub)
    remember('string.format', stringLib and stringLib.format)
    remember('type', host.type)
    local function resolve(path)
        local root,key=path:match('^([^%.]+)%.(.+)$')
        if root then
            local tbl=host[root]
            return type(tbl)=='table' and tbl[key] or nil
        end
        return host[path]
    end
    local function check()
        for path,original in pairs(refs) do
            if resolve(path)~=original then return false end
        end
        -- Behavioral canaries catch wrappers that forward the same call shape
        -- while changing the result, without touching any game state.
        if type(host.type)=='function' and host.type(nil)~='nil' then return false end
        if stringLib and type(stringLib.sub)=='function'
            and stringLib.sub('SovereignLuaIntegrity',1,8)~='Sovereig' then return false end
        return true
    end
    return {Check=check,Tracked=function()local n=0;for _ in pairs(refs)do n=n+1 end;return n end}
end
return {new=new}

    end)()
