local SovereignRuntimeLeaseCheck = function() return SovereignOfficial:Refresh() end

local function SovereignBootstrapDependencies(startup)
    local luaDir = FileMgr.GetMenuRootPath():gsub("/", "\\"):gsub("\\+$", "") .. "\\Lua"
    local dependencies = {
        {name = "natives.lua", size = 1600550, marker = "_G.SYSTEM",
            url = "https://raw.githubusercontent.com/SATTY91/Cherax-Lua-API-Documentation/50215c72ce86b90cdc71236cc920c0bd51ed8186/natives/natives.lua"},
        {name = "DataNodes.lua", size = 63107, marker = "CPedGameStateDataNode",
            url = "https://raw.githubusercontent.com/SATTY91/Cherax-Lua-API-Documentation/50215c72ce86b90cdc71236cc920c0bd51ed8186/api/DataNodes.lua"},
    }
    local function report(message)
        if Logger and type(Logger.LogError) == "function" then
            pcall(Logger.LogError, "[Sovereign dependencies] " .. tostring(message))
        else
            print("[Sovereign dependencies] " .. tostring(message))
        end
    end
    local function exists(path)
        local ok, present = pcall(FileMgr.DoesFileExist, path)
        if ok and present then return true end
        if io and type(io.open) == "function" then
            local opened, present = pcall(function()
                local file = io.open(path, "rb")
                if not file then return false end
                file:close()
                return true
            end)
            return opened and present == true
        end
        return false
    end
    local function verifyFile(path, expected)
        local reason = "FileMgr could not read the saved file"
        local found, present = pcall(FileMgr.DoesFileExist, path)
        if found and present then
            local read, content = pcall(FileMgr.ReadFileContent, path)
            if read and content == expected then return true end
            reason = read and "FileMgr readback did not match" or tostring(content)
        end
        if io and type(io.open) == "function" then
            local read, content = pcall(function()
                local file, reason = io.open(path, "rb")
                assert(file, "io.open(rb): " .. tostring(reason))
                local ok, value = pcall(file.read, file, "*a")
                local closed, result = pcall(file.close, file)
                assert(ok and closed and result, "io.read/close failed")
                return value
            end)
            if read and content == expected then return true end
            reason = read and "binary readback did not match" or tostring(content)
        end
        return false, reason
    end
    local function saveFile(path, body)
        local wrote, saved = pcall(FileMgr.WriteFileContent, path, body, false)
        local verified, readError = verifyFile(path, body)
        if verified then return true end
        local reason = "FileMgr.WriteFileContent=" .. tostring(saved) .. " (call=" .. tostring(wrote) .. "); " .. tostring(readError)
        if io and type(io.open) == "function" then
            -- Fall back to binary I/O when FileMgr cannot save the missing file.
            local written, detail = pcall(function()
                local file, openError = io.open(path, "wb")
                assert(file, "io.open(wb): " .. tostring(openError))
                local ok, result, writeError = pcall(file.write, file, body)
                local closed, closeResult, closeError = pcall(file.close, file)
                assert(ok and result, "io.write: " .. tostring(ok and writeError or result))
                assert(closed and closeResult, "io.close: " .. tostring(closed and closeError or closeResult))
                local checked, verifyError = verifyFile(path, body)
                assert(checked, tostring(verifyError))
            end)
            if written then return true end
            reason = reason .. "; " .. tostring(detail)
        else
            reason = reason .. "; io.open unavailable"
        end
        if type(FileMgr.DeleteFile) == "function" then pcall(FileMgr.DeleteFile, path) end
        if os and type(os.remove) == "function" then pcall(os.remove, path) end
        return false, reason
    end
    local missing = false
    for _, dependency in ipairs(dependencies) do
        if not exists(luaDir .. "\\" .. dependency.name) then missing = true end
    end
    if not missing then return startup() end
    if not Script or type(Script.QueueJob) ~= "function" or type(Script.Yield) ~= "function" then
        report("Cannot download missing files")
        return false
    end

    local function download(dependency)
        assert(Curl and type(Curl.Easy) == "function" and eCurlOption and eCurlCode
            and eCurlOption.CURLOPT_URL ~= nil and eCurlCode.CURLE_OK ~= nil,
            "Cherax HTTP support is unavailable")
        local curl = assert(Curl.Easy(), "Could not create dependency request")
        assert(curl:Setopt(eCurlOption.CURLOPT_URL, dependency.url) ~= false, "Could not set download URL")
        for _, option in ipairs({
            {"CURLOPT_SSL_VERIFYPEER", 1}, {"CURLOPT_SSL_VERIFYHOST", 2},
            {"CURLOPT_FOLLOWLOCATION", 0}, {"CURLOPT_TIMEOUT", 30},
        }) do
            if eCurlOption[option[1]] ~= nil then
                assert(curl:Setopt(eCurlOption[option[1]], option[2]) ~= false, "Could not set download option")
            end
        end
        -- Keep asynchronous requests rooted even if startup fails or times out.
        local pending = rawget(_G, "__SOVEREIGN_DEPENDENCY_REQUESTS")
        if type(pending) ~= "table" then
            pending = {}
            rawset(_G, "__SOVEREIGN_DEPENDENCY_REQUESTS", pending)
        end
        pending[curl] = true
        curl:Perform()
        local deadline = os.time() + 30
        local finished = false
        for _ = 1, 1200 do
            if type(ShouldUnload) == "function" and ShouldUnload() then error("Download cancelled", 0) end
            if curl:GetFinished() then finished = true; break end
            if os.time() >= deadline then break end
            Script.Yield(25)
        end
        assert(finished, "Download timed out: " .. dependency.name)
        pending[curl] = nil
        local code, body = curl:GetResponse()
        assert(code == eCurlCode.CURLE_OK, "Download failed: " .. dependency.name .. " (" .. tostring(code) .. ")")
        assert(type(body) == "string" and #body == dependency.size
            and body:find(dependency.marker, 1, true), "Invalid download content: " .. dependency.name)
        local compiled, syntaxError = load(body, "@" .. dependency.name, "t", {})
        assert(compiled, "Invalid dependency Lua: " .. tostring(syntaxError))
        return body
    end

    local queued, job = pcall(Script.QueueJob, function()
        local ok, reason = pcall(function()
            if type(FileMgr.CreateDir) == "function" then
                -- Existing directories may return false; verify the actual write and readback below.
                pcall(FileMgr.CreateDir, luaDir)
            end
            for _, dependency in ipairs(dependencies) do
                local path = luaDir .. "\\" .. dependency.name
                if type(ShouldUnload) == "function" and ShouldUnload() then return end
                if not exists(path) then
                    local body = download(dependency)
                    if type(ShouldUnload) == "function" and ShouldUnload() then return end
                    -- Another script may have supplied the file while this request was running.
                    if not exists(path) then
                        local saved, reason = saveFile(path, body)
                        if not saved then
                            error("Could not save dependency: " .. dependency.name .. " [" .. path .. "]; " .. tostring(reason), 0)
                        end
                    end
                end
            end
            if type(ShouldUnload) ~= "function" or not ShouldUnload() then startup() end
        end)
        if not ok then report(reason) end
    end)
    if not queued or job == false then
        report("Could not queue dependency download: " .. tostring(job))
        return false
    end
    return true
end

