-- Keep diagnostic wording out of the normal menu in either language.
menu.publicDisplayText = {
    ["使用当前 Legacy/Enhanced 版本独立签名。"] = "为键盘和鼠标启用游戏自带的辅助瞄准。",
    ["倾身后排队撒一次；核对脚本增量并在响应后恢复。"] = "在舞池边倾身后撒钱一次，快速增加好感度。",
    ["持续提交当前目标的镇静弹伤害事件；离开战局或关闭开关后停止。"] = "持续对选中玩家执行此操作；关闭或离开战局后停止。",
    ["发送一次所选事件；游戏状态和接收端决定是否响应。"] = "执行一次所选操作，是否生效取决于双方的游戏状态。",
    ["使用底层幽灵碰撞判定，不替换现有幽灵模式。"] = "启用单向幽灵碰撞，可与现有幽灵模式配合使用。",
    ["阻止斜坡 scramble 造成绊倒。"] = "防止在斜坡上移动时绊倒。",
    ["保留每帧清理，跳过闪电更新；关闭后恢复原始分支。"] = "隐藏闪电画面，关闭后恢复。",
    ["从底层阻止新的 PostFX 启动。"] = "阻止新的画面特效出现。",
    ["覆盖非临时事件阻挡判定。"] = "防止附近事件影响 NPC 的行为。",
    ["阻止新增前端声音事件；不会分配无关声音句柄。"] = "静音新出现的界面音效。",
    ["运行时补丁：当前游戏版本未解析"] = "当前游戏版本暂不能使用这些设置",
    ["运行时原生设置"] = "游戏设置",
    ["运行时补丁状态"] = "功能状态",
    ["底层补丁"] = "功能设置",
    ["人物补丁"] = "人物设置",
    ["动作补丁"] = "动作设置",
    ["载具补丁"] = "载具设置",
    ["世界补丁"] = "世界设置",
    ["声音补丁"] = "声音设置",
    ["当前游戏版本没有该功能签名"] = "当前游戏版本暂不支持此功能",
    ["补丁目录尚未验证当前游戏构建"] = "当前游戏版本暂不支持此功能",
    ["运行时签名未命中"] = "当前游戏暂不能使用此功能",
    ["目标字节已变化，可能与其他补丁冲突"] = "此功能可能与其他设置冲突",
    ["目标已被其他功能修改"] = "另一项功能正在控制此设置",
    ["Loader 未提供当前游戏的映射"] = "请通过 Loader 重新启动后再试",
    ["Loader 映射与当前游戏或私人版本不一致"] = "请使用对应版本的 Loader 重新启动",
    ["该功能依赖的指针解析失败"] = "此功能尚未就绪，请稍后重试",
    ["旧模块补丁尚未恢复"] = "上一次设置尚未恢复完成",
    ["宿主缺少对应的内存写入接口"] = "请更新 Cherax 后重试",
