-- R62: user-facing copy describes use and results; internal diagnostics remain unchanged.
menu.usageText = {
    ["使用蹲伏键切换原生蹲伏移动。"] = {"按蹲伏键切换蹲伏移动。", "Press the crouch key to toggle crouched movement."},
    ["键鼠使用原生辅助瞄准"] = {"键鼠辅助瞄准", "Mouse and keyboard aim assist"},
    ["原生瞄准捕获目标后，持续将准星跟踪到实际头部骨骼。"] = {"瞄准目标后，持续将准星保持在目标头部。", "After aiming at a target, keep the crosshair on their head."},
    ["使用当前 Legacy/Enhanced 版本独立签名。"] = {"为键盘和鼠标启用游戏自带的辅助瞄准。", "Enable the game's aim assist for mouse and keyboard."},
    ["使用底层幽灵碰撞判定，不替换现有幽灵模式。"] = {"启用单向幽灵碰撞，可与幽灵模式配合使用。", "Enable one-way ghost collision alongside ghost mode."},
    ["阻止斜坡 scramble 造成绊倒。"] = {"防止在斜坡上移动时绊倒。", "Prevent stumbling while moving on slopes."},
    ["保留每帧清理，跳过闪电更新；关闭后恢复原始分支。"] = {"隐藏闪电画面，关闭后恢复。", "Hide lightning visuals. Disable this to restore them."},
    ["从底层阻止新的 PostFX 启动。"] = {"阻止新的画面特效出现。", "Prevent new screen effects."},
    ["覆盖非临时事件阻挡判定。"] = {"防止附近事件影响 NPC 的行为。", "Keep nearby activity from interrupting NPC behavior."},
    ["阻止新增前端声音事件；不会分配无关声音句柄。"] = {"静音新出现的界面音效。", "Mute new menu sound effects."},
    ["阻止空闲逻辑自动移除头盔。"] = {"空闲时保留头盔。", "Keep your helmet on while idle."},
    ["阻止游戏逻辑强制关闭暂停菜单。"] = {"防止暂停菜单被强制关闭。", "Keep the pause menu from being closed automatically."},
    ["跳过落体布娃娃混合阶段。"] = {"加快落体后恢复正常动作。", "Recover normal movement sooner after falling."},
    ["移除浅水区域的移动物理限制。"] = {"在浅水中保持正常移动速度。", "Maintain normal movement speed in shallow water."},
    ["移除战斗翻滚冷却判定。"] = {"连续使用战斗翻滚，无需等待冷却。", "Use combat rolls repeatedly without waiting for a cooldown."},
    ["拦截识别到的广告脚本事件"] = {"拦截识别到的广告邀请。", "Block recognized advertising invitations."},
    ["脚本事件"] = {"玩家操作", "Player actions"},
    ["脚本事件选择"] = {"玩家操作选择", "Player action selection"},
    ["为当前选中玩家选择一个事件。"] = {"为当前选中的玩家选择一项操作。", "Choose an action for the selected player."},
    ["执行所选事件"] = {"执行所选操作", "Run selected action"},
    ["发送一次所选事件；游戏状态和接收端决定是否响应。"] = {"执行一次所选操作；是否生效取决于双方的游戏状态。", "Run the selected action once. Results depend on both players' game state."},
    ["持续提交当前目标的镇静弹伤害事件；离开战局或关闭开关后停止。"] = {"持续对选中玩家执行此操作；关闭或离开战局后停止。", "Repeat this action for the selected player until disabled or they leave the session."},
    ["传送到原任务脚本的佩里克岛位置。"] = {"传送到所选的佩里克岛地点。", "Teleport to the selected Cayo Perico location."},
    ["传送到原任务脚本的赌场位置。"] = {"传送到所选的赌场地点。", "Teleport to the selected casino location."},
    ["向当前任务控制器发送原脚本的开门事件。"] = {"在对应任务中打开任务门。", "Open the mission door during the corresponding mission."},
    ["向当前赌场任务控制器发送开门事件。"] = {"在赌场抢劫中打开任务门。", "Open the mission door during the Casino Heist."},
    ["设置当前控制器的主目标切割阶段。"] = {"切割主目标时使用，快速完成切割。", "Use while cutting the primary target to finish cutting quickly."},
    ["选择原任务脚本支持的 27 个主目标画作。"] = {"从 27 幅画作中选择主目标。", "Choose the primary target from 27 paintings."},
    ["选择原任务脚本中的具体任务节点。"] = {"选择要开始的任务阶段。", "Choose the mission stage to begin."},
    ["启动原任务脚本对应的远程管理界面。"] = {"打开对应产业的远程管理界面。", "Open the remote management screen for the selected business."},
    ["任务过程中持续设置破解阶段完成标记。"] = {"进入破解阶段后自动跳过；关闭开关即可停止。", "Skip hacking stages automatically during the mission. Disable this to stop."},
    ["设置目标、入口、人员和硬模式标志。"] = {"设置目标、入口、人员和困难模式。", "Set the target, entrance, crew and hard mode."},
    ["仅绕过任务板的不可启动状态，不绕过服务器端冷却。"] = {"允许从任务板开始可用任务；仍需等待游戏冷却结束。", "Start available missions from the planning board after the game cooldown ends."},
    ["删除当前已加载的非玩家任务 NPC，并自动请求实体控制权。"] = {"移除当前附近的任务 NPC。", "Remove nearby mission NPCs."},
    ["将任务板玩家准备标志设为已准备。"] = {"将任务板中的玩家设为已准备。", "Mark players as ready on the planning board."},
    ["将赌场任务板玩家准备标志设为已准备。"] = {"将赌场任务板中的玩家设为已准备。", "Mark players as ready on the casino planning board."},
    ["同时设置目标、路线、面具、人员、兴趣点和棋盘位。"] = {"应用目标、路线、面具、人员和侦察预设。", "Apply the target, route, mask, crew and scouting preset."},
    ["恢复赌场准备、路线、跳过计数和冷却字段。"] = {"重置赌场抢劫准备、路线和冷却。", "Reset Casino Heist preparations, route and cooldown."},
    ["重置目标轮换计数和序列类型。"] = {"重置主目标轮换顺序。", "Reset the primary target rotation."},
    ["清除科兹中心计划板冷却位。"] = {"清除科兹中心任务板的等待时间。", "Clear the wait time on the Kortz Center planning board."},
    ["设置当前任务控制器的完成阶段。"] = {"进入对应任务后使用，快速完成当前任务。", "Use during the corresponding mission to finish it quickly."},
    ["将观光客当前阶段写为完成。"] = {"快速完成观光客当前任务阶段。", "Finish the current Sightseer stage quickly."},
    ["清除赌场、经典、事务所和克拉克肯农场的本地冷却字段。"] = {"清除赌场、经典抢劫、事务所和克拉克肯农场的等待时间。", "Clear wait times for the Casino Heist, original heists, Agency and Cluckin' Bell Farm Raid."},
    ["使用 Sovereign 自研组织控制器尝试注册 CEO"] = {"立即注册为 CEO。", "Register as a CEO."},
    ["使用 Sovereign 自研组织控制器尝试注册摩托帮会长"] = {"立即注册为摩托帮会长。", "Register as an MC President."},
    ["在目标位置播放网络粒子特效"] = {"在所选玩家的位置播放特效。", "Play an effect at the selected player's location."},
    ["清除脚本生成的鸡"] = {"清除通过此菜单生成的鸡。", "Remove chickens created with this menu."},
    ["重置脚本镜头"] = {"恢复正常游戏镜头。", "Restore the normal game camera."},
    ["禁用脚本音乐"] = {"禁用任务音乐", "Mute mission music"},
    ["诊断与重置"] = {"任务重置", "Mission resets"},
    ["任务辅助只在当前控制器有效。"] = {"进入对应任务后再使用任务辅助。", "Enter the corresponding mission before using its assistance options."},
    ["当前任务控制器未运行，请进入对应任务后再执行。"] = {"请先进入对应任务，再使用此功能。", "Enter the corresponding mission before using this feature."},
    ["当前Legacy任务地址没有匹配的精确映射，已跳过该操作。"] = {"当前版本暂不能使用此任务功能。", "This mission feature is currently unavailable for this game version."},
    ["当前Legacy任务局部地址没有匹配的精确映射，已跳过该操作。"] = {"当前版本暂不能使用此任务功能。", "This mission feature is currently unavailable for this game version."},
    ["当前Legacy Tunable没有匹配的精确映射，已跳过该操作。"] = {"当前版本暂不能使用此设置。", "This setting is currently unavailable for this game version."},
    ["Legacy 简易室内映射未提供；已避免读取 Enhanced 地址"] = {"当前版本暂不能进入此室内。", "This interior is currently unavailable for this game version."},
    ["当前版本 freemode 映射不可用"] = {"当前暂不能进入此室内，请稍后重试。", "This interior is temporarily unavailable. Please try again later."},
    ["游戏版本未解析，未执行室内地址写入"] = {"请等待游戏加载完成后重试。", "Wait for the game to finish loading, then try again."},
    ["当前原生库缺少载具速度接口"] = {"当前暂不能使用氮气加速，请更新 Cherax 后重试。", "Nitrous acceleration is currently unavailable. Update Cherax and try again."},
    ["发动机音效接口不可用"] = {"当前暂不能更换发动机音效。", "The engine sound cannot be changed right now."},
