for original, labels in pairs(menu.usageText) do
    menu.publicDisplayText[original] = labels[1]
    menu.translations[original] = labels[2]
end
for original, translated in pairs(menu.translations) do
    if #original > 2 and (original:match("[:= ]$") or original:sub(-1) == "(" or original:sub(-3) == "：") then
        menu.translationPrefixes[#menu.translationPrefixes + 1] = {original, translated}
    end
    if #original > 3 and original:match("^ ") then
        menu.translationSuffixes[#menu.translationSuffixes + 1] = {original, translated}
    end
end
table.sort(menu.translationPrefixes, function(a, b) return #a[1] > #b[1] end)
table.sort(menu.translationSuffixes, function(a, b) return #a[1] > #b[1] end)

-- A few legacy notifications append a fixed English fragment directly to a
-- runtime name (for example `item.name .. "Spawned"`).  They cannot use the
-- normal `%s` format table without changing the source label, so translate
-- only the known suffix and leave the runtime name untouched.
