-- English is the canonical menu text. Keep the legacy Chinese->English
-- dictionary for runtime notices and old saved data, while exposing a stable
-- English->Chinese view for the Chinese locale. Duplicate English labels keep
-- the first registered Chinese spelling.
menu.chineseTranslations = {}
menu.translationEnglishCounts = {}
menu.nativeEnglishLiterals = {}
menu.sourceEnglishLiterals = {}
menu.rebuildTranslationDirection = function()
    local counts, reverse = {}, {}
    for chinese, english in pairs(menu.translations) do
        if type(chinese) == "string" and type(english) == "string" then
            counts[english] = (counts[english] or 0) + 1
        end
    end
    for chinese, english in pairs(menu.translations) do
        -- Only unique English labels can be reversed without losing the
        -- original Chinese wording. Collisions keep their Chinese source
        -- internally and still render through the forward translation.
        if type(chinese) == "string" and type(english) == "string"
            and counts[english] == 1 then
            reverse[english] = chinese
        end
    end
    menu.translationEnglishCounts, menu.chineseTranslations = counts, reverse
    -- The static English->Chinese table is declared below this function. Once
    -- it exists, fill only missing entries from the live Chinese->English map
    -- so runtime-added menu labels and notices use the same reverse path.
    if type(menu.englishTranslations) == "table" then
        for english, chinese in pairs(reverse) do
            if menu.englishTranslations[english] == nil then
                menu.englishTranslations[english] = chinese
            end
        end
    end
    menu.translationEnglishPrefixes = {}
    menu.translationEnglishSuffixes = {}
    for english, chinese in pairs(menu.englishTranslations or {}) do
        if type(english) == "string" and type(chinese) == "string"
            and english:sub(1, 1) ~= "^" then
            if english:sub(-1) == " " then
                menu.translationEnglishPrefixes[#menu.translationEnglishPrefixes + 1] = {english, chinese}
            elseif english:sub(1, 1) == " " then
                menu.translationEnglishSuffixes[#menu.translationEnglishSuffixes + 1] = {english, chinese}
            end
        end
    end
    table.sort(menu.translationEnglishPrefixes, function(a, b) return #a[1] > #b[1] end)
    table.sort(menu.translationEnglishSuffixes, function(a, b) return #a[1] > #b[1] end)
    if type(menu.clearTranslationCache) == "function" then
        menu.clearTranslationCache()
    end
end
menu.rebuildTranslationDirection()
