-- Keep newer source-side additions usable in the reverse direction too.  The
-- hand-maintained table above intentionally wins on wording; only fill keys
-- that were not present there so newly added menu/notice strings do not stay
-- English in the Chinese UI.
for chinese, english in pairs(menu.translations) do
    if menu.englishTranslations[english] == nil then
        menu.englishTranslations[english] = chinese
    end
end
menu.rebuildTranslationDirection()
menu.rebuildTranslationEnglishFormats = function()
    local formats = {}
    local function escapeLiteral(char)
        if char:match("[%^%$%(%)%%%.%[%]%*%+%-%?]") then return "%" .. char end
        return char
    end
    local function compile(template)
        local pattern, types = "^", {}
        local index = 1
        while index <= #template do
            local char = template:sub(index, index)
            if char ~= "%" then
                pattern = pattern .. escapeLiteral(char)
                index = index + 1
            elseif template:sub(index + 1, index + 1) == "%" then
                pattern, index = pattern .. "%%", index + 2
            else
                local cursor = index + 1
                while cursor <= #template and template:sub(cursor, cursor):match("[0-9%.%-%+ #]") do
                    cursor = cursor + 1
                end
                local conversion = template:sub(cursor, cursor)
                if conversion == "s" then
                    pattern, types = pattern .. "(.-)", types
                    types[#types + 1] = "s"
                    index = cursor + 1
                elseif conversion == "d" or conversion == "i" then
                    pattern = pattern .. "([+-]?%d+)"
                    types[#types + 1] = "n"
                    index = cursor + 1
                elseif conversion == "f" then
                    pattern = pattern .. "([+-]?%d*%.?%d+)"
                    types[#types + 1] = "n"
                    index = cursor + 1
                elseif conversion == "X" or conversion == "x" then
                    pattern = pattern .. "(%x+)"
                    types[#types + 1] = "x"
                    index = cursor + 1
                else
                    pattern = pattern .. "%%"
                    index = index + 1
                end
            end
        end
        return pattern .. "$", types
    end
    for english, chinese in pairs(menu.englishTranslations or {}) do
        if type(english) == "string" and type(chinese) == "string"
            and english:sub(1, 1) ~= "^" and english:find("%%[sdifXx]") then
            local pattern, types = compile(english)
            formats[#formats + 1] = {pattern = pattern, chinese = chinese, types = types}
        end
    end
    table.sort(formats, function(a, b) return #a.pattern > #b.pattern end)
    menu.translationEnglishFormats = formats
end
menu.rebuildTranslationEnglishFormats()
menu.addTranslation = function(chinese, english)
    if type(chinese) ~= "string" or type(english) ~= "string" then return false end
    menu.translations[chinese] = english
    menu.englishTranslations = menu.englishTranslations or {}
    menu.nativeEnglishLiterals[english] = nil
    menu.sourceEnglishLiterals[english] = nil
    if menu.englishTranslations[english] == nil then menu.englishTranslations[english] = chinese end
    menu.rebuildTranslationDirection()
    menu.rebuildTranslationEnglishFormats()
    menu.clearTranslationCache()
    menu.translationRevision = (menu.translationRevision or 0) + 1
    if menu.ui then menu.ui.sizeDirty = true end
    return true
end
menu.addTranslations = function(entries)
    if type(entries) ~= "table" then return false end
    for chinese, english in pairs(entries) do
        menu.translations[chinese] = english
        menu.englishTranslations = menu.englishTranslations or {}
        menu.nativeEnglishLiterals[english] = nil
        menu.sourceEnglishLiterals[english] = nil
        if menu.englishTranslations[english] == nil then menu.englishTranslations[english] = chinese end
    end
    menu.rebuildTranslationDirection()
    menu.rebuildTranslationEnglishFormats()
    menu.clearTranslationCache()
    menu.translationRevision = (menu.translationRevision or 0) + 1
    if menu.ui then menu.ui.sizeDirty = true end
    return true
end
menu.canonicalEnglish = function(value)
    if type(value) ~= "string" then return value end
    local english = menu.translations[value]
    if english then
        -- If the same English literal already existed as a native source
        -- value, keep this translated item in its Chinese source form. That
        -- preserves per-item Chinese wording for duplicate option labels.
        if menu.nativeEnglishLiterals[english] then return value end
        return menu.translationEnglishCounts[english] == 1 and english or value
    end
    if menu.englishTranslations and menu.englishTranslations[value] then
        menu.sourceEnglishLiterals[value] = true
    else
        menu.nativeEnglishLiterals[value] = true
    end
    return value
end

-- Failed pattern matches need no capture table. Keep this helper outside the
-- obfuscation VM as well, since a cache miss can test every translation format.
menu.translationCaptures = LPH_NO_VIRTUALIZE(function(first, ...)
    if first == nil then return nil end
    return {first, ...}
end)

menu.translate = LPH_NO_VIRTUALIZE(function(value, forceEnglish)
    if type(value) ~= "string" then return value end
    if menu.ui.language == 2 and not forceEnglish then
        local chinese = menu.englishTranslations[value] or menu.chineseTranslations[value]
        if chinese then
            return menu.publicDisplayText[chinese] or chinese
                or menu.publicDisplayText[value] or menu.chineseChrome[value] or value
        end
        for _, suffix in ipairs(menu.translationDynamicSuffixes or {}) do
            if value:sub(-#suffix[1]) == suffix[1] then
                return value:sub(1, #value - #suffix[1]) .. suffix[2]
            end
        end
        for _, format in ipairs(menu.translationEnglishFormats or {}) do
            local captures = menu.translationCaptures(value:match(format.pattern))
            if captures then
                for index, captureType in ipairs(format.types) do
                    if captureType == "n" then captures[index] = tonumber(captures[index]) or captures[index] end
                    if captureType == "x" then captures[index] = tonumber(captures[index], 16) or captures[index] end
                end
                local ok, formatted = pcall(string.format, format.chinese, table.unpack(captures))
                if ok and type(formatted) == "string" then return formatted end
            end
        end
        -- English notifications often append a player name, model or reason
        -- to a translated prefix. Translate the fixed prefix/suffix while
        -- leaving the dynamic payload byte-for-byte intact.
        for _, prefix in ipairs(menu.translationEnglishPrefixes or {}) do
            if value:sub(1, #prefix[1]) == prefix[1] then
                local remainder = value:sub(#prefix[1] + 1)
                local translatedRemainder = remainder
                for _, suffix in ipairs(menu.translationEnglishSuffixes or {}) do
                    if remainder:sub(-#suffix[1]) == suffix[1] then
                        translatedRemainder = remainder:sub(1, -#suffix[1] - 1) .. suffix[2]
                        break
                    end
                end
                return prefix[2] .. translatedRemainder
            end
        end
        if menu.nativeEnglishLiterals[value] and not menu.sourceEnglishLiterals[value] then return value end
        return menu.publicDisplayText[value] or menu.chineseChrome[value] or value
    end
    local translated = menu.translations[value]
    if translated then return translated end
    translated = menu.translationCache[value]
    if translated then return translated end
    if not value:find("[\228-\233]") then return value end
    -- Dynamic notices commonly append an identifier or player name. Translate
    -- the known leading fragment and preserve the remaining user data verbatim.
    translated = value
    local plain, repeats = value:match("^(.-)(  x%d+)$")
    local combined, count = value:match("^(.-)（合并 (%d+) 次）$")
    if combined then plain, repeats = combined, "  x" .. count end
    local bracket = value:match("^%[ (.-) %]$")
    local progressText, progress = value:match("^(.-)( %(%d+/%d+%))$")
    for _, format in ipairs(menu.translationFormats) do
        -- Match once; only successful matches allocate captures.
        local captures = menu.translationCaptures(value:match(format[1]))
        if captures then
            -- Only explicitly designated semantic captures are translated.
            -- Player names and other user-controlled values remain byte-for-byte intact.
            for _, index in ipairs(format.translated or format.known or {}) do
                captures[index] = menu.translations[captures[index]] or captures[index]
            end
            for _, index in ipairs(format.nested or {}) do
                captures[index] = menu.translate(captures[index], true)
            end
            for _, index in ipairs(format.lists or {}) do
                -- Only system-generated business-name lists use this path.
                local names = {}
                for name in (captures[index] .. "、"):gmatch("(.-)、") do
                    names[#names + 1] = menu.translations[name] or name
                end
                captures[index] = table.concat(names, ", ")
            end
            if format.order then
                local ordered = {}
                for _, index in ipairs(format.order) do ordered[#ordered + 1] = captures[index] end
                captures = ordered
            end
            translated = string.format(format[2], table.unpack(captures))
            break
        end
    end
    if translated ~= value then
        -- A complete formatted message already preserved all captured values.
    elseif plain then
        translated = menu.translate(plain, forceEnglish) .. repeats
    elseif bracket then
        translated = "[ " .. menu.translate(bracket, forceEnglish) .. " ]"
    elseif progressText and menu.translations[progressText] then
        translated = menu.translations[progressText] .. progress
    elseif value:find("\n", 1, true) then
        translated = value:gsub("[^\n]+", function(line) return menu.translate(line, forceEnglish) end)
    end
    if translated == value then
        for _, prefix in ipairs(menu.translationPrefixes) do
            if value:sub(1, #prefix[1]) == prefix[1] then
                local remainder = value:sub(#prefix[1] + 1)
                translated = prefix[2] .. (menu.translations[remainder] or remainder)
                break
            end
        end
    end
    for _, suffix in ipairs(menu.translationSuffixes) do
        if translated:sub(-#suffix[1]) == suffix[1] then
            translated = translated:sub(1, -#suffix[1] - 1) .. suffix[2]
            break
        end
    end
    -- Evict one old entry; keep the other cached labels warm. A 513-entry
    -- bound leaves spare Lua hash slots after rehashing, whereas exactly
    -- 512 live entries can force a rehash on every full-cache insertion.
    if menu.translationCache[value] == nil then
        local slot = menu.translationCacheNext
        local previous = menu.translationCacheKeys[slot]
        if previous ~= nil then
            menu.translationCache[previous] = nil
        else
            menu.translationCacheCount = menu.translationCacheCount + 1
        end
        menu.translationCacheKeys[slot] = value
        menu.translationCacheNext = slot == 513 and 1 or slot + 1
    end
    menu.translationCache[value] = translated
    return translated
end)

menu.localizedTextColored = LPH_NO_VIRTUALIZE(function(r, g, b, a, text)
    return ImGui.TextColored(r, g, b, a, menu.translate(text))
