menu.localizedInputHint = LPH_NO_VIRTUALIZE(function(id, hint, value, ...)
    return ImGui.InputTextWithHint(id, menu.translate(hint), value, ...)
end)
function menu.setLanguage(index, save)
    index = tonumber(index) == 2 and 2 or 1
    if menu.ui.language ~= index then
        menu.ui.language = index
        menu.clearTranslationCache()
        menu.translationRevision = menu.translationRevision + 1
        if menu.quick then menu.quick.searchDirty = true end
        menu.ui.sizeDirty = true
    end
    if menu.ui.items and menu.ui.items.language then menu.ui.items.language.value = index end
    if save ~= false then
        menu.queueUiSettingsSave()
    end
    return index
end
