    return menu.comboModalActive == true and menu.comboModalItem ~= item
end)

function menu.makeQuickKey(item, groupID)
    local group = globalGroups[groupID]
    local subtab = group and globalSubtabs[group.subtabID] or nil
    local tab = subtab and menu.tabs[subtab.tabID] or nil
    local source = table.concat({
        tostring(item and item.type or ""),
        tostring(tab and (tab.sourceName or tab.name) or ""),
        tostring(subtab and (subtab.sourceName or subtab.name) or ""),
        tostring(group and (group.sourceName or group.name) or groupID or ""),
        tostring(item and (item.sourceLabel or item.label) or ""),
        tostring(item and (item.sourceDescription or item.description) or "")
    }, "|")
    local hash = 5381
    for index = 1, #source do
        hash = ((hash * 33) + source:byte(index)) % 4294967296
    end
    return string.format("%08x", hash)
end

