function menu.registerQuickItem(item, groupID)
    if type(item) ~= "table" or item.type == "text" or item.type == "input" then return item end
    local rawQuickKey = item.quickKey or menu.makeQuickKey(item, groupID)
    item.quickKey = item.quickKey or (menu.quickKeyAliases[rawQuickKey] or rawQuickKey)
    item.originGroupID = item.originGroupID or groupID
    menu.quick.registry[item.quickKey] = item
    return item
end

function menu.isQuickItemVisible(item)
    if type(item) ~= "table" then return false end
    if item.player_bind or item.playerScoped == true then return false end
    local originGroup = item.originGroupID and globalGroups[item.originGroupID]
    if originGroup == nil or originGroup.hidden == true then return false end
    if type(SovereignMenuFeatureVisible) == "function"
        and not SovereignMenuFeatureVisible(item, originGroup) then
        return false
    end
    return true
end

function menu.refreshQuickGroups()
    local favoriteGroup = menu.quick.favoriteGroupID and globalGroups[menu.quick.favoriteGroupID]
    local recentGroup = menu.quick.recentGroupID and globalGroups[menu.quick.recentGroupID]
    if favoriteGroup then
        favoriteGroup.items = {}
        local seenFavorites = {}
        for _, key in ipairs(menu.quick.favoriteOrder) do
            local item = menu.quick.registry[key]
            if not seenFavorites[key] and menu.isQuickItemVisible(item) then
                seenFavorites[key] = true
                favoriteGroup.items[#favoriteGroup.items + 1] = item
            end
        end
        if #favoriteGroup.items == 0 then
            favoriteGroup.items[1] = {type = "text", label = "Right-click any feature to add it here"}
        end
    end
    if recentGroup then
        recentGroup.items = {}
        local seenRecent = {}
        for _, key in ipairs(menu.quick.recentOrder) do
            local item = menu.quick.registry[key]
            if not seenRecent[key]
                and not menu.quick.favorites[key]
                and menu.isQuickItemVisible(item) then
                seenRecent[key] = true
                recentGroup.items[#recentGroup.items + 1] = item
            end
        end
        if #recentGroup.items == 0 then
            recentGroup.items[1] = {type = "text", label = "Recently used features appear here automatically"}
        end
    end
end

function menu.queueQuickSettingsSave()
    menu.quick.savePending = true
    menu.quick.lastChangeAt = os.clock()
end

function menu.toggleFavorite(item)
    if type(item) ~= "table" or not item.quickKey then return end
    if not menu.isQuickItemVisible(item) then return end
    local key = item.quickKey
    if menu.quick.favorites[key] then
        menu.quick.favorites[key] = nil
        for index = #menu.quick.favoriteOrder, 1, -1 do
            if menu.quick.favoriteOrder[index] == key then table.remove(menu.quick.favoriteOrder, index) end
        end
        menu.notify("SovereignLua", "Removed from favorites: " .. tostring(item.label or "Feature"), 2.5, "info")
    else
        menu.quick.favorites[key] = true
        table.insert(menu.quick.favoriteOrder, 1, key)
        menu.notify("SovereignLua", "Added to favorites: " .. tostring(item.label or "Feature"), 2.5, "success")
    end
    menu.refreshQuickGroups()
    menu.queueQuickSettingsSave()
end

function menu.recordUsage(item)
    if type(item) ~= "table" or not item.quickKey then return end
    if not menu.isQuickItemVisible(item) then return end
    local key = item.quickKey
    if menu.quick.recentOrder[1] == key then return end
    for index = #menu.quick.recentOrder, 1, -1 do
        if menu.quick.recentOrder[index] == key then table.remove(menu.quick.recentOrder, index) end
    end
    table.insert(menu.quick.recentOrder, 1, key)
    while #menu.quick.recentOrder > (menu.quick.maxRecent or 12) do
        table.remove(menu.quick.recentOrder)
    end
    menu.refreshQuickGroups()
    menu.queueQuickSettingsSave()
end

menu.handleQuickItem = LPH_NO_VIRTUALIZE(function(item)
    if not menu.interactive or not item or not item.quickKey then return end
    if ImGui.IsItemHovered and ImGui.IsMouseClicked
        and ImGui.IsItemHovered() and ImGui.IsMouseClicked(1) then
        menu.toggleFavorite(item)
    end
end)

menu.themeColorFields = {"background", "panel", "control", "hover", "border", "text", "muted", "accent"}
menu.extendedThemeRoles = {
    {"tooltip", "panel"}, {"notification", "panel"},
    {"toggleOn", "accent"}, {"toggleOff", "border"}, {"cursor", "accent"},
    {"success", nil, 111, 211, 143}, {"warning", nil, 243, 197, 107}, {"error", nil, 240, 116, 116},
    {"motion", nil, 230, 152, 186}
}
for _, role in ipairs(menu.extendedThemeRoles) do
    local prefix, inherited = role[1], role[2]
    menu.themeColorFields[#menu.themeColorFields + 1] = prefix
    for index, channel in ipairs({"R", "G", "B"}) do
        local value = inherited and menu.ui.defaults[inherited .. channel] or role[index + 2]
        menu.ui.defaults[prefix .. channel], menu.ui[prefix .. channel] = value, value
    end
end
