function menu.refreshThemeColors()
    menu.themeResolvedColors = {}
    for hex, role in pairs(menu.themeHexRoles) do
        local prefix = role[1]
        local scale = tonumber(role[2]) or 1.0
        menu.themeResolvedColors[hex] = {
            math.max(0, math.min(255, math.floor(((tonumber(menu.ui[prefix .. "R"]) or 0) * scale) + 0.5))),
            math.max(0, math.min(255, math.floor(((tonumber(menu.ui[prefix .. "G"]) or 0) * scale) + 0.5))),
            math.max(0, math.min(255, math.floor(((tonumber(menu.ui[prefix .. "B"]) or 0) * scale) + 0.5)))
        }
    end
    menu.rgbaIntCache = {}
    menu.rgbaFloatCache = {}
end

menu.resolveThemeColor = LPH_NO_VIRTUALIZE(function(hex)
    if type(menu.themeResolvedColors) ~= "table" then menu.refreshThemeColors() end
    local colors = menu.themeResolvedColors
    return colors[hex] or colors[tostring(hex or ""):lower()]
end)

function menu.setThemeColor(prefix, r, g, b, save)
    r = math.max(0, math.min(255, math.floor((tonumber(r) or 0) + 0.5)))
    g = math.max(0, math.min(255, math.floor((tonumber(g) or 0) + 0.5)))
    b = math.max(0, math.min(255, math.floor((tonumber(b) or 0) + 0.5)))
    for _, role in ipairs(menu.extendedThemeRoles) do
        local name = role[1]
        if role[2] == prefix and menu.ui[name .. "R"] == menu.ui[prefix .. "R"]
            and menu.ui[name .. "G"] == menu.ui[prefix .. "G"] and menu.ui[name .. "B"] == menu.ui[prefix .. "B"] then
            menu.ui[name .. "R"], menu.ui[name .. "G"], menu.ui[name .. "B"] = r, g, b
            local item = menu.ui.items and menu.ui.items[name .. "Color"]
            if item and item.value then item.value.r, item.value.g, item.value.b = r, g, b end
        end
    end
    menu.ui[prefix .. "R"] = math.max(0, math.min(255, math.floor((tonumber(r) or 0) + 0.5)))
    menu.ui[prefix .. "G"] = math.max(0, math.min(255, math.floor((tonumber(g) or 0) + 0.5)))
    menu.ui[prefix .. "B"] = math.max(0, math.min(255, math.floor((tonumber(b) or 0) + 0.5)))
    menu.ui.themePreset = 7
    if menu.ui.items and menu.ui.items.themePreset then menu.ui.items.themePreset.value = 7 end
    menu.applyAccentTheme()
    if save and menu.queueUiSettingsSave then menu.queueUiSettingsSave() end
end

function menu.bindThemeColorItem(prefix, label, description, groupId)
    local item = menu.color(label, description, groupId, {
        r = menu.ui[prefix .. "R"],
        g = menu.ui[prefix .. "G"],
        b = menu.ui[prefix .. "B"],
        a = 255
    }, 0, function(r, g, b)
        menu.setThemeColor(prefix, r, g, b, true)
    end)
    menu.ui.items[prefix .. "Color"] = item
    return item
end

function menu.applyThemePreset(index, save)
    index = math.floor(math.max(1, math.min(7, tonumber(index) or 1)))
    menu.ui.themePreset = index
    local preset = menu.themePresets[index]
    if preset then
        for prefix, color in pairs(preset) do
            menu.ui[prefix .. "R"] = color[1]
            menu.ui[prefix .. "G"] = color[2]
            menu.ui[prefix .. "B"] = color[3]
        end
    end
    menu.applyAccentTheme()
    if menu.syncUiSettingItems then menu.syncUiSettingItems() end
    if save and menu.queueUiSettingsSave then menu.queueUiSettingsSave() end
end

