menu.encodeConfigString = LPH_JIT(function(value)
    return (tostring(value or ""):gsub(".", function(ch)
        return string.format("%02X", string.byte(ch))
    end))
end)

menu.decodeConfigString = LPH_JIT(function(value)
    value = tostring(value or "")
    if #value % 2 ~= 0 or value:find("[^%x]") then return nil end
    return (value:gsub("(%x%x)", function(pair)
        return string.char(tonumber(pair, 16))
    end))
end)

menu.isSupportedImagePath = LPH_JIT(function(path)
    path = tostring(path or ""):match("^%s*(.-)%s*$") or ""
    if path == "" then return true end
    if #path > 512 or path:find("[\r\n]") then return false end
    local extension = path:lower():match("%.([%a%d]+)$")
    return extension == "png" or extension == "jpg" or extension == "jpeg"
        or extension == "bmp" or extension == "gif"
end)

menu.createTexture = LPH_JIT(function(path)
    if not path or path == "" then return nil end
    if FileMgr and type(FileMgr.DoesFileExist) == "function" then
        local existsOk, exists = pcall(FileMgr.DoesFileExist, path)
        if not existsOk or not exists then return nil end
    end
    -- Enhanced exposes the Texture registry; older D3D11 hosts expose GUI.CreateTexture.
    local texture = nil
    if Texture and type(Texture.LoadTexture) == "function"
        and type(Texture.IsTextureValid) == "function" and type(Texture.GetTexture) == "function" then
        local loaded, id = pcall(Texture.LoadTexture, path)
        if loaded and type(id) == "number" then
            local checked, valid = pcall(Texture.IsTextureValid, id)
            if checked and valid then
                local resolved, value = pcall(Texture.GetTexture, id)
                if resolved then texture = value end
            end
        end
    end
    if not texture and GUI and type(GUI.CreateTexture) == "function" then
        local created, value = pcall(GUI.CreateTexture, path)
        if created then texture = value end
    end
    if not texture then return nil end
    local checked, width, height = pcall(function()
        return texture:GetWidth(), texture:GetHeight()
    end)
    if not checked or type(width) ~= "number" or type(height) ~= "number"
        or width <= 0 or height <= 0 then return nil end
    return texture
end)

menu.setAvatarPath = LPH_JIT(function(path, save)
    path = tostring(path or ""):match("^%s*(.-)%s*$") or ""
    if not menu.isSupportedImagePath(path) then return false, "unsupported_image" end
    local resolved = path ~= "" and path or menu.visualAssets.defaultLogoPath
    if path == "" and not menu.visualAssets.logoTexture then
        menu.visualAssets.logoTexture = menu.createTexture(menu.visualAssets.defaultLogoPath)
    end
    local texture = path == "" and menu.visualAssets.logoTexture or menu.createTexture(resolved)
    if not texture then return false, "image_load_failed" end
    menu.ui.avatarPath = path
    menu.ui.avatarPathPending = path
    menu.visualAssets.avatarTexture = texture
    menu.visualAssets.avatarLoadedPath = resolved
    if save and menu.queueUiSettingsSave then menu.queueUiSettingsSave() end
    return true
end)

menu.ensureVisualAssets = LPH_NO_VIRTUALIZE(function()
    local now = os.clock()
    if menu.ensureEmbeddedTexture then
        menu.visualAssets.logoTexture = menu.ensureEmbeddedTexture("sovereign-general.png")
    elseif not menu.visualAssets.logoTexture and now >= (menu.visualAssets.logoRetryAt or 0) then
        menu.visualAssets.logoTexture = menu.createTexture(menu.visualAssets.defaultLogoPath)
        menu.visualAssets.logoRetryAt = menu.visualAssets.logoTexture and 0 or (now + 5.0)
    end
    local desired = (menu.ui.avatarPath and menu.ui.avatarPath ~= "")
        and menu.ui.avatarPath or menu.visualAssets.defaultLogoPath
    if not menu.visualAssets.avatarTexture or menu.visualAssets.avatarLoadedPath ~= desired then
        local texture = nil
        if desired == menu.visualAssets.defaultLogoPath then
            texture = menu.visualAssets.logoTexture
        else
            texture = menu.createTexture(desired)
        end
        if texture then
            menu.visualAssets.avatarTexture = texture
            menu.visualAssets.avatarLoadedPath = desired
        elseif desired ~= menu.visualAssets.defaultLogoPath then
            menu.ui.avatarPath = ""
            menu.ui.avatarPathPending = ""
            menu.visualAssets.avatarTexture = menu.visualAssets.logoTexture
            menu.visualAssets.avatarLoadedPath = menu.visualAssets.defaultLogoPath
            if menu.ui.items and menu.ui.items.avatarPath then menu.ui.items.avatarPath.value = "" end
            if menu.ui.configLoaded and menu.queueUiSettingsSave then menu.queueUiSettingsSave() end
        end
    end
end)

menu.imageColorByte = LPH_NO_VIRTUALIZE(function(value)
    return math.max(0, math.min(255, math.floor((tonumber(value) or 0) + 0.5)))
end)
menu.packImageColor = LPH_NO_VIRTUALIZE(function(r, g, b, a)
    local byte = menu.imageColorByte
    local rr, gg, bb, aa = byte(r), byte(g), byte(b), byte(a)
    return rr | (gg << 8) | (bb << 16) | (aa << 24)
end)

menu.textureFrameCache = setmetatable({}, {__mode = "k"})
menu.readTextureCurrent = LPH_NO_VIRTUALIZE(function(texture) return texture:GetCurrent() end)
menu.drawTexture = LPH_NO_VIRTUALIZE(function(texture, x, y, width, height, uv0x, uv0y, uv1x, uv1y, rounding, tintR, tintG, tintB, tintA)
    if not texture or not ImGui or type(ImGui.AddImage) ~= "function" then return false end
    local frame = menu._visualFrame
    local cached = menu.textureFrameCache[texture]
    if not cached then cached = {}; menu.textureFrameCache[texture] = cached end
    if not frame or cached.frame ~= frame then
        local ok, current = pcall(menu.readTextureCurrent, texture)
        cached.current, cached.frame = ok and current or nil, frame
    end
    local current = cached.current
    if current == nil or current == false or current == 0 then return false end
    local tint = menu.packImageColor(tintR or 255, tintG or 255, tintB or 255, (tintA or 255) * (menu.renderAlpha or 1.0))
    if rounding and rounding > 0 and type(ImGui.AddImageRounded) == "function" then
        local rounded, result = pcall(ImGui.AddImageRounded, current, x, y, x + width, y + height,
            uv0x or 0, uv0y or 0, uv1x or 1, uv1y or 1, tint, rounding)
        if rounded and result ~= false then return true end
    end
    local drawn, result = pcall(ImGui.AddImage, current, x, y, x + width, y + height,
        uv0x or 0, uv0y or 0, uv1x or 1, uv1y or 1, tint)
    return drawn and result ~= false
end)

-- Bundled images support single-file distribution; existing assets are reused.
menu.embeddedResources = {
    ["sovereign-general.png"] = {bytes=391717, hash="8fcf3eac04aaaf28", data=[=[]=]},
    ["solstice-icons.png"] = {bytes=7008, hash="db177fa0deb03671", data=[=[]=]}
}
menu.embeddedResourceState = {paths = {}, errors = {}, textures = {}}

function menu.decodeEmbeddedResource(value)
    if type(value) ~= "string" or #value % 4 ~= 0 then return nil end
    local alphabet, lookup, parts = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", {}, {}
    for index = 1, #alphabet do lookup[alphabet:byte(index)] = index - 1 end
    for index = 1, #value, 4 do
        local a, b, c, d = value:byte(index, index + 3)
        local aa, bb, cc, dd = lookup[a], lookup[b], lookup[c], lookup[d]
        if not aa or not bb or (not cc and c ~= 61) or (not dd and d ~= 61) then return nil end
        if c == 61 and (d ~= 61 or index + 3 ~= #value) then return nil end
        if d == 61 and index + 3 ~= #value then return nil end
        local packed = (aa << 18) | (bb << 12) | ((cc or 0) << 6) | (dd or 0)
        parts[#parts + 1] = c == 61 and string.char((packed >> 16) & 255)
            or d == 61 and string.char((packed >> 16) & 255, (packed >> 8) & 255)
            or string.char((packed >> 16) & 255, (packed >> 8) & 255, packed & 255)
    end
    return table.concat(parts)
end

function menu.readEmbeddedCacheFile(path)
    if io and type(io.open) == "function" then
        local ok, body = pcall(function()
            local file = io.open(path, "rb")
            if not file then return nil end
            local read, content = pcall(file.read, file, "*a")
            local closed, result = pcall(file.close, file)
            if read and closed and result then return content end
        end)
        if ok and type(body) == "string" then return body end
    end
    if FileMgr and type(FileMgr.ReadFileContent) == "function"
        and type(FileMgr.DoesFileExist) == "function" then
        local found, exists = pcall(FileMgr.DoesFileExist, path)
        if found and exists then
            local ok, body = pcall(FileMgr.ReadFileContent, path)
            if ok and type(body) == "string" then return body end
        end
    end
    return nil
end

function menu.writeEmbeddedCacheFile(path, body)
    local reason = "binary IO unavailable"
    if io and type(io.open) == "function" then
        local ok, detail = pcall(function()
            local file, openError = io.open(path, "wb")
            assert(file, "io.open(wb): " .. tostring(openError))
            local wrote, result, writeError = pcall(file.write, file, body)
            local closed, closeResult, closeError = pcall(file.close, file)
            assert(wrote and result, "io.write: " .. tostring(wrote and writeError or result))
            assert(closed and closeResult, "io.close: " .. tostring(closed and closeError or closeResult))
            assert(menu.readEmbeddedCacheFile(path) == body, "binary readback did not match")
        end)
        if ok then return true end
        reason = tostring(detail)
    end
    if FileMgr and type(FileMgr.WriteFileContent) == "function" then
        local ok, result = pcall(FileMgr.WriteFileContent, path, body, false)
        if menu.readEmbeddedCacheFile(path) == body then return true end
        reason = reason .. "; FileMgr.WriteFileContent=" .. tostring(result) .. " (call=" .. tostring(ok) .. ")"
    end
    if FileMgr and type(FileMgr.DeleteFile) == "function" then pcall(FileMgr.DeleteFile, path) end
    if os and type(os.remove) == "function" then pcall(os.remove, path) end
    return false, reason
end

function menu.ensureEmbeddedResource(name)
    local state, resource = menu.embeddedResourceState, menu.embeddedResources[name]
    if state.paths[name] then return state.paths[name] end
    if state.errors[name] then return nil, state.errors[name] end
    local function fail(reason)
        state.errors[name] = reason
        if type(SovereignLogError) == "function" then pcall(SovereignLogError, "Sovereign assets", reason) end
        return nil, reason
    end
    if type(resource) ~= "table" then return fail("bundled_asset_unknown") end
    if not FileMgr or type(FileMgr.GetMenuRootPath) ~= "function" then return fail("asset_root_unavailable") end
    local rootOk, root = pcall(FileMgr.GetMenuRootPath)
    if not rootOk or type(root) ~= "string" or root == "" then return fail("asset_root_unavailable") end
    root = root:gsub("/", "\\"):gsub("\\+$", "")
    local directory = root .. "\\Lua\\SovereignAssets"
    local path = directory .. "\\" .. name
    for _, candidate in ipairs({path, root .. "\\Cache\\Sovereign-r9-" .. resource.hash .. "-" .. name}) do
        local body = menu.readEmbeddedCacheFile(candidate)
        if type(body) == "string" and #body == resource.bytes
            and body:sub(1, 8) == "\137PNG\r\n\26\n" then
            state.paths[name] = candidate
            return candidate
        end
    end
    local body = menu.decodeEmbeddedResource(resource.data)
    if not body or #body ~= resource.bytes or body:sub(1, 8) ~= "\137PNG\r\n\26\n" then
        return fail("bundled_asset_payload_invalid: " .. name)
    end
    if type(FileMgr.CreateDir) == "function" then pcall(FileMgr.CreateDir, directory) end
    local saved, reason = menu.writeEmbeddedCacheFile(path, body)
    if not saved then return fail("Could not create visual asset [" .. path .. "]: " .. tostring(reason)) end
    state.paths[name] = path
    return path
end

-- Only reads paths prepared by a Script job; allocation and polling stay on PresentFrame.
menu.ensureEmbeddedTexture = LPH_NO_VIRTUALIZE(function(name)
    local state, frame = menu.embeddedResourceState, menu._visualFrame or 0
    local path = state.paths[name]
    if not path then return nil, state.errors[name] or "resource_not_prepared" end
    local textureState = state.textures[name]
    if not textureState then
        textureState = {path = path, status = "waiting_texture", startedFrame = frame}
        state.textures[name] = textureState
    end
    if textureState.error then return nil, textureState.error end
    if textureState.frame == frame then
        return textureState.status == "ready" and textureState.texture or nil
    end
    textureState.frame = frame
    if not textureState.allocated then
        textureState.allocated = true
        local loader = Texture and (Texture.LoadTextureAsync or Texture.LoadTexture)
        if type(loader) == "function" and type(Texture.IsTextureValid) == "function" and type(Texture.GetTexture) == "function" then
            local ok, id = pcall(loader, path)
            if ok and type(id) == "number" and id >= 0 then textureState.textureId = id
            else textureState.error = "texture_allocation_failed" end
        elseif GUI and type(GUI.CreateTexture) == "function" then
            local ok, texture = pcall(GUI.CreateTexture, path)
            if ok and texture then textureState.texture = texture
            else textureState.error = "texture_allocation_failed" end
        else textureState.error = "texture_api_unavailable" end
    end
    if not textureState.error and not textureState.texture and textureState.textureId ~= nil then
        local checked, valid = pcall(Texture.IsTextureValid, textureState.textureId)
        if checked and valid then
            local ok, texture = pcall(Texture.GetTexture, textureState.textureId)
            if ok and texture then textureState.texture = texture end
        end
    end
    if textureState.texture then
        local ok, current = pcall(menu.readTextureCurrent, textureState.texture)
        textureState.current = ok and current or false
        if menu.textureFrameCache then
            local cached = menu.textureFrameCache[textureState.texture]
            if not cached then cached = {}; menu.textureFrameCache[textureState.texture] = cached end
            cached.current, cached.frame = textureState.current, frame
        end
        if textureState.current and textureState.current ~= 0 then
            textureState.status = "ready"
            textureState.lastReadyFrame = frame
        else textureState.status = "waiting_texture" end
    end
    if textureState.status ~= "ready" and frame - (textureState.lastReadyFrame or textureState.startedFrame) >= 600 then
        textureState.error = "texture_ready_timeout"
    end
    if textureState.error then textureState.status = "error"; return nil, textureState.error end
    return textureState.status == "ready" and textureState.texture or nil
end)

