local HexToRGBAInt = LPH_NO_VIRTUALIZE(function(hex, alpha)
    local themed = menu.resolveThemeColor(hex)
    if themed then
        local renderAlpha = math.max(0.0, math.min(1.0, tonumber(menu.renderAlpha) or 1.0))
        local brightness = math.max(0.0, math.min(1.0, tonumber(menu.colorBrightness) or 1.0))
        return math.floor(themed[1] * brightness + 0.5),
            math.floor(themed[2] * brightness + 0.5),
            math.floor(themed[3] * brightness + 0.5),
            math.floor(((alpha or 1.0) * 255 * renderAlpha) + 0.5)
    end
    local cacheKey = tostring(hex)
    menu.rgbaIntCache = menu.rgbaIntCache or {}
    local cached = menu.rgbaIntCache[cacheKey]
    if cached then
        local renderAlpha = math.max(0.0, math.min(1.0, tonumber(menu.renderAlpha) or 1.0))
        local brightness = math.max(0.0, math.min(1.0, tonumber(menu.colorBrightness) or 1.0))
        return math.floor((cached[1] * brightness) + 0.5),
            math.floor((cached[2] * brightness) + 0.5),
            math.floor((cached[3] * brightness) + 0.5),
            math.floor(((alpha or 1.0) * 255 * renderAlpha) + 0.5)
    end
    hex = hex:gsub("#", "")
    local r = tonumber(hex:sub(1, 2), 16)
    local g = tonumber(hex:sub(3, 4), 16)
    local b = tonumber(hex:sub(5, 6), 16)
    menu.rgbaIntCache[cacheKey] = {r, g, b}
    local renderAlpha = math.max(0.0, math.min(1.0, tonumber(menu.renderAlpha) or 1.0))
    local brightness = math.max(0.0, math.min(1.0, tonumber(menu.colorBrightness) or 1.0))
    return math.floor((r * brightness) + 0.5),
        math.floor((g * brightness) + 0.5),
        math.floor((b * brightness) + 0.5),
        math.floor(((alpha or 1.0) * 255 * renderAlpha) + 0.5)
end)

local HexToRGBAFloat = LPH_NO_VIRTUALIZE(function(hex, alpha)
    local themed = menu.resolveThemeColor(hex)
    if themed then
        local brightness = math.max(0.0, math.min(1.0, tonumber(menu.colorBrightness) or 1.0))
        return (themed[1] / 255) * brightness,
            (themed[2] / 255) * brightness,
            (themed[3] / 255) * brightness,
            alpha or 1.0
    end
    local cacheKey = tostring(hex)
    menu.rgbaFloatCache = menu.rgbaFloatCache or {}
    local cached = menu.rgbaFloatCache[cacheKey]
    if cached then
        local brightness = math.max(0.0, math.min(1.0, tonumber(menu.colorBrightness) or 1.0))
        return cached[1] * brightness, cached[2] * brightness, cached[3] * brightness, alpha or 1.0
    end
    hex = hex:gsub("#", "")
    local r = tonumber(hex:sub(1, 2), 16) / 255
    local g = tonumber(hex:sub(3, 4), 16) / 255
    local b = tonumber(hex:sub(5, 6), 16) / 255
    menu.rgbaFloatCache[cacheKey] = {r, g, b}
    local brightness = math.max(0.0, math.min(1.0, tonumber(menu.colorBrightness) or 1.0))
    return r * brightness, g * brightness, b * brightness, alpha or 1.0
end)

function menu.applyAccentTheme()
    menu.refreshThemeColors()
    local theme = rawget(_G, "SovereignOverlayTheme")
    if type(theme) ~= "table" then return end
    theme.background = {menu.ui.backgroundR, menu.ui.backgroundG, menu.ui.backgroundB, 238}
    theme.header = {menu.ui.controlR, menu.ui.controlG, menu.ui.controlB, 230}
    theme.border = {menu.ui.borderR, menu.ui.borderG, menu.ui.borderB, 230}
    theme.row = {menu.ui.panelR, menu.ui.panelG, menu.ui.panelB, 188}
    theme.text = {menu.ui.textR / 255, menu.ui.textG / 255, menu.ui.textB / 255, 0.94}
    theme.secondary = {menu.ui.mutedR / 255, menu.ui.mutedG / 255, menu.ui.mutedB / 255, 1.0}
    theme.accent = {
        (tonumber(menu.ui.accentR) or 176) / 255,
        (tonumber(menu.ui.accentG) or 180) / 255,
        (tonumber(menu.ui.accentB) or 255) / 255,
        1.0
    }
end

menu.hsvToRgb = LPH_NO_VIRTUALIZE(function(hue, saturation, value)
    local h = ((tonumber(hue) or 0) % 1.0) * 6.0
    local s = math.max(0.0, math.min(1.0, tonumber(saturation) or 1.0))
    local v = math.max(0.0, math.min(1.0, tonumber(value) or 1.0))
    local sector = math.floor(h)
    local fraction = h - sector
    local p = v * (1.0 - s)
    local q = v * (1.0 - (s * fraction))
    local t = v * (1.0 - (s * (1.0 - fraction)))
    local r, g, b
    if sector == 0 then
        r, g, b = v, t, p
    elseif sector == 1 then
        r, g, b = q, v, p
    elseif sector == 2 then
        r, g, b = p, v, t
    elseif sector == 3 then
        r, g, b = p, q, v
    elseif sector == 4 then
        r, g, b = t, p, v
    else
        r, g, b = v, p, q
    end
    return math.floor((r * 255.0) + 0.5), math.floor((g * 255.0) + 0.5), math.floor((b * 255.0) + 0.5)
end)

menu.getRgbBorderGeometry = LPH_NO_VIRTUALIZE(function(x, y, width, height, radius)
    local profile = math.floor(tonumber(menu.ui.performanceProfile) or 2)
    local cached = menu._rgbBorderGeometry
    if cached and cached.x == x and cached.y == y and cached.width == width
        and cached.height == height and cached.radius == radius and cached.profile == profile then
        return cached.points
    end
    local points = {}
    local function addPoint(px, py)
        points[#points + 1] = {x = px, y = py, progress = 0.0, length = 0.0}
    end
    local edgeW = math.max(1.0, width - (radius * 2.0))
    local edgeH = math.max(1.0, height - (radius * 2.0))
    -- Keep the rail smooth enough to hide joins, but cap per-frame geometry.
    -- The moving beam is drawn only near its lamps, so dense sampling here
    -- adds cost without improving the visible result.
    local hCap, vCap, minH, minV, cornerSegments
    if profile <= 1 then
        hCap, vCap, minH, minV, cornerSegments = 72, 44, 24, 16, 10
    elseif profile == 2 then
        hCap, vCap, minH, minV, cornerSegments = 140, 80, 40, 24, 12
    else
        hCap, vCap, minH, minV, cornerSegments = 220, 120, 56, 32, 16
    end
    local horizontalSegments = math.max(minH, math.min(hCap, math.ceil(edgeW / 5.5)))
    local verticalSegments = math.max(minV, math.min(vCap, math.ceil(edgeH / 5.5)))
    for index = 0, horizontalSegments - 1 do
        addPoint(x + radius + (edgeW * index / horizontalSegments), y)
    end
    for index = 0, cornerSegments - 1 do
        local angle = (-math.pi * 0.5) + ((index / cornerSegments) * (math.pi * 0.5))
        addPoint(x + width - radius + (math.cos(angle) * radius), y + radius + (math.sin(angle) * radius))
    end
    for index = 0, verticalSegments - 1 do
        addPoint(x + width, y + radius + (edgeH * index / verticalSegments))
    end
    for index = 0, cornerSegments - 1 do
        local angle = (index / cornerSegments) * (math.pi * 0.5)
        addPoint(x + width - radius + (math.cos(angle) * radius), y + height - radius + (math.sin(angle) * radius))
    end
    for index = 0, horizontalSegments - 1 do
        addPoint(x + width - radius - (edgeW * index / horizontalSegments), y + height)
    end
    for index = 0, cornerSegments - 1 do
        local angle = (math.pi * 0.5) + ((index / cornerSegments) * (math.pi * 0.5))
        addPoint(x + radius + (math.cos(angle) * radius), y + height - radius + (math.sin(angle) * radius))
    end
    for index = 0, verticalSegments - 1 do
        addPoint(x, y + height - radius - (edgeH * index / verticalSegments))
    end
    for index = 0, cornerSegments - 1 do
        local angle = math.pi + ((index / cornerSegments) * (math.pi * 0.5))
        addPoint(x + radius + (math.cos(angle) * radius), y + radius + (math.sin(angle) * radius))
    end
    local totalLength = 0.0
    for index = 1, #points do
        local nextPoint = points[(index % #points) + 1]
        local dx = nextPoint.x - points[index].x
        local dy = nextPoint.y - points[index].y
        points[index].length = math.sqrt((dx * dx) + (dy * dy))
        local length = points[index].length
        points[index].unitX = length > 0 and dx / length or 0
        points[index].unitY = length > 0 and dy / length or 0
        totalLength = totalLength + points[index].length
    end
    local traversed = 0.0
    for index = 1, #points do
        points[index].progress = totalLength > 0.0 and (traversed / totalLength) or 0.0
        traversed = traversed + points[index].length
    end
    menu._rgbBorderGeometry = {x = x, y = y, width = width, height = height, radius = radius, profile = profile, points = points}
    return points
end)

menu.getRgbBorderDrawGeometry = LPH_NO_VIRTUALIZE(function(points, thickness)
    local cached = menu._rgbBorderDrawGeometry
    if cached and cached.points == points and cached.thickness == thickness then return cached.lines end
    local lines = {}
    for index = 1, #points do
        local point, nextPoint = points[index], points[(index % #points) + 1]
        local x1, y1, x2, y2 = point.x, point.y, nextPoint.x, nextPoint.y
        local nx, ny = 0.0, 0.0
        if point.length > 0.0 then
            local overlap = math.min(math.max(0.55, thickness * 0.24), point.length * 0.44)
            local dx, dy = point.unitX * overlap, point.unitY * overlap
            x1, y1, x2, y2 = x1 - dx, y1 - dy, x2 + dx, y2 + dy
            nx, ny = -point.unitY, point.unitX
        end
        local nextProgress = nextPoint.progress
        if nextProgress <= point.progress then nextProgress = nextProgress + 1.0 end
        lines[index] = {
            progress = ((point.progress + nextProgress) * 0.5) % 1.0,
            x1 + nx * 0.62, y1 + ny * 0.62, x2 + nx * 0.62, y2 + ny * 0.62,
            x1 - nx * 0.12, y1 - ny * 0.12, x2 - nx * 0.12, y2 - ny * 0.12,
            x1 - nx * 0.72, y1 - ny * 0.72, x2 - nx * 0.72, y2 - ny * 0.72,
        }
    end
    menu._rgbBorderDrawGeometry = {points = points, thickness = thickness, lines = lines}
    return lines
end)

menu.drawAnimatedRgbBorder = LPH_NO_VIRTUALIZE(function(x, y, width, height, timeValue)
    local intensity = math.max(0.0, math.min(100.0, tonumber(menu.ui.rgbGlow) or 0.0))
    local thickness = math.max(1.0, math.min(6.0, tonumber(menu.ui.rgbThickness) or 2.8))
    local speed = math.max(0.1, math.min(3.0, tonumber(menu.ui.rgbSpeed) or 0.85))
    local density = math.floor(math.max(1.0, math.min(8.0, tonumber(menu.ui.rgbDensity) or 4.0)) + 0.5)
    -- Keep the animated rail visually restrained on the normal/performance
    -- profiles. Users can still opt into the full density on the high profile.
    local profile = math.floor(tonumber(menu.ui.performanceProfile) or 2)
    if profile <= 1 then density = math.min(density, 1)
    elseif profile == 2 then density = math.min(density, 3) end
    local renderAlpha = math.max(0.0, math.min(1.0, tonumber(menu.renderAlpha) or 1.0))
    local inset = math.max(7.0, (thickness * 0.5) + 5.0)
    local borderX = x + inset
    local borderY = y + inset
    local borderW = math.max(32.0, width - (inset * 2.0))
    local borderH = math.max(32.0, height - (inset * 2.0))
    -- The RGB path is inset from the actual window edge. Subtracting the
    -- inset keeps its centerline parallel to the window's 14px rounded edge.
    local radius = math.max(5.0, math.min(10.0, 14.0 - inset))
    local points = menu.getRgbBorderGeometry(borderX, borderY, borderW, borderH, radius)
    local lines = menu.getRgbBorderDrawGeometry(points, thickness)
    local segments = #lines
    local phase = (tonumber(timeValue) or 0.0) * speed * 0.16
    local intensityRatio = intensity / 100.0
    local spotlight = (phase * 0.72 + 0.12) % 1.0
    local spotlightWidth = 0.035 + (intensityRatio * 0.035)
    local colors = menu._rgbLampColors or {}
    menu._rgbLampColors = colors
    -- Each lamp shares one color across all of its illuminated segments.
    for slot = 0, density - 1 do
        local color = colors[slot + 1]
        if not color then color = {}; colors[slot + 1] = color end
        local r, g, b = menu.hsvToRgb((phase + slot / density) % 1.0, 0.72, 1.0)
        color[1], color[2], color[3] = r, g, b
        color[4], color[5], color[6] = math.floor(r * 0.30), math.floor(g * 0.30), math.floor(b * 0.30)
    end
    local beamThickness, highlightThickness = math.max(1.0, thickness * 0.86), math.max(0.65, thickness * 0.22)
    local railR, railG, railB = 52, 52, 71
    ImGui.AddRect(borderX, borderY, borderX + borderW, borderY + borderH,
        railR, railG, railB, math.floor(210.0 * renderAlpha), radius, 0, thickness + 0.8)
    for segment = 1, segments do
        local line = lines[segment]
        local colorProgress = line.progress
        -- Equally spaced lamps have a closed-form nearest-lamp lookup. This
        -- avoids an inner density loop for every border segment.
        local lampOffset = ((colorProgress - spotlight + 0.5) % 1.0) - 0.5
        local lampIndex = math.floor((lampOffset * density) + 0.5)
        local nearestOffset = lampOffset - (lampIndex / density)
        local lampDistance = math.abs(nearestOffset)
        local spotlightFactor = math.max(0.0, 1.0 - (lampDistance / spotlightWidth))
        spotlightFactor = spotlightFactor * spotlightFactor * (3.0 - (2.0 * spotlightFactor))
        if spotlightFactor > 0.002 then
            local color = colors[(lampIndex % density) + 1]
            local beamAlpha = math.floor((48.0 + (spotlightFactor * (142.0 + (intensityRatio * 62.0)))) * renderAlpha)
            ImGui.AddLine(line[1], line[2], line[3], line[4], color[4], color[5], color[6], math.floor(beamAlpha * 0.88), thickness)
            ImGui.AddLine(line[5], line[6], line[7], line[8], color[1], color[2], color[3], beamAlpha, beamThickness)
            ImGui.AddLine(line[9], line[10], line[11], line[12], 255, 255, 255, math.floor(beamAlpha * 0.48), highlightThickness)
        end
    end
end)

-- API Implementation
function menu.tab(name)
    local id = #menu.tabs + 1
    menu.tabs[id] = { id = id, sourceName = name, name = menu.canonicalEnglish(name), subtabs = {} }
    if id == 1 then menu.activeTab = 1 end
    return id
end

function menu.subtab(name, tabID)
    local tab = menu.tabs[tabID]
    if not tab then return -1 end
    local subtab = { id = #globalSubtabs + 1, sourceName = name, name = menu.canonicalEnglish(name), groups = {}, tabID = tabID }
    table.insert(tab.subtabs, subtab)
    globalSubtabs[subtab.id] = subtab
    if tabID == 1 and #tab.subtabs == 1 then menu.activeSubtab = subtab.id end
    return subtab.id
end

function menu.group(name, subtabID)
    local subtab = globalSubtabs[subtabID]
    if not subtab then return -1 end
    local group = {
        id = #globalGroups + 1,
        sourceName = name,
        name = menu.canonicalEnglish(name),
        items = {},
        subtabID = subtabID,
        hidden = false,
        compact = false,
        itemGap = nil,
        noSplit = false,
    }
    table.insert(subtab.groups, group)
    globalGroups[group.id] = group
    return group.id
end

function menu.setGroupHidden(groupID, hidden)
    local group = globalGroups[groupID]
    if group then
        group.hidden = hidden == true
        if menu.quick then menu.quick.searchDirty = true end
        if menu.quick and menu.quick.loaded then
            menu.refreshQuickGroups()
        end
    end
end

function menu.button(label, description, groupID, indent, callback)
    local group = globalGroups[groupID]
    if not group then return end
    globalItemUid = globalItemUid + 1
    local item = { type = "button", uid = globalItemUid, sourceLabel = label, sourceDescription = description,
        label = menu.canonicalEnglish(label), description = menu.canonicalEnglish(description),
        indent = indent or 0, callback = callback }
    table.insert(group.items, item)
    menu.registerQuickItem(item, groupID)
    return item
end

function menu.toggle(label, description, groupID, indent, callback)
    local group = globalGroups[groupID]
    if not group then return end
    globalItemUid = globalItemUid + 1
    local item = { type = "toggle", uid = globalItemUid, sourceLabel = label, sourceDescription = description,
        label = menu.canonicalEnglish(label), description = menu.canonicalEnglish(description),
        indent = indent or 0, callback = callback, value = false }
    table.insert(group.items, item)
    menu.registerQuickItem(item, groupID)
    return item
end

function menu.slider(label, description, groupID, min, max, default, format, indent, callback)
    local group = globalGroups[groupID]
    if not group then return end
    globalItemUid = globalItemUid + 1
    local item = { type = "slider", uid = globalItemUid, sourceLabel = label, sourceDescription = description,
        label = menu.canonicalEnglish(label), description = menu.canonicalEnglish(description),
        min = min, max = max, value = default, format = format or "%d", indent = indent or 0, callback = callback }
    table.insert(group.items, item)
    menu.registerQuickItem(item, groupID)
    return item
end

function menu.color(label, description, groupID, defaultColor, indent, callback)
    local group = globalGroups[groupID]
    if not group then return end
    local source = type(defaultColor) == "table" and defaultColor or {}
    globalItemUid = globalItemUid + 1
    local item = {
        type = "color",
        uid = globalItemUid,
        sourceLabel = label,
        sourceDescription = description,
        label = menu.canonicalEnglish(label),
        description = menu.canonicalEnglish(description),
        indent = indent or 0,
        callback = callback,
        value = {
            r = tonumber(source.r or source[1]) or 255,
            g = tonumber(source.g or source[2]) or 255,
            b = tonumber(source.b or source[3]) or 255,
            a = tonumber(source.a or source[4]) or 255
        }
    }
    table.insert(group.items, item)
    menu.registerQuickItem(item, groupID)
    return item
end

function menu.combo(label, description, groupID, options, defaultIdx, indent, callback)
    local group = globalGroups[groupID]
    if not group then return end
    globalItemUid = globalItemUid + 1
    local sourceOptions = type(options) == "table" and options or {}
    -- Keep option source values intact. The renderer translates each option,
    -- which preserves exact Chinese wording when English literals such as
    -- "Default" or "UFO" are also used by the game.
    local displayOptions = {}
    for index, option in ipairs(sourceOptions) do
        displayOptions[index] = option
        if type(option) == "string" and not menu.translations[option]
            and not option:find("[\228-\233]") then
            menu.nativeEnglishLiterals[option] = true
        end
    end
    local item = { type = "combo", uid = globalItemUid, sourceLabel = label, sourceDescription = description,
        label = menu.canonicalEnglish(label), description = menu.canonicalEnglish(description),
        sourceOptions = sourceOptions, options = displayOptions, value = defaultIdx,
        indent = indent or 0, callback = callback }
    table.insert(group.items, item)
    menu.registerQuickItem(item, groupID)
    return item
end

function menu.inputText(label, description, groupID, default, indent, callback, hint)
    local group = globalGroups[groupID]
    if not group then return end
    globalItemUid = globalItemUid + 1
    local item = { type = "input", uid = globalItemUid, sourceLabel = label, sourceDescription = description,
        label = menu.canonicalEnglish(label), description = menu.canonicalEnglish(description),
        value = default or "", indent = indent or 0, callback = callback, hint = hint,
        sourceHint = hint }
    table.insert(group.items, item)
    return item
end
function menu.text(label, groupID)
    local group = globalGroups[groupID]
    if not group then return end
    local item = { type = "text", sourceLabel = label, label = menu.canonicalEnglish(label) }
    table.insert(group.items, item)
    return item
end

local function GetSessionPlayers()
    local function is_valid(pid)
        if pid == nil then return false end
        if Players and type(Players.GetById) == "function" then
            local ok, p = pcall(Players.GetById, pid)
            if ok and p ~= nil then return true end
        end
        if Players and type(Players.GetName) == "function" then
            local ok, name = pcall(Players.GetName, pid)
            if ok and type(name) == "string" and name ~= "" and name ~= "Invalid" then
                return true
            end
        end
        return false
    end

    if Players and type(Players.Get) == "function" then
        local ok, list = pcall(Players.Get)
        if ok and type(list) == "table" then
            local filtered = {}
            local seen = {}
            for _, pid in ipairs(list) do
                local numericPid = tonumber(pid)
                if numericPid then
                    numericPid = math.floor(numericPid)
                end
                if numericPid and numericPid >= 0 and numericPid <= 31 and not seen[numericPid] then
                    seen[numericPid] = true
                    table.insert(filtered, numericPid)
                end
            end
            return filtered
        end
    end
    local fallback = {}
    for pid = 0, 31 do
        if is_valid(pid) then
            table.insert(fallback, pid)
        end
    end
    return fallback
end

local function GetPlayerName(pid)
    if Players and type(Players.GetName) == "function" then
        local ok, name = pcall(Players.GetName, pid)
        if ok and type(name) == "string" and name ~= "" then
            return name
        end
    end
    return "Player " .. tostring(pid)
end

function SovereignReadObjectField(object, ...)
    if object == nil then return nil end
    local keys = {...}
    for _, key in ipairs(keys) do
        local ok, value = pcall(function() return object[key] end)
        if ok and value ~= nil then
            return value
        end
    end
    return nil
end

function SovereignGetPlayerObject(pid)
    if not (Players and type(Players.GetById) == "function") then return nil end
    local ok, player = pcall(Players.GetById, pid)
    if ok then return player end
    return nil
end

local function GetPlayerRockstarId(pid)
    local player = SovereignGetPlayerObject(pid)
    if not player then return nil end

    local ok_info, info = pcall(function()
        if type(player.GetGamerInfo) == "function" then
            return player:GetGamerInfo()
        end
        return nil
    end)
    if ok_info and info ~= nil then
        local rid = tonumber(SovereignReadObjectField(info, "RockstarId", "rockstarId", "RID"))
        if rid and rid > 0 then
            return rid
        end
    end

    local ok_info2, pinfo = pcall(function() return player.PlayerInfo end)
    if ok_info2 and pinfo ~= nil then
        local netData = SovereignReadObjectField(pinfo, "NetData", "netData")
        local rid = tonumber(SovereignReadObjectField(netData, "RockstarId", "rockstarId", "RID"))
        if rid and rid > 0 then
            return rid
        end
    end
    return nil
end

do
-- World context helpers. Keep all new native reads behind protected calls so
-- older Cherax/native tables degrade to "unknown" without interrupting the
-- player information, status windows, or vehicle helpers.
local SovereignLocalizationLanguageNames = {
    [0] = "en-US", [1] = "fr-FR", [2] = "de-DE", [3] = "it-IT",
    [4] = "es-ES", [5] = "pt-BR", [6] = "pl-PL", [7] = "ru-RU",
    [8] = "ko-KR", [9] = "zh-TW", [10] = "ja-JP", [11] = "es-MX",
    [12] = "zh-CN"
}
local SovereignLocalizationDateNames = {
    [0] = "MM/DD/YYYY", [1] = "DD/MM/YYYY", [2] = "YYYY/MM/DD"
}

local function SovereignCallNative(apiName, functionName, ...)
    local api = menu.nativeApis and menu.nativeApis[apiName]
    if type(api) ~= "table" then return nil, false end
    local okLookup, fn = pcall(function() return api[functionName] end)
    if not okLookup or type(fn) ~= "function" then return nil, false end
    local result = table.pack(pcall(fn, ...))
    if not result[1] then return nil, false end
    return result[2], true
end

function SovereignReadLocalization()
    local current, currentOk = SovereignCallNative("LOCALIZATION", "GET_CURRENT_LANGUAGE")
    local system, systemOk = SovereignCallNative("LOCALIZATION", "LOCALIZATION_GET_SYSTEM_LANGUAGE")
    local dateType, dateOk = SovereignCallNative("LOCALIZATION", "LOCALIZATION_GET_SYSTEM_DATE_TYPE")
    current, system, dateType = tonumber(current), tonumber(system), tonumber(dateType)
    local languageId = currentOk and current or systemOk and system or nil
    local language = SovereignLocalizationLanguageNames[languageId]
    if not language then language = languageId and ("ID " .. tostring(languageId)) or "Unknown" end
    local systemLanguage = SovereignLocalizationLanguageNames[system]
        or (system and ("ID " .. tostring(system)) or "Unknown")
    local dateFormat = SovereignLocalizationDateNames[dateType] or "YYYY-MM-DD"
    return {
        current = current, system = system, dateType = dateType,
        language = language, systemLanguage = systemLanguage,
        dateFormat = dateFormat,
        display = string.format("%s · %s", language, dateFormat),
        available = currentOk or systemOk or dateOk
    }
end

function SovereignFormatLocalizedDateTime(timestamp, locale)
    locale = locale or SovereignReadLocalization()
    local numeric = tonumber(timestamp)
    if not numeric or not os or type(os.date) ~= "function" then return "Unknown" end
    local ok, parts = pcall(os.date, "*t", numeric)
    if not ok or type(parts) ~= "table" then
        local fallbackOk, fallback = pcall(os.date, "%Y-%m-%d %H:%M:%S", numeric)
        return fallbackOk and tostring(fallback) or "Unknown"
    end
    local year, month, day = tonumber(parts.year) or 0, tonumber(parts.month) or 0, tonumber(parts.day) or 0
    local hour, minute, second = tonumber(parts.hour) or 0, tonumber(parts.min) or 0, tonumber(parts.sec) or 0
    local dateType = tonumber(locale.dateType)
    local date
    if dateType == 0 then
        date = string.format("%02d/%02d/%04d", month, day, year)
    elseif dateType == 1 then
        date = string.format("%02d/%02d/%04d", day, month, year)
    else
        date = string.format("%04d-%02d-%02d", year, month, day)
    end
    return string.format("%s %02d:%02d:%02d", date, hour, minute, second)
end

function SovereignReadZoneDetails(x, y, z)
    x, y, z = tonumber(x), tonumber(y), tonumber(z)
    if not x or not y or not z or x ~= x or y ~= y or z ~= z then
        return {name = "Unknown zone", hash = nil, display = "Unknown zone"}
    end
    local hash, hashOk = SovereignCallNative("ZONE", "GET_ZONE_AT_COORDS", x, y, z)
    local name, nameOk = SovereignCallNative("ZONE", "GET_NAME_OF_ZONE", x, y, z)
    hash = tonumber(hash)
    if hash == 0 then hash = nil end
    if not nameOk or type(name) ~= "string" or name == "" or name == "NULL" then name = "Unknown zone" end
    if not hash and name ~= "Unknown zone" then
        local zoneId, zoneIdOk = SovereignCallNative("ZONE", "GET_ZONE_FROM_NAME_ID", name)
        zoneId = tonumber(zoneId)
        if zoneId and zoneId ~= 0 then hash, hashOk = zoneId, zoneIdOk end
    end
    if hash and hash < 0 then hash = hash + 4294967296 end
    local hashText = hash and string.format("0x%X", math.floor(hash)) or "Unknown hash"
    return {name = name, hash = hash, hashText = hashText,
        display = name .. " · " .. hashText, available = hashOk or nameOk}
end

function SovereignReadZoneFromEntity(entity)
    if not entity or entity == 0 then return {name = "Unknown zone", hash = nil, display = "Unknown zone"} end
    local entityApi = menu.nativeApis and menu.nativeApis.ENTITY
    if type(entityApi) ~= "table" or type(entityApi.GET_ENTITY_COORDS) ~= "function" then
        return {name = "Unknown zone", hash = nil, display = "Unknown zone"}
    end
    local ok, position = pcall(entityApi.GET_ENTITY_COORDS, entity, true)
    if not ok or position == nil then
        return {name = "Unknown zone", hash = nil, display = "Unknown zone"}
    end
    local okX, x = pcall(function() return position.x end)
    local okY, y = pcall(function() return position.y end)
    local okZ, z = pcall(function() return position.z end)
    if not okX or not okY or not okZ then
        return {name = "Unknown zone", hash = nil, display = "Unknown zone"}
    end
    return SovereignReadZoneDetails(x, y, z)
end

function SovereignReadLocalZone()
    local playerApi = menu.nativeApis and menu.nativeApis.PLAYER
    if type(playerApi) ~= "table" or type(playerApi.PLAYER_PED_ID) ~= "function" then
        return {name = "Unknown zone", hash = nil, display = "Unknown zone"}
    end
    local okPed, ped = pcall(playerApi.PLAYER_PED_ID)
    if not okPed or not ped or ped == 0 then
        return {name = "Unknown zone", hash = nil, display = "Unknown zone"}
    end
    return SovereignReadZoneFromEntity(ped)
end

function SovereignReadDlcDiagnostics()
    local function bool(name)
        local value, available = SovereignCallNative("DLC", name)
        if not available or value == nil then return nil end
        return value == true
    end
    local pending = bool("ARE_ANY_CCS_PENDING")
    local cloud = bool("DLC_CHECK_CLOUD_DATA_CORRECT")
    local compat = bool("DLC_CHECK_COMPAT_PACK_CONFIGURATION")
    local badPackOrder = bool("GET_EVER_HAD_BAD_PACK_ORDER")
    local loading = bool("GET_IS_LOADING_SCREEN_ACTIVE")
    local initialLoading = bool("GET_IS_INITIAL_LOADING_SCREEN_ACTIVE")
    local cloudResult, cloudResultAvailable = SovereignCallNative("DLC", "GET_EXTRACONTENT_CLOUD_RESULT")
    local state = "Unavailable"
    if pending == true or loading == true or initialLoading == true then
        state = "Loading"
    elseif cloud == false or compat == false or badPackOrder == true then
        state = "Needs attention"
    elseif pending ~= nil or cloud ~= nil or compat ~= nil or badPackOrder ~= nil
        or loading ~= nil or initialLoading ~= nil or cloudResultAvailable then
        state = "Healthy"
    end
    local detail = string.format("%s · Cloud: %s · Compatibility: %s", state,
        cloud == nil and "Unknown" or (cloud and "Healthy" or "Abnormal"),
        compat == nil and "Unknown" or (compat and "Healthy" or "Abnormal"))
    return {
        state = state, pending = pending, cloud = cloud, compat = compat,
        badPackOrder = badPackOrder, loading = loading,
        initialLoading = initialLoading, cloudResult = tonumber(cloudResult),
        available = state ~= "Unavailable", summary = state, detail = detail
    }
end
end

function SovereignGetPlayerInfoDetails(pid)
    local details = {
        ip = "Unavailable",
        network = "Unknown",
        ping = "Unavailable",
        platform = "PC",
        language = "Unknown",
        country = "Unknown",
        region = "Unknown",
        rank = "Unknown",
        city = "Unknown",
        host = "Unknown",
        coordinates = "Unavailable",
        zone = "Unknown zone"
    }

    if Players then
        local player = SovereignGetPlayerObject(pid)
        local gamerInfo = nil
        if player and type(player.GetGamerInfo) == "function" then
            local ok, value = pcall(function() return player:GetGamerInfo() end)
            if ok then gamerInfo = value end
        end
        local playerInfo = nil
        if player then
            local ok, value = pcall(function() return player.PlayerInfo end)
            if ok then playerInfo = value end
        end
        local netData = SovereignReadObjectField(playerInfo, "NetData", "netData")
        local netAddress = nil
        if type(Players.GetNetAddress) == "function" then
            local ok, value = pcall(Players.GetNetAddress, pid)
            if ok then netAddress = value end
        end
        local socketAddress = nil
        if type(Players.GetIP) == "function" then
            local ok, value = pcall(Players.GetIP, pid)
            if ok then socketAddress = value end
        end
        local ipInfo = nil
        if type(Players.GetIPInfo) == "function" then
            local ok, value = pcall(Players.GetIPInfo, pid)
            if ok then ipInfo = value end
        end

        local function FirstField(default, ...)
            for index = 1, select("#", ...) do
                local candidate = select(index, ...)
                if candidate ~= nil and tostring(candidate) ~= "" then
                    return tostring(candidate)
                end
            end
            return default
        end

        local addrType = SovereignReadObjectField(netAddress, "Type", "type")
        local addrTypeNames = {[0] = "Invalid", [1] = "Direct", [2] = "Relay server", [3] = "Peer relay"}
        if addrType ~= nil then
            details.network = addrTypeNames[tonumber(addrType)] or tostring(addrType)
        end
        if socketAddress ~= nil then
            local ok, value = pcall(function()
                if type(socketAddress.ToString) == "function" then
                    return socketAddress:ToString(false)
                end
                return socketAddress.IPv4
            end)
            if ok and value ~= nil and tostring(value) ~= "" then
                details.ip = tostring(value)
            end
        end
        if details.ip == "Unavailable" and type(Players.GetIPString) == "function" then
            local ok, value = pcall(Players.GetIPString, pid)
            if ok and value ~= nil and tostring(value) ~= "" then
                details.ip = tostring(value)
            end
        end

        details.platform = FirstField(details.platform,
            SovereignReadObjectField(gamerInfo, "Platform", "platform"),
            SovereignReadObjectField(playerInfo, "Platform", "platform"),
            SovereignReadObjectField(netData, "Platform", "platform"))
        details.language = FirstField(details.language,
            SovereignReadObjectField(gamerInfo, "Language", "language"),
            SovereignReadObjectField(playerInfo, "Language", "language"),
            SovereignReadObjectField(netData, "Language", "language"))
        details.country = FirstField(details.country,
            SovereignReadObjectField(ipInfo, "country", "Country", "countryCode", "CountryCode"),
            SovereignReadObjectField(gamerInfo, "Country", "country"),
            SovereignReadObjectField(playerInfo, "Country", "country"),
            SovereignReadObjectField(netData, "Country", "country"))
        details.region = FirstField(details.region,
            SovereignReadObjectField(ipInfo, "region", "Region", "continent", "Continent"),
            SovereignReadObjectField(gamerInfo, "Region", "region"),
            SovereignReadObjectField(playerInfo, "Region", "region"),
            SovereignReadObjectField(netData, "Region", "region"))
        details.rank = FirstField(details.rank,
            SovereignReadObjectField(playerInfo, "Rank", "rank"),
            SovereignReadObjectField(netData, "Rank", "rank"))
        details.city = FirstField(details.city,
            SovereignReadObjectField(ipInfo, "city", "City"),
            SovereignReadObjectField(gamerInfo, "City", "city"),
            SovereignReadObjectField(playerInfo, "City", "city"),
            SovereignReadObjectField(netData, "City", "city"))
        details.ping = FirstField(details.ping,
            SovereignReadObjectField(player, "Ping", "ping"),
            SovereignReadObjectField(playerInfo, "Ping", "ping"),
            SovereignReadObjectField(netData, "Ping", "ping"))
        if details.ping == "Unavailable" and menu.nativeApis.NETWORK and type(menu.nativeApis.NETWORK.NETWORK_GET_AVERAGE_PING) == "function" then
            local ok, value = pcall(menu.nativeApis.NETWORK.NETWORK_GET_AVERAGE_PING, pid)
            if ok and type(value) == "number" and value >= 0 then
                details.ping = string.format("%.0f ms", value)
            end
        end

        local tags = ""
        if type(Players.GetTags) == "function" then
            local ok, value = pcall(Players.GetTags, pid)
            if ok and value ~= nil then tags = tostring(value) end
        end
        local upperTags = string.upper(tostring(tags or ""))
        if upperTags:find("SCRIPT HOST", 1, true) or upperTags:find("SH", 1, true) then
            details.host = "Script host"
        elseif upperTags:find("HOST", 1, true) then
            details.host = "Host"
        elseif upperTags ~= "" then
            details.host = "Online"
        end
    end

    local ok_pos, pos = pcall(function()
        local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
        if not ped or ped == 0 then return nil end
        return menu.nativeApis.ENTITY.GET_ENTITY_COORDS(ped, true)
    end)
    if ok_pos and pos then
        local okx, x = pcall(function() return pos.x end)
        local oky, y = pcall(function() return pos.y end)
        local okz, z = pcall(function() return pos.z end)
        if okx and oky and okz and x ~= nil and y ~= nil and z ~= nil then
            details.coordinates = string.format("%.0f, %.0f, %.0f", x, y, z)
            details.zone = SovereignReadZoneDetails(x, y, z).display
        end
    end
    return details
end

local function GetPlayerDistance(pid)
    local PLAYER_API = rawget(_G, "PLAYER")
    local ENTITY_API = rawget(_G, "ENTITY")

    local function VecFromObj(obj)
        if obj == nil then return nil end
        local ok_pos, pos = pcall(function() return obj.Position end)
        if not ok_pos or pos == nil then return nil end
        local okx, x = pcall(function() return pos.x end)
        local oky, y = pcall(function() return pos.y end)
        local okz, z = pcall(function() return pos.z end)
        if okx and oky and okz and x ~= nil and y ~= nil and z ~= nil then
            return { x = x, y = y, z = z }
        end
        return nil
    end

    local function VecFromPlayerNative(playerId)
        if not (PLAYER_API and ENTITY_API and PLAYER_API.GET_PLAYER_PED_SCRIPT_INDEX and ENTITY_API.GET_ENTITY_COORDS) then
            return nil
        end
        local ok_ped, ped = pcall(PLAYER_API.GET_PLAYER_PED_SCRIPT_INDEX, playerId)
        if not ok_ped or not ped or ped == 0 then return nil end
        local ok_pos, pos = pcall(ENTITY_API.GET_ENTITY_COORDS, ped, true)
        if not ok_pos or pos == nil then return nil end
        local okx, x = pcall(function() return pos.x end)
        local oky, y = pcall(function() return pos.y end)
        local okz, z = pcall(function() return pos.z end)
        if okx and oky and okz and x ~= nil and y ~= nil and z ~= nil then
            return { x = x, y = y, z = z }
        end
        return nil
    end

    local localPos = nil
    local targetPos = nil

    if GTA and type(GTA.GetLocalPed) == "function" then
        local ok_local, localPed = pcall(GTA.GetLocalPed)
        if ok_local and localPed then
            localPos = VecFromObj(localPed)
        end
    end
    if Players and type(Players.GetCPed) == "function" then
        local ok_target, targetPed = pcall(Players.GetCPed, pid)
        if ok_target and targetPed then
            targetPos = VecFromObj(targetPed)
        end
    end

    -- Native fallback is generally more reliable in-session.
    if localPos == nil or targetPos == nil then
        local localId = nil
        if GTA and type(GTA.GetLocalPlayerId) == "function" then
            local ok_id, id = pcall(GTA.GetLocalPlayerId)
            if ok_id then localId = id end
        end
        if localId == nil and PLAYER_API and PLAYER_API.PLAYER_ID then
            local ok_pid, id = pcall(PLAYER_API.PLAYER_ID)
            if ok_pid then localId = id end
        end
        if localPos == nil and localId ~= nil then
            localPos = VecFromPlayerNative(localId)
        end
        if targetPos == nil then
            targetPos = VecFromPlayerNative(pid)
        end
    end

    if not localPos or not targetPos then return nil end
    local dx = localPos.x - targetPos.x
    local dy = localPos.y - targetPos.y
    local dz = localPos.z - targetPos.z
    return math.sqrt((dx * dx) + (dy * dy) + (dz * dz))
end

local function GetPlayerModderStatus(pid, rid, tags)
    local detections = nil
    if ModderDB and type(ModderDB.GetModderDetectionsByPlayerId) == "function" then
        local ok, data = pcall(ModderDB.GetModderDetectionsByPlayerId, pid)
        if ok and type(data) == "table" then
            detections = data
        end
    end
    if detections == nil and rid and ModderDB and type(ModderDB.GetModderDetections) == "function" then
        local ok, data = pcall(ModderDB.GetModderDetections, rid)
        if ok and type(data) == "table" then
            detections = data
        end
    end

    local det_count = 0
    local first_reason = nil
    if type(detections) == "table" then
        for _, v in pairs(detections) do
            det_count = det_count + 1
            if first_reason == nil and type(v) == "table" then
                first_reason = v[1] or v.name
            end
        end
    end

    if det_count > 0 then
        local detail = first_reason and (" - " .. tostring(first_reason)) or ""
        return "Flagged (" .. tostring(det_count) .. ")" .. detail, "danger"
    end

    local tag_text = tostring(tags or "")
    local upper_tags = string.upper(tag_text)
    if upper_tags:find("MODDER", 1, true) or upper_tags:find("SUS", 1, true) then
        return "Suspected flag", "warning"
    end
    return "No records", "ok"
end

local function EnsurePlayerState(pid)
    if pid == nil then return nil end
    local st = playerCtx.states[pid]
    if not st then
        st = {}
        playerCtx.states[pid] = st
    end
    return st
end

function menu.bindPlayerList(tabID)
    if not menu.tabs[tabID] then return false end
    playerCtx.boundTabs[tabID] = true
    if playerCtx.selected == nil then
        local players = GetSessionPlayers()
        playerCtx.selected = players[1] or nil
    end
    return true
end

menu.isPlayerListBound = LPH_NO_VIRTUALIZE(function(tabID)
    return playerCtx.boundTabs[tabID] == true
end)

menu.player = menu.player or {}

function menu.player.select(pid)
    playerCtx.selected = pid
end

function menu.player.get()
    return playerCtx.selected
end

function menu.player.get_name()
    if playerCtx.selected == nil then return nil end
    return GetPlayerName(playerCtx.selected)
end

function menu.pstate(pid)
    local target = pid
    if target == nil then target = playerCtx.selected end
    return EnsurePlayerState(target) or {}
end

local function ResolveSelectedPlayer()
    local pid = playerCtx.selected
    if pid == nil then
        menu.notify("Players", "Select a player first", 2.2, "warning")
        return nil, nil
    end
    if menu.nativeApis.NETWORK and type(menu.nativeApis.NETWORK.NETWORK_IS_PLAYER_ACTIVE) == "function" then
        local ok, active = pcall(menu.nativeApis.NETWORK.NETWORK_IS_PLAYER_ACTIVE, pid)
        if not ok or active ~= true then
            playerCtx.selected = nil
            menu.notify("Players", "The selected player has left the session", 2.2, "warning")
            return nil, nil
        end
    end
    return pid, EnsurePlayerState(pid)
end

function menu.ptoggle(label, description, groupID, key, default, indent, callback)
    local item
    item = menu.toggle(label, description, groupID, indent or 0, function(value)
        local pid, st = ResolveSelectedPlayer()
        if not pid then
            if item then item.value = (item.prevValue ~= nil) and item.prevValue or not value end
            return
        end
        st[key] = value
        if callback then callback(pid, value, st) end
    end)
    if item then
        item.player_bind = { kind = "toggle", key = key, default = (default == nil and false or default) }
    end
    return item
end

function menu.pslider(label, description, groupID, key, min, max, default, format, indent, callback)
    local item
    item = menu.slider(label, description, groupID, min, max, default, format, indent or 0, function(value)
        local pid, st = ResolveSelectedPlayer()
        if not pid then
            if item and item.prevValue ~= nil then item.value = item.prevValue end
            return
        end
        st[key] = value
        if callback then callback(pid, value, st) end
    end)
    if item then
        item.player_bind = { kind = "slider", key = key, default = default }
    end
    return item
end

function menu.pcombo(label, description, groupID, key, options, defaultIdx, indent, callback)
    local item
    item = menu.combo(label, description, groupID, options, defaultIdx, indent or 0, function(idx)
        local pid, st = ResolveSelectedPlayer()
        if not pid then
            if item and item.prevValue ~= nil then item.value = item.prevValue end
            return
        end
        st[key] = idx
        local opt = options[idx]
        if callback then callback(pid, idx, opt, st) end
    end)
    if item then
        item.player_bind = { kind = "combo", key = key, default = defaultIdx }
    end
    return item
end

function menu.pbutton(label, description, groupID, indent, callback)
    local item = menu.button(label, description, groupID, indent or 0, function()
        local pid, st = ResolveSelectedPlayer()
        if not pid then return end
        if callback then callback(pid, st) end
    end)
    if item then item.playerScoped = true end
    return item
end

menu.console = {
    styles = {
        [0] = {label = "ERROR", color = "\27[91m", nativeColor = "LIGHTRED"},
        [1] = {label = "WARN", color = "\27[93m", nativeColor = "YELLOW"},
        [2] = {label = "", color = "\27[96m", nativeColor = "LIGHTCYAN"},
        [3] = {label = "DEBUG", color = "\27[90m", nativeColor = "DARKGRAY"}
    },
    -- Capture the host logger before the script's local Logger declaration.
    hostLog = type(Logger) == "table" and type(Logger.Log) == "function" and Logger.Log or nil,
    hostColors = type(eLogColor) == "table" and eLogColor or nil,
    maxMessageChars = 2048
}

function menu.console.clean(value, limit)
    local ok, text = pcall(tostring, value == nil and "" or value)
    if not ok then text = "<unprintable>" end
    text = text:gsub("\27%[[0-?]*[ -/]*[@-~]", "")
        :gsub("\r\n", "\n"):gsub("\r", "\n")
        :gsub("[%z\1-\8\11\12\14-\31\127]", "")
        :gsub("\t", "    ")
    text = text:gsub("^%s*\n", ""):gsub("\n%s*$", "")
    return text:sub(1, limit or 2048)
end

function menu.console.english(value)
    local text = menu.console.clean(value)
    if type(menu.translate) ~= "function" then return text end
    local ok, translated = pcall(menu.translate, text, true)
    return ok and menu.console.clean(translated) or text
end

function menu.console.redact(value)
    local text = menu.console.clean(value, menu.console.maxMessageChars)
    local fields = {
        "[Kk][Ee][Yy]", "[Ll][Ii][Cc][Ee][Nn][Ss][Ee]", "[Tt][Oo][Kk][Ee][Nn]",
        "[Ss][Ee][Ss][Ss][Ii][Oo][Nn][_%-]?[Tt][Oo][Kk][Ee][Nn]", "[Nn][Oo][Nn][Cc][Ee]",
        "[Hh][Ww][Ii][Dd]", "[Dd][Ee][Vv][Ii][Cc][Ee][_%-]?[Hh][Aa][Ss][Hh]",
        "[Uu][Ii][Dd]", "[Ss][Ee][Cc][Rr][Ee][Tt]", "[Pp][Aa][Ss][Ss][Ww][Oo][Rr][Dd]",
        "[Aa][Uu][Tt][Hh][Oo][Rr][Ii][Zz][Aa][Tt][Ii][Oo][Nn]"
    }
    for _, field in ipairs(fields) do
        text = text:gsub("(" .. field .. "%s*[=:]%s*)[^%s,;]+", "%1[REDACTED]")
    end
    return text
end

function menu.console.format(level, module, message)
    local style = menu.console.styles[tonumber(level) or 2] or menu.console.styles[2]
    local timestamp = "--:--:--"
    if os and type(os.date) == "function" then
        local ok, value = pcall(os.date, "%H:%M:%S")
        if ok and type(value) == "string" then timestamp = value end
    end
    local body = menu.console.redact(menu.console.english(message))
    -- Shorten only recognized internal diagnostics; user text stays intact.
    if module == "SovereignInventory" then
        local edition = body:match("^runtime revision=%S+ edition=(%w+) source=.- instance=.+$")
        if edition then
            body = "Runtime ready (" .. edition .. ")"
        else
            local role, uuidSource = body:match("^direct freemode organization state converged role=(%w+) uuid=(%w+)$")
            if role then
                body = "Organization ready (" .. role:upper() .. ", UUID " .. uuidSource .. ")"
            else
                role = body:match("^direct freemode organization fields written but state did not converge role=(%w+)$")
                if role then
                    body = "Organization state not confirmed (" .. role:upper() .. ")"
                else
                    role = body:match("^direct freemode organization write failed role=(%w+)")
                    if role then body = "Organization state write failed (" .. role:upper() .. ")" end
                end
            end
        end
    end
    local badge = style.label ~= "" and (style.label .. "  ") or ""
    local prefix = timestamp .. "  Sovereign  " .. badge
    local nativeBody = badge .. body:gsub("\n", "\n    ")
    local alignedBody = body:gsub("\n", "\n" .. string.rep(" ", #prefix))
    local formatted = "\27[90m" .. timestamp .. "\27[0m  \27[96mSovereign\27[0m  "
        .. (badge ~= "" and (style.color .. badge .. "\27[0m") or "") .. alignedBody .. "\27[0m"
    return formatted, nativeBody, style.nativeColor
end

function menu.console.emit(level, module, message, sink)
    local formattedOk, formatted, body, colorName = pcall(menu.console.format, level, module, message)
    if not formattedOk then return false end
    if type(sink) == "function" then
        local ok, result = pcall(sink, formatted)
        if ok then return ok, result end
    end
    local color = menu.console.hostColors and menu.console.hostColors[colorName]
    if type(menu.console.hostLog) == "function" and type(color) == "number" then
        -- The host owns its timestamp and record boundary: no manual blank lines.
        local ok, result = pcall(menu.console.hostLog, color, "Sovereign", body)
        if ok then return ok, result end
    end
    -- Lua print owns its line ending too. Never prefix/suffix synthetic newlines.
    return pcall(print, formatted)
end

function menu.recordNotificationDiagnostic(scope, title, label, now)
    menu.notificationDiagnosticTimes = menu.notificationDiagnosticTimes or {}
    local previous = menu.notificationDiagnosticTimes[scope]
    if previous and now >= previous and now - previous < 10.0 then return end
    menu.notificationDiagnosticTimes[scope] = now
    menu.console.emit(2, scope or "Notification", title:sub(1, 80)
        .. " :: " .. label:sub(1, 1536))
end

function menu.publicNotification(title, label, status)
    -- Keep the original source strings in the queue. Canonical English is
    -- used only for classification; rendering translates from the source so
    -- a language switch and dynamic notice fragments stay correct.
    local sourceTitle = tostring(title or "")
    local sourceLabel = tostring(label or "")
    title = menu.translate(sourceTitle, true)
    label = menu.translate(sourceLabel, true)
    -- Preserve source strings until render time so visible notices and history
    -- follow a language switch. Technical detail is recorded separately below.
    local body, repeats = label:match("^(.-)(  x%d+)$")
    local combined, count = label:match("^(.-) %(combined (%d+) times%)$")
    if combined then body, repeats = combined, "  x" .. count end
    body, repeats = body or label, repeats or ""
    local function public(message, scope, level, heading)
        return heading or title, message and (message .. repeats) or nil, level or status, scope
    end
    if title == "SovereignProtectionSystem" or title == "Sovereign protection" then
        if body:find("Rope creation detected ", 1, true) == 1 then
            return public(nil, "protection_observation", status, "Sovereign protection")
        elseif body:find("advertising invitation", 1, true) then
            return public("Advertising invitation blocked", "protection_advertising", "warning", "Sovereign protection")
        elseif body:find("Removed", 1, true) == 1 then
            return public("Abnormal entities removed", "protection_entities", "warning", "Sovereign protection")
        elseif body:find("Repaired", 1, true) == 1 then
            return public("Abnormal attachments repaired", "protection_attachments", "warning", "Sovereign protection")
        elseif body:find("exception:", 1, true) or body:find("not fully loaded", 1, true) then
            return public("Some protections are temporarily unavailable. Please try again later.", "protection_unavailable", "warning", "Sovereign protection")
        elseif body:find("Blocked", 1, true) == 1 or body:find("Source player:", 1, true)
            or body:find("Entity crash protection", 1, true) then
            return public("Abnormal synchronization blocked", "protection_sync", "warning", "Sovereign protection")
        end
    elseif title == "Matchmaking region" then
        if body:find("Could not enable: ", 1, true) == 1 then
            return public("Could not set the region", "region_enable", "warning")
        elseif body:find("Not restored: ", 1, true) == 1 then
            return public("Region restore incomplete", "region_restore", "warning")
        end
    elseif title == "Strip club" then
        if body:find("Used the existing 7500 increment once", 1, true) == 1
            or body:find("Applied the 7500 increment once", 1, true) == 1 then
            return public("Tipped once. Check the game's affinity bar for the result.", "club_tipped", "success")
        elseif body:find("Restore failed", 1, true) then
            return public("Could not restore the setting. Please try again later.", "club_restore", "warning")
        elseif body:find("Not executed", 1, true) or body:find("code page", 1, true)
            or body:find("fingerprint", 1, true) or body:find("hash=", 1, true)
            or body:find("patch", 1, true) or body:find("bytes", 1, true) then
            return public("Action incomplete. Re-enter the club and try again.", "club_unavailable", "warning")
        end
    elseif title == "Audio filters" and body:match("^[%w_]+$") then
        return public("Could not restore the setting. Please try again later.", "audio_restore", "warning")
    end
    if body:find("stack traceback:", 1, true)
        or body:match("%.lua:%d+:%s")
        or body:match("^attempt to [%a ]+ a .- value") then
        return public("Action incomplete. Please try again later.", "runtime_exception", "error")
    end
    if body:find("Could not enable: ", 1, true) == 1
        or body:find("Association state switch failed:", 1, true) == 1
        or body:find("Loop error:", 1, true) == 1
        or body:find("Could not send the request: ", 1, true) == 1 then
        return public("This feature is temporarily unavailable. Please try again later.", "feature_unavailable", "warning")
    elseif body:find("Patch restore failed:", 1, true) == 1
        or body:find("Could not restore the previous setting: ", 1, true) == 1 then
        return public("Could not restore the setting. Please try again later.", "feature_restore", "warning")
    elseif body:find("Underlying wet-clothing handling was unresolved", 1, true) == 1 then
        return public("This feature is temporarily unavailable. Please try again later.", "drying_unavailable", "warning")
    end
    -- Only recognized feature notices may contain machine failure identifiers.
    -- Player messages and free-form user content keep their original text.
    local featureNotice = title == "World lighting" or title == "Vehicle nitro"
        or title == "Crouch" or title == "Auto duck in vehicles" or title == "Aim assist"
        or title == "Feature settings" or title == "Character settings" or title == "Movement settings"
        or title == "Vehicle settings" or title == "World settings" or title == "Sound settings"
        or title == "Strip club" or title == "Enter interior" or title == "Audio filters"
        or title == "Auto Dry" or title == "Release dogs"
    if featureNotice and (body:match("^%a[%w]*_[%w_]+")
        or body:find("0x%x+") or body:find("hash=", 1, true)) then
        return public("This feature is temporarily unavailable. Please try again later.", "feature_detail", "warning")
    end
    return sourceTitle, sourceLabel, status
end

menu.notificationTitleAliases = menu.notificationTitleAliases or {
    ["Sovereign"] = "SovereignLua",
    ["SovereignProtectionSystem"] = "Sovereign protection",
    ["NodeDataProtection"] = "Sovereign protection",
    ["NodeProtection"] = "Sovereign protection",
    ["Entity crash protection"] = "Sovereign protection",
    ["Block entities"] = "Sovereign protection"
}

function menu.normalizeNotificationTitle(title)
    local value = tostring(title or "")
    if value == "" then value = "SovereignLua" end
    return menu.notificationTitleAliases[value] or value
end

function menu.normalizeNotificationStatus(status)
    if status == nil then return nil end
    local value = tostring(status):lower()
    local aliases = {
        ["ok"] = "success", ["done"] = "success", ["completed"] = "success",
        ["restored"] = "success", ["enabled"] = "success", ["saved"] = "success",
        ["updated"] = "success", ["warn"] = "warning", ["blocked"] = "warning",
        ["attention"] = "warning", ["fail"] = "error", ["failed"] = "error",
        ["failure"] = "error", ["fatal"] = "error", ["exception"] = "error",
        ["crash"] = "error"
    }
    if aliases[value] then return aliases[value] end
    if value == "info" or value == "success" or value == "warning" or value == "error" then
        return value
    end
    local numeric = tonumber(status)
    if numeric == 1 then return "success" end
    if numeric == 2 then return "warning" end
    if numeric == 3 then return "error" end
    return "info"
end

function menu.inferNotificationStatus(label)
    local text = tostring(label or ""):lower()
    if text:find("crash", 1, true) or text:find("traceback", 1, true)
        or text:find("exception", 1, true) or text:find("fatal", 1, true)
        or text:find("错误", 1, true) or text:find("崩溃", 1, true) then
        return "error"
    end
    if text:find("failed", 1, true) or text:find("failure", 1, true)
        or text:find("could not", 1, true) or text:find("cannot", 1, true)
        or text:find("invalid", 1, true) or text:find("unavailable", 1, true)
        or text:find("not found", 1, true) or text:find("unable", 1, true)
        or text:find("失败", 1, true) or text:find("无法", 1, true)
        or text:find("不可用", 1, true) or text:find("无效", 1, true) then
        return "warning"
    end
    if text:find("completed", 1, true) or text:find("saved", 1, true)
        or text:find("restored", 1, true) or text:find("enabled", 1, true)
        or text:find("spawned", 1, true) or text:find("repaired", 1, true)
        or text:find("updated", 1, true) or text:find("success", 1, true)
        or text:find("成功", 1, true) or text:find("已保存", 1, true)
        or text:find("已启用", 1, true) then
        return "success"
    end
    return "info"
end

function menu.normalizeNotificationDuration(duration, fallback)
    local seconds = tonumber(duration)
    if not seconds then seconds = tonumber(fallback) or 3.0 end
    if seconds > 100 then seconds = seconds / 1000 end
    return math.max(0.8, math.min(15.0, seconds))
end

function menu.syncNotificationHistory(entry)
    if not entry then return end
    menu.notificationHistory = menu.notificationHistory or {}
    local row
    for _, candidate in ipairs(menu.notificationHistory) do
        if candidate.id == entry.id then row = candidate; break end
    end
    local data = {
        id = entry.id,
        title = entry.title,
        label = entry.label,
        status = entry.status,
        repeatCount = entry.repeatCount or 1,
        created_at = entry.created_at
    }
    if row then
        row.title, row.label, row.status = data.title, data.label, data.status
        row.repeatCount, row.created_at = data.repeatCount, data.created_at
    else
        table.insert(menu.notificationHistory, 1, data)
    end
    while #menu.notificationHistory > 50 do table.remove(menu.notificationHistory) end
end

-- One renewable alert owns one queue slot; missed samples expire it automatically.
function menu.setPoolPressureNotice(label)
    local entry, index
    for i, candidate in ipairs(notifyQueue) do
        if candidate.poolPressure then entry, index = candidate, i; break end
    end
    if not label or label == "" then
        if index then table.remove(notifyQueue, index) end
        return true
    end
    local now = ImGui.GetTime()
    local normalizedTitle = menu.normalizeNotificationTitle("Entity pool usage warning")
    local normalizedStatus = menu.normalizeNotificationStatus("warning")
    local normalizedLabel = tostring(label)
    if not entry then
        notifyUid = notifyUid + 1
        entry = {id = notifyUid, title = normalizedTitle, status = normalizedStatus, anim = 0.0,
            repeatCount = 1, poolPressure = true}
    elseif index then
        table.remove(notifyQueue, index)
    end
    entry.title, entry.rawTitle, entry.dedupeTitle = normalizedTitle, normalizedTitle, normalizedTitle
    entry.status, entry.rawLabel = normalizedStatus, normalizedLabel
    entry.label, entry.layout_w = normalizedLabel, nil
    local durationScale = math.max(0.50, math.min(2.00, (tonumber(menu.ui.notificationDurationScale) or 100) / 100.0))
    entry.created_at, entry.duration, entry.closing = now, menu.normalizeNotificationDuration(2.5) * durationScale, false
    menu.syncNotificationHistory(entry)
    table.insert(notifyQueue, 1, entry)
    local limit = math.floor(math.max(1, math.min(8, tonumber(menu.ui.notificationLimit) or 5)))
    while #notifyQueue > limit do table.remove(notifyQueue) end
    return true
end

-- menu.notify(title | nil, label, duration | nil, status | nil)
function menu.notify(title, label, duration, status)
    if not label or label == "" then return end
    local now = ImGui.GetTime()
    local normalizedTitle = menu.normalizeNotificationTitle(title)
    local normalizedLabel = tostring(label)
    local normalizedStatus = menu.normalizeNotificationStatus(status)
        or menu.inferNotificationStatus(normalizedLabel)
    local diagnosticScope
    normalizedTitle, normalizedLabel, normalizedStatus, diagnosticScope = menu.publicNotification(
        normalizedTitle, normalizedLabel, normalizedStatus
    )
    normalizedTitle = menu.normalizeNotificationTitle(normalizedTitle)
    normalizedStatus = menu.normalizeNotificationStatus(normalizedStatus)
        or menu.inferNotificationStatus(normalizedLabel)
    if diagnosticScope and type(menu.recordNotificationDiagnostic) == "function" then
        menu.recordNotificationDiagnostic(diagnosticScope, tostring(title or ""), tostring(label), now)
    end
    if not normalizedLabel or normalizedLabel == "" then return end
    local durationScale = math.max(0.50, math.min(2.00, (tonumber(menu.ui.notificationDurationScale) or 100) / 100.0))
    local scaledDuration = menu.normalizeNotificationDuration(duration, 3.0) * durationScale
    local dedupeTitle = normalizedTitle
    if menu.ui.notificationDedupe ~= 0 then
        for _, existing in ipairs(notifyQueue) do
            if not existing.poolPressure and (existing.dedupeTitle or existing.rawTitle or existing.title) == dedupeTitle
                and existing.rawLabel == normalizedLabel
                and existing.status == normalizedStatus
                and now - (existing.created_at or 0) <= 1.5 then
                existing.repeatCount = (existing.repeatCount or 1) + 1
                existing.label = normalizedLabel .. "  x" .. tostring(existing.repeatCount)
                existing.dedupeTitle = dedupeTitle
                existing.created_at = now
                existing.duration = math.max(tonumber(existing.duration) or 3.0, scaledDuration)
                existing.closing = false
                existing.layout_w = nil
                menu.syncNotificationHistory(existing)
                return
            end
        end
    end
    notifyUid = notifyUid + 1
    local entry = {
        id = notifyUid,
        title = normalizedTitle,
        label = normalizedLabel,
        rawTitle = normalizedTitle,
        rawLabel = normalizedLabel,
        dedupeTitle = dedupeTitle,
        duration = scaledDuration,
        status = normalizedStatus,
        created_at = now,
        anim = 0.0,
        closing = false,
        repeatCount = 1
    }
    table.insert(notifyQueue, notifyQueue[1] and notifyQueue[1].poolPressure and 2 or 1, entry)
    menu.syncNotificationHistory(entry)
    local limit = math.floor(math.max(1, math.min(8, tonumber(menu.ui.notificationLimit) or 5)))
    while #notifyQueue > limit do
        table.remove(notifyQueue)
    end
end

function menu.enqueueAction(label, callback, ...)
    if type(callback) ~= "function" then return end
    table.insert(menu.actionQueue, {
        label = tostring(label or "action"),
        callback = callback,
        args = {...}
    })
end

menu.invokeAction = LPH_JIT(function(action)
    local unpackFn = table.unpack or unpack
    return action.callback(unpackFn(action.args))
end)

menu.processActions = LPH_NO_VIRTUALIZE(function()
    if menu.ui.savePending and menu.flushUiSettings then
        menu.flushUiSettings(false)
    end
    if menu.quick.savePending and menu.flushQuickSettings then
        menu.flushQuickSettings(false)
    end
    if #menu.actionQueue == 0 then return end
    local queue = menu.actionQueue
    menu.actionQueue = {}
    for _, action in ipairs(queue) do
        local ok, err = pcall(menu.invokeAction, action)
        if not ok then
            if Logger and Logger.Error then
                Logger:Error("SovereignUI", tostring(action.label) .. ": " .. tostring(err))
            else
                menu.console.emit(0, "SovereignUI", tostring(action.label) .. ": " .. tostring(err))
            end
        end
    end
end)

function menu.isOpen()
    return menu.requestedOpen == true
end

menu.captureKeyboard = LPH_NO_VIRTUALIZE(function(capture)
    if not ImGui then return end
    local keyboardCapture = ImGui.SetNextFrameWantCaptureKeyboard or ImGui.CaptureKeyboardFromApp
    capture = capture == true
    if type(keyboardCapture) == "function" then
        local ok = pcall(keyboardCapture, capture)
        if ok then
            menu.keyboardCaptured = capture
        end
    elseif not capture then
        menu.keyboardCaptured = false
    end
end)

menu.captureMouse = LPH_NO_VIRTUALIZE(function(capture)
    if not ImGui then return end
    if capture then
        -- Always hide the host cursor while the menu owns input.  The custom
        -- overlay remains enabled even when the host does not expose a
        -- working None cursor (some builds otherwise fall back to an I-beam).
        if ImGui.SetMouseCursor then
            pcall(ImGui.SetMouseCursor, (ImGuiMouseCursor and ImGuiMouseCursor.None) or -1)
        end
        if ImGui.CaptureMouseFromApp then
            pcall(ImGui.CaptureMouseFromApp, true)
        end
        menu.customCursorEnabled = true
        menu.mouseCaptured = true
    elseif menu.mouseCaptured then
        if ImGui.CaptureMouseFromApp then
            pcall(ImGui.CaptureMouseFromApp, false)
        end
        if ImGui.SetMouseCursor then
            pcall(ImGui.SetMouseCursor, (ImGuiMouseCursor and ImGuiMouseCursor.Arrow) or 0)
        end
        menu.customCursorEnabled = false
        menu.mouseCaptured = false
    end
    if not capture then
        menu.captureKeyboard(false)
    end
end)


function menu.markTextInputActive()
    if not ImGui then return end
    local active = false
    if ImGui.IsItemActive then
        local ok, value = pcall(ImGui.IsItemActive)
        active = ok and value == true
    end
    if not active and ImGui.IsItemFocused then
        local ok, value = pcall(ImGui.IsItemFocused)
        active = ok and value == true
    end
    if active then
        menu.textInputActive = true
        menu.captureKeyboard(true)
    end
end

-- Cherax builds expose ImGui text input as either `text` or
-- `(changed, text)`.  Keep the UTF-8 string and ignore the boolean result;
-- converting the first return value with tostring() turns Chinese input into
-- the literal string "true" on builds using the tuple form.
function menu.extractInputValue(first, second, fallback)
    if type(second) == "string" then return second end
    if type(first) == "string" then return first end
    return fallback or ""
end

menu.processInputCapture = LPH_NO_VIRTUALIZE(function()
    if not menu.interactive and not (menu.openAnimation and menu.openAnimation > 0.001) then return end
    local hud = rawget(_G, "HUD")
    if hud and type(hud.SET_MOUSE_CURSOR_VISIBLE) == "function" then
        pcall(hud.SET_MOUSE_CURSOR_VISIBLE, false)
    end
    if hud and type(hud.DISABLE_FRONTEND_THIS_FRAME) == "function" then
        pcall(hud.DISABLE_FRONTEND_THIS_FRAME)
    end
    local pad = rawget(_G, "PAD")
    if pad and type(pad.DISABLE_CONTROL_ACTION) == "function" then
        local disableControl = pad.DISABLE_CONTROL_ACTION
        for _, control in ipairs(menu.blockedGameControls) do
            disableControl(0, control, true)
        end
    end
    local player = rawget(_G, "PLAYER")
    if player and type(player.DISABLE_PLAYER_FIRING) == "function" then
        local playerId = 0
        if type(player.PLAYER_ID) == "function" then
            local ok, value = pcall(player.PLAYER_ID)
            if ok and type(value) == "number" then
                playerId = value
            end
        end
        player.DISABLE_PLAYER_FIRING(playerId, true)
    end
end)

function menu.ensureInputCaptureLoop()
    if menu.inputCaptureLoopRegistered then
        return true
    end
    if not Script or type(Script.RegisterLooped) ~= "function" then
        return false
    end
    local ok, err = pcall(function()
        Script.RegisterLooped(LPH_NO_VIRTUALIZE(function()
            if type(ShouldUnload) == "function" and ShouldUnload() then return end
            local captureOk, captureErr = pcall(menu.processInputCapture)
            if not captureOk then
                local now = os.clock()
                if menu.inputCaptureLastErrorAt == 0 or now - menu.inputCaptureLastErrorAt >= 5.0 then
                    menu.inputCaptureLastErrorAt = now
                    SovereignLogError("SovereignUI.InputCapture", captureErr)
                end
            end
        end))
    end)
    if not ok then
        SovereignLogError("SovereignUI.InputCapture", err)
        return false
    end
    menu.inputCaptureLoopRegistered = true
    return true
end

function menu.setOpen(open)
    if open == true and not menu.ready then
        return false
    end
    local desiredOpen = open == true
    menu.requestedOpen = desiredOpen
    menu.openAnimationTarget = desiredOpen and 1.0 or 0.0
    menu.openAnimationLastTime = 0.0
    menu.closeFlushPending = not desiredOpen
    if desiredOpen then
        menu.open = true
        menu.interactive = true
    else
        menu.interactive = false
        if menu.openAnimation <= 0.001 then
            menu.open = false
        end
    end
    if desiredOpen and menu.openAnimation <= 0.001 then
        menu.openAnimation = 0.0
    end
    if not desiredOpen then
        menu.hotkeyCaptureActive = false
        menu.hotkeyCaptureReady = false
        menu.hotkeyCaptureArmFrames = 0
        menu.textInputActive = false
    end
end

menu.updateOpenAnimation = LPH_NO_VIRTUALIZE(function(now)
    now = tonumber(now) or 0.0
    if menu.openAnimationLastTime == 0.0 then
        menu.openAnimationLastTime = now
    end
    local dt = math.max(0.0, math.min(0.05, now - menu.openAnimationLastTime))
    menu.openAnimationLastTime = now
    local target = menu.openAnimationTarget or (menu.requestedOpen and 1.0 or 0.0)
    local rate = target >= 1.0 and 18.0 or 17.0
    local blend = 1.0 - math.exp(-dt * rate)
    menu.openAnimation = menu.openAnimation + (target - menu.openAnimation) * blend
    if target <= 0.0 and menu.openAnimation < 0.001 then
        menu.openAnimation = 0.0
        menu.open = false
        menu.captureMouse(false)
        if menu.closeFlushPending then
            menu.closeFlushPending = false
            if menu.flushUiSettings then
                pcall(menu.flushUiSettings, true)
            end
        end
    elseif target >= 1.0 and menu.openAnimation > 0.999 then
        menu.openAnimation = 1.0
        menu.open = true
    end
    local value = math.max(0.0, math.min(1.0, menu.openAnimation))
    return value * value * (3.0 - (2.0 * value))
end)

function menu.toggleOpen()
    menu.setOpen(not menu.requestedOpen)
end

menu.drawCursor = LPH_NO_VIRTUALIZE(function()
    if not menu.interactive or menu.customCursorEnabled ~= true or not ImGui or not ImGui.GetMousePos then
        return
    end
    local x, y = ImGui.GetMousePos()
    local displayW, displayH = ImGui.GetDisplaySize()
    if type(x) ~= "number" or type(y) ~= "number" or x ~= x or y ~= y
        or x < 0 or y < 0 or x >= displayW or y >= displayH then
        if ImGui.SetMouseCursor then pcall(ImGui.SetMouseCursor, (ImGuiMouseCursor and ImGuiMouseCursor.Arrow) or 0) end
        return
    end
    if ImGui.SetMouseCursor then
        pcall(ImGui.SetMouseCursor, (ImGuiMouseCursor and ImGuiMouseCursor.None) or -1)
    end
    local style = tonumber(menu.ui.cursorStyle) or 2
    local scale = tonumber(menu.ui.cursorSize) or 1.0
    if scale ~= scale then scale = 1.0 end
    scale = math.max(0.75, math.min(1.75, scale))
    local r, g, b, a = HexToRGBAInt("@cursor")
    -- Keep one consistent pointer even while an input is focused.  The host
    -- cursor's text/I-beam shape is intentionally never exposed.
    if style == 3 then
        ImGui.AddCircleFilled(x, y, 5 * scale, 0, 0, 0, 185)
        ImGui.AddCircleFilled(x, y, 3 * scale, r, g, b, a)
        ImGui.AddCircleFilled(x, y, scale, 245, 247, 250, a)
    elseif style == 5 then
        local radius = 7 * scale
        if type(ImGui.AddCircle) == "function" then
            ImGui.AddCircle(x, y, radius, 0, 0, 0, 190, 20, 3 * scale)
            ImGui.AddCircle(x, y, radius, r, g, b, a, 20, 1.5 * scale)
        else
            ImGui.AddCircleFilled(x, y, radius, r, g, b, a)
            ImGui.AddCircleFilled(x, y, radius - 2 * scale, 10, 12, 16, a)
        end
        ImGui.AddCircleFilled(x, y, 1.5 * scale, 245, 247, 250, a)
    elseif style == 6 then
        local arm = 8 * scale
        if type(ImGui.AddQuadFilled) == "function" then
            ImGui.AddQuadFilled(x, y - arm, x + arm, y, x, y + arm, x - arm, y,
                0, 0, 0, 190)
            ImGui.AddQuadFilled(x, y - arm + scale, x + arm - scale, y, x, y + arm - scale, x - arm + scale, y,
                r, g, b, a)
        else
            ImGui.AddLine(x, y - arm, x + arm, y, r, g, b, a, 2 * scale)
            ImGui.AddLine(x + arm, y, x, y + arm, r, g, b, a, 2 * scale)
            ImGui.AddLine(x, y + arm, x - arm, y, r, g, b, a, 2 * scale)
            ImGui.AddLine(x - arm, y, x, y - arm, r, g, b, a, 2 * scale)
            ImGui.AddCircleFilled(x, y, scale, 245, 247, 250, a)
        end
    elseif style == 4 then
        local arm, gap = 8 * scale, 3 * scale
        ImGui.AddLine(x - arm, y, x - gap, y, r, g, b, a, 1.5 * scale)
        ImGui.AddLine(x + gap, y, x + arm, y, r, g, b, a, 1.5 * scale)
        ImGui.AddLine(x, y - arm, x, y - gap, r, g, b, a, 1.5 * scale)
        ImGui.AddLine(x, y + gap, x, y + arm, r, g, b, a, 1.5 * scale)
        ImGui.AddCircleFilled(x, y, scale, 245, 247, 250, a)
    else
        -- Scale the shape around the unmodified ImGui hit-test position.
        -- Draw the tail first so its cap cannot protrude through the arrow head.
        ImGui.AddLine(x + 4.2 * scale, y + 10.5 * scale, x + 7.7 * scale, y + 19.0 * scale,
            12, 16, 22, a, 4.0 * scale)
        ImGui.AddLine(x + 4.2 * scale, y + 10.5 * scale, x + 7.7 * scale, y + 19.0 * scale,
            r, g, b, a, 2.0 * scale)
        if type(ImGui.AddTriangleFilled) == "function" then
            ImGui.AddTriangleFilled(x, y, x, y + 17.5 * scale,
                x + 12.4 * scale, y + 12.2 * scale, 12, 16, 22, a)
            ImGui.AddTriangleFilled(x + 1.2 * scale, y + 2.7 * scale, x + 1.2 * scale, y + 14.7 * scale,
                x + 9.9 * scale, y + 11.7 * scale, 246, 248, 252, a)
        else
            ImGui.AddLine(x, y, x, y + 17.5 * scale, 246, 248, 252, a, scale)
            ImGui.AddLine(x, y, x + 12.4 * scale, y + 12.2 * scale, 246, 248, 252, a, scale)
            ImGui.AddLine(x, y + 17.5 * scale, x + 12.4 * scale, y + 12.2 * scale, 246, 248, 252, a, scale)
        end
    end
end)

menu.searchTextContains = LPH_NO_VIRTUALIZE(function(text, query)
    if query == "" then return true end
    return string.find(string.lower(tostring(text or "")), query, 1, true) ~= nil
        or string.find(string.lower(tostring(menu.translate(text) or "")), query, 1, true) ~= nil
end)

menu.getSearchQuery = LPH_NO_VIRTUALIZE(function()
    local raw = tostring(menu.searchText or "")
    if menu._searchRaw == raw then return menu._normalizedSearch end
    local query = string.lower(raw)
    query = query:gsub("^%s+", ""):gsub("%s+$", "")
    menu._searchRaw, menu._normalizedSearch = raw, query
    return query
end)

menu.itemMatchesSearch = LPH_NO_VIRTUALIZE(function(item, query)
    if query == "" then return true end
    if item._searchLabel ~= item.label or not item._searchLabelLower then
        item._searchLabel, item._searchLabelLower = item.label, string.lower(tostring(item.label or ""))
    end
    if item._searchDescription ~= item.description or not item._searchDescriptionLower then
        item._searchDescription, item._searchDescriptionLower = item.description, string.lower(tostring(item.description or ""))
    end
    if item._searchLanguage ~= menu.ui.language or item._translatedSearchLabel ~= item.label
        or item._translatedSearchDescription ~= item.description then
        item._searchLanguage = menu.ui.language
        item._translatedSearchLabel, item._translatedSearchDescription = item.label, item.description
        item._translatedLabelLower = string.lower(tostring(menu.translate(item.label) or ""))
        item._translatedDescriptionLower = string.lower(tostring(menu.translate(item.description) or ""))
    end
    return item._searchLabelLower:find(query, 1, true) ~= nil or item._searchDescriptionLower:find(query, 1, true) ~= nil
        or item._translatedLabelLower:find(query, 1, true) ~= nil or item._translatedDescriptionLower:find(query, 1, true) ~= nil
end)

menu.getVisibleGroupItems = LPH_NO_VIRTUALIZE(function(group, query)
    if menu.quick and group and group.id == menu.quick.searchGroupID then
        return group.items or {}
    end
    local items = group.items or {}
    local visible = group._sovereignVisibleItems or {}
    group._sovereignVisibleItems = visible
    local count = 0
    local groupMatches = query == "" or menu.searchTextContains(group.name, query)
    for _, item in ipairs(items) do
        local allowed = type(SovereignMenuFeatureVisible) ~= "function"
            or SovereignMenuFeatureVisible(item, group)
        if allowed and (groupMatches or menu.itemMatchesSearch(item, query)) then
            count = count + 1
            visible[count] = item
        end
    end
    for index = #visible, count + 1, -1 do visible[index] = nil end
    return visible
end)

function menu.jumpToSearchResult(groupID, itemUid)
    local group = globalGroups[tonumber(groupID)]
    local subtab = group and globalSubtabs[group.subtabID] or nil
    local tab = subtab and menu.tabs[subtab.tabID] or nil
    if not group or not subtab or not tab then return false end
    if type(SovereignMenuFeatureVisible) == "function" then
        local targetItem
        for _, candidate in ipairs(group.items or {}) do
            if candidate and candidate.uid == itemUid then
                targetItem = candidate
                break
            end
        end
        if targetItem and not SovereignMenuFeatureVisible(targetItem, group) then
            return false
        end
    end

    menu.activeTab = tab.id
    menu.activeSubtab = subtab.id
    menu.searchText = ""
    menu.pendingRevealGroupID = group.id
    menu.pendingRevealItemUid = itemUid
    menu.pendingRevealApplied = nil
    tab.subtabPageHistory = {}
    for index, candidate in ipairs(tab.subtabs or {}) do
        if candidate.id == subtab.id then
            tab.subtabPageStart = index
            break
        end
    end
    if menu.quick then
        menu.quick.searchQuery = nil
        menu.quick.searchDirty = true
    end
    return true
end

menu.refreshGlobalSearchGroup = LPH_NO_VIRTUALIZE(function(query)
    local searchGroup = menu.quick and menu.quick.searchGroupID and globalGroups[menu.quick.searchGroupID]
    if not searchGroup then return end
    query = string.lower(tostring(query or "")):gsub("^%s+", ""):gsub("%s+$", "")
    if menu.quick.searchQuery == query and menu.quick.searchLanguage == menu.ui.language and menu.quick.searchDirty ~= true then return end
    menu.quick.searchLanguage = menu.ui.language
    menu.quick.searchQuery = query
    menu.quick.searchDirty = false

    local favoriteGroup = menu.quick.favoriteGroupID and globalGroups[menu.quick.favoriteGroupID]
    local recentGroup = menu.quick.recentGroupID and globalGroups[menu.quick.recentGroupID]
    if favoriteGroup then favoriteGroup.hidden = query ~= "" end
    if recentGroup then recentGroup.hidden = query ~= "" end
    searchGroup.hidden = false
    searchGroup.items = {}

    if query == "" then
        searchGroup.items[1] = {type = "text", label = "Search all features. Press Ctrl+F to jump here."}
        return
    end

    local resultCount = 0
    local resultLimit = 50
    for _, group in ipairs(globalGroups) do
        if resultCount >= resultLimit then break end
        if group and group.hidden ~= true
            and group.id ~= menu.quick.searchGroupID
            and group.id ~= menu.quick.favoriteGroupID
            and group.id ~= menu.quick.recentGroupID then
            local subtab = globalSubtabs[group.subtabID]
            local tab = subtab and menu.tabs[subtab.tabID] or nil
            local path = table.concat({
                tostring(tab and tab.name or ""),
                tostring(subtab and subtab.name or ""),
                tostring(group.name or "")
            }, " / ")
            local displayPath = table.concat({
                menu.translate(tostring(tab and tab.name or "")),
                menu.translate(tostring(subtab and subtab.name or "")),
                menu.translate(tostring(group.name or ""))
            }, " / ")
            for _, item in ipairs(group.items or {}) do
                if resultCount >= resultLimit then break end
                if item and item.type ~= "text"
                    and (type(SovereignMenuFeatureVisible) ~= "function"
                        or SovereignMenuFeatureVisible(item, group))
                    and (menu.searchTextContains(path, query) or menu.searchTextContains(displayPath, query) or menu.itemMatchesSearch(item, query)) then
                    local targetGroupID = group.id
                    local targetItemUid = item.uid
                    local targetDescription = tostring(item.description or "")
                    resultCount = resultCount + 1
                    searchGroup.items[#searchGroup.items + 1] = {
                        type = "button",
                        uid = "search_" .. tostring(targetGroupID) .. "_" .. tostring(targetItemUid or resultCount),
                        label = tostring(item.label or "Unnamed feature"),
                        description = displayPath .. (targetDescription ~= "" and (" | " .. menu.translate(targetDescription)) or ""),
                        callback = function()
                            menu.jumpToSearchResult(targetGroupID, targetItemUid)
                        end
                    }
                end
            end
        end
    end

    if resultCount == 0 then
        searchGroup.items[1] = {type = "text", label = "No matching features: " .. query}
    else
        table.insert(searchGroup.items, 1, {
            type = "text",
            label = menu.translate("Found ") .. tostring(resultCount) .. (resultCount >= resultLimit and "+" or "") .. menu.translate(" results. Select one to open its page.")
        })
    end
end)

