    if nextValue ~= nil and nextValue ~= tostring(menu.searchText or "") then
        menu.searchText = nextValue
        if menu.quick then menu.quick.searchDirty = true end
    end
end)

-- Custom Render Functions
local g_dt = 0.016
local g_last_time = 0
menu.tabIcons = menu.tabIcons or {"◈", "↝", "●", "◉", "✦", "⚙", "◇", "◆"}

-- Frame-rate independent easing.  The previous `speed * dt` lerp could
-- overshoot on hitchy frames and made combo animation feel different across
-- refresh rates.
menu.animLerp = LPH_NO_VIRTUALIZE(function(current, target, speed, dt)
    current = tonumber(current) or 0.0
    target = tonumber(target) or 0.0
    if math.abs(target - current) < 0.0001 then return target end
    speed = math.max(0.0, tonumber(speed) or 10.0)
    speed = speed * math.max(0.5, math.min(1.6, (tonumber(menu.ui.animationSpeed) or 100) / 100))
    dt = math.max(0.0, math.min(0.10, tonumber(dt) or g_dt or 0.016))
    if dt == 0 or speed == 0 then return current end
    menu._easeCache = menu._easeCache or {}
    local cached = menu._easeCache[speed]
    if not cached then cached = {}; menu._easeCache[speed] = cached end
    if cached.dt ~= dt then cached.dt, cached.alpha = dt, 1.0 - math.exp(-speed * dt) end
    local alpha = cached.alpha
    return current + ((target - current) * alpha)
end)

menu.hasVisibleDescription = LPH_NO_VIRTUALIZE(function(item)
    local description = item and item.description
    return description ~= nil and tostring(description):match("%S") ~= nil
end)

menu.getUiLineHeight = LPH_NO_VIRTUALIZE(function()
    local fontScale = tonumber(menu.ui.fontScale) or 1.0
    local cached = menu._uiLineHeightCache
    if cached and cached.scale == fontScale and cached.value and cached.value > 0 then
        return cached.value
    end

    local measuredHeight = nil
    local ok, _, textHeight = pcall(menu.localizedTextSize, "Ag")
    if ok then
        measuredHeight = tonumber(textHeight)
    end
    local measurementReady = measuredHeight and measuredHeight > 0
    if not measuredHeight or measuredHeight <= 0 then
        measuredHeight = 14.0 * fontScale
    end
    measuredHeight = math.max(14.0, measuredHeight)
    if measurementReady then
        menu._uiLineHeightCache = {scale = fontScale, value = measuredHeight}
    end
    return measuredHeight
end)

menu.getItemLayout = LPH_NO_VIRTUALIZE(function(item)
    local lineHeight = menu.getUiLineHeight()
    local fontScale = tonumber(menu.ui.fontScale) or 1.0
    local itemType = item and item.type or "text"
    local compact = item and item.compact == true
    local description = item and item.description
    local descriptionText = description ~= nil and menu.translate(tostring(description)) or nil
    local layoutWidth = item and tonumber(item._layoutWidth) or nil
    local indent = item and tonumber(item.indent) or 0
    local cache = type(item) == "table" and item._layoutCache or nil
    if cache and cache.lineHeight == lineHeight and cache.fontScale == fontScale
        and cache.itemType == itemType and cache.compact == compact
        and cache.description == descriptionText and cache.width == layoutWidth
        and cache.indent == indent then
        return cache.layout
    end

    local descriptionHeight = math.max(12.0, lineHeight * 0.85)
    local hasDescription = descriptionText ~= nil and descriptionText:match("%S") ~= nil
    local measurementReady = true
    if hasDescription and item and layoutWidth then
        local wrapWidth = math.max(80.0, layoutWidth - indent - 8.0)
        local ok, _, measuredHeight = pcall(menu.localizedTextSize, descriptionText, false, wrapWidth)
        if ok and type(measuredHeight) == "number" and measuredHeight > 0 then
            descriptionHeight = math.max(descriptionHeight, measuredHeight * 0.85)
        else
            measurementReady = false
        end
    end
    local titleY = compact and 5.0 or 8.0
    local descriptionY = titleY + lineHeight + (compact and 2.0 or 4.0)
    local contentY = hasDescription
        and (descriptionY + descriptionHeight + (compact and 5.0 or 10.0))
        or (titleY + lineHeight + (compact and 6.0 or 10.0))
    local controlHeight = math.max(compact and 28.0 or 30.0, lineHeight + (compact and 8.0 or 12.0))
    local height = math.max(compact and 18.0 or 20.0, lineHeight + (compact and 4.0 or 6.0))
    local buttonHeight = math.max(compact and 36.0 or 42.0, lineHeight + (compact and 12.0 or 18.0))
    local rowStep = math.max(compact and 24.0 or 27.0, lineHeight + (compact and 7.0 or 10.0))

    if itemType == "toggle" then
        local textBottom = hasDescription
            and (descriptionY + descriptionHeight + (compact and 8.0 or 12.0))
            or (titleY + math.max(lineHeight, 21.0) + (compact and 8.0 or 12.0))
        height = math.max(compact and 56.0 or 64.0, textBottom)
    elseif itemType == "slider" then
        height = math.max(compact and 72.0 or 80.0, contentY + (compact and 8.0 or 12.0) + 16.0)
    elseif itemType == "input" then
        height = math.max(compact and 74.0 or 84.0, contentY + controlHeight + (compact and 6.0 or 10.0))
    elseif itemType == "combo" then
        height = math.max(compact and 82.0 or 96.0, contentY + controlHeight + (compact and 6.0 or 10.0))
    elseif itemType == "color" then
        height = math.max(compact and 132.0 or 146.0, contentY + (rowStep * 3.0) + (compact and 6.0 or 10.0))
    elseif itemType == "button" then
        height = buttonHeight + (compact and 10.0 or 20.0)
    end

    local layout = {
        compact = compact,
        lineHeight = lineHeight,
        descriptionHeight = descriptionHeight,
        hasDescription = hasDescription,
        titleY = titleY,
        descriptionY = descriptionY,
        contentY = contentY,
        controlHeight = controlHeight,
        buttonHeight = buttonHeight,
        rowStep = rowStep,
        height = math.ceil(height)
    }
    -- Cache only successful measurements; transient ImGui failures must be retried.
    if type(item) == "table" and measurementReady then
        item._layoutCache = {
            lineHeight = lineHeight, fontScale = fontScale, itemType = itemType,
            compact = compact, description = descriptionText, width = layoutWidth,
            indent = indent, layout = layout
        }
    end
    return layout
end)

