    local knob_inner_b = math.floor(knob_in_off_b + (knob_in_on_b - knob_in_off_b) * item.anim_on)
    local knob_inner_a = math.floor(knob_in_off_a + (knob_in_on_a - knob_in_off_a) * item.anim_on)
    
    ImGui.AddCircleFilled(knob_pos_x, center_y, 7.0, knob_r, knob_g, knob_b, knob_a)
    ImGui.AddCircleFilled(knob_pos_x, center_y, 3.65, knob_inner_r, knob_inner_g, knob_inner_b, knob_inner_a)
    
    -- Separator line
    local line_r, line_g, line_b, line_a = HexToRGBAInt("#23232c", 0.72)
    ImGui.AddLine(p_x + indent, p_y + height, p_x + width, p_y + height, line_r, line_g, line_b, line_a, 1.0)
end)

local DrawCustomSlider = LPH_NO_VIRTUALIZE(function(item, p_x, p_y, width)
    local layout = menu.getItemLayout(item)
    local height = layout.height
    local track_height = 12
    local indent = item.indent or 0
    
    ImGui.SetCursorScreenPos(p_x, p_y)
    local clicked = ImGui.InvisibleButton("##slider_" .. tostring(item.uid or item.quickKey or item.label), width, height)
    menu.handleQuickItem(item)
    local is_active = ImGui.IsItemActive() and not menu.comboBlocksInput(item)
    local is_hovered = ImGui.IsItemHovered()
    if is_active and not item._quickActive then
        item._quickActive = true
        menu.recordUsage(item)
    elseif not is_active then
        item._quickActive = false
    end
    
    -- Animation states
    item.anim_value = item.anim_value or item.value
    if type(item.anim_value) ~= 'number' then item.anim_value = item.value end
    item.anim_value = item.anim_value + (item.value - item.anim_value) * 15.0 * g_dt
    
    -- Title
    ImGui.SetCursorScreenPos(p_x + indent, p_y + layout.titleY)
    local tr, tg, tb, ta = HexToRGBAFloat("#ffffff")
    menu.localizedTextColored(tr, tg, tb, ta, item.label)
    
    -- Description
    if layout.hasDescription then
        ImGui.SetCursorScreenPos(p_x + indent, p_y + layout.descriptionY)
        ImGui.SetWindowFontScale((menu.ui.fontScale or 1.0) * 0.85)
        menu.drawItemDescription(item, p_x + indent, p_y + layout.descriptionY, width - indent)
        ImGui.SetWindowFontScale(menu.ui.fontScale or 1.0)
    end
    
    -- Value
    local val_text = string.format(item.format or "%d", item.value)
    local text_w = menu.localizedTextSize(val_text) or 20
    ImGui.SetCursorScreenPos(p_x + width - text_w, p_y + layout.titleY)
    menu.localizedTextColored(tr, tg, tb, ta, val_text)
    
    -- Track
    local track_y = p_y + layout.contentY
    local track_x = p_x + indent
    local track_w = width - indent
    
    if is_active then
        local mouse_x, mouse_y = ImGui.GetMousePos()
        local fraction = (mouse_x - track_x) / track_w
        if fraction < 0 then fraction = 0 end
        if fraction > 1 then fraction = 1 end
        local new_value = item.min + fraction * (item.max - item.min)
        local step = tonumber(item.step)
        if step and step > 0 then
            new_value = item.min + math.floor(((new_value - item.min) / step) + 0.5) * step
            if new_value < item.min then new_value = item.min end
            if new_value > item.max then new_value = item.max end
        elseif item.format:find("%%d") then
            new_value = math.floor(new_value + 0.5)
        end
        if new_value ~= item.value then
            item.prevValue = item.value
            item.value = new_value
            if item.callback then
                if item.applyOnRelease then
                    item.callbackPending = true
                else
                    menu.enqueueAction(item.label, item.callback, item.value)
                end
            end
        end
    end

    if item.applyOnRelease and not is_active and item.callbackPending then
        item.callbackPending = false
        menu.recordUsage(item)
        if item.callback then
            menu.enqueueAction(item.label, item.callback, item.value)
        end
    end
    
    -- Background Track
    local bg_r, bg_g, bg_b, bg_a = HexToRGBAInt("#212128")
    ImGui.AddRectFilled(track_x, track_y, track_x + track_w, track_y + track_height, bg_r, bg_g, bg_b, bg_a, track_height / 2)
    
    -- Fill Track
    local fill_fraction = (item.anim_value - item.min) / (item.max - item.min)
    if fill_fraction < 0 then fill_fraction = 0 end
    if fill_fraction > 1 then fill_fraction = 1 end
    
    local fill_w = track_w * fill_fraction
    if fill_w < 12 then fill_w = 12 end
    if fill_w > track_w then fill_w = track_w end
    
    local f_r, f_g, f_b, f_a = HexToRGBAInt("#b0b4ff")
    ImGui.AddRectFilled(track_x, track_y, track_x + fill_w, track_y + track_height, f_r, f_g, f_b, f_a, track_height / 2)
    
    -- Handle
    local handle_x = track_x + fill_w - 6.0
    local handle_y = track_y + track_height / 2
    local handle_r, handle_g, handle_b, handle_a = HexToRGBAInt("#000000")
    ImGui.AddCircleFilled(handle_x, handle_y, 4.0, handle_r, handle_g, handle_b, handle_a)
    
    -- Separator line
    local line_r, line_g, line_b, line_a = HexToRGBAInt("#23232c", 0.72)
    ImGui.AddLine(p_x + indent, p_y + height, p_x + width, p_y + height, line_r, line_g, line_b, line_a, 1.0)
end)

menu.drawColor = LPH_NO_VIRTUALIZE(function(item, p_x, p_y, width)
    local layout = menu.getItemLayout(item)
    local height = layout.height
    local indent = item.indent or 0
    local value = item.value or {r = 255, g = 255, b = 255, a = 255}
    item.value = value

    local function clampByte(channel)
        return math.max(0, math.min(255, math.floor((tonumber(channel) or 0) + 0.5)))
    end

    value.r = clampByte(value.r)
    value.g = clampByte(value.g)
    value.b = clampByte(value.b)
    value.a = clampByte(value.a or 255)

    ImGui.SetCursorScreenPos(p_x + indent, p_y + layout.titleY)
    local tr, tg, tb, ta = HexToRGBAFloat("#ffffff")
    menu.localizedTextColored(tr, tg, tb, ta, item.label)

    if layout.hasDescription then
        ImGui.SetCursorScreenPos(p_x + indent, p_y + layout.descriptionY)
        ImGui.SetWindowFontScale((menu.ui.fontScale or 1.0) * 0.85)
        menu.drawItemDescription(item, p_x + indent, p_y + layout.descriptionY, width - indent - 44)
        ImGui.SetWindowFontScale(menu.ui.fontScale or 1.0)
    end

    local swatchSize = math.max(28.0, layout.lineHeight + 8.0)
    local swatchX = p_x + width - swatchSize
    local swatchY = p_y + layout.titleY + ((layout.lineHeight - swatchSize) / 2.0)
    local swatchR, swatchG, swatchB = value.r, value.g, value.b
    ImGui.AddRectFilled(swatchX, swatchY, swatchX + swatchSize, swatchY + swatchSize, swatchR, swatchG, swatchB, math.floor(255 * (menu.renderAlpha or 1.0)), 4.0)
    local borderR, borderG, borderB, borderA = HexToRGBAInt("#5a5a69")
    ImGui.AddRect(swatchX, swatchY, swatchX + swatchSize, swatchY + swatchSize, borderR, borderG, borderB, borderA, 4.0, 0, 1.0)

    local channels = {
        {label = "R", key = "r", r = 255, g = 82, b = 82},
        {label = "G", key = "g", r = 82, g = 220, b = 126},
        {label = "B", key = "b", r = 82, g = 142, b = 255}
    }
    local rowY = p_y + layout.contentY
    local labelWidth = 18
    local valueWidth = 28
    local trackX = p_x + indent + labelWidth
    local trackWidth = width - indent - labelWidth - valueWidth - 8
    local trackHeight = 10

    for index, channel in ipairs(channels) do
        local y = rowY + (index - 1) * layout.rowStep
        ImGui.SetCursorScreenPos(trackX, y)
        ImGui.InvisibleButton("##color_" .. channel.key .. "_" .. tostring(item.uid or item.label), trackWidth, math.max(18.0, layout.lineHeight + 4.0))
        if index == 1 then menu.handleQuickItem(item) end
        local channelActive = ImGui.IsItemActive() and not menu.comboBlocksInput(item)
        if channelActive and not item._quickActive then
            item._quickActive = true
            menu.recordUsage(item)
        elseif not channelActive and index == #channels then
            item._quickActive = false
        end
        if channelActive then
            local mouseX = ImGui.GetMousePos()
            local fraction = (mouseX - trackX) / trackWidth
            if fraction < 0 then fraction = 0 end
            if fraction > 1 then fraction = 1 end
            local nextValue = math.floor(fraction * 255 + 0.5)
            if nextValue ~= value[channel.key] then
                value[channel.key] = nextValue
                if item.callback then
                    menu.enqueueAction(item.label, item.callback, value.r, value.g, value.b, value.a)
                end
            end
        end

        ImGui.SetCursorScreenPos(p_x + indent, y)
        menu.localizedTextColored(tr, tg, tb, ta, channel.label)
        local bgR, bgG, bgB, bgA = HexToRGBAInt("#212128")
        local trackY = y + math.max(0.0, (layout.lineHeight - trackHeight) / 2.0)
        ImGui.AddRectFilled(trackX, trackY, trackX + trackWidth, trackY + trackHeight, bgR, bgG, bgB, bgA, trackHeight / 2)
        local fillWidth = trackWidth * (value[channel.key] / 255)
        ImGui.AddRectFilled(trackX, trackY, trackX + fillWidth, trackY + trackHeight, channel.r, channel.g, channel.b, math.floor(255 * (menu.renderAlpha or 1.0)), trackHeight / 2)
        local valueText = tostring(value[channel.key])
        ImGui.SetCursorScreenPos(p_x + width - valueWidth, y)
        menu.localizedTextColored(tr, tg, tb, ta, valueText)
    end

    local lineR, lineG, lineB, lineA = HexToRGBAInt("#23232c", 0.72)
    ImGui.AddLine(p_x + indent, p_y + height, p_x + width, p_y + height, lineR, lineG, lineB, lineA, 1.0)
end)

local DrawCustomCombo = LPH_NO_VIRTUALIZE(function(item, p_x, p_y, width)
    local layout = menu.getItemLayout(item)
    local height = layout.height
    local box_h = layout.controlHeight
    local indent = item.indent or 0
    item.anim_hover = item.anim_hover or 0
    item.anim_open = item.anim_open or 0
    item.is_open = item.is_open or false
    item.option_sel_anim = item.option_sel_anim or {}
    item.option_hover_anim = item.option_hover_anim or {}

    local uid = tostring(item.uid or item.label)
    local combo_id = "##combo_" .. uid
    local popup_id = "##combo_popup_" .. uid
    
    -- Title
    ImGui.SetCursorScreenPos(p_x + indent, p_y + layout.titleY)
    local tr, tg, tb, ta = HexToRGBAFloat("#ffffff")
    menu.localizedTextColored(tr, tg, tb, ta, item.label)
    
    -- Description
    if layout.hasDescription then
        ImGui.SetCursorScreenPos(p_x + indent, p_y + layout.descriptionY)
        ImGui.SetWindowFontScale((menu.ui.fontScale or 1.0) * 0.85)
        menu.drawItemDescription(item, p_x + indent, p_y + layout.descriptionY, width - indent)
        ImGui.SetWindowFontScale(menu.ui.fontScale or 1.0)
    end
    
    -- Box
    local box_y = p_y + layout.contentY
    local box_x = p_x + indent
    local box_w = width - indent

    ImGui.SetCursorScreenPos(box_x, box_y)
    local clicked = ImGui.InvisibleButton(combo_id, box_w, box_h)
    menu.handleQuickItem(item)
    local just_opened = false
    if clicked and not menu.comboBlocksInput(item) then
        item.is_open = not item.is_open
        just_opened = item.is_open
        if item.is_open then
            menu.comboModalItem = item
            menu.comboModalActive = true
        elseif menu.comboModalItem == item then
            menu.comboModalItem = nil
            menu.comboModalActive = false
        end
    end
    local is_hovered = ImGui.IsItemHovered()
    local target_hover = is_hovered and 1 or 0
    local target_open = item.is_open and 1 or 0
    item.anim_hover = menu.animLerp(item.anim_hover, target_hover, 10.0, g_dt)
    item.anim_open = menu.animLerp(item.anim_open, target_open, 12.0, g_dt)
    
    local bg_r, bg_g, bg_b, bg_a = HexToRGBAInt("#212128")
    ImGui.AddRectFilled(box_x, box_y, box_x + box_w, box_y + box_h, bg_r, bg_g, bg_b, bg_a, 8.0)
    local border_r, border_g, border_b, border_a = HexToRGBAInt("#23232c", 0.9)
    ImGui.AddLine(box_x + box_w - 28, box_y + 8, box_x + box_w - 28, box_y + box_h - 8, border_r, border_g, border_b, border_a, 1.0)
    
    -- Selected Value
    local val_text = item.options[item.value] or ""
    local _, combo_text_h = menu.localizedTextSize(val_text)
    if not combo_text_h then combo_text_h = 14 end
    ImGui.SetCursorScreenPos(box_x + 10, box_y + ((box_h - combo_text_h) / 2))
    menu.localizedTextColored(tr, tg, tb, ta, val_text)
    
    -- Arrow
    local arrow_x = box_x + box_w - 15
    local arrow_y = box_y + box_h / 2
    
    local ar_r, ar_g, ar_b, ar_a = HexToRGBAFloat("#6e6e81", 0.96)
    local hover_r, hover_g, hover_b, hover_a = HexToRGBAFloat("#ffffff", 0.96)
    local open_r, open_g, open_b, open_a = HexToRGBAFloat("#b0b4ff")
    if is_hovered then
        ar_r = ar_r + (hover_r - ar_r) * item.anim_hover
        ar_g = ar_g + (hover_g - ar_g) * item.anim_hover
        ar_b = ar_b + (hover_b - ar_b) * item.anim_hover
        ar_a = ar_a + (hover_a - ar_a) * item.anim_hover
    end
    ar_r = ar_r + (open_r - ar_r) * item.anim_open
    ar_g = ar_g + (open_g - ar_g) * item.anim_open
    ar_b = ar_b + (open_b - ar_b) * item.anim_open
    ar_a = ar_a + (open_a - ar_a) * item.anim_open
    
    -- Draw simple chevron
    local t = item.anim_open
    local p1_x = arrow_x - 4
    local p2_x = arrow_x
    local p3_x = arrow_x + 4
    local p1_y = (arrow_y - 2) + (4 * t)
    local p2_y = (arrow_y + 2) - (4 * t)
    local p3_y = (arrow_y - 2) + (4 * t)
    
    local arr_ir, arr_ig, arr_ib, arr_ia = math.floor(ar_r*255), math.floor(ar_g*255), math.floor(ar_b*255), math.floor(ar_a*255)
    ImGui.AddLine(p1_x, p1_y, p2_x, p2_y, arr_ir, arr_ig, arr_ib, arr_ia, 1.5)
    ImGui.AddLine(p2_x, p2_y, p3_x, p3_y, arr_ir, arr_ig, arr_ib, arr_ia, 1.5)
    
    -- Separator line
    local line_r, line_g, line_b, line_a = HexToRGBAInt("#23232c", 0.72)
    ImGui.AddLine(p_x + indent, p_y + height, p_x + width, p_y + height, line_r, line_g, line_b, line_a, 1.0)

    if item.is_open or item.anim_open > 0.01 then
        table.insert(comboOverlayQueue, {
            item = item,
            uid = uid,
            box_x = box_x,
            box_y = box_y,
            box_w = box_w,
            box_h = box_h,
            line_r = line_r,
            line_g = line_g,
            line_b = line_b,
            line_a = line_a,
            tr = tr,
            tg = tg,
            tb = tb,
            ta = ta,
            bg_r = bg_r,
            bg_g = bg_g,
            bg_b = bg_b,
            border_r = border_r,
            border_g = border_g,
            border_b = border_b,
            border_a = border_a,
            just_opened = just_opened
        })
    end
end)

local DrawComboOverlays = LPH_NO_VIRTUALIZE(function()
    if menu.comboModalActive and #comboOverlayQueue == 0 then
        if menu.comboModalItem then menu.comboModalItem.is_open = false end
        menu.comboModalItem = nil
        menu.comboModalActive = false
        return
    end
    for _, data in ipairs(comboOverlayQueue) do
        local item = data.item
        local row_h = math.max(27.0, menu.getUiLineHeight() + 9.0)
        local max_rows = 10
        local option_count = #item.options
        local page_count = math.max(1, math.ceil(option_count / max_rows))
        if data.just_opened or not item.option_page then
            item.option_page = math.floor((math.max(1, item.value or 1) - 1) / max_rows) + 1
        end
        item.option_page = math.max(1, math.min(page_count, item.option_page))
        local page_start = ((item.option_page - 1) * max_rows) + 1
        local page_end = math.min(option_count, page_start + max_rows - 1)
        local visible_count = math.max(0, page_end - page_start + 1)
        local has_pager = page_count > 1
        local popup_x = data.box_x
        local popup_y = (data.box_y + data.box_h + 2) + ((1.0 - item.anim_open) * 6.0)
        local popup_w = data.box_w
        local popup_h = (visible_count + (has_pager and 1 or 0)) * row_h
        local popup_alpha = math.max(0.0, math.min(1.0, tonumber(item.anim_open) or 0.0))

        ImGui.SetNextWindowPos(popup_x, popup_y, ImGuiCond.Always, 0.0, 0.0)
        ImGui.SetNextWindowSize(popup_w, popup_h, ImGuiCond.Always)
        local popup_flags = ImGuiWindowFlags.NoTitleBar
            | ImGuiWindowFlags.NoResize
            | ImGuiWindowFlags.NoMove
            | ImGuiWindowFlags.NoScrollbar
            | ImGuiWindowFlags.NoScrollWithMouse
            | ImGuiWindowFlags.NoCollapse
            | ImGuiWindowFlags.NoSavedSettings
            | ImGuiWindowFlags.NoBackground

        if ImGui.Begin("Z_ComboPopup_" .. data.uid, true, popup_flags) then
            ImGui.SetWindowFontScale(menu.ui.fontScale or 1.0)
            local shadow_r, shadow_g, shadow_b, shadow_a = HexToRGBAInt("#000000", 0.28)
            ImGui.AddRectFilled(popup_x + 1, popup_y + 2, popup_x + popup_w + 1, popup_y + popup_h + 2,
                shadow_r, shadow_g, shadow_b, math.floor(shadow_a * popup_alpha), 5.0)
            ImGui.AddRectFilled(popup_x, popup_y, popup_x + popup_w, popup_y + popup_h,
                data.bg_r, data.bg_g, data.bg_b, math.floor(255 * (menu.renderAlpha or 1.0) * popup_alpha), 4.0)
            ImGui.AddLine(popup_x, popup_y, popup_x + popup_w, popup_y,
                data.border_r, data.border_g, data.border_b, math.floor(data.border_a * popup_alpha), 1.0)
            ImGui.AddLine(popup_x, popup_y + popup_h, popup_x + popup_w, popup_y + popup_h,
                data.border_r, data.border_g, data.border_b, math.floor(data.border_a * popup_alpha), 1.0)

            local option_y = popup_y
            if has_pager then
                local pager_mid = popup_x + (popup_w / 2)
                ImGui.SetCursorScreenPos(popup_x, popup_y)
                local prev_clicked = ImGui.InvisibleButton("##combo_prev_" .. data.uid, popup_w / 2, row_h)
                ImGui.SetCursorScreenPos(pager_mid, popup_y)
                local next_clicked = ImGui.InvisibleButton("##combo_next_" .. data.uid, popup_w / 2, row_h)
                ImGui.AddLine(popup_x + 10, popup_y + row_h, popup_x + popup_w - 10, popup_y + row_h, data.line_r, data.line_g, data.line_b, data.line_a, 1.0)
                ImGui.AddLine(pager_mid, popup_y + 6, pager_mid, popup_y + row_h - 6, data.line_r, data.line_g, data.line_b, data.line_a, 1.0)
                local prev_text = "<"
                local next_text = ">"
                local page_text = string.format("%d/%d", item.option_page, page_count)
                local pager_text_y = popup_y + math.max(0.0, (row_h - menu.getUiLineHeight()) / 2.0)
                ImGui.SetCursorScreenPos(popup_x + 10, pager_text_y)
                menu.localizedTextColored(data.tr, data.tg, data.tb, data.ta * popup_alpha, prev_text)
                local page_w = menu.localizedTextSize(page_text)
                ImGui.SetCursorScreenPos(popup_x + ((popup_w - (tonumber(page_w) or 0)) / 2), pager_text_y)
                menu.localizedTextColored(data.tr, data.tg, data.tb, data.ta * popup_alpha, page_text)
                local next_w = menu.localizedTextSize(next_text)
                ImGui.SetCursorScreenPos(popup_x + popup_w - (tonumber(next_w) or 0) - 10, pager_text_y)
                menu.localizedTextColored(data.tr, data.tg, data.tb, data.ta * popup_alpha, next_text)
                if item.is_open and (prev_clicked or next_clicked) then
                    menu.actionQueue = {}
                    if prev_clicked then
                        item.option_page = math.max(1, item.option_page - 1)
                    else
                        item.option_page = math.min(page_count, item.option_page + 1)
                    end
                end
                option_y = popup_y + row_h
            end

            for i = page_start, page_end do
                local opt = item.options[i]
                local row_y = option_y + ((i - page_start) * row_h)
                local row_x = popup_x
                local row_w = popup_w
                ImGui.SetCursorScreenPos(row_x, row_y)
                local row_pressed = ImGui.InvisibleButton("##combo_option_" .. data.uid .. "_" .. tostring(i), row_w, row_h)
                local row_hovered = ImGui.IsItemHovered()
                local row_clicked = row_pressed and item.is_open
                local is_selected = (i == item.value)
                local sel_anim = item.option_sel_anim[i] or 0
                local hov_anim = item.option_hover_anim[i] or 0
                local sel_target = is_selected and 1 or 0
                local hov_target = row_hovered and 1 or 0
                sel_anim = menu.animLerp(sel_anim, sel_target, 14.0, g_dt)
                hov_anim = menu.animLerp(hov_anim, hov_target, 16.0, g_dt)
                item.option_sel_anim[i] = sel_anim
                item.option_hover_anim[i] = hov_anim

                if hov_anim > 0.01 or sel_anim > 0.01 then
                    local hr, hg, hb, _ = HexToRGBAInt("#262532")
                    local h_alpha = (0.15 * sel_anim) + (0.75 * hov_anim)
                    ImGui.AddRectFilled(row_x + 2, row_y + 1, row_x + row_w - 2, row_y + row_h - 1, hr, hg, hb, math.floor(255 * h_alpha * (menu.renderAlpha or 1.0)), 4.0)
                end
                if i < page_end then
                    ImGui.AddLine(row_x + 10, row_y + row_h, row_x + row_w - 10, row_y + row_h, data.line_r, data.line_g, data.line_b, data.line_a, 1.0)
                end

                local text_x = row_x + 10 + (6.0 * sel_anim)
                item._optionTextSize = item._optionTextSize or {}
                local optCache = item._optionTextSize[i]
                local optScale = menu.ui.fontScale or 1.0
                local opt_text_h = type(optCache) == "table" and optCache.label == opt
                    and optCache.scale == optScale and optCache.height or nil
                if not opt_text_h then
                    local _, measured = menu.localizedTextSize(opt)
                    opt_text_h = tonumber(measured) or 14
                    if opt_text_h > 0 then item._optionTextSize[i] = {label = opt, scale = optScale, height = opt_text_h} end
                end
                if not opt_text_h then opt_text_h = 14 end
                local off_r, off_g, off_b, off_a = 110 / 255, 110 / 255, 129 / 255, 1.0
                menu.drawClippedText(opt, text_x, row_y + ((row_h - opt_text_h) / 2),
                    row_x + row_w - 8, row_y + row_h,
                    off_r + (data.tr - off_r) * sel_anim,
                    off_g + (data.tg - off_g) * sel_anim,
                    off_b + (data.tb - off_b) * sel_anim,
                    (off_a + (data.ta - off_a) * sel_anim) * popup_alpha
                )

                if row_clicked then
                    menu.actionQueue = {}
                    item.prevValue = item.value
                    item.value = i
                    item.is_open = false
                    if menu.comboModalItem == item then
                        menu.comboModalItem = nil
                        menu.comboModalActive = false
                    end
                    if menu.recordUsage then menu.recordUsage(item) end
                    if item.callback then menu.enqueueAction(item.label, item.callback, i) end
                end
            end

            if item.is_open and ImGui.IsMouseClicked(0) and not data.just_opened then
                local mx, my = ImGui.GetMousePos()
                local in_box = mx >= data.box_x and mx <= data.box_x + data.box_w and my >= data.box_y and my <= data.box_y + data.box_h
                local in_popup = mx >= popup_x and mx <= popup_x + popup_w and my >= popup_y and my <= popup_y + popup_h
                if not in_box and not in_popup then
                    menu.actionQueue = {}
                    item.is_open = false
                    if menu.comboModalItem == item then
                        menu.comboModalItem = nil
                        menu.comboModalActive = false
                    end
                end
            end
            ImGui.SetWindowFontScale(1.0)
        end
        ImGui.End()
    end
end)

local GetNotifyStatusColor = LPH_NO_VIRTUALIZE(function(status)
    if status == "success" or status == 1 then
        return HexToRGBAInt("#6fd38f")
    elseif status == "warning" or status == 2 then
        return HexToRGBAInt("#f3c56b")
    elseif status == "error" or status == 3 then
        return HexToRGBAInt("#f07474")
    end
    return HexToRGBAInt("#b0b4ff")
end)

menu.layoutNotificationText = LPH_NO_VIRTUALIZE(function(value, wrapWidth, maxLines, lineHeight)
    local raw = menu.translate(tostring(value or ""))
    -- Bound one-time layout work; the complete message remains in notification history.
    local truncated = #raw > 16384
    local text = raw:sub(1, 16384):gsub("\r\n", "\n"):gsub("\r", "\n"):gsub("\t", "    "):gsub("%z", "")
    local units, lines = {}, {}
    for unit in text:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
        -- A byte cap may cut the final UTF-8 sequence; never render that fragment.
        local byte = unit:byte()
        local length = byte < 128 and 1 or (byte < 224 and 2 or (byte < 240 and 3 or 4))
        if #unit == length then units[#units + 1] = unit end
    end
    local width = math.max(0, wrapWidth - 2)
    local limit = math.max(1, math.floor(maxLines))
    local ready = true
    local function fits(candidate)
        local ok, measured = pcall(menu.localizedTextSize, candidate)
        if ok and type(measured) == "number" and measured == measured and measured >= 0 and measured < rawget(math, "huge") then
            return measured <= width
        end
        ready = false
        -- Missing metrics must not make a long message look like one short line.
        return #candidate * lineHeight <= width
    end
    local first = 1
    while first <= #units and #lines < limit do
        if units[first] == "\n" then
            lines[#lines + 1], first = "", first + 1
        else
            local ending = first
            while ending < #units and units[ending + 1] ~= "\n" and ending - first < 255 do ending = ending + 1 end
            local low, high, last = first, ending, first - 1
            while low <= high do
                local middle = math.floor((low + high) / 2)
                if fits(table.concat(units, "", first, middle)) then last, low = middle, middle + 1
                else high = middle - 1 end
            end
            if last < first then truncated = true; break end
            if last < ending and #units[last] == 1 and #units[last + 1] == 1 then
                for index = last, first + 1, -1 do
                    if units[index] == " " then last = index; break end
                end
            end
            lines[#lines + 1] = table.concat(units, "", first, last)
            first = last + 1
            if units[first] == "\n" then first = first + 1 end
        end
    end
    truncated = truncated or first <= #units
    if #lines == 0 then lines[1] = "" end
    if truncated then
        local tail = {}
        for unit in lines[#lines]:gmatch("[%z\1-\127\194-\244][\128-\191]*") do tail[#tail + 1] = unit end
        local low, high, best = 0, #tail, ""
        while low <= high do
            local middle = math.floor((low + high) / 2)
            local candidate = table.concat(tail, "", 1, middle) .. "..."
            if fits(candidate) then best, low = candidate, middle + 1 else high = middle - 1 end
        end
        lines[#lines] = best
    end
    return lines, truncated, ready
end)

local DrawNotifications = LPH_NO_VIRTUALIZE(function()
    if #notifyQueue == 0 then return end

    local disp_w, disp_h = ImGui.GetDisplaySize()
    local now = ImGui.GetTime()
    local requestedWidth = math.max(260, tonumber(menu.ui.notificationWidth) or 312)
    local w = math.min(requestedWidth, math.max(80, disp_w - 40))
    local position = math.floor(math.max(1, math.min(4, tonumber(menu.ui.notificationPosition) or 1)))
    local alignRight = position == 2 or position == 4
    local alignBottom = position == 3 or position == 4
    local availableHeight = math.max(80, disp_h - 36)
    local fontSize
    if type(ImGui.GetFontSize) == "function" then
        local ok, value = pcall(ImGui.GetFontSize)
        if ok and type(value) == "number" and value > 0 and value < rawget(math, "huge") then fontSize = value end
    end
    local totalHeight = 0
    for index = #notifyQueue, 1, -1 do
        local entry = notifyQueue[index]
        local hasTitle = entry.title and entry.title ~= ""
        if entry.layout_language ~= menu.ui.language or entry.layout_revision ~= menu.translationRevision or entry.layout_w ~= w or entry.layout_scale ~= menu.ui.fontScale or entry.layout_height ~= availableHeight
            or entry.layout_font ~= fontSize or entry.layout_title ~= entry.title or entry.layout_label ~= entry.label
            or (entry.layout_retry_at and now >= entry.layout_retry_at) then
            local ok, _, measuredLineHeight = pcall(menu.localizedTextSize, "Ag")
            local measured = ok and tonumber(measuredLineHeight) or nil
            if not measured or measured ~= measured or measured <= 0 or measured == rawget(math, "huge") then measured = nil end
            entry.line_h = math.max(16, math.ceil(math.max(measured or 0, tonumber(fontSize) or 0,
                14 * (tonumber(menu.ui.fontScale) or 1))) + 3)
            local titleLimit = math.min(2, math.max(1, math.floor((availableHeight - 34) / entry.line_h) - 1))
            local titleReady, bodyReady = true, true
            if hasTitle then
                entry.titleLines, entry.titleTruncated, titleReady = menu.layoutNotificationText(entry.title, w - 48, titleLimit, entry.line_h)
            else entry.titleLines = {} end
            entry.title_h = #entry.titleLines * entry.line_h
            entry.body_y = hasTitle and (12 + entry.title_h) or 10
            local maxLines = math.max(1, math.floor((availableHeight - entry.body_y - 14) / entry.line_h))
            entry.bodyLines, entry.bodyTruncated, bodyReady = menu.layoutNotificationText(entry.label, w - 28, maxLines, entry.line_h)
            entry.card_h = math.max(50, entry.body_y + #entry.bodyLines * entry.line_h + 14)
            entry.layout_language = menu.ui.language
            entry.layout_revision = menu.translationRevision
            entry.layout_w = w
            entry.layout_retry_at = nil
            if not (measured and titleReady and bodyReady) then entry.layout_retry_at = now + 0.5 end
            entry.layout_scale = menu.ui.fontScale
            entry.layout_height = availableHeight
            entry.layout_font = fontSize
            entry.layout_title, entry.layout_label = entry.title, entry.label
            entry.stack_y = nil
        end
        totalHeight = totalHeight + (tonumber(entry.card_h) or 62) + 10
    end
    while #notifyQueue > 1 and (totalHeight - 10) > availableHeight do
        local removed = table.remove(notifyQueue)
        totalHeight = totalHeight - ((tonumber(removed and removed.card_h) or 62) + 10)
    end
    if totalHeight > 0 then totalHeight = totalHeight - 10 end
    local base_x = alignRight and (disp_w - w - 20) or 20
    local current_y = alignBottom and math.max(18, disp_h - totalHeight - 18) or 18

    for i = #notifyQueue, 1, -1 do
        local n = notifyQueue[i]
        if (now - n.created_at) >= n.duration then
            n.closing = true
        end

        local target = n.closing and 0.0 or 1.0
        n.anim = menu.animLerp(n.anim, target, 12.0, g_dt)

        if n.closing and n.anim <= 0.05 then
            table.remove(notifyQueue, i)
        else
            local hasTitle = n.title and n.title ~= ""
            local h = n.card_h
            local x = alignRight
                and (base_x + ((1.0 - n.anim) * 18.0))
                or (base_x - ((1.0 - n.anim) * 18.0))
            n.stack_y = menu.animLerp(n.stack_y or current_y, current_y, 16.0, g_dt)
            local y = n.stack_y

            local bg_r, bg_g, bg_b, _ = HexToRGBAInt("@notification")
            local bd_r, bd_g, bd_b, bd_a = HexToRGBAInt("#282d38", 0.95)
            local ac_r, ac_g, ac_b, _ = GetNotifyStatusColor(n.status)
            if n.poolPressure then
                bg_r, bg_g, bg_b = 38, 15, 20
                bd_r, bd_g, bd_b, bd_a = 240, 86, 96, 230
                ac_r, ac_g, ac_b = 255, 92, 104
            end
            local opacity = math.max(0.70, math.min(1.0, (tonumber(menu.ui.notificationOpacity) or 96) / 100))
            local alpha = math.floor(255 * n.anim * opacity)
            local border_alpha = math.floor(bd_a * n.anim)
            local accent_alpha = math.floor(255 * n.anim)

            ImGui.AddRectFilled(x, y, x + w, y + h, bg_r, bg_g, bg_b, alpha, 6.0)
            ImGui.AddRect(x + 0.5, y + 0.5, x + w - 0.5, y + h - 0.5, bd_r, bd_g, bd_b, border_alpha, 6.0, 0, 1.0)

            -- status badge with icon
            local badge_w = 18
            local badge_h = 18
            local badge_x = x + 10
            local badge_y = y + 8
            local ic_x = badge_x + (badge_w / 2)
            local ic_y = badge_y + (badge_h / 2)
            if hasTitle then
                ImGui.AddCircleFilled(ic_x, ic_y, 9.0, ac_r, ac_g, ac_b, math.floor(25 * n.anim))
            end
            local ic_a = math.floor(255 * n.anim)
            local status = n.status
            if not hasTitle then
                ImGui.AddLine(x + 2, y + 9, x + 2, y + h - 9, ac_r, ac_g, ac_b, ic_a, 2.0)
            elseif status == "success" or status == 1 then
                ImGui.AddLine(ic_x - 4, ic_y + 0, ic_x - 1, ic_y + 3, ac_r, ac_g, ac_b, ic_a, 1.7)
                ImGui.AddLine(ic_x - 1, ic_y + 3, ic_x + 4, ic_y - 3, ac_r, ac_g, ac_b, ic_a, 1.7)
            elseif status == "warning" or status == 2 or n.poolPressure then
                ImGui.AddLine(ic_x, ic_y - 4, ic_x, ic_y + 1, ac_r, ac_g, ac_b, ic_a, 1.8)
                ImGui.AddCircleFilled(ic_x, ic_y + 4, 1.2, ac_r, ac_g, ac_b, ic_a)
            elseif status == "error" or status == 3 then
                ImGui.AddLine(ic_x - 3, ic_y - 3, ic_x + 3, ic_y + 3, ac_r, ac_g, ac_b, ic_a, 1.8)
                ImGui.AddLine(ic_x + 3, ic_y - 3, ic_x - 3, ic_y + 3, ac_r, ac_g, ac_b, ic_a, 1.8)
            else
                ImGui.AddCircleFilled(ic_x, ic_y - 2, 1.5, ac_r, ac_g, ac_b, ic_a)
                ImGui.AddLine(ic_x, ic_y, ic_x, ic_y + 4, ac_r, ac_g, ac_b, ic_a, 1.7)
            end

            local text_left = x + 14
            local text_right = x + w - 14
            local text_bottom = y + h - 10
            ImGui.PushClipRect(text_left, y + 6, text_right, text_bottom, true)
            ImGui.PushTextWrapPos(-1)
            local tr, tg, tb = HexToRGBAFloat("#e8ebf2")
            local mr, mg, mb = HexToRGBAFloat("#929aaa")
            if n.poolPressure then
                tr, tg, tb = HexToRGBAFloat("#ff8b8b")
                mr, mg, mb = HexToRGBAFloat("#ffacac")
            end
            if hasTitle then
                ImGui.PushClipRect(x + 34, y + 6, text_right, y + 10 + n.title_h, true)
                for line, text in ipairs(n.titleLines) do
                    ImGui.SetCursorScreenPos(x + 34, y + 8 + (line - 1) * n.line_h)
                    menu.localizedTextColored(tr, tg, tb, n.anim, text)
                end
                ImGui.PopClipRect()
            end
            for line, text in ipairs(n.bodyLines) do
                ImGui.SetCursorScreenPos(text_left, y + n.body_y + (line - 1) * n.line_h)
                menu.localizedTextColored(hasTitle and mr or tr, hasTitle and mg or tg, hasTitle and mb or tb, n.anim, text)
            end
            ImGui.PopTextWrapPos()
            ImGui.PopClipRect()

            local life = now - n.created_at
            local remain = 1.0 - (life / n.duration)
            if n.poolPressure and not n.closing then remain = 1.0 end
            if remain < 0 then remain = 0 end
            if remain > 1 then remain = 1 end
            local track_x = x + 10
            local track_y = y + h - 4
            local track_w = w - 20
            local track_h = 2
            local prog_w = track_w * remain
            if prog_w < 0 then prog_w = 0 end
            if prog_w > track_w then prog_w = track_w end

            local tr_r, tr_g, tr_b, tr_a = HexToRGBAInt("#212128", 1.0)
            tr_a = math.floor(tr_a * n.anim)
            ImGui.AddRectFilled(track_x, track_y, track_x + track_w, track_y + track_h, tr_r, tr_g, tr_b, tr_a, track_h / 2)
            ImGui.AddRectFilled(track_x, track_y, track_x + prog_w, track_y + track_h, ac_r, ac_g, ac_b, accent_alpha, track_h / 2)

            current_y = current_y + h + 10
        end
    end
end)

local SyncBoundItemValue = LPH_NO_VIRTUALIZE(function(item)
    if not item.player_bind then return end
    local pid = playerCtx.selected
    if pid == nil then return end
    local bind = item.player_bind
    local st = EnsurePlayerState(pid)
    if not st then return end
    if st[bind.key] == nil then
        st[bind.key] = bind.default
    end
    if bind.kind == "toggle" or bind.kind == "slider" or bind.kind == "combo" then
        item.value = st[bind.key]
    end
end)

menu.getCachedSessionPlayers = LPH_NO_VIRTUALIZE(function()
    local now = ImGui.GetTime()
    local cache = playerCtx.listCache
    if now - (cache.refreshedAt or 0) >= 1.0 then
        cache.players = GetSessionPlayers()
        cache.refreshedAt = now
    end
    cache.names = cache.names or {}
    cache.nameTimes = cache.nameTimes or {}
    return cache.players or {}, cache.names, cache.nameTimes
end)

menu.getCachedPlayerInfo = LPH_NO_VIRTUALIZE(function(pid)
    local now = ImGui.GetTime()
    local cache = playerCtx.infoCache
    if cache.pid ~= pid or cache.details == nil then
        local tags = ""
        if Players and type(Players.GetTags) == "function" then
            local ok_tags, value = pcall(Players.GetTags, pid)
            if ok_tags and value ~= nil then
                tags = tostring(value)
            end
        end
        local rid = GetPlayerRockstarId(pid)
        local distance = GetPlayerDistance(pid)
        local modder_text, modder_level = GetPlayerModderStatus(pid, rid, tags)
        local details = SovereignGetPlayerInfoDetails(pid)
        cache.pid = pid
        cache.refreshedAt = now
        cache.name = GetPlayerName(pid)
        cache.tags = tags
        cache.rid = rid
        cache.distance = distance
        cache.modder_text = modder_text
        cache.modder_level = modder_level
        cache.details = details
        cache.dynamicRefreshedAt = now
    elseif now - (cache.dynamicRefreshedAt or 0) >= 0.5 then
        cache.distance = GetPlayerDistance(pid)
        cache.dynamicRefreshedAt = now
    end
    return cache
end)

