            local rid = info.rid
            local distance = info.distance
            local details = info.details or {}
            local modder_text, modder_level = info.modder_text, info.modder_level

            ImGui.SetCursorScreenPos(x + 14, y + 66)
            ImGui.TextColored(tr, tg, tb, ta, name)
            ImGui.SetCursorScreenPos(x + 14, y + 84)
            menu.localizedTextColored(sr, sg, sb, sa, "PID: " .. tostring(pid))

            -- Tiny tags badge
            local tag_text = (tags ~= "" and tags ~= "0") and tags or "SESSION"
            ImGui.SetCursorScreenPos(x + panel_w - 112, y + 68)
            local badge_r, badge_g, badge_b, badge_a = HexToRGBAInt("#262532")
            ImGui.AddRectFilled(x + panel_w - 116, y + 66, x + panel_w - 18, y + 84, badge_r, badge_g, badge_b, badge_a, 4.0)
            menu.localizedTextColored(0.69, 0.71, 1.0, 1.0, tag_text)

            local rid_text = rid and tostring(rid) or "Unknown"
            local dist_text = distance and string.format("%.1fm", distance) or "Unknown"
            local mr, mg, mb, ma = tr, tg, tb, ta
            if modder_level == "danger" then
                mr, mg, mb, ma = HexToRGBAFloat("#ff8f8f")
            elseif modder_level == "warning" then
                mr, mg, mb, ma = HexToRGBAFloat("#ffd37a")
            else
                mr, mg, mb, ma = HexToRGBAFloat("#a6f3b3")
            end

            local leftRows = {
                {"Rockstar ID", rid_text, tr, tg, tb, ta},
                {"IPv4", details.ip or "Unavailable", tr, tg, tb, ta},
                {"Network", details.network or "Unknown", tr, tg, tb, ta},
                {"Latency", details.ping or "Unavailable", tr, tg, tb, ta},
                {"Platform", details.platform or "Unknown", tr, tg, tb, ta},
                {"Language", details.language or "Unknown", tr, tg, tb, ta},
                {"Country", details.country or "Unknown", tr, tg, tb, ta}
            }
            local rightRows = {
                {"Region", details.region or "Unknown", tr, tg, tb, ta},
                {"Level", details.rank or "Unknown", tr, tg, tb, ta},
                {"City", details.city or "Unknown", tr, tg, tb, ta},
                {"Host", details.host or "Unknown", tr, tg, tb, ta},
                {"Coordinates", details.coordinates or "Unavailable", tr, tg, tb, ta},
                {"Zone", details.zone or "Unknown zone", tr, tg, tb, ta},
                {"Distance", dist_text, tr, tg, tb, ta},
                {"Cheat flags", modder_text or "No records", mr, mg, mb, ma}
            }

            local childW = panel_w - 28
            local childH = panel_h - 116
            ImGui.SetCursorScreenPos(x + 14, y + 104)
            local childBgIndex = ImGuiCol and ImGuiCol.ChildBg or 3
            local childBgR, childBgG, childBgB, childBgA = HexToRGBAFloat("#1c1c21")
            ImGui.PushStyleColor(childBgIndex, childBgR, childBgG, childBgB, childBgA)
            if ImGui.BeginChild("##selected_player_info_scroll", childW, childH, false, 0) then
                local childScreenX, childScreenY = ImGui.GetWindowPos()
                local cellGap = 8
                local cellW = (childW - cellGap) / 2.0
                local rowH = 30
                local rowBgR, rowBgG, rowBgB, rowBgA = HexToRGBAInt("#1c1c21", 0.96)
                local lineR, lineG, lineB, lineA = HexToRGBAInt("#343447", 0.72)
                local function ShortInfoValue(value)
                    return tostring(value or "Unknown")
                end
                local function DrawInfoCell(columnX, rowIndex, row)
                    local rowY = (rowIndex - 1) * rowH
                    ImGui.AddRectFilled(childScreenX + columnX, childScreenY + rowY, childScreenX + columnX + cellW, childScreenY + rowY + rowH - 3, rowBgR, rowBgG, rowBgB, rowBgA, 5.0)
                    ImGui.AddLine(childScreenX + columnX + 6, childScreenY + rowY + rowH - 3, childScreenX + columnX + cellW - 6, childScreenY + rowY + rowH - 3, lineR, lineG, lineB, lineA, 1.0)
                    ImGui.SetCursorPos(columnX + 9, rowY + 7)
                    menu.localizedTextColored(sr, sg, sb, sa, row[1])
                    ImGui.PushClipRect(childScreenX + columnX + 100, childScreenY + rowY + 3, childScreenX + columnX + cellW - 6, childScreenY + rowY + rowH - 3, true)
                    ImGui.SetCursorPos(columnX + 100, rowY + 7)
                    menu.localizedTextColored(row[3], row[4], row[5], row[6], ShortInfoValue(row[2]))
                    ImGui.PopClipRect()
                end
                for index, row in ipairs(leftRows) do
                    DrawInfoCell(0, index, row)
                end
                for index, row in ipairs(rightRows) do
                    DrawInfoCell(cellW + cellGap, index, row)
                end
                ImGui.SetCursorPos(0, (#leftRows * rowH) + 2)
                ImGui.Dummy(1, 1)
            end
            ImGui.EndChild()
            ImGui.PopStyleColor()
        end
        ImGui.SetWindowFontScale(1.0)
    end
    ImGui.End()
end)

menu.drawCustomButton = LPH_NO_VIRTUALIZE(function(item, p_x, p_y, width)
    local layout = menu.getItemLayout(item)
    local height = layout.buttonHeight
    local button_y = p_y + math.max(0.0, tonumber(item._rowButtonOffset) or 0.0)
    local indent = item.indent or 0
    local btn_x = p_x + indent
    local btn_w = width - indent
    
    ImGui.SetCursorScreenPos(btn_x, button_y)
    local clicked = ImGui.InvisibleButton("##btn_" .. tostring(item.uid or item.label), btn_w, height)
    menu.handleQuickItem(item)
    if clicked and not menu.comboBlocksInput(item) then
        menu.recordUsage(item)
        if item.callback then menu.enqueueAction(item.label, item.callback) end
    end
    
    local is_hovered = ImGui.IsItemHovered()
    local is_active = ImGui.IsItemActive() and not menu.comboBlocksInput(item)
    
    local bg_r, bg_g, bg_b, bg_a
    if is_active then
        bg_r, bg_g, bg_b, bg_a = HexToRGBAInt("#ffffff")
    elseif is_hovered then
        bg_r, bg_g, bg_b, bg_a = HexToRGBAInt("#b0b4ff", 0.8)
    else
        bg_r, bg_g, bg_b, bg_a = HexToRGBAInt("#b0b4ff")
    end
    
    ImGui.AddRectFilled(btn_x, button_y, btn_x + btn_w, button_y + height, bg_r, bg_g, bg_b, bg_a, 8.0)
    
    local tr, tg, tb, ta = HexToRGBAFloat("#000000")
    local text_w, text_h = menu.localizedTextSize(item.label)
    if not text_w then text_w = 50 end
    if not text_h then text_h = 14 end
    
    ImGui.SetCursorScreenPos(btn_x + (btn_w - text_w) / 2, button_y + (height - text_h) / 2)
    menu.localizedTextColored(tr, tg, tb, ta, item.label)
    
    -- Separator line
    local line_r, line_g, line_b, line_a = HexToRGBAInt("#23232c", 0.72)
    local separator_y = p_y + math.max(layout.height, (tonumber(item._rowButtonOffset) or 0.0) + height)
    ImGui.AddLine(p_x + indent, separator_y, p_x + width, separator_y, line_r, line_g, line_b, line_a, 1.0)
end)

local DrawCustomText = LPH_NO_VIRTUALIZE(function(item, p_x, p_y)
    local layout = menu.getItemLayout(item)
    ImGui.SetCursorScreenPos(p_x, p_y + ((layout.height - layout.lineHeight) / 2.0))
    local tr, tg, tb, ta = HexToRGBAFloat("#d8d8dd")
    menu.localizedTextColored(tr, tg, tb, ta, item.label)
end)

-- Solstice visual primitives. Item state, callbacks and queueing stay on the
-- existing menu model; only measurement and drawing are replaced here.
menu.profileSaveHint = {label = "Save configuration", description = "Save feature toggles and the current menu configuration"}
menu.profileResetHint = {label = "Restore defaults", description = "Restore the default menu configuration"}

menu.updateBackgroundEffect = LPH_NO_VIRTUALIZE(function(forceOff)
    local desired = not forceOff and menu.requestedOpen == true and menu.ui.backdropBlur ~= 0
    local state = menu.blurState or {active = false, retryAt = 0}
    menu.blurState = state
    if desired == state.active or (not forceOff and os.clock() < state.retryAt) then return end
    local fn = menu.nativeApis.GRAPHICS and (desired and menu.nativeApis.GRAPHICS.TRIGGER_SCREENBLUR_FADE_IN or menu.nativeApis.GRAPHICS.TRIGGER_SCREENBLUR_FADE_OUT)
    local ok, result = false, false
    if type(fn) == "function" then ok, result = pcall(fn, forceOff and 0.0 or 180.0) end
    if ok and result ~= false then
        state.active, state.error, state.retryAt = desired, nil, 0
    else
        state.error, state.retryAt = "blur_unavailable", os.clock() + 2.0
    end
end)

menu.updateControlAnimation = LPH_NO_VIRTUALIZE(function(time)
    local state = menu.controlAnimation or {}
    menu.controlAnimation = state
    state.mode = math.floor(tonumber(menu.ui.controlMotion) or 3)
    local speed = math.max(10, math.min(200, tonumber(menu.ui.controlMotionSpeed) or 65)) / 100
    local frequency = state.mode == 2 and 2.4 or 0.9
    state.wave = (math.sin(time * speed * frequency) + 1) * 0.5
    state.amount = math.max(0, math.min(100, tonumber(menu.ui.controlMotionAmount) or 85)) / 100
    if state.mode == 4 and menu.hsvToRgb then
        state.r, state.g, state.b = menu.hsvToRgb((time * speed * 0.055) % 1, 0.57, 0.95)
    else
        state.r, state.g, state.b = menu.ui.motionR or 230, menu.ui.motionG or 152, menu.ui.motionB or 186
    end
end)

menu.animateControlColor = LPH_NO_VIRTUALIZE(function(r, g, b, kind)
    if kind and menu.ui[kind] == 0 then return r, g, b end
    local state = menu.controlAnimation
    if not state or state.mode == 1 or state.amount == 0 then return r, g, b end
    if state.mode == 2 then
        local light = 1 - 0.60 * (1 - state.wave) * state.amount
        return math.floor(r * light), math.floor(g * light), math.floor(b * light)
    end
    local blend = state.amount * (state.mode == 4 and 1 or state.wave)
    local brightness = menu.colorBrightness or 1
    return math.floor(r + (state.r * brightness - r) * blend),
        math.floor(g + (state.g * brightness - g) * blend),
        math.floor(b + (state.b * brightness - b) * blend)
end)

