menu.lucideIconScaleCache = {}
menu.drawLucideIcon = LPH_NO_VIRTUALIZE(function(slot, x, y, size, r, g, b)
    local source = menu.lucideIconSegments[slot]
    if not source or not ImGui or type(ImGui.AddLine) ~= "function" then return false end
    local cached = menu.lucideIconScaleCache[slot]
    if not cached or cached.size ~= size then
        local lines, scale = {}, size / 24
        for index = 1, #source do lines[index] = source[index] * scale end
        cached = {size = size, lines = lines}
        menu.lucideIconScaleCache[slot] = cached
    end
    local lines = cached.lines
    local byte = menu.imageColorByte
    local rr, gg, bb = byte(r or 255), byte(g or 255), byte(b or 255)
    local aa = byte(255 * (menu.renderAlpha or 1))
    local thickness = math.max(1.0, size * 1.8 / 24)
    for index = 1, #lines, 4 do
        ImGui.AddLine(x + lines[index], y + lines[index + 1],
            x + lines[index + 2], y + lines[index + 3], rr, gg, bb, aa, thickness)
    end
    return true
end)
menu.drawUiIcon = LPH_NO_VIRTUALIZE(function(slot, x, y, size, r, g, b)
    if slot == 4 then slot = 2 end
    local assets = menu.visualAssets
    if assets and assets.defaultLogoPath and type(menu.createTexture) == "function" then
        local now = os.clock()
        if menu.ensureEmbeddedTexture then
            assets.iconTexture = menu.ensureEmbeddedTexture("solstice-icons.png")
        elseif not assets.iconTexture and now >= (assets.iconRetryAt or 0) then
            local path = assets.defaultLogoPath:gsub("sovereign%-general%.png$", "solstice-icons.png")
            assets.iconTexture = menu.createTexture(path)
            assets.iconRetryAt = now + 5
        end
        if assets.iconTexture then
            if menu.drawTexture(assets.iconTexture, x, y, size, size, (slot - 1) / 12, 0, slot / 12, 1, 0, r, g, b) then
                return true
            end
            assets.iconTexture = nil
            assets.iconRetryAt = now + 5
        end
    end
    return menu.drawLucideIcon(slot, x, y, size, r, g, b)
end)

menu.pointInRect = LPH_NO_VIRTUALIZE(function(x, y, width, height)
    local mx, my = ImGui.GetMousePos()
    return mx >= x and mx <= x + width and my >= y and my <= y + height
end)

menu.drawDescriptionTooltip = LPH_NO_VIRTUALIZE(function(item, hovered)
