menu.getItemLayout = LPH_NO_VIRTUALIZE(function(item)
    local lineHeight = menu.getUiLineHeight()
    local itemType = item and item.type or "text"
    local compact = item and item.compact == true
    local width = tonumber(item and item._layoutWidth) or 0
    local label = menu.translate(tostring(item and item.label or ""))
    local scale = tonumber(menu.ui.fontScale) or 1.0
    local cache = item and item._solsticeLayoutCache
    if cache and cache.itemType == itemType and cache.compact == compact
        and cache.width == width and cache.label == label and cache.scale == scale and cache.lineHeight == lineHeight then
        return cache.layout
    end
    local height = compact and 29.0 or 36.0
    if itemType == "slider" or itemType == "combo" or itemType == "input" then
        height = compact and 29.0 or 38.0
    elseif itemType == "button" then
        height = compact and 29.0 or 36.0
    elseif itemType == "color" then
        height = compact and 80.0 or 88.0
    elseif itemType == "text" then
        height = compact and 25.0 or 28.0
        if width > 40 then
            local ok, _, measured = pcall(menu.localizedTextSize, label, false, width - 12)
            if ok and tonumber(measured) and measured > lineHeight then
                height = math.max(height, measured + 10)
            end
        end
    end
    local controlHeight = math.max(compact and 22.0 or 23.0, lineHeight + 4)
    local buttonHeight = math.max(compact and 24.0 or 25.0, lineHeight + 6)
    local rowStep = math.max(compact and 18.0 or 20.0, lineHeight + 3)
    if itemType == "color" then
        height = math.max(height, lineHeight + 15 + rowStep * 3)
    elseif itemType == "input" then
        height = lineHeight + controlHeight + 15
    else
        height = math.max(height, lineHeight + 8)
        if itemType == "combo" or itemType == "input" then height = math.max(height, controlHeight + 6) end
        if itemType == "button" then height = math.max(height, buttonHeight + 6) end
    end
    local layout = {
        compact = compact,
        lineHeight = lineHeight,
        descriptionHeight = 0,
        hasDescription = false,
        titleY = itemType == "input" and 4.0 or math.max(4.0, (height - lineHeight) / 2.0),
        descriptionY = 0,
        contentY = math.max(3.0, (height - 26.0) / 2.0),
        controlHeight = controlHeight,
        buttonHeight = buttonHeight,
        rowStep = rowStep,
        height = math.ceil(height)
    }
    if item then
        item._solsticeLayoutCache = {
            itemType = itemType, compact = compact, width = width,
            label = label, scale = scale, lineHeight = lineHeight, layout = layout
        }
    end
    return layout
end)

menu.getGroupHeaderHeight = LPH_NO_VIRTUALIZE(function()
    return math.max(31.0, math.ceil(menu.getUiLineHeight() + 9.0))
end)

menu.drawSearchBar = LPH_NO_VIRTUALIZE(function(x, y, w, h)
    local hovered = menu.pointInRect(x, y, w, h)
    local bgHex = hovered and "#20242e" or "#171a21"
    local br, bg, bb, ba = HexToRGBAInt(bgHex)
    local lr, lg, lb, la = HexToRGBAInt("#282d38", hovered and 1.0 or 0.76)
    ImGui.AddRectFilled(x, y, x + w, y + h, br, bg, bb, ba, 4.0)
    ImGui.AddRect(x, y, x + w, y + h, lr, lg, lb, la, 4.0, 0, 1.0)

    local frameBg = ImGuiCol and ImGuiCol.FrameBg or 7
    local frameBgHovered = ImGuiCol and ImGuiCol.FrameBgHovered or 8
    local frameBgActive = ImGuiCol and ImGuiCol.FrameBgActive or 9
    local textColor = ImGuiCol and ImGuiCol.Text or 0
    ImGui.PushStyleColor(frameBg, 0.0, 0.0, 0.0, 0.0)
    ImGui.PushStyleColor(frameBgHovered, 0.0, 0.0, 0.0, 0.0)
    ImGui.PushStyleColor(frameBgActive, 0.0, 0.0, 0.0, 0.0)
    local tr, tg, tb, ta = HexToRGBAFloat("#e8ebf2")
    ImGui.PushStyleColor(textColor, tr, tg, tb, ta)
    local framePadding = ImGuiStyleVar and ImGuiStyleVar.FramePadding or 11
    local frameRounding = ImGuiStyleVar and ImGuiStyleVar.FrameRounding or 12
    ImGui.PushStyleVar(framePadding, 0.0, 0.0)
    ImGui.PushStyleVar(frameRounding, 0.0)
    ImGui.SetCursorScreenPos(x + 10, y + math.max(2.0, (h - menu.getUiLineHeight()) / 2.0))
    ImGui.SetNextItemWidth(math.max(40, w - 20))
    if menu.focusSearchNext == true then
        if type(ImGui.SetKeyboardFocusHere) == "function" then pcall(ImGui.SetKeyboardFocusHere) end
        menu.focusSearchNext = false
    end
    local nextChanged, nextValue = false, nil
    local hint = menu.activeTab == menu.ui.quickTab and "Search all features" or "Search this page"
    if type(ImGui.InputTextWithHint) == "function" then
        nextChanged, nextValue = menu.localizedInputHint("##sovereign_search", hint, menu.searchText or "", 0)
    elseif type(ImGui.InputText) == "function" then
        nextChanged, nextValue = ImGui.InputText("##sovereign_search", menu.searchText or "", 0)
    end
    nextValue = menu.extractInputValue(nextChanged, nextValue, menu.searchText or "")
    menu.markTextInputActive()
    ImGui.PopStyleVar(2)
    ImGui.PopStyleColor(4)
    if nextValue ~= nil and nextValue ~= tostring(menu.searchText or "") then
        menu.searchText = nextValue
        if menu.quick then menu.quick.searchDirty = true end
    end
end)

DrawCustomToggle = LPH_NO_VIRTUALIZE(function(item, p_x, p_y, width)
    local layout = menu.getItemLayout(item)
    local indent = tonumber(item.indent) or 0
    ImGui.SetCursorScreenPos(p_x, p_y)
    local clicked = ImGui.InvisibleButton("##toggle_" .. tostring(item.uid or item.quickKey or item.label), width, layout.height)
    local hovered = ImGui.IsItemHovered()
    menu.handleQuickItem(item)
    if clicked and not menu.comboBlocksInput(item) then
        item.prevValue = item.value
        item.value = not item.value
        menu.recordUsage(item)
        if item.callback then menu.enqueueAction(item.label, item.callback, item.value) end
    end
    item.anim_hover = menu.animLerp(item.anim_hover or 0, hovered and 1 or 0, 16.0, g_dt)
    item.anim_on = menu.animLerp(item.anim_on or (item.value and 1 or 0), item.value and 1 or 0, 18.0, g_dt)
    if item._glowValue ~= item.value then
        if item._glowValue ~= nil then item._toggleFlash = 1.0 end
        item._glowValue = item.value
    end
    item._toggleFlash = menu.animLerp(item._toggleFlash or 0, 0, 8.0, g_dt)
    if item.anim_hover > 0.01 then
        local hr, hg, hb = HexToRGBAInt("#20242e")
        ImGui.AddRectFilled(p_x, p_y + 1, p_x + width, p_y + layout.height - 1,
            hr, hg, hb, math.floor(150 * item.anim_hover * (menu.renderAlpha or 1.0)), 4.0)
    end
    local switchW, switchH = 30.0, 17.0
    local switchX = p_x + width - switchW - 6
    local switchY = p_y + ((layout.height - switchH) / 2.0)
    local offR, offG, offB, offA = HexToRGBAInt("@toggleOff")
    local onR, onG, onB, onA = HexToRGBAInt("@toggleOn")
    onR, onG, onB = menu.animateControlColor(onR, onG, onB, "motionToggles")
    local mix = item.anim_on
    local colorMotion = menu.controlAnimation
    local breathGlow = colorMotion and colorMotion.mode == 2
    local ambientGlow = colorMotion and colorMotion.mode ~= 1 and menu.ui.motionToggles ~= 0
        and (breathGlow and (0.08 + 0.55 * colorMotion.wave) or (0.12 + 0.16 * colorMotion.wave))
            * colorMotion.amount * mix or 0
    local glow = math.max(0, math.min(1, (tonumber(menu.ui.toggleGlow) or 55) / 100))
        * math.max(item._toggleFlash, item.anim_hover * mix * 0.6, ambientGlow)
    if glow > 0.01 then
        local extent = 2.0 + 2.0 * item._toggleFlash
        ImGui.AddRectFilled(switchX - extent, switchY - extent, switchX + switchW + extent, switchY + switchH + extent,
            onR, onG, onB, math.floor(44 * glow * (menu.renderAlpha or 1.0)), switchH / 2 + extent)
        if menu.ui.performanceProfile ~= 1 then
            ImGui.AddRect(switchX - 1, switchY - 1, switchX + switchW + 1, switchY + switchH + 1,
                onR, onG, onB, math.floor(115 * glow * (menu.renderAlpha or 1.0)), switchH / 2 + 1, 0, 1.0)
        end
    end
    ImGui.AddRectFilled(switchX, switchY, switchX + switchW, switchY + switchH,
        math.floor(offR + (onR - offR) * mix), math.floor(offG + (onG - offG) * mix),
        math.floor(offB + (onB - offB) * mix), math.floor(offA + (onA - offA) * mix), switchH / 2)
    local knobX = switchX + 8.5 + ((switchW - 17.0) * mix)
    local kr, kg, kb, ka = HexToRGBAInt("#e8ebf2")
    ImGui.AddCircleFilled(knobX, switchY + switchH / 2, 6.1, kr, kg, kb, ka)
    local tr, tg, tb, ta = HexToRGBAFloat(item.value and "#e8ebf2" or "#c4cad4")
    menu.drawClippedText(item.label, p_x + indent + 7, p_y + layout.titleY,
        switchX - 8, p_y + layout.height, tr, tg, tb, ta)
    menu.drawDescriptionTooltip(item, hovered)
end)

DrawCustomSlider = LPH_NO_VIRTUALIZE(function(item, p_x, p_y, width)
    local layout = menu.getItemLayout(item)
    local indent = tonumber(item.indent) or 0
    local format = item.format or "%d"
    if item._sliderValue ~= item.value or item._sliderFormat ~= format or not item._sliderText then
        item._sliderValue, item._sliderFormat = item.value, format
        item._sliderText = string.format(format, item.value)
    end
    local valueText = item._sliderText
    local scale = tonumber(menu.ui.fontScale) or 1.0
    if item._sliderMeasuredText ~= valueText or item._sliderMeasuredScale ~= scale then
        local measured = menu.localizedTextSize(valueText)
        item._sliderMeasuredWidth = tonumber(measured) or 38
        if tonumber(measured) and measured > 0 then
            item._sliderMeasuredText, item._sliderMeasuredScale = valueText, scale
        end
    end
    local valueW = item._sliderMeasuredWidth or 38
    local right = p_x + width - 6
    local trackW = math.max(58.0, math.min(68.0, width * 0.24))
    local trackX = right - trackW
    local valueX = trackX - valueW - 9
    local trackY = p_y + (layout.height / 2.0)
    ImGui.SetCursorScreenPos(p_x, p_y)
    ImGui.InvisibleButton("##slider_" .. tostring(item.uid or item.quickKey or item.label), width, layout.height)
    local hovered = ImGui.IsItemHovered()
    local active = ImGui.IsItemActive() and not menu.comboBlocksInput(item)
    menu.handleQuickItem(item)
    if active and not item._quickActive then item._quickActive = true; menu.recordUsage(item) end
    if not active then item._quickActive = false end
    if active then
        local mouseX = ImGui.GetMousePos()
        local fraction = math.max(0, math.min(1, (mouseX - trackX) / trackW))
        local newValue = item.min + fraction * (item.max - item.min)
        local step = tonumber(item.step)
        if step and step > 0 then
            newValue = item.min + math.floor(((newValue - item.min) / step) + 0.5) * step
        elseif tostring(item.format or ""):find("%%d") then
            newValue = math.floor(newValue + 0.5)
        end
        newValue = math.max(item.min, math.min(item.max, newValue))
        if newValue ~= item.value then
            item.prevValue, item.value = item.value, newValue
            if item.callback then
                if item.applyOnRelease then item.callbackPending = true
                else menu.enqueueAction(item.label, item.callback, item.value) end
            end
        end
    elseif item.applyOnRelease and item.callbackPending then
        item.callbackPending = false
        menu.recordUsage(item)
        if item.callback then menu.enqueueAction(item.label, item.callback, item.value) end
    end
    if item._sliderValue ~= item.value then
        item._sliderValue, item._sliderText = item.value, string.format(format, item.value)
        valueText = item._sliderText
        local measured = menu.localizedTextSize(valueText)
        valueW = tonumber(measured) or 38
        item._sliderMeasuredWidth = valueW
        item._sliderMeasuredText, item._sliderMeasuredScale = valueText, scale
        valueX = trackX - valueW - 9
    end
    item.anim_hover = menu.animLerp(item.anim_hover or 0, hovered and 1 or 0, 16.0, g_dt)
    item.anim_value = menu.animLerp(tonumber(item.anim_value) or item.value, item.value, 18.0, g_dt)
    if item.anim_hover > 0.01 then
        local hr, hg, hb = HexToRGBAInt("#20242e")
        ImGui.AddRectFilled(p_x, p_y + 1, p_x + width, p_y + layout.height - 1,
            hr, hg, hb, math.floor(120 * item.anim_hover * (menu.renderAlpha or 1.0)), 4.0)
    end
    local lr, lg, lb, la = HexToRGBAInt("#282d38")
    ImGui.AddRectFilled(trackX, trackY - 1.5, trackX + trackW, trackY + 1.5, lr, lg, lb, la, 1.5)
    local fraction = (item.anim_value - item.min) / math.max(0.000001, item.max - item.min)
    fraction = math.max(0, math.min(1, fraction))
    local ar, ag, ab, aa = HexToRGBAInt("#9d9aff")
    ar, ag, ab = menu.animateControlColor(ar, ag, ab, "motionSliders")
    ImGui.AddRectFilled(trackX, trackY - 1.5, trackX + trackW * fraction, trackY + 1.5, ar, ag, ab, aa, 1.5)
    ImGui.AddCircleFilled(trackX + trackW * fraction, trackY, 4.3, ar, ag, ab, aa)
    local tr, tg, tb, ta = HexToRGBAFloat("#e8ebf2")
    local mr, mg, mb, ma = HexToRGBAFloat("#929aaa")
    menu.drawClippedText(item.label, p_x + indent + 7, p_y + layout.titleY,
        valueX - 8, p_y + layout.height, tr, tg, tb, ta)
    menu.drawClippedText(valueText, valueX, p_y + layout.titleY,
        trackX - 4, p_y + layout.height, mr, mg, mb, ma)
    menu.drawDescriptionTooltip(item, hovered)
end)

DrawCustomCombo = LPH_NO_VIRTUALIZE(function(item, p_x, p_y, width)
    local layout = menu.getItemLayout(item)
    local indent = tonumber(item.indent) or 0
    item.anim_hover = item.anim_hover or 0
    item.anim_open = item.anim_open or 0
    item.is_open = item.is_open or false
    item.option_sel_anim = item.option_sel_anim or {}
    item.option_hover_anim = item.option_hover_anim or {}
    local boxW = math.max(96.0, math.min(112.0, width * 0.44))
    local boxH = layout.controlHeight
    local boxX = p_x + width - boxW - 6
    local boxY = p_y + ((layout.height - boxH) / 2.0)
    local uid = tostring(item.uid or item.label)
    ImGui.SetCursorScreenPos(boxX, boxY)
    local clicked = ImGui.InvisibleButton("##combo_" .. uid, boxW, boxH)
    local hovered = ImGui.IsItemHovered()
    menu.handleQuickItem(item)
    local justOpened = false
    if clicked and not menu.comboBlocksInput(item) then
        item.is_open = not item.is_open
        justOpened = item.is_open
