        swatchX - 8, p_y + headingH, tr, tg, tb, ta)
    ImGui.AddRectFilled(swatchX, swatchY, swatchX + swatch, swatchY + swatch,
        value.r, value.g, value.b, math.floor(255 * (menu.renderAlpha or 1.0)), 3.0)
    local lr, lg, lb, la = HexToRGBAInt("#282d38")
    ImGui.AddRect(swatchX, swatchY, swatchX + swatch, swatchY + swatch, lr, lg, lb, la, 3.0, 0, 1.0)
