        local active = ImGui.IsItemActive() and not menu.comboBlocksInput(item)
        anyHovered = anyHovered or ImGui.IsItemHovered()
        if index == 1 then menu.handleQuickItem(item) end
        if active then
            local mouseX = ImGui.GetMousePos()
            local fraction = math.max(0, math.min(1, (mouseX - trackX) / trackW))
            local nextValue = math.floor(fraction * 255 + 0.5)
            if nextValue ~= value[channel[2]] then
                value[channel[2]] = nextValue
                if item.callback then menu.enqueueAction(item.label, item.callback, value.r, value.g, value.b, value.a) end
            end
        end
        menu.drawClippedText(channel[1], p_x + indent + 7, rowY, trackX - 2, rowY + layout.rowStep - 1, mr, mg, mb, ma)
        local trackY = rowY + layout.lineHeight / 2
        ImGui.AddRectFilled(trackX, trackY - 1.5, trackX + trackW, trackY + 1.5, lr, lg, lb, la, 1.5)
        local fill = trackW * (value[channel[2]] / 255)
        ImGui.AddRectFilled(trackX, trackY - 1.5, trackX + fill, trackY + 1.5,
            channel[3], channel[4], channel[5], math.floor(255 * (menu.renderAlpha or 1.0)), 1.5)
        ImGui.AddCircleFilled(trackX + fill, trackY, 3.8, channel[3], channel[4], channel[5], math.floor(255 * (menu.renderAlpha or 1.0)))
        menu.drawClippedText(tostring(value[channel[2]]), p_x + width - valueW - 5, rowY,
            p_x + width, rowY + layout.rowStep - 1, tr, tg, tb, ta)
    end
    menu.drawDescriptionTooltip(item, anyHovered or menu.pointInRect(p_x, p_y, width, 27))
end)

menu.drawCustomButton = LPH_NO_VIRTUALIZE(function(item, p_x, p_y, width)
    local layout = menu.getItemLayout(item)
    local indent = tonumber(item.indent) or 0
    local buttonY = p_y + math.max(0.0, tonumber(item._rowButtonOffset) or 0.0) + 3
    local buttonH = layout.buttonHeight
    local buttonX = p_x + indent + 6
    local buttonW = math.max(40.0, width - indent - 12)
    ImGui.SetCursorScreenPos(buttonX, buttonY)
    local clicked = ImGui.InvisibleButton("##btn_" .. tostring(item.uid or item.label), buttonW, buttonH)
    local hovered = ImGui.IsItemHovered()
    local active = ImGui.IsItemActive() and not menu.comboBlocksInput(item)
    menu.handleQuickItem(item)
    if clicked and not menu.comboBlocksInput(item) then
        menu.recordUsage(item)
        if item.callback then menu.enqueueAction(item.label, item.callback) end
    end
    item.anim_hover = menu.animLerp(item.anim_hover or 0, hovered and 1 or 0, 16.0, g_dt)
    local br, bg, bb, ba = HexToRGBAInt(active and "#9d9aff" or "#171a21")
    local hr, hg, hb = HexToRGBAInt("#20242e")
    local lr, lg, lb, la = HexToRGBAInt("#282d38")
    local ar, ag, ab = HexToRGBAInt("#9d9aff")
    local mix = item.anim_hover
    if not active then br, bg, bb = math.floor(br + (hr - br) * mix), math.floor(bg + (hg - bg) * mix), math.floor(bb + (hb - bb) * mix) end
    ar, ag, ab = menu.animateControlColor(ar, ag, ab, "motionButtons")
    local colorMotion = menu.controlAnimation
    local motion = colorMotion and colorMotion.mode ~= 1 and menu.ui.motionButtons ~= 0
        and colorMotion.amount * math.max(0, math.min(100, menu.ui.buttonMotionStrength or 65)) / 100 or 0
    local breathing = colorMotion and colorMotion.mode == 2
    if active then br, bg, bb = ar, ag, ab
    else
        local tint = motion * ((breathing and (0.10 + 0.32 * colorMotion.wave) or 0.22) + mix * 0.20)
        br, bg, bb = math.floor(br + (ar - br) * tint), math.floor(bg + (ag - bg) * tint), math.floor(bb + (ab - bb) * tint)
    end
    local edge = math.max(mix * 0.65, motion * (breathing and (0.30 + 0.65 * colorMotion.wave) or 0.85))
    lr, lg, lb = math.floor(lr + (ar - lr) * edge), math.floor(lg + (ag - lg) * edge), math.floor(lb + (ab - lb) * edge)
    ImGui.AddRectFilled(buttonX, buttonY, buttonX + buttonW, buttonY + buttonH, br, bg, bb, ba, 4.0)
    ImGui.AddRect(buttonX, buttonY, buttonX + buttonW, buttonY + buttonH, lr, lg, lb, la, 4.0, 0, 1.0)
    local textHex = active and (br * 0.2126 + bg * 0.7152 + bb * 0.0722 > 145) and "#101217" or "#e8ebf2"
    local tr, tg, tb, ta = HexToRGBAFloat(textHex)
    local cacheScale = tonumber(menu.ui.fontScale) or 1.0
    if item._solsticeButtonLanguage ~= menu.ui.language or item._solsticeButtonLabel ~= item.label or item._solsticeButtonScale ~= cacheScale then
        item._solsticeButtonTextW, item._solsticeButtonTextH = menu.localizedTextSize(item.label)
        item._solsticeButtonLanguage = menu.ui.language
        item._solsticeButtonLabel, item._solsticeButtonScale = item.label, cacheScale
    end
    local textW, textH = item._solsticeButtonTextW, item._solsticeButtonTextH
    menu.drawClippedText(item.label, buttonX + math.max(8, (buttonW - (tonumber(textW) or 0)) / 2),
        buttonY + math.max(2, (buttonH - (tonumber(textH) or layout.lineHeight)) / 2),
        buttonX + buttonW - 8, buttonY + buttonH, tr, tg, tb, ta)
    menu.drawDescriptionTooltip(item, hovered)
end)

