menu.getItemHeight = LPH_NO_VIRTUALIZE(function(item)
    return menu.getItemLayout(item).height
end)

menu.getGroupHeight = LPH_NO_VIRTUALIZE(function(items, itemColumns, itemGap, headerHeight)
    local height = headerHeight or menu.getGroupHeaderHeight()
    for rowStart = 1, #items, itemColumns do
        local rowHeight = 0
        for slot = 0, itemColumns - 1 do
            local item = items[rowStart + slot]
            if item then
                local itemHeight = item._renderedHeight or menu.getItemHeight(item)
                if item.type == "button" and (tonumber(item._rowButtonOffset) or 0) > 0 then
                    itemHeight = math.max(
                        itemHeight,
                        (tonumber(item._rowButtonOffset) or 0) + menu.getItemLayout(item).buttonHeight + 2
                    )
                end
                rowHeight = math.max(rowHeight, itemHeight)
            end
        end
        height = height + rowHeight + itemGap
    end
    return height
end)

menu.getItemOffsetInGroup = LPH_NO_VIRTUALIZE(function(items, itemUid, itemColumns, itemGap, headerHeight)
    local offset = headerHeight or menu.getGroupHeaderHeight()
    if itemUid == nil then return 0 end
    for rowStart = 1, #items, itemColumns do
        local rowHeight = 0
        local rowMatches = false
        for slot = 0, itemColumns - 1 do
            local item = items[rowStart + slot]
            if item then
                if item.uid == itemUid then rowMatches = true end
                local itemHeight = item._renderedHeight or menu.getItemHeight(item)
                if item.type == "button" and (tonumber(item._rowButtonOffset) or 0) > 0 then
                    itemHeight = math.max(
                        itemHeight,
                        (tonumber(item._rowButtonOffset) or 0) + menu.getItemLayout(item).buttonHeight + 2
                    )
                end
                rowHeight = math.max(rowHeight, itemHeight)
            end
        end
        if rowMatches then return offset end
        offset = offset + rowHeight + itemGap
    end
    return 0
end)

