menu.drawSubtabHeader = LPH_NO_VIRTUALIZE(function(currentTab, featureX, headerY, featureWidth)
    if not currentTab then return end
    local subtabCount = #currentTab.subtabs
    local searchWidth = subtabCount >= 6 and math.max(90, math.min(124, featureWidth * 0.19)) or 178
    menu.drawSearchBar(featureX + 8, headerY, searchWidth, 32)
    if subtabCount == 0 then return end

    local gap = currentTab.compactSubtabs == true and 4 or math.max(4, menu.ui.subtabGap or 12)
    local left = featureX + 8 + searchWidth + 8
    local right = featureX + featureWidth - 8
    local startIndex = math.floor(math.max(1, math.min(subtabCount, tonumber(currentTab.subtabPageStart) or 1)))
    currentTab.subtabPageStart = startIndex
    currentTab.subtabPageHistory = currentTab.subtabPageHistory or {}

    if startIndex > 1 then
        ImGui.SetCursorScreenPos(left, headerY)
        if ImGui.InvisibleButton("##subtab_prev_" .. tostring(currentTab.id), 28, 32) and not menu.comboModalActive then
            currentTab.subtabPageStart = table.remove(currentTab.subtabPageHistory) or 1
        end
        local pr, pg, pb, pa = HexToRGBAFloat("#b0b4ff")
        ImGui.SetCursorScreenPos(left + 9, headerY + 7)
        menu.localizedTextColored(pr, pg, pb, pa, "<")
        left = left + 32
    end

    local x = left
    local lastVisible = startIndex - 1
    for index = startIndex, subtabCount do
        local subtab = currentTab.subtabs[index]
        local textWidth = menu.localizedTextSize(subtab.name) or (string.len(subtab.name) * 7)
        local buttonWidth = textWidth + (currentTab.compactSubtabs == true and 14 or 22)
        local reserveNext = index < subtabCount and 32 or 0
        if x + buttonWidth + reserveNext > right and index > startIndex then break end
        buttonWidth = math.min(buttonWidth, math.max(34, right - x - reserveNext))
        ImGui.SetCursorScreenPos(x, headerY)
        local clicked = ImGui.InvisibleButton("##subtab_" .. tostring(currentTab.id) .. "_" .. tostring(subtab.id), buttonWidth, 32)
        if clicked and not menu.comboModalActive then
            menu.activeSubtab = subtab.id
            menu.searchText = ""
        end
        local selected = menu.activeSubtab == subtab.id
        local hovered = ImGui.IsItemHovered()
        if selected then
            local br, bg, bb, ba = HexToRGBAInt("#212128")
            ImGui.AddRectFilled(x, headerY, x + buttonWidth, headerY + 32, br, bg, bb, ba, 9.1)
        end
        local tr, tg, tb, ta = HexToRGBAFloat((selected or hovered) and "#ffffff" or "#6e6e81")
        local _, textHeight = menu.localizedTextSize(subtab.name)
        ImGui.PushClipRect(x + 6, headerY, x + buttonWidth - 4, headerY + 32, true)
        ImGui.SetCursorScreenPos(x + 8, headerY + ((32 - (tonumber(textHeight) or 14)) / 2))
        menu.localizedTextColored(tr, tg, tb, ta, subtab.name)
        ImGui.PopClipRect()
        lastVisible = index
        x = x + buttonWidth + gap
    end

    if lastVisible < subtabCount then
        local nextX = right - 28
        ImGui.SetCursorScreenPos(nextX, headerY)
        if ImGui.InvisibleButton("##subtab_next_" .. tostring(currentTab.id), 28, 32) and not menu.comboModalActive then
            currentTab.subtabPageHistory[#currentTab.subtabPageHistory + 1] = startIndex
            currentTab.subtabPageStart = lastVisible + 1
        end
        local nr, ng, nb, na = HexToRGBAFloat("#b0b4ff")
        ImGui.SetCursorScreenPos(nextX + 10, headerY + 7)
        menu.localizedTextColored(nr, ng, nb, na, ">")
    end
end)

local DrawUI = LPH_NO_VIRTUALIZE(function()
    comboOverlayQueue = {}
    menu.refreshComboModalState()
    local current_time = ImGui.GetTime()
    local openAnimation = menu.updateOpenAnimation(current_time)
    if not menu.open and openAnimation <= 0.001 then
        menu.textInputActive = false
        menu.captureMouse(false)
        menu.colorBrightness = 1.0
        if #notifyQueue > 0 then
            menu.drawNotificationOverlay()
        end
        return
    end
    menu.textInputActive = false
    menu.captureMouse(menu.interactive or openAnimation > 0.001)
    local menuBrightness = math.max(0.25, math.min(1.0, (tonumber(menu.ui.brightness) or 100) / 100.0))
    menu.colorBrightness = menuBrightness
    menu.renderAlpha = math.max(0.001, math.min(1.0, openAnimation))
    menu.styleAlpha = math.max(0.001, math.min(1.0, openAnimation * menuBrightness))
    local main_x, main_y, main_w, main_h = nil, nil, nil, nil
    if g_last_time == 0 then g_last_time = current_time end
    g_dt = current_time - g_last_time
    if g_dt > 0.1 then g_dt = 0.016 end
    g_last_time = current_time

    -- Remove all default ImGui window styling
    ImGui.PushStyleVar(ImGuiStyleVar.WindowPadding, 0.0, 0.0)
    ImGui.PushStyleVar(ImGuiStyleVar.WindowBorderSize, 0.0)
    ImGui.PushStyleVar(ImGuiStyleVar.WindowRounding, 14.0)
    ImGui.PushStyleVar(ImGuiStyleVar.Alpha, menu.styleAlpha or menu.renderAlpha)
    
    -- NoTitleBar (1) | NoResize (2) | NoCollapse (32) | NoBackground (128) | NoScrollbar (8) | NoScrollWithMouse (16) = 187
    local window_flags = 1 | 2 | 8 | 16 | 32 | 128
    if not menu.interactive then
        window_flags = window_flags | ImGuiWindowFlags.NoInputs
    end
    
    if menu.ui.sizeDirty or not menu.ui.sizeApplied then
        ImGui.SetNextWindowSize(menu.ui.width, menu.ui.height, ImGuiCond.Always)
        menu.ui.sizeDirty = false
        menu.ui.sizeApplied = true
    end
    
    if ImGui.Begin("Z_Main", true, window_flags) then
        ImGui.SetWindowFontScale(menu.ui.fontScale or 1.0)
        local p_x, p_y = ImGui.GetWindowPos()
        local win_w, win_h = ImGui.GetWindowSize()
        main_x, main_y, main_w, main_h = p_x, p_y, win_w, win_h

        local sidebar_w = math.max(150.0, math.min(menu.ui.sidebarWidth or 190.0, win_w * 0.32))
        
        local bg_r, bg_g, bg_b, bg_a = HexToRGBAInt("#19191c")
        ImGui.AddRectFilled(p_x, p_y, p_x + win_w, p_y + win_h, bg_r, bg_g, bg_b, bg_a, 14.0)
        if menu.ui.rgbBorder ~= 0 then
            menu.drawAnimatedRgbBorder(p_x, p_y, win_w, win_h, current_time)
        end
        
        local sidebar_r, sidebar_g, sidebar_b, sidebar_a = HexToRGBAInt("#1c1c21")
        ImGui.AddRectFilled(p_x + 10, p_y + 10, p_x + 10 + sidebar_w, p_y + win_h - 10, sidebar_r, sidebar_g, sidebar_b, sidebar_a, 14.0)
        
        -- Header in Sidebar
        ImGui.SetCursorScreenPos(p_x + 20, p_y + 25)
        local tr, tg, tb, ta = HexToRGBAFloat("#ffffff")
        menu.localizedTextColored(tr, tg, tb, ta, "SovereignLua")
        
        -- Sidebar Tabs
        local sidebar_start_y = p_y + 60
        local tab_x = p_x + 20
        local sidebar_tab_w = sidebar_w - 12.0
        local sidebar_tab_h = 40.0
        local tab_count = math.max(1, #menu.tabs)
        local max_sidebar_gap = math.max(4.0, (win_h - 90.0 - (tab_count * sidebar_tab_h)) / math.max(1, tab_count - 1))
        local sidebar_tab_gap = math.min(menu.ui.sidebarGap or 10.0, max_sidebar_gap)
        local sidebar_tab_step = sidebar_tab_h + sidebar_tab_gap
        local indicator_target_y = sidebar_start_y + ((menu.activeTab - 1) * sidebar_tab_step)
        menu.tabIndicatorY = menu.tabIndicatorY or indicator_target_y
        menu.tabIndicatorY = menu.animLerp(menu.tabIndicatorY, indicator_target_y, 14.0, g_dt)

        for i, tab in ipairs(menu.tabs) do
            local tab_y = sidebar_start_y + ((i - 1) * sidebar_tab_step)
            ImGui.SetCursorScreenPos(tab_x, tab_y)
            
            local isSelected = (menu.activeTab == tab.id)
            local clicked = ImGui.InvisibleButton("##tab_" .. tab.name, sidebar_tab_w, sidebar_tab_h)
            if clicked and not menu.comboModalActive then
                menu.activeTab = tab.id
                if #tab.subtabs > 0 then
                    menu.activeSubtab = tab.subtabs[1].id
                end
                menu.searchText = ""
            end
            
            local isHovered = ImGui.IsItemHovered()

            -- Tab animations
            tab.anim_sel = tab.anim_sel or 0
            tab.anim_hover = tab.anim_hover or 0
            local sel_target = isSelected and 1 or 0
            local hov_target = isHovered and 1 or 0
            tab.anim_sel = menu.animLerp(tab.anim_sel, sel_target, 14.0, g_dt)
            tab.anim_hover = menu.animLerp(tab.anim_hover, hov_target, 16.0, g_dt)

            if tab.anim_sel > 0.01 then
                local sel_r, sel_g, sel_b, _ = HexToRGBAInt("#212128")
                local sel_a = math.floor(255 * tab.anim_sel * (menu.renderAlpha or 1.0))
                ImGui.AddRectFilled(tab_x, tab_y, tab_x + sidebar_tab_w, tab_y + sidebar_tab_h, sel_r, sel_g, sel_b, sel_a, 9.1)
            end

            local text_shift_x = 5.0 * tab.anim_sel
            local tabIcon = menu.tabIcons and menu.tabIcons[i] or "•"
            local tabLabel = tabIcon .. "  " .. tostring(tab.name)
            local _, tab_text_h = menu.localizedTextSize(tabLabel)
            if not tab_text_h then tab_text_h = 14 end
            ImGui.SetWindowFontScale((menu.ui.fontScale or 1.0) * 1.08)
            ImGui.SetCursorScreenPos(tab_x + 17 + text_shift_x, tab_y + ((sidebar_tab_h - tab_text_h) / 2) - 1)
            local off_r, off_g, off_b, off_a = HexToRGBAFloat("#6e6e81")
            local on_r, on_g, on_b, on_a = HexToRGBAFloat("#ffffff")
            local mix = math.max(tab.anim_sel, tab.anim_hover * 0.85)
            local t_r = off_r + (on_r - off_r) * mix
            local t_g = off_g + (on_g - off_g) * mix
            local t_b = off_b + (on_b - off_b) * mix
            local t_a = off_a + (on_a - off_a) * mix
            menu.localizedTextColored(t_r, t_g, t_b, t_a, tabLabel)
            ImGui.SetWindowFontScale(menu.ui.fontScale or 1.0)
        end

        local ind_r, ind_g, ind_b, ind_a = HexToRGBAInt("#b0b4ff")
        ImGui.AddRectFilled(tab_x + 2, menu.tabIndicatorY + 8, tab_x + 5, menu.tabIndicatorY + sidebar_tab_h - 8, ind_r, ind_g, ind_b, ind_a, 1.0)
        
        -- Main Content Area
        local feature_x = p_x + 10 + sidebar_w + 10
        local feature_width = win_w - sidebar_w - 30
        local feature_header_height = 40
        
        local hdr_r, hdr_g, hdr_b, hdr_a = HexToRGBAInt("#1c1c21")
        ImGui.AddRectFilled(feature_x, p_y + 10, feature_x + feature_width, p_y + 10 + feature_header_height, hdr_r, hdr_g, hdr_b, hdr_a, 14.0)
        
        local currentTab = menu.tabs[menu.activeTab]
        if currentTab then
            menu.drawSubtabHeader(currentTab, feature_x, p_y + 14, feature_width)
            if #currentTab.subtabs > 0 then
                -- Groups with Scrollbar
                local currentSubtab = globalSubtabs[menu.activeSubtab]
                if currentSubtab then
                    if currentSubtab.id == menu.ui.quickSubtab then
                        menu.refreshGlobalSearchGroup(menu.getSearchQuery())
                    end
                    local has_player_list = menu.isPlayerListBound(menu.activeTab)
                    local player_list_w = has_player_list and 220 or 0
                    local group_start_x = feature_x + (has_player_list and (player_list_w + 10) or 0)
                    local taskLayout = currentSubtab.compact == true
                    -- Task pages use a denser content start so the first group stays visible.
                    local groupStartGap = taskLayout and 0 or 14
                    local group_start_y = p_y + 10 + feature_header_height + groupStartGap
                    local content_h = win_h - (10 + feature_header_height + groupStartGap) - 10
                    local group_area_w = feature_width - (has_player_list and (player_list_w + 10) or 0)

                    if has_player_list then
                        menu.drawPlayerListPanel(feature_x, group_start_y, player_list_w, content_h)
                    end

                    ImGui.PushStyleColor(14, 0.0, 0.0, 0.0, 0.0)
                    local sb_r, sb_g, sb_b, sb_a = HexToRGBAFloat("#212128", 1.0)
                    ImGui.PushStyleColor(15, sb_r, sb_g, sb_b, sb_a)
                    local sbh_r, sbh_g, sbh_b, sbh_a = HexToRGBAFloat("#262532", 1.0)
                    ImGui.PushStyleColor(16, sbh_r, sbh_g, sbh_b, sbh_a)
                    local sba_r, sba_g, sba_b, sba_a = HexToRGBAFloat("#b0b4ff", 1.0)
                    ImGui.PushStyleColor(17, sba_r, sba_g, sba_b, sba_a)
                    
                    ImGui.PushStyleVar(18, 6.0)
                    ImGui.PushStyleVar(19, 3.0)
                    
                    ImGui.PushStyleColor(3, 0.0, 0.0, 0.0, 0.0)
                    ImGui.SetCursorScreenPos(group_start_x, group_start_y)
                    if ImGui.BeginChild("ContentArea", group_area_w, content_h, false, 0) then
                        ImGui.SetWindowFontScale(menu.ui.fontScale or 1.0)
                        local child_p_x, child_p_y = ImGui.GetWindowPos()
                        local scroll_y = ImGui.GetScrollY()
                        local viewport_top = child_p_y - 96
                        local viewport_bottom = child_p_y + content_h + 96
                        
                        local group_gap = taskLayout
                            and math.min(menu.ui.groupGap or 14, 2)
                            or (menu.ui.groupGap or 14)
                        local column_count = math.max(1, math.min(2, math.floor((menu.ui.columns or 2) + 0.5)))
                        local adjusted_feature_width = group_area_w - 14
                        local group_width = (adjusted_feature_width - (group_gap * (column_count - 1))) / column_count
                        local col_y = {}
                        for column = 1, column_count do
                            col_y[column] = 0
                        end
                        local search_query = menu.getSearchQuery()

                        for _, group in ipairs(currentSubtab.groups) do
                            local visibleItems = menu.getVisibleGroupItems(group, search_query)
                            if not group.hidden and #visibleItems > 0 then
                                local compactGroup = group.compact == true
                                local item_gap = group.itemGap
                                if item_gap == nil then
                                    item_gap = compactGroup and math.min(menu.ui.itemGap or 4, 1) or (menu.ui.itemGap or 4)
                                end
                                if compactGroup then
                                    for _, item in ipairs(visibleItems) do
                                        item.compact = true
                                    end
                                end
                                local splitLongGroup = group.noSplit ~= true
                                    and menu.ui.splitLongGroups ~= 0
                                    and column_count > 1
                                    and #visibleItems >= 5
                                local itemColumns = splitLongGroup and 2 or 1
                                local currentGroupWidth = splitLongGroup and adjusted_feature_width or group_width
                                local horizontalPadding = math.max(14, currentGroupWidth * 0.05)
                                local innerGap = itemColumns > 1 and math.min(16, group_gap) or 0
                                local item_width = (currentGroupWidth - (horizontalPadding * 2) - (innerGap * (itemColumns - 1))) / itemColumns
                                local groupHeaderHeight = compactGroup
                                    and math.max(24.0, math.ceil(menu.getUiLineHeight() + 6.0))
                                    or menu.getGroupHeaderHeight()
                                -- Resolve mixed button/control rows before sizing the group. This keeps
                                -- the following row and the group box aligned with the actual draw position.
                                for prepRow = 1, #visibleItems, itemColumns do
                                    for prepSlot = 0, itemColumns - 1 do
                                        local prepItem = visibleItems[prepRow + prepSlot]
                                        if prepItem then
                                            prepItem._layoutWidth = item_width
                                            prepItem._rowButtonOffset = 0
                                            if compactGroup and itemColumns > 1 and prepItem.type == "button" then
                                                local peer = visibleItems[prepRow + (prepSlot == 0 and 1 or 0)]
                                                if peer and peer.type ~= "button" then
                                                    local peerLayout = menu.getItemLayout(peer)
                                                    prepItem._rowButtonOffset = math.max(0.0, math.min(
                                                        peerLayout.contentY,
                                                        peerLayout.height - menu.getItemLayout(prepItem).buttonHeight
                                                    ))
                                                end
                                            end
                                            local prepLayout = menu.getItemLayout(prepItem)
                                            local prepHeight = prepLayout.height
                                            if prepItem.type == "button" and (tonumber(prepItem._rowButtonOffset) or 0) > 0 then
                                                prepHeight = math.max(
                                                    prepHeight,
                                                    (tonumber(prepItem._rowButtonOffset) or 0) + prepLayout.buttonHeight + 6
                                                )
                                            end
                                            prepItem._renderedHeight = prepHeight
                                        end
                                    end
                                end
                                local box_height = menu.getGroupHeight(visibleItems, itemColumns, item_gap, groupHeaderHeight)

                                local col = 1
                                local groupTop = col_y[1]
                                if splitLongGroup then
                                    for column = 2, column_count do
                                        groupTop = math.max(groupTop, col_y[column])
                                    end
                                else
                                    for column = 2, column_count do
                                        if col_y[column] < col_y[col] then
                                            col = column
                                        end
                                    end
                                    groupTop = col_y[col]
                                end

                                if menu.pendingRevealGroupID == group.id then
                                    local itemOffset = menu.getItemOffsetInGroup(
                                        visibleItems,
                                        menu.pendingRevealItemUid,
                                        itemColumns,
                                        item_gap,
                                        groupHeaderHeight
                                    )
                                    local targetScrollY = math.max(0, groupTop + itemOffset - 8)
                                    if menu.pendingRevealApplied == true then
                                        menu.pendingRevealGroupID = nil
                                        menu.pendingRevealItemUid = nil
                                        menu.pendingRevealApplied = nil
                                    elseif ImGui.SetScrollY then
                                        pcall(ImGui.SetScrollY, targetScrollY)
                                        menu.pendingRevealApplied = true
                                    end
                                end

                                local g_x = splitLongGroup
                                    and child_p_x
                                    or child_p_x + ((col - 1) * (group_width + group_gap))
                                local g_y = child_p_y + groupTop - scroll_y
                                if g_y + box_height >= viewport_top and g_y <= viewport_bottom then
                                    local gb_r, gb_g, gb_b, gb_a = HexToRGBAInt("#1c1c21")
                                    local shadow_r, shadow_g, shadow_b, shadow_a = HexToRGBAInt("#000000", 0.16)
                                    ImGui.AddRectFilled(g_x + 2, g_y + 3, g_x + currentGroupWidth + 2, g_y + box_height + 3,
                                        shadow_r, shadow_g, shadow_b, shadow_a, 14.0)
                                    ImGui.AddRectFilled(g_x, g_y, g_x + currentGroupWidth, g_y + box_height, gb_r, gb_g, gb_b, gb_a, 14.0)
                                    local accent_r, accent_g, accent_b, accent_a = HexToRGBAInt("#b0b4ff", 0.70)
                                    ImGui.AddLine(g_x + 14, g_y + 1, g_x + math.min(currentGroupWidth - 14, 118), g_y + 1,
                                        accent_r, accent_g, accent_b, accent_a, 2.0)

                                    if g_y + groupHeaderHeight >= viewport_top and g_y <= viewport_bottom then
                                        local groupTitleY = g_y + ((groupHeaderHeight - menu.getUiLineHeight()) / 2.0)
                                        ImGui.SetCursorScreenPos(g_x + 15, groupTitleY)
                                        local tr, tg, tb, ta = HexToRGBAFloat("#d8d8dd")
                                        menu.localizedTextColored(tr, tg, tb, ta, group.name)
                                    end

                                    local row_y = g_y + groupHeaderHeight
                                    for rowStart = 1, #visibleItems, itemColumns do
                                        local rowHeight = 0
                                        for slot = 0, itemColumns - 1 do
                                            local item = visibleItems[rowStart + slot]
                                            if item then
                                                item._rowButtonOffset = 0
                                                if compactGroup and itemColumns > 1 and item.type == "button" then
                                                    local peer = visibleItems[rowStart + (slot == 0 and 1 or 0)]
                                                    if peer and peer.type ~= "button" then
                                                        local peerLayout = menu.getItemLayout(peer)
                                                        item._rowButtonOffset = math.max(0.0, math.min(
                                                            peerLayout.contentY,
                                                            peerLayout.height - menu.getItemLayout(item).buttonHeight
                                                        ))
                                                    end
                                                end
                                                local item_height = menu.getItemHeight(item)
                                                local rendered_height = item_height
                                                local item_x = g_x + horizontalPadding + (slot * (item_width + innerGap))
                                                if row_y + item_height >= viewport_top and row_y <= viewport_bottom then
                                                    SyncBoundItemValue(item)
                                                    if item.type == "toggle" then
                                                        DrawCustomToggle(item, item_x, row_y, item_width)
                                                    elseif item.type == "slider" then
                                                        DrawCustomSlider(item, item_x, row_y, item_width)
                                                    elseif item.type == "color" then
                                                        menu.drawColor(item, item_x, row_y, item_width)
                                                    elseif item.type == "combo" then
                                                        DrawCustomCombo(item, item_x, row_y, item_width)
                                                    elseif item.type == "input" then
                                                        DrawCustomInputText(item, item_x, row_y, item_width)
                                                    elseif item.type == "button" then
                                                        menu.drawCustomButton(item, item_x, row_y, item_width)
                                                    elseif item.type == "text" then
                                                        DrawCustomText(item, item_x, row_y)
                                                    end
                                                end
                                                if item.type == "button" and (tonumber(item._rowButtonOffset) or 0) > 0 then
                                                    rendered_height = math.max(
                                                        rendered_height,
                                                        (tonumber(item._rowButtonOffset) or 0) + menu.getItemLayout(item).buttonHeight + 6
                                                    )
                                                end
                                                item._renderedHeight = rendered_height
                                                rowHeight = math.max(rowHeight, rendered_height)
                                            end
                                        end
                                        row_y = row_y + rowHeight + item_gap
                                    end
                                end

                                local nextGroupTop = groupTop + box_height + group_gap
                                if splitLongGroup then
                                    for column = 1, column_count do
                                        col_y[column] = nextGroupTop
                                    end
                                else
                                    col_y[col] = nextGroupTop
                                end
                            end
                        end
                        
                        local max_y = 0
                        for column = 1, column_count do
                            max_y = math.max(max_y, col_y[column])
                        end
                        ImGui.SetCursorPos(0, max_y)
                        ImGui.Dummy(1, 1)
                    end

                    ImGui.SetWindowFontScale(1.0)
                    ImGui.EndChild()
                    ImGui.PopStyleColor(5)
                    ImGui.PopStyleVar(2)
                end
            end
        end
    end
    ImGui.SetWindowFontScale(1.0)
    ImGui.End()

    DrawComboOverlays()

    if main_x ~= nil and menu.isPlayerListBound(menu.activeTab) and menu.ui.showPlayerInfo ~= 0 then
        menu.drawSelectedPlayerInfoWindow(main_x + main_w + 10, main_y + 10)
    end

    menu.renderAlpha = 1.0
    menu.colorBrightness = 1.0
    ImGui.PopStyleVar(4)
    menu.captureKeyboard(menu.textInputActive)
    menu.drawNotificationOverlay()
end)

menu.tabIcons = {"#", "+", "@", "O", "*", ">", "=", "^", "~"}

menu.getLocalProfileName = LPH_NO_VIRTUALIZE(function()
    local now = os.clock()
    local cache = menu._localProfileCache
    if cache and now - (cache.at or 0) < 1.0 then return cache.name end
    local name = "Local Player"
    if GTA and type(GTA.GetLocalPlayerId) == "function" and Players and type(Players.GetName) == "function" then
        local idOk, playerId = pcall(GTA.GetLocalPlayerId)
        if idOk and tonumber(playerId) and playerId >= 0 then
            local nameOk, resolved = pcall(Players.GetName, playerId)
            if nameOk and type(resolved) == "string" and resolved ~= "" then name = resolved end
        end
    end
    menu._localProfileCache = {at = now, name = name}
    return name
end)

menu.drawSolsticeSubtabs = LPH_NO_VIRTUALIZE(function(currentTab, x, y, width, height)
    local count = #(currentTab.subtabs or {})
    if count <= 1 or width < 42 then return end
    local gap = math.max(3, math.min(8, tonumber(menu.ui.subtabGap) or 4))
    local left, right = x, x + width
    local startIndex = math.floor(math.max(1, math.min(count, tonumber(currentTab.subtabPageStart) or 1)))
    currentTab.subtabPageStart = startIndex
    currentTab.subtabPageHistory = currentTab.subtabPageHistory or {}
    local buttonH = math.max(20, math.min(math.max(24, menu.getUiLineHeight() + 4), height - 8))
    local buttonY = y + ((height - buttonH) / 2)
    local arrowW = math.min(22, (width - 4) / 2)
    local arrowStep = arrowW + 2
    if width < 84 then
        local selectedIndex = startIndex
        for index, subtab in ipairs(currentTab.subtabs) do
            if subtab.id == menu.activeSubtab then selectedIndex = index; break end
        end
        -- With no room for a readable label, arrows switch the page directly.
        for direction = -1, 1, 2 do
            local target = ((selectedIndex - 1 + direction) % count) + 1
            local targetSubtab = currentTab.subtabs[target]
            local buttonX = direction < 0 and x or (right - arrowW)
            ImGui.SetCursorScreenPos(buttonX, buttonY)
            local suffix = direction < 0 and "prev_" or "next_"
            if ImGui.InvisibleButton("##solstice_subtab_" .. suffix .. tostring(currentTab.id), arrowW, buttonH)
                and not menu.comboModalActive then
                menu.activeSubtab = targetSubtab.id
                currentTab.subtabPageStart = target
                menu.searchText = ""
            end
            local hovered = ImGui.IsItemHovered()
            local ar, ag, ab, aa = HexToRGBAFloat("#9d9aff")
            menu.drawClippedText(direction < 0 and "<" or ">", buttonX + 5,
                buttonY + math.max(2, (buttonH - menu.getUiLineHeight()) / 2),
                buttonX + arrowW, buttonY + buttonH, ar, ag, ab, aa)
            menu.drawDescriptionTooltip({label = targetSubtab.name, description = targetSubtab.name}, hovered)
        end
        return
    end
    if startIndex > 1 then
        ImGui.SetCursorScreenPos(left, buttonY)
        if ImGui.InvisibleButton("##solstice_subtab_prev_" .. tostring(currentTab.id), arrowW, buttonH)
            and not menu.comboModalActive then
            currentTab.subtabPageStart = table.remove(currentTab.subtabPageHistory) or 1
        end
        local ar, ag, ab, aa = HexToRGBAFloat("#9d9aff")
        ImGui.SetCursorScreenPos(left + 6, buttonY + math.max(2, (buttonH - menu.getUiLineHeight()) / 2))
        menu.localizedTextColored(ar, ag, ab, aa, "<")
        left = left + arrowStep
    end
    local cursorX, lastVisible = left, startIndex - 1
    for index = startIndex, count do
        local subtab = currentTab.subtabs[index]
        local fontScale = tonumber(menu.ui.fontScale) or 1.0
        if subtab._solsticeMeasureLanguage ~= menu.ui.language or subtab._solsticeMeasureLabel ~= subtab.name or subtab._solsticeMeasureScale ~= fontScale then
            subtab._solsticeTextW, subtab._solsticeTextH = menu.localizedTextSize(subtab.name)
            subtab._solsticeMeasureLanguage = menu.ui.language
            subtab._solsticeMeasureLabel, subtab._solsticeMeasureScale = subtab.name, fontScale
        end
        local textW = tonumber(subtab._solsticeTextW) or 42
        local buttonW = math.max(34, textW + 14)
        local reserve = index < count and arrowStep or 0
        if cursorX + buttonW + reserve > right and index > startIndex then break end
        -- Navigation arrows keep their own hit regions, even on narrow pages.
        buttonW = math.min(buttonW, math.max(0, right - cursorX - reserve))
        if buttonW < 8 then break end
        ImGui.SetCursorScreenPos(cursorX, buttonY)
        local clicked = ImGui.InvisibleButton("##solstice_subtab_" .. tostring(currentTab.id) .. "_" .. tostring(subtab.id), buttonW, buttonH)
        local hovered = ImGui.IsItemHovered()
        if clicked and not menu.comboModalActive then
            menu.activeSubtab = subtab.id
            menu.searchText = ""
        end
        local selected = menu.activeSubtab == subtab.id
        subtab._solsticeAnim = menu.animLerp(subtab._solsticeAnim or 0, selected and 1 or (hovered and 0.45 or 0), 16.0, g_dt)
        if subtab._solsticeAnim > 0.01 then
            local br, bg, bb = HexToRGBAInt(selected and "#9d9aff" or "#20242e")
            local fillAlpha = selected and 24 or 150
            ImGui.AddRectFilled(cursorX, buttonY, cursorX + buttonW, buttonY + buttonH,
                br, bg, bb, math.floor(fillAlpha * subtab._solsticeAnim * (menu.renderAlpha or 1.0)), 3.0)
        end
        if selected then
            local ar, ag, ab, aa = HexToRGBAInt("#9d9aff")
            ImGui.AddRectFilled(cursorX + 4, buttonY + buttonH - 2, cursorX + buttonW - 4, buttonY + buttonH,
                ar, ag, ab, aa, 1.0)
        end
        local tr, tg, tb, ta = HexToRGBAFloat((selected or hovered) and "#e8ebf2" or "#929aaa")
