        menu.drawClippedText(subtab.name, cursorX + 7, buttonY + math.max(2, (buttonH - (tonumber(textH) or 14)) / 2),
            cursorX + buttonW - 6, buttonY + buttonH, tr, tg, tb, ta)
        lastVisible = index
        cursorX = cursorX + buttonW + gap
    end
    if lastVisible < count then
        local nextX = right - arrowW
        ImGui.SetCursorScreenPos(nextX, buttonY)
        if ImGui.InvisibleButton("##solstice_subtab_next_" .. tostring(currentTab.id), arrowW, buttonH)
            and not menu.comboModalActive then
            currentTab.subtabPageHistory[#currentTab.subtabPageHistory + 1] = startIndex
            currentTab.subtabPageStart = math.min(count, math.max(startIndex + 1, lastVisible + 1))
        end
        local ar, ag, ab, aa = HexToRGBAFloat("#9d9aff")
        ImGui.SetCursorScreenPos(nextX + 7, buttonY + math.max(2, (buttonH - menu.getUiLineHeight()) / 2))
        menu.localizedTextColored(ar, ag, ab, aa, ">")
    end
end)

