                            item._renderedHeight = menu.getItemLayout(item).height
                            measuredRowH = math.max(measuredRowH, item._renderedHeight)
                            if index % itemColumns == 0 or index == #items then
                                groupH = groupH + measuredRowH + itemGap
                                measuredRowH = 0
                            end
                        end
                        local column, groupTop = 1, columnY[1]
                        if split then
                            for c = 2, columnCount do groupTop = math.max(groupTop, columnY[c]) end
                        else
                            for c = 2, columnCount do if columnY[c] < columnY[column] then column = c end end
                            groupTop = columnY[column]
                        end
                        if menu.pendingRevealGroupID == group.id then
                            local offset = menu.getItemOffsetInGroup(items, menu.pendingRevealItemUid, itemColumns, itemGap, headerH)
                            local target = math.max(0, groupTop + offset - 6)
                            if menu.pendingRevealApplied == true then
                                menu.pendingRevealGroupID, menu.pendingRevealItemUid, menu.pendingRevealApplied = nil, nil, nil
                            elseif type(ImGui.SetScrollY) == "function" then
                                pcall(ImGui.SetScrollY, target)
                                menu.pendingRevealApplied = true
                            end
                        end
                        local groupX = split and childX or childX + (column - 1) * (groupW + columnGap)
                        local groupY = childY + groupTop - scrollY
                        if groupY + groupH >= viewportTop and groupY <= viewportBottom then
                            menu.drawClippedText(tostring(group.name), groupX + 4,
                                groupY + math.max(3, (headerH - menu.getUiLineHeight()) / 2),
                                groupX + currentGroupW - 4, groupY + headerH, textR, textG, textB, textA)
                            ImGui.AddLine(groupX + 4, groupY + headerH - 1, groupX + currentGroupW - 4,
                                groupY + headerH - 1, lineR, lineG, lineB, lineA, 1.0)
                            local rowY = groupY + headerH
                            for rowStart = 1, #items, itemColumns do
                                local rowHeight = 0
                                for slot = 0, itemColumns - 1 do
                                    local item = items[rowStart + slot]
                                    if item then
                                        local itemX = groupX + slot * (itemW + innerGap)
                                        local itemHeight = item._renderedHeight
                                        if rowY + itemHeight >= viewportTop and rowY <= viewportBottom then
                                            SyncBoundItemValue(item)
                                            if item.type == "toggle" then DrawCustomToggle(item, itemX, rowY, itemW)
                                            elseif item.type == "slider" then DrawCustomSlider(item, itemX, rowY, itemW)
                                            elseif item.type == "color" then menu.drawColor(item, itemX, rowY, itemW)
                                            elseif item.type == "combo" then DrawCustomCombo(item, itemX, rowY, itemW)
                                            elseif item.type == "input" then DrawCustomInputText(item, itemX, rowY, itemW)
                                            elseif item.type == "button" then menu.drawCustomButton(item, itemX, rowY, itemW)
                                            elseif item.type == "text" then DrawCustomText(item, itemX, rowY) end
                                        end
                                        item._renderedHeight = itemHeight
                                        rowHeight = math.max(rowHeight, itemHeight)
                                    end
                                end
                                rowY = rowY + rowHeight + itemGap
                            end
                        end
                        local nextTop = groupTop + groupH + groupGap
                        if split then for c = 1, columnCount do columnY[c] = nextTop end
                        else columnY[column] = nextTop end
                    end
                end
                local maxY = 0
                for column = 1, columnCount do maxY = math.max(maxY, columnY[column]) end
                ImGui.SetCursorPos(0, maxY)
                ImGui.Dummy(1, 1)
                ImGui.SetWindowFontScale(1.0)
            end
            ImGui.EndChild()
            ImGui.PopStyleVar(2)
            ImGui.PopStyleColor(5)
        end

        ImGui.SetWindowFontScale(1.0)
    end
    ImGui.End()

    DrawComboOverlays()
    if mainX and menu.isPlayerListBound(menu.activeTab) and menu.ui.showPlayerInfo ~= 0 then
        menu.drawSelectedPlayerInfoWindow(mainX + mainW + 10, mainY + 10)
    end
    menu.renderAlpha = 1.0
    menu.colorBrightness = 1.0
    ImGui.PopStyleVar(4)
    menu.captureKeyboard(menu.textInputActive)
    menu.drawNotificationOverlay()
end)

