Crypto.sha256 = LPH_NO_VIRTUALIZE(function(message)
    local msgLen = #message
    local bitLen = msgLen * 8
    local padded = message .. '\x80'
    local modLen = (msgLen + 1) % 64
    if modLen > 56 then
        padded = padded .. string.rep('\0', 64 - modLen + 56)
    else
        padded = padded .. string.rep('\0', 56 - modLen)
    end
    for i = 1, 8 do
        padded = padded .. string.char((bitLen >> ((8 - i) * 8)) & 0xFF)
    end
    local h1, h2, h3, h4, h5, h6, h7, h8 = H[1], H[2], H[3], H[4], H[5], H[6], H[7], H[8]
    local w = sha256_w
    for chunkStart = 1, #padded, 64 do
        w[0], w[1], w[2], w[3], w[4], w[5], w[6], w[7],
        w[8], w[9], w[10], w[11], w[12], w[13], w[14], w[15] = string.unpack(SHA256_WORD_UNPACK_FMT, padded, chunkStart)
        for i = 16, 63 do
            local wi15, wi2 = w[i-15], w[i-2]
            local s0 = ((((wi15 >> 7) | (wi15 << 25)) & 0xFFFFFFFF) ~ (((wi15 >> 18) | (wi15 << 14)) & 0xFFFFFFFF) ~ (wi15 >> 3))
            local s1 = ((((wi2 >> 17) | (wi2 << 15)) & 0xFFFFFFFF) ~ (((wi2 >> 19) | (wi2 << 13)) & 0xFFFFFFFF) ~ (wi2 >> 10))
            w[i] = (w[i-16] + s0 + w[i-7] + s1) & 0xFFFFFFFF
        end
        local a, b, c, d, e, f, g, h0 = h1, h2, h3, h4, h5, h6, h7, h8
        for i = 0, 63 do
            local S1 = ((((e >> 6) | (e << 26)) & 0xFFFFFFFF) ~ (((e >> 11) | (e << 21)) & 0xFFFFFFFF) ~ (((e >> 25) | (e << 7)) & 0xFFFFFFFF))
            local ch = (e & f) ~ ((~e) & g)
            local temp1 = (h0 + S1 + ch + K[i+1] + w[i]) & 0xFFFFFFFF
            local S0 = ((((a >> 2) | (a << 30)) & 0xFFFFFFFF) ~ (((a >> 13) | (a << 19)) & 0xFFFFFFFF) ~ (((a >> 22) | (a << 10)) & 0xFFFFFFFF))
            local maj = (a & b) ~ (a & c) ~ (b & c)
            local temp2 = (S0 + maj) & 0xFFFFFFFF
            h0 = g
            g = f
            f = e
            e = (d + temp1) & 0xFFFFFFFF
            d = c
            c = b
            b = a
            a = (temp1 + temp2) & 0xFFFFFFFF
        end
        h1 = (h1 + a) & 0xFFFFFFFF
        h2 = (h2 + b) & 0xFFFFFFFF
        h3 = (h3 + c) & 0xFFFFFFFF
        h4 = (h4 + d) & 0xFFFFFFFF
        h5 = (h5 + e) & 0xFFFFFFFF
        h6 = (h6 + f) & 0xFFFFFFFF
        h7 = (h7 + g) & 0xFFFFFFFF
        h8 = (h8 + h0) & 0xFFFFFFFF
    end
    return string.pack(SHA256_HASH_PACK_FMT, h1, h2, h3, h4, h5, h6, h7, h8)
end)

function Crypto.hmac_sha256(key, message)
    local blockSize = 64
    if #key > blockSize then
        key = Crypto.sha256(key)
    end
    key = key .. string.rep('\0', blockSize - #key)
    local o_key_pad = {}
    local i_key_pad = {}
    for i = 1, blockSize do
        local b = string.byte(key, i)
        o_key_pad[i] = string.char(b ~ 0x5c)
        i_key_pad[i] = string.char(b ~ 0x36)
    end
    local inner = Crypto.sha256(table.concat(i_key_pad) .. message)
    return Crypto.sha256(table.concat(o_key_pad) .. inner)
end

Crypto.base64_encode = LPH_NO_VIRTUALIZE(function(data)
    local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local result = ""
    local padding = 0
    for i = 1, #data, 3 do
        local c1 = string.byte(data, i) or 0
        local c2 = string.byte(data, i+1) or 0
        local c3 = string.byte(data, i+2) or 0
        local a = (c1 >> 2) & 0x3F
        local b1 = ((c1 & 0x03) << 4) | ((c2 >> 4) & 0x0F)
        local c = ((c2 & 0x0F) << 2) | ((c3 >> 6) & 0x03)
        local d = c3 & 0x3F
        result = result .. string.sub(b, a+1, a+1) .. string.sub(b, b1+1, b1+1)
        if i+1 <= #data then
            result = result .. string.sub(b, c+1, c+1)
        else
            result = result .. "="
            padding = padding + 1
        end
        if i+2 <= #data then
            result = result .. string.sub(b, d+1, d+1)
        else
            result = result .. "="
            padding = padding + 1
        end
    end
    return result
end)

Crypto.base64_decode = LPH_NO_VIRTUALIZE(function(data)
    local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local decode = {}
    for i = 1, #b do decode[string.sub(b, i, i)] = i - 1 end
    decode['='] = -1
    local result = {}
    local buf = 0
    local bits = 0
    for i = 1, #data do
        local c = data:sub(i, i)
        local val = decode[c]
        if val and val >= 0 then
            buf = (buf << 6) | val
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                result[#result + 1] = string.char((buf >> bits) & 0xFF)
                if bits > 0 then
                    buf = buf & ((1 << bits) - 1)
                else
                    buf = 0
                end
            end
        end
    end
    return table.concat(result)
end)

function Crypto.hex_encode(data)
    local out = {}
    for i = 1, #data do
        out[i] = string.format("%02x", string.byte(data, i))
    end
    return table.concat(out)
end

local AuthManager
local FeatureRegistry = {
    registeredFeatures = {},
    featureGroups = {}
}

function FeatureRegistry:Register(config)
    if not config or not config.hash then
        return nil
    end
    if FeatureMgr.GetFeature(config.hash) then
        return nil
    end
    if config.cb and not config.authWrapped then
        local originalCb = config.cb
        local featureName = config.name or tostring(config.hash)
        config.cb = function(...)
            if not config._sovereignFreeAccess
                and (not AuthManager or not AuthManager:EnforceSession("Feature:" .. featureName)) then
                return
            end
            return originalCb(...)
        end
        config.authWrapped = true
    end
    local success, feature = pcall(function()
        local f
        if config.scope == "player" then
            f = FeatureMgr.AddPlayerFeature(config.hash, config.name, config.type, config.desc or "", config.cb, true)
        else
            f = FeatureMgr.AddFeature(config.hash, config.name, config.type, config.desc or "", config.cb, true)
        end
        if config.list then
            f:SetList(config.list)
        end
        if config.noCallbackOnPress ~= nil then
            f:SetNoCallbackOnPress(config.noCallbackOnPress)
        end
        if config.defaultValue ~= nil then
            if config.type == eFeatureType.Combo then
                f:SetListIndex(config.defaultValue)
            else
                f:SetDefaultValue(config.defaultValue)
            end
        end
        if config.limitValues then
            f:SetLimitValues(config.limitValues[1], config.limitValues[2])
        end
        if config.stepSize and f.SetStepSize then
            f:SetStepSize(config.stepSize)
        end
        if config.defaultColor and f.SetColor then
            f:SetColor(config.defaultColor[1] or 255, config.defaultColor[2] or 255, config.defaultColor[3] or 255, config.defaultColor[4] or 255)
        end
        self.registeredFeatures[config.hash] = { config = config,feature = f }
        local group = config.group
        self.featureGroups[group] = self.featureGroups[group] or {}
        table.insert(self.featureGroups[group], config)
        return f
    end)
    if not success then
        return nil
    end
    return feature
end
function FeatureRegistry:RegisterBatch(configs)
    for _, config in ipairs(configs or {}) do
        self:Register(config)
    end
end
function FeatureRegistry:RegisterBatches(batches)
    for _, configs in ipairs(batches or {}) do
        self:RegisterBatch(configs)
    end
end
function FeatureRegistry:AssignGroup(configs, group)
    for _, config in ipairs(configs or {}) do
        config.group = group
    end
end
function FeatureRegistry:AssignGroups(assignments)
    for _, assignment in ipairs(assignments or {}) do
        self:AssignGroup(assignment.items, assignment.group)
    end
end
function FeatureRegistry:RenderItems(items, playerIndex)
    for _, item in ipairs(items or {}) do
        if playerIndex then
            ClickGUI.RenderFeature(item.hash, playerIndex)
        else
            ClickGUI.RenderFeature(item.hash)
        end
    end
end
function FeatureRegistry:RenderGroup(group, playerIndex)
    local features = self.featureGroups[group]
    if not features then
        return
    end
    self:RenderItems(features, playerIndex)
end
function FeatureRegistry:GetFeature(hash)
    local reg = self.registeredFeatures[hash]
    return reg and reg.feature or nil
end

