    BANNED = 4
}

local SovereignProtectionFeedback = {slots={}, slotCount=0, pending={}, queue={}, clock=0, offset=0, stats={}}

function SovereignProtectionFeedback:Now()
    local raw
    if Time and type(Time.GetEpocheMs)=="function" then
        local ok,value=pcall(Time.GetEpocheMs);if ok and type(value)=="number" then raw=value/1000 end
    end
    if not raw then raw=os.clock() end
    if type(raw)~="number" or raw~=raw or math.abs(raw)==rawget(math, "huge") then raw=self.rawClock or 0 end
    if self.rawClock and raw<self.rawClock then self.offset=self.clock-raw end
    self.rawClock=raw;self.clock=raw+self.offset
    return self.clock
end

function SovereignProtectionFeedback:IsScope(scope)
    return scope=="SovereignProtectionSystem" or scope=="NodeDataProtection"
        or scope=="NodeProtection" or scope=="SovereignDetector"
end

function SovereignProtectionFeedback:Slot(key)
    key=type(key)=="string" and key:sub(1,96) or "other"
    if not self.slots[key] then
        if self.slotCount>=511 then key="overflow" else self.slotCount=self.slotCount+1 end
        self.slots[key]=self.slots[key] or {}
    end
    return self.slots[key],key
end

function SovereignProtectionFeedback:Allow(key, seconds)
    local slot=self:Slot("allow:"..tostring(key));local now=self:Now()
    if slot.allowedAt and now-slot.allowedAt<(seconds or 5) then return false end
    slot.allowedAt=now;return true
end

function SovereignProtectionFeedback:Enqueue(kind,key,message,status,duration,title)
    local slot,stable=self:Slot(kind..":"..tostring(key))
    self.stats[kind]=(self.stats[kind] or 0)+1
    local queued=self.pending[stable]
    if queued then queued.count=math.min(2147483647,queued.count+1);return true end
    local now=self:Now()
    if slot.sentAt and now-slot.sentAt<3 then return false end
    if #self.queue>=32 then self.stats.dropped=(self.stats.dropped or 0)+1;return false end
    queued={key=stable,kind=kind,message=tostring(message or ""):sub(1,768),status=status,
        duration=duration,title=title,count=1,created=now}
    self.pending[stable]=queued;self.queue[#self.queue+1]=queued
    return true
end

function SovereignProtectionFeedback:Notice(key,message,status,duration,title)
    return self:Enqueue("notice",key,message,status or "warning",duration or 3,title)
end

function SovereignProtectionFeedback:Log(key,level,message)
    return self:Enqueue("log",key,message,level or "info",0)
end

function SovereignProtectionFeedback:Report(key,title,message,status,seconds)
    return self:Notice(key,message,status=="error" and "error" or "warning",seconds or 3,title)
end

function SovereignProtectionFeedback:Reset()
    self.slots,self.pending,self.queue,self.stats={},{},{},{}
    self.slotCount,self.nextNotice,self.nextLog=0,nil,nil
end

local Logger = {
    enabled_modules = {},
    log_level = 2
}

Logger.LEVELS = {
    ERROR = 0,
    WARN = 1,
    INFO = 2,
    DEBUG = 3
}

local function printBlue(...)
    local args = {...}
    return menu.console.emit(2, "SovereignLua", table.concat(args, "\t"))
end
function Logger:Log(level, module, message)
    if level > self.log_level then
        return
    end
    if module == "AntiDump" then
        message = "Security violation detected"
    end
    if SovereignProtectionFeedback:IsScope(module) and not SovereignProtectionFeedback.flushing then
        return SovereignProtectionFeedback:Log(tostring(module)..":"..tostring(level),
            level==0 and "error" or level==1 and "warning" or "info",message)
    end
    local sink
    if level == self.LEVELS.ERROR then
        sink = self.LogError
    else
        sink = self.LogInfo
    end
    return menu.console.emit(level, module, message, sink)
end

function Logger:Error(module, message)
    self:Log(self.LEVELS.ERROR, module, message)
end

function Logger:Warn(module, message)
    self:Log(self.LEVELS.WARN, module, message)
end

function Logger:Info(module, message)
    self:Log(self.LEVELS.INFO, module, message)
end

function Logger:Debug(module, message)
    self:Log(self.LEVELS.DEBUG, module, message)
end

function Logger:Toast(title, message, duration, position)
    if self~=Logger then duration,message,title=message,title,self end
    local seconds=menu.normalizeNotificationDuration(duration,3.0)
    if title=="AntiHook" or title=="AntiDump" then message="Violation detected" end
    if SovereignProtectionFeedback:IsScope(title) then
        if tostring(message):find("Rope creation detected ",1,true)==1 then return false end
        return SovereignProtectionFeedback:Notice(tostring(title),message,"warning",seconds,title)
    end
    local body=tostring(message or "")
    local status=menu.inferNotificationStatus(body)
    return menu.notify(title or "SovereignLua",body,seconds,status)
end

function SovereignProtectionFeedback:Flush()
    local now=self:Now();local sent=0
    for index=#self.queue,1,-1 do
        if now-self.queue[index].created>15 then
            self.pending[self.queue[index].key]=nil;table.remove(self.queue,index)
        end
    end
    local index=1
    while index<=#self.queue and sent<2 do
        local entry=self.queue[index]
        local due=entry.kind=="notice" and (not self.nextNotice or now>=self.nextNotice)
            or entry.kind=="log" and (not self.nextLog or now>=self.nextLog)
        if due then
            table.remove(self.queue,index);self.pending[entry.key]=nil
            local message=entry.message
            if entry.count>1 then message=message.."  x"..tostring(entry.count) end
            local ok
            if entry.kind=="notice" then
                ok=pcall(menu.notify,entry.title or "Sovereign protection",message,entry.duration,entry.status)
                self.nextNotice=now+0.75
            else
                self.flushing=true
                local level=entry.status=="error" and 0 or entry.status=="warning" and 1 or 2
                ok=pcall(Logger.Log,Logger,level,"SovereignProtectionSystem",message)
                self.flushing=false;self.nextLog=now+0.25
            end
            self:Slot(entry.key).sentAt=now
            self.stats.delivered=(self.stats.delivered or 0)+(ok and 1 or 0)
            sent=sent+1
        else index=index+1 end
    end
end

local eTaskTypeIndex = {
    CTaskHandsUp = 0,
    CTaskClimbLadder = 1,
    CTaskExitVehicle = 2,
    CTaskCombatRoll = 3,
