local Utils1 = {}

function Utils1.StructInstance(struct, base)
    base = base or 0
    if type(struct) ~= "table" then
        Logger:Error("StructInstance", "struct is not a table, type=" .. type(struct) .. ", val=" .. tostring(struct))
        if type(struct) == "number" then return struct + base end
        return struct
    end
    local result = {}
    for key, value in pairs(struct) do
        if type(value) == "number" then
            result[key] = value + base
        elseif type(value) == "table" then
            result[key] = Utils1.StructInstance(value, base)
        else
            result[key] = value
        end
    end
    return result
end

function Utils1.StructInstanceArray(struct, base, size, count)
    if type(struct) ~= "table" then
        Logger:Error("StructInstanceArray", "struct is not a table, type=" .. type(struct))
        return {}
    end
    if type(base) ~= "number" then
        Logger:Error("StructInstanceArray", "base is not a number, type=" .. type(base))
        return {}
    end
    local temp = {}
    local tempBase = base
    for i = 0, count - 1 do
        temp[i] = Utils1.StructInstance(struct, tempBase)
        tempBase = tempBase + size
    end
    return temp
end

function Utils1.GenerateOffsetArray(base, count)
    local temp = {}
    local tempBase = base
    for i = 0, count - 1 do
        temp[i] = tempBase + i
    end
    return temp
end

