-- Script-event capability table.  Legacy transaction/mission envelopes are
-- confirmed by the local decompiled freemode audit; the Enhanced-only
-- simple-interior globals are intentionally not reused on Legacy.
SovereignScriptEventCompatibility = {
    legacy = {
        mission_confirmation = true,
        mission_force = true,
        apartment_property = true,
        simple_interior_global = false,
        simple_interior_event = true
    },
    enhanced = {
        mission_confirmation = true,
        mission_force = true,
        apartment_property = true,
        simple_interior_global = true,
        simple_interior_event = true
    }
}

function SovereignScriptEventCompatibility:Supports(name)
    local edition = Utils1:edition()
    local profile = self[string.lower(tostring(edition or "unknown"))]
    return type(profile) == "table" and profile[name] == true
end

function SovereignScriptEventCompatibility:Status(name)
    local edition = Utils1:edition()
    return self:Supports(name), tostring(edition or "unknown") .. ":" .. tostring(name)
end

