function Utils1.GetGlobalPlayerIndex(base, stride, playerID, offset)
    return base + 1 + (playerID * stride) + offset
end

function Utils1.SafeGetGlobalInt(index)
    local success, value = pcall(function()
        return ScriptGlobal.GetInt(index)
    end)
    if success then
        return value
    end
    return nil
end

function Utils1.SafeSetGlobalInt(index, value)
    local success = pcall(function()
        ScriptGlobal.SetInt(index, value)
    end)
    return success
end

function Utils1.SafeSetGlobalFloat(index, value)
    if not ScriptGlobal or type(ScriptGlobal.SetFloat) ~= "function" then
        return false
    end
    local success = pcall(function()
        ScriptGlobal.SetFloat(index, value)
    end)
    return success
end

function Utils1.SafeSetGlobalBit(index, bit, enabled)
    bit = tonumber(bit)
    if not bit then
        return false
    end
    bit = math.floor(bit)
    if bit < 0 or bit > 31 then
        return false
    end
    local current = Utils1.SafeGetGlobalInt(index)
    if type(current) ~= "number" then
        return false
    end
    local mask = 1 << bit
    local nextValue
    if enabled then
        nextValue = current | mask
    else
        nextValue = current & (~mask)
    end
    return Utils1.SafeSetGlobalInt(index, nextValue)
end

function Utils1.IsValidSimpleInterior(value)
    value = tonumber(value)
    return value ~= nil and value > 0 and value <= 300
end

function Utils1.IsValidNativeProperty(value)
    value = tonumber(value)
    return value ~= nil and value ~= -1 and value >= 0 and value <= 300
end

function Utils1.IsValidOffsetProperty(value)
    value = tonumber(value)
    return value ~= nil and value > 0 and value <= 300
end

function Utils1.GetPlayerInteriorByConfig(playerID, cfg)
    if not playerID or playerID < 0 or type(cfg) ~= "table" then
        return nil
    end
    local index = Utils1.GetGlobalPlayerIndex(cfg.globalPlayerBD, cfg.globalPlayerBDStride, playerID, cfg.simpleInteriorOffset)
    return Utils1.SafeGetGlobalInt(index)
end

function Utils1.GetPlayerSimpleInteriorInstance(playerID, cfg)
    if not playerID or playerID < 0 or type(cfg) ~= "table"
        or type(cfg.simpleInteriorInstanceOffset) ~= "number" then
        return nil
    end
    local index = Utils1.GetGlobalPlayerIndex(cfg.globalPlayerBD, cfg.globalPlayerBDStride, playerID, cfg.simpleInteriorInstanceOffset)
    return Utils1.SafeGetGlobalInt(index)
end

-- Interior support is self-contained and does not depend on the optional
-- loader mapping object.  The build check remains to prevent stale offsets
-- from being used on a different Legacy executable.
function Utils1.IsLegacyInteriorBuildSupported()
    if Utils1:edition() ~= "Legacy" then return false end
    local ok, build = pcall(function() return Utils1:buildInfo() end)
    return ok and build == "6A4F9ED3-03E5BC00"
end

function Utils1.GetInteriorConfig(playerID)
    local edition = Utils1:edition()
    -- Select only the layout matching the loaded executable.  Legacy and
    -- Enhanced use different player-BD bases; never fall through between them.
    if edition ~= "Enhanced" and edition ~= "Legacy" then return nil end
    -- Legacy interior globals have their own verified build-bound evidence;
    -- inventory/freemode feature flags may be absent in older loader profiles.
    local mappingReady = edition == "Legacy" and Utils1.IsLegacyInteriorBuildSupported()
        or edition == "Enhanced"
    if not mappingReady then return nil end
    if not playerID or playerID < 0 then
        for _, cfg in ipairs(InteriorGlobalConfigs) do
            if cfg.edition == edition then return cfg end
        end
        return nil
    end
    for _, cfg in ipairs(InteriorGlobalConfigs) do
        if cfg.edition == edition then
            local value = Utils1.GetPlayerInteriorByConfig(playerID, cfg)
            if Utils1.IsValidSimpleInterior(value) then return cfg end
        end
    end
    for _, cfg in ipairs(InteriorGlobalConfigs) do
        if cfg.edition == edition then return cfg end
    end
    return nil
end

function Utils1.GetPlayerInterior(playerID)
    local edition = Utils1:edition()
    if edition ~= "Enhanced" and edition ~= "Legacy" then return -1 end
    local mappingReady = edition == "Legacy" and Utils1.IsLegacyInteriorBuildSupported()
        or edition == "Enhanced"
    if not mappingReady then return -1 end
    if not playerID or playerID < 0 then
        return -1
    end
    for _, cfg in ipairs(InteriorGlobalConfigs) do
        if cfg.edition == edition then
            local value = Utils1.GetPlayerInteriorByConfig(playerID, cfg)
            if Utils1.IsValidSimpleInterior(value) then return value end
        end
    end
    return -1
end

function Utils1.GetCurrentlyInsideProperty(playerID)
    if not playerID or playerID < 0 then
        return -1
    end
    if Players and type(Players.GetProperty) == "function" then
        local success, property = pcall(function()
            return Players.GetProperty(playerID)
        end)
        if success and Utils1.IsValidNativeProperty(property) then
            return property
        end
    end
    local edition = Utils1:edition()
    if edition ~= "Enhanced" then
        return -1
    end
    for _, cfg in ipairs(InteriorGlobalConfigs) do
        if cfg.edition == edition then
            local index = Utils1.GetGlobalPlayerIndex(cfg.globalPlayerBDFM, cfg.globalPlayerBDFMStride, playerID, cfg.propertyOffset)
            local value = Utils1.SafeGetGlobalInt(index)
            if Utils1.IsValidOffsetProperty(value) then
                return value
            end
        end
    end
    return -1
end

function Utils1.EnterPlayerProperty(playerID, property)
    if not playerID or playerID < 0 or not Utils1.IsValidNativeProperty(property) then
        return false
    end
    local myId = GTA.GetLocalPlayerId()
    if not myId or myId < 0 then
        return false
    end
    local args = {
        SCRIPT_EVENT.INVITE_NEARBY_PLAYERS_INTO_APARTMENT,
        myId,
        1 << playerID,
        playerID,
        -1,
        1,
        property,
        0,
        0,
        0,
        0
    }
    local success, result = pcall(function()
        return GTA.TriggerScriptEvent(1 << myId, args)
    end)
    return success and result ~= false
end

function Utils1.TriggerLocalSimpleInteriorWarp(playerID, simpleInterior, cfg)
    if SovereignScriptEventCompatibility
        and not SovereignScriptEventCompatibility:Supports("simple_interior_event") then
        return false
    end
    if not playerID or playerID < 0 or not Utils1.IsValidSimpleInterior(simpleInterior) or type(cfg) ~= "table" then
        return false
    end
    if not GTA or type(GTA.TriggerScriptEvent) ~= "function" then
        return false
    end
    local myId = GTA.GetLocalPlayerId()
    if not myId or myId < 0 then
        return false
    end
    local owner = Utils1.SafeGetGlobalInt(Utils1.GetGlobalPlayerIndex(
        cfg.globalPlayerBD, cfg.globalPlayerBDStride, playerID, cfg.simpleInteriorOwnerOffset
    ))
    if type(owner) ~= "number" or owner < 0 or owner > 31 then
        owner = playerID
    end
    local instance = Utils1.GetPlayerSimpleInteriorInstance(playerID, cfg)
    if type(instance) ~= "number" or instance < 0 then
        instance = Utils1.GetPlayerSimpleInteriorInstance(myId, cfg)
    end
    if type(instance) ~= "number" or instance < 0 then
        instance = 0
    end
    local args = {
        SCRIPT_EVENT.PLAYERS_WARP_INSIDE_SIMPLE_INTERIOR,
        myId,
        1 << myId,
        simpleInterior,
        owner,
        0,
        1,
        0,
        0,
        0,
        0,
        -1,
        instance,
        2147483647,
        0,
        -1
    }
    local success, result = pcall(function()
        return GTA.TriggerScriptEvent(1 << myId, args)
    end)
    return success and result ~= false
end

function Utils1.EnterPlayerSimpleInterior(playerID, simpleInterior, cfg)
    if SovereignScriptEventCompatibility
        and not SovereignScriptEventCompatibility:Supports("simple_interior_global") then
        return false
    end
    if not playerID or playerID < 0 or not Utils1.IsValidSimpleInterior(simpleInterior)
        or type(cfg) ~= "table" or cfg.writeEnabled ~= true then
        return false
    end
    local myId = GTA.GetLocalPlayerId()
    if not myId or myId < 0 then
        return false
    end
    local base = cfg.simpleInteriorData
    if not base then
        return false
    end
    local localIndex = Utils1.GetGlobalPlayerIndex(
        cfg.globalPlayerBD, cfg.globalPlayerBDStride, myId, cfg.simpleInteriorOffset
    )
    local currentInterior = Utils1.SafeGetGlobalInt(localIndex)
    if type(currentInterior) ~= "number" then
        currentInterior = -1
    end
    local targetOwner = Utils1.SafeGetGlobalInt(Utils1.GetGlobalPlayerIndex(
        cfg.globalPlayerBD, cfg.globalPlayerBDStride, playerID, cfg.simpleInteriorOwnerOffset
    ))
    if type(targetOwner) ~= "number" or targetOwner < 0 or targetOwner > 31 then
        targetOwner = playerID
    end
    local targetInstance = Utils1.GetPlayerSimpleInteriorInstance(playerID, cfg)
    if type(targetInstance) ~= "number" or targetInstance < 0 then
        targetInstance = 0
    end
    local localInstanceIndex = Utils1.GetGlobalPlayerIndex(
        cfg.globalPlayerBD, cfg.globalPlayerBDStride, myId, cfg.simpleInteriorInstanceOffset
    )
    local localOwnerIndex = Utils1.GetGlobalPlayerIndex(
        cfg.globalPlayerBD, cfg.globalPlayerBDStride, myId, cfg.simpleInteriorOwnerOffset
    )
    local localFlagsIndex = Utils1.GetGlobalPlayerIndex(
        cfg.globalPlayerBD, cfg.globalPlayerBDStride, myId, cfg.simpleInteriorFlagsOffset
    )

    -- Mirror func_25009/func_2657 in current Enhanced freemode. Clear the
    -- active bit first, then publish it last so no partial request is consumed.
    local ok = Utils1.SafeSetGlobalInt(base + cfg.autowarpActiveOffset, 0)
    ok = Utils1.SafeSetGlobalInt(base + cfg.autowarpSelectionOffset, targetOwner) and ok
    ok = Utils1.SafeSetGlobalInt(base + cfg.autowarpCurrentInteriorOffset, currentInterior) and ok
    ok = Utils1.SafeSetGlobalInt(base + cfg.autowarpInteriorOffset, simpleInterior) and ok
    ok = Utils1.SafeSetGlobalInt(base + cfg.autowarpOverrideOffset, 0) and ok
    ok = Utils1.SafeSetGlobalFloat(base + cfg.autowarpCoordsOffset, 0.0) and ok
    ok = Utils1.SafeSetGlobalFloat(base + cfg.autowarpCoordsOffset + 1, 0.0) and ok
    ok = Utils1.SafeSetGlobalFloat(base + cfg.autowarpCoordsOffset + 2, 0.0) and ok
    ok = Utils1.SafeSetGlobalFloat(base + cfg.autowarpHeadingOffset, 0.0) and ok
    ok = Utils1.SafeSetGlobalInt(base + cfg.autowarpSetInInteriorOffset, 1) and ok
    ok = Utils1.SafeSetGlobalInt(base + cfg.autowarpFlagsOffset, 0) and ok
    ok = Utils1.SafeSetGlobalInt(base + cfg.autowarpControlOffset, 0) and ok
    ok = Utils1.SafeSetGlobalInt(base + cfg.autowarpVehicleFlagOffset, 0) and ok
    ok = Utils1.SafeSetGlobalInt(localOwnerIndex, targetOwner) and ok
    ok = Utils1.SafeSetGlobalInt(localFlagsIndex, 0) and ok
    ok = Utils1.SafeSetGlobalInt(localInstanceIndex, targetInstance) and ok
    ok = Utils1.SafeSetGlobalInt(localIndex, -1) and ok
    ok = Utils1.SafeSetGlobalBit(base + cfg.autowarpStateBitsOffset, 2, true) and ok
    ok = Utils1.SafeSetGlobalBit(
        Utils1.GetGlobalPlayerIndex(cfg.globalPlayerBD, cfg.globalPlayerBDStride, myId, cfg.simpleInteriorStateBitsOffset),
        18,
        true
    ) and ok
    if ok then
        ok = Utils1.SafeSetGlobalInt(base + cfg.autowarpActiveOffset, 1)
    end
    return ok
end

function Utils1.EnterTheirInterior(playerID)
    if not playerID or playerID < 0 or playerID == GTA.GetLocalPlayerId() then
        return false, "invalid_player"
    end

    local property = Utils1.GetCurrentlyInsideProperty(playerID)
    if Utils1.IsValidNativeProperty(property)
        and Utils1.EnterPlayerProperty(playerID, property) then
        return true, "property"
    end

    local cfg = Utils1.GetInteriorConfig(playerID)
    if not cfg then
        local edition = Utils1:edition()
        if edition == "Legacy" then
            return false, "legacy_mapping_missing"
        end
        if edition ~= "Enhanced" then
            return false, "edition_unresolved"
        end
        return false, "freemode_mapping_missing"
    end
    local simpleInterior = Utils1.GetPlayerInteriorByConfig(playerID, cfg)
    if Utils1.IsValidSimpleInterior(simpleInterior) then
        local eventQueued = Utils1.TriggerLocalSimpleInteriorWarp(playerID, simpleInterior, cfg)
        local globalApplied = Utils1.EnterPlayerSimpleInterior(playerID, simpleInterior, cfg)
        if globalApplied then
            return true, "simple_global"
        end
        if eventQueued then return true, "simple_event" end
    end
    return false, "not_found"
end

