    return ScriptGlobal.GetInt(GlobalplayerBD_FM_3[playerID].iUniquePlayerHash)
end

function Utils1.launchMission(playerId)
    if type(playerId) ~= "number" or playerId < 0 or playerId > 31
        or not GTA or type(GTA.TriggerScriptEvent) ~= "function" then
        return false
    end
    local eventHash = SCRIPT_EVENT.SCRIPT_EVENT_CONFIRMATION_LAUNCH_MISSION
        or SCRIPT_EVENT.CONFIRMATION_LAUNCH_MISSION
    if type(eventHash) ~= "number" or eventHash == 0 then return false end
    local args = {
        eventHash,
        GTA.GetLocalPlayerId(),
        1 << playerId,
    }
    for index = 4, 26 do
        args[index] = 0
    end
    local ok, result = pcall(GTA.TriggerScriptEvent, 1 << playerId, args)
    return ok and result ~= false
    -- GTA.TriggerScriptEvent((1 << playerID), {
