-- GTA edition compatibility boundary.  The Loader may set the explicit
-- lowercase override before executing this source.  Unknown values are kept
-- as Unknown so an Enhanced/Legacy offset set is never selected by accident.
do
SovereignEditionState = rawget(_G, "__SOVEREIGN_EDITION_STATE") or {
    value = nil,
    source = "unresolved",
    input = nil,
}
rawset(_G, "__SOVEREIGN_EDITION_STATE", SovereignEditionState)

function sovereignNormalizeEdition(value)
    if type(value) ~= "string" then return nil end
    local text = value:lower():match("^%s*(.-)%s*$")
    if text == "enhanced" or text == "ee" or text == "ee be" then
        return "Enhanced"
    end
    if text == "legacy" or text == "gtav" or text == "gta5" then
        return "Legacy"
    end
    return nil
end

function sovereignModuleForEdition(edition)
    if edition == "Enhanced" then return "GTA5_Enhanced.exe" end
    if edition == "Legacy" then return "GTA5.exe" end
    return nil
end

function Utils1:DetectEdition()
    local hint = rawget(_G, "__SOVEREIGN_GAME_EDITION")
    local explicit = sovereignNormalizeEdition(hint)
    local present = {}
    if Memory and type(Memory.GetBaseAddress) == "function" then
        for _, edition in ipairs({"Enhanced", "Legacy"}) do
            local ok, base = pcall(Memory.GetBaseAddress, sovereignModuleForEdition(edition))
            if ok and type(base) == "number" and base >= 0x10000 and base < 0x0000800000000000 then
                present[#present + 1] = edition
            end
        end
    end
    -- The loaded executable takes precedence over stale injector/host labels.
    if #present == 1 then
        local source = explicit == present[1] and "loader+module" or "module"
        if explicit and explicit ~= present[1] then source = "module (loader mismatch ignored)" end
        return present[1], source
    end
    -- Only recognized game-edition labels are usable. Product/tier labels,
    -- empty strings and API errors must never implicitly select Legacy.
    if Cherax and type(Cherax.GetEdition) == "function" then
        local ok, value = pcall(Cherax.GetEdition)
        local normalized = ok and sovereignNormalizeEdition(value) or nil
        if normalized then return normalized, "cherax" end
    end
    if explicit then return explicit, "loader" end
    if #present > 1 then return "Unknown", "ambiguous modules" end
    if hint ~= nil then return "Unknown", "invalid selection" end
    return "Unknown", "unresolved"
end

function Utils1:SetEdition(value)
    local normalized = sovereignNormalizeEdition(value)
    if not normalized then return false, "edition must be Enhanced or Legacy" end
    local previous = rawget(_G, "__SOVEREIGN_GAME_EDITION")
    rawset(_G, "__SOVEREIGN_GAME_EDITION", normalized:lower())
    local detected, reason = self:DetectEdition()
    if detected ~= normalized then
        rawset(_G, "__SOVEREIGN_GAME_EDITION", previous)
        return false, reason
    end
    rawset(_G, "__SOVEREIGN_GAME_EDITION", previous)
    if type(self.resetEditionMapping) == "function" then
        local resetOk, resetResult = pcall(self.resetEditionMapping)
        if not resetOk or resetResult == false then return false, "edition mapping restore failed" end
    end
    rawset(_G, "__SOVEREIGN_GAME_EDITION", normalized:lower())
    SovereignEditionState.value = normalized
    SovereignEditionState.source = "user"
    SovereignEditionState.input = normalized:lower()
    return true, normalized
end

function Utils1:edition()
    local input = rawget(_G, "__SOVEREIGN_GAME_EDITION")
    local value, source = self:DetectEdition()
    SovereignEditionState.value = value
    SovereignEditionState.source = source
    SovereignEditionState.input = input
    return value
end

function Utils1:editionInfo()
    local value = self:edition()
    return value, SovereignEditionState.source, sovereignModuleForEdition(value)
end

-- Read the loaded PE identity, not the Cherax version or payload release ID.
function Utils1:DetectBuildIdentifier()
    local _, _, module = self:editionInfo()
    if not module or not Memory or type(Memory.ReadUInt) ~= "function"
        or type(Memory.ReadUShort) ~= "function" then return nil, "unresolved" end
    local ok, identity = pcall(function()
        local base = Memory.GetBaseAddress(module)
        if type(base) ~= "number" or base < 0x10000 or Memory.ReadUShort(base) ~= 0x5A4D then return nil end
        local offset = Memory.ReadUInt(base + 0x3C)
        if offset < 64 or offset > 0x100000 then return nil end
        local nt = base + offset
        if Memory.ReadUInt(nt) ~= 0x4550 or Memory.ReadUShort(nt + 4) ~= 0x8664
            or Memory.ReadUShort(nt + 24) ~= 0x20B then return nil end
        local size = Memory.ReadUInt(nt + 80)
        if size == 0 then return nil end
        return string.format("%08X-%08X", Memory.ReadUInt(nt + 8), size)
    end)
    if not ok or not identity then return nil, "invalid PE identity" end
    local explicit = rawget(_G, "__SOVEREIGN_GAME_BUILD")
    if explicit ~= nil and explicit ~= identity then return nil, "game build mismatch" end
    return identity, explicit and "loader+PE" or "PE"
end

function Utils1:buildInfo()
    local value, source = self:DetectBuildIdentifier()
    return value or "Unknown", source
end

function SovereignMappingFeature(name)
    local mapping = SovereignOfficial:GetMapping()
    return type(name) == "string" and type(mapping) == "table"
        and type(mapping.features) == "table" and mapping.features[name] == true
end
end

function Utils1:IsValidPosition(pos)
    if not pos then
        return false
    end
    local posType = type(pos)
    if posType ~= "table" and posType ~= "userdata" then
        return false
    end
    if pos.x == nil or pos.y == nil or pos.z == nil then
        return false
    end
    return true
end

function Utils1:V3Distance(a, b)
    if not self:IsValidPosition(a) or not self:IsValidPosition(b) then
        return rawget(math, "huge")
    end
    local dx = a.x - b.x
    local dy = a.y - b.y
    local dz = a.z - b.z
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end

function Utils1:Clamp(value, min, max)
    return math.max(min, math.min(max, value))
end


function Utils1:GetNameList(items)
    local names = {}
    for i, item in ipairs(items or {}) do
        names[i] = item.name
    end
    return names
end

function Utils1:SafeInsert(tbl, value)
    if type(tbl) ~= "table" then return false end
    if value == nil then return false end
    table.insert(tbl, value)
    return true
end

function Utils1:DeepCopy(orig)
    local copy
    if type(orig) == "table" then
        copy = {}
        for k, v in next, orig, nil do
            copy[self:DeepCopy(k)] = self:DeepCopy(v)
        end
        setmetatable(copy, self:DeepCopy(getmetatable(orig)))
    else
        copy = orig
    end
    return copy
end

function Utils1:NowSeconds()
    if Time and Time.GetEpocheMs then
        local ok, ms = pcall(function() return Time.GetEpocheMs() end)
        if ok and type(ms) == "number" then
            return ms / 1000.0
        end
    end
    if menu.nativeApis.MISC and menu.nativeApis.MISC.GET_GAME_TIMER then
        local ok, ms = pcall(function() return menu.nativeApis.MISC.GET_GAME_TIMER() end)
        if ok and type(ms) == "number" then
            return ms / 1000.0
        end
    end
    return os.clock()
end

local NativeTaskQueue = {state = {}}

function NativeTaskQueue:Now()
    return Utils1:NowSeconds()
end

function NativeTaskQueue:Run(key, interval, callback)
    if type(callback) ~= "function" then
        return false
    end
    if not Script or not Script.QueueJob then
        return pcall(callback)
    end
    local now = self:Now()
    local state = self.state[key]
    if state and (state.pending or now - (state.last or 0) < (interval or 0.25)) then
        return false
    end
    self.state[key] = {pending = true, last = now}
    local queued = pcall(function()
        Script.QueueJob(function()
            pcall(callback)
            local current = self.state[key]
            if current then
                current.pending = false
                current.last = self:Now()
            end
        end)
    end)
    if not queued then
        self.state[key].pending = false
        return false
    end
    return true
end

function NativeTaskQueue:PlayAnim(key, ped, dict, anim, blendIn, blendOut, duration, flags, playbackRate, lockX, lockY, lockZ, interval)
    return self:Run("anim:" .. key, interval or 0.75, function()
        if menu.nativeApis.TASK and menu.nativeApis.TASK.TASK_PLAY_ANIM and ped and ped ~= 0 then
            menu.nativeApis.TASK.TASK_PLAY_ANIM(ped, dict, anim, blendIn, blendOut, duration, flags, playbackRate, lockX, lockY, lockZ)
        end
    end)
end

function NativeTaskQueue:ClearNow(key, ped, interval)
    return self:Run("clear_now:" .. key, interval or 0.25, function()
        if menu.nativeApis.TASK and menu.nativeApis.TASK.CLEAR_PED_TASKS_IMMEDIATELY and ped and ped ~= 0 then
            menu.nativeApis.TASK.CLEAR_PED_TASKS_IMMEDIATELY(ped)
        end
    end)
end

function NativeTaskQueue:Clear(key, ped, interval)
    return self:Run("clear:" .. key, interval or 0.25, function()
        if menu.nativeApis.TASK and menu.nativeApis.TASK.CLEAR_PED_TASKS and ped and ped ~= 0 then
            menu.nativeApis.TASK.CLEAR_PED_TASKS(ped)
        end
    end)
end

function Utils1:GeneratePlayerBitflags(players, excludeLocal)
    local bitflags = 0
    local localId = GTA.GetLocalPlayerId()
    for _, pid in ipairs(players) do
        if not excludeLocal or pid ~= localId then
            bitflags = bitflags | (1 << pid)
        end
    end
    return bitflags
end

function Utils1:GetPlayersInRange(radius)
    radius = radius or CONFIG.LIMITS.DefaultRadius
    local players = {}
    local localId = GTA.GetLocalPlayerId()
    local localPed = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(localId)
    if not localPed or localPed == 0 then
        return players
    end
    local localPos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(localPed, true)
    if not localPos then
        return players
    end
    for pid = 0, 31 do
        if pid ~= localId and PlayerManager:IsValidPlayer(pid) then
            local success, pos = PlayerManager:GetPlayerPosition(pid)
            if success and pos then
                if Utils1:V3Distance(localPos, pos) <= radius then
                    table.insert(players, pid)
                end
            end
        end
    end
    return players
end

function Utils1:GetRandomPlayerInRange(radius)
    local players = self:GetPlayersInRange(radius)
    if #players == 0 then
        return nil
    end
    return players[math.random(#players)]
end

local FileManager = {}

local function GetSafeUID()
    local ok, uid = pcall(function()
        return Cherax.GetUID()
    end)
    if ok and uid then
        return tostring(uid)
    end
    return "0"
end

local runtimeRandomSeeded = false
local function SeedRuntimeRandom()
    if runtimeRandomSeeded then return end
    local material = tostring(os.time()) .. "|" .. tostring(os.clock()) .. "|" .. GetSafeUID()
    local hash = Crypto.sha256(material)
    local seed = 0
    for i = 1, 8 do
        seed = ((seed << 5) ~ string.byte(hash, i)) & 0x7FFFFFFF
    end
    math.randomseed(seed)
    for _ = 1, 3 do math.random() end
    runtimeRandomSeeded = true
end

local runtimeSecret = nil
local function GetRuntimeSecret()
    if runtimeSecret then return runtimeSecret end
    SeedRuntimeRandom()
    local material = table.concat({
        CONFIG.NETWORK.OwnerId,
        CONFIG.NETWORK.AppName,
        GetSafeUID(),
        tostring(os.time()),
        string.format("%.6f", os.clock()),
        tostring(math.random(1, 0x7FFFFFFF)),
        tostring({})
    }, "|")
    runtimeSecret = Crypto.sha256(material)
    return runtimeSecret
end

local XorWithKeyStream = LPH_NO_VIRTUALIZE(function(data, key)
    local out = {}
    local blocks = math.ceil(#data / 32)
    for block = 0, blocks - 1 do
        local stream = Crypto.sha256(key .. string.char(block & 0xFF) .. string.char((block >> 8) & 0xFF))
        for i = 1, 32 do
            local idx = block * 32 + i
            if idx > #data then break end
            out[idx] = string.char(string.byte(data, idx) ~ string.byte(stream, i))
        end
    end
    return table.concat(out)
end)

function FileManager.NormalizeLicenseKey(key)
    if type(key) ~= "string" or #key > 4096 then return nil end
    local value = key:match("^%s*(.-)%s*$")
    if value == "" or value:find("[%z\1-\31\127]") then return nil end
    local marker = value:gsub("%s+", ""):upper()
    if marker == "LOCAL-TEST" or marker == "LOCAL_TEST" or marker == "LOCALTEST" then return nil end
    return value
end

-- Match the existing local key-file format. Only the official cache is written;
-- the older Loader/Lua cache is a read-only fallback for existing users.
do
    local function normalizeSavedKey(raw)
        local key = FileManager.NormalizeLicenseKey(raw)
        return key and #key <= 512 and key or nil
    end

    local function readSavedKey(path)
        if type(path) ~= "string" or path == "" or not FileMgr
            or type(FileMgr.ReadFileContent) ~= "function"
            or type(FileMgr.DoesFileExist) ~= "function" then return "" end
        -- Missing caches are normal on first use. pcall does not suppress the
        -- host's file-open error logger, so never read a known-missing file.
        local existsOk, exists = pcall(FileMgr.DoesFileExist, path)
        if not existsOk or exists ~= true then return "" end
        local ok, raw = pcall(FileMgr.ReadFileContent, path)
        return ok and normalizeSavedKey(raw) or ""
    end

    function FileManager:LoadSavedKey()
        local key = readSavedKey(CONFIG.PATHS.OfficialKeyFile)
        if key ~= "" then return key, "official_cache" end
        key = readSavedKey(CONFIG.PATHS.ConfigFile)
        return key, key ~= "" and "legacy_cache" or "unknown"
    end

    function FileManager:SaveKey(key)
        local value, path = normalizeSavedKey(key), CONFIG.PATHS.OfficialKeyFile
        if not value or type(path) ~= "string" or path == "" or not FileMgr
            or type(FileMgr.ReadFileContent) ~= "function"
            or type(FileMgr.DoesFileExist) ~= "function"
            or type(FileMgr.WriteFileContent) ~= "function" then return false end

        local existsOk, exists = pcall(FileMgr.DoesFileExist, path)
        if not existsOk or type(exists) ~= "boolean" then return false end
        local previousOk, previous = true, ""
        if exists then previousOk, previous = pcall(FileMgr.ReadFileContent, path) end
        if previousOk and previous == value then return true end
        -- Do not overwrite an existing cache that cannot be read.
        if not previousOk then
            return false
        elseif previous == nil then
            previous = ""
        elseif type(previous) ~= "string" or #previous > 4096 then
            return false
        end

        local wrote, result = pcall(FileMgr.WriteFileContent, path, value, false)
        local checkOk, present = pcall(FileMgr.DoesFileExist, path)
        local readOk, saved = false, nil
        if checkOk and present == true then readOk, saved = pcall(FileMgr.ReadFileContent, path) end
        if wrote and result == true and readOk and saved == value then return true end
        -- Best-effort recovery of a previous cache after an interrupted write.
        -- Never log the key, the file contents, or an exception containing them.
        if not (checkOk and present == false and not exists)
            and (not readOk or saved ~= previous) then
            pcall(FileMgr.WriteFileContent, path, previous, false)
        end
        return false
    end
end

function FileManager:WriteFile(path, content)
    local success, err = pcall(function()
        return FileMgr.WriteFileContent(path, content)
    end)
    if not success then
        Logger:Error("FileManager", "Failed to write file: " .. tostring(err))
        return false
    end
    return success and err == true
end

function menu.clampUiSetting(value, min_value, max_value)
    value = tonumber(value) or min_value
    if value < min_value then return min_value end
    if value > max_value then return max_value end
    return value
end

function menu.loadOverlayWindowSettings(values, state, prefix, defaults, minWidth, maxWidth, minHeight, maxHeight)
    if type(state) ~= "table" then return end
    defaults = defaults or {}
    state.width = menu.clampUiSetting(values[prefix .. "Width"] or state.width or defaults.width or 440,
        minWidth or 320, maxWidth or 1200)
    state.height = menu.clampUiSetting(values[prefix .. "Height"] or state.height or defaults.height or 330,
        minHeight or 180, maxHeight or 900)
    state.fontScale = menu.clampUiSetting(values[prefix .. "Font"] or state.fontScale or defaults.fontScale or 1.0, 0.70, 1.50)
    local x, y = values[prefix .. "X"], values[prefix .. "Y"]
    if type(x) == "number" and x == x and x ~= math.huge and x ~= -math.huge then state.x = x end
    if type(y) == "number" and y == y and y ~= math.huge and y ~= -math.huge then state.y = y end
    state.minimized = values[prefix .. "Minimized"] == 1
end

function menu.appendOverlayWindowSettings(lines, prefix, state, defaults)
    state, defaults = state or {}, defaults or {}
    lines[#lines + 1] = string.format("%sWidth=%.0f", prefix, state.width or defaults.width or 440)
    lines[#lines + 1] = string.format("%sHeight=%.0f", prefix, state.height or defaults.height or 330)
    lines[#lines + 1] = string.format("%sFont=%.2f", prefix, state.fontScale or defaults.fontScale or 1.0)
    lines[#lines + 1] = string.format("%sX=%.0f", prefix, state.x or -1)
    lines[#lines + 1] = string.format("%sY=%.0f", prefix, state.y or -1)
    lines[#lines + 1] = string.format("%sMinimized=%.0f", prefix, state.minimized and 1 or 0)
end

function menu.resetOverlayWindow(state, defaults)
    if type(state) ~= "table" then return end
    defaults = defaults or {}
    state.x, state.y = defaults.x, defaults.y
    state.width, state.height = defaults.width or 440, defaults.height or 330
    state.fontScale = defaults.fontScale or 1.0
    state.minimized = false
end

function menu.bindOverlayWindowSettings(prefix, label, state, groupId, minWidth, maxWidth, minHeight, maxHeight)
    if type(state) ~= "table" then return end
    menu.ui.items[prefix .. "Width"] = menu.slider(label .. " width", "Adjust " .. label .. " window width", groupId,
        minWidth, maxWidth, state.width, "%.0f", 0, function(value)
            state.width = math.max(minWidth, math.min(maxWidth, math.floor(tonumber(value) or state.width)))
            menu.queueUiSettingsSave()
        end)
    menu.ui.items[prefix .. "Height"] = menu.slider(label .. " height", "Adjust " .. label .. " window height", groupId,
        minHeight, maxHeight, state.height, "%.0f", 0, function(value)
            state.height = math.max(minHeight, math.min(maxHeight, math.floor(tonumber(value) or state.height)))
            menu.queueUiSettingsSave()
        end)
    menu.ui.items[prefix .. "Font"] = menu.slider(label .. " font", "Adjust " .. label .. " window font", groupId,
        0.70, 1.50, state.fontScale, "%.2f", 0, function(value)
            state.fontScale = math.max(0.70, math.min(1.50, tonumber(value) or state.fontScale))
            menu.queueUiSettingsSave()
        end)
end

function menu.syncOverlayWindowItems(items, prefix, state)
    if type(state) ~= "table" then return end
    if items[prefix .. "Width"] then items[prefix .. "Width"].value = state.width end
    if items[prefix .. "Height"] then items[prefix .. "Height"].value = state.height end
    if items[prefix .. "Font"] then items[prefix .. "Font"].value = state.fontScale end
end

menu.featureSettings = {entries = {}, order = {}, pending = {}, derived = {}, revisions = {},
    waiting = {}, waitingCount = 0, generation = 0, cursor = 1, restoring = false, failed = 0, dispatches = {},
    queuedCount = 0, activeCount = 0, scanComplete = false, dispatchTimeout = 15}

function menu.setFeatureRestoreStatus(phase)
    local state = menu.featureSettings
    if phase == "restoring" and state.scanComplete and state.queuedCount > 0 then phase = "waiting_jobs" end
    if state.phase == phase and state.statusQueued == state.queuedCount
        and state.statusActive == state.activeCount and state.statusFailed == state.failed then return end
    state.phase = phase
    state.statusQueued, state.statusActive, state.statusFailed = state.queuedCount, state.activeCount, state.failed
    local labels = {loaded = "Loaded", waiting_login = "Waiting for login", waiting_player = "Waiting for character",
        restoring = "Restoring", waiting_jobs = "Waiting for restore task", active = "Restore task started",
        ready = "Restored", partial = "Some features could not be restored", saved = "Saved"}
    local item = menu.ui.items and menu.ui.items.featureRestoreStatus
    if item then item.sourceLabel = "Feature configuration: " .. (labels[phase] or phase); item.label = menu.canonicalEnglish(item.sourceLabel) end
end

function menu.refreshFeatureRestoreStatus()
    local state = menu.featureSettings
    if not state.scanComplete then return end
    state.restoring = state.queuedCount > 0 or (state.waitingCount or 0) > 0
    local phase = state.queuedCount > 0 and "waiting_jobs"
        or ((state.waitingCount or 0) > 0 and "waiting_login"
        or (state.failed > 0 and "partial" or (state.activeCount > 0 and "active" or "ready")))
    menu.setFeatureRestoreStatus(phase)
    if not state.restoring and state.failed > (state.reportedFailures or 0) then
        state.reportedFailures = state.failed
        menu.notify("SovereignLua", "Some feature settings could not be restored", 4.0, "warning")
    end
end

function menu.releaseFeatureRestoreDispatch(key, token)
    local state = menu.featureSettings
    if state.dispatches[key] ~= token then return end
    if token.phase == "queued" then state.queuedCount = state.queuedCount - 1
    elseif token.phase == "active" then state.activeCount = state.activeCount - 1 end
    state.dispatches[key] = nil
    token.phase = "finished"
end

function menu.cancelFeatureRestore(key)
    local state = menu.featureSettings
    state.pending[key] = nil
    if state.waiting[key] then
        state.waiting[key] = nil
        state.waitingCount = math.max(0, (state.waitingCount or 0) - 1)
    end
    state.revisions[key] = (state.revisions[key] or 0) + 1
    local token = state.dispatches[key]
    if token then menu.releaseFeatureRestoreDispatch(key, token) end
    menu.refreshFeatureRestoreStatus()
end

function menu.queueFeatureRestore(key, value, dispatch, apply, ready)
    local state = menu.featureSettings
    local generation, revision = state.generation, state.revisions[key]
    local token = {phase = "queued", queuedAt = os.time()}
    local existing = state.dispatches[key]
    if existing then menu.releaseFeatureRestoreDispatch(key, existing) end
    state.dispatches[key] = token
    state.queuedCount = state.queuedCount + 1
    local function current()
        return state.generation == generation and state.revisions[key] == revision
            and state.dispatches[key] == token
    end
    local dispatched, queued = pcall(dispatch, function()
        if not current() then return end
        if state.pending[key] == nil then
            menu.releaseFeatureRestoreDispatch(key, token)
            menu.refreshFeatureRestoreStatus()
            return
        end
        state.queuedCount, state.activeCount = state.queuedCount - 1, state.activeCount + 1
        token.phase = "active"
        state.pending[key] = nil
        -- Persistent callbacks may yield for the entire enabled lifetime. They
        -- count as started, not as scheduler work the startup loop must await.
        menu.refreshFeatureRestoreStatus()
        if ready then
            local readyOk, readyValue = pcall(ready)
            if not readyOk or readyValue ~= true then
                state.pending[key] = value
                if not state.waiting[key] then
                    state.waiting[key] = true
                    state.waitingCount = (state.waitingCount or 0) + 1
                end
                menu.releaseFeatureRestoreDispatch(key, token)
                menu.refreshFeatureRestoreStatus()
                return
            end
        end
        local ok, result, detail = pcall(apply, value, current)
        if not current() then return end
        menu.releaseFeatureRestoreDispatch(key, token)
        local deferred = ok and result == false and (
            detail == "auth_required" or detail == "invalid_lease"
            or detail == "lease_expired" or detail == "lease_pending")
        if deferred then
            state.pending[key] = value
            if not state.waiting[key] then
                state.waiting[key] = true
                state.waitingCount = (state.waitingCount or 0) + 1
            end
        elseif not ok or result == false then
            state.pending[key] = value
            state.failed = state.failed + 1
            local reason = not ok and tostring(result)
                or tostring(detail or "callback_returned_false")
            local entry = state.entries[key]
            local featureName = entry and entry.item
                and (entry.item.sourceLabel or entry.item.label) or "unknown"
            if Logger and Logger.Error then
                Logger:Error("SovereignConfig", "async restore failed: " .. key
                    .. " feature=" .. tostring(featureName) .. " reason=" .. reason)
            end
        end
        menu.syncFeatureToggleItems()
        menu.refreshFeatureRestoreStatus()
    end)
    if not dispatched or not queued then
        menu.releaseFeatureRestoreDispatch(key, token)
        return false
    end
    return "queued"
end

function menu.syncFeatureToggleItems()
    for _, entry in pairs(menu.featureSettings.entries) do entry.item.value = entry.read() == true end
    for _, entry in ipairs(menu.featureSettings.derived) do entry.item.value = entry.read() == true end
end

function menu.bindFeatureToggle(item, key, readValue, restoreValue, restoreReady)
    if not item or item.type ~= "toggle" or item.player_bind or item.playerScoped then return item end
    assert(type(key) == "string" and key:match("^[%w_]+$") and #key <= 96, "invalid feature config key")
    local state = menu.featureSettings
    assert(state.entries[key] == nil, "duplicate feature config key: " .. key)
    local callback = item.callback
    local entry = {item = item, read = readValue or function() return item.value == true end,
        ready = restoreReady}
    entry.restore = restoreValue or function(value)
        item.value = value
        if callback then return callback(value) end
        return true
    end
    item.callback = function(...)
        -- A user change supersedes any startup value still waiting to restore.
        menu.cancelFeatureRestore(key)
        local result = callback and callback(...)
        menu.syncFeatureToggleItems()
        return result
    end
    item.value = entry.read() == true
    item.featureConfigKey = key
    state.entries[key] = entry
    state.order[#state.order + 1] = key
    return item
end

function menu.appendFeatureSettings(lines)
    local state = menu.featureSettings
    local values, keys = {}, {}
    for key, value in pairs(state.pending) do values[key] = value end
    for _, key in ipairs(state.order) do
        if values[key] == nil then values[key] = state.entries[key].read() == true end
    end
    for key in pairs(values) do keys[#keys + 1] = key end
    table.sort(keys)
    for _, key in ipairs(keys) do
        lines[#lines + 1] = "feature_" .. key .. "=" .. (values[key] and "1" or "0")
    end
end

function menu.loadFeatureSettings(values)
    local state = menu.featureSettings
    state.pending = {}
    state.generation = state.generation + 1
    state.dispatches = {}
    state.queuedCount, state.activeCount = 0, 0
    state.scanComplete, state.reportedFailures = false, 0
    state.waiting, state.waitingCount = {}, 0
    state.statusMessage = nil
    for key, value in pairs(values) do
        local featureKey = key:match("^feature_([%w_]+)$")
        if featureKey and featureKey ~= "window_task_console" then state.pending[featureKey] = value == 1 end
    end
    state.cursor, state.restoring, state.failed = 1, true, 0
    menu.setFeatureRestoreStatus("loaded")
end

function menu.restoreFeatureSettingsStep()
    local state = menu.featureSettings
    if not state.restoring then return end
    -- A paid toggle loaded before login is deferred, not failed. Once the
    -- session becomes valid, restart the small bounded scan and let the
    -- normal restore callback run exactly once for each pending feature.
    if state.scanComplete and (state.waitingCount or 0) > 0 then
        local ready = true
        for waitingKey in pairs(state.waiting) do
            local waitingEntry = state.entries[waitingKey]
            if waitingEntry and waitingEntry.ready then
                local readyOk, readyValue = pcall(waitingEntry.ready)
                if not readyOk or readyValue ~= true then ready = false; break end
            end
        end
        if ready then
            state.cursor, state.scanComplete = 1, false
        else
            menu.setFeatureRestoreStatus("waiting_login")
            return
        end
    end
    -- One callback per runtime tick bounds startup work; nothing is scanned at idle.
    local key = state.order[state.cursor]
    if not key then
        state.scanComplete = true
        local now = os.time()
        for queuedKey, token in pairs(state.dispatches) do
            if token.phase == "queued" and now - token.queuedAt >= state.dispatchTimeout then
                menu.releaseFeatureRestoreDispatch(queuedKey, token)
                state.failed = state.failed + 1
                if Logger and Logger.Error then Logger:Error("SovereignConfig", "restore queue timeout: " .. queuedKey) end
            end
        end
        menu.refreshFeatureRestoreStatus()
        return
    end
    state.cursor = state.cursor + 1
    local target = state.pending[key]
    if target == nil then return end
    local entry = state.entries[key]
    if not entry then
        state.failed = state.failed + 1
        if Logger and Logger.Error then
            Logger:Error("SovereignConfig", "restore failed: " .. key .. " reason=feature_not_registered")
        end
        return
    end
    if entry.ready then
        local readyOk, readyValue = pcall(entry.ready)
        if not readyOk or readyValue ~= true then
            if not state.waiting[key] then
                state.waiting[key] = true
                state.waitingCount = (state.waitingCount or 0) + 1
            end
            menu.setFeatureRestoreStatus("waiting_login")
            return
        end
    end
    if state.waiting[key] then
        state.waiting[key] = nil
        state.waitingCount = math.max(0, (state.waitingCount or 0) - 1)
    end
    local ok, result, detail = pcall(function()
        if entry.read() == target then return true end
        return entry.restore(target)
    end)
    local deferred = ok and result == false and (
        detail == "auth_required" or detail == "invalid_lease"
        or detail == "lease_expired" or detail == "lease_pending")
    if deferred then
        state.pending[key] = target
        if not state.waiting[key] then
            state.waiting[key] = true
            state.waitingCount = (state.waitingCount or 0) + 1
        end
    elseif not ok or result == false then
        state.failed = state.failed + 1
        local reason = not ok and tostring(result)
            or tostring(detail or "callback_returned_false")
        local featureName = entry.item and (entry.item.sourceLabel or entry.item.label) or "unknown"
        if Logger and Logger.Error then
            Logger:Error("SovereignConfig", "restore failed: " .. key
                .. " feature=" .. tostring(featureName) .. " reason=" .. reason)
        end
    end
    menu.syncFeatureToggleItems()
    -- Keep unavailable/removed feature values for a later compatible runtime.
    if ok and result ~= false and result ~= "queued" then state.pending[key] = nil end
end

function menu.loadUiSettings()
    if menu.ui.configLoaded then
        return true
    end

    local values = {}
    local ok, content = pcall(function()
        if not FileMgr.DoesFileExist(CONFIG.PATHS.UIConfigFile) then
            return ""
        end
        local result = FileMgr.ReadFileContent(CONFIG.PATHS.UIConfigFile)
        if type(result) ~= "string" then error("ui_config_read_failed") end
        return result
    end)
    if not ok or type(content) ~= "string" then return false end
    if content ~= "" then
        local _, reason, parsed = menu.parseUiSettingsContent(content)
        if not parsed then
            menu.ui.lastSaveError = reason or "invalid_content"
            return false
        end
        values = parsed
    end
    local avatarPath = menu.decodeConfigString(values.avatarPathHex or "")
    if avatarPath == nil or not menu.isSupportedImagePath(avatarPath) then avatarPath = "" end

    menu.ui.width = menu.clampUiSetting(values.width or menu.ui.defaults.width, 820, 1600)
    menu.ui.height = menu.clampUiSetting(values.height or menu.ui.defaults.height, 440, 1000)
    menu.ui.fontScale = menu.clampUiSetting(values.fontScale or menu.ui.defaults.fontScale, 0.70, 1.60)
    for _, field in ipairs(menu.appearanceSettings or {}) do
        menu.ui[field.key] = math.floor(menu.clampUiSetting(values[field.key] or field.default, field.min, field.max) + 0.5)
    end
    menu.ui.sidebarGap = menu.clampUiSetting(values.sidebarGap or menu.ui.defaults.sidebarGap, 3, 40)
    menu.ui.subtabGap = menu.clampUiSetting(values.subtabGap or menu.ui.defaults.subtabGap, 4, 32)
    menu.ui.itemGap = menu.clampUiSetting(values.itemGap or menu.ui.defaults.itemGap, 0, 20)
    menu.ui.groupGap = menu.clampUiSetting(values.groupGap or menu.ui.defaults.groupGap, 6, 36)
    menu.ui.sidebarWidth = menu.clampUiSetting(values.sidebarWidth or menu.ui.defaults.sidebarWidth, 150, 280)
    menu.ui.columns = math.floor(menu.clampUiSetting(values.columns or menu.ui.defaults.columns, 1, 2) + 0.5)
    menu.ui.splitLongGroups = values.splitLongGroups == 0 and 0 or 1
    menu.ui.showPlayerInfo = values.showPlayerInfo == 0 and 0 or 1
    menu.ui.rgbBorder = values.rgbBorder == 0 and 0 or 1
    menu.ui.rgbSpeed = menu.clampUiSetting(values.rgbSpeed or menu.ui.defaults.rgbSpeed, 0.10, 3.00)
    menu.ui.rgbGlow = menu.clampUiSetting(values.rgbGlow or menu.ui.defaults.rgbGlow, 0, 100)
    menu.ui.rgbThickness = menu.clampUiSetting(values.rgbThickness or menu.ui.defaults.rgbThickness, 1.0, 6.0)
    menu.ui.rgbDensity = math.floor(menu.clampUiSetting(values.rgbDensity or menu.ui.defaults.rgbDensity, 1, 8) + 0.5)
    menu.ui.brightness = menu.clampUiSetting(values.brightness or menu.ui.defaults.brightness, 25, 100)
    menu.ui.notificationLimit = math.floor(menu.clampUiSetting(values.notificationLimit or menu.ui.defaults.notificationLimit, 1, 8) + 0.5)
    menu.ui.notificationDedupe = values.notificationDedupe == 0 and 0 or 1
    menu.ui.notificationPosition = math.floor(menu.clampUiSetting(values.notificationPosition or menu.ui.defaults.notificationPosition, 1, 4) + 0.5)
    menu.ui.notificationWidth = math.floor(menu.clampUiSetting(values.notificationWidth or menu.ui.defaults.notificationWidth, 260, 520) + 0.5)
    menu.ui.notificationDurationScale = math.floor(menu.clampUiSetting(values.notificationDurationScale or menu.ui.defaults.notificationDurationScale, 50, 200) + 0.5)
    menu.ui.poolWarningPercent = math.floor(menu.clampUiSetting(values.poolWarningPercent or 90, 10, 95) + 0.5)
    menu.ui.streetPunchBlastSize = math.floor(menu.clampUiSetting(values.streetPunchBlastSize or 18, 8, 30) + 0.5)
    menu.ui.targetShotSelection = math.floor(menu.clampUiSetting(values.targetShotSelection or 2, 1, 2) + 0.5)
    menu.ui.targetShotBackend = 1 -- R57 removes the event selector, including imported R56 presets.
    menu.ui.targetShotBone = math.floor(menu.clampUiSetting(values.targetShotBone or 1, 1, 2) + 0.5)
    menu.ui.targetShotFov = math.floor(menu.clampUiSetting(values.targetShotFov or 180, 30, 360) + 0.5)
    menu.ui.themePreset = math.floor(menu.clampUiSetting(values.themePreset or menu.ui.defaults.themePreset, 1, 7) + 0.5)
    for _, prefix in ipairs(menu.themeColorFields) do
        for _, channel in ipairs({"R", "G", "B"}) do
            local key = prefix .. channel
            menu.ui[key] = math.floor(menu.clampUiSetting(values[key] or menu.ui.defaults[key], 0, 255) + 0.5)
        end
    end
    for _, role in ipairs(menu.extendedThemeRoles or {}) do
        if role[2] then
            for _, channel in ipairs({"R", "G", "B"}) do
                local key = role[1] .. channel
                if values[key] == nil then menu.ui[key] = menu.ui[role[2] .. channel] end
            end
        end
    end
    menu.ui.performanceProfile = math.floor(menu.clampUiSetting(values.performanceProfile or menu.ui.defaults.performanceProfile, 1, 3) + 0.5)
    menu.ui.backdropBlur = (values.backdropBlur or menu.ui.defaults.backdropBlur) == 0 and 0 or 1
    menu.ui.backdropDim = math.floor(menu.clampUiSetting(values.backdropDim or menu.ui.defaults.backdropDim, 0, 80) + 0.5)
    menu.ui.cursorStyle = math.floor(menu.clampUiSetting(values.cursorStyle or menu.ui.defaults.cursorStyle, 2, 6) + 0.5)
    menu.ui.cursorSize = menu.clampUiSetting(values.cursorSize or menu.ui.defaults.cursorSize, 0.75, 1.75)
    menu.ui.toggleGlow = menu.clampUiSetting(values.toggleGlow or menu.ui.defaults.toggleGlow, 0, 100)
    menu.ui.animationSpeed = menu.clampUiSetting(values.animationSpeed or menu.ui.defaults.animationSpeed, 50, 160)
    menu.ui.tooltipOpacity = menu.clampUiSetting(values.tooltipOpacity or menu.ui.defaults.tooltipOpacity, 70, 100)
    menu.ui.notificationOpacity = menu.clampUiSetting(values.notificationOpacity or menu.ui.defaults.notificationOpacity, 70, 100)
    menu.ui.avatarEnabled = values.avatarEnabled == 0 and 0 or 1
    menu.ui.avatarPath = avatarPath
    menu.ui.avatarPathPending = avatarPath
    if SovereignBusinessInventory and SovereignBusinessInventory.window then
        local window = SovereignBusinessInventory.window
        window.width = menu.clampUiSetting(values.inventoryWindowWidth or window.width or 700, 560, 1100)
        window.height = menu.clampUiSetting(values.inventoryWindowHeight or window.height or 560, 400, 760)
        window.fontScale = menu.clampUiSetting(values.inventoryWindowFont or window.fontScale or 1.0, 0.70, 1.50)
        if type(values.inventoryWindowX) == "number" and math.abs(values.inventoryWindowX) < math.huge then
            window.x = values.inventoryWindowX
            window.anchorRight = false
        end
        if values.inventoryWindowY and values.inventoryWindowY >= 0 then window.y = values.inventoryWindowY end
        window.minimized = values.inventoryWindowMinimized == 1
    end
    if TravellerMigration and TravellerMigration.window then
        local window = TravellerMigration.window
        window.width = menu.clampUiSetting(values.overviewWindowWidth or window.width or 520, 320, 760)
        window.height = menu.clampUiSetting(values.overviewWindowHeight or window.height or 330, 220, 640)
        window.fontScale = menu.clampUiSetting(values.overviewWindowFont or window.fontScale or 1.0, 0.70, 1.50)
        if type(values.overviewWindowX) == "number" and math.abs(values.overviewWindowX) < math.huge then window.x = values.overviewWindowX end
        if values.overviewWindowY and values.overviewWindowY >= 0 then window.y = values.overviewWindowY end
        window.minimized = values.overviewWindowMinimized == 1
    end
    menu.loadOverlayWindowSettings(values, SovereignStatusCenter and SovereignStatusCenter.window, "statusWindow",
        {x = 24, y = 420, width = 440, height = 330, fontScale = 1.0}, 320, 760, 220, 640)
    menu.loadOverlayWindowSettings(values, SovereignBattleNetworkStatus and SovereignBattleNetworkStatus.window, "battleNetworkWindow",
        {x = 430, y = 120, width = 560, height = 520, fontScale = 1.0}, 420, 900, 360, 760)
    menu.loadOverlayWindowSettings(values, menu.performanceWindowRef, "performanceWindow",
        {x = 480, y = 420, width = 520, height = 430, fontScale = 0.90}, 360, 900, 260, 760)
    menu.loadOverlayWindowSettings(values, menu.notificationHistoryWindow, "historyWindow",
        {x = 24, y = 760, width = 560, height = 340, fontScale = 0.90}, 360, 900, 220, 700)
    menu.ui.sizeDirty = true
    local configuredHotkey = values.hotkeyCode
    if configuredHotkey == nil and values.hotkeyIndex ~= nil then
        local legacyCodes = {
            0x70, 0x71, 0x72, 0x73, 0x74, 0x75, 0x76, 0x77, 0x78, 0x79, 0x7A, 0x7B,
            0x2D, 0x2E, 0x24, 0x23, 0x21, 0x22
        }
        local legacyIndex = math.floor(tonumber(values.hotkeyIndex) or 4)
        configuredHotkey = legacyCodes[legacyIndex] or menu.ui.defaults.hotkeyCode
    end
    menu.ui.hotkeyCode = math.floor(menu.clampUiSetting(configuredHotkey or menu.ui.defaults.hotkeyCode, 1, 255) + 0.5)
    if menu.hotkeyRegistered and menu.applyToggleHotkey then
        if not menu.applyToggleHotkey(menu.ui.hotkeyCode) then return false end
    else
        menu.toggleKey = menu.ui.hotkeyCode
    end
    menu.applyAccentTheme()
    menu.loadFeatureSettings(values)
    menu.ui.configLoaded = true
    return ok
end

function menu.buildUiSettingsBody()
    local inventoryWindow = SovereignBusinessInventory and SovereignBusinessInventory.window or {}
    local overviewWindow = TravellerMigration and TravellerMigration.window or {}
    local lines = {
        string.format("width=%.0f", menu.ui.width),
        string.format("height=%.0f", menu.ui.height),
        string.format("fontScale=%.2f", menu.ui.fontScale),
        string.format("sidebarGap=%.0f", menu.ui.sidebarGap),
        string.format("subtabGap=%.0f", menu.ui.subtabGap),
        string.format("itemGap=%.0f", menu.ui.itemGap),
        string.format("groupGap=%.0f", menu.ui.groupGap),
        string.format("sidebarWidth=%.0f", menu.ui.sidebarWidth),
        string.format("columns=%.0f", menu.ui.columns),
        string.format("splitLongGroups=%.0f", menu.ui.splitLongGroups),
        string.format("showPlayerInfo=%.0f", menu.ui.showPlayerInfo),
        string.format("rgbBorder=%.0f", menu.ui.rgbBorder),
        string.format("rgbSpeed=%.2f", menu.ui.rgbSpeed),
        string.format("rgbGlow=%.0f", menu.ui.rgbGlow),
        string.format("rgbThickness=%.2f", menu.ui.rgbThickness),
        string.format("rgbDensity=%.0f", menu.ui.rgbDensity),
        string.format("brightness=%.0f", menu.ui.brightness),
        string.format("notificationLimit=%.0f", menu.ui.notificationLimit),
        string.format("notificationDedupe=%.0f", menu.ui.notificationDedupe),
        string.format("notificationPosition=%.0f", menu.ui.notificationPosition),
        string.format("notificationWidth=%.0f", menu.ui.notificationWidth),
        string.format("notificationDurationScale=%.0f", menu.ui.notificationDurationScale),
        string.format("poolWarningPercent=%.0f", menu.ui.poolWarningPercent or 90),
        string.format("streetPunchBlastSize=%.0f", menu.ui.streetPunchBlastSize or 18),
        string.format("targetShotSelection=%.0f", menu.ui.targetShotSelection or 2),
        "targetShotBackend=1",
        "r56TargetRouting=1",
        string.format("targetShotBone=%.0f", menu.ui.targetShotBone or 1),
        string.format("targetShotFov=%.0f", menu.ui.targetShotFov or 180),
        string.format("themePreset=%.0f", menu.ui.themePreset),
        string.format("performanceProfile=%.0f", menu.ui.performanceProfile),
        string.format("backdropBlur=%.0f", menu.ui.backdropBlur or 0),
        string.format("backdropDim=%.0f", menu.ui.backdropDim or 0),
        string.format("cursorStyle=%.0f", menu.ui.cursorStyle or 2),
        string.format("cursorSize=%.2f", menu.ui.cursorSize or 1.0),
        string.format("toggleGlow=%.0f", menu.ui.toggleGlow or 45),
        string.format("animationSpeed=%.0f", menu.ui.animationSpeed or 100),
        string.format("tooltipOpacity=%.0f", menu.ui.tooltipOpacity or 98),
        string.format("notificationOpacity=%.0f", menu.ui.notificationOpacity or 98),
        string.format("avatarEnabled=%.0f", menu.ui.avatarEnabled or 0),
        "avatarPathHex=" .. menu.encodeConfigString(menu.ui.avatarPath or ""),
        string.format("inventoryWindowWidth=%.0f", inventoryWindow.width or 700),
        string.format("inventoryWindowHeight=%.0f", inventoryWindow.height or 560),
        string.format("inventoryWindowFont=%.2f", inventoryWindow.fontScale or 1.0),
        string.format("inventoryWindowX=%.0f", inventoryWindow.x or -1),
        string.format("inventoryWindowY=%.0f", inventoryWindow.y or -1),
        string.format("inventoryWindowMinimized=%.0f", inventoryWindow.minimized and 1 or 0),
        string.format("overviewWindowWidth=%.0f", overviewWindow.width or 370),
        string.format("overviewWindowHeight=%.0f", overviewWindow.height or 313),
        string.format("overviewWindowFont=%.2f", overviewWindow.fontScale or 1.0),
        string.format("overviewWindowX=%.0f", overviewWindow.x or -1),
        string.format("overviewWindowY=%.0f", overviewWindow.y or -1),
        string.format("overviewWindowMinimized=%.0f", overviewWindow.minimized and 1 or 0),
        string.format("hotkeyCode=%.0f", menu.ui.hotkeyCode)
    }
    for _, prefix in ipairs(menu.themeColorFields) do
        for _, channel in ipairs({"R", "G", "B"}) do
            local key = prefix .. channel
            lines[#lines + 1] = string.format("%s=%.0f", key, menu.ui[key] or menu.ui.defaults[key])
        end
    end
    menu.appendOverlayWindowSettings(lines, "statusWindow", SovereignStatusCenter and SovereignStatusCenter.window,
        {width = 440, height = 330, fontScale = 1.0})
    menu.appendOverlayWindowSettings(lines, "battleNetworkWindow", SovereignBattleNetworkStatus and SovereignBattleNetworkStatus.window,
        {width = 560, height = 520, fontScale = 1.0})
    menu.appendOverlayWindowSettings(lines, "performanceWindow", menu.performanceWindowRef,
        {width = 520, height = 430, fontScale = 0.90})
    menu.appendOverlayWindowSettings(lines, "historyWindow", menu.notificationHistoryWindow,
        {width = 560, height = 340, fontScale = 0.90})
    menu.appendFeatureSettings(lines)
    for _, field in ipairs(menu.appearanceSettings or {}) do
        lines[#lines + 1] = field.key .. "=" .. tostring(menu.ui[field.key] or field.default)
    end
    return table.concat(lines, "\n") .. "\n"
end

function menu.writeUiSettingsVerified(path, body)
    if type(body) ~= "string" or not FileMgr
        or type(FileMgr.WriteFileContent) ~= "function"
        or type(FileMgr.ReadFileContent) ~= "function" then
        return false, "file_unavailable"
    end
    local writeOk, result = pcall(FileMgr.WriteFileContent, path, body, false)
    if not writeOk or result == false then return false, "write_failed" end
    local readOk, saved = pcall(FileMgr.ReadFileContent, path)
    if not readOk or type(saved) ~= "string" then return false, "read_failed" end
    if saved:gsub("\r\n", "\n") ~= body:gsub("\r\n", "\n") then return false, "verify_failed" end
    return true
end

function menu.saveUiSettings()
    -- Explicit/forced saves supersede any partially staged automatic snapshot.
    menu.uiAutoSave = nil
    local built, body = pcall(menu.buildUiSettingsBody)
    if not built or type(body) ~= "string" then
        menu.ui.savePending, menu.ui.lastSaveError = true, "build_failed"
        return false, "build_failed"
    end
    local path = CONFIG.PATHS.UIConfigFile
    local staged, reason = menu.writeUiSettingsVerified(path .. ".pending", body)
    if not staged then
        menu.ui.savePending, menu.ui.lastSaveError = true, reason
        return false, reason
    end
    local previousOk, previous = pcall(FileMgr.ReadFileContent, path)
    local saved
    saved, reason = menu.writeUiSettingsVerified(path, body)
    if not saved and previousOk and type(previous) == "string" and previous ~= "" then
        local restored = menu.writeUiSettingsVerified(path, previous)
        if not restored then reason = "rollback_failed" end
    end
    if saved and type(FileMgr.DeleteFile) == "function" then pcall(FileMgr.DeleteFile, path .. ".pending") end
    menu.ui.savePending = not saved
    menu.ui.lastSaveError = saved and nil or reason
    if saved then menu.ui.lastSavedAt = os.clock() end
    if saved then menu.setFeatureRestoreStatus("saved") end
    return saved, reason
end

-- Defined later with the runtime notification bridge. Forward-declare it so
-- hotkey callbacks capture the local function instead of looking up a global.
local SovereignNotify

function menu.saveUiSettingsExplicit()
    menu.enqueueAction("Save menu configuration", function()
        local ok = menu.saveUiSettings()
        if SovereignNotify then
            SovereignNotify("SovereignLua", ok and "Menu configuration saved, including feature toggles" or "Could not save configuration. Your changes are retained.", ok and "success" or "warning")
        end
    end)
end

function menu.applyToggleHotkey(keyCode)
    local normalized = tonumber(keyCode)
    if not normalized then
        return false
    end
    normalized = math.floor(normalized + 0.5)
    if normalized < 1 or normalized > 255 then
        return false
    end

    local previousToggle = menu.toggleKey
    local previousBound = menu.boundToggleKey
    local feature = menu.hotkeyFeature
    local applied = false
    local featureBindingChanged = false
    local managerBindingChanged = false
    if feature then
        if feature.ClearHotkeys and feature.AddHotKey then
            local clearOk, clearResult = pcall(function()
                return feature:ClearHotkeys()
            end)
            if clearOk and clearResult ~= false then
                featureBindingChanged = true
                local addOk, addResult = pcall(function()
                    return feature:AddHotKey(normalized)
                end)
                applied = addOk and addResult ~= false
            end
        elseif feature.RemoveHotkey and feature.AddHotKey then
            local ready = true
            if menu.boundToggleKey then
                local removeOk, removeResult = pcall(function()
                    return feature:RemoveHotkey(menu.boundToggleKey, true)
                end)
                ready = removeOk and removeResult ~= false
                featureBindingChanged = ready
            end
            if ready then
                local addOk, addResult = pcall(function()
                    return feature:AddHotKey(normalized)
                end)
                applied = addOk and addResult ~= false
            end
        end
    end

    if not applied and not featureBindingChanged and HotKeyMgr and HotKeyMgr.AddHotkey and menu.hotkeyHash then
        local ready = true
        if menu.boundToggleKey and HotKeyMgr.RemoveHotkey then
            local removeOk, removeResult = pcall(HotKeyMgr.RemoveHotkey, menu.hotkeyHash, menu.boundToggleKey)
            ready = removeOk and removeResult ~= false
            managerBindingChanged = ready
        end
        if ready then
            local addOk, addResult = pcall(HotKeyMgr.AddHotkey, menu.hotkeyHash, normalized)
            applied = addOk and addResult ~= false
        end
    end

    if applied then
        menu.toggleKey = normalized
        menu.boundToggleKey = normalized
        return true
    end

    if previousBound and featureBindingChanged and feature and feature.AddHotKey then
        pcall(function()
            return feature:AddHotKey(previousBound)
        end)
    end
    if previousBound and managerBindingChanged and HotKeyMgr and HotKeyMgr.AddHotkey and menu.hotkeyHash then
        pcall(HotKeyMgr.AddHotkey, menu.hotkeyHash, previousBound)
    end
    menu.toggleKey = previousToggle
    menu.boundToggleKey = previousBound
    return false
end

function menu.parseVirtualKey(value)
    local raw = tostring(value or ""):match("^%s*(.-)%s*$")
    if raw == "" then
        return nil
    end
    local keyCode = nil
    if raw:match("^0[xX][%x]+$") then
        keyCode = tonumber(raw:sub(3), 16)
    elseif raw:match("^%d+$") then
        keyCode = tonumber(raw)
    end
    if not keyCode then
        return nil
    end
    keyCode = math.floor(keyCode + 0.5)
    if keyCode < 1 or keyCode > 255 then
        return nil
    end
    return keyCode
end

function menu.getKeyboardHotkeyOptions()
    if menu.keyboardHotkeyCodes and menu.keyboardHotkeyLabels then
        return menu.keyboardHotkeyCodes, menu.keyboardHotkeyLabels
    end

    local codes, labels = {}, {}
    local function add(code, label)
        codes[#codes + 1] = code
        labels[#labels + 1] = label
    end

    for code = 0x70, 0x87 do add(code, "F" .. tostring(code - 0x6F)) end
    for code = 0x41, 0x5A do add(code, string.char(code)) end
    for code = 0x30, 0x39 do add(code, string.char(code)) end
    for code = 0x60, 0x69 do add(code, "Numpad " .. tostring(code - 0x60)) end

    local named = {
        {0x08, "Backspace"}, {0x09, "Tab"}, {0x0C, "Clear"}, {0x0D, "Enter"},
        {0x10, "Shift"}, {0x11, "Ctrl"}, {0x12, "Alt"}, {0x13, "Pause"},
        {0x14, "Caps Lock"}, {0x1B, "Esc"}, {0x20, "Space"},
        {0x21, "Page Up"}, {0x22, "Page Down"}, {0x23, "End"}, {0x24, "Home"},
        {0x25, "Left arrow"}, {0x26, "Up arrow"}, {0x27, "Right arrow"}, {0x28, "Down arrow"},
        {0x29, "Select"}, {0x2A, "Print"}, {0x2B, "Execute"}, {0x2C, "Print Screen"},
        {0x2D, "Insert"}, {0x2E, "Delete"}, {0x2F, "Help"},
        {0x5B, "Left Win"}, {0x5C, "Right Win"}, {0x5D, "Menu key"}, {0x5F, "Sleep"},
        {0x6A, "Numpad *"}, {0x6B, "Numpad +"}, {0x6C, "Numpad separator"},
        {0x6D, "Numpad -"}, {0x6E, "Numpad ."}, {0x6F, "Numpad /"},
        {0x90, "Num Lock"}, {0x91, "Scroll Lock"},
        {0xA0, "Left Shift"}, {0xA1, "Right Shift"}, {0xA2, "Left Ctrl"},
        {0xA3, "Right Ctrl"}, {0xA4, "Left Alt"}, {0xA5, "Right Alt"},
        {0xA6, "Browser back"}, {0xA7, "Browser forward"}, {0xA8, "Browser refresh"},
        {0xA9, "Browser stop"}, {0xAA, "Browser search"}, {0xAB, "Browser favorites"},
        {0xAC, "Browser home"}, {0xAD, "Mute"}, {0xAE, "Volume down"}, {0xAF, "Volume up"},
        {0xB0, "Next track"}, {0xB1, "Previous track"}, {0xB2, "Stop playback"},
        {0xB3, "Play / pause"}, {0xB4, "Mail"}, {0xB5, "Select media"},
        {0xB6, "Application 1"}, {0xB7, "Application 2"},
        {0xBA, ";"}, {0xBB, "="}, {0xBC, ","}, {0xBD, "-"}, {0xBE, "."},
        {0xBF, "/"}, {0xC0, "`"}, {0xDB, "["}, {0xDC, "\\"}, {0xDD, "]"}, {0xDE, "'"}
    }
    for _, entry in ipairs(named) do add(entry[1], entry[2]) end

    menu.keyboardHotkeyCodes = codes
    menu.keyboardHotkeyLabels = labels
    return codes, labels
end

function menu.findKeyboardHotkeyIndex(keyCode)
    keyCode = math.floor(tonumber(keyCode) or 0)
    local codes = menu.getKeyboardHotkeyOptions()
    for index, code in ipairs(codes) do
        if code == keyCode then return index end
    end
    return 1
end

function menu.getVirtualKeyName(keyCode)
    keyCode = math.floor(tonumber(keyCode) or 0)
    local codes, labels = menu.getKeyboardHotkeyOptions()
    for index, code in ipairs(codes) do
        if code == keyCode then return labels[index] end
    end
    return string.format("VK %d", keyCode)
end

function menu.updateHotkeyStatus()
    local item = menu.ui.items and menu.ui.items.hotkeyStatus
    if item then
        item.sourceLabel = "Menu key: " .. menu.getVirtualKeyName(menu.ui.hotkeyCode); item.label = menu.canonicalEnglish(item.sourceLabel)
    end
    local selector = menu.ui.items and menu.ui.items.hotkeySelector
    if selector then
        selector.value = menu.findKeyboardHotkeyIndex(menu.ui.hotkeyCode)
    end
end

function menu.commitToggleHotkey(keyCode, notifyUser)
    keyCode = menu.parseVirtualKey(keyCode)
    if not keyCode or not menu.applyToggleHotkey(keyCode) then
        if notifyUser then
            SovereignNotify("SovereignLua", "Could not set the key. Please record it again.", "warning")
        end
        return false
    end
    menu.ui.hotkeyCode = keyCode
    if menu.ui.items and menu.ui.items.hotkeyCode then
        menu.ui.items.hotkeyCode.value = tostring(keyCode)
    end
    menu.updateHotkeyStatus()
    menu.queueUiSettingsSave()
    if notifyUser then
        SovereignNotify("SovereignLua", "Menu key set to " .. menu.getVirtualKeyName(keyCode), "success")
    end
    return true
end

function menu.startHotkeyCapture()
    menu.hotkeyCaptureActive = true
    menu.hotkeyCaptureReady = false
    menu.hotkeyCaptureArmFrames = 2
    SovereignNotify("SovereignLua", "Press the new menu key", "info")
end

function menu.pollHotkeyCapture()
    if not menu.hotkeyCaptureActive then
        return
    end
    local hasUtilsDown = Utils and Utils.IsKeyDown
    local hasUtilsPressed = Utils and Utils.IsKeyPressed
    local hasImGuiPressed = ImGui and ImGui.IsKeyPressed
    if not menu.interactive or (not hasUtilsDown and not hasUtilsPressed and not hasImGuiPressed) then
        menu.hotkeyCaptureActive = false
        menu.hotkeyCaptureReady = false
        menu.hotkeyCaptureArmFrames = 0
        return
    end

    if (menu.hotkeyCaptureArmFrames or 0) > 0 then
        menu.hotkeyCaptureArmFrames = menu.hotkeyCaptureArmFrames - 1
        return
    end

    if not menu.hotkeyCaptureReady then
        local mouseDown = false
        if hasUtilsDown then
            for keyCode = 1, 6 do
                local ok, down = pcall(Utils.IsKeyDown, keyCode)
                if ok and down then
                    mouseDown = true
                    break
                end
            end
        end
        if mouseDown then
            return
        end
        menu.hotkeyCaptureReady = true
        return
    end

    -- Mouse buttons are deliberately excluded; gameplay clicks must never
    -- become the menu hotkey.
    for keyCode = 7, 255 do
        local detected = false
        if hasUtilsDown then
            local ok, down = pcall(Utils.IsKeyDown, keyCode)
            detected = ok and down and true or false
        end
        if not detected and hasUtilsPressed then
            local ok, pressed = pcall(Utils.IsKeyPressed, keyCode)
            detected = ok and pressed and true or false
        end
        if not detected and hasImGuiPressed then
            local ok, pressed = pcall(ImGui.IsKeyPressed, keyCode)
            detected = ok and pressed and true or false
        end
        if detected then
            menu.hotkeyCaptureActive = false
            menu.hotkeyCaptureReady = false
            menu.hotkeyCaptureArmFrames = 0
            menu.commitToggleHotkey(keyCode, true)
            return
        end
    end
end

menu.isVirtualKeyDown = LPH_NO_VIRTUALIZE(function(keyCode)
    if Utils and type(Utils.IsKeyDown) == "function" then
        local ok, down = pcall(Utils.IsKeyDown, keyCode)
        if ok then return down == true end
    end
    return false
end)

menu.wasVirtualKeyPressed = LPH_NO_VIRTUALIZE(function(keyCode)
    if Utils and type(Utils.IsKeyPressed) == "function" then
        local ok, pressed = pcall(Utils.IsKeyPressed, keyCode)
        if ok then return pressed == true end
    end
    menu.shortcutKeyState = menu.shortcutKeyState or {}
    local down = menu.isVirtualKeyDown(keyCode)
    local wasDown = menu.shortcutKeyState[keyCode] == true
    menu.shortcutKeyState[keyCode] = down
    return down and not wasDown
end)

function menu.openGlobalSearch()
    if not menu.ui.quickTab or not menu.ui.quickSubtab then return false end
    if menu.comboModalItem and menu.comboModalItem.is_open == true then
        menu.comboModalItem.is_open = false
        menu.refreshComboModalState()
    end
    menu.activeTab = menu.ui.quickTab
    menu.activeSubtab = menu.ui.quickSubtab
    menu.searchText = ""
    menu.focusSearchNext = true
    if menu.quick then
        menu.quick.searchQuery = nil
        menu.quick.searchDirty = true
    end
    return true
end

menu.processKeyboardShortcuts = LPH_NO_VIRTUALIZE(function()
    if not menu.interactive then return end
    if menu.hotkeyCaptureActive then
        if menu.wasVirtualKeyPressed(0x1B) then
            menu.hotkeyCaptureActive = false
            menu.hotkeyCaptureReady = false
            menu.hotkeyCaptureArmFrames = 0
            SovereignNotify("SovereignLua", "Key recording canceled", "info")
        end
        return
    end
    local ctrlDown = menu.isVirtualKeyDown(0x11)
        or menu.isVirtualKeyDown(0xA2)
        or menu.isVirtualKeyDown(0xA3)
    if ctrlDown and menu.wasVirtualKeyPressed(0x46) then
        menu.openGlobalSearch()
        return
    end
    if menu.wasVirtualKeyPressed(0x1B) then
        if menu.comboModalItem and menu.comboModalItem.is_open == true then
            menu.comboModalItem.is_open = false
            menu.refreshComboModalState()
        else
            menu.setOpen(false)
        end
    end
end)

