function menu.syncUiSettingItems()
    for _, field in ipairs(menu.appearanceSettings or {}) do
        local item = menu.ui.items and menu.ui.items[field.key]
        if item then
            if field.toggle then item.value = menu.ui[field.key] ~= 0
            else item.value = menu.ui[field.key] end
        end
    end
    local items = menu.ui.items or {}
    local directValues = {
        width = menu.ui.width, height = menu.ui.height, fontScale = menu.ui.fontScale,
        brightness = menu.ui.brightness, sidebarWidth = menu.ui.sidebarWidth,
        sidebarGap = menu.ui.sidebarGap, subtabGap = menu.ui.subtabGap,
        itemGap = menu.ui.itemGap, groupGap = menu.ui.groupGap,
        columns = menu.ui.columns, rgbSpeed = menu.ui.rgbSpeed,
        rgbGlow = menu.ui.rgbGlow, rgbThickness = menu.ui.rgbThickness,
        rgbDensity = menu.ui.rgbDensity, notificationLimit = menu.ui.notificationLimit,
        notificationWidth = menu.ui.notificationWidth,
        notificationDurationScale = menu.ui.notificationDurationScale,
        poolWarningPercent = menu.ui.poolWarningPercent,
        streetPunchBlastSize = menu.ui.streetPunchBlastSize,
        targetShotSelection = menu.ui.targetShotSelection, targetShotBackend = 1, r56TargetRouting = 1,
        targetShotBone = menu.ui.targetShotBone, targetShotFov = menu.ui.targetShotFov,
        backdropDim = menu.ui.backdropDim, cursorStyle = (menu.ui.cursorStyle or 2) - 1,
        cursorSize = menu.ui.cursorSize, toggleGlow = menu.ui.toggleGlow,
        animationSpeed = menu.ui.animationSpeed, tooltipOpacity = menu.ui.tooltipOpacity,
        notificationOpacity = menu.ui.notificationOpacity
    }
    for key, value in pairs(directValues) do
        if items[key] then items[key].value = value end
    end
    if items.splitLongGroups then items.splitLongGroups.value = menu.ui.splitLongGroups ~= 0 end
    if items.showPlayerInfo then items.showPlayerInfo.value = menu.ui.showPlayerInfo ~= 0 end
    if items.rgbBorder then items.rgbBorder.value = menu.ui.rgbBorder ~= 0 end
    if items.backdropBlur then items.backdropBlur.value = menu.ui.backdropBlur ~= 0 end
    if items.avatarEnabled then items.avatarEnabled.value = menu.ui.avatarEnabled ~= 0 end
    if items.avatarPath then items.avatarPath.value = menu.ui.avatarPathPending or menu.ui.avatarPath or "" end
    if items.notificationDedupe then items.notificationDedupe.value = menu.ui.notificationDedupe ~= 0 end
    if items.notificationPosition then items.notificationPosition.value = menu.ui.notificationPosition end
    if items.themePreset then items.themePreset.value = menu.ui.themePreset end
    for _, prefix in ipairs(menu.themeColorFields) do
        local item = items[prefix .. "Color"]
        if item then
            item.value = {
                r = menu.ui[prefix .. "R"],
                g = menu.ui[prefix .. "G"],
                b = menu.ui[prefix .. "B"],
                a = 255
            }
        end
    end
    if items.performanceProfile then items.performanceProfile.value = menu.ui.performanceProfile end
    if items.inventoryWindowWidth and SovereignBusinessInventory and SovereignBusinessInventory.window then
        items.inventoryWindowWidth.value = SovereignBusinessInventory.window.width
        items.inventoryWindowHeight.value = SovereignBusinessInventory.window.height
        items.inventoryWindowFont.value = SovereignBusinessInventory.window.fontScale
    end
    if items.overviewWindowWidth and TravellerMigration and TravellerMigration.window then
        items.overviewWindowWidth.value = TravellerMigration.window.width
        items.overviewWindowHeight.value = TravellerMigration.window.height
        items.overviewWindowFont.value = TravellerMigration.window.fontScale
    end
    menu.syncOverlayWindowItems(items, "statusWindow", SovereignStatusCenter and SovereignStatusCenter.window)
    menu.syncOverlayWindowItems(items, "performanceWindow", menu.performanceWindowRef)
    menu.syncOverlayWindowItems(items, "historyWindow", menu.notificationHistoryWindow)
    menu.updateHotkeyStatus()
end

function menu.applyUiPreset(index)
    index = math.floor(math.max(1, math.min(5, tonumber(index) or 1)))
    if index == 1 then
        menu.resetUiSettings()
    elseif index == 2 then
        menu.ui.width, menu.ui.height, menu.ui.fontScale = 980, 600, 0.90
        menu.ui.sidebarGap, menu.ui.subtabGap = 6, 6
        menu.ui.itemGap, menu.ui.groupGap = 0, 8
        menu.ui.sidebarWidth, menu.ui.columns = 170, 2
        menu.ui.splitLongGroups, menu.ui.showPlayerInfo = 1, 1
    elseif index == 3 then
        menu.ui.width, menu.ui.height, menu.ui.fontScale = 1240, 780, 1.25
        menu.ui.sidebarGap, menu.ui.subtabGap = 14, 14
        menu.ui.itemGap, menu.ui.groupGap = 8, 18
        menu.ui.sidebarWidth, menu.ui.columns = 230, 1
        menu.ui.splitLongGroups, menu.ui.showPlayerInfo = 0, 1
    elseif index == 4 then
        menu.ui.width, menu.ui.height, menu.ui.fontScale = 900, 540, 1.0
        menu.ui.sidebarGap, menu.ui.subtabGap = 8, 8
        menu.ui.itemGap, menu.ui.groupGap = 2, 10
        menu.ui.sidebarWidth, menu.ui.columns = 180, 2
        menu.ui.splitLongGroups, menu.ui.showPlayerInfo = 1, 0
        menu.ui.rgbBorder = 0
        menu.ui.performanceProfile = 1
    else
        -- Reference layout: one compact toolbar, high-density rows and the
        -- optional animated RGB rail remain available through settings.
        menu.ui.width, menu.ui.height, menu.ui.fontScale = 940, 560, 0.92
        menu.ui.sidebarGap, menu.ui.subtabGap = 3, 4
        menu.ui.itemGap, menu.ui.groupGap = 0, 7
        menu.ui.sidebarWidth, menu.ui.columns = 166, 2
        menu.ui.splitLongGroups, menu.ui.showPlayerInfo = 1, 1
        menu.ui.rgbBorder, menu.ui.performanceProfile = 1, 2
        menu.applyThemePreset(1, false)
    end
    menu.ui.sizeDirty = true
    menu.syncUiSettingItems()
    menu.queueUiSettingsSave()
end

menu.uiConfigKeyOrder = {
    "width", "height", "fontScale", "sidebarGap", "subtabGap", "itemGap", "groupGap",
    "sidebarWidth", "columns", "splitLongGroups", "showPlayerInfo", "rgbBorder", "rgbSpeed",
    "rgbGlow", "rgbThickness", "rgbDensity", "brightness", "notificationLimit",
    "notificationDedupe", "notificationPosition", "notificationWidth", "notificationDurationScale",
    "poolWarningPercent", "streetPunchBlastSize", "targetShotSelection", "targetShotBackend", "r56TargetRouting", "targetShotBone", "targetShotFov",
    "themePreset", "backgroundR", "backgroundG", "backgroundB", "panelR", "panelG", "panelB",
    "controlR", "controlG", "controlB", "hoverR", "hoverG", "hoverB", "borderR", "borderG",
    "borderB", "textR", "textG", "textB", "mutedR", "mutedG", "mutedB",
    "accentR", "accentG", "accentB", "performanceProfile", "backdropBlur", "backdropDim",
    "avatarEnabled", "avatarPathHex", "inventoryWindowWidth",
    "inventoryWindowHeight", "inventoryWindowFont", "inventoryWindowX", "inventoryWindowY",
    "inventoryWindowMinimized", "overviewWindowWidth", "overviewWindowHeight", "overviewWindowFont",
    "overviewWindowX", "overviewWindowY", "overviewWindowMinimized", "hotkeyCode", "hotkeyIndex",
    "statusWindowWidth", "statusWindowHeight", "statusWindowFont", "statusWindowX", "statusWindowY",
    "statusWindowMinimized",
    "battleNetworkWindowWidth", "battleNetworkWindowHeight", "battleNetworkWindowFont", "battleNetworkWindowX", "battleNetworkWindowY",
    "battleNetworkWindowMinimized", "performanceWindowWidth", "performanceWindowHeight",
    "performanceWindowFont", "performanceWindowX", "performanceWindowY", "performanceWindowMinimized",
    "historyWindowWidth", "historyWindowHeight", "historyWindowFont", "historyWindowX",
    "historyWindowY", "historyWindowMinimized",
    "cursorStyle", "cursorSize", "toggleGlow", "animationSpeed", "tooltipOpacity", "notificationOpacity",
    "tooltipR", "tooltipG", "tooltipB", "notificationR", "notificationG", "notificationB",
    "toggleOnR", "toggleOnG", "toggleOnB", "toggleOffR", "toggleOffG", "toggleOffB",
    "cursorR", "cursorG", "cursorB"
}
do
    local known = {}
    for _, key in ipairs(menu.uiConfigKeyOrder) do known[key] = true end
    for _, field in ipairs(menu.appearanceSettings or {}) do
        menu.uiConfigKeyOrder[#menu.uiConfigKeyOrder + 1] = field.key
    end
    for _, prefix in ipairs(menu.themeColorFields) do
        for _, channel in ipairs({"R", "G", "B"}) do
            local key = prefix .. channel
            if not known[key] then menu.uiConfigKeyOrder[#menu.uiConfigKeyOrder + 1] = key end
        end
    end
end

function menu.serializeUiSettingsValues(values)
    local lines = {}
    for _, key in ipairs(menu.uiConfigKeyOrder) do
        if values[key] ~= nil then
            lines[#lines + 1] = key .. "=" .. tostring(values[key])
        end
    end
    local keys = {}
    for key in pairs(values) do
        if key:match("^feature_([%w_]+)$") then keys[#keys + 1] = key end
    end
    table.sort(keys)
    for _, key in ipairs(keys) do lines[#lines + 1] = key .. "=" .. tostring(values[key]) end
    return table.concat(lines, "\n") .. "\n"
end

function menu.parseUiSettingsContent(content)
    if type(content) ~= "string" or #content == 0 or #content > 131072 then
        return nil, "invalid_content"
    end

    content = content:gsub("^\239\187\191", ""):gsub("\r\n", "\n"):gsub("\r", "\n")
    local allowed, values, count = {}, {}, 0
    for _, key in ipairs(menu.uiConfigKeyOrder) do
        allowed[key] = true
    end
    -- R47's forward distance is accepted on import, then discarded. It must
    -- neither reject an existing config nor become the new impact spread.
    allowed.streetPunchRadius = true

    for rawLine in (content .. "\n"):gmatch("(.-)\n") do
        local line = rawLine:match("^%s*(.-)%s*$") or ""
        if line ~= "" and line:sub(1, 1) ~= "#" and line:sub(1, 1) ~= ";" then
            local key, rawValue = line:match("^([%a_][%w_]*)%s*=%s*(.-)%s*$")
            local featureKey = key and key:match("^feature_([%w_]+)$")
            if not key or (not allowed[key] and not featureKey) or values[key] ~= nil
                or (featureKey and #featureKey > 96) then
                return nil, "invalid_content"
            end
            if featureKey then
                if rawValue ~= "0" and rawValue ~= "1" then return nil, "invalid_content" end
                values[key] = tonumber(rawValue)
            elseif key == "avatarPathHex" then
                if #rawValue > 1024 or (#rawValue % 2) ~= 0 or rawValue:find("[^%x]") then
                    return nil, "invalid_content"
                end
                values[key] = rawValue
            else
                if not rawValue:match("^[+-]?%d+%.?%d*$") then
                    return nil, "invalid_content"
                end
                local value = tonumber(rawValue)
                if value == nil then return nil, "invalid_content" end
                values[key] = value
            end
            count = count + 1
        end
    end

    if count < 2 or values.width == nil or values.height == nil then
        return nil, "invalid_content"
    end

    return menu.serializeUiSettingsValues(values), nil, values
end

function menu.exportUiSettings()
    if not (FileMgr and type(FileMgr.WriteFileContent) == "function") then
        return false, "file_unavailable"
    end
    return menu.writeUiSettingsVerified(CONFIG.PATHS.UITransferFile, menu.buildUiSettingsBody())
end

function menu.importUiSettings()
    if not (FileMgr and type(FileMgr.DoesFileExist) == "function"
        and type(FileMgr.ReadFileContent) == "function"
        and type(FileMgr.WriteFileContent) == "function") then
        return false, "file_unavailable"
    end

    local existsOk, exists = pcall(FileMgr.DoesFileExist, CONFIG.PATHS.UITransferFile)
    if not existsOk then return false, "read_failed" end
    if not exists then return false, "file_missing" end

    local readOk, content = pcall(FileMgr.ReadFileContent, CONFIG.PATHS.UITransferFile)
    if not readOk or type(content) ~= "string" then return false, "read_failed" end
    local sanitized, parseReason, importedValues = menu.parseUiSettingsContent(content)
    if not sanitized then return false, parseReason end

    local previous = menu.buildUiSettingsBody()
    local _, previousParseReason, currentValues = menu.parseUiSettingsContent(previous)
    if not currentValues then return false, previousParseReason or "apply_failed" end
    if importedValues.hotkeyIndex ~= nil and importedValues.hotkeyCode == nil then
        currentValues.hotkeyCode = nil
    end
    for key, value in pairs(currentValues) do
        if importedValues[key] == nil then importedValues[key] = value end
    end
    sanitized = menu.serializeUiSettingsValues(importedValues)

    local writeOk, writeReason = menu.writeUiSettingsVerified(CONFIG.PATHS.UIConfigFile, sanitized)
    if not writeOk then
        local restored = menu.writeUiSettingsVerified(CONFIG.PATHS.UIConfigFile, previous)
        return false, restored and writeReason or "rollback_failed"
    end

    local applyOk, applyResult = pcall(function()
        menu.ui.configLoaded = false
        if not menu.loadUiSettings() then error("load_failed") end
        menu.syncUiSettingItems()
        if not menu.saveUiSettings() then error("save_failed") end
        return true
    end)
    if applyOk and applyResult == true then return true end

    local rollbackWriteOk = menu.writeUiSettingsVerified(CONFIG.PATHS.UIConfigFile, previous)
    if not rollbackWriteOk then
        menu.ui.configLoaded = false
        return false, "rollback_failed"
    end
    menu.ui.configLoaded = false
    local rollbackLoadOk, rollbackLoadResult = pcall(menu.loadUiSettings)
    if not rollbackLoadOk or rollbackLoadResult ~= true then return false, "rollback_failed" end
    local rollbackSyncOk = pcall(menu.syncUiSettingItems)
    if not rollbackSyncOk then return false, "rollback_failed" end
    return false, "apply_failed"
end

function menu.queueUiSettingsSave()
    menu.ui.saveRevision = (menu.ui.saveRevision or 0) + 1
    menu.ui.savePending = true
    menu.ui.lastChangeAt = os.clock()
end

-- R42 automatic settings persistence: one disk operation per logical frame.
function menu.stepUiAutoSave()
    local job = menu.uiAutoSave
    if not job then
        local ok, body = pcall(menu.buildUiSettingsBody)
        if not ok or type(body) ~= "string" then
            menu.ui.lastSaveError, menu.ui.lastChangeAt = "build_failed", os.clock()
            return false
        end
        menu.uiAutoSave = {body = body, revision = menu.ui.saveRevision or 0,
            path = CONFIG.PATHS.UIConfigFile, phase = "stage_write"}
        return false
    end
    local function finish(saved, reason)
        menu.uiAutoSave = nil
        menu.ui.savePending = not saved or (menu.ui.saveRevision or 0) ~= job.revision
        menu.ui.lastSaveError = saved and nil or reason
        if saved then
            menu.ui.lastSavedAt = os.clock()
            if not menu.ui.savePending then menu.setFeatureRestoreStatus("saved") end
        else menu.ui.lastChangeAt = os.clock() end
        return saved
    end
    local function matches(value, expected)
        return type(value) == "string" and value:gsub("\r\n", "\n") == expected:gsub("\r\n", "\n")
    end
    local function failedCommit(reason)
        job.error = reason
        if type(job.previous) == "string" and job.previous ~= "" then job.phase = "rollback_write"
        else return finish(false, reason) end
        return false
    end
    if not FileMgr or type(FileMgr.WriteFileContent) ~= "function" or type(FileMgr.ReadFileContent) ~= "function" then
        return finish(false, "file_unavailable")
    end
    if job.phase == "stage_write" then
        local ok, result = pcall(FileMgr.WriteFileContent, job.path .. ".pending", job.body, false)
        if not ok or result == false then return finish(false, "write_failed") end
        job.phase = "stage_read"
    elseif job.phase == "stage_read" then
        local ok, body = pcall(FileMgr.ReadFileContent, job.path .. ".pending")
        if not ok or type(body) ~= "string" then return finish(false, "read_failed") end
        if not matches(body, job.body) then return finish(false, "verify_failed") end
        job.phase = "previous_read"
    elseif job.phase == "previous_read" then
        local ok, body = pcall(FileMgr.ReadFileContent, job.path)
        job.previous = ok and body or nil
        job.phase = "commit_write"
    elseif job.phase == "commit_write" then
        local ok, result = pcall(FileMgr.WriteFileContent, job.path, job.body, false)
        if not ok or result == false then return failedCommit("write_failed") end
        job.phase = "commit_read"
    elseif job.phase == "commit_read" then
        local ok, body = pcall(FileMgr.ReadFileContent, job.path)
        if not ok or type(body) ~= "string" then return failedCommit("read_failed") end
        if not matches(body, job.body) then return failedCommit("verify_failed") end
        job.phase = "remove_pending"
    elseif job.phase == "remove_pending" then
        if type(FileMgr.DeleteFile) == "function" then pcall(FileMgr.DeleteFile, job.path .. ".pending") end
        return finish(true)
    elseif job.phase == "rollback_write" then
        local ok, result = pcall(FileMgr.WriteFileContent, job.path, job.previous, false)
        if not ok or result == false then return finish(false, "rollback_failed") end
        job.phase = "rollback_read"
    elseif job.phase == "rollback_read" then
        local ok, body = pcall(FileMgr.ReadFileContent, job.path)
        return finish(false, ok and matches(body, job.previous) and job.error or "rollback_failed")
    end
    return false
end
-- R42 automatic settings persistence end.

function menu.flushUiSettings(force)
    if not menu.ui.savePending then
        return
    end
    local elapsed = os.clock() - (menu.ui.lastChangeAt or 0)
    if force then
        if menu.saveUiSettings() then
            menu.ui.savePending = false
        else
            menu.ui.lastChangeAt = os.clock()
        end
    elseif menu.uiAutoSave or elapsed >= 0.35 then
        local started = menu.runtimeProbe and menu.runtimeProbe.active and os.clock() or nil
        menu.stepUiAutoSave()
        if started then menu.recordRuntimeTiming("Configuration save", started) end
    end
end

function menu.loadQuickSettings()
    if menu.quick.loaded then return true end
    menu.quick.favorites = {}
    menu.quick.favoriteOrder = {}
    menu.quick.recentOrder = {}
    local ok, content = pcall(function()
        if not FileMgr.DoesFileExist(CONFIG.PATHS.QuickConfigFile) then return "" end
        return FileMgr.ReadFileContent(CONFIG.PATHS.QuickConfigFile) or ""
    end)
    if ok and type(content) == "string" then
        local favoriteLine = content:match("favorites=([^\r\n]*)") or ""
        local recentLine = content:match("recent=([^\r\n]*)") or ""
        for key in favoriteLine:gmatch("[%x]+") do
            key = key:lower()
            if #key == 8 and not menu.quick.favorites[key] then
                menu.quick.favorites[key] = true
                menu.quick.favoriteOrder[#menu.quick.favoriteOrder + 1] = key
            end
        end
        for key in recentLine:gmatch("[%x]+") do
            key = key:lower()
            if #key == 8 then
                menu.quick.recentOrder[#menu.quick.recentOrder + 1] = key
                if #menu.quick.recentOrder >= (menu.quick.maxRecent or 12) then break end
            end
        end
    end
    menu.quick.loaded = true
    menu.refreshQuickGroups()
    return ok
end

function menu.saveQuickSettings()
    local body = "favorites=" .. table.concat(menu.quick.favoriteOrder, ",")
        .. "\nrecent=" .. table.concat(menu.quick.recentOrder, ",") .. "\n"
    local ok, result = pcall(function()
        return FileMgr.WriteFileContent(CONFIG.PATHS.QuickConfigFile, body)
    end)
    return ok and result ~= false
end

function menu.flushQuickSettings(force)
    if not menu.quick.savePending then return end
    local elapsed = os.clock() - (menu.quick.lastChangeAt or 0)
    if force or elapsed >= 0.35 then
        menu.saveQuickSettings()
        menu.quick.savePending = false
    end
end

local SecurityManager
local function detectplayerstate()
    local network = rawget(_G, "NETWORK")
    local function callNetworkBool(name)
        if type(network) ~= "table" then
            return nil
        end
        local okLookup, fn = pcall(function() return network[name] end)
        if not okLookup or type(fn) ~= "function" then
            return nil
        end
        local okCall, value = pcall(fn)
        if not okCall then
            return nil
        end
        return value == true
    end

    local signedIn = callNetworkBool("NETWORK_IS_SIGNED_IN")
    local hasScAccount = callNetworkBool("NETWORK_HAS_SOCIAL_CLUB_ACCOUNT")
    if signedIn == false or hasScAccount == false then
        -- Social Club can report false while Cherax is still bringing the
        -- session up. Keep the script pending and let the normal login retry
        -- gate try again instead of unloading the first injection.
        if AuthManager then
            AuthManager.status = AUTH_STATUS.PENDING
            AuthManager.isAuthenticated = false
        end
        Logger:Warn("SovereignLua", "Social Club session is not ready")
        return false
    end

    local socialClub = rawget(_G, "SOCIALCLUB")
    local nicknameFn = nil
    if type(socialClub) == "table" then
        local okLookup, fn = pcall(function() return socialClub["SC_ACCOUNT_INFO_GET_NICKNAME"] end)
        if okLookup and type(fn) == "function" then
            nicknameFn = fn
        end
    end
    local nickname = nil
    if nicknameFn then
        for _ = 1, 20 do
            local okNickname, value = pcall(nicknameFn)
            if okNickname and type(value) == "string" and value ~= "" then
                nickname = value
                break
            end
            if Script and type(Script.Yield) == "function" then
                Script.Yield(100)
            else
                break
            end
        end
    end
    if type(nickname) ~= "string" or nickname == "" then
        nickname = "UNKNOWN"
        Logger:Warn("SovereignLua", "Social Club nickname unavailable")
    else
        Logger:Info("SovereignLua", "Account nickname: " .. nickname)
    end
    return true, nickname
end

-- Lease timestamps are UTC epoch seconds.  Keep elapsed-time decisions tied
-- to the server clock learned by the bridge so a timezone or a drifted local
-- clock cannot invalidate a valid overseas session.  The bridge clamps the
-- offset to a bounded range and older bridges simply leave it at zero.
function RuntimeLeaseNow()
    return SovereignOfficial:Now()
end

local RuntimeLeaseFailureLimitReached
local RuntimeLeaseState = {
    check = SovereignRuntimeLeaseCheck,
    reportPlayerLink = CONFIG.RELEASE.PlayerLinkReport,
    expiresAt = 0,
    lastVerifiedAt = 0,
    refreshInProgress = false,
    -- Allow transient bridge/TLS delays without treating the first present
    -- callback as a revoked session.  A lease is still required once the
    -- grace window and the bounded retry budget are both exhausted.
    maxStaleSeconds = 4200,
    -- Hourly healthy renewal leaves ten minutes within the server-issued lease for retries.
    -- Temporary errors never extend the authenticated expiry.
    monitorIntervalMs = 3600000,
    retryIntervalMs = 30000,
    maxConsecutiveFailures = 12,
    startupGraceSeconds = 300,
    startupGraceUntil = RuntimeLeaseNow() + 300,
    successfulChecks = 0,
    consecutiveFailures = 0,
    firstFailureAt = 0,
    playerLinkInProgress = false,
    playerLinkSubmitted = false,
    playerLinkSessionSeen = false,
    lastPlayerLinkSuccessAt = 0,
    lastPlayerLinkRid = "",
    playerLinkAttemptsPerSession = 3,
    playerLinkRetryDelayMs = 5000
}
CONFIG.RELEASE.PlayerLinkReport = nil

function RuntimeLeaseState:StartupGraceActive(now)
    now = now or RuntimeLeaseNow()
    return self.startupGraceUntil > 0 and now <= self.startupGraceUntil
end

function RuntimeLeaseState:FailureTolerated(now)
    now = now or RuntimeLeaseNow()
    -- A connection retry never extends a server-issued authorization period.
    return not self.hardDenied and self.lastVerifiedAt > 0 and now >= self.lastVerifiedAt
        and self.expiresAt > now and now - self.lastVerifiedAt <= self.maxStaleSeconds
end

function RuntimeLeaseState:OnlineSessionActive()
    local network = rawget(_G, "NETWORK")
    if not network then return false end
    for _, name in ipairs({"NETWORK_IS_SESSION_ACTIVE", "NETWORK_IS_SESSION_STARTED"}) do
        local okFn, fn = pcall(function() return network[name] end)
        if okFn and type(fn) == "function" then
            local okActive, active = pcall(fn)
            if okActive and active == true then
                return true
            end
        end
    end
    return false
end

RuntimeLeaseFailureLimitReached = function(now)
    now = now or RuntimeLeaseNow()
    if RuntimeLeaseState.consecutiveFailures <= 0 or RuntimeLeaseState.firstFailureAt <= 0 then
        return false
    end
    if RuntimeLeaseState:FailureTolerated(now) or RuntimeLeaseState:StartupGraceActive(now) then
        return false
    end
    return RuntimeLeaseState.consecutiveFailures >= RuntimeLeaseState.maxConsecutiveFailures
        or now - RuntimeLeaseState.firstFailureAt >= RuntimeLeaseState.maxStaleSeconds
        or (RuntimeLeaseState.lastVerifiedAt > 0
            and now - RuntimeLeaseState.lastVerifiedAt >= RuntimeLeaseState.maxStaleSeconds)
end

local function RuntimeLeaseFresh()
    local now = RuntimeLeaseNow()
    if RuntimeLeaseState.hardDenied or type(RuntimeLeaseState.check) ~= "function" then
        return false
    end
    if RuntimeLeaseState.lastVerifiedAt <= 0 or now < RuntimeLeaseState.lastVerifiedAt then return false end
    if RuntimeLeaseState.expiresAt > now
        and now - RuntimeLeaseState.lastVerifiedAt <= RuntimeLeaseState.maxStaleSeconds then
        return true
    end
    return false -- Official sessions never run past their authenticated expiry.
end

AuthManager = {
    isAuthenticated = false,
    leaseMonitorStarted = false,
    initialLeaseRetryActive = false,
    loginGeneration = 0,
    leaseMonitorGeneration = 0,
    currentKey = "",
    keySource = "unknown",
    userType = USER_TYPE.NEW,
    status = AUTH_STATUS.PENDING,
    errorMessages = {
        ["invalidver"] = "Version error",
        [("z" .. "tlua_invalid_key")] = "License key error",
        [("z" .. "tlua_license_banned")] = "License key banned",
        [("z" .. "tlua_paused")] = "Sovereign Lua suspended",
        [("z" .. "tlua_expired")] = "License key expired",
        [("z" .. "tlua_disabled")] = "Sovereign Lua disabled"
    }
}

function AuthManager:QueueLocalPlayerLink(force)
    local reporter = RuntimeLeaseState.reportPlayerLink
    if type(reporter) ~= "function"
        or not self.isAuthenticated
        or not RuntimeLeaseFresh() then
        return false
    end
    if RuntimeLeaseState.playerLinkSubmitted then
        return true
    end
    if not RuntimeLeaseState:OnlineSessionActive() then
        RuntimeLeaseState.playerLinkSessionSeen = false
        return true
    end
    if RuntimeLeaseState.playerLinkInProgress
        or (not force and RuntimeLeaseState.playerLinkSessionSeen) then
        return true
    end
    RuntimeLeaseState.playerLinkSessionSeen = true
    RuntimeLeaseState.playerLinkInProgress = true
    local queuedOk, queued = pcall(function()
        return Script.QueueJob(function()
            local attempts = math.max(1, tonumber(RuntimeLeaseState.playerLinkAttemptsPerSession) or 1)
            for attempt = 1, attempts do
                if attempt > 1 then
                    Script.Yield(RuntimeLeaseState.playerLinkRetryDelayMs)
                end
                if not RuntimeLeaseState:OnlineSessionActive() then break end

                local slotOk, playerSlot = pcall(function()
                    return PlayerManager:GetLocalPlayerId()
                end)
                local ridOk, rockstarId = false, nil
                if slotOk and type(playerSlot) == "number" and playerSlot >= 0 and playerSlot <= 31 then
                    ridOk, rockstarId = pcall(GetPlayerRockstarId, playerSlot)
                end
                if ridOk and type(rockstarId) == "number" and rockstarId > 0 then
                    local ridText = string.format("%.0f", rockstarId)
                    local nameOk, playerName = pcall(GetPlayerName, playerSlot)
                    if not nameOk then playerName = "" end
                    local callOk, reported = pcall(function()
                        return reporter(playerSlot, ridText, playerName)
                    end)
                    if callOk and reported then
                        RuntimeLeaseState.lastPlayerLinkSuccessAt = os.time()
                        RuntimeLeaseState.lastPlayerLinkRid = ridText
                        RuntimeLeaseState.playerLinkSubmitted = true
                        break
                    end
                end
            end
            RuntimeLeaseState.playerLinkInProgress = false
        end)
    end)
    if not queuedOk or queued == false then
        RuntimeLeaseState.playerLinkInProgress = false
        return false
    end
    return true
end
-- though we have vip edition  we still keep balance between old and new users
-- they paied the same money after all
function AuthManager:IsOldUser(_)
    return SovereignOfficial:IsLegacy()
end

function AuthManager:RefreshRuntimeLease(expectedGeneration)
    local generation = expectedGeneration or self.loginGeneration
    if generation ~= self.loginGeneration or ShouldUnload() or RuntimeLeaseState.refreshInProgress
        or type(SovereignRuntimeLeaseCheck) ~= "function" then return false end
    RuntimeLeaseState.refreshInProgress = true
    local ok, allowed, expiresAt, reason, serverNow, failureCode = pcall(SovereignRuntimeLeaseCheck)
    RuntimeLeaseState.refreshInProgress = false
    if generation ~= self.loginGeneration or ShouldUnload() then return false end
    -- New bridges return the authenticated server timestamp as the fifth
    -- result. Older bridges return nil and retain the local-clock fallback.
    serverNow = tonumber(serverNow)
    if serverNow and serverNow == serverNow and math.abs(serverNow - os.time()) <= 172800 then
        -- Official runtime already validated and retained the server clock.
    end
    local now = RuntimeLeaseNow()
    expiresAt = tonumber(expiresAt)
    local invalidSuccess = ok and allowed == true and (not expiresAt or expiresAt ~= expiresAt
        or expiresAt >= rawget(math, "huge") or expiresAt <= now or expiresAt > now + 4200 or expiresAt % 1 ~= 0)
    local hardDenied = reason == "lease_denied" or reason == "lease_invalid"
        or reason == "lease_response_401" or reason == "lease_response_403"
        or reason == "lease_build" or reason == "lease_watermark" or reason == "lease_token"
        or reason == "tls_setup" or reason == "lease_expired" or invalidSuccess
        or now < RuntimeLeaseState.lastVerifiedAt
    if hardDenied then
        local knownCodes = {denied=true, stopped=true, integrity_failure=true,
            identity_unavailable=true, response_invalid=true}
        local diagnostic = type(failureCode) == "string" and knownCodes[failureCode]
            and failureCode or "lease_denied"
        if invalidSuccess then diagnostic = "invalid_lease"
        elseif now < RuntimeLeaseState.lastVerifiedAt then diagnostic = "clock_regression" end
        RuntimeLeaseState.hardDenied = true
        RuntimeLeaseState.lastFailureReason = diagnostic
        RuntimeLeaseState.expiresAt, RuntimeLeaseState.lastVerifiedAt = 0, 0
        self.isAuthenticated, self.status = false, AUTH_STATUS.PENDING
        -- A rejected saved/typed key before any authorized session should keep
        -- the login UI available, not terminate the script. No access is granted
        -- and retries stop until the user explicitly chooses Login. Revocation
        -- after a successful lease and integrity failures still fail closed.
        if ok and allowed ~= true and reason == "lease_denied" and diagnostic == "denied"
            and (RuntimeLeaseState.successfulChecks or 0) == 0 then
            self.loginRetryBlocked = true
            self.initialLeaseRetryActive = false
            RuntimeLeaseState.lastFailureReason = "license_denied"
            pcall(Logger.Warn, Logger, "SovereignAuth",
                "Authorization declined; automatic login paused. Check the license, binding, and Sovereign access, then select Login.")
            pcall(Logger.Toast, Logger, "SovereignLua",
                SovereignOfficial:StatusMessage(), CONFIG.UI.ToastDuration.Long)
            return false
        end
        pcall(Logger.Error, Logger, "SovereignAuth", "Session stopped: " .. diagnostic)
        if SecurityManager and SecurityManager.TriggerViolationUnload then
            SecurityManager:TriggerViolationUnload()
        end
        return false
    end
    expiresAt = tonumber(expiresAt)
    if not ok or allowed ~= true or not expiresAt or expiresAt ~= expiresAt
        or expiresAt >= rawget(math, "huge") or expiresAt <= now or expiresAt > now + 4200 or expiresAt % 1 ~= 0 then
        local safeReasons = {
            curl_unavailable=true, request_busy=true, curl_create=true, curl_poll=true,
            curl_timeout=true, scheduler_unavailable=true, curl_request=true,
            curl_response=true, curl_setup=true, lease_build=true, lease_watermark=true,
            lease_token=true, lease_expired=true
        }
        local diagnostic = not ok and "provider_exception" or "invalid_lease"
        if ok and type(reason) == "string" then
            if safeReasons[reason] or reason:match("^lease_response_%-?%d+$") then diagnostic = reason end
        end
        RuntimeLeaseState.lastFailureReason = diagnostic
        if not RuntimeLeaseState.lastDiagnosticAt or now - RuntimeLeaseState.lastDiagnosticAt >= 30 then
            RuntimeLeaseState.lastDiagnosticAt = now
            Logger:Warn("SovereignLua", "Runtime lease pending: " .. diagnostic)
        end
        return false
    end
    -- A remote timestamp cannot grant a longer local cache than the stale budget.
    RuntimeLeaseState.expiresAt = math.min(expiresAt, now + RuntimeLeaseState.maxStaleSeconds)
    RuntimeLeaseState.lastVerifiedAt = now
    RuntimeLeaseState.lastFailureReason = nil
    RuntimeLeaseState.hardDenied = false
    RuntimeLeaseState.consecutiveFailures = 0
    RuntimeLeaseState.firstFailureAt = 0
    RuntimeLeaseState.startupGraceUntil = 0
    RuntimeLeaseState.successfulChecks = (RuntimeLeaseState.successfulChecks or 0) + 1
    self.isAuthenticated = true
    self.status = AUTH_STATUS.SUCCESS
    return true
end

function AuthManager:StartRuntimeLeaseMonitor()
    if self.leaseMonitorStarted or not self.isAuthenticated or ShouldUnload() then return false end
    self.leaseMonitorStarted = true
    self.leaseMonitorGeneration = self.leaseMonitorGeneration + 1
    local monitorGeneration, generation = self.leaseMonitorGeneration, self.loginGeneration
    local failureSafetySeconds = 40
    local function healthyDelay()
        -- Shorter server leases also renew before expiry during staged upgrades.
        local remainingMs = (RuntimeLeaseState.expiresAt - RuntimeLeaseNow() - failureSafetySeconds) * 1000
        return math.min(RuntimeLeaseState.monitorIntervalMs, math.max(1000, remainingMs))
    end
    local nextDelayMs = healthyDelay()
    local function active()
        return self.leaseMonitorStarted and self.leaseMonitorGeneration == monitorGeneration
            and self.loginGeneration == generation and self.isAuthenticated and not ShouldUnload()
    end
    local queuedOk, queued = pcall(Script.QueueJob, function()
        while active() do
            Script.Yield(nextDelayMs)
            if not active() then break end
            local refreshed = self:RefreshRuntimeLease(generation)
            if not active() then break end
            if refreshed then
                -- Healthy sessions keep the lower request rate. A failed
                -- refresh below schedules the next attempt before expiry.
                nextDelayMs = healthyDelay()
            else
                local now = RuntimeLeaseNow()
                RuntimeLeaseState.consecutiveFailures = RuntimeLeaseState.consecutiveFailures + 1
                if RuntimeLeaseState.firstFailureAt <= 0 then
                    RuntimeLeaseState.firstFailureAt = now
                end
                if RuntimeLeaseState.expiresAt <= now or RuntimeLeaseFailureLimitReached(now) then
                    self.isAuthenticated = false
                    Logger:Error("SovereignLua", "Runtime session expired")
                    SecurityManager:TriggerViolationUnload()
                    break
                end
                -- Retry temporary failures promptly within the existing signed expiry.
                local remainingMs = (RuntimeLeaseState.expiresAt - now - failureSafetySeconds) * 1000
                nextDelayMs = math.min(RuntimeLeaseState.retryIntervalMs,
                    math.max(1000, remainingMs))
                Logger:Warn("SovereignLua", "Runtime session refresh delayed")
            end
        end
        if self.leaseMonitorGeneration == monitorGeneration then self.leaseMonitorStarted = false end
    end)
    if not queuedOk or queued == false then self.leaseMonitorStarted = false; return false end
    return true
end

function AuthManager:SessionValid()
    return not ShouldUnload() and self.isAuthenticated == true
        and self.status == AUTH_STATUS.SUCCESS
        and RuntimeLeaseFresh() and SovereignOfficial:HasLease()
end

function AuthManager:EnforceSession(context)
    if self:SessionValid() then
        return true
    end
    if self.status == AUTH_STATUS.PENDING or self.initialLeaseRetryActive then
        return false
    end
    Logger:Error("Auth", "Invalid local session state: " .. tostring(context or "unknown"))
    SetShouldUnload()
    return false
end

local PayloadCrypto = {}
function PayloadCrypto.Encrypt(plaintext, key)
    if not plaintext or plaintext == "" then return "" end
    SeedRuntimeRandom()
    local iv = {}
    for i = 1, 16 do
        iv[i] = string.char(math.random(0, 255))
    end
    iv = table.concat(iv)
    local keyBase = Crypto.sha256(key)
    local ciphertext = {}
    local blocks = math.ceil(#plaintext / 32)
    for b = 0, blocks - 1 do
        local blockKey = Crypto.sha256(keyBase .. iv .. string.char(b & 0xFF) .. string.char((b >> 8) & 0xFF))
        for i = 1, 32 do
            local idx = b * 32 + i
            if idx > #plaintext then break end
            local k = string.byte(blockKey, i)
            ciphertext[idx] = string.char(string.byte(plaintext, idx) ~ k)
        end
    end
    return Crypto.base64_encode(iv .. table.concat(ciphertext))
end

function PayloadCrypto.Decrypt(b64data, key)
    local data = Crypto.base64_decode(b64data)
    if #data < 16 then return nil end
    local iv = data:sub(1, 16)
    local ciphertext = data:sub(17)
    local keyBase = Crypto.sha256(key)
    local plaintext = {}
    local blocks = math.ceil(#ciphertext / 32)
    for b = 0, blocks - 1 do
        local blockKey = Crypto.sha256(keyBase .. iv .. string.char(b & 0xFF) .. string.char((b >> 8) & 0xFF))
        for i = 1, 32 do
            local idx = b * 32 + i
            if idx > #ciphertext then break end
            local k = string.byte(blockKey, i)
            plaintext[idx] = string.char(string.byte(ciphertext, idx) ~ k)
        end
    end
    return table.concat(plaintext)
end

