function SecurityManager:GenerateNonce()
    SeedRuntimeRandom()
    self.nonce_counter = ((self.nonce_counter or 0) + 1) & 0x7FFFFFFF
    local pos = nil
    local localPed = GTA.GetLocalPed()
    if localPed then
        pos = localPed.Position
    end
    local raw = table.concat({
        tostring(os.time()),
        string.format("%.6f", os.clock()),
        tostring(self.nonce_counter),
        GetRuntimeSecret(),
        GetSafeUID(),
        pos and string.format("%.6f%.6f%.6f", pos.x, pos.y, pos.z) or "0",
        tostring(math.random(1, 0x7FFFFFFF)),
        tostring({})
    }, "|")
    local hash = Crypto.sha256(raw)
    local hex = ""
    for i = 1, 16 do
        hex = hex .. string.format("%02X", string.byte(hash, i))
    end
    return hex
end

function SecurityManager:ValidateLocalSessionState(_)
    return RuntimeLeaseFresh()
end

function SecurityManager:TriggerViolationUnload()
    if self.m_unloading then
        return
    end
    self.m_unloading = true
    pcall(function()
        if AuthManager then
            AuthManager.isAuthenticated = false
            AuthManager.currentKey = ""
            AuthManager.sessionToken = nil
            AuthManager.sessionNonce = nil
        end
    end)
    self.session_nonce = nil
    self.session_timestamp = nil
    RuntimeLeaseState.lastVerifiedAt = 0
    RuntimeLeaseState.expiresAt = 0
    RuntimeLeaseState.consecutiveFailures = 0
    RuntimeLeaseState.firstFailureAt = 0
    AuthManager.loginGeneration = (AuthManager.loginGeneration or 0) + 1
    AuthManager.leaseMonitorGeneration = (AuthManager.leaseMonitorGeneration or 0) + 1
    AuthManager.leaseMonitorStarted = false
    AuthManager.initialLeaseRetryActive = false
    RuntimeLeaseState.startupGraceUntil = 0
    self.spent_nonces = {}
    SetShouldUnload()
    local unload = FeatureMgr.GetFeatureByName("Unload Cherax")
    if unload then
        -- unload:OnClick()
    end
end

function SecurityManager:HostsOverridePresent(targetHost)
    if not FileMgr.DoesFileExist(self.HOSTS_PATH) then return false end
    local ok, content = pcall(FileMgr.ReadFileContent, self.HOSTS_PATH)
    if not ok or not content then return false end
    local t = targetHost:lower()
    for line in content:gmatch("[^\r\n]+") do
        line = line:gsub("#.*", ""):lower()
        if line:find(t, 1, true) and line:match("%d+%.%d+%.%d+%.%d+") then
            Logger:Error("Security", "Hosts file redirection detected: " .. targetHost)
            SecurityManager:TriggerViolationUnload()
            return true
        end
    end
    return false
end

function SecurityManager:IsSecureUrl(url)
    if not url or url == "" then return false end
    if not url:match("^https://") then
        Logger:Error("Security", "Non-HTTPS request rejected: " .. (url or "nil"))
        SecurityManager:TriggerViolationUnload()
        return false
    end
    local authority = url:match("^https://([^/%?#]+)")
    local host = authority and authority:match("^%[?([^%]:]+)%]?")
    if not host then
        Logger:Error("Security", "Cannot resolve host: " .. url)
        SecurityManager:TriggerViolationUnload()
        return false
    end
    host = host:lower()
    local is_ip = host:match("^%d+%.%d+%.%d+%.%d+$") or host:match("^%[?[0-9a-fA-F:]+%]?$")
    if is_ip then
        local ip_parts = {host:match("(%d+)%.(%d+)%.(%d+)%.(%d+)")}
        if #ip_parts == 4 then
            local b1, b2 = tonumber(ip_parts[1]), tonumber(ip_parts[2])
            if b1 == 10 or b1 == 127 or (b1 == 192 and b2 == 168) or
               (b1 == 172 and b2 >= 16 and b2 <= 31) then
                Logger:Error("Security", "Private IP address rejected: " .. host)
                SecurityManager:TriggerViolationUnload()
                return false
            end
        end
        if host:match("^::1$") or host:match("^fc") or host:match("^fd") or host:match("^fe80:") then
            Logger:Error("Security", "Local IPv6 address rejected: " .. host)
            SecurityManager:TriggerViolationUnload()
            return false
        end
    end
    local domain_allowed = false
    for allowed_domain, _ in pairs(self.ALLOWED_HOSTS) do
        local escaped = allowed_domain:gsub("([%.%-])", "%%%1")
        if host == allowed_domain or host:match("%." .. escaped .. "$") then
            domain_allowed = true
            break
        end
    end
    if not domain_allowed then
        Logger:Warn("Security", "Host is not on the allowlist: " .. host)
        SecurityManager:TriggerViolationUnload()
        return false
    end
    if self:HostsOverridePresent(host) then
        SecurityManager:TriggerViolationUnload()
        return false
    end
    local port = authority:match("^.-:(%d+)$")
    if port and tonumber(port) ~= 443 then
        Logger:Error("Security", "Rejected: " .. url)
        SecurityManager:TriggerViolationUnload()
        return false
    end
    return true
end

function SecurityManager:ApplySSLOptions(curl, targetHost)
    if not curl then return false, "curl_unavailable" end
    local pin = self.PINNED_PUBLIC_KEYS[targetHost]
    if type(pin) ~= "string" or pin == "" then
        return false, "tls_pin_unavailable:" .. tostring(targetHost)
    end
    local ok, err = pcall(function()
        for _, option in ipairs({{81, 2}, {64, 1}, {52, 0}, {68, 0}, {32, 6}, {10230, pin}}) do
            if curl:Setopt(option[1], option[2]) == false then
                error("tls_option_rejected:" .. tostring(option[1]))
            end
        end
    end)
    if not ok then return false, tostring(err) end
    local serverOffset = tonumber(rawget(_G, "__SOVEREIGN_SERVER_TIME_OFFSET")) or 0
    if serverOffset ~= serverOffset or math.abs(serverOffset) > 172800 then serverOffset = 0 end
    self.SECURITY_HEADERS["X-Timestamp"] = tostring(os.time() + serverOffset)
    self.SECURITY_HEADERS["X-Nonce"] = self:GenerateNonce()
    self.SECURITY_HEADERS["X-Client-Verify"] = "1"
    self.SECURITY_HEADERS["X-Client-Version"] = CONFIG.VERSION.String
    for header_name, header_value in pairs(self.SECURITY_HEADERS) do
        curl:AddHeader(header_name .. ": " .. header_value)
    end
    return true
end

function SecurityManager:VerifyResponse(response, expected_timestamp, response_headers)
    if not response or response == "" then
        SetShouldUnload()
        return false, "Empty response"
    end
    if not response:find('"success"') then
        SecurityManager:TriggerViolationUnload()
        return false, "Invalid response format"
    end
    local resp_client_nonce = response:match('"client_nonce"%s*:%s*"([^"]+)"') or response:match('"x_nonce"%s*:%s*"([^"]+)"')
    if resp_client_nonce and self.last_request_nonce ~= "" and resp_client_nonce ~= self.last_request_nonce then
        SecurityManager:TriggerViolationUnload()
        return false, "Response nonce mismatch"
    end
    local resp_ts = tonumber(response:match('"timestamp"%s*:%s*(%d+)') or response:match('"ts"%s*:%s*(%d+)') or 0)
    local serverOffset = tonumber(rawget(_G, "__SOVEREIGN_SERVER_TIME_OFFSET")) or 0
    if serverOffset ~= serverOffset or math.abs(serverOffset) > 172800 then serverOffset = 0 end
    if resp_ts and resp_ts > 0 and self.last_request_timestamp > 0 then
        local observedOffset = resp_ts - self.last_request_timestamp
        -- A pinned HTTPS response may legitimately use the service's UTC
        -- clock. Learn a bounded offset before applying the freshness check;
        -- timezone differences never alter epoch seconds.
        if math.abs(observedOffset) > 60 and math.abs(observedOffset) <= 172800 then
            serverOffset = observedOffset
            rawset(_G, "__SOVEREIGN_SERVER_TIME_OFFSET", observedOffset)
        end
        if math.abs(resp_ts - (self.last_request_timestamp + serverOffset)) > 60 then
            SecurityManager:TriggerViolationUnload()
            return false, "Response timestamp mismatch"
        end
    end
    if expected_timestamp then
        local current_time = os.time() + serverOffset
        local time_diff = math.abs(current_time - expected_timestamp)
        if time_diff > 15 then
            SecurityManager:TriggerViolationUnload()
            return false, "Response timestamp expired"
        end
    end
    if response:find('"ownerid"') then
        local resp_ownerid = response:match('"ownerid"%s*:%s*"([^"]+)"')
        if resp_ownerid and resp_ownerid ~= CONFIG.NETWORK.OwnerId then
            Logger:Error("Security", "No matching IDs")
            SecurityManager:TriggerViolationUnload()
            return false, "ID verification failed"
        end
    end
    return true, "Verified"
end

function SecurityManager:FormEncode(value)
    local text = tostring(value or "")
    text = text:gsub("\r\n", "\n")
    text = text:gsub("([^%w%-_%.~])", function(ch)
        return string.format("%%%02X", ch:byte())
    end)
    return text
end

function SecurityManager:BuildForm(fields)
    local parts = {}
    for _, item in ipairs(fields) do
        parts[#parts + 1] = self:FormEncode(item[1]) .. "=" .. self:FormEncode(item[2])
    end
    return table.concat(parts, "&")
end

function SecurityManager:DetectProxy()
    local env_vars = {"HTTP_PROXY", "HTTPS_PROXY", "http_proxy", "https_proxy", "ALL_PROXY", "all_proxy"}
    for _, var in ipairs(env_vars) do
        local val = os.getenv(var)
        if val and val ~= "" then
            Logger:Error("Security", "System proxy environment variable detected [" .. var .. "]: " .. val)
            SecurityManager:TriggerViolationUnload()
            return true
        end
    end
    return false
end

function SecurityManager:RecordSpentNonce(nonce)
    self.spent_nonces[nonce] = os.time()
    local count = 0
    for n, t in pairs(self.spent_nonces) do
        count = count + 1
    end
    if count > self.max_nonce_cache then
        local oldest = os.time()
        local oldest_key = nil
        for n, t in pairs(self.spent_nonces) do
            if t < oldest then
                oldest = t
                oldest_key = n
            end
        end
        if oldest_key then
            self.spent_nonces[oldest_key] = nil
        end
    end
end
function SecurityManager:IsNonceSpent(nonce)
    return self.spent_nonces[nonce] ~= nil
end

-- Curl.Perform is asynchronous in the Cherax bridge. Keep timed-out handles
-- strongly referenced until the bridge reports completion; dropping the last
-- Lua reference while a callback is active aborts the request.
SecurityManager.activeCurlRequests = SecurityManager.activeCurlRequests or {}
function SecurityManager:DrainCurlRequests()
    for index = #self.activeCurlRequests, 1, -1 do
        local request = self.activeCurlRequests[index]
        local finished = false
        local ok = request and request.curl and pcall(function()
            finished = request.curl:GetFinished() == true
        end)
        -- A bridge exception can mean the callback is still unwinding. Keep
        -- the handle in that case; releasing it here recreates the abort.
        if not request or not request.curl or (ok and finished) then
            table.remove(self.activeCurlRequests, index)
        end
    end
end
function SecurityManager:RetainCurlRequest(curl)
    if not curl then return end
    self.activeCurlRequests[#self.activeCurlRequests + 1] = {
        curl = curl,
        retainedAt = os.clock()
    }
end

function SecurityManager:SecureRequest(url, post_data, timeout, expected_host, encrypted, verify_auth_response)
    if verify_auth_response == nil then verify_auth_response = true end
    if not self:IsSecureUrl(url) then
        Logger:Error("Security", "Request rejected: insecure URL")
        SecurityManager:TriggerViolationUnload()
        return nil, "Insecure URL"
    end
    self:DrainCurlRequests()
    local curl = Curl.Easy()
    if not curl then
        return nil, "Failed to create CURL"
    end
    local actualHost = tostring(url):match("^https://([^/:]+)")
    actualHost = actualHost and actualHost:lower() or nil
    if expected_host and expected_host:lower() ~= actualHost then
        return nil, "tls_host_mismatch"
    end
    local tlsReady, tlsError = SecurityManager:ApplySSLOptions(curl, actualHost)
    if not tlsReady then return nil, tlsError end
    self.last_request_nonce = tostring(self.SECURITY_HEADERS["X-Nonce"] or "")
    self.last_request_timestamp = tonumber(self.SECURITY_HEADERS["X-Timestamp"] or 0) or 0
    curl:Setopt(eCurlOption.CURLOPT_URL, url)
    pcall(function()
        curl:Setopt(eCurlOption.CURLOPT_FOLLOWLOCATION, 0)
    end)
    if timeout then
        pcall(function()
            curl:Setopt(eCurlOption.CURLOPT_TIMEOUT, timeout/1000)
        end)
    end
    if encrypted then
        curl:AddHeader("X-Encryption: 1")
    end
    if post_data then
        curl:Setopt(eCurlOption.CURLOPT_POSTFIELDS, post_data)
        curl:Setopt(eCurlOption.CURLOPT_POST, 1)
    end
    local performOk, performError = pcall(function() curl:Perform() end)
    if not performOk then
        self:RetainCurlRequest(curl)
        curl = nil
        return nil, "Network error"
    end
    local timeoutSeconds = math.max(3, ((timeout or CONFIG.NETWORK.RequestTimeout or 5000) / 1000) + 2)
    local deadline = os.clock() + timeoutSeconds
    while true do
        local finished = false
        local finishedOk = pcall(function() finished = curl:GetFinished() == true end)
        if not finishedOk then
            self:RetainCurlRequest(curl)
            curl = nil
            return nil, "Network error"
        end
        if finished then break end
        if os.clock() >= deadline then
            self:RetainCurlRequest(curl)
            curl = nil
            return nil, "Network timeout"
        end
        if not Script or type(Script.Yield) ~= "function" then
            self:RetainCurlRequest(curl)
            curl = nil
            return nil, "Network scheduler unavailable"
        end
        Script.Yield(10)
    end
    local responseOk, code, response = pcall(function() return curl:GetResponse() end)
    curl = nil
    if not responseOk or not code then
        return nil, "Network error"
    end
    if code == 1 then
        return nil, "Network error"
    end
    if verify_auth_response then
        local timestamp = tonumber(self.SECURITY_HEADERS["X-Timestamp"])
        local valid, msg = self:VerifyResponse(response, timestamp)
        if not valid then
            Logger:Error("Security", "Response verification failed: " .. msg)
            SecurityManager:TriggerViolationUnload()
            return nil, "Response verification failed: " .. msg
        end
    end
    return response
end

function AuthManager:SecureInitialize()
    -- An expired bootstrap lease may be refreshed, but never grants access here.
    return not ShouldUnload() and type(SovereignRuntimeLeaseCheck) == "function"
end

function AuthManager:FinishLogin(key, generation)
    if generation ~= self.loginGeneration or ShouldUnload() or not self:SessionValid() then return false end
    self.userType = self:IsOldUser(key) and USER_TYPE.OLD or USER_TYPE.NEW
    if not self:StartRuntimeLeaseMonitor() and not self.leaseMonitorStarted then
        self.isAuthenticated = false
        self.status = AUTH_STATUS.PENDING
        Logger:Error("SovereignLua", "Runtime lease monitor could not start")
        return false
    end
    -- A saved key never authorizes a session: persist only after the server
    -- accepted it and renewal monitoring started. Disk failures are non-fatal.
    local savedOk, saved = pcall(FileManager.SaveKey, FileManager, key)
    if not savedOk or saved ~= true then
        pcall(Logger.Toast, Logger, "SovereignLua", "Verified, but the license key could not be saved", CONFIG.UI.ToastDuration.Medium)
    end
    return true
end

function AuthManager:SecureLogin(key)
    self.loginRetryBlocked = false
    self.loginGeneration = self.loginGeneration + 1
    local generation = self.loginGeneration
    self.leaseMonitorGeneration = self.leaseMonitorGeneration + 1
    self.leaseMonitorStarted, self.initialLeaseRetryActive = false, false
    self.isAuthenticated, self.status, self.currentKey = false, AUTH_STATUS.PENDING, ""
    RuntimeLeaseState.hardDenied = false
    RuntimeLeaseState.lastVerifiedAt, RuntimeLeaseState.expiresAt = 0, 0
    RuntimeLeaseState.consecutiveFailures, RuntimeLeaseState.firstFailureAt = 0, 0
    if ShouldUnload() then return false end
    key = FileManager.NormalizeLicenseKey(key)
    if not key then
        Logger:Toast("SovereignLua", "Enter a valid license key", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    local officialReady = SovereignOfficial:Begin(key, Utils1:edition(), Utils1:buildInfo())
    if not officialReady then
        Logger:Toast("SovereignLua", SovereignOfficial:StatusMessage(), CONFIG.UI.ToastDuration.Long)
        return false
    end
    self.currentKey = key
    -- Start the bridge grace window when the user actually logs in; the
    -- script may have been loaded at the main menu for several minutes.
    RuntimeLeaseState.startupGraceUntil = RuntimeLeaseNow() + (RuntimeLeaseState.startupGraceSeconds or 300)
    local leaseReady = self:RefreshRuntimeLease(generation)
    if generation ~= self.loginGeneration or ShouldUnload() or self.loginRetryBlocked then return false end
    if not leaseReady and Script and type(Script.Yield) == "function" then
        -- The first present callback can race the bridge/session bootstrap.
        -- Retry once in the scripting thread before treating it as a failure.
        pcall(Script.Yield, 250)
        if generation ~= self.loginGeneration or ShouldUnload() then return false end
        leaseReady = self:RefreshRuntimeLease(generation)
    end
    if generation ~= self.loginGeneration or ShouldUnload() or self.loginRetryBlocked then return false end
    if not leaseReady then
        self.isAuthenticated = false
        self.status = AUTH_STATUS.PENDING
        if not self.initialLeaseRetryActive and Script and type(Script.QueueJob) == "function" then
            self.initialLeaseRetryActive = true
            local queuedOk, queued = pcall(Script.QueueJob, function()
                local recovered = false
                for _ = 1, 4 do
                    Script.Yield(1000)
                    if generation ~= self.loginGeneration or ShouldUnload() then return end
                    local refreshed = self:RefreshRuntimeLease(generation)
                    if generation ~= self.loginGeneration or ShouldUnload() or self.loginRetryBlocked then return end
                    if refreshed then
                        recovered = self:FinishLogin(key, generation)
                        break
                    end
                end
                if generation ~= self.loginGeneration or ShouldUnload() then return end
                self.initialLeaseRetryActive = false
                if not recovered then
                    -- A bridge/TLS miss during the first login is transient in
                    -- practice. Keep the login pending and let the normal
                    -- retry gate try again; the lease monitor remains the
                    -- authority for a genuinely stale authenticated session.
                    self.status = AUTH_STATUS.PENDING
                    self.isAuthenticated = false
                    Logger:Warn("SovereignLua", "Runtime lease validation delayed")
                end
            end)
            if not queuedOk or queued == false then self.initialLeaseRetryActive = false end
        end
        return false
    end
    return self:FinishLogin(key, generation)
end

function SecurityManager:StartIntegrityChecks()
    return true
end
SecurityManager:StartIntegrityChecks()

local AntiHookManager = {
    m_initialized = false,
    m_monitoring = false,
    m_monitor_generation = 0,
    m_last_check_time = 0,
    m_check_interval = 5000,
    m_monitor_check_index = 1,
    m_quickcheck_cooldown_sec = 1.0,
    m_panic_mode = false,
    m_strict_mode = false,
    m_baseline_metatables = {},
    m_baseline_globals = {},
    m_original_refs = {},
    m_local_refs = {},
    m_local_paths = {},
    m_path_parts = {},
    m_checks = nil,
    m_protected_paths = {
        "assert", "collectgarbage", "dofile", "error", "getmetatable",
        "ipairs", "load", "loadstring", "next", "pairs", "pcall",
        "print", "rawequal", "rawget", "rawset", "require",
        "setmetatable", "tonumber", "tostring", "type", "xpcall", "unpack",
        "string.byte", "string.char", "string.find", "string.format",
        "string.gmatch", "string.gsub", "string.len", "string.lower",
        "string.match", "string.rep", "string.reverse", "string.sub", "string.upper",
        "table.concat", "table.insert", "table.remove", "table.sort",
        "math.abs", "math.ceil", "math.cos", "math.floor", "math.max",
        "math.min", "math.random", "math.randomseed", "math.sin", "math.sqrt", "math.tan",
        "os.clock", "os.date", "os.difftime", "os.time",
    },
    m_custom_paths = {},
    m_suspicious_patterns = {"hook", "detour", "patch", "inject", "bytecode", "decompile", "intercept"},
    m_public_violation_message = "Violation detected"
}

function AntiHookManager:_log_violation()
    Logger:Error("AntiHook", self.m_public_violation_message)
end

function AntiHookManager:_raise_violation(hard)
    if hard then
        SovereignLuraphHardFail()
    end
    error(self.m_public_violation_message, 0)
end

function AntiHookManager:_capture_metatable_baseline()
    self.m_baseline_metatables = {}
    local getmt = self:_resolve_function("getmetatable")
    if type(getmt) ~= "function" then
        return
    end
    local libs = {"_G", "string", "table", "math", "os"}
    for _, name in ipairs(libs) do
        local target = (name == "_G") and _G or _G[name]
        local ok, mt = pcall(getmt, target)
        self.m_baseline_metatables[name] = ok and (mt or false) or false
    end
end

function AntiHookManager:_capture_global_baseline()
    self.m_baseline_globals = {}
    for name, _ in pairs(_G) do
        if type(name) == "string" then
            self.m_baseline_globals[name] = true
        end
    end
end

function AntiHookManager:_capture_baselines()
    self:_capture_metatable_baseline()
    self:_capture_global_baseline()
end

function AntiHookManager:EnableStrictMode()
    if self.m_strict_mode then
        return not self.m_panic_mode
    end
    if self.m_precheck_clean == false then
        Logger:Error("AntiHook", "[StrictMode] precheck failed: " .. tostring(self.m_precheck_reason))
        self.m_panic_mode = true
        SecurityManager:TriggerViolationUnload()
        self:_raise_violation(true)
        return false
    end
    self:_capture_global_baseline()
    self.m_strict_mode = true
    return true
end
function AntiHookManager:_check_vm_intact()
    local functions = {"type", "tostring", "pcall", "string.sub", "table.insert"}
    for _, name in ipairs(functions) do
        local fn = _G
        for part in name:gmatch("[^%.]+") do
            if type(fn) ~= "table" then
                return false, "VM missing library: " .. name
            end
            fn = fn[part]
        end
        if type(fn) ~= "function" then
            return false, "VM function missing: " .. name
        end
    end
    return true, nil
end

function AntiHookManager:_resolve_function(path)
    local parts = self.m_path_parts[path]
    if not parts then
        parts = {}
        for key in path:gmatch("[^%.]+") do
            parts[#parts + 1] = key
        end
        self.m_path_parts[path] = parts
    end
    local cur = _G
    for i = 1, #parts do
        if type(cur) ~= "table" then return nil end
        cur = cur[parts[i]]
        if cur == nil then return nil end
    end
    return type(cur) == "function" and cur or nil
end

function AntiHookManager:_store(path, fn)
    if type(fn) == "function" then
        self.m_original_refs[path] = fn
    end
end

function AntiHookManager:_store_local(path, getter, fn)
    if type(fn) == "function" and type(getter) == "function" then
        self.m_original_refs[path] = fn
        self.m_local_refs[path] = getter
        self.m_local_paths[path] = true
    end
end

function AntiHookManager:TrackLocal(path, getter)
    if type(path) ~= "string" or type(getter) ~= "function" then
        return false
    end
    local ok, fn = pcall(getter)
    if ok and type(fn) == "function" then
        self:_store_local(path, getter, fn)
        return true
    end
    return false
end


function AntiHookManager:TrackGlobalPaths(paths)
    if type(paths) ~= "table" then
        return 0
    end
    local tracked = 0
    for _, path in ipairs(paths) do
        if type(path) == "string" and not self.m_original_refs[path] then
            local first = self:_resolve_function(path)
            local second = self:_resolve_function(path)
            if type(first) == "function" and first == second then
                self:_store(path, first)
                tracked = tracked + 1
            end
        end
    end
    return tracked
end

function AntiHookManager:ProtectCheraxApiBoundary(includeNativeApis)
    local paths = {
        "FeatureMgr.AddFeature", "FeatureMgr.AddPlayerFeature", "FeatureMgr.GetFeature", "FeatureMgr.GetFeatureByName",
        "EventMgr.RegisterHandler", "ClickGUI.RenderFeature", "ClickGUI.AddTab", "ClickGUI.AddPlayerTab",
        "ClickGUI.RemoveTab", "ClickGUI.BeginCustomChildWindow", "ClickGUI.EndCustomChildWindow",
        "Curl.Easy", "FileMgr.GetMenuRootPath", "Utils.Joaat", "Utils.GetSelectedPlayer",
        "Script.QueueJob", "Script.Yield", "GUI.AddToast", "Memory.GetBaseAddress", "Memory.Scan",
        "Memory.Rip", "Memory.WriteInt", "Memory.WriteUByte", "Memory.WriteFloat", "Memory.AllocInt",
        "Memory.Free", "NetworkObjectMgr.UnregisterNetworkObject"
    }
    if includeNativeApis then
        local nativePaths = {
            "GTA.SpawnVehicle", "GTA.CreatePed", "GTA.GiveControl", "GTA.TriggerScriptEvent", "GTA.HandleToPointer",
            "ENTITY.DOES_ENTITY_EXIST", "ENTITY.DELETE_ENTITY", "ENTITY.GET_ENTITY_COORDS", "ENTITY.SET_ENTITY_COLLISION",
            "ENTITY.FREEZE_ENTITY_POSITION", "ENTITY.ATTACH_ENTITY_TO_ENTITY", "ENTITY.SET_ENTITY_VISIBLE",
            "PED.SET_PED_COMPONENT_VARIATION", "PED.SET_PED_TO_RAGDOLL", "PED.SET_PED_COMBAT_ATTRIBUTES",
            "STREAMING.REQUEST_MODEL", "STREAMING.HAS_MODEL_LOADED", "STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED",
            "MISC.GET_HASH_KEY", "MISC.SHOOT_SINGLE_BULLET_BETWEEN_COORDS", "MISC.SET_TIME_SCALE",
            "PLAYER.PLAYER_ID", "PLAYER.GET_PLAYER_PED_SCRIPT_INDEX", "PLAYER.SET_PLAYER_WANTED_LEVEL",
            "VEHICLE.SET_VEHICLE_ENGINE_ON", "VEHICLE.SET_VEHICLE_FIXED", "VEHICLE.SET_VEHICLE_DIRT_LEVEL",
            "TASK.TASK_COMBAT_PED", "TASK.CLEAR_PED_TASKS_IMMEDIATELY", "WEAPON.GIVE_WEAPON_TO_PED",
            "OBJECT.CREATE_OBJECT", "NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY"
        }
        for _, path in ipairs(nativePaths) do
            table.insert(paths, path)
        end
    end
    return self:TrackGlobalPaths(paths)
end
function AntiHookManager:_refresh_local_ref(path)
    local getter = self.m_local_refs[path]
    if type(getter) ~= "function" then
        return false
    end
    local ok, fn = pcall(getter)
    if ok and type(fn) == "function" then
        self.m_original_refs[path] = fn
        return true
    end
    return false
end

function AntiHookManager:_count()
    local n = 0
    for _ in pairs(self.m_original_refs) do n = n + 1 end
    return n
end

function AntiHookManager:_pre_pollution_check()
    local critical = {
        "string.match", "string.find", "string.gsub", "string.sub",
        "string.format", "tonumber", "tostring", "type", "pcall", "error",
        "math.random", "os.time", "table.sort", "table.insert"
    }
    for _, path in ipairs(critical) do
        local fn = self:_resolve_function(path)
        if type(fn) ~= "function" then
            return false, "critical missing: " .. path
        end
    end
    return true, nil
end

function AntiHookManager:Initialize()
    if self.m_initialized then return true end
    local clean, reason = self:_pre_pollution_check()
    self.m_precheck_clean = clean
    self.m_precheck_reason = reason
    if not clean and LPH_OBFUSCATED then
        LPH_CRASH()
    end
    if self.m_initialized then return true end
    for _, path in ipairs(self.m_protected_paths) do
        local fn = self:_resolve_function(path)
        if fn then self:_store(path, fn) end
    end
    local local_methods = {
        {name = "Crypto:sha256",                    ref = function() return Crypto.sha256 end},
        {name = "Crypto:hmac_sha256",               ref = function() return Crypto.hmac_sha256 end},
        {name = "Crypto:base64_encode",             ref = function() return Crypto.base64_encode end},
        {name = "Crypto:base64_decode",             ref = function() return Crypto.base64_decode end},
        {name = "Crypto:hex_encode",                ref = function() return Crypto.hex_encode end},
        {name = "SecurityManager:IsSecureUrl",      ref = function() return SecurityManager.IsSecureUrl end},
        {name = "SecurityManager:VerifyResponse",    ref = function() return SecurityManager.VerifyResponse end},
        {name = "SecurityManager:GenerateNonce",     ref = function() return SecurityManager.GenerateNonce end},
        {name = "SecurityManager:SecureRequest",     ref = function() return SecurityManager.SecureRequest end},
        {name = "SecurityManager:ApplySSLOptions",   ref = function() return SecurityManager.ApplySSLOptions end},
        {name = "AuthManager:SessionValid",          ref = function() return AuthManager.SessionValid end},
        {name = "AuthManager:EnforceSession",        ref = function() return AuthManager.EnforceSession end},
        {name = "AuthManager:RefreshRuntimeLease",   ref = function() return AuthManager.RefreshRuntimeLease end},
        {name = "AuthManager:SecureInitialize",      ref = function() return AuthManager.SecureInitialize end},
        {name = "AuthManager:SecureLogin",           ref = function() return AuthManager.SecureLogin end},
        {name = "FileManager:LoadSavedKey",          ref = function() return FileManager.LoadSavedKey end},
        {name = "FileManager:SaveKey",               ref = function() return FileManager.SaveKey end},
        {name = "Logger:Info",                       ref = function() return Logger.Info end},
        {name = "Logger:Error",                      ref = function() return Logger.Error end},
        {name = "Logger:Warn",                       ref = function() return Logger.Warn end},
        {name = "Logger:Toast",                      ref = function() return Logger.Toast end},
    }
    for _, item in ipairs(local_methods) do
        local ok, fn = pcall(item.ref)
        if ok and type(fn) == "function" then
            self:_store_local(item.name, item.ref, fn)
        else
            Logger:Warn("AntiHook", "Local function not ready; skipped: " .. item.name)
        end
    end
    self:_capture_baselines()
    self.m_initialized = true
    return true
end

function AntiHookManager:_monitor_active(generation)
    return self.m_monitoring and self.m_monitor_generation == generation
        and self.m_strict_mode and not self.m_panic_mode and not ShouldUnload()
end

function AntiHookManager:_check_function_integrity(generation)
    -- Only the background monitor supplies a generation. Explicit QuickCheck
    -- and RunFullCheck keep their synchronous, complete verification semantics.
    local sliced = generation ~= nil
    if sliced and not self:_monitor_active(generation) then return true end
    local checked, started = 0, sliced and os.clock() or 0
    local path, orig = next(self.m_original_refs)
    while path ~= nil do
        local getter = self.m_local_refs[path]
        if self.m_local_paths[path] or getter ~= nil then
            if type(orig) ~= "function" then
                SecurityManager:TriggerViolationUnload()
                return false, "Local function reference damaged: " .. path
            end
            if type(getter) ~= "function" then
                SecurityManager:TriggerViolationUnload()
                return false, "Local function checker missing: " .. path
            end
            local ok, cur = pcall(getter)
            if not ok or cur ~= orig then
                SecurityManager:TriggerViolationUnload()
                return false, "Local function replaced: " .. path
            end
        else
            local cur = self:_resolve_function(path)
            if cur == nil then
                SecurityManager:TriggerViolationUnload()
                return false, "Function removed: " .. path
            end
            if cur ~= orig then
                SecurityManager:TriggerViolationUnload()
                return false, "Function reference changed or hooked: " .. path
            end
        end
        path, orig = next(self.m_original_refs, path)
        if sliced then
            checked = checked + 1
            if path ~= nil and (checked >= 12 or os.clock() - started >= 0.0005) then
                Script.Yield(0)
                if not self:_monitor_active(generation) then return true end
                checked, started = 0, os.clock()
            end
        end
    end
    return true, nil
end

function AntiHookManager:_check_metatables()
    local getmt = self.m_original_refs["getmetatable"] or self:_resolve_function("getmetatable")
    if type(getmt) ~= "function" then
        return true, nil
    end
    local libs = {"_G", "string", "table", "math", "os"}
    for _, name in ipairs(libs) do
        local target = (name == "_G") and _G or _G[name]
        local ok, mt = pcall(getmt, target)
        local current = ok and (mt or false) or false
        if current ~= (self.m_baseline_metatables[name] or false) then
            return false, "metatable changed: " .. name
        end
    end
    return true, nil
end

function AntiHookManager:_check_canary()
    local s_sub   = self.m_original_refs["string.sub"]
    local s_gsub  = self.m_original_refs["string.gsub"]
    local s_match = self.m_original_refs["string.match"]
    local s_find  = self.m_original_refs["string.find"]
    local s_fmt   = self.m_original_refs["string.format"]
    local t_ins   = self.m_original_refs["table.insert"]
    local t_sort  = self.m_original_refs["table.sort"]
    local t_con   = self.m_original_refs["table.concat"]
    local m_floor = self.m_original_refs["math.floor"]
    local m_sqrt  = self.m_original_refs["math.sqrt"]
    local m_rand  = self.m_original_refs["math.random"]
    local n_tonum = self.m_original_refs["tonumber"]
    local n_tostr = self.m_original_refs["tostring"]
    local n_type  = self.m_original_refs["type"]
    if not (s_sub and s_gsub and s_match and s_find and s_fmt and t_ins and t_sort and t_con and m_floor and m_sqrt and m_rand and n_tonum and n_tostr and n_type) then
        return false, "Required original reference is missing"
    end
    if n_tonum("  1337  ") ~= 1337 then return false, "Unexpected tonumber behavior" end
    if n_tostr(91337420) ~= "91337420" then return false, "Unexpected tostring behavior" end
    if n_type(nil) ~= "nil" or n_type(true) ~= "boolean" then return false, "Unexpected type behavior" end
    if s_sub("SovereignLuaAntiHook", 1, 12) ~= "SovereignLua" then return false, "Unexpected string.sub behavior" end
    if s_gsub("hello world", "world", "SovereignLua") ~= "hello SovereignLua" then return false, "Unexpected string.gsub behavior" end
    if s_match("auth=success", "auth=(%w+)") ~= "success" then return false, "Unexpected string.match behavior" end
    if s_find("keyauth.win", "win", 1, true) ~= 9 then return false, "Unexpected string.find behavior" end
    if s_fmt("%s|%d|%.2f", "test", 123, 1.5) ~= "test|123|1.50" then return false, "Unexpected string.format behavior" end
    local t = {3, 1, 4, 1, 5}
    t_sort(t)
    if t_con(t, ",") ~= "1,1,3,4,5" then return false, "Unexpected table.sort behavior" end
    t_ins(t, 9)
    if #t ~= 6 or t[6] ~= 9 then return false, "Unexpected table.insert behavior" end
    if m_floor(2.718) ~= 2 then return false, "Unexpected math.floor behavior" end
    if m_sqrt(25) ~= 5 then return false, "Unexpected math.sqrt behavior" end
    local r = m_rand(1, 100)
    if type(r) ~= "number" or r < 1 or r > 100 then return false, "Unexpected math.random behavior" end
    local hash = Crypto.sha256("canary")
    if type(hash) ~= "string" or #hash ~= 32 then
        SecurityManager:TriggerViolationUnload()
        return false, "Unexpected output; signature output may have been hooked"
    end
    return true, nil
end

function AntiHookManager:_check_global_pollution()
    for name, _ in pairs(_G) do
        if type(name) == "string" and not self.m_baseline_globals[name] then
            local lower = name:lower()
            for _, pat in ipairs(self.m_suspicious_patterns) do
                if lower:find(pat, 1, true) then
                    return false, "suspicious global added: " .. name
                end
            end
        end
    end
    return true, nil
end

function AntiHookManager:_get_checks()
    local checks = self.m_checks
    if not checks then
        checks = {
            {false, "Function integrity check", true},
            {false, "Metatable check", false},
            {false, "Canary behavior check", true},
            {false, "Global environment scan", false},
            {false, "VM integrity check", false},
        }
        self.m_checks = checks
    end
    -- Cache only the containers; always resolve current check implementations.
    checks[1][1] = self._check_function_integrity
    checks[2][1] = self._check_metatables
    checks[3][1] = self._check_canary
    checks[4][1] = self._check_global_pollution
    checks[5][1] = self._check_vm_intact
    return checks
end

function AntiHookManager:_run_check(check, generation)
    local fn, name, hard = check[1], check[2], check[3]
    local ok, reason = fn(self, generation)
    if not ok then
        Logger:Error("AntiHook", "[" .. name .. "] " .. tostring(reason))
        self.m_panic_mode = true
        SecurityManager:TriggerViolationUnload()
        self:_raise_violation(hard)
    end
end

function AntiHookManager:_run_full_check()
    local checks = self:_get_checks()
    for _, c in ipairs(checks) do
        self:_run_check(c)
    end
end

function AntiHookManager:QuickCheck()
    if not self.m_strict_mode then return true end
    if self.m_panic_mode then return false end
    if not self.m_initialized then return true end
    local now = os.clock()
    if (now - (self.m_last_check_time or 0)) < (self.m_quickcheck_cooldown_sec or 0) then
        return true
    end
    local ok, reason = self:_check_function_integrity()
    if not ok then
        Logger:Error("AntiHook", "[QuickCheck] " .. tostring(reason))
        SecurityManager:TriggerViolationUnload()
        self:_raise_violation(true)
        return false
    end
    ok, reason = self:_check_canary()
    if not ok then
        Logger:Error("AntiHook", "[QuickCheck] " .. tostring(reason))
        SecurityManager:TriggerViolationUnload()
        self:_raise_violation(true)
        return false
    end
    self.m_last_check_time = now
    return true
end

function AntiHookManager:RunFullCheck()
    if not self.m_strict_mode then return true end
    if self.m_panic_mode then return false end
    if not self.m_initialized then return true end
    local ok, err = pcall(function() self:_run_full_check() end)
    if not ok then
        Logger:Error("AntiHook", "Full check error: " .. tostring(err))
        self.m_panic_mode = true
        SecurityManager:TriggerViolationUnload()
        return false
    end
    return not self.m_panic_mode
end

function AntiHookManager:RunNextMonitoringCheck(generation)
    if not self.m_strict_mode or self.m_panic_mode or not self.m_initialized then
        return false
    end
    local checks = self:_get_checks()
    local index = math.max(1, math.min(#checks, tonumber(self.m_monitor_check_index) or 1))
    local ok, err = pcall(function()
        self:_run_check(checks[index], generation)
    end)
    if not ok then
        Logger:Error("AntiHook", "Monitor check error: " .. tostring(err))
        self.m_panic_mode = true
        SecurityManager:TriggerViolationUnload()
        return false
    end
    if generation ~= nil and not self:_monitor_active(generation) then return false end
    self.m_monitor_check_index = (index % #checks) + 1
    return true
end

function AntiHookManager:StartMonitoring()
    if not self.m_strict_mode or self.m_panic_mode or ShouldUnload() then return end
    if self.m_monitoring then return end
    self.m_monitoring = true
    self.m_monitor_generation = self.m_monitor_generation + 1
    local generation = self.m_monitor_generation
    self.m_monitor_check_index = 1
    Script.QueueJob(function()
        local checkCount = #self:_get_checks()
        local sliceInterval = math.max(250, math.floor(self.m_check_interval / math.max(1, checkCount)))
        local nextInterval = sliceInterval
        while self.m_monitoring and self.m_monitor_generation == generation and self.m_strict_mode and not self.m_panic_mode and not ShouldUnload() do
            Script.Yield(nextInterval)
            if not self.m_monitoring or self.m_monitor_generation ~= generation or not self.m_strict_mode or self.m_panic_mode or ShouldUnload() then
                break
            end
            local started = os.clock()
            self:RunNextMonitoringCheck(generation)
            -- Account for time spent yielding inside reference scans. Preserve
            -- the five-second target round without catch-up work in one frame.
            nextInterval = math.max(1, sliceInterval - math.floor(math.max(0, os.clock() - started) * 1000))
        end
        if self.m_monitor_generation == generation then self.m_monitoring = false end
    end)
end

function AntiHookManager:ProtectFunction(fn, name)
    local self_ref = self
    return function(...)
        if not self_ref:QuickCheck() then
            Logger:Error("AntiHook", "Unusual issue detected")
            SecurityManager:TriggerViolationUnload()
            return nil
        end
        return fn(...)
    end
end

local AntiDumpManager = {
    m_initialized = false,
    m_monitoring = false,
    m_monitor_generation = 0,
    m_panic_mode = false,
    m_original_dump = nil,
    m_original_load = nil,
    m_original_loadstring = nil,
    m_original_getlocal = nil,
    m_original_getupvalue = nil,
    m_dump_hook = nil,
    m_load_hook = nil,
    m_loadstring_hook = nil,
    m_getlocal_hook = nil,
    m_getupvalue_hook = nil,
    m_load_count = 0,
    m_check_interval = 7000,
    m_suspicious_patterns = {
        "\27Lua",
        "string.dump",
        "loadstring",
        "luadec",
        "unluac",
        "decompile",
        "bytecode"
    },
    m_public_violation_message = "Security violation"
}

function AntiDumpManager:_violate(hard)
    self.m_panic_mode = true
    Logger:Error("AntiDump", self.m_public_violation_message)
    SecurityManager:TriggerViolationUnload()
    if hard then
        SovereignLuraphHardFail()
    end
    error(self.m_public_violation_message, 0)
end

function AntiDumpManager:_is_bytecode(chunk)
    if type(chunk) ~= "string" or #chunk < 1 then
        return false
    end
    return chunk:byte(1) == 0x1B or chunk:sub(1, 4) == "\27Lua"
end

function AntiDumpManager:_has_suspicious_text(chunk)
    if type(chunk) ~= "string" then
        return false
    end
    local lower = chunk:lower()
    for _, pat in ipairs(self.m_suspicious_patterns) do
        if lower:find(pat:lower(), 1, true) then
            return true
        end
    end
    return false
end

function AntiDumpManager:_wrap_dump()
    local manager = self
    local orig = self.m_original_dump
    if type(orig) ~= "function" then
        return
    end
    self.m_dump_hook = function(fn, strip)
        manager:_violate(true)
        return orig(fn, strip)
    end
    string.dump = self.m_dump_hook
end

function AntiDumpManager:_wrap_load()
    local manager = self
    local orig = self.m_original_load
    if type(orig) ~= "function" then
        return
    end
    self.m_load_hook = function(chunk, chunkname, mode, env)
        manager.m_load_count = manager.m_load_count + 1
        if manager:_is_bytecode(chunk) then
            manager:_violate(true)
        end
        if manager:_has_suspicious_text(chunk) then
            Logger:Warn("AntiDump", manager.m_public_violation_message)
        end
        return orig(chunk, chunkname, mode, env)
    end
    load = self.m_load_hook
end

function AntiDumpManager:_wrap_loadstring()
    local manager = self
    local orig = self.m_original_loadstring
    if type(orig) ~= "function" then
        return
    end
    self.m_loadstring_hook = function(chunk, chunkname)
        manager.m_load_count = manager.m_load_count + 1
        if manager:_is_bytecode(chunk) then
            manager:_violate(true)
        end
        if manager:_has_suspicious_text(chunk) then
            Logger:Warn("AntiDump", manager.m_public_violation_message)
        end
        return orig(chunk, chunkname)
    end
    loadstring = self.m_loadstring_hook
end

function AntiDumpManager:_wrap_debug_extractors()
    if type(debug) ~= "table" then
        return
    end
    local manager = self
    if type(debug.getlocal) == "function" then
        self.m_original_getlocal = debug.getlocal
        self.m_getlocal_hook = function(...)
            manager:_violate(true)
        end
        rawset(debug, "getlocal", self.m_getlocal_hook)
    end
    if type(debug.getupvalue) == "function" then
        self.m_original_getupvalue = debug.getupvalue
        self.m_getupvalue_hook = function(...)
            manager:_violate(true)
        end
        rawset(debug, "getupvalue", self.m_getupvalue_hook)
    end
end

function AntiDumpManager:ScanForDumpActivity()
    if self.m_panic_mode then
        return false
    end
    if self.m_dump_hook and string.dump ~= self.m_dump_hook then
        self:_violate(true)
        return false
    end
    if self.m_load_hook and load ~= self.m_load_hook then
        self:_violate(true)
        return false
    end
    if self.m_loadstring_hook and loadstring ~= self.m_loadstring_hook then
        self:_violate(true)
        return false
    end
    if self.m_getlocal_hook and debug and debug.getlocal ~= self.m_getlocal_hook then
        self:_violate(true)
        return false
    end
    if self.m_getupvalue_hook and debug and debug.getupvalue ~= self.m_getupvalue_hook then
        self:_violate(true)
        return false
    end
    if self.m_load_count > 50 then
        self:_violate(false)
        return false
    end
    self.m_load_count = 0
    return true
end

function AntiDumpManager:StartMonitoring()
    if self.m_monitoring or self.m_panic_mode or ShouldUnload() then return end
    self.m_monitoring = true
    self.m_monitor_generation = self.m_monitor_generation + 1
    local generation = self.m_monitor_generation
    local manager = self
    Script.QueueJob(function()
        while manager.m_monitoring and manager.m_monitor_generation == generation and not manager.m_panic_mode and not ShouldUnload() do
            Script.Yield(manager.m_check_interval)
            if not manager.m_monitoring or manager.m_monitor_generation ~= generation or manager.m_panic_mode or ShouldUnload() then
                break
            end
            manager:ScanForDumpActivity()
        end
        if manager.m_monitor_generation == generation then manager.m_monitoring = false end
    end)
end

function AntiDumpManager:IntegrateWithAntiHook()
    if not AntiHookManager or not AntiHookManager._store then
        return
    end
    if self.m_dump_hook then
        AntiHookManager:_store("string.dump", string.dump)
    end
    if self.m_load_hook then
        AntiHookManager:_store("load", load)
    end
    if self.m_loadstring_hook then
        AntiHookManager:_store("loadstring", loadstring)
    end
    if self.m_getlocal_hook then
        AntiHookManager:_store("debug.getlocal", debug.getlocal)
    end
    if self.m_getupvalue_hook then
        AntiHookManager:_store("debug.getupvalue", debug.getupvalue)
    end
end

function AntiDumpManager:Initialize()
    if self.m_initialized then
        return true
    end
    self.m_original_dump = string.dump
    self.m_original_load = load
    self.m_original_loadstring = loadstring
    self:_wrap_dump()
    self:_wrap_load()
    self:_wrap_loadstring()
    self:_wrap_debug_extractors()
    self:IntegrateWithAntiHook()
    self:StartMonitoring()
    self.m_initialized = true
    return true
end

