end

function SyncNodeManager:SetPlayerModel(model)
    self.PlayerModel = model
end

function SyncNodeManager:ParsePlayerModelInput(input)
    local text = tostring(input or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then
        return nil, "Enter a model hash or model name"
    end
    local model
    local hex = text:match("^0[xX]([%da-fA-F]+)$")
    if hex then
        model = tonumber(hex, 16)
    elseif text:match("^%-?%d+$") then
        model = tonumber(text, 10)
    else
        model = Utils.Joaat(text)
    end

    if not model then
        return nil, "Invalid model input format"
    end

    local validOk, isValid = pcall(function()
        return menu.nativeApis.STREAMING.IS_MODEL_VALID(model)
    end)
    if validOk and not isValid then
        return nil, "Model not found or unavailable"
    end

    local pedOk, isPed = pcall(function()
        return menu.nativeApis.STREAMING.IS_MODEL_A_PED(model)
    end)
    if pedOk and not isPed then
        return nil, "This is not a character model"
    end
    return model
end

function SyncNodeManager:SetPlayerModelFromInput(input)
    local model, err = self:ParsePlayerModelInput(input)
    if not model then
        Logger:Toast("Player model spoofing", err or "Invalid model input", CONFIG.UI.ToastDuration.Short)
        return false
    end
    self:SetPlayerModel(model)
    Logger:Toast("Player model spoofing", "Model set: " .. tostring(model), CONFIG.UI.ToastDuration.Short)
    return true
end

function SyncNodeManager:RegisterHandler(nodeType, handler)
    if not self.handlers[nodeType] then
        self.handlers[nodeType] = {}
    end
    table.insert(self.handlers[nodeType], handler)
    table.sort(self.handlers[nodeType], function(a, b)
        return (a.priority or 0) < (b.priority or 0)
    end)
end

function SyncNodeManager:RegisterHandlers(handlers)
    for nodeType, handlerList in pairs(handlers) do
        if type(handlerList) == "table" and handlerList.id then
            self:RegisterHandler(nodeType, handlerList)
        elseif type(handlerList) == "table" then
            for _, handler in ipairs(handlerList) do
                self:RegisterHandler(nodeType, handler)
            end
        end
    end
end

function SyncNodeManager:GetTaskTreeData(node)
    local mt = getmetatable(node)
    if not mt then
        return nil
    end
    local success, treeData = pcall(function()
        return mt.__index(node, "taskTreeData")
    end)
    return success and treeData or nil
end
function SyncNodeManager:ForeachTaskSlot(node, callback)
    local treeData = self:GetTaskTreeData(node)
    if not treeData then
        return
    end
    for i = 0, 8 do
        local success, slot = pcall(function()
            return treeData[i]
        end)
        if success and slot then
            local cbSuccess, err = pcall(callback, slot, i)
            if not cbSuccess then
                Logger:Error("Error", string.format("Task slot [%d] processing error: %s", i, err))
            end
        end
    end
end
function SyncNodeManager:SwapVehicleModel(node, mapping)
    local targetHash = type(mapping.to) == "string" and menu.nativeApis.MISC.GET_HASH_KEY(mapping.to) or mapping.to
    local sourceHash = type(mapping.from) == "string" and menu.nativeApis.MISC.GET_HASH_KEY(mapping.from) or mapping.from
    if node.modelHash and node.modelHash == sourceHash then
        node.modelHash = targetHash
        return true
    end
    return false
end
function SyncNodeManager:SwapPedModel(node)
    local sourceHash = node.modelHash or node.ModelHash
    if not sourceHash then return false end
    local replacement = self.CONSTANTS.PED_SWAPS[sourceHash]
    if replacement then
        if node.modelHash ~= nil then
            node.modelHash = replacement
        end
        if node.ModelHash ~= nil then
            node.ModelHash = replacement
        end
        return true
    end
    return false
end
function SyncNodeManager:FillArray(target, value, count)
    for i = 1, count do
        target[i] = value
    end
end
function SyncNodeManager:RandomFloat(min, max)
    return min + math.random() * (max - min)
end

