local function SovereignReadS32LE(bytes, index)
    local value = bytes[index] + bytes[index + 1] * 0x100 + bytes[index + 2] * 0x10000 + bytes[index + 3] * 0x1000000
    if value >= 0x80000000 then
        value = value - 0x100000000
    end
    return value
end

local function SovereignReadS8(value)
    return value >= 0x80 and (value - 0x100) or value
end

local function SovereignReadBytes(addr, count)
    local bytes = {}
    for i = 0, count - 1 do
        bytes[#bytes + 1] = Memory.ReadUByte(addr + i)
    end
    return bytes
end

local function SovereignResolveSimpleGetter(fnAddr, thisAddr, depth)
    depth = depth or 0
    if not fnAddr or fnAddr == 0 or depth > 3 then
        return nil
    end
    local bytes = SovereignReadBytes(fnAddr, 16)
    -- mov rax, [rcx]; jmp qword ptr [rax+imm8]
    if bytes[1] == 0x48 and bytes[2] == 0x8B and bytes[3] == 0x01 and bytes[4] == 0x48 and bytes[5] == 0xFF and bytes[6] == 0x60 then
        local vtbl = Memory.ReadLong(thisAddr)
        return SovereignResolveSimpleGetter(Memory.ReadLong(vtbl + bytes[7]), thisAddr, depth + 1)
    end
    -- mov rax, [rip+disp32]; ret
    if bytes[1] == 0x48 and bytes[2] == 0x8B and bytes[3] == 0x05 then
        return Memory.ReadLong(fnAddr + 7 + SovereignReadS32LE(bytes, 4))
    end
    -- lea rax, [rip+disp32]; ret
    if bytes[1] == 0x48 and bytes[2] == 0x8D and bytes[3] == 0x05 then
        return fnAddr + 7 + SovereignReadS32LE(bytes, 4)
    end
    if bytes[1] == 0xE9 then
        return SovereignResolveSimpleGetter(fnAddr + 5 + SovereignReadS32LE(bytes, 2), thisAddr, depth + 1)
    end
    if bytes[1] == 0xEB then
        return SovereignResolveSimpleGetter(fnAddr + 2 + SovereignReadS8(bytes[2]), thisAddr, depth + 1)
    end
    if bytes[1] == 0x48 and bytes[2] == 0x83 and bytes[3] == 0xC1 and bytes[5] == 0xE9 then
        return SovereignResolveSimpleGetter(fnAddr + 9 + SovereignReadS32LE(bytes, 6), thisAddr + SovereignReadS8(bytes[4]), depth + 1)
    end
    if bytes[1] == 0x48 and bytes[2] == 0x8B and bytes[3] == 0x81 then
        return Memory.ReadLong(thisAddr + SovereignReadS32LE(bytes, 4))
    end
    if bytes[1] == 0x48 and bytes[2] == 0x8B and bytes[3] == 0x41 then
        return Memory.ReadLong(thisAddr + SovereignReadS8(bytes[4]))
    end
    if bytes[1] == 0x48 and bytes[2] == 0x8D and bytes[3] == 0x81 then
        return thisAddr + SovereignReadS32LE(bytes, 4)
    end
    if bytes[1] == 0x48 and bytes[2] == 0x8D and bytes[3] == 0x41 then
        return thisAddr + SovereignReadS8(bytes[4])
    end
    return nil
end

local function SovereignValidatePlayerSyncTree(treeAddr, netAddr)
    if not treeAddr or treeAddr == 0 then
        return false
    end
    local ok, valid = pcall(function()
        return Memory.ReadLong(treeAddr + 0x08) == netAddr
            and Memory.ReadUInt(treeAddr + 0x20) <= 128
            and Memory.ReadUInt(treeAddr + 0x24) <= 128
    end)
    return ok and valid or false
end

local function SovereignResolvePlayerSyncTreeFromNetObject(netAddr)
    local vtbl = Memory.ReadLong(netAddr)
    for _, offset in ipairs({0x58, 0x60, 0x48, 0x50, 0x68, 0x70}) do
        local ok, candidate = pcall(function()
            return SovereignResolveSimpleGetter(Memory.ReadLong(vtbl + offset), netAddr)
        end)
        if ok and SovereignValidatePlayerSyncTree(candidate, netAddr) then
            return candidate
        end
    end
    return nil
end

local function SovereignReadSecondaryPartialAnim(treeAddr)
    if not treeAddr or treeAddr == 0 then
        return nil
    end
    local appearanceBase = treeAddr + 0x39F0
    local secondaryBase = appearanceBase + 0x3F0
    return {
        tree = treeAddr,
        appearance = appearanceBase,
        secondary = secondaryBase,
        phone = Memory.ReadUByte(secondaryBase + 0x37) ~= 0,
        phoneSecondary = Memory.ReadUByte(secondaryBase + 0x38) ~= 0,
        isBlocked = Memory.ReadUByte(secondaryBase + 0x39) ~= 0,
        phoneMode = Memory.ReadUInt(appearanceBase + 0x438),
    }
end

function SecondaryPartialAnimMonitor:UpdateFromNetAddress(netAddr)
    if not netAddr or netAddr == 0 then
        return nil
    end
    local tree = SovereignResolvePlayerSyncTreeFromNetObject(netAddr)
    if not tree then
        return nil
    end
    self.tree = tree
    return SovereignReadSecondaryPartialAnim(tree)
end

function SecondaryPartialAnimMonitor:Update(pPhysical)
    if not pPhysical then
        return nil
    end
    local ok, data = pcall(function()
        local physAddr = pPhysical:GetAddress()
        if not physAddr or physAddr == 0 then
            return nil
        end
        return self:UpdateFromNetAddress(Memory.ReadLong(physAddr + 0xD0))
    end)
    if ok then
        return data
    end
    return nil
end

function SecondaryPartialAnimMonitor:UpdateFromNetObject(netObject)
    if not netObject then
        return nil
    end
    local ok, data = pcall(function()
        local entity = netObject:GetEntity()
        if entity then
            local byEntity = self:Update(entity)
            if byEntity then
                return byEntity
            end
        end
        local objectId = netObject.ObjectID
        if objectId == nil then
            return nil
        end
        local resolvedNetObject = NetworkObjectMgr.GetNetworkObject(objectId, true)
        if not resolvedNetObject then
            return nil
        end
        local resolvedEntity = resolvedNetObject:GetEntity()
        if not resolvedEntity then
            return nil
        end
        return self:Update(resolvedEntity)
    end)
    if ok then
        return data
    end
    return nil
end

function SecondaryPartialAnimMonitor:Get()
    return SovereignReadSecondaryPartialAnim(self.tree)
end
