            node.taskIndex = math.random(0, 8)
            node.taskData.TaskType = dangerousTasks[math.random(1, #dangerousTasks)]
            node.taskData.TaskDataSize = 420
        end
    },
    {
        id = "TaskSequence",
        priority = 100,
        condition = function() return SyncNodeManager.states.TaskSequence end,
        execute = function(node, ctx)
            node.hasSequence = true 
            if node.taskData then
                for i = 0, math.min(node.numTasks - 1, 50) do
                    local task = node.taskData[i]
                    if task and task.TaskData then
                        task.TaskType = eTaskTypeIndex.CTaskUseSequence
                    end
                end
            end
        end
    }
}

local RideTestHandler = {
    id = "AllTask",
    priority = 100,
    condition = function() return SyncNodeManager.states.T_Ride end,
    execute = function(node, ctx)
        local currentTime = menu.nativeApis.MISC.GET_GAME_TIMER()
        if currentTime - SyncNodeManager.lastTaskSwitch > 5 then
            SyncNodeManager.currentTestTask = (SyncNodeManager.currentTestTask + 1) % 531
            SyncNodeManager.lastTaskSwitch = currentTime
        end
        SyncNodeManager:ForeachTaskSlot(node, function(slot, index)
            node.scriptCommand = math.random(0, 75)
            node.taskStage = math.random(0, 6)
            slot.taskActive = true
            slot.taskType = SyncNodeManager.currentTestTask
            slot.taskPriority = math.random(0, 3)
        end)
    end
}

local SubcarNodeHandler = {
    id = "subcar",
    priority = 100,
    condition = function()
        return SyncNodeManager.states.CrashState
            and SyncNodeManager.states.subcar1
            and Sovereign.GetPlayerCount() <= 1
    end,
    execute = function(node, ctx)
        if not ctx.pPhysical then
            return
        end
        local addr = ctx.pPhysical:GetAddress()
        if not addr or not _G.g_subcar_vehicles[addr] then
            return
        end
        if ctx.nodeType == eSyncDataNode.CVehicleControlDataNode then
            node.isSubCar = true
        elseif ctx.nodeType == eSyncDataNode.CVehicleScriptGameStateDataNode then
            node.lockedToXY = true
        elseif ctx.nodeType == eSyncDataNode.CHeliControlDataNode then
            node.isSubCar = true
        end
    end
}

function SyncNodeManager:Initialize()
    self:RegisterHandler(eSyncDataNode.CPhysicalAttachDataNode, AttachmentCrashHandler)
    self:RegisterHandler(eSyncDataNode.CPedAttachDataNode, PedAttachHandler)
    self:RegisterHandler(eSyncDataNode.CPlayerAppearanceDataNode, InteriorIndexHandlers[1])
    self:RegisterHandler(eSyncDataNode.CPedAppearanceDataNode, InteriorIndexHandlers[2])
    self:RegisterHandler(eSyncDataNode.CDynamicEntityGameStateDataNode, InteriorIndexHandlers[3])
    self:RegisterHandler(eSyncDataNode.CDynamicEntityGameStateDataNode, InteriorIndexHandlers[4])
    self:RegisterHandler(eSyncDataNode.CPlayerGameStateDataNode, InteriorIndexHandlers[5])
    self:RegisterHandlers({[eSyncDataNode.CPlayerAppearanceDataNode] = {InvalidModelHandlers[1], PlayerModelSpoofHandlers[1]},[eSyncDataNode.CPlayerCreationDataNode] = {InvalidModelHandlers[2], PlayerModelSpoofHandlers[2]},})
    self:RegisterHandlers({[eSyncDataNode.CPedCreationDataNode] = {ComponentCrashHandler}, [eSyncDataNode.CVehicleCreationDataNode] = {OverflowCrashHandler, LandingGearHandler[1], TrainCrashHandlers[3]},})
    self:RegisterHandler(eSyncDataNode.CPlaneGameStateDataNode, LandingGearHandler[2])
    self:RegisterHandler(eSyncDataNode.CTrainGameStateDataNode, LandingGearHandler[3])
    self:RegisterHandler(eSyncDataNode.CObjectGameStateDataNode, ObjGameState)
    self:RegisterHandler(eSyncDataNode.CVehicleGadgetDataNode, OutOfGadgetType[1])
    self:RegisterHandler(eSyncDataNode.CVehicleAppearanceDataNode, OutOfGadgetType[2])
    self:RegisterHandler(eSyncDataNode.CPickupCreationDataNode , WeaponComponentsCrash_)
    self:RegisterHandler(eSyncDataNode.CPedGameStateDataNode , WeaponComponentsCrash_)
    self:RegisterHandler(eSyncDataNode.CTrainGameStateDataNode, TrainCrashHandlers[1])
    self:RegisterHandler(eSyncDataNode.CEntityScriptGameStateDataNode, TrainCrashHandlers[2])
    self:RegisterHandler(eSyncDataNode.CVehicleTaskDataNode, HeliTaskHandlers[1])
    self:RegisterHandler(eSyncDataNode.CVehicleProximityMigrationDataNode, HeliTaskHandlers[2])
    self:RegisterHandlers({[eSyncDataNode.CPedTaskTreeDataNode] = {HeliRappelHandlers[1], HeliRappelV2Handler, RideTestHandler}, [eSyncDataNode.CPlaneGameStateDataNode] = {HeliRappelHandlers[2]}})
    self:RegisterHandler(eSyncDataNode.CPedTaskSpecificDataNode, InvalidScenarioCrash)
    self:RegisterHandler(eSyncDataNode.CVehicleControlDataNode, SubcarNodeHandler)
    self:RegisterHandler(eSyncDataNode.CVehicleScriptGameStateDataNode, SubcarNodeHandler)
    self:RegisterHandler(eSyncDataNode.CHeliControlDataNode, SubcarNodeHandler)
end

function SyncNodeManager:OnWriteSyncData(nodeType, node, pPhysical, isExclusive, exclusivePlayer)
    local handlers = self.handlers[nodeType]
    if not handlers or #handlers == 0 then
        return
    end
    local ctx = {
        nodeType = nodeType,
        pPhysical = pPhysical,
        isExclusive = isExclusive,
        exclusivePlayer = exclusivePlayer,
    }
    for _, handler in pairs(handlers) do
        local success, shouldExecute = pcall(handler.condition)
        if success and shouldExecute then
            local execSuccess, err = pcall(function()
                handler.execute(node, ctx)
            end)
            if not execSuccess then
                Logger:Error("SovereignLua",string.format("Handler [%s] execution error: %s", handler.id, tostring(err)))
                handler.condition = function()
                    return false
                end
            end
        end
    end
end
SyncNodeManager:Initialize()
EventMgr.RegisterHandler(eLuaEvent.ON_SYNC_DATA_NODE, function(nodeType, node, pPhysical, isExclusive, exclusivePlayer)
    SyncNodeManager:OnWriteSyncData(nodeType, node, pPhysical, isExclusive, exclusivePlayer)
end)

local NodeDataProtectionManager = {
    handlers = {},
    states = {
        ProtectInvalidMount = false,
        ProtectInvalidTask = false,
        ProtectInvalidPedModel = false,
        ProtectTrainData = false,
        ProtectInvalidPhysicalAttach = false,
        ProtectPedVehicleAttach = false,
    },
    BLOCKED_PED_MODELS = {
        [0x2D7030F3] = "Invalid model",
        [0x3F039CBA] = "Invalid model",
        [0x856CFB02] = "Invalid model",
        [0x38951A1B] = "CS_Lazlow",
        [0xB594F5C3] = "Invalid-texture crash ped",
        [0x450EEF9D] = "Invalid-texture crash ped",
        [0xD2EE1337] = "Invalid-texture crash ped",
        [0x1D953580] = "CS_LesterCrest_3",
        [0xB63911D] = "CS_LesterCrest_2",
        [0xB3D82D2F] = "Invalid-task crash ped",
        [0x53536529] = "Invalid-task crash ped",
        [0x26BEBE36] = "CS_TaoCheng2",
        [0x8864083D] = "CS_TaoCheng",
        [0xC314F727] = "Cs_Gurk",
    }
}
function NodeDataProtectionManager:RegisterHandler(nodeType, handler)
    if not self.handlers[nodeType] then
        self.handlers[nodeType] = {}
    end
    for _,existing in ipairs(self.handlers[nodeType]) do
        if existing.id==handler.id then return false end
    end
    table.insert(self.handlers[nodeType], handler)
    table.sort(self.handlers[nodeType], function(a, b)
        return (a.priority or 0) < (b.priority or 0)
    end)
end
function NodeDataProtectionManager:RegisterHandlers(handlers)
    for nodeType, handlerList in pairs(handlers) do
        if type(handlerList) == "table" and handlerList.id then
            self:RegisterHandler(nodeType, handlerList)
        else
            for _, handler in ipairs(handlerList) do
                self:RegisterHandler(nodeType, handler)
            end
        end
    end
end
function NodeDataProtectionManager:Report(ctx,message)
    local key="node:"..tostring(ctx.handlerId)..":"..tostring(ctx.playerId)
    if not SovereignProtectionFeedback:Allow(key,3) then return end
    local text=type(message)=="function" and message() or tostring(message)
    SovereignProtectionFeedback:Notice(key,text,"warning",4)
    SovereignProtectionFeedback:Log(key,"info",text)
end

NodeDataProtectionManager.EvaluateHandler = LPH_NO_VIRTUALIZE(function(handler, node, ctx)
    ctx.handlerId=handler.id
    if handler.condition and not handler.condition() then
        return true
    end
    return handler.execute(node, ctx)
end)

NodeDataProtectionManager.ProcessNode = LPH_NO_VIRTUALIZE(function(self, node, ctx)
    local nodeType = node:GetNodeType()
    local handlers = self.handlers[nodeType]
    if not handlers then return true end
    for _,handler in ipairs(handlers) do
        if handler.observeOnly then
            -- Keep observations in this callback only. Every blocking check in
            -- the update finishes before optional scoring reads or DB writes.
            local ok,enabled=true,true
            if handler.condition then ok,enabled=pcall(handler.condition) end
            if ok and enabled then
                local pending=ctx.observers
                if not pending then pending={};ctx.observers=pending end
                pending[#pending+1]={handler=handler,node=node}
            elseif not ok then
                Logger:Error("NodeDataProtection",string.format("Handler [%s] condition exception: %s",handler.id,tostring(enabled)))
            end
        else
            local success,result=pcall(self.EvaluateHandler,handler,node,ctx)
            if not success then
                Logger:Error("NodeDataProtection",string.format("Handler [%s] execution exception: %s",handler.id,tostring(result)))
            elseif result==false then
                return false
            end
        end
    end
    return true
end)

NodeDataProtectionManager.ProcessObservers = LPH_NO_VIRTUALIZE(function(self,ctx)
    local pending=ctx.observers
    if not pending then return end
    for _,entry in ipairs(pending) do
        local success,result=pcall(self.EvaluateHandler,entry.handler,entry.node,ctx)
        if not success then
            Logger:Error("NodeDataProtection",string.format("Observer [%s] execution exception: %s",entry.handler.id,tostring(result)))
        end
    end
    ctx.observers=nil
end)

local NodeDataProtectionHandlers = {
    {
        id = "Protect_InvalidMount",
        priority = 1000,
        nodeType = eSyncDataNode.CPedGameStateDataNode,
        condition = function()
            return NodeDataProtectionManager.states.ProtectInvalidMount
        end,
        execute = function(node, ctx)
            local pedNode = node:As("CPedGameStateDataNode")
            if pedNode and pedNode.onMount then
                NodeDataProtectionManager:Report(ctx,function() return string.format("Invalid mount crash blocked. Source: %s", ctx.playerName) end)
                return false
            end
            return true
        end
    },
    -- Task 492 will not proceed through CVehicleProximityMigrationDataNode, not sure what other tasks will go through this node
    -- Task 457 and 483 are also found in some crash mods, so also block them just in case
    -- We can't just block all invalid tasks because some tasks with invalid data will not crash and are used by mods, so we only block the ones that are known to cause crashes.
    {
        id = "Protect_InvalidTaskType",
        priority = 1000,
        nodeType = eSyncDataNode.CVehicleProximityMigrationDataNode,
        condition = function()
            return NodeDataProtectionManager.states.ProtectInvalidTask
        end,
        execute = function(node, ctx)
            local vehicleNode = node:As("CVehicleProximityMigrationDataNode")
            if vehicleNode and (vehicleNode.taskType == eTaskTypeIndex.CTaskVehicleHeliProtect or vehicleNode.taskType == eTaskTypeIndex.CTaskVehicleGoToSubmarine or vehicleNode.taskType == eTaskTypeIndex.CTaskVehicleLandPlane) then
                NodeDataProtectionManager:Report(ctx,function() return string.format("Invalid task crash V1 blocked. Source: %s", ctx.playerName) end)
                return false
            end
            if vehicleNode and vehicleNode.taskMigrationDataSize and vehicleNode.taskMigrationDataSize > 255 then
                if type(ctx.playerId)=="number" and ctx.playerId>=0 and ctx.playerId<32
                    and SovereignProtectionFeedback:Allow("task-overflow-mark:"..ctx.playerId,10) then
                    pcall(ModderDB.AddModderByPlayerId,ctx.playerId,"Task data overflow - Sovereign")
                end
                NodeDataProtectionManager:Report(ctx,function() return string.format("Invalid task overflow crash V1 blocked. Source: %s", ctx.playerName) end)
                return false
            end
            return true
        end
    },
    {
        id = "Protect_InvalidTaskType",
        priority = 1000,
        nodeType = eSyncDataNode.CVehicleTaskDataNode,
        condition = function()
            return NodeDataProtectionManager.states.ProtectInvalidTask
        end,
        execute = function(node, ctx)
            local vehicleNode = node:As("CVehicleTaskDataNode")
            if vehicleNode and (vehicleNode.taskType == eTaskTypeIndex.CTaskVehicleHeliProtect or vehicleNode.taskType == eTaskTypeIndex.CTaskVehicleGoToSubmarine or vehicleNode.taskType == eTaskTypeIndex.CTaskVehicleLandPlane) then
                NodeDataProtectionManager:Report(ctx,function() return string.format("Invalid task crash V2 blocked. Source: %s", ctx.playerName) end)
                return false
            end
            if vehicleNode and vehicleNode.taskDataSize and vehicleNode.taskDataSize > 255 then
                if type(ctx.playerId)=="number" and ctx.playerId>=0 and ctx.playerId<32
                    and SovereignProtectionFeedback:Allow("task-overflow-mark:"..ctx.playerId,10) then
                    pcall(ModderDB.AddModderByPlayerId,ctx.playerId,"Task data overflow - Sovereign")
                end
                NodeDataProtectionManager:Report(ctx,function() return string.format("Task data overflow blocked. Source: %s", ctx.playerName) end)
                return false
            end
            return true
        end
    },
    {
        id = "Protect_InvalidPedModel",
        priority = 1000,
        nodeType = eSyncDataNode.CPedCreationDataNode,
        condition = function()
            return NodeDataProtectionManager.states.ProtectInvalidPedModel
        end,
        execute = function(node, ctx)
            local creationNode = node:As("CPedCreationDataNode")
            if not creationNode then
                return true
            end
            local model=math.tointeger(creationNode.modelHash)
            local blockedInfo = model and NodeDataProtectionManager.BLOCKED_PED_MODELS[model & 0xFFFFFFFF]
            if blockedInfo then
                NodeDataProtectionManager:Report(ctx,function() return string.format("%s Source: %s,\n Model hash=0x%X", blockedInfo, ctx.playerName, creationNode.modelHash) end)
                return false
            end
            return true
        end
    },
    {
        id = "Protect_InvalidTrainState",
        priority = 1000,
        nodeType = eSyncDataNode.CTrainGameStateDataNode,
        condition = function()
            return NodeDataProtectionManager.states.ProtectTrainData
        end,
        execute = function(node, ctx)
            local trainNode = node:As("CTrainGameStateDataNode")
            if not trainNode then
                return true
            end
            if trainNode.TrackID then
                if trainNode.TrackID >= 12 or trainNode.TrackID < -1 then
                    NodeDataProtectionManager:Report(ctx,function() return string.format("Invalid train track ID blocked: %d\nSource: %s",trainNode.TrackID, ctx.playerName) end)
                    return false
                end
            end
            if trainNode.LinkedToForwardID and trainNode.LinkedToBackwardID then
                if trainNode.LinkedToForwardID == trainNode.LinkedToBackwardID and trainNode.LinkedToForwardID ~= 0 then
                    NodeDataProtectionManager:Report(ctx,function() return string.format("Cyclic train link blocked\nSource: %s", ctx.playerName) end)
                    return false
                end
            end
            if trainNode.CarriageConfigIndex and trainNode.CarriageConfigIndex >= 28 then
                NodeDataProtectionManager:Report(ctx,function() return string.format("Abnormal train carriage configuration blocked\nSource: %s", ctx.playerName) end)
                return false
            end
            return true
        end
    },
    {
        id = "Protect_InvalidPhysicalAttach",
        priority = 100,
        nodeType = eSyncDataNode.CPhysicalAttachDataNode,
        condition = function()
            return NodeDataProtectionManager.states.ProtectInvalidPhysicalAttach
        end,
        execute = function(node, ctx)
            local attachNode = node:As("CPhysicalAttachDataNode")
            if not attachNode then
                return true
            end
            if attachNode.attached and type(ctx.netObjectId)=="number"
                and attachNode.attachedObjectID == ctx.netObjectId then
                NodeDataProtectionManager:Report(ctx,function() return string.format("Abnormal attachment blocked\nSource: %s", ctx.playerName) end)
                return false
            end
            return true
        end
    },
    {
        id = "Protect_PedVehicleAttach",
        priority = 950,
        nodeType = eSyncDataNode.CPhysicalAttachDataNode,
        condition = function()
            return NodeDataProtectionManager.states.ProtectPedVehicleAttach
        end,
        execute = function(node, ctx)
            local attachNode = node:As("CPhysicalAttachDataNode")
            if not attachNode or not attachNode.attached then
                return true
            end
            -- Entity types alone do not establish a crash: legitimate animations attach peds to vehicles.
            local function finite(value)
                return type(value)=="number" and value==value and math.abs(value)<rawget(math, "huge")
            end
            local invalid=false
            for _,field in ipairs({"InvMassScaleA","InvMassScaleB"}) do
                local value=attachNode[field]
                if value~=nil and (not finite(value) or value<0) then invalid=true end
            end
            for _,field in ipairs({"attachmentOffset","attachmentParentOffset","attachmentQuat"}) do
                local value=attachNode[field]
                if value and (not finite(value.x) or not finite(value.y) or not finite(value.z)) then invalid=true end
            end
            if invalid then
                NodeDataProtectionManager:Report(ctx,function() return "Invalid attachment blocked. Source player: "..ctx.playerName end)
                return false
            end
            return true
        end
    }
}

local PlayerCheatDetector = {
    enabled = false,
    running = false,
    score = {},
    reasons = {},
    lastReport = {},
    reportThreshold = 8,
}

function PlayerCheatDetector:SetEnabled(enabled)
    self.enabled = enabled == true
    if self.enabled then
        self:Start()
    end
end

function PlayerCheatDetector:GetName(playerId)
    local ok, name = pcall(Players.GetName, playerId)
    if ok and name and name ~= "" then
        return name
    end
    return "Player " .. tostring(playerId)
end

function PlayerCheatDetector:AddDetection(playerId, reason, weight)
    if not self.enabled or not playerId or playerId < 0 or playerId == GTA.GetLocalPlayerId() then
        return
    end
    self.score[playerId] = (self.score[playerId] or 0) + (weight or 1)
    self.reasons[playerId] = self.reasons[playerId] or {}
    self.reasons[playerId][reason] = true
    local now = Utils1:NowSeconds()
    if self.score[playerId] >= self.reportThreshold and (now - (self.lastReport[playerId] or 0)) > 15 then
        self.lastReport[playerId] = now
        local reasonList = {}
        for text, _ in pairs(self.reasons[playerId]) do
            table.insert(reasonList, text)
        end
        local summary = table.concat(reasonList, "; ")
        ModderDB.AddModderByPlayerId(playerId, "Sovereign unusual player data: " .. summary)
        -- Logger:Toast("SovereignDetector", string.format("Unusual player attributes: %s\n%s", self:GetName(playerId), summary), CONFIG.UI.ToastDuration.Medium)
        -- Logger:Info("SovereignDetector", string.format("pid=%s score=%s reasons=%s", tostring(playerId), tostring(self.score[playerId]), summary))
    end
end

function PlayerCheatDetector:CheckNumber(playerId, value, minValue, maxValue, reason, weight)
    if type(value) ~= "number" then
        return
    end
    if value ~= value or value == rawget(math, "huge") or value == -rawget(math, "huge") or value < minValue or value > maxValue then
        self:AddDetection(playerId, reason .. "=" .. tostring(value), weight)
    end
end

function PlayerCheatDetector:EvaluatePlayerInfo(playerId, info)
    if not info then
        return
    end
    self:CheckNumber(playerId, info.MaxHealth, 0, 1000, "Maximum health limit", 3)
    self:CheckNumber(playerId, info.MaxArmour, 0, 1000, "Maximum armor limit", 3)
    self:CheckNumber(playerId, info.WeaponDamageModifier, 0.0, 3.0, "Abnormal weapon damage", 3)
    self:CheckNumber(playerId, info.WeaponDefenseModifier, 0.0, 5.0, "Weapon anomaly", 2)
    self:CheckNumber(playerId, info.WeaponMinigunDefenseModifier, 0.0, 5.0, "Weapon anomaly", 2)
    self:CheckNumber(playerId, info.WeaponTakedownDefenseModifier, 0.0, 5.0, "Weapon anomaly", 2)
    self:CheckNumber(playerId, info.MeleeWeaponDamageModifier, 0.0, 5.0, "Weapon anomaly", 2)
    self:CheckNumber(playerId, info.MeleeWeaponDefenseModifier, 0.0, 5.0, "Weapon anomaly", 2)
    self:CheckNumber(playerId, info.MeleeWeaponForceModifier, 0.0, 8.0, "Weapon anomaly", 2)
    self:CheckNumber(playerId, info.ExplosiveDamageModifier, 0.0, 5.0, "Abnormal explosion damage", 2)
    self:CheckNumber(playerId, info.VehicleDamageModifier, 0.0, 5.0, "Abnormal vehicle modifications", 2)
    self:CheckNumber(playerId, info.VehicleDefenseModifier, 0.0, 8.0, "Abnormal vehicle modifications", 2)
    self:CheckNumber(playerId, info.RunSprintSpeedMultiplier, 0.0, 2.0, "CPlayerInfo.RunSprintSpeedMultiplier", 2)
    self:CheckNumber(playerId, info.SwimSpeedMultiplier, 0.0, 2.0, "CPlayerInfo.SwimSpeedMultiplier", 2)
    self:CheckNumber(playerId, info.CachedSprintMultThisFrame, 0.0, 2.5, "CPlayerInfo.CachedSprintMultThisFrame", 1)
    self:CheckNumber(playerId, info.MaxSprintEnergy, 0.0, 500.0, "CPlayerInfo.MaxSprintEnergy", 1)
    self:CheckNumber(playerId, info.SprintEnergy, -10.0, 600.0, "CPlayerInfo.SprintEnergy", 1)
    self:CheckNumber(playerId, info.JackSpeed, 0, 500, "CPlayerInfo.JackSpeed", 1)
end

function PlayerCheatDetector:EvaluateGameStateFlags(playerId, flags)
    if not flags then
        return
    end
    local highRisk = {
        bInvincible = 4,
        ignoresExplosions = 3,
        notDamagedByBullets = 3,
        notDamagedByCollisions = 2,
        notDamagedByFlames = 2,
        notDamagedByMelee = 2,
        notDamagedBySmoke = 1,
        notDamagedBySteam = 1,
        noCriticalHits = 2,
        neverTarget = 2,
        useKinematicPhysics = 2,
        useKinematicModeWhenStationary = 2,
        controlsDisabledByScript = 1,
        playerIsWeird = 1,
    }
    for flag, weight in pairs(highRisk) do
        if flags[flag] == true then
            self:AddDetection(playerId, "Abnormal player state. Flag reason: " .. flag, weight)
        end
    end
end

function PlayerCheatDetector:EvaluatePlayerGameStateNode(node, ctx)
    if not self.enabled or not ctx or not ctx.playerId or ctx.playerId < 0 then
        return true
    end
    local gameNode = node
    if node and node.As then
        local ok, casted = pcall(function() return node:As("CPlayerGameStateDataNode") end)
        if ok and casted then
            gameNode = casted
        end
    end
    if not gameNode then
        return true
    end
    self:EvaluateGameStateFlags(ctx.playerId, gameNode.GameStateFlags)
    self:CheckNumber(ctx.playerId, gameNode.WeaponDamageModifier, 0.0, 3.0, "CPlayerGameStateDataNode.WeaponDamageModifier", 3)
    self:CheckNumber(ctx.playerId, gameNode.WeaponDefenseModifier, 0.0, 5.0, "CPlayerGameStateDataNode.WeaponDefenseModifier", 2)
    self:CheckNumber(ctx.playerId, gameNode.MaxHealth, 0, 1000, "CPlayerGameStateDataNode.MaxHealth", 3)
    self:CheckNumber(ctx.playerId, gameNode.MaxArmour, 0, 1000, "CPlayerGameStateDataNode.MaxArmour", 3)
    self:CheckNumber(ctx.playerId, gameNode.JackSpeed, 0, 500, "CPlayerGameStateDataNode.JackSpeed", 1)
    return true
end

function PlayerCheatDetector:ScanPlayer(playerId)
    if playerId == GTA.GetLocalPlayerId() then
        return
    end
    local ok, player = pcall(Players.GetById, playerId)
    if ok and player and player.PlayerInfo then
        self:EvaluatePlayerInfo(playerId, player.PlayerInfo)
        return
    end
    local pedOk, ped = pcall(Players.GetCPed, playerId)
    if pedOk and ped and ped.PlayerInfo then
        self:EvaluatePlayerInfo(playerId, ped.PlayerInfo)
    end
end

function PlayerCheatDetector:Start()
    if self.running then
        return
    end
    self.running = true
    Script.QueueJob(function()
        while self.enabled and not ShouldUnload() do
            local okPlayers, players = pcall(Players.Get)
            if okPlayers and type(players) == "table" then
                for _, playerId in ipairs(players) do
                    local ok, err = pcall(function()
                        self:ScanPlayer(playerId)
                    end)
                    if not ok then
                        Logger:Error("SovereignDetector", "PlayerInfo scan failed: " .. tostring(err))
                    end
                    Script.Yield(0)
                end
            elseif not okPlayers then
                Logger:Error("SovereignDetector", "Player list scan failed: " .. tostring(players))
            end
            Script.Yield(5000)
        end
        self.running = false
    end)
end

function NodeDataProtectionManager:Initialize()
    self:RegisterHandlers({
        [eSyncDataNode.CPedGameStateDataNode] = NodeDataProtectionHandlers[1],
        [eSyncDataNode.CVehicleProximityMigrationDataNode] = NodeDataProtectionHandlers[2],
        [eSyncDataNode.CVehicleTaskDataNode] = NodeDataProtectionHandlers[3],
        [eSyncDataNode.CPedCreationDataNode] = NodeDataProtectionHandlers[4],
        [eSyncDataNode.CTrainGameStateDataNode] = NodeDataProtectionHandlers[5],
        [eSyncDataNode.CPhysicalAttachDataNode] = {NodeDataProtectionHandlers[6], NodeDataProtectionHandlers[7]},
    })
end

function NodeDataProtectionManager:AnyEnabled()
    for _,enabled in pairs(self.states) do if enabled then return true end end
    return PlayerCheatDetector and PlayerCheatDetector.enabled==true
end

NodeDataProtectionManager.ProcessIncoming = LPH_NO_VIRTUALIZE(function(isCreate, modelHash, position, netObject, updatedNodes)
    if not NodeDataProtectionManager:AnyEnabled() then return true end
    if type(updatedNodes)~="table" then return true end
    local ctx={isCreate=isCreate,modelHash=modelHash,position=position,netObject=netObject,
        playerId=netObject and netObject.PlayerId or -1,netObjectId=netObject and netObject.ObjectID or nil}
    setmetatable(ctx,{__index=function(t,key)
        if key=="playerName" then
            local ok,name=pcall(Players.GetName,t.playerId)
            name=ok and type(name)=="string" and name or "Unknown"
            rawset(t,key,name);return name
        elseif key=="modelName" then
            local ok,name=pcall(GTA.GetModelNameFromHash,t.modelHash)
            name=ok and type(name)=="string" and name or "Unknown"
            rawset(t,key,name);return name
        end
    end})
    if updatedNodes[0] and not NodeDataProtectionManager:ProcessNode(updatedNodes[0],ctx) then return false end
    for index,node in ipairs(updatedNodes) do
        if index>1024 then return false end
        if node and not NodeDataProtectionManager:ProcessNode(node,ctx) then return false end
    end
    NodeDataProtectionManager:ProcessObservers(ctx)
    return true
end)

local CanApplyNodeData = LPH_NO_VIRTUALIZE(function(isCreate, modelHash, position, netObject, updatedNodes)
    local success, result = pcall(NodeDataProtectionManager.ProcessIncoming,
        isCreate, modelHash, position, netObject, updatedNodes)
    if not success then
        Logger:Error("NodeProtection", string.format("CanApplyNodeData execution exception: %s", tostring(result)))
        return true
    end
    return result
end)

NodeDataProtectionManager:Initialize()
NodeDataProtectionManager:RegisterHandler(eSyncDataNode.CPlayerGameStateDataNode, {
    id = "Detect_PlayerGameStateFlags",
    priority = 2000,
    observeOnly = true,
    condition = function() return PlayerCheatDetector.enabled end,
    execute = function(node, ctx)
        return PlayerCheatDetector:EvaluatePlayerGameStateNode(node, ctx)
    end
})
