function PlayerManager:ChangeModel(modelName)
    local success, result = pcall(function()
        local hash = menu.nativeApis.MISC.GET_HASH_KEY(modelName)
        menu.nativeApis.STREAMING.REQUEST_MODEL(hash)
        local timeout = Utils1:NowSeconds() + 5
        while not menu.nativeApis.STREAMING.HAS_MODEL_LOADED(hash) do
            if Utils1:NowSeconds() > timeout then
                Logger:Error("SovereignLua", "Model load timeout: " .. modelName)
                return false
            end
            Script.Yield(0)
        end
        menu.nativeApis.PLAYER.SET_PLAYER_MODEL(menu.nativeApis.PLAYER.PLAYER_ID(), hash)
        menu.nativeApis.STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(hash)
