function PlayerManager:IsValidPlayer(playerId)
    if type(playerId) ~= "number" or playerId < 0 or playerId > 31 then
        return false
    end
    if menu.nativeApis.NETWORK and menu.nativeApis.NETWORK.NETWORK_IS_PLAYER_ACTIVE
        and not menu.nativeApis.NETWORK.NETWORK_IS_PLAYER_ACTIVE(playerId) then
        return false
    end
    local ped = self:GetPlayerPed(playerId)
    if not ped or ped == 0 then
        return false
    end
    if menu.nativeApis.ENTITY and menu.nativeApis.ENTITY.DOES_ENTITY_EXIST then
        local ok, exists = pcall(menu.nativeApis.ENTITY.DOES_ENTITY_EXIST, ped)
        return ok and exists == true
    end
    return true
end

