function EntityManager:RequestModel(hash, timeoutMs)
    timeoutMs = timeoutMs or 5
    if not hash or hash == 0 then
        return false
    end
    if menu.nativeApis.STREAMING and menu.nativeApis.STREAMING.IS_MODEL_VALID then
        local okValid, valid = pcall(function() return menu.nativeApis.STREAMING.IS_MODEL_VALID(hash) end)
        if okValid and valid == false then
            Logger:Warn("SovereignLua", "Invalid model: 0x" .. string.format("%X", hash))
            return false
        end
    elseif GTA and GTA.GetModelInfoIndexFromHash then
        local okIndex, index = pcall(function() return GTA.GetModelInfoIndexFromHash(hash) end)
        if okIndex and tonumber(index) == -1 then
            Logger:Warn("SovereignLua", "Invalid model: 0x" .. string.format("%X", hash))
            return false
        end
    end
    local success, result = pcall(function()
        menu.nativeApis.STREAMING.REQUEST_MODEL(hash)
        for _ = 1, 10 do
            menu.nativeApis.STREAMING.REQUEST_MODEL(hash)
        end
        local timeout = Utils1:NowSeconds() + timeoutMs
        while not menu.nativeApis.STREAMING.HAS_MODEL_LOADED(hash) do
            if Utils1:NowSeconds() > timeout then
                Logger:Warn("SovereignLua", "Model load timeout: 0x" .. string.format("%X", hash))
                return false
            end
            Script.Yield(0)
        end
        return true
    end)
    if not success then
        Logger:Error("SovereignLua", "RequestModel exception: " .. tostring(result))
        return false
    end
    return result
end

function EntityManager:SpawnVehicle(hash, pos, heading)
    heading = heading or 0
    if not self:RequestModel(hash) then
        return nil
    end
    local success, result = pcall(function()
        return GTA.SpawnVehicle(hash, pos.x, pos.y, pos.z, heading, true, false)
    end)
    if not success then
        Logger:Error("SovereignLua", "SpawnVehicle exception: " .. tostring(result))
        return nil
    end
    return result
end

function EntityManager:SpawnPed(hash, pos, pedType)
    pedType = pedType or 26
    if not self:RequestModel(hash) then
        return nil
    end
    local success, result = pcall(function()
        return GTA.CreatePed(hash, pedType, pos.x, pos.y, pos.z, 0, true, false)
    end)
    if not success then
        Logger:Error("SovereignLua", "SpawnPed exception: " .. tostring(result))
        return nil
    end
    return result
end

function EntityManager:SpawnObject(hash, pos)
    if not self:RequestModel(hash) then
        return nil
    end
    local success, result = pcall(function()
        local modelInfo = GTA.GetModelInfoFromHash(hash)
        if modelInfo and modelInfo:IsWorldObject() then
            return GTA.CreateWorldObject(hash, pos.x, pos.y, pos.z, true, true)
        else
            return GTA.CreateObject(hash, pos.x, pos.y, pos.z, true, true)
        end
    end)
    if not success then
        Logger:Error("SovereignLua", "SpawnObject exception: " .. tostring(result))
        return nil
    end
    return result
end

