function EntityManager:PrivateRemoteScene(entity, pos)
    local dictBase = "move_m@casual@b"
    menu.nativeApis.STREAMING.REQUEST_ANIM_DICT(dictBase)
    local timeout = Utils1:NowSeconds() + 5
    while not menu.nativeApis.STREAMING.HAS_ANIM_DICT_LOADED(dictBase) do
        if Utils1:NowSeconds() > timeout then
            Logger:Warn("SovereignLua", "Dictionary loading timed out: " .. dictBase)
            return
        end
        Script.Yield(0)
    end
    local playerPed = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(menu.nativeApis.PLAYER.PLAYER_ID())
    local heading = menu.nativeApis.ENTITY.GET_ENTITY_HEADING(playerPed)
    local scene = menu.nativeApis.NETWORK.NETWORK_CREATE_SYNCHRONISED_SCENE(pos.x, pos.y, pos.z, 0.0, 0.0, heading, 2, false, true, 1.0, 0.0, 1.0)
    menu.nativeApis.NETWORK.NETWORK_ADD_MAP_ENTITY_TO_SYNCHRONISED_SCENE(scene, Utils.Joaat("slod_human"), pos.x, pos.y, pos.z, 0, "idle", 8.0, -8.0, 0)
    menu.nativeApis.NETWORK.NETWORK_ADD_ENTITY_TO_SYNCHRONISED_SCENE(entity, scene, dictBase, "idle", 8.0, -8.0, 0)
    menu.nativeApis.NETWORK.NETWORK_START_SYNCHRONISED_SCENE(scene)
    Script.Yield(500)
    menu.nativeApis.NETWORK.NETWORK_STOP_SYNCHRONISED_SCENE(scene)
    menu.nativeApis.STREAMING.REMOVE_ANIM_DICT(dictBase)
end

function EntityManager:DeleteEntity(entity)
    if not entity or entity == 0 then
        return false
    end
    if not menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(entity) then
        return false
    end
    local success, result = pcall(function()
        local ptr = Memory.AllocInt()
        Memory.WriteInt(ptr, entity)
        menu.nativeApis.ENTITY.DELETE_ENTITY(ptr)
        Memory.Free(ptr)
        return true
    end)
    if not success then
        Logger:Warn("SovereignLua", "DeleteEntity failed: " .. tostring(result))
        return false
    end
    return result
end

function EntityManager:DeleteEntityLocal(entity, quiet)
    if not entity or entity == 0 then
        return false
    end
    local allocation
    local success, result, outcome = pcall(function()
        if not menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(entity) then return false, "gone" end
        local ptr = GTA.HandleToPointer(entity)
        if not ptr then
            return false
        end
        local netObj = ptr.NetObject
        if netObj then
            NetworkObjectMgr.UnregisterNetworkObject(netObj, 8, true, true)
        else
            -- Local, non-networked entities have no NetObject to unregister.
            -- Keep both deletion paths in the existing EntityManager method.
            allocation = Memory.AllocInt()
            if not allocation or allocation == 0 then return false, "allocation_failed" end
            Memory.WriteInt(allocation, entity)
            menu.nativeApis.ENTITY.SET_ENTITY_AS_MISSION_ENTITY(entity, true, true)
            menu.nativeApis.ENTITY.DELETE_ENTITY(allocation)
        end
        local removed = not menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(entity)
        return removed, removed and "removed" or "pending"
    end)
    if allocation and allocation ~= 0 then pcall(Memory.Free, allocation) end
    if not success then
        if not quiet then Logger:Warn("SovereignLua", "DeleteEntityLocal failed: " .. tostring(result)) end
        return false, "delete_failed"
    end
    return result, outcome
end

-- R38 pool cleanup backend: keep the local EntityManager in this closure.
SovereignPoolCleanupBackend = {
    getters = {Ped = "GetCPed", Vehicle = "GetCVehicle", Object = "GetCObject", Pickup = "GetCPickup", Camera = "GetCCamera"},
    types = {Ped = 1, Vehicle = 2, Object = 3},
}
SovereignPoolCleanupBackend.TryDelete = LPH_NO_VIRTUALIZE(function(kind, slot)
    local backend = SovereignPoolCleanupBackend
    local getterName, expectedType = backend.getters[kind], backend.types[kind]
    if type(slot) ~= "number" or slot < 0 or slot >= rawget(math, "huge") or slot ~= math.floor(slot) then
        return false, "invalid"
    end
    if not getterName or not PoolMgr or type(PoolMgr[getterName]) ~= "function"
        or not GTA or type(GTA.PointerToHandle) ~= "function" or type(GTA.HandleToPointer) ~= "function"
        or not menu.nativeApis.ENTITY or type(menu.nativeApis.ENTITY.DOES_ENTITY_EXIST) ~= "function"
        or type(menu.nativeApis.ENTITY.GET_ENTITY_TYPE) ~= "function"
        or type(menu.nativeApis.ENTITY.IS_ENTITY_ATTACHED) ~= "function" then return false, "unavailable" end
    local ok, deleted, reason, outcome = pcall(function()
        local entity = PoolMgr[getterName](slot)
        if not entity or type(entity.IsPhysical) ~= "function" or entity:IsPhysical() ~= true
            or type(entity.GetAddress) ~= "function" then
            return false, "empty"
        end
        local address = entity:GetAddress()
        if type(address) ~= "number" or address <= 0 or address >= rawget(math, "huge")
            or address ~= math.floor(address) then return false, "invalid" end
        local handle = GTA.PointerToHandle(entity)
        if type(handle) ~= "number" or handle <= 0 or handle >= rawget(math, "huge")
            or handle ~= math.floor(handle) or not menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(handle) then return false, "invalid" end
        local entityType = menu.nativeApis.ENTITY.GET_ENTITY_TYPE(handle)
        if entityType ~= 1 and entityType ~= 2 and entityType ~= 3 then return false, "unsupported" end
        if expectedType and expectedType ~= entityType then return false, "wrong_type" end
        -- Script-created entities also carry the mission flag. It is not proof
        -- that the entity belongs to an active game mission.
        if menu.nativeApis.ENTITY.IS_ENTITY_ATTACHED(handle) ~= false then
            return false, "protected"
        end
        if entityType == 1 then
            if not menu.nativeApis.PED or type(menu.nativeApis.PED.IS_PED_A_PLAYER) ~= "function"
                or type(menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE) ~= "function"
                or menu.nativeApis.PED.IS_PED_A_PLAYER(handle) ~= false or menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE(handle, false) ~= false then
                return false, "protected"
            end
        elseif entityType == 2 then
            if not menu.nativeApis.VEHICLE or type(menu.nativeApis.VEHICLE.IS_VEHICLE_SEAT_FREE) ~= "function"
                or type(menu.nativeApis.VEHICLE.GET_VEHICLE_NUMBER_OF_PASSENGERS) ~= "function"
                or menu.nativeApis.VEHICLE.IS_VEHICLE_SEAT_FREE(handle, -1, false) ~= true
                or menu.nativeApis.VEHICLE.GET_VEHICLE_NUMBER_OF_PASSENGERS(handle, false, true) ~= 0 then
                return false, "protected"
            end
        end
        local current = GTA.HandleToPointer(handle)
        if not current or type(current.GetAddress) ~= "function" or current:GetAddress() ~= address then return false, "stale" end
        local removed, status = EntityManager:DeleteEntityLocal(handle, true)
        return removed == true, "attempted", status
    end)
    if not ok then return false, "read_failed" end
    return deleted, reason, outcome
end)
-- R38 pool cleanup backend end.

