function EntertainmentOptions:ToggleGhostMode()
    self.ghostMode = not self.ghostMode
    local ped = self:GetLocalPed()
    pcall(function()
        menu.nativeApis.ENTITY.RESET_ENTITY_ALPHA(ped)
        menu.nativeApis.ENTITY.SET_ENTITY_ALPHA(ped, 255, false)
        menu.nativeApis.ENTITY.SET_ENTITY_VISIBLE(ped, true, false)
        menu.nativeApis.ENTITY.SET_ENTITY_COLLISION(ped, true, true)
        menu.nativeApis.PLAYER.SET_RUN_SPRINT_MULTIPLIER_FOR_PLAYER(menu.nativeApis.PLAYER.PLAYER_ID(), 1.0)
        menu.nativeApis.NETWORK.SET_LOCAL_PLAYER_AS_GHOST(self.ghostMode, self.ghostMode)
    end)
    Logger:Toast("Fun", self.ghostMode and "Ghost mode enabled" or "Ghost mode disabled", CONFIG.UI.ToastDuration.Short)
end

