function EntertainmentOptions:EnableGTA4Neon()
    local veh = self:GetCurrentVehicle()
    if veh == 0 then
        Logger:Toast("Fun", "Enter a vehicle first", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    self:ClearNeonObjects(true)
    for i = 0, 3 do
        pcall(function() menu.nativeApis.VEHICLE.SET_VEHICLE_NEON_ENABLED(veh, i, true) end)
    end
    pcall(function() menu.nativeApis.VEHICLE.SET_VEHICLE_LIGHTS(veh, 3) end)
    pcall(function() menu.nativeApis.VEHICLE.SET_VEHICLE_FULLBEAM(veh, true) end)
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(veh, true)
    local phoneHash = self:GetModelHash("vw_prop_casino_phone_01b")
    local offsets = {
        {x = 0.0, y = 0.0, z = -0.35},
        {x = 0.75, y = 1.1, z = -0.25},
        {x = -0.75, y = 1.1, z = -0.25},
        {x = 0.75, y = -1.1, z = -0.25},
        {x = -0.75, y = -1.1, z = -0.25}
    }
    for _, offset in ipairs(offsets) do
        local obj = EntityManager:SpawnObject(phoneHash, pos)
        if self:IsEntityValid(obj) then
            pcall(function() menu.nativeApis.ENTITY.SET_ENTITY_COLLISION(obj, false, false) end)
            pcall(function() menu.nativeApis.ENTITY.SET_ENTITY_ALPHA(obj, 180, false) end)
            self:AttachEntity(obj, veh, 0, offset.x, offset.y, offset.z, 0.0, 0.0, 0.0)
            table.insert(self.neonObjects, obj)
        end
    end
    Logger:Toast("Fun", "GTA IV neon enabled", CONFIG.UI.ToastDuration.Short)
    return true
end

