function EntertainmentOptions:ToggleMeditation()
    self.meditation = not self.meditation
    local ped = self:GetLocalPed()
    if not self.meditation then
        NativeTaskQueue:ClearNow("meditation_" .. tostring(ped), ped, 0.25)
        Logger:Toast("Fun", "Meditation disabled", CONFIG.UI.ToastDuration.Short)
        return true
    end
    if menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        self.meditation = false
        Logger:Toast("Fun", "Leave your vehicle first", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    if not self:RequestAnimDict("rcmcollect_paperleadinout@") then
        self.meditation = false
        Logger:Toast("Fun", "Could not load meditation animation", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    NativeTaskQueue:ClearNow("meditation_" .. tostring(ped), ped, 0.25)
    NativeTaskQueue:PlayAnim("meditation_" .. tostring(ped), ped, "rcmcollect_paperleadinout@", "meditiate_idle", 8.0, -8.0, -1, 1, 1.0, false, false, false, 0.75)
    Logger:Toast("Fun", "Meditation enabled", CONFIG.UI.ToastDuration.Short)
    return true
end

function EntertainmentOptions:ProcessMeditation()
    if not self.meditation then return end
    local ped = self:GetLocalPed()
    if ped == 0 or menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        self.meditation = false
        NativeTaskQueue:ClearNow("meditation_" .. tostring(ped), ped, 0.25)
        return
    end
    local playing = false
    pcall(function()
        playing = menu.nativeApis.ENTITY.IS_ENTITY_PLAYING_ANIM(ped, "rcmcollect_paperleadinout@", "meditiate_idle", 3)
    end)
    if not playing then
        NativeTaskQueue:PlayAnim("meditation_" .. tostring(ped), ped, "rcmcollect_paperleadinout@", "meditiate_idle", 8.0, -8.0, -1, 1, 1.0, false, false, false, 0.75)
    end
end

