function EntertainmentOptions:SpawnPet()
    local item = self.petOptions[self.selectedPetIndex] or self.petOptions[1]
    if not item then
        return false
    end
    local ped = self:GetLocalPed()
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(ped, true)
    local pet = EntityManager:SpawnPed(self:GetModelHash(item.model), {
        x = pos.x + math.random(-2, 2),
        y = pos.y + math.random(-2, 2),
        z = pos.z
    }, 28)
    if not self:IsEntityValid(pet) then
        Logger:Toast("Fun", "Could not spawn pet", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    pcall(function() menu.nativeApis.ENTITY.SET_ENTITY_INVINCIBLE(pet, true) end)
    pcall(function() menu.nativeApis.PED.SET_PED_CAN_RAGDOLL(pet, false) end)
    pcall(function() menu.nativeApis.PED.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS(pet, true) end)
    if item.dict and item.anim and self:RequestAnimDict(item.dict) then
        pcall(function()
            NativeTaskQueue:PlayAnim("pet_" .. tostring(pet), pet, item.dict, item.anim, 8.0, -8.0, -1, 1, 0.0, false, false, false, 0.75)
        end)
    end
    table.insert(self.pets, {handle = pet, name = item.name})
    Logger:Toast("Fun", item.name .. "Spawned", CONFIG.UI.ToastDuration.Short)
    return true
end

function EntertainmentOptions:TogglePetFollow()
    self.petFollow = not self.petFollow
    self.petLastTask = 0
    Logger:Toast("Fun", self.petFollow and "Pet follow enabled" or "Pet follow disabled", CONFIG.UI.ToastDuration.Short)
end

function EntertainmentOptions:ClearPets(silent)
    for _, item in ipairs(self.pets) do
        if item and self:IsEntityValid(item.handle) then
            EntityManager:DeleteEntity(item.handle)
            Script.Yield(0)
        end
    end
    self.pets = {}
    if not silent then
        Logger:Toast("Fun", "Pets cleared", CONFIG.UI.ToastDuration.Short)
    end
    return true
end

function EntertainmentOptions:ProcessPets()
    if not self.petFollow or #self.pets == 0 then
        return
    end
    local now = Utils1:NowSeconds()
    if now - (self.petLastTask or 0) < 2.0 then
        return
    end
    self.petLastTask = now
    local owner = self:GetLocalPed()
    local ownerPos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(owner, true)
    local heading = menu.nativeApis.ENTITY.GET_ENTITY_HEADING(owner)
    local rad = math.rad(heading)
    for _, item in ipairs(self.pets) do
        local pet = item.handle
        if self:IsEntityValid(pet) then
            local petPos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(pet, true)
            local dist = Utils1 and Utils1.V3Distance and Utils1:V3Distance(ownerPos, petPos) or 0
            if dist > 8.0 then
                local side = math.random(-2, 2)
                local back = 2.0 + math.random()
                local x = ownerPos.x + math.sin(rad) * back + math.cos(rad) * side
                local y = ownerPos.y - math.cos(rad) * back + math.sin(rad) * side
                -- pcall(function() ENTITY.SET_ENTITY_COORDS_NO_OFFSET(pet, x, y, ownerPos.z, false, false, false) end)
                menu.nativeApis.TASK.TASK_FOLLOW_TO_OFFSET_OF_ENTITY(pet, owner, 0.0, -0.3, 0.0, 7.0, -1, 1.5, true)
                -- pcall(function() ENTITY.SET_ENTITY_HEADING(pet, heading) end)
            end
        end
    end
end


function EntertainmentOptions:PlayFireworkAt(pos)
    local x = pos.x + math.random(-10, 10)
    local y = pos.y + math.random(-10, 10)
    local z = pos.z + math.random(4, 10)
    local ok = pcall(function()
        if not self:RequestPtfxAsset("scr_indep_fireworks") then
            error("firework ptfx unavailable")
        end
        self:UsePtfxAsset("scr_indep_fireworks")
        if menu.nativeApis.GRAPHICS and menu.nativeApis.GRAPHICS.START_NETWORKED_PARTICLE_FX_NON_LOOPED_AT_COORD then
            menu.nativeApis.GRAPHICS.START_NETWORKED_PARTICLE_FX_NON_LOOPED_AT_COORD("scr_indep_firework_starburst", x, y, z, 0.0, 0.0, 0.0, 1.0, false, false, false)
        elseif menu.nativeApis.GRAPHICS and menu.nativeApis.GRAPHICS.START_PARTICLE_FX_NON_LOOPED_AT_COORD then
            menu.nativeApis.GRAPHICS.START_PARTICLE_FX_NON_LOOPED_AT_COORD("scr_indep_firework_starburst", x, y, z, 0.0, 0.0, 0.0, 1.0, false, false, false)
        else
            error("firework ptfx call unavailable")
        end
    end)
    if ok then
        return true
    end
    local ped = self:GetLocalPed()
    local weapon = self:GetModelHash("weapon_firework")
    return pcall(function()
        menu.nativeApis.MISC.SHOOT_SINGLE_BULLET_BETWEEN_COORDS(x, y, pos.z + 1.0, x, y, z + 20.0, 0, true, weapon, ped, true, false, 1000.0)
    end)
end

function EntertainmentOptions:ToggleFireworkShow()
    self.fireworkShow = not self.fireworkShow
    self.fireworkWarned = false
    Logger:Toast("Fun", self.fireworkShow and "Fireworks show enabled" or "Fireworks show disabled", CONFIG.UI.ToastDuration.Short)
end

function EntertainmentOptions:ProcessFireworkShow()
    if not self.fireworkShow then
        return
    end
    local now = Utils1:NowSeconds()
    if now - (self.fireworkLast or 0) < 0.75 then
        return
    end
    self.fireworkLast = now
    local ped = self:GetLocalPed()
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(ped, true)
    for i = 1, 3 do
        local ok = self:PlayFireworkAt(pos)
        if not ok and not self.fireworkWarned then
            self.fireworkWarned = true
            Logger:Warn("Fun", "Fireworks API unavailable")
        end
    end
end

function EntertainmentOptions:SetScreenEffect(index)
    self.selectedScreenEffectIndex = math.max(1, math.min(#self.screenEffects, (index or 0) + 1))
    local item = self.screenEffects[self.selectedScreenEffectIndex] or self.screenEffects[1]
    if not item or item.effect == "" then
        return self:ClearScreenEffect()
    end
    local ok, err = pcall(function()
        if menu.nativeApis.GRAPHICS and menu.nativeApis.GRAPHICS.ANIMPOSTFX_STOP_ALL then
            menu.nativeApis.GRAPHICS.ANIMPOSTFX_STOP_ALL()
        elseif ANIMPOSTFX_STOP_ALL then
            ANIMPOSTFX_STOP_ALL()
        end
        if menu.nativeApis.GRAPHICS and menu.nativeApis.GRAPHICS.ANIMPOSTFX_PLAY then
            menu.nativeApis.GRAPHICS.ANIMPOSTFX_PLAY(item.effect, 0, true)
        elseif ANIMPOSTFX_PLAY then
            ANIMPOSTFX_PLAY(item.effect, 0, true)
        else
            error("ANIMPOSTFX_PLAY unavailable")
        end
    end)
    if not ok then
        Logger:Toast("Fun", "Screen effect API unavailable", CONFIG.UI.ToastDuration.Medium)
        Logger:Warn("Fun", "Screen effect failed: " .. tostring(err))
        return false
    end
    self.activeScreenEffect = item.effect
    Logger:Toast("Fun", item.name .. "Enabled", CONFIG.UI.ToastDuration.Short)
    return true
end

function EntertainmentOptions:ClearScreenEffect(silent)
