function EntertainmentOptions:FindNearestTrain(radius)
    radius = radius or 1000.0
    local ped = self:GetLocalPed()
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(ped, true)
    local closest = 0
    local closestDist = radius
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local veh = PoolMgr.GetCVehicle(i)
        if veh and veh:IsVehicle() and veh.Position then
            local model = veh.ModelInfo and veh.ModelInfo.Model or 0
            if self.trainModels[model] then
                local dist = Utils1 and Utils1.V3Distance and Utils1:V3Distance(pos, veh.Position) or radius + 1.0
                if dist < closestDist then
                    closestDist = dist
                    closest = GTA.PointerToHandle(veh)
                end
            end
        end
    end
    return closest
end

function EntertainmentOptions:EnterNearestTrain()
    local train = self:FindNearestTrain(1200.0)
    if not self:IsEntityValid(train) then
        Logger:Toast("Fun", "No nearby train or tram", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    menu.nativeApis.PED.SET_PED_INTO_VEHICLE(self:GetLocalPed(), train, -1)
    Logger:Toast("Fun", "Entered nearby train / tram", CONFIG.UI.ToastDuration.Short)
    return true
end

EntertainmentOptions.Process = LPH_NO_VIRTUALIZE(function(self)
    local currentVehicle = self:GetCurrentVehicle()
    if currentVehicle ~= 0 then
        self.lastVehicle = currentVehicle
    end
    if not (self.bulletTime or self.landSwim or self.wheelTrails or self.petFollow or self.fireworkShow or self.meditation or self.speedometer) then
        return
    end
    if self.bulletTime then
        pcall(function() menu.nativeApis.MISC.SET_TIME_SCALE(0.35) end)
    end
    if self.landSwim then
        local ped = self:GetLocalPed()
        pcall(function()
            if menu.nativeApis.PED and menu.nativeApis.PED.SET_PED_CONFIG_FLAG then
                menu.nativeApis.PED.SET_PED_CONFIG_FLAG(ped, 65, true)
            end
            if menu.nativeApis.PED and menu.nativeApis.PED.SET_PED_CAN_RAGDOLL then
                menu.nativeApis.PED.SET_PED_CAN_RAGDOLL(ped, false)
            end
        end)
    end
    self:ProcessWheelTrails(currentVehicle)
    self:ProcessPets()
    self:ProcessFireworkShow()
    self:ProcessMeditation()
    self:UpdateSpeedometer(currentVehicle)
end)

function EntertainmentOptions:SetSelectedEmote(index)
    self.selectedEmoteIndex = math.max(1, math.min(#self.emotes, (index or 0) + 1))
end

function EntertainmentOptions:RequestAnimDict(dict)
    menu.nativeApis.STREAMING.REQUEST_ANIM_DICT(dict)
    local timeout = Utils1:NowSeconds() + 3
    while not menu.nativeApis.STREAMING.HAS_ANIM_DICT_LOADED(dict) do
        if Utils1:NowSeconds() > timeout then
            Logger:Warn("Fun", "Animation dictionary loading timed out: " .. tostring(dict))
            return false
        end
        Script.Yield(0)
    end
    return true
end

function EntertainmentOptions:PlaySelectedEmote()
    local emote = self.emotes[self.selectedEmoteIndex] or self.emotes[1]
    if not emote then
        return false
    end
    local ped = menu.nativeApis.PLAYER.PLAYER_PED_ID()
    if menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        Logger:Toast("Fun", "Leave your vehicle before playing an animation", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    if not self:RequestAnimDict(emote.dict) then
        Logger:Toast("Fun", "Could not load animation", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    NativeTaskQueue:Run("emote_" .. tostring(ped), 0.25, function()
        menu.nativeApis.TASK.CLEAR_PED_TASKS_IMMEDIATELY(ped)
        menu.nativeApis.TASK.TASK_PLAY_ANIM(ped, emote.dict, emote.anim, 8.0, -8.0, emote.duration or -1, emote.flags or 0, 0.0, false, false, false)
    end)
    return true
end

function EntertainmentOptions:StopEmote()
    NativeTaskQueue:ClearNow("stop_emote", menu.nativeApis.PLAYER.PLAYER_PED_ID(), 0.25)
    return true
end

function EntertainmentOptions:FixCamera()
    local success, err = pcall(function()
        menu.nativeApis.CAM.RENDER_SCRIPT_CAMS(false, false, 0, true, true, 0)
        menu.nativeApis.STREAMING.CLEAR_FOCUS()
        menu.nativeApis.CAM.DESTROY_ALL_CAMS(false)
    end)
    if not success then
        Logger:Warn("Fun", "Could not reset camera: " .. tostring(err))
        return false
    end
    Logger:Toast("Fun", "Camera reset", CONFIG.UI.ToastDuration.Short)
    return true
end

function EntertainmentOptions:TrimWindmills()
    while #self.windmills >= self.maxWindmills do
        local old = table.remove(self.windmills, 1)
        EntityManager:DeleteEntity(old)
    end
end

function EntertainmentOptions:SpawnWindmillAtSelf()
    if not menu.nativeApis.STREAMING.IS_MODEL_VALID(self.windmillModel) then
        Logger:Toast("Fun", "Windmill model unavailable", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    local ped = menu.nativeApis.PLAYER.PLAYER_PED_ID()
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(ped, true)
    local heading = menu.nativeApis.ENTITY.GET_ENTITY_HEADING(ped)
    local rad = math.rad(heading)
    local spawnPos = {
        x = pos.x - math.sin(rad) * 8.0,
        y = pos.y + math.cos(rad) * 8.0,
        z = pos.z + 1.0
    }
    self:TrimWindmills()
    local object = EntityManager:SpawnObject(self.windmillModel, spawnPos)
    if not object or not menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(object) then
        Logger:Toast("Fun", "Could not spawn windmill", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    pcall(function() menu.nativeApis.ENTITY.SET_ENTITY_ROTATION(object, 90.0, 0.0, heading, 2, true) end)
    pcall(function() menu.nativeApis.ENTITY.SET_ENTITY_LOD_DIST(object, 100000) end)
    pcall(function() menu.nativeApis.ENTITY.FREEZE_ENTITY_POSITION(object, true) end)
    table.insert(self.windmills, object)
    Logger:Toast("Fun", "Windmill spawned", CONFIG.UI.ToastDuration.Short)
    return true
end

function EntertainmentOptions:ClearWindmills()
    for _, object in ipairs(self.windmills) do
        EntityManager:DeleteEntity(object)
        Script.Yield(0)
    end
    self.windmills = {}
    Logger:Toast("Fun", "Windmill cleared", CONFIG.UI.ToastDuration.Short)
    return true
end

function EntertainmentOptions:TeleportLastVehicleToMe()
    local veh = self:GetLastVehicle()
    if veh == 0 then
        Logger:Toast("Fun", "Previous vehicle not found", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    local ped = self:GetLocalPed()
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(ped, true)
    local heading = menu.nativeApis.ENTITY.GET_ENTITY_HEADING(ped)
    local rad = math.rad(heading)
    pcall(function()
        menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET(veh, pos.x - math.sin(rad) * 3.0, pos.y + math.cos(rad) * 3.0, pos.z, false, false, false)
        menu.nativeApis.ENTITY.SET_ENTITY_HEADING(veh, heading)
        menu.nativeApis.VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY(veh, 5.0)
    end)
    Logger:Toast("Fun", "Previous vehicle moved nearby", CONFIG.UI.ToastDuration.Short)
    return true
end

function EntertainmentOptions:TeleportToLastVehicle()
    local veh = self:GetLastVehicle()
    if veh == 0 then
        Logger:Toast("Fun", "Previous vehicle not found", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(veh, true)
    menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET(self:GetLocalPed(), pos.x, pos.y, pos.z + 1.0, false, false, false)
    return true
end

function EntertainmentOptions:EnterLastVehicle()
    local veh = self:GetLastVehicle()
    if veh == 0 then
        Logger:Toast("Fun", "Previous vehicle not found", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    menu.nativeApis.PED.SET_PED_INTO_VEHICLE(self:GetLocalPed(), veh, -1)
    return true
end

function EntertainmentOptions:DeleteLastVehicle()
    local veh = self:GetLastVehicle()
    if veh == 0 then
        Logger:Toast("Fun", "Previous vehicle not found", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    EntityManager:DeleteEntity(veh)
    self.lastVehicle = 0
    if self.lastVehicleBlip ~= 0 then
        pcall(function()
            if menu.nativeApis.HUD and menu.nativeApis.HUD.REMOVE_BLIP then
                menu.nativeApis.HUD.REMOVE_BLIP(self.lastVehicleBlip)
            elseif REMOVE_BLIP then
                REMOVE_BLIP(self.lastVehicleBlip)
            end
        end)
        self.lastVehicleBlip = 0
    end
    Logger:Toast("Fun", "Previous vehicle deleted", CONFIG.UI.ToastDuration.Short)
    return true
end

function EntertainmentOptions:AddLastVehicleBlip()
    local veh = self:GetLastVehicle()
    if veh == 0 then
        Logger:Toast("Fun", "Previous vehicle not found", CONFIG.UI.ToastDuration.Medium)
        return false
    end
    local ok, err = pcall(function()
        if self.lastVehicleBlip ~= 0 then
            if menu.nativeApis.HUD and menu.nativeApis.HUD.REMOVE_BLIP then
                menu.nativeApis.HUD.REMOVE_BLIP(self.lastVehicleBlip)
            elseif REMOVE_BLIP then
                REMOVE_BLIP(self.lastVehicleBlip)
            end
        end
        local blip
        if menu.nativeApis.HUD and menu.nativeApis.HUD.ADD_BLIP_FOR_ENTITY then
            blip = menu.nativeApis.HUD.ADD_BLIP_FOR_ENTITY(veh)
            if menu.nativeApis.HUD.SET_BLIP_SPRITE then menu.nativeApis.HUD.SET_BLIP_SPRITE(blip, 225) end
            if menu.nativeApis.HUD.SET_BLIP_COLOUR then menu.nativeApis.HUD.SET_BLIP_COLOUR(blip, 3) end
            if menu.nativeApis.HUD.SET_BLIP_SCALE then menu.nativeApis.HUD.SET_BLIP_SCALE(blip, 0.8) end
            if menu.nativeApis.HUD.SET_BLIP_ALPHA then menu.nativeApis.HUD.SET_BLIP_ALPHA(blip, 235) end
        elseif ADD_BLIP_FOR_ENTITY then
            blip = ADD_BLIP_FOR_ENTITY(veh)
            if SET_BLIP_SPRITE then SET_BLIP_SPRITE(blip, 225) end
            if SET_BLIP_COLOUR then SET_BLIP_COLOUR(blip, 3) end
            if SET_BLIP_SCALE then SET_BLIP_SCALE(blip, 0.8) end
            if SET_BLIP_ALPHA then SET_BLIP_ALPHA(blip, 235) end
        else
            error("ADD_BLIP_FOR_ENTITY unavailable")
        end
        self.lastVehicleBlip = blip or 0
    end)
    if not ok then
        Logger:Toast("Fun", "Vehicle map marker API unavailable", CONFIG.UI.ToastDuration.Medium)
        Logger:Warn("Fun", "Could not mark previous vehicle: " .. tostring(err))
        return false
    end
    Logger:Toast("Fun", "Previous vehicle marked", CONFIG.UI.ToastDuration.Short)
    return true
end

function EntertainmentOptions:Cleanup()
    NativeTaskQueue:ClearNow("entertainment_cleanup", menu.nativeApis.PLAYER.PLAYER_PED_ID(), 0.25)
    if self.bulletTime then
        pcall(function() menu.nativeApis.MISC.SET_TIME_SCALE(1.0) end)
        self.bulletTime = false
    end
    if self.ghostMode then
        local ped = self:GetLocalPed()
        pcall(function() menu.nativeApis.NETWORK.SET_LOCAL_PLAYER_AS_GHOST(false, false) end)
        pcall(function() menu.nativeApis.ENTITY.RESET_ENTITY_ALPHA(ped) end)
        pcall(function() menu.nativeApis.ENTITY.SET_ENTITY_ALPHA(ped, 255, false) end)
        pcall(function() menu.nativeApis.ENTITY.SET_ENTITY_VISIBLE(ped, true, false) end)
        pcall(function() menu.nativeApis.ENTITY.SET_ENTITY_COLLISION(ped, true, true) end)
        pcall(function() menu.nativeApis.PLAYER.SET_RUN_SPRINT_MULTIPLIER_FOR_PLAYER(menu.nativeApis.PLAYER.PLAYER_ID(), 1.0) end)
        self.ghostMode = false
    end
    self.speedometer = false
    self.speedometerText = nil
    self.wheelTrails = false
    if self.meditation then
        self.meditation = false
    end
    if self.landSwim then
        pcall(function() menu.nativeApis.PED.SET_PED_CONFIG_FLAG(self:GetLocalPed(), 65, false) end)
        self.landSwim = false
    end
    self.fireworkShow = false
    self.petFollow = false
    self:ClearScreenEffect(true)
    self:ClearVisualModifier(true)
    self:ClearFunVehicles(true)
    self:ClearWings(true)
    self:ClearNeonObjects(true)
    self:ClearAttachedProps(true)
    self:ClearJokeObjects(true)
    self:ClearPets(true)
    for _, object in ipairs(self.windmills) do
        if object then
            EntityManager:DeleteEntity(object)
        end
    end
    self.windmills = {}
    if self.lastVehicleBlip ~= 0 then
        pcall(function()
            if menu.nativeApis.HUD and menu.nativeApis.HUD.REMOVE_BLIP then
                menu.nativeApis.HUD.REMOVE_BLIP(self.lastVehicleBlip)
            elseif REMOVE_BLIP then
                REMOVE_BLIP(self.lastVehicleBlip)
            end
        end)
        self.lastVehicleBlip = 0
    end
end

function EntityManager:GetNearbyVehicles(radius)
    radius = radius or 500
    if Utils1 and Utils1.Clamp then
        local maxR = (CONFIG and CONFIG.LIMITS and CONFIG.LIMITS.MaxRadius) or 1000
        radius = Utils1:Clamp(radius, 1, maxR)
    else
        radius = math.max(1, math.min(radius, 1000))
    end
    local localPed = GTA.GetLocalPed()
    if not localPed then
        return {}
    end
    local localPos = localPed.Position
    if not localPos then
        return {}
    end
    local vehicles = {}
    local maxCount = PoolMgr.GetMaxVehicleCount()
    local maxResults = (CONFIG and CONFIG.LIMITS and CONFIG.LIMITS.MaxVehicles) or 50
    for i = 0, maxCount - 1 do
        local veh = PoolMgr.GetCVehicle(i)
        if veh and veh:IsVehicle() and veh.Position then
            local dist = Utils1:V3Distance(localPos, veh.Position)
            if dist <= radius then
                local handle = GTA.PointerToHandle(veh)
                if handle and handle ~= 0 and menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(handle) then
                    Utils1:SafeInsert(vehicles, handle)
                    if #vehicles >= maxResults then
                        break
                    end
                end
            end
        end
    end
    return vehicles
end

function EntityManager:GetNearbyPeds(radius)
    radius = radius or 500
    if Utils1 and Utils1.Clamp then
        local maxR = (CONFIG and CONFIG.LIMITS and CONFIG.LIMITS.MaxRadius) or 1000
        radius = Utils1:Clamp(radius, 1, maxR)
    else
        radius = math.max(1, math.min(radius, 1000))
    end
    local localPed = GTA.GetLocalPed()
    if not localPed then
        return {}
    end
    local localPos = localPed.Position
    if not localPos then
        return {}
    end
    local localHandle = GTA.PointerToHandle(localPed)
    local peds = {}
    local maxCount = PoolMgr.GetMaxPedCount()
    local maxResults = (CONFIG and CONFIG.LIMITS and CONFIG.LIMITS.MaxPeds) or 50
    for i = 0, maxCount - 1 do
        local ped = PoolMgr.GetCPed(i)
        if ped and ped:IsPed() and ped.Position then
            local pedHandle = GTA.PointerToHandle(ped)
            if pedHandle and pedHandle ~= 0 and pedHandle ~= localHandle then
                local dist = Utils1:V3Distance(localPos, ped.Position)
                if dist <= radius then
                    if menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(pedHandle) then
                        Utils1:SafeInsert(peds, pedHandle)
                        if #peds >= maxResults then
                            break
                        end
                    end
                end
            end
        end
    end
    return peds
end

