function EntityManager:InitTrainModels()
    if type(menu.nativeApis.MISC) ~= "table" or type(menu.nativeApis.MISC.GET_HASH_KEY) ~= "function" then
        return false
    end
    for _, model in ipairs(self.TRAIN_MODELS) do
        local hash = menu.nativeApis.MISC.GET_HASH_KEY(model)
        self:RequestModel(hash, 2000)
    end
    return true
end

function EntityManager:GetObjectIdFromHandle(handle)
    local success, result = pcall(function()
        local ptr = GTA.HandleToPointer(handle)
        if ptr and ptr.NetObject then
            return ptr.NetObject.ObjectID
        end
        return nil
    end)
    if not success then return nil end
    return result
end

function EntityManager:GetObjectIdFromPhysical(pPhysical)
    if not pPhysical or not pPhysical.NetObject then
        return nil
    end
    return pPhysical.NetObject.ObjectID
end

function EntityManager:TeleportSelf(pos)
    if not Utils1:IsValidPosition(pos) then
        Logger:Warn("SovereignLua", "Invalid teleport position")
        return false
    end
    local success, result = pcall(function()
        local localPed = GTA.GetLocalPed()
        if not localPed then
            return false
        end
        local handle = GTA.PointerToHandle(localPed)
        menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET(handle, pos.x, pos.y, pos.z, false, false, false)
        return true
    end)
    if not success then
        Logger:Error("SovereignLua", "TeleportSelf exception: " .. tostring(result))
        return false
    end
    return result
end

function EntityManager:ForceCamera(entity, targetPos, targetRot)
    if not Utils1:IsValidPosition(targetPos) then
        return
    end
    if not targetRot then
        return
    end
    local forward = V3.New(
        -math.sin(math.rad(targetRot.z)) * math.cos(math.rad(targetRot.x)),
        math.cos(math.rad(targetRot.z)) * math.cos(math.rad(targetRot.x)),
        math.sin(math.rad(targetRot.x))
    )
    local finalPos = V3.New(
        targetPos.x + forward.x * 15.0,
        targetPos.y + forward.y * 15.0,
        targetPos.z + forward.z * 15.0
    )
    menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET(entity, finalPos.x, finalPos.y, finalPos.z, false, false, false)
end

function EntityManager:GetModelHashFromPed(pPhysical)
    if not pPhysical or not pPhysical:IsPed() then
        return false, nil
    end
    local success, result = pcall(function()
        local handle = GTA.PointerToHandle(pPhysical)
        return menu.nativeApis.ENTITY.GET_ENTITY_MODEL(handle)
    end)
    if not success then return false, nil end
    return true, result
end

local function AssertNotNil(value, errorMsg)
    if not value then
        error(errorMsg or "Value is nil")
    end
    return value
end

local CrashFunctions = {}

function CrashFunctions:QueueCrashJob(label, callback)
    if type(callback) ~= "function" or not Script or type(Script.QueueJob) ~= "function" then
        Logger:Error("SovereignLua", tostring(label or "Crash") .. " requires Script.QueueJob")
        return false
    end
    self._queuedJobs = self._queuedJobs or {}
    local jobKey = tostring(label or "Crash")
    if self._queuedJobs[jobKey] then
        return false
    end
    self._queuedJobs[jobKey] = true
    local queued, queueError = pcall(function()
        Script.QueueJob(function()
            local ok, err = xpcall(callback, debug.traceback)
            self._queuedJobs[jobKey] = nil
            if not ok then
                Logger:Error("SovereignLua", tostring(label or "Crash") .. " exception: " .. tostring(err))
            end
        end)
    end)
    if not queued then
        self._queuedJobs[jobKey] = nil
        Logger:Error("SovereignLua", tostring(label or "Crash") .. " queue failed: " .. tostring(queueError))
        return false
    end
    return true
end

-- CrashFunctions:CrashAll() is temporarily unavailable, even with Script.EecuteAsScript, so im wondering if it is possible to directly forge ne sending
--[[
    message header: magic [14]+extension bit [1]+messageId [8]
    batch header: Number of events [5]+Total digits [15]
    event header: eventId [7]+index [9]+field [8]+payload bits [15]+flag [1]
    event body: type=6, script identifier, rope field

    function T.BuildPacket(fields,index)
        return protect(function()
            local payload,err=T.Encode(fields); if not payload then fail(err) end
            number(index,0,511,'event index',true)
            local w=W.new(); w:uns(0x3246,14); w:uns(0,1); w:uns(0x4F,8)
            w:uns(1,5); w:uns(40+payload.bits,15); w:uns(33,7)
            w:uns(index,9); w:uns(0,8); w:uns(payload.bits,15); w:uns(0,1)
            w:append(payload.bytes,payload.bits)
            return {bytes=w.bytes,bits=w.bits,payloadBits=payload.bits,eventIndex=index}
        end)
    end

    this size can only prove how much the current encoder has written, and cannot prove that the receiver will interpret in the same order
    native auditing now supports outer message headers and sending call chains
    the complete event record and rope field still lack independent native sample per bit comparison
    two sending entrances share this encoding, and any content errors will affect both paths simultaneously
    details see networktest.lua
]]
