function CrashFunctions:HandleInvalidTargetPosition(title)
    local now = Utils1:NowSeconds()
    local last = self._lastInvalidPositionNotice or 0
    if now - last >= 2.0 then
        self._lastInvalidPositionNotice = now
        Logger:Toast(title or "SovereignLua", "Invalid player coordinates", CONFIG.UI.ToastDuration.Medium)
    end
    return false
end

