function CrashFunctions:ParachuteCrash()
    menu.nativeApis.PLAYER.SET_PLAYER_PARACHUTE_VARIATION_OVERRIDE(menu.nativeApis.PLAYER.PLAYER_ID(), 5, 1, 9, false)
    menu.nativeApis.PLAYER.SET_PLAYER_PARACHUTE_PACK_MODEL_OVERRIDE(menu.nativeApis.PLAYER.PLAYER_ID(), 0xFBF7D21F)
    menu.nativeApis.PLAYER.SET_PLAYER_PARACHUTE_MODEL_OVERRIDE(menu.nativeApis.PLAYER.PLAYER_ID(), 0xFBF7D21F) --0xFBF7D21F
    local success, pos = PlayerManager:GetPlayerPosition(menu.nativeApis.PLAYER.PLAYER_ID())
    if not success or not pos then
        Logger:Error("SovereignLua", "Failed to get player position")
        return
    end
    local successa, originalPos = PlayerManager:GetPlayerPosition(menu.nativeApis.PLAYER.PLAYER_ID())
    if not successa or not originalPos then
        Logger:Error("SovereignLua", "Failed to get player position")
        return
    end
    local objhash = {0xFBF7D21F, 0xFBF7D21F, 0xFBF7D21F, 0xFBF7D21F, 0xFBF7D21F} --0xFBF7D21F 0xA126ED27
    local delete_ta = {}
    for _, obj in pairs(objhash) do
        local spobj = GTA.CreateObject(obj, pos.x, pos.y, pos.z, true, true)
        menu.nativeApis.ENTITY.SET_ENTITY_DYNAMIC(spobj, true)
        menu.nativeApis.ENTITY.APPLY_FORCE_TO_ENTITY(spobj, 1, 0, 0, 10, 0, 0, 0, 0, true, true, true, true, true)
        Utils1:SafeInsert(delete_ta, spobj)
    end
    for i = 1, 5, 1 do
        local teleportPos = {x = pos.x, y = pos.y, z = pos.z + 10}
        EntityManager:TeleportSelf(teleportPos)
        Script.Yield(10)
        local localPed = PlayerManager:GetPlayerPed(menu.nativeApis.PLAYER.PLAYER_ID())
        if localPed then
            menu.nativeApis.TASK.TASK_PARACHUTE_TO_TARGET(localPed, pos.x, pos.y, pos.z)
