    for _, value in pairs(delete_ta) do
        EntityManager:DeleteEntity(value)
    end
    menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET(menu.nativeApis.PLAYER.PLAYER_PED_ID(), originalPos.x, originalPos.y, originalPos.z, false, false, false)
