_G.g_subcar_vehicles = _G.g_subcar_vehicles or {}
function CrashFunctions:SuiYuan()
    local local_player_id = GTA.GetLocalPlayerId()
    local targets = {}
    local spawned_entities = {}
    SyncNodeManager:SetState("CrashState", true)
    SyncNodeManager:SetState("subcar1", true)
    local target_scan_ok, target_scan_error = pcall(function()
        for player_id = 0, 31 do
            if player_id ~= local_player_id
                and menu.nativeApis.NETWORK.NETWORK_IS_PLAYER_ACTIVE(player_id) then
                local position_ok, player_pos = PlayerManager:GetPlayerPosition(player_id)
                if position_ok and player_pos then
                    targets[#targets + 1] = {
                        player_id = player_id,
                        position = {
                            x = player_pos.x,
                            y = player_pos.y,
                            z = player_pos.z
                        }
                    }
                end
            end
        end
    end)
    if not target_scan_ok then
        SyncNodeManager:SetState("CrashState", false)
        SyncNodeManager:SetState("subcar1", false)
        Logger:Error("SovereignLua", "SuiYuan target scan exception: " .. tostring(target_scan_error))
        return
    end
    local function register_entity(entity)
        if not entity or entity == 0 then
            return
        end
        spawned_entities[#spawned_entities + 1] = entity
    end
    local function prepare_entity(entity)
        if not entity or entity == 0 then
            return
        end
        pcall(function() menu.nativeApis.ENTITY.FREEZE_ENTITY_POSITION(entity, true) end)
        pcall(function() menu.nativeApis.ENTITY.SET_ENTITY_COLLISION(entity, false, false) end)
        pcall(function() menu.nativeApis.ENTITY.SET_ENTITY_ALPHA(entity, 0, true) end)
    end
    local function cleanup()
        for index = #spawned_entities, 1, -1 do
            pcall(EntityManager.DeleteEntity, EntityManager, spawned_entities[index])
            pcall(Script.Yield, 0)
        end
        spawned_entities = {}
    end
    local vehicle_models = {
        Utils.Joaat("vacca"),
        Utils.Joaat("scarab2"),
        Utils.Joaat("bmx"),
        Utils.Joaat("havok")
    }
    local ped_models = {
        Utils.Joaat("slod_small_quadped"),
        Utils.Joaat("a_c_rottweiler"),
        Utils.Joaat("a_c_cat_01")
    }
    local success, error_message = pcall(function()
        for _, target in ipairs(targets) do
            for model_index, model in ipairs(vehicle_models) do
                local angle = ((model_index - 1) / #vehicle_models) * math.pi * 2.0
                local vehicle = EntityManager:SpawnVehicle(model, target.position)
                register_entity(vehicle)
                prepare_entity(vehicle)
                Script.Yield(25)
            end
            for model_index, model in ipairs(ped_models) do
                local angle = ((model_index - 1) / #ped_models) * math.pi * 2.0
                local ped = EntityManager:SpawnPed(model, target.position)
                register_entity(ped)
                prepare_entity(ped)
                Script.Yield(25)
            end
            Script.Yield(50)
        end
        Script.Yield(1000)
    end)
    SyncNodeManager:SetState("CrashState", false)
    SyncNodeManager:SetState("subcar1", false)
    cleanup()
    if not success then
        Logger:Error("SovereignLua", "SuiYuan exception: " .. tostring(error_message))
    end
end

