-- this one is special. model a_c_rat will cause ped pool overflow. CTaskExitVehicle still works..
function CrashFunctions:TaskHeliExit(targetPid)
    local success, playerPos = PlayerManager:GetPlayerPosition(targetPid)
    if not success or not playerPos then
        return self:HandleInvalidTargetPosition()
    end
    local PED_MODEL = Utils.Joaat("a_c_rat")
    local HELI_MODEL = 0x31F0B376
    local TRAIN_MODEL = 0xE5A41E08 -- 0xAFD22A6 0x3D6AAA9B 0xE5A41E08
    local PLANE_MODEL = 0x9C429B6A
    local SPAWN_COUNT = 5
    local CLEANUP_DELAY = 1000
    local spawnPos = {
        x = playerPos.x,
        y = playerPos.y,
        z = playerPos.z + 0
    }
    local spawnedEntities = {}
    local function remember(entity)
        if entity then
            spawnedEntities[#spawnedEntities + 1] = entity
        end
        return entity
    end
    local function deleteEntities(entities)
        for _, entity in pairs(entities) do
            if entity then
                EntityManager:DeleteEntity(entity)
            end
        end
    end
    local function spawnGroup()
        local group = {
            pilot = EntityManager:SpawnPed(PED_MODEL, spawnPos),
            passenger = EntityManager:SpawnPed(PED_MODEL, spawnPos),
            heli = EntityManager:SpawnVehicle(HELI_MODEL, spawnPos),
            train = EntityManager:SpawnVehicle(TRAIN_MODEL, spawnPos),
            plane = EntityManager:SpawnVehicle(PLANE_MODEL, spawnPos)
        }
        if not (group.pilot and group.passenger and group.heli and group.train and group.plane) then
            deleteEntities(group)
            return nil
        end
        remember(group.pilot)
        remember(group.passenger)
        remember(group.heli)
        remember(group.train)
        remember(group.plane)
        return group
    end
    local ok, err = pcall(function()
        for _ = 1, SPAWN_COUNT do
            local group = spawnGroup()
            if not group then
                Logger:Warn("SovereignLua", "TaskHeliExit spawn failed")
                break
            end
            menu.nativeApis.ENTITY.FREEZE_ENTITY_POSITION(group.train, true)
            menu.nativeApis.ENTITY.FREEZE_ENTITY_POSITION(group.plane, true)
            menu.nativeApis.PED.SET_PED_INTO_VEHICLE(group.pilot, group.heli, -1)
            menu.nativeApis.PED.SET_PED_INTO_VEHICLE(group.passenger, group.heli, 2)
            menu.nativeApis.FIRE.ADD_EXPLOSION(spawnPos.x, spawnPos.y, spawnPos.z, 54, 10.0, true, true, 0.0, false)
            Script.Yield(10)
            GTA.GiveControl(targetPid, group.train)
            GTA.GiveControl(targetPid, group.heli)
            Script.ExecuteAsScript("freemode", function()
                menu.nativeApis.TASK.TASK_RAPPEL_FROM_HELI(group.passenger, 30) -- TASK._TASK_RAPPEL_DOWN_WALL
            end)
        end
    end)
    if not ok then
        Logger:Warn("SovereignLua", string.format("TaskHeliExit failed: %s", tostring(err)))
    end
    Script.Yield(CLEANUP_DELAY)
    deleteEntities(spawnedEntities)
end

function CrashFunctions:RideOnBicycle(targetPid)
    local player = Players.GetById(targetPid)
    local success, Playerpos = PlayerManager:GetPlayerPosition(targetPid)
    if not success or not Playerpos then
        return self:HandleInvalidTargetPosition()
    end
    local models = {
        0xD86B5A95, 0x3C831724, 0xC2D06F53,
        0x14EC17EA, 0x431D501C, 0x56E29962,
        0x6AF51FAF, 0xC3B52966, 0xAAB71F62,
        0x2FD800B7, 0xB594F5C3, 0x53536529,
        0x8864083D
    }
    local rats = {}
    for _, hash in pairs(models) do
        local peds = AssertNotNil(EntityManager:SpawnPed(hash, Playerpos))
        NativeTaskQueue:Run("ride_bicycle_jump_" .. tostring(peds), 0.25, function()
            menu.nativeApis.TASK.TASK_JUMP(peds, true, false, false)
        end)
        Utils1:SafeInsert(rats, peds)
        Script.Yield(200)
    end
    local allpeds = EntityManager:GetNearbyPeds(20000)
    for _, value in pairs(allpeds) do
        menu.nativeApis.TASK.TASK_SET_BLOCKING_OF_NON_TEMPORARY_EVENTS(value, true)
        local netid = menu.nativeApis.NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(value)
        menu.nativeApis.NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netid, true)
        GTA.GiveControl(targetPid, value)
        Script.Yield(10)
        local ptr = GTA.HandleToPointer(value)
        if ptr then
            NetworkObjectMgr.ChangeOwner(ptr.NetObject, player, 3)
        end
    end
    local allvels = EntityManager:GetNearbyVehicles(20000)
    for _, value2 in pairs(allvels) do
        for i = 1, 10, 1 do
            local driver = menu.nativeApis.VEHICLE.GET_PED_IN_VEHICLE_SEAT(value2, -1, true)
            menu.nativeApis.TASK.TASK_SUBMARINE_GOTO_AND_STOP(1, value2, 0, 0, 0, 1)
            menu.nativeApis.TASK.TASK_PLANE_LAND(driver, value2, menu.nativeApis.VEHICLE.GET_PED_IN_VEHICLE_SEAT(value2, -1, true), 10.0, 0, 10, 0, 0);
            menu.nativeApis.TASK.TASK_VEHICLE_HELI_PROTECT(driver, value2, menu.nativeApis.VEHICLE.GET_PED_IN_VEHICLE_SEAT(value2, -1, true), 10.0, 0, 10, 0, 0)
            Script.Yield(0)
            local ptr2 = GTA.HandleToPointer(value2)
            if ptr2 then
                NetworkObjectMgr.ChangeOwner(ptr2.NetObject, player, 3)
            end
        end
    end
    Script.Yield(500)
    for key, value1 in pairs(rats) do
        EntityManager:DeleteEntity(value1)
        Script.Yield(0)
    end
    return true
end

