    local pos = menu.nativeApis.ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(targetPed, 3, 0, 0)
    local Ped = menu.nativeApis.PED.CREATE_RANDOM_PED(pos.x, pos.y, pos.z)
    menu.nativeApis.STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(Ped)
    menu.nativeApis.PED.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS(Ped, true)
    menu.nativeApis.ENTITY.SET_ENTITY_INVINCIBLE(Ped, true)
    local vehicles = {}
    for i = 1, 85 do
        local veh = AssertNotNil(EntityManager:SpawnVehicle(1483171323, pos))
        GTA.GiveControl(targetPid, veh)
        menu.nativeApis.ENTITY.FREEZE_ENTITY_POSITION(veh, true)
