        menu.nativeApis.VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false)
        menu.nativeApis.VEHICLE.SET_VEHICLE_KEEP_ENGINE_ON_WHEN_ABANDONED(veh, true)
        menu.nativeApis.ENTITY.SET_ENTITY_INVINCIBLE(veh, true)
        for m = 0, 3 do
            menu.nativeApis.VEHICLE.SET_VEHICLE_NEON_ENABLED(veh, m, true)
        end
        menu.nativeApis.VEHICLE.SET_AMBIENT_VEHICLE_NEON_ENABLED(true)
        for n = 17, 22 do
            menu.nativeApis.VEHICLE.TOGGLE_VEHICLE_MOD(veh, n, true)
        end
        menu.nativeApis.VEHICLE.SET_VEHICLE_XENON_LIGHT_COLOR_INDEX(veh, 10)
        menu.nativeApis.VEHICLE.SET_VEHICLE_HAS_UNBREAKABLE_LIGHTS(veh, false)
        menu.nativeApis.VEHICLE.SET_VEHICLE_FULLBEAM(veh, true)
        menu.nativeApis.VEHICLE.SET_VEHICLE_LIGHTS(veh, 3)
        menu.nativeApis.VEHICLE.SET_VEHICLE_HEADLIGHT_SHADOWS(veh, 3)
        menu.nativeApis.VEHICLE.SET_VEHICLE_INTERIORLIGHT(veh, true)
        menu.nativeApis.VEHICLE.SET_VEHICLE_FORCE_INTERIORLIGHT(veh, true)
        Utils1:SafeInsert(vehicles, veh)
    end
    Script.Yield(1000)
    for _, veh in ipairs(vehicles) do
