function CrashFunctions:PedOverflow(targetPid)
    local success, Playerpos = PlayerManager:GetPlayerPosition(targetPid)
    if not success or not Playerpos then
        return self:HandleInvalidTargetPosition()
    end
    Playerpos.z = Playerpos.z + 32
    local targetPed = PlayerManager:GetPlayerPed(targetPid)
    local targetRot = nil
    if targetPed then
        local rotSuccess, rot = pcall(function()
            return menu.nativeApis.ENTITY.GET_ENTITY_ROTATION(targetPed, 2)
        end)
        if rotSuccess then
            targetRot = rot
        end
    end
    local models = {
        0xD2EE1337,
        menu.nativeApis.MISC.GET_HASH_KEY("ig_wade"),
        menu.nativeApis.MISC.GET_HASH_KEY("cs_wade"),
    }
    local peds = {}
    for i = 1, 40 do
        for _, model in ipairs(models) do
            local ped = AssertNotNil(EntityManager:SpawnPed(model, Playerpos))
            GTA.GiveControl(targetPid, ped)
            Utils1:SafeInsert(peds, ped)
            Script.Yield(10)
            EntityManager:DeleteEntityLocal(ped)
        end
    end
    Script.Yield(0)
    local timeout = Utils1:NowSeconds() + 5
    while Utils1:NowSeconds() < timeout do
        local posSuccess, currentPos = PlayerManager:GetPlayerPosition(targetPid)
        if posSuccess and currentPos then
            if targetPed then
                local rotSuccess, currentRot = pcall(function()
                    return menu.nativeApis.ENTITY.GET_ENTITY_ROTATION(targetPed, 2)
                end)
                if rotSuccess then
                    targetRot = currentRot
                end
            end
            for _, ped in ipairs(peds) do
                EntityManager:ForceCamera(ped, currentPos, targetRot or {x=0, y=0, z=0})
            end
        end
        Script.Yield(0)
    end
    for _, ped in ipairs(peds) do
        EntityManager:DeleteEntity(ped)
    end
end

