function ProtectionSystem:RunProtectionScan(kind,feature,callback)
    local previous=self.runningLocks[kind]
    if not feature:IsToggled() then self.runningLocks[kind]=nil;return true end
    if previous then return true end
    local token={}
    self.runningLocks[kind]=token
    local guard={IsToggled=function()
        return not self.protectionUnloading and self.runningLocks[kind]==token and feature:IsToggled()
    end}
    local ok,result=pcall(callback,self,guard)
    if self.runningLocks[kind]==token then self.runningLocks[kind]=nil end
    if not ok then SovereignProtectionFeedback:Log("scan:"..kind,"error",tostring(result)) end
    return ok
end

-- R59: pool wrappers are never retained across yields. Every action reacquires
-- its pool slot and checks address, network identity, owner, model and distance.
-- Background pool work only. Incoming invalid data is rejected synchronously.
-- The two lanes reserve time for each other and share their limits across scans
-- restarted in the same game frame. A native call itself cannot be preempted.
function ProtectionSystem:ProtectionWorkSlice(kind, feature)
    self.protectionWorkBudget = self.protectionWorkBudget or {lanes={},stats={yields=0,peakEntityMs=0,peakAttachmentMs=0,entityBudgetMs=1,attachmentBudgetMs=0.5}}
    return {kind=kind,feature=feature,budget=self.protectionWorkBudget,resumes=0}
end

function ProtectionSystem:ProtectionWorkFinish(slice)
    if not slice.started then return end
    local lane = slice.lane
    lane.elapsed = lane.elapsed + math.max(0, os.clock() - slice.started)
    slice.started = nil
    local key = slice.kind == "attachment" and "peakAttachmentMs" or "peakEntityMs"
    slice.budget.stats[key] = math.max(slice.budget.stats[key], lane.elapsed * 1000)
end

function ProtectionSystem:ProtectionWorkCharge(slice, count)
    slice.lane.actions = slice.lane.actions + count
end

function ProtectionSystem:ProtectionWorkCheck(slice)
    self:ProtectionWorkFinish(slice)
    local budget = slice.budget
    while slice.feature:IsToggled() do
        local now = os.clock()
        local frame=slice.frame
        if frame==nil then
            local ok=false
            if menu.nativeApis.MISC and type(menu.nativeApis.MISC.GET_FRAME_COUNT)=="function" then ok,frame=pcall(menu.nativeApis.MISC.GET_FRAME_COUNT) end
            if not ok or type(frame)~="number" or frame~=frame or math.abs(frame)==rawget(math, "huge") then
                -- One shared time window, never a per-coroutine counter: two
                -- resumptions in the same window must not refill each other's lane.
                local stamp=SovereignProtectionFeedback:Now()
                frame="clock:"..tostring(math.floor(stamp*60))
                budget.stats.clockFallback=true
            end
            -- These loops have no other yields. Read the frame once on entry
            -- and once per resumption, rather than invoking a native per slot.
            slice.frame=frame
        end
        local lane = budget.lanes[slice.kind]
        if not lane or lane.frame ~= frame then
            lane = {frame=frame,slots=0,actions=0,elapsed=0}
            budget.lanes[slice.kind] = lane
        end
        -- Include budget lookup overhead in the active work estimate.
        lane.elapsed = lane.elapsed + math.max(0, os.clock()-now)
        local attach = slice.kind == "attachment"
        if lane.slots < (attach and 16 or 48) and lane.actions < (attach and 4 or 6)
            and lane.elapsed < (attach and 0.0005 or 0.0010) then
            lane.slots = lane.slots + 1
            slice.lane, slice.started = lane, os.clock()
            return true
        end
        budget.stats.yields = budget.stats.yields + 1
        Script.Yield(0)
        slice.frame=nil
        slice.resumes=slice.resumes+1
    end
    return false
end

function ProtectionSystem:EntityProtectionContext()
    local ok, context = pcall(function()
        local ped = GTA.GetLocalPed()
        if not ped then return nil end
        local pos = ped.Position
        local id = GTA.GetLocalPlayerId()
        if not pos or type(id) ~= "number" or id < 0 or id > 31 then return nil end
        local addr = ped:GetAddress()
        if not addr or addr == 0 then return nil end
        local x, y, z = pos.x, pos.y, pos.z
        if type(x) ~= "number" or type(y) ~= "number" or type(z) ~= "number"
            or x ~= x or y ~= y or z ~= z then return nil end
        return {address = addr, owner = id, x = x, y = y, z = z}
    end)
    return ok and context or nil
end

function ProtectionSystem:EntityProtectionSnapshot(pool, index, context, radius)
    local ok, item = pcall(function()
        local entity = pool.getter(index)
        if not entity then return nil end
        local address = entity:GetAddress()
        if not address or address == 0 or address == context.address then return nil end
        if pool.kind == "ped" then
            -- Unknown player status must never permit removal of a player ped.
            if not entity:IsPed() or entity:IsPlayer() ~= false then return nil end
        elseif pool.kind == "vehicle" and not entity:IsVehicle() then
            return nil
        end
        local net = entity.NetObject
        if not net then return nil end
        local owner, netId = net.PlayerId, net.ObjectID
        if type(owner) ~= "number" or owner < 0 or owner > 31 or owner % 1 ~= 0
            or owner == context.owner or type(netId) ~= "number" or netId < 0 then return nil end
        local position, modelInfo = entity.Position, entity.ModelInfo
        if not position or not modelInfo then return nil end
        local model = modelInfo.Model
        if type(model) ~= "number" or model == 0 then return nil end
        model = model & 0xFFFFFFFF
        local dx, dy, dz = position.x - context.x, position.y - context.y, position.z - context.z
        local distanceSquared = dx * dx + dy * dy + dz * dz
        if distanceSquared ~= distanceSquared or distanceSquared > radius * radius then return nil end
        return {pool = pool, index = index, address = address, owner = owner,
            netId = netId, model = model, radius = radius,
            key = tostring(address) .. ":" .. tostring(netId)}
    end)
    return ok and item or nil
end

function ProtectionSystem:EntityProtectionUnregister(item, context, stats)
    local current = self:EntityProtectionSnapshot(item.pool, item.index, context, item.radius)
    if not current or current.address ~= item.address or current.netId ~= item.netId
        or current.owner ~= item.owner or current.model ~= item.model then
        stats.stale = stats.stale + 1
        return false
    end
    -- No yield is allowed between this identity check and the manager call.
    local ok, result = pcall(function()
        local entity = item.pool.getter(item.index)
        if not entity or entity:GetAddress() ~= item.address then return false end
        local net = entity.NetObject
        if not net or net.ObjectID ~= item.netId or net.PlayerId ~= item.owner then return false end
        return NetworkObjectMgr.UnregisterNetworkObject(net, 8, true, true)
    end)
    stats.attempts = stats.attempts + 1
    if not ok or result == false then
        stats.failed = stats.failed + 1
        return false
    end
    stats.submitted = stats.submitted + 1
    -- The API normally returns void. A successful pcall is only submission;
    -- count a removal only after the slot no longer contains that net object.
    local readOk, removed = pcall(function()
        local entity = item.pool.getter(item.index)
        if not entity or entity:GetAddress() ~= item.address then return true end
        local net = entity.NetObject
        return not net or net.ObjectID ~= item.netId
    end)
    if readOk and removed then
        stats.removed = stats.removed + 1
        return true
    end
    return false
end

function ProtectionSystem:EntityProtectionPoolCount(pool)
    local ok, count = pcall(pool.max)
    if not ok or type(count) ~= "number" or count ~= count or count < 0 or count == rawget(math, "huge") then return 0 end
    return math.floor(count)
end

function ProtectionSystem:EntityCrashProtection(feature)
    local pools = {
        {kind="vehicle",max=PoolMgr.GetMaxVehicleCount,getter=PoolMgr.GetCVehicle},
        {kind="ped",max=PoolMgr.GetMaxPedCount,getter=PoolMgr.GetCPed},
    }
    while feature:IsToggled() do
        local allFeature = self.entityBlockAllFeature
        if allFeature and allFeature:IsToggled() then
            Script.Yield(350)
        else
            local context = self:EntityProtectionContext()
            local stats = {scanned=0,attempts=0,submitted=0,removed=0,failed=0,stale=0,firstActionScan=0}
            self.entityCrashStats = stats
            local groups, attempted, ownerAttempts, cancelled = {}, {}, {}, context == nil
            local origin = context
            local slice = self:ProtectionWorkSlice("entity", feature)
            local checkedResume = -1
            local function checkpoint()
                if not self:ProtectionWorkCheck(slice) then return false end
                if checkedResume==slice.resumes then return true end
                checkedResume=slice.resumes
                local fresh = self:EntityProtectionContext()
                if not fresh or not context or fresh.address ~= context.address or fresh.owner ~= context.owner then return false end
                -- Counts belong to one neighborhood; don't carry them through
                -- movement/teleports and apply them to another neighborhood.
                local dx,dy,dz=fresh.x-origin.x,fresh.y-origin.y,fresh.z-origin.z
                if dx*dx+dy*dy+dz*dz > 100 then groups={};origin=fresh end
                context = fresh
                local active = self.entityBlockAllFeature
                return not (active and active:IsToggled())
            end
            local function add(item, kind, threshold)
                local key = tostring(item.owner)..":"..kind
                local group = groups[key]
                if not group then
                    group = {count=0,removed=0}
                    groups[key] = group
                end
                group.count = group.count + 1
                -- Act on the current, freshly observed excess entity as soon
                -- as the threshold is crossed, without waiting for empty slots.
                -- Per-source quota: failures from the first owner in the pool
                -- cannot consume every other owner's cleanup opportunity.
                if group.count-group.removed <= threshold or (ownerAttempts[item.owner] or 0)>=12 or attempted[item.key] then return end
                if stats.firstActionScan == 0 then stats.firstActionScan = stats.scanned end
                local before = stats.attempts
                if self:EntityProtectionUnregister(item, context, stats) then
                    group.removed = group.removed + 1
                    if SovereignProtectionFeedback:Allow("entity-name:"..tostring(item.owner),5) then
                        local name = tostring(item.owner)
                        if Players and type(Players.GetName) == "function" then
                            local ok, value = pcall(Players.GetName,item.owner)
                            if ok and type(value)=="string" and value~="" then name=value end
                        end
                        SovereignProtectionFeedback:Report("entity:"..tostring(item.owner),"Entity crash protection",
                            string.format("Removed abnormal %s entities from %s",name,kind),"blocked",5)
                    end
                end
                local calls=stats.attempts-before
                if calls>0 then attempted[item.key]=true end
                ownerAttempts[item.owner]=(ownerAttempts[item.owner] or 0)+calls
                self:ProtectionWorkCharge(slice,calls)
            end
            if context then
                for _,pool in ipairs(pools) do
                    for index=0,self:EntityProtectionPoolCount(pool)-1 do
                        if not checkpoint() then cancelled=true;break end
                        stats.scanned = stats.scanned+1
                        local item = self:EntityProtectionSnapshot(pool,index,context,pool.kind=="vehicle" and 500.0 or 50.0)
                        if item then
                            if pool.kind=="vehicle" then
                                if self.modelLists.CrashVehModels[item.model] then add(item,"Vehicles",10) end
                            else
                                if self.modelLists.OnlinePlayerModels[item.model] then
                                    add(item,"Player model:"..tostring(item.model),39)
                                elseif not self.modelLists.SafePedModels[item.model] then
                                    add(item,"Pedestrian",32)
                                end
                            end
                        end
                    end
                    if cancelled then break end
                end
            end
            self:ProtectionWorkFinish(slice)
            stats.cancelled = cancelled
            Script.Yield(context and 350 or 500)
        end
    end
end

function ProtectionSystem:BlockAllEntities(feature)
    local pools = {
        {kind = "vehicle", max = PoolMgr.GetMaxVehicleCount, getter = PoolMgr.GetCVehicle},
        {kind = "ped", max = PoolMgr.GetMaxPedCount, getter = PoolMgr.GetCPed},
        {kind = "object", max = PoolMgr.GetMaxObjectCount, getter = PoolMgr.GetCObject},
        {kind = "pickup", max = PoolMgr.GetMaxPickupCount, getter = PoolMgr.GetCPickup},
        {kind = "camera", max = PoolMgr.GetMaxCameraCount, getter = PoolMgr.GetCCamera},
    }
    self.entityBlockAllFeature = feature
    while feature:IsToggled() do
        local stats = {scanned = 0, attempts = 0, submitted = 0, removed = 0, failed = 0, stale = 0}
        self.entityBlockAllStats = stats
        local context, attempted = self:EntityProtectionContext(), {}
        local slice, cancelled = self:ProtectionWorkSlice("entity", feature), false
        local checkedResume=-1
        if context then
            for _, pool in ipairs(pools) do
                local count = self:EntityProtectionPoolCount(pool)
                for index = 0, count - 1 do
                    if not self:ProtectionWorkCheck(slice) then cancelled=true;break end
                    if checkedResume~=slice.resumes then
                        local fresh=self:EntityProtectionContext()
                        if not fresh or fresh.address~=context.address or fresh.owner~=context.owner then cancelled=true;break end
                        context=fresh;checkedResume=slice.resumes
                    end
                    stats.scanned=stats.scanned+1
                    local item = self:EntityProtectionSnapshot(pool, index, context, 2000.0)
                    if item and not attempted[item.key] then
                        attempted[item.key] = true
                        local before = stats.attempts
                        self:EntityProtectionUnregister(item, context, stats)
                        self:ProtectionWorkCharge(slice,stats.attempts-before)
                    end
                end
                if cancelled then break end
            end
        end
        self:ProtectionWorkFinish(slice)
        stats.cancelled = cancelled
        if stats.removed > 0 then
            SovereignProtectionFeedback:Report("entity:all", "Block entities",
                string.format("Removed %d nearby remote entities", stats.removed), "blocked", 5)
        end
        Script.Yield(context and 350 or 500)
    end
    if self.entityBlockAllFeature == feature then self.entityBlockAllFeature = nil end
end

local NET_EVENTS = {
    SCRIPT_WORLD_STATE_EVENT = 33,
    NETWORK_TRAIN_REPORT_EVENT = 57,
    NETWORK_TRAIN_REQUEST_EVENT = 58,
}
local WORLD_STATE = {
    NET_WORLD_STATE_ROPE = 6,
}

local function SovereignIsTrainNetEvent(eventId)
    return eventId == NET_EVENTS.NETWORK_TRAIN_REPORT_EVENT
        or eventId == NET_EVENTS.NETWORK_TRAIN_REQUEST_EVENT
end

local function SovereignReadBufferUns(buffer, bits)
    local readUnsigned = buffer and buffer.ReadUns
    if type(readUnsigned) ~= "function" then
        return nil, false
    end
    return readUnsigned(buffer, bits)
end

local function SovereignReadBufferInt(buffer, bits)
    if buffer and type(buffer.ReadInt) == "function" then
        return buffer:ReadInt(bits)
    end
    local value, ok = SovereignReadBufferUns(buffer, bits)
    if not ok then
        return nil, false
    end
    local signBit = 2 ^ (bits - 1)
    local fullRange = 2 ^ bits
    if value >= signBit then
        value = value - fullRange
    end
    return value, true
end

local function SovereignReadBufferSignedFloat(buffer, bits, scale)
    local value, ok = SovereignReadBufferInt(buffer, bits)
    if not ok then
        return nil, false
    end
    local positiveMax = (2 ^ (bits - 1)) - 1
    local negativeMax = 2 ^ (bits - 1)
    if value < 0 then
        return (value / negativeMax) * scale, true
    end
    return (value / positiveMax) * scale, true
end

local function SovereignSkipBufferBits(buffer, bits)
    local _, ok = SovereignReadBufferUns(buffer, bits)
    return ok == true
end

local function SovereignReadGameScriptId(buffer)
    local scriptHash, ok = SovereignReadBufferUns(buffer, 32)
    if not ok then
        return nil, "scriptHash"
    end
    local timestamp
    timestamp, ok = SovereignReadBufferUns(buffer, 32)
    if not ok then
        return nil, "timestamp"
    end
    local hasPositionHash
    hasPositionHash, ok = buffer:ReadBool()
    if not ok then
        return nil, "hasPositionHash"
    end
    local positionHash = 0
    if hasPositionHash then
        positionHash, ok = SovereignReadBufferUns(buffer, 32)
        if not ok then
            return nil, "positionHash"
        end
    end
    local hasInstanceId
    hasInstanceId, ok = buffer:ReadBool()
    if not ok then
        return nil, "hasInstanceId"
    end
    local instanceId = 0
    if hasInstanceId then
        instanceId, ok = SovereignReadBufferUns(buffer, 8)
        if not ok then
            return nil, "instanceId"
        end
    end
    return {
        hash = scriptHash,
        timestamp = timestamp,
        positionHash = positionHash,
        instanceId = instanceId,
    }, nil
end

local function SovereignReadWorldStateRope(buffer)
    local ropeId, ok = SovereignReadBufferUns(buffer, 9)
    if not ok then
        return nil, "ropeId"
    end
    for _ = 1, 6 do
        if not SovereignSkipBufferBits(buffer, 19) then
            return nil, "posRot"
        end
    end
    local maxLength
    maxLength, ok = SovereignReadBufferSignedFloat(buffer, 16, 100.0)
    if not ok then
        return nil, "maxLength"
    end
    local ropeType
    ropeType, ok = SovereignReadBufferInt(buffer, 4)
    if not ok then
        return nil, "ropeType"
    end
    local initLength
    initLength, ok = SovereignReadBufferSignedFloat(buffer, 16, 100.0)
    if not ok then
        return nil, "initLength"
    end
    local minLength
    minLength, ok = SovereignReadBufferSignedFloat(buffer, 16, 100.0)
    if not ok then
        return nil, "minLength"
    end
    return {
        ropeId = ropeId,
        ropeType = ropeType,
        initLength = initLength,
        minLength = minLength,
        maxLength = maxLength,
    }, nil
end

local function SovereignFormatWorldStateRope(sender, worldStateType, changeState, scriptId, ropeData)
    return string.format(
        "SWSE Rope sender=%s eventType=%s change=%s scriptHash=0x%X instance=%s ropeId=%s type=%s init=%.6f min=%.6f max=%.6f",
        tostring(sender),
        tostring(worldStateType),
        tostring(changeState),
        tonumber(scriptId and scriptId.hash or 0) or 0,
        tostring(scriptId and scriptId.instanceId or 0),
        tostring(ropeData and ropeData.ropeId or 0),
        tostring(ropeData and ropeData.ropeType or 0),
        tonumber(ropeData and ropeData.initLength or 0) or 0,
        tonumber(ropeData and ropeData.minLength or 0) or 0,
        tonumber(ropeData and ropeData.maxLength or 0) or 0
    )
end

function ProtectionSystem:NetEventFilter(sender, eventId, buffer)
    eventId = tonumber(eventId)
    if eventId ~= NET_EVENTS.SCRIPT_WORLD_STATE_EVENT and not SovereignIsTrainNetEvent(eventId) then
        return false
    end
    if not buffer or type(buffer.Seek) ~= "function" or (eventId == NET_EVENTS.SCRIPT_WORLD_STATE_EVENT and type(buffer.ReadBool) ~= "function") then
        Logger:Info("SovereignProtectionSystem", "Blocked net event without DatBitBuffer event=" .. tostring(eventId) .. " player=" .. tostring(sender))
        return true
    end
    local readUnsigned = buffer.ReadUns
    if type(readUnsigned) ~= "function" then
        Logger:Info("SovereignProtectionSystem", "Blocked net event without unsigned reader event=" .. tostring(eventId) .. " player=" .. tostring(sender))
        return true
    end
    local ok, blocked = pcall(function()
        if buffer:Seek(0)==false then return true end
        if SovereignIsTrainNetEvent(eventId) then
            local trainTrack, trackOk = readUnsigned(buffer, 4)
            if not trackOk then
                return true
            end
            if trainTrack >= 12 then
                Logger:Toast("SovereignProtectionSystem", "Invalid track-write event blocked\nSender=" .. tostring(sender), CONFIG.UI.ToastDuration.Medium)
                Logger:Info("SovereignProtectionSystem", "Invalid track-write event blocked. Sender=" .. tostring(sender) .. " Event ID=" .. tostring(eventId) .. " Track ID" .. tostring(trainTrack))
                return true
            end
            return false
        end
        local worldStateType, ok1 = readUnsigned(buffer, 4)
        if not ok1 then
            Logger:Info("SovereignProtectionSystem", "SWSE worldStateType read error blocked: " .. tostring(worldStateType))
            return true
        end
        local changeState, ok2 = buffer:ReadBool()
        if not ok2 then
            Logger:Info("SovereignProtectionSystem", "SWSE changeState read error blocked: " .. tostring(changeState))
            return true
        end
        if worldStateType == WORLD_STATE.NET_WORLD_STATE_ROPE then
            local scriptId, scriptReadError = SovereignReadGameScriptId(buffer)
            if not scriptId then
                Logger:Info("SovereignProtectionSystem", "SWSE ScriptId error blocked: " .. tostring(scriptReadError))
                return true
            end
            local ropeData, ropeReadError = SovereignReadWorldStateRope(buffer)
            if not ropeData then
                Logger:Info("SovereignProtectionSystem", "SWSE read error blocked: " .. tostring(ropeReadError))
                return true
            end
            local lengthRange = ropeData.maxLength - ropeData.minLength
            local invalid = ropeData.ropeType < 0
                or ropeData.ropeType > 7
                or ropeData.maxLength < 0
                or ropeData.maxLength < ropeData.minLength
                or ropeData.initLength < ropeData.minLength
                or ropeData.initLength > 100
                or lengthRange > 100
            if invalid then
                local detail = SovereignFormatWorldStateRope(sender, worldStateType, changeState, scriptId, ropeData)
                Logger:Toast("SovereignProtectionSystem", "Abnormal SWSE rope creation blocked\n" .. tostring(sender), CONFIG.UI.ToastDuration.Medium)
                Logger:Info("SovereignProtectionSystem", "Abnormal SWSE rope creation blocked; data captured" .. detail)
                return true
            end
            return false
        end
        return false
    end)
    if buffer and type(buffer.Seek) == "function" then
        local restored,result=pcall(buffer.Seek,buffer,0)
        if not restored or result==false then return true end
    end
    if not ok then
        Logger:Error("SovereignProtectionSystem", "WorldState filter read failed: " .. tostring(blocked))
        return true
    end
    return blocked == true
end

function ProtectionSystem:BlockAllNetEvents()
    return true
end

function ProtectionSystem:BlockAllScriptedEvents()
    return true
end

-- R51: hashes/packed words may arrive as signed or unsigned 32-bit values.
function ProtectionSystem:AdInviteWord(value)
    if type(value) ~= "number" or value ~= value or value < -2147483648 or value > 4294967295 then return nil end
    local integer = math.tointeger(value)
    if not integer then return nil end
    integer = integer & 0xFFFFFFFF
    return integer >= 0x80000000 and integer - 0x100000000 or integer
end

function ProtectionSystem:AdSchemaUsesEvent(schema, eventHash)
    if eventHash == nil or schema.enabled == false then return false end
    if self:AdInviteWord(schema.eventHash) == eventHash then return true end
    if schema.eventKey and SCRIPT_EVENT and self:AdInviteWord(SCRIPT_EVENT[schema.eventKey]) == eventHash then return true end
    -- Aliases are opt-in, evidence-backed hashes for this EXACT layout.
    for _, hash in ipairs(schema.eventHashes or {}) do
        if self:AdInviteWord(hash) == eventHash then return true end
    end
    return false
end

function ProtectionSystem:IsAdInviteScriptEvent(eventHash)
    eventHash = self:AdInviteWord(eventHash)
    if eventHash == nil then return false end
    for _, schema in ipairs(self.adInviteSchemas) do
        if self:AdSchemaUsesEvent(schema, eventHash) then return true end
    end
    for _, key in ipairs(self.adInviteEventKeys) do
        if SCRIPT_EVENT and eventHash == self:AdInviteWord(SCRIPT_EVENT[key]) then return true end
    end
    for _, hash in ipairs(self.adInviteLiteralHashes) do
        if eventHash == self:AdInviteWord(hash) then return true end
    end
    return false
end

function ProtectionSystem:ReadAdInviteEnvelope(args)
    if type(args) ~= "table" then return nil, "invalid_args" end
    local base = rawget(args, 0) ~= nil and 0 or 1
    local count, high, inspected = 0, 0, 0
    for key in next, args do
        inspected = inspected + 1
        if inspected > 128 then return nil, "entry_limit" end
        if type(key) == "number" then
            if key % 1 ~= 0 or key < base or key >= base + 64 then return nil, "invalid_index" end
            count, high = count + 1, math.max(high, key - base + 1)
        end
    end
    if count == 0 or count ~= high then return nil, "sparse_or_empty" end
    local words = {}
    for index = 1, count do
        local value = self:AdInviteWord(rawget(args, base + index - 1))
        if value == nil then return nil, "invalid_word" end
        words[index] = value
    end
    return words, nil, base
end

-- Telemetry only; this count is NEVER an enforcement threshold.
function ProtectionSystem:TrackAdInvite(playerId, category)
    if type(playerId) ~= "number" or playerId % 1 ~= 0 or playerId < 0 or playerId > 31 then return 0 end
    local now, state = Utils1:NowSeconds(), self.adEventRate[playerId]
    if not state or now < state.startedAt or now - state.startedAt > 30 then
        state = {startedAt = now, count = 0}
        self.adEventRate[playerId] = state
    end
    state.count = math.min(state.count + 1, 2147483647)
    state.lastCategory = tostring(category)
    return state.count
end

function ProtectionSystem:IsKnownAdInvitePayload(eventHash, args, actualSender, parsed)
    eventHash = self:AdInviteWord(eventHash)
    if eventHash == nil then return false, nil, "invalid_event_hash" end
    local words, parseReason = parsed, nil
    if not words then words, parseReason = self:ReadAdInviteEnvelope(args) end
    if not words then return false, nil, parseReason end
    if words[1] ~= eventHash then return false, nil, "event_word_mismatch" end
    local reason = "unknown_event_schema"
    for _, schema in ipairs(self.adInviteSchemas) do
        if self:AdSchemaUsesEvent(schema, eventHash) then
            local matches = #words == schema.length
            reason = schema.id .. ":shape_mismatch"
            if matches then
                for index, expected in pairs(schema.required or {}) do
                    if words[index] ~= self:AdInviteWord(expected) then
                        matches, reason = false, schema.id .. ":required_field_mismatch"
                        break
                    end
                end
            end
            if matches and schema.senderIndex then
                local rawId = words[schema.senderIndex]
                local id = rawId
                if schema.senderEncoding == "negated" then
                    if type(rawId) ~= "number" or rawId >= 0 then
                        matches, reason = false, schema.id .. ":invalid_sender_encoding"
                    else
                        id = -rawId
                    end
                elseif schema.senderEncoding ~= nil then
                    matches, reason = false, schema.id .. ":unknown_sender_encoding"
                end
                if matches and (id == nil or id < 0 or id > 31 or id % 1 ~= 0) then
                    matches, reason = false, schema.id .. ":invalid_sender"
                elseif matches and schema.senderMirrorIndex and words[schema.senderMirrorIndex] ~= id then
                    matches, reason = false, schema.id .. ":sender_mirror_mismatch"
                elseif matches and type(actualSender) == "number" and actualSender >= 0 and actualSender <= 31 and id ~= actualSender then
                    matches, reason = false, schema.id .. ":sender_mismatch"
                end
            end
            if matches then
                if not schema.fingerprints then return true, schema.id, "schema_match", schema.id end
                for _, fingerprint in ipairs(schema.fingerprints) do
                    local matched = next(fingerprint.values or {}) ~= nil
                    for index, expected in pairs(fingerprint.values or {}) do
                        if words[index] ~= self:AdInviteWord(expected) then matched = false break end
                    end
                    if matched then return true, fingerprint.id, "schema_match", schema.id end
                end
                reason = schema.id .. ":fingerprint_mismatch"
            end
        end
    end
    return false, nil, reason
end

function ProtectionSystem:ResetAdInvitePlayer(playerId)
    if type(playerId) ~= "number" or playerId % 1 ~= 0 or playerId < 0 or playerId > 31 then return end
    self.adSanctionPending[playerId], self.adSanctionLast[playerId], self.adEventRate[playerId] = nil, nil, nil
end

function ProtectionSystem:ResetAdInviteRuntime()
    self.adSanctionPending, self.adSanctionLast, self.adEventRate = {}, {}, {}
end

function ProtectionSystem:GetAdInviteIdentity(playerId)
    if type(playerId) ~= "number" or playerId % 1 ~= 0 or playerId < 0 or playerId > 31 then return nil end
    local ok, player = pcall(function() return Players.GetById(playerId) end)
    if not ok or not player then return nil end
    local ridOk, found, rid = pcall(function()
        if PlayerManager and type(PlayerManager.GetRockstarId) == "function" then
            return PlayerManager:GetRockstarId(playerId)
        end
        return false, nil
    end)
    return {player = player, rid = ridOk and found and rid ~= nil and tostring(rid) ~= "0" and tostring(rid) or nil}
end

function ProtectionSystem:SameAdInviteIdentity(a, b)
    if not a or not b then return false end
    if a.rid or b.rid then return a.rid ~= nil and a.rid == b.rid end
    return a.player == b.player
end

function ProtectionSystem:QueueAdMachineSanction(playerId, playerName)
    if self.protectionUnloading or self.adProtectionEnabled == false then return false, "disabled" end
    if tonumber(self.adAction) ~= 2 then return false, "block_only" end
    if type(playerId) ~= "number" or playerId % 1 ~= 0 or playerId < 0 or playerId > 31 then return false, "invalid_sender" end
    if not GTA or type(GTA.GetLocalPlayerId) ~= "function" or playerId == GTA.GetLocalPlayerId() then return false, "local_or_unavailable" end
    local identity = self:GetAdInviteIdentity(playerId)
    if not identity then return false, "player_unavailable" end
    local now, pending, last = Utils1:NowSeconds(), self.adSanctionPending[playerId], self.adSanctionLast[playerId]
    if pending and self:SameAdInviteIdentity(pending.identity, identity) and now >= pending.at and now - pending.at < 5 then return true, "already_queued" end
    if last and self:SameAdInviteIdentity(last.identity, identity) and now >= last.at and now - last.at < 5 then return true, "recently_requested" end
    if not Script or type(Script.QueueJob) ~= "function" then return false, "queue_unavailable" end
    local job = {at = now, identity = identity, status = "queued"}
    self.adSanctionPending[playerId] = job
    local queued, result = pcall(Script.QueueJob, function()
        local jobOk = pcall(function()
        if self.adSanctionPending[playerId] ~= job then job.status = "cancelled" return end
        local elapsed = Utils1:NowSeconds() - job.at
        if self.protectionUnloading or self.adProtectionEnabled == false or tonumber(self.adAction) ~= 2
            or elapsed < 0 or elapsed > 5 or playerId == GTA.GetLocalPlayerId()
            or not self:SameAdInviteIdentity(identity, self:GetAdInviteIdentity(playerId)) then
            self.adSanctionPending[playerId], job.status = nil, "stale_target"
            return
        end
        local ok, invoked = pcall(function()
            local feature = FeatureMgr.GetFeatureByName("Smart Kick", playerId)
            if not feature or type(feature.OnClick) ~= "function" then return false end
            return feature:OnClick() ~= false
        end)
        self.adSanctionPending[playerId] = nil
        if ok and invoked then
            self.adSanctionLast[playerId], job.status = {at = Utils1:NowSeconds(), identity = identity}, "requested"
        else
            self.adSanctionLast[playerId], job.status = nil, "feature_failed"
            pcall(Logger.Warn, Logger, "SovereignProtectionSystem", "Smart Kick request failed. senderSlot=" .. playerId)
        end
        end)
        if not jobOk then
            if self.adSanctionPending[playerId] == job then self.adSanctionPending[playerId] = nil end
            job.status = "job_exception"
            pcall(Logger.Warn, Logger, "SovereignProtectionSystem", "Smart Kick job failed. senderSlot=" .. playerId)
        end
    end)
    if not queued or result == false then
        if self.adSanctionPending[playerId] == job then self.adSanctionPending[playerId] = nil end
        return false, "queue_failed"
    end
    return job.status == "queued" or job.status == "requested", job.status
end

function ProtectionSystem:GetScriptEventSenderId(sender, args)
    local function valid(value) return type(value) == "number" and value >= 0 and value <= 31 and value % 1 == 0 end
    if valid(sender) then return sender end
    if type(sender) ~= "table" and type(sender) ~= "userdata" then return -1 end
    local ok, id = pcall(function()
        for _, field in ipairs({"PlayerId", "PlayerID", "m_player_id"}) do if valid(sender[field]) then return sender[field] end end
        for _, method in ipairs({"GetId", "GetPlayerId", "GetPlayerID"}) do
            if type(sender[method]) == "function" then
                local value = sender[method](sender); if valid(value) then return value end
            end
        end
    end)
    -- Never use payload words as an authority for the kick target.
    return ok and valid(id) and id or -1
end

function ProtectionSystem:ScriptedGameEventFilter(sender, args)
    if type(args) ~= "table" then return false end
    local base = rawget(args, 0) ~= nil and 0 or 1
    local hash = self:AdInviteWord(rawget(args, base))
    if hash == nil or not self:IsAdInviteScriptEvent(hash) then return false end
    local playerId = self:GetScriptEventSenderId(sender)
    local words = self:ReadAdInviteEnvelope(args)
    if not words then return false end
    local isSpam, matched, reason, schemaId = self:IsKnownAdInvitePayload(hash, args, playerId, words)
    if not isSpam then return false end

    -- Every confirmed match is blocked immediately. Smart Kick is opt-in and
    -- is never triggered by repetition counters or a keyword-only fallback.
    local requested, action = false, "block_only"
    if tonumber(self.adAction) == 2 then
        local ok, result, queueAction = pcall(self.QueueAdMachineSanction, self, playerId)
        if ok then requested, action = result == true, queueAction or "queue_failed"
        else action = "queue_exception" end
    end
    pcall(self.TrackAdInvite, self, playerId, matched)
    pcall(function()
        if SovereignProtectionFeedback:Allow("advertising:" .. playerId, 5) then
            SovereignProtectionFeedback:Notice("advertising:" .. playerId,
                requested and "Advertising invitation blocked; Smart Kick requested" or "Advertising invitation blocked", "warning", 4)
            SovereignProtectionFeedback:Log("advertising:" .. playerId, "info", "Advertising invitation senderSlot=" .. playerId
                .. " rule=" .. self.adRuleVersion .. " event=" .. hash .. " schema=" .. tostring(schemaId)
                .. " pattern=" .. tostring(matched) .. " action=" .. tostring(action)
                .. " reason=" .. tostring(reason))
        end
    end)
    return true
end


function ProtectionSystem:AttachmentCycle(entity)
    local address=entity:GetAddress()
    if type(address)~="number" or address==0 then return false,"missing_entity" end
    local seen={[address]=true}
    local current=entity
    for depth=1,32 do
        local ext=current:GetAttachmentExtension()
        if not ext then return false,"detached" end
        local owner=ext.ThisEntity
        if owner and owner:GetAddress()~=current:GetAddress() then return false,"inconsistent_extension" end
        local parent=ext.AttachParent
        if not parent then return false,"normal_chain" end
        local parentAddress=parent:GetAddress()
        if not parentAddress or parentAddress==0 then return false,"normal_chain" end
        if seen[parentAddress] then return true,"parent_cycle" end
        seen[parentAddress]=true;current=parent
    end
    -- A long acyclic chain is not proof of corruption. Never clear its links.
    return false,"chain_budget"
end

function ProtectionSystem:RepairAttachment(pool,index,stats)
    local entity=pool.getter(index)
    if not entity then return end
    local address=entity:GetAddress()
    local bad,reason=self:AttachmentCycle(entity)
    if not bad then return end
    local handle=GTA.PointerToHandle(entity)
    if type(handle)~="number" or handle==0 then return end
    local fresh=pool.getter(index)
    if not fresh or fresh:GetAddress()~=address or not self:AttachmentCycle(fresh) then return end
    stats.attempted=stats.attempted+1
    local ok,result=pcall(menu.nativeApis.ENTITY.DETACH_ENTITY,handle,true,true)
    if not ok or result==false then stats.failed=stats.failed+1;return end
    fresh=pool.getter(index)
    if fresh and fresh:GetAddress()==address then
        local extension=fresh:GetAttachmentExtension()
        local parent=extension and extension.AttachParent
        if not parent or parent:GetAddress()==0 then stats.repaired=stats.repaired+1;return true end
    end
    stats.pending=stats.pending+1
end

function ProtectionSystem:AttachCrashProtection(feature)
    local pools={
        {max=PoolMgr.GetMaxVehicleCount,getter=PoolMgr.GetCVehicle},
        {max=PoolMgr.GetMaxPedCount,getter=PoolMgr.GetCPed},
        {max=PoolMgr.GetMaxObjectCount,getter=PoolMgr.GetCObject},
    }
    while feature:IsToggled() do
        local stats={scanned=0,attempted=0,repaired=0,failed=0,pending=0,errors=0}
        self.attachmentStats=stats
        local slice=self:ProtectionWorkSlice("attachment",feature)
        for _,pool in ipairs(pools) do
            local ok,count=pcall(pool.max)
            count=ok and type(count)=="number" and count>=0 and count<rawget(math, "huge") and math.floor(count) or 0
            for index=0,count-1 do
                if not self:ProtectionWorkCheck(slice) then return end
                stats.scanned=stats.scanned+1
                local before=stats.attempted
                local called,err=pcall(self.RepairAttachment,self,pool,index,stats)
                self:ProtectionWorkCharge(slice,stats.attempted-before)
                if not called then
                    stats.errors=stats.errors+1
                    if SovereignProtectionFeedback:Allow("attachment-read-error",5) then
                        SovereignProtectionFeedback:Log("attachment-read-error","warning",tostring(err))
                    end
                end
            end
        end
        self:ProtectionWorkFinish(slice)
        if stats.repaired>0 then
            SovereignProtectionFeedback:Notice("attachment-repaired","Repaired "..stats.repaired.." cyclic attachments","warning",4)
        end
        Script.Yield(350)
    end
end

function ProtectionSystem:DisableAntiCrashCamera(restoreMenu)
    local state=self.antiCrashCamera
    local cam=state and state.camera or 0
    if cam and cam~=0 and not menu.nativeApis.CAM then return false end
    if menu.nativeApis.CAM and cam and cam~=0 then
        local ownsRendering=false
        if type(menu.nativeApis.CAM.GET_RENDERING_CAM)=="function" then
            local ok,current=pcall(menu.nativeApis.CAM.GET_RENDERING_CAM)
            ownsRendering=ok and current==cam
        end
        if ownsRendering and type(menu.nativeApis.CAM.RENDER_SCRIPT_CAMS)=="function" then
            local ok,result=pcall(menu.nativeApis.CAM.RENDER_SCRIPT_CAMS,false,false,0,true,true,0)
            if not ok or result==false then return false end
        end
        local exists=true
        if type(menu.nativeApis.CAM.DOES_CAM_EXIST)=="function" then
            local ok,value=pcall(menu.nativeApis.CAM.DOES_CAM_EXIST,cam)
            if not ok then return false end
            exists=value==true
        end
        if exists then
            local ok,result=pcall(menu.nativeApis.CAM.DESTROY_CAM,cam,false)
            if not ok or result==false then return false end
        end
    end
    self.antiCrashCamera={camera=0,enabled=false}
    if restoreMenu and menu and menu.setOpen then pcall(menu.setOpen,true) end
    return true
end

function ProtectionSystem:AntiCrashCamera(feature)
    local wasMenuOpen = menu and menu.isOpen and menu.isOpen() or false
    local enabled = feature and feature.IsToggled and feature:IsToggled() == true
    if not enabled then
        self:DisableAntiCrashCamera(wasMenuOpen)
        return
    end

    local state = self.antiCrashCamera
    if state.enabled and state.camera and state.camera ~= 0 then
        if wasMenuOpen and menu and menu.setOpen then
            pcall(menu.setOpen, true)
        end
        return
    end

    if not self:DisableAntiCrashCamera(false) then return false end
    if not menu.nativeApis.CAM or not menu.nativeApis.CAM.CREATE_CAM_WITH_PARAMS or not menu.nativeApis.CAM.SET_CAM_ACTIVE or not menu.nativeApis.CAM.RENDER_SCRIPT_CAMS then
        Logger:Warn("SovereignProtectionSystem", "Crash protection camera API unavailable")
        if wasMenuOpen and menu and menu.setOpen then
            pcall(menu.setOpen, true)
        end
        return
    end

    local ok, err = pcall(function()
        local cam = menu.nativeApis.CAM.CREATE_CAM_WITH_PARAMS(
            "DEFAULT_SCRIPTED_CAMERA",
            2181.5520019531, 5201.8828125, 2501.0,
            -17.764436721802, 0.0, 143.65002441406,
            70.0, false, 0
        )
        if not cam or cam == 0 then
            error("camera creation failed", 0)
        end
        self.antiCrashCamera.camera = cam
        menu.nativeApis.CAM.SET_CAM_ACTIVE(cam, true)
        menu.nativeApis.CAM.RENDER_SCRIPT_CAMS(true, false, 0, true, true, 0)
        self.antiCrashCamera.enabled = true
    end)
    if not ok then
        self:DisableAntiCrashCamera(false)
        Logger:Warn("SovereignProtectionSystem", "Could not enable protection camera: " .. tostring(err))
    end
    if wasMenuOpen and menu and menu.setOpen then
        pcall(menu.setOpen, true)
    end
end

function ProtectionSystem:RegisterEventHandler(feature,eventType,handler)
    local hash=feature:GetHash()
    local existing=self.featureHandlers[hash]
    if feature:IsToggled() then
        if existing~=nil then return true end
        local ok,id=pcall(EventMgr.RegisterHandler,eventType,function(...)
            if self.protectionUnloading or not feature:IsToggled() then return false end
            local success,result=pcall(handler,...)
            if not success then
                SovereignProtectionFeedback:Log("event-handler:"..tostring(hash),"error",tostring(result))
                return false
            end
            return result==true
        end)
        if ok and id~=nil and id~=false then self.featureHandlers[hash]=id;return true end
        SovereignProtectionFeedback:Log("event-register:"..tostring(hash),"error",tostring(id))
        return false
    end
    if existing~=nil then
        local ok,result=pcall(EventMgr.RemoveHandler,existing)
        if not ok or result==false then return false end
        self.featureHandlers[hash]=nil
    end
    return true
end

function ProtectionSystem:CleanupEventHandlers()
    self:ResetAdInviteRuntime()
    self.protectionUnloading=true
    for hash,id in pairs(self.featureHandlers) do
        local ok,result=pcall(EventMgr.RemoveHandler,id)
        if ok and result~=false then self.featureHandlers[hash]=nil end
    end
end

g_pointers = g_pointers or {}
-- Plans contain resolved addresses for this invocation, never persistent RVAs.
SovereignPatchRegistry = {definitions = {}, states = {}, history = {}, order = {}}

function SovereignPatchRegistry:Now()
    return Utils1:NowSeconds()
end

function SovereignPatchRegistry:Record(id, state, reason)
    local item = self.states[id] or {id = id}
    self.states[id] = item
    item.state, item.reason, item.updated = state, reason, self:Now()
    self.history[#self.history + 1] = {id = id, state = state, reason = tostring(reason or ""), time = item.updated}
    if #self.history > 80 then table.remove(self.history, 1) end
    return item
end

function SovereignPatchRegistry:Register(id, definition)
    if type(id) ~= "string" or type(definition) ~= "table" or type(definition.resolve) ~= "function" then
        return false, "invalid_definition"
    end
    if self.states[id] and self.states[id].entries then return false, "restore_pending" end
    if not self.definitions[id] then self.order[#self.order + 1] = id end
    self.definitions[id] = definition
    self:Record(id, "idle")
    return true
end

function SovereignPatchRegistry:Read(entry)
    local reader = ({float = Memory.ReadFloat, uint = Memory.ReadUInt, byte = Memory.ReadUByte,
        ushort = Memory.ReadUShort})[entry.kind]
    if type(reader) ~= "function" then error("unsupported memory kind") end
    local value = reader(entry.address)
    if type(value) ~= "number" or value ~= value or math.abs(value) == rawget(math, "huge") then error("unreadable value") end
    return value
end

function SovereignPatchRegistry:Write(entry, value)
    local writer = ({float = Memory.WriteFloat, uint = Memory.WriteUInt, byte = Memory.WriteUByte,
        ushort = Memory.WriteUShort})[entry.kind]
    if type(writer) ~= "function" then error("memory writer unavailable") end
    local result = writer(entry.address, value)
    if result == false then error("memory writer rejected value") end
    local current = self:Read(entry)
    if not self:Equal(entry, current, value) then error("write readback mismatch") end
end

function SovereignPatchRegistry:Equal(entry, a, b)
    if type(a) ~= "number" or type(b) ~= "number" then return false end
    if entry.kind == "float" then return math.abs(a - b) <= math.max(0.00001, math.abs(b) * 0.000001) end
    return a == b
end

function SovereignPatchRegistry:Identity()
    local edition, _, module = Utils1:editionInfo()
    if not module then return nil, "edition_unresolved" end
    local base = Memory.GetBaseAddress(module)
    if type(base) ~= "number" or base < 0x10000 then return nil, "module_unavailable" end
    return edition .. ":" .. tostring(base)
end

function SovereignPatchRegistry:PlanValid(plan)
    local ok, identity = pcall(self.Identity, self)
    if not ok or identity ~= plan.identity then return false, "module_changed" end
    if type(plan.validate) ~= "function" then return false, "identity_validator_missing" end
    local valid, result, reason = pcall(plan.validate)
    if not valid or result ~= true then return false, tostring(valid and reason or result) end
    return true
end

function SovereignPatchRegistry:Resolve(id, options)
    local definition = self.definitions[id]
    if not definition then return nil, "unknown_patch" end
    local ok, plan, reason = pcall(definition.resolve, options or {})
    if not ok then reason, plan = plan, nil end
    if type(plan) ~= "table" or type(plan.writes) ~= "table" or #plan.writes == 0 or #plan.writes > 256 then
        self:Record(id, "unresolved", tostring(reason or "empty_plan"))
        return nil, reason or "empty_plan"
    end
    local identityOk, identity = pcall(self.Identity, self)
    if not identityOk or not identity then return nil, "module_unavailable" end
    plan.identity = identity
    local valid, why = self:PlanValid(plan)
    if not valid then return nil, why end
    local ranges = {}
    for _, entry in ipairs(plan.writes) do
        local size = ({float = 4, uint = 4, ushort = 2, byte = 1})[entry.kind]
        if not size or type(entry.address) ~= "number" or entry.address % 1 ~= 0
            or entry.address < 0x10000 or entry.address + size >= 0x0000800000000000
            or type(entry.value) ~= "number" or entry.value ~= entry.value or math.abs(entry.value) == rawget(math, "huge") then
            return nil, "invalid_entry"
        end
        if entry.kind ~= "float" and (entry.value % 1 ~= 0 or entry.value < 0 or entry.value >= 2 ^ (size * 8)) then
            return nil, "invalid_integer"
        end
        for _, range in ipairs(ranges) do
            if entry.address < range.last and entry.address + size > range.first then return nil, "overlapping_entries" end
        end
        for otherId, other in pairs(self.states) do
            if otherId ~= id then
                for _, owned in ipairs(other.entries or {}) do
                    local ownedSize = ({float = 4, uint = 4, ushort = 2, byte = 1})[owned.kind]
                    if entry.address < owned.address + ownedSize and entry.address + size > owned.address then
                        return nil, "patch_conflict:" .. otherId
                    end
                end
            end
        end
        ranges[#ranges + 1] = {first = entry.address, last = entry.address + size}
    end
    return plan
end

function SovereignPatchRegistry:Probe(id, options)
    local item = self.states[id]
    if item and item.entries then return false, "already_applied" end
    local plan, reason = self:Resolve(id, options)
    self:Record(id, plan and "resolved" or "unresolved", reason)
    return plan ~= nil, reason
end

function SovereignPatchRegistry:Apply(id, options)
    local prior = self.states[id]
    if prior and prior.entries then
        local restored, reason = self:Restore(id)
        if not restored then return false, reason end
    end
    local plan, reason = self:Resolve(id, options)
    if not plan then self:Record(id, "unresolved", reason); return false, reason end
    local entries = {}
    local readOk, readError = pcall(function()
        for _, proposed in ipairs(plan.writes) do
            local entry = {address = proposed.address, kind = proposed.kind, value = proposed.value, name = proposed.name}
            entry.original = self:Read(entry)
            if proposed.expected ~= nil and not self:Equal(entry, entry.original, proposed.expected) then
                error("original value changed: " .. tostring(entry.name))
            end
            entries[#entries + 1] = entry
        end
    end)
    if not readOk then self:Record(id, "failed", tostring(readError)); return false, readError end
    local item = self:Record(id, "applying")
    item.entries, item.plan, item.applied = entries, plan, 0
    local writeOk, writeError = pcall(function()
        local valid, why = self:PlanValid(plan)
        if not valid then error(why) end
        for index, entry in ipairs(entries) do
            -- Count a write before invoking it; APIs can throw after mutating memory.
            item.applied = index
            self:Write(entry, entry.value)
            entry.value = self:Read(entry)
        end
    end)
    if not writeOk then
        item.lastFailure = tostring(writeError)
        local restored = self:Restore(id)
        if restored then self:Record(id, "failed", tostring(writeError)) end
        return false, writeError
    end
    self:Record(id, "applied")
    return true
end

function SovereignPatchRegistry:Restore(id)
    local item = self.states[id]
    if not item or not item.entries then return true end
    local valid, reason = self:PlanValid(item.plan)
    if not valid then self:Record(id, "restore_pending", reason); return false, reason end
    local conflict, failed = false, false
    for index = item.applied or #item.entries, 1, -1 do
        local entry = item.entries[index]
        if not entry.restored then
            local ok, err = pcall(function()
                local current = self:Read(entry)
                if self:Equal(entry, current, entry.original) then
                    entry.restored = true
                elseif self:Equal(entry, current, entry.value) then
                    self:Write(entry, entry.original)
                    entry.restored = true
                else
                    entry.conflict, conflict = true, true
                end
            end)
            if not ok then failed, reason = true, tostring(err) end
        end
    end
    if failed or conflict then
        reason = conflict and "external_value_changed" or reason
        self:Record(id, conflict and "conflict" or "restore_pending", reason)
        return false, reason
    end
    item.entries, item.plan, item.applied = nil, nil, nil
    self:Record(id, "restored")
    return true
end

function SovereignPatchRegistry:Refresh()
    for id, item in pairs(self.states) do
        if item.entries then
            if item.state == "restore_pending" then
                self:Restore(id)
            elseif item.state == "applied" then
                local ok, reason = self:PlanValid(item.plan)
                if ok then
                    for _, entry in ipairs(item.entries) do
                        local readOk, current = pcall(self.Read, self, entry)
                        if not readOk or not self:Equal(entry, current, entry.value) then
                            ok, reason = false, readOk and "external_value_changed" or tostring(current)
                            break
                        end
                    end
                end
                if not ok then self:Record(id, "conflict", reason) end
            end
        end
    end
end

function SovereignPatchRegistry:RestoreAll()
    local success = true
    for index = #self.order, 1, -1 do
        local ok, restored = pcall(self.Restore, self, self.order[index])
        if not ok or restored ~= true then success = false end
    end
    return success
end

local MemoryBridge = {
    pointers = g_pointers,
    scanDefinitions = {},
    requiredPointers = {},
    mappingProfile = nil,
    mappingError = "unresolved",
    scanned = false,
    ready = false,
    lastScanReport = "",
    scanResults = {},
    tempAllocs = {},
}

Utils1.resetEditionMapping = function()
    if SovereignRuntimePatchBridge and type(SovereignRuntimePatchBridge.RestoreAll) == "function" then
        local restoreOk, restored = pcall(SovereignRuntimePatchBridge.RestoreAll, SovereignRuntimePatchBridge)
        if not restoreOk or restored ~= true then
            Logger:Error("EditionMapping", "reset blocked: active runtime patches were not restored")
            return false
        end
    end
    local resetOk, resetResult = pcall(MemoryBridge.ResetForEditionChange, MemoryBridge)
    if not resetOk or resetResult == false then
        Logger:Error("EditionMapping", "reset failed")
        return false
    end
    return true
end

function MemoryBridge:ResetForEditionChange()
    self.scanned = false
    self.ready = false
    self.mappingProfile = nil
    self.scanDefinitions = {}
    self.lastScanReport = ""
    self.scanResults = {}
    for name in pairs(self.pointers) do
        self.pointers[name] = nil
    end
end

function MemoryBridge:IsAvailable()
    return Memory and Memory.Scan and Memory.ReadLong and Memory.WriteUByte
end

function MemoryBridge:IsValidAddress(addr)
    return type(addr) == "number" and addr >= 0x10000 and addr < 0x800000000000
        and addr % 1 == 0
end

function MemoryBridge:RegisterPointer(name, address)
    if self:IsValidAddress(address) then
        self.pointers[name] = address
        return true
    end
    self.pointers[name] = nil
    return false
end

function MemoryBridge:GetModuleName()
    local _, _, module = Utils1:editionInfo()
    return module
end

function MemoryBridge:ResolveMappingProfile()
    local edition = Utils1:edition()
    local build = Utils1:buildInfo()
    if edition ~= "Enhanced" and edition ~= "Legacy" then
        return nil, "GTA edition is unresolved"
    end
    if not build or build == "Unknown" then
        return nil, "GTA build identifier is unresolved"
    end

    local profile = SovereignOfficial:GetMapping()
    if type(profile) ~= "table" then
        return nil, string.format("mapping profile missing: %s/%s", edition, build)
    end
    if profile.edition ~= edition:lower() or profile.gameBuild ~= build
        or type(profile.moduleSha256) ~= "string" or #profile.moduleSha256 ~= 64
        or not profile.moduleSha256:match("^%x+$")
        or type(profile.payloadBuild) ~= "string"
        or profile.payloadBuild ~= CONFIG.RELEASE.RemoteBuild
        or type(profile.signatures) ~= "table" then
        return nil, string.format("mapping profile invalid: %s/%s", edition, build)
    end
    return profile
end

function MemoryBridge:Scan(name, signature, ripOffset, resolver)
    self.pointers[name] = nil
    if not self:IsAvailable() then
        return false, "Memory API unavailable"
    end
    local moduleName = self:GetModuleName()
    if not moduleName then
        self.pointers[name] = nil
        return false, "GTA edition is unresolved"
    end
    local stage = "scan"
    local ok, result, reason = pcall(function()
        local raw = Memory.Scan(signature, moduleName)
        if not self:IsValidAddress(raw) then return nil, "signature not found" end
        if ripOffset then
            stage = "rip"
            if type(Memory.Rip) ~= "function" then return nil, "Memory.Rip unavailable" end
            raw = Memory.Rip(raw + ripOffset)
            if not self:IsValidAddress(raw) then return nil, "invalid address" end
        end
        if resolver then
            stage = "resolver"
            raw = resolver(raw)
            if not self:IsValidAddress(raw) then return nil, "invalid address" end
        end
        return raw
    end)
    if not ok then
        self.pointers[name] = nil
        return false, stage .. ": " .. tostring(result)
    end
    if self:RegisterPointer(name, result) then
        return true, result
    end
    return false, stage .. ": " .. (reason or "invalid address")
end

function MemoryBridge:BuildScanDefinitions()
    local profile, profileError = self:ResolveMappingProfile()
    self.mappingProfile = profile
    self.mappingError = profileError
    self.requiredPointers = {}
    if not profile then
        self.scanDefinitions = {}
        return false
    end

    local enhanced = Utils1:edition() == "Enhanced"
    local function crouch(ptr)
        if not self:IsValidAddress(ptr) then return nil end
        local cfg = Memory.ReadLong(ptr)
        if not self:IsValidAddress(cfg) then return nil end
        -- Both reviewed instruction chains load [global], then [config + 0x18].
        -- Dereferencing [config] again follows the vtable instead of the data.
        local movement = Memory.ReadLong(cfg + 24)
        if not self:IsValidAddress(movement) then return nil end
        return movement + (enhanced and 1396 or 1244)
    end
    local function legacyGeo(scan)
        if not self:IsValidAddress(scan) or type(Memory.Rip) ~= "function" then return nil end
        local rex, opcode, modrm = Memory.ReadUByte(scan + 13), Memory.ReadUByte(scan + 14), Memory.ReadUByte(scan + 15)
        if rex < 0x40 or rex > 0x4F or (opcode ~= 0x8B and opcode ~= 0x8D)
            or (modrm & 0xC7) ~= 0x05 then return nil end
        return Memory.Rip(scan + 16)
    end
    -- Resolver layout belongs to this exact payload release; signatures are
    -- supplied by the reviewed game profile and have no historical fallback.
    local definitions = {
        {name = "m_AllowCrouchedMovement", rip = 3, resolver = crouch},
        {name = "rlRosGetGeoLocInfo", rip = enhanced and 3 or nil, resolver = not enhanced and legacyGeo or nil},
        {name = "GetColor", rip = enhanced and 3 or 7},
        {name = "CWeaponDamageEvent__Trigger", rip = 1},
        {name = "CChangeRadioStationEvent__Trigger", rip = enhanced and 1 or 7},
        {name = "CBlowUpVehicleEvent__Trigger", rip = 1},
        {name = "CAlterWantedLevelEvent__Trigger", rip = not enhanced and 1 or nil},
    }
    for _, definition in ipairs(definitions) do
        local signature = profile.signatures[definition.name]
        if type(signature) ~= "string" or signature == "" then
            self.scanDefinitions = {}
            self.mappingError = "required mapping missing: " .. definition.name
            return false
        end
        definition.sig = signature
        self.requiredPointers[#self.requiredPointers + 1] = definition.name
    end
    self.scanDefinitions = definitions
    return true
end

function MemoryBridge:RefreshPointer(name)
    -- Rebuild atomically: a refreshed pointer must not revive a partial map.
    if not self:Initialize(true) then return false, self.lastScanReport end
    local pointer = self:GetPointer(name)
    if pointer then return true, pointer end
    return false, "scan definition not found"
end

function MemoryBridge:Initialize(force)
    if self.scanned and not force then
        return self.ready
    end
    self:ResetForEditionChange()
    self.scanned = true
    if not self:BuildScanDefinitions() then
        self.lastScanReport = self.mappingError or "E_MAPPING_MISSING"
        return false
    end
    local found, missing = 0, 0
    local failures = {}
    for _, def in ipairs(self.scanDefinitions) do
        local ok, result = self:Scan(def.name, def.sig, def.rip, def.resolver)
        self.scanResults[def.name] = {ok = ok, reason = not ok and tostring(result) or nil}
        if ok then
            found = found + 1
        else
            missing = missing + 1
            failures[#failures + 1] = def.name .. " (" .. tostring(result) .. ")"
        end
    end
    self.ready = found > 0 and missing == 0
    self.lastScanReport = string.format("MemoryBridge: %d found, %d missing", found, missing)
    if not self.ready then
        self.lastScanReport = self.lastScanReport .. "; missing=" .. table.concat(failures, "; ")
        for name in pairs(self.pointers) do self.pointers[name] = nil end
    end
    return self.ready
end

function MemoryBridge:GetPointer(name)
    if not self.ready then return nil end
    return self.pointers[name]
end

function MemoryBridge:HasPointer(name)
    return self:IsValidAddress(self:GetPointer(name))
end

function MemoryBridge:GetStatusLines()
    if not self.scanned then
        return {"MemoryBridge not initialized"}
    end
    local lines = {self.lastScanReport}
    for _, def in ipairs(self.scanDefinitions) do
        local result = self.scanResults[def.name]
        local status = result and result.ok and "OK" or "MISS"
        local reason = result and result.reason and (": " .. result.reason) or ""
        table.insert(lines, status .. " " .. def.name .. reason)
    end
    return lines
end

function MemoryBridge:Alloc(size)
    if not Memory or not Memory.Alloc then
        return nil
    end
    local ptr = Memory.Alloc(size)
    if self:IsValidAddress(ptr) then
        table.insert(self.tempAllocs, ptr)
        return ptr
    end
    return nil
end

function MemoryBridge:FreeTempAllocs()
    if not Memory or not Memory.Free then
        self.tempAllocs = {}
        return
    end
    for _, ptr in ipairs(self.tempAllocs) do
        if self:IsValidAddress(ptr) then
            pcall(function() Memory.Free(ptr) end)
        end
    end
    self.tempAllocs = {}
end

function MemoryBridge:CallPointer(name, ...)
    local ptr = self:GetPointer(name)
    if not self:IsValidAddress(ptr) then
        return false, "missing pointer: " .. tostring(name)
    end
    if not Memory or not Memory.LuaCallCFunction then
        return false, "LuaCallCFunction unavailable"
    end
    local ok, result = pcall(function(...)
        return Memory.LuaCallCFunction(ptr, ...)
    end, ...)
    if not ok then
        Logger:Warn("MemoryBridge", "Call failed: " .. tostring(name) .. " " .. tostring(result))
        return false, result
    end
    return true, result
end

function MemoryBridge:DryRunPointerCall(name, ...)
    self:Initialize(false)
    local ptr = self:GetPointer(name)
    local info = {
        name = tostring(name),
        pointer = ptr,
        pointerOk = self:IsValidAddress(ptr),
        callApiOk = Memory and Memory.LuaCallCFunction ~= nil,
        argc = select("#", ...)
    }
    Logger:Info("MemoryBridge", string.format(
        "DryRun %s ptr=%s ptrOk=%s api=%s blocked=%s argc=%d",
        info.name,
        tostring(info.pointer),
        tostring(info.pointerOk),
        tostring(info.callApiOk),
        tostring(info.blocked),
        info.argc
    ))
    return info
end

function MemoryBridge:ReadFloat3(address)
    if not self:IsValidAddress(address) or not Memory or not Memory.ReadFloat then
        return nil
    end
    local ok, result = pcall(function()
        return {
            x = Memory.ReadFloat(address),
            y = Memory.ReadFloat(address + 4),
            z = Memory.ReadFloat(address + 8)
        }
    end)
    return ok and result or nil
end

function MemoryBridge:WriteFloat3(address, x, y, z)
    if not self:IsValidAddress(address) or not Memory or not Memory.WriteFloat then
        return false
    end
    local ok = pcall(function()
        Memory.WriteFloat(address, x)
        Memory.WriteFloat(address + 4, y)
        Memory.WriteFloat(address + 8, z)
    end)
    return ok
end

function MemoryBridge:Cleanup()
    self:FreeTempAllocs()
end

local MemoryPatcher = {
    addresses = {},
    isPatched = false,
    patches = {},
}

function MemoryPatcher:ReadBytes(address, length)
    local bytes = {}
    for i = 1, length do
        bytes[i] = Memory.ReadUByte(address + (i - 1))
    end
    return bytes
end

function MemoryPatcher:WriteBytes(address, bytes)
    for i, b in ipairs(bytes) do
        Memory.WriteUByte(address + (i - 1), b)
    end
end

function MemoryPatcher:ApplyPatch(name, address, patchBytes)
    if self.patches[name] and self.patches[name].patched then
        return true
    end
    self.patches[name] = {
        address = address,
        originalBytes = self:ReadBytes(address, #patchBytes),
        patchBytes = patchBytes,
        patched = true
    }
    self:WriteBytes(address, patchBytes)
    return true
end

function MemoryPatcher:RestorePatch(name)
    local patch = self.patches[name]
    if not patch or not patch.patched or not patch.address or not patch.originalBytes then
        return true
    end
    self:WriteBytes(patch.address, patch.originalBytes)
    patch.patched = false
    return true
end

function MemoryPatcher:RestoreAllPatches()
    for name, patch in pairs(self.patches) do
        if patch and patch.patched then
            self:RestorePatch(name)
        end
    end
end
function MemoryPatcher:SetHardwareNatOpen()
    if Utils1:edition() ~= "Enhanced" then
        return
    else
        local success, result, address = pcall(function()
            local base = Memory.GetBaseAddress(MemoryBridge:GetModuleName())
            if type(base) ~= "number" or base < 0x10000 then return false end
            Memory.WriteInt(base + 0x45AFD60 + 4, 1)
            return true, base + 0x45AFD60 + 4
        end)
        if not success or result ~= true then
            Logger:Error("SovereignLua", "SetHardwareNatOpen failed: " .. tostring(result))
        else
            MemoryBridge:RegisterPointer("HardwareNatOpen", address)
            Logger:Info("SovereignLua", "Attraction optimization complete")
        end
    end
end

function MemoryPatcher:PatchNullptrPoolCrash()
    local version = Utils1:edition()
    if version == "Enhanced" then
        local success, result = pcall(function()
            local scanResult = Memory.Scan("E8 ? ? ? ? 48 85 C0 74 55 0F 13 30", MemoryBridge:GetModuleName())
            if not scanResult then
                Logger:Error("SovereignLua", "Scan failed for nullptr patch")
                return false
            end
            self.addresses.sub_7FF6FA173F80 = Memory.Rip(scanResult + 1)
            MemoryBridge:RegisterPointer("PatchNullptrPoolCrash_Main", self.addresses.sub_7FF6FA173F80)
            local jmpBytes = {0x56, 0x57, 0x48, 0x83, 0xEC, 0x28, 0x48, 0x83, 0xC4, 0x28, 0x5F, 0x5E, 0xC3}
            self:ApplyPatch("nullptr_pool_crash", self.addresses.sub_7FF6FA173F80, jmpBytes)
            local scanResult2 = Memory.Scan("E8 ? ? ? ? 49 8B 44 24 ? 49 8B 4C 24 ? 48 8B 98 ? ? ? ?", MemoryBridge:GetModuleName())
            if not scanResult2 then
                Logger:Error("SovereignLua", "Scan failed for prop patch")
                return false
            end
            self.addresses.propFunc = Memory.Rip(scanResult2 + 1)
            MemoryBridge:RegisterPointer("PatchNullptrPoolCrash_Prop", self.addresses.propFunc)
            self:ApplyPatch("nullptr_pool_prop", self.addresses.propFunc, {0xC3})
            self.isPatched = true
            return true
        end)
        if not success or result~=true then
            Logger:Error("SovereignProtectionSystem", "Some crash protections could not be enabled: " .. tostring(result))
        else
            Logger:Info("SovereignProtectionSystem", "Crash protection loaded")
        end
        return success and result==true
    elseif version == "Legacy" then
        Logger:Info("SovereignLua", "Legacy detected; Enhanced-only functions were not loaded")
    end
end

function MemoryPatcher:PatchWorldStateE()
    if Utils1:edition() ~= "Enhanced" then
        return false
    end
    local success, result = pcall(function()
        local scanResult = Memory.Scan("E8 ? ? ? ? 49 89 06 89 B0 ? ? ? ?", MemoryBridge:GetModuleName())
        if not scanResult then
            Logger:Error("SovereignLua", "Scan failed for world state patch")
            return false
        end
        self.addresses.add_rope = Memory.Rip(scanResult + 1)
        self:ApplyPatch("world_state_add_rope", self.addresses.add_rope, {0xC3})
        return true
    end)
    if not success then
        Logger:Error("SovereignLua", "PatchWorldStateE exception: " .. tostring(result))
    end
    return success and result
end

function MemoryPatcher:PatchSeatShuffleTaskCrash()
    local success, result = pcall(function()
        -- CTaskInVehicleSeatShuffle_ProcessPreFSM
        local scanResult = Memory.Scan("48 89 5C 24 ? 57 48 83 EC ? 48 8B 59 ? 48 8B 91", MemoryBridge:GetModuleName())
        if not scanResult then
            Logger:Error("SovereignLua", "Scan failed for seat shuffle task patch")
            return false
        end
        self.addresses.seat_shuffle_prefsm = scanResult
        MemoryBridge:RegisterPointer("CTaskInVehicleSeatShuffle_ProcessPreFSM", scanResult)
        self:ApplyPatch("seat_shuffle_task_crash", scanResult, {0xB8, 0x01, 0x00, 0x00, 0x00, 0xC3})
        return true
    end)
    if not success then
        Logger:Error("SovereignLua", "PatchSeatShuffleTaskCrash exception: " .. tostring(result))
        return false
    end
    if result then
        Logger:Info("SovereignLua", "Seat shuffle task crash protection patched")
    end
    return result == true
end

-- idk if these will also stop chreax protection...but we keep them here anyway
function MemoryPatcher:StopProtection()
    local success, result = pcall(function()
        self:RestorePatch("nullptr_pool_prop")
        self:RestorePatch("seat_shuffle_task_crash")
        self:RestorePatch("world_state_add_rope")
        -- self:RestoreAllPatches() nullptr_pool_crash If a game thread enters this function while Lua restores the original machine code one byte at a time, it may execute partially restored instructions and trigger an error or crash.
        return true
    end)
    if not success then
        Logger:Error("SovereignLua", "StopProtection exception: " .. tostring(result))
    end
    self.isPatched = false
end

-- R53 private canary: optional version-scoped patches are isolated from the
-- required event mapping. Every write snapshots, validates and restores the
-- exact value observed for the current module identity.
SovereignRuntimePatchBridge = {
    catalog = {Enhanced = {}, Legacy = {}},
    features = {},
    states = {},
    active = {},
    order = {},
    history = {},
    recoveryRequired = {},
    parsed = false,
    lastError = nil,
    natType = {value = "Not loaded", updated = 0},
    expectedScalars = {
        m_AllowCrouchedMovement = 0,
        m_MinFallingSpeedInRagdoll = -10.0,
        m_MinTimeInRagdoll = 1.0,
        ms_fMaximumSpeedToOpenRoofSq = 100.0,
    },
}

