function SovereignRuntimePatchBridge:Record(id, state, detail)
    local row = {
        id = tostring(id), state = tostring(state), detail = tostring(detail or ""),
        time = Utils1 and Utils1.NowSeconds and Utils1:NowSeconds() or os.clock()
    }
    self.history[#self.history + 1] = row
    if #self.history > 160 then table.remove(self.history, 1) end
    if state == "failed" or state == "conflict" then self.lastError = row end
end

function SovereignRuntimePatchBridge:ParseByteList(value)
    local result = {}
    for token in tostring(value or ""):gmatch("[^,]+") do
        local number = tonumber(token, 16)
        if number == nil or number < 0 or number > 255 then return nil end
        result[#result + 1] = number
    end
    return result
end

function SovereignRuntimePatchBridge:ParseCatalog()
    if self.parsed then return true end
    for line in SovereignRuntimePatchCatalogData:gmatch("[^\r\n]+") do
        if line ~= "" and line:sub(1, 1) ~= "@" then
            local id, edition, rip, add, kind, mode, bytes, signature, original =
                line:match("^([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]*)|([^|]+)|([^|]*)$")
            if not id then return false, "catalog_parse_failed" end
            local resolvedEdition = edition == "E" and "Enhanced" or edition == "L" and "Legacy" or nil
            local byteList = self:ParseByteList(bytes)
            local originalList = self:ParseByteList(original)
            if not resolvedEdition or not byteList or not originalList then
                return false, "catalog_value_invalid:" .. tostring(id)
            end
            if kind == "bytes" and (#byteList < 1 or #originalList ~= #byteList) then
                return false, "catalog_original_invalid:" .. tostring(id)
            end
            self.catalog[resolvedEdition][id] = {
                id = id,
                signature = signature,
                rip = rip == "-" and nil or tonumber(rip),
                add = tonumber(add) or 0,
                kind = kind,
                mode = mode,
                bytes = byteList,
                original = originalList,
            }
        end
    end
    self.parsed = true
    return true
end

function SovereignRuntimePatchBridge:IsAddress(value)
    return MemoryBridge and MemoryBridge:IsValidAddress(value)
end

function SovereignRuntimePatchBridge:Identity()
    local edition, _, module = Utils1:editionInfo()
    if edition ~= "Enhanced" and edition ~= "Legacy" then return nil, "edition_unresolved" end
    if not module then return nil, "module_unresolved" end
    local base = Memory.GetBaseAddress(module)
    if not self:IsAddress(base) then return nil, "module_unavailable" end
    local profile = MemoryBridge.mappingProfile
    if type(profile) ~= "table" or type(profile.moduleSha256) ~= "string" then
        return nil, "mapping_profile_unavailable"
    end
    return table.concat({edition, tostring(base), profile.moduleSha256, tostring(profile.payloadBuild)}, ":")
end

function SovereignRuntimePatchBridge:EnsureRuntime()
    local parsed, parseError = self:ParseCatalog()
    if not parsed then return false, parseError end
    -- Independent patches require an exact Loader-verified profile, but do
    -- not depend on unrelated event or configuration-manager pointers.
    local profile, profileError = MemoryBridge:ResolveMappingProfile()
    if not profile then return false, profileError or "mapping_unavailable" end
    local edition = Utils1:edition()
    local build = Utils1:buildInfo()
    local supported = {
        Enhanced = {"69da07ff67d05e9ded11289e597e8b8dc5855b0a429c085f37d148dc267cb2c5", "6AA45F10-05B45200"},
        Legacy = {"677e4e355cfbdb13273b1d992407e3c261b3a108dc4dd5c8a0c4c1da651802e5", "6A4F9ED3-03E5BC00"},
    }
    local expected = supported[edition]
    if not expected or profile.moduleSha256:lower() ~= expected[1] or build ~= expected[2] then
        return false, "catalog_build_unverified:" .. tostring(edition) .. "/" .. tostring(build)
    end
    MemoryBridge.mappingProfile = profile
    local identity, identityError = self:Identity()
    if not identity then return false, identityError end
    return true, identity
end

function SovereignRuntimePatchBridge:DescribeError(reason)
    local text = tostring(reason or "unknown")
    local descriptions = {
        {"version_unresolved:", "This feature is not available for this game version"},
        {"catalog_build_unverified:", "This game version is not supported yet"},
        {"signature_not_found:", "This feature is unavailable in the current game"},
        {"exact_original_mismatch:", "Another active setting may conflict with this feature"},
        {"target_already_modified", "Another feature already controls this setting"},
        {"mapping profile missing:", "Restart the game through Loader and try again"},
        {"mapping profile invalid:", "Restart the game through the matching Loader version"},
        {"required_pointer_unresolved:", "This feature is not ready. Please try again later."},
        {"module_changed_restore_required", "The previous setting has not finished restoring"},
        {"atomic_writer_unavailable:", "Update Cherax and try again"},
        {"original_scalar_mismatch", "This feature is not compatible with the current game version"},
    }
    for _, item in ipairs(descriptions) do
        if text:find(item[1], 1, true) then return item[2] .. "：" .. text end
    end
    return text
end

function SovereignRuntimePatchBridge:InspectCatalog()
    local ready, runtimeError = self:EnsureRuntime()
    if not ready then return {{id = "runtime", status = "failed", reason = tostring(runtimeError)}} end
    local rows, ids = {}, {}
    for id in pairs(self.catalog[Utils1:edition()] or {}) do ids[#ids + 1] = id end
    table.sort(ids)
    for _, id in ipairs(ids) do
        local resolver = (id == "m_AllowCrouchedMovement" or id == "GetColor")
            and self.ResolveExistingPointer or self.Resolve
        local called, state, reason = pcall(resolver, self, id)
        local row = {id = id, status = "failed", reason = tostring(called and reason or state)}
        if called and state then
            row.address = string.format("0x%X", state.address)
            if state.spec.kind == "bytes" then
                local original, readError = self:ReadBytes(state.address, #state.spec.bytes)
                local valid, validationError = false, readError
                if original then
                    if state.applied then valid = self:BytesEqual(original, state.spec.bytes)
                    else valid, validationError = self:ValidateBytes(state.spec, state.scanAddress, state.address, original) end
                    row.bytes = self:BytesHex(original)
                end
                row.status = valid and (state.applied and "active" or "ready") or "failed"
                row.reason = valid and "" or tostring(validationError or "readback_mismatch")
            else
                row.status, row.reason = "resolved", ""
            end
        end
        rows[#rows + 1] = row
    end
    return rows
end

function SovereignRuntimePatchBridge:ReadBytes(address, count)
    if not self:IsAddress(address) or type(count) ~= "number" or count < 1 or count > 64 then
        return nil, "invalid_read"
    end
    local bytes = {}
    local ok, err = pcall(function()
        for index = 0, count - 1 do
            local value = Memory.ReadUByte(address + index)
            if type(value) ~= "number" or value < 0 or value > 255 then error("byte_read_failed") end
            bytes[index + 1] = value
        end
    end)
    return ok and bytes or nil, ok and nil or tostring(err)
end

function SovereignRuntimePatchBridge:BytesEqual(left, right)
    if type(left) ~= "table" or type(right) ~= "table" or #left ~= #right then return false end
    for index = 1, #left do
        if left[index] ~= right[index] then return false end
    end
    return true
end

function SovereignRuntimePatchBridge:BytesHex(bytes)
    local result = {}
    for index, value in ipairs(bytes or {}) do result[index] = string.format("%02X", value) end
    return table.concat(result, " ")
end

function SovereignRuntimePatchBridge:WriteBytes(address, bytes)
    if type(bytes) ~= "table" or #bytes < 1 or #bytes > 8 then return false, "invalid_write_size" end
    local width = #bytes == 1 and 1 or #bytes <= 2 and 2 or #bytes <= 4 and 4 or 8
    local writeBytes = {}
    for index = 1, #bytes do writeBytes[index] = bytes[index] end
    if width > #bytes then
        local adjacent, adjacentError = self:ReadBytes(address + #bytes, width - #bytes)
        if not adjacent then return false, adjacentError end
        for _, value in ipairs(adjacent) do writeBytes[#writeBytes + 1] = value end
    end
    local packed = 0
    for index, value in ipairs(writeBytes) do
        packed = packed | ((value & 0xFF) << ((index - 1) * 8))
    end
    local writer = width == 1 and (Memory.WriteUByte or Memory.WriteByte)
        or width == 2 and Memory.WriteUShort
        or width == 4 and Memory.WriteUInt
        or width == 8 and Memory.WriteLong
    if type(writer) ~= "function" then return false, "atomic_writer_unavailable:" .. tostring(width) end
    local ok, result = pcall(writer, address, packed)
    if not ok or result == false then return false, ok and "atomic_write_rejected" or tostring(result) end
    local current, readError = self:ReadBytes(address, width)
    if not current or not self:BytesEqual(current, writeBytes) then
        return false, readError or "byte_write_readback_mismatch"
    end
    return true
end

function SovereignRuntimePatchBridge:PatternTokens(signature)
    local tokens = {}
    for token in tostring(signature or ""):gmatch("%S+") do
        tokens[#tokens + 1] = (token == "?" or token == "??") and false or tonumber(token, 16)
    end
    return tokens
end

function SovereignRuntimePatchBridge:ValidateBytes(spec, scanAddress, targetAddress, original)
    if self:BytesEqual(original, spec.bytes) then return false, "target_already_modified" end
    if type(spec.original) ~= "table" or #spec.original ~= #spec.bytes then
        return false, "exact_original_unavailable"
    end
    if not self:BytesEqual(original, spec.original) then
        return false, "exact_original_mismatch:expected=" .. self:BytesHex(spec.original)
            .. ";actual=" .. self:BytesHex(original)
    end
    if spec.mode == "jcc" then
        return spec.original[1] == 0x0F and spec.original[2]
                and spec.original[2] >= 0x80 and spec.original[2] <= 0x8F,
            "expected_near_conditional_branch"
    end
    if spec.mode == "immediate_one" then
        return #spec.original == 1 and spec.original[1] == 1, "expected_immediate_one"
    end
    return true
end

function SovereignRuntimePatchBridge:GetSpec(id)
    local edition = Utils1:edition()
    if edition ~= "Enhanced" and edition ~= "Legacy" then return nil, "edition_unresolved" end
    local spec = self.catalog[edition] and self.catalog[edition][id]
    if not spec then return nil, "version_unresolved:" .. tostring(id) end
    return spec
end

function SovereignRuntimePatchBridge:Resolve(id)
    local runtimeOk, identity = self:EnsureRuntime()
    if not runtimeOk then return nil, identity end
    local cached = self.states[id]
    if cached and cached.identity == identity and self:IsAddress(cached.address) then return cached end
    if cached and next(cached.owners or {}) ~= nil then return nil, "module_changed_restore_required" end
    local spec, specError = self:GetSpec(id)
    if not spec then return nil, specError end
    local module = MemoryBridge:GetModuleName()
    local scanOk, scanAddress = pcall(Memory.Scan, spec.signature, module)
    if not scanOk or not self:IsAddress(scanAddress) then return nil, "signature_not_found:" .. tostring(id) end
    local targetAddress = scanAddress
    if spec.rip ~= nil then
        if type(Memory.Rip) ~= "function" then return nil, "rip_unavailable" end
        local ripOk, value = pcall(Memory.Rip, scanAddress + spec.rip)
        if not ripOk or not self:IsAddress(value) then return nil, "rip_failed:" .. tostring(id) end
        targetAddress = value
    end
    targetAddress = targetAddress + (spec.add or 0)
    if not self:IsAddress(targetAddress) then return nil, "target_invalid:" .. tostring(id) end
    local state = {
        id = id, spec = spec, identity = identity, scanAddress = scanAddress,
        address = targetAddress, owners = {}, applied = false,
    }
    self.states[id] = state
    self:Record(id, "resolved", string.format("scan=0x%X target=0x%X", scanAddress, targetAddress))
    return state
end

function SovereignRuntimePatchBridge:ReadScalar(kind, address)
    local reader = kind == "float32" and Memory.ReadFloat or kind == "int32" and Memory.ReadInt or nil
    if type(reader) ~= "function" then return nil, "scalar_reader_unavailable" end
    local ok, value = pcall(reader, address)
    if not ok or type(value) ~= "number" or value ~= value or math.abs(value) == rawget(math, "huge") then
        return nil, "scalar_read_failed"
    end
    return value
end

function SovereignRuntimePatchBridge:WriteScalar(kind, address, value)
    local writer = kind == "float32" and Memory.WriteFloat or kind == "int32" and Memory.WriteInt or nil
    if type(writer) ~= "function" then return false, "scalar_writer_unavailable" end
    local ok, result = pcall(writer, address, value)
    if not ok or result == false then return false, tostring(result) end
    local current, readError = self:ReadScalar(kind, address)
    if current == nil then return false, readError end
    local equal = kind == "float32" and math.abs(current - value) <= math.max(0.0001, math.abs(value) * 0.00001)
        or current == value
    return equal, equal and nil or "scalar_write_readback_mismatch"
end

function SovereignRuntimePatchBridge:ResolveExistingPointer(id)
    local runtimeOk, identity = self:EnsureRuntime()
    if not runtimeOk then return nil, identity end
    local cached = self.states[id]
    -- GetColor is a module-relative global. Avoid scanning the module every
    -- frame when an unrelated event pointer keeps the event bridge unready.
    if id == "GetColor" and cached and cached.identity == identity and self:IsAddress(cached.address) then
        return cached
    end
    local address = MemoryBridge:GetPointer(id)
    if not self:IsAddress(address) then
        if not MemoryBridge:BuildScanDefinitions() then
            return nil, MemoryBridge.mappingError or "mapping_unavailable"
        end
        for _, definition in ipairs(MemoryBridge.scanDefinitions or {}) do
            if definition.name == id then
                local resolved, result = MemoryBridge:Scan(id, definition.sig, definition.rip, definition.resolver)
                if not resolved then return nil, "required_pointer_unresolved:" .. tostring(id) .. ":" .. tostring(result) end
                address = result
                break
            end
        end
    end
    if not self:IsAddress(address) then return nil, "required_pointer_unresolved:" .. tostring(id) end
    local spec, specError = self:GetSpec(id)
    if not spec then return nil, specError end
    local state = self.states[id]
    if state and state.identity == identity and state.address == address then return state end
    if state and (state.applied or next(state.owners or {}) ~= nil) then
        return nil, "module_changed_restore_required"
    end
    state = {id = id, spec = spec, identity = identity, address = address, owners = {}, applied = false}
    self.states[id] = state
    return state
end

function SovereignRuntimePatchBridge:Acquire(id, owner, value)
    local state, resolveError
    if id == "m_AllowCrouchedMovement" or id == "GetColor" then
        state, resolveError = self:ResolveExistingPointer(id)
    else
        state, resolveError = self:Resolve(id)
    end
    if not state then self:Record(id, "failed", resolveError); return false, resolveError end
    if state.owners[owner] then return true end
    local spec = state.spec
    if state.applied then
        if spec.kind == "bytes" then
            local current = self:ReadBytes(state.address, #spec.bytes)
            if not current or not self:BytesEqual(current, spec.bytes) then return false, "shared_patch_conflict" end
        elseif state.value ~= value then
            return false, "shared_scalar_conflict"
        end
        state.owners[owner] = true
        return true
    end
    if spec.kind == "bytes" then
        local original, readError = self:ReadBytes(state.address, #spec.bytes)
        if not original then return false, readError end
        local valid, validationError = self:ValidateBytes(spec, state.scanAddress, state.address, original)
        if not valid then self:Record(id, "failed", validationError); return false, validationError end
        state.original = original
        local written, writeError = self:WriteBytes(state.address, spec.bytes)
        if not written then
            local rollbackOk, rollbackResult, rollbackError = pcall(self.WriteBytes, self, state.address, original)
            if not rollbackOk or rollbackResult ~= true then
                local detail = tostring(writeError) .. ";rollback_failed:"
                    .. tostring(rollbackOk and rollbackError or rollbackResult)
                state.applied, state.value = true, spec.bytes
                state.owners[owner] = true
                self.active[owner] = true
                self.recoveryRequired[owner] = detail
                if not state.ordered then
                    state.ordered = true
                    self.order[#self.order + 1] = id
                end
                self:Record(id, "conflict", detail)
                return false, detail
            end
            self:Record(id, "failed", writeError)
            return false, writeError
        end
        state.value = spec.bytes
        self:Record(id, "applied", "original=" .. self:BytesHex(original))
    elseif spec.kind == "float32" or spec.kind == "int32" then
        if type(value) ~= "number" or value ~= value or math.abs(value) == rawget(math, "huge") then return false, "scalar_value_invalid" end
        local original, readError = self:ReadScalar(spec.kind, state.address)
        if original == nil then return false, readError end
        local expected = self.expectedScalars[id]
        local originalMatches = expected == nil or (spec.kind == "float32"
            and math.abs(original - expected) <= math.max(0.0001, math.abs(expected) * 0.00001)
            or original == expected)
        if not originalMatches then
            self:Record(id, "failed", "original_scalar_mismatch:" .. tostring(original))
            return false, "original_scalar_mismatch"
        end
        state.original = original
        local written, writeError = self:WriteScalar(spec.kind, state.address, value)
        if not written then
            local rollbackOk, rollbackResult, rollbackError =
                pcall(self.WriteScalar, self, spec.kind, state.address, original)
            if not rollbackOk or rollbackResult ~= true then
                local detail = tostring(writeError) .. ";rollback_failed:"
                    .. tostring(rollbackOk and rollbackError or rollbackResult)
                state.applied, state.value = true, value
                state.owners[owner] = true
                self.active[owner] = true
                self.recoveryRequired[owner] = detail
                if not state.ordered then
                    state.ordered = true
                    self.order[#self.order + 1] = id
                end
                self:Record(id, "conflict", detail)
                return false, detail
            end
            self:Record(id, "failed", writeError)
            return false, writeError
        end
        state.value = value
        self:Record(id, "applied", "original=" .. tostring(original))
    else
        return false, "unsupported_patch_kind:" .. tostring(spec.kind)
    end
    state.applied = true
    state.owners[owner] = true
    if not state.ordered then
        state.ordered = true
        self.order[#self.order + 1] = id
    end
    return true
end

function SovereignRuntimePatchBridge:Release(id, owner)
    local state = self.states[id]
    if not state or not state.owners[owner] then return true end
    state.owners[owner] = nil
    if next(state.owners) ~= nil then return true end
    if not state.applied then return true end
    local identity, identityError = self:Identity()
    if identity ~= state.identity then
        state.owners[owner] = true
        self:Record(id, "conflict", identityError or "module_changed")
        return false, identityError or "module_changed"
    end
    local spec = state.spec
    if spec.kind == "bytes" then
        local current, readError = self:ReadBytes(state.address, #spec.bytes)
        if not current then state.owners[owner] = true; return false, readError end
        if not self:BytesEqual(current, spec.bytes) and not self:BytesEqual(current, state.original) then
            state.owners[owner] = true
            self:Record(id, "conflict", "external_bytes_changed")
            return false, "external_bytes_changed"
        end
        if self:BytesEqual(current, spec.bytes) then
            local restored, restoreError = self:WriteBytes(state.address, state.original)
            if not restored then state.owners[owner] = true; return false, restoreError end
        end
    else
        local current, readError = self:ReadScalar(spec.kind, state.address)
        if current == nil then state.owners[owner] = true; return false, readError end
        local valueEqual = spec.kind == "float32"
            and math.abs(current - state.value) <= math.max(0.0001, math.abs(state.value) * 0.00001)
            or current == state.value
        local originalEqual = spec.kind == "float32"
            and math.abs(current - state.original) <= math.max(0.0001, math.abs(state.original) * 0.00001)
            or current == state.original
        if not valueEqual and not originalEqual then
            state.owners[owner] = true
            self:Record(id, "conflict", "external_scalar_changed")
            return false, "external_scalar_changed"
        end
        if valueEqual then
            local restored, restoreError = self:WriteScalar(spec.kind, state.address, state.original)
            if not restored then state.owners[owner] = true; return false, restoreError end
        end
    end
    state.applied, state.value, state.original = false, nil, nil
    self:Record(id, "restored")
    return true
end

function SovereignRuntimePatchBridge:SetEnabled(featureId, enabled)
    local definition = self.features[featureId]
    if not definition then return false, "feature_unresolved:" .. tostring(featureId) end
    if enabled == true and self.active[featureId] then
        local recoveryError = self.recoveryRequired[featureId]
        return recoveryError == nil, recoveryError
    end
    if enabled ~= true and not self.active[featureId] then return true end
    if enabled == true then
        local acquired = {}
        for _, entry in ipairs(definition) do
            local id = type(entry) == "table" and entry.id or entry
            local value = type(entry) == "table" and entry.value or nil
            local ok, reason = self:Acquire(id, featureId, value)
            if not ok then
                local rollbackFailures = {}
                for index = #acquired, 1, -1 do
                    local rollbackOk, rollbackError = self:Release(acquired[index], featureId)
                    if not rollbackOk then
                        rollbackFailures[#rollbackFailures + 1] = acquired[index] .. ":" .. tostring(rollbackError)
                    end
                end
                if #rollbackFailures > 0 then
                    self.active[featureId] = true
                    local detail = tostring(reason) .. ";rollback_failed:" .. table.concat(rollbackFailures, ",")
                    self.recoveryRequired[featureId] = detail
                    self:Record(featureId, "conflict", detail)
                    return false, detail
                end
                self:Record(featureId, "failed", reason)
                return false, reason
            end
            acquired[#acquired + 1] = id
        end
        self.active[featureId] = true
        self:Record(featureId, "enabled")
        return true
    end
    local success, reason = true, nil
    for index = #definition, 1, -1 do
        local entry = definition[index]
        local id = type(entry) == "table" and entry.id or entry
        local ok, releaseError = self:Release(id, featureId)
        if not ok then success, reason = false, releaseError end
    end
    if success then
        self.active[featureId] = nil
        self.recoveryRequired[featureId] = nil
        self:Record(featureId, "disabled")
    end
    return success, reason
end

function SovereignRuntimePatchBridge:IsEnabled(featureId)
    return self.active[featureId] == true
end

function SovereignRuntimePatchBridge:Refresh()
    local hasApplied = self.worldColorActive
    if not hasApplied then
        for _, state in pairs(self.states) do
            if state.applied then hasApplied = true; break end
        end
    end
    if not hasApplied then return end
    local currentIdentity = self:Identity()
    for id, state in pairs(self.states) do
        if state.applied then
            local matches = true
            if currentIdentity ~= state.identity then
                matches = false
            elseif state.spec.kind == "bytes" then
                local current = self:ReadBytes(state.address, #state.spec.bytes)
                matches = current ~= nil and self:BytesEqual(current, state.spec.bytes)
            elseif state.spec.kind == "float32" or state.spec.kind == "int32" then
                local current = self:ReadScalar(state.spec.kind, state.address)
                matches = current ~= nil and (state.spec.kind == "float32"
                    and math.abs(current - state.value) <= math.max(0.0001, math.abs(state.value) * 0.00001)
                    or current == state.value)
            end
            if not matches and not state.conflictRecorded then
                state.conflictRecorded = true
                self:Record(id, "conflict", currentIdentity ~= state.identity
                    and "module_identity_changed" or "runtime_readback_changed")
            elseif matches then
                state.conflictRecorded = nil
            end
        end
    end
    if self.worldColorActive then
        local state = self.states.GetColor
        local identityMatches = state and currentIdentity == state.identity
        local current = identityMatches and self:ReadFloatVector(state.address) or nil
        local matches = current ~= nil and self:VectorEqual(current, state.value)
        if state and not matches and not state.conflictRecorded then
            state.conflictRecorded = true
            self:Record("GetColor", "conflict", identityMatches
                and "runtime_readback_changed" or "module_identity_changed")
        elseif state and matches then
            state.conflictRecorded = nil
        end
    end
end

function SovereignRuntimePatchBridge:RestoreAll()
    local success = true
    local enabled = {}
    for id in pairs(self.active) do enabled[#enabled + 1] = id end
    table.sort(enabled)
    for index = #enabled, 1, -1 do
        local ok, restored = pcall(self.SetEnabled, self, enabled[index], false)
        if not ok or restored ~= true then success = false end
    end
    local colorOk, colorRestored = pcall(self.SetWorldColorEnabled, self, false)
    if not colorOk or colorRestored ~= true then success = false end
    return success
end

function SovereignRuntimePatchBridge:ReadNatType(force)
    local now = os.clock()
    if not force and now - (self.natType.updated or 0) < 30 then return self.natType.value end
    local state, resolveError = self:Resolve("GetNatType")
    if not state then self.natType.value, self.natType.updated = "Unresolved", now; return nil, resolveError end
    if not Memory or type(Memory.LuaCallCFunctionWithReturnValue) ~= "function" then
        return nil, "return_call_api_unavailable"
    end
    local ok, resultAddress = pcall(Memory.LuaCallCFunctionWithReturnValue, state.address)
    if not ok or not self:IsAddress(resultAddress) then return nil, "nat_call_failed" end
    local readOk, value = pcall(Memory.ReadInt, resultAddress)
    if type(Memory.Free) == "function" then pcall(Memory.Free, resultAddress) end
    if not readOk or type(value) ~= "number" then return nil, "nat_read_failed" end
    local names = {[0] = "Unknown", [1] = "Open", [2] = "Moderate", [3] = "Strict"}
    self.natType.value, self.natType.updated = names[value] or ("Unknown (" .. tostring(value) .. ")"), now
    return self.natType.value
end

function SovereignRuntimePatchBridge:ReadFloatVector(address)
    local values = {}
    for index = 0, 3 do
        local value, readError = self:ReadScalar("float32", address + index * 4)
        if value == nil then return nil, readError end
        values[index + 1] = value
    end
    return values
end

function SovereignRuntimePatchBridge:WriteFloatVector(address, values)
    for index = 0, 3 do
        local ok, reason = self:WriteScalar("float32", address + index * 4, values[index + 1])
        if not ok then return false, reason end
    end
    return true
end

function SovereignRuntimePatchBridge:VectorEqual(left, right)
    if type(left) ~= "table" or type(right) ~= "table" then return false end
    for index = 1, 4 do
        if type(left[index]) ~= "number" or type(right[index]) ~= "number"
            or math.abs(left[index] - right[index]) > math.max(0.001, math.abs(right[index]) * 0.00001) then
            return false
        end
    end
    return true
end

function SovereignRuntimePatchBridge:SetWorldColor(red, green, blue)
    self.worldColor = {
        math.max(0, math.min(255, tonumber(red) or 255)),
        math.max(0, math.min(255, tonumber(green) or 255)),
        math.max(0, math.min(255, tonumber(blue) or 255)),
        255.0,
    }
    if not self.worldColorActive then return true end
    local state = self.states.GetColor
    if not state or not self:IsAddress(state.address) then return false, "world_color_unresolved" end
    local identity, identityError = self:Identity()
    if identity ~= state.identity then
        self:Record("GetColor", "conflict", identityError or "module_identity_changed")
        return false, identityError or "module_identity_changed"
    end
    local before, readError = self:ReadFloatVector(state.address)
    if not before then return false, readError end
    if not self:VectorEqual(before, state.value) then return false, "external_vector_changed" end
    local ok, reason = self:WriteFloatVector(state.address, self.worldColor)
    if not ok then
        local rollbackOk, rollbackResult, rollbackError =
            pcall(self.WriteFloatVector, self, state.address, before)
        if not rollbackOk or rollbackResult ~= true then
            local detail = tostring(reason) .. ";rollback_failed:"
                .. tostring(rollbackOk and rollbackError or rollbackResult)
            self:Record("GetColor", "conflict", detail)
            return false, detail
        end
        return false, reason
    end
    state.value = {table.unpack(self.worldColor)}
    return true
end

function SovereignRuntimePatchBridge:SetWorldColorEnabled(enabled)
    if enabled == true and self.worldColorActive then return true end
    if enabled ~= true and not self.worldColorActive then return true end
    if enabled == true then
        local state, resolveError = self:ResolveExistingPointer("GetColor")
        if not state then return false, resolveError end
        local original, readError = self:ReadFloatVector(state.address)
        if not original then return false, readError end
        for _, value in ipairs(original) do
            if value < 0.0 or value > 255.0 then return false, "world_color_original_out_of_range" end
        end
        state.original = original
        self.worldColor = self.worldColor or {255.0, 64.0, 32.0, 255.0}
        local ok, reason = self:WriteFloatVector(state.address, self.worldColor)
        if not ok then
            local rollbackOk, rollbackResult, rollbackError =
                pcall(self.WriteFloatVector, self, state.address, original)
            if not rollbackOk or rollbackResult ~= true then
                local detail = tostring(reason) .. ";rollback_failed:"
                    .. tostring(rollbackOk and rollbackError or rollbackResult)
                state.value = {table.unpack(self.worldColor)}
                self.worldColorActive = true
                self:Record("GetColor", "conflict", detail)
                return false, detail
            end
            state.original = nil
            return false, reason
        end
        state.value = {table.unpack(self.worldColor)}
        self.worldColorActive = true
        self:Record("GetColor", "applied", "original=" .. table.concat(original, ","))
        return true
    end
    local state = self.states.GetColor
    if not state or not state.original then self.worldColorActive = false; return true end
    local identity, identityError = self:Identity()
    if identity ~= state.identity then
        self:Record("GetColor", "conflict", identityError or "module_identity_changed")
        return false, identityError or "module_identity_changed"
    end
    local current, readError = self:ReadFloatVector(state.address)
    if not current then return false, readError end
    if not self:VectorEqual(current, state.value) and not self:VectorEqual(current, state.original) then
        self:Record("GetColor", "conflict", "external_vector_changed")
        return false, "external_vector_changed"
    end
    if self:VectorEqual(current, state.value) then
        local ok, reason = self:WriteFloatVector(state.address, state.original)
        if not ok then return false, reason end
    end
    state.original, state.value = nil, nil
    self.worldColorActive = false
    self:Record("GetColor", "restored")
    return true
end

