function WeaponManager:ProcessWeaponFeatures(playerId)
    if not self.lastShotTime[playerId] then
        self.lastShotTime[playerId] = 0
    end
    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if self.noReload[playerId] then
        local weapon = menu.nativeApis.WEAPON.GET_SELECTED_PED_WEAPON(ped)
        if weapon and weapon ~= 0 then
            menu.nativeApis.WEAPON.SET_PED_AMMO(ped, weapon, 9999, true)
        end
    end
    if self.rapidFire[playerId] then
        local weapon = menu.nativeApis.WEAPON.GET_SELECTED_PED_WEAPON(ped)
        if weapon and weapon ~= 0 then
            local time = menu.nativeApis.MISC.GET_GAME_TIMER()
            if time - self.lastShotTime[playerId] > 50 then
                if menu.nativeApis.PLAYER.IS_PLAYER_FREE_AIMING(playerId) then
                    local camRot = menu.nativeApis.CAM.GET_GAMEPLAY_CAM_ROT(2)
                    local camPos = menu.nativeApis.CAM.GET_GAMEPLAY_CAM_COORD()
                    local direction = V3.New(
                        -math.sin(math.rad(camRot.z)) * math.cos(math.rad(camRot.x)),
                        math.cos(math.rad(camRot.z)) * math.cos(math.rad(camRot.x)),
                        math.sin(math.rad(camRot.x))
                    )
                    local targetPos = V3.New(camPos.x + direction.x * 1000,camPos.y + direction.y * 1000,camPos.z + direction.z * 1000)
                    menu.nativeApis.MISC.SHOOT_SINGLE_BULLET_BETWEEN_COORDS(camPos.x, camPos.y, camPos.z,targetPos.x, targetPos.y, targetPos.z,100, true, weapon, ped, true, false, 1000)
                    self.lastShotTime[playerId] = time
                end
            end
        end
    end
end

