SelfOptions.ProcessSelfOptions = LPH_NO_VIRTUALIZE(function(self, playerId)
    if not (self.neverWanted[playerId] or self.superJump[playerId] or self.superPunch[playerId]
        or self.autoHeal[playerId] or self.autoArmor[playerId] or self.antiAFK[playerId]
        or self.infiniteBreath[playerId] or self.infiniteStamina[playerId] or self.noClip[playerId]) then
        return
    end
    return self:_ProcessSelfOptionsActive(playerId)
end)

function SelfOptions:_ProcessSelfOptionsActive(playerId)
    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if not ped or ped == 0 then return end
    if self.neverWanted[playerId] then
        if menu.nativeApis.PLAYER.GET_PLAYER_WANTED_LEVEL(playerId) > 0 then
            menu.nativeApis.PLAYER.SET_PLAYER_WANTED_LEVEL(playerId, 0, false)
            menu.nativeApis.PLAYER.SET_PLAYER_WANTED_LEVEL_NOW(playerId, false)
        end
    end
    if self.superJump[playerId] then
        menu.nativeApis.MISC.SET_SUPER_JUMP_THIS_FRAME(playerId)
    end
    if self.superPunch[playerId] then
        menu.nativeApis.MISC.SET_EXPLOSIVE_MELEE_THIS_FRAME(playerId)
    end
    if self.autoHeal[playerId] then
        local health = menu.nativeApis.ENTITY.GET_ENTITY_HEALTH(ped)
        local maxHealth = menu.nativeApis.ENTITY.GET_ENTITY_MAX_HEALTH(ped)
        if health < maxHealth then
            menu.nativeApis.ENTITY.SET_ENTITY_HEALTH(ped, math.min(health + 5, maxHealth), 0, 5)
        end
    end
    if self.autoArmor[playerId] then
        local armor = menu.nativeApis.PED.GET_PED_ARMOUR(ped)
        if armor < 100 then
            menu.nativeApis.PED.SET_PED_ARMOUR(ped, math.min(armor + 5, 100))
        end
    end
    if self.antiAFK[playerId] then
        local time = menu.nativeApis.MISC.GET_GAME_TIMER()
        if not self.lastActivityTime[playerId] then
            self.lastActivityTime[playerId] = time
        end
        if time - self.lastActivityTime[playerId] > 120000 then
            menu.nativeApis.PAD.SET_CONTROL_SHAKE(0, 100, 50)
            self.lastActivityTime[playerId] = time
        end
    end
    if self.infiniteBreath[playerId] then
        menu.nativeApis.PLAYER.SET_PLAYER_UNDERWATER_BREATH_PERCENT_REMAINING(playerId, 100.0)
    end
    if self.infiniteStamina[playerId] then
        menu.nativeApis.PLAYER.RESTORE_PLAYER_STAMINA(playerId, 100.0)
    end
    if self.noClip[playerId] then
        self:ProcessNoClipMovement(playerId)
    end
end

function SelfOptions:ProcessNoClipMovement(playerId)
    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    menu.nativeApis.ENTITY.FREEZE_ENTITY_POSITION(ped, true)
    if not ped or ped == 0 then return end
    local speed = self.noClipSpeed[playerId] or 1.0
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(ped, true)
    local rot = menu.nativeApis.CAM.GET_GAMEPLAY_CAM_ROT(2)
    local forward = V3.New(
        -math.sin(math.rad(rot.z)) * math.cos(math.rad(rot.x)),
        math.cos(math.rad(rot.z)) * math.cos(math.rad(rot.x)),
        math.sin(math.rad(rot.x))
    )
    local right = V3.New(
        math.sin(math.rad(rot.z - 90)),
        math.cos(math.rad(rot.z - 90)),
        0
    )
    if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 32) then -- W
        pos.x = pos.x + forward.x * speed
        pos.y = pos.y + forward.y * speed
        pos.z = pos.z + forward.z * speed
    end
    if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 33) then -- S
        pos.x = pos.x - forward.x * speed
        pos.y = pos.y - forward.y * speed
        pos.z = pos.z - forward.z * speed
    end
    if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 34) then -- A
        pos.x = pos.x - right.x * speed
        pos.y = pos.y - right.y * speed
    end
    if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 35) then -- D
        pos.x = pos.x + right.x * speed
        pos.y = pos.y + right.y * speed
    end
    if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 22) then -- Space
        pos.z = pos.z + speed
    end
    if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 36) then -- Ctrl
        pos.z = pos.z - speed
    end
    menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET(ped, pos.x, pos.y, pos.z, false, false, false)
    menu.nativeApis.ENTITY.SET_ENTITY_ROTATION(ped, 0, 0, rot.z, 2, true)
end

function SelfOptions:SetNoClipSpeed(playerId, speed)
    self.noClipSpeed[playerId] = speed
end

