function VehicleOptions:IsVehicleValid(vehicle)
    if not vehicle or vehicle == 0 then return false end
    if not menu.nativeApis.ENTITY or type(menu.nativeApis.ENTITY.DOES_ENTITY_EXIST) ~= "function" then return true end
    local ok, exists = pcall(menu.nativeApis.ENTITY.DOES_ENTITY_EXIST, vehicle)
    return ok and exists == true
end

function VehicleOptions:GetPlayerVehicle(playerId)
    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if not ped or ped == 0 then return 0, ped end
    local vehicle = menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false)
    return self:IsVehicleValid(vehicle) and vehicle or 0, ped
end

function VehicleOptions:GetAppliedOverrides(playerId, vehicle, create)
    if not self:IsVehicleValid(vehicle) then return nil end
    local playerOverrides = self.appliedOverrides[playerId]
    if not playerOverrides and create then
        playerOverrides = {}
        self.appliedOverrides[playerId] = playerOverrides
    end
    if not playerOverrides then return nil end
    local overrides = playerOverrides[vehicle]
    if not overrides and create then
        overrides = {}
        playerOverrides[vehicle] = overrides
    end
    return overrides
end

function VehicleOptions:MarkAppliedOverride(playerId, vehicle, name)
    local overrides = self:GetAppliedOverrides(playerId, vehicle, true)
    if not overrides or overrides[name] == true then return end
    local function readBoolean(fn, fallback)
        if type(fn) == "function" then
            local ok, value = pcall(fn, vehicle)
            if ok and type(value) == "boolean" then return value end
        end
        return fallback
    end
    overrides[name] = true
    if name == "fly" then
        overrides.originalGravity = readBoolean(menu.nativeApis.ENTITY and menu.nativeApis.ENTITY.GET_ENTITY_HAS_GRAVITY, true)
    elseif name == "noCollision" then
        overrides.originalCollisionDisabled = readBoolean(menu.nativeApis.ENTITY and menu.nativeApis.ENTITY.GET_ENTITY_COLLISION_DISABLED, false)
    elseif name == "invisible" then
        overrides.originalVisible = readBoolean(menu.nativeApis.ENTITY and menu.nativeApis.ENTITY.IS_ENTITY_VISIBLE, true)
    elseif name == "god" then
        overrides.originalCanBeDamaged = readBoolean(menu.nativeApis.ENTITY and menu.nativeApis.ENTITY.GET_ENTITY_CAN_BE_DAMAGED, true)
    end
end

function VehicleOptions:RestoreAppliedOverride(playerId, vehicle, name)
    local playerOverrides = self.appliedOverrides[playerId]
    if not self:IsVehicleValid(vehicle) then
        if playerOverrides and vehicle then
            playerOverrides[vehicle] = nil
            if next(playerOverrides) == nil then self.appliedOverrides[playerId] = nil end
        end
        return false
    end
    local overrides = playerOverrides and playerOverrides[vehicle]
    if not overrides or overrides[name] ~= true then return false end
    if name == "fly" then
        local gravity = overrides.originalGravity ~= false
        pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_GRAVITY, vehicle, gravity)
        if menu.nativeApis.ENTITY and type(menu.nativeApis.ENTITY.SET_ENTITY_HAS_GRAVITY) == "function" then
            pcall(menu.nativeApis.ENTITY.SET_ENTITY_HAS_GRAVITY, vehicle, gravity)
        end
        overrides.originalGravity = nil
    elseif name == "noCollision" then
        pcall(menu.nativeApis.ENTITY.SET_ENTITY_COLLISION, vehicle, overrides.originalCollisionDisabled ~= true, true)
        overrides.originalCollisionDisabled = nil
    elseif name == "invisible" then
        pcall(menu.nativeApis.ENTITY.SET_ENTITY_VISIBLE, vehicle, overrides.originalVisible ~= false, false)
        overrides.originalVisible = nil
    elseif name == "god" then
        local canBeDamaged = overrides.originalCanBeDamaged ~= false
        pcall(menu.nativeApis.ENTITY.SET_ENTITY_INVINCIBLE, vehicle, not canBeDamaged)
        if canBeDamaged then
            pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_CAN_BE_VISIBLY_DAMAGED, vehicle, true)
            pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_CAN_BREAK, vehicle, true)
        end
        overrides.originalCanBeDamaged = nil
    elseif name == "keepEngine" then
        if type(menu.nativeApis.VEHICLE.SET_VEHICLE_KEEP_ENGINE_ON_WHEN_ABANDONED) == "function" then
            pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_KEEP_ENGINE_ON_WHEN_ABANDONED, vehicle, false)
        end
    end
    overrides[name] = nil
    if next(overrides) == nil then
        playerOverrides[vehicle] = nil
        if next(playerOverrides) == nil then self.appliedOverrides[playerId] = nil end
    end
    return true
end

function VehicleOptions:RestoreContinuousOverrides(playerId, vehicle)
    if not self:IsVehicleValid(vehicle) then return end
    for _, name in ipairs({"fly", "noCollision", "invisible", "god", "keepEngine"}) do
        self:RestoreAppliedOverride(playerId, vehicle, name)
    end
end

function VehicleOptions:ApplyContinuousOverrides(playerId, vehicle)
    if not self:IsVehicleValid(vehicle) then return end
    if self.godMode[playerId] then
        self:MarkAppliedOverride(playerId, vehicle, "god")
        pcall(menu.nativeApis.ENTITY.SET_ENTITY_INVINCIBLE, vehicle, true)
        pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_CAN_BE_VISIBLY_DAMAGED, vehicle, false)
        pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_CAN_BREAK, vehicle, false)
    end
    if self.invisible[playerId] then
        self:MarkAppliedOverride(playerId, vehicle, "invisible")
        pcall(menu.nativeApis.ENTITY.SET_ENTITY_VISIBLE, vehicle, false, false)
    end
    if self.noCollision[playerId] then
        self:MarkAppliedOverride(playerId, vehicle, "noCollision")
        pcall(menu.nativeApis.ENTITY.SET_ENTITY_COLLISION, vehicle, false, true)
    end
    if self.flyMode[playerId] then
        self:MarkAppliedOverride(playerId, vehicle, "fly")
        pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_GRAVITY, vehicle, false)
        if menu.nativeApis.ENTITY and type(menu.nativeApis.ENTITY.SET_ENTITY_HAS_GRAVITY) == "function" then
            pcall(menu.nativeApis.ENTITY.SET_ENTITY_HAS_GRAVITY, vehicle, false)
        end
        self.flyVehicle[playerId] = vehicle
    end
    if self.keepEngine[playerId] and type(menu.nativeApis.VEHICLE.SET_VEHICLE_KEEP_ENGINE_ON_WHEN_ABANDONED) == "function" then
        self:MarkAppliedOverride(playerId, vehicle, "keepEngine")
        pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_KEEP_ENGINE_ON_WHEN_ABANDONED, vehicle, true)
        self.keepEngineVehicle[playerId] = vehicle
    end
end

function VehicleOptions:RestoreDriftOverride(vehicle)
    if not self:IsVehicleValid(vehicle) then
        if vehicle ~= nil then self.driftOriginal[vehicle] = nil end
        return false
    end
    if menu.nativeApis.VEHICLE and type(menu.nativeApis.VEHICLE.SET_DRIFT_TYRES) == "function" then
        local original = self.driftOriginal[vehicle]
        local ok = pcall(menu.nativeApis.VEHICLE.SET_DRIFT_TYRES, vehicle, original == 1)
        self.driftOriginal[vehicle] = nil
        return ok
    end
    local gripOk = pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_REDUCE_GRIP, vehicle, false)
    local levelOk = pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_REDUCE_GRIP_LEVEL, vehicle, 1.0)
    self.driftOriginal[vehicle] = nil
    return gripOk and levelOk
end

function VehicleOptions:ResetContinuous(playerId)
    local vehicles, seen = {}, {}
    local function addVehicle(vehicle)
        if self:IsVehicleValid(vehicle) and not seen[vehicle] then
            seen[vehicle] = true
            vehicles[#vehicles + 1] = vehicle
        end
    end
    addVehicle(self.lastVehicle[playerId])
    addVehicle(self.flyVehicle[playerId])
    addVehicle(self.driftVehicle[playerId])
    addVehicle(self.keepEngineVehicle[playerId])
    local playerOverrides = self.appliedOverrides[playerId]
    for vehicle in pairs(playerOverrides or {}) do addVehicle(vehicle) end
    local currentVehicle, ped = self:GetPlayerVehicle(playerId)
    addVehicle(currentVehicle)
    for _, vehicle in ipairs(vehicles) do
        self:RestoreContinuousOverrides(playerId, vehicle)
    end
    self:RestoreDriftOverride(self.driftVehicle[playerId])
    local seatbeltPed = self.seatbeltPed[playerId] or ped
    if self.seatbeltApplied[playerId] and seatbeltPed and seatbeltPed ~= 0 then
        pcall(menu.nativeApis.PED.SET_PED_CAN_BE_KNOCKED_OFF_VEHICLE, seatbeltPed, 0)
    end
    local stateTables = {
        self.godMode, self.invisible, self.autoRepair, self.speedBoost, self.jump,
        self.instantStop, self.noCollision, self.driveOnWater, self.flyMode,
        self.hornBoost, self.driftMode, self.autoFlip, self.seatbelt, self.keepEngine
    }
    for _, state in ipairs(stateTables) do state[playerId] = false end
    self.appliedOverrides[playerId] = nil
    self.seatbeltApplied[playerId] = false
    self.seatbeltPed[playerId] = nil
    self.flyVehicle[playerId] = nil
    self.driftVehicle[playerId] = nil
    self.keepEngineVehicle[playerId] = nil
    self.lastVehicle[playerId] = nil
    self.driftApplied[playerId] = false
    self.driftModeLast[playerId] = 0
end

function VehicleOptions:Cleanup(playerId)
    self:ResetContinuous(playerId)
    local stateTables = {
        self.autoPilot, self.rainbowColor, self.neonLights, self.xenonLights,
        self.turbo, self.bulletproofTires, self.customHandling, self.infiniteBoost,
        self.cleanOnExit
    }
    for _, state in ipairs(stateTables) do state[playerId] = false end
    if self.waterHeightPtr and self.waterHeightPtr ~= 0 and Memory and type(Memory.Free) == "function" then
        pcall(Memory.Free, self.waterHeightPtr)
        self.waterHeightPtr = 0
    end
end

function VehicleOptions:RepairAllTires(playerId)
    local vehicle = self:GetPlayerVehicle(playerId)
    if vehicle == 0 or type(menu.nativeApis.VEHICLE.SET_VEHICLE_TYRE_FIXED) ~= "function" then return false end
    for tireIndex = 0, 7 do pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_TYRE_FIXED, vehicle, tireIndex) end
    return true
end

function VehicleOptions:SetDoorsOpen(playerId, open)
    local vehicle = self:GetPlayerVehicle(playerId)
    if vehicle == 0 then return false end
    if open then
        if type(menu.nativeApis.VEHICLE.SET_VEHICLE_DOOR_OPEN) ~= "function" then return false end
        for doorIndex = 0, 7 do pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_DOOR_OPEN, vehicle, doorIndex, false, false) end
    else
        if type(menu.nativeApis.VEHICLE.SET_VEHICLE_DOORS_SHUT) ~= "function" then return false end
        pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_DOORS_SHUT, vehicle, false)
    end
    return true
end

function VehicleOptions:ToggleGodMode(playerId, enabled)
    self.godMode[playerId] = enabled == nil and not (self.godMode[playerId] or false) or enabled == true
    local vehicle = self:GetPlayerVehicle(playerId)
    if vehicle == 0 then vehicle = self.lastVehicle[playerId] or 0 end
    if self.godMode[playerId] then
        self:ApplyContinuousOverrides(playerId, vehicle)
    else
        self:RestoreAppliedOverride(playerId, vehicle, "god")
    end
end

function VehicleOptions:ToggleInvisible(playerId, enabled)
    self.invisible[playerId] = enabled == nil and not (self.invisible[playerId] or false) or enabled == true
    local vehicle = self:GetPlayerVehicle(playerId)
    if vehicle == 0 then vehicle = self.lastVehicle[playerId] or 0 end
    if self.invisible[playerId] then
        self:ApplyContinuousOverrides(playerId, vehicle)
    else
        self:RestoreAppliedOverride(playerId, vehicle, "invisible")
    end
end

function VehicleOptions:ToggleAutoRepair(playerId, enabled)
    self.autoRepair[playerId] = enabled == nil and not (self.autoRepair[playerId] or false) or enabled == true
end

function VehicleOptions:ToggleSpeedBoost(playerId, enabled)
    self.speedBoost[playerId] = enabled == nil and not (self.speedBoost[playerId] or false) or enabled == true
end

function VehicleOptions:SetBoostPower(playerId, power)
    self.boostPower[playerId] = math.max(0.5, math.min(10.0, tonumber(power) or 2.5))
end

function VehicleOptions:GetWaterSurfaceHeight(position)
    if not position or not menu.nativeApis.WATER or type(menu.nativeApis.WATER.GET_WATER_HEIGHT_NO_WAVES) ~= "function"
        or not Memory or type(Memory.Alloc) ~= "function" or type(Memory.ReadFloat) ~= "function" then
        return nil
    end
    if not self.waterHeightPtr or self.waterHeightPtr == 0 then
        local ok, ptr = pcall(Memory.Alloc, 4)
        if not ok or not ptr or ptr == 0 then return nil end
        self.waterHeightPtr = ptr
    end
    local ok, found = pcall(
        menu.nativeApis.WATER.GET_WATER_HEIGHT_NO_WAVES,
        position.x, position.y, position.z + 3.0, self.waterHeightPtr
    )
    if not ok or found ~= true then return nil end
    local readOk, height = pcall(Memory.ReadFloat, self.waterHeightPtr)
    if not readOk or type(height) ~= "number" or height ~= height then return nil end
    return height
end

function VehicleOptions:ToggleJump(playerId, enabled)
    self.jump[playerId] = enabled == nil and not (self.jump[playerId] or false) or enabled == true
end

function VehicleOptions:ToggleStickToGround(playerId)
    self.stickToGround[playerId] = not (self.stickToGround[playerId] or false)
end

function VehicleOptions:ToggleInstantStop(playerId, enabled)
    self.instantStop[playerId] = enabled == nil and not (self.instantStop[playerId] or false) or enabled == true
end

function VehicleOptions:ToggleNoCollision(playerId, enabled)
    self.noCollision[playerId] = enabled == nil and not (self.noCollision[playerId] or false) or enabled == true
    local vehicle = self:GetPlayerVehicle(playerId)
    if vehicle == 0 then vehicle = self.lastVehicle[playerId] or 0 end
    if self.noCollision[playerId] then
        self:ApplyContinuousOverrides(playerId, vehicle)
    else
        self:RestoreAppliedOverride(playerId, vehicle, "noCollision")
    end
end

function VehicleOptions:ToggleDriveOnWater(playerId, enabled)
    self.driveOnWater[playerId] = enabled == nil and not (self.driveOnWater[playerId] or false) or enabled == true
