function VehicleOptions:ToggleFlyMode(playerId, enabled)
    local nextState = enabled == nil and not (self.flyMode[playerId] or false) or enabled == true
    if not nextState then
        self:RestoreAppliedOverride(playerId, self.flyVehicle[playerId], "fly")
        self.flyVehicle[playerId] = nil
    end
    self.flyMode[playerId] = nextState
    local vehicle = self:GetPlayerVehicle(playerId)
    if nextState and vehicle ~= 0 then self:ApplyContinuousOverrides(playerId, vehicle) end
end

function VehicleOptions:SetFlySpeed(playerId, speed)
    self.flySpeed[playerId] = math.max(10.0, math.min(120.0, tonumber(speed) or 45.0))
