end

function VehicleOptions:SetKeepEngine(playerId, enabled)
    local nextState = enabled == true
    if not nextState then
        local oldVehicle = self.keepEngineVehicle[playerId]
        self:RestoreAppliedOverride(playerId, oldVehicle, "keepEngine")
        self.keepEngineVehicle[playerId] = nil
    end
    self.keepEngine[playerId] = nextState
    local vehicle = self:GetPlayerVehicle(playerId)
    if nextState and vehicle ~= 0 then self:ApplyContinuousOverrides(playerId, vehicle) end
end

