    if not self.driftMode[playerId] then
        self.driftModeLast[playerId] = 0
        local appliedVehicle = self.driftVehicle[playerId]
        self:RestoreDriftOverride(appliedVehicle)
        self.driftVehicle[playerId] = nil
        self.driftApplied[playerId] = false
    end
end

