    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if ped and ped ~= 0 then
        if self.seatbelt[playerId] then
            menu.nativeApis.PED.SET_PED_CAN_BE_KNOCKED_OFF_VEHICLE(ped, 1)
            self.seatbeltApplied[playerId] = true
            self.seatbeltPed[playerId] = ped
        elseif self.seatbeltApplied[playerId] then
            menu.nativeApis.PED.SET_PED_CAN_BE_KNOCKED_OFF_VEHICLE(self.seatbeltPed[playerId] or ped, 0)
            self.seatbeltApplied[playerId] = false
            self.seatbeltPed[playerId] = nil
        end
    end
end

