function VehicleOptions:MaxUpgrade(playerId)
    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if ped and ped ~= 0 then
        local veh = menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if veh and veh ~= 0 then
            menu.nativeApis.VEHICLE.TOGGLE_VEHICLE_MOD(veh, 18, true) -- Turbo tuning
            menu.nativeApis.VEHICLE.SET_VEHICLE_MOD(veh, 11, menu.nativeApis.VEHICLE.GET_NUM_VEHICLE_MODS(veh, 11) - 1, false) -- Engine
            menu.nativeApis.VEHICLE.SET_VEHICLE_MOD(veh, 12, menu.nativeApis.VEHICLE.GET_NUM_VEHICLE_MODS(veh, 12) - 1, false) -- Brakes
            menu.nativeApis.VEHICLE.SET_VEHICLE_MOD(veh, 13, menu.nativeApis.VEHICLE.GET_NUM_VEHICLE_MODS(veh, 13) - 1, false) -- Transmission
            menu.nativeApis.VEHICLE.SET_VEHICLE_MOD(veh, 15, menu.nativeApis.VEHICLE.GET_NUM_VEHICLE_MODS(veh, 15) - 1, false) -- Suspension
            menu.nativeApis.VEHICLE.SET_VEHICLE_MOD(veh, 16, menu.nativeApis.VEHICLE.GET_NUM_VEHICLE_MODS(veh, 16) - 1, false) -- Armor
            Logger:Toast("Vehicle options", "Vehicle fully upgraded", CONFIG.UI.ToastDuration.Short)
        end
    end
end

function VehicleOptions:RandomUpgrade(playerId)
    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if ped and ped ~= 0 then
        local veh = menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if veh and veh ~= 0 then
            menu.nativeApis.VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(veh, math.random(0, 255), math.random(0, 255), math.random(0, 255))
            menu.nativeApis.VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(veh, math.random(0, 255), math.random(0, 255), math.random(0, 255))
            menu.nativeApis.VEHICLE.SET_VEHICLE_MOD(veh, 23, math.random(0, menu.nativeApis.VEHICLE.GET_NUM_VEHICLE_MODS(veh, 23) - 1), false)
        end
    end
end

function VehicleOptions:FlipVehicle(playerId)
    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if ped and ped ~= 0 then
        local veh = menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if veh and veh ~= 0 then
            local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(veh, true)
            local heading = menu.nativeApis.ENTITY.GET_ENTITY_HEADING(veh)
            menu.nativeApis.ENTITY.SET_ENTITY_COORDS(veh, pos.x, pos.y, pos.z + 2, false, false, false, false)
            menu.nativeApis.ENTITY.SET_ENTITY_ROTATION(veh, 0, 0, heading, 2, true)
        end
    end
end

function VehicleOptions:DeleteCurrentVehicle(playerId)
    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if ped and ped ~= 0 then
        local veh = menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if veh and veh ~= 0 then
            menu.nativeApis.ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true)
            EntityManager:DeleteEntity(veh)
        end
    end
end

VehicleOptions.ProcessVehicleOptions = LPH_NO_VIRTUALIZE(function(self, playerId)
    -- Keep observing a cached vehicle until the original exit/cleanup path clears it.
    if not (self.godMode[playerId] or self.invisible[playerId] or self.noCollision[playerId]
        or self.flyMode[playerId] or self.keepEngine[playerId] or self.autoRepair[playerId]
        or self.speedBoost[playerId] or self.jump[playerId] or self.instantStop[playerId]
        or self.driveOnWater[playerId] or self.autoPilot[playerId] or self.rainbowColor[playerId]
        or self.hornBoost[playerId] or self.driftMode[playerId] or self.autoFlip[playerId]
        or self.flyVehicle[playerId] or self.driftVehicle[playerId]
        or self.keepEngineVehicle[playerId] or self.driftApplied[playerId]
        or self.appliedOverrides[playerId] or self.lastVehicle[playerId]) then
        return
    end
    return self:_ProcessVehicleOptionsActive(playerId)
end)

function VehicleOptions:_ProcessVehicleOptionsActive(playerId)
    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if not ped or ped == 0 then return end
    local veh = menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if not veh or veh == 0 then
        local previousVehicle = self.lastVehicle[playerId]
        if previousVehicle then
            self:RestoreContinuousOverrides(playerId, previousVehicle)
        elseif self.flyVehicle[playerId] then
            self:RestoreAppliedOverride(playerId, self.flyVehicle[playerId], "fly")
        end
        self:RestoreDriftOverride(self.driftVehicle[playerId])
        local keepCandidate = previousVehicle or self.keepEngineVehicle[playerId]
        if self.keepEngine[playerId] and self:IsVehicleValid(keepCandidate) then
            if previousVehicle and type(menu.nativeApis.VEHICLE.SET_VEHICLE_KEEP_ENGINE_ON_WHEN_ABANDONED) == "function" then
                self:MarkAppliedOverride(playerId, keepCandidate, "keepEngine")
                pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_KEEP_ENGINE_ON_WHEN_ABANDONED, keepCandidate, true)
            end
            self.keepEngineVehicle[playerId] = keepCandidate
        else
            self:RestoreAppliedOverride(playerId, keepCandidate, "keepEngine")
            self.keepEngineVehicle[playerId] = nil
        end
        self.flyVehicle[playerId] = nil
        self.driftVehicle[playerId] = nil
        self.lastVehicle[playerId] = nil
        self.driftApplied[playerId] = false
        return
    end

    local previousVehicle = self.lastVehicle[playerId]
    if previousVehicle ~= veh then
        self:RestoreContinuousOverrides(playerId, previousVehicle)
        self:RestoreDriftOverride(self.driftVehicle[playerId])
        self.driftVehicle[playerId] = nil
        self.driftApplied[playerId] = false
        self.lastVehicle[playerId] = veh
        self:ApplyContinuousOverrides(playerId, veh)
    end

    -- Keep flight responsive instead of leaving the vehicle suspended with
    -- zero velocity when gravity is disabled.
    if self.flyMode[playerId] then
        local previousFlyVehicle = self.flyVehicle[playerId]
        if previousFlyVehicle and previousFlyVehicle ~= veh then
            self:RestoreAppliedOverride(playerId, previousFlyVehicle, "fly")
        end
        self.flyVehicle[playerId] = veh
        menu.nativeApis.VEHICLE.SET_VEHICLE_GRAVITY(veh, false)
        if menu.nativeApis.ENTITY and menu.nativeApis.ENTITY.SET_ENTITY_HAS_GRAVITY then
            pcall(menu.nativeApis.ENTITY.SET_ENTITY_HAS_GRAVITY, veh, false)
        end
        local camRot = menu.nativeApis.CAM and menu.nativeApis.CAM.GET_GAMEPLAY_CAM_ROT and menu.nativeApis.CAM.GET_GAMEPLAY_CAM_ROT(2) or {x = 0.0, y = 0.0, z = 0.0}
        local yaw, pitch = math.rad(camRot.z or 0.0), math.rad(camRot.x or 0.0)
        local cosPitch = math.abs(math.cos(pitch))
        local direction = {
            x = -math.sin(yaw) * cosPitch,
            y = math.cos(yaw) * cosPitch,
            z = math.sin(pitch)
        }
        local throttle = 0.0
        if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 71) then throttle = throttle + 1.0 end
        if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 72) then throttle = throttle - 1.0 end
        local vertical = 0.0
        if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 22) then vertical = vertical + 1.0 end
        if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 36) then vertical = vertical - 1.0 end
        local velocity = menu.nativeApis.ENTITY.GET_ENTITY_VELOCITY(veh)
        velocity = velocity or {x = 0.0, y = 0.0, z = 0.0}
        local speed = math.max(10.0, math.min(120.0, tonumber(self.flySpeed[playerId]) or 45.0))
        local targetX = velocity.x or 0.0
        local targetY = velocity.y or 0.0
        local targetZ = (velocity.z or 0.0) * 0.96
        if throttle ~= 0.0 then
            targetX = direction.x * speed * throttle
            targetY = direction.y * speed * throttle
            targetZ = direction.z * speed * throttle
        end
        if vertical ~= 0.0 then
            targetZ = vertical * speed
        end
        local blend = 0.28
        menu.nativeApis.ENTITY.SET_ENTITY_VELOCITY(
            veh,
            (velocity.x or 0.0) + ((targetX - (velocity.x or 0.0)) * blend),
            (velocity.y or 0.0) + ((targetY - (velocity.y or 0.0)) * blend),
            (velocity.z or 0.0) + ((targetZ - (velocity.z or 0.0)) * blend)
        )
    elseif self.flyVehicle[playerId] then
        self:RestoreAppliedOverride(playerId, self.flyVehicle[playerId], "fly")
        self.flyVehicle[playerId] = nil
    end
    if self.autoRepair[playerId] then
        local now = menu.nativeApis.MISC.GET_GAME_TIMER()
        if now - (self.autoRepairLast[playerId] or 0) >= 500 then
            self.autoRepairLast[playerId] = now
            local health = menu.nativeApis.ENTITY.GET_ENTITY_HEALTH(veh)
            local maxHealth = menu.nativeApis.ENTITY.GET_ENTITY_MAX_HEALTH(veh)
            if health < maxHealth * 0.9 then
                menu.nativeApis.VEHICLE.SET_VEHICLE_FIXED(veh)
            end
        end
    end
    if self.speedBoost[playerId] then
        if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 71) then
            local power = self.boostPower[playerId] or 2.5
            if menu.nativeApis.ENTITY and type(menu.nativeApis.ENTITY.APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS) == "function" then
                menu.nativeApis.ENTITY.APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS(veh, 1, 0.0, power * 0.10, 0.0, true, true, true, true)
            end
        end
    end
    if self.jump[playerId] then
        if menu.nativeApis.PAD.IS_CONTROL_JUST_PRESSED(0, 22) then 
            local vel = menu.nativeApis.ENTITY.GET_ENTITY_VELOCITY(veh)
            menu.nativeApis.ENTITY.SET_ENTITY_VELOCITY(veh, vel.x, vel.y, vel.z + 10.0)
        end
    end
    if self.instantStop[playerId] then
        if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 72) then
            menu.nativeApis.VEHICLE.SET_VEHICLE_FORWARD_SPEED(veh, 0)
        end
    end
    if self.driveOnWater[playerId] then
        local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(veh, true)
        local waterZ = self:GetWaterSurfaceHeight(pos)
        local inWater = menu.nativeApis.ENTITY.IS_ENTITY_IN_WATER and menu.nativeApis.ENTITY.IS_ENTITY_IN_WATER(veh)
        if waterZ and (inWater or pos.z <= waterZ + 0.35) then
            local vel = menu.nativeApis.ENTITY.GET_ENTITY_VELOCITY(veh)
            local targetZ = waterZ + 0.12
            local depth = targetZ - pos.z
            if depth > 1.5 then
                menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET(veh, pos.x, pos.y, targetZ, false, false, false)
                menu.nativeApis.ENTITY.SET_ENTITY_VELOCITY(veh, vel.x or 0.0, vel.y or 0.0, 0.0)
            elseif menu.nativeApis.ENTITY and type(menu.nativeApis.ENTITY.APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS) == "function" then
                local verticalSpeed = vel and (vel.z or 0.0) or 0.0
                local lift = math.max(-0.5, math.min(2.5, depth * 1.25 - verticalSpeed * 0.75))
                menu.nativeApis.ENTITY.APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS(veh, 1, 0.0, 0.0, lift, false, true, true, true)
            end
        end
    end
    if self.autoPilot[playerId] then
        if not menu.nativeApis.VEHICLE.GET_IS_VEHICLE_ENGINE_RUNNING(veh) then
            menu.nativeApis.VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false)
        end
        menu.nativeApis.VEHICLE.SET_VEHICLE_FORWARD_SPEED(veh, 30.0)
        local waypoint = menu.nativeApis.HUD.GET_FIRST_BLIP_INFO_ID(8)
        if menu.nativeApis.HUD.DOES_BLIP_EXIST(waypoint) then
            local coord = menu.nativeApis.HUD.GET_BLIP_COORDS(waypoint)
            menu.nativeApis.TASK.TASK_VEHICLE_DRIVE_TO_COORD_LONGRANGE(ped, veh, coord.x, coord.y, coord.z, 30.0, 786603, 0)
        end
    end
    if self.rainbowColor[playerId] then
        local time = menu.nativeApis.MISC.GET_GAME_TIMER()
        if time - (self.rainbowColorLast[playerId] or 0) >= 80 then
            self.rainbowColorLast[playerId] = time
            local r = math.floor((math.sin(time * 0.001) + 1) * 127.5)
            local g = math.floor((math.sin(time * 0.001 + 2.094) + 1) * 127.5)
            local b = math.floor((math.sin(time * 0.001 + 4.188) + 1) * 127.5)
            menu.nativeApis.VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(veh, r, g, b)
        end
    end
    if self.hornBoost[playerId] then
        if menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 86) then
            local power = self.boostPower[playerId] or 2.5
            if menu.nativeApis.ENTITY and type(menu.nativeApis.ENTITY.APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS) == "function" then
                menu.nativeApis.ENTITY.APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS(veh, 1, 0.0, power * 0.12, 0.0, true, true, true, true)
            end
        end
    end
    local driftShouldApply = self.driftMode[playerId]
        and (self.driftHandbrake[playerId] == false or menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 76))
    if driftShouldApply then
        local now = menu.nativeApis.MISC.GET_GAME_TIMER()
        if self.driftVehicle[playerId] and self.driftVehicle[playerId] ~= veh then
            self:RestoreDriftOverride(self.driftVehicle[playerId])
        end
        self.driftVehicle[playerId] = veh
        if now - (self.driftModeLast[playerId] or 0) >= 250 then
            self.driftModeLast[playerId] = now
            if menu.nativeApis.VEHICLE and type(menu.nativeApis.VEHICLE.SET_DRIFT_TYRES) == "function" then
                if self.driftOriginal[veh] == nil then
                    local original = false
                    if type(menu.nativeApis.VEHICLE.GET_DRIFT_TYRES_SET) == "function" then
                        local ok, value = pcall(menu.nativeApis.VEHICLE.GET_DRIFT_TYRES_SET, veh)
                        original = ok and value == true
                    end
                    self.driftOriginal[veh] = original and 1 or 0
                end
                menu.nativeApis.VEHICLE.SET_DRIFT_TYRES(veh, true)
            else
                menu.nativeApis.VEHICLE.SET_VEHICLE_REDUCE_GRIP(veh, true)
                menu.nativeApis.VEHICLE.SET_VEHICLE_REDUCE_GRIP_LEVEL(veh, 0.45)
            end
        end
        self.driftApplied[playerId] = true
    elseif self.driftApplied[playerId] then
        -- Clear the vehicle that actually received the override.  When the
        -- player switches seats/vehicles before the next tick, `veh` points
        -- at the new vehicle and the old one would otherwise keep drifting.
        local appliedVehicle = self.driftVehicle[playerId] or veh
        self:RestoreDriftOverride(appliedVehicle)
        self.driftVehicle[playerId] = nil
        self.driftApplied[playerId] = false
    end
    if self.autoFlip[playerId] then
        local now = menu.nativeApis.MISC.GET_GAME_TIMER()
        if now - (self.autoFlipLast[playerId] or 0) >= 250 then
            self.autoFlipLast[playerId] = now
            local rot = menu.nativeApis.ENTITY.GET_ENTITY_ROTATION(veh, 2)
            if math.abs(rot.x) > 90 or math.abs(rot.y) > 90 then
                local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(veh, true)
                local heading = menu.nativeApis.ENTITY.GET_ENTITY_HEADING(veh)
                menu.nativeApis.ENTITY.SET_ENTITY_ROTATION(veh, 0, 0, heading, 2, true)
                menu.nativeApis.ENTITY.SET_ENTITY_COORDS(veh, pos.x, pos.y, pos.z + 1, false, false, false, false)
            end
        end
    end
end

