    savedLocations = {}, autoPilot = {}, autoPilotSpeed = {}, keepVehicle = {},
    noOffset = {}, safeTeleport = {}, lastPosition = {}, teleportHistory = {},
    distance = 10.0, savedChoice = {}, active = nil, stopped = false,
}

