    {name = "Airport", x = -1102.0, y = -2893.0, z = 13.0},
    {name = "Military base", x = -2346.0, y = 3268.0, z = 32.0},
    {name = "Prison", x = 1679.0, y = 2513.0, z = 45.0},
    {name = "Hospital", x = 338.0, y = -1394.0, z = 32.0},
    {name = "Police station", x = 425.0, y = -979.0, z = 30.0},
    {name = "Bank", x = 252.0, y = 220.0, z = 106.0},
    {name = "Casino", x = 925.0, y = 46.0, z = 81.0},
