    {name = "Nightclub", x = -1388.0, y = -586.0, z = 30.0},
    {name = "Facility", x = 2150.0, y = 2921.0, z = 45.0},
    {name = "Hangar", x = -1267.0, y = -3380.0, z = 14.0},
