function TeleportManager:Notify(message)
    Logger:Toast("SovereignLua", message, CONFIG.UI.ToastDuration.Short)
end

function TeleportManager:ValidCoords(x, y, z)
    for _, value in ipairs({x, y, z}) do
        if type(value) ~= "number" or value ~= value or math.abs(value) > 100000 then return false end
    end
    return type(x) == "number" and type(y) == "number" and type(z) == "number"
end

function TeleportManager:GetEntity(playerId, keepVeh)
    local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if not ped or ped == 0 or not menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(ped) then return nil end
    if keepVeh == nil then keepVeh = self.keepVehicle[playerId] ~= false end
    local vehicle = menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false)
    return keepVeh and vehicle and vehicle ~= 0 and vehicle or ped, ped
end

function TeleportManager:LoadDestination(x, y, z, ground)
    local streaming, buffer, scene = menu.nativeApis.STREAMING, nil, false
    local ok, result = pcall(function()
        if ground then
            if not Memory or not Memory.Alloc or not Memory.Free or not Memory.ReadFloat or not Memory.WriteFloat then return nil end
            buffer = Memory.Alloc(8)
            if not buffer or buffer == 0 then return nil end
            Memory.WriteFloat(buffer, 0.0)
        end
        if streaming.NEW_LOAD_SCENE_START_SPHERE and streaming.IS_NEW_LOAD_SCENE_ACTIVE
            and streaming.NEW_LOAD_SCENE_STOP and not streaming.IS_NEW_LOAD_SCENE_ACTIVE() then
            scene = streaming.NEW_LOAD_SCENE_START_SPHERE(x, y, ground and 350.0 or z, ground and 500.0 or 120.0, 0) == true
            if scene and self.active then self.active.sceneOwned = true end
        end
        for attempt = 1, 80 do
            if self.stopped then return nil end
            streaming.REQUEST_COLLISION_AT_COORD(x, y, z)
            if ground then
                for _, height in ipairs({2000.0, 1000.0, 500.0, 200.0, 100.0, 50.0}) do
                    if menu.nativeApis.MISC.GET_GROUND_Z_FOR_3D_COORD(x, y, height, buffer, false, false) then
                        local groundZ = Memory.ReadFloat(buffer)
                        if self:ValidCoords(x, y, groundZ) then return groundZ + 1.0 end
                    end
                end
            elseif not scene or not streaming.IS_NEW_LOAD_SCENE_LOADED or streaming.IS_NEW_LOAD_SCENE_LOADED() then
                return z
            end
            Script.Yield(25)
        end
        if ground then return nil end
        return z
    end)
    if scene and (not self.active or self.active.sceneOwned) then pcall(streaming.NEW_LOAD_SCENE_STOP) end
    if self.active then self.active.sceneOwned = false end
    if buffer and buffer ~= 0 then pcall(Memory.Free, buffer) end
    return ok and result or nil
end

function TeleportManager:RestoreCollision(transaction)
    if transaction and transaction.collisionChanged then
        local ok = pcall(menu.nativeApis.ENTITY.SET_ENTITY_COLLISION, transaction.entity, not transaction.collisionDisabled, true)
        if ok then transaction.collisionChanged = false end
        return ok
    end
    return true
end

function TeleportManager:Cleanup()
    self.stopped = true
    if self.active and self.active.sceneOwned then
        pcall(menu.nativeApis.STREAMING.NEW_LOAD_SCENE_STOP)
        self.active.sceneOwned = false
    end
    self:RestoreCollision(self.active)
end

function TeleportManager:TeleportToCoords(playerId, x, y, z, keepVeh, skipRecord, options)
    options = options or {}
    if self.stopped or self.active then return false end
    if not self:ValidCoords(x, y, z) then self:Notify("Invalid teleport coordinates") return false end
    local entity, ped = self:GetEntity(playerId, keepVeh)
    if not entity then return false end
    if entity ~= ped and menu.nativeApis.NETWORK and menu.nativeApis.NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY
        and not menu.nativeApis.NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(entity) then
        self:Notify("Use vehicle teleport from the driver seat") return false
    end
    local original = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(entity, true)
    original = {x = original.x, y = original.y, z = original.z}
    local transaction = {entity = entity, moved = false, collisionChanged = false}
    self.active = transaction
    local ok, result = pcall(function()
        local targetZ = self:LoadDestination(x, y, z, options.ground == true)
        if targetZ == nil or self.stopped or self:GetEntity(playerId, keepVeh) ~= entity then return false end
        if self.safeTeleport[playerId] then
            transaction.collisionDisabled = menu.nativeApis.ENTITY.GET_ENTITY_COLLISION_DISABLED(entity)
            transaction.collisionChanged = true
            menu.nativeApis.ENTITY.SET_ENTITY_COLLISION(entity, false, true)
        end
        transaction.moved = true
        menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET(entity, x, y, targetZ, false, false, false)
        if self.safeTeleport[playerId] then
            for _ = 1, 40 do
                if self.stopped or not menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(entity) then return false end
                menu.nativeApis.STREAMING.REQUEST_COLLISION_AT_COORD(x, y, targetZ)
                if not menu.nativeApis.ENTITY.IS_ENTITY_WAITING_FOR_WORLD_COLLISION(entity) then break end
                Script.Yield(25)
            end
            if menu.nativeApis.ENTITY.IS_ENTITY_WAITING_FOR_WORLD_COLLISION(entity) then return false end
        end
        if options.heading and entity ~= ped then menu.nativeApis.ENTITY.SET_ENTITY_HEADING(entity, options.heading) end
        if options.ground and entity ~= ped then menu.nativeApis.VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY(entity, 5.0) end
        local actual = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(entity, true)
        if not self:ValidCoords(actual.x, actual.y, actual.z)
            or (actual.x - x)^2 + (actual.y - y)^2 + (actual.z - targetZ)^2 > 36.0 then return false end
        return {x = actual.x, y = actual.y, z = actual.z}
    end)
    if not ok or not result then
        if transaction.moved then pcall(menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET, entity, original.x, original.y, original.z, false, false, false) end
    end
    local restored = self:RestoreCollision(transaction)
    if restored then self.active = nil end
    if not ok or not result or not restored then
        self:Notify(options.ground and "No ground found; teleport cancelled" or "Teleport did not complete; try again later")
        return false
    end
    if not skipRecord then self.lastPosition[playerId] = original end
    table.insert(self.teleportHistory, {x = result.x, y = result.y, z = result.z, time = os.time()})
    if #self.teleportHistory > 50 then table.remove(self.teleportHistory, 1) end
    self:Notify("Teleported to the selected location")
    return true
end

function TeleportManager:TeleportToPlayer(playerId, targetId)
    local success, pos = PlayerManager:GetPlayerPosition(targetId)
    if success and pos then return self:TeleportToCoords(playerId, pos.x, pos.y, pos.z) end
    self:Notify("Cannot get the target player's position") return false
end

function TeleportManager:TeleportToPreset(playerId, locationName)
    for _, loc in ipairs(self.PRESET_LOCATIONS) do
        if loc.name == locationName then return self:TeleportToCoords(playerId, loc.x, loc.y, loc.z, nil, nil, {ground = true}) end
    end
    self:Notify("Location not found: " .. tostring(locationName)) return false
end

function TeleportManager:TeleportToWaypoint(playerId)
    playerId = playerId or menu.nativeApis.PLAYER.PLAYER_ID()
    local hud = menu.nativeApis.HUD
    if not hud.IS_WAYPOINT_ACTIVE() then self:Notify("Set a map waypoint first") return false end
    local blip = hud.GET_FIRST_BLIP_INFO_ID(hud.GET_WAYPOINT_BLIP_ENUM_ID())
    if not hud.DOES_BLIP_EXIST(blip) then return false end
    local pos = hud.GET_BLIP_INFO_ID_COORD(blip)
    return self:TeleportToCoords(playerId, pos.x, pos.y, pos.z, nil, nil, {ground = true})
end

function TeleportManager:TeleportToObjective(playerId)
    local hud = menu.nativeApis.HUD
    for _, sprite in ipairs({1, 66, 225, 85, 205, 270, 271, 280, 304, 432}) do
        local blip = hud.GET_FIRST_BLIP_INFO_ID(sprite)
        for _ = 1, 64 do
            if not blip or blip == 0 or not hud.DOES_BLIP_EXIST(blip) then break end
            -- Sprite 1 is also used by ordinary markers: only accept mission colours.
            local colour = hud.GET_BLIP_COLOUR(blip)
            if sprite ~= 1 or colour == 5 or colour == 46 or colour == 60 or colour == 66 then
                local pos = hud.GET_BLIP_INFO_ID_COORD(blip)
                if self:ValidCoords(pos.x, pos.y, pos.z) and not (pos.x == 0 and pos.y == 0 and pos.z == 0) then
                    return self:TeleportToCoords(playerId, pos.x, pos.y, pos.z + 1.0, nil, nil, {ground = math.abs(pos.z) < 0.01})
                end
            end
            local nextBlip = hud.GET_NEXT_BLIP_INFO_ID(sprite)
            if nextBlip == blip then break end
            blip = nextBlip
        end
    end
    self:Notify("Mission objective not found") return false
end

function TeleportManager:ReturnToLastPosition(playerId)
    local pos = self.lastPosition[playerId]
    if not pos then self:Notify("No previous position recorded") return false end
    return self:TeleportToCoords(playerId, pos.x, pos.y, pos.z)
end

function TeleportManager:SaveLocation(playerId, name)
    local entity = self:GetEntity(playerId)
    if not entity then return false end
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(entity, true)
    self.savedLocations[playerId] = self.savedLocations[playerId] or {}
    self.savedLocations[playerId][name] = {x = pos.x, y = pos.y, z = pos.z}
    self:RefreshSaved(playerId, name)
    self:Notify("Position saved: " .. name) return true
end

function TeleportManager:TeleportToSaved(playerId, name)
    local loc = (self.savedLocations[playerId] or {})[name]
    if loc then return self:TeleportToCoords(playerId, loc.x, loc.y, loc.z) end
    self:Notify("Saved location not found") return false
end

function TeleportManager:DeleteSavedLocation(playerId, name)
    if self.savedLocations[playerId] then self.savedLocations[playerId][name] = nil end
    self:RefreshSaved(playerId)
end

function TeleportManager:GetSavedLocations(playerId)
    return self.savedLocations[playerId] or {}
end

function TeleportManager:RefreshSaved(playerId, preferred)
    local names = {}
    for name in pairs(self:GetSavedLocations(playerId)) do names[#names + 1] = name end
    table.sort(names)
    self.savedNames = names
    self.savedChoice[playerId] = preferred or names[1]
    local feature = FeatureMgr.GetFeature(Utils.Joaat("tp_saved_choice"))
    if feature and feature.SetList then
        feature:SetList(#names > 0 and names or {"No saved locations"})
        if feature.SetListIndex then
            local index = 0
            for i, name in ipairs(names) do if name == self.savedChoice[playerId] then index = i - 1 end end
            feature:SetListIndex(index)
        end
    end
end

function TeleportManager:TeleportForward(playerId, direction)
    local entity = self:GetEntity(playerId)
    if not entity then return false end
    local pos = menu.nativeApis.ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(entity, 0.0, self.distance * (direction or 1), 0.0)
    return self:TeleportToCoords(playerId, pos.x, pos.y, pos.z)
end

function TeleportManager:TeleportUp(playerId)
    local entity = self:GetEntity(playerId)
    if not entity then return false end
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(entity, true)
    return self:TeleportToCoords(playerId, pos.x, pos.y, pos.z + 50.0)
end

function TeleportManager:TeleportToPath(playerId, road)
    local entity, ped = self:GetEntity(playerId)
    if not entity then return false end
    if not road and menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE(ped, false) then self:Notify("Leave the vehicle before finding a pedestrian landing") return false end
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(entity, true)
    local buffer
    local ok, point = pcall(function()
        buffer = Memory.Alloc(32)
        if not buffer or buffer == 0 then return nil end
        for offset = 0, 28, 4 do Memory.WriteFloat(buffer + offset, 0.0) end
        local found
        if road then
            found = menu.nativeApis.PATHFIND.GET_CLOSEST_VEHICLE_NODE_WITH_HEADING(pos.x, pos.y, pos.z, buffer, buffer + 24, 1, 3.0, 0.0)
        else
            found = menu.nativeApis.PATHFIND.GET_SAFE_COORD_FOR_PED(pos.x, pos.y, pos.z, true, buffer, 14)
        end
        if not found then return nil end
        local value = {x = Memory.ReadFloat(buffer), y = Memory.ReadFloat(buffer + 8), z = Memory.ReadFloat(buffer + 16)}
        if not self:ValidCoords(value.x, value.y, value.z)
            or (value.x - pos.x)^2 + (value.y - pos.y)^2 + (value.z - pos.z)^2 > 250.0^2 then return nil end
        if road then value.heading = Memory.ReadFloat(buffer + 24) end
        return value
    end)
    if buffer and buffer ~= 0 then pcall(Memory.Free, buffer) end
    if not ok or not point then self:Notify("No suitable landing nearby") return false end
    local keepVeh
    if not road then keepVeh = false end
    return self:TeleportToCoords(playerId, point.x, point.y, point.z + 1.0, keepVeh, nil, {heading = point.heading})
end

function TeleportManager:TeleportToGround(playerId)
    local entity = self:GetEntity(playerId)
    if not entity then return false end
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(entity, true)
    return self:TeleportToCoords(playerId, pos.x, pos.y, pos.z, nil, nil, {ground = true})
end

function TeleportManager:TeleportIntoVehicle(playerId)
    if self.active or self.stopped then return false end
    local _, ped = self:GetEntity(playerId)
    if not ped then return false end
    local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(ped, true)
    local closestVeh, closestSeat, closestDist = 0, nil, 100.0
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local veh = PoolMgr.GetCVehicle(i)
        if veh and veh:IsVehicle() then
            local handle = GTA.PointerToHandle(veh)
            local dist = Utils1:V3Distance(pos, veh.Position)
            if handle ~= 0 and dist < closestDist then
                local seats = menu.nativeApis.VEHICLE.GET_VEHICLE_MODEL_NUMBER_OF_SEATS(menu.nativeApis.ENTITY.GET_ENTITY_MODEL(handle))
                for seat = -1, seats - 2 do
                    if menu.nativeApis.VEHICLE.IS_VEHICLE_SEAT_FREE(handle, seat, false) then
                        closestVeh, closestSeat, closestDist = handle, seat, dist break
                    end
                end
            end
        end
    end
    if closestVeh ~= 0 and menu.nativeApis.VEHICLE.IS_VEHICLE_SEAT_FREE(closestVeh, closestSeat, false) then
        menu.nativeApis.PED.SET_PED_INTO_VEHICLE(ped, closestVeh, closestSeat)
        if menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false) == closestVeh then
            self.lastPosition[playerId] = {x = pos.x, y = pos.y, z = pos.z}
            self:Notify("Entered vehicle") return true
        end
    end
    self:Notify("No usable vehicle nearby") return false
end

function TeleportManager:ToggleAutoPilot(playerId)
    self.autoPilot[playerId] = not (self.autoPilot[playerId] or false)
end
function TeleportManager:SetAutoPilotSpeed(playerId, speed) self.autoPilotSpeed[playerId] = speed end
function TeleportManager:ToggleKeepVehicle(playerId, enabled)
    if enabled == nil then enabled = self.keepVehicle[playerId] == false end
    self.keepVehicle[playerId] = enabled == true
end
function TeleportManager:ToggleSafeTeleport(playerId, enabled)
    if enabled == nil then enabled = not self.safeTeleport[playerId] end
    self.safeTeleport[playerId] = enabled == true
end


-- World tornado with complete discovery and time-sliced updates. This module has no main-chunk local declarations.
menu.worldTornado = {
    enabled = false, follow = false, particles = true,
    radius = 45.0, height = 55.0,
    affectPeds = true, affectVehicles = true, affectObjects = true,
    poolSpecs = {{"GetMaxPedCount", "GetCPed", 1}, {"GetMaxVehicleCount", "GetCVehicle", 2}, {"GetMaxObjectCount", "GetCObject", 3}},
    records = {}, seen = {}, pools = {}, effects = {},
    controlHead = nil, controlTail = nil,
    cursor = 1, poolCursor = 1, effectCursor = 1,
    nextScan = 0, nextAssetRequest = 0, assetAttempts = 0,
    status = "Disabled", asset = "core", clock = 0,
    authorize = function() return AuthManager:SessionValid() end,
}

menu.worldTornado.Finite = LPH_NO_VIRTUALIZE(function(self, value)
    return type(value) == "number" and value == value and math.abs(value) < 10000000
end)

menu.worldTornado.PositionValid = LPH_NO_VIRTUALIZE(function(self, pos)
    return pos and self:Finite(pos.x) and self:Finite(pos.y) and self:Finite(pos.z)
end)

menu.worldTornado.Now = LPH_NO_VIRTUALIZE(function(self)
    -- GET_GAME_TIMER is wall/game elapsed time; os.clock is only a CPU budget.
    local raw = menu.nativeApis.MISC.GET_GAME_TIMER() % 4294967296
    if self.lastClock ~= nil then
        local delta = (raw - self.lastClock) % 4294967296
        -- A game-clock reset must not make cooldowns wait for days.
        if delta <= 60000 then self.clock = self.clock + delta end
    end
    self.lastClock = raw
    return self.clock
end)

function menu.worldTornado:StopEffects()
    local graphics = menu.nativeApis.GRAPHICS
    for _, effect in pairs(self.effects) do
        if effect.handle and graphics and type(graphics.STOP_PARTICLE_FX_LOOPED) == "function" then
            for _ = 1, 3 do
                if pcall(graphics.STOP_PARTICLE_FX_LOOPED, effect.handle, false) then break end
            end
        end
    end
    self.effects, self.effectCursor = {}, 1
end

function menu.worldTornado:Cleanup(reason)
    self.enabled = false
    self:StopEffects()
    -- core is also used by other features; stop only our handles, never unload
    -- their shared dictionary or remove unrelated effects in the area.
    self.records, self.seen, self.pools = {}, {}, {}
    self.controlHead, self.controlTail = nil, nil
    self.cursor, self.poolCursor, self.center = 1, 1, nil
    self.assetAttempts, self.nextAssetRequest, self.assetFailed = 0, 0, false
    self.nextControlDispatch = 0
    self.nextScan, self.lastClock, self.clock = 0, nil, 0
    self.lastPed, self.lastSession, self.lastCenterAt = nil, nil, nil
    self.status = reason or "Disabled"
end

function menu.worldTornado:Recenter()
    if self.unloaded or not self.authorize or not self.authorize() then return false end
    local player, entity = menu.nativeApis.PLAYER, menu.nativeApis.ENTITY
    local ped = player.PLAYER_PED_ID()
    if not ped or ped == 0 or not entity.DOES_ENTITY_EXIST(ped) then return false end
    local pos = entity.GET_ENTITY_COORDS(ped, false)
    local forward = entity.GET_ENTITY_FORWARD_VECTOR(ped)
    if not self:PositionValid(pos) or not self:PositionValid(forward) then return false end
    self.center = {x = pos.x + forward.x * 25.0, y = pos.y + forward.y * 25.0, z = pos.z - 1.0}
    self.records, self.seen, self.pools = {}, {}, {}
    self.controlHead, self.controlTail = nil, nil
    self.cursor, self.poolCursor, self.nextScan = 1, 1, 0
    self.lastCenterAt = nil
    return true
end

function menu.worldTornado:SetEnabled(value)
    self:Cleanup()
    if value ~= true then return true end
    if self.unloaded or not self.authorize or not self.authorize() then self.status = "Waiting for authorization"; return false end
    local a = menu.nativeApis
    if not (PoolMgr and GTA and type(GTA.PointerToHandle) == "function" and type(GTA.HandleToPointer) == "function"
        and a.ENTITY and type(a.ENTITY.SET_ENTITY_VELOCITY) == "function"
        and a.PED and a.VEHICLE and a.PLAYER and a.MISC and a.NETWORK) then
        self.status = "Entity interfaces are unavailable in this host"
        return false
    end
    local ok, ready = pcall(self.Recenter, self)
    if not ok or not ready then self.status = "Waiting for your character"; return false end
    self.enabled, self.status = true, "Running"
    return true
end

menu.worldTornado.Eligible = LPH_NO_VIRTUALIZE(function(self, entity, kind, localPed, localVehicle)
    local a = menu.nativeApis
    if entity == 0 or entity == localPed or entity == localVehicle or not a.ENTITY.DOES_ENTITY_EXIST(entity) then return false end
    if a.ENTITY.IS_ENTITY_ATTACHED(entity) then return false end
    if kind == 1 then
        if not self.affectPeds or a.PED.IS_PED_A_PLAYER(entity) or a.PED.IS_PED_IN_ANY_VEHICLE(entity, true) then return false end
    elseif kind == 2 then
        if not self.affectVehicles then return false end
        local count = a.VEHICLE.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS(entity)
        -- Unusual/invalid capacities cannot turn one candidate into a large loop.
        if not self:Finite(count) or count < 0 or count > 16 then return false end
        for seat = -1, count - 1 do
            local occupant = a.VEHICLE.GET_PED_IN_VEHICLE_SEAT(entity, seat, false)
            if occupant and occupant ~= 0 and a.PED.IS_PED_A_PLAYER(occupant) then return false end
        end
    elseif kind == 3 then
        if not self.affectObjects or a.ENTITY.IS_ENTITY_STATIC(entity) then return false end
    else
        return false
    end
    return true
end)

menu.worldTornado.InRange = LPH_NO_VIRTUALIZE(function(self, position)
    if not self:PositionValid(position) then return false end
    local dx, dy, dz = position.x - self.center.x, position.y - self.center.y, position.z - self.center.z
    return dx * dx + dy * dy <= self.radius * self.radius and dz >= -12.0 and dz <= self.height + 15.0
end)

menu.worldTornado.QueueCandidate = LPH_NO_VIRTUALIZE(function(self, ptr, kind, localPed, localVehicle, now)
    if not ptr or not self:InRange(ptr.Position) then return end
    local handle = GTA.PointerToHandle(ptr)
    if not handle or self.seen[handle] or not self:Eligible(handle, kind, localPed, localVehicle) then return end
    local address = ptr:GetAddress()
    -- Pointers exceed coordinate bounds on 64-bit hosts.
    if type(address) ~= "number" or address ~= address or address <= 0 or address >= 9007199254740992 then return end
    local record = {handle = handle, address = address, model = menu.nativeApis.ENTITY.GET_ENTITY_MODEL(handle),
        kind = kind, attempts = 0, nextControl = now, nextMove = now, ragdollAt = now, lastMove = now - 50}
    self.records[#self.records + 1], self.seen[handle] = record, record
end)

menu.worldTornado.StartScan = LPH_NO_VIRTUALIZE(function(self, now)
    self.pools, self.poolCursor = {}, 1
    for _, spec in ipairs(self.poolSpecs) do
        if PoolMgr and type(PoolMgr[spec[1]]) == "function" and type(PoolMgr[spec[2]]) == "function" then
            local ok, count = pcall(PoolMgr[spec[1]])
            if ok and self:Finite(count) and count > 0 then
                self.pools[#self.pools + 1] = {get = PoolMgr[spec[2]], kind = spec[3], index = 0, count = math.floor(count)}
            end
        end
    end
    self.nextScan = now + 750
end)

menu.worldTornado.Scan = LPH_NO_VIRTUALIZE(function(self, localPed, localVehicle, now, deadline)
    if #self.pools == 0 and now >= self.nextScan then self:StartScan(now) end
    for _ = 1, 48 do
        if #self.pools == 0 or os.clock() >= deadline then return end
        if self.poolCursor > #self.pools then self.poolCursor = 1 end
        local pool = self.pools[self.poolCursor]
        if pool.index >= pool.count then
            table.remove(self.pools, self.poolCursor)
        else
            local index = pool.index
            pool.index, self.poolCursor = index + 1, self.poolCursor + 1
            local ok, ptr = pcall(pool.get, index)
            if ok then pcall(self.QueueCandidate, self, ptr, pool.kind, localPed, localVehicle, now) end
        end
    end
end)

menu.worldTornado.UnqueueControl = LPH_NO_VIRTUALIZE(function(self, record)
    if not record.controlQueued then return end
    if record.controlPrev then record.controlPrev.controlNext = record.controlNext else self.controlHead = record.controlNext end
    if record.controlNext then record.controlNext.controlPrev = record.controlPrev else self.controlTail = record.controlPrev end
    record.controlQueued, record.controlPrev, record.controlNext = nil, nil, nil
end)

menu.worldTornado.QueueControl = LPH_NO_VIRTUALIZE(function(self, record, now)
    if record.controlQueued or now < record.nextControl then return end
    record.controlQueued, record.controlPrev = true, self.controlTail
    if self.controlTail then self.controlTail.controlNext = record else self.controlHead = record end
    self.controlTail = record
end)

menu.worldTornado.RequestRecordControl = LPH_NO_VIRTUALIZE(function(self, record, localPed, localVehicle, now)
    local a, handle = menu.nativeApis, record.handle
    -- The queue can outlive a movement visit. Recheck identity, eligibility and
    -- ownership immediately before requesting control, never trust stale handles.
    if self.seen[handle] ~= record or now < record.nextControl or not a.ENTITY.DOES_ENTITY_EXIST(handle) then return false end
    local ptr = GTA.HandleToPointer(handle)
    if not ptr or ptr:GetAddress() ~= record.address or a.ENTITY.GET_ENTITY_MODEL(handle) ~= record.model
        or a.ENTITY.GET_ENTITY_TYPE(handle) ~= record.kind then return false end
    if not self:Eligible(handle, record.kind, localPed, localVehicle)
        or not self:InRange(a.ENTITY.GET_ENTITY_COORDS(handle, false)) then return false end
    if not a.NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(handle) or a.NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(handle) then return false end
    if record.attempts >= 2 then
        record.attempts, record.nextControl = 0, now + 5000
        return false
    end
    -- Set cooldowns before entering the native so even an exception cannot
    -- turn a failed request into an every-frame request loop.
    self.nextControlDispatch = now + 125
    record.attempts, record.nextControl = record.attempts + 1, now + 500
    a.NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(handle)
    return true
end)

menu.worldTornado.ProcessControl = LPH_NO_VIRTUALIZE(function(self, localPed, localVehicle, now, deadline)
    if now < (self.nextControlDispatch or 0) then return end
    -- FIFO is independent of the movement cursor. Stale entries are bounded
    -- work per frame, never a cap on how many entities can eventually request.
    for _ = 1, 16 do
        local record = self.controlHead
        if not record or os.clock() >= deadline then return end
        self:UnqueueControl(record)
        local ok, requested = pcall(self.RequestRecordControl, self, record, localPed, localVehicle, now)
        if not ok then record.nextControl = now + 5000 end
        if requested or now < (self.nextControlDispatch or 0) then return end
    end
end)

menu.worldTornado.MoveRecord = LPH_NO_VIRTUALIZE(function(self, record, localPed, localVehicle, now)
    local a, handle = menu.nativeApis, record.handle
    -- Not due yet: avoid polling every native for the whole tracked set.
    -- Identity and ownership are still rechecked before every mutation.
    if now < record.nextMove then return true end
    if not a.ENTITY.DOES_ENTITY_EXIST(handle) then return false end
    local ptr = GTA.HandleToPointer(handle)
    if not ptr or ptr:GetAddress() ~= record.address or a.ENTITY.GET_ENTITY_MODEL(handle) ~= record.model
        or a.ENTITY.GET_ENTITY_TYPE(handle) ~= record.kind then return false end
    if not self:Eligible(handle, record.kind, localPed, localVehicle) then return false end
    local pos = a.ENTITY.GET_ENTITY_COORDS(handle, false)
    if not self:InRange(pos) then return false end
    record.nextMove = now + 40
    if a.NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(handle) and not a.NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(handle) then
        -- Retain denied records and enqueue only when their own cooldown ends.
        -- Request order is separate from movement order, preventing starvation.
        self:QueueControl(record, now)
        return true
    end
    self:UnqueueControl(record)
    local velocity = a.ENTITY.GET_ENTITY_VELOCITY(handle)
    if not self:PositionValid(velocity) then return false end
    local dx, dy, dz = pos.x - self.center.x, pos.y - self.center.y, pos.z - self.center.z
    local radius = math.sqrt(dx * dx + dy * dy)
    if radius < 0.15 then dx, dy, radius = 0.15, 0.0, 0.15 end
    local heightRatio = math.max(0.0, math.min(1.0, dz / self.height))
    local orbit = 2.0 + self.radius * 0.28 * heightRatio
    local inward = math.max(-8.0, math.min(18.0, (radius - orbit) * 1.15))
    local tangential = 16.0 + 9.0 * (1.0 - heightRatio)
    local vertical = math.max(-3.0, math.min(18.0, (self.height - dz) * 0.65))
    local vx = -dx / radius * inward - dy / radius * tangential
    local vy = -dy / radius * inward + dx / radius * tangential
    local alpha = math.min(1.0, math.max(0.016, math.min(0.25, (now - record.lastMove) / 1000.0)) * 5.0)
    record.lastMove = now
    if record.kind == 1 and now >= record.ragdollAt then
        a.PED.SET_PED_TO_RAGDOLL(handle, 1200, 1200, 0, false, false, false)
        record.ragdollAt = now + 750
    end
    -- World-space velocity convergence provides mass-independent spiral motion
    -- without permanent gravity/collision/attachment changes requiring restore.
    a.ENTITY.SET_ENTITY_VELOCITY(handle,
        math.max(-45.0, math.min(45.0, velocity.x + (vx - velocity.x) * alpha)),
        math.max(-45.0, math.min(45.0, velocity.y + (vy - velocity.y) * alpha)),
        math.max(-25.0, math.min(25.0, velocity.z + (vertical - velocity.z) * alpha)))
    return true
end)

menu.worldTornado.MoveBatch = LPH_NO_VIRTUALIZE(function(self, localPed, localVehicle, now, deadline)
    -- Visit at most one full round; the cursor resumes next frame when
    -- the time slice ends. There is no total tracked-entity limit.
    for _ = 1, #self.records do
        if os.clock() >= deadline or #self.records == 0 then return end
        if self.cursor > #self.records then self.cursor = 1 end
        local record = self.records[self.cursor]
        local ok, keep = pcall(self.MoveRecord, self, record, localPed, localVehicle, now)
        if not ok or not keep then
            self:UnqueueControl(record)
            self.seen[record.handle] = nil
            self.records[self.cursor] = self.records[#self.records]
            self.records[#self.records] = nil
        else
            self.cursor = self.cursor + 1
        end
    end
end)

menu.worldTornado.EffectPosition = LPH_NO_VIRTUALIZE(function(self, index, now)
    -- Twelve levels, two rotating arms, wider toward the top.
    local level = math.floor((index - 1) / 2) / 11.0
    local phase = now * 0.0018 + level * math.pi * 4.0 + ((index - 1) % 2) * math.pi
    local radius = 1.0 + self.radius * 0.27 * level
    return self.center.x + math.cos(phase) * radius, self.center.y + math.sin(phase) * radius,
        self.center.z + level * self.height, 0.5 + level * 1.2, phase * 180.0 / math.pi
end)

menu.worldTornado.ProcessEffects = LPH_NO_VIRTUALIZE(function(self, now, deadline)
    if not self.particles then if next(self.effects) then self:StopEffects() end; return end
    if self.assetFailed then return end
    local graphics, streaming = menu.nativeApis.GRAPHICS, menu.nativeApis.STREAMING
    if not graphics or not streaming or type(graphics.START_PARTICLE_FX_LOOPED_AT_COORD) ~= "function"
        or type(graphics.SET_PARTICLE_FX_LOOPED_OFFSETS) ~= "function"
        or type(graphics.STOP_PARTICLE_FX_LOOPED) ~= "function"
        or type(graphics.USE_PARTICLE_FX_ASSET) ~= "function"
        or type(streaming.HAS_NAMED_PTFX_ASSET_LOADED) ~= "function"
        or type(streaming.REQUEST_NAMED_PTFX_ASSET) ~= "function" then
        self.assetFailed, self.status = true, "Entity swirl running; particle interfaces unavailable"
        return
    end
    if not streaming.HAS_NAMED_PTFX_ASSET_LOADED(self.asset) then
        if now >= self.nextAssetRequest then
            if self.assetAttempts >= 5 then self.assetFailed, self.status = true, "Entity swirl running; particle assets unavailable"; return end
            streaming.REQUEST_NAMED_PTFX_ASSET(self.asset)
            self.assetAttempts, self.nextAssetRequest = self.assetAttempts + 1, now + 1000
        end
        return
    end
    local created = 0
    for _ = 1, 4 do
        if os.clock() >= deadline then return end
        local index = self.effectCursor
        self.effectCursor = self.effectCursor % 24 + 1
        local effect = self.effects[index]
        if not effect then
            if created >= 1 then return end
            effect = {nextAt = 0, attempts = 0}
            self.effects[index] = effect
        end
        if now >= effect.nextAt then
            local x, y, z, scale, rotation = self:EffectPosition(index, now)
            if effect.handle then
                if type(graphics.DOES_PARTICLE_FX_LOOPED_EXIST) == "function"
                    and not graphics.DOES_PARTICLE_FX_LOOPED_EXIST(effect.handle) then
                    effect.handle, effect.nextAt = nil, now + 1000
                else
                    graphics.SET_PARTICLE_FX_LOOPED_OFFSETS(effect.handle, x, y, z, 0.0, 0.0, rotation)
                end
                effect.nextAt = now + 100
                if effect.handle and type(graphics.SET_PARTICLE_FX_LOOPED_SCALE) == "function" then graphics.SET_PARTICLE_FX_LOOPED_SCALE(effect.handle, scale) end
            elseif effect.attempts < 3 and created < 1 then
                created = created + 1
                graphics.USE_PARTICLE_FX_ASSET(self.asset)
                local handle = graphics.START_PARTICLE_FX_LOOPED_AT_COORD("ent_amb_smoke_foundry", x, y, z,
                    0.0, 0.0, rotation, scale, false, false, false, false)
                effect.attempts, effect.nextAt = effect.attempts + 1, now + 1000
                if type(handle) == "number" and handle > 0 then
                    effect.handle, effect.nextAt = handle, now + 100
                    if type(graphics.SET_PARTICLE_FX_LOOPED_COLOUR) == "function" then graphics.SET_PARTICLE_FX_LOOPED_COLOUR(handle, 0.38, 0.34, 0.29, false) end
                    if type(graphics.SET_PARTICLE_FX_LOOPED_ALPHA) == "function" then graphics.SET_PARTICLE_FX_LOOPED_ALPHA(handle, 0.65) end
                end
            end
        end
    end
end)

menu.worldTornado.ProcessActive = LPH_NO_VIRTUALIZE(function(self)
    local a, now = menu.nativeApis, self:Now()
    local ped = a.PLAYER.PLAYER_PED_ID()
    local transition = type(a.NETWORK.NETWORK_IS_IN_TRANSITION) == "function" and a.NETWORK.NETWORK_IS_IN_TRANSITION()
    local session = type(a.NETWORK.NETWORK_IS_SESSION_ACTIVE) == "function" and a.NETWORK.NETWORK_IS_SESSION_ACTIVE() or false
    if transition or (self.lastSession ~= nil and self.lastSession ~= session)
        or not ped or ped == 0 or not a.ENTITY.DOES_ENTITY_EXIST(ped)
        or (self.lastPed ~= nil and self.lastPed ~= ped) then
        self:Cleanup("Tornado stopped after character or session change")
        return
    end
    self.lastPed, self.lastSession = ped, session
    self.radius = math.max(20.0, math.min(100.0, tonumber(self.radius) or 45.0))
    self.height = math.max(25.0, math.min(90.0, tonumber(self.height) or 55.0))
    local localVehicle = a.PED.GET_VEHICLE_PED_IS_IN(ped, true)
    if not self.center then if not self:Recenter() then self:Cleanup("Waiting for your character"); return end end
    if self.follow then
        local pos, forward = a.ENTITY.GET_ENTITY_COORDS(ped, false), a.ENTITY.GET_ENTITY_FORWARD_VECTOR(ped)
        if not self:PositionValid(pos) or not self:PositionValid(forward) then self:Cleanup("Tornado center is unavailable"); return end
        local dt = math.min(0.1, math.max(0.0, (now - (self.lastCenterAt or now)) / 1000.0))
        local dx, dy = pos.x + forward.x * 25.0 - self.center.x, pos.y + forward.y * 25.0 - self.center.y
        local length = math.sqrt(dx * dx + dy * dy)
        local scale = length > 0 and math.min(1.0, dt * 8.0 / length) or 0
        self.center.x, self.center.y = self.center.x + dx * scale, self.center.y + dy * scale
        self.center.z = self.center.z + math.max(-dt * 3.0, math.min(dt * 3.0, pos.z - 1.0 - self.center.z))
    end
    self.lastCenterAt = now
    -- Each phase starts its own soft slice after setup. An expensive preceding
    -- native cannot permanently starve discovery, movement or particles.
    -- The 0.75 ms sum excludes setup and non-preemptible native/GC overruns.
    self:Scan(ped, localVehicle, now, os.clock() + 0.00020)
    self:ProcessControl(ped, localVehicle, now, os.clock() + 0.00008)
    self:MoveBatch(ped, localVehicle, now, os.clock() + 0.00032)
    local effectsOk = pcall(self.ProcessEffects, self, now, os.clock() + 0.00015)
    if not effectsOk then self:StopEffects(); self.assetFailed, self.status = true, "Entity swirl running; particle initialization failed" end
end)

menu.worldTornado.Process = LPH_NO_VIRTUALIZE(function(self)
    if not self.enabled then return end
    return self:ProcessActive()
end)

function menu.worldTornado:Shutdown()
    self.unloaded = true
    self:Cleanup()
end

-- Call menu.worldTornado:RegisterUI(groups.worldTornado) in the UI initializer.
function menu.worldTornado:RegisterUI(group)
    menu.ui.items.worldTornadoEnabled = menu.toggle("Tornado", "All eligible NPCs, vehicles and dynamic props in range participate without an entity count limit; exclude players and player-occupied vehicles", group, 0, function(value)
        local ok = self:SetEnabled(value)
        if not ok then SovereignNotify("SovereignLua", self.status, "warning") end
    end)
    menu.bindFeatureToggle(menu.ui.items.worldTornadoEnabled, "world_tornado_enabled", function() return self.enabled end)
    menu.ui.items.worldTornadoFollow = menu.toggle("Follow player", "Move the center slowly toward 25 meters ahead of your character; disable to keep it stationary", group, 0, function(value) self.follow = value == true end)
    menu.bindFeatureToggle(menu.ui.items.worldTornadoFollow, "world_tornado_follow", function() return self.follow end)
    menu.ui.items.worldTornadoParticles = menu.toggle("Tornado particles", "Draw a rotating smoke funnel; entities continue swirling with particles disabled", group, 0, function(value) self.particles = value == true end)
    menu.bindFeatureToggle(menu.ui.items.worldTornadoParticles, "world_tornado_particles", function() return self.particles end)
    menu.slider("Tornado radius", "Effect radius in meters", group, 20, 100, self.radius, "%.0f", 0, function(value) self.radius = math.floor(value) end)
    menu.slider("Tornado height", "Funnel height in meters", group, 25, 90, self.height, "%.0f", 0, function(value) self.height = math.floor(value) end)
    menu.button("Move tornado ahead", "Place the center 25 meters ahead of your character and clear the old entity queue", group, 0, function()
        if self.enabled then self:Recenter() end
    end)
    menu.button("Stop and clear tornado", "Stop the swirl and remove this feature's particle effects", group, 0, function() self:Cleanup() end)
end

