function WorldOptions:ApplyDisablePolice(playerId, enabled)
    pcall(function()
        if menu.nativeApis.PLAYER.SET_MAX_WANTED_LEVEL then
            menu.nativeApis.PLAYER.SET_MAX_WANTED_LEVEL(enabled and 0 or 5)
        end
        if menu.nativeApis.PLAYER.SET_POLICE_IGNORE_PLAYER then
            menu.nativeApis.PLAYER.SET_POLICE_IGNORE_PLAYER(playerId, enabled)
        end
        if menu.nativeApis.PLAYER.SET_EVERYONE_IGNORE_PLAYER then
            menu.nativeApis.PLAYER.SET_EVERYONE_IGNORE_PLAYER(playerId, enabled)
        end
        if menu.nativeApis.PLAYER.SET_DISPATCH_COPS_FOR_PLAYER then
            menu.nativeApis.PLAYER.SET_DISPATCH_COPS_FOR_PLAYER(playerId, not enabled)
        end
        if not enabled then return end
        if menu.nativeApis.PLAYER.SET_PLAYER_WANTED_LEVEL then
            menu.nativeApis.PLAYER.SET_PLAYER_WANTED_LEVEL(playerId, 0, false)
        end
        if menu.nativeApis.PLAYER.SET_PLAYER_WANTED_LEVEL_NOW then
            menu.nativeApis.PLAYER.SET_PLAYER_WANTED_LEVEL_NOW(playerId, false)
        end
        if menu.nativeApis.PED.SET_CREATE_RANDOM_COPS then
            menu.nativeApis.PED.SET_CREATE_RANDOM_COPS(false)
        end
        if menu.nativeApis.PED.SET_CREATE_RANDOM_COPS_ON_SCENARIOS then
            menu.nativeApis.PED.SET_CREATE_RANDOM_COPS_ON_SCENARIOS(false)
        end
    end)
end

function WorldOptions:ApplyDisableTraffic(playerId, enabled)
    pcall(function()
        local allow = not enabled
        if menu.nativeApis.VEHICLE.SET_RANDOM_TRAINS then
            menu.nativeApis.VEHICLE.SET_RANDOM_TRAINS(allow)
        end
        if menu.nativeApis.VEHICLE.SET_RANDOM_BOATS then
            menu.nativeApis.VEHICLE.SET_RANDOM_BOATS(allow)
        end
        if menu.nativeApis.VEHICLE.SET_GARBAGE_TRUCKS then
            menu.nativeApis.VEHICLE.SET_GARBAGE_TRUCKS(allow)
        end
        if menu.nativeApis.VEHICLE.SET_ALL_VEHICLE_GENERATORS_ACTIVE_IN_AREA then
            menu.nativeApis.VEHICLE.SET_ALL_VEHICLE_GENERATORS_ACTIVE_IN_AREA(-10000, -10000, -10000, 10000, 10000, 10000, allow, false)
        end
        if not enabled then return end
        if menu.nativeApis.VEHICLE.SET_VEHICLE_DENSITY_MULTIPLIER_THIS_FRAME then
            menu.nativeApis.VEHICLE.SET_VEHICLE_DENSITY_MULTIPLIER_THIS_FRAME(0.0)
        end
        if menu.nativeApis.VEHICLE.SET_RANDOM_VEHICLE_DENSITY_MULTIPLIER_THIS_FRAME then
            menu.nativeApis.VEHICLE.SET_RANDOM_VEHICLE_DENSITY_MULTIPLIER_THIS_FRAME(0.0)
        end
        if menu.nativeApis.VEHICLE.SET_PARKED_VEHICLE_DENSITY_MULTIPLIER_THIS_FRAME then
            menu.nativeApis.VEHICLE.SET_PARKED_VEHICLE_DENSITY_MULTIPLIER_THIS_FRAME(0.0)
        end
        if menu.nativeApis.VEHICLE.SET_NUMBER_OF_PARKED_VEHICLES then
            menu.nativeApis.VEHICLE.SET_NUMBER_OF_PARKED_VEHICLES(0)
        end
    end)
end

function WorldOptions:ApplyDisablePeds(playerId, enabled)
    pcall(function()
        local allow = not enabled
        if menu.nativeApis.PED.SET_CREATE_RANDOM_COPS then
            menu.nativeApis.PED.SET_CREATE_RANDOM_COPS(allow)
        end
        if menu.nativeApis.PED.SET_CREATE_RANDOM_COPS_ON_SCENARIOS then
            menu.nativeApis.PED.SET_CREATE_RANDOM_COPS_ON_SCENARIOS(allow)
        end
        if not enabled then return end
        if menu.nativeApis.PED.SET_PED_DENSITY_MULTIPLIER_THIS_FRAME then
            menu.nativeApis.PED.SET_PED_DENSITY_MULTIPLIER_THIS_FRAME(0.0)
        end
        if menu.nativeApis.PED.SET_SCENARIO_PED_DENSITY_MULTIPLIER_THIS_FRAME then
            menu.nativeApis.PED.SET_SCENARIO_PED_DENSITY_MULTIPLIER_THIS_FRAME(0.0, 0.0)
        end
    end)
end

