WorldOptions.ProcessWorldOptions = LPH_NO_VIRTUALIZE(function(self, playerId)
    if not (self.disablePolice[playerId] or self.disableTraffic[playerId] or self.disablePeds[playerId]
        or self.clearWanted[playerId] or self.alwaysDay[playerId] or self.alwaysNight[playerId]
        or self.brightNight[playerId] or self.allGreenLights[playerId] or self.chaosMode[playerId]
        or self.invisibleWorld[playerId]) then
        return
    end
    return self:_ProcessWorldOptionsActive(playerId)
end)

function WorldOptions:_ProcessWorldOptionsActive(playerId)
    if self.disablePolice[playerId] then
        self:ApplyDisablePolice(playerId, true)
    end
    if self.disableTraffic[playerId] then
        self:ApplyDisableTraffic(playerId, true)
    end
    if self.disablePeds[playerId] then
        self:ApplyDisablePeds(playerId, true)
    end
    if self.clearWanted[playerId] then
        if menu.nativeApis.PLAYER.GET_PLAYER_WANTED_LEVEL(playerId) > 0 then
            menu.nativeApis.PLAYER.SET_PLAYER_WANTED_LEVEL(playerId, 0, false)
            menu.nativeApis.PLAYER.SET_PLAYER_WANTED_LEVEL_NOW(playerId, false)
        end
    end
    if self.alwaysDay[playerId] then
        menu.nativeApis.NETWORK.NETWORK_OVERRIDE_CLOCK_TIME(12, 0, 0)
    end
    if self.alwaysNight[playerId] then
        menu.nativeApis.NETWORK.NETWORK_OVERRIDE_CLOCK_TIME(23, 0, 0) --there's no 24 hour or more in the game. missing time crash
    end
    if self.brightNight[playerId] then
        local hour = menu.nativeApis.CLOCK.GET_CLOCK_HOURS()
        if hour >= 20 or hour <= 5 then
            menu.nativeApis.GRAPHICS.SET_ARTIFICIAL_LIGHTS_STATE(false)
            menu.nativeApis.GRAPHICS.DRAW_LIGHT_WITH_RANGE(-2000.0, 3000.0, 1500.0, 255, 255, 255, 10000.0, 100.0)
        end
    end
    if self.allGreenLights[playerId] then
        local now = menu.nativeApis.MISC.GET_GAME_TIMER()
        if now - (self.allGreenLightsLast[playerId] or 0) >= 500 then
            self.allGreenLightsLast[playerId] = now
            menu.nativeApis.VEHICLE.SET_ALL_VEHICLE_GENERATORS_ACTIVE()
            menu.nativeApis.VEHICLE.SET_ALL_VEHICLE_GENERATORS_ACTIVE_IN_AREA(10000, 10000, 10000, 10000, 10000, 10000, true, false)
        end
    end
    if self.chaosMode[playerId] then
        menu.nativeApis.MISC.SET_EXPLOSIVE_MELEE_THIS_FRAME(playerId)
        menu.nativeApis.MISC.SET_FIRE_AMMO_THIS_FRAME(playerId)
        menu.nativeApis.MISC.SET_EXPLOSIVE_AMMO_THIS_FRAME(playerId)
    end
    if self.invisibleWorld[playerId] then
        local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
        if ped and ped ~= 0 then
            local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(ped, true)
            menu.nativeApis.GRAPHICS.REMOVE_PARTICLE_FX_IN_RANGE(pos.x, pos.y, pos.z, 1000.0)
        end
    end
end

