    {
        hash = Utils.Joaat("entity_delete_execute"),
        name = "Delete entities",
        group = CONFIG.GROUPS.MISC,
        type = eFeatureType.Button,
        desc = "Works best on entities spawned by others",
        cb = function()
            local deleteType = EntityDeleteSettings.type or ENTITY_TYPE.VEHICLE
            local radius = EntityDeleteSettings.radius or 100
            local localPed = GTA.GetLocalPed()
            if not localPed then
                return
            end
            local localPos = localPed.Position
            local deletedCount = 0
            if deleteType == ENTITY_TYPE.VEHICLE or deleteType == ENTITY_TYPE.ALL then
                for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
                    local veh = PoolMgr.GetCVehicle(i)
                    if veh and veh:IsVehicle() then
                        if Utils1:V3Distance(localPos, veh.Position) <= radius then
                            NetworkObjectMgr.UnregisterNetworkObject(veh.NetObject, 8, true, true)
                            EntityManager:DeleteEntityLocal(GTA.PointerToHandle(veh))
                            deletedCount = deletedCount + 1
                        end
                    end
                end
            end
            if deleteType == ENTITY_TYPE.OBJECT or deleteType == ENTITY_TYPE.ALL then
                for i = 0, PoolMgr.GetMaxObjectCount() - 1 do
                    local obj = PoolMgr.GetCObject(i)
                    if obj and obj:IsObject() then
                        if Utils1:V3Distance(localPos, obj.Position) <= radius then
                            NetworkObjectMgr.UnregisterNetworkObject(obj.NetObject, 8, true, true)
                            EntityManager:DeleteEntityLocal(GTA.PointerToHandle(obj))
                            deletedCount = deletedCount + 1
                        end
                    end
                end
            end
            if deleteType == ENTITY_TYPE.PED or deleteType == ENTITY_TYPE.ALL then
                for i = 0, PoolMgr.GetMaxPedCount() - 1 do
                    local ped = PoolMgr.GetCPed(i)
                    if ped and ped:IsPed() and not ped:IsPlayer() then
                        if Utils1:V3Distance(localPos, ped.Position) <= radius then
                            NetworkObjectMgr.UnregisterNetworkObject(ped.NetObject, 8, true, true)
                            EntityManager:DeleteEntityLocal(GTA.PointerToHandle(ped))
                            deletedCount = deletedCount + 1
                        end
                    end
                end
            end
            Logger:Toast("Sovereign entity manager", string.format("Deleted %d entities", deletedCount), CONFIG.UI.ToastDuration.Short)
        end
    }
}

local function StopPlayerToggle(feature)
    if not feature then return end

    local stoppedSilently = false
    pcall(function()
        if type(feature.SetToggledSilently) == "function" then
            feature:SetToggledSilently(false)
            stoppedSilently = true
        end
    end)

    if not stoppedSilently then
        pcall(function()
            if feature:IsToggled() then
                feature:Toggle(false)
            end
        end)
    end

    pcall(function()
        local pid = feature:GetPlayerIndex()
        local hash = feature:GetHash()
        local state = pid ~= nil and menu.pstate(pid) or nil
        if state and hash then
            state["sovereign_" .. tostring(hash)] = false
        end
    end)
end

