                StopPlayerToggle(f)
                Logger:Toast("Sanctioned-user crash", "Do not use this on yourself", CONFIG.UI.ToastDuration.Short)
                return
            end

            local success, err = pcall(function()
                SyncNodeManager:SetState("CrashState", true)
                SyncNodeManager:SetState("G_Task_overflow", true)
                SyncNodeManager:SetState("GS_Heli_P", true)
                while f:IsToggled() do
