-- malua is my own test lua
-- So I just went ahead and used the mature features directly
(function()
local function maluaProbeModule()
    local _, _, moduleName = Utils1:editionInfo()
    return moduleName
end

-- Keep resolver/patch diagnostics out of the user-facing log; state failures still
-- surface through the short MK2 toast below.
local function maluaLogInfo(_) end
local function maluaLogError(_) end

local function maluaToast(message, long)
    if Logger and Logger.Toast then
        local duration = long and CONFIG.UI.ToastDuration.Long or CONFIG.UI.ToastDuration.Medium
        Logger:Toast("MK2", tostring(message), duration)
    end
end

local function maluaProbeHex(address, count)
    local bytes = {}
    for i = 0, count - 1 do
        local ok, value = pcall(Memory.ReadUByte, address + i)
        if not ok or value == nil then
            bytes[#bytes + 1] = "??"
        else
            bytes[#bytes + 1] = string.format("%02X", value)
        end
    end
    return table.concat(bytes, " ")
end

local function maluaReadS32(address)
    local value = Memory.ReadUInt(address)
    return value >= 0x80000000 and (value - 0x100000000) or value
end

local function maluaU32(value)
    return value < 0 and (value + 0x100000000) or value
end

local function maluaReadSectionName(address, fallback)
    local chars = {}
    for i = 0, 7 do
        local byte = Memory.ReadUByte(address + i)
        if byte == 0 then
            break
        end
        chars[#chars + 1] = string.char(byte)
    end
    local name = table.concat(chars)
    return name ~= "" and name or fallback
end

local function maluaModuleLayout()
    local moduleName = maluaProbeModule()
    if not moduleName then return nil, "GTA edition is unresolved" end
    local base = Memory.GetBaseAddress(moduleName)
    if not base or base == 0 then
        return nil, "module base is unavailable"
    end
    if Memory.ReadUShort(base) ~= 0x5A4D then return nil, "invalid DOS signature" end
    local peOffset = Memory.ReadUInt(base + 0x3C)
    if peOffset < 0x40 or peOffset > 0x1000 then
        return nil, "invalid PE header"
    end
    local nt = base + peOffset
    if Memory.ReadUInt(nt) ~= 0x4550 or Memory.ReadUShort(nt + 0x18) ~= 0x20B then
        return nil, "invalid PE64 signature"
    end
    local sectionCount = Memory.ReadUShort(nt + 0x06)
    local optionalSize = Memory.ReadUShort(nt + 0x14)
    local imageSize = Memory.ReadUInt(nt + 0x50)
    local timestamp = Memory.ReadUInt(nt + 0x08)
    if sectionCount == 0 or sectionCount > 96 or imageSize == 0 or optionalSize < 0x90 then
        return nil, "invalid PE layout"
    end

    local writable = {}
    local sections = {}
    local sectionTable = nt + 0x18 + optionalSize
    for i = 0, sectionCount - 1 do
        local section = sectionTable + i * 0x28
        local name = maluaReadSectionName(section, string.format("section_%02d", i))
        local virtualSize = Memory.ReadUInt(section + 0x08)
        local virtualAddress = Memory.ReadUInt(section + 0x0C)
        local rawSize = Memory.ReadUInt(section + 0x10)
        local rawPointer = Memory.ReadUInt(section + 0x14)
        local characteristics = Memory.ReadUInt(section + 0x24)
        local size = math.max(virtualSize, rawSize)
        if virtualAddress >= imageSize or size > imageSize - virtualAddress then
            return nil, "section outside module"
        end
        sections[#sections + 1] = {
            index = i,
            name = name,
            rva = virtualAddress,
            virtualSize = virtualSize,
            rawSize = rawSize,
            rawPointer = rawPointer,
            characteristics = characteristics,
            size = size,
            executable = (characteristics & 0x20000000) ~= 0,
            readable = (characteristics & 0x40000000) ~= 0,
            writable = (characteristics & 0x80000000) ~= 0,
        }
        if size > 0 and (characteristics & 0x80000000) ~= 0 then
            writable[#writable + 1] = {
                first = base + virtualAddress,
                last = base + virtualAddress + size,
            }
        end
    end
    return {
        base = base,
        moduleName = moduleName,
        imageSize = imageSize,
        timestamp = timestamp,
        exceptionRva = Memory.ReadUInt(nt + 0xA0),
        exceptionSize = Memory.ReadUInt(nt + 0xA4),
        headerSize = Memory.ReadUInt(nt + 0x54),
        sectionCount = sectionCount,
        sections = sections,
        writable = writable,
    }
end

local function maluaIsWritableModuleAddress(layout, address, size)
    size = size or 4
    if not layout or not address or address == 0 then
        return false
    end
    for _, range in ipairs(layout.writable) do
        if address >= range.first and address + size <= range.last then
            return true
        end
    end
    return false
end

local function maluaIsExecutableModuleAddress(layout, address, size)
    if not layout or type(address) ~= "number" then return false end
    size = size or 1
    for _, section in ipairs(layout.sections) do
        local first = layout.base + section.rva
        if section.executable and address >= first and address + size <= first + section.size then
            return true
        end
    end
    return false
end

local function maluaRuntimeFunction(layout, address)
    if not maluaIsExecutableModuleAddress(layout, address) then return nil end
    local rva, size = layout.exceptionRva, layout.exceptionSize
    if not rva or not size or rva == 0 or size < 12 or size % 12 ~= 0
        or rva + size > layout.imageSize then return nil end
    local low, high = 0, size // 12 - 1
    local relative = address - layout.base
    while low <= high do
        local mid = (low + high) // 2
        local record = layout.base + rva + mid * 12
        local first, last = Memory.ReadUInt(record), Memory.ReadUInt(record + 4)
        if relative < first then high = mid - 1
        elseif relative >= last then low = mid + 1
        else
            if first >= last or not maluaIsExecutableModuleAddress(layout, layout.base + first, last - first) then
                return nil
            end
            return layout.base + first, layout.base + last
        end
    end
    return nil
end

local function maluaResolveTargetReturnSites(layout, scan, name)
    local first, last = maluaRuntimeFunction(layout, scan)
    if not first or last - first > 0x3000 then return nil end
    local sites, counts, exitTarget = {}, {}, nil
    local function add(key, address, expected, patch, target)
        if target then
            if target < first or target + 8 > last then return end
            if exitTarget and exitTarget ~= target then return end
            exitTarget = target
        end
        counts[key] = (counts[key] or 0) + 1
        sites[#sites + 1] = {name = name .. ":" .. key, address = address,
            scan = scan, patch = patch, expected = expected}
    end
    for at = first, last - 10 do
        if layout.moduleName == "GTA5_Enhanced.exe" then
            if Memory.ReadUShort(at) == 0xF089 and Memory.ReadUInt(at + 2) == 0x2474280F then
                add("epilogue", at, {0x89, 0xF0},
                    name == "ShouldNotTargetEntity" and {0x31, 0xC0} or {0xB0, 0x01})
            end
        elseif name == "ShouldNotTargetEntity" then
            if Memory.ReadUByte(at) == 0xB8 and Memory.ReadUInt(at + 1) == 1
                and Memory.ReadUByte(at + 5) == 0xE9 then
                local target = at + 10 + maluaReadS32(at + 6)
                if target >= first and target + 8 < last
                    and Memory.ReadUInt(target) == 0x249C8D4C
                    and Memory.ReadUShort(target - 2) == 0xC032 then
                    add("constant_return", at + 1, {1, 0}, {0, 0}, target)
                end
            elseif Memory.ReadUShort(at) == 0x8A40 and Memory.ReadUByte(at + 2) == 0xC6
                and Memory.ReadUByte(at + 3) == 0xE9 then
                local target = at + 8 + maluaReadS32(at + 4)
                if target >= first and target + 8 < last
                    and Memory.ReadUInt(target) == 0x249C8D4C
                    and Memory.ReadUShort(target - 2) == 0xC032 then
                    add("computed_return", at + 1, {0x8A, 0xC6}, {0x31, 0xC0}, target)
                end
            end
        elseif Memory.ReadUShort(at) == 0xC032 and Memory.ReadUByte(at + 2) == 0xE9 then
            local target = at + 7 + maluaReadS32(at + 3)
            if target >= first and target + 8 < last
                and Memory.ReadUInt(target) == 0x245C8B48
                and Memory.ReadUShort(target - 2) == 0x01B0 then
                add("false_return", at, {0x32, 0xC0}, {0xB0, 0x01}, target)
            end
        end
    end
    if layout.moduleName == "GTA5_Enhanced.exe" then
        if counts.epilogue ~= 1 or #sites ~= 1 then return nil end
    elseif name == "ShouldNotTargetEntity" then
        if counts.constant_return ~= 1 or counts.computed_return ~= 1 or #sites ~= 2 then return nil end
    elseif counts.false_return ~= 1 or #sites ~= 1 then return nil end
    return sites
end

local function maluaWriteBytesVerified(address, bytes, phase)
    if #bytes == 4 then
        if type(Memory.WriteUInt) ~= "function" or type(Memory.ReadUInt) ~= "function" then
            error("32-bit Memory API is unavailable")
        end
        local packed = bytes[1] | (bytes[2] << 8) | (bytes[3] << 16) | (bytes[4] << 24)
        Memory.WriteUInt(address, packed)
        if Memory.ReadUInt(address) ~= packed then error((phase or "write") .. " verification failed") end
        return
    end
    if #bytes == 2 then
        if type(Memory.WriteUShort) ~= "function" or type(Memory.ReadUShort) ~= "function" then
            error("16-bit Memory API is unavailable")
        end
        local packed = (bytes[1] & 0xFF) | ((bytes[2] & 0xFF) << 8)
        Memory.WriteUShort(address, packed)
        if Memory.ReadUShort(address) ~= packed then
            error((phase or "write") .. " verification failed")
        end
        return
    end
    for index, byte in ipairs(bytes) do
        Memory.WriteUByte(address + index - 1, byte)
    end
    for index, byte in ipairs(bytes) do
        if Memory.ReadUByte(address + index - 1) ~= byte then
            error(string.format("%s verification failed at +0x%X", phase or "write", index - 1))
        end
    end
end

local function maluaPatchBytes(address, patch)
    local original = {}
    local readOk, readError = pcall(function()
        for i = 1, #patch do
            local value = Memory.ReadUByte(address + i - 1)
            if type(value) ~= "number" then error("original byte is unreadable") end
            original[i] = value
        end
    end)
    if not readOk then return nil, tostring(readError), false end
    local ok, err = pcall(function()
        maluaWriteBytesVerified(address, patch, "patch")
    end)
    if not ok then
        local rollbackOk, rollbackError = pcall(function()
            maluaWriteBytesVerified(address, original, "rollback")
        end)
        if rollbackOk then return nil, tostring(err), false end
        return original, string.format(
            "%s; rollback failed: %s", tostring(err), tostring(rollbackError)
        ), false
    end
    return original, nil, true
end

local maluaTryRead
local maluaNearFloat

local MALuaMK2PlayerLockPatch = {
    desired = false,
    active = false,
    restorePending = false,
    entries = nil,
    probeLogged = false,
    specs = {
        ["GTA5.exe"] = {
            {
                name = "ShouldNotTargetEntity",
                signature = "8B 81 A8 14 00 00 C1 E8 08 40 84 C6 74 ? 40 8A C6 E9",
            },
            {
                name = "ShouldAllowDriverLockOn",
                signature = "8B 82 48 14 00 00 C1 E8 1E 45 8B F0 48 8B FA 48 8B E9 A8 01 0F 84 ? ? ? ? F6 82 4C 14 00 00 01",
            },
        },
        ["GTA5_Enhanced.exe"] = {
            {
                name = "ShouldNotTargetEntity",
                signature = "F6 80 A9 14 00 00 01",
            },
            {
                name = "ShouldAllowDriverLockOn",
                signature = "75 ? 45 89 C7 49 89 CE",
            },
        },
    },
}

function MALuaMK2PlayerLockPatch:Enable()
    if self.active then return self.restorePending ~= true end
    -- The lock-on patch uses build-specific return sites.  Require the same
    -- exact Legacy/Enhanced mapping that the runtime patch bridge validates;
    -- a module name alone is not sufficient after an executable update.
    if not SovereignRuntimePatchBridge or type(SovereignRuntimePatchBridge.EnsureRuntime) ~= "function" then
        maluaLogError("[mALuaMK2Lock] exact Legacy/Enhanced mapping bridge unavailable; no bytes written")
        return false
    end
    local bridgeOk, mappingReady, mappingIdentity = pcall(
        SovereignRuntimePatchBridge.EnsureRuntime,
        SovereignRuntimePatchBridge
    )
    if not bridgeOk or mappingReady ~= true then
        maluaLogError("[mALuaMK2Lock] exact Legacy/Enhanced mapping rejected: " ..
            tostring(bridgeOk and mappingIdentity or mappingReady))
        return false
    end
    self.mappingIdentity = mappingIdentity
    local layout = maluaModuleLayout()
    if not layout then
        maluaLogError("[mALuaMK2Lock] module layout unavailable; no bytes written")
        return false
    end

    local specs = self.specs[layout.moduleName]
    if not specs then return false end
    local entries = {}
    for _, spec in ipairs(specs) do
        local scan = Memory.Scan(spec.signature, layout.moduleName)
        if not scan or scan == 0 or not maluaIsExecutableModuleAddress(layout, scan) then
            maluaLogError("[mALuaMK2Lock] " .. spec.name .. " signature not found; no bytes written")
            return false
        end
        local sites = maluaResolveTargetReturnSites(layout, scan, spec.name)
        if not sites then
            maluaLogError("[mALuaMK2Lock] " .. spec.name .. " return sites unresolved; no bytes written")
            return false
        end
        -- Preserve the function's timing/reference updates and stack cleanup.
        -- Only return-value producers leading to the validated epilogue change.
        for _, site in ipairs(sites) do
            for index, byte in ipairs(site.expected) do
                if Memory.ReadUByte(site.address + index - 1) ~= byte then return false end
            end
            for _, prior in ipairs(entries) do
                if prior.address == site.address then return false end
            end
            entries[#entries + 1] = site
        end
    end

    if not self.probeLogged then
        for _, entry in ipairs(entries) do
            maluaLogInfo(string.format(
                "[mALuaMK2LockProbe] %s rva=0x%X bytes=%s",
                entry.name, entry.address - layout.base, maluaProbeHex(entry.address, 0x80)
            ))
        end
        self.probeLogged = true
    end

    local applied = {}
    for _, entry in ipairs(entries) do
        local original, err, patchOk = maluaPatchBytes(entry.address, entry.patch)
        if patchOk ~= true then
            if original then
                entry.original = original
                applied[#applied + 1] = entry
            end
            self.entries = applied
            if #applied > 0 then
                self.active = true
                self.restorePending = true
                local restoreCallOk, restored = pcall(
                    MALuaMK2PlayerLockPatch.Disable,
                    MALuaMK2PlayerLockPatch
                )
                if not restoreCallOk or restored ~= true then
                    maluaLogError("[mALuaMK2Lock] failed transaction bytes remain pending for restore")
                end
            end
            maluaLogError(string.format(
                "[mALuaMK2Lock] %s patch failed; transaction rolled back: %s",
                entry.name, tostring(err)
            ))
            return false
        end
        entry.original = original
        applied[#applied + 1] = entry
    end

    self.entries = entries
    self.active = true
    self.restorePending = false
    local resolved = {}
    for _, entry in ipairs(entries) do
        resolved[#resolved + 1] = string.format("%s=0x%X", entry.name, entry.address - layout.base)
    end
    maluaLogInfo("[mALuaMK2Lock] enabled " .. table.concat(resolved, " "))
    return true
end

function MALuaMK2PlayerLockPatch:Refresh()
    if not self.active or not self.entries then return true end
    if self.restorePending then return false end
    local ok, err = pcall(function()
        for _, entry in ipairs(self.entries) do
            local needsRefresh = false
            for index, byte in ipairs(entry.patch) do
                local address = entry.address + index - 1
                local current = Memory.ReadUByte(address)
                if current ~= byte then
                    if current ~= entry.original[index] then
                        error(entry.name .. " patch bytes changed externally")
                    end
                    needsRefresh = true
                end
            end
            if needsRefresh then
                maluaWriteBytesVerified(entry.address, entry.patch, entry.name .. " patch refresh")
            end
        end
    end)
    if not ok then
        maluaLogError("[mALuaMK2Lock] refresh stopped: " .. tostring(err))
        return false
    end
    return true
end

function MALuaMK2PlayerLockPatch:Disable()
    if not self.active then return true end
    local restoreOk = true
    local ownershipLost = false
    local ok, err = pcall(function()
        for index = #(self.entries or {}), 1, -1 do
            local entry = self.entries[index]
            local current = {}
            local unknown = false
            for byteIndex, byte in ipairs(entry.patch) do
                local address = entry.address + byteIndex - 1
                local value = Memory.ReadUByte(address)
                local original = entry.original[byteIndex]
                current[byteIndex] = value
                if value ~= byte and value ~= original then unknown = true end
            end
            if unknown then
                ownershipLost = true
                maluaLogError("[mALuaMK2Lock] " .. entry.name
                    .. " instruction changed externally; full entry preserved")
            else
                local needsRestore = false
                for byteIndex, byte in ipairs(entry.patch) do
                    if current[byteIndex] == byte and byte ~= entry.original[byteIndex] then
                        needsRestore = true
                        break
                    end
                end
                if needsRestore then
                    maluaWriteBytesVerified(entry.address, entry.original, "restore")
                end
            end
        end
    end)
    if not ok then
        maluaLogError("[mALuaMK2Lock] restore failed: " .. tostring(err))
        return false
    end
    if not restoreOk then
        maluaLogError("[mALuaMK2Lock] targeting-byte restore incomplete; retrying")
        return false
    end
    self.active = false
    self.entries = nil
    self.restorePending = false
    if ownershipLost then
        maluaLogError("[mALuaMK2Lock] external targeting-byte change detected; ownership released")
        return false
    end
    maluaLogInfo("[mALuaMK2Lock] original targeting bytes restored")
    return true
end

local MALUA_MK2_GUIDANCE_FIELDS = {
    {offset = 0x178, kind = "float", name = "TimeBeforeHoming"},
    {offset = 0x17C, kind = "float", name = "TimeBeforeSwitchTargetMin"},
    {offset = 0x180, kind = "float", name = "TimeBeforeSwitchTargetMax"},
    {offset = 0x188, kind = "float", name = "PitchChangeRate"},
    {offset = 0x18C, kind = "float", name = "YawChangeRate"},
    {offset = 0x190, kind = "float", name = "RollChangeRate"},
    {offset = 0x194, kind = "float", name = "MaxRollAngleSin"},
    {offset = 0x198, kind = "float", name = "LifeTimePlayerVehicleLockedOverrideMP"},
    {offset = 0x19C, kind = "byte", name = "ShouldUseHomingParamsFromInfo"},
    {offset = 0x19D, kind = "byte", name = "ShouldIgnoreOwnerCombatBehaviour"},
    {offset = 0x1A0, kind = "float", name = "TimeBeforeStartingHoming"},
    {offset = 0x1A4, kind = "float", name = "TimeBeforeHomingAngleBreak"},
    {offset = 0x1A8, kind = "float", name = "TurnRateModifier"},
    {offset = 0x1AC, kind = "float", name = "PitchYawRollClamp"},
    {offset = 0x1B0, kind = "float", name = "DefaultHomingRocketBreakLockAngle"},
    {offset = 0x1B4, kind = "float", name = "DefaultHomingRocketBreakLockAngleClose"},
    {offset = 0x1B8, kind = "float", name = "DefaultHomingRocketBreakLockCloseDistance"},
}

local function maluaReadGuidanceField(address, field)
    if field.kind == "byte" then
        return Memory.ReadUByte(address + field.offset)
    end
    return Memory.ReadFloat(address + field.offset)
end

local function maluaWriteGuidanceField(address, field, value)
    if field.kind == "byte" then
        Memory.WriteUByte(address + field.offset, value)
    else
        Memory.WriteFloat(address + field.offset, value)
    end
end

local function maluaGuidanceLayoutLooksValid(ammo)
    if not ammo or ammo == 0 then
        return false
    end
    local ok, valid = pcall(function()
        local useInfo = Memory.ReadUByte(ammo + 0x19C)
        local ignoreOwner = Memory.ReadUByte(ammo + 0x19D)
        if useInfo > 1 or ignoreOwner > 1 then return false end
        for _, offset in ipairs({0x178, 0x188, 0x18C, 0x190, 0x1A8, 0x1AC, 0x1B0, 0x1B4, 0x1B8}) do
            local value = Memory.ReadFloat(ammo + offset)
            if value ~= value or math.abs(value) > 100000.0 then return false end
        end
        return true
    end)
    return ok and valid
end

local MALuaMK2GuidanceProbeLogged = false

local function maluaPointerLooksValid(value)
    return type(value) == "number" and value >= 0x10000 and value < 0x0000800000000000
end

maluaTryRead = function(reader, address)
    if not maluaPointerLooksValid(address) then return nil end
    local ok, value = pcall(reader, address)
    if not ok then return nil end
    return value
end

local function maluaReadAtArray(header, maxCount)
    local items = maluaTryRead(Memory.ReadLong, header)
    local count = maluaTryRead(Memory.ReadUShort, header + 0x08)
    local capacity = maluaTryRead(Memory.ReadUShort, header + 0x0A)
    if not maluaPointerLooksValid(items) or (items & 0x07) ~= 0
        or not count or count == 0 or count > maxCount
        or not capacity or capacity < count or capacity > maxCount * 2 then
        return nil
    end
    return items, count, capacity
end

local function maluaResolveAmmoPair(layout, mk2Weapon, deluxoWeapon)
    -- AmmoInfo is +0x60 in the legacy layout. Probe nearby pointer fields so a
    -- small Enhanced structure shift does not require a new hard-coded RVA.
    for _, offset in ipairs({0x60, 0x58, 0x68, 0x70, 0x50, 0x78, 0x80, 0x88, 0x90}) do
        local mk2Ammo = maluaTryRead(Memory.ReadLong, mk2Weapon + offset)
        local deluxoAmmo = maluaTryRead(Memory.ReadLong, deluxoWeapon + offset)
        if maluaPointerLooksValid(mk2Ammo)
            and maluaPointerLooksValid(deluxoAmmo)
            and mk2Ammo ~= deluxoAmmo
            and maluaGuidanceLayoutLooksValid(mk2Ammo)
            and maluaGuidanceLayoutLooksValid(deluxoAmmo) then
            local mk2Vtable = maluaTryRead(Memory.ReadLong, mk2Ammo)
            local deluxoVtable = maluaTryRead(Memory.ReadLong, deluxoAmmo)
            if mk2Vtable and deluxoVtable
                and mk2Vtable >= layout.base and mk2Vtable < layout.base + layout.imageSize
                and deluxoVtable >= layout.base and deluxoVtable < layout.base + layout.imageSize then
                return mk2Ammo, deluxoAmmo, offset
            end
        end
    end
    return nil
end

local function maluaDecodeWeaponLookupRip(address)
    local b0 = maluaTryRead(Memory.ReadUByte, address)
    local b1 = maluaTryRead(Memory.ReadUByte, address + 1)
    local b2 = maluaTryRead(Memory.ReadUByte, address + 2)
    if not b0 or not b1 or not b2 then return nil end

    local dispAt, length, kind
    if b0 == 0x0F and b1 == 0xB7 and (b2 & 0xC7) == 0x05 then
        dispAt, length, kind = address + 3, 7, "count16"
    elseif b0 >= 0x40 and b0 <= 0x4F and b1 == 0x0F and b2 == 0xB7 then
        local modrm = maluaTryRead(Memory.ReadUByte, address + 3)
        if modrm and (modrm & 0xC7) == 0x05 then
            dispAt, length, kind = address + 4, 8, "count16"
        end
    elseif b0 == 0x8B and (b1 & 0xC7) == 0x05 then
        dispAt, length, kind = address + 2, 6, "count32"
    elseif b0 >= 0x40 and b0 <= 0x4F and b1 == 0x8B and (b2 & 0xC7) == 0x05 then
        dispAt, length = address + 3, 7
        kind = (b0 & 0x08) ~= 0 and "pointer" or "count32"
    elseif b0 >= 0x48 and b0 <= 0x4F and b1 == 0x8D and (b2 & 0xC7) == 0x05 then
        dispAt, length, kind = address + 3, 7, "direct"
    end
    if not dispAt then return nil end
    return address + length + maluaReadS32(dispAt), kind
end

local function maluaFindWeaponPairInList(layout, listBase, count)
    if not maluaPointerLooksValid(listBase) or count < 2 or count > 8192 then return nil end

    local plausible = 0
    for index = 0, math.min(count - 1, 63) do
        local info = maluaTryRead(Memory.ReadLong, listBase + index * 0x08)
        if maluaPointerLooksValid(info) then
            local vtable = maluaTryRead(Memory.ReadLong, info)
            local nameHash = maluaTryRead(Memory.ReadUInt, info + 0x10)
            if vtable and vtable >= layout.base and vtable < layout.base + layout.imageSize
                and nameHash and nameHash ~= 0 then
                plausible = plausible + 1
            end
        end
    end
    if plausible < 2 then return nil end

    local wanted = {
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_OPPRESSOR2_MISSILE"))] = "mk2",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_DELUXO_MISSILE"))] = "deluxo",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_CHERNO_MISSILE"))] = "Chernobog",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_RUINER_ROCKET"))] = "ruiner",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_TANK"))] = "tank",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_KHANJALI_CANNON"))] = "khanjali",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_KHANJALI_CANNON_HEAVY"))] = "khanjaliHeavy",
    }
    local found = {}
    for index = 0, count - 1 do
        local info = maluaTryRead(Memory.ReadLong, listBase + index * 0x08)
        if maluaPointerLooksValid(info) then
            for _, nameOffset in ipairs({0x10, 0x18}) do
                local nameHash = maluaTryRead(Memory.ReadUInt, info + nameOffset)
                local key = nameHash and wanted[maluaU32(nameHash)]
                if key then found[key] = info end
            end
        end
    end
    if not found.mk2 or not found.deluxo then return nil end

    local mk2Ammo, deluxoAmmo, ammoOffset = maluaResolveAmmoPair(layout, found.mk2, found.deluxo)
    if not mk2Ammo then return nil end
    local chernobogAmmo, _, chernobogAmmoOffset = nil, nil, nil
    local ruinerAmmo, _, ruinerAmmoOffset = nil, nil, nil
    if found.Chernobog then
        local resolvedMk2, resolvedAmmo, resolvedOffset = maluaResolveAmmoPair(layout, found.mk2, found.Chernobog)
        if resolvedMk2 then chernobogAmmo, chernobogAmmoOffset = resolvedAmmo, resolvedOffset end
    end
    if found.ruiner then
        local resolvedMk2, resolvedAmmo, resolvedOffset = maluaResolveAmmoPair(layout, found.mk2, found.ruiner)
        if resolvedMk2 then ruinerAmmo, ruinerAmmoOffset = resolvedAmmo, resolvedOffset end
    end
    return {
        weaponCount = count,
        mk2Weapon = found.mk2,
        deluxoWeapon = found.deluxo,
        mk2Ammo = mk2Ammo,
        deluxoAmmo = deluxoAmmo,
        chernobogWeapon = found.Chernobog,
        chernobogAmmo = chernobogAmmo,
        chernobogAmmoOffset = chernobogAmmoOffset,
        ruinerWeapon = found.ruiner,
        ruinerAmmo = ruinerAmmo,
        ruinerAmmoOffset = ruinerAmmoOffset,
        tankWeapon = found.tank,
        khanjaliWeapon = found.khanjali,
        khanjaliHeavyWeapon = found.khanjaliHeavy,
        ammoOffset = ammoOffset,
    }
end

local function maluaResolveWeaponArray(layout)
    local signatures = {
        ["GTA5.exe"] = {
            count = "44 0F B7 0D ? ? ? ? 41 8B DF 41 FF C9 78 ? 48 8B 35", countRip = 4,
            list = "48 8B 35 ? ? ? ? 41 8D 14 19 D1 FA 48 8B 0C D6 44 3B 51 10", listRip = 3,
        },
        ["GTA5_Enhanced.exe"] = {
            count = "0F B7 15 ? ? ? ? 31 F6 85 D2 74 34 FF CA", countRip = 3,
            list = "4C 8B 0D ? ? ? ? EB 08 FF C0 89 C6 39 D6", listRip = 3,
        },
    }
    local spec = signatures[layout.moduleName]
    if not spec then return nil end
    local countScan = Memory.Scan(spec.count, layout.moduleName)
    local listScan = Memory.Scan(spec.list, layout.moduleName)
    local countFunction = countScan and maluaRuntimeFunction(layout, countScan)
    local listFunction = listScan and maluaRuntimeFunction(layout, listScan)
    if not countFunction or countFunction ~= listFunction then return nil end
    local countAddress = Memory.Rip(countScan + spec.countRip)
    local listAddress = Memory.Rip(listScan + spec.listRip)
    if type(listAddress) ~= "number" or countAddress ~= listAddress + 8
        or not maluaIsWritableModuleAddress(layout, listAddress, 12) then return nil end
    local items, count = maluaReadAtArray(listAddress, 8192)
    return {
        items = items, count = count, global = listAddress,
        countGlobal = countAddress, scan = listScan,
    }
end

local function maluaResolveWeaponListPair(layout)
    -- Enhanced keeps the sorted CWeaponInfo array and its count next to the
    -- driver-lock predicate. Resolve those RIP globals from the predicate's
    -- current code instead of walking legacy blob layouts.
    local arrayOk, array = pcall(maluaResolveWeaponArray, layout)
    if arrayOk and array then
        if array.items then
            local pair = maluaFindWeaponPairInList(layout, array.items, array.count)
            if pair then
                pair.scan = array.scan
                pair.resolver = "driver_lock_weapon_array"
                pair.global = array.global
                pair.countGlobal = array.countGlobal
                return pair
            end
            return nil, "driver lock weapon array pair is not initialized", array.scan
        end
        return nil, "driver lock weapon array globals are not initialized", array.scan
    end

    -- Enhanced changes register allocation and branch size across builds. Use
    -- the lookup-loop shape only as an anchor, then decode its RIP references.
    local signatures = {
        {name = "test_eax_jz_movzx8", pattern = "85 C0 74 ? 44 0F B7 ? ? ? ? ?"},
        {name = "test_eax_jz_movzx", pattern = "85 C0 74 ? 0F B7 ? ? ? ? ?"},
        {name = "test_eax_jz32_movzx8", pattern = "85 C0 0F 84 ? ? ? ? 44 0F B7 ? ? ? ? ?"},
        {name = "test_eax_jz32_movzx", pattern = "85 C0 0F 84 ? ? ? ? 0F B7 ? ? ? ? ?"},
        {name = "test_reg_jz_movzx8", pattern = "85 ? 74 ? 44 0F B7 ? ? ? ? ?"},
        {name = "test_reg_jz32_movzx8", pattern = "85 ? 0F 84 ? ? ? ? 44 0F B7 ? ? ? ? ?"},
        {name = "test_eax_jz_mov32", pattern = "85 C0 74 ? 8B ? ? ? ? ?"},
        {name = "test_eax_jz32_mov32", pattern = "85 C0 0F 84 ? ? ? ? 8B ? ? ? ? ?"},
    }
    local anchors, seenAnchors = {}, {}
    for _, signature in ipairs(signatures) do
        local moduleName = maluaProbeModule()
        if not moduleName then return nil, "GTA edition is unresolved" end
        local ok, scan = pcall(Memory.Scan, signature.pattern, moduleName)
        if ok and scan and scan ~= 0 and not seenAnchors[scan] then
            seenAnchors[scan] = true
            anchors[#anchors + 1] = {name = signature.name, address = scan}
        end
    end
    if #anchors == 0 then return nil, "weapon lookup semantic anchors were not found" end

    local countRefs, listRefs, seenCounts, seenLists = {}, {}, {}, {}
    for _, anchor in ipairs(anchors) do
        local first = math.max(layout.base, anchor.address - 0x20)
        local last = math.min(layout.base + layout.imageSize - 8, anchor.address + 0x200)
        for instruction = first, last do
            local ok, target, kind = pcall(maluaDecodeWeaponLookupRip, instruction)
            if ok and target and maluaIsWritableModuleAddress(layout, target, kind == "count16" and 2 or 4) then
                if kind == "count16" or kind == "count32" then
                    local value = kind == "count16"
                        and maluaTryRead(Memory.ReadUShort, target)
                        or maluaTryRead(Memory.ReadUInt, target)
                    if value and value >= 2 and value <= 8192 and not seenCounts[target] then
                        seenCounts[target] = true
                        countRefs[#countRefs + 1] = {address = target, value = value, anchor = anchor}
                    end
                elseif (kind == "pointer" or kind == "direct") and not seenLists[target] then
                    seenLists[target] = true
                    listRefs[#listRefs + 1] = {address = target, direct = kind == "direct", anchor = anchor}
                end
            end
        end
    end

    for _, countRef in ipairs(countRefs) do
        for _, listRef in ipairs(listRefs) do
            local listBase = listRef.direct and listRef.address or maluaTryRead(Memory.ReadLong, listRef.address)
            local pair = maluaFindWeaponPairInList(layout, listBase, countRef.value)
            if pair then
                pair.scan = countRef.anchor.address
                pair.resolver = "weapon_list_semantic"
                pair.global = listRef.address
                return pair
            end
        end
    end

    local hitText = {}
    for _, anchor in ipairs(anchors) do
        hitText[#hitText + 1] = string.format("%s@0x%X", anchor.name, anchor.address - layout.base)
    end
    return nil, string.format(
        "weapon lookup candidates failed anchors=%d counts=%d lists=%d hits=[%s]",
        #anchors, #countRefs, #listRefs, table.concat(hitText, ",")
    ), anchors[1].address
end

local function maluaSearchWeaponBlobHeader(layout, header, budget)
    local blobBase, blobCount = maluaReadAtArray(header, 512)
    if not blobBase then return nil end

    local wanted = {
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_OPPRESSOR2_MISSILE"))] = "mk2",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_DELUXO_MISSILE"))] = "deluxo",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_CHERNO_MISSILE"))] = "Chernobog",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_RUINER_ROCKET"))] = "ruiner",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_TANK"))] = "tank",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_KHANJALI_CANNON"))] = "khanjali",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_KHANJALI_CANNON_HEAVY"))] = "khanjaliHeavy",
    }
    local layouts = {
        {stride = 0xF8, list = 0x90},
        {stride = 0xF8, list = 0x88},
        {stride = 0xF8, list = 0x98},
        {stride = 0x100, list = 0x90},
        {stride = 0x100, list = 0x98},
        {stride = 0x108, list = 0x98},
        {stride = 0x110, list = 0xA0},
    }

    for _, blobLayout in ipairs(layouts) do
        local found = {}
        for blobIndex = 0, blobCount - 1 do
            local blob = blobBase + blobIndex * blobLayout.stride
            for listIndex = 0, 3 do
                local list = blob + blobLayout.list + listIndex * 0x10
                local items, count = maluaReadAtArray(list, 8192)
                if items then
                    for itemIndex = 0, count - 1 do
                        budget.visits = budget.visits + 1
                        if budget.visits > budget.max then return nil, "visit budget exhausted" end
                        local info = maluaTryRead(Memory.ReadLong, items + itemIndex * 0x08)
                        if maluaPointerLooksValid(info) then
                            for _, nameOffset in ipairs({0x10, 0x18}) do
                                local nameHash = maluaTryRead(Memory.ReadUInt, info + nameOffset)
                                local key = nameHash and wanted[maluaU32(nameHash)]
                                if key then found[key] = info end
                            end
                        end
                    end
                end
            end
        end
        if found.mk2 and found.deluxo then
            local mk2Ammo, deluxoAmmo, ammoOffset = maluaResolveAmmoPair(layout, found.mk2, found.deluxo)
            if mk2Ammo then
                local chernobogAmmo, chernobogAmmoOffset
                if found.Chernobog then
                    local _, resolvedAmmo, resolvedOffset = maluaResolveAmmoPair(layout, found.mk2, found.Chernobog)
                    chernobogAmmo, chernobogAmmoOffset = resolvedAmmo, resolvedOffset
                end
                local ruinerAmmo, ruinerAmmoOffset
                if found.ruiner then
                    local _, resolvedAmmo, resolvedOffset = maluaResolveAmmoPair(layout, found.mk2, found.ruiner)
                    ruinerAmmo, ruinerAmmoOffset = resolvedAmmo, resolvedOffset
                end
                return {
                    global = header,
                    blobBase = blobBase,
                    blobCount = blobCount,
                    blobStride = blobLayout.stride,
                    listOffset = blobLayout.list,
                    ammoOffset = ammoOffset,
                    mk2Weapon = found.mk2,
                    deluxoWeapon = found.deluxo,
                    mk2Ammo = mk2Ammo,
                    deluxoAmmo = deluxoAmmo,
                    chernobogWeapon = found.Chernobog,
                    chernobogAmmo = chernobogAmmo,
                    chernobogAmmoOffset = chernobogAmmoOffset,
                    ruinerWeapon = found.ruiner,
                    ruinerAmmo = ruinerAmmo,
                    ruinerAmmoOffset = ruinerAmmoOffset,
                    tankWeapon = found.tank,
                    khanjaliWeapon = found.khanjali,
                    khanjaliHeavyWeapon = found.khanjaliHeavy,
                }
            end
        end
    end
    return nil
end

local function maluaDecodeRipReference(address)
    local b0 = maluaTryRead(Memory.ReadUByte, address)
    local b1 = maluaTryRead(Memory.ReadUByte, address + 1)
    local b2 = maluaTryRead(Memory.ReadUByte, address + 2)
    if not b0 or not b1 or not b2 then return nil end

    local dispAt, length
    if b0 >= 0x40 and b0 <= 0x4F
        and (b1 == 0x8B or b1 == 0x8D or b1 == 0x89)
        and (b2 & 0xC7) == 0x05 then
        dispAt, length = address + 3, 7
    elseif (b0 == 0x8B or b0 == 0x8D or b0 == 0x89)
        and (b1 & 0xC7) == 0x05 then
        dispAt, length = address + 2, 6
    elseif b0 == 0x0F and (b1 == 0xB6 or b1 == 0xB7)
        and (b2 & 0xC7) == 0x05 then
        dispAt, length = address + 3, 7
    elseif b0 == 0xF3 and b1 == 0x0F
        and (b2 == 0x10 or b2 == 0x11) then
        local modrm = maluaTryRead(Memory.ReadUByte, address + 3)
        if modrm and (modrm & 0xC7) == 0x05 then
            dispAt, length = address + 4, 8
        end
    end
    if not dispAt then return nil end
    return address + length + maluaReadS32(dispAt)
end

local function maluaResolveWeaponInfoPair()
    local layout, layoutError = maluaModuleLayout()
    if not layout then return nil, layoutError end

    local listOk, listPair, listError, listScan = pcall(maluaResolveWeaponListPair, layout)
    if listOk and listPair then
        if not MALuaMK2GuidanceProbeLogged then
            maluaLogInfo(string.format(
                "[mALuaMK2GuidanceProbe] resolved=%s rva=0x%X count=%d ammo=+0x%X mk2=0x%X deluxo=0x%X chernobogAmmo=%s ruinerAmmo=%s global=0x%X count_global=0x%X",
                tostring(listPair.resolver),
                listPair.scan - layout.base, listPair.weaponCount, listPair.ammoOffset,
                listPair.mk2Weapon, listPair.deluxoWeapon,
                tostring(listPair.chernobogAmmo), tostring(listPair.ruinerAmmo),
                listPair.global or 0, listPair.countGlobal or 0
            ))
            MALuaMK2GuidanceProbeLogged = true
        end
        return listPair
    end
    if listOk and listScan and listError
        and string.find(tostring(listError), "driver lock weapon array", 1, true) then
        if not MALuaMK2GuidanceProbeLogged then
            maluaLogInfo(string.format(
                "[mALuaMK2GuidanceProbe] direct weapon array pending rva=0x%X reason=%s",
                listScan - layout.base, tostring(listError)
            ))
            MALuaMK2GuidanceProbeLogged = true
        end
        return nil, listError
    end
    if not listOk then
        listError, listScan = listPair, nil
    end

    local signatures = {
        {name = "legacy_rdi", pattern = "48 8B 3D ? ? ? ? F3 0F 10 0D ? ? ? ? 45 33 D2", directRip = 3},
        {name = "legacy_rsi", pattern = "48 8B 35 ? ? ? ? F3 0F 10 0D ? ? ? ? 45 33 D2", directRip = 3},
        {name = "blob_count_dec", pattern = "FF CD 0F B7 05 ? ? ? ?", countRip = 5},
        {name = "blob_count_call", pattern = "E8 ? ? ? ? FF CD 0F B7 05 ? ? ? ?", countRip = 10},
        {name = "op2_cmp_eax", pattern = "3D F1 78 3A 75"},
        {name = "op2_cmp_reg", pattern = "81 ? F1 78 3A 75"},
        {name = "op2_mov", pattern = "B8 F1 78 3A 75"},
        {name = "op2_mov_rex", pattern = "41 B8 F1 78 3A 75"},
    }
    local anchors, headers, seenAnchors, seenHeaders = {}, {}, {}, {}
    local function addAnchor(name, address)
        if address and address >= layout.base and address < layout.base + layout.imageSize
            and not seenAnchors[address] then
            seenAnchors[address] = true
            anchors[#anchors + 1] = {name = name, address = address}
        end
    end
    local function addHeader(address, reason, anchor)
        if address and maluaIsWritableModuleAddress(layout, address, 0x10) and not seenHeaders[address] then
            seenHeaders[address] = true
            headers[#headers + 1] = {address = address, reason = reason, anchor = anchor}
        end
    end

    for _, candidate in ipairs(signatures) do
        local moduleName = maluaProbeModule()
        if not moduleName then return nil, "GTA edition is unresolved" end
        local ok, scan = pcall(Memory.Scan, candidate.pattern, moduleName)
        if ok and scan and scan ~= 0 then
            addAnchor(candidate.name, scan)
            if candidate.directRip then
                local ripOk, target = pcall(Memory.Rip, scan + candidate.directRip)
                if ripOk then addHeader(target, candidate.name .. ":direct", scan) end
            end
            if candidate.countRip then
                local ripOk, countAddress = pcall(Memory.Rip, scan + candidate.countRip)
                if ripOk and countAddress then
                    addHeader(countAddress - 0x08, candidate.name .. ":count-8", scan)
                    addHeader(countAddress - 0x10, candidate.name .. ":count-10", scan)
                end
            end
        end
    end

    -- The OP2 immediate lives in CalcHomingProjectileInputs. Follow its nearby
    -- direct calls one level so the weapon-info lookup callee can contribute
    -- its own RIP-relative manager/blob globals.
    local directAnchorCount = #anchors
    for index = 1, directAnchorCount do
        local source = anchors[index]
        local first = math.max(layout.base, source.address - 0x100)
        local last = math.min(layout.base + layout.imageSize - 5, source.address + 0x80)
        for instruction = first, last do
            if maluaTryRead(Memory.ReadUByte, instruction) == 0xE8 then
                local target = instruction + 5 + maluaReadS32(instruction + 1)
                if target >= layout.base and target < layout.base + layout.imageSize then
                    addAnchor(source.name .. ":call", target)
                    if #anchors >= 32 then break end
                end
            end
        end
        if #anchors >= 32 then break end
    end

    -- Collect writable RIP-relative globals around semantic anchors. Header
    -- neighbours cover layouts where the pointer and count are separate globals.
    for _, anchor in ipairs(anchors) do
        local first = math.max(layout.base, anchor.address - 0x100)
        local last = math.min(layout.base + layout.imageSize - 8, anchor.address + 0x180)
        for instruction = first, last do
            local ok, target = pcall(maluaDecodeRipReference, instruction)
            if ok and target and maluaIsWritableModuleAddress(layout, target, 1) then
                for delta = -0x20, 0x20, 0x08 do
                    addHeader(target + delta, anchor.name .. string.format(":rip%+d", delta), anchor.address)
                end
            end
        end
    end

    local totalVisits, exhaustedCandidates = 0, 0
    local totalVisitLimit = 600000
    for _, candidate in ipairs(headers) do
        if totalVisits >= totalVisitLimit then break end
        local budget = {visits = 0, max = math.min(15000, totalVisitLimit - totalVisits)}
        local ok, pair, searchError = pcall(maluaSearchWeaponBlobHeader, layout, candidate.address, budget)
        totalVisits = totalVisits + budget.visits
        if ok and pair then
            pair.scan = candidate.anchor or anchors[1].address
            pair.resolver = candidate.reason
            if not MALuaMK2GuidanceProbeLogged then
                maluaLogInfo(string.format(
                    "[mALuaMK2GuidanceProbe] resolved=%s header=0x%X count=%d stride=0x%X list=0x%X ammo=+0x%X visits=%d",
                    pair.resolver, pair.global, pair.blobCount, pair.blobStride,
                    pair.listOffset, pair.ammoOffset, totalVisits
                ))
                MALuaMK2GuidanceProbeLogged = true
            end
            return pair
        end
        if searchError == "visit budget exhausted" then
            exhaustedCandidates = exhaustedCandidates + 1
        end
    end

    if not MALuaMK2GuidanceProbeLogged then
        local anchorText = {}
        for _, anchor in ipairs(anchors) do
            anchorText[#anchorText + 1] = string.format("%s@0x%X", anchor.name, anchor.address - layout.base)
        end
        maluaLogInfo(string.format(
            "[mALuaMK2GuidanceProbe] unresolved weaponList=%s listRva=%s anchors=%d headers=%d visits=%d exhausted=%d hits=[%s]",
            tostring(listError),
            listScan and string.format("0x%X", listScan - layout.base) or "nil",
            #anchors, #headers, totalVisits, exhaustedCandidates, table.concat(anchorText, ",")
        ))
        if listScan then
            local ok, context = pcall(maluaProbeHex, listScan - 0x10, 0x70)
            if ok then
                maluaLogInfo(string.format(
                    "[mALuaMK2GuidanceProbe] weapon_list rva=0x%X context=%s",
                    listScan - layout.base, context
                ))
            end
        end
        for i = 1, math.min(#anchors, 4) do
            local anchor = anchors[i]
            local ok, context = pcall(maluaProbeHex, anchor.address - 0x10, 0x50)
            if ok then
                maluaLogInfo(string.format(
                    "[mALuaMK2GuidanceProbe] %s rva=0x%X context=%s",
                    anchor.name, anchor.address - layout.base, context
                ))
            end
        end
        MALuaMK2GuidanceProbeLogged = true
    end
    return nil, string.format(
        "weapon info unresolved (weaponList=%s anchors=%d headers=%d visits=%d)",
        tostring(listError), #anchors, #headers, totalVisits
    )
end

-- Resolve only the weapon objects required by the caller.  The old resolver
-- always required the MK2/Deluxo guidance pair, which made tank and flags
-- patches fail or select an unrelated partially initialized blob.
local maluaLegacyResolveWeaponInfoPair = maluaResolveWeaponInfoPair
local function maluaFindWeaponPairForMode(layout, listBase, count, mode)
    if not layout or not maluaPointerLooksValid(listBase)
        or type(count) ~= "number" or count < 2 or count > 8192 then
        return nil
    end

    local wanted = {
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_OPPRESSOR2_MISSILE"))] = "mk2",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_DELUXO_MISSILE"))] = "deluxo",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_CHERNO_MISSILE"))] = "chernobog",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_RUINER_ROCKET"))] = "ruiner",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_TANK"))] = "tank",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_KHANJALI_CANNON"))] = "khanjali",
        [maluaU32(Utils.Joaat("VEHICLE_WEAPON_KHANJALI_CANNON_HEAVY"))] = "khanjaliHeavy",
    }
    local found = {}
    local plausible = 0
    for index = 0, count - 1 do
        local info = maluaTryRead(Memory.ReadLong, listBase + index * 0x08)
        if maluaPointerLooksValid(info) then
            local vtable = maluaTryRead(Memory.ReadLong, info)
            if vtable and vtable >= layout.base and vtable < layout.base + layout.imageSize then
                plausible = plausible + 1
                for _, nameOffset in ipairs({0x10, 0x18}) do
                    local nameHash = maluaTryRead(Memory.ReadUInt, info + nameOffset)
                    local key = nameHash and wanted[maluaU32(nameHash)]
                    if key then found[key] = info end
                end
            end
        end
    end
    if plausible < 2 then return nil end

    if mode == "tank" then
        if not found.tank or not found.khanjali or not found.khanjaliHeavy then return nil end
        return {
            weaponCount = count,
            tankWeapon = found.tank,
            khanjaliWeapon = found.khanjali,
            khanjaliHeavyWeapon = found.khanjaliHeavy,
        }
    elseif mode == "flags" then
        if not found.mk2 or not found.deluxo then return nil end
        return {
            weaponCount = count,
            mk2Weapon = found.mk2,
            deluxoWeapon = found.deluxo,
        }
    end

    if not found.mk2 or not found.deluxo then return nil end
    local mk2Ammo, deluxoAmmo, ammoOffset = maluaResolveAmmoPair(
        layout, found.mk2, found.deluxo
    )
    if not mk2Ammo then return nil end
    local chernobogAmmo, chernobogAmmoOffset
    local ruinerAmmo, ruinerAmmoOffset
    if found.chernobog then
        local _, ammo, offset = maluaResolveAmmoPair(layout, found.mk2, found.chernobog)
        chernobogAmmo, chernobogAmmoOffset = ammo, offset
    end
    if found.ruiner then
        local _, ammo, offset = maluaResolveAmmoPair(layout, found.mk2, found.ruiner)
        ruinerAmmo, ruinerAmmoOffset = ammo, offset
    end
    return {
        weaponCount = count,
        mk2Weapon = found.mk2,
        deluxoWeapon = found.deluxo,
        mk2Ammo = mk2Ammo,
        deluxoAmmo = deluxoAmmo,
        chernobogWeapon = found.chernobog,
        chernobogAmmo = chernobogAmmo,
        chernobogAmmoOffset = chernobogAmmoOffset,
        ruinerWeapon = found.ruiner,
        ruinerAmmo = ruinerAmmo,
        ruinerAmmoOffset = ruinerAmmoOffset,
        tankWeapon = found.tank,
        khanjaliWeapon = found.khanjali,
        khanjaliHeavyWeapon = found.khanjaliHeavy,
        ammoOffset = ammoOffset,
    }
end

function maluaResolveWeaponInfoPair(mode)
    local layout, layoutError = maluaModuleLayout()
    if not layout then return nil, layoutError end

    local arrayOk, array = pcall(maluaResolveWeaponArray, layout)
    if arrayOk and array then
        local pair = maluaFindWeaponPairForMode(layout, array.items, array.count, mode)
        if pair then
            pair.scan = array.scan
            pair.resolver = "driver_lock_weapon_array_mode"
            pair.global = array.global
            pair.countGlobal = array.countGlobal
            return pair
        end
        return nil, "driver lock weapon array objects are not initialized", array.scan
    end

    -- Keep the existing semantic/blob fallback, but still enforce the mode's
    -- required objects before a caller is allowed to write memory.
    local ok, pair, err, scan = pcall(maluaLegacyResolveWeaponInfoPair)
    if not ok then return nil, tostring(pair) end
    if pair then
        local valid = mode == nil
            or (mode == "flags" and pair.mk2Weapon and pair.deluxoWeapon)
            or (mode == "tank" and pair.tankWeapon and pair.khanjaliWeapon
                and pair.khanjaliHeavyWeapon)
        if valid then return pair, err, scan end
        return nil, "resolved weapon pair does not satisfy mode=" .. tostring(mode), scan
    end
    return nil, err, scan
end

local MALUA_MK2_DRIVER_PED_FLAG = 61
local MALUA_MK2_DRIVER_PED_MASK = 0x20000000

local function maluaReadWeaponFlagsCandidate(weapon, offset)
    local ok, d0, d1, d2 = pcall(function()
        return Memory.ReadUInt(weapon + offset),
            Memory.ReadUInt(weapon + offset + 0x04),
            Memory.ReadUInt(weapon + offset + 0x08)
    end)
    if not ok then return nil end

    -- Vehicle missiles must have CanLockonInVehicle (bit 8), Homing (bit 9)
    -- and Vehicle (bit 46). Requiring all three keeps the layout probe from
    -- treating ordinary floats or pointers as the WeaponFlags bitset.
    if (d0 & 0x00000100) == 0
        or (d0 & 0x00000200) == 0
        or (d1 & 0x00004000) == 0 then
        return nil
    end
    return {d0 = d0, d1 = d1, d2 = d2}
end

local function maluaResolveWeaponFlagsOffset(pair)
    local preferred = {0x900, 0x8C8, 0x918, 0x8E0, 0x930}
    local tested = {}
    local function testOffset(offset)
        if tested[offset] then return nil end
        tested[offset] = true
        local mk2 = maluaReadWeaponFlagsCandidate(pair.mk2Weapon, offset)
        local deluxo = maluaReadWeaponFlagsCandidate(pair.deluxoWeapon, offset)
        if mk2 and deluxo then return offset, mk2, deluxo end
        return nil
    end

    for _, offset in ipairs(preferred) do
        local found, mk2, deluxo = testOffset(offset)
        if found then return found, mk2, deluxo end
    end
    for offset = 0x700, 0xA80, 4 do
        local found, mk2, deluxo = testOffset(offset)
        if found then return found, mk2, deluxo end
    end
    return nil
end

local MALuaMK2WeaponFlagsPatch = {
    active = false,
    restorePending = false,
    pair = nil,
    flagsOffset = nil,
    address = nil,
    original = nil,
}

local MALuaMK2NPCLock = {
    desired = false,
}

local MALuaPlayerHomingLock = {
    desired = false,
}

function MALuaMK2WeaponFlagsPatch:Enable()
    if self.active then return self.restorePending ~= true end
    local pairOk, pair, pairError = pcall(maluaResolveWeaponInfoPair, "flags")
    if not pairOk then
        pairError = pair
        pair = nil
    end
    if not pair then
        maluaLogError("[mALuaMK2Lock] weapon info unresolved: " .. tostring(pairError))
        return false
    end

    local offset, mk2Flags, deluxoFlags = maluaResolveWeaponFlagsOffset(pair)
    if not offset then
        maluaLogError("[mALuaMK2Lock] WeaponFlags layout unresolved; no weapon values written")
        return false
    end

    local address = pair.mk2Weapon + offset + 0x04
    local readOk, original = pcall(Memory.ReadUInt, address)
    if not readOk or type(original) ~= "number" then
        maluaLogError("[mALuaMK2Lock] WeaponFlags original value is unreadable")
        return false
    end
    local patched = original | MALUA_MK2_DRIVER_PED_MASK

    self.pair = pair
    self.flagsOffset = offset
    self.address = address
    self.original = original
    self.active = true
    self.restorePending = true
    local ok, err = pcall(function()
        Memory.WriteUInt(address, patched)
        if (Memory.ReadUInt(address) & MALUA_MK2_DRIVER_PED_MASK) == 0 then
            error("WeaponFlags bit verification failed")
        end
    end)
    if not ok then
        local restoreCallOk, restored = pcall(
            MALuaMK2WeaponFlagsPatch.Disable,
            MALuaMK2WeaponFlagsPatch
        )
        if restoreCallOk and restored == true then
            maluaLogError("[mALuaMK2Lock] WeaponFlags write failed and was rolled back: " .. tostring(err))
        else
            maluaLogError("[mALuaMK2Lock] WeaponFlags write failed; verified restore is pending: " .. tostring(err))
        end
        return false
    end

    self.restorePending = false
    maluaLogInfo(string.format(
        "[mALuaMK2Lock] WeaponFlags enabled offset=0x%X bit=%d mk2=[%08X %08X %08X] deluxo=[%08X %08X %08X]",
        offset, MALUA_MK2_DRIVER_PED_FLAG,
        mk2Flags.d0, mk2Flags.d1, mk2Flags.d2,
        deluxoFlags.d0, deluxoFlags.d1, deluxoFlags.d2
    ))
    return true
end

function MALuaMK2WeaponFlagsPatch:Refresh()
    if not self.active then return true end
    if self.restorePending then return false end
    local ok, err = pcall(function()
        if not maluaPointerLooksValid(self.address) then error("WeaponFlags address is invalid") end
        local current = Memory.ReadUInt(self.address)
        if (current & MALUA_MK2_DRIVER_PED_MASK) == 0 then
            self.original = current
            Memory.WriteUInt(self.address, current | MALUA_MK2_DRIVER_PED_MASK)
            if (Memory.ReadUInt(self.address) & MALUA_MK2_DRIVER_PED_MASK) == 0 then
                error("WeaponFlags refresh verification failed")
            end
        end
    end)
    if not ok then
        maluaLogError("[mALuaMK2Lock] WeaponFlags refresh stopped: " .. tostring(err))
        return false
    end
    return true
end

function MALuaMK2WeaponFlagsPatch:Disable()
    if not self.active then
        self.restorePending = false
        return true
    end
    self.restorePending = true
    local ok, err = pcall(function()
        if type(self.address) ~= "number" or type(self.original) ~= "number" then
            error("WeaponFlags restore metadata is invalid")
        end
        local current = Memory.ReadUInt(self.address)
        local currentBit = current & MALUA_MK2_DRIVER_PED_MASK
        local originalBit = self.original & MALUA_MK2_DRIVER_PED_MASK
        if currentBit ~= originalBit then
            local restored = (current & 0xDFFFFFFF) | originalBit
            Memory.WriteUInt(self.address, restored)
            local verified = Memory.ReadUInt(self.address)
            if verified ~= restored or (verified & MALUA_MK2_DRIVER_PED_MASK) ~= originalBit then
                error("WeaponFlags restore verification failed")
            end
        end
    end)
    if not ok then
        maluaLogError("[mALuaMK2Lock] WeaponFlags restore failed: " .. tostring(err))
        return false
    end
    self.active = false
    self.restorePending = false
    self.pair = nil
    self.flagsOffset = nil
    self.address = nil
    self.original = nil
    maluaLogInfo("[mALuaMK2Lock] original MK2 WeaponFlags restored")
    return true
end

-- Feature-driven registration for the verified WeaponFlags field.  The
-- resolver reuses the same structure/signature probe as the live feature and
-- never stores an RVA.  It is probe-only until a caller explicitly applies it.
SovereignPatchRegistry:Register("mk2.weapon_flags", {
    resolve = function()
        local pair = maluaResolveWeaponInfoPair("flags")
        local offset, _, _ = maluaResolveWeaponFlagsOffset(pair)
        if not offset then error("weapon_flags_layout_unresolved") end
        local address = pair.mk2Weapon + offset + 0x04
        local original = Memory.ReadUInt(address)
        return {
            writes = {{
                name = "MK2 DriverPed WeaponFlags",
                address = address,
                kind = "uint",
                expected = original,
                value = original | MALUA_MK2_DRIVER_PED_MASK
            }},
            validate = function() return true end
        }
    end
})

local MALuaMK2PedTargetState = {
    originals = {},
    targetables = {},
    targetPlayer = nil,
    playerLockonActive = false,
    lockonPlayer = nil,
    rangePlayer = nil,
    localPed = nil,
    localIdentity = nil,
    localDisablePlayerLockon = false,
    localAllowFriendlyLockon = false,
    lockonRangeActive = false,
    logged = false,
}

local function maluaReadEntityIdentity(entity)
    local existsOk, exists = pcall(menu.nativeApis.ENTITY.DOES_ENTITY_EXIST, entity)
    if not existsOk then return nil, "entity existence is unreadable" end
    if not exists then return false, "entity no longer exists" end
    local modelOk, model = pcall(menu.nativeApis.ENTITY.GET_ENTITY_MODEL, entity)
    if not modelOk or type(model) ~= "number" then return nil, "entity model is unreadable" end
    local networkIdGetter = menu.nativeApis.NETWORK and menu.nativeApis.NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY
    if type(networkIdGetter) ~= "function" then return nil, "network id getter is unavailable" end
    local networkOk, networkId = pcall(networkIdGetter, entity)
    if not networkOk or type(networkId) ~= "number" or networkId <= 0 then
        return nil, "entity network id is unreadable"
    end
    return {model = maluaU32(model), networkId = maluaU32(networkId)}
end

function MALuaMK2PedTargetState:ReadIdentity(ped, pid)
    local playerPedOk, currentPed = pcall(menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX, pid)
    if not playerPedOk or type(currentPed) ~= "number" then
        return nil, "player ped identity is unreadable"
    end
    local identity, identityReason = maluaReadEntityIdentity(ped)
    if identity == nil or identity == false then return identity, identityReason end
    if currentPed ~= ped then return false, "player ped changed" end
    identity.pid = pid
    return identity
end

local function maluaTargetableMatches(entity, entry)
    if type(entry) ~= "table" or not entry.model or not entry.networkId then return true end
    local identity, reason = maluaReadEntityIdentity(entity)
    if identity == nil then return nil, reason end
    if identity == false then return false, reason end
    return identity.model == entry.model and identity.networkId == entry.networkId
end

local function maluaRememberTargetable(entity, targetable)
    local identity = maluaReadEntityIdentity(entity)
    if type(identity) == "table" then
        targetable.model, targetable.networkId = identity.model, identity.networkId
    end
    return targetable
end

function MALuaMK2PedTargetState:IdentityStatus(ped, pid, entry)
    local identity, reason = self:ReadIdentity(ped, pid)
    if identity == nil then return nil, reason end
    if identity == false then return false, reason end
    if entry and (entry.pid ~= identity.pid or entry.model ~= identity.model
        or entry.networkId ~= identity.networkId) then
        return false, "ped identity changed"
    end
    return true, identity
end

local function maluaRemovePlayerTargetable(pid, entity, entry)
    if type(entry) ~= "table" or not entry.model or not entry.networkId then return false end
    local matches = maluaTargetableMatches(entity, entry)
    if matches == false then return true end
    if matches ~= true then return false end
    local existsOk, exists = pcall(menu.nativeApis.ENTITY.DOES_ENTITY_EXIST, entity)
    if existsOk and exists == false then return true end
    local priorityOk = true
    if entry == true or (type(entry) == "table" and entry.priority == true) then
        local callOk, result = pcall(menu.nativeApis.ENTITY.SET_ENTITY_IS_TARGET_PRIORITY, entity, false, 0.0)
        priorityOk = callOk and result ~= false
    end
    local removeOk, removeResult = pcall(menu.nativeApis.PLAYER.REMOVE_PLAYER_TARGETABLE_ENTITY, pid, entity)
    return priorityOk and removeOk and removeResult ~= false
end

function MALuaMK2PedTargetState:Refresh()
    local function setFlagVerified(ped, flag, value)
        local setOk, setResult = pcall(menu.nativeApis.PED.SET_PED_CONFIG_FLAG, ped, flag, value)
        if not setOk or setResult == false then return false end
        local readOk, current = pcall(menu.nativeApis.PED.GET_PED_CONFIG_FLAG, ped, flag, true)
        return readOk and type(current) == "boolean" and current == value
    end

    local localPid = menu.nativeApis.PLAYER.PLAYER_ID()
    local localPed = menu.nativeApis.PLAYER.PLAYER_PED_ID()
    if type(localPid) ~= "number" or type(localPed) ~= "number" or localPed == 0 then return false end
    if self.localPed and self.localPed ~= localPed and not self:Restore() then return false end
    if self.localPed and self.localIdentity then
        local status, reason = self:IdentityStatus(self.localPed, self.localIdentity.pid, self.localIdentity)
        if status == nil then
            maluaLogError("[mALuaMK2Lock] local ped identity check failed: " .. tostring(reason))
            return false
        elseif status == false then
            self.localPed, self.localIdentity = nil, nil
            self.localDisablePlayerLockon, self.localAllowFriendlyLockon = false, false
        end
    end
    if self.targetPlayer and self.targetPlayer ~= localPid and not self:Restore() then return false end

    self.targetPlayer = localPid
    local lockOk, lockResult = pcall(menu.nativeApis.PLAYER.SET_PLAYER_LOCKON, localPid, true)
    if not lockOk or lockResult == false then
        maluaLogError("[mALuaMK2Lock] local player lock-on setup failed")
        return false
    end
    self.playerLockonActive, self.lockonPlayer = true, localPid
    local rangeOk, rangeResult = pcall(menu.nativeApis.PLAYER.SET_PLAYER_LOCKON_RANGE_OVERRIDE, localPid, 10000.0)
    if not rangeOk or rangeResult == false then
        maluaLogError("[mALuaMK2Lock] local player lock-on range setup failed")
        return false
    end
    self.lockonRangeActive, self.rangePlayer = true, localPid

    if self.localPed ~= localPed then
        local identityStatus, identity = self:IdentityStatus(localPed, localPid, nil)
        if identityStatus ~= true then
            maluaLogError("[mALuaMK2Lock] local ped snapshot failed: " .. tostring(identity))
            return false
        end
        local ok43, flag43 = pcall(menu.nativeApis.PED.GET_PED_CONFIG_FLAG, localPed, 43, true)
        local ok45, flag45 = pcall(menu.nativeApis.PED.GET_PED_CONFIG_FLAG, localPed, 45, true)
        if not ok43 or type(flag43) ~= "boolean" or not ok45 or type(flag45) ~= "boolean" then
            maluaLogError("[mALuaMK2Lock] local ped flag snapshot failed")
            return false
        end
        self.localPed, self.localIdentity = localPed, identity
        self.localDisablePlayerLockon, self.localAllowFriendlyLockon = flag43, flag45
    end
    if not setFlagVerified(localPed, 43, false) or not setFlagVerified(localPed, 45, true) then
        maluaLogError("[mALuaMK2Lock] local ped flag verification failed")
        return false
    end

    local seen, failures, active, added = {}, 0, 0, 0
    for pid = 0, 31 do
        if pid ~= localPid and menu.nativeApis.NETWORK.NETWORK_IS_PLAYER_ACTIVE(pid) then
            local ped = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
            if ped and ped ~= 0 and menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(ped) then
                active = active + 1
                local existingPedTarget = self.targetables[ped]
                local pedMatches, pedMatchReason = maluaTargetableMatches(ped, existingPedTarget)
                if pedMatches == nil then
                    failures = failures + 1
                elseif pedMatches == false then
                    -- The handle was reused. Do not call REMOVE on the new
                    -- entity; discard the old ownership record and re-add it.
                    self.targetables[ped] = nil
                    existingPedTarget = nil
                end
                local addOk, addResult = pcall(menu.nativeApis.PLAYER.ADD_PLAYER_TARGETABLE_ENTITY, localPid, ped)
                if addOk and addResult ~= false then
                    local targetable = type(existingPedTarget) == "table"
                        and existingPedTarget or {}
                    targetable = maluaRememberTargetable(ped, targetable)
                    self.targetables[ped], seen[ped], added = targetable, true, added + 1
                    local priorityOk, priorityResult = pcall(
                        menu.nativeApis.ENTITY.SET_ENTITY_IS_TARGET_PRIORITY, ped, true, 400.0
                    )
                    if priorityOk and priorityResult ~= false then
                        targetable.priority = true
                    else
                        failures = failures + 1
                    end
                elseif self.targetables[ped] then
                    seen[ped] = true
                    local targetable = self.targetables[ped]
                    if targetable == true then
                        targetable = {priority = true}
                        self.targetables[ped] = targetable
                    end
                    if type(targetable) == "table" and targetable.priority ~= true then
                        local priorityOk, priorityResult = pcall(
                            menu.nativeApis.ENTITY.SET_ENTITY_IS_TARGET_PRIORITY, ped, true, 400.0
                        )
                        if priorityOk and priorityResult ~= false then
                            targetable.priority = true
                        else
                            failures = failures + 1
                        end
                    end
                else
                    failures = failures + 1
                end

                local vehicleOk, targetVehicle = pcall(menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN, ped, false)
                if vehicleOk and targetVehicle and targetVehicle ~= 0 and menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(targetVehicle) then
                    local existingVehicleTarget = self.targetables[targetVehicle]
                    local vehicleMatches = maluaTargetableMatches(targetVehicle, existingVehicleTarget)
                    if vehicleMatches == false then
                        self.targetables[targetVehicle] = nil
                        existingVehicleTarget = nil
                    elseif vehicleMatches == nil then
                        failures = failures + 1
                    end
                    local vehicleAddOk, vehicleAddResult = pcall(
                        menu.nativeApis.PLAYER.ADD_PLAYER_TARGETABLE_ENTITY, localPid, targetVehicle
                    )
                    if vehicleAddOk and vehicleAddResult ~= false then
                        local targetable = type(existingVehicleTarget) == "table"
                            and existingVehicleTarget or {}
                        targetable = maluaRememberTargetable(targetVehicle, targetable)
                        self.targetables[targetVehicle], seen[targetVehicle], added = targetable, true, added + 1
                        local priorityOk, priorityResult = pcall(
                            menu.nativeApis.ENTITY.SET_ENTITY_IS_TARGET_PRIORITY, targetVehicle, true, 400.0
                        )
                        if priorityOk and priorityResult ~= false then
                            targetable.priority = true
                        else
                            failures = failures + 1
                        end
                    elseif self.targetables[targetVehicle] then
                        seen[targetVehicle] = true
                        local targetable = self.targetables[targetVehicle]
                        if targetable == true then
                            targetable = {priority = true}
                            self.targetables[targetVehicle] = targetable
                        end
                        if type(targetable) == "table" and targetable.priority ~= true then
                            local priorityOk, priorityResult = pcall(
                                menu.nativeApis.ENTITY.SET_ENTITY_IS_TARGET_PRIORITY, targetVehicle, true, 400.0
                            )
                            if priorityOk and priorityResult ~= false then
                                targetable.priority = true
                            else
                                failures = failures + 1
                            end
                        end
                    else
                        failures = failures + 1
                    end
                end

                local entry = self.originals[ped]
                local identityStatus, identity = self:IdentityStatus(ped, pid, entry)
                if entry and identityStatus == false then
                    self.originals[ped], entry = nil, nil
                elseif identityStatus == nil then
                    failures, entry = failures + 1, nil
                end
                if not entry and identityStatus == true then
                    local ok434, flag434 = pcall(menu.nativeApis.PED.GET_PED_CONFIG_FLAG, ped, 434, true)
                    local ok408, flag408 = pcall(menu.nativeApis.PED.GET_PED_CONFIG_FLAG, ped, 408, true)
                    local ok214, flag214 = pcall(menu.nativeApis.PED.GET_PED_CONFIG_FLAG, ped, 214, true)
                    local ok119, flag119 = pcall(menu.nativeApis.PED.GET_PED_CONFIG_FLAG, ped, 119, true)
                    if ok434 and type(flag434) == "boolean" and ok408 and type(flag408) == "boolean"
                        and ok214 and type(flag214) == "boolean" and ok119 and type(flag119) == "boolean" then
                        entry = {
                            pid = identity.pid, model = identity.model, networkId = identity.networkId,
                            flag434 = flag434, flag408 = flag408, flag214 = flag214, flag119 = flag119,
                        }
                        self.originals[ped] = entry
                    else
                        failures = failures + 1
                    end
                end
                if entry and identityStatus == true then
                    for _, flag in ipairs({
                        {434, false}, {408, false}, {214, true}, {119, true},
                    }) do
                        if not setFlagVerified(ped, flag[1], flag[2]) then failures = failures + 1 end
                    end
                end
            end
        end
    end
    -- Collect stale handles before mutating the ownership map.  Removing keys
    -- during pairs() can skip the next hash bucket and leave a targetable live.
    local staleTargetables = {}
    for entity in pairs(self.targetables) do
        if not seen[entity] then staleTargetables[#staleTargetables + 1] = entity end
    end
    for _, entity in ipairs(staleTargetables) do
        local entry = self.targetables[entity]
        local matches, matchReason = maluaTargetableMatches(entity, entry)
        if matches == false then
            -- A reused handle now belongs to another entity. Never remove
            -- targeting from that new entity while cleaning stale state.
            self.targetables[entity] = nil
        elseif matches == nil then
            failures = failures + 1
        elseif maluaRemovePlayerTargetable(localPid, entity, entry) then
            self.targetables[entity] = nil
        else
            failures = failures + 1
        end
    end
    if failures > 0 then
        maluaLogError(string.format("[mALuaMK2Lock] target-state verification failures=%d; retrying", failures))
        return false
    end
    if not self.logged then
        maluaLogInfo(string.format("[mALuaMK2Lock] target state activePlayers=%d targetables=%d", active, added))
        self.logged = true
    end
    return true
end

function MALuaMK2PedTargetState:Restore()
    local restoreOk = true
    local function restoreFlag(ped, flag, value, ownedValue)
        local readOk, current = pcall(menu.nativeApis.PED.GET_PED_CONFIG_FLAG, ped, flag, true)
        if not readOk or type(current) ~= "boolean" then return false end
        if current == value then return true end
        if ownedValue ~= nil and current ~= ownedValue then return true end
        local setOk, setResult = pcall(menu.nativeApis.PED.SET_PED_CONFIG_FLAG, ped, flag, value)
        if not setOk or setResult == false then return false end
        local verifyOk, verified = pcall(menu.nativeApis.PED.GET_PED_CONFIG_FLAG, ped, flag, true)
        return verifyOk and type(verified) == "boolean" and verified == value
    end

    local remainingTargetables = {}
    if self.targetPlayer then
        for entity, entry in pairs(self.targetables) do
            if not maluaRemovePlayerTargetable(self.targetPlayer, entity, entry) then
                remainingTargetables[entity], restoreOk = entry, false
            end
        end
    end
    self.targetables = remainingTargetables
    if next(remainingTargetables) == nil then self.targetPlayer = nil end

    if self.lockonRangeActive then
        local resetPid = type(self.rangePlayer) == "number" and self.rangePlayer or menu.nativeApis.PLAYER.PLAYER_ID()
        local ok, result = pcall(menu.nativeApis.PLAYER.SET_PLAYER_LOCKON_RANGE_OVERRIDE, resetPid, 0.0)
        if ok and result ~= false then
            self.lockonRangeActive, self.rangePlayer = false, nil
        else
            restoreOk = false
        end
    else
        self.rangePlayer = nil
    end

    if self.playerLockonActive then
        local resetPid = type(self.lockonPlayer) == "number" and self.lockonPlayer or menu.nativeApis.PLAYER.PLAYER_ID()
        local ok, result = pcall(menu.nativeApis.PLAYER.SET_PLAYER_LOCKON, resetPid, true)
        if ok and result ~= false then
            self.playerLockonActive, self.lockonPlayer = false, nil
        else
            restoreOk = false
        end
    else
        self.lockonPlayer = nil
    end

    local localRestored = true
    if self.localPed and self.localPed ~= 0 then
        local status
        if self.localIdentity then
            status = maluaTargetableMatches(self.localPed, self.localIdentity)
        end
        if status == nil then
            localRestored = false
        elseif status == true then
            local restored43 = restoreFlag(self.localPed, 43, self.localDisablePlayerLockon, false)
            local restored45 = restoreFlag(self.localPed, 45, self.localAllowFriendlyLockon, true)
            localRestored = restored43 and restored45
        end
    end
    if localRestored then
        self.localPed, self.localIdentity = nil, nil
        self.localDisablePlayerLockon, self.localAllowFriendlyLockon = false, false
    else
        restoreOk = false
    end

    local remainingOriginals = {}
    for ped, entry in pairs(self.originals) do
        local status = maluaTargetableMatches(ped, entry)
        local restored = status == false
        if status == true then
            restored = true
            for _, flag in ipairs({
                {434, entry.flag434, false},
                {408, entry.flag408, false},
                {214, entry.flag214, true},
                {119, entry.flag119, true},
            }) do
                if not restoreFlag(ped, flag[1], flag[2], flag[3]) then restored = false end
            end
        end
        if not restored then remainingOriginals[ped], restoreOk = entry, false end
    end
    self.originals = remainingOriginals
    if restoreOk then self.logged = false end
    return restoreOk
end

-- Validates the observed Windows x64 tunable getter ABI, not arbitrary x64 code.
-- Scan returns the first match only; every accepted candidate is checked locally.
local function newGuidanceResolver(memory, probeModule)
    local function inSection(layout, address, size, permission)
        if type(address) ~= "number" or address % 1 ~= 0 or size <= 0 then return false end
        if address < layout.base or address + size > layout.base + layout.imageSize then return false end
        for _, section in ipairs(layout.sections or {}) do
            if section.readable and section[permission]
                and address >= layout.base + section.rva
                and address + size <= layout.base + section.rva + section.size then
                return true
            end
        end
        return false
    end

    local function signed32(address)
        local value = memory.ReadUInt(address)
        return value >= 0x80000000 and value - 0x100000000 or value
    end

    local function decode(layout, address)
        if not inSection(layout, address, 1, "executable") then return nil end
        local b = memory.ReadUByte(address)
        local function result(length, kind, fields)
            if not inSection(layout, address, length, "executable") then return nil end
            fields = fields or {}
            fields.address, fields.length, fields.kind = address, length, kind
            return fields
        end
        -- Read only after the entire largest supported instruction is in code.
        if not inSection(layout, address, 10, "executable") then return nil end
        if b == 0xE8 then
            local target = address + 5 + signed32(address + 1)
            if not inSection(layout, target, 1, "executable") then return nil end
            return result(5, "call", {target = target})
        elseif b >= 0xB8 and b <= 0xBF then
            return result(5, "immediate", {reg = b - 0xB8, value = memory.ReadUInt(address + 1)})
        elseif b == 0xF3 and memory.ReadUByte(address + 1) == 0x0F then
            local op, modrm = memory.ReadUByte(address + 2), memory.ReadUByte(address + 3)
            if (op == 0x10 or op == 0x11) and (modrm & 0xC7) == 0x05 then
                return result(8, op == 0x10 and "float_load" or "float_store", {
                    reg = (modrm >> 3) & 7, target = address + 8 + signed32(address + 4),
                })
            end
        elseif b == 0x0F and memory.ReadUByte(address + 1) == 0x28 then
            local modrm = memory.ReadUByte(address + 2)
            if (modrm & 0xC0) == 0xC0 then
                return result(3, "float_move", {reg = (modrm >> 3) & 7, source = modrm & 7})
            end
        elseif b == 0x90 then
            return result(1, "nop")
        else
            local prefix = b >= 0x40 and b <= 0x4F and 1 or 0
            local rex = prefix == 1 and b or 0
            local op = memory.ReadUByte(address + prefix)
            local modrm = memory.ReadUByte(address + prefix + 1)
            if op == 0x88 or op == 0x89 or op == 0x8B then
                local reg = ((modrm >> 3) & 7) + ((rex & 4) ~= 0 and 8 or 0)
                local rm = (modrm & 7) + ((rex & 1) ~= 0 and 8 or 0)
                if (modrm & 0xC0) == 0xC0 and op ~= 0x88 then
                    return result(prefix + 2, "gpr_move", {
                        reg = op == 0x8B and reg or rm,
                        source = op == 0x8B and rm or reg,
                        wide = (rex & 8) ~= 0,
                    })
                elseif (modrm & 0xC7) == 0x05 then
                    return result(prefix + 6, op == 0x8B and "gpr_load" or "gpr_store", {
                        reg = reg, wide = (rex & 8) ~= 0,
                        target = address + prefix + 6 + signed32(address + prefix + 2),
                        size = op == 0x88 and 1 or ((rex & 8) ~= 0 and 8 or 4),
                    })
                end
            end
        end
        return nil
    end

    local function preloadedDefault(layout, anchor, source)
        if source < 6 then return nil, "default uses a volatile register across key call" end
        local candidates = {}
        for start = math.max(layout.base, anchor - 64), anchor - 8 do
            local instruction = decode(layout, start)
            if instruction and instruction.kind == "float_load" and instruction.reg == source then
                local cursor, valid = start + instruction.length, true
                while cursor < anchor and valid do
                    local nextInstruction = decode(layout, cursor)
                    if not nextInstruction or (nextInstruction.kind ~= "immediate"
                        and nextInstruction.kind ~= "gpr_move"
                        and nextInstruction.kind ~= "gpr_load"
                        and nextInstruction.kind ~= "nop") then
                        valid = false
                    else
                        cursor = cursor + nextInstruction.length
                    end
                end
                if valid and cursor == anchor then candidates[#candidates + 1] = instruction end
            end
        end
        if #candidates ~= 1 then return nil, "preloaded default is missing or ambiguous" end
        return candidates[1]
    end

    local function resolve(layout, hashBytes)
        if not layout or type(layout.base) ~= "number" or type(layout.imageSize) ~= "number" then
            return nil, "invalid module layout"
        end
        local moduleName = probeModule()
        if not moduleName or memory.GetBaseAddress(moduleName) ~= layout.base then
            return nil, "module identity changed"
        end
        local pattern = "BA " .. hashBytes
        local anchor = memory.Scan(pattern, moduleName)
        if not anchor or anchor == 0 then return nil, "hash argument not found" end
        local expected = {}
        for byte in hashBytes:gmatch("%x%x") do expected[#expected + 1] = tonumber(byte, 16) end
        if #expected ~= 4 or not inSection(layout, anchor, 5, "executable") then
            return nil, "hash argument is not executable"
        end
        for index = 1, 4 do
            if memory.ReadUByte(anchor + index) ~= expected[index] then return nil, "hash argument changed" end
        end
        if memory.ReadUByte(anchor) ~= 0xBA then return nil, "hash is not passed in edx" end
        local cursor, phase, calls = anchor + 5, 0, {}
        local default, keyInEdx, getterContext = nil, false, false
        -- This is a bounded instruction walk. No byte-by-byte store search.
        for _ = 1, 40 do
            if cursor > anchor + 160 then break end
            local instruction = decode(layout, cursor)
            if not instruction then return nil, "unsupported instruction in getter chain" end
            local kind = instruction.kind
            if kind == "call" then
                if phase == 0 then
                    phase = 1
                elseif phase == 1 and default and keyInEdx and getterContext then
                    phase = 2
                else
                    return nil, "unexpected call in getter chain"
                end
                calls[#calls + 1] = instruction.target
                if #calls == 2 and calls[1] == calls[2] then return nil, "key and float getter alias" end
            elseif kind == "float_load" or kind == "float_move" then
                if phase ~= 1 or instruction.reg ~= 2 or default then
                    return nil, "ambiguous float argument"
                end
                if kind == "float_load" then
                    default = instruction
                else
                    local reason
                    default, reason = preloadedDefault(layout, anchor, instruction.source)
                    if not default then return nil, reason end
                end
                if not inSection(layout, default.target, 4, "writable") then
                    return nil, "default is not readable writable module data"
                end
            elseif kind == "float_store" then
                if phase == 2 then
                    if instruction.reg ~= 0 or instruction.target ~= default.target then
                        return nil, "getter result does not match its default"
                    end
                    local value = memory.ReadFloat(instruction.target)
                    if type(value) ~= "number" or value ~= value or math.abs(value) > 1000 then
                        return nil, "invalid guidance override value"
                    end
                    return {
                        anchor = anchor, pattern = pattern, address = instruction.target, original = value,
                        keyResolver = calls[1], floatGetter = calls[2], defaultLoad = default.address,
                        resultStore = instruction.address, evidence = "ordered_getter_default_store",
                    }
                elseif phase ~= 0 then
                    return nil, "result stored before float getter"
                end
                -- Legacy may store the preceding tunable between this hash and its key call.
                if not inSection(layout, instruction.target, 4, "writable") then
                    return nil, "preceding result is outside module data"
                end
            elseif kind == "gpr_move" or kind == "gpr_load" or kind == "immediate" then
                if kind == "gpr_load" and not inSection(layout, instruction.target, instruction.size, "readable") then
                    return nil, "getter context load is outside readable module data"
                end
                if instruction.reg == 2 then
                    if phase == 0 then return nil, "hash argument overwritten before key resolver" end
                    if phase == 1 then
                        keyInEdx = kind == "gpr_move" and instruction.source == 0 and not instruction.wide
                    end
                elseif instruction.reg == 1 and phase == 1 then
                    getterContext = (kind == "gpr_move" or kind == "gpr_load") and instruction.wide
                end
                if instruction.reg == 0 and phase == 1 and not keyInEdx then
                    return nil, "resolved key overwritten before getter argument"
                end
                if instruction.reg == 0 and phase == 2 then return nil, "getter return clobbered" end
            elseif kind == "gpr_store" then
                if not inSection(layout, instruction.target, instruction.size, "writable") then
                    return nil, "interleaved write is outside module data"
                end
            elseif kind ~= "nop" then
                return nil, "unsupported getter operation"
            end
            cursor = cursor + instruction.length
        end
        return nil, "getter chain has no matching result store"
    end

    return function(layout, hashBytes)
        local ok, value, reason = pcall(resolve, layout, hashBytes)
        if not ok then return nil, "guidance memory read failed: " .. tostring(value) end
        return value, reason
    end
end

local maluaResolveOppressorOverride = newGuidanceResolver(Memory, maluaProbeModule)

local MALuaMK2DeadlockPatch = {
    desired = false,
    active = false,
    restorePending = false,
    sourceKey = "deluxo",
    pair = nil,
    guidanceOriginal = nil,
    guidanceValues = nil,
    overrides = nil,
    tunables = nil,
}

local MALUA_MK2_GUIDANCE_SOURCE_LABELS = {
    deluxo = "Deluxo",
    chernobog = "Chernobog",
    ruiner = "Ruiner 2000",
}

local MALUA_MK2_GUIDANCE_SOURCE_KEYS = {"deluxo", "chernobog", "ruiner"}

function MALuaMK2DeadlockPatch:SetSource(sourceKey)
    if sourceKey ~= "deluxo" and sourceKey ~= "chernobog" and sourceKey ~= "ruiner" then
        maluaLogError("[mALuaMK2Guidance] unsupported source switch: " .. tostring(sourceKey))
        return false
    end
    if sourceKey == self.sourceKey then return true end
    local wasActive = self.active
    local previousSource = self.sourceKey
    if wasActive then
        if not self:Disable() then
            maluaLogError("[mALuaMK2Guidance] source switch aborted; current patch was not restored")
            return false
        end
    end
    self.sourceKey = sourceKey
    if wasActive and self.desired then
        if self:Enable(sourceKey) then return true end
        self.sourceKey = previousSource
        return false
    end
    return true
end

function MALuaMK2DeadlockPatch:Enable(sourceKey)
    if self.active then return self.restorePending ~= true end
    sourceKey = sourceKey or self.sourceKey or "deluxo"
    if sourceKey ~= "deluxo" and sourceKey ~= "chernobog" and sourceKey ~= "ruiner" then
        maluaLogError("[mALuaMK2Guidance] unsupported guidance source: " .. tostring(sourceKey))
        return false
    end
    local layout, layoutError = maluaModuleLayout()
    if not layout then
        maluaLogError("[mALuaMK2Guidance] " .. tostring(layoutError))
        return false
    end
    local pairOk, pair, pairError = pcall(maluaResolveWeaponInfoPair)
    if not pairOk then
        pairError = pair
        pair = nil
    end
    if not pair then
        maluaLogError("[mALuaMK2Guidance] " .. tostring(pairError) .. "; no values written")
        return false
    end
    local sourceAmmo = pair[sourceKey .. "Ammo"]
    if not sourceAmmo then
        maluaLogError("[mALuaMK2Guidance] guidance source unavailable: " .. sourceKey .. "; no values written")
        return false
    end

    local clampOk, clamp, clampError = pcall(maluaResolveOppressorOverride, layout, "81 7F 85 BC")
    if not clampOk then clampError, clamp = clamp, nil end
    local turnOk, turn, turnError = pcall(maluaResolveOppressorOverride, layout, "EA FE 4A 79")
    if not turnOk then turnError, turn = turn, nil end
    if not clamp or not turn or clamp.address == turn.address
        or clamp.keyResolver ~= turn.keyResolver or clamp.floatGetter ~= turn.floatGetter then
        maluaLogError(string.format(
            "[mALuaMK2Guidance] static override resolution failed clamp=%s turn=%s; no values written",
            tostring(clampError), tostring(turnError)
        ))
        return false
    end

    local guidanceOriginal = {}
    local sourceValues = {}
    for i, field in ipairs(MALUA_MK2_GUIDANCE_FIELDS) do
        guidanceOriginal[i] = maluaReadGuidanceField(pair.mk2Ammo, field)
        sourceValues[i] = maluaReadGuidanceField(sourceAmmo, field)
        if type(guidanceOriginal[i]) ~= "number" or guidanceOriginal[i] ~= guidanceOriginal[i]
            or math.abs(guidanceOriginal[i]) > 1000.0
            or type(sourceValues[i]) ~= "number" or sourceValues[i] ~= sourceValues[i]
            or math.abs(sourceValues[i]) > 1000.0 then
            maluaLogError("[mALuaMK2Guidance] invalid guidance field: " .. field.name)
            return false
        end
    end

    local tunables = {}
    for _, item in ipairs({
        {name = "PitchYawRollClampOverride", hash = Utils.Joaat("OPPRESSOR2_MISSILE_PITCH_YAW_CLAMP")},
        {name = "TurnRateModifierOverride", hash = Utils.Joaat("OPPRESSOR2_MISSILE_TURN_RATE_MODIFIER")},
    }) do
        local ok, pointer = pcall(ScriptGlobal.GetTunableByHash, item.hash)
        if ok and pointer and pointer ~= 0 then
            local readOk, original = pcall(Memory.ReadFloat, pointer)
            if readOk and type(original) == "number" and original == original
                and math.abs(original) <= 1000.0 then
                tunables[#tunables + 1] = {name = item.name, address = pointer, original = original}
            end
        end
    end

    self.pair = pair
    self.sourceKey = sourceKey
    self.guidanceOriginal = guidanceOriginal
    self.guidanceValues = sourceValues
    self.overrides = {clamp, turn}
    self.tunables = tunables
    self.active = true
    self.restorePending = true

    local ok, err = pcall(function()
        for i, field in ipairs(MALUA_MK2_GUIDANCE_FIELDS) do
            maluaWriteGuidanceField(pair.mk2Ammo, field, sourceValues[i])
            local verify = maluaReadGuidanceField(pair.mk2Ammo, field)
            if verify ~= sourceValues[i] then
                error("guidance verification failed: " .. field.name)
            end
        end
        Memory.WriteFloat(clamp.address, 0.0)
        Memory.WriteFloat(turn.address, 0.0)
        if Memory.ReadFloat(clamp.address) ~= 0.0 or Memory.ReadFloat(turn.address) ~= 0.0 then
            error("static override verification failed")
        end
        for _, item in ipairs(tunables) do
            Memory.WriteFloat(item.address, 0.0)
            if not maluaNearFloat(Memory.ReadFloat(item.address), 0.0) then
                error("tunable verification failed: " .. item.name)
            end
        end
    end)
    if not ok then
        local restoreCallOk, restored = pcall(function() return self:Disable() end)
        if restoreCallOk and restored == true then
            maluaLogError("[mALuaMK2Guidance] patch failed and was rolled back: " .. tostring(err))
        else
            maluaLogError("[mALuaMK2Guidance] patch failed; verified restore is pending: " .. tostring(err))
        end
        return false
    end
    self.restorePending = false
    maluaLogInfo(string.format(
        "[mALuaMK2Guidance] enabled source=%s build_ts=0x%X image=0x%X blob_rva=0x%X mk2Ammo=0x%X sourceAmmo=0x%X clamp_rva=0x%X turn_rva=0x%X",
        sourceKey, layout.timestamp, layout.imageSize, pair.scan - layout.base, pair.mk2Ammo, sourceAmmo,
        clamp.address - layout.base, turn.address - layout.base
    ))
    return true
end

function MALuaMK2DeadlockPatch:Refresh()
    if not self.active then return true end
    if self.restorePending then return false end
    local ok, err = pcall(function()
        for i, field in ipairs(MALUA_MK2_GUIDANCE_FIELDS) do
            local current = maluaReadGuidanceField(self.pair.mk2Ammo, field)
            local expected = self.guidanceValues and self.guidanceValues[i]
            local original = self.guidanceOriginal and self.guidanceOriginal[i]
            if type(current) ~= "number" or type(expected) ~= "number" or type(original) ~= "number" then
                error(field.name .. " guidance field became unreadable")
            end
            if not maluaNearFloat(current, expected) then
                if not maluaNearFloat(current, original) then
                    error(field.name .. " guidance field changed externally")
                end
                maluaWriteGuidanceField(self.pair.mk2Ammo, field, expected)
                if not maluaNearFloat(maluaReadGuidanceField(self.pair.mk2Ammo, field), expected) then
                    error(field.name .. " guidance refresh verification failed")
                end
            end
        end
        for _, item in ipairs(self.overrides or {}) do
            local value = Memory.ReadFloat(item.address)
            if not maluaNearFloat(value, 0.0) then
                if type(value) ~= "number" or value ~= value or math.abs(value) > 1000.0
                    or not maluaNearFloat(value, item.original) then
                    error(item.name .. " override changed externally")
                end
                Memory.WriteFloat(item.address, 0.0)
                if not maluaNearFloat(Memory.ReadFloat(item.address), 0.0) then
                    error(item.name .. " override refresh verification failed")
                end
            end
        end
        for _, item in ipairs(self.tunables or {}) do
            local value = Memory.ReadFloat(item.address)
            if not maluaNearFloat(value, 0.0) then
                if type(value) ~= "number" or value ~= value or math.abs(value) > 1000.0
                    or not maluaNearFloat(value, item.original) then
                    error(item.name .. " tunable changed externally")
                end
                Memory.WriteFloat(item.address, 0.0)
                if not maluaNearFloat(Memory.ReadFloat(item.address), 0.0) then
                    error(item.name .. " tunable refresh verification failed")
                end
            end
        end
    end)
    if not ok then
        maluaLogError("[mALuaMK2Guidance] refresh stopped: " .. tostring(err))
        return false
    end
    return true
end

function MALuaMK2DeadlockPatch:Disable()
    if not self.active then
        self.restorePending = false
        return true
    end
    self.restorePending = true
    local restoreOk = true
    local ownershipLost = false
    local function clearState()
        self.active = false
        self.restorePending = false
        self.pair = nil
        self.guidanceOriginal = nil
        self.guidanceValues = nil
        self.overrides = nil
        self.tunables = nil
    end
    local ok, err = pcall(function()
        for i, field in ipairs(MALUA_MK2_GUIDANCE_FIELDS) do
            local current = maluaReadGuidanceField(self.pair.mk2Ammo, field)
            local expected = self.guidanceValues and self.guidanceValues[i]
            local original = self.guidanceOriginal and self.guidanceOriginal[i]
            if type(current) ~= "number" then
                error(field.name .. " guidance field is unreadable")
            elseif maluaNearFloat(current, expected) then
                maluaWriteGuidanceField(self.pair.mk2Ammo, field, original)
                if not maluaNearFloat(maluaReadGuidanceField(self.pair.mk2Ammo, field), original) then
                    restoreOk = false
                end
            elseif not maluaNearFloat(current, original) then
                ownershipLost = true
                maluaLogError("[mALuaMK2Guidance] " .. field.name .. " changed externally; restore skipped")
            end
        end
        for _, item in ipairs(self.overrides or {}) do
            local current = Memory.ReadFloat(item.address)
            if maluaNearFloat(current, 0.0) then
                Memory.WriteFloat(item.address, item.original)
                if not maluaNearFloat(Memory.ReadFloat(item.address), item.original) then restoreOk = false end
            elseif not maluaNearFloat(current, item.original) then
                ownershipLost = true
                maluaLogError("[mALuaMK2Guidance] " .. item.name .. " changed externally; restore skipped")
            end
        end
        for _, item in ipairs(self.tunables or {}) do
            local current = Memory.ReadFloat(item.address)
            if maluaNearFloat(current, 0.0) then
                Memory.WriteFloat(item.address, item.original)
                if not maluaNearFloat(Memory.ReadFloat(item.address), item.original) then restoreOk = false end
            elseif not maluaNearFloat(current, item.original) then
                ownershipLost = true
                maluaLogError("[mALuaMK2Guidance] " .. item.name .. " changed externally; restore skipped")
            end
        end
    end)
    if not ok then
        maluaLogError("[mALuaMK2Guidance] restore failed: " .. tostring(err))
        return false
    end
    if not restoreOk then
        maluaLogError("[mALuaMK2Guidance] one or more values were not restored; retrying")
        return false
    end
    if ownershipLost then
        clearState()
        maluaLogError("[mALuaMK2Guidance] external value change detected; ownership released")
        return false
    end
    clearState()
    maluaLogInfo("[mALuaMK2Guidance] original MK2 guidance and tunables restored")
    return true
end

local MALuaMK2Runtime = {
    lastTick = 0.0,
    nextLockAttempt = 0.0,
    nextWeaponFlagsAttempt = 0.0,
    nextGuidanceAttempt = 0.0,
    nextPedAttempt = 0.0,
    modelHash = Utils.Joaat("oppressor2") & 0xFFFFFFFF,
}

function MALuaMK2Runtime:IsUsingMK2()
    return self:GetMK2Vehicle() ~= 0
end

function MALuaMK2Runtime:GetMK2Vehicle()
    local ok, result = pcall(function()
        local ped = menu.nativeApis.PLAYER.PLAYER_PED_ID()
        local vehicle = menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if vehicle ~= 0 and menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(vehicle)
            and (menu.nativeApis.ENTITY.GET_ENTITY_MODEL(vehicle) & 0xFFFFFFFF) == self.modelHash then
            return vehicle
        end
        return 0
    end)
    return ok and result or 0
end

function MALuaMK2Runtime:Tick(vehicle)
    local now = os.clock()
    local onMK2 = vehicle and vehicle ~= 0
    if now - self.lastTick < 0.25 then return end
    self.lastTick = now
    if now >= self.nextPedAttempt then
        local callOk, stateOk = pcall(function()
            if MALuaPlayerHomingLock.desired then return MALuaMK2PedTargetState:Refresh() end
            return MALuaMK2PedTargetState:Restore()
        end)
        if callOk and stateOk == true then
            self.nextPedAttempt = 0.0
        else
            self.nextPedAttempt = now + 5.0
            maluaLogError("[mALuaMK2Lock] player target-state update failed: " .. tostring(stateOk))
        end
    end
    if MALuaMK2NPCLock.desired and onMK2 then
        if MALuaMK2PlayerLockPatch.active then
            if now >= self.nextLockAttempt then
                local callOk, refreshed = pcall(MALuaMK2PlayerLockPatch.Refresh, MALuaMK2PlayerLockPatch)
                if not callOk or refreshed ~= true then
                    pcall(MALuaMK2PlayerLockPatch.Disable, MALuaMK2PlayerLockPatch)
                    if not callOk then
                        maluaLogError("[mALuaMK2Lock] refresh failed: " .. tostring(refreshed))
                    end
                    self.nextLockAttempt = now + 5.0
                end
            end
        elseif now >= self.nextLockAttempt then
            local callOk, enabled, enableError = pcall(
                MALuaMK2PlayerLockPatch.Enable,
                MALuaMK2PlayerLockPatch
            )
            if not callOk then
                maluaLogError("[mALuaMK2Lock] enable failed: " .. tostring(enabled))
            end
            self.nextLockAttempt = callOk and enabled == true and 0.0 or now + 5.0
        end
        if MALuaMK2WeaponFlagsPatch.active then
            if now >= self.nextWeaponFlagsAttempt then
                local callOk, refreshed = pcall(MALuaMK2WeaponFlagsPatch.Refresh, MALuaMK2WeaponFlagsPatch)
                if not callOk or refreshed ~= true then
                    pcall(MALuaMK2WeaponFlagsPatch.Disable, MALuaMK2WeaponFlagsPatch)
                    if not callOk then
                        maluaLogError("[mALuaMK2Flags] refresh failed: " .. tostring(refreshed))
                    end
                    self.nextWeaponFlagsAttempt = now + 5.0
                end
            end
        elseif now >= self.nextWeaponFlagsAttempt then
            local callOk, enabled = pcall(
                MALuaMK2WeaponFlagsPatch.Enable,
                MALuaMK2WeaponFlagsPatch
            )
            if not callOk then
                maluaLogError("[mALuaMK2Flags] enable failed: " .. tostring(enabled))
            end
            self.nextWeaponFlagsAttempt = callOk and enabled == true and 0.0 or now + 5.0
        end
    else
        if MALuaMK2PlayerLockPatch.active and now >= self.nextLockAttempt then
            local callOk, disabled = pcall(MALuaMK2PlayerLockPatch.Disable, MALuaMK2PlayerLockPatch)
            if not callOk or disabled ~= true then self.nextLockAttempt = now + 5.0 end
        end
        if MALuaMK2WeaponFlagsPatch.active and now >= self.nextWeaponFlagsAttempt then
            local callOk, disabled = pcall(MALuaMK2WeaponFlagsPatch.Disable, MALuaMK2WeaponFlagsPatch)
            if not callOk or disabled ~= true then self.nextWeaponFlagsAttempt = now + 5.0 end
        end
    end
    if MALuaMK2DeadlockPatch.desired then
        if MALuaMK2DeadlockPatch.active then
            if now >= self.nextGuidanceAttempt then
                local callOk, refreshed = pcall(MALuaMK2DeadlockPatch.Refresh, MALuaMK2DeadlockPatch)
                if not callOk or refreshed ~= true then
                    pcall(MALuaMK2DeadlockPatch.Disable, MALuaMK2DeadlockPatch)
                    if not callOk then
                        maluaLogError("[mALuaMK2Guidance] refresh failed: " .. tostring(refreshed))
                    end
                    self.nextGuidanceAttempt = now + 5.0
                end
            end
        elseif now >= self.nextGuidanceAttempt then
            local callOk, enabled = pcall(MALuaMK2DeadlockPatch.Enable, MALuaMK2DeadlockPatch)
            if not callOk then
                maluaLogError("[mALuaMK2Guidance] enable failed: " .. tostring(enabled))
            end
            self.nextGuidanceAttempt = callOk and enabled == true and 0.0 or now + 5.0
        end
    else
        if MALuaMK2DeadlockPatch.active and now >= self.nextGuidanceAttempt then
            local callOk, disabled = pcall(MALuaMK2DeadlockPatch.Disable, MALuaMK2DeadlockPatch)
            if not callOk or disabled ~= true then self.nextGuidanceAttempt = now + 5.0 end
        end
    end
end

Script.RegisterLooped(function()
    local ok, err = pcall(function()
        local vehicle = MALuaMK2Runtime:GetMK2Vehicle()
        MALuaMK2Runtime:Tick(vehicle)
    end)
    if not ok then maluaLogError("[mALuaMK2] runtime tick failed: " .. tostring(err)) end
end)


-- Low-level tank cannon cooldown modification.  It is opt-in through the
-- menu toggle below and is restored when the script unloads.
do
local function maluaTankSilent(...) end
-- Keep fallback hashes local: some natives.lua versions omit these wrappers.
local MALUA_GET_VEHICLE_WEAPON_RELOAD_TIME = 0xD0AD348FFD7A6868
local MALUA_GET_TIME_BEFORE_VEHICLE_WEAPON_RELOAD_FINISHES = 0xC8C6F4B1CDEB40EF
local MALUA_HAS_WEAPON_RELOADING_IN_VEHICLE = 0x8062F07153F4446F
local MALUA_TANK_COOLDOWN_HASHES = {
    {name = "tank", hash = Utils.Joaat("VEHICLE_WEAPON_TANK"), required = true},
    {name = "khanjali", hash = Utils.Joaat("VEHICLE_WEAPON_KHANJALI_CANNON"), required = true},
    {name = "khanjaliHeavy", hash = Utils.Joaat("VEHICLE_WEAPON_KHANJALI_CANNON_HEAVY"), required = true},
}

local MALUA_TANK_MODELS = {
    [Utils.Joaat("rhino") & 0xFFFFFFFF] = "Rhino",
    [Utils.Joaat("khanjali") & 0xFFFFFFFF] = "Khanjali",
}

local MALUA_TANK_WEAPON_MANAGER_OFFSET = 0xC80
local MALUA_TANK_COMPONENT_SCAN_LIMIT = 0x240
local MALUA_TANK_STATE_SCAN_LIMIT = 0x500
local MALUA_TANK_POINTER_GRAPH_SCAN_LIMIT = 0x280
local MALUA_TANK_POINTER_GRAPH_OBJECT_LIMIT = 64
local MALUA_TANK_POINTER_GRAPH_MAX_DEPTH = 2
local MALUA_TANK_COMPONENT_PATTERN =
    "41 56 56 57 53 48 83 EC 28 83 B9 14 01 00 00 00 7E ? 89 D3 48 89 CF 45 31 F6"
local MALUA_TANK_COMPONENT_WEAPON_HASHES = {}
for _, definition in ipairs(MALUA_TANK_COOLDOWN_HASHES) do
    MALUA_TANK_COMPONENT_WEAPON_HASHES[maluaU32(definition.hash)] = definition.name
end

local function maluaTankReadComponentWeaponInfo(component)
    if not component or not maluaPointerLooksValid(component) then return nil end
    local child = maluaTryRead(Memory.ReadLong, component + 0x18)
    if not maluaPointerLooksValid(child) then return nil end
    local context = maluaTryRead(Memory.ReadLong, child + 0x18)
    if not maluaPointerLooksValid(context) then return nil end
    local info = maluaTryRead(Memory.ReadLong, context + 0x40)
    if not maluaPointerLooksValid(info) then return nil end
    local fallbackHash = nil
    local fallbackOffset = nil
    for _, hashOffset in ipairs({0x10, 0x18}) do
        local hash = maluaTryRead(Memory.ReadUInt, info + hashOffset)
        if hash then
            hash = maluaU32(hash)
            if not fallbackHash then
                fallbackHash = hash
                fallbackOffset = hashOffset
            end
            local name = MALUA_TANK_COMPONENT_WEAPON_HASHES[hash]
            if name then
                return {
                    child = child,
                    context = context,
                    info = info,
                    hash = hash,
                    hashOffset = hashOffset,
                    name = name,
                }
            end
        end
    end
    if not fallbackHash then return nil end
    return {
        child = child,
        context = context,
        info = info,
        hash = fallbackHash,
        hashOffset = fallbackOffset,
        name = nil,
    }
end

-- The Enhanced seat-component getter can return a wrapper whose first field is
-- the raw manager entry, rather than a C++ object.  Score both the raw entry
-- and the getter result before following the pointer graph; otherwise the
-- wrapper is mistaken for a component and every downstream field is garbage.
local function maluaTankProbeComponent(address, layout)
    if not address or not maluaPointerLooksValid(address) then return nil, 0 end
    local probe = {
        address = address,
        first = maluaTryRead(Memory.ReadLong, address),
        state = maluaTryRead(Memory.ReadLong, address + 0x18),
    }
    local score = 0
    local first = probe.first
    if first and layout and first >= layout.base
        and first < layout.base + layout.imageSize then
        score = score + 20
    end
    if maluaPointerLooksValid(probe.state) then score = score + 8 end

    local weaponInfo = maluaTankReadComponentWeaponInfo(address)
    if weaponInfo then
        probe.weaponInfo = weaponInfo
        probe.weaponHash = weaponInfo.hash
        probe.weaponName = weaponInfo.name
        score = score + 30
        if weaponInfo.name then score = score + 80 end
    end
    return probe, score
end

maluaNearFloat = function(left, right)
    if type(left) ~= "number" or type(right) ~= "number" then return false end
    if left ~= left or right ~= right then return false end
    local tolerance = math.max(0.0005, math.abs(right) * 0.002)
    return math.abs(left - right) <= tolerance
end

local function maluaTankResolveRuntimeWeaponInterval(component)
    if not component or not component.weaponInfo or not component.weaponHash
        or not menu.nativeApis.WEAPON or type(menu.nativeApis.WEAPON.GET_WEAPON_TIME_BETWEEN_SHOTS) ~= "function" then
        return nil
    end
    local info = component.weaponInfo.info
    local nativeOk, expected = pcall(
        menu.nativeApis.WEAPON.GET_WEAPON_TIME_BETWEEN_SHOTS,
        component.weaponHash
    )
    if not nativeOk or type(expected) ~= "number" or expected ~= expected
        or expected <= 0.001 or expected >= 100.0 then
        return nil
    end

    local offsets = {0x13C}
    for offset = 0x20, 0x500, 4 do
        if offset ~= 0x13C then offsets[#offsets + 1] = offset end
    end
    for _, offset in ipairs(offsets) do
        local address = info + offset
        local value = maluaTryRead(Memory.ReadFloat, address)
        if value and maluaNearFloat(value, expected) then
            return {
                component = component,
                info = info,
                hash = component.weaponHash,
                name = component.weaponName or "unknown",
                address = address,
                offset = offset,
                original = value,
                expected = expected,
            }
        end
    end
    return nil
end

local function maluaResolveTankCooldownField(pair)
    if not pair or not pair.tankWeapon then
        return nil, "vehicle_weapon_tank CWeaponInfo was not found"
    end
    if not menu.nativeApis.WEAPON or type(menu.nativeApis.WEAPON.GET_WEAPON_TIME_BETWEEN_SHOTS) ~= "function" then
        return nil, "GET_WEAPON_TIME_BETWEEN_SHOTS is unavailable"
    end

    local targets = {}
    for _, definition in ipairs(MALUA_TANK_COOLDOWN_HASHES) do
        local weapon = pair[definition.name .. "Weapon"]
        if weapon and weapon ~= 0 then
            local ok, value = pcall(menu.nativeApis.WEAPON.GET_WEAPON_TIME_BETWEEN_SHOTS, definition.hash)
            if ok and type(value) == "number" and value == value and value > 0.001 and value < 100.0 then
                targets[#targets + 1] = {
                    name = definition.name,
                    hash = definition.hash,
                    weapon = weapon,
                    expected = value,
                    required = definition.required,
                }
            end
        elseif definition.required then
            return nil, definition.name .. " weapon info is missing"
        end
    end

    if #targets == 0 then return nil, "weapon cooldown getter returned no values" end
    local offsets = {0x13C}
    for offset = 0x20, 0x1200, 4 do
        if offset ~= 0x13C then offsets[#offsets + 1] = offset end
    end
    for _, offset in ipairs(offsets) do
        local matched = true
        local values = {}
        for _, target in ipairs(targets) do
            local value = maluaTryRead(Memory.ReadFloat, target.weapon + offset)
            if not value or not maluaNearFloat(value, target.expected) then
                matched = false
                break
            end
            values[target.name] = value
        end
        if matched then
            return offset, targets, values
        end
    end
    return nil, "shared time-between-shots field was not found"
end

local MALuaTankCannonCooldownPatch = {
    desired = false,
    active = false,
    restorePending = false,
    definitionRestorePending = false,
    definitionProbeRestores = nil,
    entries = nil,
    offset = nil,
    pair = nil,
    componentGetter = nil,
    runtime = nil,
    lastRuntimeError = nil,
    lastRuntimeLog = 0,
    nextRestoreAt = 0.0,
}

local function maluaTankGetCurrentVehicle()
    local ped = menu.nativeApis.PLAYER.PLAYER_PED_ID()
    if not ped or ped == 0 then return nil end
    local vehicle = menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if not vehicle or vehicle == 0 then return nil end
    local model = menu.nativeApis.ENTITY.GET_ENTITY_MODEL(vehicle) & 0xFFFFFFFF
    local name = MALUA_TANK_MODELS[model]
    if not name then return nil end
    return vehicle, ped, model, name
end

local function maluaTankReadReloadTime(vehicle, seat)
    local native = menu.nativeApis.WEAPON and menu.nativeApis.WEAPON._GET_VEHICLE_WEAPON_RELOAD_TIME
    local ok, value
    if type(native) == "function" then
        ok, value = pcall(native, vehicle, seat)
    elseif Natives and type(Natives.InvokeFloat) == "function" then
        ok, value = pcall(
            Natives.InvokeFloat,
            MALUA_GET_VEHICLE_WEAPON_RELOAD_TIME,
            vehicle,
            seat
        )
    else
        return nil
    end
    if not ok then return nil, tostring(value) end
    if type(value) ~= "number" or value ~= value then
        return nil, "reload-time result type=" .. type(value)
    end
    return value, nil
end

local function maluaTankReadRemaining(vehicle, seat)
    local native = menu.nativeApis.WEAPON and menu.nativeApis.WEAPON._GET_TIME_BEFORE_VEHICLE_WEAPON_RELOAD_FINISHES
    local ok, value
    if type(native) == "function" then
        ok, value = pcall(native, vehicle, seat)
    elseif Natives and type(Natives.InvokeInt) == "function" then
        ok, value = pcall(
            Natives.InvokeInt,
            MALUA_GET_TIME_BEFORE_VEHICLE_WEAPON_RELOAD_FINISHES,
            vehicle,
            seat
        )
    else
        return nil
    end
    if not ok then return nil, tostring(value) end
    if type(value) ~= "number" then return nil, "remaining result type=" .. type(value) end
    return value, nil
end

local function maluaTankReadReloading(vehicle, seat)
    local native = menu.nativeApis.WEAPON and menu.nativeApis.WEAPON._HAS_WEAPON_RELOADING_IN_VEHICLE
    local ok, value
    if type(native) == "function" then
        ok, value = pcall(native, vehicle, seat)
    elseif Natives and type(Natives.InvokeBool) == "function" then
        ok, value = pcall(
            Natives.InvokeBool,
            MALUA_HAS_WEAPON_RELOADING_IN_VEHICLE,
            vehicle,
            seat
        )
    else
        return nil
    end
    if not ok then return nil, tostring(value) end
    if type(value) ~= "boolean" then
        return nil, "reloading result type=" .. type(value)
    end
    return value, nil
end

local function maluaTankGetGameTimer()
    local ok, value = pcall(menu.nativeApis.MISC.GET_GAME_TIMER)
    return ok and type(value) == "number" and (value & 0xFFFFFFFF) or nil
end

local function maluaTankHeapPointerLooksValid(value)
    return type(value) == "number"
        and value >= 0x0000010000000000
        and value < 0x0000700000000000
        and value % 8 == 0
end

local function maluaTankEnumerateDurationCandidates(runtime, expected)
    local candidates = {}
    local objects = runtime.objects or {
        {name = "component", address = runtime.component, limit = MALUA_TANK_COMPONENT_SCAN_LIMIT},
        {name = "state", address = runtime.state, limit = MALUA_TANK_STATE_SCAN_LIMIT},
    }
    for _, object in ipairs(objects) do
        if maluaPointerLooksValid(object.address) then
            for offset = 0, object.limit, 4 do
                local address = object.address + offset
                local floatValue = maluaTryRead(Memory.ReadFloat, address)
                if floatValue then
                    local floatTargets = {
                        {value = expected, scale = 1.0},
                        {value = expected / 1000.0, scale = 1000.0},
                    }
                    for _, target in ipairs(floatTargets) do
                        if maluaNearFloat(floatValue, target.value) then
                            candidates[#candidates + 1] = {
                                owner = object.name,
                                offset = offset,
                                address = address,
                                kind = "float",
                                scale = target.scale,
                                original = floatValue,
                            }
                        end
                    end
                end
                local uintValue = maluaTryRead(Memory.ReadUInt, address)
                local uintTolerance = math.max(1.0, math.abs(expected) * 0.002)
                if uintValue and math.abs(uintValue - expected) <= uintTolerance then
                    candidates[#candidates + 1] = {
                        owner = object.name,
                        offset = offset,
                        address = address,
                        kind = "uint",
                        scale = 1.0,
                        original = uintValue,
                    }
                end
            end
        end
    end
    return candidates
end

local function maluaTankReadDurationCandidate(candidate)
    if candidate.kind == "uint" then
        return maluaTryRead(Memory.ReadUInt, candidate.address)
    end
    return maluaTryRead(Memory.ReadFloat, candidate.address)
end

local function maluaTankWriteDurationCandidate(candidate, value)
    if candidate.kind == "uint" then
        return Memory.WriteUInt(candidate.address, math.floor(value + 0.5))
    end
    return Memory.WriteFloat(candidate.address, value)
end

local function maluaTankDurationCandidateIsZero(candidate, value)
    if candidate.kind == "uint" then return value == 0 end
    return maluaNearFloat(value, 0.0)
end

local function maluaTankEnumerateTimerCandidates(runtime, remaining, gameTimer)
    local candidates = {}
    local objects = runtime.objects or {
        {name = "component", address = runtime.component, limit = MALUA_TANK_COMPONENT_SCAN_LIMIT},
        {name = "state", address = runtime.state, limit = MALUA_TANK_STATE_SCAN_LIMIT},
    }
    for _, object in ipairs(objects) do
        if maluaPointerLooksValid(object.address) then
            for offset = 0, object.limit, 4 do
                local value = maluaTryRead(Memory.ReadUInt, object.address + offset)
                if value then
                    if math.abs(value - remaining) <= 32 then
                        candidates[#candidates + 1] = {
                            owner = object.name,
                            offset = offset,
                            address = object.address + offset,
                            original = value,
                            kind = "uint",
                            mode = "remaining",
                        }
                    end
                    if gameTimer then
                        local delta = ((value - gameTimer + 0x80000000) & 0xFFFFFFFF) - 0x80000000
                        if math.abs(delta - remaining) <= 64 then
                            candidates[#candidates + 1] = {
                                owner = object.name,
                                offset = offset,
                                address = object.address + offset,
                                original = value,
                                kind = "uint",
                                mode = "deadline",
                            }
                        end
                    end
                end
            end
        end
    end
    return candidates
end

local function maluaTankAddCorrelatedTimerCandidate(runtime, candidate)
    runtime.timerCorrelationScores = runtime.timerCorrelationScores or {}
    local key = string.format("%s:%s:%X", candidate.kind, candidate.mode, candidate.address)
    local score = runtime.timerCorrelationScores[key]
    if not score then
        score = {hits = 0, candidate = candidate, lastSample = -1}
        runtime.timerCorrelationScores[key] = score
    end
    if score.lastSample ~= runtime.timerCorrelationSample then
        score.hits = score.hits + 1
        score.lastSample = runtime.timerCorrelationSample
    end
    score.candidate = candidate
    score.candidate.hits = score.hits
end

local function maluaTankCollectCorrelatedTimerCandidates(runtime, remaining)
    runtime.timerCorrelationSnapshot = runtime.timerCorrelationSnapshot or {}
    runtime.timerCorrelationScores = runtime.timerCorrelationScores or {}
    runtime.timerCorrelationSample = (runtime.timerCorrelationSample or 0) + 1
    local previousRemaining = runtime.timerCorrelationRemaining
    local deltaRemaining = previousRemaining and (previousRemaining - remaining) or nil
    local canCorrelate = deltaRemaining and deltaRemaining >= 40 and deltaRemaining <= 700
    local duration = runtime.reloadBaseline or 1500.0

    for _, object in ipairs(runtime.objects or {}) do
        if maluaPointerLooksValid(object.address) then
            for offset = 0, object.limit, 4 do
                local address = object.address + offset
                local uintValue = maluaTryRead(Memory.ReadUInt, address)
                local floatValue = maluaTryRead(Memory.ReadFloat, address)
                local previous = runtime.timerCorrelationSnapshot[address]
                if canCorrelate and previous then
                    local uintTolerance = math.max(8.0, deltaRemaining * 0.10)
                    if uintValue and previous.uint
                        and uintValue <= 60000 and previous.uint <= 60000
                        and math.abs((previous.uint - uintValue) - deltaRemaining) <= uintTolerance then
                        maluaTankAddCorrelatedTimerCandidate(runtime, {
                            owner = object.name,
                            offset = offset,
                            address = address,
                            original = uintValue,
                            kind = "uint",
                            mode = "correlated_remaining",
                        })
                    end

                    if floatValue and previous.float
                        and floatValue == floatValue and previous.float == previous.float then
                        local floatDelta = previous.float - floatValue
                        local expectedSeconds = deltaRemaining / 1000.0
                        if floatValue >= 0.0 and floatValue <= 60.0
                            and previous.float >= 0.0 and previous.float <= 60.0
                            and math.abs(floatDelta - expectedSeconds)
                                <= math.max(0.015, expectedSeconds * 0.12) then
                            maluaTankAddCorrelatedTimerCandidate(runtime, {
                                owner = object.name,
                                offset = offset,
                                address = address,
                                original = floatValue,
                                kind = "float",
                                mode = "correlated_seconds_remaining",
                            })
                        end
                        if floatValue >= 0.0 and floatValue <= 60000.0
                            and previous.float >= 0.0 and previous.float <= 60000.0
                            and math.abs(floatDelta - deltaRemaining)
                                <= math.max(8.0, deltaRemaining * 0.10) then
                            maluaTankAddCorrelatedTimerCandidate(runtime, {
                                owner = object.name,
                                offset = offset,
                                address = address,
                                original = floatValue,
                                kind = "float",
                                mode = "correlated_milliseconds_remaining",
                            })
                        end
                        if duration > 0.0 then
                            local expectedRatio = deltaRemaining / duration
                            if floatValue >= 0.0 and floatValue <= 1.25
                                and previous.float >= 0.0 and previous.float <= 1.25
                                and math.abs(floatDelta - expectedRatio)
                                    <= math.max(0.01, expectedRatio * 0.15) then
                                maluaTankAddCorrelatedTimerCandidate(runtime, {
                                    owner = object.name,
                                    offset = offset,
                                    address = address,
                                    original = floatValue,
                                    kind = "float",
                                    mode = "correlated_remaining_ratio",
                                })
                            end
                            local progressDelta = floatValue - previous.float
                            if floatValue >= 0.0 and floatValue <= 1.25
                                and previous.float >= 0.0 and previous.float <= 1.25
                                and math.abs(progressDelta - expectedRatio)
                                    <= math.max(0.01, expectedRatio * 0.15) then
                                maluaTankAddCorrelatedTimerCandidate(runtime, {
                                    owner = object.name,
                                    offset = offset,
                                    address = address,
                                    original = floatValue,
                                    kind = "float",
                                    mode = "correlated_progress_ratio",
                                })
                            end
                        end
                    end
                end
                runtime.timerCorrelationSnapshot[address] = {
                    uint = uintValue,
                    float = floatValue,
                }
            end
        end
    end
    runtime.timerCorrelationRemaining = remaining

    local result = {}
    for _, score in pairs(runtime.timerCorrelationScores) do
        if score.hits >= 2 then result[#result + 1] = score.candidate end
    end
    table.sort(result, function(left, right)
        if (left.hits or 0) ~= (right.hits or 0) then
            return (left.hits or 0) > (right.hits or 0)
        end
        return left.address < right.address
    end)
    return result
end

local function maluaTankDeduplicateTimerCandidates(candidates, mode)
    local result = {}
    local seen = {}
    for _, candidate in ipairs(candidates or {}) do
        if (not mode or candidate.mode == mode) and not seen[candidate.address] then
            seen[candidate.address] = true
            result[#result + 1] = candidate
        end
    end
    return result
end

local function maluaTankTestTimerCandidateGroup(runtime, candidates)
    if not candidates or #candidates == 0 then return false, nil end
    runtime.timerProbeRestores = runtime.timerProbeRestores or {}
    if runtime.timerProbeRestorePending or next(runtime.timerProbeRestores) ~= nil then
        runtime.timerProbeRestorePending = true
        return false, nil
    end
    local gameTimer = maluaTankGetGameTimer() or 0
    local prepared = {}
    for _, candidate in ipairs(candidates) do
        local reader = candidate.kind == "float" and Memory.ReadFloat or Memory.ReadUInt
        local original = maluaTryRead(reader, candidate.address)
        if original == nil then return false, nil end
        prepared[#prepared + 1] = {
            candidate = candidate,
            reader = reader,
            writer = candidate.kind == "float" and Memory.WriteFloat or Memory.WriteUInt,
            original = original,
            value = candidate.mode == "deadline" and gameTimer
                or candidate.mode == "correlated_progress_ratio" and 1.0 or 0,
        }
    end
    local writeOk = true
    for _, item in ipairs(prepared) do
        local candidate = item.candidate
        runtime.timerProbeRestores[candidate.address] = {
            address = candidate.address,
            kind = candidate.kind,
            original = item.original,
            value = item.value,
        }
        local ok = pcall(item.writer, candidate.address, item.value)
        local verify = ok and maluaTryRead(item.reader, candidate.address) or nil
        if not ok or not MALuaTankCannonCooldownPatch:TimerValueMatches(candidate, verify, item.value) then
            writeOk = false
            break
        end
    end

    local changed = nil
    if writeOk then
        changed = maluaTankReadRemaining(runtime.vehicle, runtime.seat)
    end
    local rollbackOk = true
    for address, tracked in pairs(runtime.timerProbeRestores) do
        local candidate = {address = address, kind = tracked.kind}
        local reader = tracked.kind == "float" and Memory.ReadFloat or Memory.ReadUInt
        local writer = tracked.kind == "float" and Memory.WriteFloat or Memory.WriteUInt
        local current = maluaTryRead(reader, address)
        if MALuaTankCannonCooldownPatch:TimerValueMatches(candidate, current, tracked.original) then
            runtime.timerProbeRestores[address] = nil
        elseif MALuaTankCannonCooldownPatch:TimerValueMatches(candidate, current, tracked.value) then
            local restoreOk = pcall(writer, address, tracked.original)
            local restoreVerify = restoreOk and maluaTryRead(reader, address) or nil
            if restoreOk and MALuaTankCannonCooldownPatch:TimerValueMatches(
                candidate, restoreVerify, tracked.original
            ) then
                runtime.timerProbeRestores[address] = nil
            else
                rollbackOk = false
            end
        elseif current == nil then
            rollbackOk = false
        else
            runtime.timerProbeRestores[address] = nil
        end
    end
    runtime.timerProbeRestorePending = next(runtime.timerProbeRestores) ~= nil
    return writeOk and rollbackOk and not runtime.timerProbeRestorePending
        and changed ~= nil and changed <= 16, changed
end

local function maluaTankMinimizeTimerCandidateGroup(runtime, candidates)
    local verified = maluaTankTestTimerCandidateGroup(runtime, candidates)
    if not verified then return nil end

    local result = {}
    for _, candidate in ipairs(candidates) do result[#result + 1] = candidate end
    local index = 1
    while #result > 1 and index <= #result do
        local trial = {}
        for candidateIndex, candidate in ipairs(result) do
            if candidateIndex ~= index then trial[#trial + 1] = candidate end
        end
        if maluaTankTestTimerCandidateGroup(runtime, trial) then
            result = trial
        else
            index = index + 1
        end
    end
    return result
end

function MALuaTankCannonCooldownPatch:ResolveComponentGetter()
    if self.componentGetter and self.componentGetter ~= 0 then return self.componentGetter end
    local _, _, moduleName = Utils1:editionInfo()
    if not moduleName then return nil, "GTA edition is unresolved" end
    local ok, scan = pcall(Memory.Scan, MALUA_TANK_COMPONENT_PATTERN, moduleName)
    if not ok or not scan or scan == 0 then
        return nil, "seat weapon component signature was not found"
    end
    self.componentGetter = scan
    return scan
end

function MALuaTankCannonCooldownPatch:ResolveRuntime(vehicle, ped, model, modelName)
    local getter = nil
    if Memory and type(Memory.LuaCallCFunctionWithReturnValue) == "function" then
        getter = self:ResolveComponentGetter()
    end

    local componentLayout = nil
    pcall(function()
        componentLayout = maluaModuleLayout()
    end)

    local physical = GTA.HandleToPointer(vehicle)
    local vehicleAddress = physical and physical:GetAddress() or 0
    if not maluaPointerLooksValid(vehicleAddress) then return nil, "vehicle pointer is invalid" end
    local manager = maluaTryRead(Memory.ReadLong, vehicleAddress + MALUA_TANK_WEAPON_MANAGER_OFFSET)
    if not maluaPointerLooksValid(manager) then return nil, "vehicle weapon manager is unavailable" end
    local count = maluaTryRead(Memory.ReadUInt, manager + 0x114)
    if not count or count < 1 or count > 16 then
        return nil, "vehicle weapon component count is invalid"
    end

    local nativeSeat = -1
    if menu.nativeApis.VEHICLE and type(menu.nativeApis.VEHICLE.GET_PED_IN_VEHICLE_SEAT) == "function" then
        for seat = -1, 7 do
            local seatOk, seatPed = pcall(menu.nativeApis.VEHICLE.GET_PED_IN_VEHICLE_SEAT, vehicle, seat, false)
            if seatOk and seatPed == ped then
                nativeSeat = seat
                break
            end
        end
    end

    local components = {}
    local seen = {}
    local rawEntries = {}
    local rawComponents = {}
    for index = 0, count - 1 do
        local rawComponent = maluaTryRead(Memory.ReadLong, manager + 0x68 + index * 8)
        local rawSeatKey = maluaTryRead(Memory.ReadUInt, manager + 0x98 + index * 4)
        local seatKey = rawSeatKey
        if seatKey and seatKey >= 0x80000000 then seatKey = seatKey - 0x100000000 end
        rawEntries[#rawEntries + 1] = string.format(
            "%d:seat=%s/raw=0x%X",
            index, tostring(seatKey), rawComponent or 0
        )

        if seatKey and maluaPointerLooksValid(rawComponent) then
            rawComponents[#rawComponents + 1] = {
                index = index,
                seatKey = seatKey,
                address = rawComponent,
            }
            local component = rawComponent
            local source = "raw"
            local selectedProbe, selectedScore = maluaTankProbeComponent(
                rawComponent,
                componentLayout
            )
            if getter and selectedScore < 40 then
                local callOk, returnedSlot = pcall(
                    Memory.LuaCallCFunctionWithReturnValue,
                    getter,
                    manager,
                    seatKey
                )
                if callOk and maluaPointerLooksValid(returnedSlot) then
                    -- LuaCallCFunctionWithReturnValue returns a pointer to the
                    -- native return slot.  The component pointer is stored in
                    -- that slot, as shown by the getter's `mov r14,[...+0x68]`
                    -- return path in the Enhanced build.
                    local returned = maluaTryRead(Memory.ReadLong, returnedSlot)
                    local candidates = {returned}
                    -- Keep direct-return compatibility for runtimes that expose
                    -- the value instead of the temporary return slot.
                    if returnedSlot ~= returned then
                        candidates[#candidates + 1] = returnedSlot
                    end
                    for _, candidate in ipairs(candidates) do
                        if maluaPointerLooksValid(candidate) then
                            local returnedProbe, returnedScore = maluaTankProbeComponent(
                                candidate,
                                componentLayout
                            )
                            if returnedProbe and returnedScore > selectedScore then
                                component = candidate
                                source = "getter"
                                selectedProbe = returnedProbe
                                selectedScore = returnedScore
                            end
                        end
                    end
                end
            end
            if not seen[component] then
                seen[component] = true
                components[#components + 1] = {
                    index = index,
                    seatKey = seatKey,
                    address = component,
                    rawAddress = rawComponent,
                    source = source,
                    first = selectedProbe and selectedProbe.first
                        or maluaTryRead(Memory.ReadLong, component),
                    state = selectedProbe and selectedProbe.state
                        or maluaTryRead(Memory.ReadLong, component + 0x18),
                }
                local weaponInfo = selectedProbe and selectedProbe.weaponInfo
                    or maluaTankReadComponentWeaponInfo(component)
                components[#components].weaponHash = weaponInfo and weaponInfo.hash or nil
                components[#components].weaponName = weaponInfo and weaponInfo.name or nil
                components[#components].weaponInfo = weaponInfo
            end
        end
    end
    if #components == 0 then
        return nil, string.format(
            "no readable seat weapon component count=%d entries=[%s]",
            count, table.concat(rawEntries, ",")
        )
    end

    local objects = {}
    for _, component in ipairs(components) do
        objects[#objects + 1] = {
            name = string.format(
                "component[%d,seat=%d,%s]",
                component.index, component.seatKey, component.source
            ),
            address = component.address,
            limit = MALUA_TANK_COMPONENT_SCAN_LIMIT,
        }
        if maluaPointerLooksValid(component.state) then
            objects[#objects + 1] = {
                name = string.format(
                    "state[%d,seat=%d,%s]",
                    component.index, component.seatKey, component.source
                ),
                address = component.state,
                limit = MALUA_TANK_STATE_SCAN_LIMIT,
            }
        end
    end

    local primary = components[1]
    local preferredComponent = nil
    local preferredScore = -1
    for _, component in ipairs(components) do
        local score = 0
        if component.weaponName == "khanjaliHeavy" then
            score = 40
        elseif component.weaponName == "khanjali" then
            score = 30
        elseif component.weaponName == "tank" then
            score = 20
        end
        if component.seatKey == nativeSeat then score = score + 5 end
        if score > preferredScore then
            preferredScore = score
            preferredComponent = component
        end
    end
    if modelName == "Khanjali" and preferredComponent and preferredScore > 0 then
        primary = preferredComponent
    end
    local componentEntries = {}
    for _, component in ipairs(components) do
        componentEntries[#componentEntries + 1] = string.format(
            "%d:seat=%d/hash=%s/name=%s%s",
            component.index,
            component.seatKey,
            component.weaponHash and string.format("0x%X", component.weaponHash) or "nil",
            tostring(component.weaponName or "unknown"),
            component == primary and "/primary" or ""
        )
    end
    local runtimeIntervalFields = {}
    for _, component in ipairs(components) do
        local interval = maluaTankResolveRuntimeWeaponInterval(component)
        if interval then
            runtimeIntervalFields[#runtimeIntervalFields + 1] = interval
        end
    end
    local reloadSeats = {}
    local seenSeats = {}
    local function addReloadSeat(seat)
        if type(seat) == "number" and not seenSeats[seat] then
            seenSeats[seat] = true
            reloadSeats[#reloadSeats + 1] = seat
        end
    end
    addReloadSeat(primary.seatKey)
    for _, component in ipairs(components) do addReloadSeat(component.seatKey) end
    addReloadSeat(nativeSeat)
    addReloadSeat(nativeSeat + 1)
    return {
        vehicle = vehicle,
        vehicleAddress = vehicleAddress,
        model = model,
        modelName = modelName,
        manager = manager,
        components = components,
        objects = objects,
        component = primary.address,
        state = primary.state,
        pedSeat = nativeSeat,
        seat = primary.seatKey,
        reloadSeats = reloadSeats,
        componentSeat = primary.seatKey,
        durationField = nil,
        durationProbeAttempts = 0,
        nextDurationProbe = 0,
        lastDurationError = nil,
        lastDurationErrorLog = 0,
        timerField = nil,
        timerFields = nil,
        timerWrites = {},
        timerProbeRestores = {},
        timerProbeRestorePending = false,
        durationProbeRestore = nil,
        durationRestorePending = false,
        timerProbeAttempts = 0,
        nextTimerProbe = 0,
        timerCorrelationSnapshot = nil,
        timerCorrelationScores = nil,
        timerCorrelationRemaining = nil,
        timerCorrelationSample = 0,
        reloadBaseline = nil,
        rawEntries = rawEntries,
        rawComponents = rawComponents,
        componentEntries = componentEntries,
        primaryComponentIndex = primary.index,
        primaryComponentSeat = primary.seatKey,
        primaryWeaponHash = primary.weaponHash,
        primaryWeaponName = primary.weaponName,
        runtimeIntervalFields = runtimeIntervalFields,
        pointerGraphMaxDepth = modelName == "Khanjali"
            and math.max(MALUA_TANK_POINTER_GRAPH_MAX_DEPTH, 4)
            or MALUA_TANK_POINTER_GRAPH_MAX_DEPTH,
        pointerGraphScanLimit = modelName == "Khanjali"
            and math.max(MALUA_TANK_POINTER_GRAPH_SCAN_LIMIT, 0x500)
            or MALUA_TANK_POINTER_GRAPH_SCAN_LIMIT,
        pointerGraphObjectLimit = modelName == "Khanjali"
            and math.max(MALUA_TANK_POINTER_GRAPH_OBJECT_LIMIT, 128)
            or MALUA_TANK_POINTER_GRAPH_OBJECT_LIMIT,
    }
end

local function maluaTankFormatVtableSlots(vtable, layout, maxSlot)
    if not vtable or vtable < layout.base
        or vtable >= layout.base + layout.imageSize then
        return "outside-module"
    end
    local slots = {}
    for slot = 0, maxSlot do
        local fn = maluaTryRead(Memory.ReadLong, vtable + slot * 8)
        if fn and fn >= layout.base and fn < layout.base + layout.imageSize then
            slots[#slots + 1] = string.format("%02d=0x%X", slot, fn - layout.base)
        else
            slots[#slots + 1] = string.format(
                "%02d=%s", slot, fn and string.format("0x%X", fn) or "nil"
            )
        end
    end
    return table.concat(slots, ",")
end

function MALuaTankCannonCooldownPatch:LogRuntimeLayout(runtime)
    if runtime.layoutLogged then return end
    runtime.layoutLogged = true
    local layout, layoutError = maluaModuleLayout()
    if not layout then
        maluaTankSilent("[mALuaTankLayout] module layout failed: " .. tostring(layoutError))
        return
    end

    local loggedVtables = {}
    for _, component in ipairs(runtime.components or {}) do
        local address = component.address
        local vtable = maluaTryRead(Memory.ReadLong, address)
        local count = maluaTryRead(Memory.ReadUInt, address + 0x1E8)
        local index = maluaTryRead(Memory.ReadUInt, address + 0x1EC)
        local child = maluaTryRead(Memory.ReadLong, address + 0x18)
        local childVtable = maluaPointerLooksValid(child)
            and maluaTryRead(Memory.ReadLong, child) or nil
        local context = maluaPointerLooksValid(child)
            and maluaTryRead(Memory.ReadLong, child + 0x18) or nil
        local info = maluaPointerLooksValid(context)
            and maluaTryRead(Memory.ReadLong, context + 0x40) or nil
        local weaponHash = maluaPointerLooksValid(info)
            and maluaTryRead(Memory.ReadUInt, info + 0x10) or nil
        maluaTankSilent(string.format(
            "[mALuaTankLayout] component=%d seat=%d source=%s raw=0x%X address=0x%X vtable=%s vtableRva=%s childCount=%s childIndex=%s child=%s childVtable=%s childVtableRva=%s context=%s info=%s weaponHash=%s component1F4=0x%X child24=0x%X child1F4=0x%X",
            component.index,
            component.seatKey,
            component.source,
            component.rawAddress or 0,
            address,
            vtable and string.format("0x%X", vtable) or "nil",
            vtable and vtable >= layout.base and vtable < layout.base + layout.imageSize
                and string.format("0x%X", vtable - layout.base) or "nil",
            tostring(count),
            tostring(index),
            child and string.format("0x%X", child) or "nil",
            childVtable and string.format("0x%X", childVtable) or "nil",
            childVtable and childVtable >= layout.base
                and childVtable < layout.base + layout.imageSize
                and string.format("0x%X", childVtable - layout.base) or "nil",
            context and string.format("0x%X", context) or "nil",
            info and string.format("0x%X", info) or "nil",
            weaponHash and string.format("0x%X", maluaU32(weaponHash)) or "nil",
            maluaTryRead(Memory.ReadUInt, address + 0x1F4) or 0,
            maluaPointerLooksValid(child)
                and (maluaTryRead(Memory.ReadUInt, child + 0x24) or 0) or 0,
            maluaPointerLooksValid(child)
                and (maluaTryRead(Memory.ReadUInt, child + 0x1F4) or 0) or 0
        ))
        for label, candidateVtable in pairs({
            component = vtable,
            child = childVtable,
        }) do
            if candidateVtable and not loggedVtables[candidateVtable] then
                loggedVtables[candidateVtable] = true
                maluaTankSilent(string.format(
                    "[mALuaTankLayout] %sVtable=0x%X rva=0x%X slots=[%s]",
                    label,
                    candidateVtable,
                    candidateVtable - layout.base,
                    maluaTankFormatVtableSlots(candidateVtable, layout, 31)
                ))
            end
        end
    end
end

function MALuaTankCannonCooldownPatch:RefreshRuntimeObjects(runtime)
    local known = {}
    for _, object in ipairs(runtime.objects or {}) do known[object.address] = true end
    local added = 0
    for _, component in ipairs(runtime.components or {}) do
        local state = maluaTryRead(Memory.ReadLong, component.address + 0x18)
        component.state = state
        if maluaPointerLooksValid(state) and not known[state] then
            known[state] = true
            runtime.objects[#runtime.objects + 1] = {
                name = string.format(
                    "state[%d,seat=%d,%s]",
                    component.index, component.seatKey, component.source
                ),
                address = state,
                limit = MALUA_TANK_STATE_SCAN_LIMIT,
            }
            added = added + 1
        end
    end
    return added
end

function MALuaTankCannonCooldownPatch:ExpandRuntimeObjectGraph(runtime)
    if runtime.pointerGraphExpanded then return 0 end
    runtime.pointerGraphExpanded = true

    local known = {}
    local queue = {}
    for _, object in ipairs(runtime.objects or {}) do
        known[object.address] = true
        queue[#queue + 1] = {
            object = object,
            depth = 0,
        }
    end

    local added = 0
    local cursor = 1
    local maxDepth = runtime.pointerGraphMaxDepth or MALUA_TANK_POINTER_GRAPH_MAX_DEPTH
    local graphScanLimit = runtime.pointerGraphScanLimit or MALUA_TANK_POINTER_GRAPH_SCAN_LIMIT
    local graphObjectLimit = runtime.pointerGraphObjectLimit or MALUA_TANK_POINTER_GRAPH_OBJECT_LIMIT
    while cursor <= #queue and added < graphObjectLimit do
        local current = queue[cursor]
        cursor = cursor + 1
        if current.depth < maxDepth then
            local parent = current.object
            local scanLimit = math.min(
                parent.limit or MALUA_TANK_POINTER_GRAPH_SCAN_LIMIT,
                graphScanLimit
            )
            for offset = 0, scanLimit, 8 do
                if added >= graphObjectLimit then break end
                local pointer = maluaTryRead(Memory.ReadLong, parent.address + offset)
                if maluaTankHeapPointerLooksValid(pointer) and not known[pointer] then
                    local readable = maluaTryRead(Memory.ReadUByte, pointer)
                    if readable ~= nil then
                        local depth = current.depth + 1
                        local object = {
                            name = string.format(
                                "nested[d%d,%s+0x%X]",
                                depth, parent.name, offset
                            ),
                            address = pointer,
                            limit = graphScanLimit,
                        }
                        known[pointer] = true
                        runtime.objects[#runtime.objects + 1] = object
                        queue[#queue + 1] = {
                            object = object,
                            depth = depth,
                        }
                        added = added + 1
                    end
                end
            end
        end
    end

    runtime.pointerGraphAdded = added
    runtime.timerProbeAttempts = 0
    runtime.nextTimerProbe = 0
    maluaTankSilent(string.format(
        "[mALuaTankCooldown] expanded runtime pointer graph objects=%d added=%d depth=%d scan=0x%X",
        #(runtime.objects or {}), added, maxDepth, graphScanLimit
    ))
    return added
end

function MALuaTankCannonCooldownPatch:RestorePendingDefinitionProbes(errors, label)
    errors = errors or {}
    label = label or "definition probe restore"
    local pending = self.definitionProbeRestores or {}
    for address, entry in pairs(pending) do
        local current = maluaTryRead(Memory.ReadFloat, address)
        if current == nil then
            errors[#errors + 1] = entry.name .. " " .. label .. " is unreadable"
        elseif maluaNearFloat(current, 0.0) then
            pending[address] = nil
        elseif maluaNearFloat(current, entry.original) then
            local writeOk, writeError = pcall(Memory.WriteFloat, address, 0.0)
            local verify = writeOk and maluaTryRead(Memory.ReadFloat, address) or nil
            if writeOk and maluaNearFloat(verify, 0.0) then
                pending[address] = nil
            else
                errors[#errors + 1] = string.format(
                    "%s %s failed verify=%s error=%s",
                    entry.name, label, tostring(verify), tostring(writeError)
                )
            end
        else
            pending[address] = nil
            errors[#errors + 1] = entry.name .. " " .. label .. " ownership lost"
        end
    end
    self.definitionProbeRestores = pending
    self.definitionRestorePending = next(pending) ~= nil
    return not self.definitionRestorePending and #errors == 0
end

function MALuaTankCannonCooldownPatch:WithDefinitionsRestored(callback)
    local function writeDefinition(entry, value)
        local ok, err = pcall(Memory.WriteFloat, entry.address, value)
        local verify = ok and maluaTryRead(Memory.ReadFloat, entry.address) or nil
        return ok and maluaNearFloat(verify, value), err, verify
    end
    local function reapplyDefinitions(reason)
        local errors = {}
        self:RestorePendingDefinitionProbes(errors, "temporary definition restore")
        if self.definitionRestorePending and #errors == 0 then
            errors[#errors + 1] = "temporary definition restore remains pending"
        end
        if reason and #errors > 0 then
            return nil, reason .. "; " .. table.concat(errors, "; ")
        elseif reason then
            return nil, reason
        elseif #errors > 0 then
            return nil, table.concat(errors, "; ")
        end
        return true
    end
    if self.definitionRestorePending then
        local restored, restoreError = reapplyDefinitions()
        if not restored then return nil, restoreError end
    end
    self.definitionProbeRestores = self.definitionProbeRestores or {}
    for _, entry in ipairs(self.entries or {}) do
        local current = maluaTryRead(Memory.ReadFloat, entry.address)
        if current == nil then
            return reapplyDefinitions(entry.name .. " definition field is unreadable")
        elseif maluaNearFloat(current, 0.0) then
            self.definitionProbeRestores[entry.address] = entry
            self.definitionRestorePending = true
            local restored, err, verify = writeDefinition(entry, entry.original)
            if not restored then
                return reapplyDefinitions(string.format(
                    "%s temporary restore failed verify=%s error=%s",
                    entry.name, tostring(verify), tostring(err)
                ))
            end
        elseif maluaNearFloat(current, entry.original) then
            self.definitionProbeRestores[entry.address] = entry
            self.definitionRestorePending = true
        else
            return reapplyDefinitions(entry.name .. " definition ownership changed")
        end
    end
    local ok, first, second = pcall(callback)
    local callbackError = nil
    if not ok then callbackError = tostring(first) end
    local restored, restoreError = reapplyDefinitions(callbackError)
    if not restored then return nil, restoreError end
    return first, second
end

function MALuaTankCannonCooldownPatch:DiscoverDurationField(runtime)
    runtime.durationProbeAttempts = (runtime.durationProbeAttempts or 0) + 1
    runtime.nextDurationProbe = (maluaTankGetGameTimer() or 0) + 500
    if runtime.durationRestorePending then
        local restoreErrors = {}
        self:RestorePendingDurationProbe(runtime, restoreErrors, "duration probe restore")
        if runtime.durationRestorePending or #restoreErrors > 0 then
            return false, table.concat(restoreErrors, "; ")
        end
    end
    local result, probeError = self:WithDefinitionsRestored(function()
        local baseline = nil
        local profile = {}
        for _, seat in ipairs(runtime.reloadSeats or {runtime.seat}) do
            local duration, durationError = maluaTankReadReloadTime(runtime.vehicle, seat)
            local remaining, remainingError = maluaTankReadRemaining(runtime.vehicle, seat)
            local reloading, reloadingError = maluaTankReadReloading(runtime.vehicle, seat)
            profile[#profile + 1] = string.format(
                "seat=%d duration=%s remaining=%s reloading=%s errors=%s/%s/%s",
                seat, tostring(duration), tostring(remaining), tostring(reloading),
                tostring(durationError), tostring(remainingError), tostring(reloadingError)
            )
            if duration and duration > 0.5 and duration <= 60000.0 then
                runtime.seat = seat
                baseline = duration
                break
            end
            if (remaining and remaining > 0) or reloading then
                runtime.seat = seat
            end
        end
        if not baseline then
            return {error = "vehicle reload native profile [" .. table.concat(profile, "; ") .. "]"}
        end
        runtime.reloadBaseline = baseline

        local candidates = maluaTankEnumerateDurationCandidates(runtime, baseline)
        if #candidates == 0 and not runtime.pointerGraphExpanded then
            self:ExpandRuntimeObjectGraph(runtime)
            candidates = maluaTankEnumerateDurationCandidates(runtime, baseline)
        end
        for _, candidate in ipairs(candidates) do
            local nativeProbeValue = math.max(1.0, math.min(125.0, baseline * 0.25))
            local storageProbeValue = nativeProbeValue / (candidate.scale or 1.0)
            if candidate.kind == "uint" then
                storageProbeValue = math.floor(storageProbeValue + 0.5)
                nativeProbeValue = storageProbeValue * (candidate.scale or 1.0)
            end
            runtime.durationProbeRestore = {candidate = candidate, value = storageProbeValue}
            runtime.durationRestorePending = true
            local writeOk, writeError = pcall(
                maluaTankWriteDurationCandidate,
                candidate,
                storageProbeValue
            )
            local changed = writeOk and maluaTankReadReloadTime(runtime.vehicle, runtime.seat) or nil
            local rollbackOk, rollbackError = pcall(
                maluaTankWriteDurationCandidate,
                candidate,
                candidate.original
            )
            local restoredValue = rollbackOk and maluaTankReadDurationCandidate(candidate) or nil
            local restoredStorage = candidate.kind == "uint"
                and restoredValue == candidate.original
                or candidate.kind ~= "uint"
                and maluaNearFloat(restoredValue, candidate.original)
            if rollbackOk and restoredStorage then
                runtime.durationProbeRestore = nil
                runtime.durationRestorePending = false
            else
                return {
                    error = string.format(
                        "duration probe restore pending write=%s rollback=%s verify=%s error=%s/%s",
                        tostring(writeOk), tostring(rollbackOk), tostring(restoredValue),
                        tostring(writeError), tostring(rollbackError)
                    )
                }
            end
            local restored = maluaTankReadReloadTime(runtime.vehicle, runtime.seat)
            if writeOk and changed and restored
                and maluaNearFloat(changed, nativeProbeValue)
                and maluaNearFloat(restored, baseline) then
                return {candidate = candidate, baseline = baseline}
            end
        end
        return {
            error = string.format(
                "reload duration field unresolved baseline=%.6f candidates=%d objects=%d nested=%d",
                baseline, #candidates, #(runtime.objects or {}),
                runtime.pointerGraphAdded or 0
            )
        }
    end)
    if not result then return false, tostring(probeError) end
    if result.error then return false, result.error end
    if not result.candidate then return false, "reload duration probe returned no field" end

    runtime.durationProbeRestore = {candidate = result.candidate, value = 0.0}
    runtime.durationRestorePending = true
    local zeroOk, zeroError = pcall(
        maluaTankWriteDurationCandidate,
        result.candidate,
        0.0
    )
    local verify = zeroOk and maluaTankReadDurationCandidate(result.candidate) or nil
    if not zeroOk or not maluaTankDurationCandidateIsZero(result.candidate, verify) then
        local restoreErrors = {}
        self:RestorePendingDurationProbe(runtime, restoreErrors, "duration zero restore")
        if not runtime.durationRestorePending then runtime.durationProbeRestore = nil end
        return false, string.format(
            "reload duration zero write failed verify=%s error=%s%s",
            tostring(verify), tostring(zeroError),
            #restoreErrors > 0 and ("; " .. table.concat(restoreErrors, "; ")) or ""
        )
    end
    runtime.durationField = result.candidate
    runtime.durationProbeRestore = nil
    runtime.durationRestorePending = false
    maluaTankSilent(string.format(
        "[mALuaTankCooldown] verified vehicle reload duration %s+0x%X kind=%s scale=%.0f baseline=%.3fms",
        result.candidate.owner, result.candidate.offset,
        result.candidate.kind, result.candidate.scale or 1.0, result.baseline
    ))
    return true
end

function MALuaTankCannonCooldownPatch:DiscoverTimerField(runtime, remaining)
    runtime.timerProbeAttempts = (runtime.timerProbeAttempts or 0) + 1
    runtime.nextTimerProbe = (maluaTankGetGameTimer() or 0) + 250
    local gameTimer = maluaTankGetGameTimer()
    local candidates = maluaTankEnumerateTimerCandidates(runtime, remaining, gameTimer)
    if #candidates == 0 and not runtime.pointerGraphExpanded then
        self:ExpandRuntimeObjectGraph(runtime)
        candidates = maluaTankEnumerateTimerCandidates(runtime, remaining, gameTimer)
    end
    local correlatedCandidates = maluaTankCollectCorrelatedTimerCandidates(runtime, remaining)
    local exactDeadlines = maluaTankDeduplicateTimerCandidates(candidates, "deadline")
    local exactRemaining = maluaTankDeduplicateTimerCandidates(candidates, "remaining")
    local groups = {}
    if #exactDeadlines > 0 and #exactDeadlines <= 8 then
        groups[#groups + 1] = exactDeadlines
    end
    if #exactRemaining > 0 and #exactRemaining <= 8 then
        groups[#groups + 1] = exactRemaining
    end
    local correlationModes = {
        "correlated_remaining",
        "correlated_seconds_remaining",
        "correlated_milliseconds_remaining",
        "correlated_remaining_ratio",
        "correlated_progress_ratio",
    }
    for _, mode in ipairs(correlationModes) do
        groups[#groups + 1] = maluaTankDeduplicateTimerCandidates(
            correlatedCandidates,
            mode
        )
    end
    groups[#groups + 1] = maluaTankDeduplicateTimerCandidates(correlatedCandidates)
    local verifiedFields = nil
    for _, group in ipairs(groups) do
        if #group > 0 then
            verifiedFields = maluaTankMinimizeTimerCandidateGroup(runtime, group)
            if verifiedFields then break end
        end
    end
    if verifiedFields then
        runtime.timerFields = verifiedFields
        runtime.timerField = verifiedFields[1]
        local fieldText = {}
        for _, candidate in ipairs(verifiedFields) do
            fieldText[#fieldText + 1] = string.format(
                "%s+0x%X/%s/%s/hits=%d",
                candidate.owner, candidate.offset, candidate.kind,
                candidate.mode, candidate.hits or 0
            )
        end
        maluaTankSilent(string.format(
            "[mALuaTankCooldown] verified vehicle reload timer group fields=%d remaining=%d [%s]",
            #verifiedFields, remaining, table.concat(fieldText, ";")
        ))
        return true
    end
    local candidateText = {}
    for index, candidate in ipairs(candidates) do
        if index > 12 then break end
        candidateText[#candidateText + 1] = string.format(
            "%s+0x%X/%s=0x%X",
            candidate.owner,
            candidate.offset,
            candidate.mode,
            maluaTryRead(Memory.ReadUInt, candidate.address) or 0
        )
    end
    local correlationText = {}
    for index, candidate in ipairs(correlatedCandidates) do
        if index > 8 then break end
        local reader = candidate.kind == "float" and Memory.ReadFloat or Memory.ReadUInt
        correlationText[#correlationText + 1] = string.format(
            "%s+0x%X/%s/%s/hits=%d/value=%s",
            candidate.owner,
            candidate.offset,
            candidate.kind,
            candidate.mode,
            candidate.hits or 0,
            tostring(maluaTryRead(reader, candidate.address))
        )
    end
    return false, string.format(
        "reload timer field unresolved remaining=%d candidates=%d correlated=%d exact=[%s] correlation=[%s]",
        remaining, #candidates, #correlatedCandidates,
        table.concat(candidateText, ";"), table.concat(correlationText, ";")
    )
end

function MALuaTankCannonCooldownPatch:RuntimeOwnerStatus(runtime)
    if not runtime then return false, "runtime is absent" end
    local existsOk, exists = pcall(menu.nativeApis.ENTITY.DOES_ENTITY_EXIST, runtime.vehicle)
    if not existsOk then return nil, "vehicle identity is unreadable" end
    if not exists then return false, "vehicle no longer exists" end
    local modelOk, model = pcall(menu.nativeApis.ENTITY.GET_ENTITY_MODEL, runtime.vehicle)
    if not modelOk or type(model) ~= "number" then return nil, "vehicle model is unreadable" end
    if (model & 0xFFFFFFFF) ~= runtime.model then return false, "vehicle model changed" end
    local pointerOk, physical = pcall(GTA.HandleToPointer, runtime.vehicle)
    local addressOk, vehicleAddress = pcall(function() return physical and physical:GetAddress() or 0 end)
    if not pointerOk or not addressOk or not maluaPointerLooksValid(vehicleAddress) then
        return nil, "vehicle pointer is unreadable"
    end
    if vehicleAddress ~= runtime.vehicleAddress then return false, "vehicle pointer changed" end
    local manager = maluaTryRead(Memory.ReadLong, vehicleAddress + MALUA_TANK_WEAPON_MANAGER_OFFSET)
    if manager == nil then return nil, "weapon manager is unreadable" end
    if manager ~= runtime.manager then return false, "weapon manager changed" end

    for _, component in ipairs(runtime.components or {}) do
        local raw = maluaTryRead(Memory.ReadLong, manager + 0x68 + component.index * 8)
        local rawSeat = maluaTryRead(Memory.ReadUInt, manager + 0x98 + component.index * 4)
        if raw == nil or rawSeat == nil then return nil, "component slot is unreadable" end
        if rawSeat >= 0x80000000 then rawSeat = rawSeat - 0x100000000 end
        if raw ~= component.rawAddress or rawSeat ~= component.seatKey then
            return false, "component slot changed"
        end
        local first = maluaTryRead(Memory.ReadLong, component.address)
        if first == nil then return nil, "component vtable is unreadable" end
        if component.first and first ~= component.first then return false, "component vtable changed" end
        if maluaPointerLooksValid(component.state) then
            local state = maluaTryRead(Memory.ReadLong, component.address + 0x18)
            if state == nil then return nil, "component state is unreadable" end
            if state ~= component.state then return false, "component state changed" end
        end
        if component.weaponInfo then
            local info = maluaTankReadComponentWeaponInfo(component.address)
            if not info then return nil, "component weapon info is unreadable" end
            if info.child ~= component.weaponInfo.child
                or info.context ~= component.weaponInfo.context
                or info.info ~= component.weaponInfo.info
                or info.hash ~= component.weaponInfo.hash then
                return false, "component weapon identity changed"
            end
        end
    end
    return true
end

function MALuaTankCannonCooldownPatch:TimerValueMatches(candidate, left, right)
    if left == nil or right == nil then return false end
    if candidate.kind == "float" then return maluaNearFloat(left, right) end
    return left == right
end

function MALuaTankCannonCooldownPatch:TrackTimerWrite(runtime, candidate, value)
    local reader = candidate.kind == "float" and Memory.ReadFloat or Memory.ReadUInt
    local writer = candidate.kind == "float" and Memory.WriteFloat or Memory.WriteUInt
    local current = maluaTryRead(reader, candidate.address)
    if current == nil then return false end
    local writtenValue = candidate.kind == "float" and value or math.floor(value + 0.5)
    runtime.timerWrites = runtime.timerWrites or {}
    local tracked = runtime.timerWrites[candidate.address]
    if not tracked then
        tracked = {
            address = candidate.address,
            kind = candidate.kind,
            original = current,
            value = writtenValue,
        }
        runtime.timerWrites[candidate.address] = tracked
    else
        local currentOwned = self:TimerValueMatches(candidate, current, tracked.value)
        for _, pending in ipairs(tracked.pendingValues or {}) do
            if self:TimerValueMatches(candidate, current, pending) then
                currentOwned = true
                break
            end
        end
        if not currentOwned then
            tracked.original = current
            tracked.value = writtenValue
            tracked.pendingValues = nil
        elseif not self:TimerValueMatches(candidate, tracked.value, writtenValue) then
            tracked.pendingValues = tracked.pendingValues or {}
            local alreadyTracked = false
            for _, pending in ipairs(tracked.pendingValues) do
                if self:TimerValueMatches(candidate, pending, writtenValue) then
                    alreadyTracked = true
                    break
                end
            end
            if not alreadyTracked then tracked.pendingValues[#tracked.pendingValues + 1] = writtenValue end
        end
    end
    local writeOk = pcall(writer, candidate.address, writtenValue)
    local verify = writeOk and maluaTryRead(reader, candidate.address) or nil
    if not writeOk or not self:TimerValueMatches(candidate, verify, writtenValue) then return false end
    tracked.value = writtenValue
    tracked.pendingValues = nil
    return true
end

function MALuaTankCannonCooldownPatch:RestoreTrackedTimerWrites(runtime, restoreErrors, label)
    for address, tracked in pairs(runtime.timerWrites or {}) do
        local candidate = {address = address, kind = tracked.kind}
        local reader = tracked.kind == "float" and Memory.ReadFloat or Memory.ReadUInt
        local writer = tracked.kind == "float" and Memory.WriteFloat or Memory.WriteUInt
        local current = maluaTryRead(reader, address)
        if current == nil then
            restoreErrors[#restoreErrors + 1] = label .. " address unreadable"
        else
            local owned = self:TimerValueMatches(candidate, current, tracked.value)
            for _, pending in ipairs(tracked.pendingValues or {}) do
                if self:TimerValueMatches(candidate, current, pending) then owned = true break end
            end
            if owned then
                local writeOk, writeError = pcall(writer, address, tracked.original)
                local verify = writeOk and maluaTryRead(reader, address) or nil
                if writeOk and self:TimerValueMatches(candidate, verify, tracked.original) then
                    runtime.timerWrites[address] = nil
                else
                    restoreErrors[#restoreErrors + 1] = string.format(
                        "%s address=0x%X restore failed error=%s", label, address, tostring(writeError)
                    )
                end
            else
                runtime.timerWrites[address] = nil
            end
        end
    end
end

function MALuaTankCannonCooldownPatch:RestorePendingTimerProbes(runtime, restoreErrors, label)
    for address, tracked in pairs(runtime.timerProbeRestores or {}) do
        local candidate = {address = address, kind = tracked.kind}
        local reader = tracked.kind == "float" and Memory.ReadFloat or Memory.ReadUInt
        local writer = tracked.kind == "float" and Memory.WriteFloat or Memory.WriteUInt
        local current = maluaTryRead(reader, address)
        if current == nil then
            restoreErrors[#restoreErrors + 1] = label .. " address unreadable"
        elseif self:TimerValueMatches(candidate, current, tracked.original) then
            runtime.timerProbeRestores[address] = nil
        elseif self:TimerValueMatches(candidate, current, tracked.value) then
            local writeOk, writeError = pcall(writer, address, tracked.original)
            local verify = writeOk and maluaTryRead(reader, address) or nil
            if writeOk and self:TimerValueMatches(candidate, verify, tracked.original) then
                runtime.timerProbeRestores[address] = nil
            else
                restoreErrors[#restoreErrors + 1] = string.format(
                    "%s address=0x%X restore failed error=%s", label, address, tostring(writeError)
                )
            end
        else
            runtime.timerProbeRestores[address] = nil
        end
    end
    runtime.timerProbeRestorePending = next(runtime.timerProbeRestores or {}) ~= nil
end

function MALuaTankCannonCooldownPatch:RestorePendingDurationProbe(runtime, restoreErrors, label)
    local pending = runtime.durationProbeRestore
    if not pending then
        runtime.durationRestorePending = false
        return
    end
    local candidate = pending.candidate
    local current = maluaTankReadDurationCandidate(candidate)
    if current == nil then
        restoreErrors[#restoreErrors + 1] = label .. " address unreadable"
        runtime.durationRestorePending = true
        return
    end
    local matchesOriginal = candidate.kind == "uint"
        and current == candidate.original
        or candidate.kind ~= "uint"
        and maluaNearFloat(current, candidate.original)
    if matchesOriginal then
        runtime.durationProbeRestore = nil
        runtime.durationRestorePending = false
        return
    end
    local matchesPending = candidate.kind == "uint"
        and current == pending.value
        or candidate.kind ~= "uint"
        and maluaNearFloat(current, pending.value)
    if not matchesPending then
        runtime.durationProbeRestore = nil
        runtime.durationRestorePending = false
        restoreErrors[#restoreErrors + 1] = label .. " ownership lost"
        return
    end
    local writeOk, writeError = pcall(
        maluaTankWriteDurationCandidate,
        candidate,
        candidate.original
    )
    local verify = writeOk and maluaTankReadDurationCandidate(candidate) or nil
    local restored = candidate.kind == "uint"
        and verify == candidate.original
        or candidate.kind ~= "uint"
        and maluaNearFloat(verify, candidate.original)
    if restored then
        runtime.durationProbeRestore = nil
        runtime.durationRestorePending = false
    else
        runtime.durationRestorePending = true
        restoreErrors[#restoreErrors + 1] = string.format(
            "%s restore failed write=%s verify=%s error=%s",
            label, tostring(writeOk), tostring(verify), tostring(writeError)
        )
    end
end

function MALuaTankCannonCooldownPatch:RestoreRuntime()
    local runtime = self.runtime
    if not runtime then
        self.lastRuntimeError = nil
        return true
    end

    local ownerStatus, ownerReason = self:RuntimeOwnerStatus(runtime)
    if ownerStatus == false then
        self.runtime, self.lastRuntimeError = nil, nil
        maluaTankSilent("[mALuaTankCooldown] stale runtime ownership released: " .. tostring(ownerReason))
        return true
    elseif ownerStatus == nil then
        return false, ownerReason
    end

    local errors = {}
    self:RestorePendingTimerProbes(runtime, errors, "timer probe restore")
    self:RestorePendingDurationProbe(runtime, errors, "duration probe restore")
    local function restoreCandidate(candidate, expected)
        local reader = candidate.kind == "float" and Memory.ReadFloat or Memory.ReadUInt
        local writer = candidate.kind == "float" and Memory.WriteFloat or Memory.WriteUInt
        local current = maluaTryRead(reader, candidate.address)
        local matches = candidate.kind == "float" and maluaNearFloat or function(a, b) return a == b end
        if current == nil then return false, "unreadable" end
        if matches(current, candidate.original) then return true end
        if not matches(current, expected) then return true, "ownership-lost" end
        local writeOk, writeErr = pcall(writer, candidate.address, candidate.original)
        local verify = writeOk and maluaTryRead(reader, candidate.address) or nil
        if not writeOk or not matches(verify, candidate.original) then
            return false, tostring(writeErr or verify)
        end
        return true
    end

    self:RestoreTrackedTimerWrites(runtime, errors, "timer restore")
    if runtime.durationField then
        local restored, reason = restoreCandidate(runtime.durationField, 0)
        if not restored then errors[#errors + 1] = "duration restore: " .. tostring(reason) end
    end
    for _, interval in ipairs(runtime.runtimeIntervalFields or {}) do
        local restored, reason = restoreCandidate({
            kind = "float", address = interval.address, original = interval.original,
        }, 0.0)
        if not restored then errors[#errors + 1] = "interval restore: " .. tostring(reason) end
    end
    if #errors > 0 then return false, table.concat(errors, "; ") end
    self.runtime = nil
    self.lastRuntimeError = nil
    return true
end

function MALuaTankCannonCooldownPatch:RefreshRuntime()
    local vehicle, ped, model, modelName = maluaTankGetCurrentVehicle()
    if not vehicle then
        if self.runtime then
            local restored, restoreError = self:RestoreRuntime()
            if not restored then return false, restoreError end
        end
        return true
    end

    if not self.runtime or self.runtime.vehicle ~= vehicle then
        if self.runtime then
            local restored, restoreError = self:RestoreRuntime()
            if not restored then return false, restoreError end
        end
        local runtime, resolveError = self:ResolveRuntime(vehicle, ped, model, modelName)
        if not runtime then
            if self.lastRuntimeError ~= resolveError then
                maluaTankSilent("[mALuaTankCooldown] runtime resolve failed: " .. tostring(resolveError))
                self.lastRuntimeError = resolveError
            end
            return false, resolveError
        end
        self.runtime = runtime
        self.lastRuntimeError = nil
        maluaTankSilent(string.format(
            "[mALuaTankCooldown] vehicle instance %s handle=%d pedSeat=%d reloadSeat=%d manager=0x%X components=%d primary=%d/seat=%d/hash=%s/name=%s runtimeIntervals=%d entries=[%s]",
            runtime.modelName, runtime.vehicle, runtime.pedSeat, runtime.seat, runtime.manager,
            #runtime.components,
            runtime.primaryComponentIndex or -1,
            runtime.primaryComponentSeat or -99,
            runtime.primaryWeaponHash and string.format("0x%X", runtime.primaryWeaponHash) or "nil",
            tostring(runtime.primaryWeaponName or "unknown"),
            #(runtime.runtimeIntervalFields or {}),
            table.concat(runtime.componentEntries or runtime.rawEntries, ",")
        ))
        if #(runtime.runtimeIntervalFields or {}) > 0 then
            local intervalText = {}
            for _, interval in ipairs(runtime.runtimeIntervalFields) do
                intervalText[#intervalText + 1] = string.format(
                    "%s/info=0x%X/field=0x%X/+0x%X/original=%.6f/native=%.6f",
                    interval.name,
                    interval.info,
                    interval.address,
                    interval.offset,
                    interval.original,
                    interval.expected
                )
            end
            maluaTankSilent(
                "[mALuaTankCooldown] runtime weapon interval candidates ["
                    .. table.concat(intervalText, ";") .. "]"
            )
        end
        self:LogRuntimeLayout(runtime)
        local durationOk, durationError = self:DiscoverDurationField(runtime)
        if not durationOk then
            maluaTankSilent("[mALuaTankCooldown] " .. tostring(durationError))
            runtime.lastDurationError = tostring(durationError)
            runtime.lastDurationErrorLog = maluaTankGetGameTimer() or 0
        end
    end

    local runtime = self.runtime
    local ownerStatus, ownerReason = self:RuntimeOwnerStatus(runtime)
    if ownerStatus ~= true then
        return false, "runtime ownership check failed: " .. tostring(ownerReason)
    end
    if runtime.timerProbeRestorePending then
        local restoreErrors = {}
        self:RestorePendingTimerProbes(runtime, restoreErrors, "timer probe restore")
        if runtime.timerProbeRestorePending then
            return false, table.concat(restoreErrors, "; ")
        end
    end
    for _, interval in ipairs(runtime.runtimeIntervalFields or {}) do
        local current = maluaTryRead(Memory.ReadFloat, interval.address)
        if current == nil then return false, interval.name .. " interval is unreadable" end
        if not maluaNearFloat(current, 0.0) then
            if not maluaNearFloat(current, interval.expected)
                and not maluaNearFloat(current, interval.original) then
                return false, interval.name .. " interval changed externally"
            end
            local writeOk = pcall(Memory.WriteFloat, interval.address, 0.0)
            if not writeOk or not maluaNearFloat(maluaTryRead(Memory.ReadFloat, interval.address), 0.0) then
                return false, interval.name .. " interval write verification failed"
            end
        end
    end
    local addedStates = self:RefreshRuntimeObjects(runtime)
    if addedStates > 0 then
        maluaTankSilent(string.format(
            "[mALuaTankCooldown] attached %d late weapon-state object(s)", addedStates
        ))
    end
    if runtime.durationRestorePending then
        local restoreErrors = {}
        self:RestorePendingDurationProbe(runtime, restoreErrors, "duration probe restore")
        if runtime.durationRestorePending or #restoreErrors > 0 then
            return false, table.concat(restoreErrors, "; ")
        end
    end
    if not runtime.durationField then
        local now = maluaTankGetGameTimer() or 0
        if now >= (runtime.nextDurationProbe or 0) then
            local durationOk, durationError = self:DiscoverDurationField(runtime)
            if not durationOk then
                durationError = tostring(durationError)
                if durationError ~= runtime.lastDurationError
                    or now - (runtime.lastDurationErrorLog or 0) >= 5000 then
                    maluaTankSilent("[mALuaTankCooldown] " .. durationError)
                    runtime.lastDurationError = durationError
                    runtime.lastDurationErrorLog = now
                end
            end
            if runtime.durationRestorePending then
                return false, "duration probe restore is pending"
            end
        end
    end
    if runtime.durationField then
        local current = maluaTankReadDurationCandidate(runtime.durationField)
        if current == nil then return false, "reload duration field is unreadable" end
        if not maluaTankDurationCandidateIsZero(runtime.durationField, current) then
            local original = runtime.durationField.original
            local matchesOriginal = runtime.durationField.kind == "uint"
                and current == original or runtime.durationField.kind ~= "uint"
                and maluaNearFloat(current, original)
            if not matchesOriginal then
                return false, "reload duration field changed externally"
            end
            runtime.durationProbeRestore = {candidate = runtime.durationField, value = 0.0}
            runtime.durationRestorePending = true
            local writeOk, writeError = pcall(
                maluaTankWriteDurationCandidate,
                runtime.durationField,
                0.0
            )
            local verify = writeOk and maluaTankReadDurationCandidate(runtime.durationField) or nil
            if not writeOk or not maluaTankDurationCandidateIsZero(runtime.durationField, verify) then
                return false, "reload duration write verification failed: " .. tostring(writeError or verify)
            end
            runtime.durationProbeRestore = nil
            runtime.durationRestorePending = false
        end
    end

    local remaining = maluaTankReadRemaining(runtime.vehicle, runtime.seat)
    local reloading = maluaTankReadReloading(runtime.vehicle, runtime.seat)
    if runtime.timerFields and #runtime.timerFields > 0 then
        local gameTimer = maluaTankGetGameTimer() or 0
        for _, timerField in ipairs(runtime.timerFields) do
            local value = timerField.mode == "deadline" and gameTimer
                or timerField.mode == "correlated_progress_ratio" and 1.0
                or 0
            if not self:TrackTimerWrite(runtime, timerField, value) then
                return false, "reload timer write verification failed"
            end
        end
    else
        local now = maluaTankGetGameTimer() or 0
        local attempts = runtime.timerProbeAttempts or 0
        if remaining and remaining > 16 and attempts < 8 and now >= (runtime.nextTimerProbe or 0) then
            local timerOk, timerError = self:DiscoverTimerField(runtime, remaining)
            if not timerOk then maluaTankSilent("[mALuaTankCooldown] " .. tostring(timerError)) end
        end
    end

    local now = maluaTankGetGameTimer() or 0
    if remaining and (remaining > 16 or reloading) and now - self.lastRuntimeLog >= 500 then
        self.lastRuntimeLog = now
        maluaTankSilent(string.format(
            "[mALuaTankCooldown] reload state seat=%d remaining=%d reloading=%s duration=%s",
            runtime.seat, remaining, tostring(reloading),
            tostring(maluaTankReadReloadTime(runtime.vehicle, runtime.seat))
        ))
    end
    return true
end

function MALuaTankCannonCooldownPatch:Enable()
    if Utils1:edition() ~= "Enhanced" then
        maluaTankSilent("[mALuaTankCooldown] This feature supports Enhanced only")
        return false
    end
    if self.active then
        return self.restorePending ~= true and self.definitionRestorePending ~= true
    end
    local pairOk, pair, pairError = pcall(maluaResolveWeaponInfoPair, "tank")
    if not pairOk then
        pairError = pair
        pair = nil
    end
    if not pair then
        maluaTankSilent("[mALuaTankCooldown] weapon info unresolved: " .. tostring(pairError))
        return false
    end

    local fieldOk, offset, targets, values = pcall(maluaResolveTankCooldownField, pair)
    if not fieldOk then
        maluaTankSilent("[mALuaTankCooldown] field probe failed: " .. tostring(offset))
        return false
    end
    if not offset then
        maluaTankSilent("[mALuaTankCooldown] " .. tostring(targets))
        return false
    end

    local entries = {}
    for _, target in ipairs(targets) do
        local original = maluaTryRead(Memory.ReadFloat, target.weapon + offset)
        if type(original) ~= "number" or original ~= original
            or original <= 0.000001 or original >= 100.0 then
            maluaTankSilent("[mALuaTankCooldown] " .. target.name .. " original field is invalid")
            return false
        end
        entries[#entries + 1] = {
            name = target.name,
            hash = target.hash,
            address = target.weapon + offset,
            original = original,
        }
    end

    self.entries = entries
    self.offset = offset
    self.pair = pair
    self.active = true
    self.restorePending = true
    self.definitionRestorePending = false
    self.definitionProbeRestores = nil
    self.nextRestoreAt = 0.0
    local ok, err = pcall(function()
        for _, entry in ipairs(entries) do
            Memory.WriteFloat(entry.address, 0.0)
        end
        for _, entry in ipairs(entries) do
            local memoryValue = Memory.ReadFloat(entry.address)
            if not maluaNearFloat(memoryValue, 0.0) then
                error(entry.name .. " memory write verification failed")
            end
            local getterValue = menu.nativeApis.WEAPON.GET_WEAPON_TIME_BETWEEN_SHOTS(entry.hash)
            if type(getterValue) ~= "number" or getterValue ~= getterValue or getterValue > 0.001 then
                error(string.format("%s native verification returned %.6f", entry.name, tonumber(getterValue) or -1.0))
            end
        end
    end)
    if not ok then
        local restoreCallOk, restored = pcall(function() return self:Disable(true) end)
        if restoreCallOk and restored == true then
            maluaTankSilent("[mALuaTankCooldown] patch failed and was rolled back: " .. tostring(err))
        else
            maluaTankSilent("[mALuaTankCooldown] patch failed; verified restore is pending: " .. tostring(err))
        end
        return false
    end
    self.restorePending = false
    local originalText = {}
    for _, entry in ipairs(entries) do
        originalText[#originalText + 1] = string.format("%s=%.6f", entry.name, entry.original)
    end
    maluaTankSilent(string.format(
        "[mALuaTankCooldown] definition layer enabled offset=0x%X patched=%d [%s]",
        offset, #entries, table.concat(originalText, " ")
    ))
    return true
end

function MALuaTankCannonCooldownPatch:Refresh()
    if not self.active or not self.entries then return true end
    if self.restorePending then return false end
    local ok, err = pcall(function()
        if self.definitionRestorePending then
            local restoreErrors = {}
            self:RestorePendingDefinitionProbes(
                restoreErrors,
                "pending definition restore"
            )
            if self.definitionRestorePending or #restoreErrors > 0 then
                error(table.concat(restoreErrors, "; "))
            end
        end
        local runtimeOk, runtimeError = self:RefreshRuntime()
        if runtimeOk ~= true then error(tostring(runtimeError or "runtime refresh failed")) end
        for _, entry in ipairs(self.entries) do
            local current = maluaTryRead(Memory.ReadFloat, entry.address)
            if current == nil then error(entry.name .. " cooldown field is unreadable") end
            if maluaNearFloat(current, 0.0) then
                -- Already owned by this patch.
            elseif maluaNearFloat(current, entry.original) then
                Memory.WriteFloat(entry.address, 0.0)
                if not maluaNearFloat(maluaTryRead(Memory.ReadFloat, entry.address), 0.0) then
                    error(entry.name .. " cooldown refresh verification failed")
                end
            else
                error(string.format("%s cooldown changed externally (%.6f); patch stopped", entry.name, current))
            end
        end
    end)
    if not ok then
        maluaTankSilent("[mALuaTankCooldown] refresh stopped: " .. tostring(err))
        return false
    end
    return true
end

function MALuaTankCannonCooldownPatch:Disable(force)
    if not self.active then
        self.restorePending = false
        self.definitionRestorePending = false
        self.definitionProbeRestores = nil
        return true
    end
    local now = os.clock()
    if not force and now < (self.nextRestoreAt or 0.0) then return false end
    self.nextRestoreAt = now + 0.5
    self.restorePending = true
    local restoreOk = true
    local ownershipLost = false
    local runtimeCallOk, runtimeRestored, runtimeError = pcall(function() return self:RestoreRuntime() end)
    local runtimeOk = runtimeCallOk and runtimeRestored == true
    if not runtimeOk then
        restoreOk = false
        maluaTankSilent("[mALuaTankCooldown] runtime restore failed: "
            .. tostring(runtimeCallOk and runtimeError or runtimeRestored))
    end
    local ok, err = pcall(function()
        for _, entry in ipairs(self.entries or {}) do
            local current = maluaTryRead(Memory.ReadFloat, entry.address)
            if current == nil then
                restoreOk = false
            elseif maluaNearFloat(current, 0.0) then
                Memory.WriteFloat(entry.address, entry.original)
                if not maluaNearFloat(maluaTryRead(Memory.ReadFloat, entry.address), entry.original) then
                    restoreOk = false
                end
            elseif not maluaNearFloat(current, entry.original) then
                ownershipLost = true
                maluaTankSilent("[mALuaTankCooldown] " .. entry.name .. " changed externally; restore skipped")
            end
        end
    end)
    if not ok then
        maluaTankSilent("[mALuaTankCooldown] restore failed: " .. tostring(err))
        return false
    end
    if not restoreOk then
        maluaTankSilent("[mALuaTankCooldown] one or more fields were not restored; retrying")
        return false
    end
    self.active = false
    self.restorePending = false
    self.entries = nil
    self.offset = nil
    self.pair = nil
    self.componentGetter = nil
    self.lastRuntimeLog = 0
    self.nextRestoreAt = 0.0
    self.restorePending = false
    self.definitionRestorePending = false
    self.definitionProbeRestores = nil
    if ownershipLost then
        maluaTankSilent("[mALuaTankCooldown] external definition change detected; ownership released")
        return false
    end
    maluaTankSilent("[mALuaTankCooldown] original tank cannon cooldown restored")
    return true
end

local function maluaTankToast(message, isError)
    if Logger and Logger.Toast then
        Logger:Toast(
            "Tank cannon",
            tostring(message),
            isError and CONFIG.UI.ToastDuration.Long or CONFIG.UI.ToastDuration.Medium
        )
    end
end

Script.RegisterLooped(function()
    if MALuaTankCannonCooldownPatch.active then
        local callOk, result = pcall(function()
            if MALuaTankCannonCooldownPatch.desired then
                return MALuaTankCannonCooldownPatch:Refresh()
            end
            return MALuaTankCannonCooldownPatch:Disable()
        end)
        if MALuaTankCannonCooldownPatch.desired and (not callOk or result ~= true) then
            MALuaTankCannonCooldownPatch.desired = false
            pcall(function()
                if MALuaTankCannonCooldownPatch.feature then
                    MALuaTankCannonCooldownPatch.feature:SetToggledSilently(false)
                end
            end)
            pcall(function() MALuaTankCannonCooldownPatch:Disable() end)
        end
    end
end)

