EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    MALuaTankCannonCooldownPatch.desired = false
    MALuaMK2NPCLock.desired = false
    MALuaPlayerHomingLock.desired = false
    MALuaMK2DeadlockPatch.desired = false
    local function unloadRestore(label, callback)
        local lastError
        for _ = 1, 3 do
            local callOk, restored, restoreError = pcall(callback)
            if callOk and restored == true then return true end
            lastError = callOk and (restoreError or restored) or restored
        end
        maluaLogError("[mALua] unload " .. label .. " restore remains pending: " .. tostring(lastError))
        return false
    end
    unloadRestore("tank cooldown", function()
        return MALuaTankCannonCooldownPatch:Disable(true)
    end)
    unloadRestore("NPC lock bytes", function()
        return MALuaMK2PlayerLockPatch:Disable()
    end)
    unloadRestore("WeaponFlags", function()
        return MALuaMK2WeaponFlagsPatch:Disable()
    end)
    unloadRestore("player target state", function()
        return MALuaMK2PedTargetState:Restore()
    end)
    unloadRestore("guidance", function()
        return MALuaMK2DeadlockPatch:Disable()
    end)
end)

end
end)()

PlayerTrollOptions = {
    spawned = {},
    followerChoice = {},
}

function PlayerTrollOptions:IsValid(pid)
    return type(pid) == "number" and PlayerManager:IsValidPlayer(pid)
end

function PlayerTrollOptions:GetPed(pid)
    if not self:IsValid(pid) then return 0 end
    local ped = PlayerManager:GetPlayerPed(pid)
    if not ped or ped == 0 or not menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(ped) then
        return 0
    end
    return ped
end

function PlayerTrollOptions:GetPosition(pid)
    local ok, pos = PlayerManager:GetPlayerPosition(pid)
    if not ok then return nil end
    return pos
end

function PlayerTrollOptions:GetVehicle(pid)
    local ped = self:GetPed(pid)
    if ped == 0 or not menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        return 0
    end
    local vehicle = menu.nativeApis.PED.GET_VEHICLE_PED_IS_USING(ped)
    if not vehicle or vehicle == 0 or not menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(vehicle) then
        return 0
    end
    return vehicle
end

function PlayerTrollOptions:RequestControl(entity)
    if not entity or entity == 0 or not menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(entity) then
        return false
    end
    if menu.nativeApis.NETWORK and menu.nativeApis.NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY and menu.nativeApis.NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(entity) then
        return true
    end
    if GTA and GTA.GiveControl then
        pcall(GTA.GiveControl, menu.nativeApis.PLAYER.PLAYER_ID(), entity)
    end
    return not menu.nativeApis.NETWORK or not menu.nativeApis.NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY or menu.nativeApis.NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(entity)
end

function PlayerTrollOptions:StopFeature(feature)
    StopPlayerToggle(feature)
end

function PlayerTrollOptions:Track(pid, key, entity)
    if not entity or entity == 0 then return entity end
    self.spawned[pid] = self.spawned[pid] or {}
    self.spawned[pid][key] = self.spawned[pid][key] or {}
    table.insert(self.spawned[pid][key], entity)
    return entity
end

function PlayerTrollOptions:Clear(pid, key)
    if not key and self.ClearPtfx then self:ClearPtfx(pid) end
    local playerEntities = self.spawned[pid]
    if not playerEntities then return end
    local function clearList(list)
        for _, entity in ipairs(list or {}) do
            if entity and entity ~= 0 and menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(entity) then
                pcall(function() EntityManager:DeleteEntity(entity) end)
            end
        end
    end
    if key then
        clearList(playerEntities[key])
        playerEntities[key] = nil
    else
        for _, list in pairs(playerEntities) do
            clearList(list)
        end
        self.spawned[pid] = nil
    end
end

function PlayerTrollOptions:Notify(message)
    Logger:Toast("Player fun", message, CONFIG.UI.ToastDuration.Short)
end

function PlayerTrollOptions:SpawnDogEnclosure(pid, target, pos)
    local model=Utils.Joaat("prop_fnclink_03e")
    if not EntityManager:RequestModel(model) then return nil,"The cage is not ready yet" end
    local buffer=Memory.Alloc(56)
    if not buffer or buffer==0 then return nil,"The cage is currently unavailable" end
    local ok,layout,reason=pcall(function()
        for offset=0,52,4 do Memory.WriteFloat(buffer+offset,0.0) end
        menu.nativeApis.MISC.GET_MODEL_DIMENSIONS(model,buffer,buffer+24)
        local min={x=Memory.ReadFloat(buffer),y=Memory.ReadFloat(buffer+8),z=Memory.ReadFloat(buffer+16)}
        local max={x=Memory.ReadFloat(buffer+24),y=Memory.ReadFloat(buffer+32),z=Memory.ReadFloat(buffer+40)}
        for _,v in ipairs({min.x,min.y,min.z,max.x,max.y,max.z}) do
            if type(v)~="number" or v~=v or math.abs(v)>100 then return nil,"The cage is currently unavailable" end
        end
        local widthX,widthY=max.x-min.x,max.y-min.y
        local alongX=widthX>=widthY
        local width=math.max(widthX,widthY)
        if width<1 or max.z-min.z<1 then return nil,"The cage is not ready yet" end
        local ground=pos.z-1.0
        if menu.nativeApis.MISC.GET_GROUND_Z_FOR_3D_COORD(pos.x,pos.y,pos.z+1,buffer+48,false,false) then
            local value=Memory.ReadFloat(buffer+48)
            if type(value)=="number" and value==value and math.abs(value-pos.z)<4 then ground=value end
        else
            -- Feet are a better fallback on interiors/platforms than the ped root.
            local feet=menu.nativeApis.PED.GET_PED_BONE_COORDS(target,14201,0.0,0.0,0.0)
            if feet and type(feet.z)=="number" and math.abs(feet.z-pos.z)<2 then ground=feet.z end
        end
        return {width=width,alongX=alongX,ground=ground,baseZ=ground-min.z,
            centerX=(min.x+max.x)*0.5,centerY=(min.y+max.y)*0.5}
    end)
    Memory.Free(buffer)
    if not ok or not layout then return nil,ok and reason or tostring(layout) end
    local heading=menu.nativeApis.ENTITY.GET_ENTITY_HEADING(target)
    local radius=layout.width*0.5-0.025
    for side=0,3 do
        local angle=math.rad(heading+side*90)
        local cx,cy=pos.x-math.sin(angle)*radius,pos.y+math.cos(angle)*radius
        local yaw=heading+side*90+(layout.alongX and 0 or 90)
        local turn=math.rad(yaw)
        local x=cx-(layout.centerX*math.cos(turn)-layout.centerY*math.sin(turn))
        local y=cy-(layout.centerX*math.sin(turn)+layout.centerY*math.cos(turn))
        local wall=EntityManager:SpawnObject(model,{x=x,y=y,z=layout.baseZ})
        if not wall or wall==0 then self:Clear(pid,"dogs");return nil,"Could not create the cage" end
        self:Track(pid,"dogs",wall)
        menu.nativeApis.ENTITY.SET_ENTITY_ROTATION(wall,0.0,0.0,yaw,2,true)
        -- CREATE_OBJECT may add the model radius; use exact origin after creation.
        menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET(wall,x,y,layout.baseZ,false,false,false)
        menu.nativeApis.ENTITY.FREEZE_ENTITY_POSITION(wall,true)
        menu.nativeApis.ENTITY.SET_ENTITY_COLLISION(wall,true,true)
    end
    return layout
end


