function PlayerTrollOptions:RunHornRockets(f)
    local pid, weapon = f:GetPlayerIndex(), Utils.Joaat("weapon_rpg")
    local weapons = menu.nativeApis.WEAPON
    local ready = false
    for _ = 1, 120 do
        if not f:IsToggled() or not self:IsValid(pid) then return end
        weapons.REQUEST_WEAPON_ASSET(weapon, 31, 0)
        if weapons.HAS_WEAPON_ASSET_LOADED(weapon) then ready = true break end
        Script.Yield(25)
    end
    if not ready then self:Notify("Rocket assets did not load; try again later") self:StopFeature(f) return end
    local hornDown, lastVehicle = false, 0
    while f:IsToggled() and self:IsValid(pid) do
        local vehicle = self:GetVehicle(pid)
        if vehicle ~= lastVehicle then hornDown = false lastVehicle = vehicle end
        -- Remote horn audio is replicated; the local input native alone misses peers.
        local pressed = vehicle ~= 0 and menu.nativeApis.AUDIO.IS_HORN_ACTIVE(vehicle)
        if vehicle ~= 0 and pid == menu.nativeApis.PLAYER.PLAYER_ID() then
            pressed = pressed or menu.nativeApis.PLAYER.IS_PLAYER_PRESSING_HORN(pid)
        end
        if pressed and not hornDown then
            local front, buffer = 3.5, nil
            pcall(function()
                buffer = Memory.Alloc(48)
                if buffer and buffer ~= 0 then
                    for offset = 0, 44, 4 do Memory.WriteFloat(buffer + offset, 0.0) end
                    menu.nativeApis.MISC.GET_MODEL_DIMENSIONS(menu.nativeApis.ENTITY.GET_ENTITY_MODEL(vehicle), buffer, buffer + 24)
                    local length = Memory.ReadFloat(buffer + 32)
                    if type(length) == "number" and length == length and length > 0 and length < 30 then front = length + 1.0 end
                end
            end)
            if buffer and buffer ~= 0 then pcall(Memory.Free, buffer) end
            local owner = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(menu.nativeApis.PLAYER.PLAYER_ID())
            for _, side in ipairs({-0.8, 0.8}) do
                local start = menu.nativeApis.ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(vehicle, side, front, 0.5)
                local finish = menu.nativeApis.ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(vehicle, side, front + 100.0, 0.5)
                -- Keep the existing zero damage and ignore the launching vehicle.
                menu.nativeApis.MISC.SHOOT_SINGLE_BULLET_BETWEEN_COORDS_IGNORE_ENTITY(
                    start.x, start.y, start.z, finish.x, finish.y, finish.z,
                    0, true, weapon, owner, true, false, 250.0, vehicle, false)
            end
        end
        hornDown = pressed
        Script.Yield(50)
    end
end

function PlayerTrollOptions:RequestPtfx(asset, current)
    local streaming = menu.nativeApis.STREAMING
    if not streaming or not streaming.REQUEST_NAMED_PTFX_ASSET or not streaming.HAS_NAMED_PTFX_ASSET_LOADED then return false end
    for _ = 1, 120 do
        if self.effectsStopped or (current and not current()) then return false end
        streaming.REQUEST_NAMED_PTFX_ASSET(asset)
        if streaming.HAS_NAMED_PTFX_ASSET_LOADED(asset) then return true end
        Script.Yield(25)
    end
    return false
end

PlayerTrollOptions.ptfx = {}
PlayerTrollOptions.effectSerial = 0
PlayerTrollOptions.PTFX_CATALOG = {
    {asset = "core", name = "ent_amb_elec_crackle", scale = 1.5, looped = true},
    {asset = "weap_xs_vehicle_weapons", name = "muz_xs_turret_flamethrower_looping", scale = 1.5, looped = true},
    {asset = "scr_xs_celebration", name = "scr_xs_confetti_burst", scale = 1.5},
    {asset = "core", name = "exp_grd_grenade_smoke", scale = 1.0},
}

function PlayerTrollOptions:ClearPtfx(pid)
    local effect = self.ptfx[pid]
    self.ptfx[pid] = nil
    if effect and effect.handle and effect.handle ~= 0 then
        pcall(menu.nativeApis.GRAPHICS.STOP_PARTICLE_FX_LOOPED, effect.handle, false)
    end
end

function PlayerTrollOptions:CleanupPtfx()
    self.effectsStopped = true
    for pid in pairs(self.ptfx) do self:ClearPtfx(pid) end
end

function PlayerTrollOptions:PlayPlayerPtfx(f)
    if self.effectsStopped then return false end
    local pid, ped = f:GetPlayerIndex(), self:GetPed(f:GetPlayerIndex())
    if ped == 0 then return false end
    self:ClearPtfx(pid)
    self.effectSerial = self.effectSerial + 1
    local state = {serial = self.effectSerial}
    self.ptfx[pid] = state
    local function current()
        return not self.effectsStopped and self.ptfx[pid] == state and self:GetPed(pid) == ped
    end
    local effect = self.PTFX_CATALOG[(f:GetListIndex() or 0) + 1] or self.PTFX_CATALOG[1]
    local success, played = pcall(function()
        if not self:RequestPtfx(effect.asset, current) or not current() then return false end
        local graphics = menu.nativeApis.GRAPHICS
        local function start(networked)
            graphics.USE_PARTICLE_FX_ASSET(effect.asset)
            if effect.looped then
                local handle
                if networked then
                    handle = graphics.START_NETWORKED_PARTICLE_FX_LOOPED_ON_ENTITY(
                        effect.name, ped, 0.0, 0.0, 0.5, 0.0, 0.0, 0.0, effect.scale,
                        false, false, false, 1.0, 1.0, 1.0, 1.0)
                else
                    handle = graphics.START_PARTICLE_FX_LOOPED_ON_ENTITY(
                        effect.name, ped, 0.0, 0.0, 0.5, 0.0, 0.0, 0.0, effect.scale, false, false, false)
                end
                if type(handle) ~= "number" or handle == 0 then return false end
                state.handle = handle
                if graphics.DOES_PARTICLE_FX_LOOPED_EXIST and not graphics.DOES_PARTICLE_FX_LOOPED_EXIST(handle) then
                    pcall(graphics.STOP_PARTICLE_FX_LOOPED, handle, false)
                    state.handle = nil return false
                end
                return true
            end
            local native = networked and graphics.START_NETWORKED_PARTICLE_FX_NON_LOOPED_ON_ENTITY or graphics.START_PARTICLE_FX_NON_LOOPED_ON_ENTITY
            return native(effect.name, ped, 0.0, 0.0, 0.5, 0.0, 0.0, 0.0, effect.scale, false, false, false) == true
        end
        local function play()
            local ok, result = pcall(start, true)
            if ok and result then return true end
            local localOk, localResult = pcall(start, false)
            return localOk and localResult == true
        end
        if not play() then return false end
        if effect.looped then
            for _ = 1, 20 do
                if not current() then return true end
                Script.Yield(100)
            end
        else
            for _ = 1, 3 do
                Script.Yield(250)
                if not current() then return true end
                if not play() then return false end
            end
        end
        return true
    end)
    if self.ptfx[pid] == state then self:ClearPtfx(pid) end
    if (not success or not played) and self:IsValid(pid) and not self.effectsStopped then
        self:Notify("Particle effect could not play; try again later")
    end
    return success and played == true
end


