        {name="Casino", id=123},
        {name="Casino Penthouse", id=124},
    },
    choices = {
        {name="Remove from interior", kind="exit"},
        {name="Send to the casino interior", kind="interior"},
        {name="Send to pizza delivery", kind="activity", activity=340},
        {name="Send skydiving", kind="activity", activity=267},
        {name="Send into a UFO", kind="activity", activity=314},
        {name="Throw flashbang", kind="flash"},
        {name="Return to main menu", kind="main_menu"},
        {name="Send indoors", kind="remote_interior"},
    },
