        cb = function(f)
            local targetPid = f:GetPlayerIndex()
            local targetHandle = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(targetPid)
            local players = Players.Get()
            local localPid = GTA.GetLocalPlayerId()
            local explodedCount = 0
            for _, pid in ipairs(players) do
                if pid ~= localPid and pid ~= targetPid then
                    local ped = Players.GetCPed(pid)
                    if ped then
                        local handle = menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
                        if handle ~= 0 then
                            local pos = menu.nativeApis.ENTITY.GET_ENTITY_COORDS(handle, false)
                            if pos then
                                Natives.InvokeVoid(
                                    0x172AA1B624FA1013,
                                    targetHandle,
                                    pos.x, pos.y, pos.z + 1.0,
                                    44,
                                    5.0,
                                    true,
                                    false,
                                    0.0
                                )
                                explodedCount = explodedCount + 1
                            end
                        end
                    end
                end
                Script.Yield(10)
            end
        end
    },
    {
        scope = "player",
        hash = Utils.Joaat("force_kill"),
        name = "Repeated forced player elimination",
        group = CONFIG.GROUPS.EGAO,
        type = eFeatureType.Toggle,
        desc = "Repeat this action for the selected player until disabled or they leave the session.",
        cb = function(f) SovereignPlayerDamageEvents:ProcessFeature(f) end
    },
    {
        scope = "player",
        hash = Utils.Joaat("radio"),
        name = "Continuous radio interference",
        group = CONFIG.GROUPS.EGAO,
        type = eFeatureType.Button,
        desc = "",
        cb = function(f)
            local pid = f:GetPlayerIndex()
            if pid == menu.nativeApis.PLAYER.PLAYER_ID() then
                Logger:Toast("Radio interference", "Do not use this on yourself", CONFIG.UI.ToastDuration.Short)
                return
            end
            for i = 1, 5, 1 do
                menu.nativeApis.AUDIO.PLAY_SOUND_FROM_ENTITY(menu.nativeApis.AUDIO.GET_SOUND_ID(), "05", menu.nativeApis.PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid), "DLC_GR_CS2_Sounds", true, false)
                Script.Yield(100)
                menu.nativeApis.AUDIO.RELEASE_SOUND_ID(menu.nativeApis.AUDIO.GET_SOUND_ID())
            end
        end
    },
    {
        scope = "player",
        hash = Utils.Joaat("enter_their_interior"),
        name = "Enter their interior",
        group = CONFIG.GROUPS.EGAO,
        type = eFeatureType.Button,
        desc = "",
        cb = function(f)
            local pid = f:GetPlayerIndex()
            local ok, reason = Utils1.EnterTheirInterior(pid)
            if not ok then
                local message = reason == "not_found" and "The target player is not inside an interior"
                    or reason == "invalid_player" and "Select another online player."
                    or reason == "legacy_mapping_missing" and "This interior is currently unavailable for this game version."
                    or reason == "freemode_mapping_missing" and "This interior is temporarily unavailable. Please try again later."
                    or reason == "edition_unresolved" and "Wait for the game to finish loading, then try again."
                    or "Could not enter player interior"
                SovereignNotify("Enter interior", message, "warning")
            end
        end
    },

}

-- Three controls adapted from the user-supplied club script; no external UI registration.
SovereignClub = (function()
local TITLE = "Strip club"
local VERSION = "2.3.0-local-r56"
local DEFAULT_SPEED = 60
local MAX_SPEED = 120
local CLUB = Utils.Joaat("stripclub_mp")
local H = {
    PED = 0xD80958FC74E988A6,
    EXISTS = 0x7239B21A38F536BA,
    DEAD = 0x5F9532F3B5CC2551,
    THREADS = 0x2C83A9DA6BFFC4F9,
    PLAYING = 0x1F0B79228E461EC9,
    PHASE = 0x346D81500D088F42,
    SPEED = 0x28D1A16553C51776,
    CONTROL = 0xE8A25867FBA3B05E,
    PRESSED = 0x580417101DDB492F,
    DISABLED_PRESSED = 0x91AEF906BCA88877,
    PAUSE = 0xB0034A223497FFCB,
    WARNING = 0xE18B138FABC53103,
    CHAT = 0xB118AF58B5F332A1,
