    { kind = "enter", dict = "mini@strip_club@leaning@enter", name = "enter_female" },
    { kind = "base", dict = "mini@strip_club@leaning@base", name = "base" },
    { kind = "base", dict = "mini@strip_club@leaning@base", name = "base_female" },
}

local features = {}
local state = {
    unloaded = false, enabledBefore = false, manual = false,
    status = "Disabled", lastActivity = "Press E to lean at the stage",
    ped = 0, threads = 0, clip = nil, phase = 0.0,
    baseFrames = 0, highFrames = 0, releaseFrames = 0,
    pending = false, deadline = 0, retryAt = 0,
