-- BEGIN VERIFIED AFFINITY PATCH RUNTIME
-- Address resolution verified against the live Enhanced 1.0.1158.16 script.
-- ScanScript is deliberately not called: VM offsets are translated through
-- the currently loaded scrProgram code-page table before any byte is read.
local function CreateEnhancedClubMemory(memory, expectedHash)
    local adapter = {}
    local last = "The club is not ready yet"
    local moduleName = "GTA5_Enhanced.exe"
    local signature = "48 C7 84 C8 D8 00 00 00 00 00 00 00"
    local signatureBytes = {0x48,0xC7,0x84,0xC8,0xD8,0,0,0,0,0,0,0}
    -- Captured from the actual loaded program; verify hash AND size each use.
    local codeHash, codeSize, functionOffset = 2730381740, 578810, 0x88782
    local cachedBase, cachedTable
    local function pointer(value)
        return math.type(value) == "integer" and value >= 0x10000 and value < 0x800000000000
    end
    local function fail(message)
        last = message
        error(message, 0)
    end
    local function requireAPI()
        for _, name in ipairs({"GetBaseAddress", "Scan", "ReadLong", "ReadUInt", "ReadInt", "ReadUByte", "WriteUByte"}) do
            if type(memory) ~= "table" or type(memory[name]) ~= "function" then
                fail("The club feature is currently unavailable: " .. name)
            end
        end
    end
    local function resolveTable()
        local base = memory.GetBaseAddress(moduleName)
        if not pointer(base) then fail("This game version is not supported yet") end
        if cachedBase == base and cachedTable then return cachedTable end
        local found = memory.Scan(signature, moduleName)
        if not pointer(found) or found < base or found > base + 0x20000000 then
            fail("The club is not ready yet")
        end
        for index, byte in ipairs(signatureBytes) do
            if memory.ReadUByte(found + index - 1) ~= byte then
                fail("The club feature is currently unavailable")
            end
        end
        -- Current verified instruction: MOVZX EDX, byte ptr [RIP+disp32].
        if memory.ReadUByte(found + 0x13) ~= 0x0F
            or memory.ReadUByte(found + 0x14) ~= 0xB6
            or memory.ReadUByte(found + 0x15) ~= 0x15 then
            fail("The club feature is unavailable for this game version")
        end
        local operand = found + 0x16
        local tableAddress = operand + 4 + memory.ReadInt(operand) + 0xD8
        if not pointer(tableAddress) or tableAddress < base or tableAddress > base + 0x20000000 then
            fail("The club feature is currently unavailable")
        end
        cachedBase, cachedTable = base, tableAddress
        return tableAddress
    end
    local function resolveFunction()
        requireAPI()
        local tableAddress = resolveTable()
        local program
        for index = 0, 175 do
            local candidate = memory.ReadLong(tableAddress + index * 8)
            if candidate ~= 0 then
                if not pointer(candidate) then fail("The club feature is currently unavailable") end
                if memory.ReadUInt(candidate + 0x58) == (expectedHash & 0xFFFFFFFF) then
                    if program then fail("The club is not ready yet. Please re-enter and try again.") end
                    program = candidate
                end
            end
        end
        if not program then
            last = "Enter the club first"
            return nil
        end
        local actualHash = memory.ReadUInt(program + 0x18)
        local actualSize = memory.ReadUInt(program + 0x1C)
        if actualHash ~= codeHash or actualSize ~= codeSize then
            fail(string.format("Unsupported script: hash=%08X size=%d", actualHash, actualSize))
        end
        local pages = memory.ReadLong(program + 0x10)
        if not pointer(pages) then fail("The club feature is currently unavailable") end
        local page = memory.ReadLong(pages + (functionOffset // 0x4000) * 8)
        if not pointer(page) then fail("The club feature is currently unavailable") end
        local address = page + (functionOffset % 0x4000)
        last = string.format("Enhanced code_hash=%08X code_size=%d vm_offset=%X address=%X",
            actualHash, actualSize, functionOffset, address)
        return address
    end
    function adapter.ScanScript(hash, pattern)
        if hash ~= expectedHash then fail("The club feature is currently unavailable") end
        local tokens = {}
        for token in pattern:gmatch("%S+") do
            if token ~= "?" and token ~= "??" and not token:match("^%x%x$") then
                fail("The club feature is currently unavailable")
            end
            tokens[#tokens + 1] = token
        end
        if #tokens ~= 39 then fail("The club feature is currently unavailable") end
        local address = resolveFunction()
        if not address then return 0 end
        local bytes, matches = {}, true
        for index, token in ipairs(tokens) do
            local value = memory.ReadUByte(address + index - 1)
            if math.type(value) ~= "integer" or value < 0 or value > 255 then
                fail("The club feature is currently unavailable")
            end
            bytes[index] = string.format("%02X", value)
            if token ~= "?" and token ~= "??" and value ~= tonumber(token, 16) then matches = false end
        end
        last = last .. "\nactual_context=" .. table.concat(bytes, " ")
        return matches and address or 0
    end
    function adapter.ReadUByte(address) return memory.ReadUByte(address) end
    function adapter.WriteUByte(address, value) return memory.WriteUByte(address, value) end
    function adapter.Describe() return last end
    return adapter
end

-- Bounded, fail-closed bytecode patch factory. No game globals or local indices.
local function CreateAffinityPatch(memory, scriptHash, specs)
    local owner, borrowed, active, lastMessage = nil, nil, false, "Not applied"
    local candidates, initError = {}, nil
    local function integer(value)
        return type(value) == "number" and value == math.floor(value)
    end
    local function byte(value)
        return integer(value) and value >= 0 and value <= 255
    end
    local function fail(message) error(message, 0) end
    local function makePattern(bytes, offset, length)
        local result = {}
        for index, value in ipairs(bytes) do
            if value == false or (index > offset and index <= offset + length) then
                result[index] = "??"
            else
                result[index] = string.format("%02X", value)
            end
        end
        return table.concat(result, " ")
    end
    local function cloneBytes(values)
        if type(values) ~= "table" or #values < 1 or #values > 64 then
            fail("Invalid patch length")
        end
        local copy = {}
        for index = 1, #values do
            if not byte(values[index]) then fail("Invalid patch bytes") end
            copy[index] = values[index]
        end
        return copy
    end
    local initialized, initializationMessage = pcall(function()
        if type(memory) ~= "table" or type(memory.ScanScript) ~= "function"
            or type(memory.ReadUByte) ~= "function" or type(memory.WriteUByte) ~= "function" then
            fail("Required script access is unavailable")
        end
        if type(specs) ~= "table" or #specs < 1 or #specs > 16 then
            fail("Invalid patch pattern count")
        end
        for _, source in ipairs(specs) do
            if type(source) ~= "table" or type(source.pattern) ~= "string" then
                fail("Invalid patch pattern")
            end
            local pattern = {}
            for token in source.pattern:gmatch("%S+") do
                if token == "?" or token == "??" then
                    pattern[#pattern + 1] = false
                elseif token:match("^%x%x$") then
                    pattern[#pattern + 1] = tonumber(token, 16)
                else
                    fail("Invalid patch pattern format")
                end
            end
            local original, replacement = cloneBytes(source.original), cloneBytes(source.replacement)
            local offset = source.offset
            if #pattern > 256 or not integer(offset) or offset < 0
                or #original ~= #replacement or offset + #original > #pattern then
                fail("Invalid patch range")
            end
            local surrounding = 0
            for index, value in ipairs(pattern) do
                if index <= offset or index > offset + #original then
                    if value ~= false then surrounding = surrounding + 1 end
                elseif value ~= false and value ~= original[index - offset] then
                    fail("Original bytes do not match the patch pattern")
                end
            end
            if surrounding == 0 then fail("The patch has no fixed context") end
            local patchedPattern = {}
            for index, value in ipairs(pattern) do patchedPattern[index] = value end
            for index, value in ipairs(replacement) do patchedPattern[offset + index] = value end
            candidates[#candidates + 1] = {
                name = tostring(source.name or "Tipping affinity"), pattern = pattern,
                offset = offset, original = original, replacement = replacement,
                scanPattern = makePattern(pattern, offset, #original),
                patchedPattern = makePattern(patchedPattern, 0, 0),
            }
        end
    end)
    if not initialized then initError = tostring(initializationMessage) end

    local function scan(pattern)
        local address = memory.ScanScript(scriptHash, pattern)
        if address == nil or address == 0 then return nil end
        if not integer(address) or address <= 0 or address > math.maxinteger - 256 then
            fail("The script scan returned an invalid address")
        end
        return address
    end
    local function read(address, length)
        local bytes = {}
        for index = 1, length do
            local value = memory.ReadUByte(address + index - 1)
            if not byte(value) then fail("Could not read script bytes") end
            bytes[index] = value
        end
        return bytes
    end
    local function write(address, value)
        -- The documented API returns nil; an explicit false also means failure.
        if memory.WriteUByte(address, value) == false then fail("Could not write script bytes") end
    end
    local function inspectOwned()
        local record = owner or borrowed
        -- Resolve the currently loaded script before using any cached address.
        local address = scan(record.restorePattern)
        if not address then fail("Script unloaded or patch context changed; restoration record retained") end
        if address ~= record.base then fail("Script address changed; restoration record retained") end
        local current = read(address, #record.snapshot)
        for index, expected in ipairs(record.snapshot) do
            local slot = index - record.spec.offset
            if slot >= 1 and slot <= #record.spec.original then
                if current[index] ~= record.spec.original[slot]
                    and current[index] ~= record.spec.replacement[slot] then
                    fail("Patch range changed; restoration record retained")
                end
            elseif current[index] ~= expected then
                fail("Patch context changed; restoration record retained")
            end
        end
        return current
    end
    local function restore()
        if borrowed then
            -- This instance performed no write. Releasing the observation must
            -- not undo an earlier instance or another tool's exact same patch.
            borrowed = nil
            active = false
            return "Action ended; the existing affinity setting was preserved"
        end
        if not owner then active = false; return "No restoration needed" end
        active = false
        local current = inspectOwned()
        for index, value in ipairs(owner.spec.original) do
            local position = owner.spec.offset + index
            if current[position] ~= value then
                write(owner.base + position - 1, value)
            end
        end
        current = inspectOwned()
        for index, value in ipairs(owner.spec.original) do
            if current[owner.spec.offset + index] ~= value then fail("Restoration verification failed; restoration record retained") end
        end
        local name = owner.spec.name
        owner = nil
        return name .. ": original setting restored"
    end
    local object = {}
    function object:Apply()
        if initError then lastMessage = initError; return false, lastMessage end
        local ok, message = pcall(function()
            if owner or borrowed then
                local record = owner or borrowed
                local current = inspectOwned()
                for index, value in ipairs(record.spec.replacement) do
                    if current[record.spec.offset + index] ~= value then
                        fail("The previous setting is still being restored")
                    end
                end
                active = true
                return borrowed and "Using the existing affinity setting" or (owner.spec.name .. ": setting applied")
            end
            local selected, address, snapshot, existing
            for _, spec in ipairs(candidates) do
                local seen = {}
                -- Scan results are candidates, not proof of their contents.
                -- Some scanners cache an address across different patterns.
                for _, pattern in ipairs({ spec.patchedPattern, spec.scanPattern }) do
                    local found = scan(pattern)
                    if found and not seen[found] then
                        seen[found] = true
                        local resolved = read(found, #spec.pattern)
                        for index, expected in ipairs(spec.pattern) do
                            local outside = index <= spec.offset or index > spec.offset + #spec.original
                            if outside and expected ~= false and resolved[index] ~= expected then
                                fail("The script changed; no changes were made")
                            end
                        end
                        local isOriginal, isReplacement = true, true
                        for index, expected in ipairs(spec.original) do
                            local value = resolved[spec.offset + index]
                            isOriginal = isOriginal and value == expected
                            isReplacement = isReplacement and value == spec.replacement[index]
                        end
                        if not isOriginal and not isReplacement then
                            fail("The affinity setting changed; no changes were made")
                        end
                        if selected then fail("The game state is unclear; no changes were made") end
                        selected, address, snapshot, existing = spec, found, resolved, isReplacement
                    end
                end
            end
            if not selected then fail("Enter the club and try again") end
            local restorePattern = makePattern(snapshot, selected.offset, #selected.original)
            if scan(restorePattern) ~= address then fail("The club state changed. Please try again.") end
            local beforeWrite = read(address, #snapshot)
            for index, expected in ipairs(snapshot) do
                if beforeWrite[index] ~= expected then fail("The club state changed. Please try again.") end
            end
            if existing then
                borrowed = { spec = selected, base = address, snapshot = snapshot,
                    restorePattern = restorePattern }
                active = true
                return "Using the existing affinity setting without changing it"
            end
            -- Establish ownership before the first write: a failing API may mutate.
            owner = { spec = selected, base = address, snapshot = snapshot,
                restorePattern = restorePattern }
            local installed, installMessage = pcall(function()
                for index, value in ipairs(selected.replacement) do
                    write(address + selected.offset + index - 1, value)
                end
                local current = inspectOwned()
                for index, value in ipairs(selected.replacement) do
                    if current[selected.offset + index] ~= value then fail("The setting could not be applied") end
                end
            end)
            if not installed then
                local recovered, recoveryMessage = pcall(restore)
                local result = tostring(installMessage) .. "；" .. tostring(recoveryMessage)
                if not recovered then result = result .. " (restoration pending)" end
                fail(result)
            end
            active = true
            return selected.name .. ": setting applied"
        end)
        if not ok then active = false end
        lastMessage = tostring(message)
        return ok, lastMessage
    end
    function object:Restore()
        if initError then lastMessage = initError; return false, lastMessage end
        local ok, message = pcall(restore)
        lastMessage = tostring(message)
        return ok, lastMessage
    end
    function object:IsActive() return active end
    function object:NeedsRestore() return owner ~= nil end
    function object:UsesExisting() return borrowed ~= nil end
    function object:Describe() return lastMessage end
    return object
end

local clubCodeMemory = CreateEnhancedClubMemory(Memory, CLUB)
local affinityPatch = CreateAffinityPatch(clubCodeMemory, CLUB, {
    {
        name = "Maximum tipping affinity",
        pattern = "2D 03 05 00 00 38 01 71 72 71 72 5D ?? ?? ?? 38 02 25 0A 38 00 03 71 72 71 5D ?? ?? ?? 50 ?? ?? 38 00 01 51 ?? ?? 5D",
        offset = 17,
        original = { 0x25, 0x0A, 0x38, 0x00, 0x03 },
        replacement = { 0x43, 0x4C, 0x1D, 0x00, 0x00 },
    },
})
-- END VERIFIED AFFINITY PATCH RUNTIME


local function toast(text) SovereignNotify("Strip club", tostring(text), "info") end
features.enabled = {value=false}
function features.enabled:IsToggled() return self.value == true end
function features.enabled:SetBoolValue(value) self.value = value == true end
features.speed = {value=DEFAULT_SPEED}
function features.speed:GetIntValue() return self.value end
features.limit = {value=750}
function features.limit:GetIntValue() return self.value end
local function intValue(key, low, high)
    return math.max(low, math.min(high, features[key]:GetIntValue()))
end

local function restoreSpeed()
    local target = state.speedTarget
    state.speedTarget = nil
    if target and Natives.InvokeBool(H.EXISTS, target.ped)
        and Natives.InvokeBool(H.PLAYING, target.ped, target.dict, target.name, 3) then
        Natives.InvokeVoid(H.SPEED, target.ped, target.dict, target.name, 1.0)
    end
end

local function releaseInput()
    if state.highFrames > 0 or state.releaseFrames > 0 then
        Natives.InvokeBool(H.CONTROL, 2, 223, 0.0)
    end
    state.highFrames = 0
    state.releaseFrames = 0
end

local function suspend()
    releaseInput()
    restoreSpeed()
    if affinityPatch:IsActive() or affinityPatch:NeedsRestore() or affinityPatch:UsesExisting() then
        local usingExisting = affinityPatch:UsesExisting()
        local restored, message = affinityPatch:Restore()
        if not restored then
            state.fullStatus = "Could not restore the previous affinity setting: " .. tostring(message)
            error(state.fullStatus)
        end
        state.fullStatus = usingExisting and "Action stopped." or "Action stopped."
        state.fullRequest = false
    end
    state.pending = false
    state.baseFrames = 0
end

local function stop(message)
    features.enabled:SetBoolValue(false)
    state.enabledBefore = false
    state.manual = false
    suspend()
    state.fullRequest = false
    state.status = message
    state.lastActivity = message
end

local function detectClip(ped)
    for _, clip in ipairs(CLIPS) do
        if Natives.InvokeBool(H.PLAYING, ped, clip.dict, clip.name, 3) then
            return clip
        end
    end
end

local function beginRound()
    suspend()
    if state.fullRequest then
        state.fullStatus = "Switched to fast tipping"
        state.fullRequest = false
    end
    state.attempts, state.observed, state.missed = 0, 0, 0
    state.retryAt = 0
    state.lastError = ""
    state.lastActivity = "Press E to lean at the stage"
end

local function tick()
    if state.unloaded then return end
    local now = Time.GetEpocheMs()
    local enabled = features.enabled:IsToggled()
    if enabled and not state.enabledBefore then beginRound() end
    if not enabled and state.enabledBefore then
        suspend()
        state.manual = false
        state.lastActivity = "Disabled manually"
    end
    state.enabledBefore = enabled

    local ped = Natives.InvokeInt(H.PED)
    if ped ~= state.ped then
        suspend()
        state.manual = false
        state.fullRequest = false
    end
    state.ped = ped
    state.threads = Natives.InvokeInt(H.THREADS, CLUB)
    state.clip = nil
    state.phase = 0.0
    if ped ~= 0 and Natives.InvokeBool(H.EXISTS, ped)
        and not Natives.InvokeBool(H.DEAD, ped, false) then
        state.clip = detectClip(ped)
        if state.clip then
            state.phase = Natives.InvokeFloat(H.PHASE, ped, state.clip.dict, state.clip.name)
        end
    end
    local kind = state.clip and state.clip.kind or "none"

    if not enabled and not state.manual and not state.pending and not state.speedTarget then
        suspend()
        state.status = "Disabled"
        return
    end
    if state.threads < 1 then
        suspend()
        state.manual = false
        state.fullRequest = false
        state.status = "Wait for the club to finish loading."
        state.lastActivity = state.status
        return
    end
    if Natives.InvokeBool(H.PAUSE) or Natives.InvokeBool(H.WARNING)
        or Natives.InvokeBool(H.CHAT) then
        suspend()
        state.status = "Paused while the game menu or chat is open"
        return
    end
    if (GUI and GUI.IsOpen and GUI.IsOpen()) or (menu.isOpen and menu.isOpen()) then
        suspend()
        state.status = "Close the menu to continue"
        return
    end

    -- Prioritize the player's exit action so automatic money throwing in the same frame does not block the exit key.
    if Natives.InvokeBool(H.PRESSED, 2, 225)
        or Natives.InvokeBool(H.DISABLED_PRESSED, 2, 225) or kind == "exit" then
        stop("You stopped leaning. Enable this again to start another round.")
        return
    end
    if kind == "none" or kind == "enter" then
        suspend()
        if state.manual then
            state.manual = false
            state.fullRequest = false
            state.fullStatus = "Press E and finish leaning before trying again"
            toast("Press E and finish leaning before tipping once.")
        end
        state.status = kind == "enter" and "Waiting for the leaning animation to finish" or "Press E to lean at the stage"
        state.lastActivity = state.status
        return
    end

    if state.highFrames > 0 then
        Natives.InvokeBool(H.CONTROL, 2, 223, 0.0)
        state.highFrames = 0
        state.releaseFrames = 2
    elseif state.releaseFrames > 0 then
        Natives.InvokeBool(H.CONTROL, 2, 223, 0.0)
        state.releaseFrames = state.releaseFrames - 1
    end

    if kind == "toss" then
        state.baseFrames = 0
        if state.pending then
            state.observed = state.observed + 1
            state.pending = false
            state.missed = 0
            if state.fullRequest then
                local usingExisting = affinityPatch:UsesExisting()
                local restored, message = affinityPatch:Restore()
                state.fullRequest = false
                if not restored then
                    state.fullStatus = "The tip was accepted, but the previous affinity setting could not be restored: " .. tostring(message)
                    error(state.fullStatus)
                end
                state.fullStatus = usingExisting
                    and "Tipped once. Check the game's affinity bar for the result."
                    or "Tipped once. Check the game's affinity bar for the result."
                toast(state.fullStatus)
            end
        end
        local clip = state.clip
        state.speedTarget = { ped = ped, dict = clip.dict, name = clip.name }
        Natives.InvokeVoid(H.SPEED, ped, clip.dict, clip.name, intValue("speed", 1, MAX_SPEED) + 0.0)
        state.status = "Speeding up the tipping animation"
        state.lastActivity = state.status
        return
    end

    restoreSpeed()
    if kind == "many" then
        state.baseFrames = 0
        state.status = "Waiting for the current tips to finish"
        state.lastActivity = state.status
        return
    end

    state.baseFrames = state.baseFrames + 1
    if state.pending then
        state.status = "Leaning is ready. Waiting for tipping to begin."
        if now >= state.deadline then
            state.pending = false
            state.missed = state.missed + 1
            state.retryAt = now + 200
            if not enabled then
                if state.fullRequest then state.fullStatus = "Tipping did not start. Ending this action." end
                stop("The tip was not accepted. Check your cash and the dancer, then try tipping manually.")
                toast(state.status)
                return
            end
            if state.missed >= 3 then
                stop("Leaning is ready, but tipping did not start. Check your cash and the dancer, then try tipping manually.")
                toast(state.status)
                return
            end
        end
        state.lastActivity = state.status
        return
    end
    if not enabled and not state.manual then return end
    if enabled and state.attempts >= intValue("limit", 1, 2000) then
        stop("This round has finished. Check the game's affinity bar for the result.")
        toast(state.status)
        return
    end
    state.status = "Leaning is ready. Preparing to tip."
    state.lastActivity = state.status
    if state.baseFrames < 3 or state.phase <= 0.02 or now < state.retryAt
        or state.releaseFrames > 0 then return end

    if state.fullRequest then
        local applied, message = affinityPatch:Apply()
        if not applied then
            state.fullStatus = "Action not completed: " .. tostring(message)
            stop("Affinity action incomplete. Re-enter the club and try again.")
            toast(state.fullStatus)
            return
        end
        state.fullStatus = affinityPatch:UsesExisting()
            and "Ready. Waiting to tip."
            or "Ready. Waiting to tip."
    end

    local accepted = Natives.InvokeBool(H.CONTROL, 2, 223, 1.0)
    if not accepted then
        stop("Tipping did not start. Try tipping manually first.")
        toast(state.status)
        return
    end
    state.highFrames = 1
    state.pending = true
    state.manual = false
    state.attempts = state.attempts + 1
    state.deadline = now + 1500
    state.baseFrames = 0
    state.status = "Waiting for the tipping animation"
    state.lastActivity = state.status
end


local api = {}
function api:SetEnabled(value)
    if value then beginRound() else stop("Disabled") end
    features.enabled:SetBoolValue(value)
    state.enabledBefore = value == true
end
function api:SetSpeed(value)
    features.speed.value = math.max(1, math.min(MAX_SPEED, math.floor(tonumber(value) or DEFAULT_SPEED)))
end
function api:FullOnce()
    -- Legacy uses the same observed native-input path as manual tipping. The
    -- Enhanced bytecode adapter is never invoked against the Legacy module.
    if Utils1:edition() == "Legacy" then
        self:SetEnabled(true)
        state.fullStatus = "Tipping repeatedly to increase affinity"
        toast("Affinity tipping started. Close the menu and lean at the stage. Press the exit key or disable Fast tipping to stop.")
        return
    end
    stop("Maximum affinity queued")
    state.ped = Natives.InvokeInt(H.PED)
    state.manual, state.fullRequest = true, true
    state.fullStatus = "Queued. Close the menu and lean at the stage."
    toast("Close the menu and lean at the stage to tip once for maximum affinity.")
end
function api:Process()
    if state.unloaded then return end
    if not features.enabled:IsToggled() and not state.manual and not state.pending
        and not state.speedTarget and not affinityPatch:NeedsRestore() then return end
    local ok, err = pcall(tick)
    if not ok then
        state.lastError = tostring(err)
        pcall(stop, "The action stopped after an error")
        toast(state.lastError)
    end
    if self.toggle then self.toggle.value = features.enabled:IsToggled() end
end
function api:Cleanup()
    state.unloaded = true
    local ok, err = pcall(suspend)
    if not ok then toast("Could not restore the previous setting: " .. tostring(err)) end
    return ok
end
function api:Bind(group)
    self.toggle = menu.toggle("Fast tipping", "Press E to lean at the stage, then close the menu to tip automatically. Stop leaning to stop.", group, 0,
        function(value) self:SetEnabled(value) end)
    menu.slider("Tipping speed multiplier", "Adjust the tipping animation speed. Default: 60x.", group, 1, MAX_SPEED, DEFAULT_SPEED, "%.0f", 0,
        function(value) self:SetSpeed(value) end)
    local affinityDescription = Utils1:edition() == "Legacy"
        and "Tip repeatedly to increase affinity at the selected speed. Press the exit key or disable Fast tipping to stop."
        or "Lean at the stage, then tip once to increase affinity."
    menu.button("Maximum affinity", affinityDescription, group, 0,
        function() self:FullOnce() end)
end
return api
end)()

