local function SovereignTaskToast(title, message, status)
    if menu and type(menu.notify) == "function" then
        local body = tostring(message or "")
        local resolved = menu.normalizeNotificationStatus(status)
            or menu.inferNotificationStatus(body)
        menu.notify(title or "Missions", body, 3.0, resolved)
    elseif Logger and Logger.Toast then
        Logger:Toast(title or "Missions", tostring(message or ""), CONFIG.UI.ToastDuration.Medium)
    end
end

local function SovereignTaskTeleport(x, y, z)
    local pos = {x = tonumber(x) or 0.0, y = tonumber(y) or 0.0, z = tonumber(z) or 0.0}
    if EntityManager and type(EntityManager.TeleportSelf) == "function" then
        return SovereignTaskCall("SovereignTask.Teleport", EntityManager.TeleportSelf, EntityManager, pos)
    end
    local ped = menu.nativeApis.PLAYER and menu.nativeApis.PLAYER.PLAYER_PED_ID and menu.nativeApis.PLAYER.PLAYER_PED_ID()
    if ped and menu.nativeApis.ENTITY and menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET then
        return SovereignTaskCall("SovereignTask.Teleport", menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET, ped, pos.x, pos.y, pos.z, false, false, false)
    end
    return false
end

SovereignTaskTeleportToObjective = function(fallback, title)
    if menu.nativeApis.HUD and type(menu.nativeApis.HUD.GET_FIRST_BLIP_INFO_ID) == "function" and type(menu.nativeApis.HUD.GET_BLIP_COORDS) == "function" then
        local function teleportBlip(blip)
            local exists = type(blip) == "number" and blip ~= 0
            if exists and type(menu.nativeApis.HUD.DOES_BLIP_EXIST) == "function" then
                local okExists, result = pcall(menu.nativeApis.HUD.DOES_BLIP_EXIST, blip)
                exists = okExists and result == true
            end
            if not exists then
                return false
            end

            local getter = type(menu.nativeApis.HUD.GET_BLIP_INFO_ID_COORD) == "function" and menu.nativeApis.HUD.GET_BLIP_INFO_ID_COORD or menu.nativeApis.HUD.GET_BLIP_COORDS
            local okCoords, coords = pcall(getter, blip)
            if not okCoords or coords == nil then
                return false
            end

            local okValues, x, y, z = pcall(function()
                return tonumber(coords.x), tonumber(coords.y), tonumber(coords.z)
            end)
            if not okValues or not x or not y or not z or (x == 0.0 and y == 0.0 and z == 0.0) then
                return false
            end
            return SovereignTaskTeleport(x, y, z + 1.0)
        end

        for _, sprite in ipairs({1, 66, 225, 85, 205, 270, 271, 280, 304, 432}) do
            local okBlip, blip = pcall(menu.nativeApis.HUD.GET_FIRST_BLIP_INFO_ID, sprite)
            if okBlip then
                local checked = 0
                while type(blip) == "number" and blip ~= 0 and checked < 32 do
                    if teleportBlip(blip) then
                        return true
                    end
                    checked = checked + 1
                    if type(menu.nativeApis.HUD.GET_NEXT_BLIP_INFO_ID) ~= "function" then
                        break
                    end
                    local okNext, nextBlip = pcall(menu.nativeApis.HUD.GET_NEXT_BLIP_INFO_ID, sprite)
                    if not okNext or nextBlip == blip then
                        break
                    end
                    blip = nextBlip
                end
            end
        end
    end

    if type(fallback) == "table" then
        SovereignTaskToast(title or "Mission teleport", "No target marker in this stage; using the mission's fallback location.")
        return SovereignTaskTeleport(fallback.x, fallback.y, fallback.z)
    end

    SovereignTaskToast(title or "Mission teleport", "No available mission target marker found in this stage.", "warning")
    return false
end

local function SovereignTaskNoticeOnce(key, title, message)
    key = tostring(key or "unknown")
    if SovereignTaskState.notices[key] then
        return
    end
    SovereignTaskState.notices[key] = true
    SovereignTaskToast(title or "Mission information", message or "")
end

SovereignTaskCall = function(scope, callback, ...)
    if type(callback) ~= "function" then
        return false
    end
    local ok, result = pcall(callback, ...)
    if not ok then
        if Logger and Logger.Error then
            Logger:Error(scope or "SovereignTask", tostring(result))
        end
        return false
    end
    return result ~= false
end

local function SovereignTaskCharSlot()
    if not menu.nativeApis.STATS or not menu.nativeApis.STATS.STAT_GET_INT or not Memory or not Memory.AllocInt then
        return 0
    end
    local ptr = nil
    local ok, value = pcall(function()
        ptr = Memory.AllocInt()
        local readOk = menu.nativeApis.STATS.STAT_GET_INT(Utils.Joaat("MPPLY_LAST_MP_CHAR"), ptr, -1)
        if not readOk then
            return 0
        end
        return tonumber(Memory.ReadInt(ptr)) or 0
    end)
    if ptr and Memory.Free then
        pcall(Memory.Free, ptr)
    end
    if not ok then
        return 0
    end
    return value == 1 and 1 or 0
end

local function SovereignTaskStatHash(stat)
    local name = tostring(stat or "")
    if name:sub(1, 5) == "MPPLY" or name:sub(1, 2) == "MP" then
        return Utils.Joaat(name)
    end
    return Utils.Joaat("MP" .. tostring(SovereignTaskCharSlot()) .. "_" .. name)
end

