    return SovereignTaskCall("SovereignTask.Stat", menu.nativeApis.STATS.STAT_SET_INT, SovereignTaskStatHash(stat), tonumber(value) or 0, true)
end

SovereignTaskGetStat = function(stat)
    if not menu.nativeApis.STATS or type(menu.nativeApis.STATS.STAT_GET_INT) ~= "function" or not Memory or type(Memory.AllocInt) ~= "function" then
        return nil
    end
    local ptr = nil
    local ok, value = pcall(function()
        ptr = Memory.AllocInt()
        if not ptr or not menu.nativeApis.STATS.STAT_GET_INT(SovereignTaskStatHash(stat), ptr, -1) then
            return nil
        end
        return tonumber(Memory.ReadInt(ptr))
    end)
    if ptr and type(Memory.Free) == "function" then
        pcall(Memory.Free, ptr)
    end
    return ok and value or nil
end

local function SovereignTaskSetBoolStat(stat, value)
    if not menu.nativeApis.STATS or not menu.nativeApis.STATS.STAT_SET_BOOL then
