local function SovereignTaskLegacyTunableKind(hash)
    hash = tonumber(hash)
    if not hash or hash ~= hash or hash ~= math.floor(hash) then return nil end
    local approved = SovereignTaskLegacyTunableHashes[hash]
        or SovereignTaskLegacyTunableHashes[tostring(hash)]
    if approved == true then return "profile" end
    if not SovereignTaskLegacyExactBuild then return nil end
    return SovereignTaskLegacyExactTunableKinds[hash]
        or SovereignTaskLegacyExactTunableKinds[tostring(hash)]
end
