local function SovereignTaskEditionName()
    if Utils1 and type(Utils1.edition) == "function" then
        local ok, edition = pcall(Utils1.edition, Utils1)
        if ok and tostring(edition):lower() == "legacy" then return "Legacy" end
    end
    return "Enhanced"
end

local function SovereignTaskPageSupported(page)
    return tostring(page or ""):lower() ~= "kortz" or SovereignTaskEditionName() == "Enhanced"
end

local function SovereignTaskResolveGlobal(index)
    index = tonumber(index)
    if not index or index ~= index or index < 0 or index == rawget(math, "huge")
        or index ~= math.floor(index) then return nil end
    if SovereignTaskEditionName() == "Enhanced" then return math.floor(index) end
    local mapped = SovereignTaskLegacyGlobals[math.floor(index)]
        or SovereignTaskLegacyGlobals[tostring(math.floor(index))]
    if type(mapped) == "number" and mapped >= 0 and mapped == math.floor(mapped) then
        return mapped
    end
    if SovereignTaskLegacyExactBuild then
        local exact = SovereignTaskLegacyExactGlobals[index]
        if exact then return exact end
        for _, range in ipairs(SovereignTaskLegacyConfirmedGlobalRanges) do
            if index >= range.first and index <= range.last
                and (index - range.first) % range.stride == 0 then
                return math.floor(index)
            end
        end
        for _, translation in ipairs(SovereignTaskLegacyTranslatedGlobalRanges) do
            local offset = index - translation.enhanced
            for _, bounds in ipairs(translation.ranges) do
                if offset >= bounds[1] and offset <= bounds[2] then
                    return math.floor(translation.legacy + offset)
                end
            end
        end
        for _, translation in ipairs(SovereignTaskLegacyStridedGlobalFields) do
            for _, offset in ipairs(translation.offsets) do
                local delta = index - translation.enhanced - offset
                if delta >= 0 and delta <= translation.maxSlot * translation.stride
                    and delta % translation.stride == 0 then
                    return translation.legacy + offset + delta
                end
            end
        end
    end
    SovereignTaskNoticeOnce("legacy_global_" .. tostring(math.floor(index)), "Legacy missions",
        "This mission feature is currently unavailable for this game version.")
    return nil
end

local function SovereignTaskResolveTunable(index)
    index = tonumber(index)
    if not index or index ~= index or index ~= math.floor(index) then return nil end
    if SovereignTaskEditionName() == "Enhanced" then return math.floor(index) end
    local mapped = SovereignTaskLegacyTunables[math.floor(index)]
        or SovereignTaskLegacyTunables[tostring(math.floor(index))]
    if type(mapped) == "number" and mapped >= 0 and mapped == math.floor(mapped) then
        return mapped
    end
    return nil
end

local function SovereignTaskResolveLocal(scriptName, index)
    index = tonumber(index)
    scriptName = tostring(scriptName or "")
    if not index or index ~= index or index < 0 or index == rawget(math, "huge")
        or index ~= math.floor(index) or scriptName == "" then return nil end
    if SovereignTaskEditionName() == "Enhanced" then return math.floor(index) end
    local scriptMap = SovereignTaskLegacyLocals[scriptName]
    if type(scriptMap) ~= "table" then
        scriptMap = SovereignTaskLegacyLocals[tostring(Utils.Joaat(scriptName))]
    end
    local mapped = type(scriptMap) == "table" and (scriptMap[math.floor(index)] or scriptMap[tostring(math.floor(index))])
    if type(mapped) == "number" and mapped >= 0 and mapped == math.floor(mapped) then
        return mapped
    end
    if SovereignTaskLegacyExactBuild then
        local fields = SovereignTaskLegacyLocalFields[scriptName]
        if type(fields) == "table" then
            local exact = type(fields.exact) == "table" and fields.exact[index]
            if type(exact) == "number" then return exact end
            for _, range in ipairs(fields.ranges or {}) do
                if index >= range.enhancedFirst and index <= range.enhancedLast then
                    return range.legacyFirst + (index - range.enhancedFirst)
                end
            end
        end
        if SovereignTaskMappingFeatures.owner_task_local_canary == true then
            local candidates = SovereignTaskLegacyCanaryLocalFields[scriptName]
            local candidate = type(candidates) == "table" and candidates[index]
            if type(candidate) == "number" then return candidate end
        end
    end
    SovereignTaskNoticeOnce("legacy_local_" .. scriptName .. "_" .. tostring(math.floor(index)), "Legacy missions",
        "This mission feature is currently unavailable for this game version.")
    return nil
end

local function SovereignTaskSetGlobal(index, value)
    if not ScriptGlobal or not ScriptGlobal.SetInt then
        return false
    end
    local resolved = SovereignTaskResolveGlobal(index)
    if resolved == nil then return false end
    return SovereignTaskCall("SovereignTask.Global", ScriptGlobal.SetInt, resolved, math.floor(tonumber(value) or 0))
end

local function SovereignTaskGetGlobal(index)
    if not ScriptGlobal or type(ScriptGlobal.GetInt) ~= "function" then
        return nil
    end
    local resolved = SovereignTaskResolveGlobal(index)
    if resolved == nil then return nil end
    local ok, value = pcall(ScriptGlobal.GetInt, resolved)
    if ok and type(value) == "number" and value == value then
        return value
    end
    return nil
end

local function SovereignTaskCurrentPlayerId()
    if not menu.nativeApis.PLAYER or type(menu.nativeApis.PLAYER.PLAYER_ID) ~= "function" then return nil end
    local ok, value = pcall(menu.nativeApis.PLAYER.PLAYER_ID)
    value = ok and tonumber(value) or nil
    if not value or value ~= math.floor(value) or value < 0 or value > 31 then return nil end
    return math.floor(value)
end

local function SovereignTaskValidPlayerId(value)
    value = tonumber(value)
    return value and value == math.floor(value) and value >= 0 and value <= 31
end

local function SovereignTaskScriptHost(scriptName)
    if not menu.nativeApis.NETWORK or type(menu.nativeApis.NETWORK.NETWORK_GET_HOST_OF_SCRIPT) ~= "function" then return nil end
    local ok, value = pcall(menu.nativeApis.NETWORK.NETWORK_GET_HOST_OF_SCRIPT, tostring(scriptName or ""), -1, 0)
    return ok and SovereignTaskValidPlayerId(value) and math.floor(value) or nil
end

local function SovereignTaskPlayerActive(playerId)
    if not SovereignTaskValidPlayerId(playerId) then return false end
    if not menu.nativeApis.NETWORK or type(menu.nativeApis.NETWORK.NETWORK_IS_PLAYER_ACTIVE) ~= "function" then return true end
    local ok, active = pcall(menu.nativeApis.NETWORK.NETWORK_IS_PLAYER_ACTIVE, math.floor(playerId))
    return ok and active == true
end

-- Planning broadcasts store slot membership under the host player and ready
-- state under each real player id. Never assume that task slot N is player N.
local function SovereignTaskForceBoardReady(scriptName, root, stride, playerFieldOffset, readyFieldOffset, noticeKey)
    local host = SovereignTaskScriptHost(scriptName)
    local changed = 0
    if host then
        for slot = 1, 3 do
            local playerId = SovereignTaskGetGlobal(root + 1 + host * stride + playerFieldOffset + slot)
            if SovereignTaskPlayerActive(playerId) and playerId ~= host
                and SovereignTaskSetGlobal(root + 1 + playerId * stride + readyFieldOffset + slot, 1) then
                changed = changed + 1
            end
        end
    end
    if changed == 0 then
        SovereignTaskNoticeOnce(noticeKey, "Mission preparation", "No mission members available to update. Try again at the mission board.")
    end
    return changed > 0
end

local function SovereignTaskForceClassicReady()
    local host = SovereignTaskCurrentPlayerId()
    local changed = 0
    for slot = 0, 3 do
        local playerId = SovereignTaskGetGlobal(1936406 + 12 + 1 + slot)
        if SovereignTaskPlayerActive(playerId) and playerId ~= host
            and SovereignTaskSetGlobal(2658296 + 1 + playerId * 468 + 270, 6) then
            changed = changed + 1
        end
    end
    if changed == 0 then
        SovereignTaskNoticeOnce("classic_ready_empty", "Mission preparation", "No mission members available to update. Try again at the mission board.")
    end
    return changed > 0
end

local function SovereignTaskSetGlobalFloat(index, value)
    if not ScriptGlobal or not ScriptGlobal.SetFloat then
        return false
    end
    local resolved = SovereignTaskResolveGlobal(index)
    if resolved == nil then return false end
    return SovereignTaskCall("SovereignTask.GlobalFloat", ScriptGlobal.SetFloat, resolved, tonumber(value) or 0.0)
end

local function SovereignTaskSetLocal(scriptName, index, value)
    if not ScriptLocal or not ScriptLocal.SetInt then
        return false
    end
    local resolved = SovereignTaskResolveLocal(scriptName, index)
    if resolved == nil then return false end
    return SovereignTaskCall(
        "SovereignTask.Local",
        ScriptLocal.SetInt,
        Utils.Joaat(tostring(scriptName)),
        resolved,
        math.floor(tonumber(value) or 0)
    )
end

local function SovereignTaskGetLocal(scriptName, index)
    if not ScriptLocal or type(ScriptLocal.GetInt) ~= "function" then
        return nil
    end
    local resolved = SovereignTaskResolveLocal(scriptName, index)
    if resolved == nil then return nil end
    local ok, value = pcall(
        ScriptLocal.GetInt,
        Utils.Joaat(tostring(scriptName)),
        resolved
    )
    if ok and type(value) == "number" and value == value then
        return value
    end
    return nil
end

local function SovereignTaskIsScriptRunning(scriptName)
    if GTA and type(GTA.IsScriptRunning) == "function" then
        local ok, running = pcall(GTA.IsScriptRunning, tostring(scriptName))
        if ok and running == true then
            return true
        end
    end
    if menu.nativeApis.SCRIPT and type(menu.nativeApis.SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH) == "function"
        and Utils and type(Utils.Joaat) == "function" then
        local hashOk, scriptHash = pcall(Utils.Joaat, tostring(scriptName))
        if not hashOk or type(scriptHash) ~= "number" then return false end
        local ok, count = pcall(menu.nativeApis.SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH, scriptHash)
        if ok and type(count) == "number" then
            return count > 0
        end
    end
    return false
end

-- Solo mode changes minimum-player requirements, not the game's actual team
-- topology, live participant counters, organization registration or array sizes.
-- OnUnload is registered outside the mission adapter closure, so keep the
-- cleanup object reachable from that callback after the adapter returns.
SovereignTaskSoloRuntime = {ownedGlobals = {}}
function SovereignTaskSoloRuntime:Context(scriptName, requireHost)
    local network = menu.nativeApis.NETWORK
    local player = SovereignTaskCurrentPlayerId()
    if player == nil or not SovereignTaskIsScriptRunning(scriptName)
        or not Script or type(Script.ExecuteAsScript) ~= "function" or not network
        or type(network.NETWORK_GET_NUM_PARTICIPANTS) ~= "function"
        or type(network.NETWORK_IS_PLAYER_A_PARTICIPANT) ~= "function"
        or type(network.NETWORK_IS_PLAYER_ACTIVE) ~= "function" then return nil end
    -- Solo launcher globals only need a live script context on this machine.
    local context
    local ok = pcall(Script.ExecuteAsScript, scriptName, function()
        local count = network.NETWORK_GET_NUM_PARTICIPANTS()
        local isHost = network.NETWORK_IS_HOST_OF_THIS_SCRIPT ~= nil and network.NETWORK_IS_HOST_OF_THIS_SCRIPT() == true
        if type(count) == "number" and count >= 1 and (requireHost ~= true or isHost == true)
            and network.NETWORK_IS_PLAYER_A_PARTICIPANT(player) == true
            and network.NETWORK_IS_PLAYER_ACTIVE(player) == true then
            context = {player = player, count = count, isHost = isHost}
        end
    end)
    return ok and context or nil
end
function SovereignTaskSoloRuntime:Organization(player)
    local inventory = SovereignBusinessInventory
    if not inventory or type(inventory.GetLocalOrganizationState) ~= "function" then return nil end
    local ok, state = pcall(inventory.GetLocalOrganizationState, inventory)
    if not ok or type(state) ~= "table" or state.valid ~= true then return nil end
    if state.playerId == player and state.bossId == player and state.isBoss == true
        and (state.role == "ceo" or state.role == "vip" or state.role == "mc_president") then
        return {playerId = player, bossId = player, role = state.role}
    end
    return false -- A real resignation must invalidate the earlier snapshot.
end
function SovereignTaskSoloRuntime:RestoreGlobals()
    for index, record in pairs(self.ownedGlobals) do
        local original = record
        local target = 1
        if type(record) == "table" then
            original, target = record.original, record.target
        end
        -- Restore only values still owned by this toggle; preserve game updates.
        if SovereignTaskGetGlobal(index) == target then SovereignTaskSetGlobal(index, original) end
    end
    self.ownedGlobals = {}
end
function SovereignTaskSoloRuntime:Reset()
    self:RestoreGlobals()
    self.organization, self.mission, self.controller = nil, nil, nil
end
function SovereignTaskSoloRuntime:Minimum(index)
    local value = SovereignTaskGetGlobal(index)
    if type(value) ~= "number" or value ~= math.floor(value) or value < 0 or value > 32 then return false end
    if value <= 1 then return true end
    return self:SetOwnedGlobal(index, 1)
end
function SovereignTaskSoloRuntime:SetOwnedGlobal(index, target)
    local value = SovereignTaskGetGlobal(index)
    if type(value) ~= "number" or value ~= math.floor(value)
        or type(target) ~= "number" or target ~= math.floor(target) then return false end
    if value == target then return true end
    if self.ownedGlobals[index] == nil then
        self.ownedGlobals[index] = {original = value, target = target}
    end
    if not SovereignTaskSetGlobal(index, target) then return false end
    return SovereignTaskGetGlobal(index) == target
end
local function SovereignTaskApplySoloLauncherGlobals()
    if SovereignTaskIsScriptRunning("fm_mission_controller")
        or SovereignTaskIsScriptRunning("fm_mission_controller_2020")
        or SovereignTaskIsScriptRunning("fm_mission_controller_v3") then return false end
    if SovereignTaskSoloRuntime.controller then SovereignTaskSoloRuntime:Reset() end
    if not SovereignTaskIsScriptRunning("fmmc_launcher") then
        SovereignTaskSoloRuntime:Reset()
        return false
    end
    local context = SovereignTaskSoloRuntime:Context("fmmc_launcher", false)
    if not context then
        SovereignTaskSoloRuntime:RestoreGlobals()
        SovereignTaskSoloRuntime.organization = nil
        return false
    end
    local mission = SovereignTaskGetLocal("fmmc_launcher", 20196 + 34)
    if type(mission) ~= "number" or mission ~= math.floor(mission) or mission < 1 or mission > 1500 then return false end
    if SovereignTaskSoloRuntime.mission ~= mission then
        SovereignTaskSoloRuntime:Reset()
        SovereignTaskSoloRuntime.mission = mission
    end
    local organization = SovereignTaskSoloRuntime:Organization(context.player)
    if organization ~= nil then SovereignTaskSoloRuntime.organization = organization or nil end
    -- These are launcher gates, not mission-controller topology. They must be
    -- normalized while fmmc_launcher still owns setup or Doomsday can remain
    -- in its multiplayer/CEO-departure branch and never start the prep.
    local applied = SovereignTaskSoloRuntime:SetOwnedGlobal(2635125 + 1, 0)
    applied = SovereignTaskSoloRuntime:SetOwnedGlobal(4718592 + 3772, 1) and applied
    applied = SovereignTaskSoloRuntime:SetOwnedGlobal(4718592 + 3773, 1) and applied
    if SovereignTaskEditionName() == "Enhanced" then
        applied = SovereignTaskSoloRuntime:SetOwnedGlobal(4718592 + 3776, 1) and applied
    end
    applied = SovereignTaskSoloRuntime:Minimum(4718592 + 3769) and applied
    if SovereignTaskEditionName() == "Enhanced" then
        applied = SovereignTaskSoloRuntime:SetOwnedGlobal(4718592 + 196663 + 1, 1) and applied
    end
    applied = SovereignTaskSoloRuntime:Minimum(794989 + 80 + mission * 95) and applied
    local minimum = SovereignTaskGetLocal("fmmc_launcher", 20196 + 15)
    if type(minimum) == "number" and minimum == math.floor(minimum) and minimum > 1 and minimum <= 32 then
        applied = SovereignTaskSetLocal("fmmc_launcher", 20196 + 15, 1) and applied
    end
    local retry = SovereignTaskGetLocal("fmmc_launcher", 20438)
    if type(retry) == "number" and retry == math.floor(retry) and retry ~= 0 then
        applied = SovereignTaskSetLocal("fmmc_launcher", 20438, 0) and applied
    end
    return applied, mission
end

