-- Only the classic organization cache has a verified scalar local mapping.
-- Newer decompiler unk* names are not usable addresses and are never guessed.
local function SovereignTaskRepairSoloOrganizationCache(controller, context)
    if not controller.organizationBoss or not context then return false end
    local player = context.player
    local cached = SovereignTaskGetLocal(controller.name, controller.organizationBoss)
    if cached == player then return true end
    if cached ~= -1 then return false end
    local organization = SovereignTaskSoloRuntime:Organization(player)
    if organization == false then SovereignTaskSoloRuntime.organization = nil; return false end
    organization = organization or SovereignTaskSoloRuntime.organization
    if not organization or organization.playerId ~= player or organization.bossId ~= player then return false end
    if SovereignTaskGetLocal(controller.name, controller.base + controller.failureReason) ~= 4 then return false end
    for team = 0, 3 do
        local reason = SovereignTaskGetLocal(controller.name, controller.base + controller.failureReason + 1 + team)
        if type(reason) ~= "number" or reason ~= math.floor(reason) or reason < 0 or reason > 255 then return false end
        if reason == controller.ceoDeparture or reason == controller.mcDeparture then
            SovereignTaskNoticeOnce("solo_organization_failed", "Mission tools",
                "This mission has already recorded an organization departure. Restart it with solo mode enabled before entering the lobby.")
            return false
        end
    end
    if not SovereignTaskSetLocal(controller.name, controller.organizationBoss, player) then return false end
    return SovereignTaskGetLocal(controller.name, controller.organizationBoss) == player
end

-- These are the controller failure values used for a team-leave message while
-- the mission is already reduced to one live participant. They are deliberately
-- narrower than the full departure table: organization-leave failures (66/67)
-- and all unrelated mission failures remain visible and block the rewrite.
local function SovereignTaskIsTransientSoloTeamLeave(controller, reason)
    if type(reason) ~= "number" or reason ~= math.floor(reason) then return false end
    if controller.name == "fm_mission_controller" then
        return reason == 29 or reason == 39 or reason == 40
    end
    return reason == 27 or reason == 45
end

local function SovereignTaskIsValidTeamQuitValue(value)
    return type(value) == "number" and value == math.floor(value)
        and value >= -1 and value <= 255
end

-- A prior failed lobby can leave 66/67 in the same team-failure array that the
-- controller uses for the CEO/MC departure notice. Clear only that latch, and
-- only after the live script proves this is a one-player session owned by the
-- local organization boss. Other mission failure reasons remain untouched.
local function SovereignTaskClearSoloDepartureFailures(controller, context)
    if not context then return false end
    local organization = SovereignTaskSoloRuntime:Organization(context.player)
    if organization == false then return false end
    if organization ~= nil then SovereignTaskSoloRuntime.organization = organization end
    if not SovereignTaskSoloRuntime.organization then return false end
    local cleared = false
    for team = 0, 3 do
        local failureIndex = controller.base + controller.failureReason + 1 + team
        local reason = SovereignTaskGetLocal(controller.name, failureIndex)
        if reason == 66 or reason == 67 then
            if not SovereignTaskSetLocal(controller.name, failureIndex, 0) then return false end
            local quitIndex = controller.teamQuitReason + 1 + team
            local quit = SovereignTaskGetLocal(controller.name, quitIndex)
            if type(quit) == "number" and quit == math.floor(quit) and quit ~= -1 then
                if not SovereignTaskSetLocal(controller.name, quitIndex, -1) then return false end
            end
            cleared = true
        end
    end
    return cleared
end

local function SovereignTaskApplySoloControllerState()
    local controller
    for _, candidate in ipairs(SovereignTaskSoloControllerLayouts) do
        if SovereignTaskIsScriptRunning(candidate.name) then
            if controller then return false end
            controller = candidate
        end
    end
    if not controller then return false end
    SovereignTaskSoloRuntime.controller = controller.name
    local context = SovereignTaskSoloRuntime:Context(controller.name)
    if not context then return false end
    -- Repair before normalizing expected-player counts, not after a failure is latched.
    SovereignTaskClearSoloDepartureFailures(controller, context)
    SovereignTaskRepairSoloOrganizationCache(controller, context)
    local teams = SovereignTaskGetLocal(controller.name, controller.base + controller.teamCount)
    if type(teams) ~= "number" or teams ~= math.floor(teams) or teams < 1 or teams > 4 then return false end
    if SovereignTaskGetLocal(controller.name, controller.base + controller.activeCount) ~= 4
        or SovereignTaskGetLocal(controller.name, controller.base + controller.expectedCount) ~= 4
        or SovereignTaskGetLocal(controller.name, controller.base + controller.failureReason) ~= 4
        or SovereignTaskGetLocal(controller.name, controller.base + controller.teamCountCopy) ~= teams then return false end
    local changes, activeTeams, actual, expected = {}, {}, 0, 0
    local observations = {}
    local function addChange(index, before, after)
        if before ~= after then changes[#changes + 1] = {index = index, before = before, after = after} end
    end
    for team = 0, 3 do
        local live = SovereignTaskGetLocal(controller.name, controller.base + controller.activeCount + 1 + team)
        local index = controller.base + controller.expectedCount + 1 + team
        local before = SovereignTaskGetLocal(controller.name, index)
        local failure = SovereignTaskGetLocal(controller.name, controller.base + controller.failureReason + 1 + team)
        local quit = SovereignTaskGetLocal(controller.name, controller.teamQuitReason + 1 + team)
        if type(live) ~= "number" or live ~= math.floor(live) or live < 0 or live > 1
            or type(before) ~= "number" or before ~= math.floor(before) or before < 0 or before > 32
            or type(failure) ~= "number" or failure ~= math.floor(failure) or failure < 0 or failure > 255
            or not SovereignTaskIsValidTeamQuitValue(quit)
            or (team >= teams and live ~= 0) then return false end
        observations[team] = {live = live, before = before, failure = failure, quit = quit, index = index}
        actual, expected = actual + live, expected + before
        if live == 1 then activeTeams[#activeTeams + 1] = team end
    end
    -- Never fabricate a player/team during loading, migration or multiplayer.
    if actual ~= 1 or #activeTeams ~= 1
        or SovereignTaskGetLocal(controller.name, controller.base + controller.participantCount) ~= 1 then return false end
    local activeTeam = activeTeams[1]
    for team = 0, 3 do
        local item = observations[team]
        if item.failure ~= 0 then
            -- A team-leave latch is safe to clear only for the one live team in
            -- a confirmed solo session. Every other failure is preserved.
            if team ~= activeTeam or not SovereignTaskIsTransientSoloTeamLeave(controller, item.failure) then
                return false
            end
            addChange(controller.base + controller.failureReason + 1 + team, item.failure, 0)
        end
        if item.quit ~= -1 and item.quit ~= 0 then
            if team ~= activeTeam or not SovereignTaskIsTransientSoloTeamLeave(controller, item.quit) then
                return false
            end
            -- The decompiled controllers initialize this side array to -1.
            addChange(controller.teamQuitReason + 1 + team, item.quit, -1)
        end
        addChange(item.index, item.before, item.live)
    end
    local totalIndex = controller.base + controller.expectedTotal
    local total = SovereignTaskGetLocal(controller.name, totalIndex)
    if type(total) ~= "number" or total ~= math.floor(total) or total < 0 or total > 128 or total ~= expected then return false end
    addChange(totalIndex, total, 1)
    for slot, change in ipairs(changes) do
        if not SovereignTaskSetLocal(controller.name, change.index, change.after)
            or SovereignTaskGetLocal(controller.name, change.index) ~= change.after then
            -- No yield occurs in the batch. Undo only writes which still match ours.
            for undo = slot, 1, -1 do
                local field = changes[undo]
                if SovereignTaskGetLocal(controller.name, field.index) == field.after then
                    SovereignTaskSetLocal(controller.name, field.index, field.before)
                end
            end
            return false
        end
    end
    return true
end

local function SovereignTaskSetFloatLocal(scriptName, index, value)
    if not ScriptLocal or not ScriptLocal.SetFloat then
        return false
    end
    local resolved = SovereignTaskResolveLocal(scriptName, index)
    if resolved == nil then return false end
    return SovereignTaskCall(
        "SovereignTask.FloatLocal",
        ScriptLocal.SetFloat,
        Utils.Joaat(tostring(scriptName)),
        resolved,
        tonumber(value) or 0.0
    )
end

local function SovereignTaskApplyStats(values)
    local changed = 0
    for stat, value in pairs(values or {}) do
        if SovereignTaskSetStat(stat, value) then
            changed = changed + 1
        end
    end
    return changed
end

local function SovereignTaskApplyBoolStats(values)
    local changed = 0
    for stat, value in pairs(values or {}) do
        if SovereignTaskSetBoolStat(stat, value) then
            changed = changed + 1
        end
    end
    return changed
end

local function SovereignTaskSaveStats()
    if menu.nativeApis.STATS and type(menu.nativeApis.STATS.STAT_SAVE) == "function" then
        return SovereignTaskCall("SovereignTask.StatSave", menu.nativeApis.STATS.STAT_SAVE, 0, false, 3, false)
    end
    return false
end

local function SovereignTaskCommitStatsIfAvailable()
    local stats = menu.nativeApis and menu.nativeApis.STATS
    if not stats or type(stats.STAT_SAVE) ~= "function" then return true end
    return SovereignTaskSaveStats()
end

-- Preparation controls touch persistent character stats.  A successful native
-- call is not enough: the board can still be showing the old cached value.
-- Save once, then verify when the host exposes a stat readback API.
local function SovereignTaskSetPrepStatVerified(stat, value)
    value = math.floor(tonumber(value) or 0)
    if not SovereignTaskSetStat(stat, value) then return false end
    if not SovereignTaskCommitStatsIfAvailable() then return false end
    local actual = SovereignTaskGetStat(stat)
    return type(actual) == "number" and actual == value
end

