local function SovereignTaskApplyDoomsdayCut(playerSlot, value)
    value = math.max(0, math.min(1000, math.floor(tonumber(value) or 0)))
    -- gb_gang_ops_planning.c: Global_1969071.f_812.f_50[1..4].
    local slot = math.max(1, math.min(4, math.floor(tonumber(playerSlot) or 1)))
    local address = 1969071 + 812 + 50 + slot
    return SovereignTaskSetGlobal(address, value)
end

local function SovereignTaskApplyDoomsdayPreset(act)
    local preset = {
        [1] = { flow = 503, status = -229383, cut = 209 },
        [2] = { flow = 240, status = -229378, cut = 142 },
        [3] = { flow = 16368, status = -229380, cut = 113 },
    }
    local data = preset[tonumber(act)]
    if not data then
        return false
    end
    if SovereignTaskState.doomsdayPreset and SovereignTaskState.doomsdayPreset ~= act then
        -- Always retain the explanation that presets are mutually exclusive, so users understand why the previous setting was overwritten.
        SovereignTaskToast("The Doomsday Heist", "Finish the current preset before switching acts", "warning")
        return false
    end
    SovereignTaskApplyStats({
        GANGOPS_FLOW_MISSION_PROG = data.flow,
        GANGOPS_HEIST_STATUS = data.status,
        GANGOPS_FLOW_NOTIFICATIONS = 1557,
    })
    for slot = 1, 4 do
        SovereignTaskApplyDoomsdayCut(slot, data.cut)
    end
    SovereignTaskState.doomsdayPreset = act
    SovereignTaskNoticeOnce("doomsday_preset", "The Doomsday Heist", "This preset updates preparation and cuts. Disable it after completing the mission board.")
    return true
end

local function SovereignTaskForNearbyNpc(callback)
    if type(callback) ~= "function" then
        return 0
    end
    local peds = {}
    if PoolMgr and type(PoolMgr.GetMaxPedCount) == "function" and type(PoolMgr.GetPed) == "function" then
        local okMax, maxCount = pcall(PoolMgr.GetMaxPedCount)
        if okMax and type(maxCount) == "number" then
            for index = 0, maxCount - 1 do
                local okPed, ped = pcall(PoolMgr.GetPed, index)
                if okPed and type(ped) == "number" and ped ~= 0 and ped ~= -1 then
                    peds[#peds + 1] = ped
                end
            end
        end
    elseif EntityManager and type(EntityManager.GetNearbyPeds) == "function" then
        peds = EntityManager:GetNearbyPeds(1000.0) or {}
    end

    local count = 0
    for index, ped in ipairs(peds) do
        local isPlayer = false
        if menu.nativeApis.PED and menu.nativeApis.PED.IS_PED_A_PLAYER then
            local ok, result = pcall(menu.nativeApis.PED.IS_PED_A_PLAYER, ped)
            isPlayer = ok and result == true
        end
        if not isPlayer and menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(ped) then
            if SovereignTaskCall("SovereignTask.Npc", callback, ped) then
                count = count + 1
            end
        end
        if index % 32 == 0 then
            Script.Yield(0)
        end
    end
    return count
end

SovereignTaskPrepChoices = {"Keep current", "Skip setups", "Redo setups"}

SovereignTaskApplyClassicPrepChoice = function(definition, choice)
    choice = tonumber(choice) or 0
    if choice == 0 then
        return true
    end
    local completed = choice == 1
    if completed and definition.done == nil then
        return false
    end
    return SovereignTaskSetPrepStatVerified(
        definition.stat,
        completed and definition.done or (definition.reset or 0)
    )
end

SovereignTaskApplyKortzPrepChoice = function(definition, choice)
    if not SovereignTaskPageSupported("kortz") then return false end
    choice = tonumber(choice) or 0
    if choice == 0 then
        return true
    end
    local completed = choice == 1
    if definition.mainBit then
        local mainValue = SovereignTaskGetStatByIndex(14285)
        if type(mainValue) ~= "number" then
            return false
        end
        local mainMask = 1 << definition.mainBit
        mainValue = completed and (mainValue | mainMask) or (mainValue & ~mainMask)
        local ok = SovereignTaskSetStatByIndex(14285, mainValue)
        local prepValue = SovereignTaskGetStatByIndex(14287)
        if type(prepValue) ~= "number" then return false end
        local categoryMask = 1 << (definition.categoryPrepBit or 7)
        local selectedMain = mainValue & ((1 << 9) | (1 << 10) | (1 << 11))
        prepValue = completed and (prepValue | categoryMask)
            or (selectedMain == 0 and (prepValue & ~categoryMask) or prepValue)
        ok = SovereignTaskSetStatByIndex(14287, prepValue) and ok
        if not ok then return false end
        if not SovereignTaskCommitStatsIfAvailable() then return false end
        local mainCheck = SovereignTaskGetStatByIndex(14285)
        local prepCheck = SovereignTaskGetStatByIndex(14287)
        if type(mainCheck) ~= "number" or type(prepCheck) ~= "number" then
            return false
        end
        if (mainCheck & mainMask) ~= (completed and mainMask or 0) then
            return false
        end
        local categorySet = (prepCheck & categoryMask) ~= 0
        if completed then
            return categorySet
        end
        return selectedMain ~= 0 or not categorySet
    end
    local current = SovereignTaskGetStatByIndex(14287)
    if type(current) ~= "number" then
        return false
    end
    local mask = 1 << definition.prepBit
    current = completed and (current | mask) or (current & ~mask)
    local ok = SovereignTaskSetStatByIndex(14287, current)
    if not SovereignTaskCommitStatsIfAvailable() then return false end
    if not ok then return false end
    local verify = SovereignTaskGetStatByIndex(14287)
    return type(verify) == "number" and (verify & mask) == (completed and mask or 0)
end

SovereignTaskGetStatByIndex = function(index)
    local hash = SovereignTaskStatHashByIndex(index)
    if hash == 0 or not menu.nativeApis.STATS or type(menu.nativeApis.STATS.STAT_GET_INT) ~= "function" or not Memory or type(Memory.AllocInt) ~= "function" then
        return nil
    end
    local ptr = nil
    local ok, value = pcall(function()
        ptr = Memory.AllocInt()
        if not ptr or not menu.nativeApis.STATS.STAT_GET_INT(hash, ptr, -1) then
            return nil
        end
        return tonumber(Memory.ReadInt(ptr))
    end)
    if ptr and type(Memory.Free) == "function" then
        pcall(Memory.Free, ptr)
    end
    return ok and value or nil
end

SovereignTaskSetStatBit = function(stat, bit, completed)
    bit = math.floor(tonumber(bit) or -1)
    if bit < 0 or bit > 30 then return false end
    local current = SovereignTaskGetStat(stat)
    if type(current) ~= "number" then
        return false
    end
    local mask = 1 << bit
    local nextValue = completed and (current | mask) or (current & ~mask)
    if not SovereignTaskSetPrepStatVerified(stat, nextValue) then return false end
    local verify = SovereignTaskGetStat(stat)
    return type(verify) == "number" and (verify & mask) == (completed and mask or 0)
end

local function SovereignTaskRefreshPrepBoard(definition, choice)
    if not definition then return false end
    if definition.refreshScript and definition.refreshLocal then
        if not SovereignTaskIsScriptRunning(definition.refreshScript) then
            return true
        end
        local value = math.floor(tonumber(definition.refreshValue) or 0)
        if not SovereignTaskSetLocal(definition.refreshScript, definition.refreshLocal, value) then
            return false
        end
        return SovereignTaskGetLocal(definition.refreshScript, definition.refreshLocal) == value
    end
    if definition.kind == "classic" then
        local playerId = SovereignTaskCurrentPlayerId()
        if playerId == nil then return false end
        local globalIndex = 1877383 + 1 + playerId * 77 + 75
        local value = choice == 1 and 1 or 0
        if not SovereignTaskSetGlobal(globalIndex, value) then return false end
        return SovereignTaskGetGlobal(globalIndex) == value
    end
    return true
end

-- gb_gang_ops_planning.c stores the 14 Doomsday prep missions in
-- Global_1882797[player].f_43.f_24, one bit per prep mission (16..29).
SovereignTaskSetDoomsdayPrepBit = function(bit, completed)
    bit = math.floor(tonumber(bit) or -1)
    if bit < 0 or bit > 13 then return false end
    local playerId = SovereignTaskCurrentPlayerId()
    if not playerId then return false end
    local globalIndex = 1882797 + 1 + playerId * 321 + 43 + 24
    local current = SovereignTaskGetGlobal(globalIndex)
    if type(current) ~= "number" then
        return false
    end
    local mask = 1 << bit
    local nextValue = completed and (current | mask) or (current & ~mask)
    if not SovereignTaskSetGlobal(globalIndex, nextValue) then return false end
    local verify = SovereignTaskGetGlobal(globalIndex)
    return type(verify) == "number" and (verify & mask) == (completed and mask or 0)
end


local function SovereignTaskSetLocalBit(scriptName, index, bit)
    local current = SovereignTaskGetLocal(scriptName, index)
    if type(current) ~= "number" then
        return false
    end
    return SovereignTaskSetLocal(scriptName, index, current | (1 << bit))
end

local function SovereignTaskRequestScriptHost(scriptName)
    scriptName = tostring(scriptName or "")
    if not SovereignTaskIsScriptRunning(scriptName) then
        SovereignTaskNoticeOnce(
            "finish_missing_" .. scriptName,
            "Mission tools",
            "Enter the corresponding mission before using this feature."
        )
        return false
    end

    local canCheckHost = Script and type(Script.ExecuteAsScript) == "function"
        and menu.nativeApis.NETWORK and type(menu.nativeApis.NETWORK.NETWORK_IS_HOST_OF_THIS_SCRIPT) == "function"
    local function isHost()
        if not canCheckHost then
            return nil
        end
        local host = false
        local ok = pcall(Script.ExecuteAsScript, scriptName, function()
            host = menu.nativeApis.NETWORK.NETWORK_IS_HOST_OF_THIS_SCRIPT() == true
        end)
        return ok and host
    end

    if isHost() == true then
        return true
    end
    if not GTA or type(GTA.ForceScriptHost) ~= "function" then
        return not canCheckHost
    end

    for _ = 1, 300 do
        pcall(GTA.ForceScriptHost, Utils.Joaat(scriptName))
        if not canCheckHost then
            return true
        end
        Script.Yield(10)
        if isHost() == true then
            return true
        end
        if not SovereignTaskIsScriptRunning(scriptName) then
            return false
        end
    end
    SovereignTaskToast("Quick completion", "Mission unavailable. Try again later.", "warning")
    return false
end

-- The paired mission controllers consume bits 17..20 for teams 0..3.
-- Bit 10 is a different state flag and must not be changed by objective skipping.
local function SovereignTaskSkipObjective()
    local controller
    for _, candidate in ipairs(SovereignTaskSoloControllerLayouts) do
        if SovereignTaskIsScriptRunning(candidate.name) then
            if controller then
                SovereignTaskToast("Mission tools", "Mission transition in progress. Wait until loading finishes.", "warning")
                return false
            end
            controller = candidate
        end
    end
    if not controller then
        SovereignTaskToast("Mission tools", "Enter an active mission before skipping an objective.", "warning")
        return false
    end
    if SovereignTaskState.skipObjectivePending then return false end
    SovereignTaskState.skipObjectivePending = true
    local ok, result = pcall(function()
        if not SovereignTaskRequestScriptHost(controller.name) then return false end
        local host = false
        if Script and type(Script.ExecuteAsScript) == "function"
            and menu.nativeApis.NETWORK and type(menu.nativeApis.NETWORK.NETWORK_IS_HOST_OF_THIS_SCRIPT) == "function" then
            local checked = pcall(Script.ExecuteAsScript, controller.name, function()
                host = menu.nativeApis.NETWORK.NETWORK_IS_HOST_OF_THIS_SCRIPT() == true
            end)
            host = checked and host
        else
            local player = SovereignTaskCurrentPlayerId()
            host = player ~= nil and SovereignTaskScriptHost(controller.name) == player
        end
        if not host or not SovereignTaskIsScriptRunning(controller.name) then
            SovereignTaskToast("Mission tools", "Mission host control is unavailable. No objective state was changed.", "warning")
            return false
        end
        local teams = SovereignTaskGetLocal(controller.name, controller.base + controller.teamCount)
        local current = SovereignTaskGetLocal(controller.name, controller.base + 2)
        if type(teams) ~= "number" or teams ~= math.floor(teams) or teams < 1 or teams > 4
            or type(current) ~= "number" or current ~= math.floor(current)
            or current < -2147483648 or current > 4294967295 then
            SovereignTaskToast("Mission tools", "Mission state is not ready. Try again after the objective appears.", "warning")
            return false
        end
        local mask = 0
        for team = 0, teams - 1 do mask = mask | (1 << (17 + team)) end
        if (current & mask) ~= 0 then
            SovereignTaskToast("Mission tools", "An objective transition is already pending.", "info")
            return false
        end
        local nextValue = (current | mask) & 0xFFFFFFFF
        if nextValue >= 0x80000000 then nextValue = nextValue - 0x100000000 end
        if not SovereignTaskSetLocal(controller.name, controller.base + 2, nextValue)
            or SovereignTaskGetLocal(controller.name, controller.base + 2) ~= nextValue then
            SovereignTaskToast("Mission tools", "Could not submit the objective transition. Try again.", "warning")
            return false
        end
        -- Submit once. Reapplying each frame can skip several objectives.
        SovereignTaskToast("Mission tools", "Objective transition requested for the active mission.", "info")
        return true
    end)
    SovereignTaskState.skipObjectivePending = nil
    if not ok then
        SovereignTaskToast("Mission tools", "Objective transition could not be completed. Try again after loading.", "warning")
        return false
    end
    return result == true
end

local function SovereignTaskSetLocalBatch(scriptName, fields, executeAsScript)
    if not ScriptLocal or type(ScriptLocal.SetInt) ~= "function"
        or type(fields) ~= "table" or #fields == 0 then return false end
    local resolved = {}
    for slot, field in ipairs(fields) do
        local address = SovereignTaskResolveLocal(scriptName, field[1])
        local value = tonumber(field[2])
        if address == nil or not value or value ~= value or value == rawget(math, "huge")
            or value == -rawget(math, "huge") then return false end
        resolved[slot] = {address, math.floor(value)}
    end
    local scriptHash = Utils.Joaat(scriptName)
    local function writeResolved()
        -- Resolve every field first. Finish state belongs last, so a rejected
        -- mapping or failed counter write cannot advance an incomplete batch.
        for _, field in ipairs(resolved) do
            if not SovereignTaskCall("SovereignTask.Local", ScriptLocal.SetInt,
                scriptHash, field[1], field[2]) then return false end
        end
        return true
    end
    if executeAsScript and Script and type(Script.ExecuteAsScript) == "function" then
        local batchOk = false
        local ok = pcall(Script.ExecuteAsScript, scriptName, function()
            batchOk = writeResolved()
        end)
        return ok and batchOk
    end
    return writeResolved()
end

local function SovereignTaskFinishCayoFamily()
    local scriptName
    local base
    if SovereignTaskIsScriptRunning("fm_mission_controller_2020") then
        scriptName = "fm_mission_controller_2020"
        base = 56504
    elseif SovereignTaskIsScriptRunning("fm_mission_controller_v3") then
        scriptName = "fm_mission_controller_v3"
        base = 57250
    end
    if not scriptName or not SovereignTaskRequestScriptHost(scriptName) then
        return false
    end

    return SovereignTaskSetLocalBatch(scriptName, {
        {base + 1776 + 1, 50},
        {base, 9},
    })
end

local function SovereignTaskFinishCasinoClassic()
    local scriptName = "fm_mission_controller"
    local base = 20412
    if not SovereignTaskRequestScriptHost(scriptName) then
        return false
    end

    local fields = {}
    if SovereignTaskGetLocal(scriptName, 1695) == 26 then
        fields[#fields + 1] = {base + 2687, 0}
    end
    fields[#fields + 1] = {base + 1740 + 1, 80}
    fields[#fields + 1] = {base + 2686, 10000000}
    fields[#fields + 1] = {29326 + 1, 99999}
    fields[#fields + 1] = {32785 + 1 + 68, 99999}
    fields[#fields + 1] = {base + 1062, 5}
    return SovereignTaskSetLocalBatch(scriptName, fields)
end

local function SovereignTaskDoomsdayContext(finaleOnly)
    local scriptName = "fm_mission_controller"
    if not SovereignTaskIsScriptRunning(scriptName) then
        return false, "fm_mission_controller is not running"
    end
    local launcherState = SovereignTaskGetGlobal(2685155 + 20)
    if launcherState ~= 1 then
        return false, "Doomsday launcher state is not active"
    end
    -- The paired launcher uses the chapter-specific value in +21 for ACT I,
    -- ACT II and ACT III. Requiring it to equal 1 made the finish action work
    -- only for one chapter. The controller flow is the authoritative finale
    -- gate; +21 is retained as context only.
    -- 0 is setup and 12 is the results flow. Only touch an active mission.
    local controllerState = SovereignTaskGetLocal(scriptName, 20412)
    if controllerState ~= 9 then
        return false, "Doomsday finale state is " .. tostring(controllerState or "unavailable")
    end
    return true
end

local function SovereignTaskSkipDoomsdayHacking()
    if not SovereignTaskDoomsdayContext(false)
        or not menu.nativeApis.AUDIO or type(menu.nativeApis.AUDIO.IS_AUDIO_SCENE_ACTIVE) ~= "function" then return false end
    local scriptName = "fm_mission_controller"
    local function active(scene)
        local ok, value = pcall(menu.nativeApis.AUDIO.IS_AUDIO_SCENE_ACTIVE, scene)
        return ok and value == true
    end
    -- The two minigames are local to the player using the terminal. Requiring
    -- script host here would wrongly exclude a teammate doing the puzzle.
    if active("DLC_XM17_IAA_Hack_Minigame_Scene")
        and SovereignTaskGetLocal(scriptName, 1588) == 1 then
        -- Let the game run its success delay, result bit and cleanup. Never
        -- rewrite the tutorial selector or keep resetting the stopwatch.
        if not SovereignTaskSetLocalBatch(scriptName, {{1557, 3}, {1588, 2}}) then return false end
        return SovereignTaskGetLocal(scriptName, 1588) == 2
    end
    if active("DLC_XM17_Silo_Laser_Hack_Minigame_Scene")
        and SovereignTaskGetLocal(scriptName, 1449) == 2 then
        if not SovereignTaskSetLocal(scriptName, 1449, 3) then return false end
        return SovereignTaskGetLocal(scriptName, 1449) == 3
    end
    return false
end

local function SovereignTaskFinishDoomsday()
    local scriptName = "fm_mission_controller"
    local base = 20412
    local contextOk, contextReason = SovereignTaskDoomsdayContext(true)
    if not contextOk then
        Logger:Warn("SovereignTask", "Doomsday finish rejected: " .. tostring(contextReason))
        return false, contextReason
    end
    if not SovereignTaskRequestScriptHost(scriptName) then
        return false, "Doomsday mission host is unavailable"
    end
    -- Host acquisition can yield while the mission changes or exits. The
    -- second context check is intentionally kept, but the old external
    -- NETWORK_GET_HOST_OF_SCRIPT == PLAYER_ID check is removed: it can lag
    -- behind ExecuteAsScript even after the host request has succeeded.
    contextOk, contextReason = SovereignTaskDoomsdayContext(true)
    if not contextOk then
        Logger:Warn("SovereignTask", "Doomsday finish changed during host request: " .. tostring(contextReason))
        return false, contextReason
    end

    local fields = {
        {base + 1740 + 1, 150},
        {32785 + 1 + 68, 99999},
        {base + 1725 + 1, 80},
    }
    -- The legacy profile cannot resolve 8413 safely, but the verified
    -- Enhanced profile still consumes it as the finale payout counter.
    if SovereignTaskEditionName() == "Enhanced" then
        fields[#fields + 1] = {8413, 99999}
    end
    fields[#fields + 1] = {base, 12}
    if not SovereignTaskSetLocalBatch(scriptName, fields, true) then
        return false, "Doomsday controller rejected the completion write"
    end
    for _, field in ipairs(fields) do
        if SovereignTaskGetLocal(scriptName, field[1]) ~= field[2] then
            return false, "Doomsday completion writeback was not confirmed"
        end
    end
    return true, "Doomsday ACT I/II/III finale completion requested. Please wait for the results."
end

