    -- Tools: deduplicated utility features
    {
        hash = Utils.Joaat("task_tool_solo_heist"), name = "Allow solo heists", taskPage = "tools", taskGroup = "heist",
        type = eFeatureType.Toggle, desc = "Enable before entering the mission lobby and keep enabled until the mission ends.", cb = function(f)
            SovereignTaskNoticeOnce("solo_heist", "Mission tools", "Enable before entering the mission lobby and keep enabled until the mission ends.")
            SovereignTaskSoloRuntime:Reset()
            local diag = {launcher = false, controller = false, noticedLauncher = false, noticedController = false}
            local ok = pcall(function()
                while f:IsToggled() do
                    diag.launcher = SovereignTaskApplySoloLauncherGlobals()
                    diag.controller = SovereignTaskApplySoloControllerState()
                    if diag.launcher ~= true and not diag.noticedLauncher then
