        type = eFeatureType.Button, desc = "Skip the current objective if the mission gets stuck.", cb = function() SovereignTaskSkipObjective() end
    },
    {
        hash = Utils.Joaat("task_tool_kill_nearby_npc"), name = "Eliminate nearby NPCs", taskPage = "tools", taskGroup = "npc",
        type = eFeatureType.Button, desc = "Only affects nearby naturally spawned non-player peds.", cb = function()
            local count = SovereignTaskForNearbyNpc(function(ped)
                menu.nativeApis.ENTITY.SET_ENTITY_HEALTH(ped, 0, 0, 5)
                return true
            end)
            SovereignTaskToast("Mission tools", "Processed " .. tostring(count) .. " NPCs")
        end
    },
    {
        hash = Utils.Joaat("task_tool_delete_nearby_npc"), name = "Delete mission NPCs", taskPage = "tools", taskGroup = "npc",
        type = eFeatureType.Button, desc = "Remove nearby mission NPCs.", cb = function()
            local count = SovereignTaskForNearbyNpc(function(ped)
                if menu.nativeApis.NETWORK and menu.nativeApis.NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY and menu.nativeApis.NETWORK.SET_NETWORK_ID_CAN_MIGRATE then
                    local okNet, netId = pcall(menu.nativeApis.NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY, ped)
                    if okNet and type(netId) == "number" and netId ~= 0 then
                        pcall(menu.nativeApis.NETWORK.SET_NETWORK_ID_CAN_MIGRATE, netId, true)
                    end
                end
                for _ = 1, 20 do
                    local hasControl = not menu.nativeApis.NETWORK or not menu.nativeApis.NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY
                    if not hasControl then
                        local okControl, result = pcall(menu.nativeApis.NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY, ped)
                        hasControl = okControl and result == true
                    end
                    if hasControl then break end
                    if GTA and GTA.GiveControl and menu.nativeApis.PLAYER and menu.nativeApis.PLAYER.PLAYER_ID then
                        pcall(GTA.GiveControl, menu.nativeApis.PLAYER.PLAYER_ID(), ped)
                    elseif menu.nativeApis.NETWORK and menu.nativeApis.NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY then
                        pcall(menu.nativeApis.NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY, ped)
                    end
                    Script.Yield(0)
                end
                if menu.nativeApis.ENTITY.SET_ENTITY_AS_MISSION_ENTITY then
                    pcall(menu.nativeApis.ENTITY.SET_ENTITY_AS_MISSION_ENTITY, ped, true, true)
                end
                EntityManager:DeleteEntity(ped)
                if menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(ped) then
                    pcall(menu.nativeApis.ENTITY.SET_ENTITY_COORDS_NO_OFFSET, ped, -8271.156, -1293.2153, -200.0, false, false, false)
                    if menu.nativeApis.ENTITY.SET_ENTITY_ALPHA then pcall(menu.nativeApis.ENTITY.SET_ENTITY_ALPHA, ped, 0, false) end
                end
                return true
            end)
            SovereignTaskToast("Mission tools", "Deleted " .. tostring(count) .. " NPCs")
        end
    },
    {
        hash = Utils.Joaat("task_tool_remove_npc_weapons"), name = "Remove NPC weapons", taskPage = "tools", taskGroup = "npc",
        type = eFeatureType.Button, desc = "Remove nearby NPC weapons without deleting the NPCs.", cb = function()
            local count = SovereignTaskForNearbyNpc(function(ped)
                menu.nativeApis.WEAPON.REMOVE_ALL_PED_WEAPONS(ped, true)
                return true
