    {
        hash = Utils.Joaat("task_tool_ignore_npc"), name = "NPCs ignore me", taskPage = "tools", taskGroup = "npc",
        type = eFeatureType.Toggle, desc = "Make hostile NPCs temporarily ignore the local player.", cb = function(f)
            while f:IsToggled() do
