                Script.Yield(10)
            end
            menu.nativeApis.PLAYER.SET_EVERYONE_IGNORE_PLAYER(menu.nativeApis.PLAYER.PLAYER_ID(), false)
        end
    },
    {
        hash = Utils.Joaat("task_tool_delete_cameras"), name = "Delete mission cameras", taskPage = "tools", taskGroup = "world",
        type = eFeatureType.Button, desc = "Remove loaded surveillance cameras in Casino, Cayo Perico, Doomsday and other missions.", cb = function()
            local models = {"prop_cctv_cam_01a", "prop_cctv_cam_01b", "prop_cctv_cam_02a", "prop_cctv_cam_03a", "prop_cctv_cam_04a", "prop_cctv_cam_04c", "prop_cctv_cam_05a", "prop_cctv_cam_06a", "prop_cctv_cam_07a", "prop_cs_cctv", "p_cctv_s", "hei_prop_bank_cctv_01", "hei_prop_bank_cctv_02", "ch_prop_ch_cctv_cam_01a", "ch_prop_ch_cctv_cam_02a", "xm_prop_x17_server_farm_cctv_01", "ba_prop_battle_cctv_cam_01a", "ba_prop_battle_cctv_cam_01b", "prop_dest_cctv_01", "prop_dest_cctv_03b", "prop_cctv_01_sm_02", "h4_prop_h4_sign_cctv_01a", "h4_prop_h4_cctv_pole_04"}
            if SovereignTaskState.cameraRemovalPending then return end
            SovereignTaskState.cameraRemovalPending = true
            local ok = pcall(function()
                local entity, network = menu.nativeApis.ENTITY, menu.nativeApis.NETWORK or {}
                local usePointers = PoolMgr and type(PoolMgr.GetCObject) == "function"
                    and GTA and type(GTA.PointerToHandle) == "function"
                local getter = PoolMgr and (usePointers and PoolMgr.GetCObject or PoolMgr.GetObject)
                if not PoolMgr or type(PoolMgr.GetMaxObjectCount) ~= "function" or type(getter) ~= "function"
                    or not entity or type(entity.DOES_ENTITY_EXIST) ~= "function" or type(entity.GET_ENTITY_MODEL) ~= "function"
                    or not EntityManager or type(EntityManager.DeleteEntity) ~= "function" then
                    SovereignTaskToast("Mission tools", "Camera scan is unavailable in this runtime.", "warning")
                    return
                end
                local modelSet, cameras, seen = {}, {}, {}
                for _, model in ipairs(models) do modelSet[Utils.Joaat(model) & 0xFFFFFFFF] = true end
                local function matches(item)
                    local success, value = pcall(function()
                        return entity.DOES_ENTITY_EXIST(item.handle)
                            and (entity.GET_ENTITY_MODEL(item.handle) & 0xFFFFFFFF) == item.model
                    end)
                    return success and value == true
                end
                local maxCount = PoolMgr.GetMaxObjectCount()
                if type(maxCount) ~= "number" or maxCount < 0 or maxCount > 100000
                    or maxCount ~= math.floor(maxCount) then error("Invalid object pool size") end
                for index = 0, maxCount - 1 do
                    local got, object = pcall(getter, index)
                    if got and object and object ~= 0 and object ~= -1 then
                        local handle = object
                        if usePointers then
                            local converted, value = pcall(GTA.PointerToHandle, object)
                            handle = converted and value or nil
                        end
                        if type(handle) == "number" and handle > 0 and not seen[handle] then
                            local valid, model = pcall(function()
                                if entity.DOES_ENTITY_EXIST(handle) then return entity.GET_ENTITY_MODEL(handle) end
                            end)
                            if valid and type(model) == "number" and modelSet[model & 0xFFFFFFFF] then
                                seen[handle] = true
                                cameras[#cameras + 1] = {handle = handle, model = model & 0xFFFFFFFF}
                            end
                        end
                    end
                    if index % 32 == 0 then Script.Yield(0) end
                end
                if #cameras == 0 then
                    SovereignTaskToast("Mission tools", "No loaded surveillance cameras found nearby.", "info")
                    return
                end
                -- Request control in parallel passes, rather than blocking once per object.
                -- Never teleport cameras away or count a successful native call as deletion.
                local removed, unavailable = 0, 0
                for pass = 1, 20 do
                    local pending = 0
                    for _, item in ipairs(cameras) do
                        if not item.done then
                            if not matches(item) then
                                item.done = true
                                unavailable = unavailable + 1
                            else
                                local control = false
                                if type(network.NETWORK_GET_ENTITY_IS_NETWORKED) == "function" then
                                    local checked, networked = pcall(network.NETWORK_GET_ENTITY_IS_NETWORKED, item.handle)
                                    control = checked and networked == false
                                end
                                if not control and type(network.NETWORK_HAS_CONTROL_OF_ENTITY) == "function" then
                                    local checked, owned = pcall(network.NETWORK_HAS_CONTROL_OF_ENTITY, item.handle)
                                    control = checked and owned == true
                                end
                                if control then
                                    if type(entity.SET_ENTITY_AS_MISSION_ENTITY) == "function" then
                                        pcall(entity.SET_ENTITY_AS_MISSION_ENTITY, item.handle, true, true)
                                    end
                                    pcall(EntityManager.DeleteEntity, EntityManager, item.handle)
                                    local checked, exists = pcall(entity.DOES_ENTITY_EXIST, item.handle)
                                    if checked and exists == false then
                                        item.done = true
                                        removed = removed + 1
                                    end
                                elseif type(network.NETWORK_REQUEST_CONTROL_OF_ENTITY) == "function" then
                                    pcall(network.NETWORK_REQUEST_CONTROL_OF_ENTITY, item.handle)
                                end
                                if not item.done then pending = pending + 1 end
                            end
                        end
                    end
                    if pending == 0 then break end
                    Script.Yield(0)
                end
                local remaining = #cameras - removed - unavailable
                SovereignTaskToast("Mission tools", string.format("Cameras: %d removed, %d unavailable, %d still present.",
                    removed, unavailable, remaining), remaining > 0 and "warning" or "info")
            end)
            SovereignTaskState.cameraRemovalPending = nil
            if not ok then
                SovereignTaskToast("Mission tools", "Camera removal was interrupted. Move closer and try again.", "warning")
            end
        end
    },
    {
        hash = Utils.Joaat("task_tool_clear_help"), name = "Clear mission hints", taskPage = "tools", taskGroup = "world",
        type = eFeatureType.Button, desc = "Clear mission help text in the top-left corner.", cb = function() menu.nativeApis.HUD.CLEAR_ALL_HELP_MESSAGES() end
    },
}

