SovereignTaskSetPackedBoolRange = function(firstIndex, lastIndex)
    if not menu.nativeApis.STATS or type(menu.nativeApis.STATS.SET_PACKED_STAT_BOOL_CODE) ~= "function" then
        return false
    end
    for index = math.floor(tonumber(firstIndex) or 0), math.floor(tonumber(lastIndex) or 0) do
        pcall(menu.nativeApis.STATS.SET_PACKED_STAT_BOOL_CODE, index, true, -1)
    end
    return true
end

