local SovereignTaskTunablePointerCache = {}
local SovereignTaskTunableToggleOwners = {}
local function SovereignTaskTunablePointerByHash(hash, asFloat)
    if not ScriptGlobal or type(ScriptGlobal.GetTunableByHash) ~= "function" or not Memory then
        return nil
    end
    hash = tonumber(hash)
    if not hash or hash ~= hash or hash ~= math.floor(hash) then return nil end
    local knownKind = SovereignTaskLegacyExactTunableKinds[hash]
        or SovereignTaskLegacyExactTunableKinds[tostring(hash)]
    if knownKind and ((knownKind == "float") ~= (asFloat == true)) then
        SovereignTaskNoticeOnce("tunable_type_" .. tostring(hash), "Mission tunables",
            "Mission parameter type mismatch; action skipped.")
        return nil
    end
    if SovereignTaskEditionName() == "Legacy" then
        if not SovereignTaskLegacyTunableKind(hash) then
            SovereignTaskNoticeOnce("legacy_tunable_" .. tostring(hash), "Legacy missions",
                "This setting is currently unavailable for this game version.")
            return nil
        end
    end
    local cached = SovereignTaskTunablePointerCache[hash]
    if type(cached) == "number" and cached ~= 0 then return cached end
    local ok, ptr = pcall(ScriptGlobal.GetTunableByHash, hash)
    if not ok or type(ptr) ~= "number" or ptr == 0 or not Memory then
        return nil
    end
    SovereignTaskTunablePointerCache[hash] = ptr
    return ptr
end

SovereignTaskSetTunableByHash = function(hash, value, asFloat)
    local ptr = SovereignTaskTunablePointerByHash(hash, asFloat)
    if not ptr then return false end
    if asFloat and type(Memory.WriteFloat) == "function" then
        return SovereignTaskCall("SovereignTask.TunableFloat", Memory.WriteFloat, ptr, tonumber(value) or 0.0)
    end
    if type(Memory.WriteInt) == "function" then
        return SovereignTaskCall("SovereignTask.TunableInt", Memory.WriteInt, ptr, math.floor(tonumber(value) or 0))
    end
    return false
end

SovereignTaskGetTunableByHash = function(hash, asFloat)
    local ptr = SovereignTaskTunablePointerByHash(hash, asFloat)
    if not ptr then return nil end
    local reader = asFloat and Memory.ReadFloat or Memory.ReadInt
    if type(reader) ~= "function" then return nil end
    local ok, value = pcall(reader, ptr)
    value = ok and tonumber(value) or nil
    return value and value == value and value or nil
end

local function SovereignTaskTunableHash(value)
    if type(value) == "number" then return value end
    if type(value) ~= "string" or not Utils or type(Utils.Joaat) ~= "function" then return nil end
    local ok, hash = pcall(Utils.Joaat, value)
    return ok and type(hash) == "number" and hash or nil
end

SovereignTaskCaptureTunables = function(definitions)
    local snapshots = {}
    for _, definition in ipairs(definitions or {}) do
        local hash = SovereignTaskTunableHash(definition[1])
        local asFloat = definition[2] == true
        if hash then
            local value = SovereignTaskGetTunableByHash(hash, asFloat)
            if value == nil then value = definition[3] end
            if type(value) == "number" then
                snapshots[#snapshots + 1] = {hash = hash, asFloat = asFloat, value = value}
            end
        end
    end
    return snapshots
end

SovereignTaskRestoreTunables = function(snapshots)
    local restored = true
    for _, snapshot in ipairs(snapshots or {}) do
        restored = SovereignTaskSetTunableByHash(snapshot.hash, snapshot.value, snapshot.asFloat) and restored
    end
    return restored
end

local function SovereignTaskTunableToggleTraceback(message)
    if debug and type(debug.traceback) == "function" then
        return debug.traceback(tostring(message), 2)
    end
    return tostring(message)
end

SovereignTaskRunRestoringTunableToggle = function(key, feature, definitions, apply, yieldMilliseconds)
    if type(key) ~= "string" or key == "" then
        error("persistent Tunable toggle requires a non-empty key", 2)
    end
    if SovereignTaskTunableToggleOwners[key] ~= nil then return false end
    if not feature:IsToggled() then return false end

    local owner = {}
    SovereignTaskTunableToggleOwners[key] = owner
    local originals = {}
    local runOk, runError = xpcall(function()
        originals = SovereignTaskCaptureTunables(definitions)
        while feature:IsToggled() do
            apply()
            Script.Yield(yieldMilliseconds or 100)
        end
    end, SovereignTaskTunableToggleTraceback)
    local restoreOk, restoreResult = xpcall(function()
        return SovereignTaskRestoreTunables(originals)
    end, SovereignTaskTunableToggleTraceback)

    if SovereignTaskTunableToggleOwners[key] == owner then
        SovereignTaskTunableToggleOwners[key] = nil
    end
    if not restoreOk then
        local message = "persistent Tunable restore failed for " .. key .. ": " .. tostring(restoreResult)
        if not runOk then message = tostring(runError) .. "\n" .. message end
        error(message, 0)
    end
    if restoreResult == false then
        local message = "persistent Tunable restore returned false for " .. key
        if not runOk then message = tostring(runError) .. "\n" .. message end
        error(message, 0)
    end
    if not runOk then error(runError, 0) end
    return true
end

