SovereignTaskRegisterPrepChoices = function()
local function SovereignTaskAddPrepChoice(definition, taskPage, taskGroup)
    MenuDefinitions.ExtendedItems.Tasks[#MenuDefinitions.ExtendedItems.Tasks + 1] = {
        hash = Utils.Joaat(definition.id), name = definition.name, taskPage = taskPage, taskGroup = taskGroup,
        type = eFeatureType.Combo, desc = definition.desc or "Choose how to handle this preparation mission.", list = SovereignTaskPrepChoices, defaultValue = 0,
        cb = function(f)
            local choice = tonumber(f:GetListIndex()) or 0
            local ok
            if choice < 0 or choice > 2 then
                ok = false
            elseif definition.kind == "classic" then
                ok = SovereignTaskApplyClassicPrepChoice(definition, choice)
            elseif definition.kind == "kortz" then
                ok = SovereignTaskApplyKortzPrepChoice(definition, choice)
            elseif definition.kind == "doomsday" then
                ok = choice == 0 and true or SovereignTaskSetDoomsdayPrepBit(definition.bit, choice == 1)
            elseif definition.kind == "bitstat" then
                ok = choice == 0 and true or SovereignTaskSetStatBit(definition.stat, definition.bit, choice == 1)
            else
                ok = choice == 0 and true or SovereignTaskSetPrepStatVerified(
                    definition.stat, choice == 1 and definition.done or definition.reset
                )
            end
            if ok and choice ~= 0 then
                ok = SovereignTaskRefreshPrepBoard(definition, choice)
            end
            if choice ~= 0 then
                SovereignTaskToast(definition.title or "Mission preparations", ok and (choice == 1 and "Marked complete" or "Set to replay") or "State update failed", ok and nil or "error")
            end
        end
    }
end

local function SovereignTaskAddPrepReset(id, name, taskPage, taskGroup, definitions, handler)
    MenuDefinitions.ExtendedItems.Tasks[#MenuDefinitions.ExtendedItems.Tasks + 1] = {
        hash = Utils.Joaat(id), name = name, taskPage = taskPage, taskGroup = taskGroup,
        type = eFeatureType.Button, desc = "Reset this preparation group to incomplete so it can be replayed.", cb = function()
            local changed = 0
            if handler then
                changed = handler(definitions)
            else
                for _, definition in ipairs(definitions) do
                    if definition.kind == "bitstat" then
                        if SovereignTaskSetStatBit(definition.stat, definition.bit, false) then changed = changed + 1 end
                    elseif definition.kind == "doomsday" then
                        if SovereignTaskSetDoomsdayPrepBit(definition.bit, false) then changed = changed + 1 end
                    elseif SovereignTaskSetStat(definition.stat, definition.reset or 0) then
                        changed = changed + 1
                    end
                end
            end
            SovereignTaskSaveStats()
            SovereignTaskToast(name, "Reset " .. tostring(changed) .. " preparations")
        end
    }
end

