SovereignTaskStartScript = function(scriptName, stackSize)
    scriptName = tostring(scriptName or "")
    stackSize = math.max(5000, math.floor(tonumber(stackSize) or 5000))
    if scriptName == "" or not menu.nativeApis.SCRIPT or type(menu.nativeApis.SCRIPT.REQUEST_SCRIPT) ~= "function"
        or type(menu.nativeApis.SCRIPT.HAS_SCRIPT_LOADED) ~= "function" or type(menu.nativeApis.SCRIPT.SET_SCRIPT_AS_NO_LONGER_NEEDED) ~= "function"
        or not menu.nativeApis.SYSTEM or type(menu.nativeApis.SYSTEM.START_NEW_SCRIPT) ~= "function"
    then
        SovereignTaskToast("Remote Terminal", "Cannot open the terminal right now", "warning")
        return false
    end

    if menu.nativeApis.HUD and type(menu.nativeApis.HUD.IS_PAUSE_MENU_ACTIVE) == "function" then
        local okPause, pauseActive = pcall(menu.nativeApis.HUD.IS_PAUSE_MENU_ACTIVE)
        if okPause and pauseActive then
            SovereignTaskToast("Remote Terminal", "Close the pause menu before opening a remote terminal", "warning")
            return false
        end
    end

    if type(menu.nativeApis.SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH) == "function" then
        local okThreads, threads = pcall(menu.nativeApis.SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH, Utils.Joaat(scriptName))
        if okThreads and type(threads) == "number" and threads > 0 then
            SovereignTaskToast("Remote Terminal", "This terminal is already open")
            return true
        end
    end

    local okRequest = pcall(menu.nativeApis.SCRIPT.REQUEST_SCRIPT, scriptName)
    if not okRequest then
        SovereignTaskToast("Remote Terminal", "Terminal temporarily unavailable", "warning")
        return false
    end

    local loaded = false
    for attempt = 1, 500 do
        local okLoaded, result = pcall(menu.nativeApis.SCRIPT.HAS_SCRIPT_LOADED, scriptName)
        if okLoaded and result then
            loaded = true
            break
        end
        if attempt % 50 == 0 then
            pcall(menu.nativeApis.SCRIPT.REQUEST_SCRIPT, scriptName)
        end
        Script.Yield(10)
    end

    if not loaded then
        pcall(menu.nativeApis.SCRIPT.SET_SCRIPT_AS_NO_LONGER_NEEDED, scriptName)
        SovereignTaskToast("Remote Terminal", "Terminal loading timed out", "warning")
        return false
    end

    local okStart, threadId = pcall(menu.nativeApis.SYSTEM.START_NEW_SCRIPT, scriptName, stackSize)
    pcall(menu.nativeApis.SCRIPT.SET_SCRIPT_AS_NO_LONGER_NEEDED, scriptName)
    if not okStart or type(threadId) ~= "number" or threadId <= 0 then
        SovereignTaskToast("Remote Terminal", "Failed to open terminal", "warning")
        return false
    end
    return true
end
