-- Stone Hatchet Rampage is owned by freemode, not by the generic ability meter.
-- Paired Enhanced func_22120 / Legacy func_21437 read f_2 as a duration and
-- f_3/f_4 as its network-clock stopwatch. A fixed 99999 ms duration still expires.
-- Refresh only the stopwatch of an already active ability. Do not synthesize
-- activation, alter shared player flags, or overwrite damage/healing tunables.
local SovereignTaskStoneHatchetRuntime = {owner = nil, status = "idle"}
function SovereignTaskStoneHatchetRuntime:Step()
    local apis = menu.nativeApis or {}
    local player, network = apis.PLAYER or {}, apis.NETWORK or {}
    local entity, weapon = apis.ENTITY or {}, apis.WEAPON or {}
    if type(player.PLAYER_ID) ~= "function" or type(player.PLAYER_PED_ID) ~= "function"
        or type(player.IS_PLAYER_PLAYING) ~= "function"
        or type(network.NETWORK_IS_GAME_IN_PROGRESS) ~= "function"
        or type(network.GET_NETWORK_TIME) ~= "function" or type(network.GET_TIME_DIFFERENCE) ~= "function"
        or type(entity.DOES_ENTITY_EXIST) ~= "function" or type(entity.IS_ENTITY_DEAD) ~= "function"
        or type(weapon.GET_SELECTED_PED_WEAPON) ~= "function"
        or not ScriptLocal or type(ScriptLocal.GetInt) ~= "function" or type(ScriptLocal.SetInt) ~= "function"
        or not ScriptGlobal or type(ScriptGlobal.GetInt) ~= "function" then
        return false, "Stone Hatchet support is unavailable in this Lua runtime."
    end
    if network.NETWORK_IS_GAME_IN_PROGRESS() ~= true or not SovereignTaskIsScriptRunning("freemode") then
        return true, "waiting_session"
    end
    for _, name in ipairs({"NETWORK_IS_IN_TRANSITION", "NETWORK_IS_ACTIVITY_SESSION", "NETWORK_IS_IN_MP_CUTSCENE"}) do
        if type(network[name]) == "function" and network[name]() == true then return true, "waiting_session" end
    end
    for _, name in ipairs({"fmmc_launcher", "fm_mission_controller", "fm_mission_controller_2020", "fm_mission_controller_v3"}) do
        if SovereignTaskIsScriptRunning(name) then return true, "waiting_session" end
    end
    local pid = player.PLAYER_ID()
    if not SovereignTaskValidPlayerId(pid) or player.IS_PLAYER_PLAYING(pid) ~= true then return true, "waiting_player" end
    local ped = player.PLAYER_PED_ID()
    if type(ped) ~= "number" or ped == 0 or entity.DOES_ENTITY_EXIST(ped) ~= true
        or entity.IS_ENTITY_DEAD(ped, false) == true then return true, "waiting_player" end
    if type(player.IS_PLAYER_CONTROL_ON) == "function" and player.IS_PLAYER_CONTROL_ON(pid) ~= true then
        return true, "waiting_player"
    end
    local selected = weapon.GET_SELECTED_PED_WEAPON(ped)
    if type(selected) ~= "number" or selected ~= math.floor(selected) then return true, "waiting_weapon" end
    local hatchet, unarmed = Utils.Joaat("weapon_stone_hatchet") & 0xFFFFFFFF, Utils.Joaat("weapon_unarmed") & 0xFFFFFFFF
    selected = selected & 0xFFFFFFFF
    if selected ~= hatchet and selected ~= unarmed then return true, "waiting_weapon" end
    local flagIndex = 1893070 + 1 + pid * 615 + 16
    local flags = SovereignTaskGetGlobal(flagIndex)
    local duration = SovereignTaskGetLocal("freemode", 15814)
    local initialized = SovereignTaskGetLocal("freemode", 15816)
    local cooldown = SovereignTaskGetLocal("freemode", 15818)
    if type(flags) ~= "number" or flags ~= math.floor(flags) or flags < -2147483648 or flags > 4294967295
        or type(duration) ~= "number" or duration ~= math.floor(duration) or duration < 0 or duration > 600000
        or (initialized ~= 0 and initialized ~= 1) or (cooldown ~= 0 and cooldown ~= 1) then
        return false, "Stone Hatchet state is unavailable for this game build."
    end
    local active = (flags & (1 << 2)) ~= 0
    local nativeActive
    if type(player.IS_SPECIAL_ABILITY_ACTIVE) == "function" then
        local nativeOk, nativeValue = pcall(player.IS_SPECIAL_ABILITY_ACTIVE, pid, 0)
        if nativeOk and type(nativeValue) == "boolean" then nativeActive = nativeValue end
    end
    if not active then
        -- Skip only this ability's existing cooldown, not an unrelated ability.
        -- There is no stale cooldown snapshot to reapply to a later session.
        if nativeActive == false and selected == hatchet and cooldown == 1 and duration > 0 then
            if not SovereignTaskSetLocal("freemode", 15818, 0)
                or SovereignTaskGetLocal("freemode", 15818) ~= 0 then
                return false, "Stone Hatchet cooldown update failed. Toggle the option on again."
            end
            return true, "waiting_activation"
        end
        return true, "waiting_activation"
    end
    -- The freemode active bit is authoritative. Its stopwatch is initialized
    -- lazily on the next tick, so a native meter read cannot suppress refresh.
    if initialized ~= 1 or duration == 0 then return true, "waiting_activation" end
    local stamp = SovereignTaskGetLocal("freemode", 15815)
    local now = network.GET_NETWORK_TIME()
    if type(stamp) ~= "number" or stamp ~= math.floor(stamp) or stamp < -2147483648 or stamp > 4294967295
        or type(now) ~= "number" or now ~= math.floor(now) or now < -2147483648 or now > 4294967295 then
        return false, "Stone Hatchet timer is unavailable for this game build."
    end
    -- Normalize the native integer to a signed 32-bit script-local value.
    now = now & 0xFFFFFFFF
    if now >= 0x80000000 then now = now - 0x100000000 end
    local elapsed = network.GET_TIME_DIFFERENCE(now, stamp)
    if type(elapsed) ~= "number" or elapsed ~= math.floor(elapsed)
        or elapsed < 0 or elapsed > 2147483647 then return true, "waiting_clock" end
    if elapsed < 100 then return true, "maintaining" end
    -- Recheck immediately before the only active-state write. Never copy an old
    -- stopwatch into a new activation, player, or session after a state change.
    local currentFlags = SovereignTaskGetGlobal(flagIndex)
    if type(currentFlags) ~= "number" or currentFlags ~= math.floor(currentFlags)
        or (currentFlags & (1 << 2)) == 0
        or SovereignTaskGetLocal("freemode", 15816) ~= 1
        or SovereignTaskGetLocal("freemode", 15815) ~= stamp then return true, "waiting_activation" end
    if not SovereignTaskSetLocal("freemode", 15815, now)
        or SovereignTaskGetLocal("freemode", 15815) ~= now then
        return false, "Stone Hatchet timer update failed. Toggle the option on again."
    end
    return true, "maintaining"
end

function SovereignTaskStoneHatchetRuntime:Run(feature)
    if self.owner ~= nil or not feature:IsToggled() then return false end
    local owner, failure = {}, nil
    self.owner = owner
    local ok = pcall(function()
        SovereignTaskToast("Stone Hatchet", "Trigger Stone Hatchet Rampage normally in freemode; this option keeps it active until disabled.", "info")
        while feature:IsToggled() and self.owner == owner do
            local applied, reason = self:Step()
            self.status = applied and reason or "error"
            if not applied then failure = reason; break end
            Script.Yield(100)
        end
    end)
    if self.owner == owner then self.owner = nil end
    -- A skipped cooldown stays skipped, like an elapsed cooldown. The next
    -- ability end starts a new game-owned cooldown; never restore a stale flag.
    -- No tunables, activation flags or modifiers were changed. Stopping refresh
    -- lets the original game timer count down normally; never restore old clocks.
    if not ok or failure then
        self.status = "error"
        if type(feature.SetToggledSilently) == "function" then pcall(feature.SetToggledSilently, feature, false) end
        SovereignTaskToast("Stone Hatchet", failure or "Stone Hatchet maintenance stopped after a runtime error. Toggle the option on again.", "warning")
        return false
    end
    self.status = "idle"
    return true
end

