function ImportedExtensionOptions:Now()
    return Utils1:NowSeconds()
end

function ImportedExtensionOptions:StopNinjaRun()
    local s, api = self.ninjaRun, menu.nativeApis
    if s.active and s.ped ~= 0 and api.TASK and api.TASK.STOP_ANIM_TASK then
        local valid = true
        if api.ENTITY and api.ENTITY.DOES_ENTITY_EXIST then
            local ok, exists = pcall(api.ENTITY.DOES_ENTITY_EXIST, s.ped)
            valid = ok and exists == true
        end
        if valid then pcall(api.TASK.STOP_ANIM_TASK, s.ped, "swimming@scuba", "dive_glide", -3.0) end
    end
    s.ped, s.active = 0, false
end

function ImportedExtensionOptions:SetNinjaRun(enabled)
    local s = self.ninjaRun
    s.enabled = enabled == true
    if not s.enabled then
        self:StopNinjaRun()
        local streaming = menu.nativeApis.STREAMING
        if s.requested and streaming and streaming.REMOVE_ANIM_DICT then
            pcall(streaming.REMOVE_ANIM_DICT, "swimming@scuba")
        end
        s.requested, s.nextRequest, s.nextPlay = false, 0, 0
    end
end

function ImportedExtensionOptions:ProcessNinjaRun()
    local s, api = self.ninjaRun, menu.nativeApis
    if not s.enabled then return end
    local ped = self:GetLocalPed()
    if s.ped ~= 0 and s.ped ~= ped then self:StopNinjaRun() end
    local function yes(namespace, name, ...)
        local fn = api[namespace] and api[namespace][name]
        if type(fn) ~= "function" then return false end
        local ok, value = pcall(fn, ...)
        return ok and value == true
    end
    local player = -1
    if api.PLAYER and type(api.PLAYER.PLAYER_ID) == "function" then
        local playerOk, playerValue = pcall(api.PLAYER.PLAYER_ID)
        if playerOk and type(playerValue) == "number" then player = playerValue end
    end
    local blocked = ped == 0 or menu.interactive or self.crawl or self.ball.enabled or self.swordFly.enabled
        or yes("ENTITY", "IS_ENTITY_DEAD", ped, false)
        or yes("PED", "IS_PED_IN_ANY_VEHICLE", ped, true)
        or yes("PED", "IS_PED_GETTING_INTO_A_VEHICLE", ped)
        or yes("PED", "IS_PED_RAGDOLL", ped) or yes("PED", "IS_PED_FALLING", ped)
        or yes("PED", "IS_PED_JUMPING", ped) or yes("PED", "IS_PED_CLIMBING", ped)
        or yes("PED", "IS_PED_SWIMMING", ped) or yes("PED", "IS_PED_SWIMMING_UNDER_WATER", ped)
        or yes("PED", "IS_PED_RELOADING", ped) or yes("PED", "IS_PED_SWITCHING_WEAPON", ped)
        or yes("PLAYER", "IS_PLAYER_FREE_AIMING", player)
        or yes("PAD", "IS_CONTROL_PRESSED", 0, 24) or yes("PAD", "IS_CONTROL_PRESSED", 0, 25)
        or yes("TASK", "GET_IS_TASK_ACTIVE", ped, 56) or yes("TASK", "GET_IS_TASK_ACTIVE", ped, 290)
    if blocked or not yes("TASK", "IS_PED_SPRINTING", ped) then self:StopNinjaRun(); return end
    local now, streaming, task = self:Now(), api.STREAMING, api.TASK
    if not streaming or not task or not task.TASK_PLAY_ANIM then return end
    if not yes("STREAMING", "HAS_ANIM_DICT_LOADED", "swimming@scuba") then
        if now >= s.nextRequest and streaming.REQUEST_ANIM_DICT then
            s.requested = pcall(streaming.REQUEST_ANIM_DICT, "swimming@scuba")
            s.nextRequest = now + 1.0
        end
        return
    end
    if yes("ENTITY", "IS_ENTITY_PLAYING_ANIM", ped, "swimming@scuba", "dive_glide", 3) then return end
    if now < s.nextPlay then return end
    s.nextPlay = now + 0.5
    local ok, result = pcall(task.TASK_PLAY_ANIM, ped, "swimming@scuba", "dive_glide",
        5.0, 2.5, -1, 49, 1.0, false, false, false)
    if ok and result ~= false then s.ped, s.active = ped, true end
end

function ImportedExtensionOptions:QueueTask(key, interval, callback)
    if not Script or not Script.QueueJob or type(callback) ~= "function" then
        return false
    end
    self.taskQueueState = self.taskQueueState or {}
    local state = self.taskQueueState[key]
    local now = self:Now()
    if state and (state.pending or now - (state.last or 0) < (interval or 0.25)) then
        return false
    end
    self.taskQueueState[key] = {pending = true, last = now}
    local queued = pcall(function()
        Script.QueueJob(function()
            pcall(callback)
            local current = self.taskQueueState and self.taskQueueState[key]
            if current then
                current.pending = false
                current.last = self:Now()
            end
        end)
    end)
    if not queued then
        self.taskQueueState[key].pending = false
        return false
    end
    return true
end

function ImportedExtensionOptions:PlayAnimQueued(key, ped, dict, anim, blendIn, blendOut, duration, flags, playbackRate, lockX, lockY, lockZ, interval)
    return self:QueueTask("anim:" .. key, interval or 0.75, function()
        if menu.nativeApis.TASK and menu.nativeApis.TASK.TASK_PLAY_ANIM and ped and ped ~= 0 then
            menu.nativeApis.TASK.TASK_PLAY_ANIM(ped, dict, anim, blendIn, blendOut, duration, flags, playbackRate, lockX, lockY, lockZ)
        end
    end)
end

function ImportedExtensionOptions:RunTaskQueued(key, interval, callback)
    return self:QueueTask("task:" .. key, interval or 0.25, callback)
end

function ImportedExtensionOptions:IsAudioNativeEnabled()
    return self.audioNativeSafe == true and menu.nativeApis.AUDIO ~= nil
end

function ImportedExtensionOptions:AudioCall(callback)
    if not self:IsAudioNativeEnabled() or type(callback) ~= "function" then return false end
    local ok, result = pcall(callback)
    if not ok then self.audioLastError = tostring(result) end
    -- A single unavailable native must not permanently turn off all audio categories.
    return ok and result ~= false
end

function ImportedExtensionOptions:GetLocalPed()
    if menu.nativeApis.PLAYER and menu.nativeApis.PLAYER.PLAYER_PED_ID then
        local ok, ped = pcall(function()
            return menu.nativeApis.PLAYER.PLAYER_PED_ID()
        end)
        if ok and ped and ped ~= 0 then
            return ped
        end
    end
    if GTA and GTA.GetLocalPed and GTA.PointerToHandle then
        local localPed = GTA.GetLocalPed()
        if localPed then
            return GTA.PointerToHandle(localPed)
        end
    end
    return 0
end

function ImportedExtensionOptions:IsEntityValid(entity)
    if not entity or entity == 0 then
        return false
    end
    local ok, exists = pcall(function()
        return menu.nativeApis.ENTITY and menu.nativeApis.ENTITY.DOES_ENTITY_EXIST and menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(entity)
    end)
    return ok and exists == true
end

function ImportedExtensionOptions:RequestAnimDict(dict)
    if not menu.nativeApis.STREAMING or not menu.nativeApis.STREAMING.REQUEST_ANIM_DICT or not menu.nativeApis.STREAMING.HAS_ANIM_DICT_LOADED then
        return false
    end
    menu.nativeApis.STREAMING.REQUEST_ANIM_DICT(dict)
    local timeout = self:Now() + 3.0
    while not menu.nativeApis.STREAMING.HAS_ANIM_DICT_LOADED(dict) do
        if self:Now() > timeout then
            return false
        end
        Script.Yield(0)
    end
    return true
end

function ImportedExtensionOptions:RequestClipSet(clipset)
    if not menu.nativeApis.STREAMING or not menu.nativeApis.STREAMING.REQUEST_CLIP_SET or not menu.nativeApis.STREAMING.HAS_CLIP_SET_LOADED then
        return false
    end
    menu.nativeApis.STREAMING.REQUEST_CLIP_SET(clipset)
    local timeout = self:Now() + 3.0
    while not menu.nativeApis.STREAMING.HAS_CLIP_SET_LOADED(clipset) do
        if self:Now() > timeout then
            return false
        end
        Script.Yield(0)
    end
    return true
end

function ImportedExtensionOptions:RequestPtfxAsset(asset)
    if not menu.nativeApis.STREAMING or not menu.nativeApis.STREAMING.REQUEST_NAMED_PTFX_ASSET or not menu.nativeApis.STREAMING.HAS_NAMED_PTFX_ASSET_LOADED then
        return false
    end
    menu.nativeApis.STREAMING.REQUEST_NAMED_PTFX_ASSET(asset)
    local timeout = self:Now() + 3.0
    while not menu.nativeApis.STREAMING.HAS_NAMED_PTFX_ASSET_LOADED(asset) do
        if self:Now() > timeout then
            return false
        end
        Script.Yield(0)
    end
    return true
end

function ImportedExtensionOptions:GetRunStyleNames()
    return Utils1:GetNameList(self.runClipsets)
end

function ImportedExtensionOptions:RotationToDirection(rot)
    local z = math.rad(rot.z or 0.0)
    local x = math.rad(rot.x or 0.0)
    local cosX = math.abs(math.cos(x))
    return {
        x = -math.sin(z) * cosX,
        y = math.cos(z) * cosX,
        z = math.sin(x)
    }
end

function ImportedExtensionOptions:ApplyRunStyle(index)
    local ped = self:GetLocalPed()
    if ped == 0 then return end
    pcall(function()
        if self.currentClipset then
            if menu.nativeApis.PED and menu.nativeApis.PED.RESET_PED_MOVEMENT_CLIPSET then
                menu.nativeApis.PED.RESET_PED_MOVEMENT_CLIPSET(ped, 0.5)
            end
            if menu.nativeApis.STREAMING and menu.nativeApis.STREAMING.REMOVE_CLIP_SET then
                menu.nativeApis.STREAMING.REMOVE_CLIP_SET(self.currentClipset)
            end
            self.currentClipset = nil
        end
    end)
    local data = self.runClipsets[(index or 0) + 1]
    if data and data.clipset and self:RequestClipSet(data.clipset) then
        pcall(function()
            menu.nativeApis.PED.SET_PED_MOVEMENT_CLIPSET(ped, data.clipset, 0.5)
            self.currentClipset = data.clipset
        end)
    end
end

function ImportedExtensionOptions:SetChristmasDecor(enabled)
    self.christmasDecor = enabled == true
    self.christmasDecorLast = 0
    self:ApplyChristmasDecor(true)
end

function ImportedExtensionOptions:ApplyChristmasDecor(force)
    local now = self:Now()
    if not force and now - (self.christmasDecorLast or 0) < 2.0 then
        return
    end
    self.christmasDecorLast = now
    local enabled = self.christmasDecor == true
    if ScriptGlobal and ScriptGlobal.SetInt then
        pcall(function()
            ScriptGlobal.SetInt(262145 + 9436, enabled and 0 or 1)
            ScriptGlobal.SetInt(262145 + 9437, enabled and 0 or 1)
        end)
    end
    pcall(function()
        if enabled then
            if menu.nativeApis.MISC and menu.nativeApis.MISC.SET_WEATHER_TYPE_NOW then
                menu.nativeApis.MISC.SET_WEATHER_TYPE_NOW("XMAS")
            end
            if menu.nativeApis.MISC and menu.nativeApis.MISC.SET_WEATHER_TYPE_PERSIST then
                menu.nativeApis.MISC.SET_WEATHER_TYPE_PERSIST("XMAS")
            elseif menu.nativeApis.MISC and menu.nativeApis.MISC.SET_OVERRIDE_WEATHER then
                menu.nativeApis.MISC.SET_OVERRIDE_WEATHER("XMAS")
            end
            if menu.nativeApis.MISC and menu.nativeApis.MISC.SET_FORCE_PED_FOOTSTEPS_TRACKS then
                menu.nativeApis.MISC.SET_FORCE_PED_FOOTSTEPS_TRACKS(true)
            end
            if menu.nativeApis.MISC and menu.nativeApis.MISC.SET_FORCE_VEHICLE_TRAILS then
                menu.nativeApis.MISC.SET_FORCE_VEHICLE_TRAILS(true)
            end
        else
            if menu.nativeApis.MISC and menu.nativeApis.MISC.CLEAR_WEATHER_TYPE_PERSIST then
                menu.nativeApis.MISC.CLEAR_WEATHER_TYPE_PERSIST()
            end
            if menu.nativeApis.MISC and menu.nativeApis.MISC.SET_FORCE_PED_FOOTSTEPS_TRACKS then
                menu.nativeApis.MISC.SET_FORCE_PED_FOOTSTEPS_TRACKS(false)
            end
            if menu.nativeApis.MISC and menu.nativeApis.MISC.SET_FORCE_VEHICLE_TRAILS then
                menu.nativeApis.MISC.SET_FORCE_VEHICLE_TRAILS(false)
            end
        end
    end)
end

function ImportedExtensionOptions:SetPowerOutage(enabled)
    self.powerOutage = enabled
    pcall(function()
        if menu.nativeApis.GRAPHICS and menu.nativeApis.GRAPHICS.SET_ARTIFICIAL_LIGHTS_STATE then
            menu.nativeApis.GRAPHICS.SET_ARTIFICIAL_LIGHTS_STATE(enabled or self.blackout)
        end
