    pcall(function()
        if menu.nativeApis.GRAPHICS and menu.nativeApis.GRAPHICS.SET_ARTIFICIAL_LIGHTS_STATE then
            menu.nativeApis.GRAPHICS.SET_ARTIFICIAL_LIGHTS_STATE(enabled or self.powerOutage)
        end
        if enabled then
            if menu.nativeApis.GRAPHICS and menu.nativeApis.GRAPHICS.SET_TIMECYCLE_MODIFIER then
                menu.nativeApis.GRAPHICS.SET_TIMECYCLE_MODIFIER("dlc_island_vault")
            end
        elseif menu.nativeApis.GRAPHICS and menu.nativeApis.GRAPHICS.CLEAR_TIMECYCLE_MODIFIER then
