function ImportedExtensionOptions:ProcessLaserEyes(ped)
    if not self.laserEyes or not menu.nativeApis.PAD or not menu.nativeApis.PED or not menu.nativeApis.GRAPHICS then return end
    pcall(function()
        if not menu.nativeApis.PAD.IS_CONTROL_PRESSED(0, 51) then return end
        local now = self:Now()
        if now - self.laserEyesLast < 0.05 then return end
        self.laserEyesLast = now
        local camRot = menu.nativeApis.CAM and menu.nativeApis.CAM.GET_FINAL_RENDERED_CAM_ROT and menu.nativeApis.CAM.GET_FINAL_RENDERED_CAM_ROT(2) or {x = 0.0, y = 0.0, z = menu.nativeApis.ENTITY.GET_ENTITY_HEADING(ped)}
        local _, target = self:GetCameraAim(1000.0)
        if not target then return end
        local pedModel = menu.nativeApis.ENTITY.GET_ENTITY_MODEL(ped)
        local leftEye = 5956
        local rightEye = 6468
        if pedModel == Utils.Joaat("mp_m_freemode_01") or pedModel == Utils.Joaat("mp_f_freemode_01") then
            leftEye = 25260
            rightEye = 27474
        end
        local left = menu.nativeApis.PED.GET_PED_BONE_COORDS(ped, leftEye, 0.0, 0.0, 0.0)
        local right = menu.nativeApis.PED.GET_PED_BONE_COORDS(ped, rightEye, 0.0, 0.0, 0.0)
        if pedModel == Utils.Joaat("mp_f_freemode_01") then
            left.z = left.z + 0.02
            right.z = right.z + 0.02
        end
        if menu.nativeApis.GRAPHICS.USE_PARTICLE_FX_ASSET then
            menu.nativeApis.GRAPHICS.USE_PARTICLE_FX_ASSET(self.laserEyesAsset)
        end
        local rx = (camRot.x or 0.0) - 90.0
        if menu.nativeApis.GRAPHICS.START_NETWORKED_PARTICLE_FX_NON_LOOPED_AT_COORD then
            menu.nativeApis.GRAPHICS.START_NETWORKED_PARTICLE_FX_NON_LOOPED_AT_COORD(self.laserEyesFx, left.x, left.y, left.z, rx, camRot.y or 0.0, camRot.z or 0.0, 2.0, false, false, false, false)
            menu.nativeApis.GRAPHICS.START_NETWORKED_PARTICLE_FX_NON_LOOPED_AT_COORD(self.laserEyesFx, right.x, right.y, right.z, rx, camRot.y or 0.0, camRot.z or 0.0, 2.0, false, false, false, false)
        elseif menu.nativeApis.GRAPHICS.START_PARTICLE_FX_NON_LOOPED_AT_COORD then
            menu.nativeApis.GRAPHICS.START_PARTICLE_FX_NON_LOOPED_AT_COORD(self.laserEyesFx, left.x, left.y, left.z, rx, camRot.y or 0.0, camRot.z or 0.0, 2.0, false, false, false)
            menu.nativeApis.GRAPHICS.START_PARTICLE_FX_NON_LOOPED_AT_COORD(self.laserEyesFx, right.x, right.y, right.z, rx, camRot.y or 0.0, camRot.z or 0.0, 2.0, false, false, false)
        end
        local weaponHash = Utils.Joaat("weapon_heavysniper_mk2")
        self:ShootLocalBullet(left, target, 100, weaponHash, ped)
        self:ShootLocalBullet(right, target, 100, weaponHash, ped)
    end)
end

function ImportedExtensionOptions:AddLocalExplosion(x, y, z, explosionType, damageScale, owner)
    if not menu.nativeApis.FIRE then return false, "explosion native unavailable" end
    if not ((owner and owner ~= 0 and type(menu.nativeApis.FIRE.ADD_OWNED_EXPLOSION) == "function")
        or type(menu.nativeApis.FIRE.ADD_EXPLOSION) == "function") then return false, "explosion native unavailable" end
    local ok, err = pcall(function()
        if owner and owner ~= 0 and type(menu.nativeApis.FIRE.ADD_OWNED_EXPLOSION) == "function" then
            menu.nativeApis.FIRE.ADD_OWNED_EXPLOSION(owner, x, y, z, explosionType, damageScale or 1.0, true, false, 0.0)
