MenuDefinitions.ExtendedItems.PlayerSave = {
    {
        hash = Utils.Joaat("block_script_host_mig"),
        name = "Block Script Host Migration",
        group = CONFIG.GROUPS.SESSION,
        type = eFeatureType.Toggle,
        desc = "",
        cb = function(f)
            if menu.nativeApis.NETWORK.NETWORK_IS_HOST() then
                while f:IsToggled() do
                    menu.nativeApis.NETWORK.NETWORK_REQUEST_TO_BE_HOST_OF_THIS_SCRIPT()
                    menu.nativeApis.NETWORK.NETWORK_PREVENT_SCRIPT_HOST_MIGRATION()
                    Script.Yield(10)
                end
            else
                Logger:Toast("Block Script Host Migration", "You must be the session host", CONFIG.UI.ToastDuration.Medium)
            end
        end
    },
    {
        hash = Utils.Joaat("save_player_save"),
        name = "Save Selected Player",
        group = CONFIG.GROUPS.SESSION,
        type = eFeatureType.Button,
        desc = "Save the player currently selected in the player list",
        cb = function(f)
            local pid = f:GetPlayerIndex()
            if pid == -1 then
                Logger:Toast("Saved players", "Select a player first", CONFIG.UI.ToastDuration.Short)
                return
            end
            local success, rid = PlayerManager:GetRockstarId(pid)
            if success and rid ~= 0 then
                local name = Players.GetName(pid) or "Unknown"
                SavedPlayerManager:AddPlayer(rid, name)
            else
                Logger:Toast("Saved players", "Could not retrieve the player's RID", CONFIG.UI.ToastDuration.Short)
            end
        end
    },
    {
        hash = Utils.Joaat("save_player_list"),
        name = "View Saved Players",
        group = CONFIG.GROUPS.SESSION,
        type = eFeatureType.Combo,
        desc = "View and manage your saved players",
        list = {},
        cb = function(f)
            local list = SavedPlayerManager:GetPlayerList()
            local names = {}
            for _, data in ipairs(list) do
                local fav = data.isFavorite and "★ " or ""
                table.insert(names, fav .. data.name .. " (" .. (data.category or "Default") .. ")")
            end
            if #names == 0 then
                table.insert(names, "No saved players")
            end
            f:SetList(names)
        end
    },
    {
        hash = Utils.Joaat("save_player_remove"),
        name = "Remove Selected Player",
        group = CONFIG.GROUPS.SESSION,
        type = eFeatureType.Button,
        desc = "Remove the selected player from the saved list",
        cb = function()
            local list = SavedPlayerManager:GetPlayerList()
            local feature = FeatureMgr.GetFeature(Utils.Joaat("save_player_list"))
            if feature and #list > 0 then
                local idx = feature:GetListIndex() + 1
                if list[idx] then
                    SavedPlayerManager:RemovePlayer(list[idx].rid)
                end
            end
        end
    },
    {
        hash = Utils.Joaat("save_player_set_category"),
        name = "Set Category",
        group = CONFIG.GROUPS.SESSION,
        type = eFeatureType.Combo,
        desc = "Set the selected player's category",
        list = {"Default", "Friend", "Enemy", "Suspect"},
        cb = function(f)
            local list = SavedPlayerManager:GetPlayerList()
            local selFeature = FeatureMgr.GetFeature(Utils.Joaat("save_player_list"))
            if selFeature and #list > 0 then
                local idx = selFeature:GetListIndex() + 1
                if list[idx] then
                    local categoryMap = {"Default", "Friend", "Enemy", "Suspect"}
                    local cat = categoryMap[f:GetListIndex() + 1] or "Default"
                    SavedPlayerManager:SetCategory(list[idx].rid, cat)
                    Logger:Toast("Saved players", "Category set: " .. cat, CONFIG.UI.ToastDuration.Short)
                end
            end
        end
    },
    {
        hash = Utils.Joaat("save_player_search"),
        name = "Search Players",
        group = CONFIG.GROUPS.SESSION,
        type = eFeatureType.InputText,
        desc = "Search saved players by name",
        cb = function(f)
            local query = f:GetStringValue()
            if query and query ~= "" then
                local results = SavedPlayerManager:SearchByName(query)
                if #results > 0 then
                    local names = {}
                    for _, data in ipairs(results) do
                        table.insert(names, data.name)
                    end
                    local displayCount = math.min(#names, 5)
                    local displayNames = {}
                    for i = 1, displayCount do
                        table.insert(displayNames, "• " .. names[i])
                    end
                    local nameStr = table.concat(displayNames, "\n")
                    local suffix = #names > 5 and ("\n...and " .. (#names - 5) .. " more results") or ""
                    Logger:Toast("Search", "Found " .. #results .. " results:\n" .. nameStr .. suffix, CONFIG.UI.ToastDuration.Medium)
                    Logger:Info("Search Players", "Results for '" .. query .. "': " .. table.concat(names, ", "))
                else
                    Logger:Toast("Search", "No matching players found", CONFIG.UI.ToastDuration.Short)
                end
            end
        end
    }
}
