function R53PointerToggle(featureId, title, beforeChange)
    return function(feature)
        local requested = feature:IsToggled() == true
        local ok, reason = SovereignRuntimePatchBridge:SetEnabled(featureId, requested)
        if ok ~= true then
            local actual = SovereignRuntimePatchBridge:IsEnabled(featureId)
            feature:SetToggledSilently(actual)
            SovereignNotify(title or "Feature settings", "Could not enable: " .. SovereignRuntimePatchBridge:DescribeError(reason), "warning")
            return false
        end
        if type(beforeChange) == "function" then
            local hookOk, hookResult, hookError = pcall(beforeChange, requested)
            if not hookOk or hookResult == false then
                if requested then SovereignRuntimePatchBridge:SetEnabled(featureId, false) end
                feature:SetToggledSilently(SovereignRuntimePatchBridge:IsEnabled(featureId))
                SovereignNotify(title or "Feature settings",
                    "Could not apply the related setting: " .. tostring(hookOk and hookError or hookResult), "warning")
                return false
            end
        end
        return true
    end
end

SovereignAimAssist = {
    head = false,
    hold = false,
    target = 0,
    advanced = {
        allowPlayers = true,
        allowNpc = true,
        allowVehicle = true,
        whileDriving = false,
        strength = 1.0,
        targetBone = 31086,
        maxDistance = 300.0,
    }
}

function SovereignAimAssist:Reset()
    self.target, self.identity, self.owner = 0, nil, nil
end

function SovereignAimAssist:SetOption(name, enabled)
    self[name] = enabled == true
    self:Reset()
    return true
end

function SovereignAimAssist:IsTargetAllowed(target)
    if not target or target == 0 then return false end
    local e, p = menu.nativeApis.ENTITY, menu.nativeApis.PED
    if not e or not p then return true end
    if e.IS_ENTITY_A_PED and not e.IS_ENTITY_A_PED(target) then return false end
    local isPlayer = p.IS_PED_A_PLAYER and p.IS_PED_A_PLAYER(target) == true
    local opts = self.advanced or {}
    if isPlayer and opts.allowPlayers == false then return false end
    if not isPlayer and opts.allowNpc == false then return false end
    if opts.allowVehicle == false and p.IS_PED_IN_ANY_VEHICLE and p.IS_PED_IN_ANY_VEHICLE(target, false) then
        return false
    end
    if tonumber(opts.maxDistance) and opts.maxDistance > 0 and e.GET_ENTITY_COORDS
        and menu.nativeApis.PLAYER and menu.nativeApis.PLAYER.PLAYER_PED_ID then
        local owner = menu.nativeApis.PLAYER.PLAYER_PED_ID()
        local okA, a = pcall(e.GET_ENTITY_COORDS, owner, true)
        local okB, b = pcall(e.GET_ENTITY_COORDS, target, true)
        if okA and okB and a and b then
            local dx, dy, dz = (a.x or 0) - (b.x or 0), (a.y or 0) - (b.y or 0), (a.z or 0) - (b.z or 0)
            if math.sqrt(dx * dx + dy * dy + dz * dz) > opts.maxDistance then return false end
        end
    end
    return true
end

function SovereignAimAssist:NativeTarget(pid, owner, melee)
    if melee and menu.nativeApis.PED.GET_MELEE_TARGET_FOR_PED then
        local ok, target=pcall(menu.nativeApis.PED.GET_MELEE_TARGET_FOR_PED,owner)
        if ok and type(target)=="number" and target~=0 and self:IsTargetAllowed(target) then return target end
    end
    if not self.buffer then self.buffer = Memory.AllocInt() end
    if not self.buffer or self.buffer == 0 then return 0 end
    for _, getterName in ipairs({"GET_PLAYER_TARGET_ENTITY", "GET_ENTITY_PLAYER_IS_FREE_AIMING_AT"}) do
        local getter = menu.nativeApis.PLAYER[getterName]
        Memory.WriteInt(self.buffer, 0)
        if type(getter) == "function" then
            local ok, found=pcall(getter,pid,self.buffer)
        if ok and (found==true or found==1) then
                local target=Memory.ReadInt(self.buffer)
            if target and target~=0 and self:IsTargetAllowed(target) then return target end
            end
        end
    end
    return 0
end

SovereignAimAssist.Process = LPH_NO_VIRTUALIZE(function(self)
    if not self.head and not self.hold then return end
    if menu.isOpen() or (GUI and GUI.IsOpen and GUI.IsOpen()) then return end
    if menu.nativeApis.CAM.IS_GAMEPLAY_CAM_RENDERING and not menu.nativeApis.CAM.IS_GAMEPLAY_CAM_RENDERING() then return end
    local owner,pid=menu.nativeApis.PLAYER.PLAYER_PED_ID(),menu.nativeApis.PLAYER.PLAYER_ID()
    local driving = menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE(owner, false)
    if owner==0 or (driving and not (self.advanced and self.advanced.whileDriving))
        or menu.nativeApis.PED.IS_PED_DEAD_OR_DYING(owner,true) then self:Reset();return end
    if self.owner and self.owner~=owner then self:Reset() end
    local weapon=menu.nativeApis.WEAPON.GET_SELECTED_PED_WEAPON(owner)
    local melee=self.hold and type(weapon)=="number"
        and (weapon & 0xffffffff)==(Utils.Joaat("weapon_unarmed") & 0xffffffff)
    local function pressed(control)
        return menu.nativeApis.PAD.IS_CONTROL_PRESSED(0,control) or menu.nativeApis.PAD.IS_DISABLED_CONTROL_PRESSED(0,control)
    end
    local aiming=pressed(25)
    local attacking=melee and (pressed(24) or pressed(140) or pressed(141) or pressed(142)
        or (menu.nativeApis.PED.IS_PED_PERFORMING_MELEE_ACTION and menu.nativeApis.PED.IS_PED_PERFORMING_MELEE_ACTION(owner)))
    if self.wasMelee~=melee then self:Reset() end
    self.wasMelee=melee
    if self.target~=0 and (not self:IsTargetAllowed(self.target) or not ImportedExtensionOptions:IsTargetShotIdentityCurrent(self.identity)
        or menu.nativeApis.PED.IS_PED_DEAD_OR_DYING(self.target,true)) then self:Reset() end
    if not melee and (not self.head or not aiming) then self:Reset();return end
    -- A melee target persists across native lock loss and between punches.
    -- Releasing attack leaves movement free; it does not select another target.
    if not melee or self.target==0 then
        if not aiming and not attacking then return end
        local native=self:NativeTarget(pid,owner,melee)
        if native~=0 and native~=owner and menu.nativeApis.ENTITY.DOES_ENTITY_EXIST(native) and menu.nativeApis.ENTITY.IS_ENTITY_A_PED(native)
            and not menu.nativeApis.PED.IS_PED_DEAD_OR_DYING(native,true)
            and self:IsTargetAllowed(native) then
            local identity=ImportedExtensionOptions:GetTargetShotIdentity(native)
            if identity then self.target,self.identity,self.owner=native,identity,owner end
        elseif not melee then self:Reset();return end
    end
    if self.target==0 or (not aiming and not attacking) then return end
    local bone = melee and 24816 or ((self.advanced and self.advanced.targetBone) or 31086)
    local point=ImportedExtensionOptions:GetPrivateWeaponTargetPosition(self.target,bone,false)
    if not point then return end
    local camera,rotation=menu.nativeApis.CAM.GET_GAMEPLAY_CAM_COORD(),menu.nativeApis.CAM.GET_GAMEPLAY_CAM_ROT(2)
    local dx,dy,dz=point.x-camera.x,point.y-camera.y,point.z-camera.z
    local flat=math.sqrt(dx*dx+dy*dy)
    if flat<0.01 then return end
    local yaw,pitch=math.deg(math.atan(-dx,dy)),math.deg(math.atan(dz,flat))
    local dt=menu.nativeApis.MISC.GET_FRAME_TIME()
    if type(dt)~="number" or dt~=dt then return end
    local strength = self.advanced and tonumber(self.advanced.strength) or 1.0
    local blend=math.min(1,math.max(0,dt)*30*math.max(0, math.min(2, strength)))
    menu.nativeApis.CAM.SET_GAMEPLAY_CAM_RELATIVE_HEADING(menu.nativeApis.CAM.GET_GAMEPLAY_CAM_RELATIVE_HEADING()+((yaw-rotation.z+180)%360-180)*blend)
    local nextPitch=menu.nativeApis.CAM.GET_GAMEPLAY_CAM_RELATIVE_PITCH()+(pitch-rotation.x)*blend
    menu.nativeApis.CAM.SET_GAMEPLAY_CAM_RELATIVE_PITCH(math.max(-89,math.min(89,nextPitch)),1.0)
    if melee and attacking and menu.nativeApis.PED.SET_PED_DESIRED_HEADING then
        local position=menu.nativeApis.ENTITY.GET_ENTITY_COORDS(owner,false)
        menu.nativeApis.PED.SET_PED_DESIRED_HEADING(owner,math.deg(math.atan(-(point.x-position.x),point.y-position.y)))
    end
end)

function SovereignAimAssist:Cleanup()
    self:Reset()
    if self.buffer then pcall(Memory.Free,self.buffer);self.buffer=nil end
    self.head,self.hold,self.wasMelee=false,false,nil
    self.advanced = self.advanced or {}
    self.advanced.whileDriving = false
end

function R53TrueCrouchToggle(feature)
    local requested = feature:IsToggled() == true
    local loopOk, loopError = true, nil
    if requested then
        SovereignRuntimeNativeOptions.patchRestorePending["action.true_crouch"] = nil
        SovereignRuntimeNativeOptions.crouchRestorePending = false
        local ok, reason = SovereignRuntimePatchBridge:SetEnabled("action.true_crouch", true)
        if not ok then
            feature:SetToggledSilently(false)
            SovereignRuntimeNativeOptions.patchRestorePending["action.true_crouch"] =
                SovereignRuntimePatchBridge:IsEnabled("action.true_crouch") or nil
            SovereignNotify("Crouch", "Could not enable: " .. SovereignRuntimePatchBridge:DescribeError(reason), "warning")
            return false
        end
        loopOk, loopError = pcall(function()
            local resourcesReady, resourceError = SovereignRuntimeNativeOptions:RequestCrouchClipsets()
            assert(resourcesReady, resourceError or "crouch resources unavailable")
            local appliedPed = nil
            while feature:IsToggled() and SovereignRuntimePatchBridge:IsEnabled("action.true_crouch")
                and not (type(ShouldUnload) == "function" and ShouldUnload()) do
                local ped = menu.nativeApis.PLAYER.PLAYER_PED_ID()
                local inVehicle = ped ~= 0 and menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE(ped, false)
                if appliedPed and appliedPed ~= ped then
                    assert(SovereignRuntimeNativeOptions:RestoreCrouchPeds(appliedPed), "previous ped restore failed")
                    appliedPed = nil
                end
                if ped ~= 0 and not inVehicle then
                    -- Consume the stealth key so the game does not toggle its standing stealth task too.
                    menu.nativeApis.PAD.DISABLE_CONTROL_ACTION(0, 36, true)
                    if menu.nativeApis.PAD.IS_DISABLED_CONTROL_JUST_PRESSED(0, 36) then
                        SovereignRuntimeNativeOptions.crouched = not SovereignRuntimeNativeOptions.crouched
                    end
                end
                if ped ~= 0 and SovereignRuntimeNativeOptions.crouched and not inVehicle then
                    local applied, applyError = SovereignRuntimeNativeOptions:ApplyCrouchPed(ped)
                    assert(applied, applyError)
                    appliedPed = ped
                elseif appliedPed then
                    assert(SovereignRuntimeNativeOptions:RestoreCrouchPeds(appliedPed), "standing restore failed")
                    appliedPed = nil
                end
                Script.Yield(0)
            end
        end)
    end
    local cleanupCallOk, cleanupOk = pcall(SovereignRuntimeNativeOptions.CleanupCrouch, SovereignRuntimeNativeOptions)
    local releaseCallOk, restoreOk, restoreError = pcall(
        SovereignRuntimePatchBridge.SetEnabled, SovereignRuntimePatchBridge, "action.true_crouch", false)
    feature:SetToggledSilently(false)
    SovereignRuntimeNativeOptions.crouchRestorePending = not cleanupCallOk or cleanupOk ~= true
    SovereignRuntimeNativeOptions.patchRestorePending["action.true_crouch"] =
        (not releaseCallOk or restoreOk ~= true) or nil
    if not loopOk then SovereignNotify("Crouch", "The action stopped after an error: " .. tostring(loopError), "warning") end
    if not cleanupCallOk or cleanupOk ~= true then SovereignNotify("Crouch", "Restoring your character's previous state. Please wait.", "warning") end
    if not releaseCallOk or restoreOk ~= true then
        SovereignNotify("Crouch", "Could not restore the previous setting: " .. tostring(restoreError or restoreOk), "warning")
    end
    return loopOk and cleanupCallOk and cleanupOk == true and releaseCallOk and restoreOk == true
end

function R53AutoDuckToggle(feature)
    local requested = feature:IsToggled() == true
    SovereignRuntimeNativeOptions.patchRestorePending["vehicle.auto_duck"] = nil
    local ok, reason = SovereignRuntimePatchBridge:SetEnabled("vehicle.auto_duck", requested)
    if not ok then
        feature:SetToggledSilently(false)
        SovereignRuntimeNativeOptions.patchRestorePending["vehicle.auto_duck"] =
            SovereignRuntimePatchBridge:IsEnabled("vehicle.auto_duck") or nil
        SovereignNotify("Auto duck in vehicles", "Could not enable: " .. SovereignRuntimePatchBridge:DescribeError(reason), "warning")
        return false
    end
    local loopOk, loopError = pcall(function()
        while feature:IsToggled() and SovereignRuntimePatchBridge:IsEnabled("vehicle.auto_duck")
            and not (type(ShouldUnload) == "function" and ShouldUnload()) do
            local ped = menu.nativeApis.PLAYER.PLAYER_PED_ID()
            if ped ~= 0 and menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
                menu.nativeApis.PAD.SET_CONTROL_VALUE_NEXT_FRAME(0, 73, 1.0)
            end
            Script.Yield(0)
        end
    end)
    local releaseCallOk, restoreOk, restoreError = pcall(
        SovereignRuntimePatchBridge.SetEnabled, SovereignRuntimePatchBridge, "vehicle.auto_duck", false)
    feature:SetToggledSilently(false)
    SovereignRuntimeNativeOptions.patchRestorePending["vehicle.auto_duck"] =
        (not releaseCallOk or restoreOk ~= true) or nil
    if not loopOk then SovereignNotify("Auto duck in vehicles", "The action stopped after an error: " .. tostring(loopError), "warning") end
    if not releaseCallOk or restoreOk ~= true then
        SovereignNotify("Auto duck in vehicles", "Could not restore the previous setting: " .. tostring(restoreError or restoreOk), "warning")
    end
    return loopOk and releaseCallOk and restoreOk == true
end

function R53NitrousToggle(feature)
    local requested = feature:IsToggled() == true
    if requested then
        if not menu.nativeApis.ENTITY or type(menu.nativeApis.ENTITY.GET_ENTITY_VELOCITY) ~= "function"
            or type(menu.nativeApis.ENTITY.SET_ENTITY_VELOCITY) ~= "function" then
            feature:SetToggledSilently(false)
            SovereignNotify("Vehicle nitro", "Nitrous acceleration is currently unavailable. Update Cherax and try again.", "warning")
            return false
        end
        SovereignRuntimeNativeOptions.nitrousDiagnostic = {reason = "ready", ticks = 0}
        SovereignRuntimeNativeOptions.nitrousRestorePending = false
        SovereignRuntimeNativeOptions.nitrousEnabled = true
        SovereignRuntimeNativeOptions.nitrousCharge = 1.0
        return true
    end
    local callOk, restored = pcall(SovereignRuntimeNativeOptions.CleanupNitrous, SovereignRuntimeNativeOptions)
    if not callOk or restored ~= true then SovereignNotify("Vehicle nitro", "Restoring the previous setting. Please wait.", "warning") end
    return callOk and restored == true
end

function R53NitrousHornToggle(feature)
    -- The key is sampled directly; changing a duck-task predicate does not activate nitrous.
    SovereignRuntimeNativeOptions.nitrousUseHorn = feature:IsToggled() == true
    return true
end

function R53DisableSeatbeltForWindscreen(enabled)
    SovereignRuntimeNativeOptions.windscreenEnabled = enabled == true
    -- Defined after the local VehicleOptions declaration; the early runtime methods
    -- must not accidentally resolve an unrelated global with the same name.
    SovereignRuntimeNativeOptions.windscreenSeatbeltProbe = function(playerId)
        return VehicleOptions and VehicleOptions.seatbelt and VehicleOptions.seatbelt[playerId] == true
    end
    if not enabled then
        SovereignRuntimeNativeOptions.windscreenPending = nil
        SovereignRuntimeNativeOptions.windscreenSample = nil
        SovereignRuntimeNativeOptions.windscreenEjectUntil = nil
        return SovereignRuntimeNativeOptions:RestoreWindscreenPeds()
    end
    local shim = SovereignRuntime and SovereignRuntime.shimsByHash
        and SovereignRuntime.shimsByHash[Utils.Joaat("veh_seatbelt")]
    local wasEnabled = shim and shim:IsToggled() == true
    local ok, reason = pcall(function()
        if wasEnabled then shim:SetToggledSilently(false) end
        if VehicleOptions then VehicleOptions:ToggleSeatbelt(menu.nativeApis.PLAYER.PLAYER_ID(), false) end
    end)
    if not ok then
        SovereignRuntimeNativeOptions.windscreenEnabled = false
        if wasEnabled then
            pcall(shim.SetToggledSilently, shim, true)
            if VehicleOptions then pcall(VehicleOptions.ToggleSeatbelt, VehicleOptions, menu.nativeApis.PLAYER.PLAYER_ID(), true) end
        end
        return false, reason
    end
    return true
end

