function SovereignOverlayValueColor(value, fallback)
    local text = tostring(value or "")
    if text == "Yes" then return SovereignOverlayTheme.yes end
    if text == "No" then return SovereignOverlayTheme.no end
    return fallback or SovereignOverlayTheme.text
end

function SovereignOverlayDrawSectionTitle(x, y, width, title)
    local theme = SovereignOverlayTheme
    local _, textHeight = menu.localizedTextSize(title)
    textHeight = math.max(12, tonumber(textHeight) or 16)
    SovereignOverlayText(x + 2, y, title, theme.accent)
    ImGui.AddLine(x, y + textHeight + 5, x + width, y + textHeight + 5,
        theme.border[1], theme.border[2], theme.border[3], 125, 1.0)
    return textHeight + 14
end

function SovereignOverlayDrawRow(x, y, width, label, value, color, alternate, rowHeight)
    local theme = SovereignOverlayTheme
    rowHeight = rowHeight or 31
    value = tostring(value or "Unknown")
    local labelWidth, labelHeight = menu.localizedTextSize(label)
    local valueWidth, valueHeight = menu.localizedTextSize(value)
    local split = width * (width < 340 and 0.64 or 0.40)
    local valueX = x + math.floor(split)
    local textHeight = math.max(tonumber(labelHeight) or 16, tonumber(valueHeight) or 16)
    local textY = y + math.max(2, (rowHeight - textHeight) * 0.5)
    if alternate then
        ImGui.AddRectFilled(x, y, x + width, y + rowHeight - 2,
            theme.row[1], theme.row[2], theme.row[3], theme.row[4], 5.0)
    end
    ImGui.PushClipRect(x + 8, y, math.max(x + 9, valueX - 8), y + rowHeight, true)
    SovereignOverlayText(x + 8, textY, label, theme.secondary)
    ImGui.PopClipRect()
    ImGui.PushClipRect(valueX, y, x + width - 8, y + rowHeight, true)
    SovereignOverlayText(valueX, textY, value, SovereignOverlayValueColor(value, color))
    ImGui.PopClipRect()
    local clipped = (tonumber(labelWidth) or 0) > split - 16
        or (tonumber(valueWidth) or 0) > width - split - 8
    if clipped and type(ImGui.IsWindowHovered) == "function" and ImGui.IsWindowHovered()
        and menu.pointInRect(x, y, width, rowHeight)
        and type(ImGui.BeginTooltip) == "function" and type(ImGui.EndTooltip) == "function" then
        ImGui.BeginTooltip()
        menu.localizedTextColored(theme.secondary[1], theme.secondary[2], theme.secondary[3], theme.secondary[4], label)
        local valueColor = SovereignOverlayValueColor(value, color)
        menu.localizedTextColored(valueColor[1], valueColor[2], valueColor[3], valueColor[4], value)
        ImGui.EndTooltip()
    end
end

function SovereignOverlayBeginContent(id, state, x, y, width, height)
    ImGui.SetCursorScreenPos(x + 10, y + 52)
    local visible = ImGui.BeginChild("##content_" .. id, width - 20, height - 62,
        false, ImGuiWindowFlags.NoBackground)
    ImGui.SetWindowFontScale(state.fontScale or 1.0)
    local childX, childY = ImGui.GetWindowPos()
    local scrollY = ImGui.GetScrollY()
    local _, lineHeight = menu.localizedTextSize("Ag")
    local rowHeight = math.max(31, (tonumber(lineHeight) or 16) + 12)
    return visible, childX + 6, childY + 4 - scrollY, math.max(100, width - 48), rowHeight
end

function SovereignOverlayText(x, y, text, color)
    color = SovereignOverlayValueColor(text, color)
    ImGui.SetCursorScreenPos(x, y)
    menu.localizedTextColored(color[1], color[2], color[3], color[4], tostring(text or ""))
end

function SovereignOverlayFormatNumber(value, prefix)
    if type(value) ~= "number" then return "--" end
    local negative = value < 0
    local digits = tostring(math.floor(math.abs(value)))
    local formatted = digits:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
    return tostring(prefix or "") .. (negative and "-" or "") .. formatted
end

function SovereignOverlayBegin(id, state, title, width, height)
    if not ImGui or not ImGui.Begin or not ImGui.GetDisplaySize then
        return false
    end
    local displayWidth, displayHeight = ImGui.GetDisplaySize()
    local panelWidth = math.max(320, math.min(1200, tonumber(state.width) or width))
    local panelHeight = math.max(180, math.min(900, tonumber(state.height) or height))
    state.width = panelWidth
    state.height = panelHeight
    state.fontScale = math.max(0.70, math.min(1.50, tonumber(state.fontScale) or 1.0))
    state.minimized = state.minimized == true
    local windowHeight = state.minimized and 46 or panelHeight
    if not state.x then
        state.x = state.anchorRight and math.max(8, displayWidth - panelWidth - 24) or 24
        state._positionDirty = true
    end
    if not state.y then state.y = 120 end
    -- Keep a small grab area visible while allowing the panel to sit partly
    -- outside the viewport. This makes stacked overlays easier to arrange
    -- without ever losing the title bar completely.
    local visibleEdge = 48
    local minX = math.min(visibleEdge - (panelWidth - 110), displayWidth - visibleEdge)
    local maxX = math.max(minX, displayWidth - visibleEdge)
    local minY = 0
    local maxY = math.max(minY, displayHeight - visibleEdge)
    state.x = math.max(minX, math.min(state.x, maxX))
    state.y = math.max(minY, math.min(state.y, maxY))

    local flags = ImGuiWindowFlags.NoTitleBar
        | ImGuiWindowFlags.NoResize
        | ImGuiWindowFlags.NoMove
        | ImGuiWindowFlags.NoScrollbar
        | ImGuiWindowFlags.NoScrollWithMouse
        | ImGuiWindowFlags.NoCollapse
        | ImGuiWindowFlags.NoSavedSettings
        | ImGuiWindowFlags.NoFocusOnAppearing
        | ImGuiWindowFlags.NoBackground
    -- Floating panels stay independently interactive so their position and
    -- collapsed state can be adjusted without reopening the main menu.
    local overlayInteractive = state.interactive ~= false

    ImGui.SetNextWindowPos(state.x, state.y, ImGuiCond.Always, 0.0, 0.0)
    ImGui.SetNextWindowSize(panelWidth, windowHeight, ImGuiCond.Always)
    if not ImGui.Begin(id, true, flags) then
        ImGui.End()
        return false
    end

    local x, y = ImGui.GetWindowPos()
    ImGui.SetWindowFontScale(state.fontScale)
    local theme = SovereignOverlayTheme
    ImGui.AddRectFilled(x + 4, y + 5, x + panelWidth + 4, y + windowHeight + 5, 0, 0, 0, 64, 10.0)
    ImGui.AddRectFilled(x, y, x + panelWidth, y + windowHeight, theme.background[1], theme.background[2], theme.background[3], theme.background[4], 10.0)
    ImGui.AddRectFilled(x + 1, y + 1, x + panelWidth - 1, y + 44, theme.header[1], theme.header[2], theme.header[3], theme.header[4], 7.0)
    ImGui.AddRectFilled(x + 12, y + 13, x + 15, y + 30,
        math.floor(theme.accent[1] * 255), math.floor(theme.accent[2] * 255), math.floor(theme.accent[3] * 255), 235, 2.0)
    ImGui.AddLine(x + 12, y + 44, x + panelWidth - 12, y + 44, theme.border[1], theme.border[2], theme.border[3], theme.border[4], 1.0)
    ImGui.AddRect(x + 0.5, y + 0.5, x + panelWidth - 0.5, y + windowHeight - 0.5,
        theme.border[1], theme.border[2], theme.border[3], theme.border[4], 10.0, 0, 1.0)

    ImGui.SetCursorScreenPos(x, y)
    local dragWidth = math.max(80.0, panelWidth - 92.0)
    ImGui.InvisibleButton("##drag_" .. id, dragWidth, 44)
    if overlayInteractive and ImGui.IsItemActive and ImGui.IsItemActive() and ImGui.GetMousePos then
        local mouseX, mouseY = ImGui.GetMousePos()
        if not state.dragging then
            state.dragging = true
            state.dragOffsetX = mouseX - state.x
            state.dragOffsetY = mouseY - state.y
        else
            state.x = mouseX - (state.dragOffsetX or 0)
            state.y = mouseY - (state.dragOffsetY or 0)
            state._positionDirty = true
        end
    else
        if state.dragging and state._positionDirty then
            state._positionDirty = false
            if menu and menu.queueUiSettingsSave then menu.queueUiSettingsSave() end
        end
        state.dragging = false
    end

    ImGui.PushClipRect(x + 24, y + 4, x + panelWidth - 110, y + 42, true)
    SovereignOverlayText(x + 24, y + 13, title, theme.text)
    ImGui.PopClipRect()
    local liveX = x + panelWidth - 100
    ImGui.AddRectFilled(liveX, y + 10, liveX + 46, y + 34,
        math.floor(theme.accent[1] * 255), math.floor(theme.accent[2] * 255), math.floor(theme.accent[3] * 255), 34, 6.0)
    SovereignOverlayText(liveX + 10, y + 13, "Live", theme.accent)
    local collapseX = x + panelWidth - 42
    ImGui.SetCursorScreenPos(collapseX, y + 9)
    local collapseClicked = ImGui.InvisibleButton("##collapse_" .. id, 30, 28)
    if collapseClicked and overlayInteractive then
        state.minimized = not state.minimized
        if menu and menu.queueUiSettingsSave then menu.queueUiSettingsSave() end
    end
    SovereignOverlayText(collapseX + 10, y + 13, state.minimized and "+" or "-", theme.accent)
    if state.minimized then
        ImGui.SetWindowFontScale(1.0)
        ImGui.End()
        return false
    end
    return true, x, y, panelWidth, panelHeight
end

menu.notificationHistoryWindow = menu.notificationHistoryWindow or {
    x = 24, y = 760, width = 560, height = 340, fontScale = 0.90
}

function menu.renderNotificationHistory()
    if not menu.notificationHistoryVisible then return end
    local begun, x, y, panelWidth = SovereignOverlayBegin(
        "SovereignNotificationHistory", menu.notificationHistoryWindow, "Notification History", 560, 340)
    if not begun then return end
    local ok, err = xpcall(function()
        local theme = SovereignOverlayTheme
        local rowY = y + 54
        local visibleCount = math.min(8, #menu.notificationHistory)
        if visibleCount == 0 then
            SovereignOverlayText(x + 20, rowY + 6, "No notifications", theme.secondary)
        end
        for index = 1, visibleCount do
            local entry = menu.notificationHistory[index]
            local color = theme.accent
            if entry.status == "success" or entry.status == 1 then color = theme.product end
            if entry.status == "warning" or entry.status == 2 then color = theme.cargo end
            if entry.status == "error" or entry.status == 3 then color = {0.94, 0.45, 0.45, 1.0} end
            if index % 2 == 1 then
                ImGui.AddRectFilled(x + 12, rowY - 3, x + panelWidth - 12, rowY + 27,
                    theme.row[1], theme.row[2], theme.row[3], theme.row[4], 4.0)
            end
            local label = tostring(entry.label or "")
            SovereignOverlayText(x + 20, rowY + 3, tostring(entry.title or "SovereignLua"), color)
            ImGui.PushClipRect(x + 142, rowY, x + panelWidth - 18, rowY + 29, true)
            SovereignOverlayText(x + 142, rowY + 3, label, theme.text)
            ImGui.PopClipRect()
            rowY = rowY + 33
        end
    end, debug.traceback)
    ImGui.SetWindowFontScale(1.0)
    ImGui.End()
    if not ok then SovereignLogError("SovereignNotificationHistory.Render", err) end
end

