function SovereignBusinessInventory:Notify(message, status)
    if status == "warning" or status == "error" then
        -- Keep the actual failure and selected layout in the existing log;
        -- this does not add a prerequisite or retry a game transaction.
        pcall(function()
            local edition, source = "unknown", "unavailable"
            if Utils1 and type(Utils1.editionInfo) == "function" then
                local ok, detectedEdition, detectedSource = pcall(Utils1.editionInfo)
                if ok then
                    edition = detectedEdition or edition
                    source = detectedSource or source
                end
            end
            local mapping = nil
            if type(SovereignOfficial) == "table"
                and type(SovereignOfficial.GetMapping) == "function" then
                local ok, value = pcall(SovereignOfficial.GetMapping, SovereignOfficial)
                if ok then mapping = value end
            end
            if type(mapping) ~= "table" then
                mapping = rawget(_G, "__SOVEREIGN_GAME_MAPPING")
            end
            local hostOk, hostEdition = false, "unavailable"
            if Cherax and type(Cherax.GetEdition) == "function" then
                hostOk, hostEdition = pcall(Cherax.GetEdition)
            end
            if Logger and type(Logger.Info) == "function" then
                Logger:Info("SovereignInventory", string.format(
                "revision=%s edition=%s source=%s host=%s hint=%s inventoryDisabled=%s message=%s",
                tostring(self.runtimeRevision), tostring(edition), tostring(source),
                tostring(hostOk and hostEdition or "unavailable"),
                tostring(rawget(_G, "__SOVEREIGN_GAME_EDITION")),
                tostring(type(mapping) == "table" and mapping.inventoryDisabled == true),
                tostring(message or "")
                ))
            end
        end)
    end
    if type(menu) == "table" and type(menu.notify) == "function" then
        local body = tostring(message or "")
        local resolved = menu.normalizeNotificationStatus(status)
            or menu.inferNotificationStatus(body)
        menu.notify("SovereignLua", body, 3.0, resolved)
    end
end

function SovereignBusinessInventory:GetCharacterSlot()
    if Stats and type(Stats.GetInt) == "function" and Utils and type(Utils.Joaat) == "function" then
        local okCompat, compatValue = pcall(function()
            return self:ReadStatIntCompat(Utils.Joaat("MPPLY_LAST_MP_CHAR"))
        end)
        if okCompat and (compatValue == 0 or compatValue == 1) then return compatValue end
    end
    if Stats and type(Stats.GetInt) == "function" and Utils and type(Utils.Joaat) == "function" then
        local ok, readOk, value = pcall(Stats.GetInt, Utils.Joaat("MPPLY_LAST_MP_CHAR"))
        if ok and readOk == true and type(value) == "number" and value == value
            and (value == 0 or value == 1) then
            return math.floor(value)
        end
    end
    if not menu.nativeApis.STATS or type(menu.nativeApis.STATS.STAT_GET_INT) ~= "function"
        or not Memory or type(Memory.AllocInt) ~= "function"
        or type(Memory.ReadInt) ~= "function" then
        return nil
    end
    -- freemode's Global_1574928 is only a runtime cache populated from
    -- MPPLY_LAST_MP_CHAR; it is not a script-global character selector.
    -- Reading that address directly can select the wrong stat slot.
    local ptr = nil
    local ok, value = pcall(function()
        ptr = Memory.AllocInt()
        if not ptr or not menu.nativeApis.STATS.STAT_GET_INT(Utils.Joaat("MPPLY_LAST_MP_CHAR"), ptr, -1) then
            return nil
        end
        return tonumber(Memory.ReadInt(ptr))
    end)
    if ptr and type(Memory.Free) == "function" then
        pcall(Memory.Free, ptr)
    end
    if not ok or type(value) ~= "number" or value ~= value
        or (value ~= 0 and value ~= 1) then return nil end
    return math.floor(value)
end

function SovereignBusinessInventory:ReadStatIntCompat(hash)
    local numeric = tonumber(hash)
    if type(numeric) ~= "number" then return nil end
    local candidates = {numeric}
    local signed = self:NormalizeSignedInt32(numeric)
    if signed ~= numeric then candidates[#candidates + 1] = signed end
    for _, candidate in ipairs(candidates) do
        if Stats and type(Stats.GetInt) == "function" then
            local ok, first, second = pcall(Stats.GetInt, candidate)
            if ok then
                if first == true and type(second) == "number" then return second end
                if type(first) == "number" and second == nil then return first end
            end
        end
        if menu.nativeApis.STATS and type(menu.nativeApis.STATS.STAT_GET_INT) == "function"
            and Memory and type(Memory.AllocInt) == "function"
            and type(Memory.ReadInt) == "function" then
            local ptr = nil
            local ok, value = pcall(function()
                ptr = Memory.AllocInt()
                if not ptr or ptr == 0 or not menu.nativeApis.STATS.STAT_GET_INT(candidate, ptr, -1) then return nil end
                return tonumber(Memory.ReadInt(ptr))
            end)
            if ptr and type(Memory.Free) == "function" then pcall(Memory.Free, ptr) end
            if ok and type(value) == "number" then return value end
        end
    end
    return nil
end

function SovereignBusinessInventory:NormalizeSignedInt32(value)
    local number = tonumber(value)
    if type(number) ~= "number" or number ~= number
        or number == rawget(math, "huge") or number == -rawget(math, "huge") then
        return nil
    end
    local ok, normalized = pcall(math.floor, number)
    if not ok or normalized < -2147483648 or normalized > 4294967295 then
        return nil
    end
    if normalized > 2147483647 then
        normalized = normalized - 4294967296
    end
    return normalized
end

function SovereignBusinessInventory:GetInventoryStatName(index)
    index = tonumber(index)
    if not index or index ~= index or index ~= math.floor(index) then return nil end
    -- Verified against the installed Legacy 3889 character-mapping XML.
    -- These are character stats, not the MP_STAT_*_v0 transaction catalog.
    if index >= 3639 and index <= 3643 then return "WARHOUSESLOT" .. (index - 3639) end
    if index >= 3644 and index <= 3648 then return "CONTOTALFORWHOUSE" .. (index - 3644) end
    if index >= 3649 and index <= 3653 then return "SPCONTOTALFORWHOUSE" .. (index - 3649) end
    if index >= 3840 and index <= 3844 then return "FACTORYSLOT" .. (index - 3840) end
    if index >= 3845 and index <= 3849 then return "PRODTOTALFORFACTORY" .. (index - 3845) end
    if index >= 3850 and index <= 3854 then return "MATTOTALFORFACTORY" .. (index - 3850) end
    if index >= 7222 and index <= 7228 then return "HUB_PROD_TOTAL_" .. (index - 7222) end
    local named = {
        [5443] = "FACTORYSLOT5", [5444] = "PRODTOTALFORFACTORY5",
        [5446] = "MATTOTALFORFACTORY5", [6103] = "HANGAR_OWNED",
        [6104] = "HANGAR_CONTRABAND_TOTAL", [7212] = "CLUB_SAFE_CASH_VALUE",
        [8836] = "ARCADE_SAFE_CASH_VALUE", [11434] = "XM22_LAB_OWNED",
        [11806] = "PRODTOTALFORFACTORY6", [11807] = "MATTOTALFORFACTORY6"
    }
    return named[index]
end

function SovereignBusinessInventory:GetStatHashByIndex(index, slot)
    local statIndex = tonumber(index)
    local characterSlot = slot
    if characterSlot == nil then characterSlot = self:GetCharacterSlot() end
    characterSlot = tonumber(characterSlot)
    if type(statIndex) ~= "number" or statIndex ~= statIndex
        or statIndex < 0 or statIndex == rawget(math, "huge") or statIndex ~= math.floor(statIndex)
        or type(characterSlot) ~= "number"
        or (characterSlot ~= 0 and characterSlot ~= 1) then
        return 0
    end
    characterSlot = math.floor(characterSlot)
    local name = self:GetInventoryStatName(statIndex)
    if name then
        local hash = self:GetNamedStatHash("MP" .. characterSlot .. "_" .. name)
        if hash ~= 0 then return hash end
    end
    local function validHash(hash)
        return type(hash) == "number" and hash == hash and hash ~= 0
            and hash >= -2147483648 and hash <= 4294967295
            and hash == math.floor(hash)
    end
    if menu.nativeApis.STATS and type(menu.nativeApis.STATS._GET_STAT_HASH_FOR_CHARACTER_STAT) == "function" then
        local ok, hash = pcall(menu.nativeApis.STATS._GET_STAT_HASH_FOR_CHARACTER_STAT, 0, statIndex, characterSlot)
        if ok and validHash(hash) then return hash end
    end
    if Natives and type(Natives.InvokeInt) == "function" then
        local ok, hash = pcall(Natives.InvokeInt, 0xD69CE161FE614531, 0, statIndex, characterSlot)
        if ok and validHash(hash) then return hash end
    end
    return 0
end

function SovereignBusinessInventory:GetStatHashCandidates(index, slot)
    if slot == nil then slot = self:GetCharacterSlot() end
    if slot ~= 0 and slot ~= 1 then return {} end
    local hash = self:GetStatHashByIndex(index, slot)
    if type(hash) ~= "number" or hash == 0 then return {} end
    return {hash}
end

function SovereignBusinessInventory:GetNamedStatHash(name)
    if type(name) ~= "string" or name == "" or not Utils or type(Utils.Joaat) ~= "function" then
        return 0
    end
    local ok, hash = pcall(Utils.Joaat, name)
    return ok and type(hash) == "number" and hash or 0
end

function SovereignBusinessInventory:ReadNamedStat(name)
    local hash = self:GetNamedStatHash(name)
    if hash == 0 then return nil end
    return self:ReadStatIntCompat(hash)
end

function SovereignBusinessInventory:GetWarehouseRuntimeProductGlobal(index, playerId)
    local warehouseIndex = math.floor(tonumber(index) or -1)
    if warehouseIndex < 0 or warehouseIndex > 4 then return nil end
    if playerId == nil then playerId = self:GetLocalPlayerId() end
    playerId = tonumber(playerId)
    if playerId == nil then return nil end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 then return nil end
    -- Return the stable Enhanced logical global. ReadGlobal/WriteGlobal apply
    -- the edition-specific physical translation exactly once at the boundary.
    local playerBase = 1845347 + 1 + (playerId * 884)
    -- f_128 is the directly indexed warehouse array; its initialized value 5
    -- is the first element's type, not an array-length header.
    -- The quantity is f_1 of that element, not the warehouse location id.
    return playerBase + 260 + 128 + (warehouseIndex * 3) + 1
end

function SovereignBusinessInventory:GetWarehouseRuntimeTypeGlobal(index, playerId)
    local warehouseIndex = math.floor(tonumber(index) or -1)
    if warehouseIndex < 0 or warehouseIndex > 4 then return nil end
    if playerId == nil then playerId = self:GetLocalPlayerId() end
    playerId = tonumber(playerId)
    if playerId == nil then return nil end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 then return nil end
    -- Return the stable Enhanced logical global; the mapping layer translates
    -- it to Legacy's 1845298/881 structure when the game is Legacy.
    local playerBase = 1845347 + 1 + (playerId * 884)
    -- Enhanced and Legacy index f_260.f_128 directly by warehouse slot.
    return playerBase + 260 + 128 + (warehouseIndex * 3)
end

function SovereignBusinessInventory:ReadWarehouseType(definition, playerId)
    if type(definition) ~= "table" then return 0 end
    local typeGlobal = self:GetWarehouseRuntimeTypeGlobal(definition.index, playerId)
    local warehouseType = typeGlobal and self:ReadGlobal(typeGlobal) or nil
    return type(warehouseType) == "number" and math.floor(warehouseType) or 0
end

function SovereignBusinessInventory:GetWarehouseCapacity(definition, playerId)
    local warehouseType = self:ReadWarehouseType(definition, playerId)
    return math.floor(tonumber(self.warehouseCapacityByType[warehouseType]) or 0)
end

function SovereignBusinessInventory:GetWarehouseLocation(warehouseType)
    local normalized = math.floor(tonumber(warehouseType) or 0)
    return self.warehouseLocations and self.warehouseLocations[normalized] or nil
end

function SovereignBusinessInventory:GetWarehouseLocationName(warehouseType)
    local location = self:GetWarehouseLocation(warehouseType)
    if not location then return "Unknown location" end
    if menu.nativeApis.HUD and type(menu.nativeApis.HUD.GET_FILENAME_FOR_AUDIO_CONVERSATION) == "function" then
        local ok, localized = pcall(menu.nativeApis.HUD.GET_FILENAME_FOR_AUDIO_CONVERSATION, location.labelKey)
        if ok and type(localized) == "string" and localized ~= "" and localized ~= "NULL"
            and localized ~= location.labelKey then
            return localized
        end
    end
    return location.fallbackName
end

function SovereignBusinessInventory:ValidateWarehouseCatalog()
    if #self.warehouseDefinitions ~= 5 or #self.warehouseLocations ~= 22
        or #self.warehouseCargoTypes ~= 11 or #self.warehouseSpecialCargoTypes ~= 6
        or #self.warehouseCrateModels ~= 49 then
        return false, "catalog_count_mismatch"
    end
    for index, definition in ipairs(self.warehouseDefinitions) do
        local slot = index - 1
        if definition.index ~= slot or definition.productIndex ~= 3644 + slot
            or definition.specialProductIndex ~= 3649 + slot
            or definition.productStat ~= "MP_STAT_CONTOTALFORWHOUSE" .. tostring(slot) .. "_v0"
            or definition.specialProductStat ~= "MP_STAT_SPCONTOTALFORWHOUSE"
                .. tostring(slot) .. "_v0" then
            return false, "warehouse_slot_mismatch"
        end
    end
    for warehouseType = 1, 22 do
        local location = self.warehouseLocations[warehouseType]
        local capacity = math.floor(tonumber(self.warehouseCapacityByType[warehouseType]) or 0)
        local expectedSize = capacity == 16 and "Small"
            or (capacity == 42 and "Medium" or (capacity == 111 and "Large" or nil))
        if not location or capacity <= 0
            or capacity ~= math.floor(tonumber(location.capacity) or -1)
            or location.labelKey ~= "MP_WHOUSE_" .. tostring(warehouseType - 1)
            or location.size ~= expectedSize or type(location.fallbackName) ~= "string"
            or location.fallbackName == "" then
            return false, "location_capacity_mismatch"
        end
    end
    local normalCodeSeen = {}
    for index, cargo in ipairs(self.warehouseCargoTypes) do
        if cargo.id ~= index - 1 or type(cargo.name) ~= "string" then
            return false, "cargo_index_mismatch"
        end
        for _, poolName in ipairs({"smallCodes", "bigCodes", "closedCodes", "closedBigCodes"}) do
            local pool = cargo[poolName]
            if (poolName ~= "closedCodes" and poolName ~= "closedBigCodes") or pool ~= nil then
                if type(pool) ~= "table" or #pool == 0 then return false, "cargo_pool_missing" end
                for _, code in ipairs(pool) do
                    if type(code) ~= "number" or code < 1 or code > 49
                        or (code >= 23 and code <= 28) then
                        return false, "cargo_code_invalid"
                    end
                    normalCodeSeen[code] = true
                end
            end
        end
    end
    for code = 1, 49 do
        if (code < 23 or code > 28) and not normalCodeSeen[code] then
            return false, "cargo_code_missing"
        end
    end
    for index, special in ipairs(self.warehouseSpecialCargoTypes) do
        if special.id ~= index or special.crateCode ~= 22 + index
            or self.warehouseCrateModels[special.crateCode] ~= special.model then
            return false, "special_code_mismatch"
        end
    end
    local seenModels = {}
    for _, model in ipairs(self.warehouseCrateModels) do
        if type(model) ~= "string" or model == "" or seenModels[model] then
            return false, "crate_model_mismatch"
        end
        seenModels[model] = true
    end
    return true
end

function SovereignBusinessInventory:GetInventoryLayout()
    if not self.inventoryLayouts then
        self.inventoryLayouts = {
            Enhanced = {name = "enhanced_1158_inventory", edition = "Enhanced"},
            Legacy = {
                name = "legacy_3889_inventory", edition = "Legacy",
                playerBase = 1845298, playerStride = 881,
                organizationBase = 1892925,
                transactionBase = 4515492,
                supplyBaseline = 1673840, hangarPacking = 1964530,
                -- Keys are the existing inventory's logical Enhanced addresses.
                -- Only this module translates them, once, at the API boundary.
                globals = {
                    [77420] = 77403,
                    [4516963] = 4516963,
                    [4516967] = 4516967,
                    [4516968] = 4516968,
                    [1948675 + 53] = 1948194 + 53,
                    [1948794 + 43] = 1948313 + 43,
                    [1948841 + 53] = 1948360 + 53,
                    [1951218 + 4] = 1950702 + 4,
                    [1951218 + 4034] = 1950702 + 3992,
                    [1951061] = 1950547,
                    [1951063] = 1950549,
                    [1951071] = 1950557,
                    [1990065] = 1988711,
                    [2733326 + 3989 + 348] = 2733190 + 3988 + 348,
                    [2733326 + 3989 + 349] = 2733190 + 3988 + 349,
                    [2733326 + 3989 + 350] = 2733190 + 3988 + 350,
                },
                tunables = {
                    [16688] = 16684, [17440] = 17436,
                    [18813] = 18809, [18821] = 18817, [18829] = 18825,
                    [18837] = 18833, [18845] = 18841, [18853] = 18849,
                    [21341] = 21337, [23773] = 23769,
                    [24062] = 24058, [24063] = 24059, [24064] = 24060,
                    [24065] = 24061, [24066] = 24062, [24067] = 24063,
                    [24068] = 24064, [28878] = 28840,
                },
                bikerLocals = {[738] = 736, [738 + 122] = 736 + 122,
                    [738 + 174] = 736 + 174},
            },
        }
    end
    return self.inventoryLayouts[Utils1:edition()]
end

function SovereignBusinessInventory:ResolveInventoryGlobal(index)
    index = tonumber(index)
    if not index or index ~= index or index < 0 or index == rawget(math, "huge")
        or index ~= math.floor(index) then return nil end
    local layout = self:GetInventoryLayout()
    if not layout then return nil end
    if layout.edition == "Enhanced" then return index end
    local mapped = layout.globals[index]
    if mapped then return mapped end
    local tunable = layout.tunables[index - 262145]
    if tunable then return 262145 + tunable end
    local relative = index - (1845347 + 1)
    if relative >= 0 and relative < 32 * 884 then
        local playerId, field = math.floor(relative / 884), relative % 884
        -- Inventory business fields precede the edition-specific tail fields.
        if field > 866 then return nil end
        return layout.playerBase + 1 + playerId * layout.playerStride + field
    end
    relative = index - (1893070 + 1)
    if relative >= 0 and relative < 32 * 615 then
        return layout.organizationBase + 1 + relative
    end
    relative = index - 4515492
    if relative >= 0 and relative <= 15 * 84 then
        return layout.transactionBase + relative
    end
    relative = index - 1673847
    if relative >= 0 and relative <= 7 then
        return layout.supplyBaseline + relative
    end
    relative = index - 1965090
    if relative >= 0 and relative <= 50 then
        return layout.hangarPacking + relative
    end
    return nil
end

function SovereignBusinessInventory:ResolveInventorySaleLocal(scriptName, index)
    index = tonumber(index)
    if not index or index ~= index or index < 0 or index == rawget(math, "huge")
        or index ~= math.floor(index) then return nil end
    local layout = self:GetInventoryLayout()
    if not layout then return nil end
    if layout.edition == "Enhanced" then return index end
    if scriptName == "gb_biker_contraband_sell" then
        return layout.bikerLocals[index]
    end
    return nil
end

function SovereignBusinessInventory:HasInventoryMapping(feature)
    if feature ~= "freemode_globals" and feature ~= "transaction_layout"
        and feature ~= "sale_locals" then return false end
    local mapping = nil
    if type(SovereignOfficial) == "table"
        and type(SovereignOfficial.GetMapping) == "function" then
        local ok, value = pcall(SovereignOfficial.GetMapping, SovereignOfficial)
        if ok then mapping = value end
    end
    if type(mapping) ~= "table" then
        mapping = rawget(_G, "__SOVEREIGN_GAME_MAPPING")
    end
    -- A signed mapping may explicitly disable inventory for this build.
    -- Missing or partial metadata still uses the edition-specific static layout.
    if type(mapping) == "table" and mapping.inventoryDisabled == true then
        return false
    end
    if not self:GetInventoryLayout() then return false end
    return true
end

function SovereignBusinessInventory:GetLocalOrganizationState()
    local playerId = self:GetLocalPlayerId()
    local state = {
        playerId = playerId,
        bossId = -1,
        isBoss = false,
        valid = playerId ~= nil,
        role = "none",
        label = "No organization registered"
    }
    if playerId == nil then
        state.label = "Player state unavailable"
        state.error = "local_player_unavailable"
        return state
    end
    if not self:HasInventoryMapping("freemode_globals") then
        state.valid = false
        state.error = "inventory_mapping_unavailable"
        state.label = "Inventory layout unavailable on this version"
        return state
    end
    local organization = 1893070 + 1 + (playerId * 615) + 10
    local bossId = self:ReadGlobal(organization)
    if type(bossId) ~= "number" or bossId ~= bossId
        or bossId == rawget(math, "huge") or bossId == -rawget(math, "huge") then
        state.valid = false
        state.error = "organization_state_unavailable"
        state.label = "Organization state unavailable"
        return state
    end
    bossId = math.floor(bossId)
    -- freemode resets f_10 to -1 when the player leaves an organization.
    if bossId == -1 then return state end
    if bossId < 0 or bossId > 31 then
        state.valid = false
        state.error = "organization_state_unavailable"
        state.label = "Organization state unavailable"
        return state
    end

    state.bossId = bossId
    state.isBoss = bossId == playerId
    local bossOrganization = 1893070 + 1 + (bossId * 615) + 10
    local organizationType = self:ReadGlobal(bossOrganization + 433)
    if type(organizationType) ~= "number" or organizationType ~= organizationType
        or organizationType == rawget(math, "huge") or organizationType == -rawget(math, "huge") then
        state.valid = false
        state.error = "organization_state_unavailable"
        state.label = "Organization state unavailable"
        return state
    end
    organizationType = math.floor(organizationType)
    if organizationType == 1 then
        if state.isBoss then
            state.role, state.label = "mc_president", "MC President"
        else
            state.role, state.label = "mc_member", "MC member"
        end
        return state
    end
    local ceoFlags = self:ReadGlobal(
        1845347 + 1 + (bossId * 884) + 260 + 37
    )
    if type(ceoFlags) ~= "number" or ceoFlags ~= ceoFlags
        or ceoFlags == rawget(math, "huge") or ceoFlags == -rawget(math, "huge") then
        state.valid = false
        state.error = "organization_state_unavailable"
        state.label = "Organization state unavailable"
        return state
    end
    ceoFlags = math.floor(ceoFlags)
    local isCeoOrganization = (ceoFlags & (1 << 26)) ~= 0

    if state.isBoss then
        if isCeoOrganization then
            state.role, state.label = "ceo", "CEO"
        else
            state.role, state.label = "vip", "VIP"
        end
    elseif isCeoOrganization then
        state.role, state.label = "ceo_associate", "CEO organization member"
    else
        state.role, state.label = "vip_bodyguard", "VIP bodyguard"
    end
    return state
end

function SovereignBusinessInventory:IsLocalOrganizationTaskActive()
    -- Paired freemode _IS_FMMC_ACTIVE checks this player's f_185. An idle
    -- fmmc_launcher thread or another player's network script is not a task.
    local playerId = self:GetLocalPlayerId()
    if type(playerId) == "number" and playerId >= 0 and playerId <= 31
        and playerId == math.floor(playerId) then
        local ok, state = pcall(self.ReadGlobal, self, 1845347 + 1 + playerId * 884 + 185)
        if ok and type(state) == "number" and state == state and state ~= rawget(math, "huge")
            and state ~= -rawget(math, "huge") and state == math.floor(state) and state ~= 0 then
            return true
        end
    end
    if menu.nativeApis.NETWORK and type(menu.nativeApis.NETWORK.NETWORK_IS_ACTIVITY_SESSION) == "function" then
        local ok, active = pcall(menu.nativeApis.NETWORK.NETWORK_IS_ACTIVITY_SESSION)
        if ok and active == true then return true end
    end
    -- Cover controller startup before the player flag updates. A successful
    -- local count of zero is final; never fall back to network-wide queries.
    local function localControllerRunning(scriptName)
        if menu.nativeApis.SCRIPT and type(menu.nativeApis.SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH) == "function"
            and Utils and type(Utils.Joaat) == "function" then
            local hashOk, hash = pcall(Utils.Joaat, scriptName)
            if hashOk then
                local ok, count = pcall(menu.nativeApis.SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH, hash)
                if ok and type(count) == "number" and count == count and count >= 0
                    and count < rawget(math, "huge") and count == math.floor(count) then
                    return count > 0
                end
            end
        end
        if GTA and type(GTA.IsScriptRunning) == "function" then
            local ok, running = pcall(GTA.IsScriptRunning, scriptName)
            return ok and running == true
        end
        return false
    end
    return localControllerRunning("fm_mission_controller")
        or localControllerRunning("fm_mission_controller_2020")
        or localControllerRunning("fm_mission_controller_v3")
end

function SovereignBusinessInventory:ReadGlobalString(index)
    if not self:HasInventoryMapping("freemode_globals")
        or not ScriptGlobal or type(ScriptGlobal.GetString) ~= "function" then
        return nil
    end
    local resolved = self:ResolveInventoryGlobal(index)
    if resolved == nil then return nil end
    local ok, value = pcall(ScriptGlobal.GetString, resolved)
    if not ok or type(value) ~= "string" then return nil end
    return value
end

function SovereignBusinessInventory:WriteGlobalStringVerified(index, value)
    if not self:HasInventoryMapping("freemode_globals")
        or not ScriptGlobal or type(ScriptGlobal.SetString) ~= "function" then
        return false
    end
    local resolved = self:ResolveInventoryGlobal(index)
    local text = tostring(value or "")
    if resolved == nil or text == "" then return false end
    local ok, result = pcall(ScriptGlobal.SetString, resolved, text)
    if not ok or result == false then return false end
    if type(ScriptGlobal.GetString) ~= "function" then return true end
    for attempt = 1, 3 do
        local readOk, actual = pcall(ScriptGlobal.GetString, resolved)
        if readOk and tostring(actual or "") == text then return true end
        if attempt < 3 and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, 0)
        end
    end
    return false
end

function SovereignBusinessInventory:GetOrganizationRegistrationUuid(playerId)
    local organization = 1893070 + 1 + (playerId * 615) + 10
    local first = self:ReadGlobal(organization + 9)
    local second = self:ReadGlobal(organization + 10)
    if type(first) == "number" and type(second) == "number"
        and (first ~= 0 or second ~= 0) then
        return math.floor(first), math.floor(second), "existing"
    end
    local stats = menu.nativeApis and menu.nativeApis.STATS
    local getter = stats and stats.GET_BOSS_GOON_UUID
    if type(getter) ~= "function" and Natives and type(Natives.InvokeVoid) == "function" then
        getter = function(characterSlot, firstPtr, secondPtr)
            return Natives.InvokeVoid(0x6BC0ACD0673ACEBE, characterSlot, firstPtr, secondPtr)
        end
    end
    if type(getter) ~= "function" or not Memory
        or type(Memory.AllocInt) ~= "function"
        or type(Memory.ReadInt) ~= "function" then
        return nil, nil, "unavailable"
    end
    local slot = self:GetCharacterSlot()
    if slot ~= 0 and slot ~= 1 then slot = 0 end
    local firstPtr, secondPtr
    local ok, value1, value2 = pcall(function()
        firstPtr, secondPtr = Memory.AllocInt(), Memory.AllocInt()
        if not firstPtr or firstPtr == 0 or not secondPtr or secondPtr == 0 then
            return nil, nil
        end
        local callOk = getter(slot, firstPtr, secondPtr)
        if callOk == false then return nil, nil end
        return tonumber(Memory.ReadInt(firstPtr)), tonumber(Memory.ReadInt(secondPtr))
    end)
    if firstPtr and type(Memory.Free) == "function" then pcall(Memory.Free, firstPtr) end
    if secondPtr and type(Memory.Free) == "function" then pcall(Memory.Free, secondPtr) end
    if ok and type(value1) == "number" and type(value2) == "number" then
        return math.floor(value1), math.floor(value2), "stats"
    end
    return nil, nil, "unavailable"
end

function SovereignBusinessInventory:GetOrganizationRegistrationTimestamp()
    local cloud, available = self:CallOrganizationNative("NETWORK", "GET_CLOUD_TIME_AS_INT")
    cloud = available and tonumber(cloud) or nil
    if not cloud and os and type(os.time) == "function" then cloud = os.time() end
    if not cloud then return nil end
    return math.floor(cloud) - 43200
end

function SovereignBusinessInventory:GetOrganizationRegistrationLanguage()
    local language, available = self:CallOrganizationNative("LOCALIZATION", "LOCALIZATION_GET_SYSTEM_LANGUAGE")
    language = available and tonumber(language) or nil
    if not language or language < 0 or language > 31 then return nil end
    return math.floor(language)
end

function SovereignBusinessInventory:CallOrganizationNative(apiName, functionName, ...)
    local api = menu.nativeApis and menu.nativeApis[apiName]
    if type(api) ~= "table" then return nil, false end
    local okLookup, fn = pcall(function() return api[functionName] end)
    if not okLookup or type(fn) ~= "function" then return nil, false end
    local packed = table.pack(pcall(fn, ...))
    if not packed[1] then return nil, false end
    return packed[2], true
end

function SovereignBusinessInventory:TryDirectOrganizationRegistration(requiredRole)
    if self.directOrganizationAssist ~= true then return false, "organization_registration_unavailable" end
    if requiredRole ~= "ceo" and requiredRole ~= "mc_president" then
        return false, "organization_registration_unavailable"
    end
    if self:IsLocalOrganizationTaskActive() then return false, "task_active" end
    local playerId = self:GetLocalPlayerId()
    if type(playerId) ~= "number" or playerId < 0 or playerId > 31
        or playerId ~= math.floor(playerId) then
        return false, "local_player_unavailable"
    end
    local now = os.clock()
    if now < (tonumber(self.directOrganizationNextAt) or 0) then
        return false, "organization_registration_pending"
    end
    self.directOrganizationNextAt = now + 3.0

    -- Reconstruct freemode func_12223 locally. Cherax exposes no CEO/MC
    -- registration native, so this writes the complete local BOSS_GOON record
    -- without depending on an external menu action.
    local organization = 1893070 + 1 + (playerId * 615) + 10
    local isMc = requiredRole == "mc_president"
    local organizationType = isMc and 1 or 0
    local timestamp = self:GetOrganizationRegistrationTimestamp()
    local language = self:GetOrganizationRegistrationLanguage()
    local uuid1, uuid2, uuidSource = self:GetOrganizationRegistrationUuid(playerId)
    local flagsIndex = 1845347 + 1 + (playerId * 884) + 260 + 37
    local flags = self:ReadGlobal(flagsIndex)
    if type(flags) ~= "number" then flags = 0 end
    flags = math.floor(flags)
    local ceoMask = (1 << 26)
    local hadCeoFlag = (flags & ceoMask) ~= 0
    -- freemode func_2921() selects bossType 2 when this flag was already
    -- present; MC always uses 3 and a fresh CEO uses 1.
    local bossType = isMc and 3 or (hadCeoFlag and 2 or 1)
    if isMc then flags = flags & ~ceoMask else flags = flags | ceoMask end

    local writes = {
        {"bossId", organization, playerId},
        {"organizationType", organization + 433, organizationType},
        {"organizationTypeMirror", organization + 470, organizationType},
        {"bossType", organization + 471, bossType},
        {"organizationFlags", flagsIndex, flags},
        {"organizationStart", organization + 1, timestamp},
        {"organizationState25", organization + 25, -1},
        {"organizationState26", organization + 26, -1}
    }
    if uuid1 ~= nil and uuid2 ~= nil then
        writes[#writes + 1] = {"bossUuid0", organization + 9, uuid1}
        writes[#writes + 1] = {"bossUuid1", organization + 10, uuid2}
    end
    if language ~= nil then writes[#writes + 1] = {"language", organization + 122, language} end

    local failed = {}
    for _, item in ipairs(writes) do
        if not self:WriteGlobalVerified(item[2], item[3], {attempts = 3, retryDelay = 0}) then
            failed[#failed + 1] = item[1]
        end
    end

    -- These two controller fields are written by func_12223 after the
    -- BOSS_GOON record. They are optional because older Legacy layouts do not
    -- expose the corresponding indices through the inventory map.
    local controllerWrites = {
        {2733326 + 3989 + 227, -1},
        {2733326 + 3989 + 342, 1}
    }
    for _, item in ipairs(controllerWrites) do
        self:WriteGlobalVerified(item[1], item[2], {attempts = 2, retryDelay = 0})
    end
    local networkApi = menu.nativeApis and menu.nativeApis.NETWORK
    if networkApi and type(networkApi.NETWORK_SET_SCRIPT_CONTROLLING_TEAMS) == "function" then
        pcall(networkApi.NETWORK_SET_SCRIPT_CONTROLLING_TEAMS, 1)
    end

    local name
    if not isMc then
        local localized, available = self:CallOrganizationNative(
            "HUD", "GET_FILENAME_FOR_AUDIO_CONVERSATION", "GB_REST_ACC"
        )
        if available and type(localized) == "string" and localized ~= "" then
            name = localized
        end
    end
    name = name or (isMc and "Motorcycle Club" or "Organization")
    local nameWritten = self:WriteGlobalStringVerified(organization + 106, name)
    local crewNameWritten = self:WriteGlobalStringVerified(organization + 343, name)
    local chatNameWritten = self:WriteGlobalStringVerified(organization + 359, name)
    if timestamp == nil then failed[#failed + 1] = "cloudTime" end
    if #failed > 0 then
        Logger:Info("SovereignInventory", string.format(
            "direct freemode organization write failed role=%s fields=%s uuid=%s",
            requiredRole, table.concat(failed, ","), tostring(uuidSource)
        ))
        return false, "organization_registration_write_failed"
    end
    if not nameWritten or not crewNameWritten or not chatNameWritten then
        Logger:Info("SovereignInventory", "one or more organization name fields were unavailable; numeric freemode fields were written")
    end

    local samples = (Script and type(Script.Yield) == "function") and 10 or 1
    for _ = 1, samples do
        if Script and type(Script.Yield) == "function" then pcall(Script.Yield, 100) end
        if self:IsLocalOrganizationTaskActive() then return false, "task_active" end
        local state = self:GetLocalOrganizationState()
        if state.valid == true and state.role == requiredRole and state.bossId == playerId then
            state.registrationSource = "freemode_global_reconstruction"
            Logger:Info("SovereignInventory", string.format(
                "direct freemode organization state converged role=%s uuid=%s",
                requiredRole, tostring(uuidSource)
            ))
            return true, state
        end
    end
    Logger:Info("SovereignInventory", "direct freemode organization fields written but state did not converge role=" .. requiredRole)
    return false, "organization_registration_pending"
end

function SovereignBusinessInventory:EnsureOrganizationRole(requiredRole)
    local organization = self:GetLocalOrganizationState()
    if organization.valid == true and organization.role == requiredRole then return true, organization end
    if self.autoOrganizationAssist ~= true then
        return false, requiredRole == "ceo" and "ceo_required" or "mc_president_required"
    end
    local directOk, directState = self:TryDirectOrganizationRegistration(requiredRole)
    if directOk then return true, directState end
    if directState == "task_active" or directState == "organization_registration_unavailable"
        or directState == "organization_registration_write_failed"
        or directState == "organization_registration_pending" then
        return false, directState
    end
    Logger:Info("SovereignInventory", "organization registration did not converge role=" .. requiredRole)
    return false, requiredRole == "ceo" and "ceo_required" or "mc_president_required"
end

function SovereignBusinessInventory:RegisterOrganizationNow(requiredRole)
    self.autoOrganizationAssist = true
    self.directOrganizationAssist = true
    self.directOrganizationNextAt = 0
    local ok, state = self:TryDirectOrganizationRegistration(requiredRole)
    if ok then
        self:Notify("Automatically registered as" .. (requiredRole == "ceo" and "CEO" or "MC President"), "success")
        return true
    end
    if state == "task_active" then
        self:Notify("Organization will not change during a mission", "warning")
        return false
    end
    if state == "organization_registration_write_failed" then
        self:Notify("Direct freemode organization state write failed", "error")
    elseif state == "organization_registration_unavailable" then
        self:Notify("Direct freemode organization registration is unavailable", "warning")
    else
        self:Notify("Organization registration is pending. Try again later", "warning")
    end
    return false
end

function SovereignBusinessInventory:IsLocalCEO()
    return self:GetLocalOrganizationState().role == "ceo"
end

function SovereignBusinessInventory:IsLocalMCPresident()
    return self:GetLocalOrganizationState().role == "mc_president"
end

function SovereignBusinessInventory:IsLocalOrganizationBoss()
    return self:GetLocalOrganizationState().isBoss == true
end

function SovereignBusinessInventory:IsWarehouseOwned(definition)
    if type(definition) ~= "table" then return false end
    local warehouseType = self:ReadWarehouseType(definition)
    -- func_626 accepts warehouse types 1..22; zero is the empty slot.
    return warehouseType >= 1 and warehouseType <= 22
end

function SovereignBusinessInventory:GetOwnedWarehouseCount()
    local count = 0
    for _, definition in ipairs(self.warehouseDefinitions or {}) do
        if self:IsWarehouseOwned(definition) then count = count + 1 end
    end
    return count
end

function SovereignBusinessInventory:CheckWarehouseAccess(index)
    local organization = self:GetLocalOrganizationState()
    if organization.valid ~= true then
        return false, organization.error or "local_player_unavailable"
    end
    if organization.role ~= "ceo" then
        local roleOk, roleOrReason = self:EnsureOrganizationRole("ceo")
        if not roleOk then return false, roleOrReason end
        organization = roleOrReason
    end
    local definitions = self.warehouseDefinitions or {}
    -- A selected warehouse must not depend on unrelated slots being readable.
    if index ~= nil then
        local normalized = math.floor(tonumber(index) or 0)
        local definition = definitions[normalized]
        if not definition then return false, "invalid_request" end
        local typeGlobal = self:GetWarehouseRuntimeTypeGlobal(definition.index)
        local warehouseType = typeGlobal and self:ReadGlobal(typeGlobal) or nil
        if type(warehouseType) ~= "number" then
            return false, "warehouse_state_unavailable"
        end
        if warehouseType < 1 or warehouseType > 22 then
            return false, "warehouse_not_owned"
        end
        return true
    end
    local ownedCount = 0
    local unreadable = false
    for _, definition in ipairs(definitions) do
        local typeGlobal = self:GetWarehouseRuntimeTypeGlobal(definition.index)
        local warehouseType = typeGlobal and self:ReadGlobal(typeGlobal) or nil
        if type(warehouseType) ~= "number" then
            unreadable = true
        else
            warehouseType = math.floor(warehouseType)
            if warehouseType >= 1 and warehouseType <= 22 then ownedCount = ownedCount + 1 end
        end
    end
    if ownedCount == 0 then
        return false, unreadable and "warehouse_state_unavailable" or "warehouse_required"
    end
    return true
end

function SovereignBusinessInventory:NotifyWarehouseAccessError(reason)
    local messages = {
        local_player_unavailable = "Player is not ready",
        organization_state_unavailable = "Organization is not ready",
        inventory_mapping_unavailable = "Office warehouses are not supported on this version",
        warehouse_state_unavailable = "Office warehouse unavailable",
        ceo_required = "Office warehouse features require a CEO",
        organization_registration_unavailable = "Direct freemode organization registration is unavailable",
        organization_registration_write_failed = "Direct freemode organization state write failed",
        organization_registration_pending = "Organization registration is pending. Try again later",
        warehouse_required = "No purchased office warehouse found",
        warehouse_not_owned = "Selected office warehouse has not been purchased",
        invalid_request = "Selected office warehouse could not be read"
    }
    self:Notify(messages[tostring(reason)] or "Office warehouse requirements are not met", "warning")
end

function SovereignBusinessInventory:ReadWarehouseProduct(definition, characterSlot, playerId)
    if type(definition) ~= "table" then return nil end
    local runtimeGlobal = self:GetWarehouseRuntimeProductGlobal(definition.index, playerId)
    local liveValue = runtimeGlobal and self:ReadGlobal(runtimeGlobal) or nil
    -- The live player cache is authoritative when available, including zero.
    if type(liveValue) == "number" then return math.max(0, math.floor(liveValue)) end
    local statIndex = tonumber(definition.productIndex)
    local indexedValue = nil
    if statIndex then
        local values = self:ReadIndices({math.floor(statIndex)}, characterSlot)
        indexedValue = values and values[math.floor(statIndex)]
        if type(indexedValue) == "number" then return math.max(0, math.floor(indexedValue)) end
    end
    return nil
end

function SovereignBusinessInventory:ReadWarehousePersistentProduct(definition, characterSlot)
    if type(definition) ~= "table" then return nil end
    local statIndex = tonumber(definition.productIndex)
    if statIndex then
        local values = self:ReadIndices({math.floor(statIndex)}, characterSlot)
        local indexedValue = values and values[math.floor(statIndex)]
        if type(indexedValue) == "number" then return math.max(0, math.floor(indexedValue)) end
    end
    return nil
end

function SovereignBusinessInventory:ReadPackedIntStat(index, slot)
    local packedIndex = math.floor(tonumber(index) or -1)
    if packedIndex < 0 then return nil end
    local characterSlot = slot
    if characterSlot == nil then characterSlot = self:GetCharacterSlot() end
    characterSlot = tonumber(characterSlot)
    if type(characterSlot) ~= "number" or (characterSlot ~= 0 and characterSlot ~= 1) then
        return nil
    end
    characterSlot = math.floor(characterSlot)
    if menu.nativeApis.STATS and type(menu.nativeApis.STATS.GET_PACKED_STAT_INT_CODE) == "function" then
        local ok, value = pcall(menu.nativeApis.STATS.GET_PACKED_STAT_INT_CODE, packedIndex, characterSlot)
        if ok and type(value) == "number" then
            return math.floor(value)
        end
    end
    -- Keep a direct hash fallback for runtimes whose generated natives table is
    -- older than the current stat native database.
    if Natives and type(Natives.InvokeInt) == "function" then
        local ok, value = pcall(
            Natives.InvokeInt, 0x0BC900A6FE73770C, packedIndex, characterSlot
        )
        if ok and type(value) == "number" then
            return math.floor(value)
        end
    end
    return nil
end

function SovereignBusinessInventory:WritePackedIntStat(index, value, slot)
    local packedIndex = tonumber(index)
    local target = tonumber(value)
    local characterSlot = slot
    if type(packedIndex) ~= "number" or packedIndex ~= packedIndex
        or type(target) ~= "number" or target ~= target then
        return false
    end
    packedIndex = math.floor(packedIndex)
    target = math.floor(target)
    if packedIndex < 0 or target < 0 or target > 255 then return false end
    if characterSlot == nil then characterSlot = self:GetCharacterSlot() end
    characterSlot = tonumber(characterSlot)
    if type(characterSlot) ~= "number"
        or (characterSlot ~= 0 and characterSlot ~= 1) then
        return false
    end
    characterSlot = math.floor(characterSlot)

    local attempted = false
    if menu.nativeApis.STATS and type(menu.nativeApis.STATS.SET_PACKED_STAT_INT_CODE) == "function" then
        local ok = pcall(menu.nativeApis.STATS.SET_PACKED_STAT_INT_CODE, packedIndex, target, characterSlot)
        attempted = ok
    end
    local actual = attempted and self:ReadPackedIntStat(packedIndex, characterSlot) or nil
    if actual == target then return true end

    -- Keep a direct hash fallback for runtimes whose generated natives table is
    -- older than the current stat native database.
    if Natives and type(Natives.InvokeVoid) == "function" then
        local ok = pcall(
            Natives.InvokeVoid, 0x1581503AE529CD2E,
            packedIndex, target, characterSlot
        )
        if ok and self:ReadPackedIntStat(packedIndex, characterSlot) == target then
            return true
        end
    end
    return false
end

function SovereignBusinessInventory:ReadPackedBoolStat(index, slot)
    local packedIndex = tonumber(index)
    local characterSlot = slot
    if type(packedIndex) ~= "number" or packedIndex ~= packedIndex then return nil end
    packedIndex = math.floor(packedIndex)
    if packedIndex < 0 then return nil end
    if characterSlot == nil then characterSlot = self:GetCharacterSlot() end
    characterSlot = tonumber(characterSlot)
    if type(characterSlot) ~= "number"
        or (characterSlot ~= 0 and characterSlot ~= 1) then
        return nil
    end
    characterSlot = math.floor(characterSlot)
    if menu.nativeApis.STATS and type(menu.nativeApis.STATS.GET_PACKED_STAT_BOOL_CODE) == "function" then
        local ok, value = pcall(menu.nativeApis.STATS.GET_PACKED_STAT_BOOL_CODE, packedIndex, characterSlot)
        if ok and type(value) == "boolean" then return value end
    end
    if Natives and type(Natives.InvokeBool) == "function" then
        local ok, value = pcall(
            Natives.InvokeBool, 0xDA7EBFC49AE3F1B0, packedIndex, characterSlot
        )
        if ok and type(value) == "boolean" then return value end
    end
    return nil
end

function SovereignBusinessInventory:WritePackedBoolStat(index, value, slot)
    local packedIndex = tonumber(index)
    local characterSlot = slot
    if type(packedIndex) ~= "number" or packedIndex ~= packedIndex
        or type(value) ~= "boolean" then
        return false
    end
    packedIndex = math.floor(packedIndex)
    if packedIndex < 0 then return false end
    if characterSlot == nil then characterSlot = self:GetCharacterSlot() end
    characterSlot = tonumber(characterSlot)
    if type(characterSlot) ~= "number"
        or (characterSlot ~= 0 and characterSlot ~= 1) then
        return false
    end
    characterSlot = math.floor(characterSlot)
    if menu.nativeApis.STATS and type(menu.nativeApis.STATS.SET_PACKED_STAT_BOOL_CODE) == "function" then
        local ok = pcall(menu.nativeApis.STATS.SET_PACKED_STAT_BOOL_CODE, packedIndex, value, characterSlot)
        if ok and self:ReadPackedBoolStat(packedIndex, characterSlot) == value then
            return true
        end
    end
    if Natives and type(Natives.InvokeVoid) == "function" then
        local ok = pcall(
            Natives.InvokeVoid, 0xDB8A58AEAA67CD07,
            packedIndex, value, characterSlot
        )
        if ok and self:ReadPackedBoolStat(packedIndex, characterSlot) == value then
            return true
        end
    end
    return false
end

function SovereignBusinessInventory:WriteNamedStat(name, value)
    local hash = self:GetNamedStatHash(name)
    if hash == 0 then return false end
    local target = math.floor(tonumber(value) or 0)
    local wrote = false
    if Stats and type(Stats.SetInt) == "function" then
        local ok, result = pcall(Stats.SetInt, hash, target)
        wrote = ok and result == true
    end
    if menu.nativeApis.STATS and type(menu.nativeApis.STATS.STAT_SET_INT) == "function" then
        local ok, result = pcall(menu.nativeApis.STATS.STAT_SET_INT, hash, target, true)
        wrote = wrote or (ok and result == true)
    end
    return wrote
end

function SovereignBusinessInventory:ReadGlobal(index)
    if not self:HasInventoryMapping("freemode_globals") then return nil end
    if not ScriptGlobal or type(ScriptGlobal.GetInt) ~= "function" then
        return nil
    end
    local resolved = self:ResolveInventoryGlobal(index)
    if resolved == nil then return nil end
    local ok, value = pcall(ScriptGlobal.GetInt, resolved)
    if ok and type(value) == "number" and value == value then
        return value
    end
    return nil
end

-- These freemode globals are the game's own transaction-alert latches. They
-- are read-only here: clearing them would hide a rejected request and could
-- make the sale state look successful when the server did not accept it.
function SovereignBusinessInventory:ReadSaleTransactionAlertSnapshot()
    local snapshot = {
        supported = true,
        readable = true,
        anyActive = false,
        activeName = nil
    }
    local definitions = {
        {name = "failed", index = 4516902},
        {name = "blocked", index = 4516903},
        {name = "blocked_consume", index = 4516904}
    }
    local readableCount = 0
    for _, definition in ipairs(definitions) do
        local value = self:ReadGlobal(definition.index)
        if type(value) ~= "number" then
            snapshot.readable = false
        else
            readableCount = readableCount + 1
            value = math.floor(value)
            snapshot[definition.name] = value
            if value == -1 then
                snapshot.anyActive = true
                snapshot.activeName = snapshot.activeName or definition.name
            end
        end
    end
    -- The Legacy layout does not expose these Enhanced freemode alert
    -- latches.  Treat that as an unsupported observer, not as a broken
    -- transaction state; partial/missing Enhanced mappings still fail closed.
    local layout = nil
    if type(self.GetInventoryLayout) == "function" then
        local ok, value = pcall(self.GetInventoryLayout, self)
        if ok then layout = value end
    end
    if type(layout) ~= "table" and type(Utils1) == "table"
        and type(Utils1.edition) == "function" then
        local ok, edition = pcall(Utils1.edition, Utils1)
        if ok then layout = {edition = edition} end
    end
    if readableCount == 0 and type(layout) == "table"
        and layout.edition == "Legacy" then
        snapshot.supported = false
    end
    return snapshot
end

function SovereignBusinessInventory:GetNewSaleTransactionAlert(beforeSnapshot)
    local current = self:ReadSaleTransactionAlertSnapshot()
    if type(current) ~= "table" or current.supported == false
        or current.readable ~= true
        or current.anyActive ~= true then
        return nil, current
    end
    if type(beforeSnapshot) ~= "table" or beforeSnapshot.supported == false
        or beforeSnapshot.readable ~= true then
        return current.activeName or "unknown", current
    end
    for _, name in ipairs({"failed", "blocked", "blocked_consume"}) do
        if current[name] == -1 and beforeSnapshot[name] ~= -1 then
            return name, current
        end
    end
    return nil, current
end

function SovereignBusinessInventory:WriteGlobal(index, value)
    if not self:HasInventoryMapping("freemode_globals") then return false end
    if not ScriptGlobal or type(ScriptGlobal.SetInt) ~= "function" then
        return false
    end
    local normalizedIndex = self:ResolveInventoryGlobal(index)
    local normalizedValue = self:NormalizeSignedInt32(value)
    if type(normalizedIndex) ~= "number" or normalizedIndex ~= normalizedIndex
        or normalizedValue == nil then
        return false
    end
    local ok, result = pcall(
        ScriptGlobal.SetInt,
        math.floor(normalizedIndex),
        math.floor(normalizedValue)
    )
    return ok and result ~= false
end

function SovereignBusinessInventory:WriteStatByIndex(index, value, characterSlot)
    if (not Stats or type(Stats.SetInt) ~= "function")
        and (not menu.nativeApis.STATS or type(menu.nativeApis.STATS.STAT_SET_INT) ~= "function") then
        return false
    end
    local wrote = false
    local target = math.floor(tonumber(value) or 0)
    for _, hash in ipairs(self:GetStatHashCandidates(index, characterSlot)) do
        if Stats and type(Stats.SetInt) == "function" then
            local ok, result = pcall(Stats.SetInt, hash, target)
            wrote = wrote or (ok and result == true)
        end
        if menu.nativeApis.STATS and type(menu.nativeApis.STATS.STAT_SET_INT) == "function" then
            local ok, result = pcall(menu.nativeApis.STATS.STAT_SET_INT, hash, target, true)
            wrote = wrote or (ok and result == true)
        end
    end
    return wrote
end

function SovereignBusinessInventory:SaveStats()
    if not menu.nativeApis.STATS or type(menu.nativeApis.STATS.STAT_SAVE) ~= "function" then
        return false
    end
    local ok, result = pcall(menu.nativeApis.STATS.STAT_SAVE, 0, false, 3, false)
    return ok and result ~= false
end

function SovereignBusinessInventory:WriteGlobalVerified(index, value, writeOptions)
    local normalizedIndex = tonumber(index)
    local normalizedValue = self:NormalizeSignedInt32(value)
    if type(normalizedIndex) ~= "number" or normalizedIndex ~= normalizedIndex
        or normalizedValue == nil then
        return false
    end
    normalizedIndex = math.floor(normalizedIndex)
    if not self:WriteGlobal(normalizedIndex, normalizedValue) then return false end
    writeOptions = type(writeOptions) == "table" and writeOptions or {}
    local attempts = math.floor(tonumber(writeOptions.attempts) or 3)
    attempts = math.max(1, math.min(8, attempts))
    local retryDelay = math.floor(tonumber(writeOptions.retryDelay) or 0)
    retryDelay = math.max(0, math.min(250, retryDelay))
    -- Global writes can become visible one frame after the native returns.
    -- Read back a few times so a propagation delay is not reported as a
    -- failed write, while keeping the operation bounded and synchronous.
    for attempt = 1, attempts do
        local actual = self:ReadGlobal(normalizedIndex)
        if self:NormalizeSignedInt32(actual) == normalizedValue then
            return true
        end
        if attempt < attempts and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, retryDelay)
        end
    end
    return false
end

function SovereignBusinessInventory:WriteTransactionGlobalVerified(index, value)
    if not self:HasInventoryMapping("transaction_layout") then
        return false
    end
    return self:WriteGlobalVerified(index, value, {
        attempts = 4,
        retryDelay = 25
    })
end

function SovereignBusinessInventory:GetWarehouseCrateStat(definition, crateIndex, characterSlot)
    if type(definition) ~= "table" then return nil end
    local warehouseSlot = math.floor(tonumber(definition.index) or -1)
    local crate = math.floor(tonumber(crateIndex) or -1)
    if warehouseSlot < 0 or warehouseSlot > 4 or crate < 0 or crate > 110 then return nil end
    -- Five 111-byte slot ranges occupy WAREHOUSE_CRATES0..69. The last
    -- address is flat 554 -> word 69, bit offset 16.
    local flatIndex = (warehouseSlot * 111) + crate
    if characterSlot == nil then characterSlot = self:GetCharacterSlot() end
    characterSlot = tonumber(characterSlot)
    if characterSlot == nil then return nil end
    characterSlot = math.floor(characterSlot)
    if characterSlot ~= 0 and characterSlot ~= 1 then return nil end
    local statName = "MP" .. tostring(characterSlot)
        .. "_WAREHOUSE_CRATES" .. tostring(math.floor(flatIndex / 8))
    local hash = self:GetNamedStatHash(statName)
    if hash == 0 then return nil end
    return hash, 8 * (flatIndex % 8), statName
end

function SovereignBusinessInventory:ReadWarehouseCrateCode(definition, crateIndex, characterSlot)
    if not menu.nativeApis.STATS or type(menu.nativeApis.STATS.STAT_GET_MASKED_INT) ~= "function"
        or not Memory or type(Memory.AllocInt) ~= "function"
        or type(Memory.ReadInt) ~= "function" then
        return nil
    end
    local hash, bitOffset = self:GetWarehouseCrateStat(
        definition, crateIndex, characterSlot
    )
    if not hash then return nil end
    local ptr = nil
    local ok, value = pcall(function()
        ptr = Memory.AllocInt()
        if not ptr or ptr == 0
            or not menu.nativeApis.STATS.STAT_GET_MASKED_INT(hash, ptr, bitOffset, 8, -1) then
            return nil
        end
        return tonumber(Memory.ReadInt(ptr))
    end)
    if ptr and type(Memory.Free) == "function" then pcall(Memory.Free, ptr) end
    if not ok or type(value) ~= "number" then return nil end
    return math.max(0, math.min(255, math.floor(value)))
end

function SovereignBusinessInventory:ProbeWarehousePacking(
    definition, targetCount, characterSlot, playerId
)
    local capacity = self:GetWarehouseCapacity(definition, playerId)
    if capacity <= 0 then return false end
    local target = math.max(0, math.min(capacity, math.floor(tonumber(targetCount) or 0)))
    for crateIndex = 0, target - 1 do
        if self:ReadWarehouseCrateCode(definition, crateIndex, characterSlot) == nil then
            return false
        end
    end
    return true
end

function SovereignBusinessInventory:GetSaleKeyForRefill(request)
    if type(request) ~= "table" then return nil end
    local index = math.floor(tonumber(request.index) or 0)
    if request.kind == "warehouse" and index >= 1 and index <= 5 then
        return "warehouse_" .. tostring(index)
    end
    if (request.kind == "factory" or request.kind == "factory_product")
        and index >= 1 and index <= 5 then
        return "biker_" .. tostring(index - 1)
    end
    return nil
end

function SovereignBusinessInventory:CheckRefillAccess(request)
    if type(request) ~= "table" then return false, "invalid_request" end
    -- Enhanced has no one-shot server recipe for manufacturing finished stock.
    -- Normal production pairs +1 product with a material consumption delta.
    if request.kind == "factory_product" then
        return false, "factory_product_recipe_unverified"
    end
    local saleKey = self:GetSaleKeyForRefill(request)
    if saleKey and self.saleQuarantine and self.saleQuarantine[saleKey] then
        return false, "sale_manual_review_locked"
    end
    local requestKey = self:GetRefillRequestKey(request)
    if requestKey and self.refillQuarantine
        and self.refillQuarantine[requestKey] then
        return false, "refill_quarantine_locked"
    end
    if requestKey and self.refillRejectedKeys
        and self.refillRejectedKeys[requestKey] then
        return false, "refill_rejected_locked"
    end
    local pendingOk = self:ReconcilePendingRefill(request)
    if not pendingOk then return false, "refill_pending_verification" end
    local organization = self:GetLocalOrganizationState()
    local allowRegistration = self.autoOrganizationAssist == true
    if organization.valid ~= true and not allowRegistration then
        return false, organization.error or "local_player_unavailable"
    end
    if request.kind == "warehouse" then
        if organization.valid ~= true or organization.role ~= "ceo" then
            if not allowRegistration then return false, "ceo_required" end
            local roleOk, roleOrReason = self:EnsureOrganizationRole("ceo")
            if not roleOk then return false, roleOrReason end
            organization = roleOrReason
        end
        return self:CheckWarehouseAccess(tonumber(request.index))
    end
    if request.kind == "factory" or request.kind == "factory_product" then
        local index = math.floor(tonumber(request.index) or 0)
        if index < 1 or index > #self.factoryDefinitions then
            return false, "invalid_request"
        end
        if index <= 5 and (organization.valid ~= true or organization.role ~= "mc_president") then
            if not allowRegistration then return false, "mc_president_required" end
            local roleOk, roleOrReason = self:EnsureOrganizationRole("mc_president")
            if not roleOk then return false, roleOrReason end
            organization = roleOrReason
        end
        if index >= 6 and (organization.valid ~= true or organization.isBoss ~= true) then
            if not allowRegistration then return false, "organization_boss_required" end
            local roleOk, roleOrReason = self:EnsureOrganizationRole("ceo")
            if not roleOk then return false, roleOrReason end
            organization = roleOrReason
        end
        if index >= 6 and organization.isBoss ~= true then
            return false, "organization_boss_required"
        end
        return true
    end
    if request.kind == "nightclub" or request.kind == "hangar" then
        if organization.valid ~= true or organization.isBoss ~= true then
            if not allowRegistration then return false, "organization_boss_required" end
            local roleOk, roleOrReason = self:EnsureOrganizationRole("ceo")
            if not roleOk then return false, roleOrReason end
            organization = roleOrReason
        end
        if organization.isBoss ~= true then
            return false, "organization_boss_required"
        end
        return true
    end
    return false, "invalid_request"
end

