function SovereignBusinessInventory:WriteWarehouseCrateCode(
    definition, crateIndex, crateCode, save, characterSlot, identityGuard
)
    if not menu.nativeApis.STATS or type(menu.nativeApis.STATS.STAT_SET_MASKED_INT) ~= "function" then return false end
    local hash, bitOffset = self:GetWarehouseCrateStat(
        definition, crateIndex, characterSlot
    )
    if not hash then return false end
    local function guardCurrent()
        if type(identityGuard) ~= "function" then return true end
        local ok, allowed = pcall(identityGuard)
        return ok and allowed == true
    end
    local target = math.max(0, math.min(255, math.floor(tonumber(crateCode) or 0)))
    for attempt = 1, 3 do
        if not guardCurrent() then return false, "refill_identity_changed" end
        local ok, result = pcall(
            menu.nativeApis.STATS.STAT_SET_MASKED_INT,
            hash,
            target,
            bitOffset,
            8,
            save ~= false
        )
        if ok and result ~= false
            and self:ReadWarehouseCrateCode(definition, crateIndex, characterSlot) == target then
            return true
        end
        if attempt < 3 and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, 0)
        end
    end
    return false
end

function SovereignBusinessInventory:IsWarehouseSpecialCrateCode(crateCode)
    local code = math.floor(tonumber(crateCode) or 0)
    return code >= 23 and code <= 28
end

function SovereignBusinessInventory:GetWarehouseCrateModel(crateCode)
    local code = math.floor(tonumber(crateCode) or 0)
    return self.warehouseCrateModels and self.warehouseCrateModels[code] or nil
end

function SovereignBusinessInventory:IsWarehouseBigCratePosition(warehouseType, crateIndex)
    if math.floor(tonumber(self.warehouseCapacityByType[warehouseType]) or 0) ~= 111 then
        return false
    end
    local position = math.floor(tonumber(crateIndex) or -1)
    return (position >= 14 and position <= 20)
        or (position >= 35 and position <= 41)
        or (position >= 56 and position <= 62)
        or (position >= 77 and position <= 83)
        or (position >= 90 and position <= 92)
        or (position >= 99 and position <= 101)
        or position == 108
end

function SovereignBusinessInventory:IsWarehouseSpecialDisplayPosition(warehouseType, crateIndex)
    if math.floor(tonumber(self.warehouseCapacityByType[warehouseType]) or 0) ~= 111 then
        return true
    end
    local position = math.floor(tonumber(crateIndex) or -1)
    return position >= 0 and (
        position <= 6
        or (position >= 21 and position <= 27)
        or (position >= 42 and position <= 48)
        or (position >= 63 and position <= 69)
        or (position >= 84 and position <= 86)
        or (position >= 93 and position <= 95)
        or (position >= 102 and position <= 104)
    )
end

function SovereignBusinessInventory:ChooseWarehouseCrateCode(
    definition, crateIndex, cargoSelection, warehouseType
)
    local cargoCount = #self.warehouseCargoTypes
    if cargoCount == 0 then return nil end
    local selection = math.floor(tonumber(cargoSelection) or 1)
    local seed = math.max(0, math.floor(tonumber(crateIndex) or 0))
        + (math.max(0, math.floor(tonumber(definition.index) or 0)) * 17)
    local cargoIndex = selection <= 1 and ((seed % cargoCount) + 1)
        or math.max(1, math.min(cargoCount, selection - 1))
    local cargo = self.warehouseCargoTypes[cargoIndex]
    if not cargo then return nil end

    warehouseType = math.floor(tonumber(warehouseType) or self:ReadWarehouseType(definition))
    local forcedBig = self:IsWarehouseBigCratePosition(warehouseType, crateIndex)
    -- Keep the size and closed/open rolls independent, as freemode does. The
    -- previous parity coupling made several valid variants unreachable (for
    -- example small closed crates and big open crates).
    local useBig = forcedBig or (seed % 2 == 1)
    local pool = useBig and cargo.bigCodes or cargo.smallCodes
    local closedRoll = math.floor(seed / 2) % 4
    local useClosed = cargo.closedCodes and (
        (forcedBig and closedRoll ~= 0)
        or (not forcedBig and closedRoll % 2 == 1)
    )
    if useClosed then
        pool = useBig and cargo.closedBigCodes or cargo.closedCodes
    end
    if type(pool) ~= "table" or #pool == 0 then return nil end
    -- Use a slower roll for the model index so a two-model pool is not
    -- accidentally locked to its first entry by the size parity.
    return pool[(math.floor(seed / 8) % #pool) + 1]
end

function SovereignBusinessInventory:GetWarehouseRegisteredSpecialCodes(
    definition, targetCount, characterSlot, playerId
)
    if type(definition) ~= "table" then return {} end
    local specialIndex = math.floor(tonumber(definition.specialProductIndex)
        or (3649 + math.floor(tonumber(definition.index) or 0)))
    -- 3649..3653 are per-warehouse special-cargo count stats. The two
    -- six-entry special registries are packed-int stats and must use
    -- GET_PACKED_STAT_INT_CODE.
    local values = self:ReadIndices({specialIndex}, characterSlot) or {}
    if type(values[specialIndex]) ~= "number" then
        return nil, "special_count_read_failed"
    end
    local registeredCount = math.floor(values[specialIndex])
    if registeredCount < 0 or registeredCount > 6 then
        return nil, "special_count_invalid"
    end
    local warehouseType = self:ReadWarehouseType(definition, playerId)
    if warehouseType < 1 or warehouseType > 22 then
        return nil, "warehouse_type_invalid"
    end
    local result = {}
    if characterSlot == nil then characterSlot = self:GetCharacterSlot() end
    if characterSlot == nil then return nil, "character_slot_unavailable" end
    local target = math.max(0, math.floor(tonumber(targetCount) or 0))
    if registeredCount > target then return nil, "special_count_exceeds_stock" end
    local limit = registeredCount
    for registryIndex = 0, 5 do
        local specialType = self:ReadPackedIntStat(7642 + registryIndex, characterSlot)
        local ownerType = self:ReadPackedIntStat(7648 + registryIndex, characterSlot)
        if specialType == nil or ownerType == nil then
            return nil, "special_registry_read_failed"
        end
        specialType = math.floor(tonumber(specialType) or 0)
        ownerType = math.floor(tonumber(ownerType) or 0)
        local crateCode = 22 + specialType
        if specialType < 0 or specialType > 6 or ownerType < 0 or ownerType > 22
            or (specialType ~= 0 and ownerType == 0) then
            return nil, "special_registry_invalid"
        end
        -- Empty type slots may retain an old owner value until freemode's next
        -- registry compaction. Only a non-zero type constitutes cargo.
        if ownerType == warehouseType and specialType >= 1 then
            result[#result + 1] = crateCode
            -- A special type may occupy multiple registry slots. Keep each
            -- matching slot so a two/three-box special cargo is reconstructed
            -- with the same multiplicity instead of being collapsed to one.
        end
    end
    if #result ~= limit then return nil, "special_registry_incomplete" end
    return result, nil
end

function SovereignBusinessInventory:BuildWarehousePackingPlan(
    definition, previousCount, targetCount, cargoSelection, repairExisting,
    characterSlot, playerId
)
    local capacity = self:GetWarehouseCapacity(definition, playerId)
    if capacity <= 0 then return nil, "warehouse_not_owned" end
    local previous = math.max(0, math.min(capacity, math.floor(tonumber(previousCount) or 0)))
    local target = math.max(0, math.min(capacity, math.floor(tonumber(targetCount) or 0)))
    -- Repair mode scans the complete retained range, including when a caller
    -- lowers the aggregate count, so registered special crates inside the new
    -- target are counted before surplus slots are cleared.
    local first = repairExisting and 0 or (target < previous and target or previous)
    local last = repairExisting and 110 or (math.max(previous, target) - 1)
    local warehouseType = self:ReadWarehouseType(definition, playerId)
    local plan, byIndex = {}, {}

    for crateIndex = first, last do
        local original = self:ReadWarehouseCrateCode(
            definition, crateIndex, characterSlot
        )
        if original == nil then return nil, "packing_read_failed" end
        local desired = original
        if crateIndex >= target then
            desired = 0
        elseif crateIndex >= previous or original < 1 or original > 49 then
            desired = self:ChooseWarehouseCrateCode(
                definition, crateIndex, cargoSelection, warehouseType
            )
            if desired == nil then return nil, "packing_code_unavailable" end
        end
        local item = {crateIndex = crateIndex, original = original, desired = desired}
        plan[#plan + 1] = item
        byIndex[crateIndex] = item
    end

    if repairExisting and target > 0 then
        local registeredCodes, specialReason = self:GetWarehouseRegisteredSpecialCodes(
            definition, target, characterSlot, playerId
        )
        if not registeredCodes then return nil, specialReason end

        -- The registry is the authoritative multiset. Extra 23..28 values are
        -- not harmless display variants: sell type 3/4 derives from this exact
        -- composition, so remove every unregistered or misplaced special crate.
        local missing = {}
        for _, specialCode in ipairs(registeredCodes) do
            missing[specialCode] = (missing[specialCode] or 0) + 1
        end
        for crateIndex = 0, target - 1 do
            local item = byIndex[crateIndex]
            if item and self:IsWarehouseSpecialCrateCode(item.desired) then
                local keep = self:IsWarehouseSpecialDisplayPosition(warehouseType, crateIndex)
                    and (missing[item.desired] or 0) > 0
                if keep then
                    missing[item.desired] = missing[item.desired] - 1
                else
                    local ordinaryCode = self:ChooseWarehouseCrateCode(
                        definition, crateIndex, cargoSelection, warehouseType
                    )
                    if type(ordinaryCode) ~= "number" or ordinaryCode < 1
                        or ordinaryCode > 49
                        or self:IsWarehouseSpecialCrateCode(ordinaryCode) then
                        return nil, "packing_code_unavailable"
                    end
                    item.desired = ordinaryCode
                end
            end
        end
        for _, specialCode in ipairs(registeredCodes) do
            if (missing[specialCode] or 0) > 0 then
                local replacement = nil
                for crateIndex = 0, target - 1 do
                    local item = byIndex[crateIndex]
                    if item and self:IsWarehouseSpecialDisplayPosition(warehouseType, crateIndex)
                        and not self:IsWarehouseSpecialCrateCode(item.desired) then
                        replacement = item
                        break
                    end
                end
                if not replacement then return nil, "special_layout_unavailable" end
                replacement.desired = specialCode
                missing[specialCode] = missing[specialCode] - 1
            end
        end
    end
    return plan, nil
end

function SovereignBusinessInventory:RollbackWarehousePacking(
    definition, changes, characterSlot, identityGuard
)
    local restored = true
    for index = #(changes or {}), 1, -1 do
        local change = changes[index]
        if not self:WriteWarehouseCrateCode(
            definition, change.crateIndex, change.original, true,
            characterSlot, identityGuard
        ) then
            restored = false
        end
    end
    return restored
end

function SovereignBusinessInventory:CommitWarehousePacking(
    definition, previousCount, targetCount, cargoSelection, repairExisting,
    characterSlot, playerId, identityGuard
)
    local plan, reason = self:BuildWarehousePackingPlan(
        definition, previousCount, targetCount, cargoSelection, repairExisting,
        characterSlot, playerId
    )
    if not plan then return false, {}, reason end
    local changes = {}
    for _, item in ipairs(plan) do
        if item.desired ~= item.original then
            local wrote, writeReason = self:WriteWarehouseCrateCode(
                definition, item.crateIndex, item.desired, true,
                characterSlot, identityGuard
            )
            if not wrote then
                if writeReason == "refill_identity_changed" then
                    return false, changes, writeReason
                end
                self:WriteWarehouseCrateCode(
                    definition, item.crateIndex, item.original, true,
                    characterSlot, identityGuard
                )
                self:RollbackWarehousePacking(
                    definition, changes, characterSlot, identityGuard
                )
                return false, {}, writeReason or "packing_write_failed"
            end
            changes[#changes + 1] = item
        end
    end
    if type(identityGuard) == "function" then
        local ok, allowed = pcall(identityGuard)
        if not ok or allowed ~= true then
            return false, changes, "refill_identity_changed"
        end
    end
    return true, changes, nil
end

function SovereignBusinessInventory:VerifyWarehousePacking(
    definition, changes, characterSlot
)
    for _, change in ipairs(changes or {}) do
        if self:ReadWarehouseCrateCode(
            definition, change.crateIndex, characterSlot
        ) ~= change.desired then
            return false
        end
    end
    return true
end

function SovereignBusinessInventory:ReadWarehousePackingFingerprint(
    definition, targetCount, characterSlot, playerId
)
    local capacity = self:GetWarehouseCapacity(definition, playerId)
    if capacity <= 0 then return nil, "warehouse_not_owned" end
    local target = math.max(0, math.min(capacity, math.floor(tonumber(targetCount) or 0)))
    local warehouseType = self:ReadWarehouseType(definition, playerId)
    if warehouseType < 1 or warehouseType > 22 then
        return nil, "warehouse_type_invalid"
    end
    local presentSpecial = {}
    local codes = {}
    for crateIndex = 0, target - 1 do
        local code = self:ReadWarehouseCrateCode(
            definition, crateIndex, characterSlot
        )
        if type(code) ~= "number" or code < 1 or code > 49 then
            return nil, "packing_code_invalid"
        end
        codes[crateIndex + 1] = code
        if self:IsWarehouseSpecialCrateCode(code) then
            if not self:IsWarehouseSpecialDisplayPosition(warehouseType, crateIndex) then
                return nil, "special_layout_invalid"
            end
            presentSpecial[code] = (presentSpecial[code] or 0) + 1
        end
    end
    -- All five slots reserve 111 packing entries. Small and medium warehouses
    -- must also keep the entries beyond their physical capacity empty.
    for crateIndex = target, 110 do
        if self:ReadWarehouseCrateCode(definition, crateIndex, characterSlot) ~= 0 then
            return nil, "packing_surplus_present"
        end
        codes[crateIndex + 1] = 0
    end
    local registeredCodes = self:GetWarehouseRegisteredSpecialCodes(
        definition, target, characterSlot, playerId
    )
    if not registeredCodes then return nil, "special_registry_inconsistent" end
    for _, specialCode in ipairs(registeredCodes) do
        if (presentSpecial[specialCode] or 0) <= 0 then
            return nil, "special_registry_inconsistent"
        end
        presentSpecial[specialCode] = presentSpecial[specialCode] - 1
    end
    for specialCode = 23, 28 do
        if (presentSpecial[specialCode] or 0) ~= 0 then
            return nil, "special_registry_inconsistent"
        end
    end
    local registry = {}
    for index, code in ipairs(registeredCodes) do
        registry[index] = tostring(code)
    end
    return tostring(warehouseType) .. ":" .. table.concat(codes, ",")
        .. ":" .. table.concat(registry, ","), nil
end

function SovereignBusinessInventory:VerifyWarehousePackingRange(
    definition, targetCount, characterSlot, playerId
)
    local fingerprint = self:ReadWarehousePackingFingerprint(
        definition, targetCount, characterSlot, playerId
    )
    return fingerprint ~= nil
end

function SovereignBusinessInventory:WaitForStableWarehousePacking(
    definition, targetCount, characterSlot, playerId, identityGuard, options
)
    options = type(options) == "table" and options or {}
    local attempts = math.floor(tonumber(options.attempts) or 6)
    attempts = math.max(2, math.min(12, attempts))
    local delay = math.floor(tonumber(options.sampleDelay) or 125)
    delay = math.max(0, math.min(1000, delay))
    local previousFingerprint = nil
    local sawValid = false
    for attempt = 1, attempts do
        if type(identityGuard) == "function" then
            local ok, allowed, reason = pcall(identityGuard)
            if not ok or allowed ~= true then
                return false, reason or "sale_identity_changed"
            end
        end
        local fingerprint = self:ReadWarehousePackingFingerprint(
            definition, targetCount, characterSlot, playerId
        )
        if fingerprint then
            sawValid = true
            if fingerprint == previousFingerprint then
                return true, nil
            end
            previousFingerprint = fingerprint
        else
            previousFingerprint = nil
        end
        if attempt < attempts and delay > 0
            and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, delay)
        end
    end
    if sawValid then return false, "warehouse_packing_sync_pending" end
    return false, "warehouse_packing_inconsistent"
end

function SovereignBusinessInventory:GetRefillStatIndex(kind, index)
    if kind == "factory" or kind == "factory_product" then
        local definition = self.factoryDefinitions[index]
        if not definition then return nil end
        return kind == "factory_product" and definition.product or definition.supply
    end
    if kind == "nightclub" and self.nightclubDefinitions[index] then
        return 7221 + index
    end
    if kind == "hangar" then
        return 6104
    end
    return nil
end

function SovereignBusinessInventory:GetRefillTransactionHash(kind, index)
    if not Utils or type(Utils.Joaat) ~= "function" then return nil end
    if (kind == "factory" or kind == "factory_product") and self.factoryDefinitions[index] then
        local suffix = tostring(index - 1)
        local productHash = Utils.Joaat("MP_STAT_PRODTOTALFORFACTORY" .. suffix .. "_v0")
        if kind == "factory_product" then return productHash, nil end
        return Utils.Joaat("MP_STAT_MATTOTALFORFACTORY" .. suffix .. "_v0"), productHash
    end
    if kind == "nightclub" and self.nightclubDefinitions[index] then
        return Utils.Joaat("MP_STAT_HUB_PROD_TOTAL_" .. tostring(index - 1) .. "_v0")
    end
    if kind == "hangar" then
        return Utils.Joaat("MP_STAT_HANGAR_CONTRABAND_TOTAL_v0")
    end
    return nil
end

function SovereignBusinessInventory:GetRefillCapacity(request, playerId)
    if type(request) ~= "table" then return nil end
    local index = math.floor(tonumber(request.index) or 0)
    if request.kind == "factory" then return 100 end
    if request.kind == "factory_product" then
        local definition = self.factoryDefinitions[index]
        return definition and self:GetProductCapacity(definition) or nil
    end
    if request.kind == "nightclub" then
        local definition = self.nightclubDefinitions[index]
        return definition and self:GetNightclubCapacity(
            definition, self:GetNightclubFloors(playerId)
        ) or nil
    end
    if request.kind == "hangar" then
        return math.floor(tonumber(self.data and self.data.hangarMax) or 50)
    end
    return nil
end

function SovereignBusinessInventory:GetRefillRuntimeGlobal(request, playerId)
    if type(request) ~= "table" then return nil end
    if playerId == nil then playerId = self:GetLocalPlayerId() end
    playerId = tonumber(playerId)
    if playerId == nil then return nil end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 then return nil end
    local playerBase = 1845347 + 1 + (playerId * 884)
    local index = math.floor(tonumber(request.index) or 0)
    if request.kind == "factory" or request.kind == "factory_product" then
        if index < 1 or index > #self.factoryDefinitions then return nil end
        local runtimeBase = playerBase + 260 + 205 + 1 + ((index - 1) * 13)
        return runtimeBase + (request.kind == "factory_product" and 1 or 2)
    end
    if request.kind == "nightclub" then
        if index < 1 or index > #self.nightclubDefinitions then return nil end
        return playerBase + 260 + 321 + 8 + 1 + (index - 1)
    end
    if request.kind == "hangar" then
        return playerBase + 260 + 304 + 3
    end
    return nil
end

function SovereignBusinessInventory:NormalizeStockValue(value, capacity)
    if type(value) ~= "number" or value ~= value then return nil end
    local ok, normalized = pcall(math.floor, value)
    if not ok or normalized < 0 or normalized > capacity then return nil end
    return normalized
end

function SovereignBusinessInventory:ReadStableWarehouseState(
    definition, characterSlot, playerId, runtimeGlobal, capacity,
    identityGuard, expectedValue, readOptions
)
    if type(definition) ~= "table" or type(runtimeGlobal) ~= "number"
        or type(capacity) ~= "number" or capacity <= 0 then
        return nil, "warehouse_state_unavailable"
    end
    local stableCount = 0
    local stableValue = nil
    local changedCount = 0
    local changedValue = nil
    local outOfRangePersistent, outOfRangeLive = nil, nil
    local outOfRangeCount = 0
    local lastPersistent, lastLive = nil, nil
    local sawReadable = false
    readOptions = type(readOptions) == "table" and readOptions or {}
    local attempts = math.floor(tonumber(readOptions.attempts) or 24)
    attempts = math.max(2, math.min(24, attempts))
    local sampleDelay = math.floor(tonumber(readOptions.sampleDelay) or 125)
    sampleDelay = math.max(0, math.min(1000, sampleDelay))
    local changedThreshold = math.floor(
        tonumber(readOptions.changedThreshold) or 4
    )
    changedThreshold = math.max(2, math.min(attempts, changedThreshold))
    for attempt = 1, attempts do
        if type(identityGuard) == "function" then
            local ok, allowed, reason = pcall(identityGuard)
            if not ok or allowed ~= true then
                return nil, reason or "refill_identity_changed"
            end
        end
        local values = self:ReadIndices({definition.productIndex}, characterSlot)
        local persistent = values and values[definition.productIndex] or nil
        local live = self:ReadGlobal(runtimeGlobal)
        local persistentOk, normalizedPersistent = pcall(math.floor, persistent)
        local liveOk, normalizedLive = pcall(math.floor, live)
        local sampleValid = persistentOk and liveOk
            and type(normalizedPersistent) == "number"
            and type(normalizedLive) == "number"
            and normalizedPersistent == normalizedPersistent
            and normalizedLive == normalizedLive
        if sampleValid then
            persistent, live = normalizedPersistent, normalizedLive
            sawReadable = true
            lastPersistent, lastLive = persistent, live
            local outOfRange = persistent < 0 or persistent > capacity
                or live < 0 or live > capacity
            if outOfRange then
                -- A warehouse rebuild can expose one stale cache tuple. Only
                -- reject a tuple that remains invalid across the convergence
                -- window; the caller still fails closed while it is pending.
                if outOfRangePersistent == persistent and outOfRangeLive == live then
                    outOfRangeCount = outOfRangeCount + 1
                else
                    outOfRangePersistent, outOfRangeLive = persistent, live
                    outOfRangeCount = 1
                end
                stableCount, stableValue, changedCount, changedValue = 0, nil, 0, nil
                if outOfRangeCount >= 2 then
                    Logger:Warn("SovereignInventory", string.format(
                        "%s warehouse state out of range persistent=%d live=%d capacity=%d consecutive=%d",
                        tostring(definition.name), persistent, live, capacity,
                        outOfRangeCount
                    ))
                    return nil, "warehouse_state_out_of_range"
                end
            else
                outOfRangePersistent, outOfRangeLive, outOfRangeCount = nil, nil, 0
            end
            if not outOfRange and persistent == live then
                if expectedValue ~= nil and persistent ~= expectedValue then
                    stableCount, stableValue = 0, nil
                    if changedValue == persistent then
                        changedCount = changedCount + 1
                    else
                        changedValue, changedCount = persistent, 1
                    end
                    if changedCount >= changedThreshold then
                        Logger:Warn("SovereignInventory", string.format(
                            "%s warehouse state changed expected=%d actual=%d capacity=%d",
                            tostring(definition.name), expectedValue, persistent, capacity
                        ))
                        return nil, "warehouse_state_changed"
                    end
                else
                    changedCount, changedValue = 0, nil
                    if stableValue == persistent then
                        stableCount = stableCount + 1
                    else
                        stableValue, stableCount = persistent, 1
                    end
                    if stableCount >= 2 then
                        return {
                            persistent = persistent,
                            live = live,
                            samples = attempt
                        }, nil
                    end
                end
            elseif not outOfRange then
                stableCount, stableValue, changedCount, changedValue = 0, nil, 0, nil
            end
        else
            stableCount, stableValue, changedCount, changedValue = 0, nil, 0, nil
            outOfRangePersistent, outOfRangeLive, outOfRangeCount = nil, nil, 0
        end
        if attempt < attempts and sampleDelay > 0
            and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, sampleDelay)
        end
    end
    Logger:Warn("SovereignInventory", string.format(
        "%s warehouse state did not converge persistent=%s live=%s capacity=%d",
        tostring(definition.name), tostring(lastPersistent), tostring(lastLive), capacity
    ))
    if sawReadable then return nil, "warehouse_state_sync_pending" end
    return nil, "warehouse_state_unavailable"
end

function SovereignBusinessInventory:ReadStableSaleStock(
    statIndices, statIndex, specialStatIndex, characterSlot, runtimeGlobal,
    capacity, identityGuard, options
)
    if type(statIndices) ~= "table" or statIndex == nil
        or type(runtimeGlobal) ~= "number" or type(capacity) ~= "number"
        or capacity <= 0 then
        return nil, "sale_stock_unavailable"
    end
    options = type(options) == "table" and options or {}
    local attempts = math.floor(tonumber(options.attempts) or 24)
    attempts = math.max(2, math.min(24, attempts))
    local delay = math.floor(tonumber(options.sampleDelay) or 125)
    delay = math.max(0, math.min(1000, delay))
    local stablePersistent, stableLive, stableSpecial = nil, nil, nil
    local stableCount = 0
    local sawPrimaryLive = false
    local sawValidTuple = false
    local lastPersistent, lastLive = nil, nil
    for attempt = 1, attempts do
        if type(identityGuard) == "function" then
            local ok, allowed, reason = pcall(identityGuard)
            if not ok or allowed ~= true then
                return nil, reason or "sale_identity_changed"
            end
        end
        local values = self:ReadIndices(statIndices, characterSlot)
        local persistent = self:NormalizeStockValue(
            values and values[statIndex], capacity
        )
        local live = self:NormalizeStockValue(self:ReadGlobal(runtimeGlobal), capacity)
        lastPersistent, lastLive = persistent, live
        if persistent ~= nil and live ~= nil then
            sawPrimaryLive = true
            local special = nil
            local tupleValid = true
            if specialStatIndex ~= nil then
                special = self:NormalizeStockValue(
                    values and values[specialStatIndex], capacity
                )
                if special == nil or special > persistent then
                    tupleValid = false
                end
            end
            if tupleValid then
                sawValidTuple = true
                if stablePersistent == persistent and stableLive == live
                    and stableSpecial == special then
                    stableCount = stableCount + 1
                else
                    stablePersistent, stableLive, stableSpecial =
                        persistent, live, special
                    stableCount = 1
                end
                if stableCount >= 2
                    and (options.requireEqual ~= true or persistent == live) then
                    if type(identityGuard) == "function" then
                        local ok, allowed, reason = pcall(identityGuard)
                        if not ok or allowed ~= true then
                            return nil, reason or "sale_identity_changed"
                        end
                    end
                    return {
                        persistent = persistent,
                        live = live,
                        specialPersistent = special,
                        samples = attempt
                    }, nil
                end
            else
                stablePersistent, stableLive, stableSpecial, stableCount =
                    nil, nil, nil, 0
            end
        else
            stablePersistent, stableLive, stableSpecial, stableCount =
                nil, nil, nil, 0
        end
        if attempt < attempts and delay > 0
            and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, delay)
        end
    end
    if sawPrimaryLive and not sawValidTuple and specialStatIndex ~= nil then
        return nil, "sale_stock_unavailable"
    end
    if sawPrimaryLive then
        if options.quiet ~= true then
            Logger:Warn("SovereignInventory", string.format(
                "sale stock did not converge persistent=%s live=%s",
                tostring(lastPersistent), tostring(lastLive)
            ))
        end
        return nil, "sale_stock_sync_pending"
    end
    return nil, "sale_stock_unavailable"
end

function SovereignBusinessInventory:WaitForWarehousePacking(
    definition, targetCount, characterSlot, playerId, identityGuard
)
    return self:WaitForStableWarehousePacking(
        definition, targetCount, characterSlot, playerId, identityGuard,
        {attempts = 6, sampleDelay = 125}
    )
end

function SovereignBusinessInventory:ReadHangarPackingState(characterSlot)
    if characterSlot == nil then characterSlot = self:GetCharacterSlot() end
    characterSlot = tonumber(characterSlot)
    if characterSlot == nil then return nil, "character_slot_unavailable" end
    characterSlot = math.floor(characterSlot)
    if characterSlot ~= 0 and characterSlot ~= 1 then
        return nil, "character_slot_unavailable"
    end
    local header = self:ReadGlobal(1965090)
    if type(header) ~= "number" or math.floor(header) ~= 50 then
        return nil, "hangar_packing_unavailable"
    end
    local slots = {}
    local count = 0
    for slotIndex = 0, 49 do
        local packed = self:ReadPackedIntStat(16011 + slotIndex, characterSlot)
        local mirror = self:ReadGlobal(1965090 + 1 + slotIndex)
        if type(packed) ~= "number" or type(mirror) ~= "number" then
            return nil, "hangar_packing_unavailable"
        end
        packed, mirror = math.floor(packed), math.floor(mirror)
        if packed < 0 or packed > 16 or mirror ~= packed then
            return nil, "hangar_packing_inconsistent"
        end
        slots[slotIndex + 1] = packed
        if packed ~= 0 then count = count + 1 end
    end
    return {
        slots = slots,
        count = count,
        characterSlot = characterSlot
    }, nil
end

function SovereignBusinessInventory:VerifyHangarPacking(
    targetCount, expectedSlots, characterSlot
)
    local target = tonumber(targetCount)
    if type(target) ~= "number" or target ~= target then return false end
    target = math.floor(target)
    if target < 0 or target > 50 then return false end
    local state = self:ReadHangarPackingState(characterSlot)
    if not state or state.count ~= target then return false end
    if type(expectedSlots) == "table" then
        for index = 1, 50 do
            if state.slots[index] ~= expectedSlots[index] then return false end
        end
    end
    return true, state
end

function SovereignBusinessInventory:ValidateHangarPackingPlan(slots, targetCount)
    local target = tonumber(targetCount)
    if type(slots) ~= "table" or type(target) ~= "number" or target ~= target then
        return nil
    end
    target = math.floor(target)
    if target < 0 or target > 50 then return nil end
    local copy, count = {}, 0
    for index = 1, 50 do
        local code = tonumber(slots[index])
        if type(code) ~= "number" or code ~= code then return nil end
        code = math.floor(code)
        if code < 0 or code > 16 then return nil end
        copy[index] = code
        if code ~= 0 then count = count + 1 end
    end
    if count ~= target then return nil end
    return copy
end

function SovereignBusinessInventory:BuildHangarPackingPlan(packing, targetCount)
    if type(packing) ~= "table" or type(packing.slots) ~= "table"
        or type(packing.count) ~= "number" then
        return nil, "hangar_packing_unavailable"
    end
    local target = tonumber(targetCount)
    if type(target) ~= "number" or target ~= target then
        return nil, "invalid_request"
    end
    target = math.floor(target)
    if target < 0 or target > 50 then return nil, "stock_capacity_invalid" end
    local desired = self:ValidateHangarPackingPlan(packing.slots, packing.count)
    if not desired then return nil, "hangar_packing_inconsistent" end
    local count = math.floor(packing.count)
    if count < target then
        for slotIndex = 0, 49 do
            local index = slotIndex + 1
            if desired[index] == 0 then
                desired[index] = (slotIndex % 16) + 1
                count = count + 1
                if count == target then break end
            end
        end
    elseif count > target then
        for slotIndex = 49, 0, -1 do
            local index = slotIndex + 1
            if desired[index] ~= 0 then
                desired[index] = 0
                count = count - 1
                if count == target then break end
            end
        end
    end
    if count ~= target then return nil, "hangar_packing_unavailable" end
    return desired, nil
end

function SovereignBusinessInventory:CommitHangarPackingSnapshot(
    targetCount, expectedSlots, characterSlot, playerId, identityGuard
)
    local target = tonumber(targetCount)
    if type(target) ~= "number" or target ~= target then
        return false, "invalid_request"
    end
    target = math.floor(target)
    local desired = self:ValidateHangarPackingPlan(expectedSlots, target)
    if not desired then return false, "hangar_packing_inconsistent" end
    if type(self.data.hangarOwned) ~= "number" or self.data.hangarOwned == 0 then
        return false, "business_not_owned"
    end
    if characterSlot == nil then characterSlot = self:GetCharacterSlot() end
    characterSlot = tonumber(characterSlot)
    if type(characterSlot) ~= "number"
        or (characterSlot ~= 0 and characterSlot ~= 1) then
        return false, "character_slot_unavailable"
    end
    characterSlot = math.floor(characterSlot)
    if playerId == nil then playerId = self:GetLocalPlayerId() end
    playerId = tonumber(playerId)
    if playerId == nil then return false, "local_player_unavailable" end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 then
        return false, "local_player_unavailable"
    end
    local function guardCurrent()
        if type(identityGuard) ~= "function" then return true end
        local ok, allowed = pcall(identityGuard)
        return ok and allowed == true
    end
    if not guardCurrent() then return false, "refill_identity_changed" end
    local packingHeader = self:ReadGlobal(1965090)
    if type(packingHeader) ~= "number" or math.floor(packingHeader) ~= 50 then
        return false, "hangar_packing_unavailable"
    end
    local runtimeGlobal = 1845347 + 1 + (playerId * 884) + 260 + 304 + 3
    for slotIndex = 0, 49 do
        if not guardCurrent() then return false, "refill_identity_changed" end
        local index = slotIndex + 1
        local current = self:ReadPackedIntStat(16011 + slotIndex, characterSlot)
        if current ~= desired[index] and not self:WritePackedIntStat(
            16011 + slotIndex, desired[index], characterSlot
        ) then
            return false, "hangar_packing_write_failed"
        end
        if not self:WriteGlobalVerified(
            1965090 + 1 + slotIndex, desired[index]
        ) then
            return false, "hangar_packing_write_failed"
        end
    end
    if not guardCurrent() then return false, "refill_identity_changed" end
    if not self:VerifyHangarPacking(target, desired, characterSlot) then
        return false, "hangar_packing_readback_failed"
    end
    if not self:WriteStatByIndex(6104, target, characterSlot) then
        return false, "stat_commit_failed"
    end
    if not self:WriteGlobalVerified(runtimeGlobal, target) then
        return false, "live_commit_failed"
    end
    local expectedFullFlag = target == 50
    if not self:WritePackedBoolStat(41987, expectedFullFlag, characterSlot) then
        return false, "hangar_full_flag_failed"
    end
    if not self:SaveStats() then return false, "stat_save_failed" end
    if not guardCurrent() then return false, "refill_identity_changed" end
    local values = self:ReadIndices({6104}, characterSlot)
    local persistent = self:NormalizeStockValue(values and values[6104], 50)
    local live = self:NormalizeStockValue(self:ReadGlobal(runtimeGlobal), 50)
    local fullFlagOk = self:ReadPackedBoolStat(41987, characterSlot)
        == expectedFullFlag
    if persistent ~= target or live ~= target or not fullFlagOk
        or not self:VerifyHangarPacking(target, desired, characterSlot) then
        return false, "hangar_commit_readback_failed"
    end
    self.data.hangar = target
    return true, nil
end

function SovereignBusinessInventory:ReadRefillState(
    request, statIndex, capacity, expectedIdentity
)
    local characterSlot = type(expectedIdentity) == "table"
        and expectedIdentity.characterSlot or nil
    local playerId = type(expectedIdentity) == "table"
        and expectedIdentity.playerId or nil
    local function identityCurrent()
        if type(expectedIdentity) ~= "table" then return true end
        local current = self:CaptureRefillIdentity(request)
        return current ~= nil and self:AreRefillIdentitiesEqual(
            current, expectedIdentity
        )
    end
    local runtimeGlobal = self:GetRefillRuntimeGlobal(request, playerId)
    if not runtimeGlobal then return nil, "stock_state_unavailable" end
    local lastPersistent, lastLive
    local stablePersistent, stableLive, stableCount = nil, nil, 0
    local mismatchPersistent, mismatchLive, mismatchCount = nil, nil, 0
    local sawReadable = false
    local attempts = 24
    for attempt = 1, attempts do
        if not identityCurrent() then return nil, "refill_identity_changed" end
        local values = self:ReadIndices({statIndex}, characterSlot)
        lastPersistent = self:NormalizeStockValue(values and values[statIndex], capacity)
        lastLive = self:NormalizeStockValue(self:ReadGlobal(runtimeGlobal), capacity)
        if lastPersistent ~= nil and lastLive ~= nil then
            sawReadable = true
            if lastPersistent == lastLive then
                mismatchPersistent, mismatchLive, mismatchCount = nil, nil, 0
                if stablePersistent == lastPersistent
                    and stableLive == lastLive then
                    stableCount = stableCount + 1
                else
                    stablePersistent, stableLive, stableCount =
                        lastPersistent, lastLive, 1
                end
                if stableCount >= 2 then
                    local state = {
                        persistent = lastPersistent,
                        live = lastLive,
                        runtimeGlobal = runtimeGlobal,
                        capacity = capacity,
                        samples = attempt
                    }
                    if request.kind == "hangar" then
                        local packing, packingReason = self:ReadHangarPackingState(
                            characterSlot
                        )
                        if not packing then return nil, packingReason end
                        if packing.count ~= lastPersistent then
                            return nil, "hangar_packing_inconsistent"
                        end
                        state.packing = packing
                        state.packingConfirmed = true
                    end
                    if not identityCurrent() then
                        return nil, "refill_identity_changed"
                    end
                    return state, nil
                end
            else
                stablePersistent, stableLive, stableCount = nil, nil, 0
                if mismatchPersistent == lastPersistent
                    and mismatchLive == lastLive then
                    mismatchCount = mismatchCount + 1
                else
                    mismatchPersistent, mismatchLive, mismatchCount =
                        lastPersistent, lastLive, 1
                end
                -- Keep sampling through the bounded window. A cache can hold
                -- one stale side for several frames; only final evidence
                -- decides whether this is a conflict or still syncing.
            end
        else
            stablePersistent, stableLive, stableCount = nil, nil, 0
            mismatchPersistent, mismatchLive, mismatchCount = nil, nil, 0
        end
        if attempt < attempts and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, 125)
        end
    end
    if sawReadable then
        if mismatchCount >= 4 then return nil, "stock_state_inconsistent" end
        return nil, "stock_state_sync_pending"
    end
    return nil, "stock_state_unavailable"
end

function SovereignBusinessInventory:WriteRefillLiveValue(
    request, value, previousValue, expectedIdentity
)
    local playerId = type(expectedIdentity) == "table"
        and expectedIdentity.playerId or nil
    if request.kind == "factory" then
        return self:SetFactorySupply(request.index, value, playerId)
    elseif request.kind == "factory_product" then
        return self:SetFactoryProduct(request.index, value, playerId)
    elseif request.kind == "nightclub" then
        return self:SetNightclubStock(request.index, value, playerId)
    elseif request.kind == "hangar" then
        return self:SetHangarStock(
            value, previousValue, nil, nil, expectedIdentity
        )
    end
    return false
end

function SovereignBusinessInventory:GetRefillRequestKey(request)
    if type(request) ~= "table" then return nil end
    return tostring(request.kind or "invalid") .. ":" .. tostring(
        math.floor(tonumber(request.index) or 0)
    )
end

function SovereignBusinessInventory:CaptureRefillIdentity(request)
    if type(request) ~= "table" then return nil, "invalid_request" end
    local characterSlot = self:GetCharacterSlot()
    local playerId = self:GetLocalPlayerId()
    local organization = self:GetLocalOrganizationState()
    if characterSlot == nil then return nil, "character_slot_unavailable" end
    if playerId == nil or organization.valid ~= true
        or organization.playerId ~= playerId then
        return nil, "local_player_unavailable"
    end
    local index = math.floor(tonumber(request.index) or 0)
    local businessToken = nil
    if request.kind == "warehouse" then
        if organization.role ~= "ceo" then
            local roleOk, roleOrReason = self:EnsureOrganizationRole("ceo")
            if not roleOk then return nil, roleOrReason end
            organization = roleOrReason
        end
        local definition = self.warehouseDefinitions[index]
        businessToken = definition and self:ReadWarehouseType(definition, playerId) or nil
        if type(businessToken) ~= "number" or businessToken < 1 or businessToken > 22 then
            return nil, "warehouse_state_unavailable"
        end
    elseif request.kind == "factory" or request.kind == "factory_product" then
        if index >= 1 and index <= 5 and organization.role ~= "mc_president" then
            local roleOk, roleOrReason = self:EnsureOrganizationRole("mc_president")
            if not roleOk then return nil, roleOrReason end
            organization = roleOrReason
        end
        if index >= 6 and organization.isBoss ~= true then
            return nil, "organization_boss_required"
        end
        local definition = self.factoryDefinitions[index]
        if not definition then return nil, "invalid_request" end
        local values = self:ReadIndices({definition.property}, characterSlot)
        businessToken = values and values[definition.property] or nil
        if type(businessToken) ~= "number" or businessToken == 0 then
            return nil, "business_not_owned"
        end
    elseif request.kind == "hangar" then
        if organization.isBoss ~= true then return nil, "organization_boss_required" end
        local values = self:ReadIndices({6103}, characterSlot)
        businessToken = values and values[6103] or nil
        if type(businessToken) ~= "number" or businessToken == 0 then
            return nil, "business_not_owned"
        end
    elseif request.kind == "nightclub" then
        if organization.isBoss ~= true then return nil, "organization_boss_required" end
        -- Enhanced loads the nightclub property id from character stat 6538
        -- into f_260.f_321. f_321.f_4 contains upgrade/floor flags and can be
        -- zero for a valid one-floor nightclub, so it is not an identity token.
        local nightclubPropertyGlobal = 1845347 + 1 + (playerId * 884) + 260 + 321
        businessToken = self:ReadGlobal(nightclubPropertyGlobal)
        if type(businessToken) ~= "number" or businessToken ~= businessToken
            or businessToken ~= math.floor(businessToken)
            or businessToken < 1 or businessToken > 10 then
            return nil, "business_not_owned"
        end
    else
        return nil, "invalid_request"
    end
    if self:GetCharacterSlot() ~= characterSlot
        or self:GetLocalPlayerId() ~= playerId then
        return nil, "refill_identity_changed"
    end
    return {
        characterSlot = math.floor(characterSlot),
        playerId = playerId,
        bossId = organization.bossId,
        role = organization.role,
        businessToken = math.floor(businessToken),
        kind = request.kind,
        index = index
    }, nil
end

function SovereignBusinessInventory:IsPendingRefillIdentityCurrent(pending)
    if type(pending) ~= "table" or type(pending.identity) ~= "table"
        or type(pending.request) ~= "table" then
        return false, "refill_identity_unavailable"
    end
    local current, reason = self:CaptureRefillIdentity(pending.request)
    if not current then return false, reason or "refill_identity_unavailable" end
    local sameIdentity = self:AreRefillIdentitiesEqual(current, pending.identity)
    return sameIdentity, sameIdentity and nil or "refill_identity_changed"
end

function SovereignBusinessInventory:AreRefillIdentitiesEqual(current, expected)
    if type(current) ~= "table" or type(expected) ~= "table" then return false end
    for _, field in ipairs({
        "characterSlot", "playerId", "bossId", "role", "businessToken", "kind", "index"
    }) do
        if current[field] ~= expected[field] then return false end
    end
    return true
end

function SovereignBusinessInventory:QuarantinePendingRefill(key, pending, reason)
    if type(pending) ~= "table" or self.pendingRefillTransactions[key] ~= pending then
        return false
    end
    pending.reason = reason or pending.reason or "refill_identity_changed"
    pending.quarantinedAt = os.clock()
    pending.repairNextAt = os.clock() + 1.0
    self.refillQuarantine[key] = pending
    self.pendingRefillTransactions[key] = nil
    -- A server-accepted operation is blocked from new submissions, but remains
    -- repairable when the exact character/organization identity returns.
    if pending.transactionAccepted == true then
        self.refillRejectedKeys[key] = nil
    else
        self.refillRejectedKeys[key] = true
    end
    local currentIdentity, currentReason = self:CaptureRefillIdentity(pending.request)
    local expectedIdentity = pending.identity or {}
    Logger:Info("SovereignInventory", string.format(
        "%s identity quarantine expected(slot=%s player=%s boss=%s role=%s token=%s) current(slot=%s player=%s boss=%s role=%s token=%s) currentReason=%s",
        tostring(pending.request and (pending.request.name or pending.request.kind)),
        tostring(expectedIdentity.characterSlot), tostring(expectedIdentity.playerId),
        tostring(expectedIdentity.bossId), tostring(expectedIdentity.role), tostring(expectedIdentity.businessToken),
        tostring(currentIdentity and currentIdentity.characterSlot), tostring(currentIdentity and currentIdentity.playerId),
        tostring(currentIdentity and currentIdentity.bossId), tostring(currentIdentity and currentIdentity.role),
        tostring(currentIdentity and currentIdentity.businessToken), tostring(currentReason)
    ))
    Logger:Error("SovereignInventory", string.format(
        "%s pending refill quarantined reason=%s; no repair was written",
        tostring(pending.request and (pending.request.name or pending.request.kind)),
        tostring(pending.reason)
    ))
    self:Notify(
        tostring(pending.request and (pending.request.name or pending.request.kind) or "Business")
            .. "Restock paused. Return to the original character and organization",
        "warning"
    )
    return true
end

function SovereignBusinessInventory:ReadPendingRefillState(pending)
    if type(pending) ~= "table" or type(pending.request) ~= "table"
        or type(pending.statIndex) ~= "number" or type(pending.capacity) ~= "number" then
        return nil
    end
    local identityOk = self:IsPendingRefillIdentityCurrent(pending)
    if not identityOk then return nil end
    if pending.request.kind ~= "warehouse" then
        local state = self:ReadRefillState(
            pending.request, pending.statIndex, pending.capacity, pending.identity
        )
        if state and pending.request.kind == "hangar"
            and type(pending.expectedSlots) == "table"
            and not self:VerifyHangarPacking(
                pending.target, pending.expectedSlots,
                pending.identity and pending.identity.characterSlot
            ) then
            return nil
        end
        local stillCurrent = self:IsPendingRefillIdentityCurrent(pending)
        return stillCurrent and state or nil
    end
    local runtimeGlobal = tonumber(pending.runtimeGlobal)
    if not runtimeGlobal then return nil end
    local definition = self.warehouseDefinitions[
        math.floor(tonumber(pending.request.index) or 0)
    ]
    if not definition then return nil end
    local function identityGuard()
        return self:IsPendingRefillIdentityCurrent(pending)
    end
    -- Pending entries are checked frequently. Use a short bounded convergence
    -- window here; the full preflight path still uses the longer sampler.
    local stable, stableReason = self:ReadStableWarehouseState(
        definition,
        pending.identity and pending.identity.characterSlot,
        pending.identity and pending.identity.playerId,
        runtimeGlobal,
        pending.capacity,
        identityGuard,
        nil,
        {attempts = 4, sampleDelay = 50, changedThreshold = 4}
    )
    if not stable then return nil, stableReason end
    local packingConfirmed, packingReason = self:WaitForStableWarehousePacking(
        definition,
        stable.persistent,
        pending.identity and pending.identity.characterSlot,
        pending.identity and pending.identity.playerId,
        identityGuard,
        -- Packing is updated independently from the two stock stores. Give
        -- the game a short convergence window so one rebuild tick is not
        -- promoted to a permanent pending failure.
        {attempts = 3, sampleDelay = 25}
    )
    if not packingConfirmed then return nil, packingReason end
    local stillCurrent = self:IsPendingRefillIdentityCurrent(pending)
    if not stillCurrent then return nil end
    return {
        persistent = stable.persistent,
        live = stable.live,
        runtimeGlobal = runtimeGlobal,
        packingConfirmed = true,
        samples = stable.samples
    }
end

function SovereignBusinessInventory:ReadTransactionGlobal(index, readOptions)
    if not self:HasInventoryMapping("transaction_layout") then
        return nil
    end
    local normalizedIndex = tonumber(index)
    if type(normalizedIndex) ~= "number" or normalizedIndex ~= normalizedIndex
        or normalizedIndex == rawget(math, "huge") or normalizedIndex == -rawget(math, "huge") then
        return nil
    end
    normalizedIndex = math.floor(normalizedIndex)
    readOptions = type(readOptions) == "table" and readOptions or {}
    local attempts = math.floor(tonumber(readOptions.attempts) or 3)
    attempts = math.max(1, math.min(8, attempts))
    local retryDelay = math.floor(tonumber(readOptions.retryDelay) or 0)
    retryDelay = math.max(0, math.min(250, retryDelay))
    for attempt = 1, attempts do
        local value = self:ReadGlobal(normalizedIndex)
        local normalized = self:NormalizeSignedInt32(value)
        if normalized ~= nil then
            return normalized
        end
        if attempt < attempts and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, retryDelay)
        end
    end
    return nil
end

function SovereignBusinessInventory:MarkPendingRefill(
    request, statIndex, capacity, target, beforePersistent, beforeLive, runtimeGlobal,
    transactionAccepted, expectedSlots, expectedIdentity, transactionContext
)
    local key = self:GetRefillRequestKey(request)
    if not key then return false end
    local currentIdentity, identityReason = self:CaptureRefillIdentity(request)
    local identity = type(expectedIdentity) == "table"
        and expectedIdentity or currentIdentity
    if type(expectedIdentity) == "table" and currentIdentity
        and not self:AreRefillIdentitiesEqual(currentIdentity, expectedIdentity) then
        identityReason = "refill_identity_changed"
    end
    local requestCopy = {
        kind = request.kind,
        index = request.index,
        target = request.target,
        name = request.name,
        cargoType = request.cargoType
    }
    local slotsCopy = nil
    if type(expectedSlots) == "table" then
        slotsCopy = {}
        for index = 1, 50 do slotsCopy[index] = expectedSlots[index] end
    end
    local cleanupCopy = nil
    if type(transactionContext) == "table" then
        cleanupCopy = {
            base = tonumber(transactionContext.base),
            slot = tonumber(transactionContext.slot),
            transactionId = tonumber(transactionContext.transactionId),
            frameCount = tonumber(transactionContext.frameCount),
            attempts = tonumber(transactionContext.attempts) or 3,
            basketEndPending = transactionContext.basketEndPending == true,
            basketEndAttempted = transactionContext.basketEndAttempted == true,
            outcomePending = transactionContext.outcomePending == true,
            serverAccepted = transactionContext.serverAccepted == true,
            serverRejected = transactionContext.serverRejected == true,
            localOnlyCleanup = transactionContext.localOnlyCleanup == true,
            passiveBasketCleanup = transactionContext.passiveBasketCleanup == true,
            slotTombstone = transactionContext.slotTombstone == true,
            expectedTransactionId = tonumber(transactionContext.expectedTransactionId),
            expectedFrameCount = tonumber(transactionContext.expectedFrameCount),
            targetTransactionId = tonumber(transactionContext.targetTransactionId),
            targetFrameCount = tonumber(transactionContext.targetFrameCount),
            transactionWriteAttempted =
                transactionContext.transactionWriteAttempted == true,
            frameWriteAttempted = transactionContext.frameWriteAttempted == true,
            basketOwnerWriteAttempted =
                transactionContext.basketOwnerWriteAttempted == true,
            publishedIdentityTransition =
                transactionContext.publishedIdentityTransition == true,
            publishedIdentityTransitionExpiresAt = tonumber(
                transactionContext.publishedIdentityTransitionExpiresAt
            ),
            baselineTransactionId = tonumber(transactionContext.baselineTransactionId),
            baselineFrameCount = tonumber(transactionContext.baselineFrameCount),
            createdAt = tonumber(transactionContext.createdAt),
            cleanupDeadline = tonumber(transactionContext.cleanupDeadline),
            tombstoneNotBefore = tonumber(transactionContext.tombstoneNotBefore),
            passiveNotBefore = tonumber(transactionContext.passiveNotBefore),
            inactiveSamples = tonumber(transactionContext.inactiveSamples) or 0,
            publicationUncertain = transactionContext.publicationUncertain == true,
            zeroSamples = tonumber(transactionContext.zeroSamples) or 0,
            outcomeAbandoned = transactionContext.outcomeAbandoned == true
        }
    end
    local pending = {
        request = requestCopy,
        statIndex = statIndex,
        capacity = capacity,
        target = target,
        beforePersistent = beforePersistent,
        beforeLive = beforeLive,
        runtimeGlobal = runtimeGlobal,
        transactionAccepted = transactionAccepted == true,
        identity = identity,
        identityReason = identityReason,
        expectedSlots = slotsCopy,
        transactionContext = cleanupCopy,
        transactionCleanupAttempts = 0,
        transactionCleanupNextAt = os.clock(),
        repairAttempts = 0,
        repairNextAt = os.clock(),
        at = os.clock()
    }
    self.pendingRefillTransactions[key] = pending
    if not identity or not currentIdentity or identityReason then
        self:QuarantinePendingRefill(
            key, pending, identityReason or "refill_identity_unavailable"
        )
        return false
    end
    return true
end

function SovereignBusinessInventory:EnsurePendingRefillTransactionCleanup(pending)
    if type(pending) ~= "table" or type(pending.transactionContext) ~= "table" then
        return true, nil
    end
    local now = os.clock()
    if now < (tonumber(pending.transactionCleanupNextAt) or 0) then
        return false, pending.reason or "transaction_cleanup_unconfirmed"
    end
    local transactionContext = pending.transactionContext
    local settled, cleanupReason = self:EnsureFreemodeTransactionSettled(
        transactionContext
    )
    if not settled then
        pending.transactionCleanupAttempts = math.floor(
            tonumber(pending.transactionCleanupAttempts) or 0
        ) + 1
        pending.transactionCleanupNextAt = now + math.min(
            30.0, 0.5 * (2 ^ math.min(6, pending.transactionCleanupAttempts - 1))
        )
        pending.reason = cleanupReason or "transaction_cleanup_unconfirmed"
        if transactionContext.slotTombstone == true
            and transactionContext.outcomePending ~= true
            and now >= (tonumber(transactionContext.cleanupDeadline) or rawget(math, "huge")) then
            local key = self:GetRefillRequestKey(pending.request)
            if key and self.pendingRefillTransactions[key] == pending then
                self:QuarantinePendingRefill(
                    key, pending, "transaction_cleanup_expired"
                )
            end
        end
        return false, pending.reason
    end
    pending.transactionContext = nil
    pending.transactionCleanupResolvedAt = now
    local key = self:GetRefillRequestKey(pending.request)
    if transactionContext.outcomeAbandoned == true then
        if key then
            self:QuarantinePendingRefill(
                key, pending, "transaction_outcome_unconfirmed"
            )
        end
        return false, "transaction_outcome_unconfirmed"
    end
    if transactionContext.localOnlyCleanup == true then
        if key and self.pendingRefillTransactions[key] == pending then
            self.pendingRefillTransactions[key] = nil
        end
        if key and self.refillQuarantine[key] == pending then
            self.refillQuarantine[key] = nil
        end
        if key then self.refillRejectedKeys[key] = nil end
        Logger:Info("SovereignInventory", string.format(
            "%s unpublished transaction cleanup completed; refill retry unlocked",
            tostring(pending.request and (pending.request.name or pending.request.kind))
        ))
        return false, "transaction_not_dispatched"
    end
    if transactionContext.serverAccepted == true then
        pending.transactionAccepted = true
        if key then self.refillRejectedKeys[key] = nil end
    end
    if transactionContext.serverRejected == true then
        if key then
            self.refillRejectedKeys[key] = true
            if pending.request and pending.request.kind == "warehouse" then
                self.warehouseRefillRejected = true
            end
            if self.pendingRefillTransactions[key] == pending then
                self.pendingRefillTransactions[key] = nil
            end
            if self.refillQuarantine[key] == pending then
                self.refillQuarantine[key] = nil
            end
        end
        pending.reason = "transaction_rejected"
        Logger:Warn("SovereignInventory", string.format(
            "%s rejected transaction cleanup completed; retries locked",
            tostring(pending.request and (pending.request.name or pending.request.kind))
        ))
        return false, "transaction_rejected"
    end
    return true, nil
end

function SovereignBusinessInventory:RepairAcceptedPendingRefill(pending)
    if type(pending) ~= "table" or pending.transactionAccepted ~= true
        or type(pending.request) ~= "table" then
        return false
    end
    local identityOk = self:IsPendingRefillIdentityCurrent(pending)
    if not identityOk then return false end
    local request = pending.request
    local function identityCurrent()
        return self:IsPendingRefillIdentityCurrent(pending)
    end
    if request.kind == "warehouse" then
        local index = math.floor(tonumber(request.index) or 0)
        local cargoSelection = math.floor(
            tonumber(request.cargoType) or tonumber(self.selectedWarehouseCargo) or 1
        )
        return self:SetWarehouseStock(
            index, pending.target, pending.beforePersistent,
            cargoSelection, true, false, pending.identity
        )
    end
    if request.kind == "hangar" then
        if type(pending.expectedSlots) ~= "table" then return false end
        return self:CommitHangarPackingSnapshot(
            pending.target, pending.expectedSlots,
            pending.identity.characterSlot, pending.identity.playerId,
            identityCurrent
        )
    end
    if not identityCurrent() then return false end
    if not self:WriteRefillLiveValue(
        request, pending.target, pending.beforePersistent, pending.identity
    ) then
        return false
    end
    if not identityCurrent() then return false end
    if not self:WriteStatByIndex(
        pending.statIndex, pending.target, pending.identity.characterSlot
    ) then return false end
    if not identityCurrent() then return false end
    local saved = self:SaveStats()
    return saved and identityCurrent()
end

function SovereignBusinessInventory:ReconcilePendingRefill(request)
    local key = self:GetRefillRequestKey(request)
    if not key then return false end
    local pending = self.pendingRefillTransactions[key]
    if type(pending) ~= "table" then return true end
    local identityOk, identityReason = self:IsPendingRefillIdentityCurrent(pending)
    if not identityOk then
        self:QuarantinePendingRefill(
            key, pending, identityReason or "refill_identity_changed"
        )
        return false
    end
    local cleanupOk = self:EnsurePendingRefillTransactionCleanup(pending)
    if not cleanupOk then return false end
    local state = self:ReadPendingRefillState(pending)
    if (not state or state.persistent ~= pending.target or state.live ~= pending.target)
        and pending.transactionAccepted == true then
        local now = os.clock()
        if now >= (tonumber(pending.repairNextAt) or 0) then
            pending.repairAttempts = math.floor(tonumber(pending.repairAttempts) or 0) + 1
            self:RepairAcceptedPendingRefill(pending)
            local delay = math.min(30.0, 0.5 * (2 ^ math.min(6, pending.repairAttempts - 1)))
            pending.repairNextAt = now + delay
            state = self:ReadPendingRefillState(pending)
        end
    end
    if state and state.persistent == pending.target and state.live == pending.target then
        if pending.transactionAccepted ~= true then
            if pending.targetObserved ~= true then
                pending.targetObserved = true
                Logger:Warn("SovereignInventory", string.format(
                    "%s reached pending target without an accepted transaction receipt; keeping lock",
                    tostring(pending.request.name or pending.request.kind)
                ))
            end
            return false
        end
        self.pendingRefillTransactions[key] = nil
        self.lastRefillEvidence = {
            kind = pending.request.kind,
            index = pending.request.index,
            beforePersistent = pending.beforePersistent,
            beforeLive = pending.beforeLive,
            afterPersistent = state.persistent,
            afterLive = state.live,
            packingConfirmed = state.packingConfirmed == true,
            transactionAccepted = pending.transactionAccepted == true,
            reconciled = true,
            at = os.clock()
        }
        Logger:Info("SovereignInventory", string.format(
            "%s pending refill reconciled persistent=%s->%d live=%s->%d",
            tostring(pending.request.name or pending.request.kind),
            tostring(pending.beforePersistent), state.persistent,
            tostring(pending.beforeLive), state.live
        ))
        return true
    end
    return false
end

function SovereignBusinessInventory:GetFreeFreemodeTransactionSlot()
    if not self:HasInventoryMapping("transaction_layout") then
        return nil, nil, "transaction_mapping_unavailable"
    end
    local freeSlot, freeBase = nil, nil
    local sawReadable = false
    local sawHalfReleased = false
    for slot = 0, 14 do
        -- Global_4515492 is a script array; element zero starts after its
        -- header slot. Omitting +1 shifts the entire staged basket layout.
        local base = 4515492 + 1 + (slot * 84) + 65
        local state = self:ReadTransactionGlobal(base + 2, {
            attempts = 4,
            retryDelay = 25
        })
        local ownsBasket = self:ReadTransactionGlobal(base + 5, {
            attempts = 4,
            retryDelay = 25
        })
        if type(state) ~= "number" or type(ownsBasket) ~= "number" then
            -- One slot can be transiently unreadable while freemode rebuilds
            -- its array. Keep scanning; only an entirely unreadable array is
            -- reported as unavailable.
        else
            sawReadable = true
            state, ownsBasket = math.floor(state), math.floor(ownsBasket)
            if state ~= 0 and ownsBasket == 1 then
                return nil, nil, "transaction_busy"
            end
            if state == 0 and ownsBasket == 0 and freeSlot == nil then
                freeSlot, freeBase = slot, base
            elseif state == 0 and ownsBasket ~= 0 then
                -- State zero alone is not enough: f5 still attributes the
                -- process-global basket to this descriptor. Skip the half-
                -- released slot so a later clean slot can still be used.
                sawHalfReleased = true
            end
        end
    end
    if not sawReadable then return nil, nil, "transaction_state_unavailable" end
    if freeSlot == nil then
        return nil, nil, sawHalfReleased and "transaction_state_uncertain"
            or "transaction_busy"
    end
    return freeSlot, freeBase, nil
end

function SovereignBusinessInventory:ClearFreemodeTransactionOuterFields(base)
    if not self:HasInventoryMapping("transaction_layout") then return false end
    if type(base) ~= "number" then return false end
    base = math.floor(base)
    local outerBase = base - 65
    local writesOk = true
    -- Enhanced func_1743 clears outer fields 0..7 plus the full f_13 payload
    -- at 12..64. Fields 8..11 are not part of that reset routine.
    for offset = 0, 7 do
        if not self:WriteGlobal(outerBase + offset, 0) then writesOk = false end
    end
    for offset = 12, 64 do
        if not self:WriteGlobal(outerBase + offset, 0) then writesOk = false end
    end
    return writesOk
end

function SovereignBusinessInventory:VerifyFreemodeTransactionOuterFields(base)
    if not self:HasInventoryMapping("transaction_layout") then return false end
    if type(base) ~= "number" then return false end
    base = math.floor(base)
    local outerBase = base - 65
    for offset = 0, 7 do
        if self:ReadTransactionGlobal(outerBase + offset, {attempts = 1}) ~= 0 then
            return false
        end
    end
    for offset = 12, 64 do
        if self:ReadTransactionGlobal(outerBase + offset, {attempts = 1}) ~= 0 then
            return false
        end
    end
    return true
end

function SovereignBusinessInventory:ReadStableFreemodeTransactionIdentity(base, attempts)
    if not self:HasInventoryMapping("transaction_layout") then
        return nil, "transaction_mapping_unavailable"
    end
    if type(base) ~= "number" then
        return nil, "transaction_state_unavailable"
    end
    base = math.floor(base)
    attempts = math.max(1, math.min(8, math.floor(tonumber(attempts) or 2)))
    local sawReadable = false
    local function readOnce()
        local transactionId = self:ReadTransactionGlobal(base, {attempts = 1})
        local state = self:ReadTransactionGlobal(base + 2, {attempts = 1})
        local ownsBasket = self:ReadTransactionGlobal(base + 5, {attempts = 1})
        local frameCount = self:ReadTransactionGlobal(base + 14, {attempts = 1})
        if type(transactionId) ~= "number" or type(state) ~= "number"
            or type(ownsBasket) ~= "number" or type(frameCount) ~= "number" then
            return nil
        end
        return {
            transactionId = math.floor(transactionId),
            state = math.floor(state),
            ownsBasket = math.floor(ownsBasket),
            frameCount = math.floor(frameCount)
        }
    end
    for attempt = 1, attempts do
        local first = readOnce()
        local second = readOnce()
        if first and second then
            sawReadable = true
            if first.transactionId == second.transactionId
                and first.state == second.state
                and first.ownsBasket == second.ownsBasket
                and first.frameCount == second.frameCount then
                return second, nil
            end
        end
        if attempt < attempts and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, 25)
        end
    end
    return nil, sawReadable and "transaction_state_uncertain"
        or "transaction_state_unavailable"
end

function SovereignBusinessInventory:IsFreemodeTransactionSlotOwner(
    base, transactionId, frameCount, expectedState
)
    if type(base) ~= "number" or type(transactionId) ~= "number"
        or type(frameCount) ~= "number" then
        return false, "transaction_state_unavailable"
    end
    base = math.floor(base)
    local identity, identityReason = self:ReadStableFreemodeTransactionIdentity(base, 2)
    if not identity then return false, identityReason end
    if identity.transactionId ~= math.floor(transactionId)
        or identity.frameCount ~= math.floor(frameCount) then
        return false, "transaction_state_uncertain"
    end
    if identity.ownsBasket ~= 1 then
        return false, "transaction_state_uncertain"
    end
    if expectedState ~= nil then
        expectedState = tonumber(expectedState)
        if expectedState == nil or identity.state ~= math.floor(expectedState) then
            return false, "transaction_state_uncertain"
        end
    elseif identity.state ~= 1 and identity.state ~= 2 and identity.state ~= 3 then
        return false, "transaction_state_uncertain"
    end
    return true, nil
end

function SovereignBusinessInventory:IsFreemodeTransactionLocalClaimOwner(
    base, transactionId, frameCount
)
    if type(base) ~= "number" or type(transactionId) ~= "number"
        or type(frameCount) ~= "number" then
        return false, "transaction_state_unavailable"
    end
    local identity, identityReason = self:ReadStableFreemodeTransactionIdentity(
        math.floor(base), 2
    )
    if not identity then return false, identityReason end
    if identity.transactionId ~= math.floor(transactionId)
        or identity.frameCount ~= math.floor(frameCount)
        or identity.state ~= 1
        or (identity.ownsBasket ~= 0 and identity.ownsBasket ~= 1) then
        return false, "transaction_state_uncertain"
    end
    return true, nil
end

function SovereignBusinessInventory:ClearOwnedFreemodeTransactionSlot(
    base, transactionId, frameCount
)
    if type(base) ~= "number" or type(transactionId) ~= "number"
        or type(frameCount) ~= "number" then
        return false, "transaction_state_unavailable"
    end
    base, transactionId, frameCount = math.floor(base), math.floor(transactionId),
        math.floor(frameCount)
    local identity, identityReason = self:ReadStableFreemodeTransactionIdentity(base, 2)
    if not identity then return false, identityReason end
    if identity.state == 0 then
        if identity.ownsBasket == 0 then return true, nil end
        return false, "transaction_state_uncertain"
    end
    if identity.transactionId ~= transactionId or identity.frameCount ~= frameCount
        or (identity.state ~= 1 and identity.state ~= 2 and identity.state ~= 3) then
        return false, "transaction_state_uncertain"
    end

    if identity.ownsBasket == 1 then
        local expected = {
            [1] = 0,
            [3] = self:NormalizeSignedInt32(Utils.Joaat("NET_SHOP_TTYPE_INVALID")),
            [4] = self:NormalizeSignedInt32(Utils.Joaat("SERVICE_INVALID")),
            [6] = self:NormalizeSignedInt32(Utils.Joaat("CATEGORY_CLOTH")),
            [7] = self:NormalizeSignedInt32(Utils.Joaat("NET_SHOP_ACTION_INVALID")),
            [8] = 0, [9] = 0, [10] = 0, [11] = 0, [12] = 0,
            [13] = 0, [15] = 0, [16] = 0, [17] = 0, [18] = 0
        }
        local writesOk = self:ClearFreemodeTransactionOuterFields(base)
        for offset, value in pairs(expected) do
            if not self:WriteGlobal(base + offset, value) then writesOk = false end
        end
        if not writesOk or not self:VerifyFreemodeTransactionOuterFields(base) then
            return false, "transaction_state_unavailable"
        end
        for offset, value in pairs(expected) do
            if self:ReadTransactionGlobal(base + offset, {attempts = 1}) ~= value then
                return false, "transaction_state_unavailable"
            end
        end
        local stillOwned, ownerReason = self:IsFreemodeTransactionSlotOwner(
            base, transactionId, frameCount
        )
        if not stillOwned then
            return false, ownerReason or "transaction_state_uncertain"
        end
        if not self:WriteGlobal(base + 5, 0) then
            local afterRelease, releaseReason =
                self:ReadStableFreemodeTransactionIdentity(base, 1)
            if not afterRelease then return false, releaseReason end
            if afterRelease.state == 0 then
                if afterRelease.ownsBasket == 0 then return true, nil end
                return false, "transaction_state_uncertain"
            end
            if afterRelease.transactionId ~= transactionId
                or afterRelease.frameCount ~= frameCount
                or afterRelease.ownsBasket ~= 0 then
                return false, "transaction_state_uncertain"
            end
        end
    elseif identity.ownsBasket ~= 0 then
        return false, "transaction_state_uncertain"
    end

    -- Keep tx/frame as the recoverable cleanup identity. State zero is the
    -- authoritative free marker, and the next claimant overwrites both before
    -- publishing f5=1. This avoids an unrecoverable half-cleaned active slot.
    local releaseIdentity, releaseReason =
        self:ReadStableFreemodeTransactionIdentity(base, 2)
    if not releaseIdentity then return false, releaseReason end
    if releaseIdentity.state == 0 then
        if releaseIdentity.ownsBasket == 0 then return true, nil end
        return false, "transaction_state_uncertain"
    end
    if releaseIdentity.transactionId ~= transactionId
        or releaseIdentity.frameCount ~= frameCount
        or releaseIdentity.ownsBasket ~= 0
        or (releaseIdentity.state ~= 1 and releaseIdentity.state ~= 2
            and releaseIdentity.state ~= 3) then
        return false, "transaction_state_uncertain"
    end
    local stateReleased = self:WriteGlobal(base + 2, 0)
    local finalIdentity, finalReason =
        self:ReadStableFreemodeTransactionIdentity(base, 1)
    if finalIdentity and finalIdentity.state == 0 then
        if finalIdentity.ownsBasket == 0 then return true, nil end
        return false, "transaction_state_uncertain"
    end
    if stateReleased then
        -- The state-zero write completed without yielding. If freemode already
        -- claimed the slot again, a different identity proves our release was
        -- consumed successfully and must not be reported as cleanup failure.
        if not finalIdentity then
            return false, finalReason or "transaction_state_unavailable"
        end
        if finalIdentity.state ~= 0
            and (finalIdentity.transactionId ~= transactionId
                or finalIdentity.frameCount ~= frameCount) then
            return true, nil
        end
        return false, "transaction_state_unavailable"
    end
    if finalIdentity and finalIdentity.transactionId == transactionId
        and finalIdentity.frameCount == frameCount and finalIdentity.ownsBasket == 0 then
        return false, "transaction_state_unavailable"
    end
    return false, finalReason or "transaction_state_uncertain"
end

function SovereignBusinessInventory:EndFreemodeBasketAndVerify(
    attempts, ownershipGuard, onEndInvoked
)
    if not menu.nativeApis.NETSHOPPING
        or type(menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE) ~= "function"
        or type(menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_END) ~= "function"
        or not Script or type(Script.ExecuteAsScript) ~= "function" then
        return false, "transaction_state_unavailable"
    end
    attempts = math.max(1, math.min(12, math.floor(tonumber(attempts) or 6)))
    local lastReason = "transaction_cleanup_unconfirmed"
    local endAttempted = false
    for attempt = 1, attempts do
        local readOk, active = pcall(menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE)
        if readOk and active == false then return true, nil, endAttempted end
        if readOk and active == true and not endAttempted then
            local guardAllowed = true
            local guardFailure = nil
            local endOk = pcall(Script.ExecuteAsScript, "freemode", function()
                if type(ownershipGuard) == "function" then
                    local guardOk, allowed, guardReason = pcall(ownershipGuard)
                    if not guardOk or allowed ~= true then
                        guardAllowed = false
                        guardFailure = tostring(
                            guardReason or "transaction_state_uncertain"
                        )
                        return
                    end
                end
                if menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE() then
                    -- Mark the attempt before invoking the native. If the
                    -- binding throws after queuing END, retrying could end a
                    -- different basket that becomes active during readback.
                    endAttempted = true
                    if type(onEndInvoked) == "function" then
                        pcall(onEndInvoked)
                    end
                    menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_END()
                end
            end)
            if not guardAllowed then
                return false, guardFailure or "transaction_state_uncertain", false
            end
            if not endOk then lastReason = "transaction_state_unavailable" end
        else
            if not readOk then lastReason = "transaction_state_unavailable" end
        end
        local verifyOk, stillActive = pcall(
            menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE
        )
        if verifyOk and stillActive == false then
            return true, nil, endAttempted
        end
        if not verifyOk then lastReason = "transaction_state_unavailable" end
        if attempt < attempts and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, 50)
        end
    end
    return false, lastReason, endAttempted
end

function SovereignBusinessInventory:EnsureFreemodeTransactionSettled(context)
    if context == nil then return true, nil end
    if type(context) ~= "table" then
        return false, "transaction_state_unavailable"
    end
    local now = os.clock()
    context.createdAt = tonumber(context.createdAt) or now
    context.cleanupDeadline = tonumber(context.cleanupDeadline)
        or (context.createdAt + 45.0)
    local function transactionEngineIdle()
        if not menu.nativeApis.NETSHOPPING
            or type(menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE) ~= "function"
            or type(menu.nativeApis.NETSHOPPING.NET_GAMESERVER_TRANSACTION_IN_PROGRESS)
                ~= "function" then
            return false
        end
        local basketOk, basketActive = pcall(
            menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE
        )
        local progressOk, inProgress = pcall(
            menu.nativeApis.NETSHOPPING.NET_GAMESERVER_TRANSACTION_IN_PROGRESS
        )
        return basketOk and progressOk and basketActive == false
            and inProgress == false
    end
    local function endContextBasketOnce(ownershipGuard)
        if not menu.nativeApis.NETSHOPPING
            or type(menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE) ~= "function" then
            return false, "transaction_state_unavailable"
        end
        local activeOk, active = pcall(
            menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE
        )
        if activeOk and active == false then return true, nil end
        if not activeOk then return false, "transaction_state_unavailable" end
        if context.basketEndAttempted == true then
            return false, "transaction_cleanup_unconfirmed"
        end
        return self:EndFreemodeBasketAndVerify(
            6, ownershipGuard,
            function() context.basketEndAttempted = true end
        )
    end
    local function clearExactHalfReleasedMarker(base, transactionId, frameCount)
        base, transactionId, frameCount = tonumber(base), tonumber(transactionId),
            tonumber(frameCount)
        if base == nil or transactionId == nil or frameCount == nil then
            return false, "transaction_state_unavailable"
        end
        base, transactionId, frameCount = math.floor(base), math.floor(transactionId),
            math.floor(frameCount)
        local before, beforeReason = self:ReadStableFreemodeTransactionIdentity(base, 2)
        if not before then return false, beforeReason end
        if before.state ~= 0 or before.ownsBasket ~= 1
            or before.transactionId ~= transactionId
            or before.frameCount ~= frameCount then
            return false, "transaction_state_uncertain"
        end
        if not transactionEngineIdle() then
            return false, "transaction_cleanup_unconfirmed"
        end
        local writeOk = self:WriteGlobal(base + 5, 0)
        local first = self:ReadStableFreemodeTransactionIdentity(base, 1)
        local second = self:ReadStableFreemodeTransactionIdentity(base, 1)
        if first and second and first.state == 0 and first.ownsBasket == 0
            and second.state == 0 and second.ownsBasket == 0 then
            return true, nil
        end
        return false, writeOk and "transaction_state_uncertain"
            or "transaction_state_unavailable"
    end
    if context.slotTombstone == true then
        local identity, identityReason =
            self:ReadStableFreemodeTransactionIdentity(context.base, 2)
        if not identity then
            return false, identityReason or "transaction_state_unavailable"
        end
        local baselineTransactionId = tonumber(context.baselineTransactionId)
        local baselineFrameCount = tonumber(context.baselineFrameCount)
        local targetTransactionId = tonumber(context.targetTransactionId)
        local targetFrameCount = tonumber(context.targetFrameCount)
        local targetIdentity = targetTransactionId ~= nil
            and targetFrameCount ~= nil
            and identity.transactionId == math.floor(targetTransactionId)
            and identity.frameCount == math.floor(targetFrameCount)
        local baselineIdentity = baselineTransactionId ~= nil
            and baselineFrameCount ~= nil
            and identity.transactionId == math.floor(baselineTransactionId)
            and identity.frameCount == math.floor(baselineFrameCount)
        local transitionWindowOpen = context.publishedIdentityTransition == true
            and now <= (tonumber(context.publishedIdentityTransitionExpiresAt)
                or -rawget(math, "huge"))
        local publishedIdentityCandidate = targetIdentity
            or (transitionWindowOpen and baselineIdentity)
        local transactionTargetObserved = context.transactionWriteAttempted == true
            and targetTransactionId ~= nil
            and identity.transactionId == math.floor(targetTransactionId)
            and (baselineTransactionId == nil
                or math.floor(targetTransactionId)
                    ~= math.floor(baselineTransactionId))
        local frameTargetObserved = context.frameWriteAttempted == true
            and targetFrameCount ~= nil
            and identity.frameCount == math.floor(targetFrameCount)
            and (baselineFrameCount == nil
                or math.floor(targetFrameCount) ~= math.floor(baselineFrameCount))
        local transactionCandidate = baselineTransactionId ~= nil
            and identity.transactionId == math.floor(baselineTransactionId)
        if transactionTargetObserved then transactionCandidate = true end
        local frameCandidate = baselineFrameCount ~= nil
            and identity.frameCount == math.floor(baselineFrameCount)
        if frameTargetObserved then frameCandidate = true end
        local targetFieldObserved = transactionTargetObserved
            or frameTargetObserved
        local attributableLocalClaim = identity.state == 1
            and identity.ownsBasket == 0
            and transactionCandidate and frameCandidate and targetFieldObserved
        local matchesBaselineClaim = baselineIdentity and identity.state == 1
            and identity.ownsBasket == 0
        local publishedBasketOwner = context.basketOwnerWriteAttempted == true
            and publishedIdentityCandidate and identity.state == 1
            and identity.ownsBasket == 1
        local unattributedActiveBaselineOwner = baselineIdentity
            and identity.state == 1 and identity.ownsBasket == 1
            and not publishedBasketOwner

        -- This guard must run even when the caller already observed the
        -- process basket as inactive and cleared basketEndPending. The slot
        -- marker itself still blocks GetFreeFreemodeTransactionSlot; treating
        -- it as foreign here would unlock a second request into that stale
        -- state. Keep it quarantined until the normal cleanup deadline.
        if unattributedActiveBaselineOwner and context.outcomePending ~= true then
            return false, "transaction_cleanup_unconfirmed"
        end

        if context.outcomePending == true then
            if targetIdentity and (identity.state == 2 or identity.state == 3) then
                context.slotTombstone = false
                context.transactionId = math.floor(targetTransactionId)
                context.frameCount = math.floor(targetFrameCount)
                context.outcomePending = false
                context.serverAccepted = identity.state == 2
                context.serverRejected = identity.state == 3
                return self:EnsureFreemodeTransactionSettled(context)
            end
            if now >= context.cleanupDeadline then
                if targetIdentity and identity.state == 1 then
                    if identity.ownsBasket == 1 then
                        if not publishedBasketOwner then
                            return false, "transaction_state_uncertain"
                        end
                        local ended, endReason = endContextBasketOnce(function()
                            return self:IsFreemodeTransactionSlotOwner(
                                context.base, math.floor(targetTransactionId),
                                math.floor(targetFrameCount), 1
                            )
                        end)
                        if not ended then
                            return false, endReason or "transaction_cleanup_unconfirmed"
                        end
                    elseif identity.ownsBasket ~= 0 then
                        return false, "transaction_state_uncertain"
                    end
                    if identity.ownsBasket ~= 0 and not transactionEngineIdle() then
                        return false, "transaction_cleanup_unconfirmed"
                    end
                    context.slotTombstone = false
                    context.transactionId = math.floor(targetTransactionId)
                    context.frameCount = math.floor(targetFrameCount)
                    context.basketEndPending = false
                    context.outcomePending = false
                    local cleared = self:ClearOwnedFreemodeTransactionSlot(
                        context.base, context.transactionId, context.frameCount
                    )
                    if cleared then
                        context.outcomeAbandoned = true
                        return true, "transaction_outcome_unconfirmed"
                    end
                elseif context.basketOwnerWriteAttempted == true
                    and targetIdentity and identity.state == 0
                    and identity.ownsBasket == 1 then
                    local cleared, clearReason = clearExactHalfReleasedMarker(
                        context.base, targetTransactionId, targetFrameCount
                    )
                    if not cleared then return false, clearReason end
                    context.basketEndPending = false
                    context.outcomePending = false
                    context.outcomeAbandoned = true
                    return true, "transaction_outcome_unconfirmed"
                elseif (identity.state == 0 and identity.ownsBasket == 0)
                    or not targetIdentity then
                    context.basketEndPending = false
                    context.outcomePending = false
                    context.outcomeAbandoned = true
                    return true, "transaction_outcome_unconfirmed"
                end
            end
            -- Publication may have been observed by freemode. State zero or a
            -- foreign identity is not a rejection receipt, so keep this key
            -- isolated instead of resubmitting the same transaction.
            return false, "transaction_state_uncertain"
        end

        if context.basketEndPending == true then
            if identity.state == 0 and identity.ownsBasket == 0 then
                context.basketEndPending = false
            elseif attributableLocalClaim then
                -- f5=0 owns only this descriptor. It never proves ownership of
                -- the process-global basket, which may now belong to another path.
                context.basketEndPending = false
            elseif matchesBaselineClaim then
                -- A pure baseline tuple has no field-level proof that our writes
                -- became visible. It may be another local claimant, so only the
                -- deadline + engine-idle path below may clear its state marker.
                context.basketEndPending = false
            elseif publishedBasketOwner then
                local ownedTransactionId = identity.transactionId
                local ownedFrameCount = identity.frameCount
                local ended, endReason = endContextBasketOnce(function()
                    return self:IsFreemodeTransactionSlotOwner(
                        context.base, ownedTransactionId, ownedFrameCount, 1
                    )
                end)
                if not ended then
                    return false, endReason or "transaction_cleanup_unconfirmed"
                end
                context.basketEndPending = false
            elseif context.basketOwnerWriteAttempted == true
                and publishedIdentityCandidate
                and identity.state == 0 and identity.ownsBasket == 1 then
                -- A half-released exact marker is handled below after the
                -- cleanup deadline and engine-idle proof.
            elseif now >= (tonumber(context.tombstoneNotBefore) or now) then
                -- Stable foreign reuse proves the unpublished descriptor no
                -- longer owns this slot. Never touch or END the foreign owner.
                context.basketEndPending = false
                return true, nil
            else
                -- Without f5=1 on the exact tx/frame identity there is no safe
                -- owner guard for BASKET_END.
                return false, "transaction_cleanup_unconfirmed"
            end
        end
        if attributableLocalClaim or publishedBasketOwner then
            local ownedTransactionId = identity.transactionId
            local ownedFrameCount = identity.frameCount
            local cleared, clearReason = self:ClearOwnedFreemodeTransactionSlot(
                context.base, ownedTransactionId, ownedFrameCount
            )
            if not cleared then return false, clearReason end
            identity = self:ReadStableFreemodeTransactionIdentity(context.base, 2)
            if not identity then return false, "transaction_state_unavailable" end
        end
        if context.basketOwnerWriteAttempted == true
            and publishedIdentityCandidate
            and identity.state == 0 and identity.ownsBasket == 1
            and now >= context.cleanupDeadline then
            local cleared, clearReason = clearExactHalfReleasedMarker(
                context.base, identity.transactionId, identity.frameCount
            )
            if not cleared then return false, clearReason end
            return true, nil
        end
        if identity.state == 0 and identity.ownsBasket == 0
            and now >= (tonumber(context.tombstoneNotBefore) or now) then
            context.zeroSamples = math.floor(tonumber(context.zeroSamples) or 0) + 1
            if context.zeroSamples >= 2 then return true, nil end
            return false, "transaction_cleanup_unconfirmed"
        end
        context.zeroSamples = 0
        if matchesBaselineClaim and now >= context.cleanupDeadline
            and transactionEngineIdle() then
            local confirmed = self:ReadStableFreemodeTransactionIdentity(
                context.base, 2
            )
            if confirmed and confirmed.transactionId == math.floor(baselineTransactionId)
                and confirmed.frameCount == math.floor(baselineFrameCount)
                and confirmed.state == 1 and confirmed.ownsBasket == 0 then
                local writeOk = self:WriteGlobal(context.base + 2, 0)
                local first = self:ReadStableFreemodeTransactionIdentity(
                    context.base, 1
                )
                local second = self:ReadStableFreemodeTransactionIdentity(
                    context.base, 1
                )
                if first and second and first.state == 0 and first.ownsBasket == 0
                    and second.state == 0 and second.ownsBasket == 0 then
                    return true, nil
                end
                return false, writeOk and "transaction_state_uncertain"
                    or "transaction_state_unavailable"
            end
        end
        local attributableHalfRelease = context.basketOwnerWriteAttempted == true
            and publishedIdentityCandidate and identity.state == 0
            and identity.ownsBasket == 1
        if not matchesBaselineClaim
            and not attributableLocalClaim
            and not publishedBasketOwner
            and not attributableHalfRelease
            and now >= (tonumber(context.tombstoneNotBefore) or now) then
            -- A stable foreign descriptor after the quiet window proves this
            -- unpublished claim no longer owns the slot. Do not modify it.
            return true, nil
        end
        return false, "transaction_cleanup_unconfirmed"
    end
    if context.passiveBasketCleanup == true then
        if not menu.nativeApis.NETSHOPPING
            or type(menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE) ~= "function" then
            return false, "transaction_state_unavailable"
        end
        local attempts = math.max(1, math.min(8, math.floor(
            tonumber(context.attempts) or 3
        )))
        local passiveNotBefore = tonumber(context.passiveNotBefore)
            or ((tonumber(context.createdAt) or now) + 1.0)
        context.passiveNotBefore = passiveNotBefore
        local lastReason = "transaction_cleanup_unconfirmed"
        for attempt = 1, attempts do
            local readOk, active = pcall(
                menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE
            )
            if readOk and active == false then
                context.inactiveSamples = math.floor(
                    tonumber(context.inactiveSamples) or 0
                ) + 1
                if context.inactiveSamples >= 2 and os.clock() >= passiveNotBefore then
                    context.basketEndPending = false
                    return true, nil
                end
            elseif readOk then
                context.inactiveSamples = 0
            end
            if not readOk then lastReason = "transaction_state_unavailable" end
            if attempt < attempts and Script and type(Script.Yield) == "function" then
                pcall(Script.Yield, 50)
            end
        end
        return false, lastReason
    end
    local base = tonumber(context.base)
    local transactionId = tonumber(context.transactionId)
    local frameCount = tonumber(context.frameCount)
    if base == nil or transactionId == nil or frameCount == nil
        or base ~= base or transactionId ~= transactionId or frameCount ~= frameCount then
        return false, "transaction_state_unavailable"
    end
    base, transactionId, frameCount = math.floor(base), math.floor(transactionId),
        math.floor(frameCount)
    local attempts = math.max(1, math.min(8, math.floor(
        tonumber(context.attempts) or 3
    )))
    local lastReason = "transaction_cleanup_unconfirmed"
    for attempt = 1, attempts do
        local identity, identityReason =
            self:ReadStableFreemodeTransactionIdentity(base, 2)
        if not identity then
            lastReason = identityReason or "transaction_state_unavailable"
        elseif identity.state == 0 then
            if identity.ownsBasket ~= 0 then
                if identity.ownsBasket ~= 1 then
                    lastReason = "transaction_state_uncertain"
                else
                    local exactHalfReleased = identity.transactionId == transactionId
                        and identity.frameCount == frameCount
                    local terminalOrLocal = context.outcomePending ~= true
                        and (context.serverAccepted == true
                            or context.serverRejected == true
                            or context.localOnlyCleanup == true)
                    local abandonOutcome = context.outcomePending == true
                        and now >= context.cleanupDeadline
                    if exactHalfReleased and (terminalOrLocal or abandonOutcome) then
                        local activeOk, active = pcall(
                            menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE
                        )
                        if not activeOk then
                            lastReason = "transaction_state_unavailable"
                        elseif active == true then
                            local ended, endReason = endContextBasketOnce(function()
                                local current =
                                    self:ReadStableFreemodeTransactionIdentity(base, 2)
                                return current ~= nil and current.state == 0
                                    and current.ownsBasket == 1
                                    and current.transactionId == transactionId
                                    and current.frameCount == frameCount
                            end)
                            if not ended then
                                lastReason = endReason
                                    or "transaction_cleanup_unconfirmed"
                            end
                        end
                        if transactionEngineIdle() then
                            local cleared, clearReason = clearExactHalfReleasedMarker(
                                base, transactionId, frameCount
                            )
                            if cleared then
                                context.basketEndPending = false
                                if abandonOutcome then
                                    context.outcomePending = false
                                    context.outcomeAbandoned = true
                                    return true, "transaction_outcome_unconfirmed"
                                end
                                return true, nil
                            end
                            lastReason = clearReason
                                or "transaction_cleanup_unconfirmed"
                        end
                    elseif not exactHalfReleased and terminalOrLocal then
                        -- A stable foreign half-released descriptor is never
                        -- ours to modify. It also proves this request's exact
                        -- terminal/local descriptor has already been released.
                        context.basketEndPending = false
                        return true, nil
                    elseif not exactHalfReleased and abandonOutcome then
                        context.basketEndPending = false
                        context.outcomePending = false
                        context.outcomeAbandoned = true
                        return true, "transaction_outcome_unconfirmed"
                    else
                        lastReason = "transaction_state_uncertain"
                    end
                end
            elseif context.outcomePending == true then
                if now >= context.cleanupDeadline then
                    context.basketEndPending = false
                    context.outcomePending = false
                    context.outcomeAbandoned = true
                    return true, "transaction_outcome_unconfirmed"
                end
                return false, "transaction_state_uncertain"
            elseif context.basketEndPending == true then
                -- state=0/f5=0 proves this descriptor has released its basket.
                -- A simultaneously active process basket belongs elsewhere.
                context.basketEndPending = false
                return true, nil
            else
                return true, nil
            end
        elseif identity.transactionId ~= transactionId
            or identity.frameCount ~= frameCount then
            -- Once a terminal receipt is known and this request no longer has
            -- an attributable basket, a different stable identity proves the
            -- old descriptor was released and reused. Never touch the new one.
            if context.outcomePending ~= true
                and (context.serverAccepted == true
                    or context.serverRejected == true) then
                context.basketEndPending = false
                return true, nil
            end
            if context.outcomePending == true and now >= context.cleanupDeadline then
                context.basketEndPending = false
                context.outcomePending = false
                context.outcomeAbandoned = true
                return true, "transaction_outcome_unconfirmed"
            end
            return false, "transaction_state_uncertain"
        elseif identity.state == 2 or identity.state == 3 then
            if context.localOnlyCleanup == true then
                -- No event was sent for a local-only context. A response state
                -- here cannot be attributed safely, so never clear or retry it.
                return false, "transaction_state_uncertain"
            end
            context.outcomePending = false
            context.serverAccepted = identity.state == 2
            context.serverRejected = identity.state == 3
            if identity.state == 2
                and type(context.onAcceptedBeforeCleanup) == "function" then
                local receipt = type(context.acceptedReceipt) == "table"
                    and context.acceptedReceipt or {}
                context.acceptedReceipt = receipt
                if receipt.callbackInvoked ~= true then
                    receipt.base = base
                    receipt.slot = context.slot
                    receipt.transactionId = transactionId
                    receipt.frameCount = frameCount
                    receipt.state = 2
                    receipt.serverAccepted = true
                    -- Record the attempt before entering caller code. Cleanup
                    -- retries must never repeat a consumed native request.
                    receipt.callbackInvoked = true
                    local callbackOk, completed, callbackReason = pcall(
                        context.onAcceptedBeforeCleanup, receipt
                    )
                    receipt.callbackCompleted = callbackOk and completed == true
                    if not receipt.callbackCompleted then
                        receipt.callbackReason = callbackOk and callbackReason
                            or "transaction_runtime_exception"
                        receipt.callbackReason = receipt.callbackReason
                            or "transaction_state_uncertain"
                    end
                end
            end
            if context.basketEndPending == true then
                if identity.ownsBasket == 0 then
                    -- Terminal f5=0 means this descriptor does not own the
                    -- process basket. Clear only the exact slot below.
                    context.basketEndPending = false
                elseif identity.ownsBasket == 1 then
                    local ended, endReason = endContextBasketOnce(function()
                        return self:IsFreemodeTransactionSlotOwner(
                            base, transactionId, frameCount, identity.state
                        )
                    end)
                    if not ended then
                        lastReason = endReason or "transaction_cleanup_unconfirmed"
                    else
                        context.basketEndPending = false
                    end
                else
                    return false, "transaction_state_uncertain"
                end
            end
            if context.basketEndPending ~= true then
                local cleared, clearReason = self:ClearOwnedFreemodeTransactionSlot(
                    base, transactionId, frameCount
                )
                if cleared then return true, nil end
                lastReason = clearReason or "transaction_cleanup_unconfirmed"
            end
        elseif identity.state == 1 then
            if context.localOnlyCleanup == true then
                if identity.ownsBasket == 0 then
                    context.basketEndPending = false
                elseif identity.ownsBasket == 1 and context.basketEndPending == true then
                    local ended, endReason = endContextBasketOnce(
                        function()
                            return self:IsFreemodeTransactionSlotOwner(
                                base, transactionId, frameCount, 1
                            )
                        end
                    )
                    if not ended then
                        lastReason = endReason or "transaction_cleanup_unconfirmed"
                    else
                        context.basketEndPending = false
                    end
                elseif identity.ownsBasket ~= 1 then
                    return false, "transaction_state_uncertain"
                end
                if context.basketEndPending == true then
                    -- Preserve the state-1 owner until its basket is inactive;
                    -- otherwise a later retry could end an unrelated basket.
                else
                    local cleared, clearReason = self:ClearOwnedFreemodeTransactionSlot(
                        base, transactionId, frameCount
                    )
                    if cleared then return true, nil end
                    lastReason = clearReason or "transaction_cleanup_unconfirmed"
                end
            else
                -- Do not clear a still-pending server response. Retry after a
                -- short yield; the accepted-result path normally reaches state 2.
                if context.outcomePending == true and now >= context.cleanupDeadline then
                    if identity.ownsBasket == 1 then
                        local ended, endReason = endContextBasketOnce(function()
                            return self:IsFreemodeTransactionSlotOwner(
                                base, transactionId, frameCount, 1
                            )
                        end)
                        if not ended then
                            lastReason = endReason or "transaction_cleanup_unconfirmed"
                        end
                    elseif identity.ownsBasket ~= 0 then
                        lastReason = "transaction_state_uncertain"
                    end
                    local cleanupReady = identity.ownsBasket == 0
                        or transactionEngineIdle()
                    if cleanupReady then
                        context.basketEndPending = false
                        local cleared, clearReason =
                            self:ClearOwnedFreemodeTransactionSlot(
                                base, transactionId, frameCount
                            )
                        if cleared then
                            context.outcomePending = false
                            context.outcomeAbandoned = true
                            return true, "transaction_outcome_unconfirmed"
                        end
                        lastReason = clearReason or "transaction_cleanup_unconfirmed"
                    end
                else
                    lastReason = "transaction_cleanup_unconfirmed"
                end
            end
        else
            return false, "transaction_state_uncertain"
        end
        if attempt < attempts and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, 50)
        end
    end
    return false, lastReason
end

function SovereignBusinessInventory:StageFreemodeBasketTransaction(
    slotBase, transactionId, itemHash, category, service, itemDataF1, itemDataF2,
    descriptorF10, prePublishGuard
)
    -- This function runs after BASKET_START and before ADD_ITEM, matching
    -- Enhanced func_2195 -> func_2129 -> func_2193. It must remain yield-free
    -- until f5 publishes an exact basket owner.
    local initialIdentity, initialReason =
        self:ReadStableFreemodeTransactionIdentity(slotBase, 1)
    if not initialIdentity then
        return false, nil, initialReason or "transaction_state_unavailable"
    end
    if initialIdentity.state ~= 0 then
        return false, nil, "transaction_busy"
    end
    if initialIdentity.ownsBasket ~= 0 then
        return false, nil, "transaction_state_uncertain"
    end
    local function normalizeTransactionInt(value, fallback)
        local normalized = self:NormalizeSignedInt32(value)
        return normalized == nil and fallback or normalized
    end
    transactionId = normalizeTransactionInt(transactionId, nil)
    itemHash = normalizeTransactionInt(itemHash, nil)
    category = normalizeTransactionInt(
        category or Utils.Joaat("CATEGORY_CONTRABAND_QNTY"), nil
    )
    service = normalizeTransactionInt(service or -886368739, nil)
    itemDataF1 = normalizeTransactionInt(itemDataF1, 0)
    itemDataF2 = normalizeTransactionInt(itemDataF2, 0)
    descriptorF10 = normalizeTransactionInt(descriptorF10, 4)
    if transactionId == nil or itemHash == nil or category == nil or service == nil then
        return false, nil, "transaction_state_unavailable"
    end

    local frameCount = 0
    if menu.nativeApis.MISC and type(menu.nativeApis.MISC.GET_FRAME_COUNT) == "function" then
        local ok, value = pcall(menu.nativeApis.MISC.GET_FRAME_COUNT)
        if ok then frameCount = normalizeTransactionInt(value, 0) end
    end
    local transactionWriteAttempted = false
    local frameWriteAttempted = false
    local basketOwnerWriteAttempted = false
    local function makeStageTombstone(
        identityPublished, publicationUncertain, observedIdentity
    )
        local createdAt = os.clock()
        local observedTransactionId = type(observedIdentity) == "table"
            and tonumber(observedIdentity.transactionId) or nil
        local observedFrameCount = type(observedIdentity) == "table"
            and tonumber(observedIdentity.frameCount) or nil
        return {
            base = slotBase,
            slotTombstone = true,
            -- Every Stage failure occurs before Dispatch invokes a sender.
            -- Descriptor publication may be uncertain, but server outcome is
            -- not: this remains local cleanup and must never suppress BASKET_END.
            localOnlyCleanup = true,
            outcomePending = false,
            basketEndPending = true,
            publicationUncertain = publicationUncertain == true,
            expectedTransactionId = observedTransactionId
                or (identityPublished and transactionId or nil),
            expectedFrameCount = observedFrameCount
                or (identityPublished and frameCount or nil),
            targetTransactionId = transactionId,
            targetFrameCount = frameCount,
            transactionWriteAttempted = transactionWriteAttempted == true,
            frameWriteAttempted = frameWriteAttempted == true,
            basketOwnerWriteAttempted = basketOwnerWriteAttempted == true,
            baselineTransactionId = initialIdentity.transactionId,
            baselineFrameCount = initialIdentity.frameCount,
            createdAt = createdAt,
            cleanupDeadline = createdAt + 45.0,
            tombstoneNotBefore = createdAt + 1.0,
            attempts = 6
        }
    end

    -- Enhanced func_2129 claims f_65.f_2 before filling the descriptor. Keep
    -- this block yield-free so freemode cannot select the same zero-state slot
    -- between our field writes.
    local claimObservedOwned = false
    local claimWriteAccepted = self:WriteGlobal(slotBase + 2, 1)
    if not claimWriteAccepted then
        local observedState = self:ReadTransactionGlobal(slotBase + 2, {attempts = 1})
        if observedState == 0 then
            -- SetInt can report failure before a queued write becomes visible.
            -- Without a stable owner identity, any compensating zero write can
            -- erase a concurrent freemode claimant. Leave a baseline tombstone
            -- to observe and release only an attributable delayed claim.
            return false, frameCount, "transaction_state_unavailable", true, nil,
                makeStageTombstone(false, false)
        end
        if observedState ~= 1 then
            return false, frameCount, "transaction_state_uncertain", true, nil,
                makeStageTombstone(false, true)
        end
        claimObservedOwned = true
        -- The binding returned false after the in-process write became
        -- visible. Continue under the observed state-1 claim instead of
        -- leaking an unpublished slot.
    end
    local claimedState = self:ReadTransactionGlobal(slotBase + 2, {attempts = 1})
    if claimedState == nil then
        -- No Yield here: only confirm the synchronous SetInt propagation.
        for _ = 1, 2 do
            claimedState = self:ReadTransactionGlobal(slotBase + 2, {attempts = 1})
            if claimedState ~= nil then break end
        end
    end
    if claimedState ~= 1 then
        -- Never fill or publish a descriptor until the state-1 claim is
        -- actually observable. A nil/zero read can be a delayed SetInt; any
        -- yielding descriptor validation after that point could overwrite a
        -- different claimant that selected the still-visible free slot.
        return false, frameCount, "transaction_state_uncertain", true, nil,
            makeStageTombstone(false, true)
    end

    local identityPublished = false
    local lastAttributableIdentity = nil
    local function isAttributableUnpublishedIdentity(identity)
        if type(identity) ~= "table" or identity.state ~= 1
            or identity.ownsBasket ~= 0
            or not (claimWriteAccepted or claimObservedOwned) then
            return false
        end
        local transactionMatches = identity.transactionId == initialIdentity.transactionId
            or (transactionWriteAttempted and identity.transactionId == transactionId)
        local frameMatches = identity.frameCount == initialIdentity.frameCount
            or (frameWriteAttempted and identity.frameCount == frameCount)
        return transactionMatches and frameMatches
    end
    local function verifyReleasedClaim()
        local consecutive = 0
        for attempt = 1, 4 do
            local identity = self:ReadStableFreemodeTransactionIdentity(slotBase, 1)
            if identity and identity.state == 0 and identity.ownsBasket == 0 then
                consecutive = consecutive + 1
                if consecutive >= 2 then return true end
            else
                consecutive = 0
            end
        end
        return false
    end
    local function rollbackUnpublishedClaim()
        -- No event has been sent and f5 is kept zero until the descriptor is
        -- complete. SetInt can become readable one frame late, so order an f5
        -- reset and state release even when the immediate read still shows 0.
        local identity = self:ReadStableFreemodeTransactionIdentity(slotBase, 1)
        if not identity then return false end
        if identity.state == 0 and identity.ownsBasket == 0 then
            return verifyReleasedClaim()
        end
        local ownsClaim = false
        if identityPublished then
            if identity and identity.state == 1
                and identity.transactionId == transactionId
                and identity.frameCount == frameCount
                and (identity.ownsBasket == 0 or identity.ownsBasket == 1) then
                ownsClaim = true
            elseif identity.state ~= 0 then
                -- A different live identity is never ours to release.
                return false
            end
        elseif not identityPublished
            and isAttributableUnpublishedIdentity(identity) then
            -- Before the first possible Yield, tx and frame can each be either
            -- their baseline or new value when a binding reports failure after
            -- applying only part of the write sequence. This bounded tuple is
            -- still attributable to our synchronous state-1/f5-zero claim.
            ownsClaim = true
        end
        if not ownsClaim then return false end
        lastAttributableIdentity = identity
        self:WriteGlobal(slotBase + 5, 0)
        self:WriteGlobal(slotBase + 2, 0)
        return verifyReleasedClaim()
    end
    local function failBeforePublish(reason)
        local rolledBack = rollbackUnpublishedClaim()
        local observedIdentity = nil
        if not rolledBack then
            local current = self:ReadStableFreemodeTransactionIdentity(slotBase, 1)
            if identityPublished and current and current.state == 1
                and current.ownsBasket == 0
                and current.transactionId == transactionId
                and current.frameCount == frameCount then
                observedIdentity = current
            elseif not identityPublished
                and isAttributableUnpublishedIdentity(current) then
                observedIdentity = current
            else
                observedIdentity = lastAttributableIdentity
            end
        end
        return false, frameCount, reason or "transaction_state_unavailable",
            not rolledBack, nil,
            rolledBack and nil or makeStageTombstone(
                identityPublished, false, observedIdentity
            )
    end

    transactionWriteAttempted = true
    if not self:WriteGlobal(slotBase, transactionId) then
        return failBeforePublish("transaction_state_unavailable")
    end
    frameWriteAttempted = true
    if not self:WriteGlobal(slotBase + 14, frameCount) then
        return failBeforePublish("transaction_state_unavailable")
    end
    identityPublished = true
    if not self:WriteGlobal(slotBase + 5, 0) then
        return failBeforePublish("transaction_state_unavailable")
    end
    if not self:ClearFreemodeTransactionOuterFields(slotBase) then
        return failBeforePublish("transaction_state_unavailable")
    end

    -- freemode.c copies itemData.f_1 to f_65.f_16. f_18 is cleared before
    -- func_2130 publishes the event; the basket item retains itemData.f_3.
    local descriptor = {
        {1, itemDataF2},
        {3, 78225582},
        {4, normalizeTransactionInt(Utils.Joaat("SERVICE_INVALID"), 0)},
        {6, category}, {7, service}, {8, 0}, {9, 0},
        {10, descriptorF10}, {11, 3}, {12, 0}, {13, 0},
        {15, itemHash}, {16, itemDataF1}, {17, 0}, {18, 0}
    }
    for _, field in ipairs(descriptor) do
        if not self:WriteGlobal(slotBase + field[1], field[2]) then
            return failBeforePublish("transaction_state_unavailable")
        end
    end
    local expectedDescriptor = {
        [0] = transactionId,
        [1] = itemDataF2,
        [2] = 1,
        [3] = 78225582,
        [4] = normalizeTransactionInt(Utils.Joaat("SERVICE_INVALID"), 0),
        [5] = 1,
        [6] = category,
        [7] = service,
        [8] = 0, [9] = 0, [10] = descriptorF10, [11] = 3,
        [12] = 0, [13] = 0, [14] = frameCount, [15] = itemHash,
        [16] = itemDataF1, [17] = 0, [18] = 0
    }
    if not self:WriteGlobal(4516963, 0) then
        return failBeforePublish("transaction_state_unavailable")
    end

    -- Validate the entire descriptor while f5 is still zero. Do not Yield:
    -- the process basket exists but has no f5 owner until the final write.
    local unpublishedReady = false
    for attempt = 1, 4 do
        local matches = true
        for offset = 0, 18 do
            local expected = offset == 5 and 0 or expectedDescriptor[offset]
            if self:ReadTransactionGlobal(slotBase + offset, {attempts = 1})
                ~= expected then
                matches = false
                break
            end
        end
        if matches then
            unpublishedReady = true
            break
        end
    end
    if not unpublishedReady then
        return failBeforePublish("transaction_state_unavailable")
    end
    if type(prePublishGuard) == "function" then
        local guardOk, allowed, guardReason = pcall(prePublishGuard)
        if not guardOk or allowed ~= true then
            return failBeforePublish(
                tostring(guardReason or "transaction_guard_failed")
            )
        end
    end

    -- f5 is the basket-ownership publication marker used by func_1745. It is
    -- the final descriptor write, matching func_2129's bParam6 branch. From
    -- this write through event sender invocation the path must not Yield.
    basketOwnerWriteAttempted = true
    if not self:WriteGlobal(slotBase + 5, 1) then
        local identity = self:ReadStableFreemodeTransactionIdentity(slotBase, 1)
        if identity and identity.transactionId == transactionId
            and identity.frameCount == frameCount and identity.state == 1
            and identity.ownsBasket == 1 then
            -- The binding reported failure after f5 became visible. Continue
            -- into the same full descriptor verification used below.
        end
        if identity and identity.transactionId == transactionId
            and identity.frameCount == frameCount and identity.state == 1
            and identity.ownsBasket == 0 then
            return failBeforePublish("transaction_state_unavailable")
        end
        if identity and identity.state == 0 then
            return failBeforePublish("transaction_state_unavailable")
        end
        if not identity or identity.transactionId ~= transactionId
            or identity.frameCount ~= frameCount or identity.state ~= 1
            or identity.ownsBasket ~= 1 then
            return false, frameCount, "transaction_state_uncertain", true, nil,
                makeStageTombstone(true, true)
        end
    end

    -- One no-Yield exact read is enough here: the same descriptor was already
    -- verified while unpublished. A mismatch after f5 may mean another
    -- freemode path observed it, so preserve an outcome-pending tombstone and
    -- never perform an unpublished rollback.
    for offset = 0, 18 do
        if self:ReadTransactionGlobal(slotBase + offset, {attempts = 1})
            ~= expectedDescriptor[offset] then
            return false, frameCount, "transaction_state_uncertain", true, nil,
                makeStageTombstone(true, true)
        end
    end
    return true, frameCount, nil, false, expectedDescriptor, nil
end

function SovereignBusinessInventory:FinalizeFreemodeBasketTransaction(
    slotBase, transactionId, stagedFrameCount, expectedDescriptor
)
    slotBase, transactionId, stagedFrameCount = tonumber(slotBase),
        tonumber(transactionId), tonumber(stagedFrameCount)
    if slotBase == nil or transactionId == nil or stagedFrameCount == nil
        or type(expectedDescriptor) ~= "table" then
        return false, stagedFrameCount, "transaction_state_unavailable", nil
    end
    slotBase, transactionId, stagedFrameCount = math.floor(slotBase),
        math.floor(transactionId), math.floor(stagedFrameCount)
    if not menu.nativeApis.MISC or type(menu.nativeApis.MISC.GET_FRAME_COUNT) ~= "function" then
        return false, stagedFrameCount, "transaction_state_unavailable", nil
    end
    local frameOk, finalizedFrameCount = pcall(menu.nativeApis.MISC.GET_FRAME_COUNT)
    finalizedFrameCount = frameOk
        and self:NormalizeSignedInt32(finalizedFrameCount) or nil
    if finalizedFrameCount == nil then
        return false, stagedFrameCount, "transaction_state_unavailable", nil
    end

    local createdAt = os.clock()
    local function makeFinalizeTombstone(observedIdentity)
        local observedFrameCount = type(observedIdentity) == "table"
            and tonumber(observedIdentity.frameCount) or nil
        local observedOwner = type(observedIdentity) == "table"
            and observedIdentity.transactionId == transactionId
            and observedFrameCount ~= nil
            and (observedFrameCount == stagedFrameCount
                or observedFrameCount == finalizedFrameCount)
            and observedIdentity.state == 1
            and observedIdentity.ownsBasket == 1
        local targetFrameCount = observedOwner
            and math.floor(observedFrameCount) or finalizedFrameCount
        return {
            base = slotBase,
            slotTombstone = true,
            localOnlyCleanup = true,
            outcomePending = false,
            basketEndPending = true,
            publicationUncertain = true,
            expectedTransactionId = transactionId,
            expectedFrameCount = targetFrameCount,
            targetTransactionId = transactionId,
            -- A finalizer tombstone may own only the exact frame that was
            -- read back as state=1/f5=1 immediately before returning. If no
            -- such identity was observed, keep the new frame as an
            -- unowned target and isolate it instead of ending a stale tuple.
            targetFrameCount = targetFrameCount,
            transactionWriteAttempted = false,
            frameWriteAttempted = observedOwner
                and targetFrameCount ~= stagedFrameCount or false,
            basketOwnerWriteAttempted = observedOwner == true,
            baselineTransactionId = transactionId,
            baselineFrameCount = stagedFrameCount,
            createdAt = createdAt,
            cleanupDeadline = createdAt + 45.0,
            tombstoneNotBefore = createdAt + 1.0,
            attempts = 6
        }
    end
    local function isPublishedIdentityCandidate(identity)
        return type(identity) == "table"
            and identity.transactionId == transactionId
            and (identity.frameCount == stagedFrameCount
                or identity.frameCount == finalizedFrameCount)
            and identity.state == 1 and identity.ownsBasket == 1
    end

    local before, beforeReason = self:ReadStableFreemodeTransactionIdentity(
        slotBase, 1
    )
    if not before or before.transactionId ~= transactionId
        or before.frameCount ~= stagedFrameCount or before.state ~= 1
        or before.ownsBasket ~= 1 then
        return false, stagedFrameCount,
            beforeReason or "transaction_state_uncertain",
            makeFinalizeTombstone(before)
    end

    -- Enhanced func_2191 finalizes the Stage descriptor only after every
    -- BASKET_ADD_ITEM succeeds, immediately before func_2130 emits it. Keep
    -- these writes and their complete readback in the same yield-free closure.
    local writesOk = true
    if not self:WriteGlobal(slotBase + 13, 1) then writesOk = false end
    if not self:WriteGlobal(slotBase + 12, 0) then writesOk = false end
    if not self:WriteGlobal(slotBase + 14, finalizedFrameCount) then
        writesOk = false
    end
    if not self:WriteGlobal(slotBase + 18, 0) then writesOk = false end

    local finalizedDescriptor = {}
    for offset = 0, 18 do finalizedDescriptor[offset] = expectedDescriptor[offset] end
    finalizedDescriptor[12] = 0
    finalizedDescriptor[13] = 1
    finalizedDescriptor[14] = finalizedFrameCount
    finalizedDescriptor[18] = 0
    local descriptorMatches = true
    for offset = 0, 18 do
        if self:ReadTransactionGlobal(slotBase + offset, {attempts = 1})
            ~= finalizedDescriptor[offset] then
            descriptorMatches = false
            break
        end
    end
    local after, afterReason = self:ReadStableFreemodeTransactionIdentity(
        slotBase, 1
    )
    if descriptorMatches and isPublishedIdentityCandidate(after)
        and after.frameCount == finalizedFrameCount then
        for offset = 0, 18 do
            expectedDescriptor[offset] = finalizedDescriptor[offset]
        end
        return true, finalizedFrameCount, nil, nil
    end
    return false,
        isPublishedIdentityCandidate(after) and after.frameCount or stagedFrameCount,
        (writesOk and afterReason) or "transaction_state_unavailable",
        makeFinalizeTombstone(after)
end

function SovereignBusinessInventory:DispatchFreemodeBasketTransaction(
    slot, slotBase, preDispatchGuard, expectedPlayerId,
    expectedTransactionId, expectedFrameCount, expectedDescriptor,
    onSenderInvoked
)
    local function readDescriptorSnapshot()
        local snapshot = {}
        for offset = 0, 18 do
            local value = self:ReadTransactionGlobal(
                slotBase + offset, {attempts = 1}
            )
            if type(value) ~= "number" then return nil end
            snapshot[offset] = math.floor(value)
        end
        return snapshot
    end
    local function descriptorMatches(snapshot)
        if type(snapshot) ~= "table" or type(expectedDescriptor) ~= "table" then
            return false
        end
        for offset = 0, 18 do
            if snapshot[offset] ~= expectedDescriptor[offset] then return false end
        end
        return true
    end
    local function guardCurrent()
        -- Publication and send run in one yield-free freemode closure. Use a
        -- single exact snapshot here; a retrying read could yield and let the
        -- native freemode path consume the published descriptor first.
        if not descriptorMatches(readDescriptorSnapshot()) then
            return false, "transaction_state_uncertain"
        end
        if type(preDispatchGuard) ~= "function" then return true, nil end
        local ok, allowed, reason = pcall(preDispatchGuard)
        if not ok or allowed ~= true then
            return false, tostring(reason or "transaction_guard_failed")
        end
        return true, nil
    end
    local playerId = expectedPlayerId
    if playerId == nil then playerId = self:GetLocalPlayerId() end
    playerId = tonumber(playerId)
    if playerId == nil then
        return false, false, "local_player_unavailable", false
    end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 or self:GetLocalPlayerId() ~= playerId then
        return false, false, "transaction_guard_failed", false
    end
    if type(expectedTransactionId) ~= "number"
        or type(expectedFrameCount) ~= "number"
        or type(expectedDescriptor) ~= "table" then
        return false, false, "transaction_state_unavailable", false
    end
    local descriptorSnapshot = readDescriptorSnapshot()
    if not descriptorMatches(descriptorSnapshot) then
        return false, false, "transaction_state_uncertain", false
    end
    local args = {-710178565, playerId, 0}
    for offset = 0, 18 do
        args[#args + 1] = descriptorSnapshot[offset]
    end
    for _ = 1, 13 do args[#args + 1] = 0 end
    args[#args + 1] = slot

    local bits = 1 << playerId
    local sent = false
    local ambiguous = false
    local senderInvoked = false
    local function markSenderInvoked()
        senderInvoked = true
        if type(onSenderInvoked) == "function" then pcall(onSenderInvoked) end
    end
    if GTA and type(GTA.TriggerScriptEvent) == "function" then
        local guardOk, guardReason = guardCurrent()
        if not guardOk then return false, false, guardReason, false end
        markSenderInvoked()
        local ok, result = pcall(GTA.TriggerScriptEvent, bits, args)
        if not ok then
            ambiguous = true
        elseif result == false then
            -- Cherax does not document false as proof that no packet was
            -- queued. Treat it as an unknown outcome and never send the same
            -- mission through the low-level fallback a second time.
            ambiguous = true
        else
            sent = true
        end
    end
    -- An exception from the first sender is ambiguous: the native may have
    -- queued the event before throwing. Do not invoke the fallback sender in
    -- that case, or one request could be emitted twice.
    if not sent and not ambiguous and menu.nativeApis.SCRIPT and type(menu.nativeApis.SCRIPT._SEND_TU_SCRIPT_EVENT_NEW) == "function" then
        local guardOk, guardReason = guardCurrent()
        if not guardOk then return false, false, guardReason, false end
        local allocationOk, eventData = pcall(Memory.Alloc, 36 * 8)
        if not allocationOk then
            return false, false, "allocation_failed", false
        end
        if eventData and eventData ~= 0 then
            local prepared = pcall(function()
                Memory.MemSet(eventData, 0, 36 * 8)
                for index, value in ipairs(args) do
                    Memory.WriteInt(eventData + ((index - 1) * 8), value)
                end
            end)
            if not prepared then
                pcall(Memory.Free, eventData)
                return false, false, "allocation_failed", false
            end
            -- Enhanced freemode func_2130 passes the event hash as the fifth
            -- argument. Lua tables are 1-based, so args[1] is offset zero.
            markSenderInvoked()
            local ok, sendResult = pcall(
                menu.nativeApis.SCRIPT._SEND_TU_SCRIPT_EVENT_NEW,
                1, eventData, 36, bits, args[1]
            )
            sent = ok and sendResult ~= false
            if not ok or sendResult == false then ambiguous = true end
            pcall(Memory.Free, eventData)
        else
            return false, false, "allocation_failed", false
        end
    end
    if sent and not self:WriteTransactionGlobalVerified(4516963, 1) then
        return false, true, "transaction_state_unavailable", true
    end
    local resultReason = nil
    if not sent then
        resultReason = ambiguous and "transaction_dispatch_uncertain" or "checkout_failed"
    end
    return sent, ambiguous, resultReason, senderInvoked
end

function SovereignBusinessInventory:SubmitContrabandDelta(
    itemHash, delta, secondaryHash, category, service, transactionOptions
