            base = transactionBase,
            slot = transactionSlot,
            transactionId = stagedTransactionId,
            frameCount = stagedFrameCount,
            attempts = tonumber(options.attempts) or 6,
            basketEndPending = options.basketEndPending == true,
            basketEndAttempted = options.basketEndAttempted == true
                or basketEndAttempted == true,
            outcomePending = options.outcomePending == true,
            serverAccepted = options.serverAccepted == true,
            serverRejected = options.serverRejected == true,
            onAcceptedBeforeCleanup = onAcceptedBeforeCleanup,
            acceptedReceipt = acceptedReceipt,
            localOnlyCleanup = options.localOnlyCleanup == true,
            passiveBasketCleanup = options.passiveBasketCleanup == true,
