                            -- func_2193 updates f1/f15/f16 for each item on the
                            -- existing slot. Keep the event descriptor on the
                            -- final product item before adding that item.
                            transactionPhase = "secondary_descriptor"
                            local descriptorUpdated =
                                self:WriteGlobal(transactionBase + 1,
                                    effectiveSecondaryItemDataF2)
                                and self:WriteGlobal(transactionBase + 15, secondaryHash)
                                and self:WriteGlobal(transactionBase + 16, 0)
                            if descriptorUpdated then
                                expectedDescriptor[1] = effectiveSecondaryItemDataF2
                                expectedDescriptor[15] = secondaryHash
                                expectedDescriptor[16] = 0
                                local identity =
                                    self:ReadStableFreemodeTransactionIdentity(
                                        transactionBase, 1
                                    )
                                descriptorUpdated = identity ~= nil
                                    and identity.transactionId == stagedTransactionId
                                    and identity.frameCount == stagedFrameCount
                                    and identity.state == 1
                                    and identity.ownsBasket == 1
                                    and self:ReadTransactionGlobal(
                                        transactionBase + 1, {attempts = 1}
                                    ) == expectedDescriptor[1]
                                    and self:ReadTransactionGlobal(
                                        transactionBase + 15, {attempts = 1}
                                    ) == expectedDescriptor[15]
                                    and self:ReadTransactionGlobal(
                                        transactionBase + 16, {attempts = 1}
                                    ) == expectedDescriptor[16]
                            end
                            if descriptorUpdated then
                                Memory.MemSet(itemData, 0, 32)
                                Memory.WriteInt(itemData, secondaryHash)
                                Memory.WriteInt(itemData + 8, 0)
                                Memory.WriteInt(itemData + 16,
                                    effectiveSecondaryItemDataF2)
                                Memory.WriteInt(itemData + 24,
                                    effectiveSecondaryItemDataF3)
                                transactionPhase = "secondary_add"
                                itemsAdded = menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_ADD_ITEM(
