    end
    if not executeOk then
        local cleanupOk, cleanupReason = true, nil
        if stagedSlotOwned and not transactionDispatchAttempted and basketCleanupOk then
            cleanupOk, cleanupReason = self:ClearOwnedFreemodeTransactionSlot(
                transactionBase, stagedTransactionId, stagedFrameCount
            )
        end
        safeFree(itemData)
        safeFree(transactionPtr)
        if transactionDispatchAttempted or transactionDispatchAmbiguous then
            logTransactionFailure("transaction_runtime_exception", true)
            return false, "transaction_runtime_exception", true,
                transactionStageRecovery or makeFreemodeCleanupContext({
                    basketEndPending = true,
                    outcomePending = true
                })
        end
        if not basketCleanupOk then
            if type(transactionStageRecovery) == "table" then
                transactionStageRecovery.basketEndPending = true
                return false, "transaction_cleanup_unconfirmed", true,
                    transactionStageRecovery
            end
            if stagedSlotOwned then
                return false, "transaction_cleanup_unconfirmed", true,
                    makeFreemodeCleanupContext({
                        basketEndPending = true,
                        localOnlyCleanup = true
                    })
            end
            return false, "transaction_cleanup_unconfirmed", true,
                makePassiveBasketCleanupContext()
        end
        if transactionStageAmbiguous then
            logTransactionFailure(
                transactionDispatchReason or "transaction_state_uncertain", false
            )
            if type(transactionStageRecovery) == "table" then
                transactionStageRecovery.basketEndPending = not basketCleanupOk
                return false, transactionDispatchReason
                    or "transaction_state_uncertain", true,
                    transactionStageRecovery
            end
            return false, transactionDispatchReason
                or "transaction_state_uncertain", false
        end
        if not cleanupOk then
            -- Losing ownership while unwinding is not a clean rejection. The
            -- event was never attempted, so retain the exact local owner and
            -- clear its unpublished state-1 descriptor asynchronously.
            logTransactionFailure(
                cleanupReason or "transaction_state_uncertain", true
            )
            return false, cleanupReason or "transaction_state_uncertain", true,
                makeFreemodeCleanupContext({localOnlyCleanup = true})
        end
        logTransactionFailure("freemode_unavailable", false)
        return false, "freemode_unavailable", false
    end
    safeFree(itemData)
    safeFree(transactionPtr)
    if not transactionDispatched then
        local cleanupOk, cleanupReason = true, nil
        if stagedSlotOwned and not transactionDispatchAmbiguous and basketCleanupOk then
            cleanupOk, cleanupReason = self:ClearOwnedFreemodeTransactionSlot(
                transactionBase, stagedTransactionId, stagedFrameCount
            )
        end
        if transactionDispatchAmbiguous then
            logTransactionFailure(
                transactionDispatchReason or "transaction_dispatch_uncertain", true
            )
            return false, transactionDispatchReason
                or "transaction_dispatch_uncertain", true,
                transactionStageRecovery or makeFreemodeCleanupContext({
                    basketEndPending = true,
                    outcomePending = true
                })
        end
        if not basketCleanupOk then
            if type(transactionStageRecovery) == "table" then
                transactionStageRecovery.basketEndPending = true
                return false, "transaction_cleanup_unconfirmed", true,
                    transactionStageRecovery
            end
            if stagedSlotOwned then
                return false, "transaction_cleanup_unconfirmed", true,
                    makeFreemodeCleanupContext({
                        basketEndPending = true,
                        localOnlyCleanup = true
                    })
            end
            return false, "transaction_cleanup_unconfirmed", true,
                makePassiveBasketCleanupContext()
        end
        if transactionStageAmbiguous then
            logTransactionFailure(
                transactionDispatchReason or "transaction_state_uncertain", false
            )
            if type(transactionStageRecovery) == "table" then
                transactionStageRecovery.basketEndPending = not basketCleanupOk
                return false, transactionDispatchReason
                    or "transaction_state_uncertain", true,
                    transactionStageRecovery
            end
            return false, transactionDispatchReason
                or "transaction_state_uncertain", false
        end
        if not cleanupOk then
            -- No event was emitted. Keep a temporary lock only until this
            -- exact tx/frame owner's unpublished descriptor is released.
            logTransactionFailure(
                cleanupReason or "transaction_state_uncertain", true
            )
            return false, cleanupReason or "transaction_state_uncertain", true,
                makeFreemodeCleanupContext({localOnlyCleanup = true})
        end
        logTransactionFailure(transactionDispatchReason or "checkout_failed", false)
        return false, transactionDispatchReason or "checkout_failed", false
    end

    transactionPhase = "settlement"
    local settleOk, accepted, reason, committed, cleanupContext = pcall(function()
        if useCheckout then
            local pending = true
            local checkoutStatusUncertain = false
            for _ = 1, 300 do
                Script.Yield(100)
                local inProgress = menu.nativeApis.NETSHOPPING.NET_GAMESERVER_TRANSACTION_IN_PROGRESS()
                if Natives and type(Natives.InvokeBool) == "function" and checkoutTransactionId then
                    local okPending, value = pcall(
                        Natives.InvokeBool, 0x4B64CD6D18474126, checkoutTransactionId
                    )
                    if okPending then
                        pending = value == true
                    else
                        -- An unreadable checkout receipt is not a completed
                        -- checkout. Keep polling and never promote it to success.
                        pending = true
                        checkoutStatusUncertain = true
                    end
                else
                    pending = inProgress
                end
                if not pending and not inProgress then break end
            end
            if pending or menu.nativeApis.NETSHOPPING.NET_GAMESERVER_TRANSACTION_IN_PROGRESS() then
                return false, checkoutStatusUncertain
                    and "transaction_state_unavailable" or "transaction_timeout", true
            end
            if not endActiveBasket(stagedOwnerGuard(2)) then
                return false, "transaction_state_unavailable", true
            end
            return true, nil, true
        end

        local transactionState = 1
        local stateReason = nil
        for _ = 1, 300 do
            Script.Yield(100)
            observeTransactionAlert("settlement_poll")
            local owned, ownerReason = self:IsFreemodeTransactionSlotOwner(
                transactionBase, stagedTransactionId, stagedFrameCount
            )
            if not owned then
                stateReason = ownerReason or "transaction_state_uncertain"
                break
            end
            local stateValue = self:ReadTransactionGlobal(transactionBase + 2, {
                attempts = 4,
                retryDelay = 25
            })
            if type(stateValue) ~= "number" then
                stateReason = "transaction_state_unavailable"
                break
            end
            transactionState = math.floor(stateValue)
            lastTransactionState = transactionState
            local stillOwned, changedReason = self:IsFreemodeTransactionSlotOwner(
                transactionBase, stagedTransactionId, stagedFrameCount
            )
            if not stillOwned then
                stateReason = changedReason or "transaction_state_uncertain"
                break
            end
            if transactionState ~= 1 then break end
        end
        if stateReason then
            return false, stateReason, true, makeFreemodeCleanupContext({
                basketEndPending = true,
                outcomePending = true
            })
        end
        if transactionState == 1 then
            -- Keep the live slot intact: clearing a still-pending response can
            -- destroy the only state freemode has to finish the transaction.
            return false, "transaction_timeout", true, makeFreemodeCleanupContext({
                basketEndPending = true,
                outcomePending = true
            })
        end
        if transactionState == 2 then
            if onAcceptedBeforeCleanup then
                local acceptedContext = makeFreemodeCleanupContext({
                    basketEndPending = true,
                    serverAccepted = true
                })
                local settled, cleanupReason =
                    self:EnsureFreemodeTransactionSettled(acceptedContext)
                if acceptedReceipt.callbackInvoked == true
                    and acceptedReceipt.callbackCompleted ~= true then
                    return false, acceptedReceipt.callbackReason
                        or "transaction_state_uncertain", true,
                        not settled and acceptedContext or nil
                end
                if not settled or acceptedReceipt.callbackCompleted ~= true then
                    return true, cleanupReason
                        or "transaction_cleanup_unconfirmed", true, acceptedContext
                end
                return true, nil, true
            end
            if not endActiveBasket(stagedOwnerGuard(2)) then
                -- State 2 is already the server acceptance receipt. A delayed
                -- BASKET_END cannot turn it into a rejection; defer both the
                -- basket end and slot clear under this exact tx/frame owner.
                return true, "transaction_cleanup_unconfirmed", true,
                    makeFreemodeCleanupContext({
                        basketEndPending = true,
                        outcomePending = false,
                        serverAccepted = true
                    })
            end
            local cleared, clearReason = self:ClearOwnedFreemodeTransactionSlot(
                transactionBase, stagedTransactionId, stagedFrameCount
            )
            if not cleared then
                -- State 2 is the server's accepted result. Failure to reclaim
                -- the local descriptor cannot turn that business result back
                -- into a rejection. Return an owner-bound cleanup context so
                -- callers can defer every local inventory write until the
                -- descriptor is either cleared or observed free.
                Logger:Warn("SovereignInventory", "accepted transaction slot cleanup: "
                    .. tostring(clearReason or "transaction_state_uncertain"))
                return true, clearReason or "transaction_cleanup_unconfirmed", true,
                    makeFreemodeCleanupContext({
                        attempts = 3,
                        basketEndPending = false,
                        outcomePending = false,
                        serverAccepted = true
                    })
            end
            return true, nil, true
        end
        if transactionState == 3 then
            if not endActiveBasket(stagedOwnerGuard(3)) then
                return false, "transaction_cleanup_unconfirmed", true,
                    makeFreemodeCleanupContext({
                        basketEndPending = true,
                        outcomePending = false,
                        serverRejected = true
                    })
            end
            local cleared, clearReason = self:ClearOwnedFreemodeTransactionSlot(
                transactionBase, stagedTransactionId, stagedFrameCount
            )
            if not cleared then
                return false, clearReason or "transaction_cleanup_unconfirmed", true,
                    makeFreemodeCleanupContext({
                        attempts = 3,
                        basketEndPending = false,
                        outcomePending = false,
                        serverRejected = true
                    })
            end
            return false, "transaction_rejected", false
        end
        -- State zero can mean another freemode path already consumed/cleared
        -- the slot. It is not proof that the emitted request was rejected.
        return false, "transaction_state_uncertain", true,
            makeFreemodeCleanupContext({
                basketEndPending = true,
                outcomePending = true
            })
    end)
    if not settleOk then
        logTransactionFailure("transaction_runtime_exception", true)
        return false, "transaction_runtime_exception", true,
            makeFreemodeCleanupContext({
                basketEndPending = true,
                outcomePending = true
            })
    end
    if transactionAlertSeen ~= nil then
        Logger:Warn("SovereignInventory", string.format(
            "transaction alert observed name=%s phase=%s",
            tostring(transactionAlertSeen), tostring(transactionAlertSeenPhase)
        ))
        logTransactionFailure("transaction_alert_blocked", transactionDispatched == true)
        return false, "transaction_alert_blocked",
            transactionDispatched == true or committed == true, cleanupContext
    end
    if not accepted then logTransactionFailure(reason, committed) end
    return accepted, reason, committed, cleanupContext
end

function SovereignBusinessInventory:ApplyRefillRequest(request)
    local requestKey = self:GetRefillRequestKey(request)
    local function ensurePendingIdentity()
        local pending = requestKey and self.pendingRefillTransactions[requestKey] or nil
        if type(pending) ~= "table" then return false end
        local identityOk, identityReason = self:IsPendingRefillIdentityCurrent(pending)
        if not identityOk then
            self:QuarantinePendingRefill(
                requestKey, pending, identityReason or "refill_identity_changed"
            )
            return false
        end
        local cleanupOk = self:EnsurePendingRefillTransactionCleanup(pending)
        if not cleanupOk then return false end
        return true
    end
    local function makeRefillDispatchGuard(expectedIdentity, expectedStock)
        expectedStock = type(expectedStock) == "table" and expectedStock or nil
        return function()
            local currentIdentity, identityReason = self:CaptureRefillIdentity(request)
            if not currentIdentity then return false, identityReason end
            if not self:AreRefillIdentitiesEqual(currentIdentity, expectedIdentity) then
                return false, "refill_identity_changed"
            end
            if expectedStock then
                local statIndex = tonumber(expectedStock.statIndex)
                local runtimeGlobal = tonumber(expectedStock.runtimeGlobal)
                local capacity = tonumber(expectedStock.capacity)
                if statIndex == nil or runtimeGlobal == nil or capacity == nil then
                    return false, "stock_state_unavailable"
                end
                local values = self:ReadIndices(
                    {math.floor(statIndex)}, expectedIdentity.characterSlot
                )
                local persistent = self:NormalizeStockValue(
                    values and values[math.floor(statIndex)], math.floor(capacity)
                )
                local live = self:NormalizeStockValue(
                    self:ReadGlobal(math.floor(runtimeGlobal)), math.floor(capacity)
                )
                if persistent == nil or live == nil then
                    return false, "stock_state_unavailable"
                end
                if persistent ~= expectedStock.persistent
                    or live ~= expectedStock.live then
                    return false, "stock_state_sync_pending"
                end
                if type(expectedStock.hangarSlots) == "table"
                    and not self:VerifyHangarPacking(
                        persistent, expectedStock.hangarSlots,
                        expectedIdentity.characterSlot
                    ) then
                    return false, "hangar_packing_inconsistent"
                end
            end
            return true, nil
        end
    end
    local saleKey = self:GetSaleKeyForRefill(request)
    if saleKey and self.saleQuarantine and self.saleQuarantine[saleKey] then
        return false, "sale_manual_review_locked"
    end
    if requestKey and self.refillRejectedKeys
        and self.refillRejectedKeys[requestKey] then
        return false, "refill_rejected_locked"
    end
    if requestKey and self.refillQuarantine
        and self.refillQuarantine[requestKey] then
        return false, "refill_quarantine_locked"
    end
    if request and request.kind == "warehouse" then
        if self.warehouseRefillRejected then return false, "warehouse_refill_locked" end
        local pendingOk = self:ReconcilePendingRefill(request)
        if not pendingOk then return false, "refill_pending_verification" end
        local catalogOk, catalogReason = self:ValidateWarehouseCatalog()
        if not catalogOk then return false, catalogReason end
        local definition = self.warehouseDefinitions[tonumber(request.index) or 0]
        if not definition then return false, "invalid_request" end
        local accessOk, accessReason = self:CheckWarehouseAccess(tonumber(request.index))
        if not accessOk then return false, accessReason end
        local operationIdentity, operationIdentityReason = self:CaptureRefillIdentity(request)
        if not operationIdentity then return false, operationIdentityReason end
        local function operationIdentityCurrent()
            local currentIdentity = self:CaptureRefillIdentity(request)
            return currentIdentity ~= nil and self:AreRefillIdentitiesEqual(
                currentIdentity, operationIdentity
            )
        end
        local characterSlot = operationIdentity.characterSlot
        local playerId = operationIdentity.playerId
        local capacity = self:GetWarehouseCapacity(definition, playerId)
        if capacity <= 0 then return false, "warehouse_not_owned" end
        local runtimeGlobal = self:GetWarehouseRuntimeProductGlobal(
            definition.index, playerId
        )
        if not runtimeGlobal then return false, "runtime_global_unavailable" end

        -- A checkout is irreversible on the server. Wait for the persistent
        -- stat and freemode cache to converge over several samples; a single
        -- stale cache read must not be treated as a permanent mismatch.
        local stableState, stableReason = self:ReadStableWarehouseState(
            definition, characterSlot, playerId, runtimeGlobal, capacity,
            operationIdentityCurrent
        )
        if not stableState then return false, stableReason end
        local current = stableState.live
        local persistentCurrent = stableState.persistent
        local liveCurrent = stableState.live
        local initialPersistent, initialLive = persistentCurrent, liveCurrent
        local target = math.max(current, math.min(capacity, math.floor(tonumber(request.target) or current)))
        local cargoSelection = math.max(1, math.min(
            #self.warehouseCargoTypes + 1,
            math.floor(tonumber(request.cargoType) or tonumber(self.selectedWarehouseCargo) or 1)
        ))
        local repairExisting = true

        local hasStatSetter = (Stats and type(Stats.SetInt) == "function")
            or (menu.nativeApis.STATS and type(menu.nativeApis.STATS.STAT_SET_INT) == "function")
        if not ScriptGlobal or type(ScriptGlobal.SetInt) ~= "function"
            or not hasStatSetter
            or not menu.nativeApis.STATS or type(menu.nativeApis.STATS.STAT_SAVE) ~= "function"
            or type(menu.nativeApis.STATS.STAT_SET_MASKED_INT) ~= "function"
            or type(menu.nativeApis.STATS.STAT_GET_MASKED_INT) ~= "function"
            or self:GetStatHashByIndex(definition.productIndex, characterSlot) == 0
            or not self:ProbeWarehousePacking(
                definition, target, characterSlot, playerId
            ) then
            return false, "warehouse_write_unavailable"
        end
        if not self:VerifyWarehousePackingRange(
            definition, current, characterSlot, playerId
        ) then
            local repaired, repairReason = self:SetWarehouseStock(
                tonumber(request.index), current, current, cargoSelection, true,
                nil, operationIdentity
            )
            if not repaired or not self:VerifyWarehousePackingRange(
                definition, current, characterSlot, playerId
            ) then
                return false, repairReason or "packing_range_readback_failed"
            end
        end
        if current < target then
            local registeredCodes, registryReason = self:GetWarehouseRegisteredSpecialCodes(
                definition, target, characterSlot, playerId
            )
            if not registeredCodes then return false, registryReason end
            local itemHash = self:GetNamedStatHash(definition.productStat)
            if itemHash == 0 then return false, "catalog_hash_unavailable" end
            -- freemode's func_21249/func_21215 path submits only 1..3 boxes
            -- per checkout. Larger deltas are accepted by the client basket
            -- but are discarded before the warehouse state is committed.
            while current < target do
                if not operationIdentityCurrent() then
                    return false, "refill_identity_changed"
                end
                local batchAccess, batchAccessReason = self:CheckWarehouseAccess(
                    tonumber(request.index)
                )
                if not batchAccess then return false, batchAccessReason end
                local batchState, batchReason = self:ReadStableWarehouseState(
                    definition, characterSlot, playerId, runtimeGlobal, capacity,
                    operationIdentityCurrent, current
                )
                if not batchState then return false, batchReason end
                local batchPersistent, batchLive = batchState.persistent, batchState.live
                local packingReady, packingReason = self:WaitForWarehousePacking(
                    definition, current, characterSlot, playerId,
                    operationIdentityCurrent
                )
                if not packingReady then return false, packingReason end
                local delta = math.min(3, target - current)
                local expected = math.min(target, current + delta)
                local packingPlan, packingPlanReason = self:BuildWarehousePackingPlan(
                    definition, current, expected, cargoSelection, repairExisting,
                    characterSlot, playerId
                )
                if not packingPlan then return false, packingPlanReason end
                local batchIdentity = operationIdentity
                local identityDispatchGuard = makeRefillDispatchGuard(batchIdentity)
                local function readWarehouseBatchTuple()
                    local values = self:ReadIndices(
                        {definition.productIndex}, characterSlot
                    )
                    local persistent = values and values[definition.productIndex] or nil
                    local live = self:ReadGlobal(runtimeGlobal)
                    return self:NormalizeStockValue(persistent, capacity),
                        self:NormalizeStockValue(live, capacity)
                end
                local function warehouseBatchDispatchGuard()
                    local identityOk, identityReason = identityDispatchGuard()
                    if not identityOk then return false, identityReason end
                    local guardPersistent, guardLive = readWarehouseBatchTuple()
                    if guardPersistent == nil or guardLive == nil then
                        return false, "warehouse_state_unavailable"
                    end
                    if guardPersistent ~= batchPersistent or guardLive ~= batchLive then
                        return false, "stock_state_sync_pending"
                    end
                    return true, nil
                end
                local ok, reason, dispatched, cleanupContext = self:SubmitContrabandDelta(
                    itemHash,
                    delta,
                    nil,
                    Utils.Joaat("CATEGORY_CONTRABAND_QNTY"),
                    -886368739,
                    {
                        -- func_21216 submits {statHash, 0, HEAD, BERD};
                        -- quantity remains BASKET_ADD_ITEM's second argument.
                        checkout = false,
                        debugLabel = "warehouse:" .. tostring(request.index),
                        itemDataF1 = 0,
                        itemDataF2 = 0,
                        itemDataF3 = 1,
                        preDispatchGuard = warehouseBatchDispatchGuard
                    }
                )
                if not ok then
                    if dispatched then
                        self:MarkPendingRefill(
                            request, definition.productIndex, capacity, expected,
                            batchPersistent, batchLive, runtimeGlobal, false,
                            nil, batchIdentity, cleanupContext
                        )
                        local key = self:GetRefillRequestKey(request)
                        if self.pendingRefillTransactions[key] then
                            self.pendingRefillTransactions[key].reason = reason
                        end
                        return false, "refill_pending_verification"
                    end
                    if reason == "transaction_rejected" then
                        self.warehouseRefillRejected = true
                        self.refillRejectedKeys[requestKey] = true
                    end
                    return false, reason
                end

                if not self:MarkPendingRefill(
                    request, definition.productIndex, capacity, expected,
                    batchPersistent, batchLive, runtimeGlobal, true,
                    nil, batchIdentity, cleanupContext
                ) then
                    return false, "refill_pending_verification"
                end
                if not ensurePendingIdentity() then
                    return false, "refill_pending_verification"
                end
                local boundaryPersistent, boundaryLive = readWarehouseBatchTuple()
                local boundaryReadable = boundaryPersistent ~= nil and boundaryLive ~= nil
                local boundaryExpected = boundaryReadable
                    and (boundaryPersistent == batchPersistent
                        or boundaryPersistent == expected)
                    and (boundaryLive == batchLive or boundaryLive == expected)
                if not boundaryExpected then
                    local key = self:GetRefillRequestKey(request)
                    if self.pendingRefillTransactions[key] then
                        self.pendingRefillTransactions[key].reason = boundaryReadable
                            and "warehouse_state_changed" or "warehouse_state_unavailable"
                    end
                    Logger:Warn("SovereignInventory", string.format(
                        "%s accepted batch write boundary rejected baseline=%d/%d expected=%d actual=%s/%s",
                        tostring(definition.name), batchPersistent, batchLive, expected,
                        tostring(boundaryPersistent), tostring(boundaryLive)
                    ))
                    return false, "refill_pending_verification"
                end
                local stockOk, stockReason = self:SetWarehouseStock(
                    tonumber(request.index), expected, current, cargoSelection,
                    repairExisting, false, batchIdentity
                )
                if not stockOk then
                    local key = self:GetRefillRequestKey(request)
                    if self.pendingRefillTransactions[key] then
                        self.pendingRefillTransactions[key].reason = stockReason or "stat_commit_failed"
                    end
                    return false, "refill_pending_verification"
                end
                repairExisting = false

                local committed = false
                local persistent, live, readbackReason
                local stablePersistent, stableLive = nil, nil
                local stableReadbackCount = 0
                local abnormalPersistent, abnormalLive = nil, nil
                local abnormalCount = 0
                local abnormalReason = nil
                local lastReadbackPersistent, lastReadbackLive = nil, nil
                for attempt = 1, 30 do
                    if not ensurePendingIdentity() then
                        return false, "refill_pending_verification"
                    end
                    -- Read the raw indexed stat here. ReadWarehousePersistentProduct
                    -- intentionally clamps for UI display, which would hide a bad
                    -- negative value during the irreversible transaction path.
                    local values = self:ReadIndices(
                        {definition.productIndex}, characterSlot
                    )
                    persistent = values and values[definition.productIndex] or nil
                    live = self:ReadGlobal(runtimeGlobal)
                    if type(persistent) == "number" and type(live) == "number" then
                        local persistentOk, normalizedPersistent = pcall(math.floor, persistent)
                        local liveOk, normalizedLive = pcall(math.floor, live)
                        if persistentOk and liveOk then
                            persistent = normalizedPersistent
                            live = normalizedLive
                            lastReadbackPersistent, lastReadbackLive = persistent, live
                            if persistent == expected and live == expected then
                                -- A transient outlier is cleared as soon as
                                -- both stores converge on the requested value.
                                abnormalPersistent, abnormalLive = nil, nil
                                abnormalCount, abnormalReason = 0, nil
                                if stablePersistent == persistent and stableLive == live then
                                    stableReadbackCount = stableReadbackCount + 1
                                else
                                    stablePersistent, stableLive = persistent, live
                                    stableReadbackCount = 1
                                end
                                if stableReadbackCount >= 2 then
                                    current = expected
                                    committed = true
                                    break
                                end
                                readbackReason = "readback_sync_pending"
                            else
                                stablePersistent, stableLive, stableReadbackCount = nil, nil, 0
                                local outOfRange = persistent < 0 or persistent > capacity
                                    or live < 0 or live > capacity
                                local aboveExpected = persistent > expected or live > expected
                                local candidateReason
                                if outOfRange or aboveExpected then
                                    -- Do not quarantine on one stale/stat-cache
                                    -- sample. A repeated high/out-of-range tuple
                                    -- is treated as an external write and remains
                                    -- pending, so it can never be overwritten.
                                    candidateReason = "warehouse_state_inconsistent"
                                elseif persistent == live then
                                    candidateReason = "readback_sync_pending"
                                else
                                    candidateReason = "warehouse_state_sync_pending"
                                end
                                if outOfRange or aboveExpected then
                                    if abnormalPersistent == persistent
                                        and abnormalLive == live then
                                        abnormalCount = abnormalCount + 1
                                    else
                                        abnormalPersistent, abnormalLive = persistent, live
                                        abnormalCount = 1
                                    end
                                    abnormalReason = candidateReason
                                    if abnormalCount >= 2 then
                                        readbackReason = candidateReason
                                        pcall(function()
                                            Logger:Warn("SovereignInventory", string.format(
                                                "%s warehouse readback phase=warehouse_readback expected=%d persistent=%d live=%d consecutive=%d reason=%s",
                                                tostring(request.name or definition.name), expected,
                                                persistent, live, abnormalCount, candidateReason
                                            ))
                                        end)
                                        break
                                    end
                                else
                                    abnormalPersistent, abnormalLive = nil, nil
                                    abnormalCount, abnormalReason = 0, nil
                                end
                                readbackReason = candidateReason
                            end
                        else
                            persistent, live = nil, nil
                            stablePersistent, stableLive, stableReadbackCount = nil, nil, 0
                            abnormalPersistent, abnormalLive = nil, nil
                            abnormalCount, abnormalReason = 0, nil
                            readbackReason = "warehouse_state_unavailable"
                        end
                    else
                        stablePersistent, stableLive, stableReadbackCount = nil, nil, 0
                        abnormalPersistent, abnormalLive = nil, nil
                        abnormalCount, abnormalReason = 0, nil
                        readbackReason = "warehouse_state_unavailable"
                    end
                    if attempt < 30 and Script and type(Script.Yield) == "function" then
                        pcall(Script.Yield, 100)
                    end
                end
                if not committed then
                    local key = self:GetRefillRequestKey(request)
                    if self.pendingRefillTransactions[key] then
                        self.pendingRefillTransactions[key].reason = readbackReason
                            or abnormalReason or "warehouse_state_sync_pending"
                    end
                    pcall(function()
                        Logger:Warn("SovereignInventory", string.format(
                            "%s warehouse readback phase=warehouse_readback expected=%d persistent=%s live=%s reason=%s consecutive=%d",
                            tostring(request.name or definition.name), expected,
                            tostring(lastReadbackPersistent), tostring(lastReadbackLive),
                            tostring(readbackReason or abnormalReason or "warehouse_state_sync_pending"),
                            abnormalCount
                        ))
                    end)
                    return false, "refill_pending_verification"
                end
                self.pendingRefillTransactions[self:GetRefillRequestKey(request)] = nil
                persistentCurrent, liveCurrent = current, current
            end
        else
            local stockOk, stockReason = self:SetWarehouseStock(
                tonumber(request.index), target, current, cargoSelection, true,
                nil, operationIdentity
            )
            if not stockOk then return false, stockReason or "stat_commit_failed" end
        end
        if current < target then
            Logger:Warn("SovereignInventory", string.format(
                "%s transaction readback mismatch target=%d actual=%d",
                tostring(request.name or definition.name), target, current
            ))
            return false, "readback_mismatch"
        end
        if not self:VerifyWarehousePackingRange(
            definition, target, characterSlot, playerId
        ) then
            local repaired = self:SetWarehouseStock(
                tonumber(request.index), target, target, cargoSelection, true,
                nil, operationIdentity
            )
            if not repaired or not self:VerifyWarehousePackingRange(
                definition, target, characterSlot, playerId
            ) then
                return false, "packing_range_readback_failed"
            end
        end
        local selectedCargo = cargoSelection <= 1 and "Mixed regular cargo"
            or self.warehouseCargoTypes[cargoSelection - 1].name
        Logger:Info("SovereignInventory", string.format(
            "%s warehouseType=%d stock=%d/%d cargo=%s packing=verified",
            tostring(definition.name), self:ReadWarehouseType(definition, playerId), target, capacity,
            tostring(selectedCargo)
        ))
        self.lastRefillEvidence = {
            kind = request.kind,
            index = request.index,
            beforePersistent = initialPersistent,
            beforeLive = initialLive,
            afterPersistent = target,
            afterLive = target,
            packingConfirmed = true,
            transactionAccepted = initialPersistent < target,
            historicalServerOwnershipConfirmed = initialPersistent < target,
            noChange = initialPersistent == target,
            at = os.clock()
        }
        return true, initialPersistent < target
            and "transaction_accepted" or "already_at_target"
    end
    local accessOk, accessReason = self:CheckRefillAccess(request)
    if not accessOk then return false, accessReason end
    local statIndex = self:GetRefillStatIndex(request.kind, request.index)
    local itemHash, secondaryHash = self:GetRefillTransactionHash(request.kind, request.index)
    if not statIndex or not itemHash then return false, "invalid_request" end
    local operationIdentity, operationIdentityReason = self:CaptureRefillIdentity(request)
    if not operationIdentity then return false, operationIdentityReason end
    local function operationIdentityCurrent()
        local currentIdentity = self:CaptureRefillIdentity(request)
        return currentIdentity ~= nil and self:AreRefillIdentitiesEqual(
            currentIdentity, operationIdentity
        )
    end
    local characterSlot = operationIdentity.characterSlot
    local playerId = operationIdentity.playerId
    local capacity = self:GetRefillCapacity(request, playerId)
    if type(capacity) ~= "number" or capacity <= 0 then
        return false, "stock_capacity_invalid"
    end
    capacity = math.floor(capacity)

    local factoryEntry = self.data and self.data.factories
        and self.data.factories[math.floor(tonumber(request.index) or 0)]
    if (request.kind == "factory" or request.kind == "factory_product")
        and (not factoryEntry or factoryEntry.owned ~= true) then
        return false, "business_not_owned"
    end
    if request.kind == "hangar"
        and (type(self.data.hangarOwned) ~= "number" or self.data.hangarOwned == 0) then
        return false, "business_not_owned"
    end

    if not operationIdentityCurrent() then return false, "refill_identity_changed" end
    local before, stateReason = self:ReadRefillState(
        request, statIndex, capacity, operationIdentity
    )
    if not before then return false, stateReason end
    local current = before.persistent
    local requestedTarget = tonumber(request.target)
    if type(requestedTarget) ~= "number" then return false, "invalid_request" end
    local target = math.max(current, math.min(capacity, math.floor(requestedTarget)))
    if target == current then
        if not operationIdentityCurrent() then
            return false, "refill_identity_changed"
        end
        self.lastRefillEvidence = {
            kind = request.kind,
            index = request.index,
            beforePersistent = before.persistent,
            beforeLive = before.live,
            afterPersistent = before.persistent,
            afterLive = before.live,
            packingConfirmed = request.kind ~= "hangar"
                or before.packingConfirmed == true,
            transactionAccepted = false,
            historicalServerOwnershipConfirmed = false,
            noChange = true,
            at = os.clock()
        }
        return true, "already_at_target"
    end

    local function postCommitFailure(reason)
        local key = self:GetRefillRequestKey(request)
        local pending = key and self.pendingRefillTransactions[key] or nil
        if pending then pending.reason = reason end
        Logger:Error("SovereignInventory", string.format(
            "%s refill accepted but readback unconfirmed reason=%s; duplicate submission locked",
            tostring(request.name or request.kind), tostring(reason)
        ))
        return false, "refill_pending_verification"
    end

    if request.kind == "hangar" then
        local initialPersistent, initialLive = before.persistent, before.live
        local currentState = before
        while current < target do
            if not operationIdentityCurrent() then
                return false, "refill_identity_changed"
            end
            local batchAccess, batchAccessReason = self:CheckRefillAccess(request)
            if not batchAccess then return false, batchAccessReason end
            local latestState, latestReason = self:ReadRefillState(
                request, statIndex, capacity, operationIdentity
            )
            if not latestState then return false, latestReason end
            if latestState.persistent ~= current or latestState.live ~= current
                or latestState.packingConfirmed ~= true then
                return false, "stock_state_inconsistent"
            end
            currentState = latestState
            -- freemode's hangar source path commits one or two boxes per
            -- accepted transaction. Keep the same batch bound.
            local expected = math.min(target, current + 2)
            local expectedSlots, planReason = self:BuildHangarPackingPlan(
                currentState.packing, expected
            )
            if not expectedSlots then return false, planReason end
            local batchIdentity, identityReason = self:CaptureRefillIdentity(request)
            if not batchIdentity then return false, identityReason end
            if not self:AreRefillIdentitiesEqual(batchIdentity, operationIdentity) then
                return false, "refill_identity_changed"
            end
            batchIdentity = operationIdentity
            local hangarDispatchGuard = makeRefillDispatchGuard(batchIdentity, {
                statIndex = statIndex,
                runtimeGlobal = currentState.runtimeGlobal,
                capacity = capacity,
                persistent = currentState.persistent,
                live = currentState.live,
                hangarSlots = currentState.packing and currentState.packing.slots
            })
            local submitted, submitReason, dispatched, cleanupContext = self:SubmitContrabandDelta(
                itemHash, expected - current, secondaryHash,
                nil, nil,
                {
                    debugLabel = "hangar:" .. tostring(request.index),
                    preDispatchGuard = hangarDispatchGuard
                }
            )
            if not submitted then
                if dispatched then
                    self:MarkPendingRefill(
                        request, statIndex, capacity, expected,
                        currentState.persistent, currentState.live,
                        currentState.runtimeGlobal, false, expectedSlots,
                        batchIdentity, cleanupContext
                    )
                    local pending = self.pendingRefillTransactions[requestKey]
                    if pending then pending.reason = submitReason end
                    return false, "refill_pending_verification"
                end
                if submitReason == "transaction_rejected" then
                    self.refillRejectedKeys[requestKey] = true
                end
                return false, submitReason
            end

            if not self:MarkPendingRefill(
                request, statIndex, capacity, expected,
                currentState.persistent, currentState.live,
                currentState.runtimeGlobal, true, expectedSlots,
                batchIdentity, cleanupContext
            ) then
                return false, "refill_pending_verification"
            end
            if not ensurePendingIdentity() then
                return false, "refill_pending_verification"
            end
            local hangarOk, hangarReason = self:SetHangarStock(
                expected, current, false, expectedSlots, operationIdentity
            )
            if not hangarOk then
                return postCommitFailure(hangarReason or "hangar_commit_readback_failed")
            end

            local committed = nil
            for attempt = 1, 50 do
                if not ensurePendingIdentity() then
                    return false, "refill_pending_verification"
                end
                local state = self:ReadRefillState(
                    request, statIndex, capacity, operationIdentity
                )
                if state and state.persistent == expected and state.live == expected
                    and self:VerifyHangarPacking(
                        expected, expectedSlots, characterSlot
                    ) then
                    committed = state
                    break
                end
                if attempt < 50 then Script.Yield(200) end
            end
            if not committed then
                return postCommitFailure("hangar_commit_readback_failed")
            end
            self.pendingRefillTransactions[requestKey] = nil
            current, currentState = expected, committed
        end

        self.lastRefillEvidence = {
            kind = request.kind,
            index = request.index,
            beforePersistent = initialPersistent,
            beforeLive = initialLive,
            afterPersistent = currentState.persistent,
            afterLive = currentState.live,
            packingConfirmed = currentState.packingConfirmed == true,
            transactionAccepted = true,
            historicalServerOwnershipConfirmed = true,
            at = os.clock()
        }
        Logger:Info("SovereignInventory", string.format(
            "%s refill verified persistent=%d->%d live=%d->%d packing=verified transaction=accepted",
            tostring(request.name or request.kind), initialPersistent,
            currentState.persistent, initialLive, currentState.live
        ))
        return true, "transaction_accepted"
    end

    local finalAccess, finalAccessReason = self:CheckRefillAccess(request)
    if not finalAccess then return false, finalAccessReason end
    if not operationIdentityCurrent() then return false, "refill_identity_changed" end
    local latestBefore, latestBeforeReason = self:ReadRefillState(
        request, statIndex, capacity, operationIdentity
    )
    if not latestBefore then return false, latestBeforeReason end
    if latestBefore.persistent ~= before.persistent or latestBefore.live ~= before.live then
        -- Factory production and nightclub technicians can legitimately move
        -- stock while the bounded preflight sampler is running. Both sources
        -- agree and the business identity is pinned, so use the latest stable
        -- tuple as the transaction baseline instead of failing a valid refill.
        Logger:Info("SovereignInventory", string.format(
            "%s refill baseline rebased persistent=%d->%d live=%d->%d",
            tostring(request.name or request.kind), before.persistent,
            latestBefore.persistent, before.live, latestBefore.live
        ))
        before = latestBefore
        current = latestBefore.persistent
        target = math.max(current, math.min(capacity, math.floor(requestedTarget)))
        if target == current then
            if not operationIdentityCurrent() then
                return false, "refill_identity_changed"
            end
            self.lastRefillEvidence = {
                kind = request.kind,
                index = request.index,
                beforePersistent = before.persistent,
                beforeLive = before.live,
                afterPersistent = before.persistent,
                afterLive = before.live,
                packingConfirmed = true,
                transactionAccepted = false,
                historicalServerOwnershipConfirmed = false,
                noChange = true,
                at = os.clock()
            }
            return true, "already_at_target"
        end
    end
    local transactionIdentity, identityReason = self:CaptureRefillIdentity(request)
    if not transactionIdentity then return false, identityReason end
    if not self:AreRefillIdentitiesEqual(transactionIdentity, operationIdentity) then
        return false, "refill_identity_changed"
    end
    transactionIdentity = operationIdentity

    -- The stable preflight can be followed by a production tick before the
    -- basket is staged. Recheck the exact stock tuple at the final boundary;
    -- if it moved again, fail without sending a delta calculated from stale
    -- inventory. A later request can safely rebase on the new stable value.
    local submitBefore, submitBeforeReason = self:ReadRefillState(
        request, statIndex, capacity, operationIdentity
    )
    if not submitBefore then return false, submitBeforeReason end
    if submitBefore.persistent ~= before.persistent
        or submitBefore.live ~= before.live then
        Logger:Info("SovereignInventory", string.format(
            "%s refill submit boundary moved persistent=%d->%d live=%d->%d",
            tostring(request.name or request.kind), before.persistent,
            submitBefore.persistent, before.live, submitBefore.live
        ))
        return false, "stock_state_sync_pending"
    end

    local serverDelta = target - current
    if request.kind == "factory" then
        -- freemode func_21954/func_21955 restocks materials with
        -- (100 - current) * -1 and stages a zero product delta beside it.
        serverDelta = -serverDelta
    end
    local stockDispatchGuard = makeRefillDispatchGuard(transactionIdentity, {
        statIndex = statIndex,
        runtimeGlobal = submitBefore.runtimeGlobal,
        capacity = capacity,
        persistent = submitBefore.persistent,
        live = submitBefore.live
    })
    local submitted, submitReason, dispatched, cleanupContext = self:SubmitContrabandDelta(
        itemHash, serverDelta, secondaryHash,
        nil, nil,
        {
            debugLabel = tostring(request.kind) .. ":" .. tostring(request.index),
            secondaryDelta = request.kind == "factory" and 0 or nil,
            preDispatchGuard = stockDispatchGuard
        }
    )
    if not submitted then
        if dispatched then
            self:MarkPendingRefill(
                request, statIndex, capacity, target,
                before.persistent, before.live, before.runtimeGlobal, false,
                nil, transactionIdentity, cleanupContext
            )
            local key = self:GetRefillRequestKey(request)
            if self.pendingRefillTransactions[key] then
                self.pendingRefillTransactions[key].reason = submitReason
            end
            return false, "refill_pending_verification"
        end
        if submitReason == "transaction_rejected" and requestKey then
            self.refillRejectedKeys[requestKey] = true
        end
        return false, submitReason
    end
    if not self:MarkPendingRefill(
        request, statIndex, capacity, target,
        before.persistent, before.live, before.runtimeGlobal, true,
        nil, transactionIdentity, cleanupContext
    ) then
        return false, "refill_pending_verification"
    end
    if not ensurePendingIdentity() then
        return false, "refill_pending_verification"
    end

    -- Match freemode's accepted-result order: update the live business cache
    -- first, then persist the corresponding character stat.
    if not self:WriteRefillLiveValue(
        request, target, before.persistent, operationIdentity
    ) then
        return postCommitFailure("live_commit_failed")
    end
    if not ensurePendingIdentity() then
        return false, "refill_pending_verification"
    end
    if not self:WriteStatByIndex(statIndex, target, characterSlot) then
        return postCommitFailure("stat_commit_failed")
    end
    if not ensurePendingIdentity() then
        return false, "refill_pending_verification"
    end
    if not self:SaveStats() then
        return postCommitFailure("stat_save_failed")
    end

    local committed
    for attempt = 1, 50 do
        if not ensurePendingIdentity() then
            return false, "refill_pending_verification"
        end
        local state = self:ReadRefillState(
            request, statIndex, capacity, operationIdentity
        )
        if state and state.persistent == target and state.live == target then
            committed = state
            break
        end
        if attempt < 50 then Script.Yield(200) end
    end
    if not committed then return postCommitFailure("stock_commit_readback_failed") end
    self.pendingRefillTransactions[self:GetRefillRequestKey(request)] = nil

    if request.kind == "factory" then
        local alertState = self.alertState[request.index]
        if alertState then alertState.low = false end
    end
    self.lastRefillEvidence = {
        kind = request.kind,
        index = request.index,
        beforePersistent = before.persistent,
        beforeLive = before.live,
        afterPersistent = committed.persistent,
        afterLive = committed.live,
        packingConfirmed = request.kind ~= "hangar"
            or committed.packingConfirmed == true,
        transactionAccepted = true,
        historicalServerOwnershipConfirmed = true,
        at = os.clock()
    }
    Logger:Info("SovereignInventory", string.format(
        "%s refill verified persistent=%d->%d live=%d->%d transaction=accepted",
        tostring(request.name or request.kind), before.persistent, committed.persistent,
        before.live, committed.live
    ))
    return true, "transaction_accepted"
end

function SovereignBusinessInventory:SetWarehouseStock(
    index, value, previousValue, cargoSelection, repairExisting, rollbackOnFailure,
    expectedIdentity
)
    local definition = self.warehouseDefinitions[index]
    if not definition then return false, "invalid_request" end
    if type(expectedIdentity) ~= "table" then
        expectedIdentity = self:CaptureRefillIdentity({
            kind = "warehouse", index = index
        })
    end
    if type(expectedIdentity) ~= "table" then
        return false, "refill_identity_unavailable"
    end
    local characterSlot = expectedIdentity.characterSlot
    local playerId = expectedIdentity.playerId
    local function identityCurrent()
        local current = self:CaptureRefillIdentity({
            kind = "warehouse", index = index
        })
        return current ~= nil and self:AreRefillIdentitiesEqual(
            current, expectedIdentity
        )
    end
    if not identityCurrent() then return false, "refill_identity_changed" end
    local capacity = self:GetWarehouseCapacity(definition, playerId)
    if capacity <= 0 then return false, "warehouse_not_owned" end
    local target = math.max(0, math.min(capacity, math.floor(tonumber(value) or 0)))
    local previous = math.max(0, math.min(
        capacity,
        math.floor(tonumber(previousValue)
            or tonumber(self:ReadWarehouseProduct(
                definition, characterSlot, playerId
            )) or 0)
    ))
    local runtimeGlobal = self:GetWarehouseRuntimeProductGlobal(
        definition.index, playerId
    )
    if not runtimeGlobal then return false, "runtime_global_unavailable" end
    local previousPersistent = self:ReadWarehousePersistentProduct(
        definition, characterSlot
    )
    local previousLive = self:ReadGlobal(runtimeGlobal)

    -- Calls without a prior accepted server transaction are packing repairs
    -- only. Refuse any local-only quantity change that could later sell without
    -- a matching server-side ownership record.
    if rollbackOnFailure ~= false
        and (previousPersistent ~= target or previousLive ~= target) then
        return false, "warehouse_local_delta_forbidden"
    end

    local packingOk, packingChanges, packingReason = self:CommitWarehousePacking(
        definition, previous, target, cargoSelection, repairExisting == true,
        characterSlot, playerId, identityCurrent
    )

    local function quarantineRollback(reason)
        local quarantineKey = "warehouse:" .. tostring(
            math.floor(tonumber(index) or 0)
        )
        self.refillRejectedKeys[quarantineKey] = true
        self.refillQuarantine[quarantineKey] = {
            request = {kind = "warehouse", index = index, name = definition.name},
            reason = "warehouse_rollback_unconfirmed",
            quarantinedAt = os.clock()
        }
        Logger:Error("SovereignInventory", string.format(
            "%s rollback incomplete: %s", tostring(definition.name), tostring(reason)
        ))
    end

    local function rollbackPackingPinned(reason)
        if rollbackOnFailure == false then return false, reason end
        local restored = self:RollbackWarehousePacking(
            definition, packingChanges, characterSlot, nil
        )
        for _, change in ipairs(packingChanges or {}) do
            if self:ReadWarehouseCrateCode(
                definition, change.crateIndex, characterSlot
            ) ~= change.original then
                restored = false
                break
            end
        end
        if not restored then quarantineRollback(reason) end
        return false, reason
    end

    if not packingOk then
        if #(packingChanges or {}) > 0 then
            return rollbackPackingPinned(packingReason or "packing_write_failed")
        end
        return false, packingReason or "packing_write_failed"
    end

    local function rollback(reason)
        if rollbackOnFailure == false then return false, reason end
        if not identityCurrent() then
            return rollbackPackingPinned("refill_identity_changed")
        end
        local restored = self:RollbackWarehousePacking(
            definition, packingChanges, characterSlot, identityCurrent
        )
        local persistentRestore = type(previousPersistent) == "number" and previousPersistent or previous
        local liveRestore = type(previousLive) == "number" and previousLive or previous
        restored = self:WriteStatByIndex(
            definition.productIndex, persistentRestore, characterSlot
        ) and restored
        restored = self:WriteGlobalVerified(runtimeGlobal, liveRestore) and restored
        restored = self:SaveStats() and restored
        local packingRestored = true
        for _, change in ipairs(packingChanges or {}) do
            if self:ReadWarehouseCrateCode(
                definition, change.crateIndex, characterSlot
            )
                ~= change.original then
                packingRestored = false
                break
            end
        end
        local persistentReadback = self:ReadWarehousePersistentProduct(
            definition, characterSlot
        )
        local liveReadback = self:ReadGlobal(runtimeGlobal)
        restored = restored and packingRestored
            and persistentReadback == persistentRestore
            and liveReadback == liveRestore
        if not restored then
            quarantineRollback(reason)
        end
        return false, reason
    end

    if not identityCurrent() then
        return rollbackPackingPinned("refill_identity_changed")
    end
    if rollbackOnFailure == false then
        local boundaryPersistent = self:ReadWarehousePersistentProduct(
            definition, characterSlot
        )
        local boundaryLive = self:ReadGlobal(runtimeGlobal)
        if type(boundaryPersistent) ~= "number" or type(boundaryLive) ~= "number" then
            return false, "warehouse_state_unavailable"
        end
        local persistentAllowed = boundaryPersistent == previousPersistent
            or boundaryPersistent == target
        local liveAllowed = boundaryLive == previousLive or boundaryLive == target
        if not persistentAllowed or not liveAllowed then
            Logger:Warn("SovereignInventory", string.format(
                "%s aggregate write boundary changed baseline=%s/%s target=%d actual=%s/%s",
                tostring(definition.name), tostring(previousPersistent),
                tostring(previousLive), target, tostring(boundaryPersistent),
                tostring(boundaryLive)
            ))
            return false, "warehouse_state_changed"
        end
    end
    local statCommitted = self:WriteStatByIndex(
        definition.productIndex, target, characterSlot
    )
    if not statCommitted then return rollback("stat_commit_failed") end
    if not self:WriteGlobalVerified(runtimeGlobal, target) then return rollback("live_commit_failed") end
    if not identityCurrent() then return rollback("refill_identity_changed") end
    if not self:SaveStats() then return rollback("stat_save_failed") end
    if not identityCurrent() then return rollback("refill_identity_changed") end

    local persistent = self:ReadWarehousePersistentProduct(definition, characterSlot)
    local live = self:ReadGlobal(runtimeGlobal)
    if persistent ~= target or live ~= target
        or not self:VerifyWarehousePacking(
            definition, packingChanges, characterSlot
        ) then
        return rollback("warehouse_commit_readback_failed")
    end
    return true, nil
end

function SovereignBusinessInventory:GetRuntimeSnapshot()
    local function count(entries)
        local total = 0
        for _ in pairs(type(entries) == "table" and entries or {}) do total = total + 1 end
        return total
    end
    local queued, active = 0, 0
    for _, item in pairs(self.operationQueue or {}) do
        if not item.cancelled then queued = queued + (item.remaining or 0) end
        if item.active then active = active + 1 end
    end
    local layout = self:GetInventoryLayout()
    local snapshot = {
        revision = self.runtimeRevision, edition = Utils1:edition(),
        layout = layout and layout.name or "unavailable",
        characterSlot = self:GetCharacterSlot(), organization = self:GetLocalOrganizationState(),
        globalsAvailable = self:HasInventoryMapping("freemode_globals"),
        transactionsAvailable = self:HasInventoryMapping("transaction_layout"),
        saleLocalsAvailable = self:HasInventoryMapping("sale_locals"),
        queued = queued, active = active,
        transactionBusy = self.transactionBusy == true, saleLaunchBusy = self.saleLaunchBusy == true,
        pendingRefills = count(self.pendingRefillTransactions), pendingSales = count(self.pendingSaleReservation),
        refillQuarantines = count(self.refillQuarantine), saleQuarantines = count(self.saleQuarantine),
        factoriesOwned = 0, warehousesOwned = 0, inventoryReadable = false
    }
    for _, item in pairs(self.data and self.data.factories or {}) do
        if item.owned then snapshot.factoriesOwned = snapshot.factoriesOwned + 1 end
        if item.property ~= nil then snapshot.inventoryReadable = true end
    end
    for _, item in pairs(self.data and self.data.warehouses or {}) do
        if item.owned then snapshot.warehousesOwned = snapshot.warehousesOwned + 1 end
    end
    return snapshot
end

function SovereignBusinessInventory:CancelQueuedOperations()
    local cancelled = 0
    for _, item in pairs(self.operationQueue or {}) do
        if not item.cancelled then
            cancelled = cancelled + (item.remaining or 0)
            item.cancelled = true
        end
    end
    -- No accepted basket, dispatched mission or settlement observer is removed.
    return cancelled
end

function SovereignBusinessInventory:QueueRefillRequests(requests, successText)
    if self.transactionBusy or self.saleLaunchBusy then
        self:Notify("A restock or sale is processing", "warning")
        return false
    end
    if type(self.pendingSaleReservation) == "table"
        and next(self.pendingSaleReservation) ~= nil then
        self:Notify("Sale settling; restock not started", "warning")
        return false
    end
    if self:GetRunningSaleScript(self.saleMissionScripts) then
        self:Notify("Sale mission in progress; restock not started", "warning")
        return false
    end
    if type(self.pendingRefillTransactions) == "table"
        and next(self.pendingRefillTransactions) ~= nil then
        self:ProcessPendingRefillTransactions()
        if next(self.pendingRefillTransactions) ~= nil then
            self:Notify(self:GetRefillErrorText("refill_pending_verification"), "warning")
            return false
        end
    end
    if type(requests) ~= "table" or #requests == 0 then
        self:Notify("No restock targets available", "warning")
        return false
    end
    for _, request in ipairs(requests) do
        local accessOk, accessReason = self:CheckRefillAccess(request)
        if not accessOk then
            self:Notify(self:GetRefillErrorText(accessReason), "warning")
            return false
        end
    end
    if not Script or type(Script.QueueJob) ~= "function" then
        self:Notify("Cannot submit a restock request right now", "error")
        return false
    end
    self.operationQueue = self.operationQueue or {}
    self.operationQueueSerial = (self.operationQueueSerial or 0) + 1
    local queueId = self.operationQueueSerial
    local queueItem = {kind = "refill", remaining = #requests, active = false}
    self.operationQueue[queueId] = queueItem
    self.transactionBusy = true
    local ok, queued = pcall(Script.QueueJob, function()
        local completed, unchanged, failed, failureReason = 0, 0, 0, nil
        local runOk, runError = pcall(function()
            for _, request in ipairs(requests or {}) do
                if queueItem.cancelled then break end
                queueItem.remaining = math.max(0, queueItem.remaining - 1)
                queueItem.active = true
                if self.saleLaunchBusy
                    or next(self.pendingSaleReservation or {}) ~= nil
                    or self:GetRunningSaleScript(self.saleMissionScripts) then
                    failed = failed + 1
                    failureReason = "sale_in_progress"
                    break
                end
                local applied, reason = self:ApplyRefillRequest(request)
                if applied then
                    if reason == "transaction_accepted" then
                        completed = completed + 1
                    else
                        unchanged = unchanged + 1
                    end
                else
                    failed = failed + 1
                    failureReason = reason
                    Logger:Warn("SovereignInventory", string.format(
                        "%s refill transaction failed: %s",
                        tostring(request.name or request.kind), tostring(reason)
                    ))
                    -- Any failed request can follow an irreversible basket
                    -- acceptance. Stop the batch before another server request.
                    break
                end
            end
        end)
        self.operationQueue[queueId] = nil
        self.transactionBusy = false
        pcall(function() self:RefreshData() end)
        if not runOk then
            self.restockFailureCount = math.min(4, (tonumber(self.restockFailureCount) or 0) + 1)
            self.restockBackoffUntil = os.clock() + math.min(300, 30 * (2 ^ (self.restockFailureCount - 1)))
            Logger:Error("SovereignInventory", "refill queue exception: " .. tostring(runError))
            self:Notify("Restock incomplete. Do not repeat the action", "error")
            return
        end
        if queueItem.cancelled then
            self:Notify("Pending restocks cancelled; started requests continue processing", "info")
            return
        end
        if completed > 0 and failed == 0 then
            self.restockFailureCount = 0
            self.restockBackoffUntil = 0
            self:Notify(
                successText or "Restock completed",
                "success"
            )
        elseif completed > 0 then
            self.restockFailureCount = math.min(4, (tonumber(self.restockFailureCount) or 0) + 1)
            self.restockBackoffUntil = os.clock() + math.min(300, 30 * (2 ^ (self.restockFailureCount - 1)))
            self:Notify(
                "Some restocks completed; " .. self:GetRefillErrorText(failureReason),
                "warning"
            )
        elseif unchanged > 0 and failed == 0 then
            self.restockFailureCount = 0
            self.restockBackoffUntil = 0
            self:Notify(
                "Cargo is full; no restock needed",
                "info"
            )
        elseif unchanged > 0 then
            self.restockFailureCount = math.min(4, (tonumber(self.restockFailureCount) or 0) + 1)
            self.restockBackoffUntil = os.clock()
                + math.min(300, 30 * (2 ^ (self.restockFailureCount - 1)))
            self:Notify(
                "Some cargo is already full; " .. self:GetRefillErrorText(failureReason),
                "warning"
            )
        else
            self.restockFailureCount = math.min(4, (tonumber(self.restockFailureCount) or 0) + 1)
            self.restockBackoffUntil = os.clock() + math.min(300, 30 * (2 ^ (self.restockFailureCount - 1)))
            self:Notify(self:GetRefillErrorText(failureReason), "error")
        end
    end)
    if not ok or queued == false then
        self.operationQueue[queueId] = nil
        self.transactionBusy = false
        self:Notify("Cannot submit a restock request right now", "error")
        return false
    end
    self:Notify("Restock processing", "info")
    return true
end

-- freemode: business 1 -> packed integer 24924; character slot is explicit.
function SovereignBusinessInventory:ClearCarWashHeat()
    local slot = self:GetCharacterSlot()
    if slot ~= 0 and slot ~= 1 then return false, "Your character is not ready yet" end
    local before = self:ReadPackedIntStat(24924, slot)
    if type(before) ~= "number" or before < 0 or before > 100 then
        return false, "Could not read the heat level"
    end
    if self:GetCharacterSlot() ~= slot then return false, "Your character changed. Please try again." end
    if before ~= 0 and not self:WritePackedIntStat(24924, 0, slot) then
        return false, "Could not clear the heat level. Please try again."
    end
    if self:GetCharacterSlot() ~= slot or self:ReadPackedIntStat(24924, slot) ~= 0 then
        return false, "The heat level is still above zero. Please try again."
    end
    self.lastCarWashHeat = {slot=slot, before=before, after=0}
    return true, "Car wash heat: " .. tostring(before) .. " → 0"
end

function SovereignBusinessInventory:BindCarWashHeat(group)
    menu.button("Clear car wash heat", "Clear the current character's car wash heat and verify the result.", group, 0, function()
        local ok, message = self:ClearCarWashHeat()
        self:Notify(message, ok and "success" or "warning")
    end)
end

