function SovereignBusinessInventory:ReadIndices(indices, characterSlot)
    local values = {}
    if characterSlot == nil then characterSlot = self:GetCharacterSlot() end
    characterSlot = tonumber(characterSlot)
    if type(characterSlot) ~= "number"
        or (characterSlot ~= 0 and characterSlot ~= 1) then
        return values
    end
    characterSlot = math.floor(characterSlot)
    for _, index in ipairs(indices or {}) do
        for _, hash in ipairs(self:GetStatHashCandidates(index, characterSlot)) do
            local value = self:ReadStatIntCompat(hash)
            if type(value) == "number" and value == value then
                values[index] = value
                break
            end
        end
    end
    return values
end

function SovereignBusinessInventory:ReadCachedCapacityGlobal(index)
    self.capacityCache = type(self.capacityCache) == "table" and self.capacityCache or {}
    local key = math.floor(tonumber(index) or 0)
    local now = os.clock()
    local cached = self.capacityCache[key]
    if type(cached) == "table" and now - (tonumber(cached.at) or 0) < 30.0 then
        return cached.value
    end
    local value = self:ReadGlobal(key)
    if type(value) == "number" then
        self.capacityCache[key] = {value = value, at = now}
    end
    return value
end

function SovereignBusinessInventory:GetProductCapacity(definition)
    local capacity = self:ReadCachedCapacityGlobal(262145 + (definition.maxGlobal or 0))
    if type(capacity) ~= "number" or capacity <= 0 then
        capacity = definition.fallbackMax
    end
    return math.max(1, math.floor(tonumber(capacity) or 1))
end

function SovereignBusinessInventory:GetNightclubFloors(playerId)
    if playerId == nil then playerId = self:GetLocalPlayerId() end
    playerId = tonumber(playerId)
    if playerId == nil then return 0 end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 then return 0 end
    local playerBase = 1845347 + 1 + (playerId * 884)
    local flagsGlobal = playerBase + 260 + 321 + 4
    local cachedFloorsGlobal = playerBase + 260 + 321 + 6
    local flags = self:ReadGlobal(flagsGlobal)
    local cachedFloors = self:ReadGlobal(cachedFloorsGlobal)
    if type(flags) ~= "number" or type(cachedFloors) ~= "number" then return 0 end

    -- Enhanced freemode func_20751 checks f_321.f_4 bits 12..15, in
    -- descending order, and always returns at least one owned floor. The
    -- low five bits are unrelated nightclub upgrade/eligibility flags.
    flags = math.floor(flags)
    local derivedFloors = 1
    if (flags & (1 << 15)) ~= 0 then
        derivedFloors = 5
    elseif (flags & (1 << 14)) ~= 0 then
        derivedFloors = 4
    elseif (flags & (1 << 13)) ~= 0 then
        derivedFloors = 3
    elseif (flags & (1 << 12)) ~= 0 then
        derivedFloors = 2
    end
    cachedFloors = math.floor(cachedFloors)
    if cachedFloors < 1 or cachedFloors > 5 or cachedFloors ~= derivedFloors then
        -- Do not derive a capacity from a partially refreshed player block.
        return 0
    end
    return derivedFloors
end

function SovereignBusinessInventory:GetNightclubCapacity(definition, floors)
    if floors <= 0 then return 0 end
    local base = self:ReadCachedCapacityGlobal(262145 + (definition.maxGlobal or 0))
    if type(base) ~= "number" or base <= 0 then return 0 end
    return math.max(1, math.floor(base / 5) * floors)
end

function SovereignBusinessInventory:SetFactorySupply(index, value, playerId)
    local definition = self.factoryDefinitions[index]
    if not definition then return false end
    value = math.max(0, math.min(100, math.floor(tonumber(value) or 0)))
    if playerId == nil then playerId = self:GetLocalPlayerId() end
    playerId = tonumber(playerId)
    if playerId == nil then return false end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 then return false end
    local playerBase = 1845347 + 1 + (playerId * 884)
    -- f_205 is an array of seven 13-slot structures. The first slot stores
    -- the array length, so element zero begins at f_205 + 1.
    local runtimeBase = playerBase + 260 + 205 + 1 + ((index - 1) * 13)
    -- freemode keeps a live value, a mirror value, and a per-business baseline.
    -- Updating only the stat/live value creates a delta that freemode rolls back.
    local liveOk = self:WriteGlobalVerified(runtimeBase + 2, value)
    local mirrorOk = self:WriteGlobalVerified(runtimeBase + 3, value)
    -- Global_1673847 is also a script array; skip its length slot.
    local baselineOk = self:WriteGlobalVerified(1673847 + 1 + (index - 1), value)
    return liveOk and mirrorOk and baselineOk
end

function SovereignBusinessInventory:SetFactoryProduct(index, value, playerId)
    local definition = self.factoryDefinitions[index]
    if not definition then return false end
    local entry = self.data and self.data.factories and self.data.factories[index]
    local capacity = entry and tonumber(entry.maxProduct) or self:GetProductCapacity(definition)
    value = math.max(0, math.min(capacity, math.floor(tonumber(value) or 0)))
    if playerId == nil then playerId = self:GetLocalPlayerId() end
    playerId = tonumber(playerId)
    if playerId == nil then return false end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 then return false end
    local playerBase = 1845347 + 1 + (playerId * 884)
    local runtimeBase = playerBase + 260 + 205 + 1 + ((index - 1) * 13)
    -- f_1 is freemode's live product quantity.
    local wrote = self:WriteGlobalVerified(runtimeBase + 1, value)
    if wrote and entry then entry.product = value end
    return wrote
end

function SovereignBusinessInventory:SetNightclubStock(index, value, playerId)
    local definition = self.nightclubDefinitions[index]
    if not definition then return false end
    local floors = self:GetNightclubFloors(playerId)
    local capacity = self:GetNightclubCapacity(definition, floors)
    if capacity <= 0 then return false end
    value = math.max(0, math.min(capacity, math.floor(tonumber(value) or capacity)))
    if playerId == nil then playerId = self:GetLocalPlayerId() end
    playerId = tonumber(playerId)
    if playerId == nil then return false end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 then return false end
    local runtimeGlobal = 1845347 + 1 + (playerId * 884)
        + 260 + 321 + 8 + 1 + (index - 1)
    return self:WriteGlobalVerified(runtimeGlobal, value)
end

function SovereignBusinessInventory:SetHangarStock(
    value, previousValue, rollbackOnFailure, expectedSlots, expectedIdentity
)
    local maxStock = math.floor(tonumber(self.data and self.data.hangarMax) or 50)
    local target = tonumber(value)
    if type(target) ~= "number" or target ~= target then
        return false, "invalid_request"
    end
    target = math.floor(target)
    if target < 0 or target > maxStock or maxStock ~= 50 then
        return false, "stock_capacity_invalid"
    end
    local suppliedPlan = type(expectedSlots) == "table"
        and self:ValidateHangarPackingPlan(expectedSlots, target) or nil
    if type(expectedSlots) == "table" and not suppliedPlan then
        return false, "hangar_packing_inconsistent"
    end
    if type(expectedIdentity) ~= "table" then
        expectedIdentity = self:CaptureRefillIdentity({kind = "hangar", index = 0})
    end
    if type(expectedIdentity) ~= "table" then
        return false, "refill_identity_unavailable", suppliedPlan
    end
    local characterSlot = expectedIdentity.characterSlot
    local playerId = expectedIdentity.playerId
    local function identityCurrent()
        local current = self:CaptureRefillIdentity({kind = "hangar", index = 0})
        return current ~= nil and self:AreRefillIdentitiesEqual(
            current, expectedIdentity
        )
    end
    if not identityCurrent() then
        return false, "refill_identity_changed", suppliedPlan
    end
    if rollbackOnFailure == false and suppliedPlan then
        local ok, reason = self:CommitHangarPackingSnapshot(
            target, suppliedPlan, characterSlot, playerId, identityCurrent
        )
        return ok, reason, suppliedPlan
    end

    local original, packingReason = self:ReadHangarPackingState(characterSlot)
    if not original then return false, packingReason, suppliedPlan end
    local previous = tonumber(previousValue)
    if type(previous) ~= "number" or previous ~= previous then previous = original.count end
    previous = math.floor(previous)
    if previous < 0 or previous > 50 or original.count ~= previous then
        return false, "hangar_packing_inconsistent", suppliedPlan
    end
    local originalValues = self:ReadIndices({6104}, characterSlot)
    local originalPersistent = self:NormalizeStockValue(
        originalValues and originalValues[6104], 50
    )
    local runtimeGlobal = 1845347 + 1 + (playerId * 884) + 260 + 304 + 3
    local originalLive = self:NormalizeStockValue(self:ReadGlobal(runtimeGlobal), 50)
    local originalFullFlag = self:ReadPackedBoolStat(41987, original.characterSlot)
    if originalPersistent ~= previous or originalLive ~= previous then
        return false, "stock_state_inconsistent", suppliedPlan
    end
    local desired, planReason = suppliedPlan, nil
    if not desired then
        desired, planReason = self:BuildHangarPackingPlan(original, target)
    end
    if not desired then return false, planReason, nil end

    local committed, commitReason = self:CommitHangarPackingSnapshot(
        target, desired, characterSlot, playerId, identityCurrent
    )
    if committed then return true, nil, desired end
    if rollbackOnFailure == false then return false, commitReason, desired end
    if not identityCurrent() then
        return false, "refill_identity_changed", desired
    end

    local restored = self:CommitHangarPackingSnapshot(
        previous, original.slots, characterSlot, playerId, identityCurrent
    )
    if type(originalFullFlag) == "boolean" then
        restored = self:WritePackedBoolStat(
            41987, originalFullFlag, original.characterSlot
        ) and restored
        restored = self:SaveStats() and restored
    end
    if not restored or not self:VerifyHangarPacking(
        previous, original.slots, characterSlot
    ) then
        Logger:Error("SovereignInventory", string.format(
            "hangar rollback incomplete reason=%s", tostring(commitReason)
        ))
    end
    return false, commitReason, desired
end

function SovereignBusinessInventory:RefreshData(section)
    if type(self) ~= "table" then return false end
    local factoryDefinitions = type(self.factoryDefinitions) == "table" and self.factoryDefinitions or {}
    local nightclubDefinitions = type(self.nightclubDefinitions) == "table" and self.nightclubDefinitions or {}
    local warehouseDefinitions = type(self.warehouseDefinitions) == "table" and self.warehouseDefinitions or {}
    if type(self.ReadIndices) ~= "function" then return false end

    local full = section == nil or section == "all"
    local data = type(self.data) == "table" and self.data or {}
    data.factories = type(data.factories) == "table" and data.factories or {}
    data.nightclub = type(data.nightclub) == "table" and data.nightclub or {}
    data.warehouses = type(data.warehouses) == "table" and data.warehouses or {}

    if full or section == "factories_a" or section == "factories_b" then
        local firstIndex = full and 1 or (section == "factories_a" and 1 or 4)
        local lastIndex = full and #factoryDefinitions or (section == "factories_a" and 3 or #factoryDefinitions)
        local indices = {}
        for index = firstIndex, lastIndex do
            local definition = factoryDefinitions[index]
            if definition then
                indices[#indices + 1] = definition.property
                indices[#indices + 1] = definition.supply
                indices[#indices + 1] = definition.product
            end
        end
        local values = self:ReadIndices(indices)
        local factories = full and {} or data.factories
        for index = firstIndex, lastIndex do
            local definition = factoryDefinitions[index]
            if definition then
                local property = values[definition.property]
                factories[index] = {
                    name = definition.name,
                    property = property,
                    owned = type(property) == "number" and property ~= 0,
                    supply = values[definition.supply],
                    product = values[definition.product],
                    maxProduct = type(self.GetProductCapacity) == "function"
                        and self:GetProductCapacity(definition)
                        or math.max(1, math.floor(tonumber(definition.fallbackMax) or 1)),
                    definition = definition
                }
            end
        end
        data.factories = factories
    end

    if full or section == "nightclub" then
        local values = self:ReadIndices({7222, 7223, 7224, 7225, 7226, 7227, 7228})
        local floors = type(self.GetNightclubFloors) == "function" and self:GetNightclubFloors() or 0
        local nightclub = {}
        for index, definition in ipairs(nightclubDefinitions) do
            nightclub[#nightclub + 1] = {
                name = definition.name,
                value = values[7221 + index],
                max = type(self.GetNightclubCapacity) == "function"
                    and self:GetNightclubCapacity(definition, floors) or 0
            }
        end
        data.nightclub = nightclub
        data.nightclubFloors = floors
    end

    if full or section == "warehouses_a" or section == "warehouses_b" then
        local firstIndex = full and 1 or (section == "warehouses_a" and 1 or 3)
        local lastIndex = full and #warehouseDefinitions or (section == "warehouses_a" and 2 or #warehouseDefinitions)
        local warehouses = full and {} or data.warehouses
        for index = firstIndex, lastIndex do
            local definition = warehouseDefinitions[index]
            if definition then
                local warehouseType = self:ReadWarehouseType(definition)
                local stock = self:ReadWarehouseProduct(definition)
                local location = self:GetWarehouseLocation(warehouseType)
                warehouses[index] = {
                    name = definition.name .. (location and (" · " .. location.size) or ""),
                    value = type(stock) == "number" and stock or 0,
                    max = math.floor(tonumber(self.warehouseCapacityByType[warehouseType]) or 0),
                    owned = warehouseType >= 1 and warehouseType <= 22,
                    warehouseType = warehouseType,
                    location = location,
                    locationName = self:GetWarehouseLocationName(warehouseType),
                    definition = definition
                }
            end
        end
        data.warehouses = warehouses
    end

    if full or section == "special" then
        local values = self:ReadIndices({6103, 6104, 7212, 8836})
        local nightclubSafeMax = self:ReadCachedCapacityGlobal(262145 + 23773)
        local arcadeSafeMax = self:ReadCachedCapacityGlobal(262145 + 28878)
        data.hangar = values[6104]
        data.hangarMax = 50
        data.hangarOwned = values[6103]
        data.nightclubSafe = values[7212]
        data.nightclubSafeMax = type(nightclubSafeMax) == "number" and nightclubSafeMax > 0 and nightclubSafeMax or 250000
        data.arcadeSafe = values[8836]
        data.arcadeSafeMax = type(arcadeSafeMax) == "number" and arcadeSafeMax > 0 and arcadeSafeMax or 100000
    end

    self.data = data
    return true
end

function SovereignBusinessInventory:RefreshDataStep()
    self.refreshPhase = ((math.floor(tonumber(self.refreshPhase) or 0)) % 6) + 1
    if self.refreshPhase == 1 then return self:RefreshData("factories_a") end
    if self.refreshPhase == 2 then return self:RefreshData("factories_b") end
    if self.refreshPhase == 3 then return self:RefreshData("nightclub") end
    if self.refreshPhase == 4 then return self:RefreshData("warehouses_a") end
    if self.refreshPhase == 5 then return self:RefreshData("warehouses_b") end
    return self:RefreshData("special")
end

function SovereignBusinessInventory:RestockSelected()
    self:RefreshData()
    local index = math.max(1, math.min(#self.factoryDefinitions, math.floor(tonumber(self.selectedFactory) or 1)))
    local entry = self.data.factories[index]
    if not entry or not entry.owned then
        self:Notify("The selected business has not been purchased", "warning")
        return false
    end
    return self:QueueRefillRequests({{
        kind = "factory", index = index, target = 100, name = entry.name
    }}, entry.name .. "Supplies restocked")
end

function SovereignBusinessInventory:RestockAll()
    self:RefreshData()
    local requests = {}
    for index, entry in ipairs(self.data.factories or {}) do
        if entry.owned then
            local supplyRequest = {
                kind = "factory", index = index, target = 100, name = entry.name
            }
            if self:CheckRefillAccess(supplyRequest) then
                requests[#requests + 1] = supplyRequest
            end
        end
    end
    if #requests == 0 then
        self:Notify("No purchased businesses can be restocked under this organization", "warning")
        return false
    end
    return self:QueueRefillRequests(requests, "Supplies restocked for available businesses")
end

function SovereignBusinessInventory:RestockNightclubSelected()
    self:RefreshData()
    local index = math.max(1, math.min(#self.nightclubDefinitions, math.floor(tonumber(self.selectedNightclub) or 1)))
    local entry = self.data.nightclub[index]
    if not entry or type(entry.max) ~= "number" or entry.max <= 0 then
        self:Notify("This nightclub product is unavailable or locked", "warning")
        return false
    end
    return self:QueueRefillRequests({{
        kind = "nightclub", index = index, target = entry.max, name = entry.name
    }}, entry.name .. "Restocked")
end

function SovereignBusinessInventory:RestockNightclubAll()
    self:RefreshData()
    local requests = {}
    for index, entry in ipairs(self.data.nightclub or {}) do
        if type(entry.max) == "number" and entry.max > 0 then
            requests[#requests + 1] = {
                kind = "nightclub", index = index, target = entry.max, name = entry.name
            }
        end
    end
    if #requests == 0 then
        self:Notify("Nightclub warehouse not found", "warning")
        return false
    end
    return self:QueueRefillRequests(requests, "Nightclub warehouse filled")
end

function SovereignBusinessInventory:RestockHangar()
    self:RefreshData()
    if type(self.data.hangarOwned) ~= "number" or self.data.hangarOwned == 0 then
        self:Notify("No purchased hangar found", "warning")
        return false
    end
    local target = math.max(1, math.floor(tonumber(self.data.hangarMax) or 50))
    return self:QueueRefillRequests({{
        kind = "hangar", target = target, name = "Hangar cargo"
    }}, "Hangar cargo filled")
end

function SovereignBusinessInventory:RestockWarehouseSelected()
    self:RefreshData()
    local index = math.max(1, math.min(#self.warehouseDefinitions, math.floor(tonumber(self.selectedWarehouse) or 1)))
    local entry = self.data.warehouses and self.data.warehouses[index]
    if not entry then
        self:Notify("Selected office warehouse could not be read", "warning")
        return false
    end
    local accessOk, accessReason = self:CheckWarehouseAccess(index)
    if not accessOk then
        self:NotifyWarehouseAccessError(accessReason)
        return false
    end
    return self:QueueRefillRequests({{
        kind = "warehouse", index = index, target = entry.max, name = entry.name,
        cargoType = self.selectedWarehouseCargo
    }}, entry.name .. "Restocked")
end

function SovereignBusinessInventory:RestockWarehouses()
    self:RefreshData()
    local accessOk, accessReason = self:CheckWarehouseAccess(nil)
    if not accessOk then
        self:NotifyWarehouseAccessError(accessReason)
        return false
    end
    local requests = {}
    for index, entry in ipairs(self.data.warehouses or {}) do
        if entry.owned and type(entry.max) == "number" and entry.max > 0 then
            requests[#requests + 1] = {
                kind = "warehouse", index = index, target = entry.max, name = entry.name,
                cargoType = self.selectedWarehouseCargo
            }
        end
    end
    if #requests == 0 then
        self:Notify("Office warehouse is already full", "info")
        return false
    end
    return self:QueueRefillRequests(requests, "Purchased office warehouses filled")
end

function SovereignBusinessInventory:IsScriptRunning(scriptName)
    scriptName = tostring(scriptName or "")
    if scriptName == "" then return false end
    if menu.nativeApis.SCRIPT and type(menu.nativeApis.SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH) == "function"
        and Utils and type(Utils.Joaat) == "function" then
        local ok, count = pcall(
            menu.nativeApis.SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH,
            Utils.Joaat(scriptName)
        )
        if ok and type(count) == "number" and count > 0 then return true end
    end
    if not menu.nativeApis.NETWORK or type(menu.nativeApis.NETWORK.NETWORK_IS_SCRIPT_ACTIVE) ~= "function" then
        return false
    end
    local localPlayerId = self:GetLocalPlayerId()
    local instanceIds = {-1}
    if localPlayerId ~= nil then instanceIds[#instanceIds + 1] = localPlayerId end
    for _, instanceId in ipairs(instanceIds) do
        for _, networked in ipairs({true, false}) do
            local ok, active = pcall(
                menu.nativeApis.NETWORK.NETWORK_IS_SCRIPT_ACTIVE,
                scriptName,
                instanceId,
                networked,
                0
            )
            if ok and active == true then return true end
        end
    end
    return false
end

function SovereignBusinessInventory:GetRunningSaleScript(scriptNames)
    for _, scriptName in ipairs(scriptNames or {}) do
        if self:IsScriptRunning(scriptName) then
            return scriptName
        end
    end
    return nil
end

function SovereignBusinessInventory:IsSaleScopeEnabled(scope)
    return self.autoSellScope == 3 or scope == self.autoSellScope
end

function SovereignBusinessInventory:CollectSaleTargets(allowUnregistered)
    local targets = {}
    -- Auto-register must discover a target before the required CEO/MC state
    -- exists. The caller re-checks the role and re-collects after registration.
    local canUseBikerBusinesses = allowUnregistered == true
        or self:IsLocalMCPresident()
    local canUseWarehouses = allowUnregistered == true
        or self:IsLocalCEO()
    -- Keep the biker businesses in the same order as the inventory list.
    -- The bunker path is intentionally excluded because its sale script does
    -- not reliably enter the mission state on the current build.
    for index = 1, 5 do
        local entry = self.data.factories and self.data.factories[index]
        if canUseBikerBusinesses and entry and entry.owned and type(entry.product) == "number"
            and type(entry.maxProduct) == "number" and entry.maxProduct > 0 and entry.product > 0 then
            local ratio = math.max(0, math.min(100, entry.product * 100 / entry.maxProduct))
            targets[#targets + 1] = {
                key = "biker", scope = 1, name = entry.name,
                latchKey = "biker_" .. tostring(index - 1),
                ratio = ratio, script = "appbikerbusiness", missionScript = "gb_biker_contraband_sell",
                factoryIndex = index - 1, property = entry.property
            }
        end
    end

    for index, entry in ipairs(self.data.warehouses or {}) do
        if canUseWarehouses and entry.owned
            and type(entry.value) == "number" and type(entry.max) == "number"
            and entry.max > 0 and entry.value > 0 then
            targets[#targets + 1] = {
                key = "warehouse", scope = 2, name = entry.name,
                latchKey = "warehouse_" .. tostring(index),
                ratio = math.max(0, math.min(100, entry.value * 100 / entry.max)),
                script = "appsecuroserv", missionScript = "gb_contraband_sell",
                warehouseIndex = index - 1,
                warehouseType = entry.warehouseType
            }
        end
    end

    return targets
end

function SovereignBusinessInventory:SelectSaleTarget(ignoreLatch, allowUnregistered)
    local threshold = math.max(10, math.min(100, tonumber(self.autoSellThreshold) or 90))
    local activeKeys = {}
    for _, target in ipairs(self:CollectSaleTargets(allowUnregistered)) do
        local latchKey = tostring(target.latchKey or target.key)
        activeKeys[latchKey] = true
        if target.key == "warehouse" and self.saleLatch[latchKey]
            and self.saleLatchType[latchKey] ~= nil then
            -- A warehouse can contain special and ordinary cargo. Once the
            -- special batch is gone, the ordinary-cargo sale is a different
            -- reservation and must not inherit the old latch.
            local stock = self:GetSaleStockEvidence(target, nil, {
                attempts = 2, sampleDelay = 0, quiet = true, requireEqual = true,
                packingAttempts = 2, packingDelay = 0
            })
            if stock then
                local selection = self:GetWarehouseSaleSelection(
                    target, stock.persistent, stock.specialPersistent
                )
                if selection and selection.saleType ~= self.saleLatchType[latchKey] then
                    self.saleLatch[latchKey] = nil
                    self.saleLatchType[latchKey] = nil
                end
            end
        end
        if target.ratio < math.max(0, threshold - 5) then
            self.saleLatch[latchKey] = nil
            self.saleLatchType[latchKey] = nil
        end
        if self:IsSaleScopeEnabled(target.scope)
            and target.ratio >= threshold
            and not self.saleRejectedKeys[latchKey]
            and not self.saleQuarantine[latchKey]
            and (ignoreLatch or not self.saleLatch[latchKey]) then
            return target
        end
    end
    for key in pairs(self.saleLatch) do
        if not activeKeys[key] then
            self.saleLatch[key] = nil
            self.saleLatchType[key] = nil
        end
    end
    for key in pairs(self.saleLatchType) do
        if not activeKeys[key] then self.saleLatchType[key] = nil end
    end
    return nil
end

function SovereignBusinessInventory:GetSaleTransactionSpec(target)
    if not Utils or type(Utils.Joaat) ~= "function" or type(target) ~= "table" then return nil end
    if target.key == "biker" then
        -- The MC sale selector is func_21267(0..4), and its catalog item is
        -- IG_SELL_4.  Indices 5/6 belong to other businesses, not MC factories.
        local factoryIndex = math.max(0, math.min(4, math.floor(tonumber(target.factoryIndex) or 0)))
        return {
            item = Utils.Joaat("IG_SELL_4_t0_v0"),
            stat = Utils.Joaat("MP_STAT_MISSIONFORFACTORY" .. tostring(factoryIndex) .. "_v0"),
            resultGlobal = 4516967,
            -- freemode func_21267 selects the sale item with this service and
            -- only then does it publish Global_4516967 for the sell script.
            selectionService = -1018905335,
            service = -788753717,
            selectionItemDataF3 = 1,
            descriptorF10 = 4,
            itemDataF3 = 1,
            missionOwnsFinal = true
        }
    elseif target.key == "nightclub" then
        return {
            item = Utils.Joaat("HUB_CONTRABAND_SELL_v0"),
            stat = Utils.Joaat("HUB_CONTRABAND_MISSION_v0"),
            resultGlobal = 4516967
        }
    elseif target.key == "hangar" then
        return {
            item = Utils.Joaat(self.hangarSaleLand and "HANGAR_CONTRABAND_MISSION_1_t0_v0" or "HANGAR_CONTRABAND_MISSION_0_t0_v0"),
            stat = Utils.Joaat("MP_STAT_HANGAR_CONTRABAND_MISSION_v0"),
            resultGlobal = 4516968,
            -- freemode func_11524 reserves the hangar sale item first; the
            -- gb_smuggler mission submits the inventory/quantity/flags
            -- settlement transaction after the mission is running.
            selectionService = -1018905335,
            selectionItemDataF3 = 1,
            service = -788753717,
            descriptorF10 = 4,
            itemDataF3 = 1,
            missionOwnsFinal = true
        }
    elseif target.key == "warehouse" then
        local warehouseIndex = math.max(0, math.min(4, math.floor(tonumber(target.warehouseIndex) or 0)))
        local layout = nil
        if type(self.GetInventoryLayout) == "function" then
            local ok, value = pcall(self.GetInventoryLayout, self)
            if ok then layout = value end
        end
        if type(layout) ~= "table" and type(Utils1) == "table"
            and type(Utils1.edition) == "function" then
            local ok, edition = pcall(Utils1.edition, Utils1)
            if ok then layout = {edition = edition} end
        end
        local resultGlobal = 4516966
        if type(layout) == "table" and layout.edition == "Legacy" then
            resultGlobal = nil
        end
        return {
            item = Utils.Joaat("CB_SELL_0_t0_v0"),
            stat = Utils.Joaat("MP_STAT_MISSIONFORWHOUSE" .. tostring(warehouseIndex) .. "_v0"),
            -- Enhanced appsecuroserv publishes the selected CB_SELL_0 item
            -- through Global_4516966 before the warehouse mission starts.
            resultGlobal = resultGlobal,
            -- appsecuroserv's office flow reserves CB_SELL_0 here. The
            -- gb_contraband_sell mission owns the later final settlement.
            selectionService = -1018905335,
            selectionItemDataF3 = warehouseIndex,
            service = -788753717,
            descriptorF10 = 4,
            itemDataF3 = 1,
            missionOwnsFinal = true
        }
    end
    return nil
end

function SovereignBusinessInventory:CompleteAcceptedSaleSelector(
    target, saleSnapshot, providedSpec, selectorState
)
    selectorState = type(selectorState) == "table" and selectorState or {}
    selectorState.selectorAccepted = true
    selectorState.phase = selectorState.phase or "selector_accepted"
    local function failSelector(reason, retryable)
        selectorState.reason = reason
        selectorState.retryable = retryable == true
        selectorState.terminal = retryable ~= true
        return false, reason, selectorState
    end
    if selectorState.terminal == true then
        return false, selectorState.reason or "sale_settlement_state_lost",
            selectorState
    end
    if type(target) ~= "table" or type(saleSnapshot) ~= "table" then
        return failSelector("sale_identity_changed", false)
    end
    local spec = type(providedSpec) == "table"
        and providedSpec or self:GetSaleTransactionSpec(target)
    if type(spec) ~= "table" or spec.selectionService == nil then
        return failSelector("invalid_sale", false)
    end
    local item = self:NormalizeSignedInt32(spec.item)
    local missionStat = self:NormalizeSignedInt32(spec.stat)
    local selectionService = self:NormalizeSignedInt32(spec.selectionService)
    if item == nil or item == 0 or missionStat == nil or missionStat == 0
        or selectionService == nil or selectionService == 0 then
        return failSelector("invalid_item", false)
    end
    local identityOk, identityReason = self:IsSaleIdentityCurrent(target, saleSnapshot)
    if not identityOk then
        return failSelector(identityReason or "sale_identity_changed", false)
    end

    -- The selector receipt exists already. Resume only its post-processing;
    -- never submit the selector transaction a second time.
    if type(spec.resultGlobal) == "number"
        and selectorState.resultGlobalWritten ~= true then
        if not self:WriteGlobalVerified(spec.resultGlobal, item) then
            return failSelector("reservation_state_unavailable", true)
        end
        selectorState.resultGlobalWritten = true
        selectorState.phase = "selector_global_written"
        identityOk, identityReason = self:IsSaleIdentityCurrent(target, saleSnapshot)
        if not identityOk then
            return failSelector(identityReason or "sale_identity_changed", false)
        end
    end

    if spec.missionOwnsFinal == true and target.key == "warehouse" then
        if selectorState.finalizerInvoked ~= true then
            local warehouseType = tonumber(saleSnapshot.businessToken)
            local targetWarehouseType = tonumber(target.warehouseType)
            if type(warehouseType) ~= "number" or warehouseType ~= warehouseType
                or warehouseType == rawget(math, "huge") or warehouseType == -rawget(math, "huge")
                or type(targetWarehouseType) ~= "number"
                or targetWarehouseType ~= targetWarehouseType
                or targetWarehouseType == rawget(math, "huge")
                or targetWarehouseType == -rawget(math, "huge") then
                return failSelector("sale_native_unavailable", false)
            end
            warehouseType = math.floor(warehouseType)
            targetWarehouseType = math.floor(targetWarehouseType)
            if warehouseType < 1 or warehouseType > 22
                or targetWarehouseType ~= warehouseType
                or not menu.nativeApis.MONEY
                or type(menu.nativeApis.MONEY.NETWORK_BUY_CONTRABAND_MISSION) ~= "function"
                or not menu.nativeApis.NETSHOPPING
                or type(menu.nativeApis.NETSHOPPING.NET_GAMESERVER_SET_TELEMETRY_NONCE_SEED)
                    ~= "function"
                or type(menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE) ~= "function"
                or not Script or type(Script.ExecuteAsScript) ~= "function" then
                return failSelector("sale_native_unavailable", false)
            end
            identityOk, identityReason = self:IsSaleIdentityCurrent(target, saleSnapshot)
            if not identityOk then
                return failSelector(identityReason or "sale_identity_changed", false)
            end
            local labelHash = Utils.Joaat(
                "MP_WHOUSE_" .. tostring(warehouseType - 1)
            )
            local transactionAlertBefore = self:ReadSaleTransactionAlertSnapshot()
            if transactionAlertBefore.supported ~= false
                and (transactionAlertBefore.readable ~= true
                or transactionAlertBefore.anyActive == true) then
                return failSelector(
                    transactionAlertBefore.readable == true
                        and "transaction_alert_blocked"
                        or "transaction_alert_state_unavailable",
                    false
                )
            end
            local receipt = selectorState.acceptedReceipt
            if type(receipt) ~= "table" or receipt.serverAccepted ~= true
                or receipt.state ~= 2 or type(receipt.base) ~= "number"
                or type(receipt.transactionId) ~= "number"
                or type(receipt.frameCount) ~= "number" then
                return failSelector("sale_settlement_state_lost", false)
            end
            local nativeReason = "sale_native_unavailable"
            local nativeOk = pcall(Script.ExecuteAsScript, "freemode", function()
                local current, currentReason =
                    self:ReadStableFreemodeTransactionIdentity(receipt.base, 1)
                if not current or current.state ~= 2 or current.ownsBasket ~= 1
                    or current.transactionId ~= receipt.transactionId
                    or current.frameCount ~= receipt.frameCount then
                    nativeReason = currentReason or "transaction_state_uncertain"
                    return
                end
                if menu.nativeApis.NETSHOPPING.NET_GAMESERVER_BASKET_IS_ACTIVE() ~= true then
                    nativeReason = "transaction_state_uncertain"
                    return
                end
                -- appsecuroserv binds the accepted selector nonce before its
                -- mission native, while this exact basket/descriptor is live.
                selectorState.nonceAttempted = true
                menu.nativeApis.NETSHOPPING.NET_GAMESERVER_SET_TELEMETRY_NONCE_SEED(
                    receipt.transactionId
                )
                selectorState.nonceSeeded = true
                selectorState.finalizerInvoked = true
                selectorState.phase = "selector_finalizer_invoked"
                menu.nativeApis.MONEY.NETWORK_BUY_CONTRABAND_MISSION(
                    0, warehouseType, labelHash, false, true
                )
                local transactionAlertName = self:GetNewSaleTransactionAlert(
                    transactionAlertBefore
                )
                if transactionAlertName then
                    nativeReason = "transaction_alert_blocked"
                    selectorState.finalizerAlert = transactionAlertName
                    return
                end
                selectorState.finalizerCompleted = true
                selectorState.phase = "selector_finalizer_completed"
            end)
            if not nativeOk then
                selectorState.finalizerUncertain = true
                return failSelector("sale_native_failed", false)
            end
            if selectorState.finalizerCompleted ~= true then
                return failSelector(nativeReason, false)
            end
        elseif selectorState.finalizerCompleted ~= true then
            return failSelector("sale_native_result_uncertain", false)
        end
        identityOk, identityReason = self:IsSaleIdentityCurrent(target, saleSnapshot)
        if not identityOk then
            return failSelector(identityReason or "sale_identity_changed", false)
        end
    end

    selectorState.completed = true
    selectorState.retryable = false
    selectorState.terminal = false
    selectorState.reason = nil
    selectorState.phase = "selector_ready"
    Logger:Info("SovereignInventory", string.format(
        "%s sale phase=selector_ready item=%d stat=%d service=%d",
        tostring(target.name), item, missionStat, selectionService
    ))
    return true, nil, selectorState
end

function SovereignBusinessInventory:SubmitSaleReservation(target, saleSnapshot)
    local spec = self:GetSaleTransactionSpec(target)
    if not spec then return false, "invalid_sale", false end
    if type(saleSnapshot) ~= "table" then
        return false, "sale_identity_changed", false
    end
    local function saleIdentityGuard()
        return self:IsSaleIdentityCurrent(target, saleSnapshot)
    end
    local function saleDispatchGuard()
        local identityOk, identityReason = saleIdentityGuard()
        if not identityOk then return false, identityReason end
        if self.transactionBusy
            or next(self.pendingRefillTransactions or {}) ~= nil
            or next(self.pendingSaleReservation or {}) ~= nil then
            return false, "transaction_busy"
        end
        if self:GetRunningSaleScript(self.saleMissionScripts) then
            return false, "sale_script_already_running"
        end
        if self:GetRunningSaleScript(self.saleAppScripts) then
            return false, "sale_app_running"
        end
        return true, nil
    end
    local saleService = spec.service
        or (target.key == "nightclub" and -1018905335 or -788753717)
    local category = self:NormalizeSignedInt32(
        Utils.Joaat("CATEGORY_INVENTORY_CONTRABAND_MISSION")
    )
    if category == nil or category == 0 then return false, "invalid_item", false end
    local descriptorF10 = tonumber(spec.descriptorF10)
    if type(descriptorF10) ~= "number" or descriptorF10 ~= descriptorF10
        or descriptorF10 == rawget(math, "huge") or descriptorF10 == -rawget(math, "huge") then
        descriptorF10 = 4
    else
        descriptorF10 = math.floor(descriptorF10)
    end

    -- func_2193 reverses the two hashes for recognized inventory categories
    -- when hParam8 is present: itemData[0]/f15 is the mission stat hash and
    -- itemData[1]/f16 is the catalog item. The server rejects the opposite
    -- tuple even though BASKET_ADD_ITEM itself can still return true.
    local function submitSaleTransaction(
        catalogHash, serviceHash, missionStatHash, itemDataF3, onAcceptedBeforeCleanup
    )
        local catalog = self:NormalizeSignedInt32(catalogHash)
        local missionStat = self:NormalizeSignedInt32(missionStatHash)
        if catalog == nil or catalog == 0 or missionStat == nil or missionStat == 0 then
            return false, "invalid_item", false
        end
        local accepted, reason, committed, cleanupContext = self:SubmitContrabandDelta(
            missionStat,
            1,
            nil,
            category,
            serviceHash,
            {
                checkout = false,
                debugLabel = "sale:" .. tostring(target.key),
                itemDataF1 = catalog,
                itemDataF2 = 0,
                itemDataF3 = itemDataF3 == nil and 1 or itemDataF3,
                descriptorF10 = descriptorF10,
                preDispatchGuard = saleDispatchGuard,
                onAcceptedBeforeCleanup = onAcceptedBeforeCleanup
            }
        )
        if not accepted then
            return false, reason, committed == true, cleanupContext
        end
        if cleanupContext then
            local settled, cleanupReason = self:EnsureFreemodeTransactionSettled(cleanupContext)
            if not settled then
                return false, cleanupReason or "transaction_cleanup_unconfirmed",
                    true, cleanupContext
            end
            if onAcceptedBeforeCleanup then
                local receipt = cleanupContext.acceptedReceipt
                if type(receipt) ~= "table" or receipt.callbackCompleted ~= true then
                    return false, type(receipt) == "table" and receipt.callbackReason
                        or "sale_settlement_state_lost", true
                end
            end
        end
        local identityOk, identityReason = saleIdentityGuard()
        if not identityOk then return false, identityReason, true end
        return true, nil, true
    end

    -- These paths have a freemode selector transaction followed by a native
    -- mission transaction. Never submit the final service before the mission
    -- owns the sale; doing so creates an empty/duplicate reservation and can
    -- leave the eventual sale without a matching payout.
    local needsSelection = spec.selectionService ~= nil
    local missionOwnsFinal = spec.missionOwnsFinal == true
    local selectionCommitted = false
    local selectorState = nil
    if needsSelection then
        selectorState = {
            selectorAccepted = false,
            phase = "selector_receipt_pending",
            retryable = true,
            terminal = false,
            startedAt = os.clock()
        }
        local onSelectorAccepted = nil
        if missionOwnsFinal and target.key == "warehouse" then
            onSelectorAccepted = function(receipt)
                selectorState.acceptedReceipt = receipt
                selectorState.selectorAccepted = true
                selectorState.phase = "selector_accepted"
                local completedOk, completed, completedReason = pcall(
                    self.CompleteAcceptedSaleSelector, self,
                    target, saleSnapshot, spec, selectorState
                )
                if not completedOk then
                    selectorState.reason = "transaction_runtime_exception"
                    selectorState.retryable = false
                    selectorState.terminal = true
                    return false, selectorState.reason
                end
                if completed ~= true then
                    selectorState.retryable = false
                    selectorState.terminal = true
                end
                return completed, completedReason
            end
        end
        local selectionAccepted, selectionReason, selectionWasCommitted, selectionCleanup =
            submitSaleTransaction(
            spec.item,
            spec.selectionService or -1018905335,
            spec.stat,
            spec.selectionItemDataF3,
            onSelectorAccepted
        )
        if not selectionAccepted then
            if type(selectionCleanup) == "table" and selectionWasCommitted then
                selectionCleanup.resumeSaleAfterSelector = true
                selectorState.selectorAccepted = selectionCleanup.serverAccepted == true
                if selectorState.completed ~= true and selectorState.terminal ~= true then
                    selectorState.phase = selectionCleanup.serverAccepted == true
                        and "selector_accepted_cleanup_pending"
                        or "selector_receipt_pending"
                end
            elseif selectionWasCommitted and onSelectorAccepted then
                selectorState.reason = selectorState.reason or selectionReason
                    or "sale_settlement_state_lost"
                selectorState.retryable = false
                selectorState.terminal = true
            end
            return false, selectionReason, selectionWasCommitted,
                selectionCleanup, selectorState
        end
        selectionCommitted = true
        selectorState.selectorAccepted = true
        selectorState.phase = selectorState.phase or "selector_accepted"
        local selectorReady, selectorReason
        selectorReady, selectorReason, selectorState =
            self:CompleteAcceptedSaleSelector(
            target, saleSnapshot, spec, selectorState
        )
        if not selectorReady then
            return false, selectorReason, true, nil, selectorState
        end
    end

    if needsSelection and missionOwnsFinal then
        return true, nil, true, nil, selectorState
    end

    local accepted, reason, committed, cleanupContext = submitSaleTransaction(
        spec.item,
        saleService,
        spec.stat,
        spec.itemDataF3
    )
    if not accepted then
        return false, reason, selectionCommitted or committed == true, cleanupContext
    end

    -- Non-MC/office targets retain their existing one-stage global update, but
    -- it still occurs only after the transaction has been accepted and the
    -- local descriptor has been settled.
    if not needsSelection and type(spec.resultGlobal) == "number" then
        if not self:WriteGlobalVerified(spec.resultGlobal, spec.item) then
            return false, "reservation_state_unavailable", true
        end
    end
    return true, nil, true
end

