function SovereignBusinessInventory:CheckSaleAccess(target)
    if type(target) ~= "table" then return false, "invalid_sale" end
    local organization = self:GetLocalOrganizationState()
    if organization.valid ~= true then
        return false, organization.error or "local_player_unavailable"
    end
    if target.key == "biker" then
        if organization.role ~= "mc_president" then
            local roleOk, roleOrReason = self:EnsureOrganizationRole("mc_president")
            if not roleOk then return false, roleOrReason end
        end
        return true
    end
    if target.key == "warehouse" then
        return self:CheckWarehouseAccess(
            math.floor(tonumber(target.warehouseIndex) or -1) + 1
        )
    end
    return false, "invalid_sale"
end

function SovereignBusinessInventory:GetSaleStockEvidence(
    target, expectedIdentity, readOptions
)
    if type(target) ~= "table" then return nil, "invalid_sale" end
    local characterSlot = type(expectedIdentity) == "table"
        and expectedIdentity.characterSlot or self:GetCharacterSlot()
    local playerId = type(expectedIdentity) == "table"
        and expectedIdentity.playerId or self:GetLocalPlayerId()
    characterSlot, playerId = tonumber(characterSlot), tonumber(playerId)
    if characterSlot == nil or (characterSlot ~= 0 and characterSlot ~= 1) then
        return nil, "character_slot_unavailable"
    end
    if playerId == nil or playerId < 0 or playerId > 31 then
        return nil, "local_player_unavailable"
    end
    characterSlot, playerId = math.floor(characterSlot), math.floor(playerId)
    local function identityCurrent()
        if self:GetCharacterSlot() ~= characterSlot
            or self:GetLocalPlayerId() ~= playerId then
            return false
        end
        if type(expectedIdentity) == "table"
            and expectedIdentity.organizationRole ~= nil then
            local organization = self:GetLocalOrganizationState()
            return organization.valid == true
                and organization.playerId == playerId
                and organization.bossId == expectedIdentity.organizationBossId
                and organization.role == expectedIdentity.organizationRole
        end
        return true
    end
    if not identityCurrent() then return nil, "sale_identity_changed" end
    local statIndex, specialStatIndex, runtimeGlobal, capacity, warehouseDefinition,
        businessToken
    if target.key == "biker" then
        local index = math.floor(tonumber(target.factoryIndex) or -1) + 1
        local definition = self.factoryDefinitions[index]
        if index < 1 or index > 5 or not definition then
            return nil, "invalid_sale"
        end
        statIndex = definition.product
        capacity = self:GetProductCapacity(definition)
        local propertyValues = self:ReadIndices(
            {definition.property}, characterSlot
        )
        businessToken = propertyValues and propertyValues[definition.property] or nil
        if type(businessToken) ~= "number" or businessToken == 0 then
            return nil, "business_not_owned"
        end
        local targetProperty = tonumber(target.property)
        if type(targetProperty) ~= "number"
            or math.floor(targetProperty) ~= math.floor(businessToken) then
            return nil, "sale_identity_changed"
        end
        runtimeGlobal = 1845347 + 1 + (playerId * 884)
            + 260 + 205 + 1 + ((index - 1) * 13) + 1
    elseif target.key == "warehouse" then
        local catalogOk = self:ValidateWarehouseCatalog()
        if not catalogOk then return nil, "warehouse_catalog_invalid" end
        local index = math.floor(tonumber(target.warehouseIndex) or -1) + 1
        local definition = self.warehouseDefinitions[index]
        if not definition then
            return nil, "warehouse_not_owned"
        end
        local warehouseType = self:ReadWarehouseType(definition, playerId)
        if warehouseType < 1 or warehouseType > 22 then
            return nil, "warehouse_not_owned"
        end
        statIndex = definition.productIndex
        specialStatIndex = definition.specialProductIndex
        runtimeGlobal = self:GetWarehouseRuntimeProductGlobal(
            definition.index, playerId
        )
        capacity = self:GetWarehouseCapacity(definition, playerId)
        warehouseDefinition = definition
        businessToken = warehouseType
        local targetWarehouseType = tonumber(target.warehouseType)
        if warehouseType < 1 or warehouseType > 22
            or (targetWarehouseType and math.floor(targetWarehouseType) ~= warehouseType) then
            return nil, "sale_stock_inconsistent"
        end
    else
        return nil, "invalid_sale"
    end
    if not runtimeGlobal or type(capacity) ~= "number" or capacity <= 0 then
        return nil, "sale_stock_unavailable"
    end
    capacity = math.floor(capacity)
    local statIndices = {statIndex}
    if specialStatIndex then statIndices[#statIndices + 1] = specialStatIndex end
    local stableStock, stableStockReason = self:ReadStableSaleStock(
        statIndices, statIndex, specialStatIndex, characterSlot, runtimeGlobal,
        capacity, identityCurrent, readOptions
    )
    if not stableStock then return nil, stableStockReason end
    local persistent = stableStock.persistent
    local live = stableStock.live
    local specialPersistent = stableStock.specialPersistent
    local packingConfirmed = target.key ~= "warehouse"
    if warehouseDefinition then
        local packingReason
        packingConfirmed, packingReason = self:WaitForStableWarehousePacking(
            warehouseDefinition, persistent, characterSlot, playerId,
            identityCurrent, {
                attempts = readOptions and readOptions.packingAttempts or 6,
                sampleDelay = readOptions and readOptions.packingDelay or 125
            }
        )
        if not packingConfirmed then
            return nil, packingReason or "warehouse_packing_inconsistent"
        end
    end
    if type(expectedIdentity) == "table" and expectedIdentity.businessToken ~= nil
        and math.floor(tonumber(expectedIdentity.businessToken) or -1)
            ~= math.floor(tonumber(businessToken) or -2) then
        return nil, "sale_identity_changed"
    end
    if not identityCurrent() then return nil, "sale_identity_changed" end
    return {
        persistent = persistent,
        live = live,
        specialPersistent = specialPersistent,
        capacity = capacity,
        statIndex = statIndex,
        specialStatIndex = specialStatIndex,
        runtimeGlobal = runtimeGlobal,
        packingConfirmed = packingConfirmed,
        businessToken = math.floor(businessToken)
    }, nil
end

function SovereignBusinessInventory:IsSaleIdentityCurrent(target, snapshot)
    if type(target) ~= "table" or type(snapshot) ~= "table" then
        return false, "sale_identity_changed"
    end
    local characterSlot = self:GetCharacterSlot()
    local organization = self:GetLocalOrganizationState()
    if characterSlot ~= snapshot.characterSlot or organization.valid ~= true
        or organization.playerId ~= snapshot.playerId
        or organization.bossId ~= snapshot.organizationBossId
        or organization.role ~= snapshot.organizationRole then
        return false, "sale_identity_changed"
    end
    if target.key == "biker" then
        if organization.role ~= "mc_president" then
            return false, "mc_president_required"
        end
        local index = math.floor(tonumber(target.factoryIndex) or -1) + 1
        local definition = self.factoryDefinitions[index]
        local values = definition and self:ReadIndices(
            {definition.property}, snapshot.characterSlot
        ) or nil
        local businessToken = definition and values and values[definition.property] or nil
        if type(businessToken) ~= "number" or math.floor(businessToken) ~= snapshot.businessToken
            or math.floor(tonumber(target.property) or -1) ~= snapshot.businessToken then
            return false, "sale_identity_changed"
        end
        return true, nil
    end
    if target.key == "warehouse" then
        if organization.role ~= "ceo" then return false, "ceo_required" end
        local index = math.floor(tonumber(target.warehouseIndex) or -1) + 1
        local definition = self.warehouseDefinitions[index]
        local businessToken = definition and self:ReadWarehouseType(
            definition, snapshot.playerId
        ) or nil
        if type(businessToken) ~= "number" or math.floor(businessToken) ~= snapshot.businessToken
            or math.floor(tonumber(target.warehouseType) or -1) ~= snapshot.businessToken then
            return false, "sale_identity_changed"
        end
        return true, nil
    end
    return false, "invalid_sale"
end

function SovereignBusinessInventory:GetWarehouseSaleSelection(target, totalStock, specialStock)
    local index = math.floor(tonumber(target and target.warehouseIndex) or -1) + 1
    local definition = self.warehouseDefinitions[index]
    if not definition then return nil, "invalid_sale" end
    local special = self:NormalizeStockValue(specialStock, totalStock)
    if special == nil then
        local values = self:ReadIndices({definition.specialProductIndex})
        special = self:NormalizeStockValue(
            values and values[definition.specialProductIndex], totalStock
        )
    end
    if special == nil then return nil, "sale_stock_unavailable" end
    if special > 0 then
        return {saleType = 4, count = special, special = special}, nil
    end
    local normal = totalStock - special
    local percent = tonumber(self:ReadGlobal(262145 + 16688))
    if type(percent) ~= "number" or percent <= 0 or percent > 100 then
        return nil, "sale_stock_unavailable"
    end
    local count = math.floor((normal * percent / 100) + 0.5)
    if count <= 0 or count > normal then return nil, "no_stock" end
    return {saleType = 3, count = count, special = special}, nil
end

function SovereignBusinessInventory:GetMoneySnapshot(expectedIdentity)
    if not menu.nativeApis.MONEY or type(menu.nativeApis.MONEY.NETWORK_GET_VC_BANK_BALANCE) ~= "function"
        or type(menu.nativeApis.MONEY.NETWORK_GET_VC_WALLET_BALANCE) ~= "function" then
        return nil, "sale_money_unavailable"
    end
    local expectedSlot = type(expectedIdentity) == "table"
        and expectedIdentity.characterSlot or self:GetCharacterSlot()
    local expectedPlayerId = type(expectedIdentity) == "table"
        and expectedIdentity.playerId or self:GetLocalPlayerId()
    if expectedSlot == nil then return nil, "character_slot_unavailable" end
    if expectedPlayerId == nil then return nil, "local_player_unavailable" end
    local function identityCurrent()
        return self:GetCharacterSlot() == expectedSlot
            and self:GetLocalPlayerId() == expectedPlayerId
    end
    if not identityCurrent() then return nil, "sale_identity_changed" end
    for _ = 1, 3 do
        local bankOk, bank = pcall(menu.nativeApis.MONEY.NETWORK_GET_VC_BANK_BALANCE)
        local walletOk, wallet = pcall(menu.nativeApis.MONEY.NETWORK_GET_VC_WALLET_BALANCE, -1)
        local bankAgainOk, bankAgain = pcall(menu.nativeApis.MONEY.NETWORK_GET_VC_BANK_BALANCE)
        local walletAgainOk, walletAgain = pcall(menu.nativeApis.MONEY.NETWORK_GET_VC_WALLET_BALANCE, -1)
        if not identityCurrent() then return nil, "sale_identity_changed" end
        if bankOk and walletOk and bankAgainOk and walletAgainOk
            and type(bank) == "number" and type(wallet) == "number"
            and bank == bank and wallet == wallet
            and bank >= 0 and bank < rawget(math, "huge")
            and wallet >= 0 and wallet < rawget(math, "huge")
            and bank == bankAgain and wallet == walletAgain then
            bank, wallet = math.floor(bank), math.floor(wallet)
            return {bank = bank, wallet = wallet, total = bank + wallet}, nil
        end
    end
    return nil, "sale_money_unavailable"
end

function SovereignBusinessInventory:ReadSalePayoutMetadata(bossId)
    bossId = tonumber(bossId)
    if bossId == nil then return nil, "sale_income_identity_unavailable" end
    bossId = math.floor(bossId)
    if bossId < 0 or bossId > 31 then
        return nil, "sale_income_identity_unavailable"
    end
    -- freemode addresses f_10.f_9[0] and f_10.f_9[1] directly.  There is no
    -- Lua-visible array-length slot between f_9 and its first element.  The
    -- previous +1 read f_10.f_10/f_11 and made every valid organization look
    -- like it had no payout identity.
    local base = 1893070 + 1 + (bossId * 615) + 10 + 9
    local metadataF6, metadataF7
    local stableCount = 0
    local previousF6, previousF7 = nil, nil
    for attempt = 1, 4 do
        local currentF6 = self:ReadGlobal(base)
        local currentF7 = self:ReadGlobal(base + 1)
        if type(currentF6) == "number" and currentF6 == currentF6
            and type(currentF7) == "number" and currentF7 == currentF7 then
            currentF6, currentF7 = math.floor(currentF6), math.floor(currentF7)
            if currentF6 == previousF6 and currentF7 == previousF7 then
                stableCount = stableCount + 1
            else
                previousF6, previousF7 = currentF6, currentF7
                stableCount = 1
            end
            if stableCount >= 2 then
                metadataF6, metadataF7 = currentF6, currentF7
                break
            end
        else
            previousF6, previousF7, stableCount = nil, nil, 0
        end
        if attempt < 4 and Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, 25)
        end
    end
    if metadataF6 == nil or metadataF7 == nil then
        return nil, "sale_income_identity_unavailable"
    end
    -- An all-zero pair cannot distinguish one organization from another.
    if metadataF6 == 0 and metadataF7 == 0 then
        return nil, "sale_income_identity_unavailable"
    end
    return {
        f6 = metadataF6,
        f7 = metadataF7
    }, nil
end

function SovereignBusinessInventory:ReadSaleIncomeTransactionSlot(slot)
    local normalizedSlot = math.floor(tonumber(slot) or -1)
    if normalizedSlot < 0 or normalizedSlot > 14 then return nil end
    local entryBase = 4515492 + 1 + (normalizedSlot * 84)
    local descriptorBase = entryBase + 65
    local function retryYield()
        if Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, 25)
        end
    end
    local function readOnce()
        local transactionBefore = self:ReadGlobal(descriptorBase)
        local frameBefore = self:ReadGlobal(descriptorBase + 14)
        local stateBefore = self:ReadGlobal(descriptorBase + 2)
        if type(transactionBefore) ~= "number" or transactionBefore ~= transactionBefore
            or type(frameBefore) ~= "number" or frameBefore ~= frameBefore
            or type(stateBefore) ~= "number" or stateBefore ~= stateBefore then
            return nil
        end
        transactionBefore = math.floor(transactionBefore)
        frameBefore = math.floor(frameBefore)
        stateBefore = math.floor(stateBefore)
        local values = {
            [0] = transactionBefore,
            [2] = stateBefore,
            [14] = frameBefore
        }
        local readable = true
        local metadataF6, metadataF7
        if stateBefore ~= 0 then
            for _, offset in ipairs({1, 3, 4, 5, 6, 7, 13, 15, 16}) do
                local value = self:ReadGlobal(descriptorBase + offset)
                if type(value) ~= "number" or value ~= value then
                    readable = false
                    break
                end
                values[offset] = math.floor(value)
            end
            metadataF6 = self:ReadGlobal(entryBase + 6)
            metadataF7 = self:ReadGlobal(entryBase + 7)
            if type(metadataF6) ~= "number" or metadataF6 ~= metadataF6
                or type(metadataF7) ~= "number" or metadataF7 ~= metadataF7 then
                readable = false
            else
                metadataF6 = math.floor(metadataF6)
                metadataF7 = math.floor(metadataF7)
            end
        end
        -- The descriptor is shared with the network script. Read every
        -- attribution field twice so a slot changing between reads is never
        -- reported as a payout for this sale.
        local nestedAfter = {}
        local nestedStable = true
        if stateBefore ~= 0 then
            for _, offset in ipairs({1, 3, 4, 5, 6, 7, 13, 15, 16}) do
                local value = self:ReadGlobal(descriptorBase + offset)
                if type(value) ~= "number" or value ~= value then
                    nestedStable = false
                    break
                end
                nestedAfter[offset] = math.floor(value)
            end
            if nestedStable then
                for _, offset in ipairs({1, 3, 4, 5, 6, 7, 13, 15, 16}) do
                    if nestedAfter[offset] ~= values[offset] then
                        nestedStable = false
                        break
                    end
                end
            end
        end
        local stateAfter = self:ReadGlobal(descriptorBase + 2)
        local transactionAfter = self:ReadGlobal(descriptorBase)
        local frameAfter = self:ReadGlobal(descriptorBase + 14)
        local metadataF6After = stateBefore ~= 0 and self:ReadGlobal(entryBase + 6) or nil
        local metadataF7After = stateBefore ~= 0 and self:ReadGlobal(entryBase + 7) or nil
        if readable and nestedStable and type(stateAfter) == "number" and stateAfter == stateAfter
            and type(transactionAfter) == "number" and transactionAfter == transactionAfter
            and type(frameAfter) == "number" and frameAfter == frameAfter
            and math.floor(stateAfter) == stateBefore
            and math.floor(transactionAfter) == transactionBefore
            and math.floor(frameAfter) == frameBefore
            and (stateBefore == 0
                or (type(metadataF6After) == "number"
                    and metadataF6After == metadataF6After
                    and type(metadataF7After) == "number"
                    and metadataF7After == metadataF7After
                    and math.floor(metadataF6After) == metadataF6
                    and math.floor(metadataF7After) == metadataF7)) then
            if stateBefore == 0 then
                return {
                    slot = normalizedSlot,
                    transactionId = transactionBefore,
                    state = 0,
                    createdFrame = frameBefore
                }
            end
            return {
                slot = normalizedSlot,
                transactionId = values[0],
                amount = values[1],
                state = values[2],
                transactionType = values[3],
                service = values[4],
                ownsBasket = values[5],
                -- Outer metadata is diagnostic only for owner baskets.
                metadataF6 = metadataF6,
                metadataF7 = metadataF7,
                category = values[6],
                action = values[7],
                checkoutStarted = values[13],
                incomeItem = values[15],
                incomeStat = values[16],
                createdFrame = values[14]
            }
        end
        return nil
    end
    for attempt = 1, 3 do
        local entry = readOnce()
        if entry then return entry end
        if attempt < 3 then retryYield() end
    end
    return nil
end

function SovereignBusinessInventory:SnapshotSaleIncomeTransactions()
    if not menu.nativeApis.NETSHOPPING
        or type(menu.nativeApis.NETSHOPPING.NET_GAMESERVER_USE_SERVER_TRANSACTIONS) ~= "function" then
        return nil, "sale_income_transaction_unavailable"
    end
    local modeOk, useTransactions = pcall(
        menu.nativeApis.NETSHOPPING.NET_GAMESERVER_USE_SERVER_TRANSACTIONS
    )
    if not modeOk or useTransactions ~= true then
        return nil, "sale_income_transaction_unavailable"
    end
    local function retryYield()
        if Script and type(Script.Yield) == "function" then
            pcall(Script.Yield, 25)
        end
    end
    for groupAttempt = 1, 3 do
        local snapshot = {}
        local failed = false
        for slot = 0, 14 do
            local entry = self:ReadSaleIncomeTransactionSlot(slot)
            if not entry then
                failed = true
                break
            end
            snapshot[slot + 1] = entry
        end
        if not failed then return snapshot, nil end
        if groupAttempt < 3 then retryYield() end
    end
    return nil, "sale_income_state_unavailable"
end

function SovereignBusinessInventory:GetSaleIncomeSpec(target)
    if type(target) ~= "table" or not Utils
        or type(Utils.Joaat) ~= "function" then return nil end
    local index, itemName, statPrefix
    if target.key == "warehouse" then
        index = tonumber(target.warehouseIndex)
        itemName = "CF_MISSION_PASSED"
        statPrefix = "MP_STAT_CONTOTALFORWHOUSE"
    elseif target.key == "biker" then
        index = tonumber(target.factoryIndex)
        itemName = "CF_MISSION_PASSED_BKR"
        statPrefix = "MP_STAT_PRODTOTALFORFACTORY"
    else
        return nil
    end
    if not index or index ~= index or index < 0 or index > 4
        or index ~= math.floor(index) then return nil end
    index = math.floor(index)
    return {
        incomeItem = self:NormalizeSignedInt32(Utils.Joaat(itemName)),
        incomeStat = self:NormalizeSignedInt32(
            Utils.Joaat(statPrefix .. tostring(index) .. "_v0")
        )
    }
end

function SovereignBusinessInventory:IsSaleIncomeBasket(entry)
    if type(entry) ~= "table" or not Utils or type(Utils.Joaat) ~= "function" then
        return false
    end
    local function signed32(value)
        local normalized = math.floor(tonumber(value) or 0) & 0xFFFFFFFF
        return normalized >= 0x80000000 and (normalized - 0x100000000) or normalized
    end
    local state = math.floor(tonumber(entry.state) or 0)
    return entry.transactionId ~= 2147483647
        and type(entry.amount) == "number" and entry.amount > 0
        and (state == 1 or state == 2 or state == 3)
        -- Owner payouts finish the inventory basket with a passed flag item.
        -- SERVICE_EARN_BOSS_AGENCY belongs to associates, not CEO/MC owners.
        and signed32(entry.transactionType) == 78225582
        and signed32(entry.service) == signed32(Utils.Joaat("SERVICE_INVALID"))
        and entry.ownsBasket == 1 and entry.checkoutStarted == 1
        and signed32(entry.category)
            == signed32(Utils.Joaat("CATEGORY_INVENTORY_CONTRABAND_MISSION"))
        and signed32(entry.action) == -788753717
        and (signed32(entry.incomeItem) == signed32(Utils.Joaat("CF_MISSION_PASSED"))
            or signed32(entry.incomeItem)
                == signed32(Utils.Joaat("CF_MISSION_PASSED_BKR")))
end

function SovereignBusinessInventory:IsSaleIncomeTransaction(entry, expectedSnapshot)
    if not self:IsSaleIncomeBasket(entry)
        or type(expectedSnapshot) ~= "table"
        or type(expectedSnapshot.incomeItem) ~= "number"
        or type(expectedSnapshot.incomeStat) ~= "number" then return false end
    return self:NormalizeSignedInt32(entry.incomeItem) == expectedSnapshot.incomeItem
        and self:NormalizeSignedInt32(entry.incomeStat) == expectedSnapshot.incomeStat
end

function SovereignBusinessInventory:ObserveSaleIncomeTransactions(beforeSnapshot, monitor)
    if type(beforeSnapshot) ~= "table"
        or type(beforeSnapshot.incomeTransactions) ~= "table"
        or type(monitor) ~= "table" then
        return false, "sale_income_state_unavailable"
    end
    if type(beforeSnapshot.incomeItem) ~= "number"
        or type(beforeSnapshot.incomeStat) ~= "number" then
        return false, "sale_income_identity_unavailable"
    end
    local current, reason = self:SnapshotSaleIncomeTransactions()
    if not current then
        monitor.lastIncomeReadError = reason
        return false, reason
    end
    monitor.lastIncomeReadError = nil
    local now = os.clock()
    local missionWindowOpen = monitor.missionObserved == true
        and monitor.reservationAccepted == true
        and monitor.dispatchSent == true and monitor.missionStarted == true
        and monitor.missionGenerationChanged ~= true
        and type(monitor.missionStartFrame) == "number"
        and (monitor.missionActive == true
            or (monitor.missionEnded == true
                and type(monitor.missionSettlementGraceUntil) == "number"
                and now <= monitor.missionSettlementGraceUntil)
            or (monitor.missionEnded ~= true
                and type(monitor.missionLastSeenAt) == "number"
                and now - monitor.missionLastSeenAt <= 10.0))
    for slot = 0, 14 do
        local entry = current[slot + 1]
        local baseline = beforeSnapshot.incomeTransactions[slot + 1]
        local candidateInMissionWindow = entry
            and type(entry.createdFrame) == "number"
            and type(monitor.missionStartFrame) == "number"
            and entry.createdFrame >= monitor.missionStartFrame
            and missionWindowOpen
        local basketCandidate = entry and self:IsSaleIncomeBasket(entry)
        local generationChanged = entry ~= nil and (not baseline
            or baseline.state == 0
            or entry.transactionId ~= baseline.transactionId
            or entry.createdFrame ~= baseline.createdFrame)
        local matchingIncome = basketCandidate
            and self:IsSaleIncomeTransaction(entry, beforeSnapshot)
        local newGeneration = matchingIncome and generationChanged
            and missionWindowOpen
            and candidateInMissionWindow
        local generation = entry and (tostring(slot) .. ":"
            .. tostring(entry.transactionId) .. ":" .. tostring(entry.createdFrame)) or nil
        local alreadyTracked = generation ~= nil
            and matchingIncome
            and type(monitor.incomeCandidates) == "table"
            and monitor.incomeCandidates[generation] ~= nil
            and candidateInMissionWindow
        local candidateEligible = (newGeneration or alreadyTracked)
            and candidateInMissionWindow
        if basketCandidate and generation ~= nil and generationChanged
            and missionWindowOpen and candidateInMissionWindow and entry.state == 2
            and not matchingIncome then
            -- A payout for another warehouse/factory cannot explain this sale.
            monitor.incomeIdentityMismatches = monitor.incomeIdentityMismatches or {}
            if not monitor.incomeIdentityMismatches[generation] then
                monitor.incomeIdentityMismatches[generation] = true
                monitor.incomeIdentityMismatch = true
            end
        end
        if candidateEligible then
            monitor.incomeCandidates = monitor.incomeCandidates or {}
            monitor.incomeCandidates[generation] = {
                slot = entry.slot,
                transactionId = entry.transactionId,
                amount = entry.amount,
                state = entry.state,
                transactionType = entry.transactionType,
                service = entry.service,
                ownsBasket = entry.ownsBasket,
                checkoutStarted = entry.checkoutStarted,
                incomeItem = self:NormalizeSignedInt32(entry.incomeItem),
                incomeStat = self:NormalizeSignedInt32(entry.incomeStat),
                metadataF6 = entry.metadataF6,
                metadataF7 = entry.metadataF7,
                category = entry.category,
                action = entry.action,
                createdFrame = entry.createdFrame,
                observedAt = now,
                missionScript = monitor.missionScript,
                activityId = beforeSnapshot.activityId,
                businessToken = beforeSnapshot.businessToken
            }
            if entry.state == 2 then
                monitor.acceptedIncomeCandidates = monitor.acceptedIncomeCandidates or {}
                if monitor.acceptedIncomeCandidates[generation] == nil then
                    monitor.lastNewAcceptedIncomeAt = now
                end
                monitor.acceptedIncomeCandidates[generation] = monitor.incomeCandidates[generation]
                monitor.incomeAcceptedAt = now
            elseif entry.state == 3 then
                if type(monitor.acceptedIncomeCandidates) == "table" then
                    monitor.acceptedIncomeCandidates[generation] = nil
                end
                monitor.incomeTransactionRejected = true
            end
        end
    end
    return next(monitor.acceptedIncomeCandidates or {}) ~= nil, nil
end

function SovereignBusinessInventory:GetSalePreflightSnapshot(target, requireMoney)
    if type(target) ~= "table" then return nil, "invalid_sale" end
    local organization = self:GetLocalOrganizationState()
    if organization.valid ~= true then
        return nil, organization.error or "local_player_unavailable"
    end
    local characterSlot = self:GetCharacterSlot()
    if characterSlot == nil then return nil, "character_slot_unavailable" end
    local expectedRole
    if target.key == "warehouse" then
        if organization.role ~= "ceo" then
            local roleOk, roleOrReason = self:EnsureOrganizationRole("ceo")
            if not roleOk then return nil, roleOrReason end
            organization = roleOrReason
        end
        expectedRole = "ceo"
    elseif target.key == "biker" then
        if organization.role ~= "mc_president" then
            local roleOk, roleOrReason = self:EnsureOrganizationRole("mc_president")
            if not roleOk then return nil, roleOrReason end
            organization = roleOrReason
        end
        expectedRole = "mc_president"
    else
        return nil, "invalid_sale"
    end
    local identitySeed = {
        characterSlot = characterSlot,
        playerId = organization.playerId,
        organizationBossId = organization.bossId,
        organizationRole = expectedRole
    }
    local stock, stockReason = self:GetSaleStockEvidence(target, identitySeed, {
        requireEqual = true
    })
    if not stock then return nil, stockReason end
    if stock.persistent ~= stock.live then return nil, "sale_stock_inconsistent" end
    if stock.persistent <= 0 then return nil, "no_stock" end
    stock.characterSlot = characterSlot
    stock.playerId = organization.playerId
    stock.organizationBossId = organization.bossId
    stock.organizationRole = expectedRole
    if target.key == "warehouse" then
        local selection, selectionReason = self:GetWarehouseSaleSelection(
            target, stock.persistent, stock.specialPersistent
        )
        if not selection then return nil, selectionReason end
        stock.saleType = selection.saleType
        stock.saleCount = selection.count
        stock.specialCount = selection.special
        stock.activityId = 168
    elseif target.key == "biker" then
        -- A biker sell reservation covers the complete product inventory.
        stock.saleCount = stock.persistent
        stock.activityId = 190
    end
    local identityOk, identityReason = self:IsSaleIdentityCurrent(target, stock)
    if not identityOk then return nil, identityReason end
    if requireMoney then
        local incomeSpec = self:GetSaleIncomeSpec(target)
        if not incomeSpec then return nil, "sale_income_identity_unavailable" end
        stock.incomeItem = incomeSpec.incomeItem
        stock.incomeStat = incomeSpec.incomeStat
        local payoutMetadata, payoutMetadataReason = self:ReadSalePayoutMetadata(
            organization.bossId
        )
        if not payoutMetadata then return nil, payoutMetadataReason end
        local preflightFrame = self:GetCurrentGameFrame()
        if type(preflightFrame) ~= "number" then
            return nil, "sale_mission_evidence_unavailable"
        end
        local money, moneyReason = self:GetMoneySnapshot(stock)
        if not money then return nil, moneyReason end
        local incomeTransactions, incomeReason = self:SnapshotSaleIncomeTransactions()
        if not incomeTransactions then return nil, incomeReason end
        identityOk, identityReason = self:IsSaleIdentityCurrent(target, stock)
        if not identityOk then return nil, identityReason end
        local currentPayoutMetadata, currentMetadataReason =
            self:ReadSalePayoutMetadata(organization.bossId)
        if not currentPayoutMetadata then return nil, currentMetadataReason end
        if currentPayoutMetadata.f6 ~= payoutMetadata.f6
            or currentPayoutMetadata.f7 ~= payoutMetadata.f7 then
            return nil, "sale_income_identity_changed"
        end
        for _, entry in ipairs(incomeTransactions) do
            local entryState = type(entry) == "table"
                and math.floor(tonumber(entry.state) or 0) or 0
            if entryState ~= 0 and self:IsSaleIncomeTransaction(entry, stock) then
                -- Do not reuse a pre-existing payout descriptor. A
                -- state=1/2 entry can complete without changing its id/frame,
                -- which would otherwise evade generationChanged below.
                return nil, "sale_income_state_busy"
            end
        end
        stock.money = money
        stock.incomeTransactions = incomeTransactions
        stock.payoutMetadataF6 = payoutMetadata.f6
        stock.payoutMetadataF7 = payoutMetadata.f7
        stock.preflightFrame = preflightFrame
    end
    return stock, nil
end

function SovereignBusinessInventory:GetLocalPlayerId()
    if GTA and type(GTA.GetLocalPlayerId) == "function" then
        local ok, value = pcall(GTA.GetLocalPlayerId)
        if ok and type(value) == "number" and value == value then
            value = math.floor(value)
            if value >= 0 and value <= 31 then return value end
        end
    end
    local nativeApis = type(menu) == "table" and type(menu.nativeApis) == "table"
        and menu.nativeApis or nil
    if nativeApis and nativeApis.PLAYER
        and type(nativeApis.PLAYER.PLAYER_ID) == "function" then
        local ok, value = pcall(nativeApis.PLAYER.PLAYER_ID)
        if ok and type(value) == "number" and value == value then
            value = math.floor(value)
            if value >= 0 and value <= 31 then return value end
        end
    end
    return nil
end

function SovereignBusinessInventory:GetActivePlayerBits(localPlayerId)
    local bits = 0
    local nativeApis = type(menu) == "table" and type(menu.nativeApis) == "table"
        and menu.nativeApis or nil
    if nativeApis and nativeApis.NETWORK
        and type(nativeApis.NETWORK.NETWORK_IS_PLAYER_ACTIVE) == "function" then
        for playerId = 0, 31 do
            local ok, active = pcall(nativeApis.NETWORK.NETWORK_IS_PLAYER_ACTIVE, playerId)
            if ok and active then bits = bits | (1 << playerId) end
        end
    end
    local normalized = tonumber(localPlayerId)
    if type(normalized) ~= "number" or normalized ~= math.floor(normalized)
        or normalized < 0 or normalized > 31 then return bits end
    if bits == 0 then bits = 1 << normalized end
    return bits
end

function SovereignBusinessInventory:GetNightclubSaleValues()
    local priceOffsets = {24061, 24055, 24056, 24057, 24058, 24059, 24060}
    local total, gross, restrictedGross = 0, 0, 0
    for index, entry in ipairs(self.data.nightclub or {}) do
        local count = math.max(0, math.floor(tonumber(entry.value) or 0))
        local rawPrice = self:ReadGlobal(262145 + priceOffsets[index])
        if type(rawPrice) ~= "number" or rawPrice <= 0 then
            return nil, nil, nil, "sale_context_read_failed"
        end
        local unitPrice = math.floor(rawPrice)
        total = total + count
        gross = gross + (count * unitPrice)
        if index >= 3 then restrictedGross = restrictedGross + (count * unitPrice) end
    end
    return total, gross, restrictedGross
end

function SovereignBusinessInventory:ConfigureSaleContext(target, saleSnapshot)
    if type(saleSnapshot) ~= "table" then
        return nil, nil, "sale_identity_changed"
    end
    local playerId = tonumber(saleSnapshot.playerId)
    if playerId == nil then return nil, nil, "local_player_unavailable" end
    playerId = math.floor(playerId)
    local function identityCurrent()
        return self:IsSaleIdentityCurrent(target, saleSnapshot)
    end
    local initialIdentity, initialIdentityReason = identityCurrent()
    if not initialIdentity then
        return nil, nil, initialIdentityReason or "sale_identity_changed"
    end
    local playerRoot = 1893070 + 1 + (playerId * 615)
    local organization = playerRoot + 10
    local broadcast = 1845347 + 1 + (playerId * 884)
    local missionId, missionParam = nil, -1
    local writesOk = true
    local identityWriteFailure = nil
    local function put(index, value)
        -- Do not continue producing a mixed context after one failed write.
        if not writesOk or identityWriteFailure then return false end
        local identityOk, identityReason = identityCurrent()
        if not identityOk then
            writesOk = false
            identityWriteFailure = identityReason or "sale_identity_changed"
            return false
        end
        writesOk = self:WriteGlobalVerified(index, value)
        return writesOk
    end

    if target.key == "biker" then
        -- f_33 stores business type 190. freemode maps it through
        -- func_10378 to script id 91 (GB_BIKER_CONTRABAND_SELL).
        missionId = 190
        missionParam = math.floor(tonumber(saleSnapshot and saleSnapshot.businessToken) or -1)
        local factoryIndex = math.floor(tonumber(target.factoryIndex) or -1)
        local remoteTuneable = self:ReadGlobal(262145 + 17440)
        if missionParam <= 0 or factoryIndex < 0 or factoryIndex > 4
            or math.floor(tonumber(target.property) or -1) ~= missionParam then
            return nil, nil, "sale_stock_inconsistent"
        end
        if type(remoteTuneable) ~= "number" then
            return nil, nil, "sale_context_read_failed"
        end
        local saleType = self.bikerSaleDistant and 1 or 0
        local remoteFlag = remoteTuneable == 0 and 1 or 0
        put(organization + 195, missionParam)
        put(organization + 196, saleType)
        put(broadcast + 260 + 205 + 1 + (factoryIndex * 13) + 6, remoteFlag)
        put(1948675 + 53, 0)
        put(1951071, 1)
    elseif target.key == "bunker" then
        -- Business type 226 maps to script id 108 (bunker sale). Type 225
        -- maps to script id 107 and starts the bunker resupply path.
        missionId = 226
        put(organization + 216, 0)
        put(1948794 + 43, 0)
        put(1951071, 1)
    elseif target.key == "nightclub" then
        -- Activity 91 maps to GB_BIKER_CONTRABAND_SELL on Enhanced.
        -- 237 maps to an unrelated activity and is rejected at launch time.
        missionId = 91
        local total, gross, restrictedGross, valueReason = self:GetNightclubSaleValues()
        if not total then return nil, nil, valueReason end
        if total <= 0 then return nil, nil, "no_stock" end
        local saleData = broadcast + 870
        local values = {-1, total, gross, gross, 0, 0, restrictedGross, 0}
        for offset, value in ipairs(values) do
            put(saleData + offset - 1, value)
        end
        put(1951218 + 4034, 5)
    elseif target.key == "hangar" then
        -- 315 launches smuggler sale; 316 is the smuggler resupply content.
        -- Land/air sale selection is carried by the reserved transaction item.
        missionId = 315
        local saleFlags = self:ReadGlobal(1990065)
        if type(saleFlags) ~= "number" then
            return nil, nil, "sale_context_read_failed"
        end
        put(organization + 238, 0)
        put(organization + 238 + 22, 8)
        put(1948841 + 53, 0)
        put(1990065, math.floor(saleFlags) | (1 << 18))
        put(1951071, 1)
    elseif target.key == "warehouse" then
        local index = math.floor(tonumber(target.warehouseIndex) or -1) + 1
        local definition = self.warehouseDefinitions[index]
        local currentWarehouseType = definition and self:ReadWarehouseType(
            definition, playerId
        ) or 0
        local warehouseType = math.floor(
            tonumber(saleSnapshot and saleSnapshot.businessToken) or 0
        )
        local saleCount = math.floor(tonumber(saleSnapshot and saleSnapshot.saleCount) or 0)
        local saleType = math.floor(tonumber(saleSnapshot and saleSnapshot.saleType) or 0)
        local officeFlags = self:ReadGlobal(1951218 + 4)
        if warehouseType < 1 or warehouseType > 22
            or currentWarehouseType ~= warehouseType
            or math.floor(tonumber(target.warehouseType) or -1) ~= warehouseType
            or saleCount <= 0
            or (saleType ~= 3 and saleType ~= 4) then
            return nil, nil, "sale_stock_inconsistent"
        end
        if type(officeFlags) ~= "number" then
            return nil, nil, "sale_context_read_failed"
        end
        -- appsecuroserv dispatches activity 168 with the physical warehouse
        -- type. Freemode maps that activity to GB_CONTRABAND_SELL (script 67).
        missionId = 168
        missionParam = warehouseType
        put(organization + 184, warehouseType)
        put(organization + 185, -1)
        put(organization + 186, -1)
        put(organization + 187, 0)
        put(77420, 1)
        put(1951218 + 4, math.floor(officeFlags) & (~(1 << 4)))
        put(1951061, saleCount)
        put(1951063, saleType)
        put(1951071, 1)
    else
        return nil, nil, "invalid_sale"
    end
    put(organization + 33, missionId)
    if identityWriteFailure then return nil, nil, identityWriteFailure end
    if not writesOk then return nil, nil, "sale_context_write_failed" end
    local finalIdentity, finalIdentityReason = identityCurrent()
    if not finalIdentity then
        return nil, nil, finalIdentityReason or "sale_identity_changed"
    end
    return missionId, missionParam, nil
end

function SovereignBusinessInventory:DispatchSaleMission(
    missionId, missionParam, preDispatchGuard
)
    local function checkGuard(expectedPlayerId)
        if expectedPlayerId ~= nil
            and self:GetLocalPlayerId() ~= expectedPlayerId then
            return false, "sale_identity_changed"
        end
        if type(preDispatchGuard) ~= "function" then return true, nil end
        local ok, allowed, reason = pcall(preDispatchGuard)
        if not ok or allowed ~= true then
            return false, tostring(reason or "transaction_guard_failed")
        end
        return true, nil
    end
    local initialGuardOk, initialGuardReason = checkGuard()
    if not initialGuardOk then return false, false, initialGuardReason end
    local playerId = self:GetLocalPlayerId()
    if playerId == nil then return false, false, "local_player_unavailable" end
    local playerGuardOk, playerGuardReason = checkGuard(playerId)
    if not playerGuardOk then return false, false, playerGuardReason end
    local contextA = self:ReadGlobal(2733326 + 3989 + 348)
    local contextB = self:ReadGlobal(2733326 + 3989 + 349)
    local contextC = self:ReadGlobal(2733326 + 3989 + 350)
    if type(contextA) ~= "number" or type(contextB) ~= "number"
        or type(contextC) ~= "number" then
        return false, false, "sale_context_read_failed"
    end
    local bits = self:GetActivePlayerBits(playerId)
    local args = {
        1613825825,
        playerId,
        0,
        missionId,
        math.floor(contextA),
        math.floor(contextB),
        math.floor(contextC),
        math.floor(tonumber(missionParam) or -1)
    }
    local sent = false
    local uncertain = false
    local guardFailure = nil
    local send = function()
        local guardOk, guardReason = checkGuard(playerId)
        if not guardOk then
            guardFailure = guardReason
            return
        end
        if GTA and type(GTA.TriggerScriptEvent) == "function" then
            local ok, result = pcall(GTA.TriggerScriptEvent, bits, args)
            if ok and result ~= false then
                sent = true
                return
            end
            -- Cherax does not document a false return as proof that no
            -- packet was queued. Treat both an exception and false as an
            -- unknown outcome; never send the same mission through a second
            -- path, which could duplicate the reservation/event.
            uncertain = true
            return
        end
        if uncertain then return end
        guardOk, guardReason = checkGuard(playerId)
        if not guardOk then
            guardFailure = guardReason
            return
        end
        local nativeApis = type(menu) == "table" and type(menu.nativeApis) == "table"
            and menu.nativeApis or nil
        if nativeApis and nativeApis.SCRIPT
            and type(nativeApis.SCRIPT._SEND_TU_SCRIPT_EVENT_NEW) == "function"
            and Memory and type(Memory.Alloc) == "function"
            and type(Memory.WriteInt) == "function" and type(Memory.MemSet) == "function"
            and type(Memory.Free) == "function" then
            local eventData
            local allocated = pcall(function() eventData = Memory.Alloc(64) end)
            if not allocated then
                return
            end
            if eventData and eventData ~= 0 then
                local sendResult
                local ok = pcall(function()
                    Memory.MemSet(eventData, 0, 64)
                    for index, value in ipairs(args) do
                        Memory.WriteInt(eventData + ((index - 1) * 8), value)
                    end
                    -- Keep the fallback signature aligned with freemode's
                    -- func_2130: args[1] is the event hash in this Lua table.
                    sendResult = nativeApis.SCRIPT._SEND_TU_SCRIPT_EVENT_NEW(
                        1, eventData, 8, bits, args[1]
                    )
                end)
                pcall(Memory.Free, eventData)
                if ok and sendResult ~= false then
                    sent = true
                else
                    -- The low-level bridge is also not a documented
                    -- acknowledgement. A false return must remain
                    -- quarantined rather than being retried implicitly.
                    uncertain = true
                end
            end
        end
    end
    if Script and type(Script.ExecuteAsScript) == "function" then
        local ok = pcall(Script.ExecuteAsScript, "freemode", send)
        if not ok then uncertain = true end
    else
        send()
    end
    local reason = guardFailure
    if not reason then
        if uncertain then reason = "sale_dispatch_uncertain"
        elseif not sent then reason = "sale_dispatch_failed" end
    end
    return sent and not uncertain, uncertain, reason
end

function SovereignBusinessInventory:GetSaleStock(target, refresh)
    if refresh then self:RefreshData() end
    if type(target) ~= "table" then return nil end
    if target.key == "biker" then
        local index = math.max(1, math.min(5, math.floor(tonumber(target.factoryIndex) or 0) + 1))
        local entry = self.data.factories and self.data.factories[index]
        return entry and tonumber(entry.product) or nil
    elseif target.key == "bunker" then
        local entry = self.data.factories and self.data.factories[6]
        return entry and tonumber(entry.product) or nil
    elseif target.key == "nightclub" then
        local total = 0
        for _, entry in ipairs(self.data.nightclub or {}) do
            total = total + math.max(0, tonumber(entry.value) or 0)
        end
        return total
    elseif target.key == "hangar" then
        return tonumber(self.data.hangar)
    elseif target.key == "warehouse" then
        local index = math.max(1, math.min(5, math.floor(tonumber(target.warehouseIndex) or 0) + 1))
        local entry = self.data.warehouses and self.data.warehouses[index]
        return entry and tonumber(entry.value) or nil
    end
    return nil
end

function SovereignBusinessInventory:ResolveSaleScript(target)
    if type(target) ~= "table" or type(target.missionScript) ~= "string" then return nil end
    if self:IsScriptRunning(target.missionScript) then return target.missionScript end
    return nil
end

function SovereignBusinessInventory:WaitForSaleStart(target, missionId, beforeSnapshot)
    local lastIdentityReason = nil
    for _ = 1, 450 do
        local currentIdentity, currentIdentityReason = self:IsSaleIdentityCurrent(
            target, beforeSnapshot
        )
        if not currentIdentity then
            self.lastSaleCompletionError = currentIdentityReason or "sale_identity_changed"
            return false, nil
        end
        local scriptName = self:ResolveSaleScript(target)
        if scriptName then
            local missionIdentity, missionIdentityReason = self:ValidateSaleMissionIdentity(
                target, scriptName, beforeSnapshot, missionId
            )
            if missionIdentity then return true, scriptName end
            lastIdentityReason = missionIdentityReason
            if missionIdentityReason ~= "sale_mission_evidence_unavailable"
                and missionIdentityReason ~= "sale_mission_identity_mismatch" then
                self.lastSaleCompletionError = missionIdentityReason
                return false, nil
            end
        end
        Script.Yield(100)
    end
    self.lastSaleCompletionError = lastIdentityReason or "sale_script_not_started"
    return false, nil
end

function SovereignBusinessInventory:ReadSaleLocal(scriptName, index)
    if not self:HasInventoryMapping("sale_locals") then return nil end
    if not ScriptLocal or type(ScriptLocal.GetInt) ~= "function"
        or not Utils or type(Utils.Joaat) ~= "function" then
        return nil
    end
    local resolved = self:ResolveInventorySaleLocal(scriptName, index)
    if resolved == nil then return nil end
    local ok, value = pcall(
        ScriptLocal.GetInt,
        Utils.Joaat(tostring(scriptName or "")),
        resolved
    )
    if ok and type(value) == "number" and value == value then return value end
    return nil
end

function SovereignBusinessInventory:ValidateSaleMissionIdentity(
    target, scriptName, beforeSnapshot, missionId, missionAlreadyObserved
)
    if type(target) ~= "table" or type(beforeSnapshot) ~= "table" then
        return false, "sale_identity_changed"
    end
    local expectedActivity, expectedScript, expectedRole
    if target.key == "warehouse" then
        expectedActivity = 168
        expectedScript = "gb_contraband_sell"
        expectedRole = "ceo"
    elseif target.key == "biker" then
        expectedActivity = 190
        expectedScript = "gb_biker_contraband_sell"
        expectedRole = "mc_president"
    else
        return false, "unsupported_sale_script"
    end
    if target.missionScript ~= expectedScript or scriptName ~= expectedScript
        or beforeSnapshot.activityId ~= expectedActivity
        or beforeSnapshot.organizationRole ~= expectedRole
        or (missionId ~= nil and math.floor(tonumber(missionId) or -1) ~= expectedActivity) then
        return false, "sale_mission_identity_mismatch"
    end
    local currentIdentity, currentIdentityReason = self:IsSaleIdentityCurrent(
        target, beforeSnapshot
    )
    if not currentIdentity then
        return false, currentIdentityReason or "sale_identity_changed"
    end
    if target.key == "biker" and missionAlreadyObserved ~= true then
        -- Enhanced initializes local 738 from the selected MC business token;
        -- activity 190 selects this script but is not stored in that local.
        local expectedBusiness = math.floor(tonumber(beforeSnapshot.businessToken) or -1)
        local activeBusiness = self:ReadSaleLocal(scriptName, 738)
        if type(activeBusiness) ~= "number" then
            return false, "sale_mission_evidence_unavailable"
        end
        if expectedBusiness <= 0 or math.floor(activeBusiness) ~= expectedBusiness then
            return false, "sale_mission_identity_mismatch"
        end
    end
    return true, nil
end

function SovereignBusinessInventory:WriteSaleLocal(scriptName, index, value)
    if not self:HasInventoryMapping("sale_locals") then return false end
    if not ScriptLocal or type(ScriptLocal.SetInt) ~= "function"
        or not Utils or type(Utils.Joaat) ~= "function" then
        return false
    end
    local resolved = self:ResolveInventorySaleLocal(scriptName, index)
    if resolved == nil then return false end
    local ok, result = pcall(
        ScriptLocal.SetInt,
        Utils.Joaat(tostring(scriptName or "")),
        resolved,
        math.floor(tonumber(value) or 0)
    )
    return ok and result ~= false
end

function SovereignBusinessInventory:RequestSaleScriptHost(scriptName)
    if not self:IsScriptRunning(scriptName) then return false end
    local canCheckHost = Script and type(Script.ExecuteAsScript) == "function"
        and menu.nativeApis.NETWORK and type(menu.nativeApis.NETWORK.NETWORK_IS_HOST_OF_THIS_SCRIPT) == "function"
    local function isHost()
        if not canCheckHost then return nil end
        local host = false
        local ok = pcall(Script.ExecuteAsScript, scriptName, function()
            host = menu.nativeApis.NETWORK.NETWORK_IS_HOST_OF_THIS_SCRIPT() == true
        end)
        return ok and host
    end
    if isHost() == true then return true end
    if not GTA or type(GTA.ForceScriptHost) ~= "function" then
        return not canCheckHost
    end
    for _ = 1, 100 do
        pcall(GTA.ForceScriptHost, Utils.Joaat(scriptName))
        if isHost() == true then return true end
        if not self:IsScriptRunning(scriptName) then return false end
        Script.Yield(10)
    end
    return false
end

function SovereignBusinessInventory:ApplySaleCompletion(
    target, scriptName, beforeSnapshot
)
    scriptName = tostring(scriptName or "")
    if type(target) ~= "table" or target.key ~= "biker"
        or scriptName ~= "gb_biker_contraband_sell" then
        self.lastSaleCompletionError = target and target.key == "warehouse"
            and "office_completion_layout_unverified" or "unsupported_sale_script"
        return false
    end
    local missionIdentity, missionIdentityReason = self:ValidateSaleMissionIdentity(
        target, scriptName, beforeSnapshot
    )
    if not missionIdentity then
        self.lastSaleCompletionError = missionIdentityReason
        return false
    end
    if not self:RequestSaleScriptHost(scriptName) then
        self.lastSaleCompletionError = "script_host_unavailable"
        return false
    end
    missionIdentity, missionIdentityReason = self:ValidateSaleMissionIdentity(
        target, scriptName, beforeSnapshot
    )
    if not missionIdentity then
        self.lastSaleCompletionError = missionIdentityReason
        return false
    end
    local required = self:ReadSaleLocal(scriptName, 738 + 174)
    if type(required) ~= "number" or required <= 0 or required > 100 then
        self.lastSaleCompletionError = "completion_local_unavailable"
        return false
    end
    required = math.floor(required)
    missionIdentity, missionIdentityReason = self:ValidateSaleMissionIdentity(
        target, scriptName, beforeSnapshot
    )
    if not missionIdentity then
        self.lastSaleCompletionError = missionIdentityReason
        return false
    end
    if not self:WriteSaleLocal(scriptName, 738 + 122, required) then
        self.lastSaleCompletionError = "completion_local_write_failed"
        return false
    end
    missionIdentity, missionIdentityReason = self:ValidateSaleMissionIdentity(
        target, scriptName, beforeSnapshot
    )
    if not missionIdentity then
        self.lastSaleCompletionError = missionIdentityReason
        return false
    end
    if self:ReadSaleLocal(scriptName, 738 + 122) ~= required then
        self.lastSaleCompletionError = "completion_local_write_failed"
        return false
    end
    return true
end

function SovereignBusinessInventory:SupportsAutomaticSaleCompletion(target, scriptName)
    return type(target) == "table" and target.key == "biker"
        and scriptName == "gb_biker_contraband_sell"
end

function SovereignBusinessInventory:GetCurrentGameFrame()
    if not menu.nativeApis.MISC or type(menu.nativeApis.MISC.GET_FRAME_COUNT) ~= "function" then return nil end
    local ok, frame = pcall(menu.nativeApis.MISC.GET_FRAME_COUNT)
    if not ok or type(frame) ~= "number" or frame ~= frame then return nil end
    return math.floor(frame)
end

function SovereignBusinessInventory:UpdateSaleMissionObservation(
    target, monitor, knownScript, beforeSnapshot
)
    if type(target) ~= "table" or type(target.missionScript) ~= "string"
        or type(monitor) ~= "table" then
        return false
    end
    local scriptName = knownScript
    if scriptName ~= target.missionScript then
        scriptName = self:ResolveSaleScript(target)
    end
    local active = scriptName == target.missionScript
    monitor.missionActive = active
    local now = os.clock()
    if not active then
        if monitor.missionObserved == true then
            if type(monitor.missionInactiveSince) ~= "number" then
                monitor.missionInactiveSince = now
            elseif now - monitor.missionInactiveSince >= 0.5
                and monitor.missionEnded ~= true then
                monitor.missionEnded = true
                monitor.missionEndedAt = now
                monitor.missionEndFrame = self:GetCurrentGameFrame()
                -- The accepted income descriptor can be published after the
                -- mission script exits. Keep a bounded read-only attribution
                -- window; stock, balance, UUID and uniqueness checks still
                -- decide whether settlement is confirmed.
                monitor.missionSettlementGraceUntil = now + 10.0
            end
        end
        return false
    end
    local missionIdentity, missionIdentityReason = self:ValidateSaleMissionIdentity(
        target, scriptName, beforeSnapshot, nil, monitor.missionObserved == true
    )
    if not missionIdentity then
        monitor.missionActive = false
        monitor.missionIdentityReason = missionIdentityReason
        if missionIdentityReason ~= "sale_mission_evidence_unavailable" then
            monitor.missionIdentityMismatch = true
        end
        return false
    end
    if monitor.missionIdentityMismatch ~= true then
        monitor.missionIdentityReason = nil
    end
    if monitor.missionEnded == true then
        monitor.missionGenerationChanged = true
        monitor.missionActive = false
        return false
    end
    monitor.missionInactiveSince = nil
    local frame = self:GetCurrentGameFrame()
    if type(frame) ~= "number" then return false end
    if type(monitor.preflightFrame) ~= "number" or frame < monitor.preflightFrame then
        return false
    end
    if monitor.missionObserved ~= true then
        monitor.missionObserved = true
        -- Use the frame captured before dispatch so early receipts survive
        -- the first script poll, but pre-dispatch payouts cannot qualify.
        monitor.missionStartFrame = type(monitor.dispatchFrame) == "number"
            and math.max(monitor.preflightFrame, monitor.dispatchFrame) or frame
        monitor.missionScript = scriptName
    end
    if monitor.reservationAccepted == true and monitor.dispatchSent == true
        and monitor.missionStarted ~= true then
        monitor.missionStarted = true
        Logger:Info("SovereignInventory", string.format(
            "%s sale phase=mission_started script=%s",
            tostring(target.name), tostring(scriptName)
        ))
    end
    monitor.missionLastSeenFrame = frame
    monitor.missionLastSeenAt = now
    return true
end

function SovereignBusinessInventory:CheckSaleSettlementEvidence(target, beforeSnapshot, monitor)
    if type(beforeSnapshot) ~= "table" or type(beforeSnapshot.money) ~= "table"
        or type(beforeSnapshot.persistent) ~= "number" or type(beforeSnapshot.live) ~= "number"
        or type(beforeSnapshot.money.total) ~= "number"
        or type(beforeSnapshot.money.bank) ~= "number"
        or type(beforeSnapshot.money.wallet) ~= "number"
        or type(beforeSnapshot.incomeTransactions) ~= "table"
        or type(monitor) ~= "table" then
        return false, nil, "sale_money_unavailable"
    end
    if monitor.missionGenerationChanged == true then
        return false, monitor.lastEvidence, "sale_mission_generation_changed"
    end
    if monitor.missionIdentityMismatch == true then
        return false, monitor.lastEvidence,
            monitor.missionIdentityReason or "sale_mission_identity_mismatch"
    end
    local expectedRole = target and target.key == "warehouse" and "ceo"
        or (target and target.key == "biker" and "mc_president" or nil)
    local expectedActivity = target and target.key == "warehouse" and 168
        or (target and target.key == "biker" and 190 or nil)
    if not expectedRole or beforeSnapshot.organizationRole ~= expectedRole
        or beforeSnapshot.activityId ~= expectedActivity then
        return false, nil, "sale_organization_mismatch"
    end
    local incomeSpec = self:GetSaleIncomeSpec(target)
    if not incomeSpec or beforeSnapshot.incomeItem ~= incomeSpec.incomeItem
        or beforeSnapshot.incomeStat ~= incomeSpec.incomeStat then
        return false, nil, "sale_income_identity_unavailable"
    end
    local expectedPayoutMetadata = {
        f6 = tonumber(beforeSnapshot.payoutMetadataF6),
        f7 = tonumber(beforeSnapshot.payoutMetadataF7)
    }
    if expectedPayoutMetadata.f6 == nil or expectedPayoutMetadata.f7 == nil then
        return false, nil, "sale_income_identity_unavailable"
    end
    expectedPayoutMetadata.f6 = math.floor(expectedPayoutMetadata.f6)
    expectedPayoutMetadata.f7 = math.floor(expectedPayoutMetadata.f7)
    local currentOrganization = self:GetLocalOrganizationState()
    local currentCharacterSlot = self:GetCharacterSlot()
    if currentCharacterSlot ~= beforeSnapshot.characterSlot
        or currentOrganization.valid ~= true
        or currentOrganization.playerId ~= beforeSnapshot.playerId
        or currentOrganization.bossId ~= beforeSnapshot.organizationBossId
        or currentOrganization.role ~= beforeSnapshot.organizationRole then
        return false, nil, "sale_identity_changed"
    end
    -- Settlement polling already runs on a short cadence. Use two immediate
    -- reads here; the strict multi-sample gate remains in preflight.
    local stock, stockReason = self:GetSaleStockEvidence(target, beforeSnapshot, {
        attempts = 2, sampleDelay = 0, quiet = true,
        packingAttempts = 2, packingDelay = 0
    })
    local money, moneyReason = self:GetMoneySnapshot(beforeSnapshot)
    local saleCount = math.floor(tonumber(beforeSnapshot.saleCount) or 0)
    local expectedStock = saleCount > 0 and (beforeSnapshot.persistent - saleCount) or nil
    local evidence = {
        beforePersistent = beforeSnapshot.persistent,
        beforeLive = beforeSnapshot.live,
        beforeBank = beforeSnapshot.money.bank,
        beforeWallet = beforeSnapshot.money.wallet,
        beforeMoney = beforeSnapshot.money.total,
        beforeSpecial = beforeSnapshot.specialPersistent,
        saleType = beforeSnapshot.saleType,
        saleCount = saleCount,
        expectedStock = expectedStock,
        afterPersistent = stock and stock.persistent or nil,
        afterLive = stock and stock.live or nil,
        afterSpecial = stock and stock.specialPersistent or nil,
        afterBank = money and money.bank or nil,
        afterWallet = money and money.wallet or nil,
        afterMoney = money and money.total or nil,
        bankDelta = money and (money.bank - beforeSnapshot.money.bank) or nil,
        walletDelta = money and (money.wallet - beforeSnapshot.money.wallet) or nil,
        organizationRole = beforeSnapshot.organizationRole,
        activityId = beforeSnapshot.activityId,
        payoutMetadataF6 = expectedPayoutMetadata.f6,
        payoutMetadataF7 = expectedPayoutMetadata.f7,
        incomeItem = incomeSpec.incomeItem,
        incomeStat = incomeSpec.incomeStat,
        stockConfirmed = false,
        quantityConfirmed = false,
        specialConfirmed = target and target.key ~= "warehouse",
        packingConfirmed = target and target.key ~= "warehouse",
        missionObserved = monitor.missionObserved == true,
        missionStartFrame = monitor and monitor.missionStartFrame or nil,
        incomeTransactionConfirmed = false,
        incomeTransactionRejected = monitor.incomeTransactionRejected == true,
        incomeTransactionId = nil,
        incomeTransactionSlot = nil,
        incomeTransactionFrame = nil,
        acceptedAmount = nil,
        incomeCandidateCount = 0,
        acceptedCandidateCount = 0,
        incomeAmbiguous = false,
        incomeIdentityMismatch = monitor.incomeIdentityMismatch == true,
        incomeStable = type(monitor.lastNewAcceptedIncomeAt) == "number"
            and os.clock() - monitor.lastNewAcceptedIncomeAt >= 1.0,
        balanceDelta = money and (money.total - beforeSnapshot.money.total) or nil,
        balanceConfirmed = false,
        incomeConfirmed = false,
        reservationAccepted = monitor.reservationAccepted == true,
        dispatchSent = monitor.dispatchSent == true,
        missionStarted = monitor.missionStarted == true,
        at = os.clock()
    }
    if evidence.reservationAccepted ~= true
        or evidence.dispatchSent ~= true
        or evidence.missionStarted ~= true or evidence.missionObserved ~= true then
        return false, evidence, "sale_phase_incomplete"
    end
    if monitor.missionEnded == true then
        local graceUntil = tonumber(monitor.missionSettlementGraceUntil)
        if graceUntil == nil or os.clock() > graceUntil then
            return false, evidence, "sale_settlement_window_expired"
        end
    end
    if not stock then return false, evidence, stockReason or "sale_stock_unavailable" end
    if not money then return false, evidence, moneyReason or "sale_money_unavailable" end
    local identityStillCurrent, identityReason = self:IsSaleIdentityCurrent(
        target, beforeSnapshot
    )
    if not identityStillCurrent then
        return false, evidence, identityReason or "sale_identity_changed"
    end
    local currentPayoutMetadata, currentMetadataReason =
        self:ReadSalePayoutMetadata(beforeSnapshot.organizationBossId)
    if not currentPayoutMetadata then
        return false, evidence, currentMetadataReason
            or "sale_income_identity_unavailable"
    end
    if currentPayoutMetadata.f6 ~= expectedPayoutMetadata.f6
        or currentPayoutMetadata.f7 ~= expectedPayoutMetadata.f7 then
        evidence.incomeIdentityMismatch = true
        return false, evidence, "sale_income_identity_mismatch"
    end
    if stock.businessToken ~= beforeSnapshot.businessToken then
        return false, evidence, "sale_identity_changed"
    end
    local function candidateBelongsToMissionWindow(candidate)
        if type(candidate) ~= "table" or type(candidate.createdFrame) ~= "number"
            or type(candidate.observedAt) ~= "number"
            or type(monitor.missionStartFrame) ~= "number"
            or candidate.createdFrame < monitor.missionStartFrame then
            return false
        end
        if monitor.missionEnded ~= true then return true end
        local graceUntil = tonumber(monitor.missionSettlementGraceUntil)
        return graceUntil ~= nil and candidate.observedAt <= graceUntil
    end
    local selectedIncome = nil
    for _, candidate in pairs(
        type(monitor) == "table" and monitor.incomeCandidates or {}
    ) do
        if candidateBelongsToMissionWindow(candidate)
            and candidate.missionScript == monitor.missionScript
            and candidate.activityId == beforeSnapshot.activityId
            and candidate.businessToken == beforeSnapshot.businessToken
            and candidate.incomeItem == incomeSpec.incomeItem
            and candidate.incomeStat == incomeSpec.incomeStat
            then
            evidence.incomeCandidateCount = evidence.incomeCandidateCount + 1
        end
    end
    for _, candidate in pairs(
        type(monitor) == "table" and monitor.acceptedIncomeCandidates or {}
    ) do
        if candidateBelongsToMissionWindow(candidate)
            and type(candidate.amount) == "number" and candidate.amount > 0
            and candidate.missionScript == monitor.missionScript
            and candidate.activityId == beforeSnapshot.activityId
            and candidate.businessToken == beforeSnapshot.businessToken
            and candidate.incomeItem == incomeSpec.incomeItem
            and candidate.incomeStat == incomeSpec.incomeStat
            then
            evidence.acceptedCandidateCount = evidence.acceptedCandidateCount + 1
            selectedIncome = candidate
        end
    end
    evidence.incomeAmbiguous = evidence.incomeCandidateCount > 1
    if evidence.acceptedCandidateCount == 1
        and evidence.incomeCandidateCount == 1
        and evidence.incomeIdentityMismatch ~= true
        and monitor.incomeIdentityMismatch ~= true
        and evidence.incomeTransactionRejected ~= true then
        evidence.incomeTransactionConfirmed = true
        evidence.incomeTransactionId = selectedIncome.transactionId
        evidence.incomeTransactionSlot = selectedIncome.slot
        evidence.incomeTransactionFrame = selectedIncome.createdFrame
        evidence.acceptedAmount = selectedIncome.amount
    end
    evidence.quantityConfirmed = type(expectedStock) == "number" and expectedStock >= 0
        and stock.persistent == expectedStock and stock.live == expectedStock
    if target and target.key == "warehouse" then
        local beforeSpecial = tonumber(beforeSnapshot.specialPersistent)
        local afterSpecial = tonumber(stock.specialPersistent)
        if type(beforeSpecial) == "number" and type(afterSpecial) == "number" then
            if beforeSnapshot.saleType == 4 then
                evidence.specialConfirmed = afterSpecial == beforeSpecial - saleCount
            elseif beforeSnapshot.saleType == 3 then
                evidence.specialConfirmed = afterSpecial == beforeSpecial
            end
        end
        evidence.packingConfirmed = stock.packingConfirmed == true
    end
    evidence.stockConfirmed = stock.persistent == stock.live
        and evidence.quantityConfirmed and evidence.specialConfirmed
        and evidence.packingConfirmed
    evidence.balanceConfirmed = type(evidence.acceptedAmount) == "number"
        and evidence.acceptedAmount > 0
        and type(evidence.balanceDelta) == "number"
        and type(evidence.bankDelta) == "number"
        and type(evidence.walletDelta) == "number"
        and evidence.bankDelta >= 0
        and evidence.walletDelta >= 0
        and evidence.bankDelta + evidence.walletDelta == evidence.acceptedAmount
        and evidence.balanceDelta == evidence.acceptedAmount
    evidence.incomeConfirmed = evidence.incomeTransactionConfirmed
        and evidence.incomeStable and evidence.balanceConfirmed
    if evidence.stockConfirmed and evidence.incomeConfirmed then return true, evidence, nil end
    if evidence.stockConfirmed and evidence.incomeAmbiguous then
        return false, evidence, "sale_income_ambiguous"
    end
    if evidence.stockConfirmed then return false, evidence, "sale_income_unconfirmed" end
    if evidence.incomeConfirmed then return false, evidence, "sale_stock_unconfirmed" end
    return false, evidence, "sale_settlement_timeout"
end

function SovereignBusinessInventory:CreateSaleSettlementMonitor(beforeSnapshot)
    if type(beforeSnapshot) ~= "table" or type(beforeSnapshot.money) ~= "table"
        or type(beforeSnapshot.incomeTransactions) ~= "table" then
        return nil
    end
    return {
        incomeBaseline = beforeSnapshot.incomeTransactions,
        incomeCandidates = {},
        acceptedIncomeCandidates = {},
        incomeTransactionRejected = false,
        incomeIdentityMismatch = false,
        incomeIdentityMismatches = {},
        incomeAcceptedAt = nil,
        lastNewAcceptedIncomeAt = nil,
        lastIncomeReadError = nil,
        missionObserved = false,
        preflightFrame = beforeSnapshot.preflightFrame,
        missionActive = false,
        missionStartFrame = type(beforeSnapshot.preflightFrame) == "number"
            and math.floor(beforeSnapshot.preflightFrame) or nil,
        missionLastSeenFrame = nil,
        missionLastSeenAt = nil,
        missionInactiveSince = nil,
        missionEnded = false,
        missionEndedAt = nil,
        missionEndFrame = nil,
        missionSettlementGraceUntil = nil,
        missionGenerationChanged = false,
        missionIdentityMismatch = false,
        missionIdentityReason = nil,
        missionScript = nil,
        reservationAccepted = false,
        dispatchSent = false,
        dispatchFrame = nil,
        missionStarted = false,
        lastEvidenceCheckAt = nil,
        lastEvidence = nil,
        lastEvidenceReason = nil
    }
end

function SovereignBusinessInventory:ObserveSaleSettlement(target, beforeSnapshot, monitor)
    monitor = type(monitor) == "table" and monitor
        or self:CreateSaleSettlementMonitor(beforeSnapshot)
    if not monitor then return false, nil, "sale_money_unavailable", nil end
    self:UpdateSaleMissionObservation(target, monitor, nil, beforeSnapshot)
    if monitor.missionGenerationChanged == true then
        monitor.lastEvidenceReason = "sale_mission_generation_changed"
        return false, monitor.lastEvidence,
            "sale_mission_generation_changed", monitor
    end
    if monitor.missionIdentityMismatch == true then
        monitor.lastEvidenceReason = monitor.missionIdentityReason
            or "sale_mission_identity_mismatch"
        return false, monitor.lastEvidence, monitor.lastEvidenceReason, monitor
    end
    local acceptedBefore = next(monitor.acceptedIncomeCandidates or {}) ~= nil
    local _, incomeReason = self:ObserveSaleIncomeTransactions(beforeSnapshot, monitor)
    local acceptedAfter = next(monitor.acceptedIncomeCandidates or {}) ~= nil
    if incomeReason ~= nil or monitor.lastIncomeReadError ~= nil then
        monitor.lastEvidenceReason = incomeReason or monitor.lastIncomeReadError
        return false, monitor.lastEvidence, monitor.lastEvidenceReason, monitor
    end
    local now = os.clock()
    local checkDue = monitor.lastEvidenceCheckAt == nil
        or now - monitor.lastEvidenceCheckAt >= 0.5
        or (not acceptedBefore and acceptedAfter)
    local settled, evidence, reason = false, monitor.lastEvidence, monitor.lastEvidenceReason
    if checkDue then
        settled, evidence, reason = self:CheckSaleSettlementEvidence(
            target, beforeSnapshot, monitor
        )
        monitor.lastEvidenceCheckAt = now
        monitor.lastEvidence = evidence
        monitor.lastEvidenceReason = reason
    end
    if settled then return true, evidence, nil, monitor end
    if incomeReason and not acceptedAfter then
        reason = incomeReason
    end
    return false, evidence, reason, monitor
end

function SovereignBusinessInventory:WaitForSaleSettlement(target, beforeSnapshot, monitor)
    local checks = math.max(20, math.floor((tonumber(self.saleSettlementTimeout) or 45.0) * 20))
    local lastEvidence, lastReason
    for attempt = 1, checks do
        Script.Yield(50)
        if attempt % 40 == 0 then pcall(function() self:RefreshData() end) end
        local settled, evidence, reason
        settled, evidence, reason, monitor = self:ObserveSaleSettlement(
            target, beforeSnapshot, monitor
        )
        lastEvidence, lastReason = evidence, reason
        if settled then
            self.lastSaleSettlement = evidence
            Logger:Info("SovereignInventory", string.format(
                "%s sale phase=settlement_confirmed stock=%d/%d->%d/%d money=%d->%d accepted=%d tx=%s slot=%s frame=%s bankDelta=%s walletDelta=%s",
                tostring(target.name), evidence.beforePersistent, evidence.beforeLive,
                evidence.afterPersistent, evidence.afterLive,
                evidence.beforeMoney, evidence.afterMoney, evidence.acceptedAmount,
                tostring(evidence.incomeTransactionId), tostring(evidence.incomeTransactionSlot),
                tostring(evidence.incomeTransactionFrame), tostring(evidence.bankDelta),
                tostring(evidence.walletDelta)
            ))
            return true
        end
    end
    self.lastSaleSettlement = lastEvidence
    self.lastSaleCompletionError = lastReason or "sale_settlement_timeout"
    if lastEvidence then
        Logger:Warn("SovereignInventory", string.format(
            "%s settlement unconfirmed stock=%s income=%s tx=%s before=%s/%s/%s after=%s/%s/%s",
            tostring(target.name), tostring(lastEvidence.stockConfirmed),
            tostring(lastEvidence.incomeConfirmed),
            tostring(lastEvidence.incomeTransactionConfirmed),
            tostring(lastEvidence.beforePersistent),
            tostring(lastEvidence.beforeLive), tostring(lastEvidence.beforeMoney),
            tostring(lastEvidence.afterPersistent), tostring(lastEvidence.afterLive),
            tostring(lastEvidence.afterMoney)
        ))
    end
    return false
end

function SovereignBusinessInventory:FinalizePendingSaleSettlement(
    latchKey, pending, evidence, notificationPrefix
)
    if type(pending) ~= "table" or type(evidence) ~= "table"
        or self.pendingSaleReservation[latchKey] ~= pending then
        return false
    end
    self.pendingSaleReservation[latchKey] = nil
    self.saleSettlementProbeTokens[latchKey] = nil
    self.saleLatch[latchKey] = true
    self.saleLatchType[latchKey] = evidence.saleType
    self.lastSaleSettlement = evidence
    pcall(function() self:RefreshData() end)
    Logger:Info("SovereignInventory", string.format(
        "%s sale phase=settlement_confirmed stock=%s/%s->%s/%s money=%s->%s accepted=%s tx=%s slot=%s frame=%s bankDelta=%s walletDelta=%s",
        tostring(pending.target and pending.target.name),
        tostring(evidence.beforePersistent), tostring(evidence.beforeLive),
        tostring(evidence.afterPersistent), tostring(evidence.afterLive),
        tostring(evidence.beforeMoney), tostring(evidence.afterMoney),
        tostring(evidence.acceptedAmount), tostring(evidence.incomeTransactionId),
        tostring(evidence.incomeTransactionSlot), tostring(evidence.incomeTransactionFrame),
        tostring(evidence.bankDelta), tostring(evidence.walletDelta)
    ))
    self:Notify(
        tostring(notificationPrefix or (pending.target and pending.target.name) or "Business")
            .. "Sale completed",
        "success"
    )
    return true
end

function SovereignBusinessInventory:ShouldQuarantinePendingSale(pending, now)
    if type(pending) ~= "table" or type(pending.target) ~= "table" then return false end
    if pending.settlementWaitActive == true then return false end
    -- A server-accepted reservation whose local freemode descriptor is still
    -- owned has no safe settlement window yet. Keep it locked until the exact
    -- tx/frame slot is cleared or observed free.
    if type(pending.transactionContext) == "table" then return false end
    local monitor = pending.monitor
    if type(monitor) == "table" and monitor.missionGenerationChanged == true then
        return true
    end
    if type(monitor) == "table" and monitor.missionIdentityMismatch == true then
        return true
    end
    if type(pending.target.missionScript) == "string"
        and self:IsScriptRunning(pending.target.missionScript) then
        return false
    end
    now = tonumber(now) or os.clock()
    if type(monitor) == "table" and monitor.missionObserved == true
        and monitor.missionEnded == true
        and type(monitor.missionSettlementGraceUntil) == "number" then
        return now > monitor.missionSettlementGraceUntil + 0.5
    end
    if type(monitor) == "table" and monitor.missionObserved == true
        and type(monitor.missionLastSeenAt) == "number" then
        return now - monitor.missionLastSeenAt > 10.5
    end
    return now - (tonumber(pending.at) or now) > 60.0
end

function SovereignBusinessInventory:QueuePendingSaleContinuation(pending)
    if type(pending) ~= "table" or type(pending.saleContinuation) ~= "function"
        or not Script or type(Script.QueueJob) ~= "function" then
        return false, "sale_runtime_exception"
    end
    if pending.continuationQueued == true then
        return true, nil
    end
    if self.saleLaunchBusy then return false, "transaction_busy" end
    if os.clock() < (tonumber(pending.selectorRetryAt) or 0) then
        return false, "sale_continuation_backoff"
    end
    local latchKey = tostring(pending.target and (
        pending.target.latchKey or pending.target.key
    ) or "")
    if latchKey == "" or self.pendingSaleReservation[latchKey] ~= pending then
        return false, "sale_settlement_state_lost"
    end
    local continuation = pending.saleContinuation
    pending.continuationQueued = true
    pending.phase = "reservation_continuation_queued"
    self.saleSettlementProbeTokens[latchKey] = nil
    self.saleLaunchBusy = true
    local continuationJob = function()
        if self.pendingSaleReservation[latchKey] ~= pending then
            self.saleLaunchBusy = false
            return
        end
        local ok, result = xpcall(continuation, debug.traceback)
        self.saleLaunchBusy = false
        if not ok then
            local current = self.pendingSaleReservation[latchKey]
            if type(current) == "table" then
                current.saleContinuation = nil
                current.continuationQueued = false
                if type(current.selectorState) == "table" then
                    current.selectorState.retryable = false
                    current.selectorState.terminal = true
                    current.selectorState.reason = "sale_runtime_exception"
                end
                current.reason = "sale_runtime_exception"
                current.phase = "reservation_continuation_exception"
                current.probeRetryAt = os.clock() + 5.0
                Logger:Error("SovereignInventory", "sale reservation continuation: "
                    .. tostring(result))
                if not self:QuarantinePendingSale(
                    latchKey, current, "sale_runtime_exception"
                ) then
                    self:StartPendingSaleSettlementProbe(latchKey)
                end
            end
        elseif self.pendingSaleReservation[latchKey] == pending then
            -- A valid continuation either replaces this pending object with
            -- the reservation/mission monitor, or installs a new retryable
            -- pending object through lockCommittedFailure. Reaching here means
            -- its state hand-off was lost regardless of its Lua return value.
            pending.saleContinuation = nil
            pending.continuationQueued = false
            pending.reason = "sale_settlement_state_lost"
            pending.phase = "reservation_continuation_lost"
            if not self:QuarantinePendingSale(
                latchKey, pending, "sale_settlement_state_lost"
            ) then
                pending.continuationLost = true
            end
        end
    end
    local queueOk, queued = pcall(Script.QueueJob, continuationJob)
    if not queueOk or queued == false then
        self.saleLaunchBusy = false
        pending.continuationQueued = false
        local retryAt = os.clock() + 1.0
        pending.selectorRetryAt = retryAt
        if type(pending.selectorState) == "table" then
            pending.selectorState.retryAt = retryAt
        end
        return false, "sale_runtime_exception"
    end
    return true, nil
end

function SovereignBusinessInventory:EnsurePendingSaleTransactionCleanup(pending)
    if type(pending) ~= "table" then
        return false, "transaction_state_unavailable"
    end
    if pending.continuationQueued == true then
        return false, "sale_continuation_pending"
    end
    local now = os.clock()
    local latchKey = tostring(pending.target and (
        pending.target.latchKey or pending.target.key
    ) or "")
    local transactionContext = pending.transactionContext
    if type(transactionContext) == "table" then
        if now < (tonumber(pending.transactionCleanupNextAt) or 0) then
            return false, pending.reason or "transaction_cleanup_unconfirmed"
        end
        local settled, cleanupReason = self:EnsureFreemodeTransactionSettled(
            transactionContext
        )
        if not settled then
            pending.transactionCleanupAttempts = math.floor(
                tonumber(pending.transactionCleanupAttempts) or 0
            ) + 1
            pending.transactionCleanupNextAt = now + math.min(
                30.0, 0.5 * (2 ^ math.min(6, pending.transactionCleanupAttempts - 1))
            )
            pending.reason = cleanupReason or "transaction_cleanup_unconfirmed"
            if transactionContext.slotTombstone == true
                and transactionContext.outcomePending ~= true
                and now >= (tonumber(transactionContext.cleanupDeadline)
                    or rawget(math, "huge")) then
                pending.reason = "transaction_cleanup_expired"
                if latchKey ~= ""
                    and self.pendingSaleReservation[latchKey] == pending then
                    self:QuarantinePendingSale(
                        latchKey, pending, "transaction_cleanup_expired"
                    )
                end
            end
            return false, pending.reason
        end
        pending.transactionContext = nil
        pending.transactionCleanupResolvedAt = now
        if transactionContext.outcomeAbandoned == true then
            pending.reason = "transaction_outcome_unconfirmed"
            self:QuarantinePendingSale(
                latchKey, pending, "transaction_outcome_unconfirmed"
            )
            return false, "transaction_outcome_unconfirmed"
        end
        if transactionContext.localOnlyCleanup == true then
            if latchKey ~= "" and self.pendingSaleReservation[latchKey] == pending then
                self.pendingSaleReservation[latchKey] = nil
                self.saleSettlementProbeTokens[latchKey] = nil
                self.saleLatch[latchKey] = nil
                self.saleLatchType[latchKey] = nil
            end
            self.lastAutoSell = os.clock()
            Logger:Info("SovereignInventory", string.format(
                "%s unpublished selector cleanup completed; sale retry unlocked",
                tostring(pending.target and pending.target.name)
            ))
            return false, "transaction_not_dispatched"
        end
        if transactionContext.serverRejected == true then
            if latchKey ~= "" then
                self.saleRejectedKeys[latchKey] = true
                self.saleLatch[latchKey] = true
                if self.pendingSaleReservation[latchKey] == pending then
                    self.pendingSaleReservation[latchKey] = nil
                end
            end
            pending.reason = "transaction_rejected"
            Logger:Warn("SovereignInventory", string.format(
                "%s rejected sale cleanup completed; retries locked",
                tostring(pending.target and pending.target.name)
            ))
            return false, "transaction_rejected"
        end
        if transactionContext.serverAccepted == true
            and transactionContext.resumeSaleAfterSelector == true then
            if type(pending.selectorState) ~= "table" then
                pending.selectorState = {}
            end
            pending.selectorState.selectorAccepted = true
            if pending.selectorState.completed ~= true
                and pending.selectorState.terminal ~= true
                and pending.selectorState.finalizerInvoked ~= true then
                pending.selectorState.retryable = true
                pending.selectorState.phase = "selector_accepted"
            end
            pending.selectorState.startedAt =
                tonumber(pending.selectorState.startedAt) or now
            if type(pending.saleContinuation) ~= "function" then
                pending.saleContinuation = transactionContext.saleContinuation
            end
            if type(pending.saleContinuation) ~= "function" then
                pending.reason = "sale_settlement_state_lost"
                pending.phase = "reservation_continuation_lost"
                if not self:QuarantinePendingSale(
                    latchKey, pending, "sale_settlement_state_lost"
                ) then
                    pending.continuationLost = true
                end
                return false, pending.reason
            end
            pending.phase = "reservation_continuation_pending"
            pending.reason = "sale_continuation_pending"
        end
    end
    if pending.continuationLost == true then
        local retryAt = tonumber(pending.continuationLostRetryAt) or 0
        if now >= retryAt then
            pending.continuationLostRetryAt = now + 1.0
            if latchKey ~= "" and self.pendingSaleReservation[latchKey] == pending
                and self:QuarantinePendingSale(
                    latchKey, pending, "sale_settlement_state_lost"
                ) then
                return false, "sale_settlement_state_lost"
            end
        end
        -- While the mission is still alive QuarantinePendingSale deliberately
        -- refuses to detach it. Let the caller continue read-only settlement
        -- observation, then retry quarantine after the mission stops.
        return true, nil
    end
    if type(pending.saleContinuation) == "function" then
        local state = pending.selectorState
        if type(state) == "table" and state.terminal == true then
            pending.saleContinuation = nil
            self:QuarantinePendingSale(
                latchKey, pending, state.reason or "sale_settlement_state_lost"
            )
            return false, state.reason or "sale_settlement_state_lost"
        end
        if now < (tonumber(pending.selectorRetryAt) or 0) then
            return false, "sale_continuation_backoff"
        end
        local queued, queueReason = self:QueuePendingSaleContinuation(pending)
        return false, queued and "sale_continuation_pending" or queueReason
    end
    return true, nil
end

function SovereignBusinessInventory:QuarantinePendingSale(latchKey, pending, reason)
    if type(pending) ~= "table" or self.pendingSaleReservation[latchKey] ~= pending
        or (type(pending.target) == "table"
            and type(pending.target.missionScript) == "string"
            and self:IsScriptRunning(pending.target.missionScript)
            and not (type(pending.monitor) == "table"
                and (pending.monitor.missionGenerationChanged == true
                    or pending.monitor.missionIdentityMismatch == true))) then
        return false
    end
    local monitor = pending.monitor
    if type(monitor) == "table" and monitor.missionObserved == true then
        local now = os.clock()
        monitor.missionActive = false
        monitor.missionEnded = true
        monitor.missionEndedAt = monitor.missionEndedAt or now
        monitor.missionEndFrame = monitor.missionEndFrame or self:GetCurrentGameFrame()
        -- A delayed scheduler can reach this fallback before the normal
        -- inactive-poll edge records the grace deadline. Establish one here
        -- so an already accepted descriptor is still given the same bounded
        -- read-only settlement window, without extending quarantine itself.
        monitor.missionSettlementGraceUntil =
            monitor.missionSettlementGraceUntil or (now + 10.0)
    end
    local quarantineReason = reason or (type(monitor) == "table"
        and monitor.lastEvidenceReason) or pending.reason or "sale_settlement_timeout"
    local quarantineAt = os.clock()
    local transactionContext = pending.transactionContext
    local priorSaleGlobalQuietUntil = tonumber(self.saleGlobalQuietUntil) or 0
    local quarantineQuietUntil = quarantineAt + math.max(
        60.0,
        tonumber(self.saleQuarantineQuietPeriod) or 180.0,
        tonumber(self.saleQuarantineReconcileWindow) or 300.0
    )
    self.saleQuarantine[latchKey] = {
        target = pending.target,
        before = pending.before,
        monitor = monitor,
        phase = pending.phase,
        reason = quarantineReason,
        at = quarantineAt,
        nextReconcileAt = quarantineAt,
        reconciliationExpiresAt = quarantineAt
            + math.max(60.0, tonumber(self.saleQuarantineReconcileWindow) or 300.0),
        transactionContext = transactionContext,
        transactionCleanupAttempts = tonumber(pending.transactionCleanupAttempts) or 0,
        transactionCleanupNextAt = tonumber(pending.transactionCleanupNextAt)
            or quarantineAt,
        transactionCleanupResolvedAt = pending.transactionCleanupResolvedAt,
        priorSaleGlobalQuietUntil = priorSaleGlobalQuietUntil,
        quarantineQuietUntil = quarantineQuietUntil,
        unlockAfterLocalCleanup = type(transactionContext) == "table"
            and transactionContext.localOnlyCleanup == true
            and transactionContext.outcomePending ~= true
            and transactionContext.outcomeAbandoned ~= true
            and transactionContext.serverAccepted ~= true
            and transactionContext.serverRejected ~= true
    }
    self.pendingSaleReservation[latchKey] = nil
    self.saleSettlementProbeTokens[latchKey] = nil
    self.saleLatch[latchKey] = true
    self.saleGlobalQuietUntil = math.max(
        priorSaleGlobalQuietUntil, quarantineQuietUntil
    )
    Logger:Warn("SovereignInventory", string.format(
        "%s sale moved to per-key quarantine phase=%s reason=%s",
        tostring(pending.target and pending.target.name),
        tostring(pending.phase), tostring(quarantineReason)
    ))
    self:Notify(
        tostring(pending.target and pending.target.name or "Business")
            .. "Sale unconfirmed; paused",
        "warning"
    )
    return true
end

function SovereignBusinessInventory:StartPendingSaleSettlementProbe(latchKey)
    local pending = self.pendingSaleReservation[latchKey]
    if type(pending) ~= "table" or not Script
        or type(Script.QueueJob) ~= "function" then
        return false
    end
    if self.saleLaunchBusy or pending.continuationQueued == true then return false end
    if pending.settlementWaitActive == true then return false end
    if pending.probeStarted == true and self.saleSettlementProbeTokens[latchKey] ~= nil then
        return false
    end
    if os.clock() < (tonumber(pending.probeRetryAt) or 0) then return false end
    pending.probeStarted = false
    self.saleSettlementProbeSerial = math.floor(
        tonumber(self.saleSettlementProbeSerial) or 0
    ) + 1
    local token = self.saleSettlementProbeSerial
    self.saleSettlementProbeTokens[latchKey] = token
    pending.probeStarted = true
    pending.probeToken = token
    local probe = function()
        local probeOk, probeError = xpcall(function()
            local fastUntil = os.clock() + 10.5
            while self.saleSettlementProbeTokens[latchKey] == token do
                local current = self.pendingSaleReservation[latchKey]
                if type(current) ~= "table" or type(current.target) ~= "table"
                    or type(current.before) ~= "table" then
                    break
                end
                if current.settlementWaitActive == true then
                    Script.Yield(100)
                else
                    local cleanupOk = self:EnsurePendingSaleTransactionCleanup(current)
                    if not cleanupOk then
                        Script.Yield(100)
                    else
                        local settled, evidence
                        settled, evidence, _, current.monitor = self:ObserveSaleSettlement(
                            current.target, current.before, current.monitor
                        )
                        if settled then
                            self:FinalizePendingSaleSettlement(latchKey, current, evidence)
                            break
                        end
                        if self:ShouldQuarantinePendingSale(current, os.clock()) then
                            self:QuarantinePendingSale(latchKey, current)
                            break
                        end
                        local scriptActive = type(current.target.missionScript) == "string"
                            and self:IsScriptRunning(current.target.missionScript)
                        if scriptActive then fastUntil = os.clock() + 10.5 end
                        Script.Yield(os.clock() <= fastUntil and 50 or 1000)
                    end
                end
            end
        end, debug.traceback)
        if self.saleSettlementProbeTokens[latchKey] == token then
            self.saleSettlementProbeTokens[latchKey] = nil
        end
        local current = self.pendingSaleReservation[latchKey]
        if type(current) == "table" and current.probeToken == token then
            current.probeStarted = false
            current.probeToken = nil
            if not probeOk then
                current.probeRetryAt = os.clock() + 5.0
                Logger:Error("SovereignInventory", "sale settlement probe: "
                    .. tostring(probeError))
            end
        end
    end
    local queueOk, queued = pcall(Script.QueueJob, probe)
    if not queueOk or queued == false then
        if self.saleSettlementProbeTokens[latchKey] == token then
            self.saleSettlementProbeTokens[latchKey] = nil
        end
        if self.pendingSaleReservation[latchKey] == pending then
            pending.probeStarted = false
            pending.probeToken = nil
            pending.probeRetryAt = os.clock() + 5.0
        end
        return false
    end
    return true
end

function SovereignBusinessInventory:CompleteSaleMission(
    target, scriptName, beforeSnapshot, settlementMonitor
)
    -- Accepted descriptors can be consumed while this job waits. Keep the
    -- single settlement observer running throughout the completion delay.
    local function observeDuringWait()
        local settled, evidence, reason
        settled, evidence, reason, settlementMonitor = self:ObserveSaleSettlement(
            target, beforeSnapshot, settlementMonitor
        )
        if settled then self.lastSaleSettlement = evidence end
        return settled
    end
    local remaining = math.max(500,
        math.floor((tonumber(self.saleCompleteDelay) or 2.0) * 1000))
    while remaining > 0 do
        if observeDuringWait() then return true end
        local step = math.min(50, remaining)
        Script.Yield(step)
        remaining = remaining - step
    end
    self.lastSaleCompletionError = nil
    if not self:SupportsAutomaticSaleCompletion(target, scriptName) then
        self.lastSaleCompletionError = target and target.key == "warehouse"
            and "office_completion_layout_unverified" or "unsupported_sale_script"
        return false
    end
    local missionIdentity, missionIdentityReason = self:ValidateSaleMissionIdentity(
        target, scriptName, beforeSnapshot
    )
    if not missionIdentity then
        self.lastSaleCompletionError = missionIdentityReason
        return false
    end
    local completionApplied = false
    for _ = 1, 120 do
        if observeDuringWait() then return true end
        local runningScript = self:ResolveSaleScript(target)
        if runningScript ~= scriptName then
            self.lastSaleCompletionError = "sale_script_not_started"
            break
        end
        missionIdentity, missionIdentityReason = self:ValidateSaleMissionIdentity(
            target, scriptName, beforeSnapshot
        )
        if not missionIdentity then
            self.lastSaleCompletionError = missionIdentityReason
            break
        end
        local required = self:ReadSaleLocal(scriptName, 738 + 174)
        if type(required) == "number" and required > 0 then
            completionApplied = self:ApplySaleCompletion(
                target, scriptName, beforeSnapshot
            )
            if completionApplied then break end
        end
        for _ = 1, 5 do
            Script.Yield(50)
            if observeDuringWait() then return true end
        end
    end
    if not completionApplied then
        self.lastSaleCompletionError = self.lastSaleCompletionError or "completion_local_write_failed"
        return false
    end
    return self:WaitForSaleSettlement(target, beforeSnapshot, settlementMonitor)
end

function SovereignBusinessInventory:ContinueAcceptedSaleReservation(
    target, beforeSnapshot, latchKey, lockCommittedFailure
)
    if type(target) ~= "table" or type(beforeSnapshot) ~= "table"
        or type(lockCommittedFailure) ~= "function" then
        return false
    end
    latchKey = tostring(latchKey or target.latchKey or target.key)
    Logger:Info("SovereignInventory", string.format(
        "%s sale phase=reservation_accepted saleType=%s count=%s",
        tostring(target.name), tostring(beforeSnapshot.saleType),
        tostring(beforeSnapshot.saleCount or beforeSnapshot.persistent)
    ))
    self.saleLatch[latchKey] = true
    if beforeSnapshot.saleType then
        self.saleLatchType[latchKey] = beforeSnapshot.saleType
    end
    self.lastAutoSell = os.clock()

    local existing = self.pendingSaleReservation[latchKey]
    if type(existing) == "table" and existing.probeToken ~= nil
        and self.saleSettlementProbeTokens[latchKey] == existing.probeToken then
        self.saleSettlementProbeTokens[latchKey] = nil
    end
    self.pendingSaleReservation[latchKey] = {
        target = target,
        before = beforeSnapshot,
        monitor = type(existing) == "table" and existing.monitor
            or self:CreateSaleSettlementMonitor(beforeSnapshot),
        phase = "reserved",
        at = os.clock()
    }
    local pending = self.pendingSaleReservation[latchKey]
    if type(pending.monitor) == "table" then
        pending.monitor.reservationAccepted = true
    end

    local identityStillCurrent, identityReason = self:IsSaleIdentityCurrent(
        target, beforeSnapshot
    )
    if not identityStillCurrent then
        lockCommittedFailure(identityReason, "post_reservation_identity")
        return false
    end
    local missionId, missionParam, contextError = self:ConfigureSaleContext(
        target, beforeSnapshot
    )
    if not missionId then
        lockCommittedFailure(contextError, "context")
        return false
    end
    Logger:Info("SovereignInventory", string.format(
        "%s sale phase=context_configured missionId=%s missionParam=%s",
        tostring(target.name), tostring(missionId), tostring(missionParam)
    ))
    identityStillCurrent, identityReason = self:IsSaleIdentityCurrent(
        target, beforeSnapshot
    )
    if not identityStillCurrent then
        lockCommittedFailure(identityReason, "pre_dispatch_identity")
        return false
    end
    if type(pending.monitor) == "table" then
        pending.monitor.dispatchFrame = self:GetCurrentGameFrame()
    end
    local missionSent, missionUncertain, dispatchReason = self:DispatchSaleMission(
        missionId, missionParam,
        function()
            return self:IsSaleIdentityCurrent(target, beforeSnapshot)
        end
    )
    if not missionSent or missionUncertain then
        lockCommittedFailure(
            dispatchReason or (missionUncertain and "sale_dispatch_uncertain"
                or "sale_dispatch_failed"),
            "dispatch"
        )
        return false
    end
    Logger:Info("SovereignInventory", string.format(
        "%s sale phase=dispatch_sent missionId=%s",
        tostring(target.name), tostring(missionId)
    ))
    pending = self.pendingSaleReservation[latchKey]
    if type(pending) == "table" and type(pending.monitor) == "table" then
        pending.monitor.dispatchSent = true
    end
    local started, scriptName = self:WaitForSaleStart(
        target, missionId, beforeSnapshot
    )
    if not started then
        lockCommittedFailure(
            self.lastSaleCompletionError or "sale_script_not_started", "launch"
        )
        return false
    end
    pending = self.pendingSaleReservation[latchKey]
    if type(pending) ~= "table" then
        lockCommittedFailure("sale_settlement_state_lost", "mission_started")
        return false
    end
    pending.phase = "mission_started"
    pending.script = scriptName
    if not self:UpdateSaleMissionObservation(
        target, pending.monitor, scriptName, beforeSnapshot
    ) then
        local monitor = pending.monitor
        lockCommittedFailure(
            (type(monitor) == "table" and monitor.missionIdentityReason)
                or self.lastSaleCompletionError
                or "sale_mission_evidence_unavailable",
            "mission_evidence"
        )
        return false
    end
    if not self.autoCompleteSale then
        self:Notify(target.name .. "Sale mission started", "info")
        self:StartPendingSaleSettlementProbe(latchKey)
        return true
    end
    if not self:SupportsAutomaticSaleCompletion(target, scriptName) then
        self.lastSaleCompletionError = "office_completion_layout_unverified"
        pending.phase = "manual_completion"
        self:Notify(
            target.name .. "Sale mission started. Complete it manually",
            "info"
        )
        self:StartPendingSaleSettlementProbe(latchKey)
        return true
    end
    self:Notify(target.name .. "Automatic sale in progress", "info")
    pending.settlementWaitActive = true
    local completionSucceeded = self:CompleteSaleMission(
        target, scriptName, beforeSnapshot, pending.monitor
    )
    if self.pendingSaleReservation[latchKey] == pending then
        pending.settlementWaitActive = false
    end
    if completionSucceeded then
        local completedPending = self.pendingSaleReservation[latchKey]
        local completedEvidence = self.lastSaleSettlement
        self:FinalizePendingSaleSettlement(
            latchKey, completedPending, completedEvidence
        )
        if self.continueAutoSell then
            self.lastAutoSell = os.clock() - self.autoSellCooldown
        else
            self.lastAutoSell = os.clock()
        end
        return true
    end
    local failureReason = self.lastSaleCompletionError or "sale_settlement_timeout"
    lockCommittedFailure(failureReason, "settlement")
    Logger:Warn("SovereignInventory", string.format(
        "%s automatic sale incomplete reason=%s script=%s",
        tostring(target.name), tostring(failureReason),
        tostring(scriptName or "not_detected")
    ))
    return false
end

function SovereignBusinessInventory:StartDirectSale(target, manual)
    if type(target) ~= "table" then return false end
    local latchKey = tostring(target.latchKey or target.key)
    if self.activeSaleAttemptId ~= nil then
        if manual then self:Notify("Another automatic sale attempt is still settling", "warning") end
        return false
    end
    if self.saleQuarantine[latchKey] then
        if manual then self:Notify(self:GetSaleErrorText("sale_manual_review_locked"), "warning") end
        return false
    end
    if os.clock() < (tonumber(self.saleGlobalQuietUntil) or 0) then
        if manual then self:Notify(self:GetSaleErrorText("sale_quarantine_cooldown"), "warning") end
        return false
    end
    if os.clock() < (tonumber(self.saleTransactionAlertBackoffUntil) or 0) then
        if manual then
            self:Notify(self:GetSaleErrorText("transaction_alert_blocked"), "warning")
        end
        return false
    end
    if self.saleRejectedKeys[latchKey] then
        if manual then self:Notify(self:GetSaleErrorText("sale_rejected_locked"), "warning") end
        return false
    end
    local accessOk, accessReason = self:CheckSaleAccess(target)
    if not accessOk then
        if manual then self:Notify(self:GetSaleErrorText(accessReason), "warning") end
        return false
    end
    if type(self.pendingRefillTransactions) == "table"
        and next(self.pendingRefillTransactions) ~= nil then
        self:ProcessPendingRefillTransactions()
        if next(self.pendingRefillTransactions) ~= nil then
            if manual then self:Notify("Restock unconfirmed; sale not started", "warning") end
            return false
        end
    end
    local otherPendingKey = type(self.pendingSaleReservation) == "table"
        and next(self.pendingSaleReservation) or nil
    if otherPendingKey ~= nil and otherPendingKey ~= latchKey then
        if manual then self:Notify("Another sale is settling. Please wait", "warning") end
        return false
    end
    local pending = self.pendingSaleReservation[latchKey]
    if type(pending) == "table" then
        local probeOwnsSettlement = pending.probeStarted == true
            and self.saleSettlementProbeTokens[latchKey] == pending.probeToken
        if pending.settlementWaitActive ~= true and not probeOwnsSettlement then
            self:StartPendingSaleSettlementProbe(latchKey)
        end
        if manual then
            self:Notify(
                "Sale result unconfirmed. Do not repeat the action",
                "warning"
            )
        end
        return false
    end
    if self.transactionBusy or self.saleLaunchBusy then
        if manual then self:Notify("An inventory operation is being processed", "warning") end
        return false
    end
    if self:GetRunningSaleScript(self.saleMissionScripts) then
        if manual then self:Notify("A sale mission is already in progress", "warning") end
        return false
    end
    if self:GetRunningSaleScript(self.saleAppScripts) then
        if manual then self:Notify("Close the current management terminal first", "warning") end
        return false
    end
    if not Script or type(Script.QueueJob) ~= "function" then
        if manual then self:Notify("Cannot start a sale mission right now", "error") end
        return false
    end

    self.operationQueue = self.operationQueue or {}
    self.operationQueueSerial = (self.operationQueueSerial or 0) + 1
    local operationId = self.operationQueueSerial
    self.saleAttemptSerial = (self.saleAttemptSerial or 0) + 1
    local attemptId = self.saleAttemptSerial
    self.activeSaleAttemptId = attemptId
    self.operationQueue[operationId] = {
        kind = "sale", remaining = 1, active = false, attemptId = attemptId
    }
    self.saleLaunchBusy = true
    local job = function()
        local operation = self.operationQueue[operationId]
        if self.activeSaleAttemptId ~= attemptId then
            self.operationQueue[operationId] = nil
            self.saleLaunchBusy = false
            return
        end
        if operation and operation.cancelled then
            self.operationQueue[operationId] = nil
            self.saleLaunchBusy = false
            self.activeSaleAttemptId = nil
            return
        end
        if operation then operation.active = true; operation.remaining = 0 end
        local reservationCommitted = false
        local beforeSnapshot = nil
        local selectorState = nil
        local continueAfterSelector
        local function retryBeforeCommit()
            self.saleLatch[latchKey] = nil
            self.saleLatchType[latchKey] = nil
            self.pendingSaleReservation[latchKey] = nil
            self.saleSettlementProbeTokens[latchKey] = nil
            -- A failed pre-commit attempt must wait the full configured
            -- interval. The transaction layer may release its shared basket
            -- several frames after the local call has returned.
            self.lastAutoSell = os.clock()
        end
        local function lockCommittedFailure(
            reason, phase, transactionContext, saleContinuation, savedSelectorState
        )
            reservationCommitted = true
            self.saleLatch[latchKey] = true
            if beforeSnapshot and beforeSnapshot.saleType then
                self.saleLatchType[latchKey] = beforeSnapshot.saleType
            end
            local existing = self.pendingSaleReservation[latchKey]
            local effectiveSelectorState = type(savedSelectorState) == "table"
                and savedSelectorState
                or (type(existing) == "table" and existing.selectorState or nil)
            local effectiveContinuation = type(saleContinuation) == "function"
                and saleContinuation
                or (type(existing) == "table"
                    and type(existing.saleContinuation) == "function"
                    and effectiveSelectorState
                    and effectiveSelectorState.completed ~= true
                    and existing.saleContinuation or nil)
            local replacement = {
                target = target,
                before = beforeSnapshot,
                monitor = type(existing) == "table" and existing.monitor
                    or self:CreateSaleSettlementMonitor(beforeSnapshot),
                reason = reason,
                phase = phase or "committed_failure",
                at = os.clock(),
                probeStarted = type(existing) == "table"
                    and existing.probeStarted == true,
                probeToken = type(existing) == "table" and existing.probeToken or nil,
                probeRetryAt = type(existing) == "table" and existing.probeRetryAt or nil,
                transactionContext = transactionContext
                    or (type(existing) == "table" and existing.transactionContext or nil),
                transactionCleanupAttempts = type(existing) == "table"
                    and existing.transactionCleanupAttempts or 0,
                transactionCleanupNextAt = type(existing) == "table"
                    and existing.transactionCleanupNextAt or os.clock(),
                saleContinuation = effectiveContinuation,
                continuationQueued = false,
                selectorState = effectiveSelectorState,
                selectorAccepted = type(effectiveSelectorState) == "table"
                    and effectiveSelectorState.selectorAccepted == true,
                selectorPhase = type(effectiveSelectorState) == "table"
                    and effectiveSelectorState.phase or nil,
                selectorRetryAt = type(effectiveSelectorState) == "table"
                    and effectiveSelectorState.retryAt or nil
            }
            self.pendingSaleReservation[latchKey] = replacement
            self.lastAutoSell = os.clock()
            Logger:Warn("SovereignInventory", string.format(
                "%s submitted sale locked phase=%s reason=%s",
                tostring(target.name), tostring(phase), tostring(reason)
            ))
            self:Notify(
                self:GetSaleErrorText(reason),
                "warning"
            )
            local preMissionFailure = phase == "reservation_post_commit"
                or phase == "selector_resume"
                or phase == "post_reservation_identity"
                or phase == "context"
                or phase == "pre_dispatch_identity"
            if preMissionFailure and type(transactionContext) ~= "table"
                and type(effectiveContinuation) ~= "function" then
                self:QuarantinePendingSale(latchKey, replacement, reason)
                return
            end
            self:StartPendingSaleSettlementProbe(latchKey)
        end
        local function continueAfterReservation()
            reservationCommitted = true
            return self:ContinueAcceptedSaleReservation(
                target, beforeSnapshot, latchKey, lockCommittedFailure
            )
        end
        continueAfterSelector = function()
            reservationCommitted = true
            local selectorReady, selectorReason
            selectorReady, selectorReason, selectorState =
                self:CompleteAcceptedSaleSelector(
                target, beforeSnapshot, nil, selectorState
            )
            if not selectorReady then
                local retryContinuation = nil
                local retryCount = type(selectorState) == "table"
                    and math.floor(tonumber(selectorState.retryCount) or 0) or 0
                local retryAge = type(selectorState) == "table"
                    and (os.clock() - (tonumber(selectorState.startedAt) or os.clock()))
                    or rawget(math, "huge")
                if type(selectorState) == "table"
                    and selectorState.retryable == true
                    and selectorState.finalizerInvoked ~= true
                    and retryCount < 8 and retryAge < 30.0 then
                    selectorState.retryCount = retryCount + 1
                    selectorState.retryAt = os.clock() + math.min(
                        5.0, 0.5 * (2 ^ math.min(3, selectorState.retryCount - 1))
                    )
                    retryContinuation = continueAfterSelector
                elseif type(selectorState) == "table"
                    and selectorState.retryable == true then
                    selectorState.retryable = false
                    selectorState.terminal = true
                    selectorState.reason = "sale_settlement_timeout"
                    selectorReason = "sale_settlement_timeout"
                end
                lockCommittedFailure(
                    selectorReason or "reservation_state_unavailable",
                    "selector_resume", nil, retryContinuation, selectorState
                )
                return false
            end
            return continueAfterReservation()
        end
        local okJob, jobError = xpcall(function()
            if self.transactionBusy
                or next(self.pendingRefillTransactions or {}) ~= nil
                or next(self.pendingSaleReservation or {}) ~= nil
                or self:GetRunningSaleScript(self.saleMissionScripts)
                or self:GetRunningSaleScript(self.saleAppScripts) then
                retryBeforeCommit()
                self:Notify("Another inventory operation is in progress; sale not started", "warning")
                return
            end
            local currentAccess, currentAccessReason = self:CheckSaleAccess(target)
            if not currentAccess then
                retryBeforeCommit()
                self:Notify(self:GetSaleErrorText(currentAccessReason), "warning")
                return
            end
            local transactionAlertBefore = self:ReadSaleTransactionAlertSnapshot()
            if transactionAlertBefore.supported ~= false
                and (transactionAlertBefore.readable ~= true
                or transactionAlertBefore.anyActive == true) then
                local alertReason = transactionAlertBefore.readable == true
                    and "transaction_alert_blocked"
                    or "transaction_alert_state_unavailable"
                retryBeforeCommit()
                self.saleTransactionAlertBackoffUntil = os.clock() + 60.0
                self.saleTransactionAlertLast = transactionAlertBefore.activeName
                self.lastAutoSell = os.clock()
                Logger:Warn("SovereignInventory", string.format(
                    "%s sale blocked before preflight alert=%s readable=%s",
                    tostring(target.name), tostring(transactionAlertBefore.activeName),
                    tostring(transactionAlertBefore.readable)
                ))
                if manual then
                    self:Notify(self:GetSaleErrorText(alertReason), "warning")
                end
                return
            end
            local preflightError
            beforeSnapshot, preflightError = self:GetSalePreflightSnapshot(target, true)
            if not beforeSnapshot then
                retryBeforeCommit()
                if preflightError == "sale_income_identity_unavailable" and not manual then
                    self.saleIncomeIdentityBackoffUntil = os.clock() + 60.0
                    self.lastAutoSell = os.clock()
                end
                Logger:Warn("SovereignInventory", string.format(
                    "%s sale preflight failed reason=%s",
                    tostring(target.name), tostring(preflightError)
                ))
                self:Notify(self:GetSaleErrorText(preflightError), "error")
                return
            end
            Logger:Info("SovereignInventory", string.format(
                "%s sale preflight persistent=%d live=%d bank=%d wallet=%d",
                tostring(target.name), beforeSnapshot.persistent, beforeSnapshot.live,
                beforeSnapshot.money.bank, beforeSnapshot.money.wallet
            ))
            beforeSnapshot.saleAttemptId = attemptId
            local reserved, reserveError, committed, reservationCleanupContext,
                returnedSelectorState =
                self:SubmitSaleReservation(
                target, beforeSnapshot
            )
            if type(returnedSelectorState) == "table" then
                selectorState = returnedSelectorState
            end
            reservationCommitted = committed == true
            local transactionAlertName, transactionAlertAfter =
                self:GetNewSaleTransactionAlert(transactionAlertBefore)
            local transactionAlertStateUnavailable = type(transactionAlertAfter) == "table"
                and transactionAlertAfter.supported ~= false
                and transactionAlertAfter.readable ~= true
            if transactionAlertName or transactionAlertStateUnavailable then
                self.saleTransactionAlertBackoffUntil = os.clock() + 60.0
                self.saleTransactionAlertLast = transactionAlertName
                Logger:Warn("SovereignInventory", string.format(
                    "%s sale transaction alert=%s readable=%s committed=%s reserved=%s",
                    tostring(target.name), tostring(transactionAlertName),
                    tostring(not transactionAlertStateUnavailable),
                    tostring(reservationCommitted), tostring(reserved == true)
                ))
                reserveError = transactionAlertStateUnavailable
                    and "transaction_alert_state_unavailable"
                    or "transaction_alert_blocked"
                if reserved then
                    reservationCommitted = true
                    lockCommittedFailure(
                        reserveError, "reservation_post_commit",
                        reservationCleanupContext, nil, selectorState
                    )
                    return
                end
            end
            if not reserved then
                Logger:Warn("SovereignInventory", string.format(
                    "%s sale reservation failed reason=%s committed=%s",
                    tostring(target.name), tostring(reserveError),
                    tostring(reservationCommitted)
                ))
                if reservationCommitted then
                    if type(reservationCleanupContext) == "table"
                        and reservationCleanupContext.resumeSaleAfterSelector == true then
                        reservationCleanupContext.saleContinuation = continueAfterSelector
                    end
                    local retryContinuation = nil
                    if type(reservationCleanupContext) == "table"
                        and reservationCleanupContext.resumeSaleAfterSelector == true then
                        retryContinuation = continueAfterSelector
                    elseif type(selectorState) == "table"
                        and selectorState.retryable == true
                        and selectorState.finalizerInvoked ~= true then
                        selectorState.startedAt = tonumber(selectorState.startedAt)
                            or os.clock()
                        local retryCount = math.floor(
                            tonumber(selectorState.retryCount) or 0
                        )
                        if retryCount < 8 then
                            selectorState.retryCount = retryCount + 1
                            selectorState.retryAt = os.clock() + 0.5
                            retryContinuation = continueAfterSelector
                        else
                            selectorState.retryable = false
                            selectorState.terminal = true
                            selectorState.reason = "sale_settlement_timeout"
                            reserveError = "sale_settlement_timeout"
                        end
                    end
                    lockCommittedFailure(
                        reserveError, "reservation_post_commit",
                        reservationCleanupContext, retryContinuation, selectorState
                    )
                elseif reserveError == "transaction_rejected"
                    or reserveError == "transaction_alert_blocked"
                    or reserveError == "transaction_alert_state_unavailable" then
                    self.saleRejectedKeys[latchKey] = true
                    self.saleLatch[latchKey] = true
                    self.lastAutoSell = os.clock()
                    self:Notify(self:GetSaleErrorText(reserveError), "warning")
                else
                    retryBeforeCommit()
                    self:Notify(self:GetSaleErrorText(reserveError), "error")
                end
                return
            end
            continueAfterReservation()
        end, debug.traceback)
        self.saleLaunchBusy = false
        self.operationQueue[operationId] = nil
        if self.activeSaleAttemptId == attemptId then
            self.activeSaleAttemptId = nil
        end
        if not okJob then
            Logger:Error("SovereignInventory", tostring(jobError))
            if reservationCommitted then
                lockCommittedFailure("sale_runtime_exception", "exception")
            else
                retryBeforeCommit()
                self:Notify("Automatic sale could not start", "error")
            end
        end
    end
    local okQueue, queued = pcall(Script.QueueJob, job)
    if not okQueue or queued == false then
        self.operationQueue[operationId] = nil
        self.saleLaunchBusy = false
        if self.activeSaleAttemptId == attemptId then
            self.activeSaleAttemptId = nil
        end
        if manual then self:Notify("Sale mission could not be queued", "error") end
        return false
    end
    return true
end

function SovereignBusinessInventory:TriggerSaleCheck(now, manual)
    now = tonumber(now) or os.clock()
    if now < (tonumber(self.saleGlobalQuietUntil) or 0) then
        if manual then self:Notify(self:GetSaleErrorText("sale_quarantine_cooldown"), "warning") end
        return false
    end
    local organization = self:GetLocalOrganizationState()
    local allowRegistration = self.autoOrganizationAssist == true
    local roleNeedsSelection = organization.valid ~= true
    if organization.valid == true then
        if self.autoSellScope == 1 and organization.role ~= "mc_president" then
            roleNeedsSelection = true
        elseif self.autoSellScope == 2 and organization.role ~= "ceo" then
            roleNeedsSelection = true
        elseif self.autoSellScope == 3
            and organization.role ~= "mc_president" and organization.role ~= "ceo" then
            roleNeedsSelection = true
        end
    end
    local allowUnregistered = allowRegistration and roleNeedsSelection
    if organization.valid ~= true and not allowRegistration then
        if manual then
            self:Notify(self:GetSaleErrorText(
                organization.error or "local_player_unavailable"
            ), "warning")
        end
        return false
    end
    if manual and not allowRegistration and self.autoSellScope == 1 and organization.role ~= "mc_president" then
        self:Notify(self:GetSaleErrorText("mc_president_required"), "warning")
        return false
    end
    if manual and not allowRegistration and self.autoSellScope == 2 and organization.role ~= "ceo" then
        self:Notify(self:GetSaleErrorText("ceo_required"), "warning")
        return false
    end
    if manual and not allowRegistration and self.autoSellScope == 3
        and organization.role ~= "mc_president" and organization.role ~= "ceo" then
        self:Notify("This sale scope requires an MC President or CEO", "warning")
        return false
    end
    if manual then
        local debounce = math.max(0.5, tonumber(self.manualSaleDebounce) or 2.0)
        if now - (tonumber(self.lastManualSaleAttempt) or -1000) < debounce then
            self:Notify("Sale request is processing. Do not trigger it repeatedly", "warning")
            return false
        end
        self.lastManualSaleAttempt = now
    end
    if not manual and now - (self.lastAutoSell or 0) < self.autoSellCooldown then return false end
    -- Select from inventory evidence first. This is required when the local
    -- freemode organization record is absent: role-gated collection would
    -- otherwise return no target and never reach EnsureOrganizationRole.
    local target = self:SelectSaleTarget(manual == true, allowUnregistered)
    -- With an active role, prefer its own target first. Only if that role has
    -- no threshold-ready business do we inspect the other role's inventory.
    if not target and allowRegistration and self.autoSellScope == 3
        and organization.valid == true then
        target = self:SelectSaleTarget(manual == true, true)
        allowUnregistered = target ~= nil
    end
    if not target then
        if manual then self:Notify("No businesses in this scope meet the sale threshold", "info") end
        return false
    end
    local requiredRole = target.key == "biker" and "mc_president"
        or target.key == "warehouse" and "ceo" or nil
    if requiredRole ~= nil
        and (organization.valid ~= true or organization.role ~= requiredRole) then
        if not allowRegistration then
            if manual then
                self:Notify(self:GetSaleErrorText(
                    requiredRole == "ceo" and "ceo_required" or "mc_president_required"
                ), "warning")
            end
            return false
        end
        local roleOk, roleOrReason = self:EnsureOrganizationRole(requiredRole)
        if not roleOk then
            if manual then self:Notify(self:GetSaleErrorText(roleOrReason), "warning") end
            return false
        end
        organization = roleOrReason
        -- Registration can change which scope is readable. Rebuild the target
        -- list after convergence instead of launching with stale role data.
        target = self:SelectSaleTarget(manual == true, false)
        if not target then
            if manual then self:Notify("No businesses in this scope meet the sale threshold", "info") end
            return false
        end
    end
    return self:StartDirectSale(target, manual == true)
end

function SovereignBusinessInventory:ProcessPendingSaleSettlements(now)
    now = tonumber(now) or os.clock()
    if self.saleLaunchBusy then return end
    if now - (tonumber(self.lastPendingSaleCheck) or 0) < 0.25 then return end
    self.lastPendingSaleCheck = now
    for latchKey, pending in pairs(self.pendingSaleReservation or {}) do
        if type(pending) == "table" and type(pending.target) == "table"
            and type(pending.before) == "table" then
            local probeOwnsSettlement = pending.probeStarted == true
                and self.saleSettlementProbeTokens[latchKey] == pending.probeToken
            if pending.settlementWaitActive ~= true and not probeOwnsSettlement then
                local cleanupOk = self:EnsurePendingSaleTransactionCleanup(pending)
                if not cleanupOk then
                    -- Keep the accepted reservation locked; do not let a
                    -- stale/foreign slot be mistaken for a completed sale.
                    pending.probeRetryAt = math.max(
                        tonumber(pending.probeRetryAt) or 0, now + 0.5
                    )
                else
                    local settled, evidence
                    settled, evidence, _, pending.monitor = self:ObserveSaleSettlement(
                        pending.target, pending.before, pending.monitor
                    )
                    if settled then
                        self:FinalizePendingSaleSettlement(latchKey, pending, evidence)
                    elseif self:ShouldQuarantinePendingSale(pending, now) then
                        self:QuarantinePendingSale(latchKey, pending)
                    else
                        self:StartPendingSaleSettlementProbe(latchKey)
                    end
                end
            end
        end
    end
end

function SovereignBusinessInventory:ProcessSaleQuarantines(now)
    now = tonumber(now) or os.clock()
    local pollInterval = math.max(
        1.0, tonumber(self.saleQuarantinePollInterval) or 2.0
    )
    if now - (tonumber(self.lastSaleQuarantineCheck) or 0) < pollInterval then return end
    self.lastSaleQuarantineCheck = now
    for latchKey, quarantine in pairs(self.saleQuarantine or {}) do
        if type(quarantine) == "table" and type(quarantine.target) == "table"
            and type(quarantine.before) == "table" then
            -- A quarantined object may still own an unpublished freemode
            -- descriptor. Finish that exact local cleanup before any passive
            -- sale observation or reconciliation timeout is allowed to run.
            local cleanupReady = true
            local transactionContext = quarantine.transactionContext
            if type(transactionContext) == "table" then
                local cleanupNextAt = tonumber(quarantine.transactionCleanupNextAt) or 0
                if now < cleanupNextAt then
                    cleanupReady = false
                else
                    local settled, cleanupReason = self:EnsureFreemodeTransactionSettled(
                        transactionContext
                    )
                    if not settled then
                        local cleanupAttempts = math.floor(
                            tonumber(quarantine.transactionCleanupAttempts) or 0
                        ) + 1
                        quarantine.transactionCleanupAttempts = cleanupAttempts
                        quarantine.transactionCleanupNextAt = now + math.min(
                            30.0, 0.5 * (2 ^ math.min(6, cleanupAttempts - 1))
                        )
                        quarantine.reason = cleanupReason
                            or "transaction_cleanup_unconfirmed"
                        quarantine.lastTransactionCleanupReason = quarantine.reason
                        cleanupReady = false
                    else
                        quarantine.transactionContext = nil
                        quarantine.transactionCleanupResolvedAt = now
                        quarantine.lastTransactionCleanupReason = cleanupReason
                        local safeLocalUnlock = quarantine.unlockAfterLocalCleanup == true
                            and transactionContext.localOnlyCleanup == true
                            and transactionContext.outcomePending ~= true
                            and transactionContext.outcomeAbandoned ~= true
                            and transactionContext.serverAccepted ~= true
                            and transactionContext.serverRejected ~= true
                        if not safeLocalUnlock then
                            -- Cleanup can consume most of the original quarantine
                            -- window. Give the server-owned outcome one bounded
                            -- post-cleanup observation window before expiry.
                            quarantine.postCleanupObservationPending = true
                            quarantine.nextReconcileAt = now
                            quarantine.reconciliationExpiresAt = math.max(
                                tonumber(quarantine.reconciliationExpiresAt) or 0,
                                now + 60.0
                            )
                            quarantine.reconciliationStopped = false
                        end
                        if safeLocalUnlock
                            and self.saleQuarantine[latchKey] == quarantine then
                            self.saleQuarantine[latchKey] = nil
                            self.saleLatch[latchKey] = nil
                            self.saleLatchType[latchKey] = nil
                            self.saleRejectedKeys[latchKey] = nil
                            self.saleSettlementProbeTokens[latchKey] = nil
                            self.lastAutoSell = now
                            if next(self.saleQuarantine or {}) == nil
                                and next(self.pendingSaleReservation or {}) == nil
                                and (tonumber(self.saleGlobalQuietUntil) or 0)
                                    <= (tonumber(quarantine.quarantineQuietUntil)
                                        or rawget(math, "huge")) then
                                self.saleGlobalQuietUntil = math.max(
                                    now,
                                    tonumber(quarantine.priorSaleGlobalQuietUntil) or 0
                                )
                            end
                            Logger:Info("SovereignInventory", string.format(
                                "%s unpublished quarantined transaction cleanup completed; sale retry unlocked",
                                tostring(quarantine.target.name)
                            ))
                            self:Notify(
                                tostring(quarantine.target.name or "Business")
                                    .. "Sale did not start. You can try again now",
                                "info"
                            )
                        elseif transactionContext.outcomeAbandoned == true then
                            quarantine.transactionOutcomeAbandoned = true
                        end
                    end
                end
            end
            if self.saleQuarantine[latchKey] == quarantine and cleanupReady
                and quarantine.reconciliationStopped ~= true then
                local expiresAt = tonumber(quarantine.reconciliationExpiresAt)
                    or ((tonumber(quarantine.at) or now)
                        + math.max(60.0,
                            tonumber(self.saleQuarantineReconcileWindow) or 300.0))
                quarantine.reconciliationExpiresAt = expiresAt
                local observationDue = quarantine.postCleanupObservationPending == true
                    or (now < expiresAt
                        and now >= (tonumber(quarantine.nextReconcileAt) or 0))
                if observationDue then
                    quarantine.postCleanupObservationPending = false
                    quarantine.nextReconcileAt = now + pollInterval
                    local settled, evidence, reason
                    settled, evidence, reason, quarantine.monitor = self:ObserveSaleSettlement(
                        quarantine.target, quarantine.before, quarantine.monitor
                    )
                    quarantine.lastEvidence = evidence
                    quarantine.lastEvidenceReason = reason
                    if settled and self.saleQuarantine[latchKey] == quarantine then
                        self.saleQuarantine[latchKey] = nil
                        self.saleLatch[latchKey] = true
                        self.saleLatchType[latchKey] = evidence.saleType
                        self.lastSaleSettlement = evidence
                        pcall(function() self:RefreshData() end)
                        Logger:Info("SovereignInventory", string.format(
                            "%s quarantined sale proved by passive reconciliation stock=%s/%s->%s/%s money=%s->%s accepted=%s",
                            tostring(quarantine.target.name),
                            tostring(evidence.beforePersistent), tostring(evidence.beforeLive),
                            tostring(evidence.afterPersistent), tostring(evidence.afterLive),
                            tostring(evidence.beforeMoney), tostring(evidence.afterMoney),
                            tostring(evidence.acceptedAmount)
                        ))
                        self:Notify(
                            tostring(quarantine.target.name or "Business")
                                .. "Sale completed",
                            "success"
                        )
                    elseif reason == "sale_identity_changed"
                        or reason == "sale_organization_mismatch"
                        or reason == "sale_mission_generation_changed"
                        or reason == "sale_settlement_window_expired" then
                        quarantine.reconciliationStopped = true
                        Logger:Warn("SovereignInventory", string.format(
                            "%s passive quarantine reconciliation stopped reason=%s",
                            tostring(quarantine.target.name), tostring(reason)
                        ))
                    end
                end
                if self.saleQuarantine[latchKey] == quarantine
                    and quarantine.reconciliationStopped ~= true
                    and quarantine.postCleanupObservationPending ~= true
                    and now >= expiresAt then
                    quarantine.reconciliationStopped = true
                    quarantine.lastEvidenceReason = quarantine.lastEvidenceReason
                        or "sale_settlement_timeout"
                    Logger:Warn("SovereignInventory", string.format(
                        "%s passive quarantine reconciliation expired reason=%s",
                        tostring(quarantine.target.name),
                        tostring(quarantine.lastEvidenceReason)
                    ))
                end
            end
        end
    end
end

function SovereignBusinessInventory:ProcessPendingRefillTransactions()
    for _, pending in pairs(self.pendingRefillTransactions or {}) do
        if type(pending) == "table" and type(pending.request) == "table" then
            local name = tostring(pending.request.name or pending.request.kind)
            if self:ReconcilePendingRefill(pending.request) then
                self:Notify(name .. "Restock completed", "success")
            end
        end
    end
end

function SovereignBusinessInventory:ProcessRefillQuarantines(now)
    if self.transactionBusy or self.saleLaunchBusy
        or next(self.pendingSaleReservation or {}) ~= nil
        or self:GetRunningSaleScript(self.saleMissionScripts) then
        return
    end
    now = tonumber(now) or os.clock()
    for key, pending in pairs(self.refillQuarantine or {}) do
        local cleanupReady = true
        if type(pending) == "table" and type(pending.transactionContext) == "table" then
            cleanupReady = self:EnsurePendingRefillTransactionCleanup(pending) == true
        end
        if self.refillQuarantine[key] == pending and cleanupReady
            and type(pending) == "table" and pending.transactionAccepted == true
            and type(pending.request) == "table"
            and now >= (tonumber(pending.repairNextAt) or 0) then
            local identityOk = self:IsPendingRefillIdentityCurrent(pending)
            if identityOk then
                self.refillQuarantine[key] = nil
                self.refillRejectedKeys[key] = nil
                pending.quarantinedAt = nil
                pending.reason = "accepted_refill_repair_pending"
                self.pendingRefillTransactions[key] = pending
                local reconciled = self:ReconcilePendingRefill(pending.request)
                if reconciled then
                    self:Notify(
                        tostring(pending.request.name or pending.request.kind)
                            .. "Restock completed",
                        "success"
                    )
                end
                -- Repair one accepted operation at a time; each may write stats
                -- and must finish its own readback before another is resumed.
                return
            end
        end
    end
end

function SovereignBusinessInventory:ProcessAutomaticSell(now)
    if not self.autoSell or self.transactionBusy or self.saleLaunchBusy then return end
    if (tonumber(now) or os.clock()) < (tonumber(self.saleGlobalQuietUntil) or 0) then return end
    if (tonumber(now) or os.clock()) < (tonumber(self.saleIncomeIdentityBackoffUntil) or 0) then return end
    if (tonumber(now) or os.clock()) < (tonumber(self.saleTransactionAlertBackoffUntil) or 0) then return end
    if self.activeSaleAttemptId ~= nil then return end
    if next(self.pendingRefillTransactions or {}) ~= nil then return end
    if next(self.pendingSaleReservation or {}) ~= nil then return end
    self:TriggerSaleCheck(now, false)
end

function SovereignBusinessInventory:ProcessAutomaticRestock(now)
    if not self.autoRestock then return end
    if self.transactionBusy then return end
    if now < (tonumber(self.restockBackoffUntil) or 0) then return end
    if now - (self.lastAutoRestock or 0) < self.autoRestockInterval then return end
    self.lastAutoRestock = now
    local requests = {}
    local organization = self:GetLocalOrganizationState()
    local allowRoleRegistration = self.autoOrganizationAssist == true
    local canUseMcBusinesses = organization.role == "mc_president"
        or allowRoleRegistration
    local canUseBossBusinesses = organization.isBoss == true
        or allowRoleRegistration
    for index, entry in ipairs(self.data.factories or {}) do
        local needsRefill = type(entry.supply) ~= "number"
            or entry.supply <= self.restockThreshold
        local hasAccess = (index <= 5 and canUseMcBusinesses)
            or (index >= 6 and canUseBossBusinesses)
        if entry.owned and needsRefill and hasAccess then
            requests[#requests + 1] = {
                kind = "factory", index = index, target = 100, name = entry.name
            }
        end
    end
    for index, entry in ipairs(self.data.nightclub or {}) do
        local current = tonumber(entry.value)
        local capacity = tonumber(entry.max)
        if canUseBossBusinesses and current and capacity and capacity > 0 and current < capacity
            and (current * 100 / capacity) <= self.restockThreshold then
            requests[#requests + 1] = {
                kind = "nightclub", index = index, target = capacity, name = entry.name
            }
        end
    end
    local hangar = tonumber(self.data.hangar)
    local hangarMax = tonumber(self.data.hangarMax) or 50
    if canUseBossBusinesses and type(self.data.hangarOwned) == "number" and self.data.hangarOwned ~= 0
        and hangar and hangarMax > 0 and hangar < hangarMax
        and (hangar * 100 / hangarMax) <= self.restockThreshold then
        requests[#requests + 1] = {
            kind = "hangar", target = hangarMax, name = "Hangar cargo"
        }
    end
    local canUseWarehouses = (organization.role == "ceo" or allowRoleRegistration)
        and self:GetOwnedWarehouseCount() > 0
    if not self.warehouseRefillRejected and canUseWarehouses then
        for index, entry in ipairs(self.data.warehouses or {}) do
            local current = tonumber(entry.value) or 0
            local capacity = tonumber(entry.max) or 0
            if entry.owned and capacity > 0 and current < capacity
                and (current * 100 / capacity) <= self.restockThreshold then
                requests[#requests + 1] = {
                    kind = "warehouse", index = index, target = capacity, name = entry.name,
                    cargoType = self.selectedWarehouseCargo
                }
            end
        end
    end
    if #requests > 0 then
        self:QueueRefillRequests(requests, "Automatic restock completed")
    end
end

function SovereignBusinessInventory:UpdateAlerts()
    if not self.alertEnabled then return end
    local lowNames, fullNames = {}, {}
    for index, entry in ipairs(self.data.factories or {}) do
        local state = self.alertState[index] or {low = false, full = false}
        self.alertState[index] = state
        if not entry.owned then
            state.low = false
            state.full = false
        else
            local low = not self.autoRestock
                and type(entry.supply) == "number"
                and entry.supply <= self.restockThreshold
            local full = type(entry.product) == "number"
                and type(entry.maxProduct) == "number"
                and entry.product >= entry.maxProduct
            if low and not state.low then lowNames[#lowNames + 1] = entry.name end
            if full and not state.full then fullNames[#fullNames + 1] = entry.name end
            state.low = low
            state.full = full
        end
    end

    for index, entry in ipairs(self.data.nightclub or {}) do
        local key = "nightclub_" .. tostring(index)
        local state = self.alertState[key] or {full = false}
        self.alertState[key] = state
        local full = entry.max and entry.max > 0
            and type(entry.value) == "number"
            and entry.value >= entry.max
        if full and not state.full then fullNames[#fullNames + 1] = entry.name end
        state.full = full
    end

    local special = {
        {key = "hangar", name = "Hangar cargo", value = self.data.hangar, max = self.data.hangarMax},
        {key = "nightclubSafe", name = "Nightclub safe", value = self.data.nightclubSafe, max = self.data.nightclubSafeMax},
        {key = "arcadeSafe", name = "Arcade safe", value = self.data.arcadeSafe, max = self.data.arcadeSafeMax}
    }
    for _, entry in ipairs(special) do
        local state = self.alertState[entry.key] or {full = false}
        self.alertState[entry.key] = state
        local full = type(entry.value) == "number"
            and type(entry.max) == "number"
            and entry.value >= entry.max
        if full and not state.full then fullNames[#fullNames + 1] = entry.name end
        state.full = full
    end

    if #lowNames == 1 then
        self:Notify(lowNames[1] .. "Low supplies", "warning")
    elseif #lowNames == 2 then
        self:Notify(table.concat(lowNames, "、") .. "Low supplies", "warning")
    elseif #lowNames > 2 then
        self:Notify(tostring(#lowNames) .. " businesses have low supplies", "warning")
    end
    if #fullNames == 1 then
        self:Notify(fullNames[1] .. "Stock full", "success")
    elseif #fullNames == 2 then
        self:Notify(table.concat(fullNames, "、") .. "Stock full", "success")
    elseif #fullNames > 2 then
        self:Notify(tostring(#fullNames) .. " businesses have full stock", "success")
    end
end

function SovereignBusinessInventory:Process(now, force)
    if type(self) ~= "table" then return false end
    local visible = self.visible == true
    local autoRestock = self.autoRestock == true
    local autoSell = self.autoSell == true
    local alertEnabled = self.alertEnabled == true
    local hasPendingSale = type(self.pendingSaleReservation) == "table"
        and next(self.pendingSaleReservation) ~= nil
    local hasPendingRefill = type(self.pendingRefillTransactions) == "table"
        and next(self.pendingRefillTransactions) ~= nil
    local hasRefillQuarantine = type(self.refillQuarantine) == "table"
        and next(self.refillQuarantine) ~= nil
    local hasSaleQuarantine = type(self.saleQuarantine) == "table"
        and next(self.saleQuarantine) ~= nil
    if not visible and not autoRestock and not autoSell and not alertEnabled
        and not hasPendingSale and not hasPendingRefill
        and not hasSaleQuarantine and not hasRefillQuarantine
        and not force then
        return true
    end
    now = tonumber(now) or os.clock()
    local lastRefresh = tonumber(self.lastRefresh) or 0
    local refreshInterval = math.max(0.1, tonumber(self.refreshInterval) or 1.0)
    if not force and now - lastRefresh < refreshInterval then return true end
    self.lastRefresh = now
    if hasSaleQuarantine and type(self.ProcessSaleQuarantines) == "function" then
        self:ProcessSaleQuarantines(now)
    end
    if hasRefillQuarantine and type(self.ProcessRefillQuarantines) == "function" then
        self:ProcessRefillQuarantines(now)
    end
    local refreshed = force and self:RefreshData()
        or (type(self.RefreshDataStep) == "function" and self:RefreshDataStep())
    if refreshed == false then return false end
    if hasPendingSale and type(self.ProcessPendingSaleSettlements) == "function" then
        self:ProcessPendingSaleSettlements(now)
    end
    if hasPendingRefill and type(self.ProcessPendingRefillTransactions) == "function" then
        self:ProcessPendingRefillTransactions()
    end
    if not force and self.refreshPhase ~= 6 then return true end
    if alertEnabled and type(self.UpdateAlerts) == "function" then
        self:UpdateAlerts()
    end
    if autoRestock and type(self.ProcessAutomaticRestock) == "function" then
        self:ProcessAutomaticRestock(now)
    end
    if autoSell and type(self.ProcessAutomaticSell) == "function" then
        self:ProcessAutomaticSell(now)
    end
    return true
end

function SovereignBusinessInventory:Render()
    if not self.visible then return end
    if self.renderInProgress then return end
    local frameToken
    local nativeApis = type(menu) == "table" and type(menu.nativeApis) == "table"
        and menu.nativeApis or nil
    local miscApis = nativeApis and nativeApis.MISC or nil
    if miscApis and type(miscApis.GET_FRAME_COUNT) == "function" then
        local frameOk, value = pcall(miscApis.GET_FRAME_COUNT)
        if frameOk and type(value) == "number" and value == value then
            frameToken = math.floor(value)
        end
    end
    if frameToken ~= nil and self.lastRenderFrame == frameToken then return end
    local begun, x, y, panelWidth, panelHeight = SovereignOverlayBegin("SovereignBusinessInventory", self.window, "Business inventory", 700, 560)
    if not begun then return end
    self.renderInProgress = true
    self.lastRenderFrame = frameToken
    local ok, err = xpcall(function()
        local theme = SovereignOverlayTheme
        local function textWidth(text)
            local okMeasure, width = pcall(menu.localizedTextSize, tostring(text or ""))
            if okMeasure and type(width) == "number" and width == width then return math.max(0, width) end
            return #tostring(text or "") * 7
        end
        local function utf8Prefix(text, byteCount)
            local count = math.max(0, math.min(#text, math.floor(tonumber(byteCount) or 0)))
            local prefix = text:sub(1, count)
            -- Do not leave a partial UTF-8 continuation byte when a localized
            -- label is shortened for a narrow inventory cell.
            while #prefix > 0 do
                local last = prefix:byte(-1)
                if not last or last < 128 then break end
                if last >= 128 and last < 192 then
                    prefix = prefix:sub(1, -2)
                else
                    local expected = last >= 240 and 4
                        or last >= 224 and 3 or 2
                    local continuation = 0
                    local index = #prefix - 1
                    while index > 0 do
                        local byte = prefix:byte(index)
                        if not byte or byte < 128 or byte >= 192 then break end
                        continuation = continuation + 1
                        index = index - 1
                    end
                    if continuation < expected - 1 then
                        prefix = prefix:sub(1, index)
                    else
                        break
                    end
                end
            end
            return prefix
        end
        local function fitText(text, maxWidth)
            text = tostring(text or "")
            maxWidth = math.max(0, tonumber(maxWidth) or 0)
            if maxWidth <= 0 then return "" end
            if textWidth(text) <= maxWidth then return text end
            local suffix = "..."
            local suffixWidth = textWidth(suffix)
            if suffixWidth >= maxWidth then
                return utf8Prefix(text, math.floor(maxWidth / 7))
            end
            local low, high, best = 0, #text, suffix
            while low <= high do
                local middle = math.floor((low + high) / 2)
                local candidate = utf8Prefix(text, middle) .. suffix
                if textWidth(candidate) <= maxWidth then
                    best = candidate
                    low = middle + 1
                else
                    high = middle - 1
                end
            end
            return best
        end
        local function drawCell(cellX, cellY, cellRight, text, color, rowHeight, rightAlign)
            if cellRight <= cellX then return end
            text = fitText(text, cellRight - cellX)
            local textX = cellX
            if rightAlign then textX = math.max(cellX, cellRight - textWidth(text)) end
            ImGui.PushClipRect(cellX, cellY, cellRight, cellY + rowHeight, true)
            SovereignOverlayText(textX, cellY, text, color)
            ImGui.PopClipRect()
        end
        local function drawTwoColumnRow(rowLeft, rowRight, rowY, rowHeight, label, value, labelColor, valueColor)
            local valueText = tostring(value or "")
            local valueX = math.max(rowLeft, rowRight - textWidth(valueText))
            drawCell(rowLeft, rowY, math.max(rowLeft, valueX - 8), label, labelColor, rowHeight, false)
            drawCell(valueX, rowY, rowRight, valueText, valueColor, rowHeight, true)
        end
        local contentWidth = math.max(520, panelWidth - 32)
        local columnGap = 14
        local columnWidth = math.max(240, math.floor((contentWidth - columnGap) / 2))
        local leftX, rightX = x + 16, x + 16 + columnWidth + columnGap
        ImGui.AddLine(rightX - 10, y + 58, rightX - 10, y + panelHeight - 18, theme.border[1], theme.border[2], theme.border[3], theme.border[4], 1.0)

        SovereignOverlayText(leftX, y + 58, "Production businesses", theme.text)
        local rowY = y + 82
        local visibleFactories = 0
        for _, entry in ipairs(self.data.factories or {}) do
            if not self.hideUnowned or entry.owned then
                visibleFactories = visibleFactories + 1
                ImGui.AddRectFilled(leftX, rowY, leftX + columnWidth - 4, rowY + 34, theme.row[1], theme.row[2], theme.row[3], theme.row[4], 5.0)
                if entry.owned then
                    ImGui.AddRectFilled(leftX, rowY, leftX + 3, rowY + 34, 90, 186, 245, 235, 3.0)
                    local rowLeft, rowRight = leftX + 10, leftX + columnWidth - 8
                    local supplyText = "Supplies " .. SovereignOverlayFormatNumber(entry.supply)
                    local stockText = "Stock " .. SovereignOverlayFormatNumber(entry.product) .. "/" .. SovereignOverlayFormatNumber(entry.maxProduct)
                    local stockX = math.max(rowLeft, rowRight - textWidth(stockText))
                    local supplyX = math.max(rowLeft + 96, stockX - 8 - textWidth(supplyText))
                    supplyX = math.min(supplyX, math.max(rowLeft, stockX - 8))
                    drawCell(rowLeft, rowY + 8, math.max(rowLeft, supplyX - 8), entry.name, theme.text, 18, false)
                    drawCell(supplyX, rowY + 8, math.max(supplyX, stockX - 8), supplyText, theme.supply, 18, true)
                    drawCell(stockX, rowY + 8, rowRight, stockText, theme.product, 18, true)
                else
                    ImGui.AddRectFilled(leftX, rowY, leftX + 3, rowY + 34, 83, 83, 98, 210, 3.0)
                    local rowLeft, rowRight = leftX + 10, leftX + columnWidth - 8
                    local valueText = "Not purchased"
                    local valueX = math.max(rowLeft + 96, rowRight - textWidth(valueText))
                    drawCell(rowLeft, rowY + 8, math.max(rowLeft, valueX - 8), entry.name, theme.secondary, 18, false)
                    drawCell(valueX, rowY + 8, rowRight, valueText, theme.secondary, 18, true)
                end
                rowY = rowY + 39
            end
        end
        if visibleFactories == 0 then
            SovereignOverlayText(leftX + 10, rowY + 8, "No production businesses purchased", theme.secondary)
        end

        SovereignOverlayText(leftX, y + 362, "Office warehouse", theme.text)
        rowY = y + 386
        for _, entry in ipairs(self.data.warehouses or {}) do
            ImGui.AddRectFilled(leftX, rowY, leftX + columnWidth - 4, rowY + 26, theme.row[1], theme.row[2], theme.row[3], theme.row[4], 4.0)
            ImGui.AddRectFilled(leftX, rowY, leftX + 3, rowY + 26, 126, 104, 235, 235, 3.0)
            drawTwoColumnRow(leftX + 10, leftX + columnWidth - 8, rowY + 4, 18, entry.name,
                SovereignOverlayFormatNumber(entry.value) .. "/" .. SovereignOverlayFormatNumber(entry.max), theme.secondary, theme.warehouse)
            rowY = rowY + 30
        end

        SovereignOverlayText(rightX, y + 58, "Nightclub warehouse", theme.text)
        rowY = y + 82
        for _, entry in ipairs(self.data.nightclub or {}) do
            ImGui.AddRectFilled(rightX, rowY, rightX + columnWidth, rowY + 26, theme.row[1], theme.row[2], theme.row[3], theme.row[4], 4.0)
            ImGui.AddRectFilled(rightX, rowY, rightX + 3, rowY + 26, 184, 145, 255, 235, 3.0)
            local stockText = SovereignOverlayFormatNumber(entry.value)
            if entry.max and entry.max > 0 then
                stockText = stockText .. "/" .. SovereignOverlayFormatNumber(entry.max)
            end
            drawTwoColumnRow(rightX + 10, rightX + columnWidth - 8, rowY + 4, 18, entry.name, stockText, theme.secondary, theme.warehouse)
            rowY = rowY + 30
        end

        SovereignOverlayText(rightX, y + 298, "Hangar cargo", theme.text)
        ImGui.AddRectFilled(rightX, y + 322, rightX + columnWidth, y + 350, theme.row[1], theme.row[2], theme.row[3], theme.row[4], 4.0)
        ImGui.AddRectFilled(rightX, y + 322, rightX + 3, y + 350, 255, 186, 82, 235, 3.0)
        drawTwoColumnRow(rightX + 10, rightX + columnWidth - 8, y + 327, 18, "Current goods",
            SovereignOverlayFormatNumber(self.data.hangar) .. "/" .. SovereignOverlayFormatNumber(self.data.hangarMax), theme.secondary, theme.cargo)

        SovereignOverlayText(rightX, y + 362, "Safe balance", theme.text)
        ImGui.AddRectFilled(rightX, y + 384, rightX + columnWidth, y + 428, theme.row[1], theme.row[2], theme.row[3], theme.row[4], 4.0)
        drawTwoColumnRow(rightX + 10, rightX + columnWidth - 8, y + 388, 16, "Nightclub",
            SovereignOverlayFormatNumber(self.data.nightclubSafe, "$") .. "/" .. SovereignOverlayFormatNumber(self.data.nightclubSafeMax, "$"), theme.secondary, theme.cash)
        drawTwoColumnRow(rightX + 10, rightX + columnWidth - 8, y + 408, 16, "Arcade",
            SovereignOverlayFormatNumber(self.data.arcadeSafe, "$") .. "/" .. SovereignOverlayFormatNumber(self.data.arcadeSafeMax, "$"), theme.secondary, theme.cash)
    end, debug.traceback)
    self.renderInProgress = false
    ImGui.SetWindowFontScale(1.0)
    ImGui.End()
    if not ok then
        local now = os.clock()
        if not self.lastRenderError or now - self.lastRenderError >= 5.0 then
            self.lastRenderError = now
            SovereignLogError("SovereignInventory.Render", err)
        end
    end
end

TravellerMigration = {
    plateText = "SOVEREGN",
    seatSelection = 1,
    seatIndices = {-1, 0, 1, 2, 3, 4, 5},
    knownPlayers = {},
    snapshotReady = false,
    lastActivity = "No recent player activity",
    lastRefresh = 0,
    refreshInterval = 1.0,
    overviewVisible = false,
    overviewData = nil,
    window = {x = 24, y = 120, width = 520, height = 330, fontScale = 1.0}
}

function TravellerMigration:Notify(message, status)
    local body = tostring(message or "")
    local resolved = menu.normalizeNotificationStatus(status)
        or menu.inferNotificationStatus(body)
    menu.notify("SovereignLua", body, 3.0, resolved)
end

function TravellerMigration:GetCurrentVehicle(silent)
    local okPed, ped = pcall(menu.nativeApis.PLAYER.PLAYER_PED_ID)
    if not okPed or not ped or ped == 0 then
        if not silent then
            self:Notify("Local player entity unavailable", "warning")
        end
        return nil, nil
    end
    local okInVehicle, inVehicle = pcall(menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE, ped, false)
    if not okInVehicle or not inVehicle then
        if not silent then
            self:Notify("Enter a vehicle first", "warning")
        end
        return nil, ped
    end
    local okVehicle, vehicle = pcall(menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN, ped, false)
    local okExists, exists = false, false
    if okVehicle and vehicle and vehicle ~= 0 then
        okExists, exists = pcall(menu.nativeApis.ENTITY.DOES_ENTITY_EXIST, vehicle)
    end
    if not okVehicle or not vehicle or vehicle == 0 or not okExists or not exists then
        if not silent then
            self:Notify("Current vehicle unavailable", "warning")
        end
        return nil, ped
    end
    return vehicle, ped
end

function TravellerMigration:NormalizePlate(value)
    local text = tostring(value or "")
    text = text:gsub("[%c]", " "):gsub("[^%w%s%p]", "")
    text = text:gsub("^%s+", ""):gsub("%s+$", "")
    return text:sub(1, 8)
end

function TravellerMigration:ApplyPlate()
    local vehicle = self:GetCurrentVehicle(false)
    if not vehicle then return false end
    local text = self:NormalizePlate(self.plateText)
    if text == "" then
        self:Notify("License plate cannot be empty", "warning")
        return false
    end
    local ok = pcall(menu.nativeApis.VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT, vehicle, text)
    if not ok then
        self:Notify("Could not set the license plate", "error")
        return false
    end
    self.plateText = text
    self:Notify("License plate set to " .. text, "success")
    return true
end

function TravellerMigration:SwitchSeat()
    local vehicle, ped = self:GetCurrentVehicle(false)
    if not vehicle then return false end
    local seat = self.seatIndices[self.seatSelection] or -1
    local okMax, maxPassengers = pcall(menu.nativeApis.VEHICLE.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS, vehicle)
    if not okMax then
        self:Notify("Could not read vehicle seats", "error")
        return false
    end
    if seat >= 0 and (not maxPassengers or seat > maxPassengers) then
        self:Notify("This vehicle does not have that seat", "warning")
        return false
    end
    local okOccupant, occupant = pcall(menu.nativeApis.VEHICLE.GET_PED_IN_VEHICLE_SEAT, vehicle, seat, false)
    if not okOccupant then
        self:Notify("Could not read the selected seat", "error")
        return false
    end
    if occupant and occupant ~= 0 and occupant ~= ped then
        self:Notify("Selected seat is occupied", "warning")
        return false
    end
    local ok = pcall(menu.nativeApis.PED.SET_PED_INTO_VEHICLE, ped, vehicle, seat)
    if not ok then
        self:Notify("Could not switch seats", "error")
        return false
    end
    return true
end

function TravellerMigration:GetVehicleName(vehicle)
    if not vehicle or vehicle == 0 then return "Not in a vehicle" end
    local okModel, model = pcall(menu.nativeApis.ENTITY.GET_ENTITY_MODEL, vehicle)
    if not okModel or not model then return "Unknown" end
    local okLabel, label = pcall(menu.nativeApis.VEHICLE.GET_DISPLAY_NAME_FROM_VEHICLE_MODEL, model)
    if not okLabel then label = nil end
    if label and label ~= "" and label ~= "NULL" and menu.nativeApis.HUD and menu.nativeApis.HUD.GET_FILENAME_FOR_AUDIO_CONVERSATION then
        local okLocalized, localized = pcall(menu.nativeApis.HUD.GET_FILENAME_FOR_AUDIO_CONVERSATION, label)
        if okLocalized and localized and localized ~= "" and localized ~= "NULL" then
            return localized
        end
    end
    if label and label ~= "" and label ~= "NULL" then
        return label
    end
    return string.format("0x%X", model or 0)
end

function TravellerMigration:GetNearestPlayer(players)
    local localId = menu.nativeApis.PLAYER.PLAYER_ID()
    local nearestPid = nil
    local nearestDistance = nil
    for _, pid in ipairs(players) do
        if pid ~= localId then
            local distance = GetPlayerDistance(pid)
            if distance and (not nearestDistance or distance < nearestDistance) then
                nearestPid = pid
                nearestDistance = distance
            end
        end
    end
    if nearestPid == nil then
        return "None"
    end
    return string.format("%s (%.0fm)", GetPlayerName(nearestPid), nearestDistance)
end

function TravellerMigration:UpdatePlayerChanges(players)
    local current = {}
    local changes = {}
    for _, pid in ipairs(players) do
        local name = GetPlayerName(pid)
        current[pid] = name
        local oldName = self.knownPlayers[pid]
        if self.snapshotReady and oldName == nil then
            changes[#changes + 1] = "Joined: " .. name
        elseif self.snapshotReady and oldName ~= name then
            changes[#changes + 1] = "Left: " .. oldName
            changes[#changes + 1] = "Joined: " .. name
        end
    end
    if self.snapshotReady then
        for pid, name in pairs(self.knownPlayers) do
            if current[pid] == nil then
                changes[#changes + 1] = "Left: " .. name
            end
        end
    end
    self.knownPlayers = current
    if not self.snapshotReady then
        self.snapshotReady = true
        return
    end
    if #changes > 0 then
        self.lastActivity = changes[#changes]
    end
end

function TravellerMigration:BindSessionOverview(groupId)
    self.overviewToggle = menu.toggle("Live session overview", "Show a draggable session information window", groupId, 0, function(value)
        self.overviewVisible = value == true
        if self.overviewVisible then
            self:Process(os.clock(), true)
        end
    end)
    self.overviewToggle._sovereignFreeAccess = true
    menu.bindFeatureToggle(self.overviewToggle, "session_overview", function() return self.overviewVisible == true end)
end

function TravellerMigration:Process(now, force)
    if not self.overviewVisible and not force then return end
    now = tonumber(now) or os.clock()
    if not force and now - self.lastRefresh < self.refreshInterval then return end
    self.lastRefresh = now

    local players = GetSessionPlayers()
    self:UpdatePlayerChanges(players)

    local scriptHost = "Unknown"
    if menu.nativeApis.NETWORK and menu.nativeApis.NETWORK.NETWORK_GET_HOST_OF_SCRIPT then
        local ok, pid = pcall(menu.nativeApis.NETWORK.NETWORK_GET_HOST_OF_SCRIPT, "freemode", -1, 0)
        if ok and type(pid) == "number" and pid >= 0 and pid <= 31 then
            scriptHost = GetPlayerName(pid)
        end
    end

    local localHost = "Unknown"
    if menu.nativeApis.NETWORK and menu.nativeApis.NETWORK.NETWORK_IS_HOST then
        local ok, isHost = pcall(menu.nativeApis.NETWORK.NETWORK_IS_HOST)
        if ok then localHost = isHost and "Yes" or "No" end
    end

    local natType = "Unresolved"
    if SovereignRuntimePatchBridge and type(SovereignRuntimePatchBridge.ReadNatType) == "function" then
        local natOk, natValue = pcall(SovereignRuntimePatchBridge.ReadNatType, SovereignRuntimePatchBridge, force == true)
        if natOk and type(natValue) == "string" and natValue ~= "" then
            natType = natValue
        elseif SovereignRuntimePatchBridge.natType and SovereignRuntimePatchBridge.natType.value then
            natType = tostring(SovereignRuntimePatchBridge.natType.value)
        end
    end

    local vehicle, ped = self:GetCurrentVehicle(true)
    local speedEntity = vehicle or ped
    local speed = 0.0
    if speedEntity and speedEntity ~= 0 then
        local ok, value = pcall(menu.nativeApis.ENTITY.GET_ENTITY_SPEED, speedEntity)
        if ok and value then speed = value * 3.6 end
    end

    local vehicleLabel = self:GetVehicleName(vehicle)
    if vehicle and vehicle ~= 0 then
        local vehicleZone = SovereignReadZoneFromEntity(vehicle)
        if vehicleZone and vehicleZone.name and vehicleZone.name ~= "Unknown zone" then
            vehicleLabel = vehicleLabel .. " · " .. vehicleZone.name
        end
    end

    self.overviewData = {
        players = tostring(#players),
        scriptHost = scriptHost,
        localHost = localHost,
        natType = natType,
        nearest = self:GetNearestPlayer(players),
        vehicle = vehicleLabel,
        speed = string.format("%.0f km/h", speed),
        activity = self.lastActivity
    }
end

function TravellerMigration:RenderSessionOverview()
    if not self.overviewVisible then return end
    local begun, x, y, panelWidth, panelHeight = SovereignOverlayBegin("SovereignSessionOverview", self.window, "Session overview", 520, 330)
    if not begun then return end
    local childBegun = false
    local ok, err = xpcall(function()
        local visible, contentX, contentY, contentWidth, rowHeight = SovereignOverlayBeginContent(
            "SessionOverview", self.window, x, y, panelWidth, panelHeight)
        childBegun = true
        if not visible then return end
        local theme = SovereignOverlayTheme
        local data = self.overviewData or {}
        local rows = {
            {"Player count", data.players or "--", theme.accent},
            {"Script host", data.scriptHost or "--", theme.text},
            {"Local session host", data.localHost or "--", theme.text},
            {"NAT type", data.natType or "--", theme.text},
            {"Nearest player", data.nearest or "--", theme.text},
            {"Current vehicle", data.vehicle or "--", theme.text},
            {"Current speed", data.speed or "--", theme.product},
            {"Recent activity", data.activity or "--", theme.secondary}
        }
        local rowY
        if contentWidth < 460 * math.max(1, self.window.fontScale or 1) then
            rowY = contentY + SovereignOverlayDrawSectionTitle(contentX, contentY, contentWidth, "Session summary")
            for index, row in ipairs(rows) do
                SovereignOverlayDrawRow(contentX, rowY, contentWidth, row[1], row[2], row[3], index % 2 == 1, rowHeight)
                rowY = rowY + rowHeight
            end
        else
            local gap = 18
            local columnWidth = math.floor((contentWidth - gap) / 2)
            local rightX = contentX + columnWidth + gap
            local headingHeight = SovereignOverlayDrawSectionTitle(contentX, contentY, columnWidth, "Session details")
            SovereignOverlayDrawSectionTitle(rightX, contentY, columnWidth, "Players and vehicle")
            rowY = contentY + headingHeight
            for index = 1, 4 do
                local left, right = rows[index], rows[index + 4]
                SovereignOverlayDrawRow(contentX, rowY, columnWidth, left[1], left[2], left[3], index % 2 == 1, rowHeight)
                SovereignOverlayDrawRow(rightX, rowY, columnWidth, right[1], right[2], right[3], index % 2 == 1, rowHeight)
                rowY = rowY + rowHeight
            end
        end
        ImGui.SetCursorScreenPos(contentX, rowY + 4)
        ImGui.Dummy(1, 1)
    end, debug.traceback)
    if childBegun then ImGui.EndChild() end
    ImGui.SetWindowFontScale(1.0)
    ImGui.End()
    if not ok then
        local now = os.clock()
        if not self.lastRenderError or now - self.lastRenderError >= 5.0 then
            self.lastRenderError = now
            SovereignLogError("SovereignSessionOverview.Render", err)
        end
    end
end

SovereignBattleNetworkStatus = {
    visible = false,
    lastRefresh = 0,
    refreshInterval = 1.0,
    window = {x = 430, y = 120, width = 560, height = 520, fontScale = 1.0},
    data = {},
    recovery = {
        state = "Not checked",
        detail = "",
        attempts = 0,
        nextRetryAt = 0,
        lastIssue = nil,
        lastNotifyAt = 0
    }
}

function SovereignBattleNetworkStatus:Call(name, ...)
    local network = menu.nativeApis and menu.nativeApis.NETWORK
    if type(network) ~= "table" then return nil, false end
    local okLookup, fn = pcall(function() return network[name] end)
    if not okLookup or type(fn) ~= "function" then return nil, false end
    local okCall, value = pcall(fn, ...)
    if not okCall then return nil, false end
    return value, true
end

function SovereignBattleNetworkStatus:Bool(name)
    local value, available = self:Call(name)
    if not available or value == nil then return nil end
    return value == true
end

function SovereignBattleNetworkStatus:YesNo(value)
    if value == nil then return "Unknown" end
    return value and "Yes" or "No"
end

function SovereignBattleNetworkStatus:ReadMultiplayerClock()
    local fn = menu.nativeApis and menu.nativeApis.NETWORK
        and menu.nativeApis.NETWORK.NETWORK_GET_GLOBAL_MULTIPLAYER_CLOCK
    if type(fn) ~= "function" or not Memory
        or type(Memory.AllocInt) ~= "function"
        or type(Memory.ReadInt) ~= "function"
        or type(Memory.Free) ~= "function" then
        return "Unknown"
    end
    local pointers = {}
    local function release()
        for _, ptr in ipairs(pointers) do
            if ptr then pcall(Memory.Free, ptr) end
        end
    end
    local okAlloc = pcall(function()
        pointers[1] = Memory.AllocInt()
        pointers[2] = Memory.AllocInt()
        pointers[3] = Memory.AllocInt()
    end)
    if not okAlloc or not pointers[1] or pointers[1] == 0
        or not pointers[2] or pointers[2] == 0 or not pointers[3] or pointers[3] == 0 then
        release()
        return "Unknown"
    end
    local okCall = pcall(fn, pointers[1], pointers[2], pointers[3])
    if not okCall then
        release()
        return "Unknown"
    end
    local okRead, hours, minutes, seconds = pcall(function()
        return Memory.ReadInt(pointers[1]), Memory.ReadInt(pointers[2]), Memory.ReadInt(pointers[3])
    end)
    release()
    if not okRead then return "Unknown" end
    hours, minutes, seconds = tonumber(hours), tonumber(minutes), tonumber(seconds)
    if not hours or not minutes or not seconds
        or hours < 0 or hours > 23 or minutes < 0 or minutes > 59
        or seconds < 0 or seconds > 59 then
        return "Unknown"
    end
    return string.format("%02d:%02d:%02d", hours, minutes, seconds)
end

function SovereignBattleNetworkStatus:ReadCanEnterMultiplayer()
    local direct, available = self:Call("NETWORK_CAN_ENTER_MULTIPLAYER")
    if available and direct ~= nil then return direct == true end
    local fn = menu.nativeApis and menu.nativeApis.NETWORK
        and menu.nativeApis.NETWORK.NETWORK_CAN_ACCESS_MULTIPLAYER
    if type(fn) ~= "function" or not Memory
        or type(Memory.AllocInt) ~= "function"
        or type(Memory.ReadInt) ~= "function"
        or type(Memory.Free) ~= "function" then
        return nil
    end
    local ptr
    local okAlloc = pcall(function() ptr = Memory.AllocInt() end)
    if not okAlloc or not ptr or ptr == 0 then return nil end
    local okCall, value = pcall(fn, ptr)
    local result = nil
    if okCall and value ~= nil then result = value == true end
    pcall(Memory.Free, ptr)
    return result
end

function SovereignBattleNetworkStatus:ReadHostName(localPlayerId)
    local hostPid, available = self:Call("NETWORK_GET_HOST_PLAYER_INDEX")
    hostPid = tonumber(hostPid)
    if not available or not hostPid or hostPid < 0 or hostPid > 31 then return "Unknown" end
    if localPlayerId and hostPid == localPlayerId then return "Local player" end
    if type(GetPlayerName) == "function" then
        local ok, name = pcall(GetPlayerName, hostPid)
        if ok and type(name) == "string" and name ~= "" then return name end
    end
    return "PID " .. tostring(hostPid)
end

function SovereignBattleNetworkStatus:UpdateRecovery(now, values)
    local recovery = self.recovery
    local issue
    if values.networkAvailable ~= true then
        issue = "Network interface unavailable"
    elseif values.signedIn == false then
        issue = "Social Club signed out"
    elseif values.rosValid == false then
        issue = "ROS credentials invalid"
    elseif values.cloudAvailable == false then
        issue = "Cloud service unavailable"
    elseif values.onlinePrivileges == false then
        issue = "Online privileges unavailable"
    elseif values.canEnter == false and values.inSession ~= true then
        issue = "Multiplayer is temporarily unavailable"
    end

    local waiting = values.sessionBusy == true or values.inTransition == true
        or values.loadingScene == true
    local previousState = recovery.state
    if issue then
        recovery.detail = issue
        recovery.lastIssue = issue
        if values.rosRefreshing == true then
            recovery.state = "Refreshing credentials"
        else
            recovery.state = "Retrying automatically"
        end
        if now >= (recovery.nextRetryAt or 0) then
            recovery.attempts = (recovery.attempts or 0) + 1
            local delay = math.min(8.0, math.max(1.0, 0.5 * (2 ^ math.min(recovery.attempts - 1, 4))))
            recovery.nextRetryAt = now + delay
        end
    elseif waiting then
        recovery.state = "Waiting for session recovery"
        recovery.detail = values.inTransition == true and "Changing session" or "Session busy"
        recovery.nextRetryAt = now + 1.0
    else
        local wasRecovering = previousState ~= "Healthy" and previousState ~= "Not checked"
        recovery.state = "Healthy"
        recovery.detail = ""
        recovery.attempts = 0
        recovery.nextRetryAt = now + self.refreshInterval
        if wasRecovering and self.visible and type(SovereignNotify) == "function"
            and now - (recovery.lastNotifyAt or 0) >= 2.0 then
            recovery.lastNotifyAt = now
            pcall(SovereignNotify, "SovereignLua", "Network status restored", "success")
        end
    end

    if self.visible and recovery.state ~= previousState
        and recovery.state ~= "Healthy"
        and now - (recovery.lastNotifyAt or 0) >= 3.0
        and type(SovereignNotify) == "function" then
        recovery.lastNotifyAt = now
        pcall(SovereignNotify, "SovereignLua", recovery.detail ~= ""
            and ("Network status: " .. recovery.detail) or "Network recovery in progress", "warning")
    end
end

function SovereignBattleNetworkStatus:RefreshData(now, force)
    if not self.visible and not force then return false end
    now = tonumber(now) or os.clock()
    if not force and now - (self.lastRefresh or 0) < (self.refreshInterval or 1.0) then return true end
    self.lastRefresh = now
    local network = menu.nativeApis and menu.nativeApis.NETWORK
    local networkAvailable = type(network) == "table"
    local signedIn = self:Bool("NETWORK_IS_SIGNED_IN")
    local rosValid = self:Bool("NETWORK_HAS_VALID_ROS_CREDENTIALS")
    local rosRefreshing = self:Bool("NETWORK_IS_REFRESHING_ROS_CREDENTIALS")
    local cloudAvailable = self:Bool("NETWORK_IS_CLOUD_AVAILABLE")
    local socialClub = self:Bool("NETWORK_HAS_SOCIAL_CLUB_ACCOUNT")
    local onlinePrivileges = self:Bool("NETWORK_HAVE_ONLINE_PRIVILEGES")
    local active = self:Bool("NETWORK_IS_SESSION_ACTIVE")
    local inSession = self:Bool("NETWORK_IS_IN_SESSION")
    local started = self:Bool("NETWORK_IS_SESSION_STARTED")
    local sessionBusy = self:Bool("NETWORK_IS_SESSION_BUSY")
    local inTransition = self:Bool("NETWORK_IS_IN_TRANSITION")
    local transitionBusy = self:Bool("NETWORK_IS_TRANSITION_BUSY")
    local transitionStarted = self:Bool("NETWORK_IS_TRANSITION_STARTED")
    local canEnter = self:ReadCanEnterMultiplayer()
    local loadingScene = false
    if menu.nativeApis.STREAMING then
        local ok, value = pcall(function()
            local fn = menu.nativeApis.STREAMING.IS_NETWORK_LOADING_SCENE
            return type(fn) == "function" and fn() or false
        end)
        loadingScene = ok and value == true or false
    end
    inTransition = inTransition == true or transitionBusy == true
        or transitionStarted == true or loadingScene == true
    sessionBusy = sessionBusy == true or transitionBusy == true
    local localPlayerId = nil
    if menu.nativeApis.PLAYER and type(menu.nativeApis.PLAYER.PLAYER_ID) == "function" then
        local ok, value = pcall(menu.nativeApis.PLAYER.PLAYER_ID)
        if ok then localPlayerId = tonumber(value) end
    end
    local sessionType = "Not in session"
    if active == true or inSession == true or started == true then
        local solo = self:Bool("NETWORK_SESSION_IS_SOLO")
        local private = self:Bool("NETWORK_SESSION_IS_PRIVATE")
        if solo == true then sessionType = "Single-player state"
        elseif private == true then sessionType = "Private session"
        else sessionType = "Public session" end
    end
    local playerCount
    local count, countAvailable = self:Call("NETWORK_GET_NUM_CONNECTED_PLAYERS")
    if countAvailable and tonumber(count) then
        playerCount = math.max(0, math.floor(tonumber(count)))
    elseif type(GetSessionPlayers) == "function" then
        local ok, players = pcall(GetSessionPlayers)
        if ok and type(players) == "table" then playerCount = #players end
    end
    local socialClubReady = nil
    if socialClub ~= nil then
        socialClubReady = socialClub == true and signedIn ~= false
    end
    local zone = SovereignReadLocalZone()
    local locale = SovereignReadLocalization()
    local dlc = SovereignReadDlcDiagnostics()
    self.data = {
        sessionType = sessionType,
        host = self:ReadHostName(localPlayerId),
        busy = self:YesNo(sessionBusy),
        transition = self:YesNo(inTransition),
        multiplayerTime = self:ReadMultiplayerClock(),
        players = playerCount and tostring(playerCount) or "Unknown",
        socialClub = self:YesNo(socialClubReady),
        ros = self:YesNo(rosValid),
        cloud = self:YesNo(cloudAvailable),
        privileges = self:YesNo(onlinePrivileges),
        canEnter = self:YesNo(canEnter),
        inSession = self:YesNo(inSession),
        isHost = self:YesNo(self:Bool("NETWORK_IS_HOST")),
        zone = zone.display,
        localization = locale.language,
        dlc = dlc.summary,
        dlcDetail = dlc.detail,
        recovery = self.recovery
    }
    self:UpdateRecovery(now, {
        networkAvailable = networkAvailable,
        signedIn = signedIn,
        rosValid = rosValid,
        rosRefreshing = rosRefreshing,
        cloudAvailable = cloudAvailable,
        onlinePrivileges = onlinePrivileges,
        canEnter = canEnter,
        inSession = inSession,
        sessionBusy = sessionBusy,
        inTransition = inTransition,
        loadingScene = loadingScene
    })
    return true
end

function SovereignBattleNetworkStatus:Process(now, force)
    local ok, err = pcall(self.RefreshData, self, now, force)
    if not ok then
        if type(SovereignLogError) == "function" then
            SovereignLogError("SovereignBattleNetworkStatus.Refresh", err)
        end
        return false
    end
    return true
end

function SovereignBattleNetworkStatus:Render()
    if not self.visible then return end
    local begun, x, y, panelWidth, panelHeight = SovereignOverlayBegin(
        "SovereignBattleNetworkStatus", self.window, "Session Network Status", 560, 520)
    if not begun then return end
    local childBegun = false
    local ok, err = xpcall(function()
        local visible, contentX, contentY, contentWidth, rowHeight = SovereignOverlayBeginContent(
            "BattleNetwork", self.window, x, y, panelWidth, panelHeight)
        childBegun = true
        if not visible then return end
        local theme = SovereignOverlayTheme
        local data = self.data or {}
        local sessionRows = {
            {"Session type", data.sessionType, theme.accent},
            {"Current host", data.host, theme.text},
            {"Session busy", data.busy, theme.text},
            {"Session transition", data.transition, theme.text},
            {"Multiplayer time", data.multiplayerTime, theme.product},
            {"Connected players", data.players, theme.text},
            {"Is host", data.isHost, theme.text}
        }
        local serviceRows = {
            {"Social Club signed in", data.socialClub, theme.text},
            {"Valid ROS credentials", data.ros, theme.text},
            {"Cloud service available", data.cloud, theme.text},
            {"Online privileges", data.privileges, theme.text},
            {"Can enter multiplayer", data.canEnter, theme.text},
            {"In session", data.inSession, theme.text}
        }
        local function drawSection(sectionX, sectionY, width, title, rows)
            local rowY = sectionY + SovereignOverlayDrawSectionTitle(sectionX, sectionY, width, title)
            for index, row in ipairs(rows) do
                SovereignOverlayDrawRow(sectionX, rowY, width, row[1], row[2], row[3], index % 2 == 1, rowHeight)
                rowY = rowY + rowHeight
            end
            return rowY + 12
        end
        local nextY
        if contentWidth >= 460 * math.max(1, self.window.fontScale or 1) then
            local gap = 18
            local columnWidth = math.floor((contentWidth - gap) / 2)
            local leftEnd = drawSection(contentX, contentY, columnWidth, "Session status", sessionRows)
            local rightEnd = drawSection(contentX + columnWidth + gap, contentY, columnWidth, "Services and access", serviceRows)
            nextY = math.max(leftEnd, rightEnd)
        else
            nextY = drawSection(contentX, contentY, contentWidth, "Session status", sessionRows)
            nextY = drawSection(contentX, nextY, contentWidth, "Services and access", serviceRows)
        end
        nextY = drawSection(contentX, nextY, contentWidth, "Environment", {
            {"Current zone", data.zone, theme.text},
            {"Localization", data.localization, theme.text},
            {"DLC status", data.dlc, data.dlc == "Healthy" and theme.product or theme.accent}
        })
        local recovery = data.recovery or self.recovery or {}
        nextY = drawSection(contentX, nextY, contentWidth, "Network Recovery", {
            {"Status", recovery.state or "Unknown", recovery.state == "Healthy" and theme.product or theme.accent},
            {"Recovery details", recovery.detail ~= "" and recovery.detail or "--", theme.secondary},
            {"Retry attempts", tostring(recovery.attempts or 0), theme.secondary}
        })
        ImGui.SetCursorScreenPos(contentX, nextY)
        ImGui.Dummy(1, 1)
    end, debug.traceback)
    if childBegun then ImGui.EndChild() end
    ImGui.SetWindowFontScale(1.0)
    ImGui.End()
    if not ok and type(SovereignLogError) == "function" then
        SovereignLogError("SovereignBattleNetworkStatus.Render", err)
    end
end

SovereignStatusCenter = {
    visible = false,
    lastRefresh = 0,
    refreshInterval = 1.0,
    window = {x = 24, y = 420, width = 440, height = 330, fontScale = 1.0},
    data = {}
}

function SovereignStatusCenter:RefreshData(now, force)
    if not self.visible and not force then return end
    now = tonumber(now) or os.clock()
    if not force and now - (self.lastRefresh or 0) < (self.refreshInterval or 1.0) then return end
    self.lastRefresh = now
    local function safeValue(defaultValue, callback)
        if type(callback) ~= "function" then return defaultValue end
        local ok, value = pcall(callback)
        if not ok or value == nil then return defaultValue end
        return value
    end
    local activeTask = "Freemode"
    local taskScripts = {
        {"fm_mission_controller_v3", "Mission in progress"},
        {"fm_mission_controller_2020", "Mission in progress"},
        {"fm_mission_controller", "Original heist in progress"},
        {"fmmc_launcher", "Preparing mission"},
        {"gb_casino_heist", "Casino mission"},
        {"fm_content_island_heist", "Cayo Perico mission"},
        {"fm_content_vehrob", "Vehicle robbery mission"}
    }
    for _, entry in ipairs(taskScripts) do
        local checkOk, running = pcall(function()
            if SovereignBusinessInventory
                and type(SovereignBusinessInventory.IsScriptRunning) == "function" then
                return SovereignBusinessInventory:IsScriptRunning(entry[1])
            end
            return SovereignTaskIsScriptRunning(entry[1])
        end)
        if checkOk and running == true then
            activeTask = entry[2]
            break
        end
    end
    local playerId = safeValue(-1, function()
        if not menu.nativeApis.PLAYER or type(menu.nativeApis.PLAYER.PLAYER_ID) ~= "function" then return -1 end
        return menu.nativeApis.PLAYER.PLAYER_ID()
    end)
    local ped = safeValue(0, function()
        if not menu.nativeApis.PLAYER or type(menu.nativeApis.PLAYER.PLAYER_PED_ID) ~= "function" then return 0 end
        return menu.nativeApis.PLAYER.PLAYER_PED_ID()
    end)
    local vehicle = safeValue(0, function()
        if not ped or ped == 0 or not menu.nativeApis.PED or type(menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE) ~= "function"
            or type(menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN) ~= "function" then
            return 0
        end
        if not menu.nativeApis.PED.IS_PED_IN_ANY_VEHICLE(ped, false) then return 0 end
        return menu.nativeApis.PED.GET_VEHICLE_PED_IS_IN(ped, false)
    end)
    local interior = 0
    if ped and ped ~= 0 and menu.nativeApis.INTERIOR and type(menu.nativeApis.INTERIOR.GET_INTERIOR_FROM_ENTITY) == "function" then
        local ok, value = pcall(menu.nativeApis.INTERIOR.GET_INTERIOR_FROM_ENTITY, ped)
        if ok then interior = tonumber(value) or 0 end
    end
    local zone = SovereignReadLocalZone()
    local locale = SovereignReadLocalization()
    local dlc = SovereignReadDlcDiagnostics()
    local location = zone.display
    if interior > 0 then location = location .. " · Indoors" else location = location .. " · Outdoors" end
    local online = false
    if menu.nativeApis.NETWORK and type(menu.nativeApis.NETWORK.NETWORK_IS_SESSION_ACTIVE) == "function" then
        local ok, value = pcall(menu.nativeApis.NETWORK.NETWORK_IS_SESSION_ACTIVE)
        online = ok and value == true
    end
    local inventory = SovereignBusinessInventory
    local organizationLabel = safeValue("No organization registered", function()
        if not inventory or type(inventory.GetLocalOrganizationState) ~= "function" then
            return "No organization registered"
        end
        local state = inventory:GetLocalOrganizationState()
        return type(state) == "table" and tostring(state.label or "No organization registered")
            or "No organization registered"
    end)
    local warehouses = safeValue(0, function()
        if not inventory or type(inventory.GetOwnedWarehouseCount) ~= "function" then return 0 end
        return inventory:GetOwnedWarehouseCount()
    end)
    local players = safeValue({}, function()
        if type(GetSessionPlayers) ~= "function" then return {} end
        return GetSessionPlayers()
    end)
    if type(players) ~= "table" then players = {} end
    local vehicleName = safeValue("Unknown", function()
        if not TravellerMigration or type(TravellerMigration.GetVehicleName) ~= "function" then return "Unknown" end
        return TravellerMigration:GetVehicleName(vehicle)
    end)
    local playerName = safeValue("Unknown", function()
        if type(GetPlayerName) ~= "function" then return "Unknown" end
        return GetPlayerName(playerId)
    end)
    self.data = {
        session = online and "Online session" or "Story mode",
        players = tostring(#players),
        task = activeTask,
        interior = location,
        localization = locale.display,
        dateFormat = locale.dateFormat,
        dlc = dlc.summary,
        organization = organizationLabel,
        warehouses = tostring(tonumber(warehouses) or 0),
        vehicle = vehicleName,
        player = playerName
    }
end

function SovereignStatusCenter:Process(now, force)
    if type(self.RefreshData) ~= "function" then return false end
    local ok, err = pcall(self.RefreshData, self, now, force)
    if not ok then
        local current = os.clock()
        if not self.lastProcessError or current - self.lastProcessError >= 5.0 then
            self.lastProcessError = current
            SovereignLogError("SovereignStatusCenter.Snapshot", err)
        end
        return false
    end
    return true
end

function SovereignStatusCenter:Render()
    if not self.visible then return end
    local begun, x, y, panelWidth, panelHeight = SovereignOverlayBegin("SovereignStatusCenter", self.window, "Status Center", 440, 330)
    if not begun then return end
    local childBegun = false
    local ok, err = xpcall(function()
        local visible, contentX, contentY, contentWidth, rowHeight = SovereignOverlayBeginContent(
            "StatusCenter", self.window, x, y, panelWidth, panelHeight)
        childBegun = true
        if not visible then return end
        local theme = SovereignOverlayTheme
        local data = self.data or {}
        local rows = {
            {"Current player", data.player or "--", theme.text},
            {"Current mode", data.session or "--", theme.accent},
            {"Session players", data.players or "--", theme.text},
            {"Current activity", data.task or "--", theme.product},
            {"Current area", data.interior or "--", theme.text},
            {"Organization status", data.organization or "--", theme.text},
            {"Office warehouse", data.warehouses or "--", theme.warehouse},
            {"Current vehicle", data.vehicle or "--", theme.text}
        }
        local rowY = contentY
        for index, row in ipairs(rows) do
            SovereignOverlayDrawRow(contentX, rowY, contentWidth, row[1], row[2], row[3], index % 2 == 1, rowHeight)
            rowY = rowY + rowHeight
        end
        ImGui.SetCursorScreenPos(contentX, rowY + 4)
        ImGui.Dummy(1, 1)
    end, debug.traceback)
    if childBegun then ImGui.EndChild() end
    ImGui.SetWindowFontScale(1.0)
    ImGui.End()
    if not ok then SovereignLogError("SovereignStatusCenter.Render", err) end
end

function SovereignStatusCenter:BuildSnapshot()
    if not self:Process(os.clock(), true) then return nil end
    local data = self.data or {}
    return table.concat({
        "SovereignLua status snapshot",
        "Time: " .. SovereignFormatLocalizedDateTime(os.time and os.time() or nil, SovereignReadLocalization()),
        "Current player: " .. tostring(data.player or "--"),
        "Current mode: " .. tostring(data.session or "--"),
        "Session players: " .. tostring(data.players or "--"),
        "Current activity: " .. tostring(data.task or "--"),
        "Current area: " .. tostring(data.interior or "--"),
        "Localization: " .. tostring(data.localization or "--"),
        "DLC status: " .. tostring(data.dlc or "--"),
        "Organization status: " .. tostring(data.organization or "--"),
        "Office warehouse: " .. tostring(data.warehouses or "--"),
        "Current vehicle: " .. tostring(data.vehicle or "--")
    }, "\n")
end

function SovereignStatusCenter:CopySnapshot()
    if not (ImGui and type(ImGui.SetClipboardText) == "function") then
        return false, "clipboard_unavailable"
    end
    local snapshotOk, snapshot = pcall(self.BuildSnapshot, self)
    if not snapshotOk or type(snapshot) ~= "string" then
        if type(SovereignLogError) == "function" then
            SovereignLogError("SovereignStatusCenter.Snapshot", snapshot)
        end
        return false, "snapshot_failed"
    end
    local copyOk, copyResult = pcall(ImGui.SetClipboardText, snapshot)
    if not copyOk or copyResult == false then return false, "copy_failed" end
    return true, nil
end

SovereignRuntimeDebugPanel = {
    visible = false, lastRefresh = 0, lines = {},
    window = {x = 940, y = 420, width = 520, height = 360, fontScale = 0.9}
}

function SovereignRuntimeDebugPanel:Refresh(force)
    local now = os.clock()
    if not force and now - (self.lastRefresh or 0) < 1.0 then return true end
    local function scalar(value, fallback)
        local kind = type(value)
        if kind == "string" or kind == "number" or kind == "boolean" then return tostring(value) end
        return fallback or "unavailable"
    end
    local function info(method)
        if type(Utils1) ~= "table" or type(Utils1[method]) ~= "function" then
            return "unavailable", "unavailable"
        end
        local ok, value, source = pcall(Utils1[method], Utils1)
        if not ok then return "unavailable", "unavailable" end
        return scalar(value), scalar(source)
    end
    local edition, source = info("editionInfo")
    local build, buildSource = info("buildInfo")
    local lines = {
        "Runtime diagnostics",
        "Version: " .. edition .. " / " .. source,
        "Build: " .. build .. " / " .. buildSource
    }
    local bridgeAvailable = false
    if type(MemoryBridge) == "table" and type(MemoryBridge.GetStatusLines) == "function" then
        local ok, status = pcall(MemoryBridge.GetStatusLines, MemoryBridge)
        if ok and type(status) == "table" then
            bridgeAvailable = true
            for index = 1, math.min(#status, 256) do
                lines[#lines + 1] = scalar(status[index])
            end
            if #status > 256 then lines[#lines + 1] = "MemoryBridge: truncated" end
        end
    end
    if not bridgeAvailable then lines[#lines + 1] = "MemoryBridge: unavailable" end
    local registry = type(SovereignPatchRegistry) == "table" and SovereignPatchRegistry or {}
    if type(registry.order) == "table" and type(registry.states) == "table" then
        for index = 1, math.min(#registry.order, 256) do
            local id = registry.order[index]
            local state = (type(id) == "string" or type(id) == "number") and registry.states[id] or nil
            lines[#lines + 1] = "Patch " .. scalar(id) .. ": "
                .. scalar(type(state) == "table" and state.state or nil)
        end
        if #registry.order > 256 then lines[#lines + 1] = "PatchRegistry: truncated" end
    else
        lines[#lines + 1] = "PatchRegistry: unavailable"
    end
    self.lines = lines
    self.lastRefresh = now
    return true
end

function SovereignRuntimeDebugPanel:BuildText()
    self:Refresh(true)
    return table.concat(self.lines or {}, "\n")
end

function SovereignRuntimeDebugPanel:Copy()
    if not ImGui or type(ImGui.SetClipboardText) ~= "function" then return false, "clipboard_unavailable" end
    local snapshotOk, snapshot = pcall(self.BuildText, self)
    if not snapshotOk or type(snapshot) ~= "string" then return false, "snapshot_failed" end
    local ok, result = pcall(ImGui.SetClipboardText, snapshot)
    if not ok or result == false then return false, "copy_failed" end
    return true, nil
end

function SovereignRuntimeDebugPanel:Render()
    if not self.visible then return end
    local begun, x, y, width, height = SovereignOverlayBegin(
        "SovereignRuntimeDebugPanel", self.window, "Runtime diagnostics", 520, 360)
    if not begun then return end
    local childBegun, wrapPushed = false, false
    local ok, err = xpcall(function()
        ImGui.SetCursorScreenPos(x + 12, y + 54)
        local childVisible = ImGui.BeginChild("##SovereignRuntimeDebugContent",
            width - 24, height - 66, false, ImGuiWindowFlags.NoBackground)
        childBegun = true
        if childVisible then
            ImGui.PushTextWrapPos(0.0)
            wrapPushed = true
            local color = SovereignOverlayTheme.text
            local lines = type(self.lines) == "table" and self.lines or {}
            for _, line in ipairs(lines) do
                menu.localizedTextColored(color[1], color[2], color[3], color[4], tostring(line))
            end
        end
    end, debug.traceback)
    if wrapPushed then ImGui.PopTextWrapPos() end
    if childBegun then ImGui.EndChild() end
    ImGui.SetWindowFontScale(1.0)
    ImGui.End()
    if not ok then SovereignLogError("SovereignRuntimeDebugPanel.Render", err) end
end

function TravellerMigration:CopyPlayerInfo(pid, summary)
    if type(pid) ~= "number" or pid < 0 or pid > 31 then
        self:Notify("Select a valid player first", "warning")
        return false
    end
    if not (ImGui and type(ImGui.SetClipboardText) == "function") then
        self:Notify("Clipboard is unavailable in this environment", "warning")
        return false
    end
    local name = GetPlayerName(pid)
    local rid = GetPlayerRockstarId(pid)
    local text = rid and tostring(rid) or "Unknown"
    if summary then
        local distance = GetPlayerDistance(pid)
        text = table.concat({
            "Name: " .. name,
            "PID: " .. tostring(pid),
            "Rockstar ID: " .. (rid and tostring(rid) or "Unknown"),
            "Distance: " .. (distance and string.format("%.1fm", distance) or "Unknown")
        }, "\n")
    end
    ImGui.SetClipboardText(text)
    self:Notify(summary and "Player summary copied" or "Rockstar ID copied", "success")
    return true
end

-- This has already been abandoned
-- Matchmaking advertisement compatibility layer.
-- The current native bridge owns the detours. This Lua object only exposes
-- the state/configuration surface and the callback contract used by newer
-- bridge builds; it never installs a second detour from Lua.
SovereignMatchmakingAdvertise = rawget(_G, "__SOVEREIGN_MATCHMAKING_ADVERTISE") or {}
rawset(_G, "__SOVEREIGN_MATCHMAKING_ADVERTISE", SovereignMatchmakingAdvertise)

SovereignMatchmakingAdvertise.module = select(3, Utils1:editionInfo())
SovereignMatchmakingAdvertise.advertisePattern = "C7 47 30 01 00 00 00 E9 92"
SovereignMatchmakingAdvertise.advertiseRipBack = 0x0C
SovereignMatchmakingAdvertise.maxInstances = 7
SovereignMatchmakingAdvertise.instances = tonumber(SovereignMatchmakingAdvertise.instances) or 1
SovereignMatchmakingAdvertise.spoofPlayerCount = SovereignMatchmakingAdvertise.spoofPlayerCount == true
SovereignMatchmakingAdvertise.playerCount = tonumber(SovereignMatchmakingAdvertise.playerCount) or 25
SovereignMatchmakingAdvertise.spoofLanguage = SovereignMatchmakingAdvertise.spoofLanguage == true
SovereignMatchmakingAdvertise.language = tonumber(SovereignMatchmakingAdvertise.language) or 12
SovereignMatchmakingAdvertise.spoofRegion = SovereignMatchmakingAdvertise.spoofRegion == true
SovereignMatchmakingAdvertise.region = tonumber(SovereignMatchmakingAdvertise.region) or 4
SovereignMatchmakingAdvertise.overrideSlots = SovereignMatchmakingAdvertise.overrideSlots == true
SovereignMatchmakingAdvertise.numSlots = tonumber(SovereignMatchmakingAdvertise.numSlots) or 32
SovereignMatchmakingAdvertise.availableSlots = tonumber(SovereignMatchmakingAdvertise.availableSlots) or 32
SovereignMatchmakingAdvertise.targetFn = SovereignMatchmakingAdvertise.targetFn or 0
SovereignMatchmakingAdvertise.originalFn = SovereignMatchmakingAdvertise.originalFn or 0
SovereignMatchmakingAdvertise.enabled = SovereignMatchmakingAdvertise.enabled == true
SovereignMatchmakingAdvertise.hooked = SovereignMatchmakingAdvertise.hooked == true
SovereignMatchmakingAdvertise.sessions = SovereignMatchmakingAdvertise.sessions or {}

function SovereignMatchmakingAdvertise:Log(message)
    if Logger and Logger.Info then
        Logger:Info("Matchmaking extension", tostring(message))
    end
end

function SovereignMatchmakingAdvertise:IsPointer(value)
    return value ~= nil and value ~= 0
end

function SovereignMatchmakingAdvertise:ResolveAdvertise()
    if not Memory or type(Memory.Scan) ~= "function" or type(Memory.Rip) ~= "function" then
        self.targetFn = 0
        self.hooked = false
        self:Log("Matchmaking address resolution is unavailable")
        return false
    end
    local _, _, moduleName = Utils1:editionInfo()
    self.module = moduleName
    if not moduleName then
        self.targetFn = 0
        self.hooked = false
        self:Log("GTA version unknown; matchmaking address resolution skipped")
        return false
    end
    local okHit, hit = pcall(Memory.Scan, self.advertisePattern, moduleName)
    if not okHit or not self:IsPointer(hit) then
        self.targetFn = 0
        self.hooked = false
        self:Log("Matchmaking address not found")
        return false
    end
    local okFn, fn = pcall(Memory.Rip, hit - self.advertiseRipBack)
    if not okFn or not self:IsPointer(fn) then
        self.targetFn = 0
        self.hooked = false
        self:Log("Matchmaking address resolution failed")
        return false
    end
    self.targetFn = fn
    self:Log(string.format("Matchmaking address resolved: 0x%X", fn))
    return true
end

function SovereignMatchmakingAdvertise:SetOriginalAddress(address)
    self.originalFn = self:IsPointer(address) and address or 0
    self.hooked = self.originalFn ~= 0
    self:Log(self.hooked and "Matchmaking bridge connected" or "Matchmaking bridge disconnected")
end

function SovereignMatchmakingAdvertise:ApplyBridgeConfig()
    -- New bridge builds may expose this adapter. Older builds simply keep
    -- their native defaults and continue to pass through this call.
    local setter = rawget(_G, "__SOVEREIGN_MATCHMAKING_SET_CONFIG")
    if type(setter) ~= "function" then return false end
    local ok, result = pcall(setter, {
        enabled = self.enabled == true,
        instances = math.max(1, math.min(self.maxInstances, math.floor(tonumber(self.instances) or 1))),
        spoofPlayerCount = self.spoofPlayerCount == true,
        playerCount = math.max(1, math.min(32, math.floor(tonumber(self.playerCount) or 25))),
        overrideSlots = self.overrideSlots == true,
        numSlots = math.max(1, math.min(32, math.floor(tonumber(self.numSlots) or 32))),
        availableSlots = math.max(0, math.min(32, math.floor(tonumber(self.availableSlots) or 32)))
    })
    return ok and result ~= false
end

function SovereignMatchmakingAdvertise:ReadUInt(address)
    if not self:IsPointer(address) or not Memory or type(Memory.ReadUInt) ~= "function" then return nil end
    local ok, value = pcall(Memory.ReadUInt, address)
    return ok and tonumber(value) or nil
end

function SovereignMatchmakingAdvertise:WriteUInt(address, value)
    if not self:IsPointer(address) or not Memory or type(Memory.WriteUInt) ~= "function" then return false end
    local ok = pcall(Memory.WriteUInt, address, math.max(0, math.floor(tonumber(value) or 0)))
    return ok
end

function SovereignMatchmakingAdvertise:PatchAttributes(attrs)
    if not self:IsPointer(attrs) then return false end
    local count = self:ReadUInt(attrs + 0x04)
    if not count or count > 8 then
        self:Log("Matchmaking attribute layout validation failed")
        return false
    end
    if self.spoofPlayerCount then
        self:WriteUInt(attrs + 0xE8 + (2 * 4), self.playerCount)
    end
    if self.spoofLanguage then
        self:WriteUInt(attrs + 0xE8 + (3 * 4), self.language)
    end
    if self.spoofRegion then
        self:WriteUInt(attrs + 0xE8 + (4 * 4), self.region)
    end
    return true
end

function SovereignMatchmakingAdvertise:ReadIdHash(idAddress)
    if not self:IsPointer(idAddress) or not Memory or type(Memory.ReadString) ~= "function" then return 0 end
    local ok, text = pcall(Memory.ReadString, idAddress)
    if not ok or type(text) ~= "string" or text == "" then return 0 end
    return Utils and Utils.Joaat and Utils.Joaat(text) or 0
end

function SovereignMatchmakingAdvertise:ContextHash(context, idAddress)
    if type(context) == "table" and context.idHash ~= nil then return context.idHash end
    return self:ReadIdHash(idAddress)
end

function SovereignMatchmakingAdvertise:CallOriginal(context, outId, status)
    if not self:IsPointer(self.originalFn) or not Memory
        or type(Memory.LuaCallCFunctionWithReturnValue) ~= "function" then
        return false
    end
    local ok, resultAddress = pcall(Memory.LuaCallCFunctionWithReturnValue,
        self.originalFn,
        context.profileIndex,
        context.numSlots,
        context.availableSlots,
        context.attrs,
        context.sessionId,
        context.info,
        outId,
        status)
    if not ok or not self:IsPointer(resultAddress) then return false end
    local result = true
    if type(Memory.ReadByte) == "function" then
        local readOk, value = pcall(Memory.ReadByte, resultAddress)
        result = readOk and value ~= 0
    end
    if type(Memory.Free) == "function" then pcall(Memory.Free, resultAddress) end
    return result
end

function SovereignMatchmakingAdvertise:OnAdvertiseContext(context)
    if type(context) ~= "table" or not self:IsPointer(context.attrs) or not self:IsPointer(context.status) then
        return true
    end
    if not self:PatchAttributes(context.attrs) then return true end
    if self.overrideSlots then
        context.numSlots = math.max(1, math.min(32, math.floor(tonumber(self.numSlots) or 32)))
        context.availableSlots = math.max(0, math.min(context.numSlots, math.floor(tonumber(self.availableSlots) or 32)))
    end
    if not self.enabled or self.instances <= 1 then return true end
    if not Memory or type(Memory.ReadInt) ~= "function" or type(Memory.WriteInt) ~= "function"
        or type(Memory.Alloc) ~= "function" or type(Memory.MemSet) ~= "function" then return true end
    local okStatus, statusValue = pcall(Memory.ReadInt, context.status)
    if not okStatus or statusValue ~= 0 then return false end
    pcall(Memory.WriteInt, context.status, 1)
    if not Script or type(Script.QueueJob) ~= "function" then
        pcall(Memory.WriteInt, context.status, 2)
        return false
    end
    Script.QueueJob(function()
        local firstStatus = Memory.Alloc(8)
        if not self:IsPointer(firstStatus) then pcall(Memory.WriteInt, context.status, 2); return end
        Memory.MemSet(firstStatus, 0, 8)
        local mainId = context.outId
        local mainOk = self:CallOriginal(context, mainId, firstStatus)
        if not mainOk then
            pcall(Memory.WriteInt, context.status, 2)
            pcall(Memory.Free, firstStatus)
            return
        end
        while true do
            local readOk, state = pcall(Memory.ReadInt, firstStatus)
            if not readOk or state ~= 1 then break end
            Script.Yield(0)
        end
        local readOk, firstState = pcall(Memory.ReadInt, firstStatus)
        if not readOk or firstState == 2 then
            pcall(Memory.WriteInt, context.status, 2)
            pcall(Memory.Free, firstStatus)
            return
        end
        local hash = self:ContextHash(context, mainId)
        self.sessions[hash] = self.sessions[hash] or {}
        for _ = 2, math.min(self.instances, self.maxInstances) do
            local extraId = Memory.Alloc(0x40)
            local extraStatus = Memory.Alloc(8)
            if not self:IsPointer(extraId) or not self:IsPointer(extraStatus) then
                if self:IsPointer(extraId) then pcall(Memory.Free, extraId) end
                if self:IsPointer(extraStatus) then pcall(Memory.Free, extraStatus) end
                break
            end
            Memory.MemSet(extraId, 0, 0x40)
            Memory.MemSet(extraStatus, 0, 8)
            if self:CallOriginal(context, extraId, extraStatus) then
                while true do
                    local readExtraOk, extraState = pcall(Memory.ReadInt, extraStatus)
                    if not readExtraOk or extraState ~= 1 then break end
                    Script.Yield(0)
                end
                local readExtraOk, extraState = pcall(Memory.ReadInt, extraStatus)
                if readExtraOk and extraState == 3 then
                    table.insert(self.sessions[hash], {id = extraId, status = extraStatus})
                else
                    pcall(Memory.Free, extraId)
                    pcall(Memory.Free, extraStatus)
                end
            else
                pcall(Memory.Free, extraId)
                pcall(Memory.Free, extraStatus)
            end
        end
        pcall(Memory.WriteInt, context.status, 3)
        pcall(Memory.Free, firstStatus)
    end)
    return false
end

function SovereignMatchmakingAdvertise:OnUpdateContext(context)
    if type(context) ~= "table" or not self:IsPointer(context.id) then return end
    self:PatchAttributes(context.attrs)
    local hash = self:ContextHash(context, context.id)
    for _, extra in ipairs(self.sessions[hash] or {}) do
        if type(self.bridgeUpdate) == "function" then
            pcall(self.bridgeUpdate, context, extra.id)
        end
    end
end

function SovereignMatchmakingAdvertise:OnUnadvertiseContext(context)
    if type(context) ~= "table" or not self:IsPointer(context.id) then return true end
    local hash = self:ContextHash(context, context.id)
    local extras = self.sessions[hash]
    if extras then
        if type(self.bridgeUnadvertise) == "function" then
            for _, extra in ipairs(extras) do pcall(self.bridgeUnadvertise, extra.id) end
        end
        if Memory and type(Memory.Free) == "function" then
            for _, extra in ipairs(extras) do
                if self:IsPointer(extra.id) then pcall(Memory.Free, extra.id) end
                if self:IsPointer(extra.status) then pcall(Memory.Free, extra.status) end
            end
        end
        self.sessions[hash] = nil
    end
    return true
end

local SOVEREIGN_MATCHMAKING_REGIONS = {
    {id = 6, label = "USA (West)"},
    {id = 2, label = "USA (East)"},
    {id = 1, label = "South America"},
    {id = 3, label = "Europe"},
    {id = 5, label = "Australia"},
    {id = 7, label = "Japan"},
    {id = 0, label = "CIS"},
    {id = 4, label = "China"},
    {id = 8, label = "Unknown"},
}

local sovereignPersistedMatchmakingRegion = rawget(_G, "__SOVEREIGN_MATCHMAKING_REGION")
if type(sovereignPersistedMatchmakingRegion) ~= "table" then
    sovereignPersistedMatchmakingRegion = {
    desired = false,
    selectedIndex = 1,
    pointer = 0,
    original = nil,
    applied = nil,
    restorePending = false,
    pendingValue = nil,
    pendingRestore = nil,
    resolvedEdition = nil,
    nextRestoreAt = 0.0,
    nextRefreshAt = 0.0,
    nextResolveAt = 0.0,
    lastRefreshErrorAt = -1000.0,
    lastRestoreErrorAt = -1000.0,
    }
end
SovereignMatchmakingRegion = sovereignPersistedMatchmakingRegion
rawset(_G, "__SOVEREIGN_MATCHMAKING_REGION", SovereignMatchmakingRegion)
SovereignMatchmakingRegion.selectedIndex = math.max(1, math.min(
    #SOVEREIGN_MATCHMAKING_REGIONS,
    tonumber(SovereignMatchmakingRegion.selectedIndex) or 1
))
SovereignMatchmakingRegion.nextRestoreAt = tonumber(SovereignMatchmakingRegion.nextRestoreAt) or 0.0
SovereignMatchmakingRegion.nextRefreshAt = tonumber(SovereignMatchmakingRegion.nextRefreshAt) or 0.0
SovereignMatchmakingRegion.nextResolveAt = tonumber(SovereignMatchmakingRegion.nextResolveAt) or 0.0
SovereignMatchmakingRegion.lastRefreshErrorAt = tonumber(SovereignMatchmakingRegion.lastRefreshErrorAt) or -1000.0
SovereignMatchmakingRegion.lastRestoreErrorAt = tonumber(SovereignMatchmakingRegion.lastRestoreErrorAt) or -1000.0

function SovereignMatchmakingRegion:ClearOwnership()
    self.pointer = 0
    self.original = nil
    self.applied = nil
    self.restorePending = false
    self.pendingValue = nil
    self.pendingRestore = nil
    self.resolvedEdition = nil
    self.nextRestoreAt = 0.0
    self.nextRefreshAt = 0.0
    self.nextResolveAt = 0.0
end

function SovereignMatchmakingRegion:Now()
    return Utils1:NowSeconds()
end

function SovereignMatchmakingRegion:RescanPointer()
    local callOk, scanned, scanError = pcall(
        MemoryBridge.RefreshPointer,
        MemoryBridge,
        "rlRosGetGeoLocInfo"
    )
    if not callOk then return false, scanned end
    return scanned == true, scanError
end

function SovereignMatchmakingRegion:IsWritableModuleAddress(address, width, edition)
    if type(address) ~= "number" or address < 0x10000 then return false end
    width = math.max(1, tonumber(width) or 1)
    local moduleName = sovereignModuleForEdition(edition)
    if not moduleName then return false end
    local ok, valid = pcall(function()
        if not Memory or type(Memory.GetBaseAddress) ~= "function" then return false end
        local base = Memory.GetBaseAddress(moduleName)
        if type(base) ~= "number" or base < 0x10000 then return false end
        if Memory.ReadUShort(base) ~= 0x5A4D then return false end
        local nt = base + Memory.ReadUInt(base + 0x3C)
        if Memory.ReadUInt(nt) ~= 0x00004550 then return false end
        local sectionCount = Memory.ReadUShort(nt + 0x06)
        local optionalSize = Memory.ReadUShort(nt + 0x14)
        local imageSize = Memory.ReadUInt(nt + 0x50)
        if sectionCount < 1 or sectionCount > 96 or imageSize < 0x1000
            or address < base or address + width > base + imageSize then return false end
        local sectionTable = nt + 0x18 + optionalSize
        for index = 0, sectionCount - 1 do
            local section = sectionTable + index * 0x28
            local virtualSize = Memory.ReadUInt(section + 0x08)
            local virtualAddress = Memory.ReadUInt(section + 0x0C)
            local rawSize = Memory.ReadUInt(section + 0x10)
            local characteristics = Memory.ReadUInt(section + 0x24)
            local first = base + virtualAddress
            local last = first + math.max(virtualSize, rawSize)
            if address >= first and address + width <= last then
                return (characteristics & 0x80000000) ~= 0
            end
        end
        return false
    end)
    return ok and valid == true
end

function SovereignMatchmakingRegion:ReadCurrent(pointer)
    local ok, value = pcall(Memory.ReadInt, pointer)
    if not ok or type(value) ~= "number" or value < -1 or value > 8 then
        return nil, ok and ("implausible region value: " .. tostring(value)) or tostring(value)
    end
    return value
end

function SovereignMatchmakingRegion:Resolve(forceRescan)
    local edition = Utils1:edition()
    if edition ~= "Enhanced" and edition ~= "Legacy" then
        return false, "unsupported edition: " .. tostring(edition)
    end
    if forceRescan then
        local scanned, scanError = self:RescanPointer()
        if not scanned then return false, "region signature refresh failed: " .. tostring(scanError) end
    end
    local pointer = MemoryBridge:GetPointer("rlRosGetGeoLocInfo")
    if not self:IsWritableModuleAddress(pointer, 4, edition) then
        local scanned, scanError = self:RescanPointer()
        if not scanned then return false, "region signature refresh failed: " .. tostring(scanError) end
        pointer = MemoryBridge:GetPointer("rlRosGetGeoLocInfo")
    end
    if not self:IsWritableModuleAddress(pointer, 4, edition) then
        return false, "region pointer is unavailable or outside a writable image section"
    end
    local current, readError = self:ReadCurrent(pointer)
    if current == nil then
        local scanned, scanError = self:RescanPointer()
        if not scanned then return false, "region signature refresh failed: " .. tostring(scanError) end
        pointer = MemoryBridge:GetPointer("rlRosGetGeoLocInfo")
        if not self:IsWritableModuleAddress(pointer, 4, edition) then return false, readError end
        current, readError = self:ReadCurrent(pointer)
        if current == nil then return false, readError end
    end
    if (self.applied ~= nil or self.restorePending) and (self.pointer ~= pointer or self.resolvedEdition ~= edition) then
        return false, "region pointer changed while the previous override is still owned"
    end
    if self.pointer ~= pointer or self.resolvedEdition ~= edition or self.original == nil then
        self.pointer = pointer
        self.original = current
        self.applied = nil
        self.resolvedEdition = edition
        Logger:Info("MatchmakingRegion", string.format(
            "resolved edition=%s pointer=0x%X original=%d", edition, pointer, current
        ))
    end
    return true
end

function SovereignMatchmakingRegion:Refresh()
    if self.applied == nil then return true end
    if self.restorePending then return false, "a previous region write is pending restore" end
    local now = self:Now()
    if now >= (self.nextResolveAt or 0.0) then
        self.nextResolveAt = now + 1.0
        local resolved, resolveError = self:Resolve(true)
        if not resolved then return false, "periodic region signature validation failed: " .. tostring(resolveError) end
    end
    local pointerOk, currentPointer = pcall(function()
        return MemoryBridge:GetPointer("rlRosGetGeoLocInfo")
    end)
    if not pointerOk or currentPointer ~= self.pointer then
        local resolved, resolveError = self:Resolve(true)
        if not resolved then return false, "region pointer validation failed: " .. tostring(resolveError) end
    end
    if not self:IsWritableModuleAddress(self.pointer, 4, self.resolvedEdition) then
        local resolved, resolveError = self:Resolve(true)
        if not resolved then return false, "region pointer validation failed: " .. tostring(resolveError) end
    end
    if not self:IsWritableModuleAddress(self.pointer, 4, self.resolvedEdition) then
        return false, "owned region pointer is no longer current"
    end
    local current, readError = self:ReadCurrent(self.pointer)
    if current == nil then
        local resolved, resolveError = self:Resolve(true)
        if not resolved then return false, "region pointer validation failed: " .. tostring(resolveError) end
        current, readError = self:ReadCurrent(self.pointer)
        if current == nil then return false, readError end
    end
    if current == self.applied then return true end

    local target = self.applied
    self.restorePending = true
    self.pendingValue = target
    self.pendingRestore = current
    local writeOk, writeError = pcall(Memory.WriteInt, self.pointer, target)
    local verified = writeOk and self:ReadCurrent(self.pointer) or nil
    if not writeOk or verified ~= target then
        local rollbackOk = pcall(Memory.WriteInt, self.pointer, current)
        local rollbackValue = rollbackOk and self:ReadCurrent(self.pointer) or nil
        if rollbackOk and rollbackValue == current then
            self.restorePending = false
            self.pendingValue = nil
            self.pendingRestore = nil
        end
        return false, string.format(
            "refresh verification failed expected=%d actual=%s rollback=%s error=%s",
            target, tostring(verified), tostring(rollbackOk and rollbackValue == current), tostring(writeError)
        )
    end
    self.restorePending = false
    self.pendingValue = nil
    self.pendingRestore = nil
    return true
end

function SovereignMatchmakingRegion:Apply(regionId)
    if type(regionId) ~= "number" or regionId < 0 or regionId > 8 then
        return false, "invalid region id"
    end
    local resolved, resolveError = self:Resolve(true)
    if not resolved then return false, resolveError end
    local current, readError = self:ReadCurrent(self.pointer)
    if current == nil then return false, readError end
    if self.applied ~= nil and current ~= self.applied then
        local refreshed, refreshError = self:Refresh()
        if not refreshed then return false, "active region refresh failed: " .. tostring(refreshError) end
        current, readError = self:ReadCurrent(self.pointer)
        if current == nil then return false, readError end
    end
    local before = current
    local previousApplied = self.applied
    self.restorePending = true
    self.pendingValue = regionId
    self.pendingRestore = before
    local ok, writeError = pcall(Memory.WriteInt, self.pointer, regionId)
    local verified = ok and self:ReadCurrent(self.pointer) or nil
    if not ok or verified ~= regionId then
        local rollbackOk = pcall(Memory.WriteInt, self.pointer, before)
        local rollbackValue = rollbackOk and self:ReadCurrent(self.pointer) or nil
        if rollbackOk and rollbackValue == before then
            self.restorePending = false
            self.pendingValue = nil
            self.pendingRestore = nil
            if before == self.original then
                self.applied = nil
            else
                self.applied = previousApplied
            end
            if self.applied == nil then self:ClearOwnership() end
        else
            self.applied = previousApplied
        end
        self.desired = false
        return false, string.format(
            "write verification failed expected=%d actual=%s rollback=%s error=%s",
            regionId, tostring(verified), tostring(rollbackOk and rollbackValue == before), tostring(writeError)
        )
    end
    self.applied = regionId
    self.restorePending = false
    self.pendingValue = nil
    self.pendingRestore = nil
    Logger:Info("MatchmakingRegion", string.format(
        "applied region=%d pointer=0x%X original=%d", regionId, self.pointer, self.original
    ))
    return true
end

function SovereignMatchmakingRegion:Enable()
    local entry = SOVEREIGN_MATCHMAKING_REGIONS[self.selectedIndex]
    if not entry then
        self.desired = false
        return false, "region selection is invalid"
    end
    if self.restorePending then
        local restored, restoreError = self:Disable(true)
        if not restored then
            self.desired = false
            return false, "previous region write is still pending: " .. tostring(restoreError)
        end
    end
    local ok, err = self:Apply(entry.id)
    self.desired = ok == true
    if not ok then Logger:Error("MatchmakingRegion", "enable failed: " .. tostring(err)) end
    return ok, err
end

function SovereignMatchmakingRegion:Disable(force)
    self.desired = false
    if self.restorePending and (self.pointer == 0 or self.original == nil) then
        return false, "pending region write metadata is unavailable"
    end
    if not self.restorePending and (self.pointer == 0 or self.original == nil or self.applied == nil) then
        self:ClearOwnership()
        return true
    end
    local now = self:Now()
    if not force and now < (self.nextRestoreAt or 0.0) then return false end
    self.nextRestoreAt = now + 0.5
    local resolved, resolveError = self:Resolve(true)
    local refreshedPointer = resolved and MemoryBridge:GetPointer("rlRosGetGeoLocInfo") or nil
    if not resolved or refreshedPointer ~= self.pointer then
        return false, "owned region pointer changed; refusing stale target: " .. tostring(resolveError)
    end
    if not self:IsWritableModuleAddress(self.pointer, 4, self.resolvedEdition) then
        local resolved, resolveError = self:Resolve(true)
        if not resolved then return false, "owned region pointer is no longer writable: " .. tostring(resolveError) end
    end
    if not self:IsWritableModuleAddress(self.pointer, 4, self.resolvedEdition) then
        return false, "owned region pointer is no longer writable"
    end
    local current, readError = self:ReadCurrent(self.pointer)
    if current == nil then
        local resolved, resolveError = self:Resolve(true)
        if not resolved then return false, "owned region pointer is unreadable: " .. tostring(resolveError) end
        current, readError = self:ReadCurrent(self.pointer)
        if current == nil then return false, readError end
    end
    local function restoreValue(value)
        local writeOk, writeError = pcall(Memory.WriteInt, self.pointer, value)
        local verified = writeOk and self:ReadCurrent(self.pointer) or nil
        if not writeOk or verified ~= value then
            return false, writeError or ("readback=" .. tostring(verified))
        end
        return true
    end
    if self.restorePending then
        local pendingValue = self.pendingValue
        local pendingRestore = self.pendingRestore
        if type(pendingRestore) ~= "number" then pendingRestore = self.original end
        if current == self.original then
            self.restorePending = false
            self.pendingValue = nil
            self.pendingRestore = nil
            self.applied = nil
            self:ClearOwnership()
            return true
        elseif current == pendingValue then
            local restored, restoreError = restoreValue(pendingRestore)
            if not restored then
                return false, "pending region restore failed: " .. tostring(restoreError)
            end
            current = pendingRestore
        elseif current ~= pendingRestore then
            Logger:Error("MatchmakingRegion", "external region change detected; pending ownership released")
            self:ClearOwnership()
            return false, "pending region value changed externally"
        end
        self.restorePending = false
        self.pendingValue = nil
        self.pendingRestore = nil
        if current == self.original then
            self.applied = nil
        else
            self.applied = current
        end
    end
    if self.applied == nil then
        if current == self.original then
            self:ClearOwnership()
            return true
        end
        self:ClearOwnership()
        return false, "region value is not owned by this patch"
    end
    if current ~= self.applied and current ~= self.original then
        Logger:Error("MatchmakingRegion", "external region change detected; ownership released")
        self:ClearOwnership()
        return false, "region value changed externally"
    end
    if current ~= self.original then
        self.restorePending = true
        self.pendingValue = current
        self.pendingRestore = self.original
        local ok, writeError = restoreValue(self.original)
        if not ok then
            return false, "restore verification failed: " .. tostring(writeError)
        end
        self.restorePending = false
        self.pendingValue = nil
        self.pendingRestore = nil
    end
    Logger:Info("MatchmakingRegion", "original region restored value=" .. tostring(self.original))
    self:ClearOwnership()
    return true
end

-- A fresh script instance never inherits an enabled toggle; pending ownership
-- remains so the loop can restore it before any later enable.
SovereignMatchmakingRegion.desired = false

Script.RegisterLooped(function()
    local now = SovereignMatchmakingRegion:Now()
    if SovereignMatchmakingRegion.desired and SovereignMatchmakingRegion.applied ~= nil
        and now >= (SovereignMatchmakingRegion.nextRefreshAt or 0.0) then
        SovereignMatchmakingRegion.nextRefreshAt = now + 0.1
        local callOk, refreshed, refreshError = pcall(
            SovereignMatchmakingRegion.Refresh,
            SovereignMatchmakingRegion
        )
        if not callOk or refreshed ~= true then
            local reason = callOk and (refreshError or refreshed) or refreshed
            if now - (SovereignMatchmakingRegion.lastRefreshErrorAt or -1000.0) >= 5.0 then
                SovereignMatchmakingRegion.lastRefreshErrorAt = now
                Logger:Error("MatchmakingRegion", "active refresh failed: " .. tostring(reason))
            end
            SovereignMatchmakingRegion.desired = false
            local feature = SovereignMatchmakingRegion.feature
            if feature and type(feature.SetToggledSilently) == "function" then
                pcall(feature.SetToggledSilently, feature, false)
            end
        end
    end
    if (SovereignMatchmakingRegion.applied ~= nil or SovereignMatchmakingRegion.restorePending)
        and not SovereignMatchmakingRegion.desired
        and now >= (SovereignMatchmakingRegion.nextRestoreAt or 0.0) then
        local callOk, restored, restoreError = pcall(
            SovereignMatchmakingRegion.Disable,
            SovereignMatchmakingRegion
        )
        if (not callOk or restored ~= true)
            and now - (SovereignMatchmakingRegion.lastRestoreErrorAt or -1000.0) >= 5.0 then
            SovereignMatchmakingRegion.lastRestoreErrorAt = now
            local reason = callOk and (restoreError or restored) or restored
            Logger:Error("MatchmakingRegion", "background restore failed: " .. tostring(reason))
        end
    end
end)

