menu.missionSupport = {busy = false, stopped = false, generation = 0, batchSize = 8, sliceSeconds = 0.0006, maxRadius = 1000.0}

function menu.missionSupport:Call(namespace, name, ...)
    local api = menu.nativeApis and menu.nativeApis[namespace]
    if not api or type(api[name]) ~= "function" then return false, nil end
    return pcall(api[name], ...)
end

function menu.missionSupport:Active()
    -- Teammate/player information utilities are part of the free Information
    -- page and remain local, bounded operations. Paid session controllers still
    -- stay behind their own feature callbacks.
    return not self.stopped and menu.playerWorldPaused ~= true
end

function menu.missionSupport:CancelPending()
    self.generation = self.generation + 1
end

function menu.missionSupport:Shutdown()
    self.stopped = true
    self:CancelPending()
end

function menu.missionSupport:Notify(message, level)
    SovereignNotify("Teammate mission support", message, level or "info")
end

function menu.missionSupport:Yield()
    if not Script or type(Script.Yield) ~= "function" then return false end
    Script.Yield(0)
    return self:Active()
end

function menu.missionSupport:Exists(entity, expectedType)
    if type(entity) ~= "number" or entity <= 0 or entity >= 2147483647 or entity ~= math.floor(entity) then return false end
    local ok, exists = self:Call("ENTITY", "DOES_ENTITY_EXIST", entity)
    if not ok or exists ~= true then return false end
    if expectedType then
        local okType, entityType = self:Call("ENTITY", "GET_ENTITY_TYPE", entity)
        return okType and entityType == expectedType
    end
    return true
end

function menu.missionSupport:Position(entity)
    local ok, value = self:Call("ENTITY", "GET_ENTITY_COORDS", entity, false)
    if not ok or value == nil then return nil end
    local valid, x, y, z = pcall(function() return value.x, value.y, value.z end)
    if not valid then return nil end
    for _, number in ipairs({x, y, z}) do
        if type(number) ~= "number" or number ~= number or math.abs(number) >= 1000000 then return nil end
    end
    if x == nil or y == nil or z == nil then return nil end
    return {x = x, y = y, z = z}
end

function menu.missionSupport:Distance(a, b)
    if not a or not b then return nil end
    local x, y, z = a.x - b.x, a.y - b.y, a.z - b.z
    return x * x + y * y + z * z
end

function menu.missionSupport:CapturePlayer(pid)
    if type(pid) ~= "number" or pid < 0 or pid > 31 or pid ~= math.floor(pid) then return nil, "Invalid player" end
    local activeOk, active = self:Call("NETWORK", "NETWORK_IS_PLAYER_ACTIVE", pid)
    if not activeOk or active ~= true then return nil, "The player has left" end
    local pedOk, ped = self:Call("PLAYER", "GET_PLAYER_PED_SCRIPT_INDEX", pid)
    if not pedOk or not self:Exists(ped, 1) then return nil, "The player is not streamed in yet" end
    local playerOk, player = self:Call("PED", "IS_PED_A_PLAYER", ped)
    if not playerOk or player ~= true then return nil, "The player's character is unavailable" end
    local ridOk, rid = false, nil
    if PlayerManager and type(PlayerManager.GetRockstarId) == "function" then
        local ok, found, result = pcall(PlayerManager.GetRockstarId, PlayerManager, pid)
        ridOk, rid = ok and found == true, result
    end
    -- Delayed jobs must never target a new occupant of the same PID slot.
    if not ridOk or rid == nil or tostring(rid) == "0" then return nil, "The player's identity is not ready" end
    return {pid = pid, ped = ped, rid = tostring(rid)}
end

function menu.missionSupport:SamePlayer(target)
    if not target or not self:Active() then return false end
    local current = self:CapturePlayer(target.pid)
    return current and current.ped == target.ped and current.rid == target.rid or false
end

function menu.missionSupport:InRange(entity, anchor, radius)
    local squared = self:Distance(self:Position(entity), self:Position(anchor))
    return squared ~= nil and squared <= radius * radius
end

function menu.missionSupport:LocalPlayer()
    local ok, pid = self:Call("PLAYER", "PLAYER_ID")
    if not ok then return nil, "Your character is unavailable" end
    return self:CapturePlayer(pid)
end

function menu.missionSupport:HasControl(entity)
    local ok, networked = self:Call("NETWORK", "NETWORK_GET_ENTITY_IS_NETWORKED", entity)
    if not ok then return false end
    if networked == false then return true end
    local controlledOk, controlled = self:Call("NETWORK", "NETWORK_HAS_CONTROL_OF_ENTITY", entity)
    return controlledOk and controlled == true
end

function menu.missionSupport:AcquireControl(entity, validator, attempts)
    for attempt = 0, (attempts or 8) do
        if not self:Active() or not self:Exists(entity) or not validator() then return false, "The target changed" end
        if self:HasControl(entity) then return true end
        if attempt == (attempts or 8) then break end
        local ok = self:Call("NETWORK", "NETWORK_REQUEST_CONTROL_OF_ENTITY", entity)
        if not ok then return false, "The entity control interface is unavailable" end
        if not self:Yield() then return false, "The session has stopped" end
    end
    return false, "Could not obtain control of the entity"
end

function menu.missionSupport:WithVehicle(pid, callback)
    if not self:Active() then return false, "The session has stopped" end
    local generation = self.generation
    local target, reason = self:CapturePlayer(pid)
    if not target then return false, reason end
    local owner, localReason = self:LocalPlayer()
    if not owner then return false, localReason end
    if not self:InRange(target.ped, owner.ped, self.maxRadius) then return false, "Move within 1,000 meters of your teammate first" end
    local ok, vehicle = self:Call("PED", "GET_VEHICLE_PED_IS_IN", target.ped, false)
    if not ok or not self:Exists(vehicle, 2) then return false, "Your teammate is not in a vehicle" end
    local modelOk, model = self:Call("ENTITY", "GET_ENTITY_MODEL", vehicle)
    if not modelOk then return false, "The vehicle is unavailable" end
    local function stillCurrent()
        if generation ~= self.generation or not self:SamePlayer(target) or not self:SamePlayer(owner) or not self:Exists(vehicle, 2) then return false end
        local currentOk, current = self:Call("PED", "GET_VEHICLE_PED_IS_IN", target.ped, false)
        local currentModelOk, currentModel = self:Call("ENTITY", "GET_ENTITY_MODEL", vehicle)
        return currentOk and current == vehicle and currentModelOk and currentModel == model
            and self:InRange(target.ped, owner.ped, self.maxRadius)
    end
    local controlled, controlReason = self:AcquireControl(vehicle, stillCurrent, 8)
    if not controlled then return false, controlReason end
    return callback(vehicle, target.ped, stillCurrent)
end

function menu.missionSupport:RepairVehicle(pid)
    return self:WithVehicle(pid, function(vehicle, _, current)
        local ok = self:Call("VEHICLE", "SET_VEHICLE_FIXED", vehicle)
        if not ok then return false, "The repair interface is unavailable" end
        self:Call("VEHICLE", "SET_VEHICLE_DEFORMATION_FIXED", vehicle)
        self:Call("VEHICLE", "SET_VEHICLE_ENGINE_HEALTH", vehicle, 1000.0)
        self:Call("VEHICLE", "SET_VEHICLE_PETROL_TANK_HEALTH", vehicle, 1000.0)
        if not self:Yield() or not current() then return false, "The target changed" end
        local readOk, health = self:Call("VEHICLE", "GET_VEHICLE_ENGINE_HEALTH", vehicle)
        if not readOk or type(health) ~= "number" or health < 999.0 then return false, "Repairs could not be confirmed" end
        return true, "Your teammate's vehicle has been repaired"
    end)
end

function menu.missionSupport:UprightVehicle(pid)
    return self:WithVehicle(pid, function(vehicle, _, current)
        local speedOk, speed = self:Call("ENTITY", "GET_ENTITY_SPEED", vehicle)
        if not speedOk or type(speed) ~= "number" or speed > 3.0 then return false, "Ask your teammate to stop before righting the vehicle" end
        local airOk, inAir = self:Call("ENTITY", "IS_ENTITY_IN_AIR", vehicle)
        if not airOk or inAir ~= false then return false, "The vehicle is not on the ground yet" end
        local ok, grounded = self:Call("VEHICLE", "SET_VEHICLE_ON_GROUND_PROPERLY", vehicle, 5.0)
        if not ok or grounded ~= true then return false, "No suitable ground was found" end
        if not self:Yield() or not current() then return false, "The target changed" end
        local uprightOk, upright = self:Call("ENTITY", "IS_ENTITY_UPRIGHT", vehicle, 30.0)
        return uprightOk and upright == true, uprightOk and upright == true and "Your teammate's vehicle has been righted" or "The vehicle's upright position could not be confirmed"
    end)
end

function menu.missionSupport:UnlockVehicle(pid)
    return self:WithVehicle(pid, function(vehicle, _, current)
        local owner = self:LocalPlayer()
        if not owner then return false, "Your character is unavailable" end
        local ok = self:Call("VEHICLE", "SET_VEHICLE_DOORS_LOCKED", vehicle, 1)
        local playerOk = self:Call("VEHICLE", "SET_VEHICLE_DOORS_LOCKED_FOR_PLAYER", vehicle, owner.pid, false)
        if not ok or not playerOk then return false, "The unlock interface is unavailable" end
        if not self:Yield() or not current() then return false, "The target changed" end
        local readOk, lock = self:Call("VEHICLE", "GET_VEHICLE_DOOR_LOCK_STATUS", vehicle)
        local allowedOk, blocked = self:Call("VEHICLE", "GET_VEHICLE_DOORS_LOCKED_FOR_PLAYER", vehicle, owner.pid)
        local success = readOk and lock == 1 and allowedOk and blocked == false
        return success, success and "Your teammate's vehicle is unlocked. You can try entering it." or "The door lock state could not be confirmed"
    end)
end

function menu.missionSupport:ExtinguishVehicle(pid)
    return self:WithVehicle(pid, function(vehicle, _, current)
        local deadOk, dead = self:Call("ENTITY", "IS_ENTITY_DEAD", vehicle, false)
        local engineOk, engine = self:Call("VEHICLE", "GET_VEHICLE_ENGINE_HEALTH", vehicle)
        local tankOk, tank = self:Call("VEHICLE", "GET_VEHICLE_PETROL_TANK_HEALTH", vehicle)
        if not deadOk or dead ~= false then return false, "Emergency fire suppression is unavailable for destroyed vehicles" end
        if not engineOk or not tankOk or type(engine) ~= "number" or type(tank) ~= "number"
            or engine ~= engine or tank ~= tank then return false, "The vehicle state is unavailable" end
        if not self:Call("FIRE", "STOP_ENTITY_FIRE", vehicle) then return false, "The fire suppression interface is unavailable" end
        -- Restore only the minimum usable health; do not replace modifications,
        -- enable invincibility, or alter the driver's engine-on preference.
        if engine < 400.0 and not self:Call("VEHICLE", "SET_VEHICLE_ENGINE_HEALTH", vehicle, 400.0) then return false, "Could not restore the engine" end
        if tank < 400.0 and not self:Call("VEHICLE", "SET_VEHICLE_PETROL_TANK_HEALTH", vehicle, 400.0) then return false, "Could not restore the fuel tank" end
        if not self:Call("VEHICLE", "SET_VEHICLE_UNDRIVEABLE", vehicle, false) then return false, "Could not restore drivability" end
        if not self:Yield() or not current() then return false, "The target changed" end
        local fireOk, fire = self:Call("FIRE", "IS_ENTITY_ON_FIRE", vehicle)
        local driveOk, drive = self:Call("VEHICLE", "IS_VEHICLE_DRIVEABLE", vehicle, true)
        local success = fireOk and fire == false and driveOk and drive == true
        return success, success and "The vehicle fire is out and drivability has been restored" or "Fire suppression or drivability could not be confirmed"
    end)
end

function menu.missionSupport:RestoreTyres(pid)
    return self:WithVehicle(pid, function(vehicle, _, current)
        local changed = {}
        -- Native wheel IDs include the middle axle of six-wheel trailers.
        for index, wheel in ipairs({0, 1, 2, 3, 4, 5, 45, 47}) do
            if not current() or not self:HasControl(vehicle) then return false, "The target or entity control changed" end
            local ok, burst = self:Call("VEHICLE", "IS_VEHICLE_TYRE_BURST", vehicle, wheel, false)
            if not ok then return false, "Tire condition is unavailable" end
            if burst == true then
                if not self:Call("VEHICLE", "SET_VEHICLE_TYRE_FIXED", vehicle, wheel) then return false, "Tire repair failed" end
                changed[#changed + 1] = wheel
            end
            if index % 4 == 0 and not self:Yield() then return false, "The session has stopped" end
        end
        if not current() then return false, "The target changed" end
        for _, wheel in ipairs(changed) do
            local ok, burst = self:Call("VEHICLE", "IS_VEHICLE_TYRE_BURST", vehicle, wheel, false)
            if not ok or burst ~= false then return false, "Tire repairs could not be confirmed" end
        end
        return true, #changed == 0 and "Your teammate's tires are already in good condition" or "Your teammate's damaged tires have been repaired"
    end)
end

function menu.missionSupport:OutdoorStationary(entity)
    local interiorOk, interior = self:Call("INTERIOR", "GET_INTERIOR_FROM_ENTITY", entity)
    local deadOk, dead = self:Call("ENTITY", "IS_ENTITY_DEAD", entity, false)
    local airOk, air = self:Call("ENTITY", "IS_ENTITY_IN_AIR", entity)
    local waterOk, water = self:Call("ENTITY", "IS_ENTITY_IN_WATER", entity)
    local speedOk, speed = self:Call("ENTITY", "GET_ENTITY_SPEED", entity)
    return interiorOk and interior == 0 and deadOk and dead == false and airOk and air == false
        and waterOk and water == false and speedOk and type(speed) == "number" and speed >= 0 and speed <= 3.0
end

function menu.missionSupport:MoveContext(pid)
    if not self:Active() then return nil, "The session has stopped" end
    local owner, reason = self:LocalPlayer()
    local target, targetReason = self:CapturePlayer(pid)
    if not owner or not target then return nil, reason or targetReason end
    if owner.pid == target.pid then return nil, "Select a teammate first" end
    if not self:InRange(owner.ped, target.ped, self.maxRadius) then return nil, "Move within 1,000 meters of your teammate first" end
    local context = {owner = owner, target = target, generation = self.generation}
    function context.current()
        return context.generation == menu.missionSupport.generation
            and menu.missionSupport:SamePlayer(owner) and menu.missionSupport:SamePlayer(target)
            and menu.missionSupport:OutdoorStationary(owner.ped) and menu.missionSupport:OutdoorStationary(target.ped)
            and menu.missionSupport:InRange(owner.ped, target.ped, menu.missionSupport.maxRadius)
    end
    if not context.current() then return nil, "Both players must be stationary on outdoor ground, not in water or midair" end
    return context
end

function menu.missionSupport:FindGroundedPoint(context, vehicle, radius, minZ)
    if not Memory or type(Memory.Alloc) ~= "function" or type(Memory.ReadFloat) ~= "function"
        or type(Memory.WriteFloat) ~= "function" or type(Memory.Free) ~= "function" then return nil, "Destination validation is unavailable" end
    local buffer
    local ok, point, reason = pcall(function()
        buffer = Memory.Alloc(32)
        if not buffer or buffer == 0 then return nil, "Could not allocate destination validation data" end
        for offset = 0, 28, 4 do Memory.WriteFloat(buffer + offset, 0.0) end
        for attempt = 1, 4 do
            if not context.current() then return nil, "The target changed or is still moving" end
            local anchor = self:Position(context.target.ped)
            if not anchor then return nil, "Your teammate's position is unavailable" end
            self:Call("STREAMING", "REQUEST_COLLISION_AT_COORD", anchor.x, anchor.y, anchor.z)
            if not self:Yield() or not context.current() then return nil, "The target changed" end
            local foundOk, found
            if vehicle then
                -- Flags 0 excludes switched-off and boat nodes. Two metres of
                -- height tolerance avoids selecting a road under a bridge.
                foundOk, found = self:Call("PATHFIND", "GET_NTH_CLOSEST_VEHICLE_NODE", anchor.x, anchor.y, anchor.z, attempt, buffer, 0, 3.0, 2.0)
            else
                local offset = ({ {4.0, 0.0}, {-4.0, 0.0}, {0.0, 4.0}, {0.0, -4.0} })[attempt]
                -- 14 = not isolated | not interior | not water navmesh.
                foundOk, found = self:Call("PATHFIND", "GET_SAFE_COORD_FOR_PED", anchor.x + offset[1], anchor.y + offset[2], anchor.z, false, buffer, 14)
            end
            if foundOk and found == true then
                local pos = {x = Memory.ReadFloat(buffer), y = Memory.ReadFloat(buffer + 8), z = Memory.ReadFloat(buffer + 16)}
                local finite = true
                for _, value in ipairs({pos.x, pos.y, pos.z}) do
                    if type(value) ~= "number" or value ~= value or math.abs(value) > 100000 then finite = false end
                end
                if pos.x == nil or pos.y == nil or pos.z == nil then finite = false end
                local distance = finite and self:Distance(pos, anchor) or nil
                if distance and distance >= (vehicle and 6.0 or 2.0)^2 and distance <= (vehicle and 60.0 or 20.0)^2 and math.abs(pos.z - anchor.z) <= 4.0 then
                    local groundOk, groundFound = self:Call("MISC", "GET_GROUND_Z_FOR_3D_COORD", pos.x, pos.y, pos.z + 3.0, buffer + 24, false, false)
                    local ground = groundOk and groundFound == true and Memory.ReadFloat(buffer + 24) or nil
                    if type(ground) == "number" and ground == ground and math.abs(ground - pos.z) <= 2.5 then
                        local waterOk, water = self:Call("WATER", "GET_WATER_HEIGHT", pos.x, pos.y, pos.z + 3.0, buffer + 28)
                        local waterLevel = waterOk and water == true and Memory.ReadFloat(buffer + 28) or nil
                        if waterOk and (water == false or (type(waterLevel) == "number" and waterLevel < ground - 0.1)) then
                            local occupiedOk, occupied = self:Call("MISC", "IS_POSITION_OCCUPIED", pos.x, pos.y, ground + 1.0, radius, false, true, true, false, false, vehicle or context.owner.ped, false)
                            if occupiedOk and occupied == false then
                                pos.z = ground + (vehicle and -minZ + 0.15 or 1.0)
                                return pos
                            end
                        end
                    end
                end
            end
        end
        return nil, "No clear, loaded, safe destination was found near your teammate"
    end)
    if buffer and buffer ~= 0 then pcall(Memory.Free, buffer) end
    return ok and point or nil, ok and reason or "Destination validation failed"
end

function menu.missionSupport:TeleportNearTeammate(pid)
    local context, reason = self:MoveContext(pid)
    if not context then return false, reason end
    local onFoot, vehicle = self:Call("PED", "GET_VEHICLE_PED_IS_IN", context.owner.ped, false)
    if not onFoot or vehicle ~= 0 then return false, "Leave your vehicle before approaching your teammate on foot" end
    local function current()
        local ok, currentVehicle = self:Call("PED", "GET_VEHICLE_PED_IS_IN", context.owner.ped, false)
        return context.current() and ok and currentVehicle == 0
    end
    local destination, pointReason = self:FindGroundedPoint(context, nil, 1.2, 0)
    if not destination then return false, pointReason end
    local controlled, controlReason = self:AcquireControl(context.owner.ped, current, 4)
    if not controlled then return false, controlReason end
    if not self:LandingStillClear(context, destination, 1.2, nil) then return false, "The destination is occupied or your teammate moved" end
    local moved = self:Call("ENTITY", "SET_ENTITY_COORDS_NO_OFFSET", context.owner.ped, destination.x, destination.y, destination.z, false, false, false)
    if not moved or not self:Yield() or not self:SamePlayer(context.owner) then return false, "Your new position could not be confirmed" end
    local squared = self:Distance(self:Position(context.owner.ped), destination)
    return squared ~= nil and squared <= 4.0, squared ~= nil and squared <= 4.0 and "Moved to a ground position near your teammate" or "Your new position could not be confirmed"
end

function menu.missionSupport:VehicleFootprint(vehicle)
    if not Memory or type(Memory.Alloc) ~= "function" or type(Memory.ReadFloat) ~= "function"
        or type(Memory.WriteFloat) ~= "function" or type(Memory.Free) ~= "function" then return nil end
    local buffer
    local ok, radius, minZ = pcall(function()
        local modelOk, model = self:Call("ENTITY", "GET_ENTITY_MODEL", vehicle)
        if not modelOk then return nil end
        local carOk, car = self:Call("VEHICLE", "IS_THIS_MODEL_A_CAR", model)
        if not carOk or car ~= true then return nil end
        buffer = Memory.Alloc(48)
        if not buffer or buffer == 0 then return nil end
        for offset = 0, 44, 4 do Memory.WriteFloat(buffer + offset, 0.0) end
        if not self:Call("MISC", "GET_MODEL_DIMENSIONS", model, buffer, buffer + 24) then return nil end
        local low, high = {}, {}
        for index = 1, 3 do
            low[index], high[index] = Memory.ReadFloat(buffer + (index - 1) * 8), Memory.ReadFloat(buffer + 24 + (index - 1) * 8)
            if type(low[index]) ~= "number" or type(high[index]) ~= "number" or low[index] ~= low[index] or high[index] ~= high[index]
                or low[index] >= high[index] or math.abs(low[index]) > 20 or math.abs(high[index]) > 20 then return nil end
        end
        if high[1] - low[1] > 3.0 or high[2] - low[2] > 7.0 or high[3] - low[3] > 3.5 then return nil end
        return math.max(high[1] - low[1], high[2] - low[2]) * 0.5 + 0.8, low[3]
    end)
    if buffer and buffer ~= 0 then pcall(Memory.Free, buffer) end
    if not ok then return nil end
    return radius, minZ
end

function menu.missionSupport:LandingStillClear(context, destination, radius, vehicle)
    if not context.current() then return false end
    local squared = self:Distance(destination, self:Position(context.target.ped))
    if not squared or squared < (vehicle and 6.0 or 2.0)^2 or squared > (vehicle and 60.0 or 20.0)^2 then return false end
    local ok, occupied = self:Call("MISC", "IS_POSITION_OCCUPIED", destination.x, destination.y, destination.z,
        radius, false, true, true, false, false, vehicle or context.owner.ped, false)
    return ok and occupied == false
end

function menu.missionSupport:BringOwnVehicle(pid)
    local context, reason = self:MoveContext(pid)
    if not context then return false, reason end
    local vehicleOk, vehicle = self:Call("PED", "GET_VEHICLE_PED_IS_IN", context.owner.ped, false)
    if not vehicleOk or not self:Exists(vehicle, 2) then return false, "Get into the driver's seat of a pickup car and stop first" end
    local modelOk, model = self:Call("ENTITY", "GET_ENTITY_MODEL", vehicle)
    local function current()
        if not modelOk or not context.current() or not self:Exists(vehicle, 2) or not self:OutdoorStationary(vehicle) then return false end
        local currentOk, currentVehicle = self:Call("PED", "GET_VEHICLE_PED_IS_IN", context.owner.ped, false)
        local driverOk, driver = self:Call("VEHICLE", "GET_PED_IN_VEHICLE_SEAT", vehicle, -1, false)
        local passengersOk, passengers = self:Call("VEHICLE", "GET_VEHICLE_NUMBER_OF_PASSENGERS", vehicle, false, true)
        local currentModelOk, currentModel = self:Call("ENTITY", "GET_ENTITY_MODEL", vehicle)
        return currentOk and currentVehicle == vehicle and driverOk and driver == context.owner.ped and passengersOk and passengers == 0
            and currentModelOk and currentModel == model
    end
    if not current() then return false, "Only a stationary car you are driving, with no other occupants, can be moved" end
    local radius, minZ = self:VehicleFootprint(vehicle)
    if not radius then return false, "Only standard-size cars are supported; large and special vehicles will not be moved" end
    local destination, pointReason = self:FindGroundedPoint(context, vehicle, radius, minZ)
    if not destination then return false, pointReason end
    local controlled, controlReason = self:AcquireControl(vehicle, current, 8)
    if not controlled then return false, controlReason end
    if not self:LandingStillClear(context, destination, radius, vehicle) then return false, "The destination is occupied or your teammate moved" end
    local moved = self:Call("ENTITY", "SET_ENTITY_COORDS_NO_OFFSET", vehicle, destination.x, destination.y, destination.z, false, false, false)
    if not moved or not self:Yield() or not current() then return false, "The pickup car's new position could not be confirmed" end
    local squared = self:Distance(self:Position(vehicle), destination)
    return squared ~= nil and squared <= 9.0, squared ~= nil and squared <= 9.0 and "The pickup car is now on a road near your teammate" or "The pickup car's new position could not be confirmed"
end

function menu.missionSupport:JoinPassenger(pid)
    if not self:Active() then return false, "The session has stopped" end
    local generation = self.generation
    local target, reason = self:CapturePlayer(pid)
    local owner, localReason = self:LocalPlayer()
    if not target or not owner then return false, reason or localReason end
    if target.pid == owner.pid then return false, "Select a teammate first" end
    if not self:InRange(target.ped, owner.ped, self.maxRadius) then return false, "Move within 1,000 meters of your teammate first" end
    local ok, vehicle = self:Call("PED", "GET_VEHICLE_PED_IS_IN", target.ped, false)
    if not ok or not self:Exists(vehicle, 2) then return false, "Your teammate is not in a vehicle" end
    local seatsOk, count = self:Call("VEHICLE", "GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS", vehicle)
    if not seatsOk or type(count) ~= "number" or count < 1 or count > 32 then return false, "No passenger seat is available" end
    for seat = 0, math.floor(count) - 1 do
        local freeOk, free = self:Call("VEHICLE", "IS_VEHICLE_SEAT_FREE", vehicle, seat, true)
        if freeOk and free == true then
            local entered = self:Call("PED", "SET_PED_INTO_VEHICLE", owner.ped, vehicle, seat)
            if not entered or not self:Yield() or generation ~= self.generation or not self:SamePlayer(owner) or not self:SamePlayer(target) then return false, "Could not enter the seat" end
            local checkOk, occupant = self:Call("VEHICLE", "GET_PED_IN_VEHICLE_SEAT", vehicle, seat, false)
            return checkOk and occupant == owner.ped, checkOk and occupant == owner.ped and "Entered an empty passenger seat in your teammate's vehicle" or "The seat is occupied or could not be entered"
        end
    end
    return false, "Your teammate's vehicle has no empty passenger seats; the driver is left in place"
end

function menu.missionSupport:Waypoint(pid)
    if not self:Active() then return false, "The session has stopped" end
    local target, reason = self:CapturePlayer(pid)
    if not target then return false, reason end
    local pos = self:Position(target.ped)
    if not pos then return false, "Your teammate's position is unavailable" end
    local ok = self:Call("HUD", "SET_NEW_WAYPOINT", pos.x, pos.y)
    return ok, ok and "Marked your teammate's current position" or "The navigation interface is unavailable"
end

function menu.missionSupport:PedAt(slot)
    if PoolMgr and type(PoolMgr.GetPed) == "function" then
        local ok, handle = pcall(PoolMgr.GetPed, slot)
        if ok and type(handle) == "number" then return handle end
    end
    if PoolMgr and type(PoolMgr.GetCPed) == "function" and GTA and type(GTA.PointerToHandle) == "function" then
        local ok, handle = pcall(function()
            local ped = PoolMgr.GetCPed(slot)
            if not ped then return nil end
            return GTA.PointerToHandle(ped)
        end)
        if ok then return handle end
    end
    return nil
end

function menu.missionSupport:IsNpc(ped)
    if not self:Exists(ped, 1) then return false end
    local ok, isPlayer = self:Call("PED", "IS_PED_A_PLAYER", ped)
    return ok and isPlayer == false
end

function menu.missionSupport:MatchesNpc(ped, mode, target, owner)
    if not self:IsNpc(ped) or ped == target.ped or ped == owner.ped then return false end
    if not self:InRange(ped, owner.ped, self.maxRadius) then return false end
    local attachedOk, attached = self:Call("ENTITY", "IS_ENTITY_ATTACHED", ped)
    if not attachedOk or attached ~= false then return false end
    local deadOk, dead = self:Call("ENTITY", "IS_ENTITY_DEAD", ped, false)
    if not deadOk then return false end
    if mode == "corpses" then return dead == true end
    if mode ~= "hostile" or dead ~= false or not self:InRange(ped, target.ped, 250.0) then return false end
    -- A red blip or relationship group alone is not evidence that this NPC
    -- attacks the selected teammate. Require the actual combat target.
    local combatOk, combat = self:Call("PED", "IS_PED_IN_COMBAT", ped, target.ped)
    return combatOk and combat == true
end

function menu.missionSupport:DeleteNpc(ped)
    if not self:IsNpc(ped) or not self:HasControl(ped) then return false end
    if not Memory or type(Memory.AllocInt) ~= "function" or type(Memory.WriteInt) ~= "function" or type(Memory.Free) ~= "function" then return false end
    local pointer
    local ok = pcall(function()
        pointer = Memory.AllocInt()
        if not pointer or pointer == 0 then return end
        Memory.WriteInt(pointer, ped)
        if self:Call("ENTITY", "SET_ENTITY_AS_MISSION_ENTITY", ped, true, true) then
            self:Call("ENTITY", "DELETE_ENTITY", pointer)
        end
    end)
    if pointer and pointer ~= 0 then pcall(Memory.Free, pointer) end
    if not ok then return false end
    local existsOk, exists = self:Call("ENTITY", "DOES_ENTITY_EXIST", ped)
    return existsOk and exists == false
end

function menu.missionSupport:Cleanup(mode, pid)
    if self.busy then return false, "NPC cleanup is already running" end
    if not self:Active() then return false, "The session has stopped" end
    local owner, reason = self:LocalPlayer()
    if not owner then return false, reason end
    local target = owner
    if pid ~= nil then target, reason = self:CapturePlayer(pid) end
    if not target then return false, reason end
    if not self:InRange(target.ped, owner.ped, self.maxRadius) then return false, "Move within 1,000 meters of your teammate first" end
    if mode ~= "corpses" and mode ~= "hostile" then return false, "Invalid cleanup mode" end
    if not PoolMgr or type(PoolMgr.GetMaxPedCount) ~= "function" then return false, "The NPC pool is unavailable" end
    local poolOk, count = pcall(PoolMgr.GetMaxPedCount)
    if not poolOk or type(count) ~= "number" or count ~= math.floor(count) or count < 0 or count > 8192 then return false, "The NPC pool is unavailable" end
    self.busy = true
    local generation = self.generation
    local summary = {scanned = 0, matched = 0, deleted = 0, skipped = 0, cancelled = false}
    local success, err = pcall(function()
        local started, budget = os.clock(), 0
        for slot = 0, count - 1 do
            if generation ~= self.generation or not self:Active() then summary.cancelled = true; break end
            local ped = self:PedAt(slot)
            summary.scanned = summary.scanned + 1
            if self:MatchesNpc(ped, mode, target, owner) then
                summary.matched = summary.matched + 1
                local modelOk, model = self:Call("ENTITY", "GET_ENTITY_MODEL", ped)
                local function stillCurrent()
                    if generation ~= self.generation or not modelOk or self:PedAt(slot) ~= ped or not self:SamePlayer(target) or not self:SamePlayer(owner) then return false end
                    local currentOk, current = self:Call("ENTITY", "GET_ENTITY_MODEL", ped)
                    return currentOk and current == model and self:MatchesNpc(ped, mode, target, owner)
                end
                local controlled = self:AcquireControl(ped, stillCurrent, 4)
                if controlled and self:DeleteNpc(ped) then summary.deleted = summary.deleted + 1 else summary.skipped = summary.skipped + 1 end
            end
            budget = budget + 1
            if budget >= self.batchSize or os.clock() - started >= self.sliceSeconds then
                if not self:Yield() or generation ~= self.generation or not self:SamePlayer(target) or not self:SamePlayer(owner) then summary.cancelled = true; break end
                started, budget = os.clock(), 0
            end
        end
    end)
    self.busy = false
    self.lastCleanup = summary
    if not success then return false, "Cleanup stopped: " .. tostring(err), summary end
    return not summary.cancelled, string.format("Deleted %d NPCs; skipped %d%s", summary.deleted, summary.skipped, summary.cancelled and " (player or session changed)" or ""), summary
end

function menu.missionSupport:Run(method, pid)
    if not self:Active() then return false end
    local ok, success, message = pcall(function()
        if method == "corpses" or method == "hostile" then return self:Cleanup(method, pid) end
        return self[method](self, pid)
    end)
    self:Notify(ok and message or "Operation failed", ok and success and "success" or "warning")
    return ok and success == true
end

