-- Local-only teammate observations. No remote entity writes or script events.
menu.teammateTracking = (function()
    local api = {navigation = nil, status = nil, keys = {"navigation", "status"}, cursor = 1,
        nextPoll = 0, clock = 0, stopped = false}
    local stateKeys = {navigation = "team_support_live_navigation", status = "team_support_status_alerts"}
    local function validNumber(n)
        return type(n) == "number" and n == n and math.abs(n) < 1000000
    end
    local function translated(text)
        return type(menu.translate) == "function" and menu.translate(text) or text
    end
    local function call(namespace, name, ...)
        return menu.missionSupport:Call(namespace, name, ...)
    end
    function api:Active()
        return not self.stopped and menu.playerWorldPaused ~= true and menu.missionSupport:Active()
    end
    function api:Notify(row, message, level)
        SovereignNotify("Teammate mission support", row.label .. ": " .. translated(message), level or "info")
    end
    function api:Stop(kind)
        local row = self[kind]
        if row and row.state then row.state[stateKeys[kind]] = false end
        self[kind] = nil
    end
    function api:Cleanup()
        self:Stop("navigation")
        self:Stop("status")
        self.nextPoll, self.lastRaw, self.clock = 0, nil, 0
        -- Deduplication timestamps use this clock too. Keeping old timestamps
        -- after resetting it can suppress a fresh session's alerts for hours.
        self.lastNoticeAt, self.lastNoticeText = nil, nil
        self.lastTerminalAt, self.lastTerminalRid = nil, nil
        -- Do not erase a waypoint: the user may have replaced it manually.
    end
    function api:Shutdown()
        self.stopped = true
        self:Cleanup()
    end
    function api:Set(kind, pid, enabled, state)
        if not stateKeys[kind] then return false end
        if enabled ~= true then
            -- Disabling a toggle must stop the locked row even if the menu's
            -- current selection changed after it was enabled.
            self:Stop(kind)
            if state then state[stateKeys[kind]] = false end
            return true
        end
        if not self:Active() then if state then state[stateKeys[kind]] = false end; return false end
        local target, reason = menu.missionSupport:CapturePlayer(pid)
        if not target then
            if state then state[stateKeys[kind]] = false end
            SovereignNotify("Teammate mission support", reason or "Teammate is not ready", "warning")
            return false
        end
        self:Stop(kind)
        local name = "Player #" .. tostring(pid)
        if Players and type(Players.GetName) == "function" then
            local ok, found = pcall(Players.GetName, pid)
            if ok and type(found) == "string" and found ~= "" then name = found:gsub("[%c]", " "):sub(1, 64) end
        end
        self[kind] = {kind = kind, pid = target.pid, rid = target.rid, ped = target.ped,
            label = name, state = state, nextAt = 0, nextNotice = 0, pending = {}, values = {}}
        if state then state[stateKeys[kind]] = true end
        self.nextPoll = 0
        return true
    end
    function api:Resolve(row)
        local activeOk, active = call("NETWORK", "NETWORK_IS_PLAYER_ACTIVE", row.pid)
        if activeOk and active == false then return nil, "Teammate left; tracking stopped", true end
        if not activeOk then return nil, "Teammate status is temporarily unavailable" end
        local ridOk, found, rid = pcall(PlayerManager.GetRockstarId, PlayerManager, row.pid)
        if not ridOk or found ~= true or not rid or tostring(rid) == "0" then return nil, "Teammate identity is temporarily unavailable" end
        if tostring(rid) ~= row.rid then return nil, "Another player occupies this slot; tracking stopped", true end
        local target = menu.missionSupport:CapturePlayer(row.pid)
        if not target then return nil, "Teammate is not streamed; waiting for recovery" end
        if target.rid ~= row.rid then return nil, "Player identity changed; tracking stopped", true end
        local deadOk, dead = call("ENTITY", "IS_ENTITY_DEAD", target.ped, false)
        if not deadOk then return nil, "Teammate status is temporarily unavailable" end
        if dead then return nil, "Teammate is down; waiting for respawn" end
        local position = menu.missionSupport:Position(target.ped)
        if not position then return nil, "Teammate position is temporarily unavailable" end
        -- A new ped is allowed only after the same RID was revalidated; this
        -- follows respawns without retargeting a replacement occupant of a PID.
        row.ped = target.ped
        return position
    end
    function api:QueueNotice(row, key, message, level)
        row.pending[key] = {message = message, level = level or "warning"}
    end
    function api:FlushNotice(row, now)
        if now < row.nextNotice then return end
        local messages, severity = {}, "info"
        for _, key in ipairs({"signal", "health", "armour", "vehicle"}) do
            local event = row.pending[key]
            if event then
                messages[#messages + 1] = translated(event.message)
                if event.level == "warning" then severity = "warning" end
                row.pending[key] = nil
            end
        end
        if #messages > 0 then
            local text = row.label .. ": " .. table.concat(messages, "; ")
            if self.lastNoticeText ~= text or now - (self.lastNoticeAt or -5000) >= 5000 then
                SovereignNotify("Teammate mission support", text, severity)
                self.lastNoticeText, self.lastNoticeAt = text, now
            end
            row.nextNotice = now + 5000
        end
    end
    function api:Observe(row, key, low, recovered, lowText, recoveredText)
        local previous = row.values[key]
        if low and previous ~= true then
            row.values[key] = true
            self:QueueNotice(row, key, lowText)
        elseif recovered and previous == true then
            row.values[key] = false
            self:QueueNotice(row, key, recoveredText, "info")
        elseif previous == nil then
            row.values[key] = false
        end
    end
    function api:ReadStatus(row)
        local healthOk, health = call("ENTITY", "GET_ENTITY_HEALTH", row.ped)
        local maxOk, maximum = call("ENTITY", "GET_ENTITY_MAX_HEALTH", row.ped)
        if healthOk and maxOk and validNumber(health) and validNumber(maximum) and maximum > 0 then
            -- GTA human ped health includes the 100-point base; 120/200 is 20%
            -- playable health, not 60%. Nonstandard low maxima use raw values.
            local base = maximum > 100 and 100 or 0
            local ratio = math.max(0, math.min(1, (health - base) / (maximum - base)))
            self:Observe(row, "health", ratio <= 0.35, ratio >= 0.50, "Teammate health is low", "Teammate health recovered")
        end
        local armourOk, armour = call("PED", "GET_PED_ARMOUR", row.ped)
        local capacityOk, capacity = call("PLAYER", "GET_PLAYER_MAX_ARMOUR", row.pid)
        if armourOk and capacityOk and validNumber(armour) and validNumber(capacity) and capacity > 0 then
            local ratio = armour / capacity
            self:Observe(row, "armour", ratio <= 0.25, ratio >= 0.40, "Teammate armor is low", "Teammate armor recovered")
        end
        local vehicleOk, vehicle = call("PED", "GET_VEHICLE_PED_IS_IN", row.ped, false)
        if vehicleOk and vehicle == 0 then
            -- Leaving a damaged vehicle ends that vehicle's alert, but does not
            -- claim that the abandoned vehicle has been repaired.
            row.values.vehicle, row.pending.vehicle = false, nil
        elseif vehicleOk and menu.missionSupport:Exists(vehicle, 2) then
            local engineOk, engine = call("VEHICLE", "GET_VEHICLE_ENGINE_HEALTH", vehicle)
            local bodyOk, body = call("VEHICLE", "GET_VEHICLE_BODY_HEALTH", vehicle)
            if engineOk and bodyOk and validNumber(engine) and validNumber(body) then
                self:Observe(row, "vehicle", engine <= 300 or body <= 300, engine >= 500 and body >= 500,
                    "Teammate vehicle is severely damaged", "Teammate current vehicle condition recovered")
            end
        end
    end
    function api:PollRow(row, now)
        if not self:Active() then self:Cleanup(); return end
        local position, reason, terminal = self:Resolve(row)
        if terminal then
            self:Stop(row.kind)
            if self.lastTerminalRid ~= row.rid or now - (self.lastTerminalAt or -5000) >= 5000 then
                self:Notify(row, reason, "warning")
                self.lastTerminalRid, self.lastTerminalAt = row.rid, now
            end
            return
        end
        if not position then
            if not row.lost then
                row.lost = true
                row.pending = {}
                self:QueueNotice(row, "signal", reason)
            end
        else
            if row.lost then
                row.lost = false
                self:QueueNotice(row, "signal", "Teammate status recovered", "info")
            end
            if row.kind == "navigation" then
                local prior = row.lastWaypoint
                local dx, dy = prior and position.x - prior.x or 100, prior and position.y - prior.y or 100
                if not prior or dx * dx + dy * dy >= 100 then
                    local ok = call("HUD", "SET_NEW_WAYPOINT", position.x, position.y)
                    if ok then row.lastWaypoint = {x = position.x, y = position.y} end
                end
            else
                self:ReadStatus(row)
            end
        end
        self:FlushNotice(row, now)
    end
    function api:Poll(now)
        if not self:Active() then self:Cleanup(); return end
        local deadline = os.clock() + 0.0005
        self.nextPoll = now + 1000
        for _ = 1, 2 do
            if os.clock() >= deadline then self.nextPoll = now + 50; return end
            local key = self.keys[self.cursor]
            self.cursor = self.cursor % 2 + 1
            local row = self[key]
            if row and now >= row.nextAt then
                row.nextAt = now + 1000
                self:PollRow(row, now)
            end
        end
    end
    api.Process = LPH_NO_VIRTUALIZE(function(self)
        if not self.navigation and not self.status then return end
        local raw = menu.nativeApis.MISC.GET_GAME_TIMER() % 4294967296
        if self.lastRaw ~= nil then
            local delta = (raw - self.lastRaw) % 4294967296
            if delta <= 60000 then self.clock = self.clock + delta end
        end
        self.lastRaw = raw
        if self.clock < self.nextPoll then return end
        return self:Poll(self.clock)
    end)
    function api:Bind(group)
        menu.ptoggle("Keep waypoint on teammate", "Check the locked teammate every second and update your waypoint after 10 meters of movement; changing menu selection keeps the locked target.",
            group, stateKeys.navigation, false, 0, function(pid, enabled, state) self:Set("navigation", pid, enabled, state) end)
