        type = eFeatureType.Toggle,
        desc = "",
        cb = function(f)
            local pid = f:GetPlayerIndex()
            local desired = f:IsToggled()
            local getter = FeatureMgr and FeatureMgr.GetFeatureByName
            local feature = nil
            if type(getter) == "function" then
                local ok, result = pcall(getter, "Spectate Player", pid)
                if ok then feature = result end
            end
            if not feature then
                SovereignNotify("SovereignLua", "Cherax spectate feature not found", "warning")
                return
            end
            local current = nil
            for _, method in ipairs({"IsToggled", "GetBoolValue"}) do
                if type(feature[method]) == "function" then
                    local ok, value = pcall(function() return feature[method](feature) end)
                    if ok then current = value == true break end
                end
            end
            if current == desired then return end
            if type(feature.Toggle) == "function" then
                pcall(function() feature:Toggle(desired) end)
            elseif type(feature.SetValue) == "function" then
                pcall(function() feature:SetValue(desired):OnClick() end)
            elseif type(feature.SetBoolValue) == "function" then
                pcall(function() feature:SetBoolValue(desired):TriggerCallback() end)
            end
        end
