local RIDTracker = {
    queue = {},
    map = {},
    maxHistory = CONFIG.LIMITS.MaxHistory,
    isLoaded = false
}
function RIDTracker:SaveDB()
    local success, result = pcall(function()
        local data = {}
        for i = 1, #self.queue do
            data[i] = tostring(self.queue[i])
        end
        return FileManager:WriteFile(CONFIG.PATHS.DatabaseFile, table.concat(data, "\\n"))
    end)
    if not success then
        Logger:Error("SovereignLua", "SaveDB failed: " .. tostring(result))
    end
end
function RIDTracker:Insert(rid)
    if rid == 0 or self.map[rid] then
        return
    end
    local success, myRid = PlayerManager:GetRockstarId(menu.nativeApis.PLAYER.PLAYER_ID())
    if success and rid == myRid then
        return
    end
    table.insert(self.queue, rid)
    self.map[rid] = true
    if #self.queue > self.maxHistory then
        for i = 1, self.maxHistory // 2 do
            self.map[self.queue[i]] = nil
        end
        local newQueue = {}
        for i = self.maxHistory // 2 + 1, #self.queue do
            table.insert(newQueue, self.queue[i])
        end
        self.queue = newQueue
        self:SaveDB()
    else
        self:SaveDB()
    end
end

function RIDTracker:LoadDB()
    if self.isLoaded then
        return
    end
    local success, myRid = PlayerManager:GetRockstarId(menu.nativeApis.PLAYER.PLAYER_ID())
    if not success then
        return
    end
    local fileSuccess, content = pcall(function()
        if FileMgr.DoesFileExist(CONFIG.PATHS.DatabaseFile) then
            return FileMgr.ReadFileContent(CONFIG.PATHS.DatabaseFile)
        end
        return nil
    end)
    if not fileSuccess or not content then
        self.isLoaded = true
        return
    end
    for line in content:gmatch("%d+") do
        local rid = tonumber(line)
        if rid and rid ~= 0 and rid ~= myRid and not self.map[rid] then
            table.insert(self.queue, rid)
            self.map[rid] = true
            if #self.queue > self.maxHistory then
                local old = table.remove(self.queue, 1)
                self.map[old] = nil
            end
        end
    end
    self.isLoaded = true
end

function RIDTracker:CheckReunion(pid)
    local success, rid = PlayerManager:GetRockstarId(pid)
    if not success then
        return false, ""
    end
    if self.map[rid] then
        return true, Players.GetName(pid) or "Unknown"
    else
        self:Insert(rid)
        return false, ""
    end
end

EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_JOIN, function(pid)
    ProtectionSystem:ResetAdInvitePlayer(pid)
