-- R42 opt-in timing capture: fixed buckets, no file I/O during sampling.
menu.runtimeProbe = {active = false, rows = {}, order = {
    "Logic frame", "Render frame", "Frame interval", "Entity pools", "Function integrity check", "Metatable check", "Canary behavior check",
    "Global environment scan", "VM integrity check", "Headlamp", "Aim tracking", "Player action selection", "Strip club",
    "Self", "Vehicles", "World", "Teammate tracking", "Tornado", "Session support", "Support cleanup", "Fun", "Extensions", "Game settings",
    "Looped features", "Dynamic lists", "Session overview", "Session Network Status", "Status Center", "Business inventory", "Feature checks", "Feature status", "Runtime diagnostics", "Configuration save", "Extended controls"
}}
function menu.startRuntimeProbe()
    local probe = menu.runtimeProbe
    if probe.active then return false end
    probe.rows = {}
    for _, name in ipairs(probe.order) do
        local buckets = {}
        for i = 1, 129 do buckets[i] = 0 end
        probe.rows[name] = {count = 0, total = 0, peak = 0, over8 = 0, over16 = 0, buckets = buckets}
    end
    probe.started, probe.lastPresent, probe.clockResets = os.clock(), nil, 0
    probe.wallStarted = Utils1:NowSeconds()
    probe.deadline, probe.active, probe.finished = probe.wallStarted + 30, true, nil
    return true
end
menu.recordRuntimeTiming = LPH_NO_VIRTUALIZE(function(name, started, finished)
    local probe = menu.runtimeProbe
    if not probe.active or started == nil then return end
    local row = probe.rows[name]
    if not row then return end
    local now = finished or os.clock()
    if now < started then probe.clockResets = probe.clockResets + 1; return end
    local ms = (now - started) * 1000
    row.count, row.total, row.peak = row.count + 1, row.total + ms, math.max(row.peak, ms)
    if ms > 8 then row.over8 = row.over8 + 1 end
    if ms > 16.667 then row.over16 = row.over16 + 1 end
    local bucket = math.min(129, math.floor(ms * 4) + 1)
    row.buckets[bucket] = row.buckets[bucket] + 1
end)
menu.finishRuntimeProbeFrame = LPH_NO_VIRTUALIZE(function(started)
    local probe = menu.runtimeProbe
    if not probe.active or started == nil then return end
    local now = os.clock()
    menu.recordRuntimeTiming("Render frame", started, now)
    if probe.lastPresent then menu.recordRuntimeTiming("Frame interval", probe.lastPresent, started) end
    probe.lastPresent = started
    local wallNow = Utils1:NowSeconds()
    if wallNow >= probe.deadline or wallNow < probe.wallStarted then
        probe.active, probe.finished, probe.wallFinished = false, now, wallNow
        if wallNow < probe.wallStarted then probe.clockResets = probe.clockResets + 1 end
    end
end)
function menu.exportRuntimeProbe()
    local probe = menu.runtimeProbe
    if probe.active or not probe.finished then return false end
    local english = menu.ui.language ~= 2
    local lines = {english and "Sovereign performance report" or "Sovereign performance report",
        (english and "Duration: " or "Duration: ")
            .. string.format("%.1f s", math.max(0, probe.wallFinished - probe.wallStarted))}
    local displayNames = {
        ["Logic frame"] = {"Menu response", "Menu response"}, ["Render frame"] = {"Menu drawing", "Menu drawing"},
        ["Frame interval"] = {"Frame interval", "Frame interval"}, ["Entity pools"] = {"Scene objects", "Scene objects"},
        ["Function integrity check"] = {"Security check 1", "Security check 1"}, ["Metatable check"] = {"Security check 2", "Security check 2"},
        ["Canary behavior check"] = {"Security check 3", "Security check 3"}, ["Global environment scan"] = {"Security check 4", "Security check 4"},
        ["VM integrity check"] = {"Security check 5", "Security check 5"}, ["Runtime diagnostics"] = {"Status checks", "Status checks"},
    }
    for _, name in ipairs(probe.order) do
        local row, cumulative, p95 = probe.rows[name], 0, 0
        if row.count > 0 then
            for i, count in ipairs(row.buckets) do
                cumulative = cumulative + count
                if cumulative >= math.ceil(row.count * 0.95) then p95 = i * 0.25; break end
            end
            local percentile = p95 > 32 and ">32 ms" or string.format("%.2f ms", p95)
            local labels = displayNames[name]
            local label = labels and labels[english and 2 or 1] or menu.translate(name)
            local format = english
                and "%s | Average: %.3f ms | Peak: %.3f ms | 95%%: %s"
                or "%s | Average: %.3f ms | Peak: %.3f ms | 95%%: %s"
            lines[#lines + 1] = string.format(format,
                label, row.total / row.count, row.peak, percentile)
        end
    end
    if not FileMgr or type(FileMgr.GetMenuRootPath) ~= "function"
        or type(FileMgr.WriteFileContent) ~= "function" or type(FileMgr.ReadFileContent) ~= "function" then return false end
    local ok, result = pcall(function()
        local path = FileMgr.GetMenuRootPath() .. "//Sovereign-runtime-timing.txt"
        local body = table.concat(lines, "\n") .. "\n"
        return FileMgr.WriteFileContent(path, body) == true and FileMgr.ReadFileContent(path) == body
    end)
    return ok and result == true
end
-- R42 opt-in timing capture end.

SovereignRuntime.GetModuleState = LPH_NO_VIRTUALIZE(function(self, name)
    local state = self.moduleStates[name]
    if not state then
        state = {
            enabled = true,
            failures = 0,
            consecutiveFailures = 0,
            cooldownUntil = 0,
            lastErrorAt = 0,
            lastMs = 0,
            averageMs = 0,
            peakMs = 0,
            calls = 0
        }
        self.moduleStates[name] = state
    end
    return state
end)

SovereignRuntime.RunModule = LPH_NO_VIRTUALIZE(function(self, name, callback, ...)
    if type(callback) ~= "function" then return false end
    local state = self:GetModuleState(name)
    if state.enabled == false then return false end
    local now
    local profiling = menu.runtimeProbe and menu.runtimeProbe.active
    if self.performanceVisible or profiling or (state.cooldownUntil or 0) > 0 then
        now = os.clock()
        if now < (state.cooldownUntil or 0) then return false end
    end
    local started = (self.performanceVisible or profiling) and now or nil
    local ok, result = pcall(callback, ...)
    if profiling then menu.recordRuntimeTiming(name, started) end
    if started then
        local elapsed = math.max(0, (os.clock() - started) * 1000.0)
        state.lastMs = elapsed
        state.calls = (state.calls or 0) + 1
        state.averageMs = state.calls == 1 and elapsed or ((state.averageMs or 0) * 0.90) + (elapsed * 0.10)
        state.peakMs = math.max(tonumber(state.peakMs) or 0, elapsed)
    end
    if ok then
        if (state.consecutiveFailures or 0) >= (self.moduleFailureLimit or 3) then
            SovereignNotify("SovereignLua", tostring(name) .. "Automatically restored", "success")
        end
        state.consecutiveFailures = 0
        state.cooldownUntil = 0
        return true, result
    end
    now = now or os.clock()
    state.failures = (state.failures or 0) + 1
    state.consecutiveFailures = (state.consecutiveFailures or 0) + 1
    if now - (state.lastErrorAt or 0) >= 5.0 then
        state.lastErrorAt = now
        SovereignLogError("SovereignRuntime." .. tostring(name), result)
    end
    if state.consecutiveFailures >= (self.moduleFailureLimit or 3) then
        state.cooldownUntil = now + (self.moduleCooldown or 15.0)
        SovereignNotify("SovereignLua", tostring(name) .. "Temporarily paused; will resume automatically", "warning")
    end
    return false, result
end)

function SovereignRuntime:ResetModuleStates()
    for _, state in pairs(self.moduleStates) do
        state.enabled = true
        state.failures = 0
        state.consecutiveFailures = 0
        state.cooldownUntil = 0
        state.lastErrorAt = 0
        state.lastMs = 0
        state.averageMs = 0
        state.peakMs = 0
        state.calls = 0
    end
end

function SovereignRuntime:ApplyPerformanceProfile(index)
    index = math.floor(math.max(1, math.min(3, tonumber(index) or 2)))
    menu.ui.performanceProfile = index
    self.sessionCheckInterval = 3.0
    self.permissionCheckInterval = 1.0
    self.playerLinkProbeInterval = 1.0
    if index == 1 then
        self.dynamicListInterval = 2.0
        TravellerMigration.refreshInterval = 2.0
        SovereignStatusCenter.refreshInterval = 2.0
        SovereignBusinessInventory.refreshInterval = 0.67
    elseif index == 3 then
        self.dynamicListInterval = 0.5
        TravellerMigration.refreshInterval = 0.5
        SovereignStatusCenter.refreshInterval = 0.5
        SovereignBusinessInventory.refreshInterval = 0.17
    else
        self.dynamicListInterval = 1.0
        TravellerMigration.refreshInterval = 1.0
        SovereignStatusCenter.refreshInterval = 1.0
        SovereignBusinessInventory.refreshInterval = 0.34
    end
end

function SovereignRuntime:RenderPerformanceOverlay()
    if not self.performanceVisible then return end
    local begun, x, y, panelWidth = SovereignOverlayBegin("SovereignPerformance", self.performanceWindow, "Performance Monitor", 520, 430)
    if not begun then return end
    local ok, err = xpcall(function()
        local theme = SovereignOverlayTheme
        local now = os.clock()
        local rowY = y + 54
        for index, name in ipairs(self.moduleOrder) do
            local state = self:GetModuleState(name)
            local remaining = math.max(0, (state.cooldownUntil or 0) - now)
            local status = remaining > 0 and string.format("Resume in %.0fs", remaining) or "Healthy"
            local statusColor = remaining > 0 and theme.cargo or theme.product
            if index % 2 == 1 then
                ImGui.AddRectFilled(x + 12, rowY - 3, x + panelWidth - 12, rowY + 25,
                    theme.row[1], theme.row[2], theme.row[3], theme.row[4], 4.0)
            end
            SovereignOverlayText(x + 20, rowY + 2, name, theme.text)
            SovereignOverlayText(x + 166, rowY + 2, string.format("%.2f ms", state.averageMs or 0), theme.accent)
            SovereignOverlayText(x + 286, rowY + 2, string.format("Peak %.2f", state.peakMs or 0), theme.secondary)
            SovereignOverlayText(x + panelWidth - 88, rowY + 2, status, statusColor)
            rowY = rowY + 31
        end
    end, debug.traceback)
    ImGui.SetWindowFontScale(1.0)
    ImGui.End()
    if not ok then SovereignLogError("SovereignPerformance.Render", err) end
end

local function SovereignEnum(enumTable, key)
    if not enumTable then return nil end
    local ok, value = pcall(function() return enumTable[key] end)
    if ok then return value end
    return nil
end

local SovereignFeatureType = {
    Button = SovereignEnum(eFeatureType, "Button"),
    Toggle = SovereignEnum(eFeatureType, "Toggle"),
