local function SovereignTypeIs(config, typeValue)
    return config and typeValue ~= nil and config.type == typeValue
end

local function SovereignConfigKey(config)
    if not config then return "unknown" end
    if config.hash then return tostring(config.hash) end
    if config.name then return tostring(config.name) end
    return tostring(config)
end

function menu.featurePersistKey(config)
    local raw = SovereignConfigKey(config)
    -- Hashes are stable across menu rebuilds; sanitize the signed decimal form
    -- so it remains a valid config key on every Lua runtime.
    raw = tostring(raw):gsub("[^%w]", "_")
    return "shim_" .. raw
end

SovereignNotify = function(title, message, status)
    if menu and menu.notify then
        local body = tostring(message or "")
        local resolved = menu.normalizeNotificationStatus(status)
            or menu.inferNotificationStatus(body)
        menu.notify(title or "SovereignLua", body, 3.0, resolved)
        return
    end
    if Logger and Logger.Toast then
        Logger:Toast(title or "SovereignLua", tostring(message or ""), CONFIG.UI.ToastDuration.Medium)
    end
end

-- R20 pool pressure monitor: count-only sampling; optional cleanup is separate.
SovereignPoolMonitor = {
    enabled = false,
    cleanupEnabled = false,
    sampleInterval = 1.0,
    nextSample = 0,
    lastTime = nil,
    revision = "pool-r41",
    pools = {
        {name = "Ped pool", kind = "Ped"},
        {name = "Vehicle pool", kind = "Vehicle"},
        {name = "Object pool", kind = "Object"},
        {name = "Pickup pool", kind = "Pickup"},
        {name = "Camera pool", kind = "Camera"},
    },
}

SovereignPoolMonitor.Reset = LPH_JIT(function(self)
    self.nextSample, self.lastTime = 0, nil
    if self.ResetCleanup then self:ResetCleanup() end
    self:PublishAlert(nil)
    self.nextHealthNotice, self.lastCheck, self.lastScheduledSample = 0, nil, nil
    self.scheduledSamples, self.availablePools, self.confirmationPending = 0, 0, self.enabled
    for _, pool in ipairs(self.pools) do
        pool.level = 0
        pool.available, pool.count, pool.capacity, pool.reason = false, nil, nil, "not_sampled"
        pool.minimum, pool.peak, pool.validSamples = nil, nil, 0
    end
end)

SovereignPoolMonitor.SetEnabled = LPH_JIT(function(self, enabled)
    enabled = enabled == true
    if self.enabled == enabled then return end
    self.enabled = enabled
    self:Reset()
end)

SovereignPoolMonitor.IsFiniteCount = LPH_NO_VIRTUALIZE(function(value)
    return type(value) == "number" and value == value and value >= 0
        and value < rawget(math, "huge") and value % 1 == 0
end)

SovereignPoolMonitor.Now = LPH_NO_VIRTUALIZE(function(self, now)
    if now == nil then
        if Utils1 and type(Utils1.NowSeconds) == "function" then
            local ok, value = pcall(Utils1.NowSeconds, Utils1)
            if ok then now = value end
        else
            now = os.clock()
        end
    end
    if type(now) ~= "number" or now ~= now or now < 0 or now == rawget(math, "huge") then return nil end
    return now
end)

SovereignPoolMonitor.WarningPercent = LPH_NO_VIRTUALIZE(function(self)
    local value = menu and menu.ui and tonumber(menu.ui.poolWarningPercent) or 90
    if not value or value ~= value or value == rawget(math, "huge") or value == -rawget(math, "huge") then value = 90 end
    return math.floor(math.max(10, math.min(95, value)) + 0.5)
end)

SovereignPoolMonitor.Sample = LPH_NO_VIRTUALIZE(function(self, pool, warningRatio)
    pool.available, pool.count, pool.capacity = false, nil, nil
    local apiOk, current, maximum = pcall(function()
        return PoolMgr and PoolMgr["GetCurrent" .. pool.kind .. "Count"],
            PoolMgr and PoolMgr["GetMax" .. pool.kind .. "Count"]
    end)
    if not apiOk or type(current) ~= "function" or type(maximum) ~= "function" then
        pool.level = 0
        pool.reason = "api_unavailable"
        return
    end
    local currentOk, count = pcall(current)
    local maximumOk, capacity = pcall(maximum)
    if not currentOk or not maximumOk or not self.IsFiniteCount(count)
        or not self.IsFiniteCount(capacity) or capacity <= 0 then
        pool.level = 0
        pool.reason = (not currentOk or not maximumOk) and "read_failed" or "invalid_count"
        return
    end
    pool.available, pool.count, pool.capacity, pool.reason = true, count, capacity, "ok"
    pool.minimum = math.min(pool.minimum or count, count)
    pool.peak = math.max(pool.peak or count, count)
    pool.validSamples = (pool.validSamples or 0) + 1
    local ratio = count / capacity
    warningRatio = warningRatio or self:WarningPercent() / 100
    if ratio < warningRatio then
        pool.level = 0
    elseif ratio >= 0.98 then
        pool.level = 2
    else
        pool.level = 1
    end
end)

SovereignPoolMonitor.SampleAll = LPH_NO_VIRTUALIZE(function(self)
    local threshold = self:WarningPercent()
    self.availablePools = 0
    for _, pool in ipairs(self.pools) do
        self:Sample(pool, threshold / 100)
        if pool.available then self.availablePools = self.availablePools + 1 end
    end
end)

SovereignPoolMonitor.Notify = LPH_JIT(function(self, message, status)
    if type(SovereignNotify) ~= "function" then return false end
    local ok, result = pcall(SovereignNotify, "Sovereign", message, status or "warning")
    return ok and result ~= false
end)

SovereignPoolMonitor.AlertRank = LPH_NO_VIRTUALIZE(function(self, pool)
    if not pool.available or pool.level == 0 then return 0 end
    if pool.level == 2 then return 3 end
    return pool.count / pool.capacity >= 0.90 and 2 or 1
end)

SovereignPoolMonitor.WarningMessage = LPH_NO_VIRTUALIZE(function(self, pool)
    return pool.name .. (pool.count / pool.capacity >= 0.90 and ": Nearly full" or ": Usage warning")
end)

SovereignPoolMonitor.PublishAlert = LPH_NO_VIRTUALIZE(function(self, label)
    if not menu or type(menu.setPoolPressureNotice) ~= "function" then return false end
    local ok, delivered = pcall(menu.setPoolPressureNotice, label)
    return ok and delivered ~= false
end)

SovereignPoolMonitor.Warn = LPH_NO_VIRTUALIZE(function(self)
    -- All affected pools share one renewable notice, highest pressure first.
    local lines = {}
    for rank = 3, 1, -1 do
        for _, pool in ipairs(self.pools) do
            if self:AlertRank(pool) == rank then lines[#lines + 1] = self:WarningMessage(pool) end
        end
    end
    local label = #lines > 0 and table.concat(lines, "\n") or nil
    local delivered = self:PublishAlert(label)
    return label ~= nil and delivered
end)

SovereignPoolMonitor.ReportHealth = LPH_NO_VIRTUALIZE(function(self, now)
    if now < (self.nextHealthNotice or 0) then return end
    if self.availablePools < #self.pools then
        local message = self.availablePools == 0 and "Entity pool monitoring is unavailable" or "Some entity pools cannot be monitored"
        self.nextHealthNotice = now + 60.0
        self:Notify(message, "warning")
    elseif self.confirmationPending then
        for _, pool in ipairs(self.pools) do if pool.level > 0 then return end end
        self.nextHealthNotice = now + 5.0
        if self:Notify("Entity pool monitoring enabled", "info") then self.confirmationPending = false end
    end
end)

SovereignPoolMonitor.Tick = LPH_NO_VIRTUALIZE(function(self, now, allowCleanup)
    if not self.enabled then return end
    now = self:Now(now)
    if not now then return end
    if self.lastTime and now < self.lastTime then self:Reset() end
    self.lastTime = now
    if now < self.nextSample then
        if allowCleanup ~= false and self.cleanupEnabled and self.CleanupTick then self:CleanupTick(now) end
        return
    end
    self.nextSample = now + self.sampleInterval
    self:SampleAll()
    self.lastScheduledSample = now
    self.scheduledSamples = (self.scheduledSamples or 0) + 1
    if self:Warn(now) then
        if self.availablePools == #self.pools then self.confirmationPending = false end
    else
        self:ReportHealth(now)
    end
    if allowCleanup ~= false and self.cleanupEnabled and self.CleanupTick then self:CleanupTick(now) end
end)

SovereignPoolMonitor.DiagnosticText = LPH_JIT(function(self, now)
    local age = self.lastScheduledSample and math.max(0, now - self.lastScheduledSample) or -1
    local lines = {
        "revision=" .. self.revision,
        "enabled=" .. tostring(self.enabled),
        "cleanup_enabled=" .. tostring(self.cleanupEnabled == true),
        "scheduled_samples=" .. tostring(self.scheduledSamples or 0),
        "scheduled_sample_age_seconds=" .. string.format("%.3f", age),
        "available_pools=" .. tostring(self.availablePools or 0),
        "warning_percent=" .. tostring(self:WarningPercent()),
        "critical_percent=98",
    }
    for _, pool in ipairs(self.pools) do
        lines[#lines + 1] = string.format("%s status=%s count=%s capacity=%s level=%s",
            pool.kind, pool.reason or "not_sampled", tostring(pool.count), tostring(pool.capacity), tostring(pool.level))
        lines[#lines + 1] = string.format("%s minimum=%s peak=%s valid_samples=%s",
            pool.kind, tostring(pool.minimum), tostring(pool.peak), tostring(pool.validSamples or 0))
        lines[#lines + 1] = string.format("%s cleanup_scanned=%s attempts=%s removed=%s pending=%s failed=%s last=%s cursor=%s",
            pool.kind, tostring(pool.cleanupScanned or 0), tostring(pool.cleanupAttempts or 0),
            tostring(pool.cleanupRemoved or 0), tostring(pool.cleanupPending or 0), tostring(pool.cleanupFailed or 0),
            tostring(pool.cleanupLast or "idle"), tostring(pool.cleanupCursor or 0))
    end
    return table.concat(lines, "\n") .. "\n"
end)

SovereignPoolMonitor.CheckNow = LPH_JIT(function(self)
    local now = self:Now()
    if not now then return self:Notify("Entity pool monitoring is unavailable", "warning") end
    if self.lastCheck and now >= self.lastCheck and now - self.lastCheck < 2.0 then return false end
    self.lastCheck = now
    self:SampleAll()
    -- Explicit check only: no file access in the automatic sampling path.
    local report = self:DiagnosticText(now)
    self.diagnosticSaved = false
    if FileMgr and FileMgr.GetMenuRootPath and FileMgr.WriteFileContent and FileMgr.ReadFileContent then
        local ok, saved = pcall(function()
            local path = FileMgr.GetMenuRootPath() .. "//Sovereign-pool-check.txt"
            return FileMgr.WriteFileContent(path, report) == true and FileMgr.ReadFileContent(path) == report
        end)
        self.diagnosticSaved = ok and saved == true
    end
    if not self.enabled then return self:Notify("Entity pool monitoring disabled", "info") end
    local pressure = self:Warn()
    if pressure then return true end
    if self.availablePools < #self.pools then
        return self:Notify(self.availablePools == 0 and "Entity pool monitoring is unavailable" or "Some entity pools cannot be monitored", "warning")
    end
    if not self.lastScheduledSample or now < self.lastScheduledSample
        or now - self.lastScheduledSample > self.sampleInterval * 3 then
        return self:Notify("Automatic entity pool monitoring has not run yet", "warning")
    end
    return self:Notify("Entity pool usage is below the warning threshold", "info")
end)
-- R20 pool pressure monitor end.

-- R38 optional pool cleanup: bounded slices, only after an occupancy warning.
SovereignPoolMonitor.ResetCleanup = LPH_JIT(function(self)
    self.nextCleanup, self.cleanupPoolCursor = 0, 0
    for _, pool in ipairs(self.pools) do
        pool.cleanupCursor, pool.cleanupResumeAt = 0, 0
        pool.cleanupScanned, pool.cleanupAttempts, pool.cleanupRemoved = 0, 0, 0
        pool.cleanupPending, pool.cleanupFailed, pool.cleanupLast = 0, 0, "idle"
        pool.cleanupOutstanding, pool.cleanupObservedCount, pool.cleanupPendingUntil = 0, nil, 0
    end
end)

SovereignPoolMonitor.SetCleanupEnabled = LPH_JIT(function(self, enabled)
    self.cleanupEnabled = enabled == true
    self:ResetCleanup()
end)

SovereignPoolMonitor.CleanupTick = LPH_NO_VIRTUALIZE(function(self, now)
    if not self.enabled or not self.cleanupEnabled then return end
    if now < (self.nextCleanup or 0) then return end
    -- One slice per eligible frame, never catch up after a long frame.
    self.nextCleanup = now + 0.05
    local backend = SovereignPoolCleanupBackend
    if not backend or type(backend.TryDelete) ~= "function" then return end
    local pool
    for _ = 1, #self.pools do
        self.cleanupPoolCursor = ((self.cleanupPoolCursor or 0) % #self.pools) + 1
        local candidate = self.pools[self.cleanupPoolCursor]
        if candidate.available and candidate.level > 0 and backend.getters[candidate.kind]
            and now >= (candidate.cleanupResumeAt or 0) then pool = candidate; break end
    end
    if not pool then return end
    local start = os.clock()
    -- Re-read before touching entities; never use a stale warning as authority.
    self:Sample(pool)
    if not pool.available or pool.level == 0 then self:Warn(); return end
    if pool.capacity > 100000 then return end
    -- Keep outstanding async requests out of the next deletion allowance.
    -- These credits never alter the host count or dismiss its warning.
    if now >= (pool.cleanupPendingUntil or 0) then pool.cleanupOutstanding = 0 end
    if pool.cleanupObservedCount then
        local recovered = math.max(0, pool.cleanupObservedCount - pool.count)
        pool.cleanupOutstanding = math.max(0, (pool.cleanupOutstanding or 0) - recovered)
    end
    pool.cleanupObservedCount = pool.count
    local outstanding = pool.cleanupOutstanding or 0
    local target = math.ceil(pool.capacity * self:WarningPercent() / 100) - 1
    local allowance = math.max(0, pool.count - target - outstanding)
    if allowance == 0 then return end
    local critical = pool.count / pool.capacity >= 0.98
    local maxAttempts = math.min(critical and 8 or 4, allowance)
    local slots = math.min(critical and 96 or 64, pool.capacity)
    local attempts, scanned, pending = 0, 0, 0
    while scanned < slots and attempts < maxAttempts do
        if not self.enabled or not self.cleanupEnabled then return end
        if os.clock() - start >= 0.00075 then break end
        local slot = (pool.cleanupCursor or 0) % pool.capacity
        pool.cleanupCursor = (slot + 1) % pool.capacity
        scanned = scanned + 1
        local ok, deleted, reason, outcome = pcall(backend.TryDelete, pool.kind, slot)
        if not self.enabled or not self.cleanupEnabled then return end
        pool.cleanupScanned = (pool.cleanupScanned or 0) + 1
        pool.cleanupLast = ok and (outcome or reason) or "read_failed"
        if not ok or reason == "unavailable" or reason == "read_failed" then
            pool.cleanupFailed = (pool.cleanupFailed or 0) + 1
            pool.cleanupResumeAt = now + 1.0
            break
        end
        if reason == "attempted" then
            attempts = attempts + 1
            pool.cleanupAttempts = (pool.cleanupAttempts or 0) + 1
            if deleted then
                pool.cleanupRemoved = (pool.cleanupRemoved or 0) + 1
            elseif outcome == "pending" then
                pool.cleanupPending = (pool.cleanupPending or 0) + 1
                pending = pending + 1
            else
                pool.cleanupFailed = (pool.cleanupFailed or 0) + 1
            end
            -- No synthetic decrements or success toast: the host counter owns
            -- recovery, including delayed/failed unregister operations.
            self:Sample(pool)
            if not pool.available or pool.level == 0 then break end
            if not deleted and outcome ~= "pending" then pool.cleanupResumeAt = now + 1.0; break end
            -- Stop at the real recovery target, including asynchronous work.
            if pool.count - target <= outstanding + pending then break end
        end
    end
    pool.cleanupObservedCount = pool.count
    pool.cleanupOutstanding = outstanding + pending
    if pending > 0 then
        pool.cleanupPendingUntil = now + 0.5
        pool.cleanupResumeAt = math.max(pool.cleanupResumeAt or 0, now + 0.10)
    end
    if not pool.available or pool.level == 0 then
        pool.cleanupOutstanding, pool.cleanupPendingUntil = 0, 0
    end
    if scanned == pool.capacity then pool.cleanupResumeAt = math.max(pool.cleanupResumeAt or 0, now + 0.5) end
    self:Warn()
end)
-- R38 optional pool cleanup end.

local function SovereignNormalizeNotifyDuration(duration)
    local value = tonumber(duration)
    if not value then
        return 3.0
    end
    if value > 100 then
        return value / 1000.0
    end
    return value
end

local function SovereignInstallToastBridge()
    -- Logger routes directly to the script UI from its definition onward.
    -- No host-toast fallback or startup-time replacement is needed.
    if not Logger or Logger._sovereignToastBridgeInstalled then return end
    Logger._sovereignToastBridgeInstalled=true
    if AntiHookManager and type(AntiHookManager._refresh_local_ref)=="function" then
        AntiHookManager:_refresh_local_ref("Logger:Toast")
    end
end

do
    local errorLogScopes, errorLogSlots = {}, {}
    local errorLogScopeCount, errorLogClock, errorLogRawClock, errorLogClockOffset = 0, 0, nil, 0
    for index = 1, 64 do errorLogSlots[index] = { lastAt = nil, suppressed = 0 } end

    local errorLogText = LPH_NO_VIRTUALIZE(function(value, limit)
        if type(value) ~= "string" then
            local ok, text = pcall(tostring, value)
            value = ok and type(text) == "string" and text or "<unprintable error>"
        end
        if #value > limit then return value:sub(1, limit - 3) .. "..." end
        return value
    end)

    SovereignLogError = LPH_NO_VIRTUALIZE(function(scope, err)
        local now = os.clock()
        if type(now) ~= "number" or now ~= now or now <= -rawget(math, "huge") or now >= rawget(math, "huge") then
            now = errorLogRawClock or 0
        end
        if errorLogRawClock ~= nil and now < errorLogRawClock then
            errorLogClockOffset = errorLogClock - now
        end
        errorLogClock = now + errorLogClockOffset
        errorLogRawClock = now

        local scopeKey = type(scope) == "string" and #scope <= 96 and scope or nil
        if scope == nil or scope == false then scopeKey = "SovereignRuntime" end
        local slotIndex = scopeKey and errorLogScopes[scopeKey] or nil
        if not slotIndex then
            -- Reserve one shared slot so changing or oversized scopes cannot grow the cache.
            if scopeKey and errorLogScopeCount < 63 then
                errorLogScopeCount = errorLogScopeCount + 1
                slotIndex = errorLogScopeCount
                errorLogScopes[scopeKey] = slotIndex
            else
                slotIndex = 64
            end
        end
        local slot = errorLogSlots[slotIndex]
        if slot.lastAt ~= nil and errorLogClock - slot.lastAt < 5 then
            slot.suppressed = math.min(2147483647, slot.suppressed + 1)
            return false
        end
        slot.lastAt = errorLogClock
        local message = errorLogText(err, 2048)
        if slot.suppressed > 0 then
            message = message .. " [suppressed=" .. tostring(slot.suppressed) .. " in cooldown]"
            slot.suppressed = 0
        end
        local title = errorLogText(scope or "SovereignRuntime", 96)
        if Logger and type(Logger.Error) == "function" then
            local ok = pcall(Logger.Error, Logger, title, message)
            if ok then return true end
        end
        menu.console.emit(0, title, message)
        return true
    end)
end

local function SovereignCheckAuth()
    if not AuthManager then
        SovereignNotify("SovereignLua", "Please login in Protection / Auth first", "warning")
        return false
    end
    if type(AuthManager.EnforceSession) ~= "function" or not AuthManager:EnforceSession("SovereignFeature") then
        return false
    end
    return true
end

local function SovereignRefreshUtilsBridgeBaseline()
    if not AntiHookManager or type(AntiHookManager._store) ~= "function" or not Utils then
        return
    end
    if type(Utils.GetSelectedPlayer) == "function" then
        AntiHookManager:_store("Utils.GetSelectedPlayer", Utils.GetSelectedPlayer)
    end
end

local function SovereignBridgeSelectedPlayer()
    if not Utils or SovereignRuntime.utilsSelectedPlayerBridged then
        return
    end
    SovereignRuntime.originalUtils.GetSelectedPlayer = Utils.GetSelectedPlayer
    Utils.GetSelectedPlayer = function(...)
        if SovereignRuntime.selectedPlayerOverride ~= nil then
            return SovereignRuntime.selectedPlayerOverride
        end
        if type(SovereignRuntime.originalUtils.GetSelectedPlayer) == "function" then
            return SovereignRuntime.originalUtils.GetSelectedPlayer(...)
        end
        return nil
    end
    SovereignRuntime.utilsSelectedPlayerBridged = true
    SovereignRefreshUtilsBridgeBaseline()
end

local function SovereignWithSelectedPlayer(pid, callback)
    local oldSelectedPlayerOverride = nil
    local shouldRestore = false
    if pid ~= nil then
        SovereignBridgeSelectedPlayer()
        oldSelectedPlayerOverride = SovereignRuntime.selectedPlayerOverride
        SovereignRuntime.selectedPlayerOverride = pid
        shouldRestore = true
    end
    local ok, result = xpcall(callback, debug.traceback)
    if shouldRestore then
        SovereignRuntime.selectedPlayerOverride = oldSelectedPlayerOverride
    end
    if not ok then
        return false, result
    end
    return true, result
end

local function SovereignRunJob(key, callback)
    if type(callback) ~= "function" then return false end
    if Script and Script.QueueJob then
        local ok, err = pcall(function()
            Script.QueueJob(function()
                local success, jobErr = pcall(callback)
                if not success then
                    SovereignLogError(key or "SovereignRuntime.Job", jobErr)
                end
            end)
        end)
        if not ok then
            SovereignLogError(key or "SovereignRuntime.QueueJob", err)
            return false
        end
        return true
    end
    local ok, err = pcall(callback)
    if not ok then
        SovereignLogError(key or "SovereignRuntime.DirectJob", err)
        return false
    end
    return true
end

local function SovereignNewNoopFeature(name)
    local noop = {
        _sovereignNoop = true,
        _name = tostring(name or "unknown"),
        _hash = 0,
        _toggled = false,
        _listIndex = 0,
        _value = 0,
        _stringValue = "",
        _color = {r = 255, g = 255, b = 255, a = 255}
    }
    function noop:IsToggled() return self._toggled == true end
    function noop:Toggle(value)
        self._toggled = value == nil and not self._toggled or value == true
        return false
    end
    function noop:OnClick() return false end
    function noop:TriggerCallback() return false end
    function noop:GetHash() return self._hash end
    function noop:GetName() return self._name end
    function noop:GetPlayerIndex() return nil end
    function noop:SetPlayerIndex(_) end
    function noop:GetListIndex() return self._listIndex end
    function noop:SetListIndex(value) self._listIndex = tonumber(value) or 0 end
    function noop:SetList(_) end
    function noop:SetDefaultValue(value) self._value = value end
    function noop:SetLimitValues(_, _) end
    function noop:SetNoCallbackOnPress(_) end
    function noop:GetIntValue() return math.floor((tonumber(self._value) or 0) + 0.5) end
    function noop:GetFloatValue() return tonumber(self._value) or 0.0 end
    function noop:GetStringValue() return tostring(self._stringValue or "") end
    function noop:SetStringValue(value) self._stringValue = tostring(value or "") end
    function noop:GetColor() return self._color.r, self._color.g, self._color.b, self._color.a end
    function noop:SetColor(r, g, b, a)
        self._color = {r = tonumber(r) or 255, g = tonumber(g) or 255, b = tonumber(b) or 255, a = tonumber(a) or 255}
    end
    return noop
end

local function SovereignGetNoopFeature(name)
    SovereignRuntime.noopFeatures = SovereignRuntime.noopFeatures or {}
    local key = tostring(name or "unknown")
    local noop = SovereignRuntime.noopFeatures[key]
    if not noop then
        noop = SovereignNewNoopFeature(key)
        SovereignRuntime.noopFeatures[key] = noop
    end
    return noop
end

local function SovereignRegisterShim(shim)
    if not shim or not shim.config then return end
    if shim.playerIndex ~= nil then return end
    local config = shim.config
    if config.hash then
        SovereignRuntime.shimsByHash[config.hash] = shim
    end
    if config.name then
        SovereignRuntime.shimsByName[tostring(config.name)] = shim
    end
end

local function SovereignRegisterConfigTemplate(config)
    if not config then return end
    if config.hash then
        SovereignRuntime.configsByHash[config.hash] = config
    end
    if config.name then
        SovereignRuntime.configsByName[tostring(config.name)] = config
    end
end

local function SovereignNormalizeComboList(list)
    if type(list) ~= "table" or #list == 0 then
        return {""}
    end
    local out = {}
    for i, value in ipairs(list) do
        out[i] = tostring(value)
    end
    return out
end

local function SovereignCreateShim(config, playerIndex)
    local defaultValue = config and config.defaultValue or nil
    local defaultColor = config and config.defaultColor or nil
    local shim = {
        config = config or {},
        playerIndex = playerIndex,
        toggled = defaultValue == true,
        listIndex = tonumber(defaultValue) or 0,
        value = defaultValue or 0,
        stringValue = type(defaultValue) == "string" and defaultValue or "",
        list = config and config.list or nil,
        color = {
            r = tonumber(defaultColor and (defaultColor.r or defaultColor[1])) or 255,
            g = tonumber(defaultColor and (defaultColor.g or defaultColor[2])) or 255,
            b = tonumber(defaultColor and (defaultColor.b or defaultColor[3])) or 255,
            a = tonumber(defaultColor and (defaultColor.a or defaultColor[4])) or 255
        }
    }

    shim.IsToggled = LPH_NO_VIRTUALIZE(function(self)
        return self.toggled == true
    end)

    function shim:SetToggledSilently(value)
        self.toggled = value == true
        if self.uiItem and self.uiItem.type == "toggle" then
            self.uiItem.value = self.toggled
        end
    end

    function shim:Toggle(value)
        if value == nil then
            self.toggled = not self.toggled
        else
            self.toggled = value == true
        end
        return SovereignInvokeShim(self, false)
    end

    function shim:OnClick()
        return SovereignInvokeShim(self, false)
    end

    function shim:TriggerCallback()
        return SovereignInvokeShim(self, false)
    end

    function shim:GetHash()
        return self.config.hash
    end

    function shim:GetName()
        return self.config.name
    end

    function shim:GetPlayerIndex()
        return self.playerIndex
    end

    function shim:SetPlayerIndex(pid)
        self.playerIndex = pid
    end

    function shim:GetListIndex()
        return tonumber(self.listIndex) or 0
    end

    function shim:SetListIndex(index)
        self.listIndex = tonumber(index) or 0
        self.value = self.listIndex
        if self.uiItem and self.uiItem.type == "combo" then
            self.uiItem.value = self.listIndex + 1
        end
    end

    function shim:SetList(list)
        self.list = list or {}
        self.config.list = self.list
        if self.uiItem and self.uiItem.options then
            self.uiItem.options = SovereignNormalizeComboList(self.list)
            if self.uiItem.value == nil or self.uiItem.value < 1 or self.uiItem.value > #self.uiItem.options then
                self.uiItem.value = 1
            end
        end
    end

    function shim:SetDefaultValue(value)
        self.value = value
        if type(value) == "string" then
            self.stringValue = value
        elseif type(value) == "boolean" then
            self.toggled = value
        elseif type(value) == "number" then
            self.listIndex = value
        end
        if self.uiItem then
            if self.uiItem.type == "input" then
                self.uiItem.value = tostring(value or "")
            elseif self.uiItem.type == "toggle" then
                self.uiItem.value = value == true
            else
                self.uiItem.value = value
            end
        end
    end

    function shim:SetLimitValues(minValue, maxValue)
        self.minValue = minValue
        self.maxValue = maxValue
        if self.uiItem then
            self.uiItem.min = minValue
            self.uiItem.max = maxValue
        end
    end

    function shim:SetNoCallbackOnPress(value)
        self.noCallbackOnPress = value == true
    end

    function shim:GetIntValue()
        local n = tonumber(self.value)
        if n == nil then n = tonumber(self.listIndex) or 0 end
        return math.floor(n + 0.5)
    end

    function shim:GetFloatValue()
        return tonumber(self.value) or 0.0
    end

    function shim:GetStringValue()
        return tostring(self.stringValue or "")
    end

    function shim:SetStringValue(value)
        self.stringValue = tostring(value or "")
        self.value = self.stringValue
        if self.uiItem and self.uiItem.type == "input" then
            self.uiItem.value = self.stringValue
        end
    end

    function shim:GetColor()
        return self.color.r, self.color.g, self.color.b, self.color.a
    end

    function shim:SetColor(r, g, b, a)
        self.color.r = tonumber(r) or self.color.r
        self.color.g = tonumber(g) or self.color.g
        self.color.b = tonumber(b) or self.color.b
        self.color.a = tonumber(a) or self.color.a
        if self.uiItem and self.uiItem.type == "color" then
            self.uiItem.value = {
                r = self.color.r,
                g = self.color.g,
                b = self.color.b,
                a = self.color.a
            }
        end
    end

    return shim
end

local function SovereignGetOrCreateAdhocShim(config, playerIndex)
    if not config then return nil end
    local key = SovereignConfigKey(config) .. ":" .. tostring(playerIndex or "global")
    local shim = SovereignRuntime.adhocShims[key]
    if shim then
        shim:SetPlayerIndex(playerIndex)
        return shim
    end
    shim = SovereignCreateShim(config, playerIndex)
    SovereignRuntime.adhocShims[key] = shim
    if playerIndex == nil then
        SovereignRegisterShim(shim)
    end
    return shim
end

-- Free-access policy is deliberately allowlisted by the final UI location.
-- It keeps the paid gate on every other feature while allowing the selected
-- local/session utilities to work before a license is entered.
SovereignGroupAllowsFreeAccess = function(groupId, config)
    local group = globalGroups and globalGroups[groupId]
    local subtab = group and globalSubtabs and globalSubtabs[group.subtabID]
    local tab = subtab and menu and menu.tabs and menu.tabs[subtab.tabID]
    local tabName = tab and tostring(tab.sourceName or ""):lower() or ""
    local subtabName = subtab and tostring(subtab.sourceName or ""):lower() or ""

    -- Individual free utilities must not unlock their entire paid page.
    if config and config.hash and Utils and Utils.Joaat then
        if tabName == "protection" and subtabName == "core"
            and config.hash == Utils.Joaat("anticrash_ca") then
            return true
        end
        if tabName == "session" and subtabName == "session"
            and (config.hash == Utils.Joaat("force_cloud_save")
                or config.hash == Utils.Joaat("anti_spectate")) then
            return true
        end
    end

    if tabName == "settings" then
        return true
    end
    if tabName == "local" and subtabName == "self" then
        return true
    end
    if tabName == "world" and subtabName == "extensions" then
        return true
    end
    if tabName == "players" and subtabName == "information" then
        return true
    end
    if tabName == "missions" and subtabName == "tools" then
        return true
    end
    if tabName == "protection" and subtabName == "saved players" then
        return true
    end

    -- These specific player trolling utilities are intentionally free. The
    -- rest of the Trolling page remains license-gated.
    if tabName == "players" and subtabName == "trolling" and config and Utils and Utils.Joaat then
        local freeNames = {
            "sovereign_troll_mount_player",
            "sovereign_troll_coffin_team",
            "sovereign_troll_dog_pack",
            "sovereign_troll_teleport_to_player",
            "sovereign_troll_enter_vehicle",
            "sovereign_troll_mark_player",
            "sovereign_troll_lock_inside_vehicle",
            "sovereign_troll_slippery_vehicle",
            "sovereign_troll_disable_engine",
            "sovereign_troll_flip_vehicle",
        }
        for _, name in ipairs(freeNames) do
            if config.hash == Utils.Joaat(name) then
                return true
            end
        end
    end
    return false
end

SovereignSubtabAllowsFreeAccess = function(subtabID)
    local subtab = globalSubtabs and globalSubtabs[subtabID]
    local tab = subtab and menu and menu.tabs and menu.tabs[subtab.tabID]
    local tabName = tab and tostring(tab.sourceName or ""):lower() or ""
    local subtabName = subtab and tostring(subtab.sourceName or ""):lower() or ""
    return tabName == "settings"
        or (tabName == "local" and subtabName == "self")
        or (tabName == "world" and subtabName == "extensions")
        or (tabName == "players" and subtabName == "information")
        or (tabName == "missions" and subtabName == "tools")
        or (tabName == "protection" and subtabName == "saved players")
end

SovereignFeatureIsFree = function(config)
    return config and config._sovereignFreeAccess == true
end

SovereignMenuSessionValid = function()
    return AuthManager and type(AuthManager.SessionValid) == "function"
        and AuthManager:SessionValid() == true
end

-- Menu visibility and callback authorization share the same allowlist.  The
-- renderer calls this after the menu has been built, so the late-bound policy
-- is also available to search, favorites and recent items.
SovereignMenuFeatureVisible = function(item, group)
    if SovereignMenuSessionValid() then return true end
    if group and SovereignRuntime and group.id == SovereignRuntime.authGroupId then return true end
    if group and group._sovereignAccessNotice == true then return true end
    if group and type(SovereignGroupAllowsFreeAccess) == "function"
        and SovereignGroupAllowsFreeAccess(group.id, item and item._sovereignConfig) then
        return true
    end
    return item and item._sovereignFreeAccess == true
end

SovereignInvokeShim = LPH_JIT(function(shim, fromTick, checkResult)
    if not shim or not shim.config or type(shim.config.cb) ~= "function" then
        return true, nil
    end
    if not SovereignFeatureIsFree(shim.config) and not SovereignCheckAuth() then
        return false, "auth_required"
    end
    if shim.config._sovereignRequiresOldUser then
        local allowed = AuthManager and USER_TYPE and AuthManager.userType == USER_TYPE.OLD
        if allowed and AuthManager.IsOldUser then
            allowed = AuthManager:IsOldUser(AuthManager.currentKey)
        end
        if not allowed then
            SovereignNotify("SovereignLua", "This feature is available for old users only", "warning")
            return false, "old_user_required"
        end
    end
    -- Preserve the click's identity across SovereignRunJob/Script.QueueJob.
    -- This belongs to this invocation, never to a reusable player shim.
    local targetGuard = menu.playerActionGuard
    local targetSnapshot = targetGuard and targetGuard.currentSnapshot
    local function call()
        if targetSnapshot and (menu.playerActionGuard ~= targetGuard
            or shim.playerIndex ~= targetSnapshot.pid
            or not targetGuard:Matches(targetSnapshot)) then
            return true, false
        end
        return SovereignWithSelectedPlayer(shim.playerIndex, function()
            return shim.config.cb(shim)
        end)
    end
    if fromTick then
        local ok, err = call()
        if not ok then
            SovereignLogError("SovereignRuntime.Tick:" .. tostring(shim.config.name), err)
            return false, tostring(err)
        end
        return checkResult ~= true or err ~= false, err == false and "callback_returned_false" or nil
    end
    return SovereignRunJob("SovereignRuntime.Feature:" .. tostring(shim.config.name), function()
        local ok, err = call()
        if not ok then
            error(err)
        end
    end)
end)

local function SovereignIsTickFeature(config)
    return config and SovereignOnTick ~= nil and config.callbackTrigger == SovereignOnTick
end

local function SovereignAddTickShim(shim)
    if not shim then return end
    SovereignRuntime.tickShims[shim] = true
end

local function SovereignAddDynamicListShim(shim)
    if shim then
        SovereignRuntime.dynamicListShims[shim] = {last = 0, initialized = false, revision = -1}
    end
end

local function SovereignIsDynamicListFeature(config)
    return config
        and config.hash
        and Utils
        and Utils.Joaat
        and config.hash == Utils.Joaat("save_player_list")
end

local SovereignProcessTickShims = LPH_NO_VIRTUALIZE(function()
    local sessionValid = AuthManager and type(AuthManager.SessionValid) == "function"
        and AuthManager:SessionValid() == true
    for shim in pairs(SovereignRuntime.tickShims) do
        local free = shim and SovereignFeatureIsFree(shim.config)
        if shim and (free or sessionValid) and (shim:IsToggled() or shim.forceTick) then
            SovereignInvokeShim(shim, true)
        end
    end
end)

local function SovereignProcessDynamicLists()
    local now = os.clock()
    local revision = SavedPlayerManager.listRevision
    for shim, state in pairs(SovereignRuntime.dynamicListShims) do
        if shim and state and now - (state.last or 0) > 1.0 then
            state.last = now
            if not state.initialized or state.revision ~= revision then
                if SovereignInvokeShim(shim, true) == true then
                    state.revision = revision
                    state.initialized = true
                end
            end
        end
    end
end

local function SovereignMakePlayerShim(config, pid, st)
    local key = "sovereign_" .. SovereignConfigKey(config)
    st[key .. "_shim"] = st[key .. "_shim"] or SovereignCreateShim(config, pid)
    local shim = st[key .. "_shim"]
    shim:SetPlayerIndex(pid)
    return shim
end

function SovereignRuntime:ShouldRegisterConfig(config)
    if not config or not config.hash or not Utils or not Utils.Joaat then
        return true
    end
    local hash = config.hash
    local joaat = Utils.Joaat
    if hash == joaat("sovereign_import_paint_color")
        or hash == joaat("sovereign_import_paint_size")
        or hash == joaat("sovereign_import_rainbow_paint")
        or hash == joaat("sovereign_import_paintball")
        or hash == joaat("sovereign_import_clear_paint")
        or hash == joaat("sovereign_import_disable_ped_screams")
        or hash == joaat("sovereign_import_disable_ped_speech")
        or hash == joaat("sovereign_import_disable_freemode_music")
        or hash == joaat("sovereign_import_disable_ambient_sounds")
        or hash == joaat("sovereign_import_disable_radio_emitters")
        or hash == joaat("sovereign_import_disable_vehicle_audio")
        or hash == joaat("sovereign_import_disable_radio")
        or hash == joaat("sovereign_import_disable_vehicle_alarms")
        or hash == joaat("sovereign_import_disable_horn_on_death")
        or hash == joaat("sovereign_import_disable_thunder")
        or hash == joaat("sovereign_import_disable_sirens")
        or hash == joaat("sovereign_import_clear_frontend_audio") then
        return false
    end
    return true
end

local function SovereignRegisterFeature(config, groupId, isPlayer)
    if not config or not config.name or not groupId or not SovereignRuntime:ShouldRegisterConfig(config) then return nil end
    config._sovereignFreeAccess = SovereignGroupAllowsFreeAccess(groupId, config) == true
    if SovereignRuntime.menuBuildInProgress then
        SovereignRuntime.menuBuildYieldCounter = SovereignRuntime.menuBuildYieldCounter + 1
        if SovereignRuntime.menuBuildYieldCounter >= SovereignRuntime.menuBuildYieldEvery then
            SovereignRuntime.menuBuildYieldCounter = 0
            if Script and type(Script.Yield) == "function" then
                pcall(Script.Yield, 0)
            end
        end
    end
    SovereignRegisterConfigTemplate(config)
    local desc = config.desc or ""
    local indent = config.indent or 0
    local key = "sovereign_" .. SovereignConfigKey(config)

    local function tag(item)
        if item then
            item._sovereignConfig = config
            item._sovereignFreeAccess = config._sovereignFreeAccess == true
        end
        return item
    end

    if SovereignIsTickFeature(config) and SovereignTypeIs(config, SovereignFeatureType.Button) then
        config._sovereignConvertedToToggle = true
    end

    if isPlayer then
        if SovereignTypeIs(config, SovereignFeatureType.Combo) then
            local defaultIdx = (tonumber(config.defaultValue) or 0) + 1
            local item = menu.pcombo(config.name, desc, groupId, key, SovereignNormalizeComboList(config.list), defaultIdx, indent, function(pid, idx, _, st)
                local shim = SovereignMakePlayerShim(config, pid, st)
                shim:SetListIndex((tonumber(idx) or 1) - 1)
                SovereignInvokeShim(shim, false)
            end)
            return tag(item)
        elseif SovereignTypeIs(config, SovereignFeatureType.SliderInt) or SovereignTypeIs(config, SovereignFeatureType.SliderFloat) then
            local minValue = config.limitValues and config.limitValues[1] or 0
            local maxValue = config.limitValues and config.limitValues[2] or 100
            local defaultValue = config.defaultValue
            if defaultValue == nil then defaultValue = minValue end
            local format = SovereignTypeIs(config, SovereignFeatureType.SliderFloat) and "%.2f" or "%d"
            local item = menu.pslider(config.name, desc, groupId, key, minValue, maxValue, defaultValue, format, indent, function(pid, value, st)
                local shim = SovereignMakePlayerShim(config, pid, st)
                shim.value = value
                SovereignInvokeShim(shim, false)
            end)
            if item then item.step = config.stepSize end
            return tag(item)
        elseif SovereignTypeIs(config, SovereignFeatureType.InputText) and menu.inputText then
            menu.text(config.name .. " (uses selected player)", groupId)
            local item = menu.inputText(config.name, desc, groupId, tostring(config.defaultValue or ""), indent, function(value)
                local pid = menu.player.get()
                local st = menu.pstate(pid)
                if not pid or not st then return end
                local shim = SovereignMakePlayerShim(config, pid, st)
                shim:SetStringValue(value)
                SovereignInvokeShim(shim, false)
            end, config.hint)
            return tag(item)
        elseif SovereignTypeIs(config, SovereignFeatureType.Toggle) or config._sovereignConvertedToToggle then
            local item = menu.ptoggle(config.name, desc, groupId, key, false, indent, function(pid, value, st)
                local shim = SovereignMakePlayerShim(config, pid, st)
                shim.toggled = value == true
                if SovereignIsTickFeature(config) then
                    SovereignAddTickShim(shim)
                end
                SovereignInvokeShim(shim, false)
            end)
            return tag(item)
        else
            local item = menu.pbutton(config.name, desc, groupId, indent, function(pid, st)
                local shim = SovereignMakePlayerShim(config, pid, st or {})
                SovereignInvokeShim(shim, false)
            end)
            return tag(item)
        end
    end

    local shim = SovereignCreateShim(config, nil)
    SovereignRegisterShim(shim)

    local function bindPersistedToggle(item)
        if item and item.type == "toggle" then
            local restoreReady = function()
                return SovereignFeatureIsFree(config) or SovereignMenuSessionValid()
            end
            menu.bindFeatureToggle(item, menu.featurePersistKey(config),
                function() return shim:IsToggled() end,
                function(value)
                    return menu.queueFeatureRestore(menu.featurePersistKey(config), value,
                        function(job) return SovereignRunJob("SovereignConfig.Restore", job) end,
                        function(target, current)
                            local previous = shim:IsToggled()
                            shim:SetToggledSilently(target)
                            local ok, result, reason = pcall(SovereignInvokeShim, shim, true, true)
                            if not ok or result == false then
                                if current() then shim:SetToggledSilently(previous) end
                                return false, not ok and tostring(result) or tostring(reason or "invoke_rejected")
                            end
                            return true
                        end, restoreReady)
                end)
        end
        return item
    end

    if SovereignTypeIs(config, SovereignFeatureType.Combo) then
        local defaultIdx = (tonumber(config.defaultValue) or 0) + 1
        shim.uiItem = menu.combo(config.name, desc, groupId, SovereignNormalizeComboList(config.list), defaultIdx, indent, function(idx)
            shim:SetListIndex((tonumber(idx) or 1) - 1)
            SovereignInvokeShim(shim, false)
        end)
        if SovereignIsDynamicListFeature(config) then
            SovereignAddDynamicListShim(shim)
        end
        return tag(shim.uiItem)
    elseif SovereignTypeIs(config, SovereignFeatureType.SliderInt) or SovereignTypeIs(config, SovereignFeatureType.SliderFloat) then
        local minValue = config.limitValues and config.limitValues[1] or 0
        local maxValue = config.limitValues and config.limitValues[2] or 100
        local defaultValue = config.defaultValue
        if defaultValue == nil then defaultValue = minValue end
        local format = SovereignTypeIs(config, SovereignFeatureType.SliderFloat) and "%.2f" or "%d"
        shim.value = defaultValue
        shim.uiItem = menu.slider(config.name, desc, groupId, minValue, maxValue, defaultValue, format, indent, function(value)
            shim.value = value
            SovereignInvokeShim(shim, false)
        end)
        shim.uiItem.step = config.stepSize
        return tag(shim.uiItem)
    elseif SovereignTypeIs(config, SovereignFeatureType.InputColor3) and menu.color then
        local color = config.defaultColor or {255, 255, 255, 255}
        shim:SetColor(color.r or color[1], color.g or color[2], color.b or color[3], color.a or color[4])
        shim.uiItem = menu.color(config.name, desc, groupId, shim.color, indent, function(r, g, b, a)
            shim:SetColor(r, g, b, a)
            SovereignInvokeShim(shim, false)
        end)
        return tag(shim.uiItem)
    elseif SovereignTypeIs(config, SovereignFeatureType.InputText) and menu.inputText then
        shim:SetStringValue(tostring(config.defaultValue or ""))
        shim.uiItem = menu.inputText(config.name, desc, groupId, shim:GetStringValue(), indent, function(value)
            shim:SetStringValue(value)
            SovereignInvokeShim(shim, false)
        end, config.hint)
        return tag(shim.uiItem)
    elseif SovereignTypeIs(config, SovereignFeatureType.Toggle) or config._sovereignConvertedToToggle then
        shim.uiItem = menu.toggle(config.name, desc, groupId, indent, function(value)
            shim.toggled = value == true
            if SovereignIsTickFeature(config) then
                SovereignAddTickShim(shim)
            end
            SovereignInvokeShim(shim, false)
        end)
        if shim.uiItem then shim.uiItem.value = shim.toggled == true end
        if SovereignIsTickFeature(config) then
            SovereignAddTickShim(shim)
        end
        return tag(bindPersistedToggle(shim.uiItem))
    end

    local item = menu.button(config.name, desc, groupId, indent, function()
        SovereignInvokeShim(shim, false)
    end)
    return tag(item)
end

local function SovereignRegisterFeatureList(configs, groupId, isPlayer)
    for _, config in ipairs(configs or {}) do
        SovereignRegisterFeature(config, groupId, isPlayer)
    end
end

R53RegisterMappedMenu = function(groups)
    local edition = Utils1:edition()
    if edition ~= "Enhanced" and edition ~= "Legacy" then
        menu.text("Feature settings are unavailable for this game version", groups.importedSelf)
        return
    end
    SovereignRegisterFeatureList(MenuDefinitions.ExtendedItems.R53SelfState, groups.importedSelf, false)
    SovereignRegisterFeatureList(MenuDefinitions.ExtendedItems.R53Action, groups.importedMovement, false)
    SovereignRegisterFeatureList(MenuDefinitions.ExtendedItems.R53Aim, groups.weaponAim, false)
    SovereignRegisterFeatureList(MenuDefinitions.ExtendedItems.R53VehicleDriving, groups.vehicleDriving, false)
    SovereignRegisterFeatureList(MenuDefinitions.ExtendedItems.R53VehicleAppearance, groups.vehicleAppearance, false)
    SovereignRegisterFeatureList(MenuDefinitions.ExtendedItems.R53WorldNpc, groups.worldTraffic, false)
    SovereignRegisterFeatureList(MenuDefinitions.ExtendedItems.R53WorldVisual, groups.worldVisual, false)
    SovereignRegisterFeatureList(MenuDefinitions.ExtendedItems.R53Audio, groups.importedWorldAudio, false)
end

local function SovereignRefreshFeatureMgrBridgeBaseline()
    if not AntiHookManager or type(AntiHookManager._store) ~= "function" or not FeatureMgr then
        return
    end
    if type(FeatureMgr.GetFeature) == "function" then
        AntiHookManager:_store("FeatureMgr.GetFeature", FeatureMgr.GetFeature)
    end
    if type(FeatureMgr.GetFeatureByName) == "function" then
        AntiHookManager:_store("FeatureMgr.GetFeatureByName", FeatureMgr.GetFeatureByName)
    end
    if type(FeatureMgr.SetFeatureInt) == "function" then
        AntiHookManager:_store("FeatureMgr.SetFeatureInt", FeatureMgr.SetFeatureInt)
    end
end

local function SovereignBridgeFeatureMgr()
    if not FeatureMgr or SovereignRuntime.featureMgrBridged then return end
    SovereignRuntime.originalFeatureMgr.GetFeature = FeatureMgr.GetFeature
    SovereignRuntime.originalFeatureMgr.GetFeatureByName = FeatureMgr.GetFeatureByName
    SovereignRuntime.originalFeatureMgr.SetFeatureInt = FeatureMgr.SetFeatureInt

    FeatureMgr.GetFeature = function(hash, ...)
        local feature = nil
        if SovereignRuntime.originalFeatureMgr.GetFeature then
            local ok, result = pcall(SovereignRuntime.originalFeatureMgr.GetFeature, hash, ...)
            if ok then feature = result end
        end
        if feature ~= nil then return feature end
        local config = SovereignRuntime.configsByHash[hash]
        local pid = select(1, ...)
        if pid ~= nil and config then
            return SovereignGetOrCreateAdhocShim(config, pid)
        end
        local shim = SovereignRuntime.shimsByHash[hash]
        if shim then return shim end
        if config then
            return SovereignGetOrCreateAdhocShim(config, pid)
        end
        return SovereignGetNoopFeature(hash)
    end

    FeatureMgr.GetFeatureByName = function(name, ...)
        local feature = nil
        if SovereignRuntime.originalFeatureMgr.GetFeatureByName then
            local ok, result = pcall(SovereignRuntime.originalFeatureMgr.GetFeatureByName, name, ...)
            if ok then feature = result end
        end
        if feature ~= nil then return feature end
        local key = tostring(name)
        local config = SovereignRuntime.configsByName[key]
        local pid = select(1, ...)
        if pid ~= nil and config then
            return SovereignGetOrCreateAdhocShim(config, pid)
        end
        local shim = SovereignRuntime.shimsByName[key]
        if shim then return shim end
        if config then
            return SovereignGetOrCreateAdhocShim(config, pid)
        end
        return SovereignGetNoopFeature(key)
    end

    if FeatureMgr.SetFeatureInt then
        FeatureMgr.SetFeatureInt = function(hash, value, ...)
            if hash == nil or hash == 0 then
                return false
            end
            local ok, result = pcall(SovereignRuntime.originalFeatureMgr.SetFeatureInt, hash, value, ...)
            if not ok then
                SovereignLogError("SovereignRuntime.FeatureMgr.SetFeatureInt", result)
                return false
            end
            return result
        end
    end

    SovereignRefreshFeatureMgrBridgeBaseline()
    SovereignRuntime.featureMgrBridged = true
end

local function SovereignGroupByMainGroup(groups, config)
    if not config then return groups.misc end
    if config.hash and Utils and Utils.Joaat then
        local joaat = Utils.Joaat
        if config.hash == joaat("ninjia_run")
            or config.hash == joaat("land_swim")
            or config.hash == joaat("fun_land_swim") then
            return groups.importedMovement
        end
        if config.hash == joaat("boost_refill") then
            return groups.vehicleDriving
        end
        if config.hash == joaat("entity_delete_type")
            or config.hash == joaat("entity_delete_radius")
            or config.hash == joaat("entity_delete_execute") then
            return groups.entityManagement
        end
    end
    if CONFIG and CONFIG.GROUPS then
        if config.group == CONFIG.GROUPS.PROTECTION then return groups.protection end
        if config.group == CONFIG.GROUPS.CRASH then return groups.troll end
        if config.group == CONFIG.GROUPS.SESSION then return groups.session end
        if config.group == CONFIG.GROUPS.TROLL then return groups.troll end
        if config.group == CONFIG.GROUPS.WEAPON then return nil end
        if config.group == CONFIG.GROUPS.EGAO then return groups.troll end
    end
    return groups.misc
end

local function SovereignRegisterSplitMainItems(configs, groups)
    for _, config in ipairs(configs or {}) do
        SovereignRegisterFeature(config, SovereignGroupByMainGroup(groups, config), false)
    end
end

-- The task definitions live in their own adapter closure.  Keep the outer
-- menu builder on the same edition gate without depending on that closure's
-- local helper.
SovereignTaskPageSupported = function(page)
    if tostring(page or ""):lower() ~= "kortz" then return true end
    if Utils1 and type(Utils1.edition) == "function" then
        local ok, edition = pcall(Utils1.edition, Utils1)
        if ok then return tostring(edition):lower() ~= "legacy" end
    end
    return true
end

function SovereignRuntime:RegisterTaskFeatures(taskGroups)
    for _, config in ipairs(MenuDefinitions.ExtendedItems.Tasks or {}) do
        if SovereignTaskPageSupported(config.taskPage) then
            local page = taskGroups and taskGroups[config.taskPage]
            local group = page and page[config.taskGroup]
            if not group then
                group = page and page.root or (taskGroups and taskGroups.root)
            end
            if group then
                local item = SovereignRegisterFeature(config, group, false)
                if item then item.compact = true end
            end
        end
    end
end

function SovereignRuntime:GetVehicleGroup(groups, config)
    if not config then return groups.vehicle end
    local hash = config.hash
    local joaat = Utils and Utils.Joaat
    if not joaat then return groups.vehicle end

    if hash == joaat("veh_speed_boost")
        or hash == joaat("veh_boost_power")
        or hash == joaat("veh_fly_speed")
        or hash == joaat("veh_jump")
        or hash == joaat("veh_instant_stop")
        or hash == joaat("veh_no_collision")
        or hash == joaat("veh_drive_on_water")
        or hash == joaat("veh_fly_mode")
        or hash == joaat("veh_horn_boost")
        or hash == joaat("veh_drift_mode")
        or hash == joaat("veh_drift_handbrake")
        or hash == joaat("veh_keep_engine")
        or hash == joaat("veh_auto_flip")
        or hash == joaat("veh_seatbelt") then
        return groups.vehicleDriving
    end

    if hash == joaat("veh_rainbow_color")
        or hash == joaat("veh_neon_lights")
        or hash == joaat("veh_xenon_lights")
        or hash == joaat("veh_turbo")
        or hash == joaat("veh_max_upgrade")
        or hash == joaat("veh_random_upgrade")
        or hash == joaat("dk_wheel_trails")
        or hash == joaat("fun_gta4_neon")
        or hash == joaat("fun_clear_gta4_neon")
        or hash == joaat("dk_engine_sound_select")
        or hash == joaat("dk_apply_engine_sound") then
        return groups.vehicleAppearance
    end

    if hash == joaat("veh_fix")
        or hash == joaat("veh_clean")
        or hash == joaat("veh_fix_tires")
        or hash == joaat("veh_open_doors")
        or hash == joaat("veh_close_doors")
        or hash == joaat("veh_flip")
        or hash == joaat("veh_delete") then
        return groups.vehicleAction
    end

    if hash == joaat("dk_last_vehicle_to_me")
