local function SovereignEnableAuthorizedRuntime()
    if not MemoryBridge:Initialize(false) then
        if SovereignRuntime.mappingError ~= MemoryBridge.lastScanReport then
            SovereignRuntime.mappingError = MemoryBridge.lastScanReport
            SovereignLogError("SovereignRuntime.Mapping", MemoryBridge.lastScanReport)
        end
        return false
    end
    if SovereignRuntime.authorized then
        return true
    end
    SovereignRuntime.authorized = true
    return true
end

function SovereignRuntime:ApplyPermissionVisibility()
    local authenticated = SovereignMenuSessionValid()
    if self.permissionGroupsApplied and self.permissionVisibilityState == authenticated then
        return
    end
    if self.authGroupId then
        -- Keep the login controls available while signed out, and remove them
        -- after a valid session is established.
        menu.setGroupHidden(self.authGroupId, authenticated)
        self.authGroupHidden = authenticated
    end
    if self.playerVipGroupId then
        local isOldUser = authenticated and AuthManager and USER_TYPE and AuthManager.userType == USER_TYPE.OLD
        if isOldUser and AuthManager.IsOldUser then
            isOldUser = AuthManager:IsOldUser(AuthManager.currentKey)
        end
        menu.setGroupHidden(self.playerVipGroupId, not isOldUser)
    end
    for _, subtab in ipairs(globalSubtabs or {}) do
        if subtab and not SovereignSubtabAllowsFreeAccess(subtab.id) then
            local noticeID = self.loginNoticeGroups[subtab.id]
            if not noticeID or not globalGroups[noticeID] then
                noticeID = menu.group("Sovereign access", subtab.id)
                local noticeGroup = globalGroups[noticeID]
                if noticeGroup then
                    noticeGroup._sovereignAccessNotice = true
                    noticeGroup.compact = true
                    noticeGroup.noSplit = true
                    menu.text("Sign in to Sovereign to unlock all features", noticeID)
                end
                self.loginNoticeGroups[subtab.id] = noticeID
            end
            if globalGroups[noticeID] then
                globalGroups[noticeID].hidden = authenticated
            end
        end
    end
    self.permissionGroupsApplied = true
    self.permissionVisibilityState = authenticated
    if menu.quick then
        menu.quick.searchDirty = true
        if menu.quick.loaded then menu.refreshQuickGroups() end
    end
end

function menu.registerHotkey()
    if menu.hotkeyRegistered then
        return true
    end
    if not FeatureMgr or not Utils or not eFeatureType or not eFeatureType.Button then
        return false
    end
    local hash = Utils.Joaat("sovereign_menu_toggle_f4")
    local ok, feature = pcall(function()
        local existing = nil
        if FeatureMgr.GetFeature then
            local foundOk, found = pcall(FeatureMgr.GetFeature, hash)
            if foundOk then existing = found end
        end
        if existing ~= nil then
            return existing
        end
        return FeatureMgr.AddFeature(hash, "Sovereign Menu", eFeatureType.Button, "Toggle Sovereign menu", function()
            menu.toggleOpen()
        end, false)
    end)
    if not ok or not feature then
        SovereignLogError("SovereignRuntime.MenuHotkey", feature)
        return false
    end
    if feature.SetSearchable then pcall(function() feature:SetSearchable(false) end) end
    if feature.SetSaveable then pcall(function() feature:SetSaveable(false) end) end
    menu.hotkeyHash = hash
    menu.hotkeyFeature = feature
    menu.hotkeyRegistered = true
    if not menu.applyToggleHotkey(menu.toggleKey) then
        SovereignLogError("SovereignRuntime.MenuHotkey", "failed to bind configured key")
        return false
    end
    return true
end

local function SovereignLogin(force)
    local now = os.clock()
    if SovereignRuntime.authInProgress then return end
    if not force and AuthManager.loginRetryBlocked then return end
    if not force and now < (SovereignRuntime.autoLoginNextAttempt or 0) then return end
    if force and now - (SovereignRuntime.lastLoginAttemptAt or 0) < 2.0 then return end
    SovereignRuntime.lastLoginAttemptAt = now
    SovereignRuntime.authInProgress = true
    local queued = SovereignRunJob("SovereignRuntime.Login", function()
        local success, err = xpcall(function()
            if AuthManager.currentKey == "" then
                SovereignNotify("SovereignLua", "License key is empty", "warning")
                return
            end
            local ok = false
            if AuthManager:SecureInitialize() then
                local detectOk = detectplayerstate()
                if detectOk then
                    -- Snapshot the submitted key after any host wait.
                    local submittedKey = AuthManager.currentKey
                    local loginOk, loginResult = pcall(function()
                        return AuthManager:SecureLogin(submittedKey)
                    end)
                    ok = loginOk and loginResult == true
                    if not loginOk then
                        SovereignLogError("SovereignRuntime.Login", loginResult)
                    end
                end
            end
            if AuthManager:SessionValid() then
                if SovereignEnableAuthorizedRuntime() then
                    SovereignNotify("SovereignLua", "Verification complete", "success")
                end
            elseif not ok and not AuthManager.loginRetryBlocked then
                local reason = RuntimeLeaseState and RuntimeLeaseState.lastFailureReason
                local message
                if reason == "curl_timeout" or reason == "curl_request" or reason == "curl_unavailable"
                    or reason == "curl_create" or reason == "curl_poll" or reason == "getaddrinfo" then
                    message = "Cannot connect to authentication service. Try again later"
                elseif reason == "invalid_lease" or reason == "lease_expired" then
                    message = "Authentication service returned no valid authorization. Try again later"
                else
                    message = "Verification incomplete. Try again later"
                end
                local now = os.clock()
                if now - (SovereignRuntime.lastLoginNoticeAt or 0) >= 8.0 then
                    SovereignRuntime.lastLoginNoticeAt = now
                    SovereignNotify("SovereignLua", message, "warning")
                end
            end
        end, debug.traceback)
        if not success then
            SovereignLogError("SovereignRuntime.Login", err)
        end
        SovereignRuntime.authInProgress = false
        SovereignRuntime.autoLoginQueued = false
        if AuthManager.loginRetryBlocked then
            SovereignRuntime.autoLoginNextAttempt = rawget(math, "huge")
        elseif AuthManager:SessionValid() then
            SovereignRuntime.autoLoginFailureCount = 0
            SovereignRuntime.autoLoginNextAttempt = rawget(math, "huge")
        else
            SovereignRuntime.autoLoginFailureCount = math.min(6, (SovereignRuntime.autoLoginFailureCount or 0) + 1)
            local delay = math.min(60.0, 10.0 * (2 ^ math.max(0, SovereignRuntime.autoLoginFailureCount - 1)))
            SovereignRuntime.autoLoginNextAttempt = os.clock() + delay
        end
    end)
    if not queued then
        SovereignRuntime.authInProgress = false
        SovereignRuntime.autoLoginQueued = false
        SovereignRuntime.autoLoginFailureCount = math.min(6, (SovereignRuntime.autoLoginFailureCount or 0) + 1)
        SovereignRuntime.autoLoginNextAttempt = os.clock() + math.min(60.0, 10.0 * (2 ^ math.max(0, SovereignRuntime.autoLoginFailureCount - 1)))
    end
end

