    -- Cherax settings/pseudocode. These are list positions, not event IDs.
    local CheraxEventStarter = {
        selectorHash = 152661453,
        buttonHash = 305781531,
        entries = {
            tennis={index=219,label="tennis_network_mp"},
            golf={index=217,label="golf_mp"},
            darts={index=216,label="AM_Darts"},
            armwrestle={index=215,label="AM_ArmWrestling"},
