            skydive={index=145,label="fm_content_skydive"},
            ufo={index=172,label="fm_content_ufo_abduction"},
        },
    }
    function CheraxEventStarter:Start(key)
        local entry=self.entries[key]
        if not entry or not FeatureMgr then return false,"cherax_event_starter_unavailable" end
        if not Utils1 or type(Utils1.edition)~="function" or Utils1:edition()~="Enhanced" then
            return false,"cherax_event_starter_legacy_unverified"
        end
        if type(FeatureMgr.SetFeatureListIndex)~="function"
            or type(FeatureMgr.TriggerFeatureCallback)~="function" then
            return false,"cherax_event_starter_api_unavailable"
        end
        local setOk,setResult=pcall(FeatureMgr.SetFeatureListIndex,self.selectorHash,entry.index)
        if not setOk or setResult==false then return false,"cherax_event_selector_rejected" end
        local clickOk,clickResult=pcall(FeatureMgr.TriggerFeatureCallback,self.buttonHash)
        if not clickOk or clickResult==false then return false,"cherax_event_callback_rejected" end
        return true,string.format("Cherax Event Starter requested: %s (index=%d)",entry.label,entry.index)
    end
    menu.cheraxEventStarter=CheraxEventStarter
    api.cheraxEventStarter=CheraxEventStarter

    local profiles = {
        Legacy={build="6A4F9ED3-03E5BC00",moduleSha256="677e4e355cfbdb13273b1d992407e3c261b3a108dc4dd5c8a0c4c1da651802e5", players=1892925, missions=2655292,activityInfo=1675664,activityFlags=1674453,
            tennis=250, golf=248, darts=247, armwrestle=246},
        Enhanced={build="6AA45F10-05B45200",moduleSha256="69da07ff67d05e9ded11289e597e8b8dc5855b0a429c085f37d148dc267cb2c5", players=1893070, missions=2655295,activityInfo=1675717,activityFlags=1674506,
            tennis=253, golf=251, darts=250, armwrestle=249},
    }
    local labels = {
        repair="Repair player vehicles", upright="Recover overturned player vehicles", unlock="Unlock player vehicles", clean="Clean player vehicles",
        health="Distribute medical supplies", armour="Distribute armour supplies", wanted="Request wanted level removal",
        golf="Send golf activity requests", darts="Send darts activity requests", armwrestle="Send arm wrestling activity requests",
        tennis="Send tennis activity requests", pizza="Request pizza delivery activity", skydive="Request skydiving activity", ufo="Request UFO activity",
    }
    local vehicleActions = {repair=true,upright=true,unlock=true,clean=true}
    local invitations = {tennis=true,golf=true,darts=true,armwrestle=true}
    local activities = {pizza=340,skydive=267,ufo=314}
    local pickupDefinitions = {
        health={kind="PICKUP_HEALTH_STANDARD",model="prop_ld_health_pack",amount=100},
        armour={kind="PICKUP_ARMOUR_STANDARD",model="prop_armour_pickup",amount=100},
    }
    local function native(ns, name, ...)
        local bucket=menu.nativeApis and menu.nativeApis[ns]
        local fn=bucket and bucket[name]
        if type(fn)~="function" then error("Native unavailable: "..ns.."."..name,0) end
        return fn(...)
    end
    local function now() return SovereignProtectionFeedback:Now() end
    local function authorized()
        return AuthManager and type(AuthManager.SessionValid)=="function" and AuthManager:SessionValid()
            and not (type(ShouldUnload)=="function" and ShouldUnload())
    end
    local function notify(message, kind) SovereignNotify("Session support", message, kind or "info") end
    local function integer(value)
        return type(value)=="number" and value==value and value%1==0
            and value>=-0x80000000 and value<=0xffffffff
    end
    local function read(index)
        local ok, value=pcall(ScriptGlobal.GetInt,index)
        if not ok or not integer(value) then error("Activity data has not synchronized yet",0) end
        return value
    end
    local function readWord(index)
        if type(ScriptGlobal.GetPtr)~="function" or not Memory or type(Memory.ReadLong)~="function" then
            error("The activity data reader is unavailable",0)
        end
