        if type(pointer)~="number" or pointer<0x10000 then error("Activity details have not synchronized yet",0) end
        local value=Memory.ReadLong(pointer)
        if type(value)~="number" or math.type(value)~="integer" then error("Activity details are incomplete",0) end
        return value
    end
    function api:Profile()
        -- Only this module's reviewed globals/envelopes are covered here.
        -- The loader's generic pointer mapping has no freemode feature flag;
        -- do not promote that mapping to a blanket freemode approval.
        local edition=Utils1:edition()
        local profile=profiles[edition]
        local build=Utils1:DetectBuildIdentifier()
        if not profile or build~=profile.build then return nil,"The game version does not match the activity data." end
        if not MemoryBridge or type(MemoryBridge.ResolveMappingProfile)~="function" then
            return nil,"Activity version identity is not ready. Sign in again and retry."
        end
        local ok,mapping=pcall(MemoryBridge.ResolveMappingProfile,MemoryBridge)
        if not ok or type(mapping)~="table" then
            return nil,"Activity version identity is not ready. Sign in again and retry."
        end
        if mapping.sessionSupportDisabled==true then return nil,"Session activity support is disabled for this version." end
        if mapping.edition~=edition:lower() or mapping.gameBuild~=profile.build
            or type(mapping.moduleSha256)~="string" or mapping.moduleSha256:lower()~=profile.moduleSha256 then
            return nil,"The game file does not match a verified activity version."
        end
        return profile
    end
    function api:Invitation(profile, key)
        local wantedType=profile[key]
        -- The game's own sender copies the 21-word descriptor from a live slot.
        -- Do not synthesize a job name, session token, location or invitation.
        for slot=0,15 do
            local base=profile.missions+1+slot*41
            local state=read(base)
            if state>=0 and state<5 and read(base+3)==wantedType then
                local words={}
                -- Packed job-name slots contain all 64 bits. GetInt would truncate them.
                for field=0,20 do words[field+1]=readWord(base+3+field) end
                local hasName=false
                for field=4,9 do if words[field]~=0 then hasName=true;break end end
                if hasName and words[18]~=0 then
                    return {slot=slot,words=words,slotFlags=read(base+40)}
                end
            end
        end
        return nil,"Create the corresponding activity lobby in the game before sending requests."
    end
    function api:InvitationFlags(profile, activity)
        -- freemode func_354 -> func_352 -> func_351. The checked builds have
        -- no supported team-specific resolution (func_355/356 return false).
        local info=profile.activityInfo+1+activity*6
        if read(info+4)~=0 then return nil,"The activity's team requirements have not been met" end
        local index=read(info+5)
        local count=read(profile.activityFlags)
        if count<=0 or count>1210 or index<0 or index>=count then return nil,"Activity invitation requirements have not synchronized yet" end
        return read(profile.activityFlags+1+index)
    end
    function api:Identity(pid)
        if not integer(pid) or pid<0 or pid>31 or not native("NETWORK","NETWORK_IS_PLAYER_ACTIVE",pid) then return nil end
        local rid=GetPlayerRockstarId(pid)
        if type(rid)~="number" or rid<=0 then return nil end
        return tostring(rid)
    end
    function api:CheckTarget(row, streamed)
        if self:Identity(row.pid)~=row.rid then return nil,"The player left or another player took their slot" end
        if not streamed then return true end
        local ped=native("PLAYER","GET_PLAYER_PED",row.pid)
        if not ped or ped==0 or not native("ENTITY","DOES_ENTITY_EXIST",ped)
            or native("ENTITY","IS_ENTITY_DEAD",ped,false) then return nil,"The player's character is not loaded or is down" end
        local pos=native("ENTITY","GET_ENTITY_COORDS",ped,true)
        local own=native("ENTITY","GET_ENTITY_COORDS",native("PLAYER","PLAYER_PED_ID"),true)
        if not pos or not own then return nil,"Position has not synchronized yet" end
        local dx,dy,dz=pos.x-own.x,pos.y-own.y,pos.z-own.z
        if dx*dx+dy*dy+dz*dz>1000*1000 then return nil,"The player is outside streaming range" end
        return ped,pos
    end
    function api:StartForPlayer(key,pid,capturedRid)
        if self.stopped then return false end
        if key~="health" and key~="armour" and key~="wanted" then
            notify("This operation is unavailable for individual support.","warning");return false
        end
        -- Explicit target entry: nil/invalid selection must never become a batch.
        if not integer(pid) or pid<0 or pid>31 then
            notify("Select another online player.","warning");return false
        end
        return self:Start(key,pid,capturedRid)
    end
    function api:Start(key,selectedPid,capturedRid)
        if self.stopped then return false end
        if not authorized() then notify("Sign-in verification is not complete","warning");return false end
        if not labels[key] then return false end
        if self.job then notify("A batch operation is already running. Cancel it before starting another.","warning");return false end
        local time=now()
        if time<(self.cooldown[key] or 0) then notify("This action is on cooldown. Please try again shortly.","warning");return false end
        local job={key=key,rows={},index=1,seenVehicles={},verified=0,submitted=0,failed=0,skipped=0,nextAt=time,created=time}
        if invitations[key] or activities[key] or key=="wanted" then
            local reason
            job.profile,reason=self:Profile()
            if not job.profile then notify(reason,"warning");return false end
            if invitations[key] then
                local started,startMessage=self.cheraxEventStarter:Start(key)
                if started then
                    job.cheraxEventStartedAt=time
                    job.cheraxEventDeadline=time+6.0
                    job.cheraxEventMessage=startMessage
                else
                    local ok,invitation,message=pcall(self.Invitation,self,job.profile,key)
                    if not ok or not invitation then notify(ok and message or tostring(invitation),"warning");return false end
                    job.invitation=invitation
                end
            end
        end
        if pickupDefinitions[key] and #self.pickups>=64 then notify("Previous supplies are still being cleaned up. Please try again shortly.","warning");return false end
        local own=native("PLAYER","PLAYER_ID")
        if selectedPid~=nil then
            if not integer(selectedPid) or selectedPid<0 or selectedPid>31 or selectedPid==own then
                notify("Select another online player.","warning");return false
            end
            local rid=self:Identity(selectedPid)
            if not rid then notify("The selected player left or their identity has not synchronized.","warning");return false end
            if capturedRid ~= nil and tostring(capturedRid) ~= tostring(rid) then
                notify("The selected player's identity changed. Select the player again.","warning");return false
            end
            job.rows[1]={pid=selectedPid,rid=rid}
            job.selectedPid=selectedPid
        else
            local seen={}
            local candidates={}
            for _,pid in ipairs(Players.Get() or {}) do candidates[#candidates+1]=pid end
            candidates[#candidates+1]=own
            for _,pid in ipairs(candidates) do
                if not seen[pid] then
                    seen[pid]=true
                    local rid=self:Identity(pid)
                    if rid then job.rows[#job.rows+1]={pid=pid,rid=rid} else job.skipped=job.skipped+1 end
                end
            end
        end
        if #job.rows==0 then notify("No online players with a synced identity","warning");return false end
        if activities[key] then
            local started,startMessage=self.cheraxEventStarter:Start(key)
            if started then
                self.cooldown[key]=time+30
                notify(labels[key].."："..startMessage.."; recipient confirmation is pending")
                return true
            end
        end
        self.cooldown[key]=time+(pickupDefinitions[key] and 60 or (invitations[key] or activities[key]) and 30 or 5)
        self.job=job
        notify(labels[key]..": queued "..#job.rows.." players"..(job.cheraxEventMessage and "；"..job.cheraxEventMessage or ""))
        return true
    end
    function api:FinishRow(kind, reason)
        local job=self.job
        job[kind]=job[kind]+1
        if reason then job.lastReason=reason end
        job.current=nil;job.index=job.index+1;job.nextAt=now()+0.12
    end
    function api:Send(pid,args,descriptor)
        if not GTA or type(GTA.TriggerScriptEvent)~="function" then return false,"This action is currently unavailable." end
        for i,value in ipairs(args) do
            if descriptor and i>=4 and i<=24 then
                if type(value)~="number" or math.type(value)~="integer" then return false,"Activity details are invalid" end
            else
                if not integer(value) then return false,"This action is currently unavailable." end
                value=value&0xffffffff;args[i]=value>=0x80000000 and value-0x100000000 or value
            end
        end
        local ok,result=pcall(GTA.TriggerScriptEvent,1<<pid,args)
        if not ok then return false,"The activity request failed" end
        if result==false or result==0 then return false,"The activity request was rejected" end
        return true,result==nil and "Send requested; recipient confirmation is pending" or "Request submitted; recipient confirmation is pending"
    end
    function api:SendActivity(pid,activity)
        if not integer(pid) or pid<0 or pid>31 or pid==native("PLAYER","PLAYER_ID")
            or not native("NETWORK","NETWORK_IS_PLAYER_ACTIVE",pid) then
            return false,"Select another online player."
        end
        if not integer(activity) then return false,"This action is currently unavailable." end
        if not GTA or type(GTA.TriggerScriptEvent)~="function" then return false,"This action is currently unavailable." end
        local localId=type(GTA.GetLocalPlayerId)=="function" and GTA.GetLocalPlayerId()
            or native("PLAYER","PLAYER_ID")
        if not integer(localId) or localId<0 or localId>31 then return false,"Wait for your character to finish loading, then try again." end
        local ok,result=pcall(GTA.TriggerScriptEvent,1<<pid,1450115979,pid,localId,activity,-1)
        if not ok then return false,"The activity request failed" end
        if result==false or result==0 then return false,"The activity request was rejected" end
        return true,result==nil and "Cherax activity request sent; recipient confirmation is pending" or "Cherax activity request submitted; recipient confirmation is pending"
    end
    function api:EventStep(job,row)
        if not self:CheckTarget(row,false) then return self:FinishRow("skipped","The player's identity changed") end
        local profile,reason=self:Profile()
        if profile~=job.profile then return self:FinishRow("failed",reason or "The game compatibility profile changed") end
        if invitations[job.key] and not job.invitation then
            local current,invitationReason=self:Invitation(profile,job.key)
            if not current then
                if job.cheraxEventDeadline and now()<job.cheraxEventDeadline then
                    job.nextAt=now()+0.15
                    return
                end
                return self:FinishRow("failed",invitationReason or "Cherax Event Starter did not create the required activity lobby")
            end
            job.invitation=current
        end
        local sender=native("PLAYER","PLAYER_ID")
        local args
        if job.invitation then
            local current=self:Invitation(profile,job.key)
            if not current or current.slot~=job.invitation.slot then return self:FinishRow("failed","The activity lobby closed") end
            local bits,flagReason=self:InvitationFlags(profile,current.words[1])
            if bits==nil then return self:FinishRow("skipped",flagReason) end
            local short=(bits&8)~=0
            args={short and 1541018842 or -366707054,sender,0}
            for i=1,21 do
                if current.words[i]~=job.invitation.words[i] then return self:FinishRow("failed","The activity lobby changed") end
                args[#args+1]=current.words[i]
            end
            args[25]=(current.slotFlags&2)~=0 and 4 or 0
            if not short then
                -- Match game's func_340 -> func_346: bParam2 combines activity
                -- permission bits 0/1; bParam3 uses slot bit 0 only otherwise.
                if (bits&3)~=0 then args[25]=args[25]|1
                elseif (current.slotFlags&1)~=0 then args[25]=args[25]|2 end
                local token=read(profile.players+1+row.pid*615+517)
                if token==0 then return self:FinishRow("skipped","The player's session is not synchronized yet") end
                args[26]=token;args[27]=current.slot
            end
        elseif job.key=="wanted" then
            local token=read(profile.players+1+row.pid*615+517)
            if token==0 then return self:FinishRow("skipped","The player's session is not synchronized yet") end
            args={-1704545346,sender,0,token}
        else
            local ok,message=self:SendActivity(row.pid,activities[job.key])
            self:FinishRow(ok and "submitted" or "failed",ok and nil or message)
            return
        end
        local ok,message=self:Send(row.pid,args,job.invitation~=nil)
        self:FinishRow(ok and "submitted" or "failed",ok and nil or message)
    end
    function api:VehicleStep(job,row,time)
        local ped,reason=self:CheckTarget(row,true)
        if not ped then return self:FinishRow("skipped",reason) end
        local vehicle=native("PED","GET_VEHICLE_PED_IS_IN",ped,false)
        if vehicle==0 or not native("ENTITY","DOES_ENTITY_EXIST",vehicle) then return self:FinishRow("skipped","The player is not in a vehicle") end
        if not job.current then
            if job.seenVehicles[vehicle] then return self:FinishRow("skipped","Passengers in the same vehicle were grouped together") end
            job.current={vehicle=vehicle,model=native("ENTITY","GET_ENTITY_MODEL",vehicle),started=time,requestAt=0}
        end
        local state=job.current
        if vehicle~=state.vehicle or native("ENTITY","GET_ENTITY_MODEL",vehicle)~=state.model then return self:FinishRow("skipped","The player changed vehicles") end
        if state.written then
            local verified=false
            if job.key=="repair" then
                verified=native("VEHICLE","GET_VEHICLE_ENGINE_HEALTH",vehicle)>=999.0 and native("VEHICLE","GET_VEHICLE_BODY_HEALTH",vehicle)>=999.0
            elseif job.key=="upright" then verified=math.abs(native("ENTITY","GET_ENTITY_ROLL",vehicle))<15
            elseif job.key=="unlock" then verified=native("VEHICLE","GET_VEHICLE_DOOR_LOCK_STATUS",vehicle)==1
            elseif job.key=="clean" then verified=native("VEHICLE","GET_VEHICLE_DIRT_LEVEL",vehicle)<=0.1 end
            if verified then job.seenVehicles[vehicle]=true;return self:FinishRow("verified") end
            if time-state.written>=1.0 then return self:FinishRow("failed","The vehicle state could not be confirmed") end
            job.nextAt=time+0.1;return
        end
        if native("NETWORK","NETWORK_GET_ENTITY_IS_NETWORKED",vehicle)~=false and native("NETWORK","NETWORK_HAS_CONTROL_OF_ENTITY",vehicle)~=true then
            if time-state.started>=1.5 then return self:FinishRow("failed","Could not obtain control of the vehicle") end
            if time>=state.requestAt then native("NETWORK","NETWORK_REQUEST_CONTROL_OF_ENTITY",vehicle);state.requestAt=time+0.15 end
            job.nextAt=time+0.05;return
        end
        if job.key=="repair" then
            native("VEHICLE","SET_VEHICLE_FIXED",vehicle)
            native("VEHICLE","SET_VEHICLE_DEFORMATION_FIXED",vehicle)
        elseif job.key=="upright" then
            if native("ENTITY","GET_ENTITY_SPEED",vehicle)>3.0 or native("ENTITY","IS_ENTITY_IN_AIR",vehicle) then return self:FinishRow("skipped","Only stationary vehicles on the ground can be righted") end
            if native("VEHICLE","IS_THIS_MODEL_A_HELI",state.model) or native("VEHICLE","IS_THIS_MODEL_A_PLANE",state.model)
                or native("VEHICLE","IS_THIS_MODEL_A_BOAT",state.model) or native("VEHICLE","IS_THIS_MODEL_A_TRAIN",state.model) then return self:FinishRow("skipped","Only ground vehicles can be righted") end
            native("VEHICLE","SET_VEHICLE_ON_GROUND_PROPERLY",vehicle,5.0)
        elseif job.key=="unlock" then native("VEHICLE","SET_VEHICLE_DOORS_LOCKED",vehicle,1)
        elseif job.key=="clean" then native("VEHICLE","SET_VEHICLE_DIRT_LEVEL",vehicle,0.0);native("VEHICLE","SET_VEHICLE_ENVEFF_SCALE",vehicle,0.0) end
        state.written=time;job.nextAt=time+0.15
    end
    function api:PickupStep(job,row,time)
        local ped,pos=self:CheckTarget(row,true)
        if not ped then return self:FinishRow("skipped",pos) end
        if native("PED","IS_PED_IN_ANY_VEHICLE",ped,false) then return self:FinishRow("skipped","The player needs to leave their vehicle to collect supplies") end
        if #self.pickups>=64 then return self:FinishRow("skipped","The supply limit has been reached") end
        local definition=pickupDefinitions[job.key]
        if not job.model then
            job.model=Utils.Joaat(definition.model);job.modelStarted=time
            if not native("STREAMING","IS_MODEL_VALID",job.model) then return self:FinishRow("failed","The supply model is unavailable") end
            native("STREAMING","REQUEST_MODEL",job.model)
        end
        if not native("STREAMING","HAS_MODEL_LOADED",job.model) then
            if time-job.modelStarted>=3.0 then return self:FinishRow("failed","Loading the supply model timed out") end
            job.nextAt=time+0.1;return
        end
        if native("NETWORK","CAN_REGISTER_MISSION_PICKUPS",1)~=true then return self:FinishRow("failed","The game cannot create any more supplies") end
        local point=native("ENTITY","GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS",ped,0.0,1.0,0.0)
        local object=native("OBJECT","CREATE_AMBIENT_PICKUP",Utils.Joaat(definition.kind),point.x,point.y,point.z,282,definition.amount,job.model,true,false)
        if not object or object==0 or not native("ENTITY","DOES_ENTITY_EXIST",object) then return self:FinishRow("failed","The supply could not be created") end
        local networked=native("NETWORK","NETWORK_GET_ENTITY_IS_NETWORKED",object)
        local netId=networked==true and native("NETWORK","NETWORK_GET_NETWORK_ID_FROM_ENTITY",object) or nil
        self.pickups[#self.pickups+1]={object=object,model=job.model,netId=netId,expires=time+60.0,retries=0}
        if native("NETWORK","NETWORK_GET_ENTITY_IS_NETWORKED",object)~=true then return self:FinishRow("failed","The supply did not synchronize with the session") end
        self:FinishRow("verified") -- Object existence only: recipient collection is not claimed.
    end
    function api:ReleasePickup(entry)
        local ptr
        local ok=pcall(function()
            ptr=Memory.AllocInt()
            if not ptr or ptr==0 then error("Allocation unavailable") end
            Memory.WriteInt(ptr,entry.object)
            native("ENTITY","SET_ENTITY_AS_NO_LONGER_NEEDED",ptr)
        end)
        if ptr and ptr~=0 then pcall(Memory.Free,ptr) end
        return ok
    end
    function api:CleanupPickup(index)
        local entry=self.pickups[index]
        if not entry then return end
        local exists=native("ENTITY","DOES_ENTITY_EXIST",entry.object)
        if not exists or native("ENTITY","GET_ENTITY_MODEL",entry.object)~=entry.model
            or (entry.netId and native("NETWORK","NETWORK_GET_NETWORK_ID_FROM_ENTITY",entry.object)~=entry.netId) then table.remove(self.pickups,index);return end
        if native("NETWORK","NETWORK_GET_ENTITY_IS_NETWORKED",entry.object)~=false and native("NETWORK","NETWORK_HAS_CONTROL_OF_ENTITY",entry.object)~=true then
            if entry.retries>=8 then
                self:ReleasePickup(entry)
                self.cleanupUnconfirmed=(self.cleanupUnconfirmed or 0)+1
                table.remove(self.pickups,index)
                return
            end
            native("NETWORK","NETWORK_REQUEST_CONTROL_OF_ENTITY",entry.object)
            entry.retries=entry.retries+1
            return
        end
        EntityManager:DeleteEntity(entry.object)
        if not native("ENTITY","DOES_ENTITY_EXIST",entry.object) then table.remove(self.pickups,index)
        else entry.retries=entry.retries+1;if entry.retries>=8 then self:ReleasePickup(entry);self.cleanupUnconfirmed=(self.cleanupUnconfirmed or 0)+1;table.remove(self.pickups,index) end end
    end
    function api:Cancel(silent)
        local job=self.job;self.job=nil
        if job and job.model then pcall(native,"STREAMING","SET_MODEL_AS_NO_LONGER_NEEDED",job.model) end
        if job and not silent then notify("Batch operation cancelled. Completed actions have been kept.") end
    end
    function api:Cleanup()
        self:Cancel(true)
        for _,entry in ipairs(self.pickups) do entry.expires=0 end
        -- Cleanup is continued in bounded steps; never spin waiting for ownership.
    end
    function api:Shutdown()
        self.stopped=true
        self:Cancel(true)
        for index=#self.pickups,1,-1 do
            local entry=self.pickups[index]
            entry.retries=8
            local ok=pcall(self.CleanupPickup,self,index)
            if not ok then self.cleanupUnconfirmed=(self.cleanupUnconfirmed or 0)+1;table.remove(self.pickups,index) end
        end
        if (self.cleanupUnconfirmed or 0)>0 then
            notify("Cleanup could not confirm removal of "..self.cleanupUnconfirmed.." supplies; they were released for game cleanup","warning")
        end
    end
    function api:CleanupTick()
        if #self.pickups==0 then return end
        local time=now()
        if time>=self.cleanupAt and #self.pickups>0 then
            self.cleanupAt=time+0.25
            self.cleanupIndex=((self.cleanupIndex or 0)%#self.pickups)+1
            local entry=self.pickups[self.cleanupIndex]
            if time>=entry.expires then
                local ok=pcall(self.CleanupPickup,self,self.cleanupIndex)
                if not ok then
                    entry.errors=(entry.errors or 0)+1
                    if entry.errors>=3 then
                        self.cleanupUnconfirmed=(self.cleanupUnconfirmed or 0)+1
                        table.remove(self.pickups,self.cleanupIndex)
                    end
                end
            end
        end
    end
    function api:Tick()
        if not self.job then return end
        if self.stopped or not authorized() then self:Cancel(true);return end
        local time=now()
        local job=self.job
        if time-job.created>120 then self:Cancel(true);notify("Batch operation timed out","warning");return end
        if time<job.nextAt then return end
        local row=job.rows[job.index]
        if not row then
            local noun=pickupDefinitions[job.key] and "Supplies created" or "Results confirmed"
            local text=labels[job.key].."："..noun.." "..job.verified.."; requests submitted "..job.submitted.."; skipped "..job.skipped.."; failed "..job.failed
            if job.submitted>0 then text=text..". Recipient confirmation is pending" end
            if pickupDefinitions[job.key] then text=text..". Nearby players can collect the supplies; cleanup follows after 60 seconds" end
            if job.lastReason then text=text.."；"..job.lastReason end
            self:Cancel(true);notify(text,job.failed>0 and "warning" or "info");return
        end
        -- One recipient/stage per tick, at most one control request or one creation.
        local ok,err=pcall(function()
            if vehicleActions[job.key] then self:VehicleStep(job,row,time)
            elseif pickupDefinitions[job.key] then self:PickupStep(job,row,time)
            else self:EventStep(job,row) end
        end)
        if not ok then self:FinishRow("failed",tostring(err)) end
    end
    function api:BindPlayer(group)
        local rows={
            {"health","Medical supply for selected teammate","Create one medical supply beside the selected teammate, who must be streamed and on foot. The player collects it."},
            {"armour","Armour supply for selected teammate","Create one armour supply beside the selected teammate, who must be streamed and on foot. The player collects it."},
            {"wanted","Request selected teammate's wanted level removal","Send a wanted level removal request only to the selected teammate using their session token. Mission scripts may restore the wanted level."},
        }
        for _,row in ipairs(rows) do
            local action=row[1]
            local item=menu.button(row[2],row[3],group,0,function()
                self:StartForPlayer(action,menu.player.get())
            end)
            if item then item.playerScoped=true end
        end
    end
    function api:Bind(group)
        for _,key in ipairs({"repair","upright","unlock","clean","health","armour","wanted","golf","darts","armwrestle"}) do
            local action=key
            local description=invitations[key] and "Request activity startup automatically, then send invitations. The recipient game determines the result."
                or pickupDefinitions[key] and "Create one networked supply near each streamed player on foot. Clean up after 60 seconds; collection is not confirmed."
                or key=="wanted" and "Send a wanted level removal request with the current player's session token. Mission scripts may restore the wanted level."
                or "Process streamed player vehicles in batches, once per vehicle. Require network control and read back the result."
            menu.button(labels[key],description,group,0,function() self:Start(action) end)
        end
        menu.button("Cancel pending support actions","Cancel actions that have not been performed yet.",group,0,function() self:Cancel(false) end)
    end
    return api
end)()
