        self.stopped=true
        self:Invalidate()
    end
    function guard:Capture()
        local pid=menu.player and type(menu.player.get)=="function" and menu.player.get() or nil
        return {pid=pid,rid=identity(pid),generation=self.generation}
    end
    function guard:Matches(snapshot)
        return not self.stopped and type(snapshot)=="table" and snapshot.rid~=nil
            and snapshot.generation==self.generation
            and menu.player and type(menu.player.get)=="function" and menu.player.get()==snapshot.pid
            and identity(snapshot.pid)==snapshot.rid
    end
    function guard:Cancel(item)
        if item and item.type=="toggle" and item.prevValue~=nil then item.value=item.prevValue end
        SovereignNotify("Teammate mission support","The selected player or identity changed. The pending action was cancelled.","warning")
        return false
    end
    menu.playerActionGuard=guard
    menu.enqueueAction=LPH_NO_VIRTUALIZE(function(label,callback,...)
        local item=guard.callbacks[callback]
        if not item then return enqueue(label,callback,...) end
        local snapshot=guard:Capture()
        local count=#menu.actionQueue
        enqueue(label,callback,...)
        if #menu.actionQueue==count+1 then
            local action=menu.actionQueue[#menu.actionQueue]
            action.playerTarget=snapshot
            action.playerTargetItem=item
        end
    end)
    menu.invokeAction=LPH_NO_VIRTUALIZE(function(action)
        if action.playerTargetItem and not guard:Matches(action.playerTarget) then
            return guard:Cancel(action.playerTargetItem)
        end
        -- Only explicitly registered actions propagate a click snapshot into
        -- jobs created by their callback. A nested unrelated action must not
        -- inherit it. Restore even when the callback raises or returns nils.
        local previous=guard.currentSnapshot
        guard.currentSnapshot=action.playerTargetItem and action.playerTarget or nil
        local result=table.pack(pcall(invoke,action))
        guard.currentSnapshot=previous
        if not result[1] then error(result[2],0) end
        return table.unpack(result,2,result.n)
    end)
end)()
-- END PLAYER ACTION TARGET GUARD 20261004

-- Stop only the newly owned work when authorization pauses; keep existing lease policy unchanged.
function menu.pausePlayerWorldFeatures()
    if menu.playerWorldPaused then return end
    menu.playerWorldPaused = true
    menu.playerActionGuard:Invalidate()
    menu.missionSupport:CancelPending()
    menu.teammateTracking:Cleanup()
    menu.worldTornado:Cleanup()
    menu.sessionSupport:Cleanup()
end

