-- Extended local controls and player utilities.
-- FILES content browser and action layer.  FILES is the game's DLC/apparel
-- catalogue; all writes stay explicit and are validated before application.
SovereignFileContent = {bound = false, busy = false, ui = {},
    catalog = {vehicles = {}, weapons = {}, tattoos = {}, outfitCount = 0}, appearance = nil,
    dlcStatus = nil}

function SovereignFileContent:Notify(text, level)
    if type(SovereignNotify) == "function" then pcall(SovereignNotify, "FILES", tostring(text), level or "info")
    elseif menu and type(menu.notify) == "function" then pcall(menu.notify, "FILES", tostring(text), 3.0, level or "info") end
end
function SovereignFileContent:Call(name, ...)
    local api = menu.nativeApis.FILES
    if not api or type(api[name]) ~= "function" then return false end
    local r = {pcall(api[name], ...)}; local ok = table.remove(r, 1); return ok, r[1]
end
function SovereignFileContent:CallApi(apiName, name, ...)
    local api = menu.nativeApis[apiName]
    if not api or type(api[name]) ~= "function" then return false end
    local r = {pcall(api[name], ...)}; local ok = table.remove(r, 1); return ok, r[1]
end
function SovereignFileContent:Alloc(size)
    if not Memory or type(Memory.Alloc) ~= "function" or type(Memory.Free) ~= "function" then return nil end
    local ok, p = pcall(Memory.Alloc, size); if not ok or not p or p == 0 then return nil end
    local zero = type(Memory.MemSet) == "function" and pcall(Memory.MemSet, p, 0, size)
    if not zero and type(Memory.WriteUByte) == "function" then zero = pcall(function()
        for i = 0, size - 1 do Memory.WriteUByte(p + i, 0) end
    end) end
    if not zero then pcall(Memory.Free, p); return nil end
    return p
end
function SovereignFileContent:Free(p) if p and p ~= 0 and Memory and Memory.Free then pcall(Memory.Free, p) end end
function SovereignFileContent:UInt(p)
    if not p or not Memory then return nil end
    local f = Memory.ReadUInt or Memory.ReadInt; if type(f) ~= "function" then return nil end
    local ok, v = pcall(f, p); return ok and type(v) == "number" and (v & 0xffffffff) or nil
end
function SovereignFileContent:HashEqual(a, b)
    if a == nil or b == nil then return false end
    return ((tonumber(a) or 0) & 0xffffffff) == ((tonumber(b) or 0) & 0xffffffff)
end
function SovereignFileContent:IsLocked(lockHash, fallbackHash)
    local hash = tonumber(lockHash) or 0
    if hash == 0 then hash = tonumber(fallbackHash) or 0 end
    if hash == 0 then return false end
    local called, locked = self:Call("IS_CONTENT_ITEM_LOCKED", hash)
    return called and locked == true
end
function SovereignFileContent:CString(p)
    if not p or not Memory or type(Memory.ReadString) ~= "function" then return nil end
    local ok, v = pcall(Memory.ReadString, p)
    if not ok or type(v) ~= "string" then return nil end
    v = v:gsub("%z.*$", ""); return v ~= "" and #v <= 64 and not v:find("[%c]") and v or nil
end
function SovereignFileContent:Yield() if Script and Script.Yield then pcall(Script.Yield, 0) end end
function SovereignFileContent:Ped()
    local p = menu.nativeApis.PLAYER
    if p and type(p.PLAYER_PED_ID) == "function" then local ok, v = pcall(p.PLAYER_PED_ID); if ok and v and v ~= 0 then return v end end
    return 0
end
function SovereignFileContent:Label(prefix, index, hash, name)
    return type(name) == "string" and name ~= "" and name or string.format("%s %03d · 0x%08X", prefix, index or 0, (hash or 0) & 0xffffffff)
end

function SovereignFileContent:RefreshTattoos(ped)
    local model = 0
    local entity = menu.nativeApis.ENTITY
    if entity and type(entity.GET_ENTITY_MODEL) == "function" then
        local modelOk, modelValue = pcall(entity.GET_ENTITY_MODEL, ped)
        if modelOk then model = tonumber(modelValue) or 0 end
    end
    local male = Utils and Utils.Joaat and Utils.Joaat("mp_m_freemode_01") or nil
    local female = Utils and Utils.Joaat and Utils.Joaat("mp_f_freemode_01") or nil
    local character = self:HashEqual(model, male) and 3 or self:HashEqual(model, female) and 4 or nil
    local ok, count = false, 0
    if character then
        ok, count = self:Call("GET_NUM_TATTOO_SHOP_DLC_ITEMS", character)
    else
        local maleOk, maleCount = self:Call("GET_NUM_TATTOO_SHOP_DLC_ITEMS", 3)
        local femaleOk, femaleCount = self:Call("GET_NUM_TATTOO_SHOP_DLC_ITEMS", 4)
        maleCount, femaleCount = tonumber(maleCount) or 0, tonumber(femaleCount) or 0
        if maleOk and maleCount >= femaleCount and maleCount > 0 then
            character, ok, count = 3, true, maleCount
        elseif femaleOk and femaleCount > 0 then
            character, ok, count = 4, true, femaleCount
        end
    end
    character = character or 3
    count = ok and math.min(2048, math.max(0, tonumber(count) or 0)) or 0
    local rows = {}
    for i = 0, count - 1 do
        local b = self:Alloc(256); local got, result = false, false
        if b then got, result = self:Call("GET_TATTOO_SHOP_DLC_ITEM_DATA", character, i, b) end
        if b and got and result == true then
            -- sTattooShopItemValues is eight-byte padded: LockHash, Index,
            -- CollectionHash, PresetHash, Cost, Facing, UpdateGroup, label.
            local lockHash, collection, overlay = self:UInt(b), self:UInt(b + 16), self:UInt(b + 24)
            local label = self:CString(b + 56)
            if collection and overlay and collection ~= 0 and overlay ~= 0 then
                rows[#rows + 1] = {lockHash = lockHash, collection = collection, overlay = overlay,
                    locked = self:IsLocked(lockHash, overlay), label = self:Label("Tattoo", i, overlay, label)}
            end
        end
        self:Free(b); if i % 16 == 0 then self:Yield() end
    end
    self.catalog.tattoos = rows
end

function SovereignFileContent:Refresh(silent)
    if self.busy then return false end; self.busy = true
    local ok, err = xpcall(function()
        local vehicles, weapons = {}, {}
        local called, count = self:Call("GET_NUM_DLC_VEHICLES"); count = called and math.min(1024, math.max(0, tonumber(count) or 0)) or 0
        for i = 0, count - 1 do
            local mok, model = self:Call("GET_DLC_VEHICLE_MODEL", i)
            local fok, flags = self:Call("GET_DLC_VEHICLE_FLAGS", i)
            local hash = mok and ((tonumber(model) or 0) & 0xffffffff) or 0
            local lockHash = 0
            local b = self:Alloc(32)
            if b then
                local dok, yes = self:Call("GET_DLC_VEHICLE_DATA", i, b)
                if dok and yes == true then
                    lockHash, hash = self:UInt(b) or 0, self:UInt(b + 8) or hash
                end
            end
            self:Free(b)
            if hash ~= 0 then
                vehicles[#vehicles + 1] = {modelHash = hash, lockHash = lockHash,
                    flags = tonumber(fok and flags or 0) or 0,
                    locked = self:IsLocked(lockHash, hash), label = self:Label("DLC vehicle", i, hash)}
            end
            if i % 16 == 0 then self:Yield() end
        end
        called, count = self:Call("GET_NUM_DLC_WEAPONS"); count = called and math.min(1024, math.max(0, tonumber(count) or 0)) or 0
        for i = 0, count - 1 do
            local b, hash, name, lockHash = self:Alloc(384), nil, nil, 0
            if b then
                local dok, yes = self:Call("GET_DLC_WEAPON_DATA", i, b)
                if dok and yes == true then
                    lockHash, hash, name = self:UInt(b) or 0, self:UInt(b + 8), self:CString(b + 56)
                end
            end
            local cok, componentCount = self:Call("GET_NUM_DLC_WEAPON_COMPONENTS", i); componentCount = cok and math.min(256, math.max(0, tonumber(componentCount) or 0)) or 0
            self:Free(b)
            if hash and hash ~= 0 then
                local components = {}
                for ci = 0, componentCount - 1 do
                    local cb = self:Alloc(192); local ch, cn
                    local componentLockHash = 0
                    if cb then
                        local cgot, yes = self:Call("GET_DLC_WEAPON_COMPONENT_DATA", i, ci, cb)
                        if cgot and yes == true then
                            componentLockHash, ch, cn = self:UInt(cb), self:UInt(cb + 24), self:CString(cb + 48)
                        end
                    end
                    self:Free(cb)
                    if ch and ch ~= 0 then
                        components[#components + 1] = {hash = ch, lockHash = componentLockHash,
                            label = self:Label("DLC component", ci, ch, cn)}
                    end
                    if ci % 16 == 0 then self:Yield() end
                end
                weapons[#weapons + 1] = {hash = hash, lockHash = lockHash,
                    locked = self:IsLocked(lockHash, hash), label = self:Label("DLC weapon", i, hash, name), components = components}
            end
            if i % 8 == 0 then self:Yield() end
        end
        local ped = self:Ped(); self.catalog.vehicles, self.catalog.weapons = vehicles, weapons
        self.catalog.outfitCount = 0
        if ped ~= 0 then
            local model = 0; local entity = menu.nativeApis.ENTITY
            if entity and type(entity.GET_ENTITY_MODEL) == "function" then
                local modelOk, modelValue = pcall(entity.GET_ENTITY_MODEL, ped)
                if modelOk then model = tonumber(modelValue) or 0 end
            end
            local male = Utils and Utils.Joaat and Utils.Joaat("mp_m_freemode_01") or -1
            local female = Utils and Utils.Joaat and Utils.Joaat("mp_f_freemode_01") or -2
            local character = model == male and 3 or model == female and 4 or 0
            local ook, outfits = self:Call("SETUP_SHOP_PED_OUTFIT_QUERY", character, false); self.catalog.outfitCount = ook and tonumber(outfits) or 0
            self:RefreshTattoos(ped)
        else self.catalog.tattoos = {} end
        self:UpdateOptions()
        self.dlcStatus = SovereignReadDlcDiagnostics()
        if self.ui.dlcStatus then
            self.ui.dlcStatus.label = "DLC status: " .. tostring(self.dlcStatus.detail or self.dlcStatus.summary or "Unknown")
        end
        self:Status(string.format("DLC %d · Weapons %d · Tattoos %d · Outfits %d", #vehicles, #weapons, #self.catalog.tattoos, self.catalog.outfitCount or 0))
    end, debug.traceback)
    self.busy = false
    if not ok then
        self:Status("Couldn't read the FILES catalogue")
        if self.ui.dlcStatus then self.ui.dlcStatus.label = "DLC status: read failed" end
        if not silent then self:Notify("Couldn't read the FILES catalogue", "warning") end
        return false, err
    end
    if not silent then self:Notify("FILES catalogue refreshed", "success") end
    return true
end
function SovereignFileContent:Status(text) if self.ui.status then self.ui.status.label = tostring(text) end end
function SovereignFileContent:Options(item, rows)
    if not item then return end; local options = {}
    for i, row in ipairs(rows or {}) do
        options[i] = tostring(row.label or "Entry") .. (row.locked and " · Unavailable" or "")
    end
    item.options = #options > 0 and options or {"No entries"}; item.value = math.max(1, math.min(item.value or 1, #item.options))
end
function SovereignFileContent:UpdateOptions()
    local u = self.ui; self:Options(u.vehicle, self.catalog.vehicles); self:Options(u.weapon, self.catalog.weapons)
    local w = self.catalog.weapons[u.weapon and u.weapon.value or 0]; self:Options(u.component, w and w.components or {}); self:Options(u.tattoo, self.catalog.tattoos)
end

function SovereignFileContent:SpawnVehicle()
    local row = self.catalog.vehicles[self.ui.vehicle.value]; local ped = self:Ped()
    if not row or ped == 0 or not EntityManager or not EntityManager.SpawnVehicle then self:Notify("The selected DLC vehicle is unavailable", "warning"); return false end
    local e = menu.nativeApis.ENTITY; local ok, pos = false, nil
    if e and type(e.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS) == "function" then
        ok, pos = pcall(e.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS, ped, 0.0, 6.0, 0.0)
    end
    if (not ok or type(pos) ~= "table") and e and type(e.GET_ENTITY_COORDS) == "function" then
        ok, pos = pcall(e.GET_ENTITY_COORDS, ped, true)
    end
    if not ok or not pos then self:Notify("Couldn't find a vehicle spawn position", "warning"); return false end
    local heading = 0.0
    if e and type(e.GET_ENTITY_HEADING) == "function" then
        local headingOk, headingValue = pcall(e.GET_ENTITY_HEADING, ped)
        if headingOk and type(headingValue) == "number" then heading = headingValue end
    end
    local spawnOk, vehicle = pcall(EntityManager.SpawnVehicle, EntityManager,
        row.modelHash, {x = pos.x, y = pos.y, z = pos.z}, heading)
    if not spawnOk then vehicle = 0 end
    if not vehicle or vehicle == 0 then self:Notify("DLC vehicle spawn failed", "warning"); return false end
    if menu.nativeApis.PED.SET_PED_INTO_VEHICLE then pcall(menu.nativeApis.PED.SET_PED_INTO_VEHICLE, ped, vehicle, -1) end
    self:Notify("DLC vehicle spawned", "success"); return true
end
function SovereignFileContent:GiveWeapon()
    local row = self.catalog.weapons[self.ui.weapon.value]; local w, ped = menu.nativeApis.WEAPON, self:Ped()
    if not row or not w or ped == 0 or not w.GIVE_WEAPON_TO_PED then self:Notify("The selected DLC weapon is unavailable", "warning"); return false end
    local ok, accepted = pcall(w.GIVE_WEAPON_TO_PED, ped, row.hash, 9999, false, true)
    local success = ok and accepted ~= false
    self:Notify(success and "DLC weapon given" or "DLC weapon give failed", success and "success" or "warning"); return success
end
function SovereignFileContent:GiveAllWeapons()
    local w, ped = menu.nativeApis.WEAPON, self:Ped(); if not w or ped == 0 or not w.GIVE_WEAPON_TO_PED then return false end
    local count = 0
    for _, row in ipairs(self.catalog.weapons) do
        local ok, accepted = pcall(w.GIVE_WEAPON_TO_PED, ped, row.hash, 9999, false, false)
        if ok and accepted ~= false then count = count + 1 end
        if count % 8 == 0 then self:Yield() end
    end
    self:Notify(string.format("Gave %d DLC weapons", count), "success"); return true
end
function SovereignFileContent:GiveComponent()
    local wrow = self.catalog.weapons[self.ui.weapon.value]; local crow = wrow and wrow.components[self.ui.component.value]; local w, ped = menu.nativeApis.WEAPON, self:Ped()
    if not wrow or not crow or not w or ped == 0 or not w.GIVE_WEAPON_COMPONENT_TO_PED then self:Notify("The selected DLC component is unavailable", "warning"); return false end
    local ok, accepted = pcall(w.GIVE_WEAPON_COMPONENT_TO_PED, ped, wrow.hash, crow.hash)
    local success = ok and accepted ~= false
    self:Notify(success and "DLC component installed" or "DLC component installation failed", success and "success" or "warning"); return success
end

function SovereignFileContent:CaptureAppearance()
    local ped, p, e = self:Ped(), menu.nativeApis.PED, menu.nativeApis.ENTITY; if ped == 0 or not p then return nil end
    local model = e and e.GET_ENTITY_MODEL and e.GET_ENTITY_MODEL(ped) or 0; local s = {model = model, components = {}, props = {}}
    for slot = 0, 11 do
        local d = p.GET_PED_DRAWABLE_VARIATION and p.GET_PED_DRAWABLE_VARIATION(ped, slot) or -1
        local t = p.GET_PED_TEXTURE_VARIATION and p.GET_PED_TEXTURE_VARIATION(ped, slot) or 0
        local pal = p.GET_PED_PALETTE_VARIATION and p.GET_PED_PALETTE_VARIATION(ped, slot) or 0
        local _, hash = self:Call("GET_HASH_NAME_FOR_COMPONENT", ped, slot, d, t); s.components[#s.components + 1] = {slot = slot, drawable = d, texture = t, palette = pal, hash = hash or 0}
    end
    for slot = 0, 7 do
        local d = p.GET_PED_PROP_INDEX and p.GET_PED_PROP_INDEX(ped, slot) or -1; local t = p.GET_PED_PROP_TEXTURE_INDEX and p.GET_PED_PROP_TEXTURE_INDEX(ped, slot) or 0
        local hash = 0
        if d >= 0 then
            local hashOk, hashValue = self:Call("GET_HASH_NAME_FOR_PROP", ped, slot, d, t)
            if hashOk then hash = tonumber(hashValue) or 0 end
        end
        s.props[#s.props + 1] = {slot = slot, drawable = d, texture = t, hash = hash}
    end
    self.appearance = s; self:Status(string.format("Appearance · %d components · %d props", #s.components, #s.props)); return s
end
function SovereignFileContent:Path()
    if not FileMgr or type(FileMgr.GetMenuRootPath) ~= "function" then return nil end
    local ok, root = pcall(FileMgr.GetMenuRootPath)
    return ok and type(root) == "string" and root ~= "" and (root .. "/Sovereign_files_appearance.cfg") or nil
end
function SovereignFileContent:Encode(s)
    local lines = {"SOVEREIGN_APPEARANCE_V1", "model=" .. tostring(s.model or 0)}
    for _, r in ipairs(s.components) do lines[#lines + 1] = string.format("C|%d|%d|%d|%d", r.slot, r.drawable, r.texture, r.palette) end
    for _, r in ipairs(s.props) do lines[#lines + 1] = string.format("P|%d|%d|%d", r.slot, r.drawable, r.texture) end
    return table.concat(lines, "\n") .. "\n"
end
function SovereignFileContent:Decode(body)
    if type(body) ~= "string" or #body > 65536 or not body:match("^SOVEREIGN_APPEARANCE_V1\n") then return nil end
    local s = {model = 0, components = {}, props = {}, seenC = {}, seenP = {}}
    for line in body:gmatch("[^\r\n]+") do
        s.model = tonumber(line:match("^model=(%d+)$")) or s.model
        local a,b,c,d = line:match("^C|(%d+)|(%d+)|(%d+)|(%d+)$")
        if a and not s.seenC[tonumber(a)] and tonumber(a) <= 11 and tonumber(b) <= 128 and tonumber(c) <= 64 and tonumber(d) <= 3 then s.seenC[tonumber(a)] = true; s.components[#s.components + 1] = {slot=tonumber(a),drawable=tonumber(b),texture=tonumber(c),palette=tonumber(d)} end
        local pa,pb,pc = line:match("^P|(%d+)|(-?%d+)|(%d+)$")
        if pa and not s.seenP[tonumber(pa)] and tonumber(pa) <= 7 and tonumber(pb) >= -1 and tonumber(pb) <= 128 and tonumber(pc) <= 64 then s.seenP[tonumber(pa)] = true; s.props[#s.props + 1] = {slot=tonumber(pa),drawable=tonumber(pb),texture=tonumber(pc)} end
    end
    s.seenC, s.seenP = nil, nil; return #s.components > 0 and s or nil
end
function SovereignFileContent:SaveAppearance()
    local s, path = self:CaptureAppearance(), self:Path(); if not s or not path or not menu.writeUiSettingsVerified then self:Notify("Appearance snapshot save failed", "warning"); return false end
    local body = self:Encode(s); if not self:Decode(body) then self:Notify("Appearance snapshot validation failed", "warning"); return false end
    local previousOk, previous = false, nil
    if FileMgr and type(FileMgr.ReadFileContent) == "function" then previousOk, previous = pcall(FileMgr.ReadFileContent, path) end
    if not menu.writeUiSettingsVerified(path .. ".pending", body) then self:Notify("Appearance snapshot staging failed", "warning"); return false end
    if not menu.writeUiSettingsVerified(path, body) then
        if previousOk and type(previous) == "string" then pcall(menu.writeUiSettingsVerified, path, previous) elseif FileMgr and type(FileMgr.DeleteFile) == "function" then pcall(FileMgr.DeleteFile, path) end
        if FileMgr and type(FileMgr.DeleteFile) == "function" then pcall(FileMgr.DeleteFile, path .. ".pending") end
        self:Notify("Appearance snapshot write failed; rolled back", "warning"); return false
    end
    if FileMgr.DeleteFile then pcall(FileMgr.DeleteFile, path .. ".pending") end; self:Notify("Appearance snapshot saved", "success"); return true
end
function SovereignFileContent:ApplyAppearance(s)
    s = s or self.appearance; local ped, p = self:Ped(), menu.nativeApis.PED; if not s or ped == 0 or not p then return false end
    local changed, skipped = 0, 0
    for _, r in ipairs(s.components) do
        local ok, count = self:CallApi("PED", "GET_NUMBER_OF_PED_DRAWABLE_VARIATIONS", ped, r.slot)
        if ok and type(count) == "number" and r.drawable >= 0 and r.drawable < count and p.SET_PED_COMPONENT_VARIATION then
            local texture = math.max(0, tonumber(r.texture) or 0)
            local textureOk, textureCount = self:CallApi("PED", "GET_NUMBER_OF_PED_TEXTURE_VARIATIONS", ped, r.slot, r.drawable)
            if textureOk and type(textureCount) == "number" and texture >= textureCount then texture = 0 end
            local callOk, result = pcall(p.SET_PED_COMPONENT_VARIATION, ped, r.slot, r.drawable, texture, r.palette or 0)
            if callOk and result ~= false then changed = changed + 1 else skipped = skipped + 1 end
        else skipped = skipped + 1 end
    end
    for _, r in ipairs(s.props) do
        if r.drawable < 0 and p.CLEAR_PED_PROP then
            local callOk, result = pcall(p.CLEAR_PED_PROP, ped, r.slot)
            if callOk and result ~= false then changed = changed + 1 else skipped = skipped + 1 end
        elseif r.drawable >= 0 and p.SET_PED_PROP_INDEX then
            local ok, count = self:CallApi("PED", "GET_NUMBER_OF_PED_PROP_DRAWABLE_VARIATIONS", ped, r.slot)
            if ok and type(count) == "number" and r.drawable < count then
                local texture = math.max(0, tonumber(r.texture) or 0)
                local textureOk, textureCount = self:CallApi("PED", "GET_NUMBER_OF_PED_PROP_TEXTURE_VARIATIONS", ped, r.slot, r.drawable)
