                local callOk, result = pcall(p.SET_PED_PROP_INDEX, ped, r.slot, r.drawable, texture, true)
                if callOk and result ~= false then changed = changed + 1 else skipped = skipped + 1 end
            else skipped = skipped + 1 end
        else skipped = skipped + 1 end
    end
    self:CaptureAppearance(); self:Notify(string.format("Applied %d appearance items%s", changed, skipped > 0 and string.format("; skipped %d unavailable items", skipped) or ""), skipped > 0 and "warning" or "success"); return changed > 0
end
