function SovereignFileContent:ApplyComponentFromUi()
    local u, p, api = self.ui, self:Ped(), menu.nativeApis.PED
    local slot = math.floor(tonumber(u.componentSlot and u.componentSlot.value or 1) or 1) - 1
    local drawable = math.floor(tonumber(u.componentDrawable and u.componentDrawable.value or 0) or 0)
    local texture = math.floor(tonumber(u.componentTexture and u.componentTexture.value or 0) or 0)
    local palette = math.floor(tonumber(u.componentPalette and u.componentPalette.value or 0) or 0)
    if p == 0 or not api or type(api.SET_PED_COMPONENT_VARIATION) ~= "function" then self:Notify("Component interface unavailable", "warning"); return false end
    local countOk, drawableCount = self:CallApi("PED", "GET_NUMBER_OF_PED_DRAWABLE_VARIATIONS", p, slot)
    if not countOk or type(drawableCount) ~= "number" or drawable < 0 or drawable >= drawableCount then self:Notify("Current component index is unavailable", "warning"); return false end
    local textureOk, textureCount = self:CallApi("PED", "GET_NUMBER_OF_PED_TEXTURE_VARIATIONS", p, slot, drawable)
    if textureOk and type(textureCount) == "number" and texture >= textureCount then texture = 0 end
    local callOk, result = pcall(api.SET_PED_COMPONENT_VARIATION, p, slot, drawable, texture, palette)
    local ok = callOk and result ~= false
    if ok then self:CaptureAppearance(); self:Notify("Component applied", "success") else self:Notify("Component application failed", "warning") end
    return ok
end
function SovereignFileContent:ApplyPropFromUi(clear)
    local u, p, api = self.ui, self:Ped(), menu.nativeApis.PED
    local slot = math.floor(tonumber(u.propSlot and u.propSlot.value or 1) or 1) - 1
    if p == 0 or not api then self:Notify("Prop interface unavailable", "warning"); return false end
    if clear then
        if type(api.CLEAR_PED_PROP) ~= "function" then return false end
        local callOk, result = pcall(api.CLEAR_PED_PROP, p, slot); local ok = callOk and result ~= false
        if ok then self:CaptureAppearance(); self:Notify("Prop cleared", "success") else self:Notify("Prop clear failed", "warning") end; return ok
    end
    local drawable = math.floor(tonumber(u.propDrawable and u.propDrawable.value or 0) or 0)
    local texture = math.floor(tonumber(u.propTexture and u.propTexture.value or 0) or 0)
    local countOk, drawableCount = self:CallApi("PED", "GET_NUMBER_OF_PED_PROP_DRAWABLE_VARIATIONS", p, slot)
    if not countOk or type(drawableCount) ~= "number" or drawable < 0 or drawable >= drawableCount or type(api.SET_PED_PROP_INDEX) ~= "function" then self:Notify("Current prop index is unavailable", "warning"); return false end
    local textureOk, textureCount = self:CallApi("PED", "GET_NUMBER_OF_PED_PROP_TEXTURE_VARIATIONS", p, slot, drawable)
    if textureOk and type(textureCount) == "number" and texture >= textureCount then texture = 0 end
    local callOk, result = pcall(api.SET_PED_PROP_INDEX, p, slot, drawable, texture, true)
    local ok = callOk and result ~= false
    if ok then self:CaptureAppearance(); self:Notify("Prop applied", "success") else self:Notify("Prop application failed", "warning") end
    return ok
end
