    u.propSlot = menu.combo("Prop slot", "", a, {"0","1","2","3","4","5","6","7"}, 1, 0, function() end); u.propDrawable = menu.slider("Prop drawable", "", a, 0, 128, 0, "%d", 0, function() end); u.propTexture = menu.slider("Prop texture", "", a, 0, 64, 0, "%d", 0, function() end)
