SovereignGameplayOptions = {
    bound = false,
    entityForce = 100.0,
    includePlayerVehicles = false,
    grabber = {enabled = false, entity = 0, attached = false, nextAction = 0.0, lastNotice = 0.0},
    weapon = {
        projectileSpeed = 500.0,
        fireDelay = 100.0,
        selectedHash = Utils.Joaat("weapon_pistol"),
        infiniteAmmo = false,
        noReload = false,
        autoLoadout = false,
        loadout = nil,
        sessionToken = nil,
        affectedPed = 0,
        affectedWeapon = 0,
        infiniteApplied = false,
        clipApplied = false,
        lastTick = 0.0,
    },
    handling = {
        enabled = false,
        burnout = false,
        enginePower = 1.0,
        brakeForce = 1.0,
        gripMin = 1.0,
        gripMax = 1.0,
        lowSpeedGrip = 1.0,
        rollCentreRear = nil,
        steeringBias = 0.0,
        steeringTouchiness = nil,
        clumsiness = nil,
        wheelie = nil,
        blinkers = false,
        vehicle = 0,
        hostBaseline = {},
        lastApply = 0.0,
    },
    aim = {
        allowPlayers = true,
        allowNpc = true,
        allowVehicle = true,
        whileDriving = false,
    },
}

function SovereignGameplayOptions:Now()
    local misc = menu and menu.nativeApis and menu.nativeApis.MISC
    if misc and type(misc.GET_GAME_TIMER) == "function" then
        local ok, value = pcall(misc.GET_GAME_TIMER)
        if ok and type(value) == "number" then return value / 1000.0 end
    end
    return os.clock()
end

function SovereignGameplayOptions:Notify(body, level)
    if SovereignNotify then
        pcall(SovereignNotify, "Extended controls", menu.translate(body or ""), level or "info")
    elseif Logger and Logger.Info then
        pcall(Logger.Info, Logger, "Extended controls", body or "")
    end
end

SovereignGameplayOptions.Local = LPH_NO_VIRTUALIZE(function(self)
    local p = menu and menu.nativeApis and menu.nativeApis.PLAYER
    if not p then return 0, -1 end
    local ped = type(p.PLAYER_PED_ID) == "function" and p.PLAYER_PED_ID() or 0
    local pid = type(p.PLAYER_ID) == "function" and p.PLAYER_ID() or -1
    return ped or 0, pid or -1
end)

function SovereignGameplayOptions:Vehicle(ped)
    local p = menu and menu.nativeApis and menu.nativeApis.PED
    if not p then return 0 end
    local ok, vehicle
    if type(p.GET_VEHICLE_PED_IS_IN) == "function" then
        ok, vehicle = pcall(p.GET_VEHICLE_PED_IS_IN, ped, false)
        if ok and vehicle and vehicle ~= 0 then return vehicle end
    end
    if type(p.GET_VEHICLE_PED_IS_USING) == "function" then
        ok, vehicle = pcall(p.GET_VEHICLE_PED_IS_USING, ped)
        if ok and vehicle and vehicle ~= 0 then return vehicle end
    end
    return 0
end

function SovereignGameplayOptions:RequestControl(entity)
    if not entity or entity == 0 then return false end
    if PlayerTrollOptions and type(PlayerTrollOptions.RequestControl) == "function" then
        local ok, result = pcall(PlayerTrollOptions.RequestControl, PlayerTrollOptions, entity)
        if ok then return result ~= false end
    end
    local network = menu.nativeApis.NETWORK
    if network and type(network.NETWORK_HAS_CONTROL_OF_ENTITY) == "function" then
        local ok, owned = pcall(network.NETWORK_HAS_CONTROL_OF_ENTITY, entity)
        if ok and owned then return true end
        if type(network.NETWORK_REQUEST_CONTROL_OF_ENTITY) == "function" then
            pcall(network.NETWORK_REQUEST_CONTROL_OF_ENTITY, entity)
        end
        ok, owned = pcall(network.NETWORK_HAS_CONTROL_OF_ENTITY, entity)
        return ok and owned == true
    end
    return true
end

function SovereignGameplayOptions:AimedEntity(pid)
    if SovereignAimAssist and type(SovereignAimAssist.NativeTarget) == "function" then
        local ped = self:Local()
        local ok, entity = pcall(SovereignAimAssist.NativeTarget, SovereignAimAssist, pid, ped, false)
        if ok and entity then return entity end
    end
    return 0
end

function SovereignGameplayOptions:IsPlayerVehicle(vehicle)
    local p, v = menu.nativeApis.PED, menu.nativeApis.VEHICLE
    if not p or not v or type(v.GET_PED_IN_VEHICLE_SEAT) ~= "function" then return false end
    local maxPassengers = 0
    if type(v.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS) == "function" then
        local ok, value = pcall(v.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS, vehicle)
        if ok then maxPassengers = math.max(0, tonumber(value) or 0) end
    end
    for seat = -1, maxPassengers - 1 do
        local ok, ped = pcall(v.GET_PED_IN_VEHICLE_SEAT, vehicle, seat, false)
        if ok and ped and ped ~= 0 and type(p.IS_PED_A_PLAYER) == "function" then
            local playerOk, isPlayer = pcall(p.IS_PED_A_PLAYER, ped)
            if playerOk and isPlayer then return true end
        end
    end
    return false
end

function SovereignGameplayOptions:HostHandlingFeature(name)
    local h = self.handling
    h.hostFeatures = h.hostFeatures or {}
    if h.hostFeatures[name] ~= nil then return h.hostFeatures[name] or nil end
    local getter = SovereignRuntime and SovereignRuntime.originalFeatureMgr
        and SovereignRuntime.originalFeatureMgr.GetFeature
    if type(getter) ~= "function" then getter = FeatureMgr and FeatureMgr.GetFeature end
    if type(getter) ~= "function" then return nil end
    local ok, feature = pcall(getter, Utils.Joaat(name))
    if not ok or (type(feature) ~= "table" and type(feature) ~= "userdata")
        or (type(feature) == "table" and feature._sovereignNoop == true) then
        h.hostFeatures[name] = false
        return nil
    end
    h.hostFeatures[name] = feature
    return feature
end

function SovereignGameplayOptions:GetHostHandling(name)
    local feature = self:HostHandlingFeature(name)
    if not feature then return nil end
    local ok, value = pcall(function() return feature:GetFloatValue() end)
    if ok and type(value) == "number" and value == value and math.abs(value) < math.huge then return value end
end

function SovereignGameplayOptions:SetHostHandling(name, value)
    local h, feature = self.handling, self:HostHandlingFeature(name)
    if not feature or type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then return false end
    -- Never change a host parameter without a readable value to restore.
    if h.hostBaseline[name] == nil then h.hostBaseline[name] = self:GetHostHandling(name) end
    if h.hostBaseline[name] == nil then return false end
    h.hostApplied = h.hostApplied or {}
    if h.hostApplied[name] == value then return true end
    h.hostApplied[name] = nil
    local ok, accepted = pcall(function()
        local result = feature:SetFloatValue(value)
        if result == false then return false end
        return feature:TriggerCallback() ~= false
    end)
    if not ok or accepted ~= true then return false end
    h.hostApplied[name] = value
    return true
end

function SovereignGameplayOptions:GrabTarget(ped, pid)
    local e, v = menu.nativeApis.ENTITY, menu.nativeApis.VEHICLE
    if not e or not v or type(e.DOES_ENTITY_EXIST) ~= "function" then return 0 end
    local target = self:AimedEntity(pid)
    if target == 0 or not e.DOES_ENTITY_EXIST(target) or not e.IS_ENTITY_A_VEHICLE
        or not e.IS_ENTITY_A_VEHICLE(target) then
        if type(e.GET_ENTITY_COORDS) ~= "function" or type(v.GET_CLOSEST_VEHICLE) ~= "function" then return 0 end
        local ok, pos = pcall(e.GET_ENTITY_COORDS, ped, true)
        if not ok or not pos then return 0 end
        ok, target = pcall(v.GET_CLOSEST_VEHICLE, pos.x, pos.y, pos.z, 6.0, 0, 71)
        if not ok then target = 0 end
    end
    if not target or target == 0 or not e.DOES_ENTITY_EXIST(target) then return 0 end
    if not self.includePlayerVehicles and self:IsPlayerVehicle(target) then return 0 end
    return target
end

function SovereignGameplayOptions:AttachGrabbed(entity, ped)
    local e = menu.nativeApis.ENTITY
    if not e or type(e.ATTACH_ENTITY_TO_ENTITY) ~= "function" or not self:RequestControl(entity) then return false end
    local ok, result = pcall(e.ATTACH_ENTITY_TO_ENTITY, entity, ped, 0, 0.0, 0.0, 1.4,
        0.0, 0.0, -90.0, true, false, false, false, 0, true, false)
    if ok and result ~= false then
        self.grabber.entity, self.grabber.attached = entity, true
        return true
    end
    return false
end

function SovereignGameplayOptions:ReleaseGrabbed(ped, throwIt)
    local g, e = self.grabber, menu.nativeApis.ENTITY
    local entity = g.entity
    if not entity or entity == 0 then
        g.entity, g.attached = 0, false
        return false
    end
    if e and type(e.DOES_ENTITY_EXIST) == "function" and e.DOES_ENTITY_EXIST(entity) then
        if type(e.DETACH_ENTITY) == "function" then pcall(e.DETACH_ENTITY, entity, true, true) end
        if throwIt then
            local cam = menu.nativeApis.CAM
            local force = self.entityForce
            local rot = cam and type(cam.GET_GAMEPLAY_CAM_ROT) == "function" and cam.GET_GAMEPLAY_CAM_ROT(2) or {x = 0.0, z = 0.0}
            local rz, rx = math.rad(rot.z or 0.0), math.rad(rot.x or 0.0)
            local dx, dy, dz = -math.sin(rz) * math.cos(rx), math.cos(rz) * math.cos(rx), math.sin(rx)
            if type(e.APPLY_FORCE_TO_ENTITY) == "function" then
                pcall(e.APPLY_FORCE_TO_ENTITY, entity, 3, dx * force, dy * force, dz * force,
                    0.0, 0.0, 0.0, 0, false, false, true, false, true)
            elseif type(e.SET_ENTITY_VELOCITY) == "function" then
                pcall(e.SET_ENTITY_VELOCITY, entity, dx * force, dy * force, dz * force)
            end
        end
    end
    g.entity, g.attached = 0, false
    if throwIt and menu.nativeApis.TASK and type(menu.nativeApis.TASK.CLEAR_PED_TASKS) == "function" then
        pcall(menu.nativeApis.TASK.CLEAR_PED_TASKS, ped)
    end
    return true
end

SovereignGameplayOptions.ProcessGrabber = LPH_NO_VIRTUALIZE(function(self)
    local g = self.grabber
    if not g.enabled then return end
    local ped, pid = self:Local()
    if ped == 0 then return end
    if g.attached then
        local e = menu.nativeApis.ENTITY
        if not e or type(e.DOES_ENTITY_EXIST) ~= "function" or not e.DOES_ENTITY_EXIST(g.entity) then
            self:ReleaseGrabbed(ped, false)
            return
        end
    end
    local pad = menu.nativeApis.PAD
    if not pad or type(pad.IS_CONTROL_JUST_PRESSED) ~= "function"
        or not pad.IS_CONTROL_JUST_PRESSED(0, 38) then return end
    local now = self:Now()
    if now < (g.nextAction or 0.0) then return end
    g.nextAction = now + 0.25
    if g.attached then
        self:ReleaseGrabbed(ped, true)
        self:Notify("Entity released", "info")
        return
    end
    local entity = self:GrabTarget(ped, pid)
    if entity ~= 0 and self:AttachGrabbed(entity, ped) then
        self:Notify("Entity grabbed", "success")
    elseif now - (g.lastNotice or 0.0) > 1.0 then
        g.lastNotice = now
        self:Notify("No nearby entity available", "warning")
    end
end)

function SovereignGameplayOptions:RestoreAmmoFlags()
    local w = self.weapon
    local weapon = menu.nativeApis.WEAPON
    if w.affectedPed and w.affectedPed ~= 0 and w.affectedWeapon and w.affectedWeapon ~= 0 and weapon then
        if w.infiniteApplied and type(weapon.SET_PED_INFINITE_AMMO) == "function" then
            pcall(weapon.SET_PED_INFINITE_AMMO, w.affectedPed, false, w.affectedWeapon)
        end
        if w.clipApplied and type(weapon.SET_PED_INFINITE_AMMO_CLIP) == "function" then
            pcall(weapon.SET_PED_INFINITE_AMMO_CLIP, w.affectedPed, false)
        end
    end
    w.infiniteApplied, w.clipApplied = false, false
    w.affectedPed, w.affectedWeapon = 0, 0
end

SovereignGameplayOptions.ProcessWeapon = LPH_NO_VIRTUALIZE(function(self)
    local w, weapon = self.weapon, menu.nativeApis.WEAPON
    if not w.infiniteAmmo and not w.noReload and not w.autoLoadout then
        if w.infiniteApplied or w.clipApplied then self:RestoreAmmoFlags() end
        w.sessionToken = nil
        return
    end
    local now = self:Now()
    if w.lastTick and now >= w.lastTick and now - w.lastTick < 0.20 then return end
    w.lastTick = now
    local ped = self:Local()
    if ped == 0 or not weapon or type(weapon.GET_SELECTED_PED_WEAPON) ~= "function" then
        if w.infiniteApplied or w.clipApplied then self:RestoreAmmoFlags() end
        return
    end
    local selected = weapon.GET_SELECTED_PED_WEAPON(ped) or 0
    if selected == 0 then return end
    if w.affectedPed ~= ped or w.affectedWeapon ~= selected then self:RestoreAmmoFlags() end
    w.affectedPed, w.affectedWeapon = ped, selected
    if w.infiniteAmmo and type(weapon.SET_PED_INFINITE_AMMO) == "function" then
        pcall(weapon.SET_PED_INFINITE_AMMO, ped, true, selected)
        w.infiniteApplied = true
    elseif w.infiniteApplied and type(weapon.SET_PED_INFINITE_AMMO) == "function" then
        pcall(weapon.SET_PED_INFINITE_AMMO, ped, false, selected)
        w.infiniteApplied = false
    end
    if w.noReload and type(weapon.SET_PED_INFINITE_AMMO_CLIP) == "function" then
        pcall(weapon.SET_PED_INFINITE_AMMO_CLIP, ped, true)
        w.clipApplied = true
    elseif w.clipApplied and type(weapon.SET_PED_INFINITE_AMMO_CLIP) == "function" then
        pcall(weapon.SET_PED_INFINITE_AMMO_CLIP, ped, false)
        w.clipApplied = false
    end
    if w.autoLoadout then
        local network = menu.nativeApis.NETWORK
        local active = network and type(network.NETWORK_IS_SESSION_ACTIVE) == "function"
            and network.NETWORK_IS_SESSION_ACTIVE() == true or false
        local token = tostring(active) .. ":" .. tostring(ped)
        if token ~= w.sessionToken and not w.job then
            if not active or self:RunWeaponJob(function(owner) owner:ApplyLoadout(true) end) then w.sessionToken = token end
        end
    else
        w.sessionToken = nil
    end
end)

