    {"COMPONENT_MICROSMG_VARMOD_SECURITY", "Organics Finish", "Organics Finish"},
    {"COMPONENT_MICROSMG_VARMOD_FRN", "Employee Of The Month Finish", "Employee Of The Month Finish"},
    {"COMPONENT_MICROSMG_VARMOD_XM3", "Season's Greeting", "Season's Greeting"},
    {"COMPONENT_RPG_VARMOD_TVR", "Love Fist", "Love Fist"},
    {"COMPONENT_GRENADELAUNCHER_CLIP_01", "Default Clip", "Default Clip"},
}

-- Local inventory configuration. Catalogues are queried on demand, never per frame.
function SovereignGameplayOptions:WeaponNative(name, ...)
    local api = menu.nativeApis.WEAPON
    if not api or type(api[name]) ~= "function" then return false, nil end
    return pcall(api[name], ...)
end

function SovereignGameplayOptions:WeaponWrite(name, ...)
    local ok, value = self:WeaponNative(name, ...)
    return ok and value ~= false
end

function SovereignGameplayOptions:WeaponCheckpoint()
    local job = self.weapon.job
    if not job then return end
    if (AuthManager and type(AuthManager.SessionValid) == "function" and not AuthManager:SessionValid())
        or (type(ShouldUnload) == "function" and ShouldUnload()) then job.cancelled = true end
    if job.cancelled or self:Local() ~= job.ped then error("loadout_cancelled", 0) end
    job.work = job.work + 1
    if job.work >= 32 and Script and type(Script.Yield) == "function" then
        job.work = 0
        Script.Yield()
        if job.cancelled or self:Local() ~= job.ped then error("loadout_cancelled", 0) end
    end
end

function SovereignGameplayOptions:RunWeaponJob(fn)
    if self.weapon.job then self:Notify("Weapon operation in progress", "info"); return false end
    local ped = self:Local()
    if ped == 0 then return false end
    local job = {ped = ped, work = 0}
    self.weapon.job = job
    local function run()
        local ok = pcall(function() self:WeaponCheckpoint(); fn(self) end)
        if self.weapon.job == job then self.weapon.job = nil end
        if not ok and not job.cancelled then self:Notify("Action could not be completed", "warning") end
    end
    if Script and type(Script.QueueJob) == "function" then
        local ok, accepted = pcall(Script.QueueJob, run)
        if not ok or accepted == false then self.weapon.job = nil; self:Notify("Action could not be completed", "warning"); return false end
    else
        run()
    end
    return true
end

function SovereignGameplayOptions:AvailableWeapons(category)
    local rows = {}
    for _, item in ipairs(self.weaponCatalog) do
        item.hash = item.hash or Utils.Joaat(item[1])
        if not category or category == "All" or item[4] == category then
            local ok, valid = self:WeaponNative("IS_WEAPON_VALID", item.hash)
            if ok and valid == true then rows[#rows + 1] = item end
        end
        self:WeaponCheckpoint()
    end
    return rows
end

function SovereignGameplayOptions:CompatibleComponents(hash)
    self.weapon.componentCache = self.weapon.componentCache or {}
    local cached = self.weapon.componentCache[hash]
    if cached then return cached end
    local rows = {}
    for _, item in ipairs(self.componentCatalog) do
        item.hash = item.hash or Utils.Joaat(item[1])
        local ok, takes = self:WeaponNative("DOES_WEAPON_TAKE_WEAPON_COMPONENT", hash, item.hash)
        if not ok then error("component_query_failed", 0) end
        if takes == true then rows[#rows + 1] = item end
        self:WeaponCheckpoint()
    end
    self.weapon.componentCache[hash] = rows
    return rows
end

function SovereignGameplayOptions:LoadoutPath()
    if not FileMgr or type(FileMgr.GetMenuRootPath) ~= "function" then return nil end
    local ok, root = pcall(FileMgr.GetMenuRootPath)
    return ok and type(root) == "string" and root .. "/Sovereign_loadout.cfg" or nil
end

function SovereignGameplayOptions:EncodeLoadout(snapshot)
    local lines = {"SOVEREIGN_LOADOUT_V1", "selected=" .. tostring(snapshot.selected or 0)}
    local hashes = {}
    for hash in pairs(snapshot.weapons) do hashes[#hashes + 1] = hash end
    table.sort(hashes)
    for _, hash in ipairs(hashes) do
        local row = snapshot.weapons[hash]
        lines[#lines + 1] = string.format("W|%d|%d|%d", hash, row.ammo, row.tint)
        for _, component in ipairs(row.components) do
            lines[#lines + 1] = string.format("C|%d|%d|%d", hash, component.hash, component.tint)
        end
    end
    return table.concat(lines, "\n") .. "\n"
end

function SovereignGameplayOptions:DecodeLoadout(body)
    if type(body) ~= "string" or #body > 262144 then return nil end
    body = body:gsub("\r\n", "\n")
    if not body:match("^SOVEREIGN_LOADOUT_V1\nselected=") then return nil end
    local snapshot, count, seen = {weapons = {}}, 0, {}
    for line in body:gmatch("[^\n]+") do
        if count == 0 then
            if line ~= "SOVEREIGN_LOADOUT_V1" then return nil end
        elseif count == 1 then
            local selected = tonumber(line:match("^selected=(%d+)$"))
            if not selected or selected > 0xffffffff then return nil end
            snapshot.selected = selected
        else
            local kind, hash, first, second = line:match("^([WC])|(%d+)|(%d+)|(-?%d+)$")
            hash, first, second = tonumber(hash), tonumber(first), tonumber(second)
            if not kind or not hash or hash == 0 or hash > 0xffffffff or not first or not second then return nil end
            if kind == "W" then
                if snapshot.weapons[hash] or first > 100000 or second < 0 or second > 255 then return nil end
                snapshot.weapons[hash] = {ammo = first, tint = second, components = {}}
                seen[hash] = {}
            else
                local row = snapshot.weapons[hash]
                if not row or first == 0 or first > 0xffffffff or second < -1 or second > 31 or seen[hash][first] then return nil end
                seen[hash][first] = true
                row.components[#row.components + 1] = {hash = first, tint = second}
            end
        end
        count = count + 1
        if count > 4096 then return nil end
    end
    return count >= 2 and snapshot or nil
end

function SovereignGameplayOptions:ReadLoadout(silent)
    local path = self:LoadoutPath()
    if not path or not FileMgr or type(FileMgr.ReadFileContent) ~= "function" then return nil end
    local ok, body = pcall(FileMgr.ReadFileContent, path)
    local snapshot = ok and self:DecodeLoadout(body) or nil
    if not snapshot and not silent then self:Notify("No saved weapon configuration available", "warning") end
    return snapshot
end

function SovereignGameplayOptions:SaveLoadout()
    local ped = self:Local()
    local snapshot = {weapons = {}}
    local selectedOk, selected = self:WeaponNative("GET_SELECTED_PED_WEAPON", ped)
    if not selectedOk then return false end
    snapshot.selected = (tonumber(selected) or 0) & 0xffffffff
    for _, item in ipairs(self:AvailableWeapons()) do
        local ok, owned = self:WeaponNative("HAS_PED_GOT_WEAPON", ped, item.hash, false)
        if not ok then error("inventory_query_failed", 0) end
        if owned then
            local ammoOk, ammo = self:WeaponNative("GET_AMMO_IN_PED_WEAPON", ped, item.hash)
            local tintOk, tint = self:WeaponNative("GET_PED_WEAPON_TINT_INDEX", ped, item.hash)
            if not ammoOk or not tintOk then error("inventory_query_failed", 0) end
            local row = {ammo = math.floor(math.max(0, math.min(100000, tonumber(ammo) or 0))),
                tint = math.floor(math.max(0, tonumber(tint) or 0)), components = {}}
            for _, component in ipairs(self:CompatibleComponents(item.hash)) do
                local hasOk, has = self:WeaponNative("HAS_PED_GOT_WEAPON_COMPONENT", ped, item.hash, component.hash)
                if not hasOk then error("component_query_failed", 0) end
                if has then
                    local color = -1
                    if component[1]:find("CAMO", 1, true) then
                        local colorOk, value = self:WeaponNative("GET_PED_WEAPON_COMPONENT_TINT_INDEX", ped, item.hash, component.hash)
                        if not colorOk then error("component_query_failed", 0) end
                        color = math.max(-1, math.min(31, math.floor(tonumber(value) or -1)))
                    end
                    row.components[#row.components + 1] = {hash = component.hash & 0xffffffff, tint = color}
                end
                self:WeaponCheckpoint()
            end
            snapshot.weapons[item.hash & 0xffffffff] = row
        end
        self:WeaponCheckpoint()
    end
    local path, body = self:LoadoutPath(), self:EncodeLoadout(snapshot)
    if not path or not self:DecodeLoadout(body) or type(menu.writeUiSettingsVerified) ~= "function" then
        self:Notify("Could not save weapon configuration", "warning"); return false
    end
    if not menu.writeUiSettingsVerified(path .. ".pending", body) then self:Notify("Could not save weapon configuration", "warning"); return false end
    local previousOk, previous = pcall(FileMgr.ReadFileContent, path)
    if not menu.writeUiSettingsVerified(path, body) then
        if previousOk and type(previous) == "string" then pcall(menu.writeUiSettingsVerified, path, previous) end
        self:Notify("Could not save weapon configuration", "warning"); return false
    end
    if type(FileMgr.DeleteFile) == "function" then pcall(FileMgr.DeleteFile, path .. ".pending") end
    self.weapon.loadout = snapshot
    self:Notify("Loadout saved", "success")
    return true
end

function SovereignGameplayOptions:ApplyLoadout(silent)
    local snapshot = self:ReadLoadout(silent)
    if not snapshot then return false end
    local ped, completed = self:Local(), true
    if ped == 0 then return false end
    self.weapon.loadout = snapshot
    for hash, row in pairs(snapshot.weapons) do
        local validOk, valid = self:WeaponNative("IS_WEAPON_VALID", hash)
        if validOk and valid and self:WeaponWrite("GIVE_WEAPON_TO_PED", ped, hash, row.ammo, false, false) then
            local desired = {}
            for _, component in ipairs(row.components) do desired[component.hash] = component end
            local supported = {}
            for _, component in ipairs(self:CompatibleComponents(hash)) do
                local id = component.hash & 0xffffffff
                supported[id] = true
                if not desired[id] then
                    local hasOk, has = self:WeaponNative("HAS_PED_GOT_WEAPON_COMPONENT", ped, hash, component.hash)
                    if not hasOk or (has and not self:WeaponWrite("REMOVE_WEAPON_COMPONENT_FROM_PED", ped, hash, component.hash)) then completed = false end
                end
                self:WeaponCheckpoint()
            end
            for _, component in ipairs(row.components) do
                if not supported[component.hash] or not self:WeaponWrite("GIVE_WEAPON_COMPONENT_TO_PED", ped, hash, component.hash) then
                    completed = false
                elseif component.tint >= 0 and not self:WeaponWrite("SET_PED_WEAPON_COMPONENT_TINT_INDEX", ped, hash, component.hash, component.tint) then
                    completed = false
                end
                self:WeaponCheckpoint()
            end
            local tintOk, count = self:WeaponNative("GET_WEAPON_TINT_COUNT", hash)
            if tintOk and type(count) == "number" and count > row.tint then
                if not self:WeaponWrite("SET_PED_WEAPON_TINT_INDEX", ped, hash, row.tint) then completed = false end
            elseif row.tint ~= 0 then completed = false end
            if not self:WeaponWrite("SET_PED_AMMO", ped, hash, row.ammo, false) then completed = false end
        else completed = false end
        self:WeaponCheckpoint()
    end
    if snapshot.weapons[snapshot.selected] then
        if not self:WeaponWrite("SET_CURRENT_PED_WEAPON", ped, snapshot.selected, true) then completed = false end
    end
    if not silent or not completed then self:Notify(completed and "Loadout applied" or "Some configuration entries could not be applied", completed and "success" or "warning") end
    return completed
end

function SovereignGameplayOptions:ChangeComponents(add, selectedHash, silent)
    local hash, ped = self:CurrentWeapon()
    hash = selectedHash or hash
    if not hash or hash == 0 or ped == 0 then return false end
    local ok, owned = self:WeaponNative("HAS_PED_GOT_WEAPON", ped, hash, false)
    if not ok or not owned then return false end
    local count, complete = 0, true
    for _, item in ipairs(self:CompatibleComponents(hash)) do
        -- Bulk upgrades retain appearance and avoid mutually exclusive specialist magazines.
        local name = item[1]
        local standard = not name:find("CAMO", 1, true) and not name:find("VARMOD", 1, true)
            and not name:find("_CLIP_01", 1, true) and not name:find("_CLIP_TRACER", 1, true)
            and not name:find("_CLIP_INCENDIARY", 1, true) and not name:find("_CLIP_HOLLOWPOINT", 1, true)
            and not name:find("_CLIP_ARMORPIERCING", 1, true) and not name:find("_CLIP_FMJ", 1, true)
            and not name:find("_CLIP_EXPLOSIVE", 1, true)
        if not add or standard then
            local good = self:WeaponWrite(add and "GIVE_WEAPON_COMPONENT_TO_PED" or "REMOVE_WEAPON_COMPONENT_FROM_PED", ped, hash, item.hash)
            if good then count = count + 1 else complete = false end
        end
        self:WeaponCheckpoint()
    end
    if not silent then self:Notify(count > 0 and complete and (add and "Current components applied" or "Current components removed") or "No compatible components", count > 0 and complete and "success" or "warning") end
    return count > 0 and complete
end

function SovereignGameplayOptions:RefreshWeaponSelection(category, preferred)
    self.weapon.category = category or self.weapon.category or "All"
    local rows, labels, selected = self:AvailableWeapons(self.weapon.category), {}, 1
    for i, item in ipairs(rows) do
        labels[i] = item[2]
        if item.hash == preferred then selected = i end
    end
    self.weapon.visibleWeapons = rows
    self.weapon.selectedHash = rows[selected] and rows[selected].hash or 0
    local ui = self.weapon.ui
    if ui and ui.selection then
        ui.selection.options, ui.selection.value = #labels > 0 and labels or {"No items available for this version"}, selected
    end
    self.weapon.visibleComponents = {}
    if ui and ui.component then ui.component.options, ui.component.value = {"Read components first"}, 1 end
end

function SovereignGameplayOptions:RefreshWeaponDetails()
    local hash, ped, ui = self.weapon.selectedHash, self:Local(), self.weapon.ui
    if not ui or not hash or hash == 0 then return end
    local rows, labels = self:CompatibleComponents(hash), {}
    for i, item in ipairs(rows) do labels[i] = item[2] end
    -- A selection change while the query yields must not bind controls to an old weapon.
    if self.weapon.selectedHash ~= hash then return end
    self.weapon.visibleComponents = rows
    ui.component.options, ui.component.value = #labels > 0 and labels or {"No compatible components"}, 1
    local ok, ammo = self:WeaponNative("GET_AMMO_IN_PED_WEAPON", ped, hash)
    if ok and type(ammo) == "number" then ui.ammo.value = math.min(9999, math.max(0, ammo)) end
    local tintOk, count = self:WeaponNative("GET_WEAPON_TINT_COUNT", hash)
    local tints = {}
    if tintOk and type(count) == "number" then
        for index = 0, math.min(255, count - 1) do tints[#tints + 1] = string.format("%02d", index) end
    end
    local currentOk, tint = self:WeaponNative("GET_PED_WEAPON_TINT_INDEX", ped, hash)
    ui.tint.options = #tints > 0 and tints or {"Default"}
    ui.tint.value = currentOk and math.max(1, math.min(#ui.tint.options, (tonumber(tint) or 0) + 1)) or 1
end

function SovereignGameplayOptions:ChangeSelectedComponent(add)
    local ui, hash, ped = self.weapon.ui, self.weapon.selectedHash, self:Local()
    local item = ui and self.weapon.visibleComponents and self.weapon.visibleComponents[ui.component.value]
    local ok, owned = self:WeaponNative("HAS_PED_GOT_WEAPON", ped, hash, false)
    if not item or not ok or not owned then self:Notify("Own the selected weapon and read its components first", "warning"); return false end
    local good = self:WeaponWrite(add and "GIVE_WEAPON_COMPONENT_TO_PED" or "REMOVE_WEAPON_COMPONENT_FROM_PED", ped, hash, item.hash)
    self:Notify(good and (add and "Component installed" or "Component removed") or "Action could not be completed", good and "success" or "warning")
    return good
end

function SovereignGameplayOptions:BindLoadout(group)
    local w = self.weapon
    w.ui = {}
    local ui = w.ui
    local categories = {"All", "Pistol", "SMGs and machine guns", "Rifles", "Shotguns", "Sniper rifles", "Heavy weapons", "Melee", "Throwables", "Tools"}
    ui.category = menu.combo("Weapon category", "", group, categories, 1, 0, function(index)
        self:RefreshWeaponSelection(categories[index] or "All")
    end)
    ui.selection = menu.combo("Weapon selection", "", group, {"No items available for this version"}, 1, 0, function(index)
        local row = w.visibleWeapons and w.visibleWeapons[index]
        w.selectedHash = row and row.hash or 0
        w.visibleComponents = {}
        ui.component.options, ui.component.value = {"Read components first"}, 1
    end)
    menu.button("Select held weapon", "", group, 0, function()
        local hash = self:CurrentWeapon()
        ui.category.value = 1
        self:RefreshWeaponSelection("All", hash)
        self:RunWeaponJob(function(owner) owner:RefreshWeaponDetails() end)
    end)
    menu.button("Give selected weapon", "", group, 0, function() self:GiveSelectedWeapon() end)
    menu.button("Remove selected weapon", "", group, 0, function() self:RemoveSelectedWeapon() end)
    ui.ammo = menu.slider("Selected weapon ammo", "", group, 0, 9999, 9999, "%d", 0, function() end)
    menu.button("Set selected ammo", "", group, 0, function()
        local ok, owned = self:WeaponNative("HAS_PED_GOT_WEAPON", self:Local(), w.selectedHash, false)
        local good = ok and owned and self:WeaponWrite("SET_PED_AMMO", self:Local(), w.selectedHash, math.floor(ui.ammo.value), false)
        self:Notify(good and "Ammo set" or "Own the selected weapon and read its components first", good and "success" or "warning")
    end)
    menu.button("Read components and tints", "", group, 0, function() self:RunWeaponJob(function(owner) owner:RefreshWeaponDetails() end) end)
    ui.component = menu.combo("Compatible components", "", group, {"Read components first"}, 1, 0, function() end)
    menu.button("Install selected component", "", group, 0, function() self:ChangeSelectedComponent(true) end)
    menu.button("Remove selected component", "", group, 0, function() self:ChangeSelectedComponent(false) end)
    ui.tint = menu.combo("Selected weapon tint", "", group, {"Default"}, 1, 0, function(index)
        local hash = w.selectedHash
        local ok, count = self:WeaponNative("GET_WEAPON_TINT_COUNT", hash)
        if ok and type(count) == "number" and index >= 1 and index <= count then
            self:WeaponWrite("SET_PED_WEAPON_TINT_INDEX", self:Local(), hash, index - 1)
        end
    end)
    ui.camoTint = menu.slider("Camo colour", "Requires an installed camo component.", group, 0, 31, 0, "%d", 0, function(value)
        local item = w.visibleComponents and w.visibleComponents[ui.component.value]
        if item and item[1]:find("CAMO", 1, true) then
            local ok, installed = self:WeaponNative("HAS_PED_GOT_WEAPON_COMPONENT", self:Local(), w.selectedHash, item.hash)
            if ok and installed then self:WeaponWrite("SET_PED_WEAPON_COMPONENT_TINT_INDEX", self:Local(), w.selectedHash, item.hash, math.floor(value)) end
        end
    end)
    ui.camoTint.applyOnRelease = true
    menu.button("Save loadout", "Save owned weapons, ammo, components and tints.", group, 0, function() self:RunWeaponJob(function(owner) owner:SaveLoadout() end) end)
    menu.button("Apply loadout", "Read the saved configuration.", group, 0, function() self:RunWeaponJob(function(owner) owner:ApplyLoadout(false) end) end)
    local auto = menu.toggle("Auto apply loadout", "Apply the saved configuration on entering a session.", group, 0, function(value)
        w.autoLoadout, w.sessionToken = value == true, nil
    end)
    if menu.bindFeatureToggle then menu.bindFeatureToggle(auto, "sovereign_auto_loadout", function() return w.autoLoadout end) end
    self:RefreshWeaponSelection("All", w.selectedHash)
end


function SovereignGameplayOptions:CurrentWeapon()
    local weapon, ped = menu.nativeApis.WEAPON, self:Local()
    if not weapon or ped == 0 or type(weapon.GET_SELECTED_PED_WEAPON) ~= "function" then return 0, ped end
    return weapon.GET_SELECTED_PED_WEAPON(ped) or 0, ped
end

function SovereignGameplayOptions:RefillCurrentAmmo()
    local weapon, hash, ped = menu.nativeApis.WEAPON, nil, nil
    hash, ped = self:CurrentWeapon()
    if not weapon or hash == 0 or ped == 0 or type(weapon.SET_PED_AMMO) ~= "function" then return false end
    local ok, accepted = pcall(weapon.SET_PED_AMMO, ped, hash, 9999, false)
    if not ok or accepted == false then self:Notify("Action could not be completed", "warning"); return false end
    self:Notify("Current ammo refilled", "success")
    return true
end

function SovereignGameplayOptions:GiveSelectedWeapon()
    local weapon, ped = menu.nativeApis.WEAPON, self:Local()
    local hash = self.weapon.selectedHash
    if not weapon or not hash or hash == 0 or ped == 0 or type(weapon.GIVE_WEAPON_TO_PED) ~= "function" then
        return false
    end
    local ok, accepted = pcall(weapon.GIVE_WEAPON_TO_PED, ped, hash, 9999, false, true)
    if not ok or accepted == false then self:Notify("Action could not be completed", "warning"); return false end
    self:Notify("Selected weapon given", "success")
    return true
end

function SovereignGameplayOptions:RemoveSelectedWeapon()
    local weapon, ped = menu.nativeApis.WEAPON, self:Local()
    local hash = self.weapon.selectedHash
    if not weapon or not hash or hash == 0 or ped == 0 or type(weapon.REMOVE_WEAPON_FROM_PED) ~= "function" then
        return false
    end
    local ok, accepted = pcall(weapon.REMOVE_WEAPON_FROM_PED, ped, hash)
    if not ok or accepted == false then self:Notify("Action could not be completed", "warning"); return false end
    self:Notify("Selected weapon removed", "success")
    return true
end

function SovereignGameplayOptions:RememberHandling(veh)
    local h = self.handling
    h.vehicle, h.hostBaseline, h.hostApplied, h.hostFeatures = veh, {}, {}, {}
    h.nativeApplied, h.lastApply, h.unavailableNotice = {}, nil, false
end

function SovereignGameplayOptions:RestoreHandling()
    local h, v = self.handling, menu.nativeApis.VEHICLE
    local pending = false
    for name, value in pairs(h.hostBaseline or {}) do
        if not self:SetHostHandling(name, value) then pending = true end
    end
    local applied, veh = h.nativeApplied or {}, h.vehicle
    local entity = menu.nativeApis.ENTITY
    local exists = veh and veh ~= 0 and entity and type(entity.DOES_ENTITY_EXIST) == "function"
        and entity.DOES_ENTITY_EXIST(veh)
    if exists and v then
        local function restore(key, fn, ...)
            if applied[key] ~= nil then
                local ok, result = pcall(fn, ...)
                if ok and result ~= false then applied[key] = nil else pending = true end
            end
        end
        restore("power", v.MODIFY_VEHICLE_TOP_SPEED, veh, 0.0)
        restore("steer", v.SET_VEHICLE_STEER_BIAS, veh, 0.0)
        restore("burnout", v.SET_VEHICLE_BURNOUT, veh, false)
        restore("left", v.SET_VEHICLE_INDICATOR_LIGHTS, veh, 0, false)
        restore("right", v.SET_VEHICLE_INDICATOR_LIGHTS, veh, 1, false)
    end
    if pending then return false end
    h.vehicle, h.hostBaseline, h.hostApplied, h.hostFeatures, h.nativeApplied = 0, {}, {}, {}, {}
    return true
end

SovereignGameplayOptions.ProcessHandling = LPH_NO_VIRTUALIZE(function(self)
    local h, v = self.handling, menu.nativeApis.VEHICLE
    if not h.enabled and h.vehicle == 0 then return end
    local now = self:Now()
    if h.lastApply and now >= h.lastApply and now - h.lastApply < 0.1 then return end
    h.lastApply = now
    if not h.enabled then self:RestoreHandling(); return end
    local ped = self:Local()
    local veh = ped ~= 0 and self:Vehicle(ped) or 0
    if not v or veh == 0 then
        if h.vehicle ~= 0 then self:RestoreHandling() end
        return
    end
    if h.vehicle ~= veh then
        if h.vehicle ~= 0 and not self:RestoreHandling() then return end
        self:RememberHandling(veh)
        h.lastApply = now
    end
    local unavailable = false
    local applied = h.nativeApplied
    local function apply(key, fn, value, neutral, ...)
        if value == neutral and applied[key] == nil then return end
        if applied[key] == value then return end
        if type(fn) ~= "function" then unavailable = true; return end
        local ok, result = pcall(fn, ...)
        if ok and result ~= false then applied[key] = value else unavailable = true end
    end
    -- This native accepts a percentage change; 0 restores its default.
    local power = (h.enginePower - 1.0) * 100.0
    apply("power", v.MODIFY_VEHICLE_TOP_SPEED, power, 0, veh, power)
    apply("steer", v.SET_VEHICLE_STEER_BIAS, h.steeringBias, 0, veh, h.steeringBias)
    apply("burnout", v.SET_VEHICLE_BURNOUT, h.burnout, false, veh, h.burnout)
    apply("left", v.SET_VEHICLE_INDICATOR_LIGHTS, h.blinkers, false, veh, 0, h.blinkers)
    apply("right", v.SET_VEHICLE_INDICATOR_LIGHTS, h.blinkers, false, veh, 1, h.blinkers)
    local function hostValue(name, factor, absolute)
        if factor == 1.0 and absolute == nil and h.hostBaseline[name] == nil then return end
        local base = h.hostBaseline[name]
        if base == nil then base = self:GetHostHandling(name) end
        if base == nil or not self:SetHostHandling(name, absolute or base * factor) then unavailable = true end
    end
    local touch = h.steeringTouchiness and h.steeringTouchiness + 4.0 or nil
    hostValue("HandlingBrakeStrength", h.brakeForce)
    hostValue("HandlingLowSpeedBurnoutMult", h.lowSpeedGrip)
    hostValue("HandlingTireGripMin", h.gripMin, touch)
    hostValue("HandlingTireGripMax", h.gripMax, touch)
    local roll = h.rollCentreRear
    if h.clumsiness then roll = -h.clumsiness end
    if h.wheelie then
        local pad = menu.nativeApis.PAD
        local pressed = pad and pad.IS_CONTROL_PRESSED
        if type(pressed) == "function" and pressed(0, 71) and pressed(0, 280) then roll = -h.wheelie end
    end
    hostValue("HandlingRollcentreRear", 1.0, roll)
    if unavailable and not h.unavailableNotice then
        h.unavailableNotice = true
        self:Notify("Some handling options are unavailable", "warning")
    end
end)

