function SovereignGameplayOptions:Bind(groups)
    if self.bound then return end
    self:AddTranslations()
    local entityGroup = groups.entityManagement
    local weaponGroup = groups.weaponConfiguration
    local fingerGroup = groups.weaponFingerGun
    local aimGroup = groups.weaponAim
    local drivingGroup = groups.vehicleDriving
    if entityGroup then
        menu.slider("Throw force", "", entityGroup, 1, 1000, 100, "%d", 0, function(value)
            self.entityForce = math.max(1, tonumber(value) or 100)
        end)
        menu.toggle("Include player vehicles", "", entityGroup, 0, function(value)
            self.includePlayerVehicles = value == true
        end)
        local grab = menu.toggle("Entity grabber", "Press E to grab, then again to release.", entityGroup, 0, function(value)
            self.grabber.enabled = value == true
            if not self.grabber.enabled and self.grabber.attached then
                self:ReleaseGrabbed(self:Local(), false)
            end
        end)
        if grab and menu.bindFeatureToggle then
            menu.bindFeatureToggle(grab, "sovereign_entity_grabber", function() return self.grabber.enabled end)
        end
    end

    if fingerGroup then
        menu.slider("Finger gun projectile speed", "", fingerGroup, 1, 1000, 500, "%d", 0, function(value)
            self.weapon.projectileSpeed = tonumber(value) or 500
            ImportedExtensionOptions.fingerGunProjectileSpeed = self.weapon.projectileSpeed
        end)
        menu.slider("Shot delay", "", fingerGroup, 10, 1000, 100, "%d ms", 0, function(value)
            self.weapon.fireDelay = tonumber(value) or 100
            ImportedExtensionOptions.fingerGunInterval = math.max(0.01, self.weapon.fireDelay / 1000.0)
        end)
        ImportedExtensionOptions.fingerGunWeaponHash = Utils.Joaat("weapon_raypistol")
        menu.combo("Finger gun projectile", "Choose the projectile fired by the finger gun.", fingerGroup,
            {"Up-n-Atomizer", "Pistol", "SMG", "Carbine Rifle", "Pump Shotgun", "Heavy Sniper", "RPG", "Firework Launcher"}, 1, 0, function(index)
                local names = {"RAYPISTOL", "PISTOL", "SMG", "CARBINERIFLE", "PUMPSHOTGUN", "HEAVYSNIPER", "RPG", "FIREWORK"}
                local slot = math.max(1, math.min(#names, math.floor(tonumber(index) or 1)))
                ImportedExtensionOptions.fingerGunWeaponHash = WeaponManager.WEAPON_HASHES[names[slot]]
            end)
    end
    if weaponGroup then
        self:BindLoadout(weaponGroup)
        local infinite = menu.toggle("Infinite ammo", "", weaponGroup, 0, function(value) self.weapon.infiniteAmmo = value == true end)
        if infinite and menu.bindFeatureToggle then
            menu.bindFeatureToggle(infinite, "sovereign_infinite_ammo", function() return self.weapon.infiniteAmmo end)
        end
        local noReload = menu.toggle("No reload", "", weaponGroup, 0, function(value) self.weapon.noReload = value == true end)
        if noReload and menu.bindFeatureToggle then
            menu.bindFeatureToggle(noReload, "sovereign_no_reload", function() return self.weapon.noReload end)
        end
        menu.button("Refill current ammo", "", weaponGroup, 0, function() self:RefillCurrentAmmo() end)
        menu.button("Upgrade held weapons", "", weaponGroup, 0, function()
            self:RunWeaponJob(function(owner)
                local ped, count = owner:Local(), 0
                for _, row in ipairs(owner:AvailableWeapons()) do
                    local ok, held = owner:WeaponNative("HAS_PED_GOT_WEAPON", ped, row.hash, false)
                    if ok and held and owner:ChangeComponents(true, row.hash, true) then count = count + 1 end
                    owner:WeaponCheckpoint()
                end
                owner:Notify(count > 0 and "Current components applied" or "No compatible components", count > 0 and "success" or "warning")
            end)
        end)
        menu.button("Add current weapon components", "", weaponGroup, 0, function() self:RunWeaponJob(function(owner) owner:ChangeComponents(true) end) end)
        menu.button("Remove current weapon components", "", weaponGroup, 0, function() self:RunWeaponJob(function(owner) owner:ChangeComponents(false) end) end)
        menu.button("Give all weapons", "", weaponGroup, 0, function()
            self:RunWeaponJob(function(owner)
                local ped, complete = owner:Local(), true
                for _, row in ipairs(owner:AvailableWeapons()) do
                    if not owner:WeaponWrite("GIVE_WEAPON_TO_PED", ped, row.hash, 9999, false, false) then complete = false end
                    owner:WeaponCheckpoint()
                end
                if not complete then owner:Notify("Action could not be completed", "warning") end
            end)
        end)
        menu.button("Remove all weapons", "", weaponGroup, 0, function()
            if WeaponManager then pcall(WeaponManager.RemoveAllWeapons, WeaponManager, select(2, self:Local())) end
        end)
    end
    if aimGroup then
        local allowPlayers = menu.toggle("Allow player lock-on", "Allow aim assist to target player characters.", aimGroup, 0, function(value)
            self.aim.allowPlayers = value == true
            SovereignAimAssist.advanced.allowPlayers = self.aim.allowPlayers
            SovereignAimAssist:Reset()
        end)
        local allowNpc = menu.toggle("Allow NPC lock-on", "Allow aim assist to target NPCs.", aimGroup, 0, function(value)
            self.aim.allowNpc = value == true
            SovereignAimAssist.advanced.allowNpc = self.aim.allowNpc
            SovereignAimAssist:Reset()
        end)
        local allowVehicle = menu.toggle("Allow vehicle occupants", "Allow aim assist to target vehicle occupants.", aimGroup, 0, function(value)
            self.aim.allowVehicle = value == true
            SovereignAimAssist.advanced.allowVehicle = self.aim.allowVehicle
            SovereignAimAssist:Reset()
        end)
        local whileDriving = menu.toggle("Allow lock-on while driving", "Allow aim assist while you are in a vehicle.", aimGroup, 0, function(value)
            self.aim.whileDriving = value == true
            SovereignAimAssist.advanced.whileDriving = self.aim.whileDriving
            SovereignAimAssist:Reset()
        end)
        menu.slider("Aim assist strength", "Enable aim assist first. Higher values track faster.", aimGroup, 0, 200, 100, "%d%%", 0, function(value)
            SovereignAimAssist.advanced.strength = (tonumber(value) or 100) / 100.0
        end)
        menu.combo("Aim bone", "", aimGroup,
            {"Head", "Chest", "Pelvis"}, 1, 0, function(index)
                local bones = {[1] = 31086, [2] = 24818, [3] = 11816}
                SovereignAimAssist.advanced.targetBone = bones[math.max(1, math.min(3, tonumber(index) or 1))]
                SovereignAimAssist:Reset()
            end)
        menu.slider("Maximum lock-on distance", "", aimGroup, 50, 1000, 300, "%dm", 0, function(value)
            SovereignAimAssist.advanced.maxDistance = tonumber(value) or 300.0
            SovereignAimAssist:Reset()
        end)
        if allowPlayers then allowPlayers.value = true end
        if allowNpc then allowNpc.value = true end
        if allowVehicle then allowVehicle.value = true end
        if menu.bindFeatureToggle then
            menu.bindFeatureToggle(allowPlayers, "sovereign_aim_players", function() return self.aim.allowPlayers end)
            menu.bindFeatureToggle(allowNpc, "sovereign_aim_npc", function() return self.aim.allowNpc end)
            menu.bindFeatureToggle(allowVehicle, "sovereign_aim_vehicle", function() return self.aim.allowVehicle end)
            menu.bindFeatureToggle(whileDriving, "sovereign_aim_driving", function() return self.aim.whileDriving end)
        end
    end

    if drivingGroup then
        local fineHandling = menu.toggle("Fine vehicle handling", "", drivingGroup, 0, function(value)
            self.handling.enabled = value == true
            if not self.handling.enabled and self.handling.vehicle ~= 0 then self:RestoreHandling() end
        end)
        if fineHandling and menu.bindFeatureToggle then
            menu.bindFeatureToggle(fineHandling, "sovereign_fine_handling", function() return self.handling.enabled end)
        end
        local burnout = menu.toggle("Low-speed burnout", "", drivingGroup, 0, function(value) self.handling.burnout = value == true; if value == true then self.handling.enabled = true end end)
        if burnout and menu.bindFeatureToggle then
            menu.bindFeatureToggle(burnout, "sovereign_burnout", function() return self.handling.burnout end)
        end
        menu.slider("Engine power multiplier", "", drivingGroup, 50, 300, 100, "%d%%", 0, function(value)
            self.handling.enginePower = (tonumber(value) or 100) / 100.0
            self.handling.enabled = true
        end)
        menu.slider("Brake strength", "", drivingGroup, 50, 300, 100, "%d%%", 0, function(value)
            self.handling.brakeForce = (tonumber(value) or 100) / 100.0
            self.handling.enabled = true
        end)
        menu.slider("Minimum tire grip", "", drivingGroup, 50, 300, 100, "%d%%", 0, function(value)
            self.handling.gripMin = (tonumber(value) or 100) / 100.0
            self.handling.enabled = true
        end)
        menu.slider("Maximum tire grip", "", drivingGroup, 50, 300, 100, "%d%%", 0, function(value)
            self.handling.gripMax = (tonumber(value) or 100) / 100.0
            self.handling.enabled = true
        end)
        menu.slider("Low-speed grip", "", drivingGroup, 50, 300, 100, "%d%%", 0, function(value)
            self.handling.lowSpeedGrip = (tonumber(value) or 100) / 100.0
            self.handling.enabled = true
        end)
        menu.slider("Rear roll-centre height", "", drivingGroup, 0, 100, 50, "%d%%", 0, function(value)
            self.handling.rollCentreRear = (tonumber(value) or 50) / 100.0
            self.handling.enabled = true
        end)
        menu.slider("Steering bias", "", drivingGroup, -100, 100, 0, "%d", 0, function(value)
            self.handling.steeringBias = (tonumber(value) or 0) / 100.0
            self.handling.enabled = true
        end)
        menu.slider("Steering touchiness", "", drivingGroup, 0, 10, 0, "%d", 0, function(value)
            local n = tonumber(value) or 0
            self.handling.steeringTouchiness = n > 0 and n or nil
            if n > 0 then self.handling.enabled = true end
        end)
        menu.slider("Vehicle clumsiness", "", drivingGroup, 0, 100, 0, "%d%%", 0, function(value)
            local n = tonumber(value) or 0
            self.handling.clumsiness = n > 0 and n / 100.0 or nil
            if n > 0 then self.handling.wheelie = nil; self.handling.enabled = true end
        end)
        menu.slider("Wheelie tendency", "Ctrl + W", drivingGroup, 0, 100, 0, "%d%%", 0, function(value)
            local n = tonumber(value) or 0
            self.handling.wheelie = n > 0 and n / 100.0 or nil
            if n > 0 then self.handling.clumsiness = nil; self.handling.enabled = true end
        end)
        local blinkers = menu.toggle("Hazard blinkers", "", drivingGroup, 0, function(value)
            self.handling.blinkers = value == true
            if value == true then self.handling.enabled = true end
        end)
        if blinkers and menu.bindFeatureToggle then
            menu.bindFeatureToggle(blinkers, "sovereign_hazard_blinkers", function() return self.handling.blinkers end)
        end
        menu.button("Reset handling", "", drivingGroup, 0, function()
            self.handling.enabled = false
            self.handling.burnout, self.handling.steeringBias = false, 0.0
            self.handling.steeringTouchiness, self.handling.clumsiness, self.handling.wheelie = nil, nil, nil
            self.handling.blinkers = false
            self.handling.enginePower, self.handling.brakeForce = 1.0, 1.0
            self.handling.gripMin, self.handling.gripMax, self.handling.lowSpeedGrip = 1.0, 1.0, 1.0
            self.handling.rollCentreRear = nil
            if self:RestoreHandling() then self:Notify("Handling settings reset", "success")
            else self:Notify("Restoring handling settings", "warning") end
        end)
    end

    self.bound = true
end

SovereignGameplayOptions.Process = LPH_NO_VIRTUALIZE(function(self)
    if not self.bound then return end
    self:ProcessGrabber()
    self:ProcessWeapon()
    self:ProcessHandling()
end)

function SovereignGameplayOptions:Cleanup()
    if self.weapon.job then self.weapon.job.cancelled = true end
    if self.grabber and self.grabber.attached then
        pcall(self.ReleaseGrabbed, self, self:Local(), false)
    end
    self.grabber.enabled, self.grabber.entity, self.grabber.attached = false, 0, false
    self.weapon.infiniteAmmo, self.weapon.noReload = false, false
    self:RestoreAmmoFlags()
    self.handling.enabled = false
    self:RestoreHandling()
    self.bound = false
end

function SovereignGameplayOptions:JoinPlayerVehicle(pid)
    if not PlayerManager:IsValidPlayer(pid) then self:Notify("Player unavailable", "warning"); return false end
    local vehicle = PlayerTrollOptions:GetVehicle(pid)
    local ped = self:Local()
    local v, task = menu.nativeApis.VEHICLE, menu.nativeApis.TASK
    if not vehicle or vehicle == 0 or ped == 0 or not v or not task then return false end
    local ok, joined = pcall(function()
        local lastSeat = math.floor(v.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS(vehicle)) - 1
        for seat = 0, math.min(31, lastSeat) do
            if v.IS_VEHICLE_SEAT_FREE(vehicle, seat, false) then
                task.TASK_WARP_PED_INTO_VEHICLE(ped, vehicle, seat)
                return true
            end
        end
        return false
    end)
    if not ok or not joined then self:Notify("No empty passenger seat", "warning"); return false end
    return true
end

