                pcall(menu.nativeApis.HUD.SET_NEW_WAYPOINT, pos.x, pos.y)
            end
        end
    },
    {
        hash = Utils.Joaat("sovereign_player_enter_vehicle"),
        name = "Enter player's vehicle",
        type = eFeatureType.Button,
        desc = "Enter the selected player's current vehicle.",
        cb = function(f)
            local pid = f:GetPlayerIndex()
            SovereignGameplayOptions:JoinPlayerVehicle(pid)
        end
    },
    {
        hash = Utils.Joaat("sovereign_player_join_empty_seat"),
        name = "Join an empty seat",
        type = eFeatureType.Button,
        desc = "Join an empty passenger seat.",
        cb = function(f)
            local pid = f:GetPlayerIndex()
            SovereignGameplayOptions:JoinPlayerVehicle(pid)
        end
    },
    {
        hash = Utils.Joaat("sovereign_player_profile"),
        name = "Open Rockstar profile",
        type = eFeatureType.Button,
        desc = "Open this player's Rockstar profile.",
        cb = function(f)
            local pid = f:GetPlayerIndex()
            local ok = pcall(function()
                if not Players.GetById(pid) then error("player_left") end
                local network = menu.nativeApis.NETWORK
                local buffer = GamerHandleBuffer.New()
                local address = buffer:GetBuffer()
                if not address or address == 0 then error("profile_buffer") end
                network.NETWORK_HANDLE_FROM_PLAYER(pid, address, 13)
                if not network.NETWORK_IS_HANDLE_VALID(address, 13) then error("profile_handle") end
                network.NETWORK_SHOW_PROFILE_UI(address)
            end)
            if not ok then SovereignGameplayOptions:Notify("Player profile unavailable", "warning") end
        end
    },
    {
        hash = Utils.Joaat("sovereign_player_status"),
        name = "View player status",
        type = eFeatureType.Button,
        desc = "View this player's status.",
        cb = function(f)
            local pid = f:GetPlayerIndex()
            if not PlayerManager:IsValidPlayer(pid) then SovereignGameplayOptions:Notify("Player unavailable", "warning"); return end
            local name = GetPlayerName(pid)
            local details = type(SovereignGetPlayerInfoDetails) == "function" and SovereignGetPlayerInfoDetails(pid) or {}
            local distance = GetPlayerDistance(pid)
            local rid = "Unavailable"
            if PlayerManager and type(PlayerManager.GetRockstarId) == "function" then
                local ridOk, found, value = pcall(PlayerManager.GetRockstarId, PlayerManager, pid)
                if ridOk and found == true and value then rid = value end
            end
            local text = string.format(menu.translate("%s | RID=%s | Ping=%s | Distance=%s | Position=%s"),
                tostring(name), tostring(rid),
                tostring(menu.translate(details.ping or "Unavailable")), distance and string.format("%.0fm", distance) or menu.translate("Unavailable"),
                tostring(menu.translate(details.coordinates or "Unavailable")))
            text = text .. " | " .. menu.translate("Zone") .. "=" .. tostring(menu.translate(details.zone or "Unknown zone"))
            if SovereignNotify then pcall(SovereignNotify, "Player status", text, "info") end
        end
    },
    {
        hash = Utils.Joaat("sovereign_player_clear_target"),
        name = "Clear target cache",
        type = eFeatureType.Button,
        desc = "Clear local aim and tracking state.",
        cb = function()
            if SovereignAimAssist then SovereignAimAssist:Reset() end
        end
    }
}


