        local key, keySource = "", "unknown"
        if FileManager and FileManager.LoadSavedKey then
            local ok, value, source = pcall(function() return FileManager:LoadSavedKey() end)
            if ok and type(value) == "string" then key, keySource = value, source end
        end
        if key ~= "" then
            AuthManager.keySource = keySource
            if key ~= AuthManager.currentKey then
                AuthManager.currentKey = key
                AuthManager.isAuthenticated = false
                AuthManager.status = AUTH_STATUS.PENDING
                SovereignRuntime.autoLoginNextAttempt = 0
            end
            if authKeyInput then authKeyInput.value = key end
        end
        SovereignNotify("SovereignLua", key ~= "" and "Saved license key loaded" or "No saved license key found", key ~= "" and "success" or "warning")
    end)
    menu.text("Login status appears in notifications.", groups.auth)

    do
    -- The injector selects the target executable. Lua only reports the module
    -- detected at runtime; keeping a second selector here can desynchronize
    -- the chosen process and the memory layout.
    local editionUi = {}
    editionUi.detected, editionUi.source = Utils1:editionInfo()
    menu.text("Current version: " .. tostring(editionUi.detected), groups.runtimeSettings)
