    menu.button("Apply avatar", "Load the path above and update the avatar immediately", groups.uiSettings, 0, function()
        local ok, reason = menu.setAvatarPath(menu.ui.avatarPathPending or "", true)
        local message = "Avatar updated"
        if reason == "unsupported_image" then
