local function SovereignQueueMenuBuild()
    if SovereignRuntime.menuBuilt then
        return true
    end
    if SovereignRuntime.menuBuildFailed then
        return false
    end
    if SovereignRuntime.menuBuildQueued then
        return true
    end

    SovereignRuntime.menuBuildQueued = true
    local queued = SovereignRunJob("SovereignRuntime.BuildMenu", function()
        local dependencyOk, dependencyError = pcall(function()
            require("DataNodes")
        end)
        if not dependencyOk then
            SovereignLogError("SovereignLua", "Failed to load dependencies: " .. tostring(dependencyError))
        else
            AntiHookManager:ProtectCheraxApiBoundary(true)
        end

        local buildOk, buildError = xpcall(SovereignBuildMenu, debug.traceback)
        SovereignRuntime.menuBuildInProgress = false
        if not buildOk then
            SovereignRuntime.menuBuildQueued = false
            SovereignRuntime.menuBuildFailed = true
            menu.setOpen(false)
            menu.captureMouse(false)
            SovereignLogError("SovereignRuntime.BuildMenu", buildError)
        end
    end)
    if not queued then
        SovereignRuntime.menuBuildQueued = false
        SovereignRuntime.menuBuildFailed = true
    end
    return queued
end

local function SovereignInitialize()
    if SovereignRuntime.initialized then return true end
    if SovereignRuntime.initializationFailed then
        return false
    end
    if SovereignRuntime.initializationQueued then
        return false
    end
    SovereignRuntime.initializationQueued = true
    local queued = SovereignRunJob("SovereignRuntime.Initialize", function()
        local ok, err = xpcall(function()
            if not SovereignInitializeRuntimeGuards() then
                error("runtime guard initialization failed", 0)
            end
            SovereignRuntime.releaseTrace = table.concat({
                tostring(CONFIG.VERSION.String or ""),
                tostring(SovereignRuntime.remoteBuild or ""),
                tostring(SovereignRuntime.watermark or "")
            }, "|")
            package.path = CONFIG.PATHS.LuaRoot .. ";" .. package.path
            menu.registerHotkey()
            SovereignQueueMenuBuild()
            SovereignInstallToastBridge()
            SovereignRuntime:EnsureLoop()
            local detectedEdition, detectedSource = Utils1:editionInfo()
            Logger:Info("SovereignInventory", string.format(
                "runtime revision=%s edition=%s source=%s instance=%s",
                tostring(SovereignBusinessInventory.runtimeRevision),
                tostring(detectedEdition), tostring(detectedSource),
                tostring(SovereignBusinessInventory)
            ))
            if SovereignRuntime.watermark and SovereignRuntime.watermark ~= "" then
                Logger:Info("SovereignLua", "Help ID: " .. tostring(SovereignRuntime.watermark))
            end
        end, debug.traceback)
        SovereignRuntime.initializationQueued = false
        if not ok then
            SovereignRuntime.initializationFailed = true
            SovereignLogError("SovereignRuntime.Initialize", err)
            SetShouldUnload()
            return
        end
        SovereignRuntime.initialized = true
    end)
    if not queued then
        SovereignRuntime.initializationQueued = false
        SovereignRuntime.initializationFailed = true
        return false
    end
    return false
end

local function SovereignOnAuthorizedFirstPresent()
    if SovereignRuntime.menuLoaded then return end
    local edition = Utils1 and Utils1.edition and Utils1:edition() or "Unknown"
    if edition == "Enhanced" or edition == "Legacy" then
        MemoryBridge:Initialize(false)
    end
    if edition == "Enhanced" then
        MemoryPatcher:SetHardwareNatOpen()
        MemoryPatcher:PatchNullptrPoolCrash()
    end
    local localName = Players.GetName(PlayerManager:GetLocalPlayerId())
    Logger:Toast("SovereignLua", "Welcome " .. (localName or "whats ur name?"), CONFIG.UI.ToastDuration.Long)
    SovereignRuntime.menuLoaded = true
end

SovereignProcessFreeRuntime = LPH_NO_VIRTUALIZE(function(now)
    if not SovereignRuntime.menuBuilt then return end
    SovereignRuntime:ApplyPermissionVisibility()
    -- Initialize the local saved-player store before authentication so the
    -- allowlisted Protection page works from a fresh install.
    if not SavedPlayerManager.isLoaded then
        pcall(SavedPlayerManager.Init, SavedPlayerManager)
    end
    menu.playerWorldPaused = false

    local playerId = menu.nativeApis.PLAYER.PLAYER_ID()
    SovereignRuntime:RunModule("Self", SelfOptions.ProcessSelfOptions, SelfOptions, playerId)
    SovereignRuntime:RunModule("World Extensions", ImportedExtensionOptions.ProcessWorldExtensionsFree,
        ImportedExtensionOptions)

    -- Free monitoring stays live without a lease. Preserve the saved cleanup
    -- preference, but never run paid entity cleanup from the free branch.
    if SovereignPoolMonitor.enabled then
        SovereignRuntime:RunModule("Entity pools", SovereignPoolMonitor.Tick, SovereignPoolMonitor, now, false)
    end
    if TravellerMigration.overviewVisible == true
        and now - (TravellerMigration.lastRefresh or 0) >= (TravellerMigration.refreshInterval or 1.0) then
        SovereignRuntime:RunModule("Session overview", TravellerMigration.Process, TravellerMigration, now, false)
    end
    if SovereignBattleNetworkStatus.visible == true
        and now - (SovereignBattleNetworkStatus.lastRefresh or 0) >= (SovereignBattleNetworkStatus.refreshInterval or 1.0) then
        SovereignRuntime:RunModule("Session Network Status", SovereignBattleNetworkStatus.Process,
            SovereignBattleNetworkStatus, now, false)
    end

    if menu.teammateTracking.navigation or menu.teammateTracking.status then
        SovereignRuntime:RunModule("Teammate tracking", menu.teammateTracking.Process, menu.teammateTracking)
    end

    -- Tick shims are individually filtered by the same free-access marker as
    -- click callbacks, so mission Tools and free player toggles keep running
    -- without opening any paid category.
    SovereignRuntime:RunModule("Looped features", SovereignProcessTickShims)

    if menu.featureSettings.restoring then
        if menu.nativeApis.PLAYER.PLAYER_PED_ID() ~= 0 then
            menu.setFeatureRestoreStatus("restoring")
            menu.restoreFeatureSettingsStep()
        else
            menu.setFeatureRestoreStatus("waiting_player")
        end
    end

    if now - (SovereignRuntime.lastDynamicListProcess or 0) >= (SovereignRuntime.dynamicListInterval or 1.0) then
        SovereignRuntime.lastDynamicListProcess = now
        SovereignRuntime:RunModule("Dynamic lists", SovereignProcessDynamicLists)
    end
end)

local SovereignProcessRuntime = LPH_NO_VIRTUALIZE(function()
    if #menu.sessionSupport.pickups > 0 then
        SovereignRuntime:RunModule("Support cleanup", menu.sessionSupport.CleanupTick, menu.sessionSupport)
    end
    if SovereignRuntime.authInProgress
        or not (AuthManager and type(AuthManager.SessionValid) == "function"
            and AuthManager:SessionValid() == true) then
        -- Keep the selected free pages responsive while the paid runtime waits
        -- for a lease. No paid module is entered from this branch.
        SovereignProcessFreeRuntime(os.clock())
        return
    end
    menu.playerWorldPaused = false
    if #SovereignProtectionFeedback.queue > 0 then SovereignProtectionFeedback:Flush() end
    local now = os.clock()
    if now - (SovereignRuntime.lastSessionCheck or 0) >= (SovereignRuntime.sessionCheckInterval or 3.0) then
        SovereignRuntime.lastSessionCheck = now
        if not AuthManager:EnforceSession("SovereignPresent") then
            menu.pausePlayerWorldFeatures()
            return
        end
    end
    -- Restoring a switch follows the same authorization path as clicking it.
    -- Unrelated mapping scans must not block native-only and UI callbacks.
    if SovereignRuntime.menuBuilt and menu.featureSettings.restoring then
        if menu.nativeApis.PLAYER.PLAYER_PED_ID() ~= 0 then
            menu.setFeatureRestoreStatus("restoring")
            menu.restoreFeatureSettingsStep()
        else
            menu.setFeatureRestoreStatus("waiting_player")
        end
    end
    -- Host pool counters do not depend on the script address mapping.
    if SovereignPoolMonitor.enabled then
        local poolStarted = menu.runtimeProbe and menu.runtimeProbe.active and os.clock() or nil
        SovereignPoolMonitor:Tick()
        if poolStarted then menu.recordRuntimeTiming("Entity pools", poolStarted) end
    end
    if not SovereignEnableAuthorizedRuntime() then
        return
    end
    SovereignOnAuthorizedFirstPresent()
    if now - (SovereignRuntime.lastPlayerLinkProbe or 0) >= (SovereignRuntime.playerLinkProbeInterval or 1.0) then
        SovereignRuntime.lastPlayerLinkProbe = now
        AuthManager:QueueLocalPlayerLink(false)
    end
    if not SovereignRuntime.extendedInitialized then
        SavedPlayerManager:Init()
        Logger:Info("SovereignLua", "Verification complete")
        SovereignRuntime.extendedInitialized = true
    end
    if SovereignRuntime.authGroupId and SovereignMenuSessionValid()
        and not SovereignRuntime.authGroupHidden then
        menu.setGroupHidden(SovereignRuntime.authGroupId, true)
        SovereignRuntime.authGroupHidden = true
    end
    if now - (SovereignRuntime.lastPermissionCheck or 0) >= (SovereignRuntime.permissionCheckInterval or 1.0) then
        SovereignRuntime.lastPermissionCheck = now
        SovereignRuntime:ApplyPermissionVisibility()
    end
    SovereignRuntime.runtimeFrame = (SovereignRuntime.runtimeFrame or 0) + 1
    local playerId = menu.nativeApis.PLAYER.PLAYER_ID()
    if ImportedExtensionOptions.headlamp.enabled then
        local playerPed = ImportedExtensionOptions:GetLocalPed()
        if playerPed ~= 0 then
            SovereignRuntime:RunModule("Headlamp", ImportedExtensionOptions.ProcessHeadlamp, ImportedExtensionOptions, playerPed)
        end
    end
    SovereignRuntime:RunModule("Aim tracking", SovereignAimAssist.Process, SovereignAimAssist)
    SovereignRuntime:RunModule("Self", SelfOptions.ProcessSelfOptions, SelfOptions, playerId)
    SovereignRuntime:RunModule("Vehicles", VehicleOptions.ProcessVehicleOptions, VehicleOptions, playerId)
    SovereignRuntime:RunModule("Player action selection", SovereignPlayerEventMenu.Process, SovereignPlayerEventMenu)
    SovereignRuntime:RunModule("World", WorldOptions.ProcessWorldOptions, WorldOptions, playerId)
    SovereignRuntime:RunModule("Tornado", menu.worldTornado.Process, menu.worldTornado)
    if menu.teammateTracking.navigation or menu.teammateTracking.status then
        SovereignRuntime:RunModule("Teammate tracking", menu.teammateTracking.Process, menu.teammateTracking)
    end
    if menu.sessionSupport.job then
        SovereignRuntime:RunModule("Session support", menu.sessionSupport.Tick, menu.sessionSupport)
    end
    SovereignRuntime:RunModule("Strip club", SovereignClub.Process, SovereignClub)
    SovereignRuntime:RunModule("Fun", EntertainmentOptions.Process, EntertainmentOptions)
    SovereignRuntime:RunModule("Extensions", ImportedExtensionOptions.Process, ImportedExtensionOptions)
    if SovereignGameplayOptions then
        SovereignRuntime:RunModule("Extended controls", SovereignGameplayOptions.Process, SovereignGameplayOptions)
    end
    SovereignRuntime:RunModule("Game settings", SovereignRuntimeNativeOptions.Process, SovereignRuntimeNativeOptions)
    SovereignRuntime:RunModule("Looped features", SovereignProcessTickShims)
    if now - (SovereignRuntime.lastDynamicListProcess or 0) >= (SovereignRuntime.dynamicListInterval or 1.0) then
        SovereignRuntime.lastDynamicListProcess = now
        SovereignRuntime:RunModule("Dynamic lists", SovereignProcessDynamicLists)
    end
    if TravellerMigration.overviewVisible == true
        and now - (TravellerMigration.lastRefresh or 0) >= (TravellerMigration.refreshInterval or 1.0) then
        SovereignRuntime:RunModule("Session overview", TravellerMigration.Process, TravellerMigration, now, false)
    end
    if SovereignBattleNetworkStatus.visible == true
        and now - (SovereignBattleNetworkStatus.lastRefresh or 0) >= (SovereignBattleNetworkStatus.refreshInterval or 1.0) then
        SovereignRuntime:RunModule("Session Network Status", SovereignBattleNetworkStatus.Process,
            SovereignBattleNetworkStatus, now, false)
    end
    if SovereignStatusCenter.visible == true
        and now - (SovereignStatusCenter.lastRefresh or 0) >= (SovereignStatusCenter.refreshInterval or 1.0) then
        SovereignRuntime:RunModule("Status Center", SovereignStatusCenter.Process, SovereignStatusCenter, now, false)
    end
    -- R42 patch status polling: verification/retry only; writes still validate immediately.
    if SovereignPatchRegistry and (not SovereignRuntime.lastPatchStatusRefresh
        or now < SovereignRuntime.lastPatchStatusRefresh
        or now - SovereignRuntime.lastPatchStatusRefresh >= 0.25) then
        SovereignRuntime.lastPatchStatusRefresh = now
        SovereignRuntime:RunModule("Feature checks", SovereignPatchRegistry.Refresh, SovereignPatchRegistry)
        SovereignRuntime:RunModule("Feature status", SovereignRuntimePatchBridge.Refresh, SovereignRuntimePatchBridge)
    end
    local inventory = SovereignRuntime.businessInventory
    if type(inventory) == "table" and type(inventory.Process) == "function"
        and (inventory.visible == true or inventory.autoRestock == true
            or inventory.autoSell == true or inventory.alertEnabled == true
            or next(inventory.pendingRefillTransactions or {}) ~= nil
            or next(inventory.refillQuarantine or {}) ~= nil
            or next(inventory.pendingSaleReservation or {}) ~= nil
            or next(inventory.saleQuarantine or {}) ~= nil) then
        SovereignRuntime:RunModule("Business inventory", inventory.Process, inventory, now, false)
    end
end)

SovereignRuntime.Tick = LPH_NO_VIRTUALIZE(function()
    menu.updateBackgroundEffect(false)
    if menu and menu.processActions then
        menu.processActions()
    end
    SovereignProcessRuntime()
end)

function SovereignRuntime:EnsureLoop()
    if menu and menu.ensureInputCaptureLoop then
        menu.ensureInputCaptureLoop()
    end
    if self.runtimeLoopRegistered then
        return true
    end
    if not Script or not Script.RegisterLooped then
        return false
    end
    local ok, err = pcall(function()
        Script.RegisterLooped(LPH_NO_VIRTUALIZE(function()
            if type(ShouldUnload) == "function" and ShouldUnload() then return end
            local started = menu.runtimeProbe and menu.runtimeProbe.active and os.clock() or nil
            local tickOk, tickErr = pcall(SovereignRuntime.Tick)
            if started then menu.recordRuntimeTiming("Logic frame", started) end
            if not tickOk then
                local now = os.clock()
                if self.runtimeLoopLastErrorAt == 0 or now - self.runtimeLoopLastErrorAt >= 5.0 then
                    self.runtimeLoopLastErrorAt = now
                    SovereignLogError("SovereignRuntime.LoopTick", tickErr)
                end
            end
        end))
    end)
    if not ok then
        SovereignLogError("SovereignRuntime.Loop", err)
        return false
    end
    self.runtimeLoopRegistered = true
    return true
end

SovereignRuntime.PresentFrame = LPH_NO_VIRTUALIZE(function()
    if not SovereignInitialize() then
        return
    end
    if menu and menu.processKeyboardShortcuts then
        menu.processKeyboardShortcuts()
    end
    if menu and menu.hotkeyCaptureActive and menu.pollHotkeyCapture then
        menu.pollHotkeyCapture()
    end
    if SovereignRuntime.menuBuilt and not SovereignRuntime.autoLoginQueued
        and not AuthManager.loginRetryBlocked
        and os.clock() >= (SovereignRuntime.autoLoginNextAttempt or 0)
        and AuthManager.currentKey and AuthManager.currentKey ~= ""
        and not AuthManager.isAuthenticated then
        SovereignRuntime.autoLoginQueued = true
        SovereignLogin(false)
    end
    local sessionValid = AuthManager:SessionValid()
    if sessionValid then
        if ImportedExtensionOptions and ImportedExtensionOptions.RenderPresent then
            ImportedExtensionOptions:RenderPresent()
        end
        if EntertainmentOptions.speedometer then
            EntertainmentOptions:RenderSpeedometer()
        end
    end
    if menu.open or (menu.openAnimation and menu.openAnimation > 0.001) or #notifyQueue > 0 then
        DrawUI()
    end
    -- These two status windows are explicitly allowlisted as free read-only
    -- diagnostics, so they must remain visible while the paid lease is absent.
    if TravellerMigration.overviewVisible then TravellerMigration:RenderSessionOverview() end
    if SovereignBattleNetworkStatus.visible then SovereignBattleNetworkStatus:Render() end
    if sessionValid then
        if SovereignStatusCenter.visible then SovereignStatusCenter:Render() end
        if SovereignRuntime.performanceVisible then SovereignRuntime:RenderPerformanceOverlay() end
        if menu.notificationHistoryVisible then menu.renderNotificationHistory() end
        local inventory = SovereignRuntime.businessInventory
        if type(inventory) == "table" and inventory.visible == true
            and type(inventory.Render) == "function" then
            inventory:Render()
        end
    end
    if menu.interactive and menu.customCursorEnabled == true then
        menu.drawCursorOverlay()
    end
end)

local SovereignOnPresent = LPH_NO_VIRTUALIZE(function()
    local started = menu.runtimeProbe and menu.runtimeProbe.active and os.clock() or nil
    local ok, err = pcall(SovereignRuntime.PresentFrame)
    if started then menu.finishRuntimeProbeFrame(started) end
    if not ok then
        SovereignLogError("SovereignRuntime.Present", err)
    end
end)

function SovereignRuntime.OnUnload()
    if type(SovereignTaskSoloRuntime) == "table"
        and type(SovereignTaskSoloRuntime.Reset) == "function" then
        pcall(SovereignTaskSoloRuntime.Reset, SovereignTaskSoloRuntime)
    end
    SovereignOfficial:Stop()
    pcall(TeleportManager.Cleanup, TeleportManager)
    pcall(PlayerTrollOptions.CleanupPtfx, PlayerTrollOptions)
    if SovereignGameplayOptions and type(SovereignGameplayOptions.Cleanup) == "function" then pcall(SovereignGameplayOptions.Cleanup, SovereignGameplayOptions) end
    menu.playerActionGuard:Shutdown()
    menu.missionSupport:Shutdown()
    menu.teammateTracking:Shutdown()
    menu.sessionSupport:Shutdown()
    menu.worldTornado:Shutdown()
    SovereignProtectionFeedback:Reset()
    menu.updateBackgroundEffect(true)
    if SovereignRuntimePatchBridge and type(SovereignRuntimePatchBridge.RestoreAll) == "function" then
        local restoreOk, restored = pcall(SovereignRuntimePatchBridge.RestoreAll, SovereignRuntimePatchBridge)
        if not restoreOk or restored ~= true then
            Logger:Error("SovereignRuntimePatchBridge", "unload restore failed: " .. tostring(restored))
        end
    end
    if SovereignPatchRegistry and type(SovereignPatchRegistry.RestoreAll) == "function" then
        local restoreOk, restored = pcall(SovereignPatchRegistry.RestoreAll, SovereignPatchRegistry)
        if not restoreOk or restored ~= true then
            Logger:Error("SovereignPatchRegistry", "unload restore failed: " .. tostring(restored))
        end
    end
    if SovereignRuntimeNativeOptions and type(SovereignRuntimeNativeOptions.Cleanup) == "function" then
        local cleanupOk, restored
        for _ = 1, 3 do
            cleanupOk, restored = pcall(SovereignRuntimeNativeOptions.Cleanup, SovereignRuntimeNativeOptions)
            if cleanupOk and restored == true then break end
        end
        if not cleanupOk or restored ~= true then
            Logger:Error("SovereignRuntimeNativeOptions", "unload restore failed: " .. tostring(restored))
        end
    end
    if SovereignMatchmakingRegion and type(SovereignMatchmakingRegion.Disable) == "function" then
        SovereignMatchmakingRegion.desired = false
        local callOk, restored, restoreError
        for _ = 1, 3 do
            callOk, restored, restoreError = pcall(
                SovereignMatchmakingRegion.Disable,
                SovereignMatchmakingRegion,
                true
            )
            if callOk and restored == true then break end
        end
        if not callOk or restored ~= true then
            Logger:Error("MatchmakingRegion", "unload restore failed: "
                .. tostring(callOk and restoreError or restored))
        end
    end
    if VehicleOptions and type(VehicleOptions.Cleanup) == "function" and menu.nativeApis.PLAYER and type(menu.nativeApis.PLAYER.PLAYER_ID) == "function" then
        local ok, playerId = pcall(menu.nativeApis.PLAYER.PLAYER_ID)
        if ok then pcall(VehicleOptions.Cleanup, VehicleOptions, playerId) end
    end
    if ProtectionSystem then
        pcall(ProtectionSystem.CleanupEventHandlers,ProtectionSystem)
        pcall(ProtectionSystem.DisableAntiCrashCamera,ProtectionSystem,false)
    end
    if menu and menu.setOpen then
        menu.setOpen(false)
    end
    if menu and menu.flushUiSettings then pcall(menu.flushUiSettings, true) end
    if menu and menu.flushQuickSettings then pcall(menu.flushQuickSettings, true) end
    if SovereignClub then pcall(SovereignClub.Cleanup, SovereignClub) end
    if SovereignAimAssist then pcall(SovereignAimAssist.Cleanup, SovereignAimAssist) end
    if PlayerTrollOptions and PlayerTrollOptions.spawned then
        for pid in pairs(PlayerTrollOptions.spawned) do
            pcall(PlayerTrollOptions.Clear, PlayerTrollOptions, pid)
        end
    end
    pcall(ImportedExtensionOptions.SetOrbitalImpact, ImportedExtensionOptions, false)
    ImportedExtensionOptions:SetStreetPunch(false)
    ImportedExtensionOptions:SetTargetShot(false)
    if MemoryBridge and type(MemoryBridge.Cleanup) == "function" then
        pcall(MemoryBridge.Cleanup, MemoryBridge)
    end
    menu.captureMouse(false)
    SetShouldUnload()
end

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, SovereignRuntime.OnUnload)
EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, SovereignOnPresent)

end

SovereignBootstrapDependencies(SovereignContinueStartup)


